// Índice não pode vir do cache sem perguntar. Estes arquivos dizem ONDE os outros estão, e um
// mapa velho aponta para arquivo que não existe mais — 172 itens ficaram sem imagem para quem já
// tinha visitado o site, enquanto um navegador limpo via tudo certo. `cache: 'no-cache'` não
// desliga o cache: obriga a revalidar, o que com ETag custa um 304 de ~200 bytes.
const SEM_CACHE = { cache: 'no-cache' };

/** itemId → raridade — espelha `CASA_POR_RARIDADE` no servidor (70040…70044). */
const RAR_POR_CASA_ITEM = { 70040: 'comum', 70041: 'incomum', 70042: 'rara', 70043: 'mitica', 70044: 'lendaria' };
const CASA_ITEM_POR_RAR = Object.fromEntries(Object.entries(RAR_POR_CASA_ITEM).map(([id, r]) => [r, Number(id)]));

/** itemId → raridade — espelha `BICICLETA_POR_RARIDADE` no servidor (70080…70084). */
const RAR_POR_BICICLETA_ITEM = { 70080: 'comum', 70081: 'incomum', 70082: 'rara', 70083: 'mitica', 70084: 'lendaria' };
const BICICLETA_ITEM_POR_RAR = Object.fromEntries(
  Object.entries(RAR_POR_BICICLETA_ITEM).map(([id, r]) => [r, Number(id)]),
);

const NOSSOS_ITENS_I18N = {
  70010: 'item.escapeRope',
  70011: 'item.fragmentoChave',
  70012: 'item.fragmentoShiny',
  70013: 'item.fragmentoBicicleta',
  // Os dois fragmentos de MEGA. As 63 pedras (71xxx/72xxx) ficam de fora de propósito: o nome
  // delas é nome PRÓPRIO ("Gengarite", "Shiny Gengarite"), igual em qualquer idioma, como já
  // acontece com a Water Stone e a Leaf Stone.
  70014: 'item.fragmentoMega',
  70015: 'item.fragmentoMegaShiny',
  70016: 'item.nameTag',
  70050: 'item.xpShareHeld',
  // As Caixas de Fundador. Reaproveitam as chaves de `caixas.nome.*`, que são as mesmas que a
  // Loja e o diálogo usam — o nome da caixa é UM em toda a interface, inclusive na linha do
  // catálogo do Mercado, onde ela é só mais um item da lista.
  70060: 'caixas.nome.fundador',
  70061: 'caixas.nome.cofundador',
  // O MysticTicket e os três ovos da Chocadeira (`shared/mistico.mjs`, `shared/chocadeira.mjs`).
  [MYSTIC_TICKET_ID]: 'item.mysticTicket',
  ...Object.fromEntries(OVOS.map((o) => [o.itemId, `item.ovo.${o.id}`])),
};

/** Nome traduzido dos itens nossos; o catálogo continua em inglês no servidor. */
function nomeItem(itemOrId, fallback) {
  const id = typeof itemOrId === 'object' ? Number(itemOrId.id) : Number(itemOrId);
  const fb = typeof itemOrId === 'object' ? (itemOrId.nome ?? itemOrId.name) : fallback;
  const skin = SKIN_POR_ITEM.get(id);
  if (skin) return t('skin.itemNome', { nome: nomeDaSkin(skin) });
  const rar = RAR_POR_CASA_ITEM[id];
  if (rar) {
    const k = `item.casa.${rar}`;
    const tr = t(k);
    if (tr !== k) return tr;
  }
  const rarBicicleta = RAR_POR_BICICLETA_ITEM[id];
  if (rarBicicleta) {
    const k = `item.bicicleta.${rarBicicleta}`;
    const tr = t(k);
    if (tr !== k) return tr;
  }
  const chave = NOSSOS_ITENS_I18N[id];
  if (chave) {
    const tr = t(chave);
    if (tr !== chave) return tr;
  }
  const tipoShiny = (estado.shinyStone?.pedras ?? []).find((p) => p.itemId === id)?.tipo;
  if (tipoShiny) {
    const tr = t('pedra.nome', { tipo: tipoShiny });
    if (tr !== 'pedra.nome') return tr;
  }
  return tituloInglesItem(fb ?? '');
}

const $ = (s) => document.querySelector(s);
const num = (n) => (n ?? 0).toLocaleString('pt-BR');

// ------------------------------------------------------------------ ícones
//
// Tudo sai do espelho de assets — nada de emoji. Os retratos de espécie vêm do atlas de
// marcadores do mapa-múndi (297 células de 64 px), e as bolas dos sprites de arremesso.

const ATLAS = { url: '/assets/site/assets/maps/marker-atlas.png', celula: 64, cols: 16, rows: 1 };
let atlasSlots = null;
/** A promessa é exportada para a barra de carregamento poder esperar por esta etapa. */
const atlasPronto = fetch('/assets/site/assets/maps/marker-atlas.json', SEM_CACHE)
  .then((r) => r.json())
  .then((j) => {
    atlasSlots = j.slots;
    ATLAS.celula = j.cell ?? 64;
    ATLAS.cols = j.cols ?? 16;
    ATLAS.rows = j.rows ?? Math.max(1, Math.ceil(Object.keys(j.slots ?? {}).length / ATLAS.cols));
    if (j.version) ATLAS.url = `/assets/site/assets/maps/marker-atlas.png?v=${j.version}`;
    else if (j.image) ATLAS.url = j.image;
    for (const el of document.querySelectorAll('[data-ico]')) pintarIcone(el);
  })
  .catch(() => {});

/**
 * Retrato de uma espécie, recortado do atlas por `background-position`.
 *
 * ATENÇÃO: o atlas é indexado por **looktype**, não por pokeId. Os dois coincidem em 161 das
 * 443 espécies, o que dá um bug silencioso e traiçoeiro — o ícone aparece, só que é de outro
 * pokémon. Pelo looktype, 416 das 443 têm retrato.
 */
/**
 * Retrato ESTÁTICO de um looktype que não está no atlas de marcadores.
 *
 * O `marker-atlas` indexa retratos por looktype. Quem não está no atlas usa o sprite do
 * outfit em runtime (`retratoDeLooktype`). Regere com `npm run marker-atlas`.
 */
const cacheRetrato = new Map(); // looktype -> Promise<dataURL|null>
/** Mesma composição do `build-marker-atlas.py`: quadro sul num quadrado, pé embaixo. */
function retratoQuadrado(s, tam = 64) {
  const q = s && quadrosDe(s, 3)[0];
  const pag = q && s.imagens[q.pagina];
  if (!pag || !q) return null;
  const escala = Math.min(tam / q.w, tam / q.h, 1);
  const nw = Math.max(1, Math.round(q.w * escala));
  const nh = Math.max(1, Math.round(q.h * escala));
  const cv = document.createElement('canvas');
  cv.width = tam;
  cv.height = tam;
  const ctx = cv.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(pag, q.x, q.y, q.w, q.h, (tam - nw) >> 1, tam - nh - 2, nw, nh);
  return cv.toDataURL();
}
function retratoDeLooktype(looktype, px) {
  if (!cacheRetrato.has(looktype)) {
    cacheRetrato.set(
      looktype,
      carregarOutfit(looktype)
        .then((s) => retratoQuadrado(s))
        .catch(() => null),
    );
  }
  const el = document.createElement('img');
  el.className = 'ico-poke-sprite';
  el.style.width = el.style.height = `${px}px`;
  el.style.objectFit = 'contain'; // sprite alto (64×96) não pode achatar dentro do círculo
  el.style.imageRendering = 'pixelated';
  cacheRetrato.get(looktype).then((url) => {
    if (url) el.src = url;
    else if (el.isConnected) el.replaceWith(iconeBola(1, px)); // nem no atlas de outfits: bola
  });
  return el;
}

function iconeEspecie(looktype, px = 22) {
  const slot = atlasSlots?.[String(looktype)];
  // Sem retrato no atlas de marcadores: tenta o sprite de verdade antes de desistir. Só cai na
  // pokébola quando não há looktype nenhum para desenhar.
  if (!slot) return looktype ? retratoDeLooktype(looktype, px) : iconeBola(1, px);
  const el = document.createElement('span');
  el.className = 'ico-poke';
  el.style.width = el.style.height = `${px}px`;
  // URL versionada no JS (não no CSS): evita PNG velho em cache com índice novo do JSON.
  el.style.backgroundImage = `url('${ATLAS.url}')`;
  el.style.backgroundSize = `${ATLAS.cols * px}px ${ATLAS.rows * px}px`;
  el.style.backgroundPosition = `${-slot[0] * px}px ${-slot[1] * px}px`;
  return el;
}

/**
 * A ESPÉCIE de um pokémon vindo do servidor, achada pelo id e, se preciso, pelo nome.
 *
 * O nome existe como segunda via por causa do Mercado Global: a ficha de um anúncio é um
 * retrato CONGELADO no dia em que ele foi aberto, e as mais antigas não guardavam `speciesId`.
 * O nome elas sempre tiveram, e é ele que reancora a linha no catálogo de hoje.
 */
const especieDe = (k) => estado.especies.get(k?.speciesId) ?? estado.especiePorNome.get(k?.nome) ?? null;

/**
 * O looktype que deve ser DESENHADO para um pokémon.
 *
 * A regra é resolver pela ESPÉCIE e nunca confiar no `looktype` que veio junto. Parece
 * excesso de zelo e não é — foi assim que o Charizard preto apareceu na vitrine:
 *
 *   {"nome":"Charizard","level":87,"shiny":false,"looktype":9874}
 *
 * 9874 é o looktype da forma SHINY. O anúncio congelou esse número num dia em que o espelho
 * de assets numerava as coisas de outro jeito, e a tela obedeceu — desenhou o bicho preto num
 * anúncio marcado como comum, sem selo de shiny nenhum. Outro anúncio guardou 8716, que hoje
 * não é outfit de coisa alguma, e ficava um quadrado em branco.
 *
 * Espécie é identidade; looktype é detalhe de desenho que muda quando o espelho é regerado.
 * Resolvendo a partir da espécie, os dois casos se consertam sozinhos — e o shiny passa a
 * mostrar a arte shiny DE VERDADE, que é o que o jogador pagou para ter.
 */
function looktypeDe(k) {
  // A SKIN vestida manda no desenho, por cima da forma shiny — a skin shiny É a arte shiny (ver
  // `shared/skins.mjs`). `looktypeDaSkin` confere espécie e cor: o que vem do servidor com uma
  // skin que não serve mais (evoluiu vestido) cai no desenho de sempre.
  const daSkin = looktypeDaSkin(k);
  if (daSkin) return daSkin;
  const esp = especieDe(k);
  const base = esp?.looktype ?? k?.looktype;
  if (!k?.shiny) return base;
  const id = esp?.pokeId ?? k?.speciesId;
  if (k?.shiny && id != null && isOutlandPokeId(id)) {
    return estado.shinyLooksOutland[id] ?? k?.lookShiny ?? base;
  }
  const dexN = id != null ? dexDoPokeId(id) : null;
  return (dexN != null ? estado.shinyLooks[dexN] : null)
    ?? (id != null ? estado.shinyLooks[id] : null)
    ?? k?.lookShiny
    ?? base;
}

/**
 * O sprite ANIMADO de um pokémon, já na forma certa.
 *
 * A queda em `iconeEspecie` é pelo looktype COMUM de propósito: o atlas de retratos do
 * mapa-múndi não tem célula para as formas shiny, e cair na pokébola genérica seria pior que
 * mostrar o bicho certo na cor errada.
 */
function spritePokemon(k, px = 40) {
  const comum = especieDe(k)?.looktype ?? k?.looktype;
  return spriteAnimado(looktypeDe(k), px, 3, () => iconeEspecie(comum, px));
}

// As folhas de arremesso são grades de 3×3 com a bola em movimento (rastro e tudo), então
// não servem de ícone parado. Os ícones vêm do pokesprite, espelhados em site/assets/ui.
//
// A Super Ball (id 3) usa arte nossa — ícone em `/img/` e animação em `/effects/catch/`.
/**
 * As três moedas, e o que separa cada uma:
 *
 *   OURO      se ganha jogando (drop, venda ao NPC). Compra do NPC.
 *   DIAMANTE  se compra com PIX ou cartão e acaba ao ser gasto. Compra da LOJA.
 *   GEMA      se compra com USDT e VOLTA em USDT (ver `orbs.mjs`). Compra de OUTRO JOGADOR,
 *             no Mercado da Comunidade.
 *
 * Os três PNGs são visivelmente diferentes de propósito: diamante e gema já dividiram o mesmo
 * orbe azul, e os dois contadores lado a lado no HUD eram indistinguíveis.
 */
const ICONE_OURO = 'site/assets/ui/moeda-ouro.png';
const ICONE_DIAMANTE = '/img/moeda-diamante.png';
// Arte NOSSA fica em `src/client/img/`, servida em `/img/` — e não no espelho `/assets/`.
// `public/data` é gitignorado (é a cópia regenerável do pack de terceiro), então ícone nosso
// posto lá nunca chega ao servidor: some em produção e funciona na sua máquina.
const ICONE_GEMA = '/img/moeda-gema.png';

/**
 * O arquivo de cada pokébola.
 *
 * A Beast Ball (id 5) é a única com caminho ABSOLUTO: ela é arte nossa, servida junto do
 * cliente, e não sai do espelho de assets — que é gitignorado e some no `npm run fetch`.
 * `iconeArquivo` já distingue os dois casos pela barra inicial.
 */
const SPRITE_BOLA = {
  1: 'site/assets/ui/ball-poke.png',
  2: 'site/assets/ui/ball-great.png',
  3: '/img/ball-super.png',
  4: 'site/assets/ui/ball-ultra.png',
  5: '/img/ball-beast.png',
};

const iconeBola = (ballId, px = 22) => iconeArquivo(SPRITE_BOLA[ballId] ?? SPRITE_BOLA[1], px);

/** Lupa com + ou − dentro, desenhada em SVG para não depender de fonte nem de emoji. */
const lupa = (sinal) => `
  <svg viewBox="0 0 20 20" width="19" height="19" aria-hidden="true">
    <circle cx="8.5" cy="8.5" r="6" fill="none" stroke="currentColor" stroke-width="2"/>
    <line x1="13" y1="13" x2="18.5" y2="18.5" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/>
    <line x1="5.5" y1="8.5" x2="11.5" y2="8.5" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
    ${sinal === '+' ? '<line x1="8.5" y1="5.5" x2="8.5" y2="11.5" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>' : ''}
  </svg>`;

/** Prancheta — estatísticas da sessão de hunt. */
const iconePrancheta = () => `
  <svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true">
    <rect x="4" y="2.5" width="12" height="15" rx="1.5" fill="none" stroke="currentColor" stroke-width="1.8"/>
    <line x1="7" y1="6.5" x2="13" y2="6.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
    <line x1="7" y1="10" x2="13" y2="10" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
    <line x1="7" y1="13.5" x2="11" y2="13.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
    <rect x="6.5" y="1" width="2" height="3" rx=".6" fill="currentColor"/>
    <rect x="11.5" y="1" width="2" height="3" rx=".6" fill="currentColor"/>
  </svg>`;

/**
 * O gráfico de barras do botão TRACKER (topo do modal de PvP).
 *
 * BARRAS, e não a prancheta: a prancheta já quer dizer "os números DISTO AQUI" em três telas
 * (sessão, tabela de preços, análise da guerra), e este botão não mostra números — ele SAI do
 * jogo para um site de estatística. Um desenho diferente é o que impede o jogador de esperar
 * que o modal abra por cima, como os outros três fazem.
 */
const iconeGrafico = () => `
  <svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true">
    <rect x="2.5" y="11" width="3.6" height="6.5" rx=".8" fill="currentColor"/>
    <rect x="8.2" y="6.5" width="3.6" height="11" rx=".8" fill="currentColor"/>
    <rect x="13.9" y="2.5" width="3.6" height="15" rx=".8" fill="currentColor"/>
  </svg>`;

/*
 * ---- os ícones da barra do Mercado NO CELULAR ----
 *
 * No desktop aquela barra é seis botões escritos, e escrito está certo: há largura de sobra e
 * a palavra não deixa dúvida. Num telefone os mesmos seis botões custavam 300 px — mais da
 * metade da tela — antes do primeiro anúncio aparecer. Aqui eles viram ícone, que é o que faz
 * a vitrine do iFood, do Uber e do Marketplace caber na mão.
 *
 * Todos seguem a mesma receita da prancheta acima: caixa de 20×20, traço em `currentColor`
 * (para herdarem o branco do botão roxo e o bege do apagado sem uma cor a mais no arquivo) e
 * espessura ~1,8 px, que é o que sobrevive à escala de um pixel art sem virar borrão.
 */

/** Funil — abrir os filtros. */
const iconeFunil = () => `
  <svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true">
    <path d="M2.6 4h14.8l-5.7 6.6v5.2l-3.4 1.7v-6.9z"
          fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round"/>
  </svg>`;

/** Mais — anunciar. */
const iconeMais = () => `
  <svg viewBox="0 0 20 20" width="20" height="20" aria-hidden="true">
    <line x1="10" y1="3.6" x2="10" y2="16.4" stroke="currentColor" stroke-width="2.8" stroke-linecap="round"/>
    <line x1="3.6" y1="10" x2="16.4" y2="10" stroke="currentColor" stroke-width="2.8" stroke-linecap="round"/>
  </svg>`;

/** Etiqueta de preço — os meus anúncios. */
const iconeEtiqueta = () => `
  <svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true">
    <path d="M10.6 2.4H17.6v7l-7.5 7.5a1.5 1.5 0 0 1-2.1 0l-4.9-4.9a1.5 1.5 0 0 1 0-2.1z"
          fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/>
    <circle cx="14.2" cy="5.8" r="1.4" fill="currentColor"/>
  </svg>`;

/**
 * Bandeja com seta — histórico de VENDAS (para cima, o que saiu daqui) e de COMPRAS (para
 * baixo, o que entrou). É o par de entrada/saída de qualquer aplicativo de banco: lado a lado
 * os dois se distinguem de relance, o que um par de sacolas parecidas não daria.
 */
const iconeFluxo = (dir) => {
  const cima = dir === 'cima';
  return `
  <svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true">
    <polyline points="3,12.4 3,16.8 17,16.8 17,12.4" fill="none" stroke="currentColor"
              stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
    <line x1="10" y1="${cima ? '2.6' : '13'}" x2="10" y2="${cima ? '13' : '2.6'}"
          stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/>
    <polyline points="${cima ? '6.2,6.4 10,2.6 13.8,6.4' : '6.2,9.2 10,13 13.8,9.2'}"
              fill="none" stroke="currentColor" stroke-width="1.9"
              stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
};

/**
 * Ícones da Loja cujo ARQUIVO é uma tira vertical, e não um desenho único.
 *
 * O Pacote de Suprimentos vem 32×576 na origem — 18 quadros de 32×32 empilhados. Num `<img>`
 * com `object-fit: contain` a tira inteira era espremida na caixa e virava um risco colorido
 * de dois pixels de altura.
 *
 * **Os 18 quadros são IDÊNTICOS** (conferido pixel a pixel: 775 opacos e alfa médio 193 em
 * todos). Ou seja, não há animação nenhuma para reproduzir — é o mesmo desenho repetido. Por
 * isso aqui se mostra só o PRIMEIRO quadro, parado. A primeira tentativa animava a tira com
 * `steps(18)` e o ícone piscava: além de não haver o que animar, porcentagem em
 * `background-position` é posicionamento relativo (`container − imagem`), não deslocamento,
 * então os "quadros" caíam fora do desenho.
 *
 * O valor é a altura de UM quadro. Quem não estiver aqui é desenho único e segue pelo caminho
 * normal do `<img>`.
 */
const ICONES_EM_TIRA = { 'supplypack.png': 32 };

/** Ícone de item do espelho (moeda, poção, revive…). */
/**
 * O `src` de um ícone do jogo, e a única régua que decide isso.
 *
 * Caminho ABSOLUTO = arte NOSSA, servida junto do cliente (`src/client/img/`). O resto é
 * relativo ao espelho de assets (`/assets/`), que é regenerável e está fora do git — arte
 * própria ali sumiria no primeiro `npm run fetch`.
 *
 * Existe porque a regra estava escrita em dois lugares: aqui dentro, para quem monta o ícone
 * como NÓ, e à mão (`/assets/${ICONE}`) em cada `<img>` de template. Quem esquecia o prefixo
 * mandava o navegador resolver o caminho relativo contra a página — `/app` virava
 * `/site/assets/ui/moeda-ouro.png` e o ícone do ouro vinha 404 no painel do Mercado. Com a
 * régua num lugar só, passar a constante crua é o caminho certo em todo lugar.
 */
const srcIcone = (rel) => (String(rel).startsWith('/') ? rel : `/assets/${rel}`);

function iconeArquivo(rel, px = 18) {
  const src = srcIcone(rel);

  if (ICONES_EM_TIRA[rel.split('/').pop()]) {
    const el = document.createElement('span');
    el.className = 'ico-tira';
    el.style.width = el.style.height = `${px}px`;
    el.style.backgroundImage = `url("${src}")`;
    // A imagem é escalada pela LARGURA (`auto` na altura), então um quadro ocupa exatamente a
    // caixa e a tira inteira fica `px × 18px` logo abaixo. Com `background-position: 0 0` — o
    // padrão, no CSS — a caixa mostra só o quadro de cima. O ícone escala junto com `px` em
    // vez de ficar preso ao tamanho do arquivo.
    el.style.backgroundSize = `${px}px auto`;
    return el;
  }

  const img = document.createElement('img');
  img.src = src;
  // Caixa quadrada com o desenho inteiro dentro: as fontes têm tamanhos diferentes
  // (32×32 no pokesprite, 55×61 no espelho do idleworld) e a plaquinha do botão
  // precisa ficar quadrada de qualquer jeito.
  img.style.width = img.style.height = `${px}px`;
  img.style.objectFit = 'contain';
  img.alt = '';
  return img;
}

/**
 * `data-ico` vira um ícone de verdade na frente do texto. Três formatos:
 *   `img:site/assets/ui/NOME.png`  arquivo do espelho de assets (`/assets/`)
 *   `img:/img/NOME.png`            arte NOSSA, versionada em `src/client/img/`
 *   `look:59`                   retrato de espécie, recortado do atlas
 *   `bola`                      pokébola
 * `data-ico-px` escolhe o tamanho (o padrão de 20 px serve para as abas das gavetas).
 *
 * Roda duas vezes: uma no carregamento (pega arquivos e bolas) e outra quando o atlas de
 * marcadores chega (pega os retratos). Marcar o elemento evita ícone em dobro.
 */
function pintarIcone(el) {
  const pedido = el.dataset.ico;
  if (!pedido || el.dataset.icoFeito) return;
  const px = Number(el.dataset.icoPx) || 20;

  if (pedido.startsWith('img:')) {
    el.dataset.icoFeito = '1';
    el.prepend(iconeArquivo(pedido.slice(4), px));
    return;
  }
  const looktype = pedido.startsWith('look:') ? Number(pedido.slice(5)) : null;
  if (looktype && !atlasSlots) return; // sem o atlas ainda; a segunda passada resolve
  el.dataset.icoFeito = '1';
  el.prepend(looktype ? iconeEspecie(looktype, px) : iconeBola(1, px));
}
for (const el of document.querySelectorAll('[data-ico]')) pintarIcone(el);

const PX_ICONE_OURO_HUD = 20;
/** Diamante e gema: arte 18×15 num canvas 32×32 — ~1,8× o ouro para pesar igual na barra. */
const PX_ICONE_GEMA_HUD = 36;
/** Largura reservada na fileira — os três contadores alinham o número na mesma coluna. */
const COL_MOEDA_HUD = 20;

/** Ícone de moeda no HUD: coluna fixa à esquerda, sprite ancorado no canto. */
function iconeMoedaHud(rel, px, colPx = COL_MOEDA_HUD) {
  const caixa = document.createElement('span');
  caixa.className = 'tr-moeda-ico';
  caixa.style.width = caixa.style.height = `${colPx}px`;
  caixa.appendChild(iconeArquivo(rel, px));
  return caixa;
}

$('#tr-gold-box').prepend(iconeMoedaHud(ICONE_OURO, PX_ICONE_OURO_HUD));
$('#tr-diamantes-box').prepend(iconeMoedaHud(ICONE_DIAMANTE, PX_ICONE_GEMA_HUD));
$('#tr-gemas-box').prepend(iconeMoedaHud(ICONE_GEMA, PX_ICONE_GEMA_HUD));
$('#tr-online-box').prepend(iconeBola(1, 14));

/** O mesmo outfit que anda atrás do pokémon no mapa (kind `trainer` no índice). */
const LOOKTYPE_TREINADOR = 159;

/**
 * O boneco do PRÓPRIO jogador, com o outfit e as cores dele.
 *
 * Existe porque três lugares da tela desenham o mesmo treinador (o retrato do painel, a ficha
 * e as linhas do ranking) e os três liam só o looktype — o que dava três bonecos de cores
 * padrão em cima de um jogador que escolheu as dele.
 */
const spriteDeMim = (px = 44, dir = 3) => {
  const l = estado.eu?.loja;
  return spriteAnimado(
    l?.looktype ?? LOOKTYPE_TREINADOR, px, dir, null,
    empacotarVisual(l?.visual),
  );
};

/** Troca o boneco de um contêiner — a aparência muda no meio da partida (skin, gênero). */
const pintarRetrato = (sel, px) => {
  const host = $(sel);
  if (!host) return;
  host.replaceChildren(spriteDeMim(px));
};

// O outfit padrão enquanto ninguém entrou. `pintarTreinador` troca pelo do jogador no
// primeiro pacote de estado — aqui `estado` ainda nem foi declarado (é adiante no arquivo).
$('#tr-retrato').appendChild(
  spriteAnimado(LOOKTYPE_TREINADOR, 44, 3, null, empacotarVisual(VISUAL_PADRAO)),
);
// O retrato é a porta da ficha do treinador. Vira botão de verdade (cursor, title e teclado)
// em vez de só ganhar um `onclick`: um alvo clicável que não se anuncia não é clicado.
$('#tr-retrato').classList.add('clicavel');
$('#tr-retrato').tabIndex = 0;
$('#tr-retrato').setAttribute('role', 'button');
$('#tr-retrato').onclick = () => abrirModal('perfil');
$('#tr-retrato').onkeydown = (ev) => {
  if (ev.key === 'Enter' || ev.key === ' ') {
    ev.preventDefault();
    abrirModal('perfil');
  }
};
$('#btn-afiliados').onclick = () => abrirModal('afiliados');
$('#btn-votar').onclick = () => abrirModal('votar');
$('#btn-calculadora').onclick = () => abrirModal('calculadora');
$('#btn-amigos').onclick = () => abrirModal('amigos');
$('#btn-config').onclick = () => abrirModal('configuracoes');
$('#btn-bolsa')?.addEventListener('click', () => abrirModal('bolsa'));

/**
 * Os painéis que se recolhem: Equipe (esquerda), Automações e chat (direita).
 *
 * Recolher é uma escolha sobre a MESA, não sobre o jogo — vale entre sessões, então mora no
 * `localStorage` e não no servidor. Cada um guarda uma chave própria: quem fecha as
 * Automações porque já configurou tudo não quer o chat fechado junto.
 *
 * O arranjo da direita sai sozinho das duas chaves, e é por isso que não há uma terceira:
 *
 * · só Automações recolhida → o chat é o `.cresce` da coluna e ocupa a altura que sobrou;
 * · só chat recolhido       → ele vira a fita das abas e a coluna fica curta;
 * · os DOIS recolhidos      → não há mais conteúdo pedindo 306 px de largura. Entra
 *                             `html.dir-min`, a coluna encolhe e o palco herda a diferença.
 */
const PAINEIS_RECOLHIVEIS = [
  { id: 'p-equipe', botao: 'btn-equipe-toggle', chave: 'equipeRecolhida', dica: 'equipe' },
  { id: 'p-auto', botao: 'btn-auto-toggle', chave: 'autoRecolhida', dica: 'auto' },
  { id: 'p-chat', botao: 'btn-chat-toggle', chave: 'chatRecolhido', dica: 'chat' },
];

const painelRecolhido = (chave) => {
  try { return localStorage.getItem(chave) === '1'; } catch { return false; }
};
/**
 * No celular NÃO existe painel recolhido: cada um já mora numa gaveta que fecha inteira (ver
 * §8 do DESIGN.md), e o `mobile.css` neutraliza as regras de recolhimento. A preferência do
 * desktop continua guardada — ela só não vale enquanto a outra montagem está no ar, e quem
 * pergunta "o chat está fechado?" precisa da resposta que a TELA está dando.
 */
const montagemMovel = () => document.documentElement.classList.contains('mobile');
const chatRecolhido = () => !montagemMovel() && painelRecolhido('chatRecolhido');

function aplicarPaineisRecolhidos() {
  for (const p of PAINEIS_RECOLHIVEIS) {
    const painel = $(`#${p.id}`);
    const btn = $(`#${p.botao}`);
    if (!painel || !btn) continue;
    const rec = painelRecolhido(p.chave);
    painel.classList.toggle('recolhida', rec);
    btn.setAttribute('aria-expanded', String(!rec));
    const chave = `tip.${p.dica}${rec ? 'Expandir' : 'Recolher'}`;
    btn.title = t(chave);
    btn.setAttribute('aria-label', t(chave));
  }
  // A coluna estreita só com os dois da direita fechados — ver a nota acima.
  document.documentElement.classList.toggle(
    'dir-min',
    painelRecolhido('autoRecolhida') && painelRecolhido('chatRecolhido'),
  );
}

const guardarPainelRecolhido = (chave, rec) => {
  try { localStorage.setItem(chave, rec ? '1' : '0'); } catch { /* quota */ }
  aplicarPaineisRecolhidos();
};

/**
 * Abre ou fecha o chat.
 *
 * Fora do botão de recolher, quem chama é o clique numa ABA ou numa BANDEIRA com o painel
 * fechado: os dois continuam à vista na fita, e escolher um canal para depois continuar sem
 * poder lê-lo seria um botão que mente. Trocar de canal abre o chat — que é o que a pessoa
 * quis dizer.
 */
function definirChatRecolhido(rec) {
  if (montagemMovel()) return;
  // Sai cedo quando já está no estado pedido: clicar numa aba com o chat ABERTO passa por
  // aqui a cada troca de canal, e não há por que gravar no `localStorage` e repintar a coluna
  // para dizer o que já estava dito.
  if (rec === chatRecolhido()) return;
  guardarPainelRecolhido('chatRecolhido', rec);
  // Fechado, o chat é `display: none`: a lista perde a rolagem e os painéis flutuantes
  // (moderação, ignorados, emoji) ficariam pendurados sobre uma fita de 28 px.
  fecharPainelModChat();
  fecharPainelIgnorados();
  fecharMenuCanais();
  fecharOpcoesChat();
  $('#chat-emojis')?.classList.add('hidden');
  $('#chat-emoji')?.classList.remove('on');
  if (!rec) {
    // Reabrindo: as mensagens que chegaram enquanto estava fechado já estão na lista, e quem
    // abre o chat quer ver a última — não a linha em que parou meia hora atrás.
    rolarChatAoFim();
    marcarChatNovas(0);
    if (ehCanalPublico(estado.canalChat)) marcarCanalChatVisto(estado.canalChat);
  }
  pintarSelosChatAbas();
}

for (const p of PAINEIS_RECOLHIVEIS) {
  $(`#${p.botao}`)?.addEventListener('click', () => {
    const rec = !painelRecolhido(p.chave);
    if (p.id === 'p-chat') return definirChatRecolhido(rec);
    guardarPainelRecolhido(p.chave, rec);
    if (p.id === 'p-auto') pintarSeloAutomacoes();
  });
}
aplicarPaineisRecolhidos();

/**
 * A altura da BARRA DE MENU, publicada em `--menu-alt`.
 *
 * Os painéis recolhidos da direita se alinham por ela: a fita das Automações tem a altura
 * exata da barra, e por isso o chat logo abaixo começa na mesma linha que o palco — as duas
 * colunas usam o mesmo `gap`, então acertar o primeiro quadro acerta tudo que vem depois.
 *
 * É MEDIDO, e não escrito à mão, porque a barra muda de altura: os botões encolhem em três
 * degraus de `@media` e, abaixo de 1280 px, ela quebra em duas linhas. Um `82px` fixo ficaria
 * certo no monitor de quem escreveu e errado em todos os outros.
 */
const medirAlturaDoMenu = () => {
  const menu = document.querySelector('.menu-topo');
  // No celular a barra vira uma grade dentro da gaveta "Menu" e deixa de medir a mesma coisa —
  // lá nenhuma regra usa `--menu-alt`, então basta não escrever lixo por cima.
  if (!menu || montagemMovel()) return;
  const h = Math.round(menu.getBoundingClientRect().height);
  if (h > 0) document.documentElement.style.setProperty('--menu-alt', `${h}px`);
};
{
  const menu = document.querySelector('.menu-topo');
  if (menu && window.ResizeObserver) new ResizeObserver(medirAlturaDoMenu).observe(menu);
  medirAlturaDoMenu();
}

/** Selo de tipo nas cores clássicas (o CSS tem uma classe por tipo). */
const selosDeTipo = (tipos) => (tipos ?? []).map((t) => `<span class="tipo ${t}">${t}</span>`).join('');

/** Prefixo antes do nome quando o pokémon é shiny (equipe, depot, hunt…). */
const prefixoShiny = () => `✨ ${t('calc.shiny')} `;

/**
 * O BRILHO do shiny nas vitrines do próprio bicho — a ficha, a Equipe e o Em campo: um halo de
 * ouro que respira atrás do sprite e duas faíscas de pixel que piscam fora de compasso. Discreto
 * de propósito: a festa de verdade é o aviso da captura, e este é o "olha o que você tem".
 *
 * A Equipe e o Em campo se redesenham a cada snapshot (duas vezes por segundo), e um elemento
 * novo começa a animação do zero — o halo nunca sairia do primeiro quadro. Por isso a FASE vem
 * do relógio: o atraso negativo põe cada cópia nova no ponto do ciclo em que a anterior estava,
 * e de quebra todo shiny da tela respira junto. O ciclo é o mesmo `3.2s` do `.sh-halo`.
 */
const CICLO_BRILHO_SHINY_MS = 3200;
const brilhoShiny = () => {
  const fase = `style="--sh-fase:-${Date.now() % CICLO_BRILHO_SHINY_MS}ms" aria-hidden="true"`;
  return `<i class="sh-halo" ${fase}></i><i class="sh-faisca f1" ${fase}></i><i class="sh-faisca f2" ${fase}></i>`;
};

/**
 * O selo do TÍTULO DE GINÁSIO no pokémon que está batendo mais forte por causa dele.
 *
 * Sem isto o +25% seria invisível: o jogador ganharia o ginásio e continuaria vendo os
 * mesmos números na tela de batalha, sem nada ligando uma coisa à outra. `estado.eu.ginasios`
 * é a lista de tipos que ele lidera AGORA, e vem no snapshot justamente para este selo poder
 * existir longe da aba Ginásio.
 */
const seloGinasio = (p) =>
  multBuffGinasio(p?.tipos, estado.eu?.ginasios) > 1
    ? `<span class="selo-ginasio" title="${t('gin.seloDica', { pct: GINASIO_BUFF_PCT })}">👑 +${GINASIO_BUFF_PCT}%</span>`
    : '';

/** Os 18 tipos — reutilizado no mapa, Mercado da Comunidade e Depot. */
const TIPOS_FILTRO = [
  'NORMAL', 'FIRE', 'WATER', 'GRASS', 'ELECTRIC', 'ICE', 'FIGHTING', 'POISON', 'GROUND',
  'FLYING', 'PSYCHIC', 'BUG', 'ROCK', 'GHOST', 'DRAGON', 'DARK', 'STEEL', 'FAIRY',
];

/** Selos de TM Disk no pokémon (elemental + AoE), como no idleworld. */
const selosTm = (pk) => {
  if (!pk) return '';
  const partes = [];
  const el = pk.tmElemental ?? pk.tm_elemental ?? null;
  const aoe = pk.tmAoe ?? pk.tm_aoe;
  if (el) partes.push(`<span class="tm-selo">${escapar(String(el))}</span>`);
  if (aoe === true || aoe === 'true' || aoe === 1) {
    partes.push(`<span class="tm-selo aoe">AoE</span>`);
  }
  return partes.join('');
};

/**
 * Os idiomas em que se CONVERSA — duas bandeiras, e não as três da interface.
 *
 * A interface segue em português, inglês e espanhol: traduzir uma tela custa uma vez e serve
 * para sempre. Um canal de conversa é outra coisa — ele só vale se houver gente dentro, e o
 * espanhol dividia a sala num terceiro cômodo que ficava quase sempre vazio. Quem entrava por
 * ali via um chat morto e concluía que o jogo não tem ninguém, que é o oposto do que o chat
 * existe para mostrar. Duas salas cheias valem mais do que três pela metade.
 *
 * A lista do SERVIDOR continua com `es` (ver `IDIOMAS_CHAT` no `protocol.mjs`): as mensagens
 * antigas não deixam de existir, e reabrir a bandeira um dia é só voltar o `id` aqui.
 */
const IDIOMAS_CHAT_ATIVOS = ['pt', 'en'];
const IDIOMAS_DO_CHAT = () => IDIOMAS.filter((l) => IDIOMAS_CHAT_ATIVOS.includes(l.id));

/**
 * Em que bandeira o chat abre.
 *
 * Cai na do jogo quando ela é uma das duas; senão, no INGLÊS — quem joga em espanhol vinha do
 * canal `es`, e mandá-lo para o português seria trocar uma língua que ele não fala por outra.
 * Sem esta conversão a preferência guardada (`es`) sobreviveria e o chat abriria numa bandeira
 * que não existe mais na barra: nenhuma acesa, e a lista vazia para sempre.
 */
function idiomaChatInicial() {
  let guardado = null;
  try { guardado = localStorage.getItem('idiomaChat'); } catch { /* modo privado */ }
  if (IDIOMAS_CHAT_ATIVOS.includes(guardado)) return guardado;
  const escolhido = IDIOMAS_CHAT_ATIVOS.includes(idioma()) ? idioma() : 'en';
  try { localStorage.setItem('idiomaChat', escolhido); } catch { /* quota */ }
  return escolhido;
}

