// ------------------------------------------------------------------ conexão

/** Timer da próxima tentativa de reconexão (só um de cada vez). */
let reconectarTimer = null;

/**
 * A conta foi aberta noutro aparelho (ou aba) e o servidor fechou esta sessão com 4001.
 *
 * Enquanto estiver ligada, NADA reconecta sozinho — nem o `onclose`, nem a volta do foco, nem a
 * rede que volta (`online`), nem um `enviar` de relógio. Só o "Jogar aqui" do aviso. O 4001 já
 * barrava a reconexão do `onclose`, mas os outros três caminhos ficavam abertos: o tablet
 * esquecido em casa reconectava na primeira oscilação do Wi-Fi e tomava a conta do celular, que
 * a tomava de volta no evento seguinte. Tomar a conta tem de ser sempre um gesto de alguém.
 */
let sessaoTomada = false;

function mostrarSessaoTomada() {
  sessaoTomada = true;
  clearTimeout(reconectarTimer);
  reconectarTimer = null;
  $('#sessao-tomada')?.classList.remove('hidden');
}

$('#sessao-tomada-jogar')?.addEventListener('click', () => {
  sessaoTomada = false;
  $('#sessao-tomada')?.classList.add('hidden');
  estado.tentativasReconexao = 0;
  logCena(t('ev.reconectando'));
  conectar();
});

/**
 * Agenda uma reconexão. Substitui `setTimeout(conectar, …)` solto: centraliza o cancelamento
 * (um `visibilitychange` ou um `online` pode querer reconectar JÁ) e evita dois sockets no ar.
 */
function agendarReconexao(ms = 1500) {
  clearTimeout(reconectarTimer);
  reconectarTimer = setTimeout(conectar, ms);
}

function fecharSocketAtual() {
  if (!estado.ws) return;
  try { estado.ws.close(); } catch {}
  estado.ws = null;
}

function conectar() {
  clearTimeout(reconectarTimer);
  reconectarTimer = null;

  // Outra sessão tomou a conta: só o "Jogar aqui" reabre — ver `sessaoTomada`.
  if (sessaoTomada) return;

  // Já tem um socket abrindo, aberto ou fechando: não abre um segundo.
  if (estado.ws && estado.ws.readyState <= 1) return;

  const sessao = sessaoSalva();
  if (!sessao?.token) {
    $('#app').classList.add('hidden');
    $('#portal').classList.remove('hidden');
    mostrarLogin();
    toast(t('auth.precisaLogin'));
    return;
  }

  const proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
  const ws = new WebSocket(`${proto}//${location.host}`);
  estado.ws = ws;
  estado.ultimaMsgEm = Date.now();
  estado.ultimaMsgJogo = Date.now();

  ws.onopen = () => {
    estado.ultimaMsgEm = Date.now();
    estado.ultimaMsgJogo = Date.now();
    // `delta: 1` diz ao servidor que ESTE cliente sabe remontar o estado que vem em
    // pedaços. Não é enfeite de versão: no deploy o socket cai e o cliente RECONECTA sem
    // recarregar a página (ver `onclose`, logo abaixo), então quem estava jogando na hora
    // continua com o `app.js` antigo em memória falando com o servidor novo. Sem esta
    // bandeira, o servidor mandaria delta para um cliente que espera o quadro inteiro e a
    // tela quebrava — para todo mundo que estivesse online, até apertar F5.
    // `dispositivo` vai junto porque o caminho normal de quem já joga NÃO passa por
    // `/auth/entrar`: a sessão fica 30 dias no `localStorage` e o jogo abre direto no socket.
    // Sem isto, o carimbo de origem só enxergaria quem digita senha ou entra por provedor — ou
    // seja, quase ninguém depois da primeira semana.
    enviar({ t: 'hello', nick: sessao.nick, token: sessao.token, delta: 1, dispositivo: idDispositivo() });
  };

  ws.onmessage = (ev) => {
    // Marca de vida da conexão: o vigia abaixo usa isto para derrubar um socket meio-aberto
    // (notebook que dormiu, NAT que trocou de porta, sim reiniciado no deploy) que o
    // navegador ainda mostra como "aberto" mas por onde não chega mais nada.
    estado.ultimaMsgEm = Date.now();
    const m = JSON.parse(ev.data);
    if (m.t === 'pong') return; // resposta do keepalive — só serve para marcar vida acima
    // Sessão renovada pelo servidor (passou da metade dos 30 dias). Guardar é tudo o que há
    // para fazer: é o que impede a aba aberta há semanas de cair no login na próxima queda
    // de conexão. Não mexe em nada da tela.
    if (m.t === 'sessao.renovada') {
      const s = sessaoSalva();
      if (s && m.token) {
        s.token = m.token;
        guardarSessao(s);
      }
      return;
    }
    estado.ultimaMsgJogo = Date.now();
    // O estado chega em delta e é remontado aqui, no ponto de entrada — daqui para dentro
    // `estado.eu` é o quadro completo de sempre. Ver `mesclarEstado`.
    if (m.t === 'welcome') {
      estado.tentativasReconexao = 0;
      m.estado = mesclarEstado(m.estado);
      aoEntrar(m);
    } else if (m.t === 'estado') aplicarEstado(mesclarEstado(m.estado));
    else if (m.t === 'batalha') for (const e of m.ev) aoEvento(e);
    else if (m.t === 'campo.init') {
      estado.campo?.iniciar(m);
      // Saindo da praça, o herói volta a ser o pokémon — e o sprite dele não vem no
      // `campo.init` da hunt. Sem isto o jogador caçava com o boneco do treinador no lugar do
      // Charmander até o snapshot seguinte, um quarto de segundo depois.
      if (!m.centro && !m.pvp) aplicarHeroiAtivo(estado.eu);
      if (m.casa) syncCasaBonecoBotoes();
      pintarBarraBoss();
    }
    else if (m.t === 'campo') {
      estado.campo?.aplicar(m);
      if (huntSemMobVivoNoCampo()) estado._spawnOndaAtual = false;
      pintarBarraBoss();
    }
    else if (m.t === 'ranking') {
      if (m.aba === 'bosses' && m.bossKey) {
        (estado.rankingBoss ??= {})[m.bossKey] = m.linhas;
      } else {
        estado.ranking[m.aba] = m.linhas;
      }
      if (estado.modalAberto === 'ranking') pintarRanking();
    } else if (m.t === 'perfil') mostrarPerfil(m.perfil);
    else if (m.t === 'estatisticas') pintarEstatisticasDaConta(m);
    else if (m.t === 'ranking.ficha') abrirFichaDoPokemon(m.pokemon);
    else if (m.t === 'pvp') aoReceberPvp(m);
    else if (m.t === 'passe') aoReceberPasse(m);
    else if (m.t === 'guild') aoReceberGuild(m);
    else if (m.t === 'ginasio') aoReceberGinasio(m);
    else if (m.t === 'treino') aoReceberTreino(m);
    else if (m.t === 'caixa.npc') aoReceberCaixaNpc(m);
    else if (m.t === 'campeonato') aoReceberCampeonato(m);
    else if (m.t === 'convite') aoReceberConvite(m);
    else if (m.t === 'oferenda') {
      // A MESMA resposta serve aos dois pedidos (o Auto Selecionar e o lote). Quem pediu é quem
      // recebe: as duas travas são exclusivas entre si, e sem este desvio o lote acenderia o
      // toast do outro botão.
      if ('protegidos' in m) {
        if (estado.ofrLote) ofrLoteTerminar(m.protegidos);
        else ofrAutoTerminar(m.protegidos);
      }
    }
    else if (m.t === 'amigos') aoReceberAmigos(m);
    else if (m.t === 'comercio') aoReceberComercio(m);
    else if (m.t === 'orbs') aoReceberOrbs(m);
    else if (m.t === 'chat') receberChat(m);
    else if (m.t === 'chat.historico') mesclarChatHistorico(m.canal, m.mensagens ?? []);
    else if (m.t === 'chat.del') excluirChat(m.id);
    else if (m.t === 'chat.fixadas') receberChatFixadas(m.lista ?? []);
    else if (m.t === 'chat.fixada') receberChatFixada(m);
    else if (m.t === 'chat.mute') aplicarMuteChat(m.ate);
    // `nick` vem em avisos que precisam de placeholder (mute ok, etc.).
    else if (m.t === 'chat.aviso') {
      if (m.chave === 'chat.modMuteOk') toast(t('chat.modMuteOk', { nick: m.nick ?? '', minutos: m.minutos ?? '' }));
      // Resposta de comando vai em TOAST e não na lista: o `/mute` pode ter sido digitado no
      // painel da guild, e a linha de aviso ficaria fora de vista.
      // As respostas de fixar/desafixar também: são confirmação de um clique no menu, e não fala.
      else if (['chat.cmd', 'chat.fixar', 'chat.desafixar'].some((p) => String(m.chave ?? '').startsWith(p))) {
        toast(t(m.chave, { nick: m.nick ?? '', minutos: m.minutos ?? '' }));
      }
      else mostrarAvisoChat(m.chave, { nick: m.nick ?? '', minutos: m.minutos, tempo: m.tempo ?? '' });
    }
    else if (m.t === 'shiny.captura') mostrarAnuncioShinyCaptura(m);
    else if (m.t === 'lendario.captura') mostrarAnuncioLendarioCaptura(m);
    else if (m.t === 'shiny.lista') receberShinys(m);
    else if (m.t === 'p5.lista') receberP5s(m);
    else if (m.t === 'casas.lista') receberRegistroCasas(m);
    else if (m.t === 'bicicletas.lista') receberRegistroBikes(m);
    else if (m.t === 'market') receberMercado(m);
    // `chave` é a versão traduzível do erro; `msg` é o texto em português que os avisos
    // antigos do gateway ainda mandam cru. Preferir a chave quando ela vier deixa os dois
    // conviverem sem ter de i18n-izar tudo de uma vez.
    else if (m.t === 'erro') {
      // `motivoBan` é o texto que a moderação escreveu. Ele vem À PARTE da `chave` porque a
      // linha acima prefere a chave (para traduzir) — e era assim que o motivo do ban chegava
      // pelo socket e sumia sem nunca aparecer para quem tomou o ban.
      const base = m.chave ? t(m.chave) : m.msg;
      toast(m.motivoBan ? `${base}\n${t('login.banMotivo')} ${m.motivoBan}` : base);
      // Recusa do chat (o intervalo de 5 s é a mais comum): a mensagem já foi apagada do
      // input no envio otimista, então devolvemos o texto para o jogador não perder o que
      // digitou. Só se o input estiver vazio — se ele já começou outra frase no meio do
      // round-trip, ela é que vale.
      if (CHAVES_ERRO_CHAT.has(m.chave) && ultimoChatTentado) {
        const inp = $('#chat-input');
        if (inp && !inp.value.trim()) {
          inp.value = ultimoChatTentado;
          inp.focus();
          inp.setSelectionRange?.(inp.value.length, inp.value.length);
        }
        ultimoChatTentado = '';
      }
    }
  };

  ws.onclose = (ev) => {
    // Só o socket ATUAL comanda a reconexão. Um `close` atrasado de um socket velho (que o
    // vigia acabou de derrubar) não deve reagendar por cima da tentativa que já está de pé.
    if (estado.ws !== ws) return;
    // A prancheta vai ao disco AGORA, com os kills que o tique de 2 s ainda não gravou: daqui
    // para a frente o relógio dela para, e só volta a andar quando o socket voltar.
    salvarSessaoHunt(Date.now(), true);
    estado.ws = null;
    // Outro aparelho, outra aba (ou reconexão mais nova) tomou esta conta — reconectar aqui só
    // gera loop. O aviso fica na tela até alguém escolher jogar aqui de novo.
    if (ev.code === 4001) {
      logCena(t('ev.substituido'));
      mostrarSessaoTomada();
      // Esta aba não reconecta mais — segurar a tela dela acesa seria gastar bateria à toa.
      manterTelaAcesa(false);
      return;
    }
    // A rede foi banida pelo painel: reconectar só bateria na mesma porta, em laço.
    if (ev.code === 4003) {
      logCena(t('auth.ipBanido'));
      toast(t('auth.ipBanido'));
      manterTelaAcesa(false);
      return;
    }
    logCena(t('ev.reconectando'));
    // Rede que piscou volta em ~1–2 s; servidor reiniciando (1012) espalha a volta por até 15 s, e
    // cada falha seguida dobra a espera — ver `shared/reconexao.mjs`.
    estado.tentativasReconexao = (estado.tentativasReconexao ?? 0) + 1;
    agendarReconexao(atrasoDeReconexao({ tentativa: estado.tentativasReconexao, codigo: ev.code }));
  };
  ws.onerror = () => {};
}

// ---------------------------------------------------------------- vida da conexão
//
// O servidor tem heartbeat (derruba socket sem tráfego do cliente em ~60 s) e, do lado dele, uma
// carência de reconexão que segura a equipe e a hunt por 90 s. O que faltava era o cliente
// PERCEBER que caiu: sem FIN de TCP — notebook que dorme, Wi-Fi que oscila, aba de segundo
// plano congelada pelo Chrome, deploy do sim — o `onclose` nunca dispara e o jogo fica
// eternamente "aberto" sem receber nada. Estes três mecanismos fecham esse buraco.

/** Keepalive: um ping a cada 25 s mantém a conexão viva através de NAT/proxy e alimenta o vigia. */
setInterval(() => {
  if (estado.ws?.readyState === 1) {
    try { estado.ws.send(JSON.stringify({ t: 'ping' })); } catch {}
  }
}, 25000);

/** Vigia: socket "aberto" mas sem jogo há 30 s está morto — derruba para o `onclose` reconectar.
 *  Pong NÃO conta: o gateway responde ping mesmo com o sim congelado na carência de reconexão. */
setInterval(() => {
  const ultimo = estado.ultimaMsgJogo || estado.ultimaMsgEm || 0;
  if (estado.ws?.readyState === 1 && Date.now() - ultimo > 30000) {
    try { estado.ws.close(); } catch {}
  }
}, 10000);

/**
 * Voltou o foco (ou a rede): se o socket não está aberto, reconecta AGORA em vez de esperar
 * o próximo tique do timer — que, numa aba que estava congelada, pode nem ter corrido. Se
 * está aberto, cutuca com um ping: uma aba que ficou horas em segundo plano quase sempre
 * tem um socket zumbi, e o perde-resposta manda o vigia derrubar em seguida.
 */
function verificarConexao() {
  if (sessaoTomada || !sessaoSalva()?.token) return;
  if (estado.ws?.readyState === 1) {
    try { estado.ws.send(JSON.stringify({ t: 'ping' })); } catch {}
  } else if (!estado.ws || estado.ws.readyState >= 2) {
    conectar();
  }
}
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') verificarConexao();
});
window.addEventListener('online', verificarConexao);
window.addEventListener('focus', verificarConexao);

/**
 * Manda um comando. Se o socket estiver caído, avisa em vez de engolir em silêncio —
 * um clique que não faz nada e não explica é o pior tipo de bug para o jogador.
 */
function enviar(obj) {
  if (estado.ws?.readyState !== 1) {
    // O aviso de sessão tomada já está na tela, e reconectar daqui tomaria a conta de volta
    // sem ninguém ter pedido — ver `sessaoTomada`.
    if (sessaoTomada) return false;
    toast(t('ev.semConexao'));
    if (sessaoSalva()?.token) agendarReconexao(500);
    return false;
  }
  try {
    estado.ws.send(JSON.stringify(obj));
  } catch {
    toast(t('ev.semConexao'));
    try { estado.ws?.close(); } catch {}
    estado.ws = null;
    if (sessaoSalva()?.token) agendarReconexao(500);
    return false;
  }
  return true;
}

// --------------------------------------------------------------- carregando
//
// O jogo precisa de alguns megabytes antes de valer alguma coisa: 443 espécies, 295 itens, o
// atlas de retratos e o índice de outfits. Antes isso acontecia DEPOIS do clique em "Entrar",
// com a tela parada e um "carregando…" de texto; agora acontece na frente da pessoa, com a
// arte do jogo e uma barra que anda de verdade.
//
// "De verdade" importa: a barra avança por ETAPA CONCLUÍDA, não num relógio fingindo
// progresso. Quando ela para num pedaço grande, é porque aquilo está mesmo baixando.

/** O Pikachu que corre na ponta da barra. Direção 2 = leste, olhando para onde ele vai. */
const LOOKTYPE_PIKACHU = 59;
/** O Mew que senta no botão de logar, como na arte de referência da tela de entrada. */
const LOOKTYPE_MEW = 9;

/**
 * Os três MARCOS da barra: 30%, 70% e 100%, com uma respirada em cada um.
 *
 * A barra continua andando por trabalho de verdade — o que mudou é o RITMO. Antes ela dava
 * seis saltinhos de 16% e sumia; numa máquina rápida isso passava em meio segundo e a arte
 * nem chegava a ser vista. Agora cada marco espera as suas etapas terminarem E o tempo mínimo
 * passar, então a entrada tem sempre o mesmo compasso: enche, respira, enche, respira, entra.
 *
 * `pausaMs` é a respirada DEPOIS de chegar no número — é ela que dá o "demora um pouco" entre
 * um marco e o outro. `minMs` é o piso do trecho, para a barra não pular 0 → 70 num cache
 * quente. As duas coisas juntas somam ~2,4 s de entrada, que é o tempo de ler o nome do jogo.
 */
const MARCOS = [
  { pct: 30, minMs: 600, pausaMs: 450 },
  { pct: 70, minMs: 700, pausaMs: 520 },
  { pct: 100, minMs: 500, pausaMs: 620 },
];

const carga = {
  /** Peso já concluído e peso total, em bytes esperados. */
  feitas: 0,
  total: 1,
  /** Fração (0..1) da etapa que está baixando agora, para a barra andar DENTRO dela. */
  parcial: 0,
  /** Quando não é null, a barra ignora a conta e obedece este número (os marcos). */
  forcada: null,
  /** Fecha a etapa atual e soma o peso dela. */
  passo(peso, rotulo) {
    this.feitas += peso;
    this.parcial = 0;
    this.pintar(rotulo);
  },
  /** Progresso dentro da etapa atual: `fracao` de `peso` bytes. */
  andando(peso, fracao) {
    this.parcial = peso * fracao;
    this.pintar();
  },
  /** Leva a barra a um número exato (usado pelos marcos). */
  irPara(pct, rotulo) {
    this.forcada = pct;
    this.pintar(rotulo);
  },
  pintar(rotulo) {
    const pct = this.forcada
      ?? Math.min(100, Math.round(((this.feitas + this.parcial) / this.total) * 100));
    const fill = $('#carga-fill');
    if (fill) fill.style.width = `${pct}%`;
    // O corredor acompanha a ponta do preenchido. `calc` porque a barra tem 3 px de recuo de
    // cada lado, e sem descontar isso o Pikachu chega ao fim antes da barra.
    const corredor = $('#carga-corredor');
    if (corredor) corredor.style.left = `calc(3px + (100% - 6px) * ${pct / 100})`;
    const num = $('#carga-pct');
    if (num) num.textContent = pct;
    const etapa = $('#carga-etapa');
    if (etapa && rotulo) etapa.textContent = t(rotulo);
  },
};

/**
 * Baixa um arquivo relatando o progresso REAL, byte a byte.
 *
 * O `content-length` de uma resposta comprimida conta bytes do FIO, mas o que o stream entrega
 * ao JS já vem descomprimido pelo navegador — dividir um pelo outro daria uma barra fechando em
 * 600%. Por isso o servidor manda `x-bytes-crus` com o tamanho antes do gzip, e é contra ele
 * que a fração é medida (ver `gateway.mjs`).
 *
 * Sem `x-bytes-crus` (um proxy que recomprime, um arquivo pequeno demais para gzip) a fração
 * não é calculável: aí não se relata nada e a etapa vale tudo-ou-nada, que é o comportamento
 * antigo. Melhor uma etapa sem barra fina do que uma barra mentindo.
 */
async function baixar(url, aoProgredir) {
  const r = await fetch(url, SEM_CACHE);
  const total = Number(r.headers.get('x-bytes-crus') ?? r.headers.get('content-length') ?? 0);
  if (!r.body || !total || !aoProgredir) return r.json();

  let lidos = 0;
  const pedacos = [];
  const leitor = r.body.getReader();
  for (;;) {
    const { done, value } = await leitor.read();
    if (done) break;
    pedacos.push(value);
    lidos += value.length;
    aoProgredir(Math.min(1, lidos / total));
  }
  aoProgredir(1);
  return JSON.parse(new TextDecoder().decode(await new Blob(pedacos).arrayBuffer()));
}

/**
 * A arte do topo do portal. `carga` é o banner (acompanha a barra) e `login` é a ilustração
 * de entrada, com o time inteiro na floresta.
 *
 * Duas imagens no mesmo `<img>` em vez de duas `<img>` empilhadas: com as duas no HTML, o
 * navegador baixaria as duas na análise da página e a barra de carregamento estaria esperando
 * uma arte que ainda nem é para aparecer.
 */
const ARTE_PORTAL = { carga: 'img/banner.jpg', login: 'img/login.jpg' };
function trocarArteDoPortal(qual) {
  const img = $('#portal-img');
  if (img && ARTE_PORTAL[qual]) img.src = ARTE_PORTAL[qual];
}

/** Baixa uma imagem e só resolve quando ela está decodificada e pronta para desenhar. */
const preloadImagem = (src) =>
  new Promise((ok) => {
    const i = new Image();
    i.onload = i.onerror = () => ok();
    i.src = src;
  });

/** Espelho + creatures-novos + outland-novos + patches do lab — o mesmo merge que content.mjs faz no servidor. */
async function carregarCatalogoEspecies(aoProgredir) {
  const cr = await baixar('/assets/creatures.json', aoProgredir);
  const lista = [...(cr.creatures ?? [])];
  try {
    const extra = await fetch('/assets/creatures-novos.json', SEM_CACHE).then((r) => (r.ok ? r.json() : null));
    if (extra?.creatures?.length) lista.push(...extra.creatures);
  } catch { /* opcional — Pokédex fica só com o espelho */ }
  try {
    const outland = await fetch('/assets/creatures-outland-novos.json', SEM_CACHE).then((r) => (r.ok ? r.json() : null));
    if (outland?.creatures?.length) lista.push(...outland.creatures);
  } catch { /* opcional — Outland #2048+ fica só no servidor */ }
  // O espelho idleworld pode vir com Outland em #10501+; normaliza para #2001+ como o content.mjs.
  aplicarRemapOutlandLista(lista);
  try {
    const lab = await fetch('/assets/creatures-sprites-lab.json', SEM_CACHE).then((r) => (r.ok ? r.json() : null));
    for (const p of lab?.patches ?? []) {
      const c = lista.find((x) => x.pokeId === p.pokeId);
      if (c && p.looktype) c.looktype = p.looktype;
    }
  } catch { /* opcional */ }
  // Auditoria pokemondb das espécies base-only (só existem no espelho). Mesmo merge do content.mjs.
  try {
    const ovr = await fetch('/assets/creatures-audit-overrides.json', SEM_CACHE).then((r) => (r.ok ? r.json() : null));
    for (const o of ovr?.overrides ?? []) {
      const c = lista.find((x) => x.pokeId === o.pokeId);
      if (!c) continue;
      for (const k of ['baseHp', 'baseAtk', 'baseDef', 'baseSpAtk', 'baseSpDef', 'baseSpeed']) {
        if (typeof o[k] === 'number') c[k] = o[k];
      }
      if (Array.isArray(o.attacks)) c.attacks = o.attacks.map((a) => ({ ...a }));
    }
  } catch { /* opcional — Pokédex fica com os moves do espelho */ }
  // Os golpes das planilhas (iniciais, pseudo-lendários) — mesmo ponto do content.mjs: antes do Outland.
  aplicarGolpesDasPlanilhas((id) => lista.filter((c) => c.pokeId === id));
  herdarLooktypeOrre(lista);
  herdarLooktypeOutland(lista);
  herdarBaseOutland(lista); // variantes Outland herdam stats + moves da espécie-base
  // Vigoroth → Slaking e Shelgon → Salamence, antes da injeção de golpes: é o que tira deles o
  // ultimate de última evolução, exatamente como o servidor faz. Sem esta linha a Pokédex
  // dizia "não evolui" nos dois, enquanto o botão Evoluir funcionava.
  aplicarCadeiasTruncadas(lista);
  normalizarEvolveLevel600(lista);
  aplicarAjustesHuntLevel((id) => lista.find((c) => c.pokeId === id));
  for (const c of lista) {
    if (isEspelhoFantasmaPokeId(c.pokeId)) continue;
    for (const l of c.loot ?? []) l.name = resolverNomeItem(l.name);
    if (c.loot?.length) c.loot = c.loot.filter((l) => !itemMortoPorNome(l.name));
    injetarGolpesEspeciais(c);
    normalizarSellValue(c);
    // Variante de Outland NÃO evolui — o servidor zera o par no boot, e o `pokemon.evoluir`
    // recusa de saída. Sem espelhar aqui, a ficha do Ancient Dragonair prometia "vira Dragonite
    // no Nv 100" e a pedra de dragão listava ele entre quem a usa: duas promessas que o
    // servidor não cumpre.
    if (isOutlandPokeId(c.pokeId)) {
      c.evolvesToId = 0;
      c.evolveLevel = 0;
    }
    estado.especies.set(c.pokeId, c);
    estado.especiePorNome.set(c.name, c);
  }
  // Os elos entre gerações (Sneasel → Weavile, Gligar → Gliscor…) NÃO estão nos JSONs: o
  // espelho nunca conheceu Sinnoh. O servidor escreve os dele no boot e a Pokédex daqui
  // continuaria dizendo "não evolui" — é por isso que a tabela mora em `shared/`. Depois do
  // laço acima pelo mesmo motivo que lá no servidor: a ordem contra `injetarGolpesEspeciais`
  // é o que decide se o Makuhita mantém o golpe de 600 que ele já tem.
  // Os clones de ORRE (#13xxx) copiam a lista de golpes do nacional, e aqui — depois do laço
  // acima, que é onde `injetarGolpesEspeciais` roda. A injeção olha para a cadeia de evolução
  // de cada espécie, e a do clone é truncada (não existe Dusknoir de Orre): copiar antes dela
  // deixava o clone com dois golpes de 600 que a Pokédex da espécie não tem. Mesma ordem do
  // servidor — a ficha do jogador e a Pokédex saem daqui, e têm de contar a mesma história.
  herdarGolpesOrre(lista);
  aplicarEvolucoesEntreGeracoes(lista);
  alinharNivelPadraoRamificado(lista);
  corrigirNiveisDeEvolucao(lista);
  // O teto de captura (`tetoCaptura`) e o alinhamento dos degraus de evolução de Outland+ à
  // mesma escada. POR ÚLTIMO entre os ajustes de evolução, na mesma ordem do servidor: as
  // quatro linhas acima escrevem `evolveLevel`, e uma delas rodando depois desfaria isto.
  const { estagios } = aplicarTetoDeCaptura(lista, (id) => estado.especies.get(id));
  // O piso da linhagem do N=, na mesma posição do servidor: depois dos elos entre gerações, que
  // são justamente as cadeias em que evoluir derrubava a nota. Fora de ordem, a calculadora daqui
  // A Sun Stone não cai de nenhuma hunt do espelho — a fonte mora em `shared/drops-nossos.mjs`.
  // Aqui também, senão a hunt solta a pedra e a ficha da espécie não a lista.
  aplicarDropsNossos(lista);
  /**
   * As 59 MEGAS (#3026…#3780), no MESMO ponto do `content.mjs`: depois dos golpes, das
   * evoluções, do teto de captura e dos drops — e antes do piso da linhagem.
   *
   * A Pokédex daqui é montada deste catálogo, não do que o servidor manda; sem estas duas
   * linhas a aba "Mega" viria vazia e a ficha de um Mega Gengar do jogador não acharia a
   * espécie #3094 para desenhar.
   */
  for (const esp of criarEspeciesMega(lista)) {
    lista.push(esp);
    estado.especies.set(esp.pokeId, esp);
    estado.especiePorNome.set(esp.name, esp);
  }
  // e a nota que o servidor manda contariam histórias diferentes para o mesmo pokémon.
  anotarLinhagemDaNota(lista, (id) => estado.especies.get(id), elosMegaDaNota(lista));
  // O valor da espécie: sobe ao da hunt quem tem nível de Kanto e só aparece acima dele, e o
  // pré-evolução fica abaixo da evolução (`shared/valor-cadeia.mjs`). As hunts só chegam no
  // `welcome`, então `aoEntrar` chama de novo — a passagem parte sempre do mesmo valor.
  estagiosDoCatalogo = estagios;
  assentarValorDoCatalogo();
}

/** O mapa de estágios que `carregarCatalogoEspecies` montou — `null` antes de o catálogo chegar. */
let estagiosDoCatalogo = null;

/**
 * Assenta o valor das espécies com as hunts que houver até agora.
 *
 * A hunt mais baixa de cada espécie é por `pokeId` exato, como `nivelDeHuntDaEspecie` no servidor
 * (que monta a partir da mesma lista que vem no `welcome`), e não por dex como `huntsComEspecie`:
 * por dex o clone de Hoenn herdaria a hunt do nacional, e a Pokédex daria um valor que a venda não paga.
 */
function assentarValorDoCatalogo() {
  if (!estagiosDoCatalogo) return;
  const menor = new Map();
  for (const h of estado.hunts ?? []) {
    for (const e of h.especies ?? []) {
      const antes = menor.get(e.pokeId);
      if (antes == null || h.nivel < antes) menor.set(e.pokeId, h.nivel);
    }
  }
  assentarValorDasEspecies(estado.especies.values(), estagiosDoCatalogo, (id) => menor.get(id) ?? null);
}

/**
 * A sequência de boot. Cada `passo` é uma etapa da barra.
 *
 * Um erro em qualquer etapa NÃO trava a tela: o jogo entra sem aquele pedaço (um ícone que
 * falta é melhor que uma barra parada em 60% para sempre). Por isso os `catch` são silenciosos
 * e o boot segue.
 */
async function bootstrap() {
  // O Pikachu entra ANTES do primeiro passo e sem `await`: ele é enfeite, e esperar por ele
  // atrasaria o que o jogo precisa. Aparece sozinho quando o atlas dele chegar — e como ele
  // tem de correr a barra INTEIRA, começar a carregá-lo no fim (onde estava) o deixava visível
  // por meio segundo, que é o mesmo que não existir.
  $('#carga-corredor').appendChild(spriteAnimado(LOOKTYPE_PIKACHU, 46, 2));

  // As etapas em três GRUPOS, um por marco da barra, e cada uma com o PESO em bytes que ela
  // baixa. A barra anda por byte recebido, não por etapa concluída: com o gzip ligado
  // (`gateway.mjs`), `creatures.json` desceu de 981 kB para 72 kB, e uma barra que dá seis
  // saltinhos iguais não mostraria nada do que de fato está acontecendo.
  //
  // Os pesos são o tamanho CRU de cada arquivo — é ele que o navegador entrega ao JS depois de
  // descomprimir, e é contra ele que `baixar` mede a fração.
  const grupos = [
    [
      // O índice de outfits vem PRIMEIRO porque é ele que o Pikachu da barra espera: enquanto
      // ele não chega, o corredor é um canvas em branco, e numa conexão lenta o bicho só
      // aparecia perto do fim — justamente quando não há mais barra para correr.
      ['carga.sprites', 128e3, () => carregarIndice()],
      // O banner já começou a baixar sozinho (é uma `<img>` do HTML, o navegador dispara na
      // análise da página). Este passo só espera o mesmo pedido terminar, para a barra não
      // fechar em 100% com a arte ainda entrando.
      ['carga.arte', 418e3, () => preloadImagem('img/banner.jpg')],
    ],
    [
      ['carga.especies', 1630e3, (aoProgredir) => carregarCatalogoEspecies(aoProgredir)],
      ['carga.itens', 72e3, async () => {
        const [it, ic] = await Promise.all([
          fetch('/assets/items.json', SEM_CACHE).then((r) => r.json()),
          fetch('/assets/items-icons.json', SEM_CACHE).then((r) => r.json()),
        ]);
        for (const i of it.items) {
          if (IDS_ITEM_DUPLICADO.has(i.id)) continue;
          if (itemMortoDoJogo(i)) continue;
          estado.itens.set(i.id, ajustarItemEspelho(normalizarNpcPriceItem(i)));
          registrarIconeDoCatalogo(ic, i.id, i.icon);
        }
        estado.iconesItem = ic;
        estado.itensPorNome = null;
        // O REEQUILÍBRIO DA RENDA (ver `shared/economia-drop.mjs`) roda AQUI, e não dentro de
        // `carregarCatalogoEspecies`, por ordem de carregamento: as espécies entram na etapa
        // anterior deste mesmo grupo, mas o solver precisa do PREÇO de cada item, e o catálogo
        // de itens é justamente o que esta etapa acabou de montar.
        //
        // Sem isto a Pokédex desenharia a tabela de loot antiga — `listaDropsEspecie` lê
        // `especie.loot` direto — e prometeria ao jogador um drop que a hunt não larga mais.
        aplicarEconomiaDrop([...estado.especies.values()], precoDeVendaPorNomeItem);
        for (const [id, rel] of Object.entries(ICONES_ITEM_FIXOS)) estado.iconesItem[id] = rel;
        aplicarIconesTmElemental();
        estado.iconesItem[PVP_FICHA_ID] = estado.iconesItem[PVP_FICHA_ID] ?? 'site/assets/items/pvp_ficha.png';
      }],
    ],
    [
      ['carga.retratos', 495e3, () => atlasPronto],
      // A arte da tela de entrada. Baixada AQUI, e não quando o login abre, para a troca de
      // imagem acontecer com ela pronta — trocar o `src` na hora deixaria um buraco escuro no
      // lugar da ilustração enquanto ela decodifica.
      ['carga.entrada', 375e3, () => preloadImagem('img/login.jpg')],
    ],
  ];
  carga.total = grupos.flat().reduce((s, [, peso]) => s + peso, 0);
  carga.pintar('carga.iniciando');

  const dormir = (ms) => new Promise((r) => setTimeout(r, ms));

  for (const [i, grupo] of grupos.entries()) {
    const marco = MARCOS[i];
    const comecou = performance.now();
    for (const [rotulo, peso, fn] of grupo) {
      $('#carga-etapa').textContent = t(rotulo);
      // A etapa recebe um relator de progresso; quem não souber usar simplesmente ignora, e aí
      // ela vale tudo-ou-nada como antes.
      await Promise.resolve(fn((f) => carga.andando(peso, f))).catch(() => {});
      carga.passo(peso, rotulo);
    }
    // O trecho nunca termina antes do piso: é o que impede a barra de saltar direto ao fim
    // quando tudo já está no cache do navegador (agora, com ETag, é o caso comum na 2ª visita).
    await dormir(Math.max(0, marco.minMs - (performance.now() - comecou)));
    carga.irPara(marco.pct);
    // E a respirada no número redondo, que é o que se lê como "está fazendo alguma coisa".
    await dormir(marco.pausaMs);
  }

  // O quadro CONTINUA na tela — só o miolo troca. É a diferença entre "a tela de
  // carregamento saiu e a de login entrou" e "a moldura ficou, e o que estava dentro dela
  // virou outra coisa"; a segunda não pisca.
  $('#carregando').classList.add('hidden');
  trocarArteDoPortal('login');

  // O link de troca de senha ganha de tudo: quem chegou por ele veio TROCAR a senha, e entrar
  // direto por uma sessão antiga seria ignorar o motivo do clique.
  if (tokenRedefinir) return mostrarRedefinicao(tokenRedefinir);
  if (tokenAutorizarTrocaEmail) return mostrarAutorizacaoTrocaEmail(tokenAutorizarTrocaEmail);

  // Sessão guardada entra direto; o resto vê o login.
  const sessao = await alinharSessaoComServidor();
  // Quem entrou por provedor e fechou a aba antes de escolher o nick volta para o mesmo
  // passo: sem isto ele entraria com o nome inventado a partir da conta do Google, para sempre.
  if (sessao?.precisaNick) return mostrarEscolhaDeNick();
  if (sessao?.token) return conectar();
  mostrarLogin();
}

// ------------------------------------------------------------------- login
//
// Dois caminhos: conta com senha e provedor (Google/Discord). Sem sessão assinada, o WebSocket
// recusa o `hello` — não há entrada anônima.

const CHAVE_SESSAO = 'sessao';
const CHAVE_REF = 'pokeidle_ref';

/** Meta Pixel — conversões para anúncios no Facebook/Instagram. */
const pixelFb = (evento, params) => {
  try { if (typeof fbq === 'function') fbq('track', evento, params); } catch (_) {}
};

const refSalva = () => {
  try {
    return localStorage.getItem(CHAVE_REF) ?? '';
  } catch {
    return '';
  }
};

const refNoCorpo = (corpo) => {
  const ref = refSalva();
  if (ref) corpo.ref = ref;
  return corpo;
};

const sessaoSalva = () => {
  try {
    const s = JSON.parse(localStorage.getItem(CHAVE_SESSAO) ?? 'null');
    return s?.nick && s?.token ? s : null;
  } catch {
    return null;
  }
};
/**
 * Confere no servidor se o token ainda vale e se a conta ainda precisa escolher nick.
 * Sessões antigas no localStorage podem ficar sem `precisaNick` ou sem `contaId` no token —
 * aí o jogo abria com nick provisório, mas `/diamantes/comprar` recusava com "Entre na sua conta".
 */
async function alinharSessaoComServidor() {
  const sessao = sessaoSalva();
  if (!sessao?.token) return null;
  try {
    const r = await fetch('/auth/conta', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ token: sessao.token }),
    });
    if (!r.ok) {
      localStorage.removeItem(CHAVE_SESSAO);
      return null;
    }
    const conta = await r.json();
    // RENOVAÇÃO DESLIZANTE: passada a metade do prazo, o servidor manda um token novo junto da
    // ficha. Gravar aqui é o que faz quem joga direto nunca mais cair na tela de login — e é
    // de graça, porque esta chamada já acontece a cada carga de página.
    if (conta.tokenNovo) {
      sessao.token = conta.tokenNovo;
      guardarSessao(sessao);
    }
    if (conta.precisaNick) {
      sessao.precisaNick = true;
      guardarSessao(sessao);
      return sessao;
    }
    delete sessao.precisaNick;
    if (conta.nick && conta.nick !== sessao.nick) {
      sessao.nick = conta.nick;
      guardarSessao(sessao);
      localStorage.setItem('nick', conta.nick);
    }
    return sessao;
  } catch {
    return sessao;
  }
}
const guardarSessao = (s) => localStorage.setItem(CHAVE_SESSAO, JSON.stringify(s));
const atualizarSessaoNick = (nick, token) => {
  const s = sessaoSalva();
  if (!s) return;
  s.nick = nick;
  if (token) s.token = token;
  guardarSessao(s);
  localStorage.setItem('nick', nick);
};
/**
 * Encerra a sessão. O `nick` fica guardado de propósito — é conveniência de digitação no
 * próximo login, não credencial: sozinho ele não abre mais nada desde que o convidado saiu.
 */
const limparSessao = () => {
  localStorage.removeItem(CHAVE_SESSAO);
  limparCanalChatSessao();
};

/**
 * A linha vermelha do login. `detalhe` é a segunda linha, hoje o motivo do ban.
 *
 * O detalhe vai num FILHO criado aqui, com `textContent` — nunca `innerHTML`. É o único texto
 * desta tela que não foi escrito por nós: sai da mão da moderação, passa pelo banco e chega
 * cru. Montar HTML com ele seria dar a quem escreve o motivo do ban uma tag na tela de login
 * de quem tomou o ban.
 */
const erroLogin = (msg, ok = false, detalhe = '') => {
  const el = $('#login-erro');
  el.textContent = msg;
  el.classList.toggle('ok', ok);
  if (!detalhe) return;
  const linha = document.createElement('span');
  linha.className = 'erro-motivo';
  linha.textContent = detalhe;
  el.append(linha);
};

/**
 * O motivo do ban, pronto para virar a segunda linha — `''` quando o erro não for de ban.
 *
 * Lê tanto a resposta JSON do login com senha quanto os parâmetros da volta do OAuth: são
 * transportes diferentes (corpo e query) para o MESMO campo, e quem chama não deveria precisar
 * saber por qual dos dois o jogador entrou.
 */
const motivoDoBan = (fonte) => {
  const motivo = typeof fonte?.get === 'function' ? fonte.get('motivoBan') : fonte?.motivoBan;
  return motivo ? `${t('login.banMotivo')} ${motivo}` : '';
};

/**
 * A tela de ESCOLHER SENHA NOVA, que o link do e-mail abre (`/app?redefinir=<token>`).
 *
 * Mora no mesmo quadro do login, e não numa página do servidor, para a troca acontecer na tela
 * que a pessoa já conhece — um formulário solto com outra cara, chegando por e-mail, é
 * exatamente o que se ensina a desconfiar.
 *
 * Quem valida o token é o servidor, na hora de gravar. Aqui não há como saber se ele presta, e
 * fingir que sabe (checando formato, por exemplo) só daria uma mensagem errada mais cedo.
 */
function mostrarRedefinicao(token) {
  mostrarNoPortal('login');
  trocarArteDoPortal('login');
  $('#login-abas').classList.add('hidden');
  $('#form-entrar').classList.add('hidden');
  $('#form-criar').classList.add('hidden');
  $('#form-esqueci').classList.add('hidden');
  $('#login-social').classList.add('hidden');

  const form = document.createElement('form');
  form.className = 'login-form';
  form.id = 'form-redefinir';
  form.innerHTML = `
    <p class="login-aviso">${t('senha.escolhaNova')}</p>
    <label class="campo">
      <span>${t('login.senha')}</span>
      <span class="campo-linha"><span class="campo-bola"></span>
        <input id="nova-senha" type="password" maxlength="72" autocomplete="new-password" placeholder="••••••••"></span>
      <em>${t('login.senhaAjuda')}</em>
    </label>
    <label class="campo">
      <span>${t('login.senha2')}</span>
      <span class="campo-linha"><span class="campo-bola"></span>
        <input id="nova-senha2" type="password" maxlength="72" autocomplete="new-password" placeholder="••••••••"></span>
    </label>
    <button class="login-acao" id="salvar-senha" type="submit">${t('senha.salvar')}</button>`;
  $('#login').prepend(form);
  $('#nova-senha').focus();

  for (const sel of ['#nova-senha', '#nova-senha2']) {
    $(sel).onkeydown = (ev) => {
      if (ev.key === 'Enter') {
        ev.preventDefault();
        form.requestSubmit();
      }
    };
  }

  form.onsubmit = async (ev) => {
    ev.preventDefault();
    const senha = $('#nova-senha').value;
    const senha2 = $('#nova-senha2').value;
    if (senha.length < 8) return erroLogin(t('login.senhaCurta'));
    if (senha !== senha2) return erroLogin(t('login.senhasDiferentes'));

    const botao = $('#salvar-senha');
    botao.disabled = true;
    erroLogin(t('senha.salvando'));
    try {
      const r = await fetch('/auth/redefinir', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ token, senha }),
      });
      const dados = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(dados.erro ? t(dados.erro) : t('login.falhou'));
      // Trocou a senha: já entra. Pedir para digitar de novo o que ele acabou de escolher é
      // burocracia — o token do e-mail já provou que a caixa é dele.
      history.replaceState(null, '', location.pathname);
      entrarComo(dados);
    } catch (err) {
      botao.disabled = false;
      erroLogin(err.message);
    }
  };
}

/**
 * Passo 1 da troca de e-mail — quem clicou no link do e-mail ATUAL autoriza o passo 2.
 */
async function mostrarAutorizacaoTrocaEmail(token) {
  history.replaceState(null, '', location.pathname);
  mostrarNoPortal('login');
  trocarArteDoPortal('login');
  $('#login-abas').classList.add('hidden');
  $('#form-entrar').classList.add('hidden');
  $('#form-criar').classList.add('hidden');
  $('#form-esqueci').classList.add('hidden');
  $('#login-social').classList.add('hidden');

  const host = document.createElement('div');
  host.className = 'login-form';
  host.id = 'form-trocar-email';
  host.innerHTML = `<p class="login-aviso">${t('email.trocaCarregando')}</p>`;
  $('#login').prepend(host);

  let st;
  try {
    const r = await fetch(`/auth/trocar-email/status?token=${encodeURIComponent(token)}`);
    const dados = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(dados.erro ?? 'conta.linkVencido');
    st = dados;
  } catch (err) {
    host.innerHTML = `<p class="login-erro">${t(String(err.message))}</p>`;
    return;
  }

  host.innerHTML = `
    <h2 class="login-titulo-form">${t('email.trocaTitulo')}</h2>
    <p class="login-aviso">${t('email.trocaTexto', { nick: escapar(st.nick), atual: escapar(st.emailAtual), novo: escapar(st.emailNovo) })}</p>
    <p class="login-aviso login-aviso-dim">${t('email.trocaPasso2')}</p>
    <button type="button" class="login-acao" id="autorizar-troca-email">${t('email.trocaAutorizar')}</button>
    <p class="login-aviso login-aviso-dim hidden" id="troca-email-ok"></p>`;

  $('#autorizar-troca-email').onclick = async () => {
    const btn = $('#autorizar-troca-email');
    btn.disabled = true;
    btn.textContent = t('email.trocaEnviando');
    try {
      const r = await fetch('/auth/trocar-email/autorizar', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ token }),
      });
      const dados = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(dados.erro ?? 'login.falhou');
      btn.classList.add('hidden');
      const ok = $('#troca-email-ok');
      ok.classList.remove('hidden');
      ok.innerHTML = t('email.trocaEnviado', { email: escapar(dados.email ?? st.emailNovo) });
    } catch (err) {
      btn.disabled = false;
      btn.textContent = t('email.trocaAutorizar');
      erroLogin(t(String(err.message)));
    }
  };
}

function mostrarLogin() {
  mostrarNoPortal('login');
  trocarArteDoPortal('login');
  $('#form-esqueci').classList.add('hidden');
  const guardado = localStorage.getItem('nick');
  if (guardado) $('#login-id').value = guardado;
  $('#login-id').focus();
  // O Mew do botão. Direção 4 = oeste, para ele olhar para o texto e não para fora da tela.
  const mascote = $('#acao-mascote');
  if (mascote && !mascote.childElementCount) mascote.appendChild(spriteAnimado(LOOKTYPE_MEW, 36, 4));
  // Voltou do link do e-mail: a confirmação é a metade da tarefa, e a outra metade é entrar.
  // O aviso é VERDE e fica na tela (o toast some em três segundos, e quem clicou no link do
  // celular e voltou para a aba do computador nunca o veria).
  if (params.get('emailOk')) erroLogin(t('conta.emailConfirmadoEntre'), true);
  if (params.get('emailTrocado')) erroLogin(t('conta.emailTrocado'), true);
  // Os botões de provedor só aparecem se o servidor disser que estão configurados — um
  // "Continuar com Google" que devolve erro é pior que não existir.
  fetch('/auth/provedores')
    .then((r) => r.json())
    .then(aplicarProvedores)
    .catch(() => $('#login-social').classList.add('hidden'));
  turnstileDesenhar('entrar');
}

// Enter envia o formulário da aba em que se está.
//
// A submissão implícita do navegador (Enter num campo de texto de um form com botão submit)
// deveria bastar, e não basta: ela não dispara para eventos de teclado sintéticos, então o
// teste de teclado — que existe justamente porque um bug de Enter já passou por aqui uma vez —
// nunca entraria no jogo. `requestSubmit` dispara o mesmo `submit` que o botão dispararia,
// validação inclusive.
//
// Cuidado: num handler de propriedade (onkeydown), retornar false cancela a ação padrão e a
// tecla não chega a ser digitada. Por isso o corpo é um bloco, sem valor de retorno.
for (const sel of ['#login-id', '#login-senha', '#cad-nick', '#cad-email', '#cad-senha', '#cad-senha2', '#esq-email']) {
  $(sel).onkeydown = (ev) => {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      ev.target.closest('form')?.requestSubmit();
    }
  };
}

// -------------------------------------------------------- Turnstile (captcha do login)
//
// `onTurnstilePronto` é o callback do `?onload=` no <script> do index.html — a API do
// Cloudflare pode carregar antes ou depois do fetch de /auth/provedores responder, então os
// dois widgets só desenham quando TANTO a API quanto a site key (que vem do servidor) já
// chegaram. Sem site key configurada no servidor, nada disto roda — os dois campos ficam
// vazios e `pegarTurnstileToken` sempre devolve string vazia, que é o que o servidor espera
// quando TURNSTILE_SECRET_KEY também está vazia (captcha desligado nos dois lados).
let turnstileSiteKey = null;
let turnstileApiPronta = false;
const turnstileIds = { entrar: null, criar: null, esqueci: null };

/** Desenha o widget de um form, uma vez só — chamado de novo não faz nada. */
function turnstileDesenhar(form) {
  if (!turnstileSiteKey || !turnstileApiPronta || turnstileIds[form] != null) return;
  const el = $(`#turnstile-${form}`);
  if (!el) return;
  turnstileIds[form] = window.turnstile.render(el, { sitekey: turnstileSiteKey, size: 'flexible' });
}

window.onTurnstilePronto = () => {
  turnstileApiPronta = true;
  turnstileDesenhar('entrar');
  // O de "criar conta" só desenha quando a aba abre: um container `display:none` não tem
  // largura para o `size: 'flexible'` calcular, e o widget nasce cortado.
  if (!$('#form-criar').classList.contains('hidden')) turnstileDesenhar('criar');
};

/** O token da vez, ou '' se o captcha nem estiver ligado — o servidor aceita os dois. */
const pegarTurnstileToken = (form) => {
  const id = turnstileIds[form];
  return id != null ? (window.turnstile.getResponse(id) ?? '') : '';
};

/** Depois de um erro o token já foi consumido — sem isto a segunda tentativa falha sempre. */
const turnstileResetar = (form) => {
  const id = turnstileIds[form];
  if (id != null) window.turnstile.reset(id);
};

/** Remove os widgets quando o jogador entra — parar de rodar o Turnstile escondido evita
 *  iframes do Cloudflare refrescando em background (ruído no console e possível custo). */
function turnstileDestruir() {
  for (const form of ['entrar', 'criar', 'esqueci']) {
    const id = turnstileIds[form];
    if (id == null) continue;
    try { window.turnstile.remove(id); } catch {}
    turnstileIds[form] = null;
    $(`#turnstile-${form}`)?.replaceChildren();
  }
}

$('#login-abas').onclick = (ev) => {
  const b = ev.target.closest('.login-aba');
  if (!b) return;
  $('#form-esqueci').classList.add('hidden');
  for (const outro of b.parentElement.children) outro.classList.toggle('on', outro === b);
  const criando = b.dataset.aba === 'criar';
  $('#form-entrar').classList.toggle('hidden', criando);
  $('#form-criar').classList.toggle('hidden', !criando);
  // Criar conta tem quatro campos e é mais alto que a tela de um notebook. O quadro avisa o
  // CSS para encolher o banner — melhor perder um pedaço da arte do que empurrar os botões de
  // provedor para baixo da dobra. Com confirmação de e-mail são só três campos (sem nick).
  $('#portal').classList.toggle('compacto', criando && !confirmacaoEmail);
  erroLogin('');
  if (criando) {
    $(confirmacaoEmail ? '#cad-email' : '#cad-nick').focus();
    turnstileDesenhar('criar');
  } else $('#login-id').focus();
};

const NICK_OK = /^[a-zA-Z0-9_]{3,16}$/;
const EMAIL_OK = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/** Com Resend ligado, o cadastro por e-mail não pede nick — ele vem depois de confirmar. */
let confirmacaoEmail = false;
/** Se algum provedor está ligado. Quem volta do "esqueci" precisa saber se o bloco social
 *  reaparece ou continua escondido — remostrá-lo sempre deixaria um "ou" com nada embaixo. */
let temProvedores = false;

const aplicarProvedores = (p) => {
  confirmacaoEmail = !!p.confirmacaoEmail;
  temProvedores = !!(p.google || p.discord);
  $('#cad-nick-wrap')?.classList.toggle('hidden', confirmacaoEmail);
  $('#btn-google').classList.toggle('hidden', !p.google);
  $('#btn-discord').classList.toggle('hidden', !p.discord);
  $('#login-social').classList.toggle('hidden', !p.google && !p.discord);
  turnstileSiteKey = p.turnstile || null;
  turnstileDesenhar('entrar');
};
fetch('/auth/provedores').then((r) => r.json()).then(aplicarProvedores).catch(() => {});

/**
 * Fala com o servidor de contas.
 *
 * Erro de rede e erro de regra chegam pelo mesmo caminho para quem chamou — o formulário só
 * precisa de uma mensagem para mostrar, e distinguir "o servidor caiu" de "senha errada" na
 * tela de login não muda o que a pessoa faz a seguir.
 */
/**
 * O id DESTE navegador — o mais perto de "máquina" que uma página consegue chegar.
 *
 * Nasce aqui, é nosso, e serve a uma pergunta só: quantas contas entram deste mesmo lugar. Não
 * é digital de navegador e não tenta ser — nada de canvas, fontes ou resolução. A diferença
 * importa: uma digital sobrevive a limpar o site, mas ACUSA duas máquinas iguais de serem a
 * mesma, e no parque de celular brasileiro isso é rotina, não exceção. Este id faz o contrário
 * — some quando se limpa o site ou se abre uma aba anônima, e em troca nunca confunde dois
 * aparelhos. Para medir origem de conta, errar para menos é o lado certo de errar.
 *
 * `try/catch` porque `localStorage` NÃO é garantido: aba anônima de alguns navegadores e
 * configurações que bloqueiam dados de site fazem o acesso lançar. Sem id, o servidor carimba
 * só o IP e o login segue — isto nunca pode ficar no caminho de alguém entrar no jogo.
 */
const CHAVE_DISPOSITIVO = 'id-dispositivo';
function idDispositivo() {
  try {
    let id = localStorage.getItem(CHAVE_DISPOSITIVO);
    if (!id || !/^[a-zA-Z0-9-]{8,64}$/.test(id)) {
      id = (crypto.randomUUID?.() ?? `d${Date.now().toString(36)}${Math.random().toString(36).slice(2, 12)}`);
      localStorage.setItem(CHAVE_DISPOSITIVO, id);
    }
    return id;
  } catch {
    return null;
  }
}

async function pedirAuth(rota, corpo) {
  const r = await fetch(`/auth/${rota}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    // O id vai em TODA chamada de conta, e não só no cadastro, de propósito: é o login de uma
    // conta que já existe que revela a máquina de quem criou as outras antes desta coluna
    // existir. Sem isso o painel só enxergaria contas novas e levaria meses para dizer algo.
    body: JSON.stringify({ ...corpo, dispositivo: idDispositivo() }),
  });
  const dados = await r.json().catch(() => ({}));
  if (!r.ok) {
    if (dados.esperaMs != null) dados.tempo = duracaoCurta(dados.esperaMs);
    const erro = new Error(dados.erro ? t(dados.erro, dados) : t('login.falhou'));
    // A CHAVE crua vai junto da mensagem traduzida: alguns erros pedem uma tela em vez de uma
    // linha vermelha (e-mail por confirmar, espera de uma hora), e comparar texto traduzido
    // para decidir isso quebraria no primeiro idioma novo.
    erro.chave = dados.erro;
    erro.dados = dados;
    throw erro;
  }
  return dados;
}

async function pedirVoto(rota, corpo = {}) {
  const sessao = sessaoSalva();
  if (!sessao?.token) throw new Error(t('auth.precisaLogin'));
  const r = await fetch(`/topidle/${rota}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ...corpo, token: sessao.token }),
  });
  const dados = await r.json().catch(() => ({}));
  if (!r.ok) {
    const erro = new Error(dados.erro ? t(dados.erro, dados) : t('voto.falhou'));
    erro.chave = dados.erro;
    throw erro;
  }
  return dados;
}

async function pedirAfiliado(rota, corpo = {}) {
  const sessao = sessaoSalva();
  if (!sessao?.token) throw new Error(t('auth.precisaLogin'));
  const r = await fetch(`/affiliate/${rota}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ...corpo, token: sessao.token }),
  });
  const dados = await r.json().catch(() => ({}));
  if (!r.ok) {
    const erro = new Error(dados.erro ? t(dados.erro, dados) : t('af.falhou'));
    erro.chave = dados.erro;
    throw erro;
  }
  return dados;
}

/** Entra de fato: guarda a sessão e abre o socket. */
function entrarComo(sessao) {
  guardarSessao(sessao);
  localStorage.setItem('nick', sessao.nick);
  // Some com o formulário mas DEIXA o quadro: o socket ainda vai abrir, e sumir com tudo
  // antes disso daria um piscar de xadrez vazio até o jogo aparecer.
  $('#login').classList.add('hidden');
  turnstileDestruir();
  // Provedor ou cadastro local sem nick ainda não conecta: o nick é a chave do socket, e abrir
  // a conexão com o nome provisório criaria o `players` errado — depois disso não haveria mais
  // o que escolher.
  if (sessao.precisaNick) return mostrarEscolhaDeNick();
  conectar();
}

// ------------------------------------------------- confirmação de e-mail

/** Deixa visível só um dos miolos do portal. */
function mostrarNoPortal(qual) {
  for (const [sel, nome] of [
    ['#carregando', 'carga'],
    ['#login', 'login'],
    ['#confirmar-email', 'confirmar'],
    ['#escolher-nick', 'nick'],
  ]) {
    $(sel)?.classList.toggle('hidden', nome !== qual);
  }
}

/**
 * "Confirme seu e-mail": o que aparece depois de criar conta, e também quando alguém tenta
 * entrar numa conta pendente.
 *
 * `credenciais` só existe no segundo caso — o reenvio pede a senha de novo, e é o que impede
 * a rota de virar um canal para disparar e-mail na caixa de qualquer jogador só sabendo o nick.
 * Vindo do cadastro, o botão de reenviar some: o e-mail acabou de sair.
 */
function mostrarConfirmacaoDeEmail(email, credenciais = null) {
  mostrarNoPortal('confirmar');
  // Vindo do LOGIN não se sabe o e-mail (o servidor não o entrega a quem só acertou a senha de
  // uma conta pendente), e aí a frase muda em vez de sair com um "para ." no fim.
  $('#confirma-texto').innerHTML = email
    ? t('conf.enviamos', { email: `<b>${escapar(email)}</b>` })
    : t('conf.pendente');
  const botao = $('#confirma-reenviar');
  botao.classList.toggle('hidden', !credenciais);
  botao.disabled = false;
  botao.textContent = t('conf.reenviar');
  if (credenciais) {
    let timerReenvio = null;
    const contarReenvio = (ms) => {
      const ate = Date.now() + ms;
      clearInterval(timerReenvio);
      const pintar = () => {
        const resta = ate - Date.now();
        if (resta <= 0) {
          botao.disabled = false;
          botao.textContent = t('conf.reenviar');
          return false;
        }
        botao.disabled = true;
        botao.textContent = t('conf.reenviarEspera', { tempo: duracaoCurta(resta) });
        return true;
      };
      if (!pintar()) return;
      timerReenvio = setInterval(() => { if (!pintar()) clearInterval(timerReenvio); }, 1000);
    };
    botao.onclick = async () => {
      botao.disabled = true;
      botao.textContent = t('conf.reenviando');
      try {
        const r = await pedirAuth('reenviar', credenciais);
        botao.textContent = t(r.jaConfirmado ? 'conf.jaConfirmado' : 'conf.reenviado');
        if (r.confirmacaoEsperaMs) contarReenvio(r.confirmacaoEsperaMs);
      } catch (err) {
        if (err.chave === 'conta.confirmacaoEspere' && err.dados?.esperaMs) {
          contarReenvio(err.dados.esperaMs);
          toast(err.message);
        } else {
          botao.disabled = false;
          botao.textContent = t('conf.reenviar');
          toast(err.message);
        }
      }
    };
  }
  $('#confirma-voltar').onclick = () => {
    mostrarNoPortal('login');
    erroLogin('');
  };
}

// ------------------------------------------------------- escolha do nick

/**
 * O nick de quem entrou por Google/Discord ou criou conta com e-mail pendente de escolha.
 *
 * O provedor devolve "Pedro Henrique", que não passa nas regras do jogo — `nickLivre` no
 * servidor limpa isso para conseguir criar a conta, mas o resultado é um nome que ninguém
 * escolheu. Quem se cadastra com e-mail também cai aqui depois de confirmar a caixa e entrar.
 * Aqui a pessoa escolhe o dela, com as MESMAS regras do cadastro com senha (quando este pede).
 *
 * A disponibilidade é conferida enquanto se digita, mas quem decide é o servidor no envio: o
 * nick pode ser tomado entre a checagem e o clique, e o `UNIQUE` do banco é a única verdade.
 */
function mostrarEscolhaDeNick() {
  mostrarNoPortal('nick');
  trocarArteDoPortal('login');
  const campo = $('#nick-novo');
  const estadoNick = $('#nick-estado');
  campo.focus();

  let pedido = 0;
  const conferir = async () => {
    const nick = campo.value.trim();
    estadoNick.className = 'nick-estado';
    if (!nick) return (estadoNick.textContent = '');
    if (!NICK_OK.test(nick)) {
      estadoNick.textContent = t('login.nickInvalido');
      estadoNick.classList.add('ruim');
      return;
    }
    const meu = ++pedido;
    estadoNick.textContent = t('nick.conferindo');
    try {
      const r = await pedirAuth('nick-livre', { nick });
      if (meu !== pedido) return; // chegou uma resposta velha: a pessoa já digitou mais
      estadoNick.textContent = t(r.livre ? 'nick.livre' : 'login.nickEmUso');
      estadoNick.classList.add(r.livre ? 'bom' : 'ruim');
    } catch {
      if (meu === pedido) estadoNick.textContent = '';
    }
  };
  let timer = null;
  campo.oninput = () => {
    clearTimeout(timer);
    timer = setTimeout(conferir, 300);
  };
  campo.onkeydown = (ev) => {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      $('#form-nick').requestSubmit();
    }
  };

  $('#form-nick').onsubmit = async (ev) => {
    ev.preventDefault();
    const nick = campo.value.trim();
    if (!NICK_OK.test(nick)) return erroLogin(t('login.nickInvalido'));
    const botao = $('#nick-salvar');
    botao.disabled = true;
    try {
      const sessao = await pedirAuth('nick', refNoCorpo({ token: sessaoSalva()?.token, nick }));
      guardarSessao(sessao);
      localStorage.setItem('nick', sessao.nick);
      pixelFb('CompleteRegistration');
      mostrarNoPortal('nada');
      fecharSocketAtual();
      conectar();
    } catch (err) {
      botao.disabled = false;
      estadoNick.textContent = err.message;
      estadoNick.className = 'nick-estado ruim';
    }
  };
}

$('#form-entrar').onsubmit = async (ev) => {
  ev.preventDefault();
  const id = $('#login-id').value.trim();
  const senha = $('#login-senha').value;
  if (!id) return erroLogin(t('login.informeUsuario'));
  if (!senha) return erroLogin(t('login.informeSenha'));

  const botao = $('#entrar');
  botao.disabled = true;
  erroLogin(t('login.entrando'));
  try {
    entrarComo(await pedirAuth('entrar', { id, senha, turnstileToken: pegarTurnstileToken('entrar') }));
    try {
      if (sessionStorage.getItem('fb-pending-reg')) {
        sessionStorage.removeItem('fb-pending-reg');
        pixelFb('CompleteRegistration');
      }
    } catch (_) {}
  } catch (err) {
    turnstileResetar('entrar');
    // Conta com e-mail pendente não é "senha errada": é uma etapa que ficou pela metade, e a
    // pessoa precisa do caminho de volta (reenviar o link) em vez de uma linha vermelha.
    if (err.chave === 'login.confirmeEmail') {
      erroLogin('');
      return mostrarConfirmacaoDeEmail(null, { id, senha });
    }
    erroLogin(err.message, false, motivoDoBan(err.dados));
  } finally {
    botao.disabled = false;
  }
};

// ------------------------------------------------- esqueci minha senha

/**
 * Abre (ou fecha) o pedido de link para quem não consegue entrar.
 *
 * Troca o miolo do MESMO quadro — abas, formulário de entrar e botões de provedor saem de cena
 * enquanto isto está aberto. A alternativa (uma página `/esqueci` própria) faria a pessoa sair
 * do portal para voltar depois, e o caminho mais comum aqui é justamente a volta: metade de
 * quem clica lembra a senha antes de terminar de digitar o e-mail.
 */
function mostrarEsqueci(abrir) {
  $('#form-esqueci').classList.toggle('hidden', !abrir);
  $('#login-abas').classList.toggle('hidden', abrir);
  $('#form-entrar').classList.toggle('hidden', abrir);
  $('#form-criar').classList.add('hidden');
  $('#login-social').classList.toggle('hidden', abrir || !temProvedores);
  $('#portal').classList.remove('compacto');
  erroLogin('');
  if (!abrir) {
    for (const aba of $('#login-abas').children) aba.classList.toggle('on', aba.dataset.aba === 'entrar');
    $('#login-id').focus();
    return;
  }
  // Aproveita o que já está no login, mas SÓ se for um e-mail: quem digitou o nick ali
  // veria o campo nascer preenchido com algo que esta tela recusa.
  const doLogin = $('#login-id').value.trim();
  if (EMAIL_OK.test(doLogin)) $('#esq-email').value = doLogin;
  $('#esq-ok').classList.add('hidden');
  $('#esq-email').focus();
  turnstileDesenhar('esqueci');
}

$('#abrir-esqueci').onclick = () => mostrarEsqueci(true);
$('#esq-voltar').onclick = () => mostrarEsqueci(false);

$('#form-esqueci').onsubmit = async (ev) => {
  ev.preventDefault();
  const email = $('#esq-email').value.trim();
  // Recusar o nick AQUI, e não com a resposta genérica do servidor, é o que separa um erro
  // de digitação de um beco sem saída: lá o pedido morreria em silêncio ("se existir uma
  // conta...") e a pessoa ficaria esperando um e-mail que nunca foi mandado.
  if (!EMAIL_OK.test(email)) return erroLogin(t('esq.soEmail'));

  const botao = $('#esq-enviar');
  let timer = null;
  /** Segura o botão pelo tempo que o servidor mandou — o cooldown é do IP, não da conta. */
  const contar = (ms) => {
    const ate = Date.now() + ms;
    clearInterval(timer);
    const pintar = () => {
      const resta = ate - Date.now();
      if (resta <= 0) {
        botao.disabled = false;
        botao.textContent = t('esq.enviar');
        return false;
      }
      botao.disabled = true;
      botao.textContent = t('esq.espera', { tempo: duracaoCurta(resta) });
      return true;
    };
    if (!pintar()) return;
    timer = setInterval(() => { if (!pintar()) clearInterval(timer); }, 1000);
  };

  botao.disabled = true;
  botao.textContent = t('esq.enviando');
  erroLogin('');
  try {
    const r = await pedirAuth('esqueci', { email, turnstileToken: pegarTurnstileToken('esqueci') });
    // A confirmação é DE PROPÓSITO vaga: o servidor responde igual exista a conta ou não, e
    // uma tela que dissesse "pronto, enviado!" prometeria o que ela não tem como saber.
    const ok = $('#esq-ok');
    ok.classList.remove('hidden');
    ok.textContent = t('esq.enviado');
    turnstileResetar('esqueci');
    contar(r.esperaMs ?? 60_000);
  } catch (err) {
    turnstileResetar('esqueci');
    if (err.chave === 'conta.esqueciEspere' && err.dados?.esperaMs) contar(err.dados.esperaMs);
    else {
      botao.disabled = false;
      botao.textContent = t('esq.enviar');
    }
    erroLogin(err.message);
  }
};

$('#form-criar').onsubmit = async (ev) => {
  ev.preventDefault();
  const nick = $('#cad-nick').value.trim();
  const email = $('#cad-email').value.trim();
  const senha = $('#cad-senha').value;
  const senha2 = $('#cad-senha2').value;

  // A validação acontece aqui só para poupar uma ida ao servidor — quem decide continua
  // sendo ele, que revalida tudo e é o único que sabe se o nick já é de alguém.
  const marcar = (sel, ruim) => $(sel).setAttribute('aria-invalid', ruim ? 'true' : 'false');
  if (!confirmacaoEmail) marcar('#cad-nick', !NICK_OK.test(nick));
  marcar('#cad-email', !emailPermitidoCadastro(email));
  marcar('#cad-senha', senha.length < 8);
  marcar('#cad-senha2', senha !== senha2);

  if (!confirmacaoEmail && !NICK_OK.test(nick)) return erroLogin(t('login.nickInvalido'));
  if (!emailPermitidoCadastro(email)) return erroLogin(t('login.emailDominio'));
  if (senha.length < 8) return erroLogin(t('login.senhaCurta'));
  if (senha !== senha2) return erroLogin(t('login.senhasDiferentes'));

  const botao = $('#criar');
  botao.disabled = true;
  erroLogin(t('login.criando'));
  try {
    const base = { email, senha, turnstileToken: pegarTurnstileToken('criar') };
    const corpo = confirmacaoEmail ? refNoCorpo(base) : refNoCorpo({ nick, ...base });
    const r = await pedirAuth('criar', corpo);
    // Com e-mail ligado, criar conta NÃO entra: a resposta nem traz token. A pessoa confirma
    // pela caixa, entra com e-mail e senha, e só então escolhe o nick — igual ao OAuth.
    if (r.precisaConfirmar) {
      pixelFb('Lead');
      erroLogin('');
      $('#portal').classList.remove('compacto');
      return mostrarConfirmacaoDeEmail(r.email, { id: email, senha });
    }
    pixelFb('CompleteRegistration');
    entrarComo(r);
  } catch (err) {
    turnstileResetar('criar');
    erroLogin(err.message);
  } finally {
    botao.disabled = false;
  }
};

// O provedor abre na MESMA aba: um popup bloqueado é um botão que não faz nada, e o retorno
// do OAuth volta para cá com `?sessao=` no endereço (tratado logo abaixo).
// O `?d=` é o id do dispositivo indo para o servidor ANTES do desvio para o provedor: ele
// volta dentro do `state` assinado (ver `assinarState`), que é o único campo que sobrevive à
// ida e à volta do OAuth. Sem isso, quem entra por Google seria a única gente sem carimbo de
// máquina — e é exatamente o caminho mais barato para abrir conta em série.
const irParaProvedor = (p) => {
  const d = idDispositivo();
  location.href = d ? `/auth/${p}?d=${encodeURIComponent(d)}` : `/auth/${p}`;
};
$('#btn-google').onclick = () => irParaProvedor('google');
$('#btn-discord').onclick = () => irParaProvedor('discord');

// Volta do OAuth: o servidor devolve a sessão no endereço, guardamos e limpamos a barra para
// o token não ficar no histórico nem num link compartilhado.
const params = new URLSearchParams(location.search);
// `sessao`, `redefinir` e `autorizarTrocaEmail` já saíram da barra no primeiro `<script>` do
// index.html — antes do GTM e do Pixel, que registram a URL. Voltam para cá do lugar onde ficaram.
for (const [k, v] of Object.entries(window.__parametrosSensiveis ?? {})) params.set(k, v);
// Mesma forma frouxa da landing (ver o comentário lá): cobre o código gerado e o slug de
// streamer, e o servidor é quem decide se existe. Sem `toUpperCase()` — ele destruía o slug.
const refUrl = params.get('ref')?.trim();
if (refUrl && /^[a-z0-9][a-z0-9_-]{1,18}[a-z0-9]$/i.test(refUrl)) {
  localStorage.setItem(CHAVE_REF, refUrl);
  fetch('/affiliate/visita', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ code: refUrl }),
  })
    .then((r) => (r.ok ? r.json() : null))
    .then((d) => { if (d?.vipGratis) anunciarVipDoLink(d); })
    .catch(() => {});
}

/** "1 dia" / "2 dias" — o VIP de boas-vindas é contado em horas no servidor e lido em dias. */
const diasDeVip = (horas) => {
  const dias = Math.max(1, Math.round((Number(horas) || 24) / 24));
  return dias === 1 ? t('vipRef.umDia') : t('vipRef.nDias', { n: dias });
};

/**
 * O anúncio do VIP de boas-vindas na tela de cadastro: o link é de um Referral Especial, então
 * quem CRIAR a conta por ele ganha VIP no primeiro login. É o que o streamer anuncia na live — e
 * a tela confirma antes de a pessoa se cadastrar, com o nome dele.
 */
function anunciarVipDoLink(d) {
  const el = document.getElementById('login-vip-ref');
  if (!el) return;
  el.textContent = t('vipRef.convite', { padrinho: String(d.padrinho ?? ''), tempo: diasDeVip(d.horas) });
  el.classList.remove('hidden');
}
const sessaoUrl = params.get('sessao');
if (sessaoUrl) {
  try {
    guardarSessao(JSON.parse(atob(sessaoUrl)));
  } catch {}
  history.replaceState(null, '', location.pathname);
}
if (params.get('erroAuth')) {
  const chave = params.get('erroAuth');
  const msg = t(chave);
  erroLogin(msg !== chave ? msg : t('login.falhou'), false, motivoDoBan(params));
  history.replaceState(null, '', location.pathname);
}

/** `?redefinir=<token>` é o link que sai no e-mail de troca de senha. */
const tokenRedefinir = params.get('redefinir');
/** `?autorizarTrocaEmail=<token>` — passo 1 da troca de e-mail (e-mail atual). */
const tokenAutorizarTrocaEmail = params.get('autorizarTrocaEmail');

// `?emailOk=1` é o destino do link de confirmação de e-mail. O parâmetro sai da barra assim
// que é lido: ele já cumpriu o papel, e deixá-lo ali fazia um F5 (ou o link no histórico)
// repetir "e-mail confirmado" para sempre. Quem AVISA é a tela de login, em `mostrarLogin` —
// `params` foi lido antes desta linha, então o aviso continua saindo mesmo com a URL limpa.
if (params.get('emailOk')) {
  try { sessionStorage.setItem('fb-pending-reg', '1'); } catch (_) {}
  history.replaceState(null, '', location.pathname);
}
if (params.get('emailTrocado')) history.replaceState(null, '', location.pathname);
// `?twitch=<resultado>` é a volta do "Vincular Twitch" (ver `/auth/twitch/retorno`). Sai da barra
// agora, pelo motivo do `emailOk`: um F5 repetiria o aviso. Quem avisa é o `welcome`
// (`avisarRetornoTwitch`). Declarado AQUI, e não junto do modal lá embaixo: esta linha roda no
// carregamento do módulo, e um `let` declarado depois dela estaria na zona morta.
let retornoTwitchPendente = params.get('twitch') || null;
if (retornoTwitchPendente) history.replaceState(null, '', location.pathname);
// `?kick=<resultado>` é a volta do "Vincular Kick" (ver `/auth/kick/retorno`), pelo mesmo caminho do
// `?twitch=`. Leva mais duas coisas: `kv`, o vínculo que a tela tem de CONFIRMAR (o servidor só
// grava depois do "sim" — é para sempre), e `canal`, o que aconteceu com o canal de quem é
// streamer oficial. Quem avisa é o `welcome` (`avisarRetornoKick`).
let retornoKickPendente = params.get('kick')
  ? { resultado: params.get('kick'), kv: params.get('kv') || null, canal: params.get('canal') || null }
  : null;
if (retornoKickPendente) history.replaceState(null, '', location.pathname);

function aoEntrar(m) {
  estado.hunts = m.hunts;
  // Com as hunts em mãos, o valor de quem só aparece acima de Kanto sobe (Vespiquen, Aegislash…)
  // e a cadeia se reassenta — a ficha e o rótulo do Mercado passam a bater com a venda.
  assentarValorDoCatalogo();
  estado.catalogoBolas = m.catalogoBolas;
  estado.itensCompraveis = m.itensCompraveis ?? [];
  estado.potencias = m.potencias ?? [];
  estado.itensTipos = m.itensTipos ?? {};
  // Os itens NOSSOS chegam pelo welcome, não pelo `/assets/items.json` do carregamento —
  // aquele é o espelho e não conhece nenhum deles. Entram no MESMO mapa dos outros para todo
  // o resto da tela (bolsa, mercado, tooltip, ficha) continuar fazendo um lookup só.
  for (const i of m.itensNossos ?? []) {
    estado.itens.set(i.id, i);
    if (i.icon) estado.iconesItem[i.id] = i.icon.startsWith('/') ? i.icon : caminhoIconeRel(i.icon);
  }
  for (const [id, rel] of Object.entries(ICONES_ITEM_FIXOS)) estado.iconesItem[id] = rel;
  aplicarIconesTmElemental();
  estado.shinyLooks = m.shinyLooks ?? {};
  estado.shinyLooksOutland = m.shinyLooksOutland ?? {};
  estado.outlandDex = m.outlandDex ?? null;
  setOutlandDexMap(estado.outlandDex);
  estado.chanceShiny = Number(m.chanceShiny) || 0;
  // Quem a Arena Mística sorteia, direto do servidor (ver `misticoPool` no welcome). Vazio
  // significa "o servidor não mandou", e aí a ficha cai na conta feita aqui.
  estado.misticoPool = Array.isArray(m.misticoPool) ? new Set(m.misticoPool.map(Number)) : null;
  estado.captura = m.captura ?? { base: 0.0075, piso: 0.003, teto: 0.1, raridadeDiv: 17 };
  estado.multShinyStats = m.multShinyStats ?? 3;
  estado.maxEquipe = m.maxEquipe ?? MAX_EQUIPE;
  // A matéria-prima da Pokepédia. Sem isto ela desenhava a tabela de tipos INTEIRA como
  // neutra (×1 em tudo) e as constantes de combate caíam nos valores de reserva — um manual
  // que mente calado, que é o pior resultado possível para uma tela de consulta.
  estado.tabelaTipos = m.tabelaTipos ?? {};
  estado.ampliacaoHunt = m.ampliacaoHunt ?? 1.5;
  estado.multHpSelvagem = m.multHpSelvagem ?? 5;
  estado.multDanoSelvagem = m.multDanoSelvagem ?? 1.8;
  estado.chanceBossToken = m.chanceBossToken ?? 0.0005;
  estado.outlandTiers = m.outlandTiers ?? null;
  estado.economia = m.economia ?? null;
  estado.bossesCatalogo = m.bossesCatalogo ?? [];
  estado.bossesJogaveis = m.bossesJogaveis ?? [];
  estado.tmResearcher = m.tmResearcher ?? null;
  estado.lojaProdutos = m.lojaProdutos ?? [];
  estado.tiposBoost = m.tiposBoost ?? [];
  estado.pedrasEvolucao = m.pedrasEvolucao ?? {};
  estado.refino = m.refino ?? null;
  // Catálogo da vitrine (toda pedra/TM/ficha), a faixa mínima de pokémon e a diária.
  // A aba de itens desenha o catálogo INTEIRO, então sem isto ela nasce vazia.
  estado.mercado = m.mercado ?? null;
  // Casa/XP Share e Shiny Stone: as regras e os ids, para a tela (e a Pokepédia) lerem a
  // MESMA fonte do servidor em vez de repetirem número escrito à mão.
  estado.casas = m.casas ?? null;
  estado.shinyStone = m.shinyStone ?? null;
  estado.mega = m.mega ?? null;
  // A OFERENDA: quantas casas a roleta tem. Vem do servidor porque é ele que valida o teto —
  // a tela desenha as casas e calcula a chance (`oferecidos / casas`) a partir deste número.
  estado.oferenda = m.oferenda ?? null;
  // O mapa de Shiny Stone é DERIVADO de `shinyStone.pedras`; zerar aqui força a remontagem na
  // próxima leitura, senão uma reconexão que trocasse o catálogo ficaria com o mapa velho.
  estado.ofrShinyPorTipo = null;
  estado.bicicletas = m.bicicletas ?? null;
  estado.xpShareHeld = m.xpShareHeld ?? null;
  estado.guildCusto = m.guildCusto ?? 250_000;
  estado.guildMaxTime = m.guildMaxTime ?? 10;
  // A roda das dicas do chat (guia → Discord → guia…). Idempotente: o `welcome` volta em toda
  // reconexão e o relógio é um só por aba.
  iniciarDicasDoChat();
  // Agora sim o quadro inteiro sai — o jogo chegou.
  $('#portal').classList.add('hidden');
  $('#app').classList.remove('hidden');
  // Sound Mode só dentro do jogo: no F5 o player aparece pausado; o jogador dá play de novo.
  sincronizarSom(somLigado(), { autoplay: false });
  // Com alguém dentro, o botão de sair passa a fazer sentido.
  $('#btn-sair')?.classList.remove('hidden');
  if (!estado.campo) {
    estado.campo = new Campo($('#cena'));
    ajustarZoomCena(0); // acerta o estado dos botões conforme o zoom salvo
  }
  montarPopup(estado, { avisar: toast }); // liga os botões do Modo Pop-up (idempotente)
  aplicarEstado(m.estado);
  estado.souAdmin = !!m.admin;
  estado.chatMod = !!m.chatMod;
  estado.chatCmd = !!m.chatCmd;
  // A lista das fixadas chega ANTES do welcome (o gateway manda no `hello`), quando ainda não se
  // sabia se este jogador é admin — e é isso que decide o × do cartão.
  pintarChatFixada();
  // A volta do OAuth da Twitch: só no primeiro `welcome` desta página (o de uma reconexão não é a
  // volta de nada), e depois do `souAdmin`, que o modal consulta.
  if (retornoTwitchPendente) {
    const resultado = retornoTwitchPendente;
    retornoTwitchPendente = null;
    avisarRetornoTwitch(resultado);
  }
  // A volta da Kick, na mesma regra: só no primeiro `welcome` da página.
  if (retornoKickPendente) {
    const volta = retornoKickPendente;
    retornoKickPendente = null;
    avisarRetornoKick(volta);
  }
  document.querySelector('.chat-vao')?.classList.toggle('admin-mod', estado.chatMod);
  // A prancheta NÃO nasce zerada aqui: `welcome` chega também no F5 e em TODA reconexão
  // (deploy, rede que caiu), e zerar neste ponto apagava a hunt de horas sem ninguém pedir.
  // Ver `sessaoGuardada` — de verdade, só o botão "Reset" zera.
  estado.sessao = sessaoGuardada() ?? sessaoNova();
  estado.sessaoAberta = false;
  estado.sessaoResetLivreEm = 0;
  estado.capturasHist = [];
  estado.capturasHistAberta = false;
  estado.capturasHistResetLivreEm = 0;
  estado.capturasNaoVistas = 0;
  pintarSeloCapturas();
  // O efeito de shiny entra em cache agora, não na captura: 72 kB baixados no meio da
  // comemoração chegariam depois dela.
  if (somShinyLigado() || somCapturaLigado() || somTmBossLigado()) {
    prepararSons({ shiny: somShinyLigado(), captura: somCapturaLigado(), tmBoss: somTmBossLigado() });
  }
  $('#cena-sessao')?.classList.remove('hidden');
  $('#cena-capturas')?.classList.remove('hidden');
  $('#sessao-painel')?.classList.add('hidden');
  $('#capturas-painel')?.classList.add('hidden');
  $('#cena-sessao')?.classList.remove('on');
  $('#cena-capturas')?.classList.remove('on');
  // DEPOIS de a prancheta e o histórico serem zerados e fechados acima: o Modo Economia os
  // reabre e os traz para o painel. Também é aqui que o socket novo fica sabendo da escolha —
  // toda reconexão passa por este ponto.
  sincronizarEconomia();
  sincronizarTelaAcesa();
  logCena(t('ev.bemVindo', { nick: m.estado.nick }));

  // O selo do Vote & Ganhe. Um pedido só, sem segurar nada da entrada: se falhar, o botão
  // continua lá e a tela dele conta o que houve.
  atualizarVoto(true);
  atualizarSeloAfiliado(true);

  // Onboarding: primeiro o personagem (gênero e cores), depois o pokémon. Quem já tem visual
  // definido e ainda não tem pokémon cai direto no starter — é o caso de quem ficou sem time.
  if (!m.estado.loja?.visualOk) return abrirOnboarding(m.starters);
  if (m.starters?.length) return abrirStarter(m.starters);

  if (!m.estado.huntSlug) logCena(t('ev.escolhaArea'));
  aplicarAtalhosUrl();
  maybeStartTutorial();
  maybeMostrarPopups();
  pedirHistoricoChat('mundo');
  // O canal volta da sessão (F5 com o Comércio aberto) sem passar por `trocarCanalChat`, que é
  // quem pede o histórico dos outros canais — sem isto a lista reabria vazia.
  if (estado.canalChat !== 'mundo') pedirHistoricoChat(estado.canalChat);
}

/** ?hunt=<slug> entra na hunt, &auto=1 liga as automações, &modal=<nome> abre uma aba. */
function aplicarAtalhosUrl() {
  if (estado.atalhosFeitos) return;
  estado.atalhosFeitos = true;
  const q = new URLSearchParams(location.search);
  if (q.get('hunt')) enviar({ t: 'hunt.select', slug: q.get('hunt') });
  if (q.get('auto')) {
    enviar({
      t: 'auto.set',
      autoBallSemParar: true,
      autoBallAteCapturar: false,
      ballIds: [1],
      autoRevive: true,
      autoPotion: true,
    });
  }
  if (q.get('modal')) setTimeout(() => abrirModal(q.get('modal')), 800);
}

// --------------------------------------------------------------- onboarding
//
// Três passos, nesta ordem: gênero → cores → starter.
//
// A ordem é a decisão de produto inteira deste bloco. Antes, a primeira (e única) pergunta do
// jogo era qual pokémon inicial — o jogador escolhia o companheiro do jogo inteiro antes de
// existir um personagem para acompanhá-lo. Agora ele primeiro se monta e só depois escolhe com
// quem sai. O servidor cobra a mesma ordem (`starter.pick` recusa sem `visualOk`), então não é
// só o desenho da tela: um cliente adulterado não pula para o pokémon.
//
// Passa por aqui quem tem `visualOk` falso — inclusive quem já jogava antes desta versão, que
// dá uma passada pelo editor e segue direto para o jogo (sem passo de starter, porque já tem
// pokémon).

/** O visual sendo montado agora. Vira `visual.set` no fim do passo 2. */
const rascunho = { genero: 'male', visual: { ...VISUAL_PADRAO } };

/** Os dois outfits de treinador do pack — é o gênero que escolhe qual sprite é desenhado. */
const LOOK_DO_GENERO = { male: 159, female: 160 };

/**
 * Como remontar o passo que está na tela agora.
 *
 * O onboarding é construído por JS com `t()` no momento em que cada passo abre, então a
 * tradução fica CONGELADA no idioma daquele instante — trocar a bandeira no meio do cadastro
 * não mudava uma palavra. E é justamente aí que a troca mais importa: é a primeira tela do
 * jogo, e quem não lê português vai procurar a bandeira exatamente nessa hora.
 *
 * `aplicarI18n()` não resolve, porque ele só alcança o que tem `data-i18n` no HTML — e aqui o
 * HTML é só a moldura vazia (`#ob-titulo`, `#ob-corpo`).
 *
 * Cada passo guarda aqui como se redesenhar. `redesenharPorIdioma` chama de volta, e o passo
 * se remonta com os textos novos, sem perder o que já foi escolhido: gênero e cores vivem em
 * `rascunho`, que é externo à tela.
 */
let repintarPassoDoOnboarding = null;

const sorteioDe = (n) => Math.floor(Math.random() * n);

function abrirOnboarding(starters) {
  rascunho.genero = estado.eu?.loja?.gender === 'female' ? 'female' : 'male';
  rascunho.visual = normalizarVisual(estado.eu?.loja?.visual);

  // `?starter=` é o atalho das ferramentas (o mesmo espírito do `?nick=`): quem entra por ele
  // quer testar o JOGO, não o onboarding. Fecha o visual no padrão e vai direto ao starter —
  // sem isto, os testes de UI que abrem uma conta nova ficariam parados no editor de cores.
  if (new URLSearchParams(location.search).get('starter')) {
    enviar({ t: 'visual.set', genero: rascunho.genero, visual: rascunho.visual });
    if (!starters?.length) return;
    $('#onboarding').classList.remove('hidden');
    return passoDoStarter(starters);
  }

  $('#onboarding').classList.remove('hidden');
  passoDoGenero(starters);
}

/**
 * Os pontinhos do topo. `starters` nulo quer dizer que este jogador não tem passo 3.
 *
 * O `nome` do passo fica no `data-passo` do quadro porque o CSS do celular precisa dele: o
 * editor de cores é o único passo que vira uma folha de altura fixa com a lista rolando por
 * dentro, e os outros dois continuam do tamanho do conteúdo. Sem a marca, a escolha de gênero
 * (dois cartões) abriria uma folha de tela inteira com o resto vazio.
 */
function pintarPassos(atual, total, nome = '') {
  $('#onboarding').dataset.passo = nome;
  const host = $('#ob-passos');
  host.innerHTML = '';
  for (let i = 1; i <= total; i++) {
    const p = document.createElement('i');
    p.className = i === atual ? 'on' : i < atual ? 'feito' : '';
    host.appendChild(p);
  }
}

/**
 * `edicao` liga o modo TROCA DE AVATAR: os mesmos dois passos, mas para quem já jogou.
 *
 * A diferença é toda no fim — o passo das cores manda `visual.trocar` (que o servidor cobra
 * uma vez por dia) em vez de `visual.set`, e há por onde desistir. O editor é o mesmo de
 * propósito: quem trocar vai procurar a tela que já conhece.
 */
function passoDoGenero(starters, edicao = false) {
  // Guarda como se remontar, para a troca de bandeira poder repetir este passo.
  repintarPassoDoOnboarding = () => passoDoGenero(starters, edicao);
  const total = starters?.length ? 3 : 2;
  $('#ob-titulo').textContent = t(edicao ? 'av.titulo' : 'ob.tituloGenero');
  pintarPassos(1, total, 'genero');

  const corpo = $('#ob-corpo');
  corpo.innerHTML = `<p class="ob-ajuda">${t('ob.ajudaGenero')}</p>
    <div class="ob-generos" id="ob-generos"></div>
    ${edicao ? `<div class="ob-rodape"><button class="btn-apagado" id="ob-cancelar">${t('av.cancelar')}</button></div>` : ''}`;

  for (const genero of ['male', 'female']) {
    const b = document.createElement('button');
    b.className = 'ob-genero';
    b.classList.toggle('on', rascunho.genero === genero);
    // O outfit ANDA no cartão: parado, os dois se distinguem por pouco, e em movimento a
    // silhueta inteira ajuda a escolher.
    b.appendChild(
      spriteAnimado(LOOK_DO_GENERO[genero], 104, 3, null, empacotarVisual(rascunho.visual)),
    );
    const nome = document.createElement('span');
    nome.textContent = t(genero === 'male' ? 'ob.masculino' : 'ob.feminino');
    b.appendChild(nome);
    b.onclick = () => {
      rascunho.genero = genero;
      for (const outro of b.parentElement.children) outro.classList.toggle('on', outro === b);
      passoDasCores(starters, edicao);
    };
    $('#ob-generos').appendChild(b);
  }
  $('#ob-cancelar')?.addEventListener('click', fecharEditorDeAvatar);
}

/**
 * O boneco de hoje e o de amanhã, lado a lado: a pessoa confere a roupa uma última vez antes de a
 * troca travar por um dia.
 */
function confirmarTrocaAvatar(rascunho, aoConfirmar) {
  confirmar({
    titulo: t('av.confirmarTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteTreinador(null, null, 72), nome: escapar(t('av.hoje')) })}
        ${dlgSeta()}
        ${dlgAtor({
          arte: dlgArteTreinador(LOOK_DO_GENERO[rascunho.genero], empacotarVisual(rascunho.visual), 72),
          nome: escapar(t('av.nova')),
          classe: 'novo',
        })}`)}
      ${dlgFrase('', t('av.confirmarTexto'))}`,
    rotuloSim: t('av.confirmar'),
    aoConfirmar,
  });
}

function passoDasCores(starters, edicao = false) {
  // Guarda como se remontar, para a troca de bandeira poder repetir este passo.
  repintarPassoDoOnboarding = () => passoDasCores(starters, edicao);
  const total = starters?.length ? 3 : 2;
  $('#ob-titulo').textContent = t(edicao ? 'av.titulo' : 'ob.tituloCores');
  pintarPassos(2, total, 'cores');

  const corpo = $('#ob-corpo');
  corpo.innerHTML = `
    <div class="ob-editor">
      <div class="ob-palco">
        <div class="ob-boneco" id="ob-boneco"></div>
        <div class="ob-giro" id="ob-giro"></div>
      </div>
      <div class="ob-pecas" id="ob-pecas"></div>
    </div>
    <div class="ob-rodape">
      <button class="btn-apagado" id="ob-voltar">${t('ob.voltar')}</button>
      <button class="btn-apagado" id="ob-sortear">${t('ob.sortear')}</button>
      ${edicao ? `<button class="btn-apagado" id="ob-cancelar">${t('av.cancelar')}</button>` : ''}
      <button id="ob-pronto">${t(edicao ? 'av.confirmar' : 'ob.pronto')}</button>
    </div>`;

  // O outfit aparece nas QUATRO direções: a de frente é a que a pessoa julga, mas a roupa muda
  // bastante de costas, e escolher sem ver isso dá arrependimento na primeira vez que ela anda
  // para cima na praça.
  const look = () => LOOK_DO_GENERO[rascunho.genero];
  // No celular o palco divide a altura da tela com as quatro paletas empilhadas, e com o
  // boneco em 132 px cabiam exatamente três: a quarta (SAPATO) ficava fora sem nenhuma beirada
  // aparecendo, que é o mesmo que não existir. Em 104 px o rótulo da quarta aparece por baixo
  // da terceira, e aí a rolagem se anuncia sozinha.
  const movel = montagemMovel();
  const redesenhar = () => {
    const cores = empacotarVisual(rascunho.visual);
    $('#ob-boneco').replaceChildren(spriteAnimado(look(), movel ? 104 : 132, 3, null, cores));
    $('#ob-giro').replaceChildren(
      ...[2, 1, 4].map((d) => spriteAnimado(look(), movel ? 40 : 46, d, null, cores)),
    );
  };

  // A grade das 133 cores do Tibia: 19 matizes por linha, 7 linhas de saturação/brilho. A
  // forma da grade NÃO é enfeite — é o que deixa achar "o mesmo azul, mais escuro" descendo
  // uma linha, em vez de caçar num varal de 133 amostras.
  const pecas = $('#ob-pecas');
  const marcarSelecao = () => {
    for (const b of pecas.querySelectorAll('.ob-cor')) {
      b.classList.toggle('on', rascunho.visual[b.dataset.peca] === Number(b.dataset.cor));
    }
  };

  for (const { chave, i18n } of REGIOES) {
    const linha = document.createElement('div');
    linha.className = 'ob-peca';
    linha.innerHTML = `<span class="ob-peca-nome">${t(i18n)}</span>`;
    const grade = document.createElement('div');
    grade.className = 'ob-cores';

    for (let i = 0; i < PALETA.length; i++) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'ob-cor';
      b.style.background = hexDaCor(i);
      b.dataset.peca = chave;
      b.dataset.cor = i;
      b.onclick = () => {
        rascunho.visual[chave] = i;
        marcarSelecao();
        redesenhar();
      };
      grade.appendChild(b);
    }
    linha.appendChild(grade);
    pecas.appendChild(linha);
  }

  marcarSelecao();
  redesenhar();

  $('#ob-voltar').onclick = () => passoDoGenero(starters, edicao);
  $('#ob-sortear').onclick = () => {
    for (const { chave } of REGIOES) rascunho.visual[chave] = sorteioDe(PALETA.length);
    marcarSelecao();
    redesenhar();
  };
  $('#ob-cancelar')?.addEventListener('click', fecharEditorDeAvatar);
  $('#ob-pronto').onclick = () => {
    // Trocar de avatar avisa da espera ANTES de gastar a troca. É a mesma ideia da confirmação
    // de venda em lote: a ação em si é boa, mas ela custa algo que só se descobre depois.
    if (edicao) {
      return confirmarTrocaAvatar(rascunho, () => {
        if (!enviar({ t: 'visual.trocar', genero: rascunho.genero, visual: rascunho.visual })) return;
        fecharEditorDeAvatar();
      });
    }
    if (!enviar({ t: 'visual.set', genero: rascunho.genero, visual: rascunho.visual })) return;
    // O starter vai no MESMO socket e logo atrás, então o servidor já terá gravado `visualOk`
    // quando ele chegar — as mensagens de uma conexão são processadas em ordem.
    if (starters?.length) return passoDoStarter(starters);
    $('#onboarding').classList.add('hidden');
    toast(t('ob.salvo'));
    maybeMostrarPopups();
  };
}

/**
 * Abre o editor de aparência para quem JÁ tem personagem — o "Mudar avatar" da ficha.
 *
 * A trava de 24 h é conferida no servidor; aqui a tela só se recusa a abrir quando sabe que a
 * troca seria negada, porque montar o boneco inteiro para levar um "não" no fim é pior do que
 * ouvir o "não" antes de começar.
 */
function abrirEditorDeAvatar() {
  const livreEm = estado.eu?.loja?.visualTrocaLivreEm ?? 0;
  const resta = livreEm - Date.now();
  if (resta > 0) {
    const horas = Math.ceil(resta / 3_600_000);
    return toast(t('av.espere', { horas: num(horas) }));
  }
  rascunho.genero = estado.eu?.loja?.gender === 'female' ? 'female' : 'male';
  rascunho.visual = normalizarVisual(estado.eu?.loja?.visual);
  fecharModal();
  $('#onboarding').classList.remove('hidden');
  passoDoGenero(null, true);
}

function fecharEditorDeAvatar() {
  $('#onboarding').classList.add('hidden');
  repintarPassoDoOnboarding = null;
}

function passoDoStarter(lista) {
  // Guarda como se remontar, para a troca de bandeira poder repetir este passo.
  repintarPassoDoOnboarding = () => passoDoStarter(lista);
  $('#ob-titulo').textContent = t('starter.titulo');
  pintarPassos(3, 3, 'starter');
  const corpo = $('#ob-corpo');
  corpo.innerHTML = `<p class="ob-ajuda">${t('starter.aviso')}</p>
    <div class="starter-lista" id="ob-starters"></div>`;
  montarCartoesDeStarter(lista, $('#ob-starters'), () => {
    $('#onboarding').classList.add('hidden');
    maybeMostrarPopups();
  });
}

// ------------------------------------------------------- escolha do starter

/**
 * Os três cartões de starter, num contêiner qualquer.
 *
 * Existe separado porque os mesmos cartões aparecem em dois lugares: no último passo do
 * onboarding (jogador novo) e no modal solto de `#starter` (quem ficou sem pokémon nenhum
 * depois de já ter jogado). Duas cópias já teriam divergido no `?starter=` dos testes.
 */
function montarCartoesDeStarter(lista, host, aoEscolher) {
  host.innerHTML = '';
  for (const s of lista) {
    const b = document.createElement('button');
    b.className = 'starter-card';
    b.dataset.especie = s.speciesId;
    b.innerHTML = `<div class="st-arte"></div><div class="st-nome">${s.nome}</div><div class="st-tipos">${s.tipos.join(' / ')}</div>`;
    // `encaixar` porque as três células têm tamanhos diferentes — a do Charmander é 64×32 e a
    // dos outros dois é 32×32. Limitando a CÉLULA, ele saía com metade da altura dos vizinhos;
    // limitando o BICHO, os três ficam do mesmo tamanho. A caixa de altura fixa do `.st-arte`
    // é o que põe os três com o pé na mesma linha, já que agora cada um tem sua proporção.
    b.querySelector('.st-arte').appendChild(
      spriteAnimado(s.looktype, 84, 3, null, null, { encaixar: true }),
    );
    b.onclick = () => {
      for (const outro of host.children) outro.disabled = true;
      enviar({ t: 'starter.pick', speciesId: s.speciesId });
      aoEscolher?.();
    };
    host.appendChild(b);
  }

  // atalho de teste: ?starter=charmander (ou o id) escolhe sozinho
  const pedido = new URLSearchParams(location.search).get('starter');
  if (!pedido) return;
  const escolha = lista.find(
    (s) => String(s.speciesId) === pedido || s.nome.toLowerCase() === pedido.toLowerCase(),
  );
  if (escolha) {
    enviar({ t: 'starter.pick', speciesId: escolha.speciesId });
    aoEscolher?.();
  }
}

function abrirStarter(lista) {
  montarCartoesDeStarter(lista, $('#starter-lista'), () => {
    $('#starter').classList.add('hidden');
    maybeMostrarPopups();
  });
  $('#starter').classList.remove('hidden');
}

// --------------------------------------------------------------- tutorial
//
// O GUIA DO PRIMEIRO LOGIN. Antes era um tour das dez abas do topo, na ordem em que elas
// aparecem na barra — o que descreve o MENU, não o jogo. Um treinador novo saía de lá sabendo
// que existe um botão "Market" e sem saber o que fazer nos cinco minutos seguintes.
//
// Agora o guia segue o CAMINHO: o inicial que ele acabou de escolher, curar a equipe quando
// ela cair, abrir o mapa, achar uma área fácil para o TIPO dele, entrar na hunt, ligar as
// automações, capturar, vender o que dropou, vender bicho para outro jogador e, no fim, o
// chat — que é onde ele tira as dúvidas que sobrarem.
//
// Cada passo diz onde mora (`alvo`), o que precisa estar aberto para ele existir (`modal`,
// `aba` no celular) e o que escrever. O guia ABRE sozinho o que o passo precisa: o modal, a
// gaveta certa do celular, a aba do Market, a folha de filtros do mapa. O jogador só aperta
// "Próximo" — a tela vai junto com o texto, em vez de o texto falar de uma tela que ele
// teria de ir procurar sozinho.
//
// No celular há um passo A MAIS, e é o passo que faltava: as abas do jogo moram dentro da
// gaveta "Menu", e quem nunca a abriu não tem como adivinhar que o Mapa está lá dentro.

/** O elemento, ou `null` se ele não estiver na tela agora (`hidden`, gaveta fechada…). */
const naTela = (el) => (el && el.getClientRects().length ? el : null);

/** Nome e tipos do inicial, para as frases que falam DO POKÉMON DELE e não de "um pokémon". */
function paramsDoInicial() {
  const pk = estado.eu?.pokemons?.find((p) => p.id === estado.eu.activeId)
    ?? estado.eu?.pokemons?.[0];
  const tipos = pk?.tipos ?? [];
  return {
    nome: escapar(pk?.nome ?? t('painel.emCampo')),
    tipo: tipos[0] ?? '—',
    tipos: tipos.length ? selosDeTipo(tipos) : '—',
  };
}

/**
 * No celular os filtros do mapa moram numa folha que nasce fechada, atrás do botão "Filtros".
 * O passo que ensina o filtro de tipo precisa dela ABERTA — senão o holofote cairia sobre um
 * grupo de checkboxes que está fora da tela.
 */
function abrirFiltrosDoMapa() {
  if (movelAtivo()) reabrirFolhaDeFiltros();
}

/** Abre o Market já na aba certa — `abrirModal` acende a aba que estiver em `abaMarket`. */
const abaDoMarket = (aba) => () => {
  estado.abaMarket = aba;
};

const TUTORIAL_PASSOS = [
  // 1 · logou
  { chave: 'bemvindo' },

  // 2 · o inicial que ele acabou de escolher
  { chave: 'inicial', aba: 'equipe', alvo: () => $('#p-ativo'), params: paramsDoInicial },

  // 3 · curar a equipe. O botão FLUTUA sobre a Enfermeira Joy, e ela anda pela praça — daí o
  //     `segue`, que faz o holofote acompanhar a cada quadro em vez de deslizar atrás dela.
  {
    chave: 'curar',
    segue: true,
    alvo: () => naTela($('#centro-curar')) ?? $('#palco'),
    params: paramsDoInicial,
  },

  // 4 · SÓ NO CELULAR: a gaveta antes do mapa.
  { chave: 'menuMovel', so: 'movel', alvo: () => $('#m-nav button[data-aba="menu"]') },

  // 5 · o mapa
  { chave: 'mapa', aba: 'menu', alvo: () => $('.menu-topo button[data-modal="mapa"]') },

  // 6 · a hunt certa para o TIPO dele — o filtro composto do mapa faz a conta sozinho
  {
    chave: 'hunt',
    modal: 'mapa',
    depois: abrirFiltrosDoMapa,
    fundo: () => $('#modal .modal-caixa'),
    alvo: () => naTela($('.mapa-matchup-filtros')) ?? $('#f-tipos'),
    params: paramsDoInicial,
  },

  // 7 · entrar na hunt
  {
    chave: 'entrarHunt',
    modal: 'mapa',
    fundo: () => $('#modal .modal-caixa'),
    alvo: () => $('#mapa-mundi'),
  },

  // 8 · as automações
  { chave: 'auto', aba: 'auto', alvo: () => $('#auto-corpo') ?? $('#p-auto') },

  // 9 · revive, poção e a bola automática, que é do VIP
  {
    chave: 'itens',
    aba: 'auto',
    fundo: () => $('#p-auto'),
    alvo: () => [
      $('#auto-ball-captura')?.closest('.auto-linha'),
      $('#auto-revive')?.closest('.auto-linha'),
      $('#auto-potion')?.closest('.auto-linha'),
    ],
  },

  // 10 · a captura na mão. A lista de caídos só existe com bicho no chão, e no primeiro login
  //      não há nenhum: sem ela o holofote abre no palco, que é onde ela vai nascer.
  { chave: 'captura', alvo: () => naTela($('#caidos')) ?? $('#palco') },

  // 11 · o Market do NPC: comprar
  {
    chave: 'market',
    modal: 'market',
    antes: abaDoMarket('compra'),
    fundo: () => $('#modal .modal-caixa'),
    alvo: () => $('.mk-aba[data-aba="compra"]'),
  },

  // 12 · vender o que os selvagens dropam
  {
    chave: 'venda',
    modal: 'market',
    antes: abaDoMarket('venda'),
    fundo: () => $('#modal .modal-caixa'),
    alvo: () => $('.mk-aba[data-aba="venda"]'),
  },

  // 13 · vender os pokémon capturados
  {
    chave: 'vendaPk',
    modal: 'market',
    antes: abaDoMarket('pokemons'),
    fundo: () => $('#modal .modal-caixa'),
    alvo: () => $('.mk-aba[data-aba="pokemons"]'),
  },

  // 14 · o Mercado da Comunidade, que é o outro mercado — o de jogador para jogador
  { chave: 'community', aba: 'menu', alvo: () => $('.menu-topo button[data-modal="community"]') },

  // 15 · o resto por cima: ginásio, PvP, guild, Torneio, Passe, boss, Pokédex…
  //
  // No CELULAR a barra é uma grade de duas colunas, e com o Passe ela passou de seis para sete
  // fileiras — mais alta que a gaveta aberta. Duas correções por causa disso:
  //   · `rolar` manda a rolagem para o PRIMEIRO botão, e não para a barra inteira: com o alvo
  //     maior que o vão, o `scrollIntoView` do passo anterior deixava a grade no meio e a luz
  //     nascia com a primeira fileira cortada em cima.
  //   · o alvo é a ÁREA VISÍVEL da gaveta, porque um recorte da altura da barra vazaria por
  //     cima dela, acendendo um naco da cena que não tem nada a ver com o texto.
  {
    chave: 'resto',
    aba: 'menu',
    rolar: () => $('.menu-topo button'),
    alvo: () => (movelAtivo() ? $('.m-pane[data-aba="menu"]') ?? $('.menu-topo') : $('.menu-topo')),
  },

  // 16 · o chat, que é a saída para toda dúvida que sobrou
  { chave: 'chat', aba: 'chat', alvo: () => $('#p-chat') },
];

/** Os passos válidos NESTA tela — o `menuMovel` não existe no desktop. */
function passosDoGuia() {
  const movel = movelAtivo();
  return TUTORIAL_PASSOS.filter((p) => !p.so || (p.so === 'movel') === movel);
}

let tutorialAtivo = false;
let tutorialIdx = 0;
let tutorialPassos = TUTORIAL_PASSOS;
/** rAF do holofote que persegue alvo que anda (a Enfermeira Joy). */
let tutorialSeguindo = 0;

function tutorialPronto() {
  if (tutorialAtivo || !estado.eu || estado.eu.tutorialVisto) return false;
  if (!estado.eu.pokemons?.length) return false;
  if (!estado.eu.loja?.visualOk) return false;
  if (!$('#portal').classList.contains('hidden')) return false;
  if (!$('#onboarding').classList.contains('hidden')) return false;
  if (!$('#starter').classList.contains('hidden')) return false;
  if (!$('#escolher-nick')?.classList.contains('hidden')) return false;
  if (estado.modalAberto) return false;
  const q = new URLSearchParams(location.search);
  if (q.get('modal') || q.get('starter')) return false;
  return true;
}

/** Retângulo que cobre todos os alvos do passo — um só, ou a união de vários. */
function retanguloDoPasso(alvos) {
  const lista = (Array.isArray(alvos) ? alvos : [alvos]).filter((el) => naTela(el));
  if (!lista.length) return null;
  let { left, top, right, bottom } = lista[0].getBoundingClientRect();
  for (const el of lista.slice(1)) {
    const o = el.getBoundingClientRect();
    left = Math.min(left, o.left);
    top = Math.min(top, o.top);
    right = Math.max(right, o.right);
    bottom = Math.max(bottom, o.bottom);
  }
  return { left, top, width: right - left, height: bottom - top };
}

const encaixarNaTela = (el, r, pad) => {
  el.style.left = `${Math.max(4, r.left - pad)}px`;
  el.style.top = `${Math.max(4, r.top - pad)}px`;
  el.style.width = `${r.width + pad * 2}px`;
  el.style.height = `${r.height + pad * 2}px`;
};

/**
 * Põe o recorte, o anel e o cartão no lugar.
 *
 * São DUAS marcas, e não uma. O recorte (`#tutorial-spot`) é o que fica ACESO no meio da tela
 * escura; o anel (`#tutorial-anel`) é o dedo apontando. Quase sempre os dois caem no mesmo
 * lugar e só o recorte aparece — mas quando o passo mora dentro de um modal, o recorte tem de
 * abrir a TELA INTEIRA (senão o jogador vê uma aba acesa e nada em volta, e não aprende onde
 * ela fica) enquanto o anel aponta exatamente a aba de que o texto está falando.
 */
function posicionarTutorial(alvo, fundo, { soMarca = false } = {}) {
  const rAlvo = retanguloDoPasso(alvo);
  const rFundo = retanguloDoPasso(fundo) ?? rAlvo;
  const spot = $('#tutorial-spot');
  const anel = $('#tutorial-anel');
  const caixa = $('#tutorial-caixa');

  // Passo sem alvo nenhum (o "bem-vindo", ou um alvo que sumiu): sem recorte, cartão no meio.
  // Sem recorte não há sombra de 9999px, e é ela que escurece a tela — daí a classe, que põe
  // o mesmo escuro no pano de fundo inteiro.
  if (!rFundo) {
    if (soMarca) return; // alvo que anda saiu de quadro: melhor a luz parada que a luz sumida
    $('#tutorial').classList.add('sem-spot');
    spot.classList.add('hidden');
    anel.classList.add('hidden');
    caixa.classList.add('no-meio');
    caixa.style.left = '';
    caixa.style.top = '';
    return;
  }
  $('#tutorial').classList.remove('sem-spot');
  caixa.classList.remove('no-meio');

  spot.classList.remove('hidden');
  encaixarNaTela(spot, rFundo, 8);

  // O anel só entra quando ele e o recorte são coisas diferentes — apontar para a mesma borda
  // duas vezes só engorda a linha.
  const separados = !!rAlvo && (rFundo.width - rAlvo.width > 24 || rFundo.height - rAlvo.height > 24);
  anel.classList.toggle('hidden', !separados);
  if (separados) encaixarNaTela(anel, rAlvo, 5);

  // Perseguindo alvo que anda: mexer no cartão a cada quadro faria o texto tremer junto com a
  // Enfermeira Joy. A luz segue; o que se lê fica parado.
  if (soMarca) return;

  // Onde o cartão cabe SEM tapar o que ele aponta.
  //
  // Quem manda é `rAlvo`, não `rFundo`: o que não pode ser coberto é a coisa de que o texto
  // fala. A ordem das tentativas é a que o olho espera — primeiro a faixa vertical do lado
  // oposto ao alvo (embaixo de um botão do topo, em cima de um botão do rodapé), depois as
  // laterais, que é o que salva os passos dentro de um modal alto: no desktop sobra tela à
  // direita da caixa do Mercado, e antes o cartão insistia em subir e cobria a vitrine.
  //
  // Se nada couber — celular com um modal do tamanho da tela —, ele encosta na borda de baixo
  // e deixa a maior parte do alvo à vista. Sobrepor um pedaço é melhor que sair da tela.
  const r = rAlvo ?? rFundo;
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const cw = caixa.offsetWidth || 320;
  const ch = caixa.offsetHeight || 200;
  // No celular a barra de abas mora no rodapé, e o cartão não pode nascer debaixo dela — é
  // justamente lá que fica o alvo do passo do "Menu". O piso é a altura dela, medida, porque
  // a barra cresce com a `safe-area` do aparelho.
  const rodape = movelAtivo() ? ($('#m-nav')?.getBoundingClientRect().height ?? 0) + 10 : 10;
  const prender = (v, min, max) => Math.max(min, Math.min(max, v));
  const yLivre = prender(r.top, 10, Math.max(10, vh - ch - rodape));
  const xLivre = prender(r.left, 10, Math.max(10, vw - cw - 10));

  const abaixo = { x: xLivre, y: r.top + r.height + 14, cabe: r.top + r.height + 14 + ch <= vh - rodape };
  const acima = { x: xLivre, y: r.top - ch - 14, cabe: r.top - ch - 14 >= 10 };
  const direita = { x: r.left + r.width + 14, y: yLivre, cabe: r.left + r.width + 14 + cw <= vw - 10 };
  const esquerda = { x: r.left - cw - 14, y: yLivre, cabe: r.left - cw - 14 >= 10 };

  const vertical = r.top > vh * 0.45 ? [acima, abaixo] : [abaixo, acima];
  const posto = [...vertical, direita, esquerda].find((f) => f.cabe)
    ?? { x: xLivre, y: Math.max(10, vh - ch - rodape) };

  caixa.style.left = `${prender(posto.x, 10, Math.max(10, vw - cw - 10))}px`;
  caixa.style.top = `${prender(posto.y, 10, Math.max(10, vh - ch - rodape))}px`;
  caixa.style.right = 'auto';
  caixa.style.bottom = 'auto';
}

/**
 * Abre o que o passo precisa: o modal, a gaveta do celular, a folha de filtros.
 *
 * São dois ganchos porque `abrirModal` refaz o corpo do modal do zero, e há coisa dos dois
 * lados dessa linha. `antes` mexe no ESTADO que o `render()` vai ler — é assim que o passo do
 * Market nasce já na aba certa. `depois` mexe no DOM que acabou de nascer — é assim que a
 * folha de filtros do celular abre, já que ela é um nó novo a cada abertura.
 */
function prepararPasso(passo) {
  passo.antes?.();

  if (passo.modal) {
    // No celular o modal cobre a tela inteira: deixar a gaveta aberta atrás dele só deixaria
    // a barra de abas acesa por baixo de uma tela que já tomou conta de tudo.
    if (movelAtivo()) fecharGavetaMobile();
    abrirModal(passo.modal);
    passo.depois?.();
    return;
  }

  if (estado.modalAberto) fecharModal();
  passo.depois?.();
  if (!movelAtivo()) return;
  if (passo.aba) abrirAbaMobile(passo.aba);
  else fecharGavetaMobile();
}

/** O holofote persegue alvo que anda — hoje só o botão de curar, que segue a Enfermeira Joy. */
function seguirAlvoDoTutorial() {
  tutorialSeguindo = 0;
  if (!tutorialAtivo) return;
  const passo = tutorialPassos[tutorialIdx];
  if (!passo?.segue) return;
  posicionarTutorial(passo.alvo?.(), passo.fundo?.(), { soMarca: true });
  tutorialSeguindo = requestAnimationFrame(seguirAlvoDoTutorial);
}

function renderTutorialPasso() {
  const passo = tutorialPassos[tutorialIdx];
  if (!passo) return;
  cancelAnimationFrame(tutorialSeguindo);
  tutorialSeguindo = 0;

  const total = tutorialPassos.length;
  $('#tutorial-contador').textContent = t('tut.step', { n: tutorialIdx + 1, total });
  $('#tutorial-progresso').style.width = `${((tutorialIdx + 1) / total) * 100}%`;
  $('#tutorial-titulo').textContent = t(`tut.${passo.chave}.t`);
  $('#tutorial-corpo').innerHTML = t(`tut.${passo.chave}.b`, passo.params?.());
  $('#tutorial-voltar').classList.toggle('hidden', tutorialIdx === 0);
  const ultimo = tutorialIdx >= total - 1;
  $('#tutorial-pular').classList.toggle('hidden', ultimo);
  $('#tutorial-proximo').textContent = t(ultimo ? 'tut.finalizar' : 'tut.proximo');
  // O holofote NÃO transiciona atrás de quem anda: com a Joy dando um passo por quadro, os
  // 200 ms de easing viravam um atraso permanente entre ela e a luz.
  $('#tutorial-spot').classList.toggle('segue', !!passo.segue);

  prepararPasso(passo);

  // Dois quadros de folga antes de medir, e uma segunda medida depois da transição. O modal
  // acabou de trocar de conteúdo e a gaveta do celular sobe em 200 ms — medir agora poria a
  // luz na altura em que o alvo AINDA está, e não na em que ele vai parar.
  const medir = () => {
    if (!tutorialAtivo || tutorialPassos[tutorialIdx] !== passo) return;
    // `rolar` existe para o alvo que é MAIOR que o seu vão: aí o navegador rola o mínimo, e o
    // mínimo pode ser deixar o começo do alvo para trás. O passo diz então o que precisa estar
    // à vista (ver o `resto`, no celular).
    (passo.rolar?.() ?? passo.alvo?.())?.scrollIntoView?.({ block: 'nearest', inline: 'nearest', behavior: 'smooth' });
    posicionarTutorial(passo.alvo?.(), passo.fundo?.());
    if (passo.segue && !tutorialSeguindo) seguirAlvoDoTutorial();
  };
  requestAnimationFrame(() => requestAnimationFrame(medir));
  setTimeout(medir, 280);
}

function pararTutorial() {
  tutorialAtivo = false;
  cancelAnimationFrame(tutorialSeguindo);
  tutorialSeguindo = 0;
  $('#tutorial').classList.add('hidden');
  $('#tutorial').setAttribute('aria-hidden', 'true');
  document.body.classList.remove('tutorial-trava');
  // O guia abriu telas pelo caminho; sair dele devolve o jogador ao jogo, e não à última aba
  // do Market por onde ele passou.
  if (estado.modalAberto) fecharModal();
  if (movelAtivo()) fecharGavetaMobile();
}

function iniciarTutorial() {
  if (!tutorialPronto()) return;
  tutorialAtivo = true;
  tutorialIdx = 0;
  tutorialPassos = passosDoGuia();
  $('#tutorial').classList.remove('hidden');
  $('#tutorial').setAttribute('aria-hidden', 'false');
  document.body.classList.add('tutorial-trava');
  renderTutorialPasso();
}

function maybeStartTutorial() {
  if (!tutorialPronto()) return;
  // Um frame de folga: o onboarding acabou de sumir e o layout ainda está se assentando.
  requestAnimationFrame(() => requestAnimationFrame(iniciarTutorial));
}

function finalizarTutorial() {
  pararTutorial();
  // A bandeira sobe AQUI, antes de a resposta do servidor voltar. Não é otimismo: o convite do
  // Discord logo abaixo só abre para quem já viu o guia, e o snapshot com `tutorialVisto` leva
  // meio segundo para chegar — sem esta linha o convite era engolido e não aparecia nunca.
  if (estado.eu) estado.eu.tutorialVisto = true;
  enviar({ t: 'tutorial.concluir' });
  maybeMostrarPopups();
}

/**
 * Troca de idioma no meio do guia: o texto é remontado, e com ele a tela do passo.
 *
 * A lista de passos é refeita porque entre um render e outro o layout pode ter trocado (uma
 * rotação que leva o desktop para o modo celular, por exemplo), e o passo do "Menu" só existe
 * num dos dois. Procurar pela CHAVE, e não pelo índice, é o que impede o jogador de pular ou
 * repetir um passo quando a lista muda de tamanho debaixo dele.
 */
function repintarTutorial() {
  if (!tutorialAtivo) return;
  const chave = tutorialPassos[tutorialIdx]?.chave;
  tutorialPassos = passosDoGuia();
  const i = tutorialPassos.findIndex((p) => p.chave === chave);
  tutorialIdx = i >= 0 ? i : Math.min(tutorialIdx, tutorialPassos.length - 1);
  renderTutorialPasso();
}

$('#tutorial-proximo').onclick = () => {
  if (tutorialIdx >= tutorialPassos.length - 1) return finalizarTutorial();
  tutorialIdx++;
  renderTutorialPasso();
};
$('#tutorial-voltar').onclick = () => {
  if (tutorialIdx <= 0) return;
  tutorialIdx--;
  renderTutorialPasso();
};
// Pular é o mesmo fim do guia: o servidor grava `tutorialVisto` e ele não volta. Quem pulou
// não quer revê-lo no próximo login mais do que quem chegou até o fim.
$('#tutorial-pular').onclick = finalizarTutorial;

window.addEventListener('resize', () => {
  if (!tutorialAtivo) return;
  const passo = tutorialPassos[tutorialIdx];
  posicionarTutorial(passo?.alvo?.(), passo?.fundo?.());
});

// -------------------------------------------------------------- estado → UI

// ------------------------------------------------------- estado que chega em delta
//
// O servidor manda só o que mudou (ver `estadoParaEnviar` em `sim.mjs`). A remontagem
// acontece no ponto de ENTRADA, antes de qualquer tela olhar para o estado — é o que permite
// que as ~44 telas que leem `estado.eu.pokemons` continuem exatamente como estavam. Para
// elas, `estado.eu` é o objeto completo de sempre; ter chegado em pedaços é assunto do
// transporte, não da interface.
const mesclarEstado = criarMescladorDeEstado();

function aplicarEstado(e) {
  const anterior = estado.eu;
  estado.eu = e;
  // Antes de qualquer tela olhar: o `automation` que chegou ainda não conhece os pedidos de
  // Coleção que estão a caminho.
  if (colecaoPendente.size) reaplicarColecaoPendente();

  // O servidor guarda o cooldown de cada golpe por NOME, e o relógio só corre com o pokémon EM
  // CAMPO: trocar de ativo PAUSA o que falta e devolve ao pokémon que saiu (ver `p.cdGolpes` e
  // `sincronizarCooldownsDoAtivo` em sim.mjs). O espelho local é `sincronizarCooldownsDaUI`, e
  // é chamado daqui porque o `activeId` do snapshot é a palavra final sobre quem está em campo
  // — a troca otimista do clique e o evento `troca` só adiantam o que este `e.activeId` confirma.
  //
  // Zerar de verdade são dois momentos, e os dois chegam por EVENTO (`case 'curado'` e `case
  // 'bossEntrou'`/`'misticoEntrou'`, em `aoEvento`), nunca por aqui.
  //
  // Já foi AQUI, pela arena nova no estado, e apagava o primeiro golpe do boss. O estado sai
  // DEPOIS dos eventos do mesmo tique, e o golpe de abertura (o de 600, sempre o mais forte
  // pronto) sai no mesmo tique da entrada: o relógio dele era armado e, no pacote seguinte,
  // apagado. O golpe batia, mas o ícone ficava "pronto" os 60 s da recarga — a luta inteira,
  // num boss que cai antes disso —, e o jogador via um golpe travado.
  sincronizarCooldownsDaUI(e.activeId);

  if (e.servidorAgora) {
    estado.campo?.sincronizar(e.servidorAgora);
    // O desvio do relógio local, para as contagens que NÃO passam pelo campo — hoje a das
    // Caixas de Fundador. Sem ele, quem está com o PC adiantado veria a venda liberar antes
    // da hora e levaria um "ainda não abriu" do servidor ao clicar em comprar.
    estado.desvioServidor = Date.now() - e.servidorAgora;
  }

  pintarTreinador(e);
  pintarAtivo(e);
  pintarTime(e);
  pintarBolsa();
  repintarFolhaSkin();
  pintarAutomacoes(e);
  pintarHudCena(e);
  pintarFaixaDeEvento(e);
  atualizarPopup(); // barras de XP da janelinha do Modo Pop-up, quando aberta

  syncChatInput();
  syncChatGuildTab();
  // A bancada do refino não é um `modalAberto`, então não entra no switch lá embaixo — e a
  // ficha aberta também não remonta sozinha. As duas se atualizam aqui, cada uma decidindo se
  // vale remontar (ver `atualizarTelasDeRefino`).
  atualizarTelasDeRefino();

  // A tela da Casa reage ao INVENTÁRIO: vender a casa boa no Mercado ou fabricar uma nova
  // muda a Academia inteira, e as duas coisas acontecem sem passar por aqui. Redesenhar no
  // snapshot é o que mantém a lista de bonecos honesta com o que o servidor acha.
  if (estado.modalAberto === 'casa') montarCasa();

  // O Professor também não é um `modalAberto`, e só se redesenhava no EVENTO de cada bancada —
  // que chega ANTES do snapshot com a bolsa nova quando o servidor não manda o estado junto
  // (troca de peças, Shiny Stone, Mega, aplicar disco). A bancada ficava com as peças de antes
  // e o botão aceso até o próximo clique, e a confirmação dizia "você tem 0". Aqui ela
  // acompanha a bolsa e os TMs da equipe. Com a busca de megas em foco ela espera o próximo
  // caractere (que já redesenha), para não roubar o cursor de quem digita.
  if (
    !$('#tm-researcher').classList.contains('hidden')
    && document.activeElement?.id !== 'mega-busca'
    && (e.items !== anterior?.items || tmsDaEquipe(e) !== tmsDaEquipe(anterior)
      // O craft de casas gasta CASAS, que não moram na bolsa: sem isto, as cinco consumidas
      // continuariam na grade até o próximo clique. O de bicicletas, idem.
      || e.casa?.lista !== anterior?.casa?.lista
      || e.bicicleta?.lista !== anterior?.bicicleta?.lista)
  ) montarTmResearcher();

  // o starter chegou: fecha a escolha e só então os atalhos de URL fazem sentido
  if (e.pokemons.length && !$('#starter').classList.contains('hidden')) {
    $('#starter').classList.add('hidden');
    logCena(t('ev.escolhaArea'));
    aplicarAtalhosUrl();
    maybeMostrarPopups();
  }

  // Primeiro pokémon acabou de chegar — hora de mostrar o tour das abas.
  if (e.pokemons.length && !anterior?.pokemons?.length) {
    const naEquipe = e.pokemons.find((p) => p.slot != null);
    const ativoOk = e.activeId != null && e.pokemons.some((p) => p.id === e.activeId);
    // Rede de segurança: o starter devia vir ativo do servidor, mas se o snapshot chegar
    // sem `activeId` o jogador ficaria preso até clicar na equipe — e a hunt quebra sem herói.
    const utilizavel = e.pokemons.find((p) => p.slot != null && podeUsarPokemon(e.level, p));
    if (utilizavel && !ativoOk) enviar({ t: 'team.active', pokemonId: utilizavel.id });
    if (!e.tutorialVisto) maybeStartTutorial();
  }

  // Centro Pokémon: a cena vira o balcão da enfermeira e o botão de curar sobe por cima
  pintarCentro(e);

  const arena = e.boss?.arena ?? null;
  // A ARENA MÍSTICA é mais uma cena que segura o campo sem hunt: quem nunca escolheu uma área e
  // usa o ticket tinha a sala APAGADA aqui, e o primeiro golpe estourava em `Campo.pos` — levando
  // junto o resto do lote de eventos (a bola e o resultado da captura).
  const mistico = e.mistico ?? null;
  const mudouCena =
    e.huntSlug !== anterior?.huntSlug ||
    !!mistico !== !!anterior?.mistico ||
    // Trocar de Outland não troca de mapa, mas troca a ETIQUETA do canto — "Brave Blastoise"
    // vira "Brave Blastoise · Outland 2". Sem esta linha o degrau novo só apareceria na
    // próxima vez que o jogador mudasse de área.
    (e.outlandTier ?? 1) !== (anterior?.outlandTier ?? 1) ||
    e.noCentro !== anterior?.noCentro ||
    // A CASA é a sexta cena, e entrar nela não mexe em nenhuma das outras cinco bandeiras: sem
    // esta linha, quem entrava em casa ficava com a etiqueta da hunt anterior no canto.
    (e.casa?.dentro ?? null) !== (anterior?.casa?.dentro ?? null) ||
    (arena?.key ?? null) !== (anterior?.boss?.arena?.key ?? null);
  pintarHudHunt(e);

  if (mudouCena) {
    // Sem hunt e sem arena não há cena nenhuma — mas entrar numa arena (ou em casa) antes de
    // escolher hunt é normal, então esses seguram o campo.
    //
    // A CASA entrou nesta lista depois de aparecer como bug: quem nunca escolheu uma área
    // (`huntSlug` nulo) e entrava em casa via menu tinha a sala APAGADA aqui, meio segundo
    // depois de o `campo.init` dela chegar — o jogador via "escolha uma área no Mapa" dentro
    // da própria casa, com os botões dos bonecos sem em que se pendurar.
    if (!e.huntSlug && !e.noCentro && !e.casa?.dentro && !arena && !mistico) {
      estado.campo?.limpar();
    }
  }

  if (deveUsarHeroiPokemon(e)) aplicarHeroiAtivo(e);

  // Modal aberto reflete o estado novo (ouro na loja, dex, hunt ativa).
  //
  // O Mapa fica de fora: redesenhar o corpo do modal duas vezes por segundo jogava o zoom e
  // a rolagem de volta ao início a cada snapshot — dava a impressão de que a roda do mouse
  // não funcionava, quando na verdade o zoom era desfeito no tick seguinte. Ali só o que
  // muda com o estado é o nível (que libera áreas) e a hunt ativa.
  //
  // O Market também: o combate continua rodando por trás, então loot cai e ouro entra o
  // tempo todo. Redesenhar tudo apagaria o número que o jogador está digitando no contador.
  //
  // O Community Market e a Shop caem no mesmo problema: `abrirModal` troca o HTML inteiro e
  // zera a rolagem da grade — quem está lendo anúncios ou produtos volta pro topo a cada
  // snapshot (~500 ms). Só atualizamos o que muda de verdade (saldo, gemas, selos).
  if (estado.modalAberto === 'mapa') {
    if (
      e.level !== anterior?.level
      || e.huntSlug !== anterior?.huntSlug
      || (e.outlandTier ?? 1) !== (anterior?.outlandTier ?? 1)
    ) montarMapaMundi();
  } else if (estado.modalAberto === 'market') {
    atualizarMarket();
  } else if (estado.modalAberto === 'bolsa') {
    atualizarBolsa();
  } else if (estado.modalAberto === 'community') {
    atualizarComunidade(e, anterior);
  } else if (estado.modalAberto === 'shop') {
    atualizarLoja(e, anterior);
  } else if (estado.modalAberto === 'ranking') {
    // O placar não depende do estado do jogador: ele chega pelas mensagens `ranking` e tem
    // sprites animados em cada linha. Redesenhar aqui reiniciaria todos e apagaria a busca.
  } else if (estado.modalAberto === 'deposito' || estado.modalAberto === 'withdraw') {
    // Depósito/saque: o extrato não muda a cada tick de hunt; remontar apagaria o scroll.
  } else if (estado.modalAberto === 'pokedex') {
    // Atualiza quando a pokédex muda (captura, evolução) sem remontar a cada tick de combate.
    if (JSON.stringify(e.pokedex ?? {}) !== JSON.stringify(anterior?.pokedex ?? {})) ligarPokedex();
  } else if (estado.modalAberto === 'shinys') {
    // Mesma história: campo de busca e uma grade de sprites animados. Quem manda nesta tela é
    // a resposta do servidor (`shiny.lista`), não o snapshot do jogador.
  } else if (estado.modalAberto === 'p5s') {
    // Idem shinys — lista paginada do servidor (`p5.lista`).
  } else if (estado.modalAberto === 'pokepedia') {
    // Manual estático — o snapshot de combate não mexe no conteúdo.
  } else if (estado.modalAberto === 'bosses') {
    // A lista de 87 bosses rola na coluna esquerda; remontar a cada tick zera o scroll —
    // o mesmo problema da Shop e da Pokédex. Só a fileira da equipe (rodapé) atualiza.
    const sig = assinaturaEquipeBossDe(e);
    if (sig !== assinaturaEquipeBoss) {
      assinaturaEquipeBoss = sig;
      pintarEquipeDoBoss();
    }
    // Reconcilia o "Vezes derrotado" com o snapshot fresco — o incremento otimista do
    // evento `bossMorto` cobre o intervalo, isto conserta qualquer diferença que sobre.
    for (const key of Object.keys(e.boss?.vitorias ?? {})) {
      if ((e.boss.vitorias[key] ?? 0) !== (anterior?.boss?.vitorias?.[key] ?? 0)) atualizarContadorBoss(key);
    }
  } else if (estado.modalAberto === 'diamantes') {
    // O campo de quantidade e o aceite somem se remontar a cada tick — volta ao mínimo (3).
    atualizarDiamantes(e, anterior);
  } else if (estado.modalAberto === 'afiliados') {
    // Modal com campo de código: remontar a cada snapshot apagaria o que está sendo digitado
    // e reiniciaria a animação do botão no painel (o mesmo problema da Shop e do Market).
  } else if (estado.modalAberto === 'votar') {
    // Nada aqui depende do snapshot: o painel do voto vem do `/topidle/me` e só muda quando um
    // voto cai — e aí o evento `votoCreditado` remonta a tela.
  } else if (estado.modalAberto === 'twitch') {
    // Só o bloco `twitch` do snapshot mexe nesta tela (a live começou, o vigia achou o jogador no
    // chat, o vínculo mudou). Remontar a cada tick fecharia o diálogo de desvincular por baixo.
    if (JSON.stringify(e.twitch ?? null) !== ultimaAssinaturaTwitch) montarTwitch();
  } else if (estado.modalAberto === 'kick') {
    // O mesmo critério: só o bloco `kick` (um resgate creditado, a lista de canais) remonta a tela.
    // A contagem regressiva das horas anda sozinha, no `tiqueModalKick`.
    if (JSON.stringify(e.kick ?? null) !== ultimaAssinaturaKick) montarKick();
  } else if (estado.modalAberto === 'calculadora') {
    // Ferramenta com três campos abertos. Remontar a cada tick apagaria o que está sendo
    // digitado, que é o mesmo motivo do Market e do de diamantes.
  } else if (estado.modalAberto === 'perfil') {
    // Retrato animado + fetch de conta: remontar a cada tick reiniciava o boneco e o bloco
    // "carregando" da seção de e-mail (o mesmo bug de zoom da Shop/Mapa).
    atualizarPerfil(e, anterior);
  } else if (estado.modalAberto === 'amigos') {
    // A Lista de Amigos é toda alimentada pelas mensagens `amigos` do servidor — o snapshot
    // não muda nada nela. Sem esta guarda ela caía no `abrirModal` genérico abaixo e era
    // remontada a cada tick de combate (~500 ms), apagando a DM sendo digitada e o valor no
    // diálogo de coins — o mesmo bug do Market/Calculadora. Fora de combate o snapshot é
    // raro, e por isso o problema só aparecia na hunt e não no Centro Pokémon.
    atualizarAmigos(e, anterior);
  } else if (estado.modalAberto === 'ginasios') {
    // Mesmo caso da Lista de Amigos, e mais grave: a tela dos Ginásios TEM NAVEGAÇÃO por
    // dentro (grade → um ginásio → o editor de time), e `montarGinasios` sempre volta para a
    // grade. Caindo no `abrirModal` genérico abaixo, cada snapshot de combate (~500 ms)
    // arrancava o jogador do ginásio que ele tinha acabado de abrir e ainda mandava um
    // `ginasio.info` novo — parecia o socket reiniciando sozinho. Quem alimenta esta tela são
    // as mensagens `ginasio`; o snapshot não tem nada a dizer a ela. Ramo VAZIO de propósito,
    // como o do voto e o da calculadora — o ⚔ de um pokémon que subiu de nível no meio da
    // escolha fica alguns segundos velho, e isso é invisível perto de perder a tela inteira.
  } else if (estado.modalAberto === 'pvp') {
    // Mesmo caso da Lista de Amigos e dos Ginásios. O painel do PvP Guild tem uma LISTA
    // ROLÁVEL própria (`.guild-pvp-corpo`: as guilds registradas numa aba, o placar da última
    // guerra na outra). Caindo no `abrirModal` genérico abaixo, cada snapshot de combate
    // (~500 ms) trocava o `#modal-corpo` inteiro — e com ele o `.guild-pvp-corpo` —, então
    // quem tinha rolado a lista voltava ao topo sozinho a cada golpe da hunt.
    //
    // De quebra, reabrir a tela dispararia um `pvp.info` e um `guild.pvp.info` a cada snapshot:
    // dois pedidos por meio segundo para uma tela que já é alimentada por push.
    //
    // Do snapshot esta tela só precisa de duas coisas — a COLEÇÃO (os slots da equipe desenham
    // sprites dela, e vender um pokémon no Mercado com a aba aberta tem de esvaziar o slot) e o
    // NÍVEL (é ele que libera o botão da fila). A assinatura abaixo é o que separa essas duas
    // de todo o resto do snapshot: sem ela, cada golpe da hunt reconstruiria as listas de
    // tabela e histórico e jogaria de volta ao topo quem estivesse lendo.
    const assinaturaPvp = `${estado.eu?.level ?? 0}:${(estado.eu?.pokemons ?? []).map((p) => p.id).join(',')}`;
    if (assinaturaPvp !== ultimaAssinaturaPvp) {
      ultimaAssinaturaPvp = assinaturaPvp;
      pintarPvp();
    }
  } else if (estado.modalAberto === 'casa') {
    // Ramo VAZIO de propósito: a tela da Casa já se atualizou lá em cima (`montarCasa`, que só
    // repinta o que mudou). Caindo no `abrirModal` genérico abaixo, cada snapshot de combate
    // (~500 ms) trocava o `#modal-corpo` inteiro — a lista voltava ao topo a cada golpe da hunt,
    // o contador do servidor recomeçava do zero, e o modal ainda pedia de novo o registro e a
    // releitura das casas ao servidor duas vezes por segundo.
  } else if (estado.modalAberto === 'passe') {
    // O Passe só muda num resgate ou numa compra (o campo `passe` do snapshot) e com o saldo
    // de diamante (o botão de comprar). Remontar a cada tick apagaria a trilha rolada e a
    // animação de abertura no meio.
    const assinaturaPasse = `${JSON.stringify(estado.eu?.passe ?? null)}|${estado.eu?.diamonds ?? 0}|${estado.eu?.level ?? 0}`;
    if (assinaturaPasse !== ultimaAssinaturaPasse) {
      ultimaAssinaturaPasse = assinaturaPasse;
      pintarPasse();
    }
  } else if (estado.modalAberto === 'campeonato') {
    // Sem remontar a tela: ela é alimentada pelo pacote `campeonato`, e cair no `abrirModal`
    // genérico abaixo trocaria o `#modal-corpo` inteiro a cada tick de combate (~500 ms) —
    // quem tinha rolado a lista de inscritos voltaria ao topo a cada golpe da hunt.
    //
    // Do snapshot a tela só usa o NÍVEL (é ele que libera o "Registrar"), e só o cabeçalho
    // depende dele. Subir de nível com a aba aberta repinta só aquele canto.
    const nivelCamp = estado.eu?.level ?? 0;
    if (nivelCamp !== ultimoNivelCampeonato) {
      ultimoNivelCampeonato = nivelCamp;
      pintarCabecalhoCampeonato();
    }
  } else if (estado.modalAberto) {
    abrirModal(estado.modalAberto);
  }

  // O selo do botão "Passe" acompanha o snapshot: ele acende quando há resgate esperando.
  pintarSeloPasse();

  // No celular, guild e voto ficam dois toques abaixo (dentro do Menu). O pontinho vermelho
  // sobe até a barra de abas para que "tem coisa te esperando" continue visível de fora.
  sincronizarMobile();
}

/**
 * O "herói" da cena — quem a câmera segue e quem ganha o anel azul embaixo.
 *
 * Em toda cena de batalha é o POKÉMON em campo: a posição dele vem nas mensagens `campo` e a
 * aparência (nível, HP, sprite) vem daqui, a cada snapshot — limitar isto à troca de pokémon
 * deixava a placa presa no nível de quando ele entrou.
 *
 * Na praça do Centro é o contrário: o herói é o BONECO do jogador, porque é ele que anda com o
 * teclado, e o pokémon vira mais um da cena. Lá o sprite vem no próprio pacote do campo, então
 * escrever o pokémon por cima aqui trocaria o treinador por um Charmander.
 *
 * Quem decide se isto vale é o CHAMADOR, e por um motivo de sincronia: a cena troca no
 * `campo.init`, que chega antes do snapshot de estado seguinte. Perguntar `estado.eu.noCentro`
 * aqui dentro leria a cena velha nos dois sentidos — carimbava o nível do pokémon no boneco ao
 * chegar na praça, e deixava a hunt começar com o treinador no lugar do pokémon ao sair dela.
 */
const deveUsarHeroiPokemon = (e) =>
  !!e && !e.noCentro && !e.casa?.dentro;

function aplicarHeroiAtivo(e) {
  if (!deveUsarHeroiPokemon(e)) return;
  const at = e.pokemons.find((p) => p.id === e.activeId);
  if (!at) return;
  estado.campo?.definirHeroi({
    // `looktypeDe`, e não `at.looktype`: o herói é a ÚNICA entidade da cena cujo sprite é
    // escolhido no cliente (o dos selvagens já vem resolvido em `lt`, no serializarMob). Sem
    // isto o shiny do jogador andava na hunt com a arte do pokémon comum — quem comprava um
    // Shiny Charizard no Mercado via o laranja em campo e o preto em todo o resto da tela.
    // A placa em cima do sprite leva o APELIDO da Name Tag, quando há. É a única entidade da
    // cena que o jogador batizou, e era a última tela em que o nome comprado não aparecia —
    // justamente a que ele olha o tempo todo.
    //
    // Só o HERÓI, e de propósito: os mobs do campo (os selvagens, e na arena os pokémon do
    // adversário) continuam com o nome da ESPÉCIE, que vem do servidor em `serializarMob`.
    // Numa luta de PvP, saber contra o que se está lutando é informação de jogo — esconder
    // "Dragonite" atrás de um apelido seria deixar a etiqueta cosmética mexer no combate, que
    // é exatamente o que ela não pode fazer. O resultado é o certo dos dois lados: eu vejo o
    // meu apelido, o adversário vê a minha espécie.
    looktype: looktypeDe(at), nome: nomeExibidoPokemon(at), level: at.level,
    hp: at.hp, maxHp: at.maxHp, shiny: at.shiny,
  });
}

function pintarTreinador(e) {
  $('#tr-nick').textContent = e.nick;
  // O retrato só é redesenhado quando a APARÊNCIA muda (skin comprada, gênero, cores do
  // onboarding). Redesenhar a cada pacote de estado trocaria o canvas 4×/s e a animação do
  // boneco nunca sairia do primeiro quadro.
  const cara = `${e.loja?.looktype}|${empacotarVisual(e.loja?.visual).join(',')}`;
  if (estado.caraDesenhada !== cara) {
    estado.caraDesenhada = cara;
    pintarRetrato('#tr-retrato', 44);
  }
  $('#tr-level').textContent = e.level;
  const ouro = num(e.gold);
  const dias = num(e.diamonds ?? 0);
  const gemas = num(e.orbs ?? 0);
  if ($('#tr-gold').textContent !== ouro) $('#tr-gold').textContent = ouro;
  if ($('#tr-diamantes').textContent !== dias) $('#tr-diamantes').textContent = dias;
  if ($('#tr-gemas').textContent !== gemas) $('#tr-gemas').textContent = gemas;
  const dentro = e.xp - e.xpNivel;
  const faixa = Math.max(1, e.xpProximo - e.xpNivel);
  $('#tr-xp-fill').style.width = `${Math.min(100, (dentro / faixa) * 100)}%`;
  $('#tr-xp-txt').textContent = `${num(dentro)} / ${num(faixa)} xp`;

  // O RANK do PvP, embaixo do personagem o tempo todo — é progressão de treinador, como o
  // nível, e não um número que só existe enquanto se está lutando.
  //
  // O snapshot é a SEMENTE (`e.pvp`), e não a verdade corrente: quem manda é `estado.pvpRank`,
  // que a aba e o fim de cada partida atualizam sem esperar o servidor. Sem essa ordem, o
  // emblema piscaria de volta para o valor de antes da partida no snapshot seguinte.
  if (e.pvp && !estado.pvpRank) estado.pvpRank = e.pvp;
  pintarRankDoTreinador();

  pintarAtivosDoTreinador(e);
  pintarSlotGuild(e.guild ?? null, e.guildConvites ?? []);
  pintarBadgeAmigos();
}

// ------------------------------------------------- VIP e boosts ativos no HUD
//
// Uma linha por coisa comprada que ainda está valendo, com o tempo restante contando ao lado.
// Três boosts ligados = três linhas empilhadas, que é o pedido — e é também o desenho certo:
// eles vencem em horas diferentes e um contador só não teria como dizer qual.
//
// O que a tela guarda é o CARIMBO de expiração (vem no snapshot); a contagem regressiva anda
// por timer local, do mesmo jeito que o botão de sair da arena. Sem isso o
// número só mexeria duas vezes por segundo, quando o servidor manda estado.

/** "2d 5h", "1h 59m", "5m 30s" — o que sobra; subunidade zero fica de fora ("2h", não "2h 0m"). */
function tempoCurto(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  if (s >= 86400) {
    const d = Math.floor(s / 86400);
    const h = Math.floor((s % 86400) / 3600);
    return h ? `${d}d ${h}h` : `${d}d`;
  }
  if (s >= 3600) {
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    return m ? `${h}h ${m}m` : `${h}h`;
  }
  if (s >= 60) {
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return sec ? `${m}m ${sec}s` : `${m}m`;
  }
  return `${s}s`;
}

/**
 * O tipo de boost, pela chave com que ele fica gravado no jogador.
 *
 * Vem do `welcome` (`tiposBoost`) e NÃO do catálogo de produtos: lá o id é o do jogo original
 * (`boost_shinycharm`, `boost_capture`) e aqui a chave é a nossa (`shiny`, `captura`).
 * Procurar por `boost_${chave}` acertava três dos cinco e mostrava a chave crua nos outros
 * dois — "shiny" no lugar de "Shiny Secret Lure".
 *
 * O nome sai sem a duração entre parênteses: "XP Boost (1h)" com quatro horas restantes
 * (porque a pessoa comprou quatro pacotes de uma hora) diria a coisa errada.
 */
const tipoDeBoost = (chave) => estado.tiposBoost.find((b) => b.chave === chave) ?? null;

/**
 * O texto de um produto da Loja, no idioma do jogador.
 *
 * O catálogo é montado no SERVIDOR (`game/loja.mjs`) e chegava com nome e descrição já
 * escritos — em português, sempre, mesmo com o jogo em inglês ou espanhol. O servidor não tem
 * como traduzir: o dicionário mora aqui e o idioma é escolha de cada aba. Então ele passou a
 * mandar a CHAVE junto do texto pronto, e a tradução acontece no último instante, aqui.
 *
 * **O texto do servidor é o fallback, não o contrário.** Produto sem chave (uma outfit nova,
 * uma promoção de última hora) continua aparecendo em português em vez de sumir da vitrine ou
 * mostrar `loja.d.algumaCoisa` na tela.
 *
 * **A convenção do sufixo `Chave`:** um parâmetro chamado `efeitoChave` é ele próprio uma
 * chave de tradução, e entra na frase como `{efeito}` já traduzido. É o que permite montar
 * "+50% de XP do TREINADOR por 2 horas" a partir de dois pedaços independentes — sem isso, as
 * 35 combinações de boost × duração precisariam de 35 frases inteiras por idioma.
 */
function textoDaLoja(chave, params, prontoDoServidor) {
  if (!chave || !temChave(chave)) return prontoDoServidor ?? '';
  const resolvidos = {};
  for (const [k, v] of Object.entries(params ?? {})) {
    if (k.endsWith('Chave')) resolvidos[k.slice(0, -5)] = temChave(v) ? t(v) : String(v ?? '');
    else resolvidos[k] = v;
  }
  return t(chave, resolvidos);
}

/** A descrição de um tipo de boost (vem do `welcome`), traduzida. */
const descricaoDoBoost = (tipo) => textoDaLoja(tipo?.descChave, null, tipo?.descricao ?? '');

/** O nome de um produto da Loja, traduzido. Card, card de pacote e janela de confirmação. */
const nomeDoProduto = (prod) => (prod?.skin && SKIN_POR_ID.has(prod.skin)
  ? t('skin.itemNome', { nome: nomeDaSkin(SKIN_POR_ID.get(prod.skin)) })
  : textoDaLoja(prod?.i18n?.nome, prod?.i18n?.params, prod?.nome ?? ''));
const nomeDoBoost = (chave) => (tipoDeBoost(chave)?.nome ?? chave).replace(/\s*\(.*\)$/, '');

function pintarAtivosDoTreinador(e) {
  const host = $('#tr-ativos');
  if (!host) return;
  const l = e.loja ?? {};
  // O relógio do SERVIDOR, não o do navegador. O carimbo de fim do boost (`ate`) é do sim, e
  // comparar com um `Date.now()` local faz a linha sumir da tela antes da hora em quem está
  // com o relógio adiantado — por fuso errado, por relógio parado ou por extensão que acelera
  // o tempo do navegador. O boost segue valendo no servidor; quem mentia era o painel.
  const agora = agoraDoServidor();

  // A assinatura evita redesenhar (e recriar os `<img>`) a cada snapshot: o que muda de
  // segundo em segundo é só o texto do contador, e quem cuida dele é `tiqueAtivos`.
  const chaves = Object.entries(l.boosts ?? {})
    .filter(([, ate]) => ate > agora)
    .map(([k, ate]) => `${k}:${ate}`)
    .sort()
    .join('|');
  const passeVipAte = Number(e.passe?.vipAte) || 0;
  const passeVip = passeVipAte > agora;
  const tw = e.twitch ?? null;
  const kk = e.kick ?? null;
  // O `livesTwitchQueFaltam` entra na assinatura, e não é detalhe: um segundo streamer entrando no
  // ar não mexe em `aoVivo`, `assistindo` nem `pctAtual` de quem já está assistindo a um. Sem ele,
  // a linha não seria redesenhada e o ponto vermelho só apareceria no próximo motivo qualquer.
  const assinatura = `${l.vip ? l.vipAte : 0}|${passeVip ? passeVipAte : 0}|${chaves}|${e.guildBonusPct ?? 0}|${e.guildBonusRank ?? 0}|${
    tw ? `${tw.login ?? ''}:${tw.aoVivo ? 1 : 0}:${tw.assistindo ? 1 : 0}:${tw.pctAtual ?? 0}:${livesTwitchQueFaltam(tw)}` : '-'}|${
    kk ? `${kk.vinculado ? 1 : 0}:${kk.login ?? ''}:${TIPOS_KICK_TELA.map((tp) => (Number(kk.bonus?.[tp]) > agora ? kk.bonus[tp] : 0)).join(',')}` : '-'}`;
  if (host.dataset.assinatura === assinatura) return;
  host.dataset.assinatura = assinatura;

  host.innerHTML = '';

  // O VIP primeiro, com a tag azul. Em DIAS, que é a unidade em que a assinatura é vendida.
  if (l.vip) {
    // O marco de 500 convidados dá VIP que não expira, e ele é gravado como um instante
    // absurdamente longe (ver `VIP_PERMANENTE_ATE`, em `shared/convites.mjs`). Sem este desvio
    // a linha diria "354.421 dias" e o título, "VIP até 01/01/2999".
    const permanente = vipEhPermanente(l.vipAte);
    const dias = Math.max(1, Math.ceil((l.vipAte - agora) / 86400000));
    const linha = document.createElement('div');
    linha.className = 'tr-ativo vip';
    linha.title = `${t('painel.vipAtivo')} · ${t('painel.vipBonusXp')}${
      permanente ? ` · ${t('painel.vipPermanente')}` : ` · ${t('painel.vipAte', { tempo: new Date(l.vipAte).toLocaleString('pt-BR') })}`}`;
    linha.innerHTML = `
      <span class="selo-vip">VIP</span>
      <span class="tr-ativo-nome">${t('painel.vipBonusXp')}</span>
      ${permanente
        ? `<span class="tr-ativo-tempo">${t('painel.vipPermanente')}</span>`
        : `<span class="tr-ativo-tempo" data-ate="${l.vipAte}" data-dias="1">${t('painel.dias', { n: dias })}</span>`}`;
    host.appendChild(linha);
  }

  // O Passe VIP logo abaixo, com a coroa do próprio passe. É outro prazo (30 dias corridos da
  // compra, `passe.vipAte`), independente do VIP da Loja — quem tem os dois vê as duas linhas.
  // O clique abre o Passe: é de lá que sai o resgate dobrado de hoje.
  if (passeVip) {
    const dias = Math.max(1, Math.ceil((passeVipAte - agora) / 86400000));
    const linha = document.createElement('button');
    linha.type = 'button';
    linha.className = 'tr-ativo passe-vip';
    linha.title = t('painel.passeVipAte', { tempo: new Date(passeVipAte).toLocaleString('pt-BR') });
    // A coroa no tamanho do arquivo (28×19): encolhida para 16 px ela vira um borrão.
    linha.innerHTML = `
      <img class="tr-ativo-passe" src="${ICONE_PASSE_VIP}" width="28" height="19" alt="">
      <span class="tr-ativo-nome">${t('passe.vipTitulo')}</span>
      <span class="tr-ativo-tempo" data-ate="${passeVipAte}" data-dias="1">${t('painel.dias', { n: dias })}</span>`;
    linha.addEventListener('click', () => abrirModal('passe'));
    host.appendChild(linha);
  }

  const pctGuild = Number(e.guildBonusPct) || 0;
  const rankGuild = Number(e.guildBonusRank) || 0;
  if (pctGuild > 0 && rankGuild > 0) {
    const linha = document.createElement('div');
    linha.className = 'tr-ativo';
    const top = rotuloTopGuild(rankGuild);
    linha.title = t('guild.bonusAtivo', { top, n: pctGuild });
    linha.innerHTML = `
      <span class="tr-ativo-nome">⚔ Guild</span>
      <span class="tr-ativo-valor">${top} — +${pctGuild}%</span>`;
    host.appendChild(linha);
  }

  // O BÔNUS TWITCH fica junto dos outros bônus, e aparece SEMPRE (quando o servidor tem a Twitch
  // configurada): sem vínculo ele é o convite "Conectar Twitch"; com vínculo, diz se o +15% está
  // valendo agora. Ver `linhaTwitch`.
  if (tw) host.appendChild(linhaTwitch(tw));
  // O BÔNUS NA KICK logo abaixo, no verde da Kick: uma linha só, com o ícone de cada bônus que está
  // valendo — a contagem de cada um fica no modal. Ver `linhaKick`.
  if (kk) host.appendChild(linhaKick(kk, agora));

  for (const [chave, ate] of Object.entries(l.boosts ?? {})) {
    if (ate <= agora) continue;
    const linha = document.createElement('div');
    linha.className = 'tr-ativo';
    const tipo = tipoDeBoost(chave);
    linha.title = descricaoDoBoost(tipo) || nomeDoBoost(chave);
    linha.appendChild(iconeArquivo(tipo?.icone ?? ICONE_DIAMANTE, 16));
    const nome = document.createElement('span');
    nome.className = 'tr-ativo-nome';
    nome.textContent = nomeDoBoost(chave);
    const tempo = document.createElement('span');
    tempo.className = 'tr-ativo-tempo';
    tempo.dataset.ate = ate;
    tempo.textContent = tempoCurto(ate - agora);
    linha.append(nome, tempo);
    host.appendChild(linha);
  }
}

/**
 * O glifo da Twitch — o balão com os dois traços. SVG inline pelo mesmo motivo dos ícones da coluna
 * do retrato: um desenho de uma linha não vale uma requisição nem um arquivo de arte a manter.
 * Traçado do Simple Icons (CC0).
 */
const GLIFO_TWITCH = `<svg class="tw-glifo" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M11.571 4.714h1.715v5.143H11.57zm4.715 0H18v5.143h-1.714zM6 0L1.714 4.286v15.428h5.143V24l4.286-4.286h3.428L22.286 12V0zm14.571 11.143l-3.428 3.428h-3.429l-3 3v-3H6.857V1.714h13.714Z"/></svg>`;

/**
 * As lives oficiais que estão no ar DANDO bônus e que ele ainda não abriu.
 *
 * É a conta que separa "estou ganhando o bônus" de "estou ganhando MENOS do que dá": quem assiste
 * ao patopapao com o axtlol e o clovao também no ar está em 15% quando podia estar em 17%. Esse
 * número vira o ponto vermelho na ficha e nas linhas do modal.
 *
 * Duas exigências, e as duas evitam um ponto que mente:
 *
 *   · **vínculo** — sem conta da Twitch ligada não há "+1% a mais" a perder; o que a tela tem a
 *     dizer a quem não vinculou é o convite, que já é o estado `conectar`.
 *   · **`bonus === true`** — só conta a live cujo chat o vigia consegue ler. Numa live sem o
 *     `/mod faasii` ninguém é detectado: mandar o jogador para lá não daria +1% nenhum, e o ponto
 *     seria uma promessa que o servidor não tem como cumprir.
 */
function livesTwitchQueFaltam(tw) {
  if (!tw?.login) return 0;
  const minusculo = (x) => String(x ?? '').toLowerCase();
  const jaEstou = new Set((tw.assistindoEm ?? []).map(minusculo));
  const comBonus = new Set((tw.oficiais ?? []).filter((o) => o.bonus === true).map((o) => minusculo(o.login)));
  return (tw.lives ?? []).filter((l) => comBonus.has(minusculo(l.login)) && !jaEstou.has(minusculo(l.login))).length;
}

/**
 * A linha do BÔNUS TWITCH na ficha do treinador. Quatro estados, e a linha é sempre um botão que
 * abre o modal da Twitch:
 *
 *   conectar   sem vínculo           "Conectar Twitch   +15% XP"   — o convite
 *   ativo      achado no chat        "Bônus Twitch      +17% XP"   — acesa, como o VIP, com o bônus
 *                                                                    DELE (15% + 1% por live a mais)
 *   aovivo     live no ar, não achado "Twitch ao vivo  • assista"   — o ponto vermelho chama
 *   offline    vinculado, sem live    "Bônus Twitch      offline"   — apagada
 *
 * O "aovivo" também é o estado dos primeiros minutos de quem acabou de abrir a live: a lista do
 * chat da Twitch chega atrasada, e a linha só acende quando o vigia o encontra.
 *
 * E, no "ativo", um PONTO VERMELHO quando sobrou live para abrir. Quem já está numa live tem a
 * linha acesa e o "+15% XP" verde — tudo diz "está tudo certo", e era justamente aí que o jogador
 * não tinha como saber que o colega do streamer estava no ar valendo mais um ponto. O ponto é o
 * mesmo do "aovivo", e pela mesma razão: é o estado em que ele tem algo a FAZER.
 */
function linhaTwitch(tw) {
  const situacao = !tw.login ? 'conectar' : tw.assistindo ? 'ativo' : tw.aoVivo ? 'aovivo' : 'offline';
  const faltam = situacao === 'ativo' ? livesTwitchQueFaltam(tw) : 0;
  const nome = {
    conectar: t('twitch.linhaConectar'),
    ativo: t('twitch.linhaBonus'),
    aovivo: t('twitch.linhaAoVivo'),
    offline: t('twitch.linhaBonus'),
  }[situacao];
  const valor = situacao === 'aovivo'
    ? `<i class="tw-ponto" aria-hidden="true"></i>${escapar(t('twitch.valorAssista'))}`
    : situacao === 'offline' ? escapar(t('twitch.valorOffline'))
      : `+${Number(situacao === 'ativo' && tw.pctAtual) || Number(tw.pct) || 0}% XP`;
  const linha = document.createElement('button');
  linha.type = 'button';
  linha.className = `tr-ativo twitch tw-${situacao}${faltam ? ' tw-tem-mais' : ''}`;
  linha.title = faltam
    ? t('twitch.tipFaltam', { n: faltam, extra: Number(tw.extra) || 0 })
    : t('twitch.tip', { pct: Number(tw.pct) || 0, extra: Number(tw.extra) || 0 });
  linha.innerHTML = `${faltam ? '<i class="tw-ponto" aria-hidden="true"></i>' : ''}${GLIFO_TWITCH}<span class="tr-ativo-nome">${escapar(nome)}</span><span class="tr-ativo-valor">${valor}</span>`;
  linha.addEventListener('click', () => abrirModal('twitch'));
  return linha;
}

/**
 * O glifo da Kick: o "K" de blocos da marca, desenhado em retângulos. SVG inline pelo motivo do
 * glifo da Twitch.
 */
const GLIFO_KICK = `<svg class="kk-glifo" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M1.5 0h8v5.3h2.7V2.7h2.6V0h8v8h-2.6v2.7h-2.7v2.6h2.7V16h2.6v8h-8v-2.7h-2.6v-2.6H9.5V24h-8z"/></svg>`;

/** Os três bônus da Kick, na ordem da tela — as mesmas chaves dos boosts da Loja (ícone e nome). */
const TIPOS_KICK_TELA = ['xp', 'captura', 'shiny'];

/**
 * As linhas do BÔNUS NA KICK na ficha do treinador.
 *
 * A primeira é sempre o BOTÃO (abre o modal da Kick), em três estados:
 *
 *   conectar   sem vínculo          "Bônus na Kick   vincular"        — o convite, com o fundo verde
 *   ativo      algum bônus valendo  "Bônus na Kick   [XP][CATCH][LURE]" — acesa, com o ícone de cada
 *                                                                       bônus que está rodando
 *   vinculado  nenhum valendo       "Bônus na Kick   resgate"         — no lugar, esperando a live
 *
 * Uma linha SÓ, com os três bônus valendo ao mesmo tempo: o tempo de cada um mora no modal (o clique
 * abre), e não numa pilha de linhas na ficha. `data-kk-fim` é o fim do que acaba primeiro — o
 * `tiqueAtivos` redesenha a linha nessa hora, para o ícone dele sair.
 */
function linhaKick(kk, agora) {
  const ativos = TIPOS_KICK_TELA
    .map((tp) => [tp, Number(kk.bonus?.[tp]) || 0])
    .filter(([, ate]) => ate > agora);
  // Vinculado pelo id (`kk.vinculado`), não pelo nome — a Kick devolve o nome vazio para algumas contas.
  const situacao = !(kk.vinculado ?? !!kk.login) ? 'conectar' : ativos.length ? 'ativo' : 'vinculado';
  const pct = Number(kk.pct) || 0;
  const botao = document.createElement('button');
  botao.type = 'button';
  botao.className = `tr-ativo kick kk-${situacao}`;
  botao.innerHTML = `${GLIFO_KICK}<span class="tr-ativo-nome">${escapar(t('kick.linha'))}</span>`;
  if (situacao === 'ativo') {
    const icones = document.createElement('span');
    icones.className = 'tr-ativo-valor kk-icones';
    for (const [tp] of ativos) icones.appendChild(iconeArquivo(tipoDeBoost(tp)?.icone ?? ICONE_DIAMANTE, 16));
    botao.appendChild(icones);
    botao.dataset.kkFim = String(Math.min(...ativos.map(([, ate]) => ate)));
    botao.title = t('kick.ativosDica', { lista: ativos.map(([tp]) => t(`kick.bonus.${tp}`, { pct })).join(' · ') });
  } else {
    const valor = situacao === 'conectar' ? t('kick.valorVincular') : t('kick.valorResgate');
    botao.insertAdjacentHTML('beforeend', `<span class="tr-ativo-valor">${escapar(valor)}</span>`);
    botao.title = t('kick.tip', { pct });
  }
  botao.setAttribute('aria-label', `${t('kick.linha')} — ${botao.title}`);
  botao.addEventListener('click', () => abrirModal('kick'));
  return botao;
}

/**
 * A contagem regressiva dos ativos, a cada segundo.
 *
 * Quando um deles chega a zero a linha some na hora — mas a assinatura é zerada junto, para
 * o próximo snapshot redesenhar a lista e não deixar um buraco onde estava o boost vencido.
 */
function tiqueAtivos() {
  const agora = Date.now();
  // A prancheta corre ANTES do `return` logo abaixo: o relógio dela não tem relação nenhuma
  // com a lista de boosts, e ficava congelado em quem não tinha nenhum ligado.
  tiqueSessao(agora);
  // As horas do modal da Kick andam no mesmo relógio, e também antes do `return`: o modal pode
  // estar aberto com a ficha vazia.
  tiqueModalKick();
  const host = $('#tr-ativos');
  if (!host?.children.length) return;
  // Os carimbos `data-ate` são do SERVIDOR e só podem ser comparados com o relógio dele —
  // o mesmo motivo de `pintarAtivosDoTreinador`. A prancheta acima fica no relógio local de
  // propósito: ela mede o tempo desta sessão no aparelho, não um prazo que o sim concedeu.
  const doServidor = agoraDoServidor();
  let venceu = false;
  for (const el of host.querySelectorAll('.tr-ativo-tempo[data-ate]')) {
    const resta = Number(el.dataset.ate) - doServidor;
    if (resta <= 0) {
      venceu = true;
      continue;
    }
    el.textContent = el.dataset.dias
      ? t('painel.dias', { n: Math.max(1, Math.ceil(resta / 86400000)) })
      : tempoCurto(resta);
  }
  // A linha da Kick não tem contador (o tempo de cada bônus está no modal), mas o ícone do bônus
  // que acabou tem de sair da ficha na hora — ver `linhaKick`.
  for (const el of host.querySelectorAll('[data-kk-fim]')) {
    if (Number(el.dataset.kkFim) - doServidor <= 0) venceu = true;
  }
  if (venceu) {
    host.dataset.assinatura = '';
    if (estado.eu) pintarAtivosDoTreinador(estado.eu);
  }
}

/**
 * O tique da prancheta: o relógio na tela, os botões de Reset saindo do bloqueio e a gravação
 * de rotina no disco.
 *
 * A gravação só acontece com o SOCKET DE PÉ, e é isso que tira o tempo offline da conta: com a
 * conexão caída nada é gravado, então na volta o relógio retoma do último instante em que o
 * jogo estava mesmo rodando. E ela roda por TEMPO, não por evento — quem está parado no Centro
 * também precisa ter o relógio salvo.
 */
function tiqueSessao(agora) {
  if (!estado.sessao) return;
  if (estado.ws?.readyState === 1) salvarSessaoHunt(agora);
  // O RITMO do Modo Economia anda por tempo, não por evento: o denominador é o relógio, então
  // ele muda mesmo num minuto sem nenhum abate. Seis `textContent` por segundo.
  if (economiaLigado()) pintarRitmoEconomia();
  if (!estado.sessaoAberta) return;
  const el = $('#sessao-tempo');
  if (el) el.textContent = tempoSessao(agora - estado.sessao.inicio);
  pintarRitmoSessao(agora);
  const reset = $('#sessao-reset');
  if (reset?.disabled && agora >= estado.sessaoResetLivreEm) reset.disabled = false;
  const resetCap = $('#capturas-reset');
  if (resetCap?.disabled && agora >= estado.capturasHistResetLivreEm) resetCap.disabled = false;
}
setInterval(tiqueAtivos, 1000);

// ------------------------------------------------------- faixa de evento
//
// O buff que o administrador liga para o servidor inteiro, anunciado no alto da batalha.
//
// Ela pisca DEVAGAR (3 s por ciclo) e nunca some por conta própria: um evento é a única coisa
// que muda o jogo para todo mundo ao mesmo tempo, e quem entrou no meio precisa entender em um
// olhar por que a XP está estranha. Um toast só alcançaria quem estava com a aba aberta na
// hora exata em que o admin clicou.
//
// O prazo é um CARIMBO (`terminaEm`) e a contagem usa o relógio sincronizado com o servidor —
// mesma decisão do botão de sair do Centro. Com `Date.now()` puro, um PC
// com horário atrasado mostrava mais tempo de evento do que quem tinha o relógio certo.

/** "XP Bonus Trainer: 50% + XP Bonus Pokemon: 50% + Bonus Farm: 30% por 60 minutos" */
function textoDoEvento(ev) {
  return t('evt.faixa', {
    tr: num(ev.xpTreinadorPct ?? 0),
    pk: num(ev.xpPokemonPct ?? 0),
    farm: num(ev.farmPct ?? 0),
    min: num(ev.minutos ?? 0),
  });
}

/**
 * "🎉 EVENTO! +10% XP · +5% farm" — a versão CURTA, que é a que vai para a tela.
 *
 * A frase longa tinha 700 px e nascia no meio do topo da cena, onde só cabem uns 400: ela
 * passava por cima do "Ir para o Centro Pokémon" e do "Desistir do Combate". O texto inteiro
 * continua no `aria-label`, para quem lê a tela por leitor.
 *
 * Os dois XP viram UM pedaço quando são iguais (que é o caso de quase todo evento) e o que
 * está em zero não aparece: "+10% XP · +5% farm" em vez de "+10% XP treinador · +10% XP
 * pokémon · +0% farm".
 */
function textoCurtoDoEvento(ev) {
  const tr = Number(ev.xpTreinadorPct) || 0;
  const pk = Number(ev.xpPokemonPct) || 0;
  const farm = Number(ev.farmPct) || 0;
  const partes = [];
  if (tr && tr === pk) partes.push(t('evt.parteXp', { n: num(tr) }));
  else {
    if (tr) partes.push(t('evt.parteXpTr', { n: num(tr) }));
    if (pk) partes.push(t('evt.parteXpPk', { n: num(pk) }));
  }
  if (farm) partes.push(t('evt.parteFarm', { n: num(farm) }));
  return t('evt.curta', { bonus: partes.join(' · ') });
}

/** "1:04:20" ou "12:07" — a contagem regressiva do evento, na precisão do segundo. */
function tempoDeEvento(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const mm = String(Math.floor((s % 3600) / 60)).padStart(2, '0');
  const ss = String(s % 60).padStart(2, '0');
  const h = Math.floor(s / 3600);
  return h > 0 ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
}

function pintarFaixaDeEvento(e) {
  const faixa = $('#evento-faixa');
  if (!faixa) return;
  const ev = e?.evento ?? null;
  const agora = agoraSincronizado();
  estado.evento = ev && ev.terminaEm > agora ? ev : null;
  faixa.classList.toggle('hidden', !estado.evento);
  if (!estado.evento) return;
  $('#evento-texto').textContent = textoCurtoDoEvento(estado.evento);
  faixa.setAttribute('aria-label', textoDoEvento(estado.evento));
  tiqueEvento();
}

/** O relógio da faixa. Some sozinha quando o prazo vira — sem esperar pacote nenhum. */
function tiqueEvento() {
  const faixa = $('#evento-faixa');
  if (!faixa || !estado.evento) return;
  const resta = estado.evento.terminaEm - agoraSincronizado();
  if (resta <= 0) {
    estado.evento = null;
    faixa.classList.add('hidden');
    return;
  }
  // Só o relógio, sem o "restam": é a parte que muda a cada segundo, e a que precisa caber
  // inteira quando a frase ao lado já está cortada por reticências.
  $('#evento-tempo').textContent = `⏱ ${tempoDeEvento(resta)}`;
}
setInterval(tiqueEvento, 1000);

/** Botões e barras que só existem numa cena específica (a arena do boss, a saída da hunt). */
function pintarHudCena(e) {
  // Arena: o botão de abandonar, com o aviso de que a entrada não volta. O MESMO botão serve à
  // Arena Mística — a pergunta de confirmação é que muda (ver o `onclick` dele).
  const mistico = e.mistico ?? null;
  const arena = e.boss?.arena ?? (mistico ? { key: ARENA_MISTICA, mistico: true } : null);
  $('#boss-sair').classList.toggle('hidden', !arena || !!mistico?.arremessou);
  // O lendário no chão com a bola ainda na mão: a escolha abre (de novo, se a aba recarregou).
  if (mistico?.caido) abrirEscolhaBolaMistica(mistico.caido);
  if ((arena?.key ?? null) !== (estado.bossBarKey ?? null)) {
    estado.bossBarKey = arena?.key ?? null;
    estado.bossBarHp = null;
  }
  pintarBarraBoss();

  // "Ir para o Centro Pokémon" só numa HUNT: já estar no Centro, numa arena de boss ou
  // dentro de casa são casos em que ele não faz sentido ou fura regra.
  const emCasa = !!e.casa?.dentro;
  const naHunt = !!e.huntSlug && !e.noCentro && !emCasa && !arena;
  $('#hunt-saida').classList.toggle('hidden', !naHunt);
  $('#palco')?.classList.toggle('hunt-ativa', naHunt);
  // A Escape Rope acompanha a mesma condição (é a mesma saída, sem a espera) e some junto na
  // arena PvP — o servidor recusa lá, e um botão que só produz recusa não deveria existir.
  pintarEscapeRope(e);
  // O carimbo do servidor só manda quando é MAIOR que o nosso: entre dois snapshots o cliente
  // já rearmou a contagem a cada dano, e aceitar um carimbo velho faria o relógio voltar.
  if (naHunt) {
    estado.centroLivreEm = Math.max(estado.centroLivreEm, e.centroLivreEm ?? 0);
    estado.ondaSeq = e.ondaSeq ?? estado.ondaSeq ?? 0;
    estado.combateOndaSeq = e.combateOndaSeq ?? estado.combateOndaSeq ?? 0;
  } else {
    estado.centroLivreEm = 0;
    estado.ondaSeq = 0;
    estado.combateOndaSeq = 0;
    estado._spawnOndaAtual = false;
  }
}

/** Relógio alinhado ao servidor — ver `campo.sincronizar`. */
const agoraSincronizado = () => estado.campo?.agora ?? Date.now();

/** Barra grande de vida do boss no centro do palco — lê o mob pelo slot da arena. */
function pintarBarraBoss() {
  const caixa = $('#boss-vida');
  if (!caixa) return;
  // O lendário da ARENA MÍSTICA usa a mesma barra enquanto está de pé: é uma luta de chefe, e o
  // HP dele (nível 100, ×5 de selvagem) não cabe na barrinha acima da cabeça.
  const mst = estado.eu?.mistico;
  const arena = estado.eu?.boss?.arena
    ?? (mst && mst.slot != null && !mst.caido && !mst.arremessou ? { key: null, slot: mst.slot, nome: mst.nome } : null);
  caixa.classList.toggle('mistico', !!arena && arena.key == null);
  if (!arena) {
    caixa.classList.add('hidden');
    caixa.setAttribute('aria-hidden', 'true');
    estado.bossBarHp = null;
    return;
  }

  const ficha = arena.key ? fichaDoBoss(arena.key) : null;
  const mob = estado.campo?.mobs?.get(arena.slot);
  const maxHp = mob?.maxHp;
  caixa.classList.remove('hidden');
  caixa.setAttribute('aria-hidden', 'false');
  $('#boss-vida-nome').textContent = ficha?.nome ?? arena.nome ?? mob?.nome ?? arena.key;

  if (!maxHp) {
    $('#boss-vida-txt').textContent = '';
    return;
  }

  const hp = Math.max(0, Number(mob.hp ?? maxHp));
  const pct = Math.min(100, (hp / maxHp) * 100);
  const trilhoVida = $('#boss-vida-trilho-vida');
  const atual = $('#boss-vida-atual');
  const derretendo = $('#boss-vida-derretendo');

  $('#boss-vida-txt').textContent = `${num(Math.round(hp))} / ${num(maxHp)}`;
  trilhoVida.classList.toggle('baixo', pct <= 35);
  atual.style.width = `${pct}%`;

  const hpAnterior = estado.bossBarHp;
  if (hpAnterior == null || hp >= hpAnterior) {
    derretendo.style.transition = 'none';
    derretendo.style.width = `${pct}%`;
    requestAnimationFrame(() => {
      derretendo.style.transition = '';
    });
  } else {
    const velhoPct = Math.min(100, (hpAnterior / maxHp) * 100);
    derretendo.style.transition = 'none';
    derretendo.style.width = `${velhoPct}%`;
    requestAnimationFrame(() => {
      derretendo.style.transition = '';
      derretendo.style.width = `${pct}%`;
    });
    caixa.classList.remove('pulso');
    void caixa.offsetWidth;
    caixa.classList.add('pulso');
  }

  estado.bossBarHp = hp;
}

/**
 * A trava de 3 s do botão "Ir para o Centro Pokémon", a 12 fps.
 *
 * Mesma ideia do botão da arena PvP: o servidor manda o CARIMBO em que a saída libera e a tela
 * conta sozinha até lá. E, como lá, o cliente rearma a contagem a cada dano que ele mesmo vê
 * (`rearmarCombate`) — o snapshot sai no máximo 2×/s, e uma contagem de três segundos que só
 * anda de meio em meio segundo parece travada.
 */
function tiqueCentroSaida() {
  const btn = $('#ir-centro');
  const resta = restaCombateHuntMs();
  // Quem esconde a dupla é o CONTÊINER (`#hunt-saida`), não o botão — ver o HTML.
  if (!$('#hunt-saida')?.classList.contains('hidden')) {
    btn.disabled = resta > 0;
    $('#ir-centro-conta').textContent = resta > 0 ? `${(resta / 1000).toFixed(1)}s` : '';
  }
  // A trava de combate da hunt (3 s) vale para trocar de área. O PvP ranqueado NÃO entra
  // aqui: a partida dele acontece no servidor, longe da hunt, e procurar fila enquanto se
  // caça é exatamente o que o modo se propõe a ser.
}
setInterval(tiqueCentroSaida, 80);

/** Selvagens vivos no palco (ignora corpos caídos). */
function huntSemMobVivoNoCampo() {
  const mobs = estado.campo?.mobs;
  if (!mobs?.size) return true;
  for (const m of mobs.values()) {
    if (!m.morto && (m.hp ?? 0) > 0) return false;
  }
  return true;
}

/**
 * Janela em que a saída da hunt libera na hora: entre ondas ou logo após respawn, antes do
 * primeiro golpe da onda nova. Depois do primeiro dano, voltam os 3 s normais.
 */
function huntSaidaLivreAgora() {
  if (!estado.eu?.huntSlug || estado.eu?.noCentro || estado.eu?.boss?.arena || estado.eu?.mistico) return false;
  if (!estado.campo) return false;
  if (huntSemMobVivoNoCampo()) return true;
  return (estado.combateOndaSeq ?? 0) < (estado.ondaSeq ?? 0);
}

/**
 * Qualquer dano trocado na hunt rearma os 3 s. É a mesma regra do servidor.
 *
 * Ela já remontou a aba de PvP a cada golpe, e não remonta mais: aquilo existia para atualizar
 * o rótulo "aguarde 2,4s" dos botões de entrar na arena ao vivo, que não existem mais. A fila
 * do ranqueado não é travada por combate — procurar partida enquanto se caça é o ponto do modo.
 */
const rearmarCombate = () => {
  if (!estado.eu?.huntSlug || estado.eu?.noCentro) return;
  estado.combateOndaSeq = estado.ondaSeq ?? 0;
  estado.centroLivreEm = agoraSincronizado() + 3000;
};

$('#boss-sair').onclick = () => confirmarSairArena();

/**
 * Sair da arena. Na do Boss, a pergunta é "largar a entrada que já foi paga"; na Arena Mística é
 * outra: sair é perder o lendário E o ticket, sem volta.
 *
 * O desenho é o de uma desistência: quem fica para trás aparece sem cor, com a bandeira branca
 * no canto — e, na Mística, o ticket ao lado, riscado.
 */
function confirmarSairArena() {
  const mst = estado.eu?.mistico;
  if (mst) {
    const lt = estado.especies.get(mst.speciesId)?.looktype;
    return confirmar({
      titulo: t('mistico.sairTitulo'),
      texto: `
        ${dlgPalco(`
          ${dlgAtor({
            arte: lt ? dlgArteLt(lt, 72) : dlgArteHtml(dlgMedalha({ icone: 'interrogacao', tom: 'mega' })),
            nome: escapar(mst.nome ?? ''),
            classe: 'sai',
            marca: dlgIcone('bandeira', 15),
          })}
          ${dlgAtor({ arte: dlgArteItem(MYSTIC_TICKET_ID, 64), nome: 'MysticTicket', classe: 'sai', marca: dlgIcone('xis', 13) })}`, 'perigo')}
        ${dlgFrase('', t('mistico.sairTexto', { nome: escapar(mst.nome ?? '') }))}`,
      rotuloSim: t('mistico.sairSim'),
      tom: 'perigo',
      aoConfirmar: () => enviar({ t: 'mistico.sair' }),
    });
  }
  const key = estado.eu?.boss?.arena?.key;
  const boss = fichaDoBoss(key);
  // A arte mora no catálogo da galeria (`bossesCatalogo`), não na ficha de quem tem arena.
  const lt = estado.bossesCatalogo?.find((b) => b.key === key)?.looktype;
  return confirmar({
    titulo: t('boss.abandonarTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: lt ? dlgArteLt(lt, 76) : dlgArteHtml(dlgMedalha({ icone: 'bandeira', tom: 'perigo' })),
        nome: escapar(boss?.nome ?? ''),
        classe: 'sai',
        marca: dlgIcone('bandeira', 15),
      }), 'perigo')}
      ${dlgFrase('', t('boss.abandonarTexto'))}`,
    tom: 'perigo',
    aoConfirmar: () => enviar({ t: 'boss.sair' }),
  });
}

// ---------------------------------------------------------------------- ORBs
//
// A carteira: comprar ORBs com USDT, sacar ORBs para USDT, e o painel PÚBLICO do caixa do
// projeto. Todo número aqui vem do servidor — a tela não calcula preço nenhum, porque um
// preço divergente entre cliente e servidor numa moeda com lastro é o pior tipo de bug.

/** Formata USDT com 2 casas — é assim que o jogador pensa em dinheiro. */
const usd = (v) => `$${Number(v ?? 0).toFixed(2)}`;

const ROTULO_MOTIVO = {
  compra: 'orbs.tipoCompra',
  saque: 'orbs.tipoSaque',
  saque_estorno: 'orbs.tipoEstorno',
  market_venda: 'orbs.tipoVenda',
  market_compra: 'orbs.tipoCompraMarket',
};

const ROTULO_STATUS = {
  pendente: 'orbs.statusPendente',
  aguardando_aprovacao: 'orbs.statusAguardando',
  enviando: 'orbs.statusEnviando',
  confirmado: 'orbs.statusConfirmado',
  falhou: 'orbs.statusFalhou',
  cancelado: 'orbs.statusCancelado',
};

/**
 * DEPÓSITO e WITHDRAW são dois modais separados, abertos de dentro da Loja.
 *
 * Antes era um painel só com tudo junto. Separar tem uma razão prática: são as duas ações do
 * jogo que mexem com dinheiro de verdade, e cada uma tem um aviso próprio que precisa ser
 * lido. Numa tela só, o aviso de "transferência na blockchain não volta" ficava rolando junto
 * com o endereço de depósito, que é a informação oposta.
 *
 * O painel público do caixa aparece nos dois — é o compromisso de transparência do projeto, e
 * ele vale tanto para quem põe dinheiro quanto para quem tira.
 */
function renderDeposito() {
  return `<div id="orbs-corpo" class="orbs-corpo">${t('comum.carregando')}</div>`;
}
const renderWithdraw = renderDeposito;

function aoReceberOrbs(m) {
  estado.orbs = m;
  if (estado.eu) estado.eu.orbs = m.saldo;
  pintarTreinador(estado.eu ?? {});
  if (estado.modalAberto === 'deposito') montarDeposito();
  else if (estado.modalAberto === 'withdraw') montarWithdraw();
  else if (estado.modalAberto === 'shop') montarLoja();
}

/** O painel público do caixa. Igual nos dois modais — é o mesmo compromisso. */
function blocoDoCaixa(c) {
  return `
    <section class="orbs-caixa">
      <p class="orbs-nota">${t('orbs.carteiraProjetoTexto')}</p>
      ${
        c.carteira
          ? `<code class="orbs-endereco">${escapar(c.carteira)}</code>
             ${c.explorer ? `<a class="orbs-link" href="${escapar(c.explorer)}" target="_blank" rel="noopener">${t('orbs.verNoExplorer')}</a>` : ''}`
          : `<em class="orbs-nota">— CARTEIRA_PROJETO não configurada —</em>`
      }
      <div class="orbs-numeros">
        <div><span>${t('orbs.arrecadado')}</span><b>${usd(c.arrecadadoUsdt)}</b></div>
        <div><span>${t('orbs.sacadoJogadores')}</span><b>${usd(c.sacadoUsdt)}</b></div>
        <div title="${escapar(t('orbs.taxasMercadoNota'))}">
          <span>${t('orbs.taxasMercado', { pct: intervaloFaixasOrb(c.taxasMercadoFaixas) })}</span>
          <b>${usd(c.taxasMercadoUsdt ?? 0)}</b>
        </div>
        <div><span>${t('orbs.emCaixa')}</span><b>${usd(c.emCaixaUsdt)}</b></div>
        ${(c.aguardandoRecolhaUsdt ?? 0) > 0.001
          ? `<div><span>${t('orbs.aguardandoRecolha')}</span><b>${usd(c.aguardandoRecolhaUsdt)}</b></div>`
          : ''}
      </div>
      <p class="orbs-nota orbs-taxas-nota">${t('orbs.taxasMercadoExplicacao')}</p>
    </section>`;
}

/** A faixa de saldo, no topo dos dois modais. */
/**
 * A rede. Uma só, e por isso não é escolha do jogador.
 *
 * O seletor com Solana/BSC/Polygon vinha do desenho antigo, quando as três iam existir.
 * Só a Solana está implementada — `chain.mjs` recusa as outras — e um menu que oferece
 * opções que não funcionam é pior que não ter menu: alguém escolhe BSC, manda USDT de lá,
 * e o dinheiro chega numa rede que ninguém está olhando.
 *
 * Quando houver uma segunda rede de verdade, o seletor volta; até lá, é informação.
 */
const REDE_UNICA = 'solana';
const NOME_DA_REDE = 'Solana (SPL)';

/** Uma seção recolhida. O que não é preciso para agir NÃO fica aberto ocupando tela. */
const detalhe = (titulo, conteudo) => `
  <details class="orbs-det">
    <summary>${titulo}</summary>
    <div class="orbs-det-corpo">${conteudo}</div>
  </details>`;

/**
 * Liga dois campos de valor, nos DOIS sentidos.
 *
 * Quem pensa "quero gastar 20 dólares" digita num; quem pensa "quero 5.000 ORBs" digita no
 * outro. A tela antiga só aceitava um lado e obrigava à conta de cabeça no outro.
 *
 * A guarda `mexendo` é o que impede o laço infinito: escrever em B dispara o `input` de B,
 * que recalcularia A, que dispararia o de A…
 */
function ligarCamposDeConversao({ a, b, aParaB, bParaA, casasA = 0, casasB = 0 }) {
  let mexendo = false;
  const arredonda = (v, casas) => (casas ? Number(v).toFixed(casas) : String(Math.floor(v)));

  const liga = (de, para, converte, casas) => {
    de.oninput = () => {
      if (mexendo) return;
      mexendo = true;
      const v = Math.max(0, Number(de.value) || 0);
      para.value = arredonda(converte(v), casas);
      mexendo = false;
    };
  };
  liga(a, b, aParaB, casasB);
  liga(b, a, bParaA, casasA);
}

/**
 * O aviso de RISCO das Gemas — o mesmo nos dois modais (depósito e saque).
 *
 * Três coisas diferentes que o jogador precisa saber ANTES de mexer com dinheiro de verdade,
 * e nenhuma delas é óbvia:
 *
 *   1. troca entre jogadores por valor real é PERMITIDA aqui (o Mercado da Comunidade existe
 *      para isso). Dizer isso evita a dúvida de "estou quebrando alguma regra?";
 *   2. o projeto NÃO arbitra golpe entre jogadores. Combinação por fora, promessa não
 *      cumprida, compra errada — não há como desfazer nem para quem;
 *   3. endereço errado é dinheiro perdido, e isso não é política nossa: é como a blockchain
 *      funciona. Aqui não existe estorno.
 *
 * Fica em `<details>` FECHADO no depósito e ABERTO no saque? Não: aberto nos dois. É texto
 * curto, e esconder aviso de risco atrás de um clique é o mesmo que não ter aviso.
 */
const blocoDoRisco = () => `
  <div class="orbs-aviso orbs-risco">
    <p><b>${t('orbs.riscoTitulo')}</b></p>
    <p>${t('orbs.riscoRmt')}</p>
    <p>${t('orbs.riscoGolpe')}</p>
    <p>${t('orbs.riscoEndereco')}</p>
  </div>`;

/**
 * O alerta de MOEDA x REDE — só na tela de depósito.
 *
 * É o erro mais caro que dá para cometer aqui, e o mais fácil de cometer: "Solana" é ao
 * mesmo tempo o nome da rede que usamos e o nome da moeda que NÃO aceitamos. Quem nunca
 * mexeu com cripto lê "na rede Solana (SPL)" no alto da tela e manda SOL — que chega no
 * endereço certo e fica lá, sem virar Gema, porque o detector só conhece o token USDT.
 *
 * Por isso este bloco é o único da tela que PULSA: o aviso de risco logo abaixo já é
 * vermelho, e um segundo quadrado vermelho parado ao lado dele some no mesmo tom. O pulso
 * é da borda e do brilho, nunca do tamanho — caixa que cresce empurra o formulário inteiro
 * e faz a tela tremer no celular, que é a forma mais rápida de alguém fechar o modal.
 *
 * Fica ACIMA da faixa do tutorial, e não junto do endereço: o texto termina pedindo para
 * assistir ao vídeo, e o vídeo é a próxima coisa na tela.
 */
const blocoDoAlertaSolana = () => `
  <div class="orbs-alerta" role="alert">
    <strong class="orbs-alerta-tit">⚠ ${t('orbs.alertaSolTitulo')} ⚠</strong>
    <p>${t('orbs.alertaSolCorpo')}</p>
    <p>${t('orbs.alertaSolTicket')}</p>
    <p class="orbs-alerta-tuto">${t('orbs.alertaSolTutorial')}</p>
  </div>`;

/**
 * Os vídeos de "como se faz", um por tela.
 *
 * Ficam em constante, e não no dicionário: URL não se traduz, e uma cópia por idioma é uma
 * cópia por idioma para esquecer de atualizar no dia em que o vídeo for regravado.
 */
const TUTORIAL_DEPOSITO = 'https://www.youtube.com/watch?v=YSL-H0lR8Ec';
const TUTORIAL_SAQUE = 'https://www.youtube.com/watch?v=fMQbe0tG-Tc';

/**
 * A faixa do tutorial em vídeo — a primeira coisa do corpo, nas duas telas.
 *
 * ### Por que no topo, e não junto do botão de agir
 *
 * Quem precisa dela ainda não sabe o que fazer, e no celular o formulário sozinho já ocupa a
 * tela inteira: embaixo do botão de sacar ela só seria encontrada por quem já não precisava.
 * Fica acima do formulário, na MESMA posição nas duas telas, para virar um lugar conhecido.
 *
 * ### Por que não compete com o botão roxo
 *
 * Depositar e sacar são as duas ações que mexem com dinheiro de verdade, e o botão roxo é
 * delas. Esta faixa é AJUDA: fundo escuro do vão, contorno discreto, e o vermelho aparece só
 * no selo de play — o bastante para o olho reconhecer "isso é um vídeo" sem disputar o clique
 * com a ação principal.
 *
 * Link, e não `<iframe>`, por dois motivos independentes: a CSP do jogo só permite frame de
 * `'self'` (ver `seguranca.mjs`), e um player embutido carregaria script do YouTube dentro da
 * tela onde o jogador digita o endereço da carteira dele.
 */
function blocoDoTutorial(url, chave) {
  return `
    <a class="orbs-tuto" href="${escapar(url)}" target="_blank" rel="noopener noreferrer">
      <span class="orbs-tuto-play" aria-hidden="true">
        <svg viewBox="0 0 24 17" width="24" height="17">
          <rect x="0.5" y="0.5" width="23" height="16" rx="4" fill="#e02f2f" stroke="#7d1414"/>
          <path d="M9.5 4.6 L16 8.5 L9.5 12.4 Z" fill="#fff"/>
        </svg>
      </span>
      <span class="orbs-tuto-txt">${t(chave)}</span>
      <span class="orbs-tuto-seta" aria-hidden="true">↗</span>
    </a>`;
}

function blocoDoSaldo(o) {
  return `
    <div class="orbs-saldo">
      <span>${t('orbs.saldo')}</span>
      <b>${num(o.saldo)}</b> ${seloGema(18)}
      <em>≈ ${usd(o.saldo * o.precos.saque)}</em>
    </div>`;
}

// ------------------------------------------------------------------ depósito

/**
 * Para onde mandar o dinheiro. Dois modos, e a diferença entre eles é grande.
 *
 * Com `deposito.meu`, o jogador tem um endereço EXCLUSIVO: manda de onde quiser e o
 * servidor sabe que é dele porque foi naquele endereço que caiu. Não há memo, então não há
 * o que errar — que é justamente o problema do outro modo.
 *
 * Sem ele (seed de depósitos não configurada), volta a carteira única e o memo, com o
 * aviso em vermelho: mandar sem o código é a forma mais comum de o dinheiro chegar sem
 * dono, e o texto tem de assustar um pouco.
 */
function blocoDoEndereco(o) {
  if (o.deposito.meu) {
    return `
      <div class="sw-destino">
        <label>${t('orbs.seuEndereco')}
          <div class="sw-copiavel">
            <code id="orbs-end-txt">${escapar(o.deposito.meu)}</code>
            <button class="sw-copiar" id="orbs-copiar">${t('orbs.copiar')}</button>
          </div>
        </label>
        <p class="orbs-nota">${t('orbs.seuEnderecoNota')}</p>
      </div>`;
  }
  if (o.deposito.endereco) {
    return `
      <div class="sw-destino">
        <label>${t('orbs.enderecoDoProjeto')}
          <div class="sw-copiavel">
            <code id="orbs-end-txt">${escapar(o.deposito.endereco)}</code>
            <button class="sw-copiar" id="orbs-copiar">${t('orbs.copiar')}</button>
          </div>
        </label>
        <p class="orbs-aviso">${t('orbs.memo')}: <code>${escapar(o.referencia)}</code> — ${t('orbs.avisoMemo')}</p>
      </div>`;
  }
  return `<p class="orbs-aviso">${t('orbs.semCarteira')}</p>`;
}

function montarDeposito() {
  const host = $('#orbs-corpo');
  const o = estado.orbs;
  if (!host || !o) return;

  host.innerHTML = `
    ${blocoDoSaldo(o)}
    ${blocoDoAlertaSolana()}
    ${blocoDoTutorial(TUTORIAL_DEPOSITO, 'orbs.tutorialDeposito')}

    <div class="sw">
      <div class="sw-caixa">
        <div class="sw-topo"><span>${t('orbs.vocePaga')}</span><em>${t('orbs.naRede', { rede: NOME_DA_REDE })}</em></div>
        <div class="sw-linha">
          <input id="sw-usdt" type="number" min="0" step="1" value="10" inputmode="decimal">
          <span class="sw-moeda usdt">USDT</span>
        </div>
      </div>

      <div class="sw-seta">↓</div>

      <div class="sw-caixa">
        <div class="sw-topo"><span>${t('orbs.voceRecebe')}</span><em>${t('orbs.taxaPorOrb', { preco: o.precos.compra.toFixed(4) })}</em></div>
        <div class="sw-linha">
          <input id="sw-orbs" type="number" min="0" step="100" value="1000" inputmode="numeric">
          <span class="sw-moeda orb">${seloGema(16)} ${t('moeda.gemas')}</span>
        </div>
      </div>
    </div>

    ${blocoDoEndereco(o)}

    ${blocoDoRisco()}

    ${detalhe(t('orbs.extrato'), `<div class="orbs-lista" id="orbs-extrato"></div>`)}
    ${detalhe(t('orbs.carteiraProjeto'), blocoDoCaixa(o.caixa))}`;

  // Os dois campos são LIGADOS, nos dois sentidos: quem pensa "quero gastar 20 dólares"
  // digita em cima, quem pensa "quero 5.000 ORBs" digita embaixo. Obrigar a conta de
  // cabeça num dos lados é o que fazia a tela antiga parecer formulário de banco.
  ligarCamposDeConversao({
    a: $('#sw-usdt'),
    b: $('#sw-orbs'),
    aParaB: (usdt) => Math.floor(usdt / o.precos.compra),
    bParaA: (orbs) => orbs * o.precos.compra,
  });

  const btnCopiar = $('#orbs-copiar');
  if (btnCopiar) {
    btnCopiar.onclick = () => {
      // O endereço PRÓPRIO tem precedência: é o que está desenhado logo acima do botão, e
      // copiar a carteira geral com o endereço exclusivo na tela mandaria o dinheiro para
      // o lugar onde ninguém sabe de quem ele é.
      const alvo = o.deposito.meu ?? o.deposito.endereco;
      navigator.clipboard?.writeText(alvo).then(() => toast(t('orbs.copiado')));
    };
  }

  pintarExtrato(o);
}

// ------------------------------------------------------------------ withdraw

/**
 * A confirmação do saque. Repete o endereço INTEIRO: transferência em blockchain não volta, e o
 * erro mais caro que existe aqui é um endereço colado errado — por isso ele ganha caixa própria,
 * em letra de máquina, em vez de ficar no meio da frase. As Gemas saem (sem cor), o USDT chega.
 */
function confirmarSaqueGemas({ orbs, usdt, endereco, aoConfirmar }) {
  confirmar({
    titulo: t('orbs.saqueConfirmarTitulo', { orbs: num(orbs) }),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteArquivo(ICONE_GEMA, 56), nome: `${num(orbs)} ${escapar(t('moeda.gemas'))}`, classe: 'sai' })}
        ${dlgSeta()}
        ${dlgAtor({
          arte: dlgArteHtml(dlgMedalha({ icone: 'moedas', tom: 'verde' })),
          nome: `${escapar(usd(usdt))} USDT`,
          classe: 'novo',
        })}`, 'azul')}
      ${dlgFrase('', t('orbs.saqueRecebeEm', { usdt: escapar(usd(usdt)) }))}
      <p class="dlg-carteira"><code>${escapar(endereco)}</code></p>
      ${dlgAviso(t('orbs.saqueAviso'))}`,
    aoConfirmar,
  });
}

function montarWithdraw() {
  const host = $('#orbs-corpo');
  const o = estado.orbs;
  if (!host || !o) return;

  host.innerHTML = `
    ${blocoDoSaldo(o)}
    ${blocoDoTutorial(TUTORIAL_SAQUE, 'orbs.tutorialSaque')}

    <div class="orbs-info"><p>${t('orbs.avisoVarredura')}</p></div>

    <div class="sw">
      <div class="sw-caixa">
        <div class="sw-topo">
          <span>${t('orbs.voceSaca')}</span>
          <em><button type="button" class="sw-max" id="sw-max">${t('orbs.tudo')}</button></em>
        </div>
        <div class="sw-linha">
          <input id="sw-orbs" type="number" min="${o.precos.minimo}" step="100" value="${o.precos.minimo}" inputmode="numeric">
          <span class="sw-moeda orb">${seloGema(16)} ${t('moeda.gemas')}</span>
        </div>
      </div>

      <div class="sw-seta">↓</div>

      <div class="sw-caixa">
        <div class="sw-topo"><span>${t('orbs.voceRecebe')}</span><em>${t('orbs.taxaPorOrb', { preco: o.precos.saque.toFixed(4) })}</em></div>
        <div class="sw-linha">
          <input id="sw-usdt" type="number" min="0" step="1" value="${(o.precos.minimo * o.precos.saque).toFixed(2)}" inputmode="decimal">
          <span class="sw-moeda usdt">USDT</span>
        </div>
      </div>
    </div>

    <div class="sw-destino">
      <label>${t('orbs.enderecoDestino', { rede: NOME_DA_REDE })}
        <input id="orbs-endereco" type="text" placeholder="${t('orbs.colePlaceholder')}" autocomplete="off" spellcheck="false">
      </label>
      <p class="sw-erro" id="sw-erro"></p>
    </div>

    <button class="orbs-btn sw-acao" id="orbs-sacar">${t('orbs.pedirSaque')}</button>
    <p class="orbs-aviso sw-aviso">${t('orbs.avisoIrreversivel')}</p>

    ${blocoDoRisco()}

    ${detalhe(t('orbs.meusSaques'), `
      <p class="orbs-nota">${t('orbs.notaReenvio', { min: Math.round(o.precos.reenvioMs / 60000) })}</p>
      <div class="orbs-lista" id="orbs-saques"></div>`)}
    ${detalhe(t('orbs.extrato'), `<div class="orbs-lista" id="orbs-extrato"></div>`)}
    ${detalhe(t('orbs.carteiraProjeto'), blocoDoCaixa(o.caixa))}`;

  const qtd = $('#sw-orbs');
  ligarCamposDeConversao({
    a: qtd,
    b: $('#sw-usdt'),
    aParaB: (orbs) => orbs * o.precos.saque,
    bParaA: (usdt) => Math.floor(usdt / o.precos.saque),
    casasB: 2,
  });

  // "Tudo" existe porque saldo redondo é exceção: quem tem 13.470 ORBs não quer digitar
  // 13.470, quer sacar o que tem.
  $('#sw-max').onclick = () => {
    qtd.value = Math.floor(o.saldo);
    qtd.dispatchEvent(new Event('input'));
  };

  // Valida o endereço EM TEMPO REAL. Saque é irreversível: descobrir que o endereço estava
  // errado depois de clicar não é descobrir, é perder.
  const campoEnd = $('#orbs-endereco');
  const erro = $('#sw-erro');
  const conferir = () => {
    const v = campoEnd.value.trim();
    const ok = !v || /^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(v);
    campoEnd.classList.toggle('ruim', !ok);
    erro.textContent = ok ? '' : t('orbs.enderecoInvalido', { rede: NOME_DA_REDE });
    return ok && !!v;
  };
  campoEnd.oninput = conferir;

  $('#orbs-sacar').onclick = () => {
    const orbs = Math.floor(Number(qtd.value) || 0);
    // A rede não é mais escolha: só a Solana está implementada, e um seletor com opções
    // que não funcionam é um convite a mandar dinheiro para a rede errada.
    const rede = REDE_UNICA;
    const endereco = $('#orbs-endereco').value.trim();
    if (orbs < o.precos.minimo) return toast(t('orbs.saqueMinimo', { min: num(o.precos.minimo) }));
    if (orbs > o.saldo) return toast(t('orbs.saldoInsuficiente'));
    if (!conferir()) return toast(t('orbs.enderecoInvalido', { rede: NOME_DA_REDE }));

    confirmarSaqueGemas({
      orbs,
      usdt: orbs * o.precos.saque,
      endereco,
      aoConfirmar: () => enviar({ t: 'orbs.sacar', orbs, rede, endereco }),
    });
  };

  const hostSaques = $('#orbs-saques');
  hostSaques.innerHTML =
    (o.saques ?? [])
      .map((s) => {
        const podeCancelar = s.status === 'pendente' || s.status === 'falhou' || s.status === 'aguardando_aprovacao';
        const reenvio =
          s.status === 'falhou'
            ? `<em>${t('orbs.reenviarEm', { tempo: faltaPara(s.tentadoEm + o.precos.reenvioMs) })}</em>`
            : '';
        return `
        <div class="orbs-linha saque ${s.status}">
          <span class="orbs-l-tipo">${t('orbs.tipoSaque')}</span>
          <span class="orbs-l-valor">−${num(s.orbs)} ${t('moeda.gemas')} · ${usd(s.usdt)}</span>
          <span class="orbs-l-status">${t(ROTULO_STATUS[s.status] ?? s.status)} ${reenvio}</span>
          ${podeCancelar ? `<button class="orbs-mini" data-cancelar="${escapar(s.id)}">×</button>` : ''}
        </div>`;
      })
      .join('') || `<em class="orbs-nota">${t('orbs.semMovimento')}</em>`;
  hostSaques.onclick = (ev) => {
    const b = ev.target.closest('[data-cancelar]');
    if (b) enviar({ t: 'orbs.cancelar', id: b.dataset.cancelar });
  };

  pintarExtrato(o);
}

/** O extrato do ledger, igual nos dois modais. */
function pintarExtrato(o) {
  const host = $('#orbs-extrato');
  if (!host) return;
  host.innerHTML =
    (o.extrato ?? [])
      .map(
        (l) => `
        <div class="orbs-linha">
          <span class="orbs-l-tipo">${t(ROTULO_MOTIVO[l.motivo] ?? l.motivo)}</span>
          <span class="orbs-l-valor ${l.delta > 0 ? 'up' : 'down'}">${l.delta > 0 ? '+' : ''}${num(l.delta)} ${t('moeda.gemas')}</span>
          <span class="orbs-l-saldo">${num(l.saldo)}</span>
        </div>`,
      )
      .join('') || `<em class="orbs-nota">${t('orbs.semMovimento')}</em>`;
}

// ------------------------------------------------------------------ loja VIP
//
// Três categorias, o catálogo vem no `welcome` e o saldo sai do estado. Toda compra passa
// por uma confirmação com o preço e o saldo depois — diamante é moeda paga, e um clique
// errado que gasta dinheiro de verdade não pode ser desfeito.

/** "2m 30s", "1h 5m", "1d 2h" — duração em ms, texto curto. */
function duracaoCurta(ms) {
  const s = Math.ceil(Math.max(0, ms) / 1000);
  if (s >= 86400) return `${Math.floor(s / 86400)}d ${Math.floor((s % 86400) / 3600)}h`;
  if (s >= 3600) return `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`;
  if (s >= 60) return `${Math.floor(s / 60)}m ${s % 60}s`;
  return `${s}s`;
}

/** "2d 4h", "3h 12m", "45s" — o que sobra de um carimbo, em texto curto. */
function faltaPara(ate) {
  return tempoCurto(Math.max(0, ate - Date.now()));
}

/**
 * O menu lateral da Loja.
 *
 * A arrumação NÃO é a `cat` do catálogo original: lá "mercado" junta pokébola, VIP, troca de
 * nome e bênção numa grade só — onze produtos sem nada em comum, e quem procura o VIP passa
 * por três pacotes de bola antes de achar. O `grupo` que o servidor manda é esta divisão, e é
 * ela que decide o que cada botão mostra.
 *
 * `ico` é o desenho de cada seção: os mesmos ícones que o resto do jogo já usa, para o menu
 * ser reconhecível de relance em vez de uma pilha de palavras.
 */
/** O vestido de concurso — o ícone da seção Cosméticos da Loja e da aba Skins da bolsa. */
const ICONE_COSMETICOS = '/img/itens/cosmeticos-vestido.png';

const GRUPOS_LOJA = [
  { id: '', chave: 'loja.grpTudo', ico: `img:${ICONE_DIAMANTE}` },
  // As Caixas de Fundador abriam o menu durante o beta. A seção só aparece quando o servidor
  // vende alguma — e desde 24/09/2026 ele não vende (ver `CAIXAS_NA_LOJA` no servidor) — e
  // some também quando as 150 acabam (ver `gruposLojaVisiveis`).
  { id: 'caixas', chave: 'loja.grpCaixas', ico: 'img:/img/itens/caixa-fundador.png' },
  // Os PACOTES vêm logo depois das caixas e antes de tudo o mais: é a prateleira em promoção,
  // e promoção que mora no fim do menu é promoção que ninguém encontra.
  { id: 'pacotes', chave: 'loja.grpPacotes', ico: 'img:site/assets/loja/shinysecretlure.png' },
  { id: 'utilitarios', chave: 'loja.grpUtil', ico: 'img:/img/ball-beast.png' },
  { id: 'vip', chave: 'loja.grpVip', ico: 'img:site/assets/loja/vip.png' },
  { id: 'boosts', chave: 'loja.grpBoosts', ico: 'img:site/assets/loja/exp.png' },
  { id: 'personagem', chave: 'loja.grpPersonagem', ico: 'img:site/assets/loja/name.png' },
  // COSMÉTICOS vem logo depois de Personagem, e a vizinhança é o argumento: as duas prateleiras
  // vendem enfeite, e a diferença entre elas é só de ALVO — o treinador ali, o pokémon aqui.
  // Separadas por Outfits, pareceriam dois assuntos sem relação.
  // O ícone é o vestido de concurso do pokesprite (`key-item/contest-costume--dress`), APARADO da
  // moldura transparente: os 32×32 do pokesprite trazem o desenho em 15×20 no meio, e na caixa de
  // 16 px do menu ele saía com metade do tamanho dos vizinhos.
  { id: 'cosmeticos', chave: 'loja.grpCosmeticos', ico: `img:${ICONE_COSMETICOS}` },
  { id: 'outfits', chave: 'loja.grpOutfits', ico: 'img:site/assets/ui/menu-depot.png' },
];

/**
 * Os selos das duas moedas pagas.
 *
 * São PNGs diferentes de propósito. Enquanto as duas dividiam o mesmo orbe azul, o contador de
 * uma era indistinguível do da outra na mesma linha do HUD — e isso importa mais aqui do que
 * em qualquer outro lugar do jogo, porque confundir as duas é confundir "o que eu comprei com
 * PIX" com "o que eu posso sacar em USDT".
 *
 * ATENÇÃO ao escolher o `px`: os dois PNGs são 32×32 com a arte ocupando só 18×15 no meio —
 * quase metade da caixa é transparente. A moeda de OURO preenche o arquivo inteiro, então no
 * mesmo `px` o diamante sai com pouco mais da METADE do tamanho aparente do ouro. Para os dois
 * pesarem igual na tela, o selo daqui pede uma caixa ~1,8× maior que a do ouro.
 */
const seloDiamante = (px = 14) =>
  `<img class="selo-moeda" src="${ICONE_DIAMANTE}" alt="${t('moeda.diamantes')}" style="width:${px}px;height:${px}px">`;

const seloOuro = (px = 14) =>
  `<img class="selo-moeda" src="${srcIcone(ICONE_OURO)}" alt="" style="width:${px}px;height:${px}px">`;

const seloGema = (px = 14) =>
  `<img class="selo-moeda" src="/img/moeda-gema.png" alt="${t('moeda.gemas')}" style="width:${px}px;height:${px}px">`;

/**
 * A seção CAIXAS some do menu quando a Loja não tem caixa para vender.
 *
 * Não é economia de espaço: um botão que abre uma prateleira vazia é uma promessa quebrada.
 * Isso acontece de dois jeitos. O servidor pode não mandar produto de caixa nenhum — é o caso
 * desde que a venda no balcão acabou com o beta. Ou as 150 acabaram, e quem quiser terá de
 * comprar de um jogador, no Mercado da Comunidade. Enquanto o servidor ainda não disse quantas
 * saíram (`vendidas` ausente), uma caixa À VENDA mantém a seção: sumir por falta de dado
 * esconderia o produto justo no primeiro quadro depois do login.
 */
function gruposLojaVisiveis(g) {
  if (g.id !== 'caixas') return true;
  return LISTA_CAIXAS.some((c) => {
    if (!produtoDaCaixa(c.tipo)) return false;
    const restam = restamCaixas(c.tipo);
    return restam == null || restam > 0;
  });
}

function renderLoja() {
  const grupo = estado.grupoLoja ?? '';
  const boost = estado.boostLoja ?? '';

  // O segundo nível só existe dentro de Boosts, e existe porque lá são 35 produtos: cinco
  // tipos × sete durações. Sem ele a seção é uma parede de cartões quase iguais, e a decisão
  // real ("quero XP Boost — por quanto tempo?") pede ver um tipo de cada vez.
  const filtroBoost =
    grupo === 'boosts'
      ? `<div class="cm-fgrupo">${t('loja.tipoDeBoost')}</div>
         <button class="cm-filtro ${boost ? '' : 'on'}" data-boost="">${t('loja.grpTudo')}</button>
         ${estado.tiposBoost
           .map(
             (b) => `<button class="cm-filtro ${boost === b.chave ? 'on' : ''}" data-boost="${b.chave}">
                       <span class="cm-fico" data-ico="img:${b.icone}" data-ico-px="16"></span>${escapar(b.nome)}
                     </button>`,
           )
           .join('')}`
      : '';

  return `
    <div class="loja-topo">
      <!-- Saldo de DIAMANTES e a porta de comprar mais. A Loja não fala de gema: gema é do
           Mercado da Comunidade, e misturar as duas aqui foi justamente o que confundia. -->
      <div class="loja-carteira">
        <div class="loja-saldo">${t('loja.saldo')}: <b id="loja-diamantes">0</b> ${seloDiamante(28)}</div>
        <button class="loja-mini" id="loja-comprar-diamantes">${t('diamantes.comprar')}</button>
      </div>
      <div class="loja-ativos" id="loja-ativos"></div>
    </div>

    <div class="cm-corpo">
      <nav class="cm-filtros loja-filtros">
        <div class="cm-fgrupo">${t('loja.secao')}</div>
        ${GRUPOS_LOJA.filter(gruposLojaVisiveis).map(
          (g) => `<button class="cm-filtro ${g.id === grupo ? 'on' : ''} ${g.id === 'caixas' ? 'cm-filtro-cx' : ''}" data-grupo="${g.id}">
                    <span class="cm-fico" data-ico="${g.ico}" data-ico-px="16"></span>${t(g.chave)}
                  </button>`,
        ).join('')}
        ${filtroBoost}
      </nav>

      <div class="cm-painel loja-painel">
        <div class="loja-cabeca" id="loja-cabeca"></div>
        <div class="loja-grade" id="loja-grade"></div>
      </div>
    </div>`;
}

/** A faixa de "o que está ativo agora": VIP, boosts correndo e a bênção guardada. */
function montarAtivosDaLoja() {
  const host = $('#loja-ativos');
  if (!host) return;
  const l = estado.eu?.loja;
  if (!l) return;

  const selos = [];
  if (l.vip) {
    selos.push(`<span class="loja-selo vip">${vipEhPermanente(l.vipAte)
      ? t('loja.vipPermanente')
      : t('loja.vipAtivo', { tempo: faltaPara(l.vipAte) })}</span>`);
  }
  for (const [chave, ate] of Object.entries(l.boosts ?? {})) {
    if (ate <= Date.now()) continue;
    const nome = estado.lojaProdutos.find((x) => x.id === `boost_${chave}`)?.nome ?? chave;
    // Só o nome do tipo, sem a duração do produto — "XP Boost (1h)" com 4h restantes confunde.
    const curto = nome.replace(/\s*\(.*\)$/, '');
    selos.push(`<span class="loja-selo">${escapar(curto)} · ${t('loja.expiraEm', { tempo: faltaPara(ate) })}</span>`);
  }
  if (l.bless) {
    const nome = estado.lojaProdutos.find((x) => x.id === l.bless)?.nome ?? l.bless;
    selos.push(`<span class="loja-selo bless">${escapar(nome)}</span>`);
  }

  // Sem nada correndo a faixa some inteira: no topo da tela, ao lado do saldo, uma linha
  // dizendo "nenhum bônus ativo agora" só ocupa espaço com uma não-informação.
  host.innerHTML = selos.length
    ? `<h4>${t('loja.ativos')}</h4><div class="loja-selos">${selos.join('')}</div>`
    : '';
}

/**
 * O desconto de uma faixa, como o selo escreve: "10%", "17,5%".
 *
 * Uma casa decimal, e só quando ela existe — a escada da Beast Ball tem 17,5% e 22,5% no meio
 * de inteiros, e escrever "10,0%" ao lado deles só engorda o selo sem dizer nada a mais.
 */
const pctDesconto = (v) => `${Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 1 })}%`;

function montarLoja() {
  const host = $('#loja-grade');
  if (!host) return;
  const grupo = estado.grupoLoja ?? '';
  const boost = estado.boostLoja ?? '';
  const l = estado.eu?.loja ?? {};
  const saldo = estado.eu?.diamonds ?? 0;
  $('#loja-diamantes').textContent = num(saldo);
  montarAtivosDaLoja();

  const lista = estado.lojaProdutos
    .filter((x) => !grupo || x.grupo === grupo)
    .filter((x) => !boost || x.boost === boost)
    // A skin de venda limitada SAI da vitrine quando a venda acaba: depois disso ela só existe no
    // Mercado da Comunidade, e um card que não compra nada é uma promessa quebrada.
    .filter((x) => !x.skin || situacaoSkinNaLoja(x) !== 'encerrada');

  // O cabeçalho diz o que está na tela e quantos são. Numa vitrine com filtro, saber que a
  // lista curta é filtro (e não catálogo vazio) é a diferença entre procurar e desistir.
  //
  // A seção de Boosts já teve aqui a linha "Máx. 5×/dia por tipo · não acumula" — a cota diária
  // saiu em 18/09/2026 e a linha foi junto. O `.loja-regra` que sobra só estica o espaço.
  const nomeGrupo = t(GRUPOS_LOJA.find((g) => g.id === grupo)?.chave ?? 'loja.grpTudo');
  $('#loja-cabeca').innerHTML = `
    <h4>${escapar(nomeGrupo)}</h4>
    <span class="loja-regra"></span>
    <span class="loja-conta">${t('loja.nProdutos', { n: lista.length })}</span>`;

  host.innerHTML = '';
  if (!lista.length) {
    host.innerHTML = `<div class="cm-vazio">${t('loja.nadaAqui')}</div>`;
    return;
  }

  // A faixa do evento de skins abre a prateleira — uma vez, antes do primeiro card de skin.
  const primeiraSkin = lista.find((x) => x.skin && x.vendaSkin);
  let faixaPosta = false;

  for (const prod of lista) {
    // A SKIN tem card próprio: duas artes animadas (comum e shiny) e o relógio da venda limitada.
    if (prod.skin && SKIN_POR_ID.has(prod.skin)) {
      if (!faixaPosta && primeiraSkin) {
        host.appendChild(faixaSkinsDaLoja(primeiraSkin));
        faixaPosta = true;
      }
      host.appendChild(cardSkinDaLoja(prod, saldo));
      continue;
    }
    // A Caixa de Fundador tem card próprio: o que decide a compra dela não é o preço, é o que
    // vem dentro e quantas ainda existem — e nada disso cabe no card comum.
    if (prod.caixaBeta) {
      host.appendChild(cardCaixaDaLoja(prod));
      continue;
    }
    // O pacote também tem card próprio, e pela mesma razão da caixa: o que decide a compra
    // dele não é o preço sozinho, é o preço CONTRA a soma dos avulsos — e essa comparação não
    // cabe numa linha de descrição.
    if (prod.pacote) {
      host.appendChild(cardPacoteDaLoja(prod, saldo));
      continue;
    }

    const card = document.createElement('div');
    card.className = 'loja-card';

    const vipOutfit = !!prod.vipExclusive;
    const betaOutfit = !!prod.betaExclusive;
    const betaFechado = betaOutfit && !l.betaOutfitsAbertas;
    const podeUsar = vipOutfit
      ? !!l.vip
      : prod.looktype != null && (l.ownedOutfits ?? []).includes(prod.looktype);
    const equipada = prod.looktype != null && l.looktype === prod.looktype;
    // Quando o produto tem espera (o Pacote de Suprimentos), o selo mostra quanto falta em
    // vez de deixar o jogador clicar para descobrir.
    const esperaAte = l.comprasCooldown?.[prod.id] ?? 0;
    const emEspera = esperaAte > Date.now();

    // Boost: a DURAÇÃO sai do nome e vira o selo do canto, e a descrição encolhe para só o
    // efeito ("+50% de XP do TREINADOR"). Sete cards do mesmo tipo passam a se distinguir
    // pelo que de fato os distingue — quanto tempo dura e quanto custa.
    const duracao = prod.boost ? /\(([^)]+)\)$/.exec(prod.nome)?.[1] : null;
    const nomeCheio = nomeDoProduto(prod);
    const nome = duracao ? nomeCheio.replace(/\s*\(.*\)$/, '') : nomeCheio;
    // No card de BOOST a descrição encolhe para só o efeito ("+50% de XP do TREINADOR") — a
    // duração já é o selo do canto. Fora dos boosts vale a frase inteira do produto.
    const desc = prod.boost
      ? descricaoDoBoost(tipoDeBoost(prod.boost))
      : textoDaLoja(prod.i18n?.desc, prod.i18n?.params, prod.descricao ?? '');

    const selo = duracao
      ? `<span class="loja-tag duracao">${escapar(duracao)}</span>`
      : prod.limiteDias
        ? `<span class="loja-tag ${emEspera ? 'espera' : ''}">${
            emEspera ? t('loja.liberaEm', { tempo: faltaPara(esperaAte) }) : t('loja.porSemana')
          }</span>`
        // Pacote em escada (a Beast Ball): o selo é quanto a faixa abate contra a MENOR. É a
        // única coisa que distingue sete cards do mesmo desenho, e é o que responde a pergunta
        // que o jogador faz na frente deles — "compensa levar o maior?".
        : prod.desconto > 0
          ? `<span class="loja-tag off">−${pctDesconto(prod.desconto)}</span>`
          : '';

    card.innerHTML = `
      <div class="loja-arte"></div>
      ${selo}
      <div class="loja-nome">${escapar(nome)}</div>
      <div class="loja-desc">${escapar(desc)}</div>
      <button class="loja-btn"></button>`;

    // Outfit desenha o boneco animado; o resto usa o ícone espelhado do produto.
    const arte = card.querySelector('.loja-arte');
    if (prod.looktype != null) arte.appendChild(spriteAnimado(prod.looktype, 48));
    else arte.appendChild(iconeArquivo(prod.icone ?? 'site/assets/loja/diamond.png', 40));

    const preco = `${num(prod.preco)} ${seloDiamante(22)}`;
    const btn = card.querySelector('.loja-btn');
    if (vipOutfit && !l.vip) {
      btn.textContent = t('loja.requerVip');
      btn.onclick = () => convidarParaOVip();
    } else if (betaFechado && !podeUsar) {
      btn.textContent = t('loja.indisponivel');
      btn.disabled = true;
    } else if (podeUsar && prod.looktype != null) {
      if (equipada) {
        btn.textContent = t('loja.desequipar');
        const padrao = LOOK_DO_GENERO[l.gender ?? 'male'] ?? 159;
        btn.onclick = () => enviar({ t: 'loja.equipar', looktype: padrao });
      } else {
        btn.textContent = t('loja.equipar');
        btn.onclick = () => enviar({ t: 'loja.equipar', looktype: prod.looktype });
      }
    } else if (saldo < prod.preco) {
      // Sem saldo o botão vira ATALHO para comprar diamante, em vez de ficar morto: quem
      // chegou aqui já escolheu o produto, e desabilitar o botão obriga a procurar sozinho
      // onde se recarrega.
      btn.innerHTML = preco;
      btn.classList.add('sem-saldo');
      btn.title = t('loja.semDiamantes');
      btn.onclick = () => abrirCompraDeDiamantes(prod.preco - saldo);
    } else if (betaOutfit && prod.preco === 0) {
      btn.textContent = t('loja.resgatar');
      btn.onclick = () => confirmarCompra(prod, saldo);
    } else {
      btn.innerHTML = preco;
      btn.onclick = () => confirmarCompra(prod, saldo);
    }
    // A CHOCADEIRA mostra quantas a conta já tem, e para de vender na sexta — o servidor recusa a
    // sétima antes do débito, e um botão que só produz recusa não deveria existir.
    if (prod.id === 'chocadeira') {
      const total = chocadeiraDe(estado.eu).total;
      if (!selo) card.insertAdjacentHTML('afterbegin', `<span class="loja-tag">${num(total)}/${CHOCADEIRAS_MAX}</span>`);
      if (total >= CHOCADEIRAS_MAX) {
        btn.textContent = t('chocadeira.maximo');
        btn.disabled = true;
        btn.onclick = null;
        btn.classList.remove('sem-saldo');
      }
    }
    // O ABSORB BULB aquece UM OVO que já esteja chocando, e é na Chocadeira que se escolhe qual.
    // Comprar pela vitrine, sem espaço, só produziria a recusa do servidor — então aqui o botão
    // LEVA à aba em vez de cobrar, e o selo diz quantos ovos ainda podem ser aquecidos.
    if (prod.id === 'bulbo') {
      const est = chocadeiraDe(estado.eu);
      const frios = est.ovos.filter((o) => o.luz !== true).length;
      if (!selo && frios) {
        card.insertAdjacentHTML('afterbegin', `<span class="loja-tag">${num(frios)}</span>`);
      }
      btn.textContent = frios ? t('chocadeira.luzEscolher') : t('chocadeira.luzSemOvoCurto');
      btn.disabled = false;
      btn.classList.remove('sem-saldo');
      btn.onclick = () => {
        estado.abaBolsa = 'chocadeira';
        abrirModal('bolsa');
      };
    }
    host.appendChild(card);
  }
}

/**
 * O "tem certeza?" da Loja: o produto no palco dourado, a etiqueta de diamantes com o saldo que
 * fica, e a descrição curta do card. O título vai por `textContent`, então o nome entra cru.
 */
function confirmarCompra(prod, saldo) {
  const arte = prod.looktype != null
    ? dlgArteLt(prod.looktype, 64)
    : dlgArteArquivo(prod.icone ?? 'site/assets/loja/diamond.png', 56);
  const desc = prod.boost
    ? descricaoDoBoost(tipoDeBoost(prod.boost))
    : textoDaLoja(prod.i18n?.desc, prod.i18n?.params, prod.descricao ?? '');
  const corpo = (extra = '') => `
    ${dlgPalco(dlgAtor({ arte, nome: escapar(nomeDoProduto(prod)), classe: 'novo' }), 'ouro')}
    ${extra}
    ${prod.preco > 0 ? dlgCusto({ moeda: 'diamante', valor: prod.preco, saldo }) : ''}
    ${desc ? dlgFrase('', escapar(desc)) : ''}`;
  // "Troca de Nome" precisa do nome ANTES de cobrar: pedir depois deixaria o jogador com um
  // diamante gasto e um prompt cancelado.
  if (prod.pedeTexto) {
    const nome = window.prompt(`${t('loja.trocarNome')}\n${t('loja.trocarNomeAviso')}`, estado.eu?.nick ?? '');
    if (!nome) return;
    if (!/^[a-zA-Z0-9_]{3,16}$/.test(nome.trim())) return toast(t('loja.trocarNomeAviso'));
    return confirmar({
      titulo: t('loja.confirmarTitulo', { nome: nomeDoProduto(prod) }),
      texto: corpo(dlgReqs(dlgReq({
        arte: dlgIcone('pessoa', 22),
        nome: escapar(nome.trim()),
        sub: escapar(t('loja.novoNome')),
      }))),
      aoConfirmar: () => enviar({ t: 'loja.comprar', id: prod.id, nome: nome.trim() }),
    });
  }
  confirmar({
    titulo: t('loja.confirmarTitulo', { nome: nomeDoProduto(prod) }),
    texto: corpo(),
    aoConfirmar: () => enviar({ t: 'loja.comprar', id: prod.id }),
  });
}

// ------------------------------------------------------- Caixas de Fundador
//
// Três telas usam as mesmas peças, e por isso elas moram juntas aqui:
//
//   · o CARD da Loja (vitrine) — o baú, o que vem dentro e o contador de restantes;
//   · o DIÁLOGO da Loja — abre ao clicar no card, mostra o mesmo conteúdo em tamanho grande
//     e é ele que compra (ou mostra a contagem regressiva, antes do lançamento);
//   · o DIÁLOGO de ABRIR — o da bolsa, com o aviso de que não tem volta.
//
// Os três se apoiam no diálogo de confirmação que já existe (`#confirmar`). Ganhar a caixa de
// madeira, o botão roxo, o Esc, o clique no fundo e a folha que sobe do rodapé no celular sai
// de graça — e é o mesmo lugar de onde toda decisão irreversível do jogo já é tomada.

const caixasDoEstado = () => estado.eu?.caixas ?? null;

/** O produto da Loja de um tipo de caixa (`fundador` | `cofundador`). */
const produtoDaCaixa = (tipo) => estado.lojaProdutos.find((x) => x.caixaBeta === tipo) ?? null;

/**
 * A tag que ele tem deste tipo — a de série MENOR, que é a que o servidor exibe.
 *
 * `null` se ele não abriu nenhuma caixa deste tipo. Espelha `tagDoLooktype` do servidor, e é
 * usado só para DESENHAR: quem carimba a mensagem do chat é o gateway.
 */
function tagDaCaixaDoJogador(tipo) {
  const doTipo = (caixasDoEstado()?.tags ?? []).filter((x) => x.tipo === tipo);
  if (!doTipo.length) return null;
  return doTipo.reduce((a, b) => (Number(b.serie) < Number(a.serie) ? b : a));
}

/** Ele já comprou este tipo NO BALCÃO? (No Mercado da Comunidade não há teto.) */
function jaComprouCaixa(tipo) {
  const c = caixasDoEstado();
  if (!c) return false;
  return (c.compradas?.[tipo] ?? 0) >= (c.porJogador ?? 1);
}

/** Quantas ainda restam deste tipo — `null` enquanto o servidor não disse. */
function restamCaixas(tipo) {
  const c = caixasDoEstado();
  const prod = produtoDaCaixa(tipo);
  if (!c || !prod?.limiteCaixa) return null;
  return Math.max(0, prod.limiteCaixa - (c.vendidas?.[tipo] ?? 0));
}

/**
 * O relógio do SERVIDOR, corrigido pelo desvio do último snapshot.
 *
 * A contagem até o lançamento é longa (dias), mas quem está com o relógio do PC adiantado em
 * uma hora veria o botão liberar uma hora antes — e levaria um "ainda não abriu" do servidor
 * ao clicar. O campo já vem em todo estado (`servidorAgora`); aqui é só reaproveitá-lo.
 */
const agoraDoServidor = () => Date.now() - (estado.desvioServidor ?? 0);

/** "6d 12h", "3h 12m", "45s" — o mesmo formato curto do resto da Loja. */
const faltaParaServidor = (ate) => faltaPara(ate + (estado.desvioServidor ?? 0));

const caixaAbertaParaVenda = () =>
  !!caixasDoEstado()?.aberta || agoraDoServidor() >= (caixasDoEstado()?.abremEm ?? Infinity);

/** "#01" / "#001" — a série com os zeros que o tipo pede (2 dígitos no Fundador, 3 no Co). */
const serieDaCaixa = (tipo, serie) => rotuloSerieCaixa(tipo, serie);

/** A etiqueta colorida da tag — `[#01]` / `[#007]` — como ela aparece na lista do que vem dentro. */
function tagDaCaixaHtml(tipo, serie) {
  const def = CAIXAS_BETA[tipo];
  if (!def) return '';
  return `<span class="cx-tag" style="--cx-cor:${def.cor}">[${escapar(serieDaCaixa(tipo, serie))}]</span>`;
}

/**
 * A lista do que vem dentro — as três linhas que o jogador precisa ler antes de decidir.
 *
 * O sprite da outfit é montado depois (é um canvas animado, e template de string não carrega
 * nó do DOM); aqui fica o buraco marcado com `data-cx-look`.
 */
function conteudoDaCaixaHtml(tipo, { serie = null } = {}) {
  const def = CAIXAS_BETA[tipo];
  if (!def) return '';
  const tag = serie == null
    ? `<span class="cx-tag" style="--cx-cor:${def.cor}">[#${'0'.repeat(def.digitos)}]</span>`
    : tagDaCaixaHtml(tipo, serie);

  return `
    <ul class="cx-conteudo">
      <li>
        <span class="cx-ci" data-cx-look="${def.looktype}"></span>
        <b>${escapar(t(`caixas.outfit.${tipo}`))}</b>
        <i>${escapar(t('caixas.outfitAjuda'))}</i>
      </li>
      <li>
        <span class="cx-ci cx-ci-tag" style="--cx-cor:${def.cor}"></span>
        <b>${tag}</b>
        <i>${escapar(t('caixas.tagAjuda'))}</i>
      </li>
      <li>
        <span class="cx-ci"><img src="${ICONE_DIAMANTE}" alt="" width="26" height="26"></span>
        <b>${num(def.diamantes)} ${escapar(t('moeda.diamantes'))}</b>
        <i>${escapar(t('caixas.diamantesAjuda'))}</i>
      </li>
    </ul>`;
}

/** Preenche os `data-cx-look` com o boneco animado da outfit. */
function pintarConteudoDaCaixa(raiz) {
  for (const el of raiz.querySelectorAll('[data-cx-look]')) {
    el.replaceChildren(spriteAnimado(Number(el.dataset.cxLook), 34));
  }
}

/**
 * O diálogo grande da caixa — o mesmo para "quero comprar" e para "quero abrir".
 *
 * `modo`:
 *   `loja`  vitrine. Compra se a venda já abriu; senão o botão vira a contagem regressiva.
 *   `abrir` bolsa. Pede a confirmação do aviso de que nada mais é transferível.
 *
 * A CONTAGEM é redesenhada de segundo em segundo enquanto o diálogo estiver aberto, e o
 * intervalo morre junto com ele (`hidden` no `#confirmar`). Sem isso a tela mostraria "faltam
 * 3 dias" parado — e no minuto da virada o jogador teria de recarregar para poder comprar.
 */
function abrirDialogoCaixa(tipo, { modo = 'loja', caixaId = null, serie = null } = {}) {
  const def = CAIXAS_BETA[tipo];
  if (!def) return;
  const prod = produtoDaCaixa(tipo);
  const preco = prod?.preco ?? def.preco;
  const saldo = estado.eu?.diamonds ?? 0;
  const restam = restamCaixas(tipo);
  const abrindo = modo === 'abrir';

  const titulo = abrindo
    ? t('caixas.abrirTitulo', { nome: t(`caixas.nome.${tipo}`), serie: serieDaCaixa(tipo, serie) })
    : t(`caixas.nome.${tipo}`);

  const estoque = restam == null || abrindo
    ? ''
    : `<p class="cx-estoque ${restam === 0 ? 'esgotada' : ''}">
         ${escapar(restam === 0
           ? t('caixas.esgotadaSelo')
           : t('caixas.restam', { n: num(restam), total: num(def.limiteCaixa ?? def.limite) }))}
       </p>`;

  const rodape = abrindo
    ? `<p class="cx-aviso">${escapar(t('caixas.avisoAbrir'))}</p>`
    // Fora da abertura, a nota diz as DUAS regras que mudam a decisão: a caixa é revendável
    // fechada, e o balcão só vende uma por conta.
    : `<p class="cx-nota">${escapar(t('caixas.umaPorJogador'))}</p>`
      + `<p class="cx-nota">${escapar(t('caixas.notaMercado'))}</p>`;

  confirmar({
    titulo,
    largura: 'larga',
    texto: `
      <div class="cx-dialogo" style="--cx-cor:${def.cor}">
        <div class="cx-arte">
          <img src="/img/itens/caixa-${tipo}.png" alt="" width="128" height="128">
          ${serie == null ? '' : `<span class="cx-serie">${escapar(serieDaCaixa(tipo, serie))}</span>`}
        </div>
        <div class="cx-corpo">
          <p class="cx-lead">${escapar(t('caixas.vemDentro'))}</p>
          ${conteudoDaCaixaHtml(tipo, { serie })}
          ${estoque}
          ${rodape}
        </div>
      </div>`,
    rotuloSim: abrindo ? t('caixas.abrir') : `${num(preco)} 💎`,
    aoConfirmar: () => {
      if (abrindo) return enviar({ t: 'caixa.abrir', id: caixaId });
      if (saldo < preco) return abrirCompraDeDiamantes(preco - saldo);
      enviar({ t: 'loja.comprar', id: def.produtoId });
    },
  });

  const corpo = $('#confirmar-texto');
  if (corpo) pintarConteudoDaCaixa(corpo);

  const bt = $('#confirmar-sim');
  if (!bt) return;
  bt.classList.add('cx-btn');
  // O botão de confirmar mora FORA do `.cx-dialogo` (é do diálogo, não do conteúdo), então a
  // cor da caixa não chega nele por herança — tem de ser escrita aqui. É o que faz a contagem
  // regressiva sair verde no Fundador e roxa no CoFundador.
  bt.style.setProperty('--cx-cor', def.cor);

  if (abrindo) return;

  // "Já comprada" vem ANTES de "esgotada": para quem já tem a sua, o que a Loja não vende é a
  // SEGUNDA — e dizer "esgotou" nesse caso mandaria a pessoa procurar no Mercado por uma coisa
  // que ela pode não querer.
  if (jaComprouCaixa(tipo)) {
    bt.disabled = true;
    bt.textContent = t('caixas.jaComprouSelo');
    return;
  }
  if (restam === 0) {
    bt.disabled = true;
    bt.textContent = t('caixas.esgotadaSelo');
    return;
  }
  // Sem saldo o botão vira ATALHO para comprar diamante em vez de morrer — a mesma decisão
  // já tomada no card comum da Loja (ver `montarLoja`).
  if (caixaAbertaParaVenda()) {
    if (saldo < preco) {
      bt.classList.add('sem-saldo');
      bt.innerHTML = `${num(preco)} ${seloDiamante(20)}`;
    } else {
      bt.innerHTML = `${escapar(t('caixas.comprar'))} · ${num(preco)} ${seloDiamante(20)}`;
    }
    return;
  }

  // Antes do lançamento: o botão É a contagem, e não compra nada.
  const abremEm = caixasDoEstado()?.abremEm ?? 0;
  bt.disabled = true;
  bt.classList.add('cx-espera');
  const tique = () => {
    if ($('#confirmar').classList.contains('hidden')) return clearInterval(timer);
    if (caixaAbertaParaVenda()) {
      clearInterval(timer);
      // Virou a hora com o diálogo aberto: repinta em vez de deixar o botão morto.
      return abrirDialogoCaixa(tipo, { modo, caixaId, serie });
    }
    bt.textContent = t('caixas.abreEm', { tempo: faltaParaServidor(abremEm) });
  };
  const timer = setInterval(tique, 1000);
  tique();
}

/**
 * A tela de "você recebeu", depois de abrir.
 *
 * Um toast não serve aqui por duas razões. A primeira é que são TRÊS prêmios de uma vez, e um
 * deles (a tag) não aparece em lugar nenhum da interface até a pessoa falar no chat — sem esta
 * tela, ela não saberia que ganhou. A segunda é que a ação é irreversível: o fecho de um
 * caminho sem volta merece uma confirmação de que deu certo, e não um aviso que some em 2,6 s.
 *
 * Caixa de um botão só (`soOk`): não há "não" possível — a caixa já foi aberta.
 */
function mostrarCaixaAberta(e) {
  const def = CAIXAS_BETA[e.tipo];
  if (!def) return toast(t('caixas.abertaSimples'));

  confirmar({
    titulo: t('caixas.abertaTitulo'),
    largura: 'larga',
    soOk: true,
    rotuloSim: t('caixas.abertaOk'),
    texto: `
      <div class="cx-dialogo cx-premio" style="--cx-cor:${def.cor}">
        <div class="cx-arte">
          <span class="cx-boneco" data-cx-retrato="${def.looktype}"></span>
          <span class="cx-serie" style="--cx-cor:${def.cor}">${escapar(serieDaCaixa(e.tipo, e.serie))}</span>
        </div>
        <div class="cx-corpo">
          <p class="cx-lead">${escapar(t('caixas.recebeu', {
            nome: t(`caixas.nome.${e.tipo}`), serie: serieDaCaixa(e.tipo, e.serie),
          }))}</p>
          ${conteudoDaCaixaHtml(e.tipo, { serie: e.serie })}
          <p class="cx-nota">${escapar(t('caixas.ondeAchar'))}</p>
        </div>
      </div>`,
    aoConfirmar: () => {},
  });

  const corpo = $('#confirmar-texto');
  if (corpo) {
    // O boneco do prêmio vem GRANDE (96 px) e vestido com as cores do jogador: é o retrato do
    // que ele acabou de ganhar, não um ícone de lista. Atributo próprio (`data-cx-retrato`)
    // para `pintarConteudoDaCaixa` não o rebaixar aos 34 px da lista.
    for (const el of corpo.querySelectorAll('[data-cx-retrato]')) {
      el.replaceChildren(spriteAnimado(Number(el.dataset.cxRetrato), 96, 3, null,
        empacotarVisual(estado.eu?.loja?.visual)));
    }
    pintarConteudoDaCaixa(corpo);
  }
}

/** O card da vitrine. Difere do card comum por ser CLICÁVEL inteiro e por mostrar o conteúdo. */
/**
 * O card de um PACOTE de boosts — o único card da Loja que mostra dois preços.
 *
 * ### Por que o preço riscado é o centro do card, e não o selo de canto
 *
 * Todo o resto da Loja vende UMA coisa e o card só precisa dizer quanto custa. O pacote vende
 * uma COMPARAÇÃO: os mesmos boosts saem por 116 avulsos e por 100 aqui. Enfiar isso numa linha
 * de descrição ("Avulsos sairiam por 116 💎") é escrever o argumento no lugar em que ninguém
 * lê — a descrição é o parágrafo que o olho pula. Então o "de 116" vai riscado colado ao "por
 * 100", que é a fôrma que qualquer vitrine usa e que se entende sem ler palavra nenhuma.
 *
 * ### As duas comparações do kit de 7 dias
 *
 * O de uma semana desconta em dois eixos (juntar os boosts, e o 7d de cada boost já ser mais
 * barato que 24h×7), e o número grande — 26% — só aparece na comparação com sete noites
 * soltas. Ele entra como uma FAIXA à parte, embaixo do preço, e não trocando o "de 700": os
 * dois querem dizer coisas diferentes e alternar entre eles conforme o produto faria o jogador
 * comparar maçã com laranja entre um card e o vizinho.
 *
 * Nenhum dos números é calculado aqui: `prod.pacote` vem pronto do servidor, que é o dono da
 * tabela de preços dos boosts. Ver `montarCatalogo` em `server/game/loja.mjs`.
 */
function cardPacoteDaLoja(prod, saldo) {
  const pk = prod.pacote;
  const destaque = pk.economiaSemanaPct != null;

  const card = document.createElement('div');
  card.className = `loja-card pac-card${destaque ? ' pac-destaque' : ''}`;
  card.innerHTML = `
    <span class="loja-tag pac-selo">${t('loja.pacoteOff', { pct: pk.economiaPct })}</span>
    <div class="loja-arte pac-arte"></div>
    <div class="loja-nome">${escapar(nomeDoProduto(prod))}</div>
    <div class="pac-itens"></div>
    <div class="pac-precos">
      <s class="pac-antes">${num(pk.avulso)} ${seloDiamante(16)}</s>
      <b class="pac-agora">${num(prod.preco)} ${seloDiamante(22)}</b>
    </div>
    <div class="pac-economia">${t('loja.pacoteEconomia', { n: num(pk.economia) })}</div>
    ${destaque
      ? `<div class="pac-semana">${t('loja.pacoteSemana', {
          pct: pk.economiaSemanaPct, n: num(pk.economiaSemana),
        })}</div>`
      : ''}
    <button class="loja-btn pac-btn" type="button"></button>`;

  card.querySelector('.pac-arte').appendChild(
    iconeArquivo(prod.icone ?? 'site/assets/loja/diamond.png', 40),
  );

  // A lista do que vem dentro, com o ícone de cada boost: é o que separa "Pacote Farmer" de
  // "Pacote Shiny Hunter" para quem nunca leu o nome deles antes.
  //
  // O BRINDE (hoje só a Exp. Share do kit de uma semana) é mais uma linha desta lista, com o
  // selo "brinde" no lugar do prazo. Uma seção própria para um item só empurraria o preço para
  // baixo da dobra do card — e o que o jogador precisa ver é que ele vem junto, não onde mora.
  const itens = card.querySelector('.pac-itens');
  for (const it of pk.itens ?? []) {
    const li = document.createElement('div');
    li.className = `pac-item${it.brinde ? ' pac-item-brinde' : ''}`;
    li.appendChild(iconeArquivo(it.icone, 18));
    li.insertAdjacentHTML(
      'beforeend',
      // A quantidade só existe no brinde (os boosts se medem em prazo, não em unidade), e vem
      // colada no nome porque "1x Exp. Share" é UM rótulo de produto, não dois campos.
      `<span class="pac-item-nome">${it.qtd ? `${num(it.qtd)}x ` : ''}${escapar(it.nome)}</span>`
      + (it.brinde ? `<em class="pac-brinde-selo">${escapar(t('loja.pacoteBrinde'))}</em>` : ''),
    );
    li.title = textoDaLoja(it.descChave, null, it.descricao ?? '');
    itens.appendChild(li);
  }

  const bt = card.querySelector('.loja-btn');
  if (saldo < prod.preco) {
    // Mesma saída do card comum: sem saldo o botão vira o atalho de comprar diamante, em vez
    // de morrer e mandar o jogador procurar sozinho onde se recarrega.
    bt.innerHTML = `${num(prod.preco)} ${seloDiamante(22)}`;
    bt.classList.add('sem-saldo');
    bt.title = t('loja.semDiamantes');
    bt.onclick = () => abrirCompraDeDiamantes(prod.preco - saldo);
  } else {
    bt.innerHTML = `${num(prod.preco)} ${seloDiamante(22)}`;
    bt.onclick = () => confirmarCompra(prod, saldo);
  }
  return card;
}

function cardCaixaDaLoja(prod) {
  const tipo = prod.caixaBeta;
  const def = CAIXAS_BETA[tipo];
  const restam = restamCaixas(tipo);
  const abremEm = caixasDoEstado()?.abremEm ?? 0;
  const aberta = caixaAbertaParaVenda();
  const jaComprou = jaComprouCaixa(tipo);
  // A minha, quando já comprei: o card deixa de ser oferta e passa a ser recibo. Se ela já foi
  // aberta a série vem da tag; se ainda está fechada, da bolsa.
  const minha = jaComprou
    ? (caixasDoEstado()?.minhas ?? []).find((c) => c.tipo === tipo) ?? tagDaCaixaDoJogador(tipo)
    : null;

  // Com a caixa já comprada a lista deixa de falar em "#00" e mostra o número DELE: o card
  // virou recibo, e o número é a única linha que muda de dono para dono.
  const card = document.createElement('div');
  card.className = `loja-card cx-card ${jaComprou ? 'cx-minha' : ''}`;
  card.style.setProperty('--cx-cor', def.cor);
  card.innerHTML = `
    <span class="loja-tag cx-selo">${escapar(jaComprou && minha
      ? serieDaCaixa(tipo, minha.serie)
      : t('caixas.selo'))}</span>
    <div class="loja-arte cx-arte-card">
      <img src="/img/itens/caixa-${tipo}.png" alt="" width="88" height="88">
    </div>
    <div class="loja-nome">${escapar(t(`caixas.nome.${tipo}`))}</div>
    ${conteudoDaCaixaHtml(tipo, { serie: minha?.serie ?? null })}
    <div class="cx-estoque ${restam === 0 && !jaComprou ? 'esgotada' : ''}">${
      restam == null
        ? ''
        : escapar(restam === 0 && !jaComprou
          ? t('caixas.esgotadaSelo')
          : t('caixas.restam', { n: num(restam), total: num(def.limite) }))
    }</div>
    <div class="cx-limite">${escapar(t('caixas.umaPorJogador'))}</div>
    <button class="loja-btn cx-btn" type="button"></button>`;

  pintarConteudoDaCaixa(card);

  const bt = card.querySelector('.loja-btn');
  const pintarBotao = () => {
    // A ordem importa: quem já tem a sua não deve ler "Esgotada" (o que faltou para ele não é
    // estoque, é permissão), nem uma contagem regressiva para uma compra que não vai fazer.
    if (jaComprou) {
      bt.disabled = true;
      bt.textContent = t('caixas.jaComprouSelo');
    } else if (restam === 0) {
      bt.disabled = true;
      bt.textContent = t('caixas.esgotadaSelo');
    } else if (aberta) {
      bt.innerHTML = `${num(prod.preco)} ${seloDiamante(22)}`;
    } else {
      bt.classList.add('cx-espera');
      bt.textContent = t('caixas.abreEm', { tempo: faltaParaServidor(abremEm) });
    }
  };
  pintarBotao();

  // A contagem do CARD anda enquanto a Loja estiver aberta. Diferente da do diálogo, ela pode
  // ser lenta (de 30 em 30 s): num card, o segundo não é informação — o dia e a hora são.
  if (!aberta && restam !== 0 && !jaComprou) {
    const timer = setInterval(() => {
      if (!card.isConnected) return clearInterval(timer);
      if (caixaAbertaParaVenda()) {
        clearInterval(timer);
        return montarLoja();
      }
      bt.textContent = t('caixas.abreEm', { tempo: faltaParaServidor(abremEm) });
    }, 30_000);
  }

  // O card INTEIRO abre o diálogo — antes do lançamento é a única coisa que dá para fazer com
  // ele, e depois continua sendo o caminho certo: ninguém deve gastar 150 diamantes num
  // clique de vitrine sem ver o que está levando.
  const abrir = () => abrirDialogoCaixa(tipo, { modo: 'loja' });
  card.tabIndex = 0;
  card.onclick = abrir;
  card.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      abrir();
    }
  };
  return card;
}

// ---------------------------------------------------- comprar diamantes (R$)
//
// O cartão leva o jogador para FORA da aba (checkout hospedado do Stripe); o PIX fica DENTRO —
// a Efí não hospeda página nenhuma, então o QR code e o "copia e cola" são desenhados aqui
// mesmo. Nos dois casos o crédito volta por webhook, e por isso não há "confirmar pagamento"
// nesta tela — o servidor credita sozinho, e a tela só precisa avisar que está esperando.
//
// A vitrine (`/diamantes/precos`) é buscada uma vez e guardada: preço não muda no meio da
// sessão, e refazer o pedido a cada abertura piscaria a tela sem trocar um número.

/** Quantos diamantes faltam para o produto que o jogador tentou comprar, se veio de lá. */
let faltamDiamantes = 0;

const reais = (centavos) => `R$ ${(centavos / 100).toFixed(2).replace('.', ',')}`;

async function abrirCompraDeDiamantes(faltam = 0) {
  faltamDiamantes = faltam;
  if (!estado.diamantesPrecos) {
    try {
      estado.diamantesPrecos = await fetch('/diamantes/precos').then((r) => r.json());
    } catch {
      return toast(t('diamantes.indisponivel'));
    }
  }
  if (!estado.diamantesPrecos.ativo) return toast(t('diamantes.indisponivel'));
  abrirModal('diamantes');
}

function renderCompraDiamantes() {
  const p = estado.diamantesPrecos;
  if (!p?.ativo) return `<p class="orbs-nota">${t('diamantes.indisponivel')}</p>`;

  // O pacote sugerido é o menor que COBRE o que faltou. Quem clicou num produto sem saldo
  // quer sair daqui podendo comprar aquele produto, não escolher entre cinco números.
  const sugerido = faltamDiamantes
    ? p.pacotes.find((x) => x.qtd >= faltamDiamantes) ?? p.pacotes[p.pacotes.length - 1]
    : null;

  const cards = p.pacotes.map((x) => `
    <button class="dia-card ${sugerido && x.qtd === sugerido.qtd ? 'sugerido' : ''}" data-qtd="${x.qtd}">
      ${seloDiamante(28)}
      <b>${num(x.qtd)}</b>
      <span>${reais(x.centavos)}</span>
      ${x.desconto ? `<em class="dia-off">−${x.desconto}%</em>` : ''}
    </button>`).join('');

  // `orbs-corpo` traz as caixas do painel de gemas (mesma natureza de tela: dinheiro de
  // verdade entrando). `dia-corpo` é o que devolve ao número a cor do DIAMANTE — sem ela o
  // saldo saía no rosa da gema, que é justamente a confusão que os dois ícones existem para
  // evitar.
  return `
    <div class="orbs-corpo dia-corpo">
      ${faltamDiamantes ? `<p class="orbs-aviso">${t('diamantes.faltam', { qtd: num(faltamDiamantes) })}</p>` : ''}

      <div class="orbs-saldo">
        <span>${t('loja.saldo')}</span>
        <b>${num(estado.eu?.diamonds ?? 0)}</b> ${seloDiamante(18)}
      </div>

      <div class="orbs-secao">
        <h4>${t('diamantes.escolhaPacote')}</h4>
        <div class="dia-pacotes" id="dia-pacotes">${cards}</div>

        <div class="orbs-campo">
          <span>${t('diamantes.outraQtd')}</span>
          <input id="dia-qtd" type="number" min="${p.qtdMinima}" max="${p.qtdMaxima}"
                 step="10" value="${sugerido?.qtd ?? p.qtdMinima}" inputmode="numeric">
        </div>
        <!-- O recibo da troca: o que sai (R$) → o que entra (💎), com a seta do diálogo de jogo.
             Os números são do cliente só para MOSTRAR; quem cobra refaz a conta no servidor. -->
        <div class="dia-recibo">
          <span class="dia-recibo-lado">
            <small>${t('diamantes.vocePaga')}</small>
            <b id="dia-total">—</b>
          </span>
          <span class="dlg-seta-divisas" aria-hidden="true"><i></i><i></i><i></i></span>
          <span class="dia-recibo-lado recebe">
            <small>${t('diamantes.voceRecebe')}</small>
            <b>${seloDiamante(22)}<span id="dia-recibo-qtd">—</span></b>
          </span>
        </div>

        <!-- CPF do tomador da nota fiscal — SÓ no PIX. No cartão o pagador costuma ser
             estrangeiro (sem CPF) e o nome/endereço vêm do Stripe; exigir CPF trancaria essas
             compras. O bloco nasce escondido quando há cartão disponível e aparece no primeiro
             clique em "Pagar com PIX" (ver ligarCompraDiamantes); com PIX como única opção já
             nasce visível. -->
        <div id="dia-cpf-bloco"${p.cartaoAtivo ? ' hidden' : ''}>
          <div class="orbs-campo">
            <span>${t('diamantes.cpf')}</span>
            <input id="dia-cpf" type="text" inputmode="numeric" autocomplete="off"
                   maxlength="14" placeholder="000.000.000-00">
          </div>
          <p class="orbs-nota">${t('diamantes.cpfAjuda')}</p>
        </div>

        <!-- O ACEITE vem ANTES dos botões, e não depois: é a última coisa lida antes de
             clicar. Embaixo dos botões seria um texto que ninguém encontra no momento em
             que ele importa. Os dois botões nascem desabilitados e só abrem com a marcação. -->
        <label class="dia-aceite">
          <input type="checkbox" id="dia-ok">
          <span>${t('diamantes.declaro')}</span>
        </label>

        <div class="dia-metodos">
          ${p.pixAtivo ? `<button class="orbs-btn" id="dia-pix">${t('diamantes.pagarPix')}</button>` : ''}
          ${p.cartaoAtivo ? `<button class="orbs-btn" id="dia-cartao">${t('diamantes.pagarCartao')}</button>` : ''}
          <button class="orbs-btn orbs-btn-sec" id="dia-verificar">${t('diamantes.verificar')}</button>
        </div>

        ${dlgLista([
          { icone: 'volta', html: t('diamantes.reembolso') },
          { icone: 'moedas', html: t('diamantes.reembolsoUso') },
        ])}

        <!-- A Efí não hospeda página de pagamento — diferente do Stripe, que abre numa aba
             nova, o PIX é resolvido AQUI: QR code para escanear ou código para colar no app
             do banco. Nasce escondido; mostrarQrPix() revela depois de criar a cobrança. -->
        <div class="dia-pix-painel hidden" id="dia-pix-painel">
          <img id="dia-pix-img" alt="QR Code PIX">
          <button class="orbs-btn orbs-btn-sec" id="dia-pix-copiar" type="button">${t('diamantes.copiarCodigo')}</button>
          <p class="orbs-nota">${t('diamantes.pixInstrucao')}</p>
        </div>

        ${dlgLista([{ icone: 'relogio', html: t('diamantes.aviso') }])}
        <p class="orbs-nota dia-legal">${t('diamantes.doacao')}</p>
      </div>
    </div>`;
}

/**
 * Liga a tela de compra. Chamada depois de o HTML entrar no DOM (ver `abrirModal`).
 *
 * O total é recalculado no cliente só para MOSTRAR — quem cobra é o servidor, que refaz a
 * conta a partir da quantidade. Um total adulterado aqui não vira desconto lá.
 */
function ligarCompraDiamantes() {
  const p = estado.diamantesPrecos;
  const campo = $('#dia-qtd');
  if (!p?.ativo || !campo) return;

  // A MESMA conta do servidor (`precoEmCentavos`), inclusive o `Math.min` contra os cortes
  // acima — sem ele a tela mostraria R$ 43,56 para 99 diamantes e o servidor cobraria R$ 42,00.
  // Isto é só para MOSTRAR: quem cobra é o servidor, que refaz tudo a partir da quantidade.
  const faixas = p.faixas ?? [];
  const unitario = (n) => faixas.find((f) => n >= f.minimo)?.centavos ?? p.centavosUnidade;
  const cheio = (n) => Math.round(n * unitario(n));
  const totalDe = (qtd) => faixas
    .filter((f) => f.minimo > qtd)
    .reduce((menor, f) => Math.min(menor, cheio(f.minimo)), cheio(qtd));

  const aceite = $('#dia-ok');

  // CPF do comprador. Máscara só para leitura; o que vai ao servidor são os 11 dígitos, e é lá
  // que os dígitos verificadores são conferidos de novo (`cpfValido`).
  const campoCpf = $('#dia-cpf');
  const cpfDigitos = () => (campoCpf?.value ?? '').replace(/\D/g, '');
  const cpfOk = () => cpfDigitos().length === 11;
  if (campoCpf) {
    campoCpf.oninput = () => {
      const d = cpfDigitos().slice(0, 11);
      campoCpf.value = d
        .replace(/^(\d{3})(\d)/, '$1.$2')
        .replace(/^(\d{3})\.(\d{3})(\d)/, '$1.$2.$3')
        .replace(/^(\d{3})\.(\d{3})\.(\d{3})(\d)/, '$1.$2.$3-$4');
      repintar();
    };
  }

  // O QR code de uma cobrança PIX aberta. Guardado à parte (e não só no <img>) porque o botão
  // "copiar código" precisa do TEXTO do copia-e-cola, que não dá para ler de volta da imagem.
  const pixPainel = $('#dia-pix-painel');
  const pixImg = $('#dia-pix-img');
  let pixCodigoAtual = '';

  const mostrarQrPix = ({ qrcode, imagemQrcode }) => {
    pixCodigoAtual = qrcode ?? '';
    if (pixImg) pixImg.src = imagemQrcode ?? '';
    pixPainel?.classList.remove('hidden');
  };

  const pixCopiar = $('#dia-pix-copiar');
  if (pixCopiar) {
    pixCopiar.onclick = async () => {
      toast(t(await copiarTexto(pixCodigoAtual) ? 'diamantes.codigoCopiado' : 'diamantes.copiarFalhou'));
    };
  }

  const cpfBloco = $('#dia-cpf-bloco');

  const repintar = () => {
    const qtd = Math.floor(Number(campo.value) || 0);
    // Base dos dois métodos: quantidade válida E aceite marcado. O CPF entra SÓ no PIX (o
    // cartão é a via do estrangeiro, que não tem CPF) — e é checado no clique, não aqui, para
    // o botão poder revelar o campo. O servidor repete tudo em `/diamantes/comprar`.
    const base = qtd >= p.qtdMinima && qtd <= p.qtdMaxima && aceite.checked;
    const valida = qtd >= p.qtdMinima && qtd <= p.qtdMaxima;
    $('#dia-total').textContent = valida
      ? reais(totalDe(qtd))
      : t('diamantes.minimoAviso', { qtd: num(p.qtdMinima) });
    $('#dia-total').classList.toggle('invalido', !valida);
    $('#dia-recibo-qtd').textContent = valida ? num(qtd) : '—';
    for (const b of document.querySelectorAll('.dia-metodos .orbs-btn')) b.disabled = !base;
  };

  // Mudar a quantidade invalida o QR na tela: ele foi gerado para OUTRO valor, e continuar
  // mostrando-o deixaria o jogador escanear um código que paga o pacote errado.
  const mudarQtd = () => {
    pixPainel?.classList.add('hidden');
    repintar();
  };
  campo.oninput = mudarQtd;
  aceite.onchange = repintar;
  for (const b of document.querySelectorAll('#dia-pacotes .dia-card')) {
    b.onclick = () => {
      campo.value = b.dataset.qtd;
      mudarQtd();
    };
  }

  const pagar = async (metodo, botao) => {
    const qtd = Math.floor(Number(campo.value) || 0);
    // Trava o botão pelo tempo da ida ao servidor: cada clique cria uma cobrança de verdade no
    // provedor, e dois cliques rápidos deixariam duas pendentes no nome do jogador.
    botao.disabled = true;
    try {
      const r = await fetch('/diamantes/comprar', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          authorization: `Bearer ${sessaoSalva()?.token ?? ''}`,
        },
        // `aceite` vai junto: é o servidor que grava o carimbo do consentimento ao lado do
        // pagamento, e é ele que recusa a compra sem ele. Um checkbox só na tela não prova nada
        // numa disputa de estorno, que é exatamente o cenário para o qual esse texto existe.
        body: JSON.stringify({
          qtd, metodo, aceite: aceite.checked,
          cpf: metodo === 'pix' ? cpfDigitos() : undefined,
        }),
      });
      const j = await r.json();
      if (!r.ok || !(j.url || j.qrcode)) throw new Error(j.erro ?? 'diamantes.falhou');
      if (j.qrcode) {
        // A Efí não hospeda página nenhuma — o QR code é desenhado AQUI, dentro do modal.
        mostrarQrPix(j);
        toast(t('diamantes.pixAguardando'));
      } else {
        // Aba nova, e não `location.href`: o jogo é um socket aberto, e trocar a página derruba
        // a sessão — o jogador voltaria do pagamento tendo perdido a hunt em que estava.
        window.open(j.url, '_blank', 'noopener');
        toast(t('diamantes.aguardando'));
      }
      iniciarPollVerificar();
    } catch (err) {
      // Só traduz o que É chave nossa. `t()` devolve a própria chave quando não acha, então
      // um erro de rede ("Failed to fetch") viraria essa frase crua na tela do jogador.
      const chave = String(err.message ?? '');
      toast(chave.startsWith('diamantes.') ? t(chave) : t('diamantes.falhou'));
    } finally {
      botao.disabled = false;
    }
  };

  const pix = $('#dia-pix');
  const cartao = $('#dia-cartao');
  if (pix) {
    pix.onclick = () => {
      // O PIX gera nota fiscal no nome de quem paga: sem CPF válido, revela o campo e espera
      // em vez de abrir a cobrança. O cartão não passa por aqui — segue direto.
      if (!cpfOk()) {
        if (cpfBloco) cpfBloco.hidden = false;
        campoCpf?.focus();
        toast(t('diamantes.cpfPix'));
        return;
      }
      pagar('pix', pix);
    };
  }
  if (cartao) cartao.onclick = () => pagar('cartao', cartao);

  let diaPollTimer = null;
  const pararPoll = () => {
    if (diaPollTimer) clearInterval(diaPollTimer);
    diaPollTimer = null;
  };

  const verificarPagamento = async (silencioso = false) => {
    const btn = $('#dia-verificar');
    if (btn?.disabled) return;
    if (btn) btn.disabled = true;
    try {
      const r = await fetch('/diamantes/verificar', {
        method: 'POST',
        headers: { authorization: `Bearer ${sessaoSalva()?.token ?? ''}` },
      });
      const j = await r.json();
      if (!r.ok) throw new Error(j.erro ?? 'diamantes.verificarFalhou');
      if (j.status === 'creditado' || j.status === 'ja_pago') {
        pararPoll();
        if (j.status === 'creditado' && !silencioso) toast(t('diamantes.creditados', { qtd: num(j.qtd) }));
        atualizarDiamantes(estado.eu ?? {}, {});
      } else if (j.status === 'aguardando' && !silencioso) {
        toast(t('diamantes.aindaPendente'));
      }
    } catch (err) {
      const chave = String(err.message ?? '');
      if (!silencioso) toast(chave.startsWith('diamantes.') ? t(chave) : t('diamantes.verificarFalhou'));
    } finally {
      if (btn) btn.disabled = false;
    }
  };

  const iniciarPollVerificar = () => {
    pararPoll();
    let tentativas = 0;
    diaPollTimer = setInterval(() => {
      if (estado.modalAberto !== 'diamantes' || tentativas++ >= 24) {
        pararPoll();
        return;
      }
      verificarPagamento(true);
    }, 15_000);
  };

  const verificar = $('#dia-verificar');
  if (verificar) verificar.onclick = () => verificarPagamento(false);

  repintar();
}

// --------------------------------------------------------------- PvP ranqueado
//
// Três telas que compartilham um estado só:
//
//   a ABA        rank, equipe, tabela e histórico. Só existe com o modal aberto.
//   o PILL       "na fila · 0:42" no alto do palco. Existe com o modal FECHADO — é ele que
//                deixa o jogador procurar partida enquanto caça, que é o ponto do jogo.
//   a PARTIDA    o mapinha do ginásio tocando a fita, com o ganho/perda revelado no fim.
//
// Nada aqui decide nada. A partida chega PRONTA do servidor (ver o cabeçalho de
// `game/pvp-ranqueado.mjs`): quando o pacote `partida` bate na porta, os pontos já mudaram no
// banco. A fita é reprodução, e fechar o modal no meio não desfaz coisa alguma — o que é
// exatamente o que torna o sistema à prova de desconexão.

/**
 * O emblema na ficha do treinador — a única parte do PvP que existe fora do modal.
 *
 * Lê `estado.pvpRank`, que é semeado pelo snapshot e mantido em dia pela aba e pelo fim de
 * cada partida. Durante o posicionamento não há emblema: o `?` é honesto, e carimbar um tier
 * que o jogador ainda não provou seria dar a ele um número que não ganhou.
 */
function pintarRankDoTreinador() {
  const box = $('#tr-rank-box');
  if (!box) return;
  const rank = estado.pvpRank;
  const img = $('#tr-rank-emblema');
  const vazio = $('#tr-rank-vazio');
  const semRank = posicionando(rank);

  img.classList.toggle('hidden', semRank);
  vazio.classList.toggle('hidden', !semRank);
  if (!semRank) {
    const src = iconeDoRank(rank.tierId);
    if (img.getAttribute('src') !== src) img.setAttribute('src', src);
  }
  $('#tr-rank-nome').textContent = semRank ? t('pvp.naoClassificado') : rotuloDoRank(rank);
  $('#tr-rank-pr').textContent = rank && !semRank ? `${num(rank.pontos)} ${t('pvp.pr')}` : '';
  box.classList.toggle('sem-rank', semRank);
  pintarRelogioDoDecaimento();
}

/**
 * Quando a elite deste jogador cai por inatividade (ms, relógio do servidor), ou `null`.
 *
 * Só Challenger e Mestre têm o relógio — é só a eles que a regra se aplica. O `tierId` é
 * conferido de novo aqui, e não só no servidor, porque o rank muda na tela sem ida ao servidor
 * (fim de partida, ver `abrirPartidaPvp`) e um `decaiEm` velho não pode sobreviver a um rebaixamento.
 */
function prazoDoDecaimento(rank = estado.pvpRank) {
  if (!rank || posicionando(rank)) return null;
  if (rank.tierId !== 'challenger' && rank.tierId !== 'mestre') return null;
  return Number(rank.decaiEm) || null;
}

/** "23:59:59" até a queda, ou vazio quando o prazo passou e a passada do servidor ainda não rodou. */
const textoDoDecaimento = (ate) =>
  (ate - agoraDoServidor() > 0 ? relogioPasse(ate) : '');

/**
 * O relógio da queda anda sozinho, uma vez por segundo: no cartão do PvP (`.pvp-decai-relogio`)
 * e na ficha do treinador (`#tr-rank-decai`). Só escreve o que mudou.
 *
 * Quando zera, a frase vira "caindo…" e fica assim até o pacote `decaiu` chegar — a passada do
 * servidor roda a cada poucos segundos, e o número desce com ela.
 */
function pintarRelogioDoDecaimento() {
  const ate = prazoDoDecaimento();
  const txt = ate ? textoDoDecaimento(ate) : '';
  const tr = $('#tr-rank-decai');
  if (tr) {
    tr.classList.toggle('hidden', !ate);
    tr.classList.toggle('urgente', !!ate && ate - agoraDoServidor() < 3 * 3_600_000);
    const rotulo = ate ? `⏳ ${txt || '0:00'}` : '';
    if (tr.textContent !== rotulo) tr.textContent = rotulo;
    const dica = ate ? t('pvp.decaiDica', { horas: PVP_DECAIMENTO_HORAS }) : '';
    if (tr.title !== dica) tr.title = dica;
  }
  for (const linha of document.querySelectorAll('.pvp-cartao-decai')) {
    linha.classList.toggle('urgente', !!ate && ate - agoraDoServidor() < 3 * 3_600_000);
    const rel = linha.querySelector('.pvp-decai-relogio');
    if (txt && rel) {
      if (rel.textContent !== txt) rel.textContent = txt;
    } else if (!txt && ate && !linha.dataset.zerou) {
      // Zerou: troca a frase inteira, uma vez. O próximo `pintarPvp` (com o rank já caído) a tira.
      linha.dataset.zerou = '1';
      linha.textContent = t('pvp.decaindo');
    }
  }
}
setInterval(pintarRelogioDoDecaimento, 1000);

$('#tr-rank-box')?.addEventListener('click', () => {
  estado.pvpAba = 'ranqueado';
  abrirModal('pvp');
});

/**
 * "agora", "12 min", "3 h", "2 d" — quando foi a partida.
 *
 * Não usa `tempoDesde`: aquela função foi escrita para "líder DESDE tal dia" e a menor unidade
 * dela é o dia inteiro ("desde hoje"), o que numa lista de partidas jogadas nos últimos
 * minutos diz exatamente nada. Aqui a unidade que importa é o minuto.
 */
function quandoFoi(iso) {
  const ms = Date.now() - new Date(iso).getTime();
  if (!Number.isFinite(ms) || ms < 60_000) return t('pvp.agora');
  const min = Math.floor(ms / 60_000);
  if (min < 60) return t('pvp.haMin', { n: min });
  const h = Math.floor(min / 60);
  if (h < 24) return t('pvp.haHoras', { n: h });
  return t('pvp.haDias', { n: Math.floor(h / 24) });
}

/** O rótulo do rank, traduzido: "Ouro II", "Challenger". */
function rotuloDoRank(rank) {
  if (!rank) return '';
  const tier = t(`pvp.tier.${rank.tierId}`);
  return rank.divisaoNum ? `${tier} ${rank.divisaoNum}` : tier;
}

/** Ainda posicionando? Enquanto for, não há emblema a mostrar. */
const posicionando = (rank) =>
  !rank || (rank.partidas ?? 0) < (estado.pvpRegras?.posicionamento ?? PVP_PARTIDAS_POSICIONAMENTO);

/** "3V" / "2D" — a sequência atual, ou vazio. */
function selosDeSequencia(seq) {
  const n = Number(seq) || 0;
  if (!n) return '';
  const cls = n > 0 ? 'up' : 'down';
  return `<span class="pvp-seq ${cls}">${Math.abs(n)}${t(n > 0 ? 'pvp.seqV' : 'pvp.seqD')}</span>`;
}

/** O emblema de um tier, no tamanho pedido. `null` durante o posicionamento. */
function emblemaDoRank(rank, classe = '') {
  if (posicionando(rank)) {
    return `<div class="pvp-emblema pvp-emblema-vazio ${classe}" aria-hidden="true">?</div>`;
  }
  return `<img class="pvp-emblema ${classe}" src="${iconeDoRank(rank.tierId)}"
    alt="${escapar(rotuloDoRank(rank))}" loading="lazy">`;
}

// ------------------------------------------------------------------- a fila

/**
 * Quanto falta da espera entre partidas, em ms. `0` = liberado.
 *
 * O servidor manda `cooldownMs` (quanto faltava NAQUELE instante) e o cliente o converte em
 * um CARIMBO de quando acaba. Sem isso o número ficava congelado: quem deixasse a aba aberta
 * depois de uma partida veria "aguarde 20s" para sempre, porque nada repintava — e o botão
 * continuava desabilitado mesmo com a espera já vencida.
 */
const msDeEsperaEntrePartidas = () =>
  Math.max(0, (estado.pvpEsperaAte ?? 0) - agoraSincronizado());

/**
 * Há quanto tempo estou na fila, em ms. `0` fora dela.
 *
 * O relógio é o do CAMPO (`agoraSincronizado`), e não o do navegador: `desde` é um carimbo do
 * SERVIDOR, e o campo já mantém a diferença entre os dois relógios por média móvel — a mesma
 * correção que a faixa de evento usa. Com `Date.now()` puro, um jogador
 * com o relógio dois minutos adiantado abriria a fila já vendo "2:00" e a tela diria que a
 * busca está aberta até Platina quando o servidor ainda a tem apertada em meia divisão.
 */
const msNaFila = () =>
  estado.pvpFila?.na && estado.pvpFila.desde
    ? Math.max(0, agoraSincronizado() - estado.pvpFila.desde)
    : 0;

/** "0:42" — o relógio da fila. */
function relogioDeFila(ms) {
  const s = Math.floor(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

/**
 * A faixa de rank em que a busca está AGORA, em texto.
 *
 * Calculada no cliente com a mesma `janelaDeBusca` do servidor, e recalculada a cada quadro:
 * é o que transforma a espera numa coisa que se pode ACOMPANHAR ("já está procurando até
 * Platina") em vez de uma ampulheta muda. Se o servidor mudar a curva, os dois mudam juntos —
 * a tabela é uma só, em `shared/pvp-rank.mjs`.
 */
function faixaDaBusca() {
  const rank = estado.pvpRank;
  if (!rank) return '';
  const janela = janelaDeBusca(msNaFila());
  if (!Number.isFinite(janela)) return t('pvp.buscaQualquer');
  const baixo = rotuloDoRank(rankDePontos(Math.max(0, rank.pontos - janela)));
  const alto = rotuloDoRank(rankDePontos(rank.pontos + janela));
  return baixo === alto ? baixo : `${baixo} – ${alto}`;
}

/**
 * O pill do palco: discreto, no alto e no meio, e some assim que a fila acaba.
 *
 * Fica ao CENTRO por eliminação, e as vizinhanças estão todas ocupadas: o canto esquerdo tem
 * o nome da hunt e a coluna de golpes logo abaixo, o direito tem "Ir ao Centro"/"Desistir", e
 * os dois rodapés são o log da batalha e os caídos. Quando a faixa de EVENTO está no ar, o
 * pill desce para debaixo dela em vez de disputar o mesmo pixel (regra de irmão no CSS) — e a
 * cena desce mais um degrau, pelo mesmo motivo.
 */
function pintarPillDeFila() {
  const pill = $('#pvp-fila-pill');
  if (!pill) return;
  const na = !!estado.pvpFila?.na;
  pill.classList.toggle('hidden', !na);
  if (!na) return;
  $('#pvp-fila-tempo').textContent = relogioDeFila(msNaFila());
  const faixa = $('#pvp-fila-faixa');
  const txt = faixaDaBusca();
  if (faixa.textContent !== txt) faixa.textContent = txt;
}
setInterval(pintarPillDeFila, 250);

/** Clicar no pill abre o PvP; o × cancela a busca sem abrir nada. */
$('#pvp-fila-pill')?.addEventListener('click', (ev) => {
  if (ev.target.closest('#pvp-fila-cancelar')) return;
  estado.pvpAba = 'ranqueado';
  abrirModal('pvp');
});
$('#pvp-fila-cancelar')?.addEventListener('click', (ev) => {
  ev.stopPropagation();
  enviar({ t: 'pvp.fila.sair' });
});

// ------------------------------------------------------------- o que chega

/**
 * O guarda-chuva `pvp`. Só vêm os campos que a resposta encheu — o mesmo desenho de `guild`
 * e `ginasio`.
 */
function aoReceberPvp(m) {
  if (m.rank !== undefined) estado.pvpRank = m.rank;
  if (m.posicao !== undefined) estado.pvpPosicao = m.posicao;
  if (m.totalClassificados !== undefined) estado.pvpTotalClassificados = m.totalClassificados;
  if (m.time !== undefined) estado.pvpTime = m.time ?? [];
  if (m.formacoes !== undefined) {
    estado.pvpFormacoes = m.formacoes ?? [];
    // A folha de equipe do Campeonato pede o armário quando abre sem ele (ver `chipsDeFormacao`).
    pintarFolhaDaEquipe?.();
  }
  if (m.ladder !== undefined) estado.pvpLadder = m.ladder ?? [];
  if (m.historico !== undefined) estado.pvpHistorico = m.historico ?? [];
  // A partida aberta no histórico (`pvp.partida.ficha`). O repinte do fim deste handler já a
  // desenha; a rolagem só acompanha se ela ainda é a que está aberta.
  if (m.ficha?.id != null) {
    const id = Number(m.ficha.id);
    fichasPvpHist.set(id, { ...m.ficha, id, recebidaEm: Date.now() });
    if (estado.pvpHistAberta === id) rolarParaFichaPvp = true;
  }
  if (m.regras !== undefined) estado.pvpRegras = m.regras;
  if (m.fila !== undefined) {
    estado.pvpFila = { ...estado.pvpFila, ...m.fila };
    if (m.fila.cooldownMs !== undefined) {
      estado.pvpEsperaAte = agoraSincronizado() + Math.max(0, m.fila.cooldownMs);
    }
  }
  // A recusa por espera também traz quanto falta — é o caminho de quem tenta entrar cedo.
  if (m.filaRecusa?.restaMs > 0) estado.pvpEsperaAte = agoraSincronizado() + m.filaRecusa.restaMs;

  if (m.timeSalvo !== undefined) {
    estado.pvpTime = m.timeSalvo;
    estado.pvpSalvandoTime = false;
    folhaEquipePvp?.fechar();
    // "Usar" uma formação também chega como `timeSalvo`; o aviso diz QUAL entrou.
    if (m.formacaoOk?.acao !== 'usar') toast(t('pvp.timeSalvo'));
  }
  if (m.formacaoOk) {
    estado.pvpFormacaoEnviando = 0;
    // O editor fecha só com a confirmação da formação DELE — outra ação ainda em voo não conta.
    if (m.formacaoOk.acao === 'salvar' && m.formacaoOk.slot === folhaFormacao?.slot) folhaFormacao.fechar();
    toast(textoDaFormacaoOk(m.formacaoOk));
  }
  if (m.formacaoRecusa) {
    estado.pvpFormacaoEnviando = 0;
    // Recusado, o editor continua aberto com o rascunho, e o botão volta.
    folhaFormacao?.repintar();
    toast(t(m.formacaoRecusa.msg, { max: FORMACAO_NOME_MAX, maxPk: PVP_TIME_MAX }));
  }
  if (m.recusa) {
    estado.pvpSalvandoTime = false;
    folhaEquipePvp?.repintar();
    toast(m.recusa.msg);
  }
  if (m.filaRecusa) {
    estado.pvpFila = { ...estado.pvpFila, na: false, desde: 0 };
    toast(m.filaRecusa.msg);
  }
  // A fila automática desligou sozinha (equipe vazia, nível). Um aviso à parte porque o
  // toast da recusa explica o QUE deu errado, e este explica o que MUDOU por causa disso.
  if (m.filaAutoDesligada) {
    if (estado.eu?.automation) estado.eu.automation.pvpAutoFila = false;
    toast(t('pvp.autoFilaDesligou'));
  }
  if (m.filaAuto) toast(t('pvp.autoFilaEntrou'));
  // A fila continuou de onde parou depois de uma atualização do servidor. O aviso existe porque
  // o contrário seria pior dos dois lados: sem ele, quem voltou acha que caiu da fila e clica de
  // novo (perdendo o tempo de espera que a retomada acabou de preservar).
  if (m.filaRetomada) toast(t('pvp.filaRetomada'));

  // Caiu da elite por inatividade (o `rank` novo já veio no mesmo pacote). A aba aberta pede a
  // tabela de novo: a posição e a lista mudaram junto com os pontos.
  if (m.decaiu) {
    toast(t('pvp.decaiu', {
      horas: PVP_DECAIMENTO_HORAS, antes: num(m.decaiu.antes), pontos: num(m.decaiu.pontos),
    }));
    pintarRankDoTreinador();
    if (estado.modalAberto === 'pvp') enviar({ t: 'pvp.info' });
  }

  // As partidas que ficaram esperando: o jogador caiu no último segundo e o resultado seguiu
  // sem ele. Vira toast, não modal — ninguém quer assistir a três replays ao entrar no jogo.
  //
  // O filtro por `partidasVistas` não é zelo: `pvp.partida.vista` e `pvp.info` saem daqui um
  // atrás do outro, e os dois handlers do servidor são assíncronos e não ordenados entre si.
  // Sem ele, a consulta da caixa postal podia rodar antes da marcação e devolver a partida que
  // o jogador está ASSISTINDO naquele instante — com um "enquanto você estava fora" por cima.
  // Quem já viu, o cliente sabe; não precisa perguntar.
  for (const p of m.naoVistas ?? []) {
    if (partidasVistas.has(p.id)) continue;
    partidasVistas.add(p.id);
    toast(t(p.venci ? 'pvp.perdidoVitoria' : 'pvp.perdidoDerrota', {
      nick: escapar(p.oponente),
      delta: `${p.delta >= 0 ? '+' : ''}${p.delta}`,
    }));
  }

  if (m.partida) abrirPartidaPvp(m.partida);

  pintarPillDeFila();
  if (estado.modalAberto === 'pvp') pintarPvp();
}

// -------------------------------------------------------------- a partida

/** O resultado que a lateral do player revela no fim da fita. `null` fora de uma partida. */
let partidaPvpAtual = null;

/**
 * Ids de partida que ESTA aba já mostrou — assistidas ao vivo ou anunciadas em toast.
 *
 * Existe porque a caixa postal do servidor é marcada na LEITURA, e a leitura pode chegar antes
 * da marcação (ver o laço de `naoVistas`). Vive só na memória da aba: recarregar a página
 * esquece tudo, e aí a fonte da verdade volta a ser o servidor — que é o comportamento certo.
 */
const partidasVistas = new Set();

/**
 * Toca a fita da partida no player da Guerra de Guilds — o mesmo mapinha do desafio de
 * ginásio, que é o que foi pedido.
 *
 * O resultado NÃO aparece de cara: ele é revelado quando a fita termina (ver `pintarReplay`).
 * O pacote já traz o número desde o primeiro quadro, e traz de propósito — segurá-lo no
 * servidor para mandar depois seria uma segunda viagem que pode não chegar, e aí o jogador
 * assistiria à própria vitória sem nunca ver o ganho.
 */
function abrirPartidaPvp(partida) {
  estado.pvpFila = { ...estado.pvpFila, na: false, desde: 0 };
  pintarPillDeFila();
  // O rank novo entra no estado JÁ: se o jogador fechar a fita no meio, a aba atrás dela tem
  // de mostrar o número de agora, e não o de antes da partida.
  if (estado.pvpRank) {
    const novo = rankParaTela(partida.pontos, partida.posicao);
    estado.pvpRank = {
      ...estado.pvpRank,
      ...novo,
      partidas: (estado.pvpRank.partidas ?? 0) + 1,
      vitorias: (estado.pvpRank.vitorias ?? 0) + (partida.venci ? 1 : 0),
      derrotas: (estado.pvpRank.derrotas ?? 0) + (partida.venci ? 0 : 1),
      // A partida zera o relógio da queda: é o "resetado a cada ranqueada". O `pvp.info` logo
      // abaixo traz o carimbo do banco, mas o relógio não pode ficar mostrando o prazo velho até lá.
      decaiEm: decaiEm(agoraDoServidor(), novo.tierId),
    };
  }
  // Como a batalha aparece é escolha do jogador (ver `TELA_BATALHA`). Os três caminhos
  // guardam `partidaPvpAtual` DEPOIS de abrir, e não antes: `abrirReplayGuerra` começa
  // fechando o player anterior, e `fecharReplayGuerra` esquece a partida corrente de propósito
  // (senão a fita seguinte — uma Guerra de Guilds, um desafio de ginásio — terminaria
  // mostrando o "+18" desta aqui). Guardar antes era o mesmo que não guardar.
  const modo = telaDeBatalha();
  if (modo === TELA_BATALHA.OFF) {
    // Sem tela nenhuma: sobra o número, que é o que o jogador de fato esperava. Sem isto a
    // partida aconteceria em silêncio absoluto e pareceria que a fila não anda.
    toast(t(partida.venci ? 'pvp.resultadoToastVitoria' : 'pvp.resultadoToastDerrota', {
      nick: escapar(partida.oponente?.nick ?? ''),
      delta: `${partida.delta >= 0 ? '+' : ''}${partida.delta}`,
    }));
    partidaPvpAtual = partida;
  } else if (modo === TELA_BATALHA.MINI && abrirMiniPvp(partida)) {
    partidaPvpAtual = partida;
  } else {
    // COMPLETA — e também o retorno da janelinha quando ela não pôde abrir (fita sem atores).
    abrirReplayPartidaPvp(partida);
  }
  // A espera entre partidas começa AGORA. Vem da constante compartilhada em vez de uma ida
  // ao servidor: quem recusa de verdade é ele, e isto é só o botão dizendo a verdade sem
  // esperar um pacote que talvez nem venha.
  estado.pvpEsperaAte = agoraSincronizado() + PVP_ENTRE_PARTIDAS_MS;
  // Assistida: sai da caixa postal para não voltar como toast no próximo login.
  partidasVistas.add(partida.id);
  enviar({ t: 'pvp.partida.vista', id: partida.id });
  if (estado.modalAberto === 'pvp') pintarPvp();
  // A aba por baixo do player já pode pedir a tabela nova — o histórico ganhou uma linha.
  enviar({ t: 'pvp.info' });
}

/**
 * A partida ranqueada em TELA CHEIA — o modal de sempre, já acelerado para caber.
 *
 * Separada de `abrirPartidaPvp` porque o ⤢ da janelinha também entra por aqui: quem minimizou
 * e resolveu assistir quer a fita do começo, e não o modal aberto na metade em que estava.
 */
function abrirReplayPartidaPvp(partida) {
  abrirReplayGuerra({
    replay: partida.replay,
    titulo: t('pvp.partidaTitulo', { nick: escapar(partida.oponente?.nick ?? '') }),
    // O acelerador vale também na tela cheia, e pela mesma razão: a fila automática puxa a
    // próxima 20 s depois do fim, e uma fita de 5 min atropelaria a partida seguinte esteja
    // ela num modal ou num canto. Os botões de velocidade continuam lá para quem quiser
    // desfazer — o que isto muda é só o ponto de partida.
    aoPronto: acelerarParaCaber,
  });
  partidaPvpAtual = partida;
}

// ------------------------------------------- como a batalha do PvP aparece
//
// Três modos, e a razão de existirem é a fila automática: com ela ligada o jogador leva uma
// partida a cada poucos minutos, e um modal de tela cheia por cima do farm a cada uma é o tipo
// de coisa que faz desligar o modo em vez de desligar o aviso.
//
// Mora no `localStorage`, e não no servidor, pela mesma regra dos painéis recolhíveis: é uma
// escolha sobre a MESA, não sobre o jogo. Nada aqui muda o que acontece na partida — ela já foi
// simulada e gravada antes de o pacote chegar.

const TELA_BATALHA = { COMPLETA: 'completa', MINI: 'mini', OFF: 'off' };
const CHAVE_TELA_BATALHA = 'pvpTelaBatalha';

function telaDeBatalha() {
  // MODO ECONOMIA: a fita da partida é uma CENA, e o modo desligou a cena. A janelinha ainda
  // mora no palco (que o modo esconde), então abri-la daria um `ReplayGuerra` desenhando a
  // 60 Hz num canvas invisível — o contrário exato do que o jogador pediu. Sobra o `off`, que
  // é o caminho já existente para "só me diga o resultado": um toast com o nick e o delta.
  if (economiaLigado()) return TELA_BATALHA.OFF;
  try {
    const v = localStorage.getItem(CHAVE_TELA_BATALHA);
    return Object.values(TELA_BATALHA).includes(v) ? v : TELA_BATALHA.COMPLETA;
  } catch { return TELA_BATALHA.COMPLETA; }
}

function definirTelaDeBatalha(v) {
  if (!Object.values(TELA_BATALHA).includes(v)) return;
  try { localStorage.setItem(CHAVE_TELA_BATALHA, v); } catch { /* modo privado / quota */ }
  // Trocar para "não mostrar" com uma fita rodando fecha o que está no ar: a preferência nova
  // vale a partir de agora, e deixar a janelinha aberta contradiz o que acabou de ser pedido.
  if (v === TELA_BATALHA.OFF) {
    fecharMiniPvp();
    if (partidaPvpAtual) fecharReplayGuerra();
  }
}

/**
 * O fator de velocidade que faz a fita caber na janela entre duas partidas.
 *
 * `PVP_ENTRE_PARTIDAS_MS` (20 s) é o tempo que a fila automática espera antes de puxar a
 * próxima. Uma partida pode ir até o teto de 5 min do simulador, e nesse caso a fita ainda
 * estaria rodando quando a seguinte chegasse — duas batalhas disputando a mesma tela.
 *
 * Fitas curtas (a grande maioria: a média medida em produção é ~43 s… que já passa de 20 s)
 * não são desaceleradas: o piso é 1×, então isto só acelera, nunca arrasta.
 */
function velocidadeParaCaber(duracaoMs) {
  const alvo = PVP_ENTRE_PARTIDAS_MS;
  if (!(duracaoMs > alvo)) return 1;
  return duracaoMs / alvo;
}

/** Aplica o acelerador a um player de partida RANQUEADA (a guerra de guild não é tocada). */
function acelerarParaCaber(player) {
  const v = velocidadeParaCaber(player?.duracao ?? 0);
  if (v > 1) player.velocidade(v, { livre: true });
  sincronizarBotoesVel(player);
  return v;
}

/**
 * Deixa a barra de velocidades dizendo a verdade.
 *
 * O acelerador usa um fator contínuo (15×, por exemplo) que não existe entre os quatro botões.
 * Sem isto a barra continuaria com o 1× aceso enquanto a fita corre a 15× — e o jogador que
 * clicasse em 1× para "voltar ao normal" veria o botão já aceso não fazer nada.
 *
 * Nenhum aceso é a leitura honesta de "está numa velocidade que não é nenhuma destas"; o
 * número real aparece ao lado, no rótulo.
 */
function sincronizarBotoesVel(player) {
  const host = $('#gwr-vels');
  if (!host || replayGuerra !== player) return;
  const atual = player.vel;
  for (const b of host.querySelectorAll('.gwr-vel')) {
    b.classList.toggle('on', Number(b.dataset.vel) === atual);
  }
  const livre = !VELOCIDADES.includes(atual);
  host.dataset.livre = livre ? `${Math.round(atual)}×` : '';
  host.classList.toggle('com-livre', livre);
}

// ------------------------------------------------------- a janelinha do canto

let miniPvp = null;
let miniPvpFechaEm = 0;

/** Quantos ms o resultado fica na janelinha antes de ela sumir sozinha. */
const MINI_PVP_RESULTADO_MS = 4000;

function fecharMiniPvp() {
  miniPvp?.destruir();
  miniPvp = null;
  miniPvpFechaEm = 0;
  $('#pvp-mini')?.classList.add('hidden');
  $('#pvp-mini-res')?.classList.add('hidden');
}

/**
 * Abre a batalha na janelinha do canto do palco.
 *
 * É o MESMO `ReplayGuerra` do modal, com outro canvas e um `aoAtualizar` que não pinta nada —
 * a janelinha não tem barra de tempo, elenco nem feed, e chamar `pintarReplay` aqui mexeria
 * nos elementos do modal, que está fechado.
 */
function abrirMiniPvp(partida) {
  const rep = partida?.replay;
  const caixa = $('#pvp-mini');
  if (!rep?.atores?.length || !caixa) return false;

  fecharMiniPvp();
  caixa.classList.remove('hidden');
  $('#pvp-mini-vs').textContent = t('pvp.partidaTitulo', { nick: partida.oponente?.nick ?? '' });

  // Fora do `hidden` ANTES de construir: o `Campo` mede o pai no construtor, e num elemento
  // escondido isso dá zero — o mesmo cuidado que `abrirReplayGuerra` já toma.
  // O `aoAtualizar` da janelinha faz UMA coisa: perceber que a fita acabou. As duas condições
  // são as mesmas de `pintarReplay` — `acabou` só é marcado quando a fita rodou até o fim
  // tocando, e uma fita que termina com a aba em segundo plano chega em `t >= dur` sem ele.
  const player = new ReplayGuerra($('#pvp-mini-campo'), rep, {
    mini: true,
    aoAtualizar: (st) => {
      if (miniPvp === player && (st.acabou || st.t >= st.dur)) mostrarResultadoMini(partida);
    },
  });
  miniPvp = player;
  player.iniciar().then(() => {
    if (miniPvp !== player) return;
    acelerarParaCaber(player);
    player.tocar();
  });
  return true;
}

/** O resultado por cima da janelinha, quando a fita acaba. */
function mostrarResultadoMini(partida) {
  const res = $('#pvp-mini-res');
  // Já mostrado: o `aoAtualizar` chama isto a CADA quadro depois do fim, e sem esta guarda o
  // `miniPvpFechaEm` seria empurrado para a frente a cada um — a janelinha nunca fecharia.
  if (!res || !res.classList.contains('hidden')) return;
  const venci = !!partida.venci;
  const delta = `${partida.delta >= 0 ? '+' : ''}${partida.delta} ${t('pvp.pr')}`;
  res.innerHTML = `<b class="${venci ? 'venceu' : 'perdeu'}">${t(venci ? 'pvp.vitoria' : 'pvp.derrota')}</b>
    <span>${escapar(delta)}</span>`;
  res.classList.remove('hidden');
  miniPvpFechaEm = agoraSincronizado() + MINI_PVP_RESULTADO_MS;
}

// A janelinha se fecha sozinha depois do resultado. Um relógio no mesmo tique do pill da fila,
// e não um `setTimeout`: um timer pendurado sobreviveria a um logout ou a uma partida nova.
setInterval(() => {
  if (!miniPvpFechaEm || agoraSincronizado() < miniPvpFechaEm) return;
  fecharMiniPvp();
}, 500);

// Fechar a janelinha segue a mesma regra do modal: se a fita ainda não revelou o resultado,
// o termômetro assume o lugar dela. `#pvp-mini-res` escondido é exatamente "ainda não revelou".
$('#pvp-mini-fechar')?.addEventListener('click', () => {
  const partida = partidaPvpAtual;
  const jaRevelou = !$('#pvp-mini-res')?.classList.contains('hidden');
  fecharMiniPvp();
  if (partida && !jaRevelou) mostrarTickDeRank(partida);
});
// ⤢ promove a janelinha a tela cheia, do começo: a fita é curta e o jogador que clicou aqui
// quer ver a briga, não pegá-la pela metade.
$('#pvp-mini-abrir')?.addEventListener('click', () => {
  const p = partidaPvpAtual;
  fecharMiniPvp();
  if (p) abrirReplayPartidaPvp(p);
});

// ------------------------------------------------- o termômetro de rank
//
// O que sobra quando o jogador FECHA a batalha no meio. Ele fechou a tela, não a partida — ela
// já estava decidida antes do primeiro quadro (ver o cabeçalho de `pvp-ranqueado.mjs`) —, e
// perder o número junto com a fita é perder justamente a parte que ele esperava.
//
// Mostra o rank NOVO e anda a barra do valor velho até o novo. Ocupa a mesma vaga da
// janelinha, e os dois nunca convivem: fechar um mostra o outro.

let tickFechaEm = 0;

/** Quanto tempo o termômetro fica na tela antes de sumir sozinho. */
const TICK_RANK_MS = 6000;

function fecharTickDeRank() {
  tickFechaEm = 0;
  $('#pvp-tick')?.classList.add('hidden');
}

/**
 * Desenha o termômetro para uma partida ranqueada.
 *
 * A barra sai do progresso ANTIGO e vai para o novo. Quando o tier mudou, "progresso antigo"
 * não existe na régua do tier novo — quem promoveu entra pelo chão dele (0) e quem rebaixou
 * entra pelo teto (1). É a leitura que bate com o que aconteceu, e é o que faz a barra andar
 * no sentido certo em vez de dar um salto sem explicação.
 */
function mostrarTickDeRank(partida) {
  const caixa = $('#pvp-tick');
  if (!caixa || !partida) return;
  fecharMiniPvp();

  const novo = rankParaTela(partida.pontos, partida.posicao);
  const velho = rankParaTela(partida.pontos - partida.delta, partida.posicao);
  const pct = (r) => (r.progresso == null ? 1 : Math.max(0, Math.min(1, r.progresso)));
  const de = partida.promoveu ? 0 : partida.rebaixou ? 1 : pct(velho);
  const ate = pct(novo);

  $('#pvp-tick-emblema').innerHTML = emblemaDoRank({ ...novo, partidas: 99 });
  $('#pvp-tick-rank').textContent = rotuloDoRank(novo);
  const delta = $('#pvp-tick-delta');
  delta.textContent = `${partida.delta >= 0 ? '+' : ''}${partida.delta}`;
  delta.className = `pvp-tick-delta ${partida.delta >= 0 ? 'up' : 'down'}`;
  $('#pvp-tick-total').textContent = `${num(partida.pontos)} ${t('pvp.pr')}`;
  caixa.querySelector('.pvp-tick-barra').classList.toggle('desce', partida.delta < 0);

  const fill = $('#pvp-tick-fill');
  // Pinta no ponto de PARTIDA sem transição, força o navegador a assumir esse valor e só então
  // solta o destino — sem o `offsetWidth` no meio, as duas escritas viram uma só e a barra
  // nasce já no fim, sem andar.
  fill.style.transition = 'none';
  fill.style.width = `${de * 100}%`;
  void fill.offsetWidth;
  fill.style.transition = '';
  caixa.classList.remove('hidden');
  requestAnimationFrame(() => {
    fill.style.width = `${ate * 100}%`;
  });

  tickFechaEm = agoraSincronizado() + TICK_RANK_MS;
}

setInterval(() => {
  if (!tickFechaEm || agoraSincronizado() < tickFechaEm) return;
  fecharTickDeRank();
}, 500);

$('#pvp-tick-fechar')?.addEventListener('click', fecharTickDeRank);

/**
 * Os campos derivados do PR, do mesmo jeito que o servidor os manda.
 *
 * A POSIÇÃO entra na conta porque acima de `PVP_PR_ELITE` é ela que decide entre Challenger,
 * Mestre e "tem os pontos, espera vaga" — o cartão de resultado desenharia Diamante I para
 * quem acabou de entrar no top 20 se olhasse só o número.
 */
function rankParaTela(pontos, posicao = null) {
  const r = rankComVaga(pontos, posicao);
  return {
    posicao: r.posicao ?? posicao ?? null,
    aguardandoVaga: !!r.aguardandoVaga,
    faltamPosicoes: r.faltamPosicoes ?? null,
    tierId: r.tierId,
    divisao: r.divisao,
    divisaoNum: r.divisaoNum,
    pontos: r.pontos,
    de: r.de,
    ate: Number.isFinite(r.ate) ? r.ate : null,
    progresso: r.progresso,
    naFaixa: r.naFaixa,
    larguraFaixa: r.larguraFaixa,
  };
}

/**
 * O cartão de resultado, na lateral do player.
 *
 * Chamado por `pintarReplay` a cada quadro; ele mesmo decide QUANDO aparecer (`s.acabou`).
 * Sai da lateral e não por cima do campo porque o pedido é explícito — "no final aparece se
 * ele ganhou ELO ou perdeu ELO na lateral" — e porque cobrir o campo no último segundo
 * esconderia justamente o golpe que decidiu a luta.
 */
function pintarResultadoPvp(acabou) {
  const p = partidaPvpAtual;
  // O cartão é RECRIADO quando falta, e isso não é paranoia: `montarControlesReplay` escreve
  // `#gwr-lateral.innerHTML` inteiro para montar a lista de lutadores, e leva junto qualquer
  // filho que estivesse lá — foi o que fez o resultado nunca aparecer na primeira versão.
  // Recriar aqui é mais robusto do que pedir ao painel de guild que preserve um nó que não é
  // dele: o dia em que aquela lista mudar de forma, isto continua funcionando.
  let host = $('#gwr-pvp-resultado');
  if (!host) {
    if (!p) return;
    const lateral = $('#gwr-lateral');
    if (!lateral) return;
    host = document.createElement('div');
    host.className = 'gwr-pvp-resultado hidden';
    host.id = 'gwr-pvp-resultado';
    lateral.prepend(host);
  }
  if (!p) {
    host.classList.add('hidden');
    host.innerHTML = '';
    return;
  }
  host.classList.toggle('hidden', !acabou);
  if (!acabou || host.dataset.partida === String(p.id)) return;
  host.dataset.partida = String(p.id);

  // O AMISTOSO não tem PR: o cartão é só quem venceu, com a mesma cor de vitória/derrota.
  if (p.amistoso) {
    host.innerHTML = `
      <div class="pvp-res ${p.venci ? 'venci' : 'perdi'}">
        <div class="pvp-res-titulo">${t(p.venci ? 'pvp.vitoria' : 'pvp.derrota')}</div>
        <div class="pvp-res-rank">${escapar(t('amigos.pvpa.tituloFita', { nick: p.oponente?.nick ?? '' }))}</div>
        <div class="pvp-res-nota">${t('amigos.pvpa.semPr')}</div>
      </div>`;
    return;
  }

  const rank = rankParaTela(p.pontos, p.posicao);
  const sinal = p.delta >= 0 ? '+' : '';
  const barra = rank.progresso == null ? 100 : Math.round(rank.progresso * 100);
  host.innerHTML = `
    <div class="pvp-res ${p.venci ? 'venci' : 'perdi'}">
      <div class="pvp-res-titulo">${t(p.venci ? 'pvp.vitoria' : 'pvp.derrota')}</div>
      ${emblemaDoRank({ ...rank, partidas: 99 }, 'pvp-emblema-res')}
      <div class="pvp-res-rank">${escapar(rotuloDoRank(rank))}</div>
      <div class="pvp-res-delta ${p.delta >= 0 ? 'up' : 'down'}">${sinal}${p.delta} ${t('pvp.pr')}</div>
      <div class="pvp-res-total">${num(p.pontos)} ${t('pvp.pr')}</div>
      <div class="pvp-barra"><i style="width:${barra}%"></i></div>
      ${p.promoveu ? `<div class="pvp-res-selo up">${t('pvp.promoveu')}</div>` : ''}
      ${p.rebaixou ? `<div class="pvp-res-selo down">${t('pvp.rebaixou')}</div>` : ''}
      ${p.escudoUsou ? `<div class="pvp-res-selo escudo">${t('pvp.escudoSegurou')}</div>` : ''}
      ${p.mesmaCasa ? `<div class="pvp-res-nota">${t('pvp.mesmaCasa')}</div>` : ''}
    </div>`;
}

// ------------------------------------------------------------------- a aba

function renderPvp() {
  return `
    <div class="pvp-tela">
      <!-- O Ranqueado leva o ícone do PvP do menu (o data-ico vira imagem no abrirModal). O
           escudo da Guild vai com o seletor U+FE0F: sem ele o Windows desenha o glifo de texto,
           um contorno vazado, em vez do emoji colorido. -->
      <div class="pvp-abas" role="tablist">
        <button type="button" class="pvp-aba" data-aba="ranqueado" role="tab">
          <span class="pvp-aba-ico" aria-hidden="true" data-ico="img:/img/menu-pvp.png" data-ico-px="20"></span>${t('pvp.abaRanqueado')}
        </button>
        <button type="button" class="pvp-aba" data-aba="guild" role="tab">
          <span class="pvp-aba-ico" aria-hidden="true">${'\u{1F6E1}\uFE0F'}</span>${t('pvp.abaGuild')}
        </button>
        <button type="button" class="pvp-aba" data-aba="treino" role="tab">
          <span class="pvp-aba-ico" aria-hidden="true">🎯</span>${t('pvp.abaTreino')}
        </button>
      </div>
      <div class="pvp-conteudo">
        <div class="pvp-painel" id="pvp-painel-ranqueado"></div>
        <div class="pvp-painel hidden" id="pvp-painel-guild">
          <div id="guild-pvp-painel" class="guild-pvp-painel"></div>
        </div>
        <div class="pvp-painel hidden" id="pvp-painel-treino"></div>
      </div>
    </div>`;
}

/** Abre o modal na aba certa e liga os botões. Chamado uma vez por abertura. */
function montarPvp() {
  for (const bt of document.querySelectorAll('.pvp-aba')) {
    bt.onclick = () => {
      estado.pvpAba = bt.dataset.aba;
      pintarPvp();
    };
  }
  enviar({ t: 'pvp.info' });
  enviar({ t: 'guild.pvp.info' });
  pintarPvp();
}

/**
 * Repinta a aba aberta.
 *
 * Repintar tudo é barato aqui — são um cartão, cinco slots e duas listas de vinte linhas — e
 * evita o bug clássico desta tela: vender no Mercado um pokémon da equipe de PvP com o modal
 * aberto tem de sumir com o slot na mesma hora, e um redesenho parcial deixaria um fantasma
 * que o "entrar na fila" recusaria sem explicar por quê.
 *
 * O SELETOR de equipe não entra aqui: ele é uma folha por cima do modal, com rascunho próprio
 * — ver `abrirSeletorDeTimePvp`.
 */
function pintarPvp() {
  const aba = ['guild', 'treino'].includes(estado.pvpAba) ? estado.pvpAba : 'ranqueado';
  estado.pvpAba = aba;
  // A cor do tier desce por uma variável de CSS, presa na raiz da tela. É ela que pinta o halo
  // do cartão e o realce das listas — sem isto, cada emblema seria um adesivo colorido solto
  // no meio de uma tábua marrom. Some durante o posicionamento, junto com o emblema.
  const tela = $('.pvp-tela');
  if (tela) {
    const rank = estado.pvpRank;
    if (posicionando(rank)) delete tela.dataset.tier;
    else tela.dataset.tier = rank.tierId;
  }
  for (const bt of document.querySelectorAll('.pvp-aba')) bt.classList.toggle('on', bt.dataset.aba === aba);
  $('#pvp-painel-ranqueado')?.classList.toggle('hidden', aba !== 'ranqueado');
  $('#pvp-painel-guild')?.classList.toggle('hidden', aba !== 'guild');
  $('#pvp-painel-treino')?.classList.toggle('hidden', aba !== 'treino');
  if (aba === 'guild') return montarGuildPvp();
  if (aba === 'treino') return pintarTreino();
  pintarRanqueado();
}

// ------------------------------------------------------ as recompensas (🏆)
//
// Um botão pequeno em cada aba que premia, logo abaixo da ação principal dela: a Fila automática
// no Ranqueado, o replay da última guerra no Guild. O Treino não premia nada e não tem botão.
// Cada linha da folha sai dos mesmos objetos com que o servidor paga (`PVP_PREMIOS`,
// `BONUS_RANKING_GP`, `PREMIOS_GLOBAL`, todos no shared), e não de texto escrito à mão: mudou o
// prêmio, a folha muda junto, sem prometer o que não se paga.

/** O botão 🏆 Recompensas. Quem liga o clique é o painel que o desenhou. */
const botaoPremiosPvp = (id) => `
  <button type="button" class="pvp-premios-bt" id="${id}" title="${escapar(t('pvp.premiosDica'))}">
    <span class="pvp-premios-ico" aria-hidden="true">🏆</span>${t('pvp.premiosBt')}
  </button>`;

/**
 * Quanto falta até `fim`, pelo relógio do servidor. Abaixo de dois dias vira horas: "1 dias" é
 * erro de português, e "1 dia" some com as 23 h.
 */
function tempoAte(fim) {
  const falta = Math.max(0, fim - agoraDoServidor());
  const dias = Math.floor(falta / 86_400_000);
  if (dias >= 2) return t('painel.dias', { n: dias });
  return `${Math.floor(falta / 3_600_000)}h ${Math.floor((falta % 3_600_000) / 60_000)}m`;
}

/** Até a virada da temporada do PvP Ranqueado: a próxima segunda-feira, 00:00 de Brasília. */
const tempoAteViradaDaSemanaPvp = () => tempoAte(fimDaTemporada(temporadaDe(agoraDoServidor())));

/** Até o dia 1º, 00:00 UTC — quando fecha a Temporada Global de guilds, que continua mensal. */
function tempoAteViradaDoMes() {
  const d = new Date(agoraDoServidor());
  return tempoAte(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1));
}

/** A duração de um boost de prêmio: "2 dias" quando fecha em dias, "18 horas" quando não. */
const duracaoDoPremio = (horas) => (horas % 24 === 0
  ? t('painel.dias', { n: horas / 24 })
  : t('pvpr.horas', { n: horas }));

/**
 * Uma linha da folha: a posição à esquerda, o prêmio à direita. O selo "você está aqui" mora
 * embaixo do rótulo, e não numa terceira coluna — no celular ela espremeria o prêmio.
 */
const linhaDePremio = ({ rotulo, sub = '', arte = '', premio, eu = false, selo = '' }) => `
  <div class="pvpr-linha${eu ? ' eu' : ''}">
    <div class="pvpr-pos">
      ${arte}
      <div class="pvpr-pos-txt">
        <b>${rotulo}</b>${sub ? `<span>${sub}</span>` : ''}${eu ? `<em class="pvpr-voce">${selo}</em>` : ''}
      </div>
    </div>
    <div class="pvpr-premio">${premio}</div>
  </div>`;

/** "🧪 Shiny Secret Lure · 2 dias" — o boost com o ícone da Loja e a duração. */
function itemDeBoostPvp(chave, horas) {
  const tipo = tipoDeBoost(chave);
  const ico = tipo?.icone ? `<img class="pvpr-ico" src="/assets/${escapar(tipo.icone)}" alt="">` : '';
  return `<span class="pvpr-item">${ico}<span>${escapar(nomeDoBoost(chave))}</span><b>${duracaoDoPremio(horas)}</b></span>`;
}

function abrirPremiosRanqueado() {
  const { corpo } = folhaMercado(`🏆 ${escapar(t('pvpr.titulo', { modo: t('rk.arenaPvp') }))}`);
  // A posição só existe depois do posicionamento; antes disso, nenhuma linha é "sua".
  const pos = Number(estado.pvpPosicao) || 0;
  let de = 1;
  const linhas = PVP_PREMIOS.map((f) => {
    const faixa = { de, ate: f.ate };
    de = f.ate + 1;
    // O pódio é Challenger também (são as três primeiras das vinte vagas): o emblema é o mesmo,
    // e quem separa as duas linhas é o nome da faixa.
    const tier = f.faixa === 'mestre' ? 'mestre' : 'challenger';
    return linhaDePremio({
      rotulo: t('pvpr.posicoes', faixa),
      sub: f.faixa === 'podio' ? t('pvpr.podio') : t(`pvp.tier.${tier}`),
      arte: `<img class="pvpr-emblema" src="${iconeDoRank(tier)}" alt="">`,
      premio: Object.entries(f.horas).map(([chave, horas]) => itemDeBoostPvp(chave, horas)).join(''),
      eu: pos >= faixa.de && pos <= faixa.ate,
      selo: t('pvpr.voce'),
    });
  }).join('');
  corpo.innerHTML = `
    <div class="pvpr">
      <p class="pvpr-lead">${t('pvpr.ranqueadoLead')}</p>
      <p class="pvpr-relogio">${t('pvpr.fechaEm', { tempo: tempoAteViradaDaSemanaPvp() })}</p>
      <div class="pvpr-lista">${linhas}</div>
      <p class="pvpr-nota">${t('rk.pvpPremiosNota', { horas: PVP_DECAIMENTO_HORAS })}</p>
    </div>`;
  setaDeRolagem(corpo);
}

function abrirPremiosGuild() {
  const { corpo } = folhaMercado(`🏆 ${escapar(t('pvpr.titulo', { modo: t('guild.pvpTitulo') }))}`);
  // O bônus que a guild do jogador TEM agora: é a posição dela no ranking Diário, a mesma que
  // acende a linha "⚔ Guild" dos ativos do treinador. Sem GP hoje, nenhuma linha é dela.
  const rankHoje = estado.eu?.guild ? Number(estado.eu?.guildBonusRank) || 0 : 0;
  // O pódio leva o troféu e as medalhas do Campeonato; dali para baixo, a posição num selo
  // redondo. É o que faz a escada se ler de relance, sem ler "TOP" dez vezes.
  const marcaDaPos = (pos) => (ICONE_LUGAR_CAMPEONATO[pos]
    ? `<img class="pvpr-emblema pvpr-medalha" src="${ICONE_LUGAR_CAMPEONATO[pos]}" alt="">`
    : `<span class="pvpr-num">${pos >= PRIMEIRA_POS_RESTO ? `>${PRIMEIRA_POS_RESTO - 1}` : pos}</span>`);
  // Uma linha por posição com % próprio, mais a do piso — a escada inteira sai de
  // `POSICOES_BONUS_GP`, e não de uma lista escrita aqui que envelheceria no próximo ajuste. A
  // barra mede o bônus contra o do 1º lugar: a distância entre o 1º e o 5º é o que motiva.
  const topoPct = Math.max(1, bonusPctPorPosRanking(POSICOES_BONUS_GP[0] ?? 1));
  const diario = [...POSICOES_BONUS_GP, PRIMEIRA_POS_RESTO].map((pos) => {
    const pct = bonusPctPorPosRanking(pos);
    return linhaDePremio({
      rotulo: rotuloTopGuild(pos),
      arte: marcaDaPos(pos),
      premio: `<span class="pvpr-item pvpr-grande">${t('pvpr.bonusFarm', { n: pct })}</span>
        <span class="pvpr-barra" aria-hidden="true"><i style="width:${Math.round((pct / topoPct) * 100)}%"></i></span>`,
      eu: rankHoje > 0 && (pos < PRIMEIRA_POS_RESTO ? rankHoje === pos : rankHoje >= PRIMEIRA_POS_RESTO),
      selo: t('pvpr.suaGuild'),
    });
  }).join('');
  const mensal = Object.entries(PREMIOS_GLOBAL).map(([pos, qtd]) => linhaDePremio({
    rotulo: `TOP ${Number(pos)}`,
    arte: marcaDaPos(Number(pos)),
    premio: `<span class="pvpr-item pvpr-grande">${seloDiamante(20)}<b>+${num(qtd)}</b><span>${t('pvpr.porMembro')}</span></span>`,
  })).join('');
  corpo.innerHTML = `
    <div class="pvpr">
      <h4 class="pvpr-sec">${t('pvpr.guildDiaTitulo', { h: estado.guildPvp?.horaUtc ?? 22 })}</h4>
      <p class="pvpr-lead">${t('pvpr.guildDiaLead')}</p>
      <div class="pvpr-lista">${diario}</div>
      <p class="pvpr-nota">${t('guild.pvpGpDetalhe')} ${t('rk.guildBonusZero')}</p>
      <h4 class="pvpr-sec">${t('pvpr.guildMesTitulo')}</h4>
      <p class="pvpr-lead">${t('pvpr.guildMesLead')}</p>
      <p class="pvpr-relogio">${t('pvpr.fechaEm', { tempo: tempoAteViradaDoMes() })}</p>
      <div class="pvpr-lista">${mensal}</div>
      <p class="pvpr-nota">${t('rk.guildGlobalBonusZero')}</p>
    </div>`;
  setaDeRolagem(corpo);
}

/** Os pokémon da equipe salva, na ordem — os que ainda existem na coleção. */
const pokemonsDoTimePvp = () =>
  (estado.pvpTime ?? [])
    .map((id) => (estado.eu?.pokemons ?? []).find((p) => p.id === id))
    .filter(Boolean);

function pintarRanqueado() {
  const host = $('#pvp-painel-ranqueado');
  if (!host) return;
  const rank = estado.pvpRank;
  const regras = estado.pvpRegras ?? {};
  const nivelMin = regras.nivelMin ?? PVP_NIVEL_MIN;
  const time = pokemonsDoTimePvp();

  // A aba é redesenhada a cada pacote de PvP (fila, tabela, resultado). Sem guardar a rolagem,
  // a Tabela voltava ao topo no meio da leitura — e a linha que o jogador olhava sumia de vista.
  const rolagem = {
    painel: host.scrollTop,
    tabela: host.querySelector('.pvp-ladder')?.scrollTop ?? 0,
    historico: host.querySelector('.pvp-hist')?.scrollTop ?? 0,
  };

  host.innerHTML = `
    <div class="pvp-r-grade">
      <section class="pvp-r-col">
        ${cartaoDeRank(rank)}
        <!-- A FILA vem antes da equipe, e não depois, por uma razão de uso: a equipe se monta
             uma vez e a fila se abre toda vez. Deixando-a por último, os cinco cards empurravam
             o "Procurar partida" para fora da tela — o botão mais importante da aba exigindo
             rolagem para ser encontrado. -->
        ${blocoDaFila(rank, nivelMin, time)}
        ${blocoDaEquipePvp(time)}
        ${blocoDasFormacoes(time)}
      </section>
      <section class="pvp-r-col">
        ${blocoDaLadder()}
        ${blocoDoHistorico()}
      </section>
    </div>`;

  ligarRanqueado();
  host.scrollTop = rolagem.painel;
  const tabela = host.querySelector('.pvp-ladder');
  if (tabela) tabela.scrollTop = rolagem.tabela;
  const historico = host.querySelector('.pvp-hist');
  if (historico) historico.scrollTop = rolagem.historico;
  if (rolarParaFichaPvp) {
    rolarParaFichaPvp = false;
    const aberta = host.querySelector('.pvp-hist-linha.aberta');
    // Da LINHA até o fim da ficha: `nearest` na ficha sozinha podia esconder a própria linha
    // clicada no alto, e o jogador perdia de vista em que partida estava.
    if (aberta) {
      const ficha = aberta.nextElementSibling;
      (ficha?.classList.contains('pvp-hist-ficha') ? ficha : aberta).scrollIntoView({ block: 'nearest' });
      aberta.scrollIntoView({ block: 'nearest' });
    }
  }
}

/**
 * "⏳ Cai para o Diamante em 5:12:03" — só no cartão de quem está com a vaga.
 *
 * Nasce com o texto do instante e segue andando por `pintarRelogioDoDecaimento`, que reescreve só
 * o `<b>` a cada segundo — repintar o cartão inteiro por segundo apagaria a barra no meio da animação.
 */
function linhaDoDecaimento(rank) {
  const ate = prazoDoDecaimento(rank);
  if (!ate) return '';
  const txt = textoDoDecaimento(ate);
  const urgente = ate - agoraDoServidor() < 3 * 3_600_000 ? ' urgente' : '';
  const dica = escapar(t('pvp.decaiDica', { horas: PVP_DECAIMENTO_HORAS }));
  return `<div class="pvp-cartao-decai${urgente}" title="${dica}"${txt ? '' : ' data-zerou="1"'}>${
    txt
      ? t('pvp.decaiEm', { tempo: `<b class="pvp-decai-relogio">${txt}</b>` })
      : t('pvp.decaindo')
  }</div>`;
}

/** O cartão grande: emblema, rank, barra e o cartaz de vitórias. */
function cartaoDeRank(rank) {
  if (!rank) return `<div class="pvp-cartao pvp-cartao-vazio">${t('pvp.carregando')}</div>`;
  const posicionamentoRestante =
    (estado.pvpRegras?.posicionamento ?? PVP_PARTIDAS_POSICIONAMENTO) - (rank.partidas ?? 0);

  if (posicionando(rank)) {
    const feitas = rank.partidas ?? 0;
    const total = estado.pvpRegras?.posicionamento ?? PVP_PARTIDAS_POSICIONAMENTO;
    return `
      <div class="pvp-cartao pvp-cartao-pos">
        ${emblemaDoRank(rank, 'pvp-emblema-grande')}
        <div class="pvp-cartao-info">
          <div class="pvp-cartao-rank">${t('pvp.naoClassificado')}</div>
          <div class="pvp-cartao-sub">${t('pvp.posicionamentoFaltam', { n: posicionamentoRestante })}</div>
          <div class="pvp-barra pvp-barra-pos">
            <i style="width:${Math.round((feitas / total) * 100)}%"></i>
            <span class="pvp-barra-txt">${feitas} / ${total}</span>
          </div>
          <div class="pvp-cartao-wl">
            ${t('pvp.vitDerr', { v: num(rank.vitorias ?? 0), d: num(rank.derrotas ?? 0) })}
          </div>
        </div>
      </div>`;
  }

  const barra = rank.progresso == null ? 100 : Math.round(rank.progresso * 100);
  const faltam = rank.ate != null ? rank.ate - rank.pontos : null;
  const total = (rank.vitorias ?? 0) + (rank.derrotas ?? 0);
  const taxa = total ? Math.round(((rank.vitorias ?? 0) / total) * 100) : 0;

  return `
    <div class="pvp-cartao">
      ${emblemaDoRank(rank, 'pvp-emblema-grande')}
      <div class="pvp-cartao-info">
        <div class="pvp-cartao-rank">
          ${escapar(rotuloDoRank(rank))} ${selosDeSequencia(rank.sequencia)}
        </div>
        <div class="pvp-cartao-pr"><b>${num(rank.pontos)}</b> ${t('pvp.pr')}</div>
        <div class="pvp-barra">
          <i style="width:${barra}%"></i>
          <span class="pvp-barra-txt">${
            rank.ate == null
              ? t('pvp.semTeto')
              : `${num(rank.naFaixa)} / ${num(rank.larguraFaixa)}`
          }</span>
        </div>
        <div class="pvp-cartao-sub">
          ${
            rank.aguardandoVaga
              ? t('pvp.aguardandoVaga', {
                n: num(rank.faltamPosicoes ?? 0),
                vagas: PVP_VAGAS_MESTRE,
              })
              : faltam != null
                ? t('pvp.faltamPara', {
                  n: num(faltam),
                  rank: escapar(rotuloDoRank(rankDePontos(rank.ate))),
                })
                : t('pvp.noTopo', {
                  vagas: rank.tierId === 'challenger' ? PVP_VAGAS_CHALLENGER : PVP_VAGAS_MESTRE,
                })
          }
        </div>
        ${linhaDoDecaimento(rank)}
        <div class="pvp-cartao-wl">
          ${t('pvp.vitDerr', { v: num(rank.vitorias ?? 0), d: num(rank.derrotas ?? 0) })}
          <span class="pvp-cartao-taxa">${taxa}%</span>
          ${
            estado.pvpPosicao
              ? `<span class="pvp-cartao-pos">${t('pvp.posicaoDe', {
                pos: num(estado.pvpPosicao), total: num(estado.pvpTotalClassificados),
              })}</span>`
              : ''
          }
          ${rank.escudo > 0 ? `<span class="pvp-cartao-escudo" title="${t('pvp.escudoDica')}">🛡</span>` : ''}
        </div>
      </div>
    </div>`;
}

/**
 * Os cinco slots da equipe. Vazio é um convite, não um erro.
 *
 * O card mostra o que decide uma partida — nível, ⚔, tipos e a fileira de selos (qualidade,
 * IV, nota, potência), a mesma do Depot e do Mercado. É a informação que o jogador precisa
 * para olhar a equipe e saber se ela é boa, sem abrir cinco fichas.
 *
 * A ORDEM (1..5) é a de entrada na luta, e por isso ela é o elemento mais forte do card em
 * vez de um número miúdo no canto: quem abre a briga é o 1, e trocar a ordem é uma decisão
 * de verdade. Clicar no card abre a ficha completa.
 */
function blocoDaEquipePvp(time) {
  const slots = [];
  for (let i = 0; i < PVP_TIME_MAX; i++) {
    const p = time[i];
    slots.push(
      p
        ? `<div class="pvp-slot cheio" data-slot="${i}" data-pk="${p.id}"
             role="button" tabindex="0" title="${escapar(t('pvp.verFicha'))}">
             <span class="pvp-slot-ordem">${i + 1}</span>
             <span class="pvp-slot-sprite"></span>
             <span class="pvp-slot-nome">${p.shiny ? prefixoShiny() : ''}${escapar(p.nome)}</span>
             <span class="pvp-slot-nv">${t('painel.nivelCurto')}${p.level} · ⚔ ${num(p.poder ?? 0)}</span>
             <span class="pvp-slot-linha3">
               <span class="pvp-slot-tipos">${selosDeTipo(p.tipos)}</span>
               <span class="pvp-slot-selos">${selosAtributos(p, { compacto: true })}</span>
             </span>
           </div>`
        : `<div class="pvp-slot vago" data-slot="${i}"><span class="pvp-slot-ordem">${i + 1}</span></div>`,
    );
  }
  return `
    <div class="pvp-equipe">
      <div class="pvp-sec-cab">
        <h3>${t('pvp.equipeTitulo')}</h3>
        <button type="button" class="pvp-btn pvp-btn-peq" id="pvp-editar-time">${t('pvp.editarEquipe')}</button>
      </div>
      <p class="pvp-sec-nota">${t('pvp.equipeNota', { max: PVP_TIME_MAX })}</p>
      <div class="pvp-slots">${slots.join('')}</div>
      ${
        time.length && time.length < PVP_TIME_MAX
          ? `<p class="pvp-aviso-leve">${t('pvp.equipeIncompleta', { n: time.length, max: PVP_TIME_MAX })}</p>`
          : ''
      }
    </div>`;
}

// ------------------------------------------------- o armário de formações
//
// Até `PVP_FORMACOES_MAX` equipes salvas com nome e placar, trocadas com um clique. A regra (o
// placar é da ESCALAÇÃO exata, na ordem; trocar a escalação zera; só o dono vê) está no cabeçalho
// de `shared/pvp-formacoes.mjs`. Aqui é só a tela: o servidor confere tudo de novo.

/** O aviso de sucesso de cada ação do armário. O nome é do jogador: vai escapado (o toast é HTML). */
function textoDaFormacaoOk(ok) {
  const nome = escapar(ok.nome ?? '');
  if (ok.acao === 'usar') {
    return ok.faltaram > 0
      ? t('pvp.formUsadaFaltaram', { nome, n: ok.faltaram })
      : t('pvp.formUsada', { nome });
  }
  if (ok.acao === 'renomear') return t('pvp.formRenomeada', { nome });
  if (ok.acao === 'apagar') return t('pvp.formApagada');
  return t('pvp.formSalva', { nome });
}

/** "62%" verde, vermelho ou neutro — a cor responde "essa funciona?" antes de o número ser lido. */
const classeDaTaxa = (taxa) => (taxa >= 55 ? 'boa' : taxa <= 45 ? 'ruim' : '');

/** O placar de uma formação: a taxa grande, V/D ao lado e a barra. Sem partida, diz isso. */
function placarDaFormacao(f) {
  const taxa = taxaDaFormacao(f);
  const dica = escapar(t('pvp.formPlacarDica', { v: num(f.v), d: num(f.d), cv: num(f.cv), cd: num(f.cd) }));
  if (taxa == null) return `<div class="pvp-form-placar" title="${dica}"><span class="pvp-form-semjogo">${t('pvp.formSemPartidas')}</span></div>`;
  return `
    <div class="pvp-form-placar" title="${dica}">
      <b class="pvp-form-pct ${classeDaTaxa(taxa)}">${taxa}%</b>
      <span class="pvp-form-vd">${t('pvp.formVD', { v: num(f.v + f.cv), d: num(f.d + f.cd) })}</span>
      <span class="pvp-form-barra" aria-hidden="true"><i style="width:${taxa}%"></i></span>
    </div>`;
}

function cardDaFormacao(f, idsTime) {
  const emUso = mesmaEscalacao(f.ids, idsTime);
  // A escalação na ordem: o 1º abre a luta. Os sprites entram em `ligarFormacoes`.
  const pks = f.ids.map((id) => `<span class="pvp-form-pk" data-pk="${id}"></span>`).join('');
  // Madeira (`btn-apagado`) para as três secundárias: o roxo da aba fica para "Procurar partida"
  // e o "Usar" — as ações que mudam o que vai lutar.
  const ico = (attr, icone, rotulo, extra = '') =>
    `<button type="button" class="pvp-btn pvp-btn-peq btn-apagado pvp-form-ico${extra}" ${attr}="${f.slot}" title="${escapar(rotulo)}" aria-label="${escapar(rotulo)}">${dlgIcone(icone, 14)}</button>`;
  return `
    <div class="pvp-form${emUso ? ' em-uso' : ''}" data-slot="${f.slot}">
      <div class="pvp-form-topo">
        <b class="pvp-form-nome">${escapar(f.nome)}</b>
        ${emUso ? `<span class="pvp-form-selo">${dlgIcone('check', 11)}${t('pvp.formEmUso')}</span>` : ''}
      </div>
      <div class="pvp-form-pks">${pks}</div>
      ${placarDaFormacao(f)}
      <div class="pvp-form-acoes">
        <button type="button" class="pvp-btn pvp-btn-peq pvp-form-usar" data-form-usar="${f.slot}"${emUso ? ' disabled' : ''}>${t(emUso ? 'pvp.formEmUso' : 'pvp.formUsar')}</button>
        ${ico('data-form-trocar', 'volta', t('pvp.formAtualizar'))}
        ${ico('data-form-editar', 'lapis', t('pvp.formEditar'))}
        ${ico('data-form-apagar', 'lixeira', t('pvp.formApagar'), ' perigo')}
      </div>
    </div>`;
}

/**
 * O bloco do armário, logo abaixo da equipe: as formações salvas e um botão para guardar a equipe
 * atual na primeira vaga. Vagas vazias NÃO são desenhadas uma a uma — cinco cards de "vazio" para
 * quem nunca salvou nada seriam meia tela de nada; o contador "2/5" já diz quanto cabe.
 */
function blocoDasFormacoes(time) {
  const lista = estado.pvpFormacoes;
  const cheio = (lista?.length ?? 0) >= PVP_FORMACOES_MAX;
  let rodape = '';
  if (lista != null) {
    if (cheio) rodape = `<p class="pvp-aviso-leve">${t('pvp.formCheio', { max: PVP_FORMACOES_MAX })}</p>`;
    else {
      rodape = `
        <button type="button" class="pvp-btn pvp-btn-peq btn-apagado pvp-form-nova" id="pvp-form-nova"${time.length ? '' : ' disabled'}>${t('pvp.formSalvarAtual')}</button>
        ${time.length ? '' : `<p class="pvp-sec-nota">${t('pvp.formMonteAntes')}</p>`}`;
    }
  }
  return `
    <div class="pvp-equipe pvp-forms">
      <div class="pvp-sec-cab">
        <h3>${t('pvp.formTitulo')}</h3>
        ${lista != null ? `<span class="pvp-forms-conta">${lista.length}/${PVP_FORMACOES_MAX}</span>` : ''}
      </div>
      <p class="pvp-sec-nota">${t('pvp.formNota')}</p>
      ${lista == null
        ? `<div class="pvp-forms-vazio">${t('pvp.formCarregando')}</div>`
        : `<div class="pvp-forms-lista">${lista.map((f) => cardDaFormacao(f, estado.pvpTime ?? [])).join('')}</div>`}
      ${rodape}
    </div>`;
}

/** A primeira vaga livre do armário, ou `null`. */
function vagaLivreDeFormacao() {
  const usados = new Set((estado.pvpFormacoes ?? []).map((f) => f.slot));
  for (let s = 1; s <= PVP_FORMACOES_MAX; s++) if (!usados.has(s)) return s;
  return null;
}

/**
 * Manda uma ação do armário, uma de cada vez. A trava some na resposta (`formacaoOk`/`formacaoRecusa`)
 * ou em 8 s — resposta perdida não pode deixar os botões mortos.
 */
function enviarFormacao(pacote) {
  if (estado.pvpFormacaoEnviando && Date.now() - estado.pvpFormacaoEnviando < 8000) return;
  estado.pvpFormacaoEnviando = Date.now();
  enviar(pacote);
}

/**
 * A caixa do NOME do "salvar a equipe atual": a confirmação da casa com um campo dentro, conferido
 * a cada tecla pelo MESMO validador do servidor — o botão só acende com um nome que vai ser aceito.
 * (Renomear é no editor da formação, `abrirEditorDeFormacao`, junto com a escalação.)
 */
function pedirNomeDeFormacao({ titulo, texto = '', inicial = '', rotuloSim, aoConfirmar }) {
  let valor = inicial;
  confirmar({
    titulo,
    rotuloSim,
    texto: `
      ${texto ? `<p class="pvp-form-dlg-txt">${texto}</p>` : ''}
      <label class="pvp-form-dlg-campo">
        <span>${t('pvp.formNomeRotulo')}</span>
        <input type="text" id="pvp-form-nome" maxlength="${FORMACAO_NOME_MAX}" autocomplete="off"
               spellcheck="false" value="${escapar(inicial)}">
      </label>
      <p class="pvp-form-dlg-dica" id="pvp-form-dica"></p>`,
    montar: (corpo) => {
      const campo = corpo.querySelector('#pvp-form-nome');
      const dica = corpo.querySelector('#pvp-form-dica');
      const sim = $('#confirmar-sim');
      const conferir = () => {
        valor = campo.value;
        const v = validarNomeFormacao(valor);
        sim.disabled = !v.ok;
        const ruim = !v.ok && valor.trim() !== '';
        dica.textContent = ruim ? t(v.erro, { max: FORMACAO_NOME_MAX }) : t('pvp.formNomeDica', { max: FORMACAO_NOME_MAX });
        dica.classList.toggle('ruim', ruim);
      };
      campo.oninput = conferir;
      campo.onkeydown = (ev) => {
        if (ev.key === 'Enter' && !sim.disabled) sim.click();
      };
      conferir();
      setTimeout(() => { campo.focus(); campo.select(); }, 0);
    },
    aoConfirmar: () => {
      const v = validarNomeFormacao(valor);
      if (v.ok) aoConfirmar(v.nome);
    },
  });
}

/** Os ids da equipe de PvP que ainda estão na coleção, na ordem — o que "salvar a equipe atual" grava. */
const idsDoTimePvp = () => pokemonsDoTimePvp().map((p) => p.id);

function novaFormacao() {
  const slot = vagaLivreDeFormacao();
  const ids = idsDoTimePvp();
  if (!slot || !ids.length) return;
  pedirNomeDeFormacao({
    titulo: t('pvp.formNovaTitulo'),
    texto: t('pvp.formNovaTexto', { n: ids.length }),
    inicial: t('pvp.formNomePadrao', { n: slot }),
    rotuloSim: t('pvp.formSalvarBt'),
    aoConfirmar: (nome) => enviarFormacao({ t: 'pvp.formacao.salvar', slot, nome, pokemonIds: ids }),
  });
}

const formacaoDoSlot = (slot) => (estado.pvpFormacoes ?? []).find((f) => f.slot === slot) ?? null;

/** Liga os sprites e os botões do armário — chamado pelo `ligarRanqueado` a cada repintura. */
function ligarFormacoes(host) {
  const meus = new Map((estado.eu?.pokemons ?? []).map((p) => [p.id, p]));
  for (const el of host.querySelectorAll('.pvp-form-pk[data-pk]')) {
    const pk = meus.get(Number(el.dataset.pk));
    if (!pk) {
      // Vendido ou anunciado desde que a formação foi salva: o buraco aparece, com o motivo.
      el.classList.add('sumiu');
      el.textContent = '?';
      el.title = t('pvp.formPkSumiu');
      continue;
    }
    el.appendChild(spritePokemon(pk, 30));
    el.title = `${pk.shiny ? '★ ' : ''}${nomeExibidoPokemon(pk)} · ${t('painel.nivelCurto')}${pk.level}`;
    el.onclick = () => abrirFichaDoPokemon(pk);
  }
  const nova = host.querySelector('#pvp-form-nova');
  if (nova) nova.onclick = novaFormacao;
  for (const bt of host.querySelectorAll('[data-form-usar]')) {
    bt.onclick = () => {
      bt.disabled = true;
      enviarFormacao({ t: 'pvp.formacao.usar', slot: Number(bt.dataset.formUsar) });
    };
  }
  for (const bt of host.querySelectorAll('[data-form-editar]')) {
    bt.onclick = () => abrirEditorDeFormacao(Number(bt.dataset.formEditar));
  }
  for (const bt of host.querySelectorAll('[data-form-trocar]')) {
    bt.onclick = () => {
      const f = formacaoDoSlot(Number(bt.dataset.formTrocar));
      const ids = idsDoTimePvp();
      if (!f) return;
      if (!ids.length) return toast(t('pvp.formMonteAntes'));
      if (mesmaEscalacao(f.ids, ids)) return toast(t('pvp.formJaIgual', { nome: escapar(f.nome) }));
      confirmar({
        titulo: t('pvp.formAtualizarTitulo'),
        texto: `<p class="pvp-form-dlg-txt">${t('pvp.formAtualizarTexto', { nome: escapar(f.nome), n: ids.length })}</p>`,
        rotuloSim: t('pvp.formAtualizarBt'),
        aoConfirmar: () => enviarFormacao({ t: 'pvp.formacao.salvar', slot: f.slot, nome: f.nome, pokemonIds: ids }),
      });
    };
  }
  for (const bt of host.querySelectorAll('[data-form-apagar]')) {
    bt.onclick = () => {
      const f = formacaoDoSlot(Number(bt.dataset.formApagar));
      if (!f) return;
      confirmar({
        titulo: t('pvp.formApagarTitulo'),
        texto: `<p class="pvp-form-dlg-txt">${t('pvp.formApagarTexto', { nome: escapar(f.nome) })}</p>`,
        rotuloSim: t('pvp.formApagar'),
        tom: 'perigo',
        aoConfirmar: () => enviarFormacao({ t: 'pvp.formacao.apagar', slot: f.slot }),
      });
    };
  }
}

/** O botão da fila, com o motivo da recusa escrito no próprio rótulo. */
function blocoDaFila(rank, nivelMin, time) {
  const na = !!estado.pvpFila?.na;
  const nivelOk = (estado.eu?.level ?? 0) >= nivelMin;
  const cooldown = msDeEsperaEntrePartidas();

  let rotulo = t('pvp.procurar');
  // `motivo` vai para o `dataset` do botão: é como `tiqueFilaNoModal` sabe que o bloqueio é
  // a espera (a única coisa que passa sozinha) e não o nível ou a equipe vazia.
  let motivo = '';
  if (na) rotulo = t('pvp.cancelarBusca');
  else if (!nivelOk) { rotulo = t('pvp.semNivel', { n: nivelMin }); motivo = 'nivel'; }
  else if (!time.length) { rotulo = t('pvp.semEquipe'); motivo = 'time'; }
  else if (cooldown > 0) { rotulo = t('pvp.aguardeSeg', { s: Math.ceil(cooldown / 1000) }); motivo = 'espera'; }

  return `
    <div class="pvp-fila-bloco${na ? ' buscando' : ''}">
      <button type="button" class="pvp-btn pvp-btn-fila${na ? ' cancelar' : ''}"
        id="pvp-fila-bt" data-motivo="${motivo}" ${motivo ? 'disabled' : ''}>${rotulo}</button>
      ${blocoFilaAuto()}
      ${botaoPremiosPvp('pvp-premios-ranqueado')}
      ${blocoTelaBatalha()}
      ${
        na
          ? `<div class="pvp-fila-estado">
               <div class="pvp-fila-linha">
                 <span class="pvp-fila-girando" aria-hidden="true"></span>
                 <span id="pvp-fila-relogio">0:00</span>
               </div>
               <div class="pvp-fila-faixa" id="pvp-fila-faixa-modal"></div>
               <div class="pvp-fila-quantos">${t('pvp.naFilaAgora', { n: estado.pvpFila?.tamanho ?? 1 })}</div>
               <p class="pvp-sec-nota">${t('pvp.podeMinimizar')}</p>
             </div>`
          : `<p class="pvp-sec-nota">${t('pvp.comoFunciona')}</p>`
      }
    </div>`;
}

/**
 * A fila automática — benefício de VIP.
 *
 * Ela existe por causa da janela de busca lenta: procurar partida pode levar meia hora, e
 * uma espera dessas só é aceitável se for "ligar e esquecer". Sem VIP o interruptor aparece
 * assim mesmo, com cadeado — esconder um benefício é a melhor forma de ninguém saber que
 * ele existe. Quem recusa de verdade é o servidor (`auto.set`).
 */
/**
 * A escolha de como a batalha aparece. Três botões, um ligado.
 *
 * Fica ao lado da fila automática de propósito: é ela que cria o problema que estas opções
 * resolvem — com a fila ligada chega uma partida a cada poucos minutos, e um modal de tela
 * cheia por cima do farm a cada uma faz o jogador desligar a FILA em vez do aviso.
 *
 * Não tem cadeado de VIP: é preferência de tela, não benefício.
 */
function blocoTelaBatalha() {
  const modo = telaDeBatalha();
  const op = (v, rotulo, dica) => `
    <label class="pvp-tela-op${modo === v ? ' on' : ''}" title="${escapar(dica)}">
      <input type="radio" name="pvp-tela" value="${v}" ${modo === v ? 'checked' : ''}>
      <span>${escapar(rotulo)}</span>
    </label>`;
  return `
    <div class="pvp-tela-opcoes">
      <div class="pvp-tela-titulo">${t('pvp.telaTitulo')}</div>
      <div class="pvp-tela-lista" id="pvp-tela-lista">
        ${op(TELA_BATALHA.COMPLETA, t('pvp.telaCompleta'), t('pvp.telaCompletaDica'))}
        ${op(TELA_BATALHA.MINI, t('pvp.telaMini'), t('pvp.telaMiniDica'))}
        ${op(TELA_BATALHA.OFF, t('pvp.telaOff'), t('pvp.telaOffDica'))}
      </div>
    </div>`;
}

function blocoFilaAuto() {
  const vip = !!estado.eu?.loja?.vip;
  const ligado = !!estado.eu?.automation?.pvpAutoFila;
  return `
    <label class="pvp-auto${vip ? '' : ' travado'}" title="${escapar(t(vip ? 'pvp.autoFilaDica' : 'pvp.autoFilaVip'))}">
      <input type="checkbox" id="pvp-auto-fila" ${ligado ? 'checked' : ''} ${vip ? '' : 'disabled'}>
      <span class="pvp-auto-txt">${t('pvp.autoFila')}</span>
      ${vip ? '<span class="pvp-auto-selo">VIP</span>' : '<span class="pvp-auto-cadeado">🔒 VIP</span>'}
    </label>`;
}

function blocoDaLadder() {
  const linhas = estado.pvpLadder ?? [];
  if (!linhas.length) {
    return `<div class="pvp-lista-bloco">
      <h3>${t('pvp.tabelaTitulo')}</h3>
      <p class="vazio-msg">${t('pvp.tabelaVazia')}</p>
    </div>`;
  }
  const meu = estado.eu?.nick;
  return `
    <div class="pvp-lista-bloco">
      <h3>${t('pvp.tabelaTitulo')}</h3>
      <div class="pvp-ladder">
        ${linhas.map((l) => `
          <div class="pvp-lad-linha${l.nick === meu ? ' eu' : ''}" role="button" tabindex="0"
               data-perfil="${escapar(l.nick ?? '')}" title="${escapar(t('pvp.verEquipe'))}">
            <span class="pvp-lad-pos">${l.pos}</span>
            <img class="pvp-lad-emblema" src="${iconeDoRank(l.tierId)}" alt="" loading="lazy">
            <span class="pvp-lad-nick">${escapar(l.nick ?? '')}</span>
            <span class="pvp-lad-rank">${escapar(rotuloDoRank(l))}</span>
            <span class="pvp-lad-pr">${num(l.pontos)}</span>
            <span class="pvp-lad-wl">${l.vitorias}V/${l.derrotas}D</span>
          </div>`).join('')}
      </div>
    </div>`;
}

function blocoDoHistorico() {
  const linhas = estado.pvpHistorico ?? [];
  if (!linhas.length) {
    return `<div class="pvp-lista-bloco">
      <h3>${t('pvp.historicoTitulo')}</h3>
      <p class="vazio-msg">${t('pvp.historicoVazio')}</p>
    </div>`;
  }
  // A linha ABRE a partida ali mesmo (a equipe do oponente e o resumo da luta), em vez de levar
  // a outra tela. É a lista que o jogador usa para estudar quem ele enfrentou — e, ao contrário
  // da Tabela, ela não se reordena sozinha: quem estava ali continua ali.
  const aberta = estado.pvpHistAberta;
  const temAberta = linhas.some((l) => l.id === aberta);
  return `
    <div class="pvp-lista-bloco">
      <h3>${t('pvp.historicoTitulo')}</h3>
      <div class="pvp-hist${temAberta ? ' tem-aberta' : ''}">
        ${linhas.map((l) => {
          const abre = l.id === aberta;
          return `
          <button type="button" class="pvp-hist-linha ${l.venci ? 'venci' : 'perdi'}${abre ? ' aberta' : ''}"
                  data-partida="${Number(l.id)}" aria-expanded="${abre}" title="${escapar(t('pvp.histAbrirDica'))}">
            <span class="pvp-hist-res">${t(l.venci ? 'pvp.vCurto' : 'pvp.dCurto')}</span>
            <span class="pvp-hist-nick">${escapar(l.oponente)}</span>
            <span class="pvp-hist-delta ${l.delta >= 0 ? 'up' : 'down'}">${l.delta >= 0 ? '+' : ''}${l.delta}</span>
            <span class="pvp-hist-quando">${quandoFoi(l.criadoEm)}</span>
            <span class="pvp-hist-seta" aria-hidden="true">▾</span>
          </button>${abre ? htmlFichaDoHistorico(l) : ''}`;
        }).join('')}
      </div>
    </div>`;
}

/**
 * As fichas já pedidas das partidas do histórico, por id (`pvp.partida.ficha` no sim).
 *
 * Moram fora do `estado` e sobrevivem ao repinte: a aba inteira é redesenhada a cada pacote de
 * PvP (fila, tabela, resultado), e sem isto a linha aberta fecharia no meio da leitura — o mesmo
 * problema que fazia a Tabela perder quem o jogador estava olhando. Uma ficha com mais de um
 * minuto é pedida de novo ao reabrir: a equipe ATUAL do oponente é a parte que envelhece.
 */
const fichasPvpHist = new Map();
const FICHA_PVP_HIST_VALIDADE_MS = 60_000;
/** Depois de abrir (ou de a ficha chegar), o repinte traz a ficha para dentro da tela uma vez. */
let rolarParaFichaPvp = false;

function alternarPartidaDoHistorico(id) {
  if (estado.pvpHistAberta === id) {
    estado.pvpHistAberta = null;
    pintarRanqueado();
    return;
  }
  estado.pvpHistAberta = id;
  const f = fichasPvpHist.get(id);
  if (!f || f.erro || Date.now() - f.recebidaEm > FICHA_PVP_HIST_VALIDADE_MS) {
    // A que deu erro some antes do pedido novo: a linha mostra "carregando", e não o erro velho.
    if (f?.erro) fichasPvpHist.delete(id);
    enviar({ t: 'pvp.partida.ficha', id });
  }
  rolarParaFichaPvp = true;
  pintarRanqueado();
}

/**
 * O que abre embaixo da linha: a equipe de PvP que o oponente tem AGORA e o resumo da partida.
 *
 * As duas, e não só a da partida: a ficha gravada guarda apenas quem ENTROU em campo, e quem
 * venceu rápido aparece com dois pokémon — que o jogador leria como "o time dele é esse". Nas
 * duas a ordem é a da Pokédex, nunca a de entrada (a regra é do servidor; ver `vistaDaPartida`).
 */
function htmlFichaDoHistorico(l) {
  const id = `pvp-hf-${Number(l.id)}`;
  const f = fichasPvpHist.get(l.id);
  if (!f) return `<div class="pvp-hist-ficha" id="${id}"><p class="pvp-hf-msg">${t('pvp.hf.carregando')}</p></div>`;
  if (f.erro || f.vazia) {
    return `<div class="pvp-hist-ficha" id="${id}"><p class="pvp-hf-msg">${t(f.erro ? 'pvp.hf.erro' : 'pvp.hf.vazia')}</p></div>`;
  }
  const nickCru = f.oponente?.nick ?? l.oponente ?? '';
  const nick = escapar(nickCru);
  const equipe = f.equipeAtual ?? [];
  const cards = equipe.map((pk, i) => `
        <button type="button" class="pvp-hf-card" data-hf-eq="${i}" title="${escapar(pk.nome ?? '')}">
          <span class="pvp-hf-spr" data-hf-sp="eq:${i}"></span>
          <span class="pvp-hf-card-nome">${pk.shiny ? '✨ ' : ''}${escapar(pk.nome ?? '—')}</span>
          <span class="pvp-hf-card-nv">${t('painel.nivelCurto')} <b>${num(pk.level ?? 1)}</b></span>
        </button>`).join('');

  const lado = (titulo, ladoF, chave) => {
    if (!ladoF?.pks?.length) return '';
    const max = Math.max(1, ...ladoF.pks.map((x) => x.dano));
    return `
        <div class="pvp-hf-lado">
          <h5>${titulo}</h5>
          ${ladoF.pks.map((pk, i) => `
            <div class="pvp-hf-pk${pk.caiu ? ' caiu' : ''}">
              <span class="pvp-hf-spr" data-hf-sp="${chave}:${i}"></span>
              <span class="pvp-hf-pk-nome">${pk.shiny ? '✨ ' : ''}${escapar(pk.nome)}
                <small>${t('painel.nivelCurto')} ${num(pk.nivel)}${pk.caiu ? ` · ${t('pvp.hf.caiu')}` : ''}</small></span>
              <span class="pvp-hf-pk-dano" title="${escapar(t('pvp.hf.danoDica', { dano: num(pk.dano), abates: num(pk.abates) }))}">${numCurto(pk.dano)}<i style="--w:${Math.round((pk.dano / max) * 100)}%"></i></span>
            </div>`).join('')}
        </div>`;
  };
  const partida = f.ele?.pks?.length && f.eu?.pks?.length
    ? `<div class="pvp-hf-lados">${lado(nick, f.ele, 'ele')}${lado(t('pvp.hf.voce'), f.eu, 'eu')}</div>
       <p class="pvp-hf-nota">${t('pvp.hf.soQuemEntrou')}</p>`
    : `<p class="pvp-hf-msg">${t('pvp.hf.semFicha')}</p>`;
  const resumo = [
    t(f.venci ? 'pvp.hf.venceu' : 'pvp.hf.perdeu'),
    f.duracaoMs ? duracaoCurta(f.duracaoMs) : '',
    f.motivo === 'tempo' ? t('pvp.hf.porTempo') : '',
  ].filter(Boolean).join(' · ');

  return `
    <div class="pvp-hist-ficha" id="${id}">
      <section class="pvp-hf-sec">
        <div class="pvp-hf-cab"><b>${t('pvp.hf.equipeAtual', { nick })}</b><span>${t('pvp.hf.agora')}</span></div>
        ${equipe.length ? `<div class="pvp-hf-equipe">${cards}</div>` : `<p class="pvp-hf-msg">${t('pvp.hf.semEquipe', { nick })}</p>`}
      </section>
      <section class="pvp-hf-sec">
        <div class="pvp-hf-cab"><b>${t('pvp.hf.nestaPartida')}</b><span>${escapar(resumo)}</span></div>
        ${partida}
      </section>
      <div class="pvp-hf-acoes">
        <button type="button" class="pvp-btn pvp-btn-peq" data-hf-perfil="${nick}">${t('pvp.hf.perfil')}</button>
        <a class="pvp-hf-link" href="/tracker/j/${encodeURIComponent(nickCru)}" target="_blank" rel="noopener noreferrer">${t('pvp.hf.tracker')} ↗</a>
      </div>
    </div>`;
}

/** Os sprites e os cliques da ficha aberta — depois de o HTML estar no DOM, como o resto da aba. */
function ligarFichaDoHistorico(host) {
  const f = estado.pvpHistAberta != null ? fichasPvpHist.get(estado.pvpHistAberta) : null;
  if (!f || f.erro || f.vazia) return;
  for (const el of host.querySelectorAll('[data-hf-sp]')) {
    const [grupo, i] = el.dataset.hfSp.split(':');
    const pk = grupo === 'eq' ? f.equipeAtual?.[Number(i)] : f[grupo]?.pks?.[Number(i)];
    if (!pk) continue;
    // A equipe atual vem no pacote de ficha do perfil (com `speciesId`); a da partida, no da
    // ficha gravada (com a espécie em `id`). `spritePokemon` resolve o desenho pela espécie.
    el.appendChild(grupo === 'eq'
      ? spritePokemon(pk, 40)
      : spritePokemon({ speciesId: pk.id, nome: pk.nome, looktype: pk.looktype, shiny: !!pk.shiny }, 30));
  }
  for (const bt of host.querySelectorAll('[data-hf-eq]')) {
    const pk = f.equipeAtual?.[Number(bt.dataset.hfEq)];
    if (pk) bt.onclick = () => abrirFichaDoPokemon(pk);
  }
  const perfil = host.querySelector('[data-hf-perfil]');
  if (perfil) perfil.onclick = () => pedirPerfil(perfil.dataset.hfPerfil);
}

/** Liga os botões e injeta os sprites, depois de o HTML estar no DOM. */
function ligarRanqueado() {
  for (const card of document.querySelectorAll('#pvp-painel-ranqueado .pvp-slot.cheio')) {
    const p = (estado.eu?.pokemons ?? []).find((x) => x.id === Number(card.dataset.pk));
    if (!p) continue;
    card.querySelector('.pvp-slot-sprite')?.appendChild(spritePokemon(p, 40));
    const abrir = () => abrirFichaDoPokemon(p);
    card.onclick = abrir;
    // Teclado também: o card é `role="button"`, e um botão que só responde ao mouse mente
    // sobre o que é.
    card.onkeydown = (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        abrir();
      }
    };
  }
  $('#pvp-editar-time')?.addEventListener('click', abrirSeletorDeTimePvp);
  $('#pvp-premios-ranqueado')?.addEventListener('click', abrirPremiosRanqueado);
  const bt = $('#pvp-fila-bt');
  if (bt) {
    bt.onclick = () => {
      if (estado.pvpFila?.na) return enviar({ t: 'pvp.fila.sair' });
      enviar({ t: 'pvp.fila.entrar' });
    };
  }
  const auto = $('#pvp-auto-fila');
  // A escolha de tela é local: grava no `localStorage` e repinta só os três botões. Não manda
  // nada ao servidor — ele não tem o que fazer com isso.
  const telaLista = $('#pvp-tela-lista');
  if (telaLista) {
    telaLista.onchange = (ev) => {
      const r = ev.target.closest('input[name="pvp-tela"]');
      if (!r) return;
      definirTelaDeBatalha(r.value);
      for (const l of telaLista.querySelectorAll('.pvp-tela-op')) {
        l.classList.toggle('on', l.querySelector('input')?.value === r.value);
      }
    };
  }

  // A TABELA abre a ficha do treinador — que agora traz a equipe de PvP dele. Era a única
  // lista de nicks do jogo em que clicar não fazia nada, e logo a que mais convida ao clique:
  // quem olha o topo da tabela está perguntando com o que aquela gente ganha.
  for (const linha of document.querySelectorAll('#pvp-painel-ranqueado .pvp-lad-linha[data-perfil]')) {
    const abrir = () => {
      const nick = linha.dataset.perfil;
      if (nick) pedirPerfil(nick);
    };
    linha.onclick = abrir;
    linha.onkeydown = (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); abrir(); }
    };
  }
  // O HISTÓRICO abre a partida ali mesmo (ver `blocoDoHistorico`). É `<button>`, então o teclado
  // já vem de graça.
  const host = $('#pvp-painel-ranqueado');
  if (host) {
    for (const bt of host.querySelectorAll('.pvp-hist-linha[data-partida]')) {
      bt.onclick = () => alternarPartidaDoHistorico(Number(bt.dataset.partida));
    }
    ligarFichaDoHistorico(host);
    ligarFormacoes(host);
  }

  if (auto) {
    auto.onchange = () => {
      // A automação viaja pelo MESMO `auto.set` do resto (auto-revive, auto-poção): é uma
      // preferência do jogador em `players.automation`, e não um comando de PvP. E vai pelo
      // `mandarAutomacao`, que espalha o estado INTEIRO antes do patch — mandar só um campo
      // apagaria os outros no flush seguinte.
      mandarAutomacao({ pvpAutoFila: auto.checked });
    };
  }
  tiqueFilaNoModal();
}

/**
 * O relógio da fila DENTRO do modal, a 4 fps.
 *
 * Separado do pill do palco porque os dois vivem em momentos diferentes — o pill existe com o
 * modal fechado, e este só com ele aberto —, mas os dois leem o mesmo `desde` do servidor.
 */
function tiqueFilaNoModal() {
  if (estado.modalAberto !== 'pvp' || estado.pvpAba !== 'ranqueado') return;
  const bt = $('#pvp-fila-bt');
  if (!bt) return;

  if (!estado.pvpFila?.na) {
    // Fora da fila só há uma coisa que muda sozinha: a espera entre partidas vencendo. O
    // repinte acontece UMA vez, na virada — repintar a cada quarto de segundo arrancaria o
    // foco do teclado e reiniciaria a rolagem das listas ao lado.
    const esperando = msDeEsperaEntrePartidas() > 0;
    if (bt.disabled && !esperando && bt.dataset.motivo === 'espera') pintarRanqueado();
    return;
  }

  const rel = $('#pvp-fila-relogio');
  if (rel) rel.textContent = relogioDeFila(msNaFila());
  const faixa = $('#pvp-fila-faixa-modal');
  if (faixa) faixa.textContent = t('pvp.buscandoEm', { faixa: faixaDaBusca() });
}
setInterval(tiqueFilaNoModal, 250);

// ------------------------------------------------ a folha de escolher EQUIPE

/**
 * A escolha de uma equipe — PvP Ranqueado e Guerra de Guilds.
 *
 * Era uma lista de linhas com o nome e três números. Agora é a mesma folha da Oferenda e do
 * Campeonato: cards com sprite e a fileira P·IV·Q·N, busca, "só shiny", tipo, IV mínimo,
 * ordenação e o filtro "Local" (Equipe / Depot / Coleção), com a ★ em quem é da Coleção.
 *
 * O clique marca e desmarca; o número no card é a ORDEM em que o pokémon entra em campo. Em cima
 * da grade, a fileira da equipe montada — com as setas para trocar a ordem sem desmarcar e
 * remarcar, e o × para tirar. Nada vai ao servidor antes do "Salvar", que confere tudo de novo.
 *
 * Desenha dentro de `corpo` (uma folha do Mercado, ou o corpo do modal da equipe de guerra) e
 * devolve `{ repintar, pintarBotoes }`. Só a parte de baixo repinta: a busca e os filtros
 * sobrevivem, e o campo de IV reage ao dígito sem perder o foco.
 */
function montarEscolhaDeEquipe(corpo, {
  max,
  idsIniciais,
  filtro,
  // HTML no alto da folha, antes da nota (o nome da formação). Quem passa liga os campos dele
  // depois do `montar` — o repinte nunca mexe nesse pedaço.
  antes = '',
  nota = '',
  // A nota vira faixa com ícone (o `info` do diálogo de jogo); `selos` a troca por pílulas,
  // quando ela é uma lista de regras curtas ("não perde HP", "não ganha XP"…).
  notaIcone = 'interrogacao',
  selos = null,
  contagem,
  extraContagem = null,
  rotuloSalvar,
  rotuloLimpar,
  rotuloCheio,
  salvar,
  salvando = () => false,
  // O "Salvar" só acende quando isto aceita o rascunho (a formação pede nome válido e alguém
  // escalado; a equipe de PvP aceita até vazia, que é como se desmonta a equipe).
  podeSalvar = () => true,
  // Chamado a cada repinte com o rascunho, na ordem — para quem mostra o que muda ao salvar.
  aoMudar = null,
}) {
  const noJogo = () => new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  // Só entra no rascunho o que AINDA existe na coleção: um pokémon vendido no Mercado sai sozinho,
  // em vez de virar uma casa fantasma que o salvar recusaria sem explicação.
  const iniciais = noJogo();
  let sel = [...new Set(idsIniciais ?? [])].filter((id) => iniciais.has(id)).slice(0, max);

  corpo.classList.add('dmpk', 'eqf');
  corpo.classList.remove('pkf-aberta');
  const topo = selos?.length
    ? `<div class="eqf-nota">${dlgSelos(...selos.map((s) => dlgSelo(s.icone, escapar(s.texto), s.tom ?? '')))}</div>`
    : nota ? `<p class="dlg-aviso info eqf-nota">${dlgIcone(notaIcone, 18)}<span>${nota}</span></p>` : '';
  corpo.innerHTML = `
    ${antes}
    ${topo}
    <div class="eqf-cabeca">
      <span class="eqf-conta"></span>
      <span class="eqf-extra"></span>
    </div>
    <div class="eqf-ordem"></div>
    <div class="eqf-casa-barra"></div>
    <div class="dmpk-topo">
      <span class="cm-busca-caixa">${lupa()}<input class="cm-busca eqf-busca" type="search" autocomplete="off"
             maxlength="32" placeholder="${escapar(t('camp.equipeBusca'))}" value="${escapar(filtro.busca ?? '')}"></span>
      <label class="auto-linha dmpk-shiny"><span>${t('amigos.anexarSoShiny')}</span>
        <input type="checkbox" class="eqf-shiny"${filtro.soShiny ? ' checked' : ''}></label>
      <span class="shl-conta eqf-achados"></span>
    </div>
    <div class="dmpk-filtros eqf-filtros"></div>
    <div class="mk-grade cm-pk-escolha-grade cm-rolagem eqf-grade"></div>
    <div class="eqf-rodape">
      <button type="button" class="camp-btn sec camp-btn-mini eqf-limpar">${escapar(rotuloLimpar)}</button>
      <button type="button" class="camp-btn eqf-salvar">${escapar(rotuloSalvar)}</button>
    </div>`;

  const q = (sel_) => corpo.querySelector(sel_);
  const grade = q('.eqf-grade');
  const ordem = q('.eqf-ordem');
  const barraCasa = q('.eqf-casa-barra');
  const btSalvar = q('.eqf-salvar');
  const btLimpar = q('.eqf-limpar');
  // No celular as três setinhas de cada casa não cabem no dedo (a casa tem ~60 px): tocar a
  // casa a MARCA, e as ações dela vão para uma barra única logo abaixo, em tamanho de toque.
  const movel = montagemMovel();
  let casaAtiva = null;

  const alternar = (id) => {
    if (salvando()) return;
    if (casaAtiva === id) casaAtiva = null;
    if (sel.includes(id)) sel = sel.filter((x) => x !== id);
    else if (sel.length >= max) return toast(rotuloCheio);
    else sel = [...sel, id];
    repintar();
  };
  const mover = (id, delta) => {
    const i = sel.indexOf(id);
    const j = i + delta;
    if (i < 0 || j < 0 || j >= sel.length) return;
    const nova = [...sel];
    [nova[i], nova[j]] = [nova[j], nova[i]];
    sel = nova;
    repintar();
  };

  // Com UMA casa só (o Treino), a fileira vira um pedestal largo: o escolhido grande, com nome
  // e nível — cinco colunas para um pokémon deixavam uma caixinha perdida no canto.
  const umaCasa = max === 1;
  ordem.classList.toggle('um', umaCasa);
  function pintarOrdem(porId) {
    ordem.innerHTML = '';
    for (let i = 0; i < max; i++) {
      const pk = porId.get(sel[i]);
      const casa = document.createElement('div');
      casa.className = `eqf-casa${pk ? ' cheia' : ''}`;
      if (!pk) {
        // A casa vazia é uma pokébola apagada: o lugar existe e está esperando alguém.
        casa.innerHTML = `<span class="eqf-casa-n">${i + 1}</span><span class="eqf-casa-vazia"></span>${umaCasa
          ? `<span class="eqf-casa-dica">${escapar(t('escolha.casaVazia'))}</span>` : ''}`;
        casa.querySelector('.eqf-casa-vazia').appendChild(iconeBola(1, umaCasa ? 28 : 20));
        ordem.appendChild(casa);
        continue;
      }
      casa.title = pk.nome;
      casa.innerHTML = `
        <span class="eqf-casa-n">${i + 1}</span>
        <span class="eqf-casa-arte"></span>
        ${umaCasa ? `<span class="eqf-casa-nome">${pk.shiny ? dlgSeloShiny(true) : ''}${escapar(nomeExibidoPokemon(pk))}
          <small>${t('painel.nivelCurto')} ${num(pk.level)}</small></span>` : ''}
        <span class="eqf-casa-acoes">
          <button type="button" class="eqf-seta" data-mover="-1" title="${escapar(t('guild.timeSubir'))}"${i === 0 ? ' disabled' : ''}>◀</button>
          <button type="button" class="eqf-tirar" title="${escapar(t('oferenda.tirarDica', { nome: nomeExibidoPokemon(pk) }))}">×</button>
          <button type="button" class="eqf-seta" data-mover="1" title="${escapar(t('guild.timeDescer'))}"${i === sel.length - 1 ? ' disabled' : ''}>▶</button>
        </span>`;
      casa.querySelector('.eqf-casa-arte').appendChild(spritePokemon(pk, umaCasa ? 48 : 32));
      casa.querySelector('[data-mover="-1"]').onclick = () => mover(pk.id, -1);
      casa.querySelector('[data-mover="1"]').onclick = () => mover(pk.id, 1);
      casa.querySelector('.eqf-tirar').onclick = () => alternar(pk.id);
      if (movel) {
        casa.tabIndex = 0;
        casa.setAttribute('role', 'button');
        casa.setAttribute('aria-pressed', String(casaAtiva === pk.id));
        casa.classList.toggle('ativa', casaAtiva === pk.id);
        casa.onclick = (ev) => {
          if (ev.target.closest('button')) return;
          casaAtiva = casaAtiva === pk.id ? null : pk.id;
          repintar();
        };
      }
      ordem.appendChild(casa);
    }
    if (movel) pintarBarraDaCasa(porId);
  }

  /** A barra das ações da casa marcada (só no celular). Sem casa marcada, ela ensina o gesto. */
  function pintarBarraDaCasa(porId) {
    if (casaAtiva != null && !sel.includes(casaAtiva)) casaAtiva = null;
    const pk = casaAtiva != null ? porId.get(casaAtiva) : null;
    if (!pk) {
      barraCasa.classList.remove('ativa');
      barraCasa.innerHTML = `<span class="eqf-barra-dica">${escapar(t(sel.length ? 'escolha.casaDica' : 'escolha.casaVazia'))}</span>`;
      return;
    }
    const i = sel.indexOf(pk.id);
    barraCasa.classList.add('ativa');
    barraCasa.innerHTML = `
      <span class="eqf-barra-nome"><b>${i + 1}</b> ${escapar(pk.nome)}</span>
      <button type="button" class="camp-btn sec eqf-barra-bt" data-mover="-1" aria-label="${escapar(t('guild.timeSubir'))}"${i === 0 ? ' disabled' : ''}>◀</button>
      <button type="button" class="camp-btn sec eqf-barra-bt eqf-barra-tirar">✕ ${escapar(t('escolha.casaTirar'))}</button>
      <button type="button" class="camp-btn sec eqf-barra-bt" data-mover="1" aria-label="${escapar(t('guild.timeDescer'))}"${i === sel.length - 1 ? ' disabled' : ''}>▶</button>`;
    barraCasa.querySelector('[data-mover="-1"]').onclick = () => mover(pk.id, -1);
    barraCasa.querySelector('[data-mover="1"]').onclick = () => mover(pk.id, 1);
    barraCasa.querySelector('.eqf-barra-tirar').onclick = () => alternar(pk.id);
  }

  function repintar() {
    // A GRADE, e não o corpo: o corpo do modal da guerra fica no documento para sempre, e uma
    // folha antiga repintaria por cima da nova.
    if (!grade.isConnected) return;
    const porId = noJogo();
    // Quem sumiu da coleção (vendido, oferendado) sai do rascunho sozinho.
    sel = sel.filter((id) => porId.has(id));
    const todos = [...porId.values()];
    const colecao = conjuntoColecaoCliente();
    const busca = (filtro.busca ?? '').trim().toLowerCase();
    const piso = ivMinDoFiltro(filtro.ivMin);
    const lista = ordenarMarketPokemon(
      todos.filter(
        (k) => (!filtro.soShiny || k.shiny) && passaLocal(k, filtro.local, colecao)
          && depotPassaFiltros(k, busca, filtro.tipo, piso),
      ),
      filtro.ordem,
    );
    q('.eqf-conta').textContent = contagem(sel.length);
    q('.eqf-extra').innerHTML = extraContagem ? extraContagem(sel.map((id) => porId.get(id))) : '';
    q('.eqf-achados').textContent = t('amigos.anexarConta', { n: num(lista.length), total: num(todos.length) });
    pintarBotoes();
    pintarOrdem(porId);
    aoMudar?.([...sel]);

    const rolagem = grade.scrollTop;
    grade.innerHTML = '';
    if (!lista.length) {
      grade.innerHTML = `<div class="cm-vazio">${t(todos.length ? 'amigos.anexarVazio' : 'pvp.semPokemon')}</div>`;
      return;
    }
    for (const k of lista) {
      const idx = sel.indexOf(k.id);
      const on = idx >= 0;
      const card = cardPokemonEscolha(k, {
        colecao,
        aoVerFicha: () => abrirFichaDoPokemon(k),
        aoSelecionar: () => alternar(k.id),
      });
      card.dataset.id = k.id;
      if (on) card.classList.add('ofrpk-on');
      if (!on && sel.length >= max) card.classList.add('ofrpk-bloqueado');
      if (on) {
        const marca = document.createElement('span');
        marca.className = 'ofrpk-ordem';
        marca.textContent = idx + 1;
        card.appendChild(marca);
      }
      grade.appendChild(card);
    }
    grade.scrollTop = rolagem;
  }

  /** Só os dois botões do rodapé: um campo de fora (o nome) acende o "Salvar" sem refazer a grade. */
  function pintarBotoes() {
    const ocupado = salvando();
    btSalvar.disabled = ocupado || !podeSalvar([...sel]);
    btLimpar.disabled = ocupado || !sel.length;
    btSalvar.textContent = ocupado ? t('camp.enviando') : rotuloSalvar;
  }

  q('.eqf-filtros').appendChild(criarFiltrosSelect({
    tipo: filtro.tipo,
    ordem: filtro.ordem,
    ivMin: filtro.ivMin,
    local: filtro.local,
    locais: LOCAIS_TODOS,
    ordens: MK_POKEMON_ORDENS,
    ordemI18n: MK_POKEMON_ORDEM_I18N,
    onChange: (campo, valor) => {
      if (campo === 'ordem') filtro.ordem = valor || 'padrao';
      else filtro[campo] = valor;
      repintar();
    },
  }));
  q('.eqf-busca').oninput = (ev) => {
    filtro.busca = ev.target.value;
    repintar();
  };
  q('.eqf-shiny').onchange = (ev) => {
    filtro.soShiny = ev.target.checked;
    repintar();
  };
  btLimpar.onclick = () => {
    sel = [];
    casaAtiva = null;
    repintar();
  };
  btSalvar.onclick = () => {
    if (salvando() || !podeSalvar([...sel])) return;
    salvar([...sel]);
    repintar();
  };
  dobrarFiltrosNoCelular({
    campos: [q('.dmpk-shiny'), q('.eqf-filtros')],
    botaoEm: q('.dmpk-topo'),
    host: corpo,
  });
  // As pílulas não dobram: são quatro regras de três palavras, e cortá-las no meio esconderia
  // justamente as duas de baixo. Só o parágrafo de regra fica a um toque.
  if (!selos?.length) dobrarNotaNoCelular(q('.eqf-nota'));
  repintarComAColecao(grade, repintar);
  repintar();
  return { repintar, pintarBotoes };
}

/** Os filtros das duas folhas de equipe, fora das funções: sobrevivem a fechar e abrir. */
const pvpEqFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', soShiny: false, local: 'todos' };
const guerraEqFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', soShiny: false, local: 'todos' };
const treinoEqFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', soShiny: false, local: 'todos' };

/** A folha da equipe do PvP aberta: repinta e fecha de fora (a resposta do servidor). */
let folhaEquipePvp = null;

/**
 * "Montar equipe" do PvP Ranqueado. O rascunho parte da equipe salva; o "Salvar" manda
 * `pvp.time.salvar`, e a folha só fecha quando o servidor confirma (`timeSalvo`). Recusada, ela
 * fica aberta com o botão de volta — e uma resposta que não chega destrava em 10 s.
 */
function abrirSeletorDeTimePvp() {
  const { corpo, fechar } = folhaMercado(escapar(t('pvp.equipeTitulo')));
  const ctl = montarEscolhaDeEquipe(corpo, {
    max: PVP_TIME_MAX,
    idsIniciais: estado.pvpTime ?? [],
    filtro: pvpEqFiltro,
    nota: t('pvp.equipeRegras', { max: PVP_TIME_MAX }),
    notaIcone: 'espadas',
    contagem: (n) => t('pvp.escolhidos', { n, max: PVP_TIME_MAX }),
    extraContagem: (pks) => `${t('painel.poder')} <b>${num(pks.reduce((s, k) => s + (k?.poder ?? 0), 0))}</b>`,
    rotuloSalvar: t('pvp.salvarEquipe'),
    rotuloLimpar: t('pvp.limpar'),
    rotuloCheio: t('pvp.equipeCheia', { max: PVP_TIME_MAX }),
    salvando: () => !!estado.pvpSalvandoTime,
    salvar: (ids) => {
      estado.pvpSalvandoTime = true;
      enviar({ t: 'pvp.time.salvar', pokemonIds: ids });
      setTimeout(() => {
        if (!estado.pvpSalvandoTime) return;
        estado.pvpSalvandoTime = false;
        folhaEquipePvp?.repintar();
      }, 10_000);
    },
  });
  const sair = () => {
    folhaEquipePvp = null;
    fechar();
  };
  folhaEquipePvp = { repintar: ctl.repintar, fechar: sair };
  corpo.closest('.cm-folha')?.querySelector('.cm-fechar')?.addEventListener('click', sair);
}

/** A folha de editar formação aberta: fecha com o `formacaoOk` DELA e destrava na recusa. */
let folhaFormacao = null;

/**
 * O LÁPIS de uma formação: a mesma folha do "Sua equipe de PvP", com o NOME no alto. O rascunho
 * parte da escalação salva (quem saiu da coleção já não entra) e o "Salvar" manda
 * `pvp.formacao.salvar` — a mesma mensagem, e a mesma conferência no servidor, do "salvar a equipe
 * atual". Mexer em quem entra ou na ordem zera o placar, e a linha embaixo do nome avisa ANTES do
 * clique; trocar só o nome guarda o placar (o servidor compara a escalação).
 */
function abrirEditorDeFormacao(slot) {
  const f = formacaoDoSlot(slot);
  if (!f) return;
  const { folha, corpo, fechar } = folhaMercado(escapar(t('pvp.formEditarTitulo')));
  let nome = f.nome;
  let rascunho = [];
  const placar = partidasDaFormacao(f)
    ? t('pvp.formVD', { v: num(f.v + f.cv), d: num(f.d + f.cd) })
    : null;
  const enviando = () => !!estado.pvpFormacaoEnviando && Date.now() - estado.pvpFormacaoEnviando < 8000;

  /** A linha embaixo do nome: o erro do nome, o aviso de que o placar zera, ou o que vale hoje. */
  function pintarDica() {
    const dica = corpo.querySelector('.pvp-form-ed-dica');
    if (!dica) return;
    const v = validarNomeFormacao(nome);
    const zera = placar && !mesmaEscalacao(rascunho, f.ids);
    dica.classList.toggle('ruim', !v.ok);
    dica.classList.toggle('zera', v.ok && !!zera);
    if (!v.ok) dica.textContent = t(v.erro, { max: FORMACAO_NOME_MAX });
    else if (zera) dica.innerHTML = `${dlgIcone('alerta', 12)}<span>${t('pvp.formEdZera', { vd: placar })}</span>`;
    else if (placar) dica.textContent = t('pvp.formEdPlacar', { vd: placar });
    else dica.textContent = t('pvp.formNomeDica', { max: FORMACAO_NOME_MAX });
  }

  const ctl = montarEscolhaDeEquipe(corpo, {
    max: PVP_TIME_MAX,
    idsIniciais: f.ids,
    filtro: pvpEqFiltro,
    antes: `
      <div class="pvp-form-ed">
        <label class="pvp-form-ed-campo">
          <span>${t('pvp.formNomeRotulo')}</span>
          <input type="text" class="pvp-form-ed-nome" maxlength="${FORMACAO_NOME_MAX}" autocomplete="off"
                 spellcheck="false" value="${escapar(f.nome)}">
        </label>
        <p class="pvp-form-ed-dica"></p>
      </div>`,
    nota: t('pvp.equipeRegras', { max: PVP_TIME_MAX }),
    notaIcone: 'espadas',
    contagem: (n) => t('pvp.escolhidos', { n, max: PVP_TIME_MAX }),
    extraContagem: (pks) => `${t('painel.poder')} <b>${num(pks.reduce((s, k) => s + (k?.poder ?? 0), 0))}</b>`,
    rotuloSalvar: t('pvp.formEdSalvar'),
    rotuloLimpar: t('pvp.limpar'),
    rotuloCheio: t('pvp.equipeCheia', { max: PVP_TIME_MAX }),
    salvando: enviando,
    podeSalvar: (ids) => ids.length > 0 && validarNomeFormacao(nome).ok,
    aoMudar: (ids) => {
      rascunho = ids;
      pintarDica();
    },
    salvar: (ids) => {
      const v = validarNomeFormacao(nome);
      if (!v.ok || !ids.length) return;
      enviarFormacao({ t: 'pvp.formacao.salvar', slot: f.slot, nome: v.nome, pokemonIds: ids });
      // Resposta perdida: a trava do `enviarFormacao` vence em 8 s, e o botão volta junto.
      setTimeout(() => folhaFormacao?.pintarBotoes(), 8100);
    },
  });

  const campo = corpo.querySelector('.pvp-form-ed-nome');
  campo.oninput = () => {
    nome = campo.value;
    pintarDica();
    ctl.pintarBotoes();
  };
  // Enter só fecha o teclado: salvar daqui levaria junto uma escalação ainda pela metade.
  campo.onkeydown = (ev) => {
    if (ev.key === 'Enter') campo.blur();
  };

  const sair = () => {
    if (folhaFormacao?.folha === folha) folhaFormacao = null;
    fechar();
  };
  folhaFormacao = { folha, slot: f.slot, repintar: ctl.repintar, pintarBotoes: ctl.pintarBotoes, fechar: sair };
  folha.querySelector('.cm-fechar')?.addEventListener('click', sair);
}

// ------------------------------------------------------ a aba TREINAMENTO
//
// A BANCADA DE TESTES do PvP: duas equipes montadas na mão lutam pelas regras do Ranqueado e o
// jogador assiste. Cada casa aceita um pokémon DELE (uma cópia — o original nem entra na arena)
// ou um pokémon de MENTIRA, descrito campo a campo. Não há XP, Coin, item nem ponto, e nada é
// gravado: a promessa do outro lado está em `server/game/treino.mjs`.
//
// A tela é POSICIONAL — cinco casas de cada lado, escolhidas uma a uma. É o que deixa a ordem na
// mão do jogador (a casa 1 entra em campo primeiro) e o que permite 5 × 1: os lados são
// independentes, e uma luta desequilibrada é uma pergunta legítima numa bancada de testes.

const casasDoLado = (lado) => estado.treino?.[lado] ?? [];
const treinoEsperaMs = () => Math.max(0, (estado.treinoProximaEm ?? 0) - Date.now());

/** O pokémon de uma casa no formato dos cards da tela — o meu, ou o de teste montado na hora. */
function pokemonDaCasaTreino(casa) {
  if (!casa) return null;
  if (casa.meu != null) {
    const meu = (estado.eu?.pokemons ?? []).find((k) => k.id === casa.meu);
    // Vendido (ou anunciado) com a bancada montada: a casa fica vazia em vez de mentir.
    return meu ? { ...meu, ehTeste: false } : null;
  }
  const d = casa.teste;
  const esp = estado.especies.get(d.speciesId);
  return {
    ehTeste: true,
    id: `t${d.speciesId}`,
    speciesId: d.speciesId,
    nome: esp?.name ?? `#${d.speciesId}`,
    level: d.level,
    shiny: d.shiny,
    potencia: d.potencia,
    quality: d.qualidade,
    ivs: { ...d.ivs },
  };
}

const somaIv = (ivs) => STATS_IV.reduce((s, k) => s + (Number(ivs?.[k]) || 0), 0);

/** Repinta a bancada inteira. É barato: são dez casas e dois botões. */
function pintarTreino() {
  const host = $('#pvp-painel-treino');
  if (!host) return;
  // Pokémon vendido (ou anunciado) com a bancada montada sai da casa antes de desenhar: o
  // servidor o descartaria de qualquer jeito, e uma casa que mostra "+" mas conta como cheia
  // deixaria o botão Lutar aceso para um lado que já não existe.
  for (const lado of ['a', 'b']) {
    const limpo = casasDoLado(lado).filter((c) => pokemonDaCasaTreino(c));
    if (limpo.length !== casasDoLado(lado).length) estado.treino = { ...estado.treino, [lado]: limpo };
  }
  host.innerHTML = `
    <p class="trn-aviso">${escapar(t('treino.aviso'))}</p>
    <div class="trn-mesa">
      <section class="trn-lado" data-lado="a">
        <h4 class="trn-lado-tit">${escapar(t('treino.ladoA'))}<b class="trn-conta">${casasDoLado('a').length}/${TREINO_MAX_LADO}</b></h4>
        <div class="trn-casas"></div>
      </section>
      <div class="trn-vs" aria-hidden="true">VS</div>
      <section class="trn-lado" data-lado="b">
        <h4 class="trn-lado-tit">${escapar(t('treino.ladoB'))}<b class="trn-conta">${casasDoLado('b').length}/${TREINO_MAX_LADO}</b></h4>
        <div class="trn-casas"></div>
      </section>
    </div>
    <!-- O rodapé é o de uma caixa de diálogo: a ação que DESFAZ à esquerda, a que AVANÇA à
         direita, as duas nas bordas do painel. E a espera fica embaixo do "Lutar", colada no
         botão a que ela se refere, em vez de espremida entre os dois. -->
    <div class="trn-pe">
      <div class="trn-pe-acoes">
        <button type="button" class="camp-btn sec trn-limpar" id="trn-limpar">${escapar(t('treino.limpar'))}</button>
        <button type="button" class="camp-btn trn-lutar" id="trn-lutar">${escapar(t('treino.lutar'))}</button>
      </div>
      <span class="trn-espera" id="trn-espera"></span>
    </div>`;

  for (const secao of host.querySelectorAll('.trn-lado')) {
    const lado = secao.dataset.lado;
    const grade = secao.querySelector('.trn-casas');
    for (let i = 0; i < TREINO_MAX_LADO; i++) grade.appendChild(casaDeTreino(lado, i));
  }
  host.querySelector('#trn-limpar').onclick = () => {
    estado.treino = { a: [], b: [] };
    pintarTreino();
  };
  host.querySelector('#trn-lutar').onclick = () => lutarTreino();
  tiqueTreino();
}

/** Uma casa: vazia (o "+" que abre o menu) ou com o card do lutador e o × para tirar. */
function casaDeTreino(lado, i) {
  const casa = casasDoLado(lado)[i] ?? null;
  const pk = pokemonDaCasaTreino(casa);
  const el = document.createElement('div');
  el.className = `trn-casa${pk ? ' cheia' : ''}${pk?.ehTeste ? ' teste' : ''}`;
  if (!pk) {
    el.innerHTML = `<button type="button" class="trn-add" aria-label="${escapar(t('treino.escolher'))}">+</button>`;
    el.querySelector('.trn-add').onclick = () => abrirMenuDaCasaTreino(lado, i);
    return el;
  }
  el.innerHTML = `
    <span class="trn-casa-n">${i + 1}</span>
    <span class="trn-casa-arte"></span>
    <span class="trn-casa-nome">${escapar(pk.nome)}${pk.shiny ? ' ✨' : ''}</span>
    <span class="trn-casa-selos">
      <b class="trn-selo nv">${t('painel.nivelCurto')} ${num(pk.level)}</b>
      ${selosAtributos(pk)}
    </span>
    ${pk.ehTeste ? `<span class="trn-marca">${escapar(t('treino.marcaTeste'))}</span>` : ''}
    <button type="button" class="trn-tirar" aria-label="${escapar(t('treino.tirar'))}">×</button>`;
  el.querySelector('.trn-casa-arte').appendChild(spritePokemon(pk, 40));
  el.querySelector('.trn-tirar').onclick = () => {
    estado.treino[lado] = casasDoLado(lado).filter((_, j) => j !== i);
    pintarTreino();
  };
  // Clicar no card reabre a escolha daquela casa — trocar é mais comum do que tirar.
  el.onclick = (ev) => {
    if (ev.target.closest('.trn-tirar')) return;
    if (casa?.teste) return abrirFormDeTeste(lado, i, casa.teste);
    abrirMenuDaCasaTreino(lado, i);
  };
  return el;
}

/**
 * O menu da casa: pokémon meu ou pokémon de teste. É a escolha que o jogador faz antes.
 *
 * Duas CARTAS de escolha, cada uma com o que ela é desenhado em cima: a sua equipe em fila, e a
 * silhueta do "quem é esse pokémon?" que o formulário de teste vai preencher. A explicação que
 * antes era um parágrafo em cima dos dois botões virou a legenda de cada carta — é na hora de
 * escolher que o jogador precisa saber que o pokémon dele entra como CÓPIA.
 */
function abrirMenuDaCasaTreino(lado, i) {
  const { corpo, fechar } = folhaMercado(escapar(t('treino.casaTitulo', { n: i + 1 })));
  const equipe = (estado.eu?.pokemons ?? []).filter((p) => p.slot != null).sort((a, b) => a.slot - b.slot);
  const ltSilhueta = estado.especies.get(25)?.looktype ?? estado.especies.get(1)?.looktype ?? 0;
  corpo.innerHTML = `
    <div class="trn-menu">
      <button type="button" class="trn-escolha" id="trn-menu-meu">
        <span class="trn-escolha-arte">${equipe.length
          ? dlgFila(equipe, 32, 3)
          : dlgMedalha({ icone: 'pessoa', tom: 'rx', px: 30 })}</span>
        <b>${escapar(t('treino.escolherMeu'))}</b>
        <small>${escapar(t('treino.meuSub'))}</small>
      </button>
      <button type="button" class="trn-escolha" id="trn-menu-teste">
        <span class="trn-escolha-arte trn-silhueta">${ltSilhueta ? dlgArteLt(ltSilhueta, 52) : ''}<i aria-hidden="true">?</i></span>
        <b>${escapar(t('treino.escolherTeste'))}</b>
        <small>${escapar(t('treino.testeSub'))}</small>
      </button>
    </div>`;
  hidratarDialogo(corpo);
  corpo.querySelector('#trn-menu-meu').onclick = () => abrirEscolhaMeuTreino(lado, i);
  corpo.querySelector('#trn-menu-teste').onclick = () => abrirFormDeTeste(lado, i, null);
  return fechar;
}

/** Põe (ou troca) o que está na casa `i` do lado, sem mexer nas outras. */
function porNaCasaTreino(lado, i, valor) {
  const casas = [...casasDoLado(lado)];
  // A lista é densa: escolher a casa 4 com as três primeiras vazias entra na primeira vaga.
  if (i >= casas.length) casas.push(valor);
  else casas[i] = valor;
  estado.treino = { ...estado.treino, [lado]: casas.slice(0, TREINO_MAX_LADO) };
  pintarTreino();
}

/** A folha de escolher UM pokémon meu — a mesma da equipe do PvP, com uma casa só. */
function abrirEscolhaMeuTreino(lado, i) {
  const { corpo, fechar } = folhaMercado(escapar(t('treino.escolherMeu')));
  montarEscolhaDeEquipe(corpo, {
    max: 1,
    idsIniciais: [],
    filtro: treinoEqFiltro,
    // As quatro garantias da cópia, em pílulas: é a pergunta de quem vai pôr o melhor pokémon
    // num treino ("ele vai se machucar?") respondida antes do clique.
    selos: [
      { icone: 'copia', texto: t('treino.seloCopia'), tom: 'ouro' },
      { icone: 'cura', texto: t('treino.seloHp'), tom: 'bom' },
      { icone: 'subir', texto: t('treino.seloXp') },
      { icone: 'cadeado', texto: t('treino.seloLugar') },
    ],
    contagem: (n) => t('treino.escolhidos', { n }),
    rotuloSalvar: t('treino.usarEste'),
    rotuloLimpar: t('pvp.limpar'),
    rotuloCheio: t('treino.umPorCasa'),
    salvar: (ids) => {
      if (!ids.length) return;
      porNaCasaTreino(lado, i, { meu: ids[0] });
      fechar();
    },
  });
}

/**
 * O formulário do POKÉMON DE TESTE.
 *
 * Três blocos, na ordem em que a cabeça decide: a espécie (com busca e grade de sprites), o
 * resumo do bicho que está sendo montado (⚔ e os mesmos selos P·IV·Q·N dos cards do jogo) e os
 * campos de nascimento. Potência e shiny são CHIPS, e não `select` e `checkbox` do navegador:
 * além de não destoarem da tábua, são alvo de dedo no celular.
 *
 * O resumo recalcula a cada digitada e é o ponto do formulário — é ele que responde "o bicho que
 * eu descrevi é mais forte que o meu?" antes de a luta rodar.
 *
 * `inicial` reabre a casa para ajuste.
 */
function abrirFormDeTeste(lado, i, inicial) {
  const { corpo, fechar } = folhaMercado(escapar(t('treino.testeTitulo')));
  // O formulário abre num pokémon que existe no jogo (o #1 da Pokédex), e não no primeiro do
  // catálogo — que pode ser uma forma de Outland ou uma espécie sem sprite.
  const padraoEsp = estado.especies.has(1) ? 1 : (especiesPokedex()[0]?.pokeId ?? 1);
  let dados = normalizarPokemonTeste(inicial ?? pokemonTestePadrao(padraoEsp));
  let busca = '';

  corpo.innerHTML = `
    <p class="cm-nota">${escapar(t('treino.testeExplica'))}</p>
    <div class="trn-esp-topo">
      <input type="search" id="trn-busca" class="trn-busca" placeholder="${escapar(t('cm.buscarPokemon'))}" autocomplete="off">
      <span class="trn-esp-conta" id="trn-esp-conta"></span>
    </div>
    <div class="trn-especies" id="trn-especies"></div>
    <div class="trn-resumo" id="trn-resumo"></div>
    <div class="trn-campos">
      <label class="trn-campo">
        <span class="trn-campo-rot">${escapar(t('treino.nivel'))}</span>
        <input type="number" id="trn-nivel" min="${TREINO_NIVEL_MIN}" max="${TREINO_NIVEL_MAX}" step="1" inputmode="numeric">
      </label>
      <label class="trn-campo">
        <span class="trn-campo-rot">${escapar(t('treino.qualidade'))} <em>${QUALIDADE_MIN.toFixed(2)}–${QUALIDADE_MAX.toFixed(2)}</em></span>
        <input type="number" id="trn-qualidade" min="${QUALIDADE_MIN}" max="${QUALIDADE_MAX}" step="0.01" inputmode="decimal">
      </label>
      <div class="trn-campo trn-campo-larga">
        <span class="trn-campo-rot">${escapar(t('treino.potencia'))}</span>
        <div class="trn-chips" id="trn-potencia">
          ${Array.from({ length: POTENCIA_MAX }, (_, n) => `
            <button type="button" class="trn-chip pot" data-pot="${n + 1}">P${n + 1}</button>`).join('')}
        </div>
      </div>
      <div class="trn-campo">
        <span class="trn-campo-rot">${escapar(t('treino.shiny'))}</span>
        <button type="button" class="trn-chip trn-shiny-chip" id="trn-shiny">✨ ${escapar(t('treino.shiny'))}</button>
      </div>
    </div>
    <div class="trn-ivs">
      <div class="trn-ivs-topo">
        <b>${escapar(t('treino.ivs'))} <em>${IV_POR_STAT.min}–${IV_POR_STAT.max}</em></b>
        <span class="trn-ivs-soma" id="trn-ivs-soma"></span>
        <button type="button" class="trn-chip mini" id="trn-iv-max">${escapar(t('treino.ivMax'))}</button>
        <button type="button" class="trn-chip mini" id="trn-iv-min">${escapar(t('treino.ivMin'))}</button>
      </div>
      <div class="trn-ivs-campos">
        ${STATS_IV.map((k) => `
          <label class="trn-iv">
            <span>${escapar(rotuloStat(k))}</span>
            <input type="number" data-iv="${k}" min="${IV_POR_STAT.min}" max="${IV_POR_STAT.max}" step="1" inputmode="numeric">
          </label>`).join('')}
      </div>
    </div>
    <div class="cm-botoes">
      <button type="button" class="cm-acao" id="trn-cancelar">${escapar(t('cm.cancelar'))}</button>
      <button type="button" class="cm-acao destaque" id="trn-ok">${escapar(t(inicial ? 'treino.salvarTeste' : 'treino.addTeste'))}</button>
    </div>`;

  const lista = corpo.querySelector('#trn-especies');
  const pintarEspecies = () => {
    const alvo = busca.trim().toLowerCase();
    const todas = especiesPokedex();
    const achadas = alvo ? todas.filter((e) => (e.name ?? '').toLowerCase().includes(alvo)) : todas;
    const mostradas = achadas.slice(0, 60);
    lista.innerHTML = '';
    for (const esp of mostradas) {
      const bt = document.createElement('button');
      bt.type = 'button';
      bt.className = `trn-esp${esp.pokeId === dados.speciesId ? ' on' : ''}`;
      bt.title = esp.name;
      bt.innerHTML = `<span class="trn-esp-arte"></span><span class="trn-esp-nome">${escapar(esp.name)}</span>`;
      bt.querySelector('.trn-esp-arte').appendChild(spritePokemon({ speciesId: esp.pokeId, shiny: dados.shiny }, 34));
      bt.onclick = () => {
        dados = { ...dados, speciesId: esp.pokeId };
        pintarEspecies();
        pintarResumo();
      };
      lista.appendChild(bt);
    }
    if (!mostradas.length) lista.innerHTML = `<p class="vazio-msg">${escapar(t('treino.semEspecie'))}</p>`;
    // "60 de 1.218": sem isto, quem não acha o bicho na grade não descobre que precisa buscar.
    corpo.querySelector('#trn-esp-conta').textContent = t('treino.especiesConta', {
      n: num(mostradas.length), total: num(achadas.length),
    });
  };

  const campos = {
    nivel: corpo.querySelector('#trn-nivel'),
    qualidade: corpo.querySelector('#trn-qualidade'),
  };
  const ivs = [...corpo.querySelectorAll('[data-iv]')];
  const chipsPot = [...corpo.querySelectorAll('[data-pot]')];
  const chipShiny = corpo.querySelector('#trn-shiny');

  /** O bicho como o resto do jogo o entende — é com ele que o ⚔ e os selos são calculados. */
  const comoPokemon = () => ({
    speciesId: dados.speciesId,
    nome: estado.especies.get(dados.speciesId)?.name ?? '',
    level: dados.level,
    ivs: dados.ivs,
    quality: dados.qualidade,
    potencia: dados.potencia,
    shiny: dados.shiny,
    refino: null,
  });

  const pintarResumo = () => {
    const pk = comoPokemon();
    const alvo = corpo.querySelector('#trn-resumo');
    alvo.innerHTML = `
      <span class="trn-resumo-arte"></span>
      <span class="trn-resumo-txt">
        <b>${escapar(pk.nome || `#${dados.speciesId}`)}${dados.shiny ? ' ✨' : ''}</b>
        <span class="trn-resumo-nv">Nv ${num(dados.level)}</span>
      </span>
      <span class="trn-resumo-poder">⚔ ${num(poderDePokemon(pk, especieDe(pk)))}</span>
      ${selosAtributos(pk, { compacto: true })}`;
    alvo.querySelector('.trn-resumo-arte').appendChild(spritePokemon(pk, 40));
  };

  const paraTela = () => {
    campos.nivel.value = dados.level;
    campos.qualidade.value = dados.qualidade;
    for (const el of ivs) el.value = dados.ivs[el.dataset.iv];
    for (const bt of chipsPot) bt.classList.toggle('on', Number(bt.dataset.pot) === dados.potencia);
    chipShiny.classList.toggle('on', dados.shiny);
    corpo.querySelector('#trn-ivs-soma').textContent = t('treino.ivSoma', { n: somaIv(dados.ivs) });
    pintarResumo();
  };
  // Cada digitada passa pela MESMA peneira do servidor (`normalizarPokemonTeste`): o que a tela
  // mostra é exatamente o que vai lutar, e não há como montar aqui um bicho que lá não existe.
  const daTela = () => {
    dados = normalizarPokemonTeste({
      speciesId: dados.speciesId,
      level: campos.nivel.value,
      qualidade: campos.qualidade.value,
      potencia: dados.potencia,
      shiny: dados.shiny,
      ivs: Object.fromEntries(ivs.map((el) => [el.dataset.iv, el.value])),
    });
    corpo.querySelector('#trn-ivs-soma').textContent = t('treino.ivSoma', { n: somaIv(dados.ivs) });
    pintarResumo();
  };
  for (const el of [campos.nivel, campos.qualidade, ...ivs]) {
    // `change` (sair do campo) escreve de volta o valor já preso na faixa; `input` só recalcula
    // o resumo, para o número não pular embaixo do dedo enquanto se digita.
    el.onchange = () => { daTela(); paraTela(); };
    el.oninput = daTela;
  }
  for (const bt of chipsPot) {
    bt.onclick = () => {
      dados = { ...dados, potencia: Number(bt.dataset.pot) };
      paraTela();
    };
  }
  chipShiny.onclick = () => {
    dados = { ...dados, shiny: !dados.shiny };
    paraTela();
    pintarEspecies(); // a grade passa a desenhar as formas shiny
  };
  corpo.querySelector('#trn-iv-max').onclick = () => {
    dados = { ...dados, ivs: Object.fromEntries(STATS_IV.map((k) => [k, IV_POR_STAT.max])) };
    paraTela();
  };
  corpo.querySelector('#trn-iv-min').onclick = () => {
    dados = { ...dados, ivs: Object.fromEntries(STATS_IV.map((k) => [k, IV_POR_STAT.min])) };
    paraTela();
  };
  corpo.querySelector('#trn-busca').oninput = (ev) => {
    busca = ev.target.value;
    pintarEspecies();
  };
  corpo.querySelector('#trn-cancelar').onclick = fechar;
  corpo.querySelector('#trn-ok').onclick = () => {
    daTela();
    porNaCasaTreino(lado, i, { teste: dados });
    fechar();
  };
  paraTela();
  pintarEspecies();
}

/** Manda a bancada lutar. O servidor confere tudo de novo — aqui só se evita o clique à toa. */
function lutarTreino() {
  if (estado.treinoLutando) return;
  if (!casasDoLado('a').length || !casasDoLado('b').length) return toast(t('treino.recusa.vazio'));
  if (treinoEsperaMs() > 0) return toast(t('treino.recusa.espera'));
  estado.treinoLutando = true;
  enviar({ t: 'treino.lutar', a: casasDoLado('a'), b: casasDoLado('b') });
  tiqueTreino();
  // A resposta pode não vir (socket caído). Sem isto o botão ficaria mudo para sempre — a
  // mesma trava do desafio de ginásio.
  setTimeout(() => {
    if (!estado.treinoLutando) return;
    estado.treinoLutando = false;
    tiqueTreino();
  }, 20_000);
}

/** O botão e o relógio da espera. Chamado a cada segundo enquanto a aba está aberta. */
function tiqueTreino() {
  const bt = $('#trn-lutar');
  if (!bt) return;
  const espera = treinoEsperaMs();
  const vazio = !casasDoLado('a').length || !casasDoLado('b').length;
  bt.disabled = estado.treinoLutando || espera > 0 || vazio;
  bt.textContent = estado.treinoLutando ? t('treino.lutando') : t('treino.lutar');
  // "Limpar tudo" com a bancada vazia é um botão que não faz nada: apagado, ele para de
  // disputar a atenção com o "Lutar" enquanto não há o que limpar.
  const limpar = $('#trn-limpar');
  if (limpar) limpar.disabled = !casasDoLado('a').length && !casasDoLado('b').length;
  const rel = $('#trn-espera');
  if (rel) {
    // Durante a espera o texto é o relógio, e ele merece destaque — é a resposta para "por que
    // o botão está apagado?".
    rel.classList.toggle('esperando', espera > 0);
    rel.textContent = espera > 0
      ? t('treino.esperaRestante', { tempo: relogioDeFila(espera) })
      : t('treino.esperaLivre');
  }
}
setInterval(() => {
  if (estado.modalAberto === 'pvp' && estado.pvpAba === 'treino') tiqueTreino();
}, 1000);

/** A resposta do servidor: a fita para assistir, ou a recusa. */
function aoReceberTreino(m) {
  estado.treinoLutando = false;
  if (m.recusa) {
    if (m.recusa.chave === 'treino.recusa.espera' && m.recusa.restaMs > 0) {
      estado.treinoProximaEm = Date.now() + m.recusa.restaMs;
    }
    toast(t(m.recusa.chave));
    return tiqueTreino();
  }
  const r = m.resultado;
  if (!r?.replay) return tiqueTreino();
  estado.treinoProximaEm = Date.now() + (r.cooldownMs ?? TREINO_COOLDOWN_MS);
  tiqueTreino();
  abrirReplayGuerra({
    replay: r.replay,
    titulo: t(r.venceuA ? 'treino.venceuA' : 'treino.venceuB', { a: r.ladoA, b: r.ladoB }),
  });
}

/**
 * O placar da guerra mais recente — mostrado na aba "Última guerra" do painel PvP Guild.
 */
function blocoUltimaGuerra(ultima) {
  if (!ultima?.placar?.length) return `<p class="vazio-msg">${t('guild.pvpSemGuerra')}</p>`;
  const minha = estado.eu?.guild?.id ?? null;
  const linhas = ultima.placar
    .map(
      (g) => `<button type="button" class="gw-res-linha guild-abre${g.id === minha ? ' eu' : ''}${g.pos === 1 ? ' campea' : ''}"
        data-guild="${g.id}" title="${escapar(t('guild.verFicha'))}">
        <span class="gw-res-pos">${g.pos}º</span>
        <span class="gd-mini" data-gid="${g.id}"></span>
        <span class="gw-res-nome">${escapar(g.nome)}</span>
        <span class="gw-res-kd">${num(g.abates ?? 0)}⚔ / ${num(g.mortes ?? 0)}☠</span>
        <em class="gw-res-gp">+${num(g.gp ?? 0)} GP</em>
        <span class="guild-abre-seta" aria-hidden="true">›</span>
      </button>`,
    )
    .join('');
  const mvp = ultima.vencedor?.mvp;
  return `
    <div class="gw-res-cab">
      <span>${t('guild.pvpGuerraDe', { dia: escapar(ultima.dia ?? '—') })}</span>
      ${ultima.motivo === 'tempo' ? `<em>${t('guild.pvpPorTempo')}</em>` : ''}
      ${ultima.motivo === 'sozinha' ? `<em>${t('guild.pvpSozinha')}</em>` : ''}
    </div>
    <div class="gw-res-lista">${linhas}</div>
    ${mvp ? `<p class="gw-res-mvp">${t('guild.pvpMvp', { nick: escapar(mvp.nick), n: num(mvp.abates) })}</p>` : ''}`;
}

function blocoRegistradas(registradas) {
  if (!registradas.length) return `<p class="vazio-msg">${t('guild.semRegistro')}</p>`;
  return `<div class="guild-pvp-lista">${registradas
    .map(
      (g) => `<button type="button" class="guild-pvp-linha guild-abre" data-guild="${g.id}"
          title="${escapar(t('guild.verFicha'))}">
          <span class="gd-mini" data-gid="${g.id}"></span>
          <span class="guild-pvp-nome">${escapar(g.nome)}</span>
          <em>${num(g.gp)} GP</em>
          <span class="guild-abre-seta" aria-hidden="true">›</span>
        </button>`,
    )
    .join('')}</div>`;
}

function montarGuildPvp() {
  const host = $('#guild-pvp-painel');
  if (!host) return;
  const info = estado.guildPvp ?? {};
  const prox = info.proximoEm ? Math.max(0, info.proximoEm - Date.now()) : 0;
  const h = Math.floor(prox / 3600000);
  const m = Math.floor((prox % 3600000) / 60000);
  const registradas = info.registradas ?? [];
  const ultima = info.ultima ?? null;
  const aba = estado.guildPvpAba === 'ultima' ? 'ultima' : 'registradas';
  estado.guildPvpAba = aba;
  host.innerHTML = `
    <p class="guild-pvp-intro">${t('guild.pvpIntro', {
      h: info.horaUtc ?? 22,
      max: info.maxTime ?? estado.guildMaxTime ?? 10,
    })}</p>
    <!-- A regra do TIME dita, por extenso, no lugar onde ela decide alguma coisa: quem abre o
         PvP Guild está perguntando "o que a minha guild leva para a guerra?", e a resposta
         deixou de ser "todo mundo". -->
    <p class="guild-pvp-time">${t('guild.pvpTime', { max: info.maxTime ?? estado.guildMaxTime ?? 10 })}</p>
    <p class="guild-pvp-prox">${t('guild.pvpProximo', { h, m })}</p>
    <p class="guild-pvp-gp">${t('guild.pvpGp', { n: num(info.gpMaximo ?? info.registradas?.length ?? 0) })}</p>
    <p class="guild-pvp-gp-detalhe">${t('guild.pvpGpDetalhe')}</p>
    <div class="guild-pvp-acoes">
      ${
        // Depois da guerra do dia o botão continua, e diz para qual guerra vale: o servidor grava o
        // registro na de amanhã (ver `guild.pvp.registrar`). Antes ele sumia até a meia-noite UTC,
        // e o card da guild, que mandava o dono para cá, virava um beco sem saída.
        podeGerirGuild() && !info.autoRegistro
          ? `<button type="button" class="guild-btn" id="guild-pvp-registrar">${t(info.encerrado ? 'guild.registrarAmanha' : 'guild.registrar')}</button>`
          : info.autoRegistro
            ? `<p class="guild-ok">${t('guild.registradaAuto')}</p>`
            : info.minhaRegistrada
              ? `<p class="guild-ok">${t('guild.registrada')}</p>`
              // Quem não manda na guild nunca vê o botão — e sem esta frase concluía que ele tinha
              // sumido do jogo.
              : `<p class="guild-pvp-reg-nota">${escapar(t('guild.registroSoDono'))}</p>`
      }
      ${
        ultima?.temReplay
          ? `<button type="button" class="guild-btn gw-assistir" id="guild-pvp-replay">${t('guild.pvpAssistir')}</button>`
          : ''
      }
      <!-- Recompensas e a ANÁLISE da última guerra lado a lado, embaixo do replay: as duas são
           "o que saiu da guerra", uma em prêmio e a outra em números. -->
      <div class="guild-pvp-linha2">
        ${botaoPremiosPvp('pvp-premios-guild')}
        ${
          ultima?.temReplay
            ? `<button type="button" class="pvp-premios-bt gwa-abrir-bt" id="guild-pvp-analise" title="${escapar(t('guild.analise.dica'))}">
                 <span class="pvp-premios-ico" aria-hidden="true">📊</span>${t('guild.analise.bt')}
               </button>`
            : ''
        }
      </div>
    </div>
    <div class="guild-pvp-abas" role="tablist">
      <button type="button" class="guild-pvp-aba${aba === 'registradas' ? ' on' : ''}" data-aba="registradas" role="tab" aria-selected="${aba === 'registradas' ? 'true' : 'false'}">${t('guild.registradas')}</button>
      <button type="button" class="guild-pvp-aba${aba === 'ultima' ? ' on' : ''}" data-aba="ultima" role="tab" aria-selected="${aba === 'ultima' ? 'true' : 'false'}">${t('guild.pvpUltima')}</button>
    </div>
    <div class="guild-pvp-corpo">
      <div class="guild-pvp-painel-aba${aba === 'registradas' ? '' : ' hidden'}" data-aba="registradas" role="tabpanel">${blocoRegistradas(registradas)}</div>
      <div class="guild-pvp-painel-aba${aba === 'ultima' ? '' : ' hidden'}" data-aba="ultima" role="tabpanel"><div class="gw-res">${blocoUltimaGuerra(ultima)}</div></div>
    </div>`;
  host.querySelector('#guild-pvp-registrar')?.addEventListener('click', () =>
    enviar({ t: 'guild.pvp.registrar' }),
  );
  host.querySelector('#guild-pvp-replay')?.addEventListener('click', pedirReplayGuerra);
  host.querySelector('#guild-pvp-analise')?.addEventListener('click', pedirAnaliseGuerra);
  host.querySelector('#pvp-premios-guild')?.addEventListener('click', abrirPremiosGuild);
  // A ficha da guild, a mesma do Ranking. Vale nas DUAS listas: quem olha "registradas hoje"
  // está decidindo se compensa entrar na guerra, e quem olha o placar quer saber quem foi
  // aquela que passou na frente — as duas perguntas se respondem com a equipe dos membros.
  for (const bt of host.querySelectorAll('.guild-abre')) {
    bt.addEventListener('click', () => pedirDetalheGuild(Number(bt.dataset.guild)));
  }
  for (const bt of host.querySelectorAll('.guild-pvp-aba')) {
    bt.addEventListener('click', () => {
      const nova = bt.dataset.aba;
      if (!nova || nova === estado.guildPvpAba) return;
      estado.guildPvpAba = nova;
      montarGuildPvp();
    });
  }
  const brasoes = new Map([
    ...registradas.map((g) => [g.id, g.brasao]),
    ...(ultima?.placar ?? []).map((g) => [g.id, g.brasao]),
  ]);
  for (const el of host.querySelectorAll('.gd-mini')) {
    const b = brasoes.get(Number(el.dataset.gid));
    if (b) pintarBrasao(el, b, 28);
  }
}

// ------------------------------------------- análise da Guerra de Guilds
//
// Os números de cada jogador na última guerra: dano causado e recebido, abates, pokémon perdidos,
// quais pokémon entraram em campo e quanto cada um fez. Quem calcula é o SERVIDOR, a partir da
// própria fita (`game/guild-pvp-analise.mjs`) — a tela recebe a tabela pronta (~130 KB para 170
// lutadores) em vez de baixar os ~600 KB do replay e refazer a conta no celular.
//
// Assistência não aparece: a fita não guarda o bastante para separar ajuda de coincidência, e
// um número inventado é pior do que a ausência dele.

/** O estado da folha: o que chegou, a aba, o recorte e quem está aberto. */
const analiseGw = {
  dados: null, aba: 'jogadores', guild: 'todas', ordem: 'd', busca: '', abertos: new Set(), pedindo: false,
};

/** Por onde a aba Jogadores ordena. `mo` = pokémon perdidos. */
const ORDENS_ANALISE = [
  { id: 'd', chave: 'guild.analise.ordDano' },
  { id: 'k', chave: 'guild.analise.ordAbates' },
  { id: 'r', chave: 'guild.analise.ordRecebido' },
  { id: 'mo', chave: 'guild.analise.ordPerdidos' },
  { id: 'gl', chave: 'guild.analise.ordGolpes' },
  { id: 'sup', chave: 'guild.analise.ordSuper' },
];

/** "2,2 mi" / "2.2M" — os totais da guerra passam fácil dos sete dígitos. */
const numCurto = (n) => {
  const v = Number(n) || 0;
  if (Math.abs(v) < 10_000) return num(v);
  try {
    return new Intl.NumberFormat(localeData(), { notation: 'compact', maximumFractionDigits: 1 }).format(v);
  } catch {
    return num(v);
  }
};

function pedirAnaliseGuerra() {
  if (analiseGw.pedindo) return;
  analiseGw.pedindo = true;
  analiseGw.dados = null;
  $('#gwa-titulo').textContent = t('guild.analise.titulo');
  $('#gwa-corpo').innerHTML = `<div class="gwa-carregando">${t('guild.analise.carregando')}</div>`;
  $('#gwa').classList.remove('hidden');
  enviar({ t: 'guild.pvp.analise' });
  // A resposta pode não vir (socket caído, servidor reiniciando). Sem isto a folha ficaria
  // dizendo "calculando" para sempre e o botão, mudo.
  setTimeout(() => {
    if (!analiseGw.pedindo) return;
    analiseGw.pedindo = false;
    if (!$('#gwa').classList.contains('hidden') && !analiseGw.dados) {
      $('#gwa-corpo').innerHTML = `<div class="gwa-carregando">${t('guild.analiseFalhou')}</div>`;
    }
  }, 15_000);
}

function fecharAnaliseGuerra() {
  $('#gwa').classList.add('hidden');
  $('#gwa-corpo').innerHTML = '';
  analiseGw.dados = null;
}

function receberAnaliseGuerra(a) {
  analiseGw.pedindo = false;
  // Fechou antes de a resposta chegar: não reabre por conta própria.
  if ($('#gwa').classList.contains('hidden')) return;
  if (!a || a.vazia || !Array.isArray(a.jogadores)) {
    $('#gwa-corpo').innerHTML = `<div class="gwa-carregando">${t('guild.pvpSemGuerra')}</div>`;
    return;
  }
  analiseGw.dados = a;
  analiseGw.abertos = new Set();
  analiseGw.busca = '';
  // A primeira vista é a MINHA guild, se ela lutou: é a pergunta que traz o jogador até aqui
  // ("como a gente foi?"). Quem não lutou cai no placar das guilds.
  const minha = a.guilds.find((g) => g.id === (estado.eu?.guild?.id ?? -1));
  analiseGw.guild = minha ? String(minha.i) : 'todas';
  analiseGw.aba = minha ? 'jogadores' : 'guilds';
  // Abre o primeiro (o de mais dano da minha guild): a folha nasce mostrando o que ela sabe fazer.
  const meu = a.jogadores.find((j) => j.nick.toLowerCase() === (estado.eu?.nick ?? '').toLowerCase());
  if (meu) analiseGw.abertos.add(meu.nick);
  $('#gwa-titulo').textContent = t('guild.analise.tituloDia', { dia: diaDaGuerra(a.dia) });
  pintarAnaliseGuerra();
}

/** "2026-09-18" → "18/09/2026" no idioma da tela. O dia da guerra é UTC, e é lido como UTC. */
const diaDaGuerra = (dia) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(dia ?? ''))) return String(dia ?? '');
  return new Date(`${dia}T12:00:00Z`).toLocaleDateString(localeData(), { timeZone: 'UTC' });
};

const guildDaAnalise = (a, i) => a.guilds.find((g) => g.i === i) ?? null;

/** A bolinha na cor da guild — a mesma cor do replay, então quem assistiu reconhece. */
const bolaGuild = (i) => `<i class="gwa-cor" style="--gw-cor:${corDaGuilda(i)}" aria-hidden="true"></i>`;

/** Lugar de um retrato, trocado pelo sprite depois do innerHTML (ver `pintarRetratosAnalise`). */
const lugarPk = (lt, px) => `<span class="gwa-pk" data-lt="${Number(lt) || 0}" data-px="${px}"></span>`;

function pintarRetratosAnalise(host) {
  for (const el of host.querySelectorAll('.gwa-pk:not(.pronto)')) {
    el.classList.add('pronto');
    const px = Number(el.dataset.px) || 28;
    el.appendChild(retratoDeLooktype(Number(el.dataset.lt) || 0, px));
  }
}

function htmlCabecalhoAnalise(a) {
  const tot = a.totais ?? {};
  const item = (valor, chave) => `<div class="gwa-cab-num"><b>${valor}</b><span>${t(chave)}</span></div>`;
  return `
    <div class="gwa-cab">
      ${item(num(tot.guilds), 'guild.analise.guilds')}
      ${item(num(tot.lutadores), 'guild.analise.lutadores')}
      ${item(num(tot.abates), 'guild.analise.abates')}
      ${item(numCurto(tot.dano), 'guild.analise.danoTotal')}
      ${item(num(tot.golpes), 'guild.analise.golpes')}
      ${item(tempoFita(a.dur), 'guild.analise.duracao')}
      ${a.motivo === 'tempo' ? `<em class="gwa-tag">${t('guild.pvpPorTempo')}</em>` : ''}
      ${a.semGolpes ? `<em class="gwa-tag">${t('guild.analise.semGolpes')}</em>` : ''}
    </div>`;
}

function htmlDestaquesAnalise(a) {
  const d = a.destaques ?? {};
  const quem = (x) => (x ? `${bolaGuild(x.g)}<b>${escapar(x.nick)}</b>` : '—');
  const cartao = ({ ico, rot, val, de, sub = '', classe = '', arte = '' }) => `
    <div class="gwa-dest ${classe}">
      <span class="gwa-dest-ico" aria-hidden="true">${arte || ico}</span>
      <span class="gwa-dest-txt">
        <span class="gwa-dest-rot">${rot}</span>
        <b class="gwa-dest-val">${val}</b>
        <span class="gwa-dest-quem">${de}</span>
        ${sub ? `<span class="gwa-dest-sub">${sub}</span>` : ''}
      </span>
    </div>`;
  const cartoes = [];
  if (d.dano) cartoes.push(cartao({ ico: '💥', rot: t('guild.analise.dDano'), val: num(d.dano.v), de: quem(d.dano), classe: 'ouro' }));
  if (d.abates) cartoes.push(cartao({ ico: '⚔️', rot: t('guild.analise.dAbates'), val: num(d.abates.v), de: quem(d.abates), classe: 'ouro' }));
  if (d.pokemon) {
    cartoes.push(cartao({
      arte: lugarPk(d.pokemon.lt, 44),
      rot: t('guild.analise.dPokemon'),
      val: `${d.pokemon.sh ? '✨' : ''}${escapar(d.pokemon.n)} <small>${t('painel.nivelCurto')} ${num(d.pokemon.nv)}</small>`,
      de: quem(d.pokemon),
      sub: t('guild.analise.dPokemonSub', { d: num(d.pokemon.v), k: num(d.pokemon.k) }),
      classe: 'lenda',
    }));
  }
  if (d.maiorGolpe) {
    cartoes.push(cartao({
      ico: '☄️',
      rot: t('guild.analise.dGolpe'),
      val: num(d.maiorGolpe.v),
      de: quem(d.maiorGolpe),
      sub: `${escapar(d.maiorGolpe.golpe ?? '')} ${d.maiorGolpe.tipo ? selosDeTipo([d.maiorGolpe.tipo]) : ''} · ${escapar(d.maiorGolpe.pk ?? '')} → ${escapar(d.maiorGolpe.alvo ?? '')}`,
    }));
  }
  if (d.muralha) cartoes.push(cartao({ ico: '🛡️', rot: t('guild.analise.dMuralha'), val: num(d.muralha.v), de: quem(d.muralha) }));
  if (d.superEfetivo) cartoes.push(cartao({ ico: '🎯', rot: t('guild.analise.dSuper'), val: num(d.superEfetivo.v), de: quem(d.superEfetivo) }));
  if (d.primeiroSangue) {
    const ps = d.primeiroSangue;
    const g = a.jogadores.find((j) => j.nick === ps.a)?.g ?? 0;
    cartoes.push(cartao({
      ico: '🩸',
      rot: t('guild.analise.dPrimeiro'),
      val: tempoFita(ps.t),
      de: quem({ nick: ps.a, g }),
      sub: t('guild.analise.dPrimeiroSub', { apk: escapar(ps.apk ?? ''), v: escapar(ps.v ?? ''), vpk: escapar(ps.vpk ?? '') }),
    }));
  }
  if (d.sobrevivente) {
    cartoes.push(cartao({
      ico: '⏱️',
      rot: t('guild.analise.dSobrevivente'),
      val: d.sobrevivente.vivo ? t('guild.analise.deOPe') : tempoFita(d.sobrevivente.ate),
      de: quem(d.sobrevivente),
    }));
  }
  return cartoes.length ? `<div class="gwa-dests">${cartoes.join('')}</div>` : '';
}

function htmlBarraJogadores(a) {
  const opcoesGuild = [...a.guilds]
    .sort((x, y) => x.pos - y.pos)
    .map((g) => `<option value="${g.i}"${analiseGw.guild === String(g.i) ? ' selected' : ''}>${g.pos}º · ${escapar(g.nome)}${g.id === estado.eu?.guild?.id ? ` (${t('guild.analise.minha')})` : ''}</option>`)
    .join('');
  return `
    <div class="gwa-barra">
      <label class="gwa-campo"><span>${t('guild.analise.guild')}</span>
        <select id="gwa-guild">
          <option value="todas"${analiseGw.guild === 'todas' ? ' selected' : ''}>${t('guild.analise.todas')}</option>
          ${opcoesGuild}
        </select></label>
      <label class="gwa-campo"><span>${t('cm.ordenarPor')}</span>
        <select id="gwa-ordem">
          ${ORDENS_ANALISE.map((o) => `<option value="${o.id}"${analiseGw.ordem === o.id ? ' selected' : ''}>${t(o.chave)}</option>`).join('')}
        </select></label>
      <span class="cm-busca-caixa gwa-busca-caixa">${lupa()}<input id="gwa-busca" class="cm-busca" maxlength="16" autocomplete="off"
        placeholder="${escapar(t('guild.analise.buscar'))}" value="${escapar(analiseGw.busca)}"></span>
    </div>`;
}

function htmlDetalheJogador(j) {
  const melhor = j.pks.reduce((m, p) => (!m || p.d > m.d ? p : m), null);
  const pks = j.pks.map((p) => `
    <div class="gwa-det-pk${p === melhor && p.d > 0 ? ' top' : ''}${p.caiu ? ' caiu' : ''}">
      ${p === melhor && p.d > 0 ? `<span class="gwa-det-selo">★ ${t('guild.analise.destaque')}</span>` : ''}
      ${lugarPk(p.lt, 48)}
      <b class="gwa-det-nome">${p.sh ? '✨' : ''}${escapar(p.n)}</b>
      <span class="gwa-det-nv">${t('painel.nivelCurto')} ${num(p.nv)}</span>
      <dl>
        <dt>${t('guild.analise.col.dano')}</dt><dd class="dano">${num(p.d)}</dd>
        <dt>${t('guild.analise.col.abates')}</dt><dd>${num(p.k)}</dd>
        <dt>${t('guild.analise.col.recebido')}</dt><dd>${num(p.r)}</dd>
        <dt>${t('guild.analise.col.golpes')}</dt><dd>${num(p.gl)}</dd>
      </dl>
      <span class="gwa-det-tempo">${p.caiu ? t('guild.analise.caiuAos', { t: tempoFita(p.ate) }) : t('guild.analise.terminouDePe')}</span>
    </div>`).join('');
  const maior = j.maior
    ? t('guild.analise.maiorGolpeDe', {
      v: num(j.maior.v), golpe: escapar(j.maior.golpe ?? ''), pk: escapar(j.maior.pk ?? ''), alvo: escapar(j.maior.alvo ?? ''),
    }) + (j.maior.tipo ? ` ${selosDeTipo([j.maior.tipo])}` : '')
    : '';
  return `
    <div class="gwa-det">
      <p class="gwa-det-resumo">
        <span>${t('guild.analise.resGolpes', { n: num(j.gl), s: num(j.sup) })}</span>
        <span>${j.vivo ? t('guild.analise.resDePe') : t('guild.analise.resCaiu', { t: tempoFita(j.caiuEm) })}</span>
        ${maior ? `<span>${maior}</span>` : ''}
      </p>
      <div class="gwa-det-pks">${pks}</div>
    </div>`;
}

function htmlListaJogadores(a) {
  const filtro = analiseGw.guild;
  const busca = analiseGw.busca.trim().toLowerCase();
  const ord = ORDENS_ANALISE.some((o) => o.id === analiseGw.ordem) ? analiseGw.ordem : 'd';
  const eu = (estado.eu?.nick ?? '').toLowerCase();
  const lista = a.jogadores
    .filter((j) => (filtro === 'todas' || String(j.g) === filtro) && (!busca || j.nick.toLowerCase().includes(busca)))
    .sort((x, y) => (Number(y[ord]) || 0) - (Number(x[ord]) || 0) || y.d - x.d || x.nick.localeCompare(y.nick));
  if (!lista.length) return `<p class="gwa-vazio">${t('guild.analise.ninguem')}</p>`;
  const topoD = Math.max(1, ...lista.map((j) => j.d));
  return lista.map((j, i) => {
    const aberto = analiseGw.abertos.has(j.nick);
    const melhor = j.pks.reduce((m, p) => (!m || p.d > m.d ? p : m), null);
    const g = guildDaAnalise(a, j.g);
    const mini = j.pks.map((p) => `<span class="gwa-mini${p === melhor && p.d > 0 ? ' top' : ''}${p.caiu ? ' caiu' : ''}"
        title="${escapar(`${p.sh ? '✨' : ''}${p.n} ${t('painel.nivelCurto')} ${p.nv} · ${num(p.d)} · ${p.k}⚔`)}">${lugarPk(p.lt, 26)}<em>${numCurto(p.d)}</em></span>`).join('');
    return `
      <div class="gwa-jog${aberto ? ' aberto' : ''}${j.nick.toLowerCase() === eu ? ' eu' : ''}">
        <button type="button" class="gwa-jog-linha" data-abrir="${escapar(j.nick)}" aria-expanded="${aberto ? 'true' : 'false'}">
          <span class="gwa-jog-pos">${i + 1}</span>
          <span class="gwa-jog-nome">${bolaGuild(j.g)}<span><b>${escapar(j.nick)}</b><small>${escapar(g?.nome ?? '')}${j.vivo ? ` · ${t('guild.analise.deOPe')}` : ''}</small></span></span>
          <span class="gwa-jog-dano"><b>${num(j.d)}</b><i class="gwa-trilho"><i style="width:${((j.d / topoD) * 100).toFixed(1)}%"></i></i></span>
          <span class="gwa-num k" title="${escapar(t('guild.analise.col.abates'))}">${num(j.k)}<small>⚔</small></span>
          <span class="gwa-num mo" title="${escapar(t('guild.analise.col.perdidos'))}">${num(j.mo)}<small>☠</small></span>
          <span class="gwa-num r" title="${escapar(t('guild.analise.col.recebido'))}">${numCurto(j.r)}<small>🛡</small></span>
          <span class="gwa-jog-pks">${mini}</span>
          <span class="gwa-jog-seta" aria-hidden="true">›</span>
        </button>
        ${aberto ? htmlDetalheJogador(j) : ''}
      </div>`;
  }).join('');
}

function htmlAbaJogadores(a) {
  return `
    ${htmlBarraJogadores(a)}
    <div class="gwa-jog-cab" aria-hidden="true">
      <span>#</span><span>${t('guild.analise.col.jogador')}</span><span>${t('guild.analise.col.dano')}</span>
      <span>⚔</span><span>☠</span><span>🛡</span><span>${t('guild.analise.col.pokemons')}</span><span></span>
    </div>
    <div class="gwa-lista" id="gwa-lista">${htmlListaJogadores(a)}</div>`;
}

function htmlAbaGuilds(a) {
  const minha = estado.eu?.guild?.id ?? null;
  const topoD = Math.max(1, ...a.guilds.map((g) => g.d));
  const linhas = a.guilds.map((g) => `
    <button type="button" class="gwa-g${g.id === minha ? ' eu' : ''}${g.pos === 1 ? ' campea' : ''}" data-ver-guild="${g.i}"
            title="${escapar(t('guild.analise.verJogadores'))}">
      <span class="gwa-g-pos">${g.pos}º</span>
      <span class="gwa-g-nome">${bolaGuild(g.i)}<span class="gd-mini" data-gid="${g.id}"></span><b>${escapar(g.nome)}</b></span>
      <span class="gwa-num lut" title="${escapar(t('guild.analise.col.lutadores'))}">${num(g.vivos)}/${num(g.n)}<small>👤</small></span>
      <span class="gwa-num k">${num(g.k)}<small>⚔</small></span>
      <span class="gwa-num mo">${num(g.mo)}<small>☠</small></span>
      <span class="gwa-jog-dano"><b>${numCurto(g.d)}</b><i class="gwa-trilho"><i style="width:${((g.d / topoD) * 100).toFixed(1)}%"></i></i></span>
      <span class="gwa-num r">${numCurto(g.r)}<small>🛡</small></span>
      <em class="gwa-g-gp">+${num(g.gp)} GP</em>
      <span class="gwa-g-mvp">${g.mvp ? `★ ${escapar(g.mvp)}` : '—'}</span>
    </button>`).join('');
  return `
    <div class="gwa-g-cab" aria-hidden="true">
      <span>#</span><span>${t('guild.analise.col.guild')}</span><span>${t('guild.analise.col.lutadores')}</span>
      <span>⚔</span><span>☠</span><span>${t('guild.analise.col.dano')}</span><span>🛡</span><span>GP</span><span>${t('guild.analise.col.mvp')}</span>
    </div>
    <div class="gwa-lista">${linhas}</div>`;
}

function htmlAbaPokemon(a) {
  const topoE = Math.max(1, ...(a.especies ?? []).map((e) => e.d));
  const topoG = Math.max(1, ...(a.golpes ?? []).map((e) => e.d));
  const especies = (a.especies ?? []).map((e, i) => `
    <div class="gwa-rank">
      <span class="gwa-rank-pos">${i + 1}</span>${lugarPk(e.lt, 32)}
      <span class="gwa-rank-nome"><b>${e.sh ? '✨' : ''}${escapar(e.n)}</b><small>${t('guild.analise.entradas', { n: num(e.usos) })} · ${num(e.k)}⚔</small></span>
      <span class="gwa-jog-dano"><b>${numCurto(e.d)}</b><i class="gwa-trilho"><i style="width:${((e.d / topoE) * 100).toFixed(1)}%"></i></i></span>
    </div>`).join('');
  const golpes = (a.golpes ?? []).map((g, i) => `
    <div class="gwa-rank">
      <span class="gwa-rank-pos">${i + 1}</span>
      <span class="gwa-rank-nome"><b>${escapar(g.n ?? '?')}</b><small>${g.t ? selosDeTipo([g.t]) : ''} ${t('guild.analise.usos', { n: num(g.usos) })}</small></span>
      <span class="gwa-jog-dano"><b>${numCurto(g.d)}</b><i class="gwa-trilho"><i style="width:${((g.d / topoG) * 100).toFixed(1)}%"></i></i></span>
    </div>`).join('');
  const fim = (a.abatesFinais ?? []).map((x) => `
    <li><time>${tempoFita(x.t)}</time> <b>${escapar(x.a)}</b> <em>(${escapar(x.apk)})</em> ⚔ <b>${escapar(x.v)}</b> <em>(${escapar(x.vpk)})</em></li>`).join('');
  return `
    <div class="gwa-duas">
      <section class="gwa-bloco"><h4>${t('guild.analise.topPokemon')}</h4>${especies || `<p class="gwa-vazio">—</p>`}</section>
      <section class="gwa-bloco"><h4>${t('guild.analise.topGolpes')}</h4>${golpes || `<p class="gwa-vazio">—</p>`}</section>
    </div>
    ${fim ? `<section class="gwa-bloco"><h4>${t('guild.analise.fimDaGuerra')}</h4><ul class="gwa-fim">${fim}</ul></section>` : ''}`;
}

function pintarAnaliseGuerra() {
  const a = analiseGw.dados;
  const host = $('#gwa-corpo');
  if (!a || !host) return;
  const aba = ['jogadores', 'guilds', 'pokemon'].includes(analiseGw.aba) ? analiseGw.aba : 'jogadores';
  const corpo = aba === 'guilds' ? htmlAbaGuilds(a) : aba === 'pokemon' ? htmlAbaPokemon(a) : htmlAbaJogadores(a);
  const rolagemAntes = host.querySelector('.gwa-rolo')?.scrollTop ?? 0;
  host.innerHTML = `
    <div class="gwa-rolo">
      ${htmlCabecalhoAnalise(a)}
      ${htmlDestaquesAnalise(a)}
      <div class="gwa-abas" role="tablist">
        ${['jogadores', 'guilds', 'pokemon'].map((id) => `<button type="button" role="tab" class="gwa-aba${aba === id ? ' on' : ''}"
          aria-selected="${aba === id ? 'true' : 'false'}" data-aba="${id}">${t(`guild.analise.aba.${id}`)}</button>`).join('')}
      </div>
      <div class="gwa-painel">${corpo}</div>
    </div>`;
  host.querySelector('.gwa-rolo').scrollTop = rolagemAntes;
  pintarRetratosAnalise(host);
  for (const el of host.querySelectorAll('.gd-mini')) {
    const g = a.guilds.find((x) => String(x.id) === el.dataset.gid);
    if (g?.brasao) pintarBrasao(el, g.brasao, 22);
  }
  const busca = host.querySelector('#gwa-busca');
  if (busca) {
    busca.oninput = (ev) => {
      analiseGw.busca = ev.target.value;
      // Só a LISTA é repintada: repintar a folha inteira tiraria o foco do campo a cada letra.
      const lista = host.querySelector('#gwa-lista');
      if (!lista) return;
      lista.innerHTML = htmlListaJogadores(a);
      pintarRetratosAnalise(lista);
    };
  }
  host.querySelector('#gwa-guild')?.addEventListener('change', (ev) => {
    analiseGw.guild = ev.target.value;
    pintarAnaliseGuerra();
  });
  host.querySelector('#gwa-ordem')?.addEventListener('change', (ev) => {
    analiseGw.ordem = ev.target.value;
    pintarAnaliseGuerra();
  });
}

$('#gwa-corpo').addEventListener('click', (ev) => {
  const aba = ev.target.closest('[data-aba]');
  if (aba) {
    analiseGw.aba = aba.dataset.aba;
    return pintarAnaliseGuerra();
  }
  const verGuild = ev.target.closest('[data-ver-guild]');
  if (verGuild) {
    analiseGw.guild = verGuild.dataset.verGuild;
    analiseGw.aba = 'jogadores';
    analiseGw.busca = '';
    return pintarAnaliseGuerra();
  }
  const abrir = ev.target.closest('[data-abrir]');
  if (abrir) {
    const nick = abrir.dataset.abrir;
    if (analiseGw.abertos.has(nick)) analiseGw.abertos.delete(nick);
    else analiseGw.abertos.add(nick);
    pintarAnaliseGuerra();
  }
});
$('#gwa-fechar').onclick = fecharAnaliseGuerra;
$('#gwa').onclick = (ev) => {
  if (ev.target === $('#gwa')) fecharAnaliseGuerra();
};

// ------------------------------------------- replay da Guerra de Guilds
//
// A guerra roda uma vez por dia no servidor, com todo mundo offline. Aqui só se ASSISTE: o
// pacote que chega é a gravação (`server/game/guild-pvp-sim.mjs`), e quem a transforma em cena
// é `replay.mjs`, que alimenta um segundo `Campo` — o mesmo renderizador do palco.
//
// Este bloco é só a casca: os botões, a linha do tempo e os painéis que ficam por cima do
// canvas. Nenhuma regra de batalha passa por aqui.

/** Uma cor por guild, para o placar e o feed. Sete tons que se separam em cima do mapa. */
const CORES_GUERRA = ['#ffd166', '#6fd3ff', '#8affc1', '#ff8a7a', '#d9a6ff', '#ffb347', '#9fe0a0'];
const corDaGuilda = (i) => CORES_GUERRA[i % CORES_GUERRA.length];

/** "2:07" — a leitura de uma fita, não de um relógio de jogo. */
const tempoFita = (ms) => {
  const s = Math.max(0, Math.round(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
};

let replayGuerra = null;
let pedindoReplay = false;

function pedirReplayGuerra() {
  if (pedindoReplay) return;
  pedindoReplay = true;
  toast(t('guild.pvpBaixandoReplay'));
  enviar({ t: 'guild.pvp.replay' });
  // A resposta pode não vir (servidor sem gravação, socket caído). Sem isto o botão ficaria
  // mudo para sempre depois de uma falha.
  setTimeout(() => {
    pedindoReplay = false;
  }, 15000);
}

/**
 * Fechar a batalha COMO JOGADOR — o ×, o clique no fundo, o Esc.
 *
 * Diferente de `fecharReplayGuerra`, que também é chamado por dentro (abrir uma fita nova
 * começa fechando a anterior) e não pode disparar termômetro nenhum.
 *
 * O termômetro só entra quando a fita ainda NÃO tinha revelado o resultado: se o cartão do
 * modal já mostrou o "+18", repetir o número num canto é barulho.
 */
function fecharBatalhaPvp() {
  const partida = partidaPvpAtual;
  const jaRevelou = !!$('#gwr-pvp-resultado')?.dataset.partida;
  fecharReplayGuerra();
  if (partida && !jaRevelou && !partida.amistoso) mostrarTickDeRank(partida);
}

function fecharReplayGuerra() {
  replayGuerra?.destruir();
  replayGuerra = null;
  // O resultado é de UMA partida. Sem esquecê-lo aqui, o replay seguinte (uma Guerra de
  // Guilds, um desafio de ginásio) terminaria mostrando o "+18" da partida anterior.
  partidaPvpAtual = null;
  const res = $('#gwr-pvp-resultado');
  if (res) {
    res.classList.add('hidden');
    res.innerHTML = '';
    delete res.dataset.partida;
  }
  $('#gwr').classList.add('hidden');
}

function abrirReplayGuerra(pacote) {
  pedindoReplay = false;
  const rep = pacote?.replay;
  if (!rep?.atores?.length) return toast(t('guild.pvpSemGuerra'));

  fecharReplayGuerra();
  $('#gwr').classList.remove('hidden');
  // O player é o mesmo da Guerra de Guilds, mas o cabeçalho não: o desafio de ginásio manda
  // o próprio título ("você foi amassado por Fulano"), a guerra manda o dia.
  $('#gwr-titulo').textContent = pacote.titulo ?? t('guild.pvpReplayTitulo', { dia: pacote.dia ?? '' });
  $('#gwr-carregando').textContent = t('cena.carregandoMapa');
  $('#gwr-carregando').classList.remove('hidden');

  // O canvas só tem tamanho depois de o modal sair do `hidden` — o `Campo` mede o pai no
  // construtor, e num elemento escondido isso dá zero.
  const player = new ReplayGuerra($('#gwr-campo'), rep, { aoAtualizar: pintarReplay });
  replayGuerra = player;
  montarControlesReplay(player);
  // O play espera o cenário: começar a fita com o mapa ainda baixando gastaria a abertura da
  // guerra numa tela preta. O `replayGuerra ===` é para o caso de fecharem o modal no meio.
  // `aoPronto` roda uma vez, entre o mapa carregar e a fita começar. É por onde a partida
  // ranqueada aplica o acelerador — chamar `iniciar()` de novo do lado de fora recarregaria o
  // mapa e recentralizaria a câmera, porque ele não é idempotente.
  player.iniciar().then(() => {
    if (replayGuerra !== player) return;
    pacote.aoPronto?.(player);
    player.tocar();
  });
}

function montarControlesReplay(player) {
  $('#gwr-vels').innerHTML = VELOCIDADES
    .map((v) => `<button type="button" class="gwr-vel${v === 1 ? ' on' : ''}" data-vel="${v}">${v}×</button>`)
    .join('');
  $('#gwr-vels').onclick = (ev) => {
    const b = ev.target.closest('.gwr-vel');
    if (!b) return;
    player.velocidade(Number(b.dataset.vel));
    sincronizarBotoesVel(player);
  };

  $('#gwr-play').onclick = () => player.alternar();
  // Enquanto o dedo está na barra, quem manda é ele: escrever o `value` a cada quadro faria a
  // alça escapar da mão de volta para o tempo corrente.
  $('#gwr-linha').oninput = (ev) => player.irPara((Number(ev.target.value) / 1000) * player.duracao);
  $('#gwr-linha').onpointerdown = () => {
    arrastandoLinha = true;
  };
  const soltarLinha = () => {
    arrastandoLinha = false;
  };
  $('#gwr-linha').onpointerup = soltarLinha;
  $('#gwr-linha').onpointercancel = soltarLinha;
  $('#gwr-linha').onblur = soltarLinha;
  $('#gwr-auto').textContent = t('guild.pvpReplayAuto');
  $('#gwr-auto').onclick = () => {
    player.auto = !player.auto;
    $('#gwr-auto').classList.toggle('on', player.auto);
    if (player.auto) player.escolherFoco();
  };
  $('#gwr-auto').classList.toggle('on', player.auto);

  // Recentralizar: some enquanto a câmera acompanha alguém, e só aparece quando o arrasto
  // solta ela (ver `pintarReplay`, que liga a visibilidade em `s.camLivre`). Clicar retoma o
  // MESMO foco de antes — `seguir` já cuida de desligar a câmera livre.
  $('#gwr-recentralizar').textContent = t('guild.pvpReplayRecentralizar');
  $('#gwr-recentralizar').title = t('guild.pvpReplayRecentralizar');
  $('#gwr-recentralizar').onclick = () => {
    if (player.focoSlot != null) player.seguir(player.focoSlot, true);
    else player.escolherFoco();
  };

  $('#gwr-zoom-mais').innerHTML = lupa('+');
  $('#gwr-zoom-menos').innerHTML = lupa('-');
  $('#gwr-zoom-mais').title = t('guild.pvpReplayZoomMais');
  $('#gwr-zoom-menos').title = t('guild.pvpReplayZoomMenos');
  const atualizarBotoesZoomReplay = () => {
    $('#gwr-zoom-mais').disabled = !player.campo.podeAproximar;
    $('#gwr-zoom-menos').disabled = !player.campo.podeAfastar;
  };
  const ajustarZoomReplay = (passo) => {
    player.campo.mudarZoom(passo);
    atualizarBotoesZoomReplay();
  };
  $('#gwr-zoom-mais').onclick = () => ajustarZoomReplay(+1);
  $('#gwr-zoom-menos').onclick = () => ajustarZoomReplay(-1);
  atualizarBotoesZoomReplay();
  // A roda sobre o palco também aproxima — mesmo gesto do palco ao vivo (`ajustarZoomCena`).
  $('.gwr-palco').onwheel = (ev) => {
    ev.preventDefault();
    ajustarZoomReplay(ev.deltaY < 0 ? +1 : -1);
  };

  $('#gwr-dica-arrasto').textContent = t('guild.pvpReplayDicaArrasto');

  // O painel lateral é fixo: quem entrou na guerra não muda no meio dela, e a guilda de
  // ninguém troca. Só o "vivos/total" de cada guilda e a classe "caído" mudam — e isso é
  // repintado no `pintarReplay`, sem reconstruir a lista inteira.
  const guilds = player.rep.guilds ?? [];
  const porGuilda = new Map(guilds.map((g, i) => [i, []]));
  for (const l of player.lutadores()) porGuilda.get(l.guilda)?.push(l);
  $('#gwr-lateral').innerHTML = guilds
    .map((g, i) => {
      const membros = porGuilda.get(i) ?? [];
      if (!membros.length) return '';
      return `
        <div class="gwr-lat-guild" style="--gw-cor:${corDaGuilda(i)}">
          <div class="gwr-lat-guild-tit">
            <span class="gwr-lat-guild-nome">${escapar(g.nome ?? '')}</span>
            <span class="gwr-lat-guild-vivos" data-guildvivos="${i}"></span>
          </div>
          <div class="gwr-lat-jogadores">
            ${membros
              .map(
                (l) => `<button type="button" class="gwr-lat-jog" data-slot="${l.slot}">
                  <b>${escapar(l.nick ?? '—')}</b>
                  <span>${escapar(l.pokemon ?? '')} ${t('painel.nivelCurto')}${num(l.nivel ?? 0)}</span>
                </button>`,
              )
              .join('')}
          </div>
        </div>`;
    })
    .join('');
  $('#gwr-lateral').onclick = (ev) => {
    const b = ev.target.closest('.gwr-lat-jog');
    if (b) player.seguir(Number(b.dataset.slot), true);
  };

  replayPintado = { t: -1, feed: -1, foco: null, vivos: '', camLivre: false, auto: null };
}

/** O que já foi desenhado, para não reescrever o DOM 60 vezes por segundo à toa. */
let replayPintado = { t: -1, feed: -1, foco: null, vivos: '', camLivre: false, auto: null };

/** A última coleção/nível que a aba de PvP desenhou — ver o ramo `'pvp'` de `atualizarModalAberto`. */
let ultimaAssinaturaPvp = '';
/** O nível com que o cabeçalho do Campeonato foi desenhado. Ver o ramo dele em `aplicarEstado`. */
let ultimoNivelCampeonato = -1;
let arrastandoLinha = false;

function pintarReplay(s) {
  const player = replayGuerra;
  if (!player) return;

  const carregando = $('#gwr-carregando');
  if (player.campo.mapa && !carregando.classList.contains('hidden')) carregando.classList.add('hidden');

  // O resultado da partida ranqueada, na lateral. Ele só entra quando a fita chega ao FIM —
  // revelar o "+18" no primeiro quadro entregaria o final antes do primeiro golpe.
  //
  // Duas condições, e a segunda não é redundante: `acabou` só é marcado quando a fita rodou
  // até o fim TOCANDO. Quem arrasta a barra até a ponta (a forma mais comum de dizer "me
  // mostra logo o resultado") chega em `t === dur` com `acabou` ainda falso, e ficaria olhando
  // para um painel vazio.
  pintarResultadoPvp(!!s.acabou || s.t >= s.dur);

  const seg = Math.floor(s.t / 500);
  if (seg !== replayPintado.t || s.tocando !== replayPintado.tocando) {
    replayPintado.t = seg;
    replayPintado.tocando = s.tocando;
    $('#gwr-tempo').textContent = `${tempoFita(s.t)} / ${tempoFita(s.dur)}`;
    if (!arrastandoLinha) $('#gwr-linha').value = String(Math.round((s.t / s.dur) * 1000));
    $('#gwr-play').textContent = s.tocando ? '❚❚' : s.acabou ? '↺' : '▶';
  }

  // A chave sai de `guildsTodas` (todas as guildas, sempre) e não de `guilds` (só as top-8 de
  // pé no cantinho): senão a guilda 9ª pra baixo perder um lutador nunca repintaria o painel
  // lateral, que mostra todo mundo.
  const vivos = s.guildsTodas.map((g) => `${g.idx}:${g.vivos}`).join(',');
  if (vivos !== replayPintado.vivos) {
    replayPintado.vivos = vivos;
    $('#gwr-guilds').innerHTML =
      s.guilds
        .map(
          (g) => `<div class="gwr-guild" style="--gw-cor:${corDaGuilda(g.idx)}">
            <span class="gwr-guild-nome">${escapar(g.nome ?? '')}</span>
            <span class="gwr-guild-vivos">${g.vivos}/${g.total}</span>
          </div>`,
        )
        .join('') +
      (s.guildsFora > 0
        ? `<div class="gwr-guild fora"><span class="gwr-guild-nome">${t('guild.pvpForaDoPlacar', { n: s.guildsFora })}</span></div>`
        : '');

    for (const g of s.guildsTodas) {
      const badge = $(`.gwr-lat-guild-vivos[data-guildvivos="${g.idx}"]`);
      if (badge) badge.textContent = `${g.vivos}/${g.total}`;
      const card = badge?.closest('.gwr-lat-guild');
      card?.classList.toggle('fora', g.vivos === 0);
    }
    for (const b of $('#gwr-lateral').querySelectorAll('.gwr-lat-jog')) {
      b.classList.toggle('gwr-caido', !!player.estado.get(Number(b.dataset.slot))?.fora);
    }
  }

  if (s.feed.length !== replayPintado.feed) {
    replayPintado.feed = s.feed.length;
    $('#gwr-feed').innerHTML = s.feed
      .map((e) => {
        const linha = e.p
          ? `<b>${escapar(e.a)}</b> ⚔ <em class="gwr-abate-pk">${escapar(e.p)}</em> <span>${t('guild.pvpAbateDe', { v: escapar(e.v) })}</span>`
          : `<b>${escapar(e.a)}</b> ⚔ <span>${escapar(e.v)}</span>`;
        return `<div class="gwr-abate" style="--gw-cor:${corDaGuilda(e.g)}">${linha}</div>`;
      })
      .join('');
  }

  if (s.foco !== replayPintado.foco) {
    replayPintado.foco = s.foco;
    const painel = $('#gwr-lateral');
    for (const b of painel.querySelectorAll('.gwr-lat-jog')) {
      b.classList.toggle('on', Number(b.dataset.slot) === s.foco);
    }
    // O painel acompanha a câmera automática, mas SÓ ele: `.gwr-lateral` tem `overflow-y`
    // PRÓPRIO (o `.modal-corpo` não rola mais — ver a CSS), então `scrollIntoView` aqui rola
    // só esta coluna, nunca o modal inteiro.
    painel.querySelector('.gwr-lat-jog.on')?.scrollIntoView({ block: 'nearest' });
  }

  // O botão de recentralizar só faz sentido depois que o arrasto solta a câmera do foco —
  // enquanto ela está seguindo alguém, mexer nele não faria nada.
  if (s.camLivre !== replayPintado.camLivre) {
    replayPintado.camLivre = s.camLivre;
    $('#gwr-recentralizar').classList.toggle('hidden', !s.camLivre);
  }

  // `player.auto` também muda FORA do clique no botão — o arrasto (ver `ligarArrasto`) desliga
  // sozinho, do mesmo jeito que soltar o pé do acelerador desarma o piloto automático. Sem este
  // espelhamento, o botão continuaria "ligado" (roxo) mesmo depois de a câmera automática ter
  // sido desligada por baixo.
  if (s.auto !== replayPintado.auto) {
    replayPintado.auto = s.auto;
    $('#gwr-auto').classList.toggle('on', s.auto);
  }
}

$('#gwr-fechar').onclick = fecharBatalhaPvp;
$('#gwr').onclick = (ev) => {
  // Bloco, e não expressão — ver a nota em `#confirmar`.
  if (ev.target === $('#gwr')) fecharBatalhaPvp();
};

// ------------------------------------------------------------------ guild

/**
 * Quem pode MEXER na guild: o dono e o sub-dono.
 *
 * As três ações que continuam sendo só do dono — apagar a guild, transferir a liderança e
 * nomear sub-dono — checam `isOwner` direto, porque as três são "tirar o dono do lugar"
 * escritas de outro jeito. Ver `mandoNaGuild` em `server/guild-db.mjs`, que é a trava de
 * verdade; isto aqui só decide o que a tela mostra.
 */
const podeGerirGuild = (g = estado.eu?.guild) => !!(g?.isOwner || g?.isSubdono);

const rascunhoBrasao = normalizarBrasao(null);
/** A TAG em edição — vale para a tela de criar e para o editor do painel. */
const rascunhoTag = { tag: '', cor: COR_TAG_PADRAO };

/**
 * A paleta de cores da TAG, montada num `host`.
 *
 * É a mesma gramática da paleta do brasão (`.guild-paleta` / `.guild-cor`), com uma diferença:
 * cada quadrado mostra as LETRAS na cor, e não a cor chapada. A tag é lida sobre o vidro preto
 * do chat, e um quadrado de `#ffffff` não conta como `[FAS]` branco vai ficar lá.
 */
function paletaDaTag(host, aoTrocar) {
  if (!host) return;
  const amostra = (rascunhoTag.tag || tagPadraoDoNome($('#guild-nome')?.value) || 'ABC');
  host.innerHTML = CORES_TAG.map(
    (c) => `<button type="button" class="guild-cor gld-cor-tag${rascunhoTag.cor === c ? ' on' : ''}"
              style="--gt:${c}" data-cor="${c}">${escapar(amostra)}</button>`,
  ).join('');
  host.onclick = (ev) => {
    const b = ev.target.closest('.gld-cor-tag');
    if (!b) return;
    rascunhoTag.cor = b.dataset.cor;
    paletaDaTag(host, aoTrocar);
    aoTrocar?.();
  };
}
const BRASAO_EDITAR_MS = 24 * 60 * 60 * 1000;
let guildModo = 'painel';

/** Horas (mín. 1) que faltam para o líder poder editar o brasão de novo. */
function horasRestantesBrasaoGuild(g = estado.eu?.guild) {
  const editado = Number(g?.brasaoEditadoEm) || 0;
  if (!editado) return 1;
  const resta = Math.max(0, BRASAO_EDITAR_MS - (Date.now() - editado));
  return Math.max(1, Math.ceil(resta / 3_600_000));
}

function pintarSlotGuild(guild, convites) {
  const el = $('#tr-guild');
  if (!el) return;
  const pendentes = convites ?? estado.eu?.guildConvites ?? [];
  if (guild?.brasao) {
    pintarBrasao(el, guild.brasao, 48);
    el.classList.add('tem-guild');
    // Quem manda na guild vê o mesmo brilho de "tem algo para você" quando alguém bate na porta.
    // Sem isto, o pedido ficaria esperando na caixa até o líder abrir o painel por outro motivo
    // — que é exatamente o problema do recado no chat, recriado dentro da tela nova.
    const pedidos = podeGerirGuild(guild) ? (Number(estado.guildPedidos) || 0) : 0;
    el.classList.toggle('tem-convite', pedidos > 0);
    el.title = pedidos > 0
      ? `${guild.nome} · ${t('guild.pedidosDica', { n: pedidos })}`
      : `${guild.nome} · ${num(guild.gp)} GP`;
  } else {
    el.innerHTML = '<span class="tr-guild-vazio">+</span>';
    el.classList.remove('tem-guild');
    el.classList.toggle('tem-convite', pendentes.length > 0);
    el.title = pendentes.length ? t('guild.convitesDica') : t('guild.criarDica');
  }
}

function fecharGuild() {
  $('#guild').classList.add('hidden');
  guildTopoVoltar(false);
  guildPainelMembroAberto = null;
  // A ABA sobrevive (reabrir cai onde a pessoa estava); a busca não — voltar a uma lista
  // filtrada por um nick que já nem se lembra de ter digitado parece uma guild que encolheu.
  guildBuscaMembros = '';
  // Mesma regra no Quadro, e pelo mesmo motivo: reabrir com "zero" digitado mostraria três
  // guilds e a impressão de que o servidor esvaziou. O filtro "onde eu entro" também volta ao
  // padrão; ele esconde guilds, e um filtro esquecido ligado é indistinguível de uma lista curta.
  quadroGuild.busca = '';
  quadroGuild.so = 'todas';
  quadroGuild.pagina = 0;
  quadroGuild.dados = null;
  clearTimeout(quadroTimer);
}

function guildTopoVoltar(mostrar) {
  const btn = $('#guild-voltar');
  btn?.classList.toggle('hidden', !mostrar);
  btn?.closest('.modal-topo-esq')?.classList.toggle('tem-voltar', mostrar);
  if (btn && mostrar) {
    const rot = t('guild.voltarLabel');
    btn.setAttribute('aria-label', rot);
    btn.title = rot;
  }
}

function abrirGuild() {
  enviar({ t: 'guild.info' });
  if (estado.eu?.guild) return montarGuildPainel();
  // Sem guild, a tela abre no QUADRO — a pergunta de quem não tem guild é "quais existem?", e
  // ela vinha sendo respondida com um formulário de fundar uma. Quem foi convidado cai direto
  // na aba dos convites: para ele a resposta já chegou, e fazê-lo procurá-la numa lista de
  // duzentas guilds seria esconder o que ele veio ver.
  if (!ABAS_SEM_GUILD.some((a) => a.id === guildAba)) {
    guildAba = (estado.eu?.guildConvites ?? []).length ? 'convites' : 'quadro';
  }
  montarGuildSemGuild();
}

/**
 * A força do pokémon NA GUERRA DE GUILDS — o ⚔ do card com o nível medido pela régua da guerra.
 *
 * A guerra mede o time com o nível comprimido (`nivelNaGuerra`, expoente 0,20): quem leva um
 * nv 3.000 luta como 273 (ver `pokemonDaLinha` em `server/game/guild-pvp.mjs`). Enquanto esta
 * tela mostrava o `poder` cru do ranking — que multiplica pelo nível REAL — o número do editor
 * prometia uma força que a arena nunca ia ver.
 *
 * ### Por que o nível é medido AQUI, e não dentro de `poderNoGinasio`
 *
 * A conta é a mesma máquina do pódio dos ginásios, mas o EXPOENTE é outro: a guerra comprime
 * mais que o ginásio, de propósito. Passar o pokémon cru daria a força na régua do ginásio, e
 * não na da guerra. Então o nível da guerra é aplicado antes de entregar o bicho ao medidor:
 * tudo que vem depois (stats, escolha de golpe, dps) lê `pk.level` e herda a régua certa de
 * uma vez só.
 */
const poderNaGuerra = (pk) =>
  poderNoGinasio({ ...pk, level: nivelNaGuerra(pk?.level) }, especieDe(pk));

/**
 * O nível como uma arena o lê: o real e, quando a compressão morde, quanto ele CONTA.
 *
 * Já foi "150 <s>287</s>" — o medido com o real riscado ao lado. O risco em cima do número
 * dizia "o que você fez ali não vale", e era verdade enquanto existia teto duro: acima de 150
 * o nível rendia zero. Com a compressão não é mais: nv 287 conta 168, nv 3.000 conta 578, e o
 * segundo número SOBE toda vez que o jogador upa. Mostrar os dois nessa ordem é a mesma
 * matemática contada do jeito que ela de fato funciona.
 */
function rotuloNivelDeArena(nivel, medido) {
  const n = Math.max(1, Math.floor(Number(nivel) || 1));
  const m = Math.max(1, Math.floor(Number(medido) || 1));
  return m < n ? t('arena.nivelConta', { nivel: n, medido: m }) : String(n);
}

/** O nível como a GUERRA o lê. */
const rotuloNivelNaGuerra = (nivel) => rotuloNivelDeArena(nivel, nivelNaGuerra(nivel));

/** Resumo curto da equipe de guerra salva (ou fallback da equipe de hunt). */
function resumoEquipeGuerra() {
  const salvos = estado.guildPvpEquipe;
  const pokemons = estado.eu?.pokemons ?? [];
  const ids =
    salvos === null
      ? pokemons.filter((p) => p.slot != null).map((p) => p.id)
      : salvos.filter((id) => pokemons.some((p) => p.id === id));
  if (!ids.length) {
    return salvos === null ? t('guild.timeResumoHuntVazio') : t('guild.timeResumoVazio');
  }
  const nomes = ids
    .map((id) => pokemons.find((p) => p.id === id))
    .filter(Boolean)
    .map((p) => p.nome)
    .join(', ');
  return t('guild.timeResumo', { n: ids.length, max: MAX_EQUIPE, nomes });
}

function idsEquipeGuerraInicial() {
  const pokemons = estado.eu?.pokemons ?? [];
  const salvos = estado.guildPvpEquipe;
  const base =
    salvos === null
      ? pokemons.filter((p) => p.slot != null).map((p) => p.id)
      : [...salvos];
  return base.filter((id) => pokemons.some((p) => p.id === id)).slice(0, MAX_EQUIPE);
}

function fecharEditorEquipeGuerra() {
  estado.guildSalvandoTime = false;
  editorGuerra = null;
  $('#guild-time-modal').classList.add('hidden');
  const corpo = $('#guild-time-corpo');
  corpo.innerHTML = '';
  corpo.classList.remove('dmpk', 'eqf', 'pkf-host', 'pkf-aberta');
}

/**
 * "Editar meu Time" da Guerra de Guilds — a mesma folha de equipe do PvP, dentro do modal
 * próprio da guerra (que fica por cima da janela da Guild). O que muda é a conta: o ⚔ é o da
 * GUERRA (nível capado), e a nota explica o teto. Fecha na confirmação (`guildEquipeSalva`).
 */
function abrirEditorEquipeGuerra() {
  $('#guild-time-titulo').textContent = t('guild.timeTitulo');
  estado.guildSalvandoTime = false;
  const corpo = $('#guild-time-corpo');
  editorGuerra = montarEscolhaDeEquipe(corpo, {
    max: MAX_EQUIPE,
    idsIniciais: idsEquipeGuerraInicial(),
    filtro: guerraEqFiltro,
    nota: `${t('guild.timeIntro', { max: MAX_EQUIPE })} ${t('guild.timeCapNivel', { cheio: ARENA_NIVEL_CHEIO })}`,
    notaIcone: 'escudo',
    contagem: (n) => t('guild.timeContagem', { n, max: MAX_EQUIPE }),
    extraContagem: (pks) => `${t('painel.poder')} <b>${num(pks.reduce((s, k) => s + (k ? poderNaGuerra(k) : 0), 0))}</b>`,
    rotuloSalvar: t('guild.timeSalvar'),
    rotuloLimpar: t('pvp.limpar'),
    rotuloCheio: t('guild.timeCheio', { max: MAX_EQUIPE }),
    salvando: () => !!estado.guildSalvandoTime,
    salvar: (ids) => {
      estado.guildSalvandoTime = true;
      enviar({ t: 'guild.pvp.equipe.salvar', pokemonIds: ids });
      setTimeout(() => {
        if (!estado.guildSalvandoTime) return;
        estado.guildSalvandoTime = false;
        repintarEditorEquipeGuerra();
      }, 10_000);
    },
  });
  $('#guild-time-modal').classList.remove('hidden');
}

/** A folha da equipe de guerra aberta (`{ repintar }`), ou `null`. */
let editorGuerra = null;

/** A recusa do servidor (aviso) destrava o "Salvar" da folha aberta. */
function repintarEditorEquipeGuerra() {
  if ($('#guild-time-modal').classList.contains('hidden')) return;
  editorGuerra?.repintar();
}

/**
 * O painel de quem NÃO tem guild — as mesmas abas de quem tem, com outras três perguntas.
 *
 * Antes, esta tela era um formulário de FUNDAR guild, com os convites recebidos na frente
 * quando havia algum. Quer dizer: para o jogador que queria entrar numa guild, o jogo respondia
 * "crie a sua" — e a única forma de achar uma era pedir no chat do mundo e esperar. Agora a
 * primeira coisa que ele vê é a lista de guildas que existem, e fundar é a terceira aba, para
 * quem chegou até ela querendo isso.
 */
function montarGuildSemGuild() {
  guildModo = 'painel';
  guildTopoVoltar(false);
  $('#guild-titulo').textContent = t('guild.titulo');
  const convites = (estado.eu?.guildConvites ?? []).length;
  $('#guild-corpo').innerHTML = `
    <div class="gld-abas gld-abas-3" role="tablist">
      ${ABAS_SEM_GUILD.map((a) => htmlAbaGuild(a, a.id === 'convites' ? convites : 0)).join('')}
    </div>
    <div class="gld-pane" id="gld-pane"></div>`;
  ligarAbasGuild(ABAS_SEM_GUILD, pintarPaneSemGuild);
  pintarPaneSemGuild();
  $('#guild').classList.remove('hidden');
}

function pintarPaneSemGuild() {
  const host = $('#gld-pane');
  if (!host || estado.eu?.guild) return;
  if (guildAba === 'convites') return pintarGuildConvites(host);
  if (guildAba === 'fundar') return pintarGuildFundar(host);
  pintarGuildQuadro(host);
}

function pintarGuildConvites(host) {
  const convites = estado.eu?.guildConvites ?? [];
  if (!convites.length) {
    host.innerHTML = `<p class="gld-vazio">${t('guild.semConvites')}</p>`;
    return;
  }
  const lista = convites
    .map(
      (c) => `<div class="guild-convite" data-id="${c.id}">
        <div class="guild-convite-brasao" id="guild-convite-brasao-${c.id}"></div>
        <div class="guild-convite-info">
          <b>${escapar(c.guildNome)}</b>
          <span>${t('guild.conviteDe', { nick: escapar(c.deNick) })}</span>
          <span class="guild-convite-gp">${num(c.gp)} GP</span>
        </div>
        <div class="guild-convite-acoes">
          <button type="button" class="guild-btn" data-aceitar="${c.id}">${t('guild.aceitar')}</button>
          <button type="button" class="guild-mini-btn btn-apagado" data-recusar="${c.id}">${t('guild.recusar')}</button>
        </div>
      </div>`,
    )
    .join('');
  host.innerHTML = `
    <p class="guild-ajuda">${t('guild.convitesAjuda')}</p>
    <div class="guild-convites-lista">${lista}</div>`;
  for (const c of convites) pintarBrasao($(`#guild-convite-brasao-${c.id}`), c.brasao, 48);
  for (const b of host.querySelectorAll('[data-aceitar]')) {
    b.onclick = () => enviar({ t: 'guild.aceitar', inviteId: Number(b.dataset.aceitar) });
  }
  for (const b of host.querySelectorAll('[data-recusar]')) {
    b.onclick = () => enviar({ t: 'guild.recusar', inviteId: Number(b.dataset.recusar) });
  }
}

function pintarGuildFundar(host) {
  const custo = num(estado.guildCusto ?? 250_000);
  host.innerHTML = `
    <p class="guild-ajuda">${t('guild.criarAjuda', { custo, max: estado.guildMaxTime ?? 10 })}</p>
    <label class="guild-campo">${t('guild.nome')}
      <input id="guild-nome" maxlength="16" autocomplete="off" placeholder="${t('guild.nomePh')}">
    </label>
    <!-- A TAG já na criação: deixar para depois faria a guild nascer com uma tag que ninguém
         escolheu e só aparece quando alguém fala no chat. Vazia continua valendo — aí valem as
         três primeiras letras do nome, e o campo mostra isso enquanto o nome é digitado. -->
    <label class="guild-campo">${t('guild.tagTitulo')}
      <div class="gld-tag-linha">
        <span class="gld-tag-previa" id="gld-tag-previa"></span>
        <input id="gld-tag-campo" maxlength="${MAX_TAG_GUILD}" autocomplete="off"
               placeholder="${escapar(t('guild.tagPh'))}">
      </div>
    </label>
    <div class="guild-cores gld-cores-criar">
      <span>${t('guild.tagCor')}</span>
      <div id="gld-tag-cores" class="guild-paleta gld-paleta-tag"></div>
    </div>
    <div class="guild-editor">
      <div class="guild-preview" id="guild-preview"></div>
      <div class="guild-opcoes">
        <label>${t('guild.escudo')}
          <select id="guild-escudo">${ESCUDOS.map((e) => `<option value="${e.id}">${e.nome}</option>`).join('')}</select>
        </label>
        <label>${t('guild.emblema')}
          <select id="guild-emblema">${EMBLEMAS.map((e) => `<option value="${e.id}">${e.nome}</option>`).join('')}</select>
        </label>
        <label>${t('guild.borda')}
          <select id="guild-borda">${BORDAS.map((e) => `<option value="${e.id}">${e.nome}</option>`).join('')}</select>
        </label>
        <div class="guild-cores">
          <span>${t('guild.corFundo')}</span><div id="guild-cor-bg" class="guild-paleta"></div>
          <span>${t('guild.corPri')}</span><div id="guild-cor-pri" class="guild-paleta"></div>
          <span>${t('guild.corSec')}</span><div id="guild-cor-sec" class="guild-paleta"></div>
        </div>
      </div>
    </div>
    <button type="button" class="guild-btn" id="guild-criar-btn">${t('guild.criarBtn', { custo })}</button>`;

  const repintar = () => {
    rascunhoBrasao.escudo = $('#guild-escudo').value;
    rascunhoBrasao.emblema = $('#guild-emblema').value;
    rascunhoBrasao.borda = $('#guild-borda').value;
    pintarBrasao($('#guild-preview'), rascunhoBrasao, 96);
  };
  // `alvo`, e não `host`: o parâmetro desta função já se chama assim, e sombreá-lo aqui faria
  // uma edição futura achar que está mexendo no painel inteiro.
  const paleta = (id, chave) => {
    const alvo = $(id);
    alvo.innerHTML = CORES_BRASAO.map(
      (c) => `<button type="button" class="guild-cor ${rascunhoBrasao[chave] === c ? 'on' : ''}" style="background:${c}" data-cor="${c}"></button>`,
    ).join('');
    alvo.onclick = (ev) => {
      const b = ev.target.closest('.guild-cor');
      if (!b) return;
      rascunhoBrasao[chave] = b.dataset.cor;
      paleta(id, chave);
      repintar();
    };
  };
  paleta('#guild-cor-bg', 'bg');
  paleta('#guild-cor-pri', 'pri');
  paleta('#guild-cor-sec', 'sec');
  $('#guild-escudo').onchange = repintar;
  $('#guild-emblema').onchange = repintar;
  $('#guild-borda').onchange = repintar;
  repintar();
  // A TAG da tela de criar. A prévia segue o NOME enquanto ninguém digita uma tag própria: é o
  // jeito de mostrar, sem explicar, que a guild já vai ter uma.
  rascunhoTag.tag = '';
  rascunhoTag.cor = COR_TAG_PADRAO;
  const campoTagNova = $('#gld-tag-campo');
  const previaTagNova = () => {
    const alvo = $('#gld-tag-previa');
    if (!alvo) return;
    const val = tagGuildValida(rascunhoTag.tag) ?? tagPadraoDoNome($('#guild-nome')?.value);
    alvo.style.setProperty('--gt', rascunhoTag.cor);
    alvo.textContent = val ?? '';
    alvo.classList.toggle('vazia', !val);
  };
  if (campoTagNova) {
    campoTagNova.oninput = () => {
      rascunhoTag.tag = campoTagNova.value;
      previaTagNova();
      paletaDaTag($('#gld-tag-cores'), previaTagNova);
    };
  }
  $('#guild-nome').addEventListener('input', previaTagNova);
  paletaDaTag($('#gld-tag-cores'), previaTagNova);
  previaTagNova();
  $('#guild-criar-btn').onclick = () => {
    const nome = $('#guild-nome').value.trim();
    if (!nome) return toast(t('guild.nomeObrigatorio'));
    enviar({
      t: 'guild.criar',
      nome,
      brasao: { ...rascunhoBrasao },
      tag: rascunhoTag.tag,
      tagCor: rascunhoTag.cor,
    });
  };
}

// ------------------------------------------------- o painel da guild: faixa, abas, listas
//
// A tela nasceu como uma PILHA: cabecalho de texto, lista, e cinco botoes roxos de largura
// cheia empilhados — "Time da Guild", "Minha equipe de guerra", "Editar brasao", "Convidar",
// "Apagar guild". Todos com o mesmo peso visual, do primeiro ao que apaga a guild inteira, e
// no celular tudo isso era um rolo de tela e meia antes do primeiro membro.
//
// O arranjo de agora e o de uma tela de cla: uma FAIXA de identidade em cima (brasao grande,
// nome, dono, e os tres numeros que definem a guild em placas), ABAS logo abaixo, e so entao o
// conteudo. Cada aba responde a uma pergunta, e nenhuma delas e "o que esses cinco botoes
// fazem?":
//
//   Membros  quem esta aqui (e, para o dono, como chamar mais gente)
//   Guerra   o que EU levo e quem a guild escala
//   Guild    o brasao e a saida — o que se mexe uma vez e nao se mexe mais
//
// O que some da tela e o ganho: o dono deixa de ver "Apagar guild" toda vez que abre o painel
// para olhar quem esta online, e as acoes por membro (expulsar, passar a lideranca) saem da
// LINHA — onde apertavam o nick contra dois botoes roxos — e passam a morar dentro do membro
// aberto, junto com a equipe dele.

/** Aba aberta do painel. Vive fora da funcao: todo pacote de guild repinta a tela. */
let guildAba = 'membros';
/** Busca da lista de membros. Mesma vida da aba. */
let guildBuscaMembros = '';
/** A partir de quantos membros a busca aparece — abaixo disso ela so rouba altura. */
const GLD_BUSCA_MIN = 8;

/**
 * Os desenhos da tela de guild.
 *
 * SVG inline, e nao emoji nem PNG: emoji muda de desenho (e de largura) a cada sistema, e o
 * espelho de assets nao tem icone de troféu nem de espada. Inline, eles herdam `currentColor`
 * e acompanham a cor do estado — aceso no roxo da aba ligada, apagado no resto.
 */
const SVG_GLD = {
  gp: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M7 3h10v1h4v3a4 4 0 0 1-4 4h-.6A5.6 5.6 0 0 1 13 15.8V18h4v3H7v-3h4v-2.2A5.6 5.6 0 0 1 7.6 11H7a4 4 0 0 1-4-4V4h4V3zm0 3H5v1a2 2 0 0 0 2 2V6zm10 0v3a2 2 0 0 0 2-2V6h-2z"/></svg>',
  membros: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M9 11a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7zm7.8 0a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM2 19.2c0-3.2 3.1-5.4 7-5.4s7 2.2 7 5.4V20H2v-.8zm15.6-4.5c2.7.6 4.4 2.3 4.4 4.3V20h-4.3v-.8c0-1.7-.6-3.2-1.7-4.3l1.6-.2z"/></svg>',
  time: '<svg viewBox="0 0 24 24" aria-hidden="true"><g fill="currentColor"><path d="M3 3h3.2l11 11-3.2 3.2L3 6.2V3z"/><path d="M21 3h-3.2l-4.3 4.3 3.2 3.2L21 6.2V3z"/><path d="M8.6 12.9 4.3 17.2l-1.4 3.9 3.9-1.4 4.3-4.3-2.5-2.5z" opacity=".75"/><path d="M15.4 12.9l4.3 4.3 1.4 3.9-3.9-1.4-4.3-4.3 2.5-2.5z" opacity=".75"/></g></svg>',
  escudo: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2l8 3.2v6.1c0 4.9-3.4 9.1-8 10.7-4.6-1.6-8-5.8-8-10.7V5.2L12 2z"/></svg>',
  convidar: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M10 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm0 2c-3.9 0-7 2.1-7 4.8V20h11.4A6 6 0 0 1 13 15.6 11 11 0 0 0 10 14zm8 0h2v3h3v2h-3v3h-2v-3h-3v-2h3v-3z"/></svg>',
  coroa: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M3 7.5l4 3.2L12 4l5 6.7 4-3.2-1.7 11H4.7L3 7.5z"/></svg>',
  sair: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h5v-2H5V5h5V3zm6.6 3.6L15.2 8l3 3H9v2h9.2l-3 3 1.4 1.4L22 12l-5.4-5.4z"/></svg>',
  lupa: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M10.5 3a7.5 7.5 0 0 1 5.9 12.1l4.3 4.3-1.4 1.4-4.3-4.3A7.5 7.5 0 1 1 10.5 3zm0 2a5.5 5.5 0 1 0 0 11 5.5 5.5 0 0 0 0-11z"/></svg>',
  porta: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M5 3h9a2 2 0 0 1 2 2v16H5V3zm7.5 8.2a1.2 1.2 0 1 0 0 2.4 1.2 1.2 0 0 0 0-2.4zM17 7h2v14h-2V7z"/></svg>',
};

/** O bonus de ranking da guild, em chip — ou nada, quando ela nao pontuou. */
function chipBonusGuild(g) {
  const pct = Number(g.bonusPct) || 0;
  const rank = Number(g.bonusRank) || 0;
  if (!(pct > 0 && rank > 0)) {
    return `<span class="gld-chip gld-chip-off">${t('guild.semBonus')}</span>`;
  }
  return `<span class="gld-chip gld-chip-on" title="${escapar(
    t('guild.bonusAtivo', { top: rotuloTopGuild(rank), n: pct }),
  )}">${t('guild.bonusChip', { top: rotuloTopGuild(rank), n: pct })}</span>`;
}

/**
 * A FAIXA: brasao, nome, dono, idade da guild e as tres placas de numero.
 *
 * As placas nao sao enfeite — sao as tres perguntas que a tela recebe ("quanto a guild fez
 * hoje?", "quantos somos?", "o time esta cheio?"), e a terceira e um BOTAO: quem olha "8/10"
 * quer mexer nisso, e obrigá-lo a achar a aba Guerra para isso seria esconder a acao atras do
 * numero que a provoca.
 */
function htmlBannerGuild(g) {
  const max = estado.guildMaxTime ?? 10;
  const criada = Number(g.criadoEm) || 0;
  return `
    <div class="gld-banner">
      <div class="gld-brasao" id="gld-brasao"></div>
      <div class="gld-ident">
        <b class="gld-nome">${g.tag
          ? `<span class="gld-tag" style="--gt:${corTagValida(g.tagCor)}">${escapar(g.tag)}</span> `
          : ''}${escapar(g.nome)}</b>
        <span class="gld-sub">
          <span class="gld-dono">${SVG_GLD.coroa}${escapar(g.ownerNick ?? '')}</span>
          ${criada ? `<span class="gld-idade">${t('guild.criadaHa', { tempo: tempoCurto(Date.now() - criada) })}</span>` : ''}
        </span>
        ${chipBonusGuild(g)}
      </div>
    </div>
    <div class="gld-stats">
      <div class="gld-stat">
        <span class="gld-stat-ico">${SVG_GLD.gp}</span>
        <b>${num(g.gp)}</b><span>${t('guild.statGp')}</span>
      </div>
      <div class="gld-stat">
        <span class="gld-stat-ico">${SVG_GLD.membros}</span>
        <b>${num(Number(g.membros) || 0)}</b><span>${t('guild.statMembros')}</span>
      </div>
      <button type="button" class="gld-stat gld-stat-bt" id="gld-stat-time"
              title="${escapar(t('guild.escalacaoBt'))}">
        <span class="gld-stat-ico">${SVG_GLD.time}</span>
        <b>${Number(g.escalados) || 0}/${max}</b><span>${t('guild.statTime')}</span>
      </button>
    </div>
    <p class="gld-eu ${g.escalado ? 'ok' : 'fora'}">
      ${g.escalado ? t('guild.euEscaladoCurto') : t('guild.euReserva')}
    </p>`;
}

const ABAS_GUILD = [
  { id: 'membros', chave: 'guild.abaMembros', ico: 'membros' },
  { id: 'caixa', chave: 'guild.abaCaixa', ico: 'convidar' },
  { id: 'quadro', chave: 'guild.abaQuadro', ico: 'lupa' },
  { id: 'guerra', chave: 'guild.abaGuerra', ico: 'time' },
  { id: 'ajustes', chave: 'guild.abaAjustes', ico: 'escudo' },
];

/** As três de quem ainda não tem guild. A ordem é a das perguntas dele, nessa ordem. */
const ABAS_SEM_GUILD = [
  { id: 'quadro', chave: 'guild.abaQuadro', ico: 'lupa' },
  { id: 'convites', chave: 'guild.abaConvites', ico: 'convidar' },
  { id: 'fundar', chave: 'guild.abaFundar', ico: 'escudo' },
];

/**
 * Uma aba, com o selo de pendência quando há o que responder.
 *
 * O selo é um NÚMERO, e não uma bolinha: "3" diz que vale abrir agora, a bolinha diz só que
 * algo mudou. É a mesma decisão da aba de chat da guild, que já mostra contagem.
 */
function htmlAbaGuild(a, selo = 0) {
  const on = a.id === guildAba;
  return `
    <button type="button" class="gld-aba${on ? ' on' : ''}" data-aba="${a.id}"
            role="tab" aria-selected="${on ? 'true' : 'false'}">
      <span class="gld-aba-ico">${SVG_GLD[a.ico]}</span>${t(a.chave)}
      ${selo > 0 ? `<span class="gld-aba-selo">${selo > 99 ? '99+' : selo}</span>` : ''}
    </button>`;
}

/**
 * Liga o clique das abas de um painel de guild.
 *
 * Só as CLASSES trocam ao mudar de aba — o cabeçalho e a barra não são redesenhados. Repintar o
 * painel inteiro aqui apagaria o campo de busca do Quadro no meio da digitação de quem clicasse
 * numa aba e voltasse, e é o mesmo motivo pelo qual a lista de membros repinta sozinha.
 */
function ligarAbasGuild(abas, repintar) {
  for (const bt of $('#guild-corpo').querySelectorAll('.gld-aba')) {
    bt.onclick = () => {
      if (guildAba === bt.dataset.aba) return;
      guildAba = bt.dataset.aba;
      for (const x of $('#guild-corpo').querySelectorAll('.gld-aba')) {
        const on = x.dataset.aba === guildAba;
        x.classList.toggle('on', on);
        x.setAttribute('aria-selected', on ? 'true' : 'false');
      }
      repintar();
    };
  }
  return abas;
}

function montarGuildPainel() {
  guildModo = 'painel';
  const g = estado.eu.guild;
  guildTopoVoltar(false);
  $('#guild-titulo').textContent = g.nome;
  // Quem está no painel COM guild pode ter vindo de uma aba que só existe sem guild (acabou de
  // entrar estando no Quadro, ou aceitou um convite). `quadro` é a única que atravessa os dois
  // modos; as outras caem em Membros, que é a tela que ele quer ver ao entrar numa guild.
  if (!ABAS_GUILD.some((a) => a.id === guildAba)) guildAba = 'membros';
  $('#guild-corpo').innerHTML = `
    ${htmlBannerGuild(g)}
    <div class="gld-abas gld-abas-5" role="tablist">
      ${ABAS_GUILD.map((a) => htmlAbaGuild(a, a.id === 'caixa' ? (estado.guildPedidos || 0) : 0)).join('')}
    </div>
    <div class="gld-pane" id="gld-pane"></div>`;

  pintarBrasao($('#gld-brasao'), g.brasao, 62);
  $('#gld-stat-time')?.addEventListener('click', abrirEscalacaoGuild);
  ligarAbasGuild(ABAS_GUILD, pintarPaneGuild);
  pintarPaneGuild();
  $('#guild').classList.remove('hidden');
}

function pintarPaneGuild() {
  const host = $('#gld-pane');
  const g = estado.eu?.guild;
  if (!host || !g) return;
  if (guildAba === 'guerra') return pintarGuildGuerra(host, g);
  if (guildAba === 'ajustes') return pintarGuildAjustes(host, g);
  if (guildAba === 'quadro') return pintarGuildQuadro(host);
  if (guildAba === 'caixa') return pintarGuildCaixa(host, g);
  pintarGuildMembros(host, g);
}

// ------------------------------------------------------------------ aba Quadro
//
// A lista de TODAS as guildas do servidor — a tela que faltava.
//
// O recrutamento do jogo era uma linha no chat do mundo: "guild recrutando, chama no pv". A
// mensagem subia em dez segundos, quem entrava um minuto depois não via nada, e o líder que
// estava offline na hora perdia o jogador. Quem procurava guild tinha de ficar olhando o chat.
//
// Aqui a oferta fica PARADA: cada guild diz o nome, o brasão, quantos são, quanto fizeram e —
// o que decide o clique — se ela aceita gente agora. O botão da linha já é a ação, e não um
// "fale com o líder": `Entrar` nas abertas, `Candidatar-se` nas fechadas, e o requisito escrito
// quando ele é o que barra.

/** O que o Quadro está mostrando. Vive fora da função: cada resposta do servidor repinta. */
const quadroGuild = {
  busca: '',
  so: 'todas',
  pagina: 0,
  dados: null,
  pedindo: false,
};

/** Espera entre a última tecla e o pedido ao servidor. O mesmo do Mercado. */
const QUADRO_DEBOUNCE_MS = 250;
let quadroTimer = 0;

function pedirQuadroGuild({ pagina = quadroGuild.pagina } = {}) {
  quadroGuild.pagina = pagina;
  quadroGuild.pedindo = true;
  enviar({
    t: 'guild.quadro',
    busca: quadroGuild.busca,
    so: quadroGuild.so,
    pagina,
  });
}

/** A busca digitada: espera o dedo parar antes de ir ao servidor, e volta para a página 1. */
function agendarBuscaQuadro() {
  clearTimeout(quadroTimer);
  quadroTimer = setTimeout(() => pedirQuadroGuild({ pagina: 0 }), QUADRO_DEBOUNCE_MS);
}

/**
 * Eu, como a porta de uma guild me mede: nível e PR.
 *
 * O PR sai de `estado.eu.pvp.pontos` — o mesmo número que a ficha do treinador mostra embaixo
 * do emblema. Não existe `estado.eu.elo`: o ELO da arena aposentada nem viaja mais para a tela,
 * e usá-lo aqui daria `undefined` em todo mundo, pintando "você não alcança" em toda guild com
 * requisito de PvP. O servidor mede pelo mesmo campo (`jogadorParaRequisito`, em `sim.mjs`).
 */
const meuNivelEPr = () => ({
  level: estado.eu?.level,
  pr: Number(estado.eu?.pvp?.pontos) || 0,
});

/** Quanto ainda falta da espera de quem saiu de uma guild, em ms (0 = pode entrar). */
function esperaGuildRestante() {
  const ate = Number(estado.guildEsperaAte) || 0;
  return Math.max(0, ate - Date.now());
}

/**
 * O chip da política, que é o que a pessoa lê antes de tudo na linha.
 *
 * Três cores para três respostas diferentes, e não um texto só: verde é "entra agora", âmbar é
 * "entra se alcançar", madeira é "precisa pedir". Quem varre a lista decide pela cor e só lê a
 * que interessa.
 */
function chipPoliticaGuild(g) {
  if (g.politica === 'aberta') {
    return `<span class="gldq-chip aberta">${t('guild.polAbertaChip')}</span>`;
  }
  if (g.politica === 'requisitos') {
    const req = [
      g.reqLevel > 0 ? t('guild.reqLevelChip', { n: num(g.reqLevel) }) : '',
      g.reqPr > 0 ? t('guild.reqPrChip', { n: num(g.reqPr) }) : '',
    ].filter(Boolean).join(' · ');
    return `<span class="gldq-chip req">${req || t('guild.polReqChip')}</span>`;
  }
  return `<span class="gldq-chip fechada">${t('guild.polFechadaChip')}</span>`;
}

/**
 * O botão do fim da linha — a única parte da lista que muda de pessoa para pessoa.
 *
 * A ordem das recusas importa: a espera de quem saiu vem ANTES do requisito, porque ela pega
 * todas as guilds ao mesmo tempo e explicar o nível de uma guild para quem não pode entrar em
 * nenhuma seria responder a pergunta errada.
 */
function htmlBotaoQuadro(g) {
  if (estado.eu?.guild) return '';
  const espera = esperaGuildRestante();
  if (espera > 0) {
    return `<button type="button" class="guild-mini-btn btn-apagado gldq-bt" disabled
                    title="${escapar(t('guild.esperaDica'))}">${t('guild.esperaCurto', { tempo: tempoCurto(espera) })}</button>`;
  }
  if (g.pedido) {
    return `<button type="button" class="guild-mini-btn gldq-bt btn-apagado" data-cancelar="${g.id}"
                    title="${escapar(t('guild.cancelarPedidoDica'))}">${t('guild.aguardando')}</button>`;
  }
  const acao = acaoDeEntrada(g, meuNivelEPr());
  if (acao === 'entrar') {
    return `<button type="button" class="guild-btn gldq-bt" data-entrar="${g.id}">${t('guild.entrarBt')}</button>`;
  }
  if (acao === 'candidatar') {
    return `<button type="button" class="guild-btn gldq-bt" data-candidatar="${g.id}">${t('guild.candidatarBt')}</button>`;
  }
  // `requisito`: o botão fica apagado E diz o que falta. Um botão desabilitado sem motivo é a
  // tela dizendo "não" e virando as costas.
  const falta = faltaParaEntrar(g, meuNivelEPr());
  return `<button type="button" class="guild-mini-btn btn-apagado gldq-bt" disabled>${
    t(falta?.campo === 'pr' ? 'guild.faltaPr' : 'guild.faltaLevel', { n: num(falta?.minimo ?? 0) })
  }</button>`;
}

function htmlLinhaQuadro(g) {
  return `
    <div class="gldq-linha" data-guild="${g.id}">
      <span class="gldq-brasao" id="gldq-brasao-${g.id}"></span>
      <div class="gldq-info">
        <b class="gldq-nome">${g.tag
          ? `<span class="gld-tag" style="--gt:${corTagValida(g.tagCor)}">${escapar(g.tag)}</span> `
          : ''}${escapar(g.nome)}</b>
        <span class="gldq-nums">
          <span>${num(g.membros)} ${t('guild.statMembros')}</span>
          <span>${num(g.gp)} GP</span>
          ${chipPoliticaGuild(g)}
        </span>
        ${g.descricao ? `<span class="gldq-desc">${escapar(g.descricao)}</span>` : ''}
      </div>
      ${htmlBotaoQuadro(g)}
    </div>`;
}

function pintarGuildQuadro(host) {
  const temGuild = !!estado.eu?.guild;
  host.innerHTML = `
    <div class="gldq-topo">
      <input id="gldq-busca" class="gld-campo gldq-busca" type="search" autocomplete="off"
             maxlength="32" placeholder="${escapar(t('guild.quadroBuscaPh'))}"
             value="${escapar(quadroGuild.busca)}">
      ${temGuild ? '' : `
        <label class="gldq-filtro">
          <input type="checkbox" id="gldq-so-posso" ${quadroGuild.so === 'posso' ? 'checked' : ''}>
          <span>${t('guild.quadroSoPosso')}</span>
        </label>`}
    </div>
    <p class="gd-ajuda" id="gldq-resumo"></p>
    <div class="gldq-lista" id="gldq-lista"></div>
    <div class="gldq-paginacao" id="gldq-paginacao"></div>`;

  const campo = $('#gldq-busca');
  if (campo) {
    campo.oninput = () => {
      quadroGuild.busca = campo.value;
      agendarBuscaQuadro();
    };
  }
  $('#gldq-so-posso')?.addEventListener('change', (ev) => {
    quadroGuild.so = ev.target.checked ? 'posso' : 'todas';
    pedirQuadroGuild({ pagina: 0 });
  });

  pintarListaQuadro();
  // Sempre pede ao abrir: a lista envelhece rápido (guilds enchem, abrem e fecham) e o que
  // estava em cache era do minuto passado. O que já está desenhado fica na tela enquanto a
  // resposta não chega, em vez de piscar um vazio.
  pedirQuadroGuild();
}

/**
 * Só a LISTA se repinta quando a resposta chega — o campo de busca fica de fora de propósito.
 *
 * Redesenhar o painel inteiro a cada resposta tiraria o cursor do campo no meio da digitação:
 * com debounce de 250 ms, a resposta da terceira letra chega enquanto a pessoa digita a quinta.
 */
function pintarListaQuadro() {
  const lista = $('#gldq-lista');
  if (!lista) return;
  const d = quadroGuild.dados;
  const resumo = $('#gldq-resumo');

  if (!d) {
    lista.innerHTML = `<p class="guild-membros-carregando">${t('guild.escalacaoCarregando')}</p>`;
    if (resumo) resumo.textContent = '';
    $('#gldq-paginacao').innerHTML = '';
    return;
  }

  if (resumo) {
    const espera = esperaGuildRestante();
    // A espera é a informação que governa a tela inteira de quem saiu há pouco: sem ela em
    // cima, ele lê uma lista de botões apagados e conclui que a tela está quebrada.
    resumo.innerHTML = espera > 0
      ? `<span class="gldq-espera">${t('guild.esperaAviso', { tempo: tempoCurto(espera) })}</span>`
      : t('guild.quadroResumo', { n: num(d.total), total: num(estado.guildTotal ?? d.total) });
  }

  if (!d.itens.length) {
    lista.innerHTML = `<p class="gld-vazio">${t(quadroGuild.busca ? 'guild.quadroSemBusca' : 'guild.quadroVazio')}</p>`;
    $('#gldq-paginacao').innerHTML = '';
    return;
  }

  lista.innerHTML = d.itens.map(htmlLinhaQuadro).join('');
  for (const g of d.itens) pintarBrasao($(`#gldq-brasao-${g.id}`), g.brasao, 38);

  // Clique na LINHA abre a ficha pública (a mesma do Ranking de Guilds): quem vai entrar numa
  // guild quer ver quem está nela antes. Os botões param o clique para não abrir a ficha junto.
  lista.onclick = (ev) => {
    const bt = ev.target.closest('button');
    if (bt) {
      ev.stopPropagation();
      if (bt.dataset.entrar) return enviar({ t: 'guild.entrar', guildId: Number(bt.dataset.entrar) });
      if (bt.dataset.candidatar) {
        return enviar({ t: 'guild.candidatar', guildId: Number(bt.dataset.candidatar) });
      }
      if (bt.dataset.cancelar) {
        return enviar({ t: 'guild.candidatura.cancelar', guildId: Number(bt.dataset.cancelar) });
      }
      return;
    }
    const linha = ev.target.closest('.gldq-linha');
    if (linha) pedirDetalheGuild(Number(linha.dataset.guild));
  };

  const paginas = Math.max(1, Math.ceil(d.total / (d.porPagina || 20)));
  const pag = $('#gldq-paginacao');
  pag.innerHTML = paginas <= 1 ? '' : `
    <button type="button" class="guild-mini-btn btn-apagado" id="gldq-ant" ${d.pagina <= 0 ? 'disabled' : ''}>‹</button>
    <span>${t('guild.quadroPagina', { n: d.pagina + 1, de: paginas })}</span>
    <button type="button" class="guild-mini-btn btn-apagado" id="gldq-prox" ${d.pagina + 1 >= paginas ? 'disabled' : ''}>›</button>`;
  $('#gldq-ant')?.addEventListener('click', () => pedirQuadroGuild({ pagina: d.pagina - 1 }));
  $('#gldq-prox')?.addEventListener('click', () => pedirQuadroGuild({ pagina: d.pagina + 1 }));
}

// ------------------------------------------------------------------- aba Caixa
//
// Quem está a caminho da guild: os que pediram para entrar e os que foram convidados e ainda
// não responderam. TODO membro lê — saber quem bate na porta é parte de ser da guild, e o
// membro comum que reconhece um amigo na fila vai cutucar o líder. Só dono e sub-dono agem.

function htmlPedidoGuild(pd, podeAgir) {
  return `
    <div class="gldc-linha" data-pedido="${pd.id}">
      <div class="gldc-info">
        <b>${escapar(pd.nick)}</b>
        <span class="gldc-nums">
          <span>${t('painel.nivelCurto')}${num(pd.level)}</span>
          <span>${num(pd.pr)} ${t('pvp.pr')}</span>
          <span class="gldc-quando">${t('guild.pedidoHa', { tempo: tempoCurto(Date.now() - (pd.criadoEm || Date.now())) })}</span>
        </span>
      </div>
      ${podeAgir ? `
        <div class="gldc-acoes">
          <button type="button" class="guild-btn" data-aceitar-pedido="${pd.id}">${t('guild.aceitar')}</button>
          <button type="button" class="guild-mini-btn btn-apagado" data-recusar-pedido="${pd.id}">${t('guild.recusar')}</button>
        </div>` : ''}
    </div>`;
}

function pintarGuildCaixa(host, g) {
  const podeAgir = podeGerirGuild(g);
  const caixa = estado.guildCaixa;
  if (!caixa) {
    host.innerHTML = `<p class="guild-membros-carregando">${t('guild.escalacaoCarregando')}</p>`;
    enviar({ t: 'guild.caixa' });
    return;
  }

  const pedidos = caixa.pedidos ?? [];
  const convites = caixa.convites ?? [];
  host.innerHTML = `
    <section class="gld-bloco">
      <h4 class="gld-bloco-tit">${t('guild.pedidosTitulo')} ${pedidos.length ? `(${pedidos.length})` : ''}</h4>
      <p class="gld-bloco-sub">${t(
        g.politica === 'fechada' ? 'guild.pedidosSub' : 'guild.pedidosSubAberta',
      )}</p>
      ${pedidos.length
        ? `<div class="gldc-lista">${pedidos.map((pd) => htmlPedidoGuild(pd, podeAgir)).join('')}</div>`
        : `<p class="gld-vazio">${t('guild.semPedidos')}</p>`}
    </section>
    <section class="gld-bloco">
      <h4 class="gld-bloco-tit">${t('guild.convitesEnviadosTitulo')} ${convites.length ? `(${convites.length})` : ''}</h4>
      <p class="gld-bloco-sub">${t('guild.convitesEnviadosSub')}</p>
      ${convites.length
        ? `<div class="gldc-lista">${convites.map((c) => `
            <div class="gldc-linha">
              <div class="gldc-info">
                <b>${escapar(c.nick)}</b>
                <span class="gldc-nums">
                  <span>${t('guild.convidadoPor', { nick: escapar(c.porNick) })}</span>
                  <span class="gldc-quando">${t('guild.pedidoHa', { tempo: tempoCurto(Date.now() - (c.criadoEm || Date.now())) })}</span>
                </span>
              </div>
              ${podeAgir
                ? `<div class="gldc-acoes">
                     <button type="button" class="guild-mini-btn btn-apagado" data-cancelar-convite="${c.id}">${t('guild.cancelarConvite')}</button>
                   </div>`
                : ''}
            </div>`).join('')}</div>`
        : `<p class="gld-vazio">${t('guild.semConvitesEnviados')}</p>`}
    </section>`;

  if (!podeAgir) return;
  host.onclick = (ev) => {
    const bt = ev.target.closest('button');
    if (!bt) return;
    if (bt.dataset.aceitarPedido) {
      return enviar({ t: 'guild.pedido.aceitar', pedidoId: Number(bt.dataset.aceitarPedido) });
    }
    if (bt.dataset.recusarPedido) {
      return enviar({ t: 'guild.pedido.recusar', pedidoId: Number(bt.dataset.recusarPedido) });
    }
    if (bt.dataset.cancelarConvite) {
      enviar({ t: 'guild.convite.cancelar', inviteId: Number(bt.dataset.cancelarConvite) });
    }
  };
}

// ----------------------------------------------------------------- aba Membros

function pintarGuildMembros(host, g) {
  const total = Number(g.membros) || 0;
  host.innerHTML = `
    ${podeGerirGuild(g)
      ? `<div class="gld-convite">
           <input id="guild-convite-nick" class="gld-campo" maxlength="16" autocomplete="off"
                  placeholder="${escapar(t('guild.convitePh'))}">
           <button type="button" class="guild-btn gld-bt-ico" id="guild-convidar">
             <span class="gld-bt-svg">${SVG_GLD.convidar}</span>${t('guild.convidar')}
           </button>
         </div>`
      : ''}
    ${total >= GLD_BUSCA_MIN
      ? `<input id="gld-busca" class="gld-campo gld-busca" type="search" autocomplete="off"
                placeholder="${escapar(t('guild.buscarMembro'))}" value="${escapar(guildBuscaMembros)}">`
      : ''}
    <p class="gd-ajuda">${t('guild.membrosAjuda')}</p>
    <div class="guild-membros-host" id="guild-membros-host"></div>`;

  const campoBusca = $('#gld-busca');
  if (campoBusca) {
    campoBusca.oninput = () => {
      guildBuscaMembros = campoBusca.value;
      // So a LISTA se repinta: trocar o painel inteiro tiraria o cursor do campo a cada letra.
      pintarMembrosGuildPainel();
    };
  }
  $('#guild-convidar')?.addEventListener('click', () => {
    const campo = $('#guild-convite-nick');
    const nick = campo.value.trim();
    if (!nick) return campo.focus();
    enviar({ t: 'guild.convidar', nick });
    campo.value = '';
  });
  $('#guild-convite-nick')?.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter') $('#guild-convidar')?.click();
  });

  if (guildPainelDetalhe?.id === g.id) pintarMembrosGuildPainel();
  else {
    $('#guild-membros-host').innerHTML = `<p class="guild-membros-carregando">${t('guild.escalacaoCarregando')}</p>`;
    pedirDetalheGuild(g.id, 'painel');
  }
}

// ------------------------------------------------------------------ aba Guerra

/** As cinco casas da minha equipe de guerra, com o sprite de cada bicho. */
function htmlCasasEquipeGuerra(ids) {
  const porId = new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  const vivos = ids.map((id) => porId.get(id)).filter(Boolean);
  return Array.from({ length: MAX_EQUIPE }, (_, i) => {
    const pk = vivos[i];
    return pk
      ? `<span class="gld-casa cheia" data-pk="${pk.id}" title="${escapar(
          `${pk.shiny ? '✨ ' : ''}${pk.nome} · ${t('painel.nivelCurto')}${pk.level}`,
        )}"></span>`
      : '<span class="gld-casa"></span>';
  }).join('');
}

function pintarGuildGuerra(host, g) {
  const max = estado.guildMaxTime ?? 10;
  const ids = idsEquipeGuerraInicial();
  const daHunt = estado.guildPvpEquipe === null;
  // O botão de REGISTRAR mora no PvP → Guild, e não aqui. Um dono que procurava o registro nesta
  // aba só achava "Abrir o PvP Guild", apagado, sem nenhuma palavra sobre inscrição — e concluía
  // que o botão tinha sumido do jogo. Com a guild fora da guerra, o bloco diz isso e o botão
  // acende. `=== false`: sem o estado da guerra carregado ainda, fica a frase de sempre.
  const pvp = estado.guildPvp ?? {};
  const semRegistro = podeGerirGuild(g) && pvp.autoRegistro === false && !pvp.minhaRegistrada;
  host.innerHTML = `
    <section class="gld-bloco">
      <h4 class="gld-bloco-tit">${t('guild.minhaEquipe')}</h4>
      <p class="gld-bloco-sub">${t(daHunt ? 'guild.minhaEquipeHunt' : 'guild.minhaEquipeSub')}</p>
      <div class="gld-casas">${htmlCasasEquipeGuerra(ids)}</div>
      ${ids.length ? '' : `<p class="gld-aviso">⚠ ${escapar(resumoEquipeGuerra())}</p>`}
      <button type="button" class="guild-btn" id="guild-editar-time">${t('guild.editarTime')}</button>
    </section>

    <section class="gld-bloco">
      <h4 class="gld-bloco-tit">${t('guild.timeDaGuild')}</h4>
      <p class="gld-bloco-sub">${t('guild.timeDaGuildSub', {
        n: Number(g.escalados) || 0, max, total: num(Number(g.membros) || 0),
      })}</p>
      <button type="button" class="guild-btn${podeGerirGuild(g) ? '' : ' btn-apagado'}" id="guild-escalacao-bt">
        ${t(podeGerirGuild(g) ? 'guild.escalacaoBt' : 'guild.verTime')}
      </button>
    </section>

    <section class="gld-bloco">
      <h4 class="gld-bloco-tit">${t('guild.pvpTitulo')}</h4>
      <p class="gld-bloco-sub">${t(semRegistro ? 'guild.guerraRegistrar' : 'guild.guerraQuando', { h: estado.guildPvp?.horaUtc ?? 22 })}</p>
      <button type="button" class="guild-btn${semRegistro ? '' : ' btn-apagado'}" id="gld-ir-pvp">${t(semRegistro ? 'guild.irRegistrar' : 'guild.irParaGuerra')}</button>
    </section>`;

  // Os sprites entram depois do HTML, como na faixa de equipe do Campeonato. A casa cheia abre
  // a ficha do bicho: a pergunta que a fileira provoca ("esse Dratini está bom para a guerra?")
  // se responde na ficha, e obrigar a ir à Bolsa procurá-lo seria mandar o jogador embora.
  const porId = new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  for (const casa of host.querySelectorAll('.gld-casa[data-pk]')) {
    const pk = porId.get(Number(casa.dataset.pk));
    if (!pk) continue;
    casa.appendChild(spritePokemon(pk, 32));
    casa.onclick = () => abrirFichaDoPokemon(pk);
  }
  $('#guild-editar-time')?.addEventListener('click', abrirEditorEquipeGuerra);
  $('#guild-escalacao-bt')?.addEventListener('click', abrirEscalacaoGuild);
  $('#gld-ir-pvp')?.addEventListener('click', () => {
    fecharGuild();
    estado.pvpAba = 'guild';
    abrirModal('pvp');
  });
}

// ----------------------------------------------------------------- aba Guild

/** Horas (mín. 1) que faltam para o dono poder trocar a TAG de novo. */
function horasRestantesTagGuild(g = estado.eu?.guild) {
  const editada = Number(g?.tagEditadaEm) || 0;
  if (!editada) return 1;
  const resta = Math.max(0, TAG_EDITAR_MS - (Date.now() - editada));
  return Math.max(1, Math.ceil(resta / 3_600_000));
}

// ----------------------------------------------------------- a PORTA da guild
//
// O bloco que o líder usa para decidir quem entra. É a peça que faz o Quadro valer alguma
// coisa: uma lista em que todas as guilds são "fechada, fale com o líder" é a mesma linha de
// chat de antes, só que num lugar mais bonito.
//
// Três botões e não um `select`: as opções são TRÊS e cada uma muda o que a guild recebe todo
// dia. Num select, a escolha atual vira uma palavra dentro de uma caixinha e as outras duas só
// existem para quem pensar em abri-la.

/** O que o líder está editando agora. Reaproveitado a cada abertura da aba. */
const rascunhoRecr = { politica: 'fechada', reqLevel: 0, reqPr: 0, descricao: '' };

function htmlBlocoRecrutamento(g) {
  rascunhoRecr.politica = POLITICAS_GUILD.includes(g.politica) ? g.politica : 'fechada';
  rascunhoRecr.reqLevel = Number(g.reqLevel) || 0;
  rascunhoRecr.reqPr = Number(g.reqPr) || 0;
  rascunhoRecr.descricao = g.descricao ?? '';
  return `
    <section class="gld-bloco" id="gld-recr">
      <h4 class="gld-bloco-tit">${t('guild.recrTitulo')}</h4>
      <p class="gld-bloco-sub">${t('guild.recrSub')}</p>
      <div class="gldr-opcoes" role="radiogroup" aria-label="${escapar(t('guild.recrTitulo'))}">
        ${POLITICAS_GUILD.map((pol) => `
          <button type="button" class="gldr-op${pol === rascunhoRecr.politica ? ' on' : ''}"
                  role="radio" aria-checked="${pol === rascunhoRecr.politica ? 'true' : 'false'}"
                  data-pol="${pol}">
            <b>${t(`guild.pol.${pol}`)}</b>
            <span>${t(`guild.polAjuda.${pol}`)}</span>
          </button>`).join('')}
      </div>
      <div class="gldr-reqs${rascunhoRecr.politica === 'requisitos' ? '' : ' hidden'}" id="gldr-reqs">
        <label class="gldr-req">${t('guild.reqLevel')}
          <input type="number" id="gldr-level" min="0" max="${REQ_LEVEL_MAX}" step="1"
                 inputmode="numeric" value="${rascunhoRecr.reqLevel || ''}"
                 placeholder="0">
        </label>
        <label class="gldr-req">${t('guild.reqPr')}
          <input type="number" id="gldr-pr" min="0" max="${REQ_PR_MAX}" step="1"
                 inputmode="numeric" value="${rascunhoRecr.reqPr || ''}"
                 placeholder="0">
        </label>
      </div>
      <label class="guild-campo gldr-desc">${t('guild.recrDescricao')}
        <input id="gldr-descricao" maxlength="${MAX_DESCRICAO_GUILD}" autocomplete="off"
               placeholder="${escapar(t('guild.recrDescricaoPh'))}"
               value="${escapar(rascunhoRecr.descricao)}">
      </label>
      <button type="button" class="guild-btn" id="gldr-salvar">${t('guild.recrSalvar')}</button>
    </section>`;
}

function ligarBlocoRecrutamento(g) {
  const bloco = $('#gld-recr');
  if (!bloco) return;
  const reqs = $('#gldr-reqs');

  bloco.querySelectorAll('.gldr-op').forEach((bt) => {
    bt.onclick = () => {
      rascunhoRecr.politica = bt.dataset.pol;
      for (const x of bloco.querySelectorAll('.gldr-op')) {
        const on = x.dataset.pol === rascunhoRecr.politica;
        x.classList.toggle('on', on);
        x.setAttribute('aria-checked', on ? 'true' : 'false');
      }
      // Os dois campos aparecem e somem com a opção do meio. Deixá-los sempre visíveis faria a
      // guild "aberta" exibir um nível mínimo que não vale nada — e alguém ia digitar nele.
      reqs?.classList.toggle('hidden', rascunhoRecr.politica !== 'requisitos');
    };
  });

  $('#gldr-salvar')?.addEventListener('click', () => {
    const lido = (sel, max) => {
      const n = Math.floor(Number($(sel)?.value) || 0);
      return Math.min(Math.max(0, n), max);
    };
    enviar({
      t: 'guild.recrutamento',
      politica: rascunhoRecr.politica,
      reqLevel: lido('#gldr-level', REQ_LEVEL_MAX),
      reqPr: lido('#gldr-pr', REQ_PR_MAX),
      // Limpa aqui também, e não só no servidor: o que o líder vê depois de salvar tem de ser o
      // que ficou gravado, e não o que ele digitou.
      descricao: descricaoGuildLimpa($('#gldr-descricao')?.value ?? ''),
    });
  });
  // Fechar a guild com pedidos na caixa é a única mudança que APAGA algo (os pedidos perdem o
  // assunto quando a porta abre). O aviso fica na própria tela, e não num diálogo: quem abre a
  // guild quer abrir, e um "tem certeza?" a cada troca de política viraria ruído.
  const selo = Number(estado.guildPedidos) || 0;
  if (selo > 0 && g.politica === 'fechada') {
    bloco.querySelector('.gld-bloco-sub')?.insertAdjacentHTML(
      'afterend',
      `<p class="gld-aviso">⚠ ${t('guild.recrAvisoPedidos', { n: selo })}</p>`,
    );
  }
}

function pintarGuildAjustes(host, g) {
  const horasEspera = horasRestantesBrasaoGuild(g);
  const editado = Number(g.brasaoEditadoEm) || 0;
  const podeBrasao = !editado || Date.now() - editado >= BRASAO_EDITAR_MS;
  // A TAG tem a mesma espera do brasão — e a primeira troca é livre (`tagEditadaEm` nulo).
  const tagEditada = Number(g.tagEditadaEm) || 0;
  const podeTag = !tagEditada || Date.now() - tagEditada >= TAG_EDITAR_MS;
  const horasTag = horasRestantesTagGuild(g);
  host.innerHTML = `
    ${podeGerirGuild(g) ? htmlBlocoRecrutamento(g) : ''}
    ${podeGerirGuild(g)
      ? `<section class="gld-bloco">
           <h4 class="gld-bloco-tit">${t('guild.tagTitulo')}</h4>
           <p class="gld-bloco-sub">${t('guild.tagSub', { max: MAX_TAG_GUILD })} ${t('guild.tagEsperaNota')}</p>
           <div class="gld-tag-linha">
             <span class="gld-tag-previa" id="gld-tag-previa"></span>
             <input id="gld-tag-campo" class="gld-campo" maxlength="${MAX_TAG_GUILD}" autocomplete="off"
                    placeholder="${escapar(t('guild.tagPh'))}" value="${escapar(g.tag ?? '')}">
           </div>
           <div class="guild-paleta gld-paleta-tag" id="gld-tag-cores"></div>
           <button type="button" class="guild-btn" id="gld-tag-salvar" ${podeTag ? '' : 'disabled'}>
             ${podeTag ? t('guild.tagSalvar') : t('guild.tagEspera', { horas: num(horasTag) })}
           </button>
         </section>
         <section class="gld-bloco">
           <h4 class="gld-bloco-tit">${t('guild.editarBrasaoTitulo')}</h4>
           <p class="gld-bloco-sub">${t('guild.editarBrasaoAjuda')}</p>
           <button type="button" class="guild-btn" id="guild-editar-brasao" ${podeBrasao ? '' : 'disabled'}>
             ${podeBrasao ? t('guild.editarBrasao') : t('guild.brasaoEspera', { horas: num(horasEspera) })}
           </button>
         </section>`
      : ''}
    <!-- O que nao tem volta mora sozinho, no fim, atras de um titulo que avisa. Enquanto
         "Apagar guild" dividia a pilha com "Convidar", ele era so mais um botao roxo. -->
    <!-- Sub-dono vê "Sair da guild", e não "Apagar guild": apagar é uma das três coisas que
         continuam só do dono, porque some com a guild dele junto. -->
    <section class="gld-bloco gld-perigo">
      <h4 class="gld-bloco-tit">${t('guild.zonaPerigo')}</h4>
      <p class="gld-bloco-sub">${t(g.isOwner ? 'guild.apagarTexto' : 'guild.sairTexto')}</p>
      <button type="button" class="guild-btn btn-apagado gld-bt-ico" id="${g.isOwner ? 'guild-apagar' : 'guild-sair'}">
        <span class="gld-bt-svg">${SVG_GLD.sair}</span>${t(g.isOwner ? 'guild.apagar' : 'guild.sair')}
      </button>
    </section>`;

  // O editor da TAG: campo, prévia e paleta andam juntos, e a prévia é desenhada com a MESMA
  // classe da linha do chat (`m-guild-tag`) — a pergunta que o jogador faz aqui é "como isso vai
  // ficar lá", e responder com um estilo próprio seria responder outra coisa.
  ligarBlocoRecrutamento(g);

  rascunhoTag.tag = g.tag ?? '';
  rascunhoTag.cor = corTagValida(g.tagCor);
  const campoTag = $('#gld-tag-campo');
  const previaTag = () => {
    const alvo = $('#gld-tag-previa');
    if (!alvo) return;
    const val = tagGuildValida(rascunhoTag.tag);
    alvo.style.setProperty('--gt', rascunhoTag.cor);
    alvo.textContent = val ?? '';
    alvo.classList.toggle('vazia', !val);
  };
  if (campoTag && !podeTag) campoTag.disabled = true;
  if (campoTag) {
    campoTag.oninput = () => {
      rascunhoTag.tag = campoTag.value;
      previaTag();
      paletaDaTag($('#gld-tag-cores'), previaTag);
    };
  }
  paletaDaTag($('#gld-tag-cores'), previaTag);
  previaTag();
  $('#gld-tag-salvar')?.addEventListener('click', () => {
    if (!podeTag) return;
    enviar({ t: 'guild.tag', tag: rascunhoTag.tag, tagCor: rascunhoTag.cor });
  });
  $('#guild-editar-brasao')?.addEventListener('click', montarGuildEditarBrasao);
  $('#guild-apagar')?.addEventListener('click', () => confirmarApagarGuild(estado.eu?.guild));
  $('#guild-sair')?.addEventListener('click', () => confirmarSairGuild(estado.eu?.guild));
}

/** O brasão da guild como ator do palco (o desenho é SVG pronto, sem hidratação). */
const dlgArteBrasao = (g, px = 72) => dlgArteHtml(`<span class="dlg-brasao">${svgBrasao(g?.brasao, px)}</span>`);

/**
 * Apagar a guild: o brasão sem cor, com a lixeira no canto, e as três perdas uma por linha — numa
 * frase só, "os GP são perdidos" ficava no meio e passava batido.
 */
function confirmarApagarGuild(g) {
  confirmar({
    titulo: t('guild.apagarTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({ arte: dlgArteBrasao(g), nome: escapar(g?.nome ?? ''), classe: 'sai', marca: dlgIcone('lixeira', 14) }), 'perigo')}
      ${dlgLista([
        { icone: 'pessoaMenos', html: t('guild.apagarMembros'), perigo: true },
        { icone: 'estrela', html: t('guild.apagarGp'), perigo: true },
        { icone: 'espadas', html: t('guild.apagarPvp'), perigo: true },
      ])}
      ${dlgSelos(dlgSelo('cadeado', escapar(t('dlg.semVolta')), 'perigo'))}`,
    tom: 'perigo',
    aoConfirmar: () => enviar({ t: 'guild.apagar' }),
  });
}

/** Sair da guild: você, a seta e a porta. A guild continua; quem sai é você. */
function confirmarSairGuild(g) {
  confirmar({
    titulo: t('guild.sairTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteBrasao(g, 64), nome: escapar(g?.nome ?? '') })}
        ${dlgSeta()}
        ${dlgAtor({ arte: dlgArteTreinador(null, null, 64), nome: escapar(estado.eu?.nick ?? ''), marca: dlgIcone('porta', 14) })}`, 'perigo')}
      ${dlgFrase('', t('guild.sairTexto'))}`,
    tom: 'perigo',
    aoConfirmar: () => enviar({ t: 'guild.sair' }),
  });
}

/** O membro de quem a caixa fala, animado e com as cores dele. */
const dlgArteMembro = (mb, px = 64) => dlgArteTreinador(mb?.looktype ?? LOOKTYPE_TREINADOR, mb?.visual ?? null, px);

/** Promover a sub-dono (o escudo) ou rebaixar (o ×): o membro no centro do palco. */
function confirmarSubdono(mb, kick) {
  const tirar = !!mb.ehSubdono;
  confirmar({
    titulo: t(tirar ? 'guild.tirarSubdonoTitulo' : 'guild.porSubdonoTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArteMembro(mb, 72),
        nome: escapar(mb.nick ?? ''),
        sub: dlgNivel(mb.level ?? 1),
        classe: tirar ? '' : 'novo',
        marca: dlgIcone(tirar ? 'xis' : 'escudo', 14),
      }), tirar ? 'perigo' : 'rx')}
      ${dlgFrase('', t(tirar ? 'guild.tirarSubdonoTexto' : 'guild.porSubdonoTexto', { nick: escapar(mb.nick ?? '') }))}`,
    aoConfirmar: () => kick.onSubdono(mb.playerId, !tirar),
  });
}

/** Passar a coroa: ela sai de você e vai para o membro — a seta carrega a coroa. */
function confirmarTransferirLider(mb, kick) {
  confirmar({
    titulo: t('guild.transferirLiderTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteTreinador(null, null, 64), nome: escapar(estado.eu?.nick ?? '') })}
        ${dlgSeta({ icone: 'coroa' })}
        ${dlgAtor({
          arte: dlgArteMembro(mb, 64),
          nome: escapar(mb.nick ?? ''),
          classe: 'novo',
          marca: dlgIcone('coroa', 14),
        })}`, 'ouro')}
      ${dlgFrase('', t('guild.transferirLiderTexto', { nick: escapar(mb.nick ?? '') }))}
      ${dlgSelos(dlgSelo('cadeado', escapar(t('guild.transferirSelo')), 'perigo'))}`,
    tom: 'perigo',
    aoConfirmar: () => kick.onTransfer(mb.playerId, mb.nick),
  });
}

/** Expulsar: o membro sem cor, com o "−" no canto. */
function confirmarExpulsar(mb, kick) {
  confirmar({
    titulo: t('guild.expulsarTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArteMembro(mb, 72),
        nome: escapar(mb.nick ?? ''),
        sub: dlgNivel(mb.level ?? 1),
        classe: 'sai',
        marca: dlgIcone('pessoaMenos', 15),
      }), 'perigo')}
      ${dlgFrase('', t('guild.expulsarTexto'))}`,
    tom: 'perigo',
    aoConfirmar: () => kick.onKick(mb.playerId),
  });
}

function montarGuildEditarBrasao() {
  const g = estado.eu?.guild;
  if (!podeGerirGuild(g)) return;
  guildModo = 'brasao';
  guildTopoVoltar(true);
  Object.assign(rascunhoBrasao, normalizarBrasao(g.brasao));
  const editado = Number(g.brasaoEditadoEm) || 0;
  const resta = editado ? Math.max(0, BRASAO_EDITAR_MS - (Date.now() - editado)) : 0;
  const podeSalvar = resta <= 0;
  const horasEspera = horasRestantesBrasaoGuild(g);
  $('#guild-titulo').textContent = t('guild.editarBrasaoTitulo');
  $('#guild-corpo').innerHTML = `
    <p class="guild-ajuda">${t('guild.editarBrasaoAjuda')}</p>
    <div class="guild-editor">
      <div class="guild-preview" id="guild-preview"></div>
      <div class="guild-opcoes">
        <label>${t('guild.escudo')}
          <select id="guild-escudo">${ESCUDOS.map((e) => `<option value="${e.id}">${e.nome}</option>`).join('')}</select>
        </label>
        <label>${t('guild.emblema')}
          <select id="guild-emblema">${EMBLEMAS.map((e) => `<option value="${e.id}">${e.nome}</option>`).join('')}</select>
        </label>
        <label>${t('guild.borda')}
          <select id="guild-borda">${BORDAS.map((e) => `<option value="${e.id}">${e.nome}</option>`).join('')}</select>
        </label>
        <div class="guild-cores">
          <span>${t('guild.corFundo')}</span><div id="guild-cor-bg" class="guild-paleta"></div>
          <span>${t('guild.corPri')}</span><div id="guild-cor-pri" class="guild-paleta"></div>
          <span>${t('guild.corSec')}</span><div id="guild-cor-sec" class="guild-paleta"></div>
        </div>
      </div>
    </div>
    <button type="button" class="guild-btn" id="guild-salvar-brasao" ${podeSalvar ? '' : 'disabled'}>
      ${podeSalvar ? t('guild.salvarBrasao') : t('guild.brasaoEspera', { horas: num(horasEspera) })}
    </button>`;
  $('#guild-escudo').value = rascunhoBrasao.escudo;
  $('#guild-emblema').value = rascunhoBrasao.emblema;
  $('#guild-borda').value = rascunhoBrasao.borda ?? 'none';
  const repintar = () => {
    rascunhoBrasao.escudo = $('#guild-escudo').value;
    rascunhoBrasao.emblema = $('#guild-emblema').value;
    rascunhoBrasao.borda = $('#guild-borda').value;
    pintarBrasao($('#guild-preview'), rascunhoBrasao, 96);
  };
  const paleta = (id, chave) => {
    const host = $(id);
    host.innerHTML = CORES_BRASAO.map(
      (c) => `<button type="button" class="guild-cor ${rascunhoBrasao[chave] === c ? 'on' : ''}" style="background:${c}" data-cor="${c}"></button>`,
    ).join('');
    host.onclick = (ev) => {
      const b = ev.target.closest('.guild-cor');
      if (!b) return;
      rascunhoBrasao[chave] = b.dataset.cor;
      paleta(id, chave);
      repintar();
    };
  };
  paleta('#guild-cor-bg', 'bg');
  paleta('#guild-cor-pri', 'pri');
  paleta('#guild-cor-sec', 'sec');
  $('#guild-escudo').onchange = repintar;
  $('#guild-emblema').onchange = repintar;
  $('#guild-borda').onchange = repintar;
  repintar();
  $('#guild-salvar-brasao')?.addEventListener('click', () => {
    if (!podeSalvar) return;
    enviar({ t: 'guild.editarBrasao', brasao: { ...rascunhoBrasao } });
  });
  $('#guild').classList.remove('hidden');
}

function aoReceberGuild(m) {
  const aberto = () => !$('#guild').classList.contains('hidden');
  if (m.guild !== undefined) {
    // Trocou de guild (entrou, foi expulso, aceitou convite): a caixa em cache é da guild
    // ANTERIOR, e mostrá-la na nova seria o líder lendo pedidos que não são dele. `null` faz
    // a aba pedir a caixa certa na primeira abertura.
    if (m.guild?.id !== estado.eu?.guild?.id) {
      estado.guildCaixa = null;
      estado.guildPedidos = 0;
    }
    if (estado.eu) estado.eu.guild = m.guild;
    pintarSlotGuild(estado.eu?.guild ?? null, estado.eu?.guildConvites ?? []);
    if (m.guild && aberto()) {
      if (guildPainelDetalhe?.id === m.guild.id) pedirDetalheGuild(m.guild.id, 'painel');
      else if (guildModo === 'brasao' && podeGerirGuild(m.guild)) montarGuildPainel();
      else montarGuildPainel();
    }
    if (m.guild === null) {
      guildPainelDetalhe = null;
      guildPainelMembroAberto = null;
      estado.guildCaixa = null;
      estado.guildPedidos = 0;
      // Sair da guild não fecha mais a janela: o painel troca para o de quem não tem guild, com
      // o Quadro na frente. Fechar seria devolver o jogador ao mapa exatamente no momento em que
      // ele está decidindo para onde ir.
      if (aberto()) montarGuildSemGuild();
    }
  }
  if (m.convites !== undefined) {
    if (estado.eu) estado.eu.guildConvites = m.convites;
    pintarSlotGuild(estado.eu?.guild ?? null, m.convites);
    if (!estado.eu?.guild && aberto()) montarGuildSemGuild();
  }
  // ---- recrutamento
  if (m.total !== undefined) estado.guildTotal = Number(m.total) || 0;
  if (m.esperaMs !== undefined) {
    // Guardado como INSTANTE, e não como duração: a tela repinta várias vezes até o jogador
    // fechá-la, e um "faltam 6 h" congelado no primeiro pacote continuaria dizendo 6 h uma hora
    // depois. O instante envelhece sozinho.
    estado.guildEsperaAte = Number(m.esperaMs) > 0 ? Date.now() + Number(m.esperaMs) : 0;
  }
  if (m.candidaturas !== undefined) {
    const ids = new Set((m.candidaturas ?? []).map(Number));
    estado.guildCandidaturas = ids;
    // A lista que já está na tela recebe as marcas novas em vez de ser pedida de novo: o
    // servidor acabou de dizer o que mudou, e uma volta ao banco por isso seria gasto puro.
    for (const g of quadroGuild.dados?.itens ?? []) g.pedido = ids.has(g.id);
    if (guildAba === 'quadro' && aberto()) pintarListaQuadro();
  }
  if (m.quadro) {
    // Respostas fora de ordem: com debounce de 250 ms, a da terceira letra pode chegar depois da
    // da quinta. A resposta que não corresponde ao que está no campo AGORA é descartada — senão
    // a lista pisca para trás no meio da digitação.
    if (String(m.quadro.busca ?? '') === quadroGuild.busca && m.quadro.so === quadroGuild.so) {
      quadroGuild.dados = m.quadro;
      quadroGuild.pagina = m.quadro.pagina;
      quadroGuild.pedindo = false;
      if (guildAba === 'quadro' && aberto()) pintarListaQuadro();
    }
  }
  if (m.pedidos !== undefined) {
    estado.guildPedidos = Number(m.pedidos) || 0;
    pintarSlotGuild(estado.eu?.guild ?? null, estado.eu?.guildConvites ?? []);
    // Só o SELO da aba se atualiza; repintar o painel jogaria fora a aba aberta e a rolagem de
    // quem está lendo outra coisa.
    const selo = $('#guild-corpo .gld-aba[data-aba="caixa"]');
    if (selo) {
      const atual = selo.querySelector('.gld-aba-selo');
      if (estado.guildPedidos > 0) {
        const txt = estado.guildPedidos > 99 ? '99+' : String(estado.guildPedidos);
        if (atual) atual.textContent = txt;
        else selo.insertAdjacentHTML('beforeend', `<span class="gld-aba-selo">${txt}</span>`);
      } else atual?.remove();
    }
  }
  if (m.caixa) {
    estado.guildCaixa = m.caixa;
    estado.guildPedidos = (m.caixa.pedidos ?? []).length;
    if (guildAba === 'caixa' && aberto() && estado.eu?.guild) {
      pintarGuildCaixa($('#gld-pane'), estado.eu.guild);
    }
  }
  if (m.pvp) {
    estado.guildPvp = m.pvp;
    if (estado.modalAberto === 'pvp') montarGuildPvp();
    // A aba Guerra do painel da guild também lê o registro (ver `pintarGuildGuerra`).
    if (!$('#guild').classList.contains('hidden') && estado.eu?.guild && guildAba === 'guerra') {
      pintarPaneGuild();
    }
  }
  if (m.escalacao) receberEscalacaoGuild(m.escalacao);
  if (m.pvpEquipe !== undefined) {
    estado.guildPvpEquipe = m.pvpEquipe;
    // A aba Guerra desenha as cinco casas a partir desta lista: salvou a equipe, ela repinta.
    if (!$('#guild').classList.contains('hidden') && estado.eu?.guild && guildAba === 'guerra') {
      pintarPaneGuild();
    }
  }
  if (m.replay) abrirReplayGuerra(m.replay);
  if (m.analise) receberAnaliseGuerra(m.analise);
  if (m.detalhe) mostrarDetalheGuild(m.detalhe);
  if (m.ranking) {
    estado.ranking.guild = m.ranking;
    if (estado.modalAberto === 'ranking' && estado.abaRanking === 'guild') pintarRanking();
  }
}

// ------------------------------------------------ a ficha pública de uma guild do ranking
//
// O Ranking de Guilds mostrava nome, dono e GP. Faltava a única coisa que responde à pergunta
// que a lista provoca — "essa aí em primeiro é forte ou só tem gente?": QUEM está nela, e com
// o que cada um vai para a Guerra de Guilds.
//
// São dois níveis, não uma árvore aberta: a lista de membros e, ao tocar num membro, a equipe
// dele. Desenhar as quarenta equipes de uma vez daria trezentos sprites animados numa tela só.

/** Qual membro está com a equipe aberta. `null` = nenhum, só a lista. */
let guildDetalheAberto = { dados: null, membroId: null };
/** `modal` = ficha do ranking; `painel` = lista dentro do painel da própria guild. */
let guildDetalheDestino = 'modal';
/** Cache da ficha quando o painel da guild pede detalhe — evita reabrir o modal do ranking. */
let guildPainelDetalhe = null;
/** Membro expandido no painel da guild (id do player). */
let guildPainelMembroAberto = null;

/** Pedido em voo, para o duplo-clique numa linha do placar não virar dois pedidos. */
let guildDetalhePedido = 0;
const GUILD_DETALHE_ESPERA_MS = 1500;

function fecharDetalheGuild() {
  guildDetalheAberto = { dados: null, membroId: null };
  guildDetalheDestino = 'modal';
  $('#guild-detalhe')?.classList.add('hidden');
}

function rotuloOnlineMembro(mb) {
  if (mb.online) return t('gd.online');
  if (mb.lastSeen) return t('gd.vistoAtras', { tempo: tempoCurto(Date.now() - mb.lastSeen) });
  return t('gd.vistoNunca');
}

/**
 * Lista expansível de membros — ranking global e painel da própria guild.
 * @param {object} [kick] `{ podeGerir, isOwner, ownerId, onKick, onTransfer, onSubdono }` — as
 *   ações de quem manda. `podeGerir` abre a barra (dono ou sub-dono); `isOwner` é o que decide
 *   se ela traz promover e transferir, que continuam sendo só do dono.
 */
/** Último membro que a lista trouxe para a tela — ver a nota no fim de `pintarListaMembrosGuild`. */
let gdMembroRolado = null;

function pintarListaMembrosGuild(host, membros, membroAbertoId, aoToggle, kick = null) {
  if (!host) return;
  host.innerHTML = '';
  if (!membros.length) {
    host.innerHTML = `<div class="cm-vazio">${t('gd.semMembros')}</div>`;
    return;
  }

  for (const mb of membros) {
    const aberto = membroAbertoId === mb.playerId;
    const el = document.createElement('div');
    el.className = 'gd-membro' + (aberto ? ' aberto' : '');

    const topo = document.createElement('div');
    topo.className = 'gd-membro-top';

    const cab = document.createElement('button');
    cab.type = 'button';
    cab.className = 'gd-membro-cab';
    cab.setAttribute('aria-expanded', String(aberto));
    // Duas linhas, e nao tres: nick com os selos em cima, e o resto ("Nv 350 · 4 na equipe ·
    // Online agora") numa fita so embaixo. A terceira linha existia so para o "Online agora" e
    // esticava toda linha da lista em 14 px — numa guild de trinta, meia tela de altura.
    cab.innerHTML = `
      <span class="gd-ava"></span>
      <span class="gd-membro-txt">
        <b>${escapar(mb.nick ?? '')}${mb.ehDono ? ` <em class="gd-selo-dono">${t('gd.seloDono')}</em>` : ''}${
          mb.ehSubdono && !mb.ehDono ? ` <em class="gd-selo-sub">${t('gd.seloSubdono')}</em>` : ''
        }${
          mb.escalado
            ? ` <em class="gd-selo-time">${t('gd.time')}</em>`
            : ` <em class="gd-selo-reserva">${t('gd.reserva')}</em>`
        }</b>
        <span class="gd-membro-meta">
          <small>${t('painel.nivelCurto')} ${num(mb.level)}</small>
          <small>${t('gd.equipeDe', { n: (mb.equipe ?? []).length })}</small>
          <span class="gd-online${mb.online ? ' on' : ''}">${escapar(rotuloOnlineMembro(mb))}</span>
        </span>
      </span>
      <span class="gd-membro-poder">⚔ ${num(poderDaEquipe(mb.equipe))}</span>
      <span class="gd-seta">${aberto ? '▾' : '▸'}</span>`;
    cab.querySelector('.gd-ava').appendChild(
      spriteAnimado(mb.looktype ?? LOOKTYPE_TREINADOR, 32, 3, null, mb.visual, { treinador: true }),
    );
    cab.onclick = () => aoToggle(mb.playerId, aberto);
    topo.appendChild(cab);

    // VER PERFIL — a ficha pública do membro, a mesma do chat, do ranking e da lista de
    // amigos. Abre POR CIMA do modal da guild, então fechá-la devolve a lista onde estava.
    //
    // IRMÃO do cabeçalho, e não um filho dele: `<button>` dentro de `<button>` é HTML
    // inválido, e o navegador desmonta o de dentro — o clique viraria "abrir a equipe".
    //
    // Ícone e rótulo (e só o ícone no celular, ver mobile.css): esta é a única ação que
    // aparece em TODAS as linhas, inclusive para quem não manda na guild, e trinta rótulos
    // empilhados são a fileira de frases que a barra do dono evita ficando escondida.
    if (mb.nick) {
      const perfil = document.createElement('button');
      perfil.type = 'button';
      perfil.className = 'gd-membro-perfil';
      perfil.title = t('amigos.verPerfil');
      perfil.setAttribute('aria-label', `${t('amigos.verPerfil')} — ${mb.nick}`);
      perfil.innerHTML = `
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M12 12.6a5.3 5.3 0 1 0 0-10.6 5.3 5.3 0 0 0 0 10.6z" fill="currentColor"/>
          <path d="M12 14.4c-4.6 0-8.3 2.6-8.3 5.8V22h16.6v-1.8c0-3.2-3.7-5.8-8.3-5.8z" fill="currentColor"/>
        </svg>
        <span class="gd-membro-perfil-txt">${escapar(t('amigos.verPerfil'))}</span>`;
      // `stopPropagation` não bastaria sozinho (o cabeçalho é irmão, não pai), mas o clique
      // ainda sobe até a lista — e é lá que mora o fechamento do detalhe de guild.
      perfil.onclick = (ev) => { ev.stopPropagation(); pedirPerfil(mb.nick); };
      topo.appendChild(perfil);
    }
    el.appendChild(topo);

    if (aberto) {
      // As acoes do dono vivem AQUI, no membro aberto — nao na linha fechada. Na linha elas
      // espremiam o nick contra dois botoes roxos de largura fixa, repetidos em cada membro:
      // trinta membros davam sessenta botoes vermelhos numa lista que se le de relance. Abertas
      // junto com a equipe, elas aparecem uma vez, para o membro sobre o qual se decidiu olhar.
      // Quem vê a barra de ações: o dono (tudo) e o sub-dono (só expulsar, e só membro comum).
      // Sub-dono não expulsa sub-dono — senão a promoção vira corrida de quem clica primeiro.
      const souODono = !!kick?.isOwner;
      const alvoEhChefe = !!mb.ehDono || !!mb.ehSubdono;
      const podeAgir = !!kick?.podeGerir && mb.playerId !== kick.ownerId
        && (souODono || !alvoEhChefe);
      if (podeAgir) {
        const acoes = document.createElement('div');
        acoes.className = 'gd-acoes';

        const mini = (rotulo, classe, aoClicar) => {
          const b = document.createElement('button');
          b.type = 'button';
          b.className = `guild-mini-btn${classe ? ` ${classe}` : ''}`;
          b.textContent = rotulo;
          b.onclick = (ev) => { ev.stopPropagation(); aoClicar(); };
          acoes.appendChild(b);
        };

        if (souODono) {
          // Promover / rebaixar é só do dono: quem controla a permissão controla a guild.
          mini(t(mb.ehSubdono ? 'guild.tirarSubdono' : 'guild.porSubdono'), '', () => confirmarSubdono(mb, kick));
          mini(t('guild.transferirLider'), '', () => confirmarTransferirLider(mb, kick));
        }

        mini(t('guild.expulsar'), 'gd-kick', () => confirmarExpulsar(mb, kick));
        el.appendChild(acoes);
      }

      const equipe = document.createElement('div');
      equipe.className = 'gd-equipe';
      if (!(mb.equipe ?? []).length) {
        equipe.innerHTML = `<div class="cm-vazio gd-sem-equipe">${t('gd.semEquipe')}</div>`;
      } else {
        for (const pk of mb.equipe) equipe.appendChild(cardEquipeGuild(pk));
      }
      el.appendChild(equipe);
    }
    host.appendChild(el);
  }

  // Abrir um membro lá embaixo da lista deixava a equipe dele FORA da tela: a lista repinta,
  // o bloco cresce para baixo e quem tocou continua olhando o mesmo pedaço de antes, achando
  // que não aconteceu nada. `nearest` rola o mínimo — quem já estava visível não se mexe.
  //
  // Só na TROCA de membro, e não a cada repintura: a lista se redesenha sozinha a cada
  // atualização da guild, e um membro com cinco pokémon é mais alto que a janela — `nearest`
  // o traria de volta toda vez, arrancando a rolagem da mão de quem está lendo lá embaixo.
  if (membroAbertoId && membroAbertoId !== gdMembroRolado) {
    host.querySelector('.gd-membro.aberto')?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }
  gdMembroRolado = membroAbertoId ?? null;
}

/** Os membros da ficha, peneirados pela busca do painel. */
function membrosBuscadosGuild(membros) {
  const q = guildBuscaMembros.trim().toLowerCase();
  return q ? membros.filter((m) => String(m.nick ?? '').toLowerCase().includes(q)) : membros;
}

function pintarMembrosGuildPainel() {
  const host = $('#guild-membros-host');
  const g = estado.eu?.guild;
  if (!host || !g) return;
  const d = guildPainelDetalhe?.id === g.id ? guildPainelDetalhe : null;
  if (!d) {
    host.innerHTML = `<p class="guild-membros-carregando">${t('guild.escalacaoCarregando')}</p>`;
    return;
  }
  const lista = membrosBuscadosGuild(d.membros ?? []);
  // A busca que nao acha nada precisa dizer isso: a lista vazia sozinha parece uma guild vazia.
  if (!lista.length && guildBuscaMembros.trim()) {
    host.innerHTML = `<div class="cm-vazio">${t('guild.semResultado')}</div>`;
    return;
  }
  const fora = Math.max(0, Number(d.totalMembros ?? 0) - (d.membros ?? []).length);
  host.innerHTML = `<div class="gd-membros" id="guild-membros-lista"></div>${
    fora ? `<p class="gd-ajuda gd-mais">${t('gd.maisMembros', { n: num(fora) })}</p>` : ''}`;
  pintarListaMembrosGuild(
    $('#guild-membros-lista'),
    lista,
    guildPainelMembroAberto,
    (playerId, aberto) => {
      guildPainelMembroAberto = aberto ? null : playerId;
      pintarMembrosGuildPainel();
    },
    podeGerirGuild(g)
      ? {
          podeGerir: true,
          isOwner: !!g.isOwner,
          ownerId: g.ownerId,
          onKick: (alvoId) => enviar({ t: 'guild.expulsar', alvoId: Number(alvoId) }),
          onTransfer: (alvoId) => enviar({ t: 'guild.transferirLider', alvoId: Number(alvoId) }),
          onSubdono: (alvoId, ligado) =>
            enviar({ t: 'guild.subdono', alvoId: Number(alvoId), ligado: !!ligado }),
        }
      : null,
  );
}

/**
 * Pede a ficha de uma guild. Uma de cada vez.
 *
 * A consulta do lado de lá são três idas ao banco, e a última traz uma linha por pokémon de
 * cada membro — numa guild cheia, duzentas. É mais cara que o resto do placar, e uma lista em
 * que cada linha é clicável é exatamente onde o duplo-clique acontece sozinho.
 */
function pedirDetalheGuild(guildId, destino = 'modal') {
  if (!guildId) return;
  const agora = Date.now();
  if (agora - guildDetalhePedido < GUILD_DETALHE_ESPERA_MS) return;
  guildDetalhePedido = agora;
  guildDetalheDestino = destino;
  enviar({ t: 'guild.detalhe', guildId });
}

function mostrarDetalheGuild(d) {
  guildDetalhePedido = 0;
  if (guildDetalheDestino === 'painel' && estado.eu?.guild?.id === d.id) {
    guildPainelDetalhe = d;
    guildPainelMembroAberto = null;
    if (!$('#guild').classList.contains('hidden')) pintarMembrosGuildPainel();
    guildDetalheDestino = 'modal';
    return;
  }
  guildDetalheAberto = { dados: d, membroId: null };
  const modal = $('#guild-detalhe');
  if (!modal) return;
  $('#guild-detalhe-titulo').textContent = d.nome ?? '';
  modal.classList.remove('hidden');
  pintarDetalheGuild();
}

/**
 * O total de ⚔ de uma equipe — a leitura de "esse membro pesa quanto" sem abrir nada.
 *
 * Com o nível travado no cap da guerra (ver `poderNaGuerra`): esta lista é lida para decidir
 * se vale desafiar a guild, e o `poder` cru do ranking respondia à pergunta errada — ele
 * cresce com o nível REAL, que a arena corta em 150.
 */
const poderDaEquipe = (equipe) => (equipe ?? []).reduce((soma, pk) => soma + poderNaGuerra(pk), 0);

function pintarDetalheGuild() {
  const host = $('#guild-detalhe-corpo');
  const d = guildDetalheAberto.dados;
  if (!host || !d) return;

  const membros = d.membros ?? [];
  const poderTotal = membros.reduce((soma, mb) => soma + poderDaEquipe(mb.equipe), 0);
  const max = Number(d.maxTime) || estado.guildMaxTime || 10;
  // `totalMembros` é a contagem VERDADEIRA; `membros.length` é só o que coube na lista (a guild
  // não tem mais teto de gente — ver `MAX_MEMBROS_FICHA` no servidor).
  const total = Number(d.totalMembros ?? membros.length) || 0;
  const foraDaLista = Math.max(0, total - membros.length);

  host.innerHTML = `
    <div class="gd-cab">
      <span class="gd-brasao" id="gd-brasao"></span>
      <div class="gd-cab-txt">
        <div class="gd-dono">${t('gd.dono')} <b>${escapar(d.ownerNick ?? '—')}</b></div>
        <div class="gd-numeros">
          <span>${t('gd.gp')} <b>${num(d.gp ?? 0)}</b></span>
          <span>${t('gd.membros')} <b>${num(total)}</b></span>
          <span>${t('gd.escalados')} <b>${num(Number(d.escalados) || 0)}/${max}</b></span>
          <span>${t('gd.poderTotal')} <b>⚔ ${num(poderTotal)}</b></span>
        </div>
      </div>
    </div>
    <p class="gd-ajuda">${t('gd.ajudaTime', { max })}</p>
    <p class="gd-ajuda">${t('gd.ajuda')}</p>
    <div class="gd-membros" id="gd-membros"></div>
    ${foraDaLista ? `<p class="gd-ajuda">${t('gd.maisMembros', { n: num(foraDaLista) })}</p>` : ''}`;

  pintarBrasao($('#gd-brasao'), d.brasao, 44);

  const lista = $('#gd-membros');
  if (!membros.length) {
    lista.innerHTML = `<div class="cm-vazio">${t('gd.semMembros')}</div>`;
    return;
  }

  pintarListaMembrosGuild(lista, membros, guildDetalheAberto.membroId, (playerId, aberto) => {
    guildDetalheAberto.membroId = aberto ? null : playerId;
    pintarDetalheGuild();
  });
}

/** Um pokémon da equipe de guerra. Mesma fileira de selos dos cards do Market e do Mercado. */
function cardEquipeGuild(pk) {
  const el = document.createElement('div');
  el.className = 'gd-pk' + (pk.shiny ? ' shiny' : '');
  el.innerHTML = `
    <div class="gd-pk-arte"></div>
    <div class="gd-pk-info">
      <div class="gd-pk-nome">${pk.shiny ? prefixoShiny() : ''}${escapar(pk.nome ?? '')}${selosTm(pk)}</div>
      <div class="gd-pk-sub">${chipsDeTipo(pk.tipos)}</div>
      <div class="gd-pk-lv">${t('painel.nivelCurto')} ${rotuloNivelNaGuerra(pk.level)} · ⚔ ${num(poderNaGuerra(pk))}</div>
    </div>
    <div class="gd-pk-selos">${selosAtributos(pk, { compacto: true })}</div>`;
  el.querySelector('.gd-pk-arte').appendChild(spritePokemon(pk, 44));
  el.title = t('cm.verFicha');
  el.onclick = () => abrirFichaDoPokemon(pk);
  return el;
}

$('#guild-detalhe-fechar')?.addEventListener('click', fecharDetalheGuild);
$('#guild-detalhe')?.addEventListener('click', (ev) => {
  // A ficha do pokémon abre POR CIMA desta tela; o clique no fundo dela não pode atravessar
  // e fechar a guild embaixo. Mesma guarda do Depot.
  if (fichaAberta()) return;
  if (ev.target === $('#guild-detalhe')) fecharDetalheGuild();
});

$('#tr-guild')?.addEventListener('click', abrirGuild);
$('#guild-fechar')?.addEventListener('click', fecharGuild);
// O ← do topo só existe no editor de brasão agora: as outras telas viraram ABAS, e aba não tem
// "voltar" — tem a aba de onde se veio, sempre visível na barra.
$('#guild-voltar')?.addEventListener('click', () => {
  if (estado.eu?.guild) return montarGuildPainel();
  montarGuildSemGuild();
});
$('#guild')?.addEventListener('click', (ev) => {
  if (ev.target === $('#guild')) fecharGuild();
});
$('#guild-time-fechar')?.addEventListener('click', fecharEditorEquipeGuerra);
$('#guild-time-modal')?.addEventListener('click', (ev) => {
  if (ev.target === $('#guild-time-modal')) fecharEditorEquipeGuerra();
});

// --------------------------------------------------- o TIME da guild (a escalação)
//
// A guild deixou de ter teto de membros: o dono chama quantos quiser. O que tem teto é o TIME
// — os `guildMaxTime` escalados que vão à Guerra de Guilds e, por isso mesmo, os únicos que
// levam o bônus diário do ranking e os diamantes do fechamento mensal.
//
// É outra tela do "Minha equipe de guerra" logo acima, e a confusão entre as duas seria fácil:
// lá o JOGADOR escolhe os pokémon dele, aqui o DONO escolhe os jogadores. Por isso o título
// diz "Time da Guild" e o texto de abertura repete, em uma frase, o que cada escolha decide.
//
// Guild com `max` membros ou menos não escolhe nada: está toda escalada (o servidor mantém
// isso verdadeiro em `completarTime`), e a tela troca a lista por um aviso dizendo isso — uma
// grade de caixinhas todas marcadas e impossíveis de desmarcar seria uma escolha falsa.

/** A seleção em edição. `null` enquanto a lista do servidor não chegou. */
let escalacaoSel = null;
let escalacaoBusca = '';

function fecharEscalacaoGuild() {
  estado.guildSalvandoEscalacao = false;
  escalacaoSel = null;
  escalacaoBusca = '';
  $('#guild-escalacao-modal')?.classList.add('hidden');
  const corpo = $('#guild-escalacao-corpo');
  if (corpo) corpo.innerHTML = '';
}

function abrirEscalacaoGuild() {
  if (!estado.eu?.guild) return;
  escalacaoSel = null;
  escalacaoBusca = '';
  const corpo = $('#guild-escalacao-corpo');
  if (corpo) corpo.innerHTML = `<p class="guild-membros-carregando">${t('guild.escalacaoCarregando')}</p>`;
  $('#guild-escalacao-modal')?.classList.remove('hidden');
  enviar({ t: 'guild.escalacao' });
}

/** A lista chegou (ou voltou depois de salvar) — repinta com a seleção do servidor. */
function receberEscalacaoGuild(e) {
  estado.guildEscalacao = e;
  estado.guildSalvandoEscalacao = false;
  escalacaoSel = new Set((e?.membros ?? []).filter((m) => m.escalado).map((m) => m.playerId));
  if (!$('#guild-escalacao-modal')?.classList.contains('hidden')) pintarEscalacaoGuild();
  // A placa "8/10 no time" da faixa: com a lista nova em mãos ela deixa de depender do
  // próximo delta de estado para contar certo.
  const placa = $('#gld-stat-time')?.querySelector('b');
  if (placa) placa.textContent = `${escalacaoSel.size}/${maxTimeGuild()}`;
}

const maxTimeGuild = () => Number(estado.guildEscalacao?.max) || Number(estado.guildMaxTime) || 10;

function pintarEscalacaoGuild() {
  const corpo = $('#guild-escalacao-corpo');
  const dados = estado.guildEscalacao;
  if (!corpo || !dados) return;
  const max = maxTimeGuild();
  const membros = dados.membros ?? [];
  const souDono = podeGerirGuild();
  const sel = escalacaoSel ?? new Set();

  // Guild que cabe inteira no time: nada a escolher, e dizer isso é mais honesto do que
  // desenhar dez caixinhas marcadas que não se podem desmarcar.
  const cabeInteira = membros.length <= max;

  const busca = escalacaoBusca.trim().toLowerCase();
  const visiveis = busca
    ? membros.filter((m) => String(m.nick ?? '').toLowerCase().includes(busca))
    : membros;

  const linhas = visiveis
    .map((m) => {
      const marcado = sel.has(m.playerId);
      const trava = !souDono || cabeInteira;
      return `<label class="gesc-linha${marcado ? ' on' : ''}">
          <input type="checkbox" data-pid="${m.playerId}" ${marcado ? 'checked' : ''} ${trava ? 'disabled' : ''}>
          <span class="gesc-nick">${escapar(m.nick ?? '')}</span>
          <span class="gesc-nv">${t('painel.nivelCurto')} ${num(m.level)}</span>
          <span class="gesc-tag${marcado ? ' on' : ''}">${marcado ? t('guild.escalado') : t('guild.reserva')}</span>
        </label>`;
    })
    .join('');

  corpo.innerHTML = `
    <div class="gesc-nota">
      <p class="gesc-intro">${t('guild.escalacaoIntro', { max })}</p>
      <p class="gesc-premio">${t('guild.escalacaoPremio')}</p>
      ${cabeInteira ? '' : `<p class="gesc-auto">${t('guild.escalacaoAuto')}</p>`}
    </div>
    ${cabeInteira
      ? `<p class="guild-ok gesc-todos">${t('guild.escalacaoTodos', { n: num(membros.length), max })}</p>`
      : `${souDono ? '' : `<p class="gesc-auto">${t('guild.escalacaoSoDono')}</p>`}
         <div class="gesc-topo">
           <span class="gesc-contagem">${t('guild.escalacaoContagem', { n: sel.size, max })}</span>
           <input id="gesc-busca" class="gesc-busca" type="search" autocomplete="off"
                  placeholder="${escapar(t('guild.escalacaoBuscar'))}" value="${escapar(escalacaoBusca)}">
         </div>`}
    <div class="gesc-lista">${linhas}</div>
    ${cabeInteira || !souDono
      ? ''
      : `<button type="button" class="guild-btn" id="gesc-salvar" ${estado.guildSalvandoEscalacao ? 'disabled' : ''}>
           ${t('guild.escalacaoSalvar')}
         </button>`}`;

  // A regra inteira come 40% da tela do celular antes da primeira caixinha. Duas linhas e o
  // resto a um toque — o mesmo trato das folhas de equipe (`dobrarNotaNoCelular`).
  dobrarNotaNoCelular(corpo.querySelector('.gesc-nota'));

  const campo = $('#gesc-busca');
  if (campo) {
    campo.oninput = () => {
      escalacaoBusca = campo.value;
      pintarEscalacaoGuild();
      // Repintar troca o nó do campo: sem devolver o cursor, digitar a segunda letra exigiria
      // clicar de novo na caixa de busca.
      const novo = $('#gesc-busca');
      novo?.focus();
      novo?.setSelectionRange(novo.value.length, novo.value.length);
    };
  }

  for (const cx of corpo.querySelectorAll('.gesc-linha input[data-pid]')) {
    cx.onchange = () => {
      const pid = Number(cx.dataset.pid);
      if (cx.checked) {
        if (sel.size >= max) {
          cx.checked = false;
          return toast(t('guild.escalacaoCheia', { max }));
        }
        sel.add(pid);
      } else {
        sel.delete(pid);
      }
      escalacaoSel = sel;
      pintarEscalacaoGuild();
    };
  }

  $('#gesc-salvar')?.addEventListener('click', () => {
    if (estado.guildSalvandoEscalacao) return;
    estado.guildSalvandoEscalacao = true;
    pintarEscalacaoGuild();
    enviar({ t: 'guild.escalacao.salvar', playerIds: [...sel] });
    // A recusa do servidor chega como aviso e não repinta nada; sem este prazo o botão ficaria
    // desabilitado para sempre.
    setTimeout(() => {
      if (!estado.guildSalvandoEscalacao) return;
      estado.guildSalvandoEscalacao = false;
      if (!$('#guild-escalacao-modal')?.classList.contains('hidden')) pintarEscalacaoGuild();
    }, 10_000);
  });
}

$('#guild-escalacao-fechar')?.addEventListener('click', fecharEscalacaoGuild);
$('#guild-escalacao-modal')?.addEventListener('click', (ev) => {
  if (ev.target === $('#guild-escalacao-modal')) fecharEscalacaoGuild();
});

// ------------------------------------------------------------------ ginásios
//
// Dezoito ginásios, um por tipo, disputados entre jogadores: cada um registra até cinco
// pokémon DAQUELE tipo e o pódio é ordenado pela soma da força dos cinco, medida com o nível
// travado em 150. Quem está em 1º leva +25% de dano com os pokémon daquele tipo na hunt
// (boss incluso), mas nunca dentro do próprio ginásio nem na Arena PvP.
//
// A tela tem TRÊS estados, e é o mesmo corpo de modal que troca de conteúdo:
//
//   grade    os 18 cards, com o líder e a minha situação em cada
//   painel   um ginásio aberto: o pódio, o meu time e o botão de desafiar
//   editor   a escolha dos cinco, com o motivo de cada recusa escrito no card
//
// Quem decide de verdade é o servidor (`server/ginasios-db.mjs`), que roda as MESMAS funções
// de `shared/ginasios.mjs` sobre as linhas do banco. Aqui elas servem para o jogador ver o
// "não" antes de clicar, em vez de descobrir depois de um round-trip.

/** Quanto tempo o botão de desafiar fica mudo depois do clique, esperando a simulação. */
const GINASIO_DESAFIO_ESPERA_MS = 120_000;
let ginasioDesafiando = false;

/**
 * Quanto a tela espera uma resposta antes de assumir que ela não vem.
 *
 * Sem isto o "Carregando os ginásios…" fica eterno em qualquer caso em que o pedido se perde:
 * pacote descartado, servidor mais VELHO que o cliente (o sim ignora em silêncio o `t` que não
 * conhece — ver `comandos[msg.t]` em `sim.mjs`), ou uma falha na consulta. Uma tela que espera
 * para sempre não é uma tela carregando, é uma tela quebrada que não conta o que houve.
 */
const GINASIO_ESPERA_MS = 12_000;
let ginasioTimeoutId = null;
/** `null` enquanto está tudo bem; `'demorou'` quando a resposta não veio. */
let ginasioErro = null;

/** Arma o relógio da espera. Toda ida ao servidor passa por aqui. */
function pedirAoServidorGinasio(msg) {
  ginasioErro = null;
  clearTimeout(ginasioTimeoutId);
  ginasioTimeoutId = setTimeout(() => {
    ginasioErro = 'demorou';
    if (estado.modalAberto === 'ginasios') pintarGinasios();
  }, GINASIO_ESPERA_MS);
  enviar(msg);
}

/** Chegou resposta: desarma o relógio. */
function chegouRespostaGinasio() {
  clearTimeout(ginasioTimeoutId);
  ginasioTimeoutId = null;
  ginasioErro = null;
}

/** O bloco de "não deu" com o botão de tentar de novo, no lugar do conteúdo que faltou. */
function htmlFalhaGinasio() {
  return `
    <div class="gin-falha">
      <p>${t('gin.falhou')}</p>
      <button type="button" class="gin-btn" id="gin-tentar">${t('gin.tentarDeNovo')}</button>
    </div>`;
}

/** Liga o botão de tentar de novo, se ele estiver na tela. */
function ligarTentarDeNovo() {
  const bt = $('#gin-tentar');
  if (!bt) return;
  bt.onclick = () => {
    if (estado.ginasioTipo) pedirAoServidorGinasio({ t: 'ginasio.painel', tipo: estado.ginasioTipo });
    else pedirAoServidorGinasio({ t: 'ginasio.info' });
    pintarGinasios();
  };
}

/**
 * A força do pokémon NO GINÁSIO: o mesmo ⚔ do card, com o nível travado no cap.
 *
 * O número sai da MESMA função que o servidor usa para montar o pódio, sobre os mesmos
 * campos (`ivs`, `quality`, `potencia`, `shiny`, `refino`) que o snapshot já traz. É o que
 * garante que o "⚔ 41.320" do editor seja o mesmo que vai aparecer na tabela.
 */
const poderGinasioDoMeu = (p) => poderNoGinasio(p, especieDe(p));

/** O que o jogador tem HOJE em cada ginásio, lido do último `ginasio.info`. */
function ginasioDaGrade(tipo) {
  return estado.ginasioInfo?.ginasios?.find((g) => g.tipo === tipo) ?? null;
}

function renderGinasios() {
  return `
    <div class="gin-tela" id="gin-tela">
      <div class="gin-carregando">${t('gin.carregando')}</div>
    </div>`;
}

/** Abre a tela: sempre pela GRADE, e pede o retrato fresco ao servidor. */
function montarGinasios() {
  estado.ginasioTipo = null;
  estado.ginasioPainel = null;
  estado.ginasioEditando = null;
  pedirAoServidorGinasio({ t: 'ginasio.info' });
  if (estado.ginasioInfo) pintarGinasios();
}

/** Roteador das três telas. Chamado sempre que chega pacote novo ou o jogador navega. */
function pintarGinasios() {
  const host = $('#gin-tela');
  if (!host) return;
  // A ordem é a da navegação, do mais interno para o mais externo. O EDITOR vem primeiro de
  // propósito: enquanto ele está aberto, uma resposta atrasada do servidor não pode trocá-lo
  // pelo painel — isso apagaria a escolha em andamento sem o jogador ter pedido nada.
  if (estado.ginasioEditando) return montarEditorDeGinasio(estado.ginasioEditando);
  if (estado.ginasioTipo) return pintarGinasioPainel(host);
  pintarGinasioGrade(host);
}

// ---------------------------------------------------------------- a grade

function pintarGinasioGrade(host) {
  host.classList.remove('editando');
  const info = estado.ginasioInfo;
  if (!info) {
    host.innerHTML = ginasioErro
      ? htmlFalhaGinasio()
      : `<div class="gin-carregando">${t('gin.carregando')}</div>`;
    return ligarTentarDeNovo();
  }
  const meus = info.ginasios.filter((g) => g.souLider).length;
  host.innerHTML = `
    <p class="gin-intro">${t('gin.intro', {
      max: info.timeMax,
      pct: GINASIO_BUFF_PCT,
    })}</p>
    ${info.podeRegistrar
      ? (meus
        ? `<p class="gin-meus-titulos">${t('gin.meusTitulos', { n: meus })}</p>`
        : '')
      : `<p class="gin-travado">${t('gin.semNivel', { n: info.nivelMin })}</p>`}
    <div class="gin-grade" id="gin-grade"></div>`;

  const grade = $('#gin-grade');
  for (const g of info.ginasios) {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = `gin-card ${g.tipo}${g.souLider ? ' meu' : ''}`;
    card.dataset.tipo = g.tipo;
    // O card é um PÔSTER do ginásio: o tipo no alto, o LÍDER andando no meio e como eu estou
    // embaixo. O boneco no centro é o que transforma dezoito retângulos iguais em dezoito
    // lugares com dono — e é o que dá sentido ao espaço que a grade tinha sobrando.
    card.innerHTML = `
      <div class="gin-card-topo">
        <img class="gin-card-ico" src="${iconeDoGinasio(g.tipo)}" alt="">
        <span class="gin-card-nome">${g.tipo}</span>
      </div>
      <div class="gin-card-palco"${g.lider ? '' : ` style="--gin-marca:url('${iconeDoGinasio(g.tipo)}')"`}></div>
      <div class="gin-card-lider">${
        g.lider ? `👑 ${escapar(g.lider.nick)}` : `<i>${t('gin.semLider')}</i>`
      }</div>
      <div class="gin-card-poder">${g.lider ? `⚔ ${num(g.lider.poder)}` : ''}</div>
      <div class="gin-card-meu">${
        g.meuTime
          ? t('gin.meuPoder', { poder: num(g.meuTime.poder) })
          : `<i>${t('gin.semTime')}</i>`
      }</div>`;
    // O boneco é o mesmo `spriteAnimado` do ranking e do replay: anda sozinho, olhando para
    // baixo. Ginásio sem dono fica com o palco vazio de propósito — a ausência é a informação.
    if (g.lider) {
      card.querySelector('.gin-card-palco').appendChild(
        spriteAnimado(g.lider.looktype ?? 159, 52, 3, null, g.lider.vs, { treinador: true }),
      );
    }
    card.onclick = () => abrirGinasio(g.tipo);
    grade.appendChild(card);
  }
}

function abrirGinasio(tipo) {
  estado.ginasioTipo = tipo;
  estado.ginasioPainel = null;
  estado.ginasioTimeSel = [];
  estado.ginasioEditando = null;
  pedirAoServidorGinasio({ t: 'ginasio.painel', tipo });
  pintarGinasios();
}

function voltarParaGrade() {
  fecharTimeGinasio();
  estado.ginasioTipo = null;
  estado.ginasioPainel = null;
  estado.ginasioEditando = null;
  pedirAoServidorGinasio({ t: 'ginasio.info' });
  pintarGinasios();
}

// ------------------------------------------------------------- um ginásio

/** As cinco bolinhas de sprite de um time do pódio. */
function fileiraDeSprites(pokemons) {
  const div = document.createElement('div');
  div.className = 'gin-time-sprites';
  for (const pk of pokemons) {
    const cell = document.createElement('span');
    cell.className = 'gin-time-sprite';
    cell.title = `${pk.shiny ? prefixoShiny() : ''}${pk.nome} · ${t('painel.nivelCurto')}${pk.levelGinasio ?? pk.level}${
      pk.level > (pk.levelGinasio ?? pk.level) ? ` (${t('painel.nivelCurto')}${pk.level})` : ''
    }`;
    cell.appendChild(spritePokemon(pk, 28));
    div.appendChild(cell);
  }
  return div;
}

/** Modal do time completo — mesma ideia do Ranking → Guild → membro. */
let ginTimeDetalheLinha = null;

function fecharTimeGinasio() {
  ginTimeDetalheLinha = null;
  $('#gin-time-detalhe')?.classList.add('hidden');
}

/**
 * O nível de um pokémon do pódio: o real e, acima de `ARENA_NIVEL_CHEIO`, quanto ele CONTA.
 *
 * `levelGinasio` é lido primeiro porque é o número que a linha do pódio de fato USOU — um
 * pódio em cache de antes do deploy traz a medida antiga, e preferir o campo do servidor é o
 * que impede a tela de mostrar uma conta e o ranking outra. Quando ele não vem, a régua é
 * recalculada aqui com a mesma função compartilhada.
 */
function rotuloNivelGinasio(pk) {
  const real = Math.max(1, Math.floor(Number(pk.level) || 1));
  const medido = pk.levelGinasio ?? nivelNoGinasio(real);
  return `${t('painel.nivelCurto')}${rotuloNivelDeArena(real, medido)}`;
}

/** Card de um pokémon do time de ginásio — reutiliza o visual da equipe de guild. */
function cardTimeGinasio(pk) {
  const el = document.createElement('div');
  el.className = 'gd-pk' + (pk.shiny ? ' shiny' : '');
  el.innerHTML = `
    <div class="gd-pk-arte"></div>
    <div class="gd-pk-info">
      <div class="gd-pk-nome">${pk.shiny ? prefixoShiny() : ''}${escapar(pk.nome ?? '')}${selosTm(pk)}</div>
      <div class="gd-pk-sub">${chipsDeTipo(pk.tipos)}</div>
      <div class="gd-pk-lv">${rotuloNivelGinasio(pk)} · ⚔ ${num(pk.poder ?? 0)}</div>
    </div>
    <div class="gd-pk-selos">${selosAtributos(pk, { compacto: true })}</div>`;
  el.querySelector('.gd-pk-arte').appendChild(spritePokemon(pk, 44));
  el.title = t('cm.verFicha');
  el.onclick = () => abrirFichaDoPokemon(pk);
  return el;
}

function abrirTimeGinasio(linha, tipo) {
  if (!linha?.pokemons?.length) return;
  ginTimeDetalheLinha = linha;
  const modal = $('#gin-time-detalhe');
  if (!modal) return;
  $('#gin-time-detalhe-titulo').textContent = t('gin.timeDe', {
    nick: linha.nick ?? '',
    tipo: tipo ?? estado.ginasioTipo ?? '',
  });
  const host = $('#gin-time-detalhe-corpo');
  host.innerHTML = `
    <div class="gin-time-detalhe-cab">
      <span class="gin-time-detalhe-ava" id="gin-time-detalhe-ava"></span>
      <div class="gin-time-detalhe-meta">
        <div class="gin-time-detalhe-pos">${t('gin.timePosicao', { pos: linha.pos ?? '—' })}</div>
        <div class="gin-time-detalhe-poder">⚔ ${num(linha.poder ?? 0)}</div>
        <div class="gin-time-detalhe-nv">${t('painel.nivelCurto')} ${num(linha.nivelTreinador ?? '—')}</div>
      </div>
    </div>
    <p class="gin-time-detalhe-ajuda">${t('gin.timeAjuda')}</p>
    <div class="gd-equipe gin-time-detalhe-equipe" id="gin-time-detalhe-equipe"></div>`;
  $('#gin-time-detalhe-ava').appendChild(
    spriteAnimado(linha.looktype ?? 159, 44, 3, null, linha.vs, { treinador: true }),
  );
  const equipe = $('#gin-time-detalhe-equipe');
  for (const pk of linha.pokemons) equipe.appendChild(cardTimeGinasio(pk));
  modal.classList.remove('hidden');
}

function ligarTimeGinasio(el, linha, tipo) {
  if (!linha?.pokemons?.length) return;
  el.classList.add('gin-clicavel');
  el.setAttribute('role', 'button');
  el.tabIndex = 0;
  el.title = t('gin.verTime');
  const abrir = () => abrirTimeGinasio(linha, tipo);
  el.onclick = abrir;
  el.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      abrir();
    }
  };
}

$('#gin-time-detalhe-fechar')?.addEventListener('click', fecharTimeGinasio);
$('#gin-time-detalhe')?.addEventListener('click', (ev) => {
  if (fichaAberta()) return;
  if (ev.target === $('#gin-time-detalhe')) fecharTimeGinasio();
});

function pintarGinasioPainel(host) {
  host.classList.remove('editando');
  const tipo = estado.ginasioTipo;
  const painel = estado.ginasioPainel;
  const daGrade = ginasioDaGrade(tipo);
  const info = estado.ginasioInfo;

  host.innerHTML = `
    <div class="gin-topo">
      <button type="button" class="gin-voltar" id="gin-voltar">← ${t('gin.voltar')}</button>
      <img class="gin-topo-ico" src="${iconeDoGinasio(tipo)}" alt="">
      <h3 class="gin-topo-nome">${t('gin.tituloDoGinasio', { tipo })}</h3>
    </div>
    <p class="gin-regra">${t('gin.regraBuff', { pct: GINASIO_BUFF_PCT, tipo })}</p>
    <div class="gin-meu" id="gin-meu"></div>
    <h4 class="gin-podio-titulo">${t('gin.podio')}</h4>
    <div class="gin-podio" id="gin-podio">${
      painel ? '' : (ginasioErro ? htmlFalhaGinasio() : `<div class="gin-carregando">${t('gin.carregando')}</div>`)
    }</div>`;
  $('#gin-voltar').onclick = voltarParaGrade;
  ligarTentarDeNovo();

  // ---- o meu bloco: time registrado, posição e os dois botões
  const meu = $('#gin-meu');
  const podeRegistrar = info?.podeRegistrar ?? false;
  const pos = painel?.minhaPos ?? null;
  const meuTime = painel?.meuTime ?? null;
  meu.innerHTML = `
    <div class="gin-meu-linha">
      <span class="gin-meu-rotulo">${t('gin.meuTime')}</span>
      <span class="gin-meu-valor">${
        meuTime
          ? t('gin.minhaPosicao', { pos, poder: num(meuTime.poder) })
          : `<i>${t('gin.semTime')}</i>`
      }</span>
    </div>
    <div class="gin-meu-sprites" id="gin-meu-sprites"></div>
    <div class="gin-meu-acoes">
      <button type="button" class="gin-btn" id="gin-editar" ${podeRegistrar ? '' : 'disabled'}>${
        meuTime ? t('gin.editarTime') : t('gin.registrarTime')
      }</button>
      <button type="button" class="gin-btn btn-apagado" id="gin-desafiar">${t('gin.desafiar')}</button>
    </div>
    ${podeRegistrar ? '' : `<p class="gin-travado">${t('gin.semNivel', { n: info?.nivelMin ?? 150 })}</p>`}`;

  if (meuTime?.pokemons?.length) $('#gin-meu-sprites').appendChild(fileiraDeSprites(meuTime.pokemons));
  $('#gin-editar').onclick = () => abrirEditorDeGinasio(tipo);

  const btDesafiar = $('#gin-desafiar');
  const souLider = daGrade?.souLider ?? (pos === 1);
  const cdDesafio = painel?.desafioCooldownMs ?? 0;
  if (!daGrade?.lider) {
    btDesafiar.textContent = t('gin.semLider');
    btDesafiar.disabled = true;
  } else if (souLider) {
    btDesafiar.textContent = t('gin.vocEhLider');
    btDesafiar.disabled = true;
  } else if (!meuTime) {
    btDesafiar.textContent = t('gin.desafiarSemTime');
    btDesafiar.disabled = true;
  } else if (cdDesafio > 0) {
    btDesafiar.textContent = t('gin.desafioEm', { tempo: formatarCooldownDesafio(cdDesafio) });
    btDesafiar.disabled = true;
  } else {
    btDesafiar.disabled = ginasioDesafiando;
    btDesafiar.textContent = t('gin.desafiar');
    btDesafiar.onclick = () => desafiarGinasio(tipo);
  }

  // ---- o pódio
  if (!painel) return;
  const podio = $('#gin-podio');
  podio.innerHTML = '';
  if (!painel.ranking.length) {
    podio.innerHTML = `<p class="vazio-msg">${t('gin.podioVazio')}</p>`;
    return;
  }
  montarPodioGinasio(podio, painel, tipo);
}

/**
 * O TOP 3 em degraus (2º, 1º, 3º) e o resto em lista — a mesma montagem do Ranking, com o
 * mesmo troféu e a mesma coroa.
 *
 * Reaproveitar a linguagem do Ranking não é economia de código (o HTML é outro): é que o
 * jogador já aprendeu o que aquele degrau significa. Um segundo pódio com desenho próprio
 * seria uma segunda coisa para entender, dizendo exatamente a mesma coisa.
 */
function montarPodioGinasio(host, painel, tipo) {
  const top3 = painel.ranking.slice(0, 3);
  const degraus = document.createElement('div');
  degraus.className = 'gin-degraus';
  for (const pos of [2, 1, 3]) {
    const l = top3[pos - 1];
    const caixa = document.createElement('div');
    caixa.className = `gin-pod lugar-${pos}${l && l.nick === estado.eu?.nick ? ' eu' : ''}`;
    if (!l) {
      // Degrau sem dono fica VISÍVEL e vazio, e não escondido: o buraco no pódio é um convite.
      caixa.classList.add('vago');
      caixa.innerHTML = `
        <img class="gin-pod-trofeu" src="/assets/site/assets/ui/trofeu-${pos}.png" alt="">
        <div class="gin-pod-lugar">${pos}º</div>
        <div class="gin-pod-vago">${t('gin.degrauVago')}</div>`;
      degraus.appendChild(caixa);
      continue;
    }
    caixa.innerHTML = `
      <img class="gin-pod-trofeu" src="/assets/site/assets/ui/trofeu-${pos}.png" alt="${pos}º">
      <div class="gin-pod-lugar">${pos}º</div>
      <div class="gin-pod-ava">
        <img class="gin-pod-coroa" src="/assets/site/assets/ui/coroa-${pos}.png" alt="" aria-hidden="true">
      </div>
      <div class="gin-pod-nome">${escapar(l.nick)}</div>
      <div class="gin-pod-val">⚔ ${num(l.poder)}</div>
      ${pos === 1 ? `<div class="gin-pod-premio">+${GINASIO_BUFF_PCT}% ${tipo}</div>` : ''}
      <div class="gin-pod-time"></div>`;
    caixa.querySelector('.gin-pod-ava').appendChild(
      spriteAnimado(l.looktype ?? 159, pos === 1 ? 60 : 46, 3, null, l.vs, { treinador: true }),
    );
    caixa.querySelector('.gin-pod-time').appendChild(fileiraDeSprites(l.pokemons));
    ligarTimeGinasio(caixa, l, tipo);
    degraus.appendChild(caixa);
  }
  host.appendChild(degraus);

  // A faixa do líder: há quanto tempo ele segura o ginásio. Só aparece quando há líder.
  if (painel.liderDesde && top3[0]) {
    const faixa = document.createElement('p');
    faixa.className = 'gin-desde';
    faixa.innerHTML = t('gin.liderDesde', {
      nick: escapar(top3[0].nick),
      tempo: tempoDesde(painel.liderDesde),
    });
    host.appendChild(faixa);
  }

  // O QUANTO FALTA. É o número que traz o jogador de volta — "⚔ 4.120 atrás do 1º" é uma
  // meta; "2º lugar" é só uma posição.
  if (painel.minhaPos > 1 && painel.faltaParaOTopo > 0) {
    const alvo = document.createElement('p');
    alvo.className = 'gin-falta';
    alvo.innerHTML = t('gin.faltaParaOTopo', { poder: num(painel.faltaParaOTopo) });
    host.appendChild(alvo);
  }

  // Do 4º em diante, em lista.
  const resto = painel.ranking.slice(3);
  if (resto.length) {
    const lista = document.createElement('div');
    lista.className = 'gin-lista';
    for (const linha of resto) {
      const el = document.createElement('div');
      el.className = `gin-linha${linha.nick === estado.eu?.nick ? ' eu' : ''}`;
      el.innerHTML = `
        <span class="gin-pos">${linha.pos}</span>
        <span class="gin-ava"></span>
        <span class="gin-nick">${escapar(linha.nick)}</span>
        <span class="gin-poder">⚔ ${num(linha.poder)}</span>`;
      el.querySelector('.gin-ava').appendChild(
        spriteAnimado(linha.looktype ?? 159, 28, 3, null, linha.vs, { treinador: true }),
      );
      el.appendChild(fileiraDeSprites(linha.pokemons));
      ligarTimeGinasio(el, linha, tipo);
      lista.appendChild(el);
    }
    host.appendChild(lista);
  }

  if (painel.total > painel.ranking.length) {
    const rodape = document.createElement('p');
    rodape.className = 'gin-podio-rodape';
    rodape.textContent = t('gin.podioMais', { n: painel.total - painel.ranking.length });
    host.appendChild(rodape);
  }
}

/** "23 h", "45 min" — quanto falta para desafiar de novo ESTE ginásio. */
function formatarCooldownDesafio(ms) {
  const h = Math.ceil(ms / 3_600_000);
  if (h >= 2) return t('gin.desafioCooldownHoras', { n: h });
  const m = Math.max(1, Math.ceil(ms / 60_000));
  return t('gin.desafioCooldownMin', { n: m });
}

/** "há 3 dias", "há 4 h", "hoje" — o tempo que o líder segura o ginásio. */
function tempoDesde(iso) {
  const ms = Date.now() - new Date(iso).getTime();
  if (!Number.isFinite(ms) || ms < 0) return t('gin.desdeHoje');
  const dias = Math.floor(ms / 86400000);
  if (dias >= 1) return t('gin.desdeDias', { n: dias });
  const horas = Math.floor(ms / 3600000);
  if (horas >= 1) return t('gin.desdeHoras', { n: horas });
  return t('gin.desdeHoje');
}

// ---------------------------------------------------------------- o editor

/**
 * Os meus pokémon que PODEM entrar neste ginásio, os escolhidos primeiro.
 *
 * Espécie já representada no time SOME da lista em vez de aparecer apagada. Uma coleção de
 * verdade tem dezenas de pokémon do mesmo tipo, e deixar todos os Charizards ali riscados
 * empurrava o botão de salvar para o fim de uma lista que ninguém vai ler. Desmarcar o
 * escolhido traz os irmãos dele de volta na hora — a lista é uma consequência da escolha,
 * não um catálogo fixo.
 */
function pokemonsParaGinasio(tipo) {
  const posSel = (id) => estado.ginasioTimeSel.indexOf(id);
  const escolhidos = estado.ginasioTimeSel
    .map((id) => (estado.eu?.pokemons ?? []).find((p) => p.id === id))
    .filter(Boolean);
  const especiesTomadas = new Set(escolhidos.map((p) => p.speciesId));
  return [...(estado.eu?.pokemons ?? [])]
    .filter((p) => pokemonDoTipo(p.tipos, tipo))
    .filter((p) => posSel(p.id) >= 0 || !especiesTomadas.has(p.speciesId))
    .sort((a, b) => {
      const pa = posSel(a.id);
      const pb = posSel(b.id);
      if (pa >= 0 && pb >= 0) return pa - pb;
      if (pa >= 0 || pb >= 0) return pa >= 0 ? -1 : 1;
      return poderGinasioDoMeu(b) - poderGinasioDoMeu(a) || String(a.nome).localeCompare(String(b.nome));
    });
}

function abrirEditorDeGinasio(tipo) {
  const registrados = ginasioDaGrade(tipo)?.meuTime?.pokemonIds
    ?? estado.ginasioPainel?.meuTime?.pokemons?.map((p) => p.id)
    ?? [];
  // Só entra no rascunho o que AINDA existe na coleção — vendido no Mercado ou evoluído para
  // fora do tipo sai sozinho, em vez de virar um slot fantasma que o salvar recusaria.
  estado.ginasioTimeSel = registrados.filter((id) =>
    (estado.eu?.pokemons ?? []).some((p) => p.id === id && pokemonDoTipo(p.tipos, tipo)),
  );
  estado.ginasioEditando = tipo;
  montarEditorDeGinasio(tipo);
}

/** Sai do editor e volta ao painel do ginásio. */
function fecharEditorDeGinasio() {
  estado.ginasioEditando = null;
  $('#gin-tela')?.classList.remove('editando');
  pintarGinasios();
}

function montarEditorDeGinasio(tipo) {
  const host = $('#gin-tela');
  if (!host) return;
  const max = estado.ginasioInfo?.timeMax ?? 5;
  const escolhidos = estado.ginasioTimeSel
    .map((id) => (estado.eu?.pokemons ?? []).find((p) => p.id === id))
    .filter(Boolean);
  const poderTotal = escolhidos.reduce((s, p) => s + poderGinasioDoMeu(p), 0);

  // O editor é uma COLUNA de três partes: cabeçalho, lista que rola e rodapé grudado. A
  // classe `editando` é o que troca a rolagem da tela inteira pela rolagem só da lista —
  // sem ela, o "Salvar time" descia junto com os duzentos pokémon do jogador e virava um
  // botão que só existe para quem tem paciência de chegar ao fim.
  host.classList.add('editando');
  host.innerHTML = `
    <div class="gin-ed-cabeca">
      <div class="gin-topo">
        <button type="button" class="gin-voltar" id="gin-ed-voltar">← ${t('gin.voltar')}</button>
        <img class="gin-topo-ico" src="${iconeDoGinasio(tipo)}" alt="">
        <h3 class="gin-topo-nome">${t('gin.editarTituloDoGinasio', { tipo })}</h3>
      </div>
      <p class="gin-regra">${t('gin.editarRegras', { max, tipo })}</p>
      <div class="gin-ed-barra">
        <p class="gin-contagem">${t('gin.contagem', {
          n: escolhidos.length, max, poder: num(poderTotal),
        })}</p>
        <label class="filtros-select-campo filtros-select-local gin-ed-local">
          <span>${t('colecao.filtroLocal')}</span>
          <select class="filtros-select-el" id="gin-ed-local">${htmlOpcoesLocal(LOCAIS_TODOS, estado.ginasioLocal)}</select>
        </label>
      </div>
    </div>
    <div class="gin-ed-lista" id="gin-ed-lista"></div>
    <div class="gin-ed-rodape">
      <button type="button" class="gin-btn btn-apagado" id="gin-ed-cancelar">${t('gin.cancelar')}</button>
      <button type="button" class="gin-btn" id="gin-ed-salvar">${t('gin.salvar')}</button>
    </div>`;

  const lista = $('#gin-ed-lista');
  // O "Local" corta só quem AINDA não foi escolhido: o time montado fica sempre à vista, senão
  // trocar o filtro esconderia metade da equipe que o "Salvar" vai gravar.
  const colecao = conjuntoColecaoCliente();
  const local = estado.ginasioLocal ?? 'todos';
  const candidatos = pokemonsParaGinasio(tipo).filter(
    (p) => estado.ginasioTimeSel.includes(p.id) || passaLocal(p, local, colecao),
  );
  if (!candidatos.length) {
    lista.innerHTML = `<p class="vazio-msg">${t(local === 'todos' ? 'gin.semCandidatos' : 'depot.nenhumResultado', { tipo })}</p>`;
  }
  $('#gin-ed-local').onchange = (ev) => {
    estado.ginasioLocal = ev.target.value || 'todos';
    montarEditorDeGinasio(tipo);
  };
  for (const p of candidatos) {
    const idx = estado.ginasioTimeSel.indexOf(p.id);
    const on = idx >= 0;
    // O motivo é calculado contra os OUTROS escolhidos: sem tirar o próprio da lista, um
    // pokémon já selecionado se acusaria de espécie repetida contra si mesmo.
    const motivo = on ? null : motivoForaDoGinasio(p, tipo, escolhidos);
    const el = document.createElement('div');
    el.className = `gin-ed-pk${on ? ' on' : ''}${motivo ? ' bloqueado' : ''}`;
    el.innerHTML = `
      <div class="gin-ed-pk-info">
        <!-- O nível sai cru: o ginásio não tem mais teto, então não há o que riscar. -->
        <div class="gin-ed-pk-nome">${p.shiny ? prefixoShiny() : ''}${escapar(p.nome)}
          <span class="pl-lv">${t('painel.nivelCurto')}${p.level}</span>${htmlMarcaColecao(p, colecao)}</div>
        <div class="depot-meta">${selosDeTipo(p.tipos)} · ⚔ ${num(poderGinasioDoMeu(p))}${
          motivo ? ` · <b class="gin-ed-motivo">${t(`gin.recusa.${motivo}`)}</b>` : ''
        }</div>
        <div class="gin-ed-pk-selos">${selosAtributos(p, { compacto: true })}</div>
      </div>
      <div class="gin-ed-pk-marca">${on ? `<span class="gin-ed-pk-ordem">${idx + 1}</span>` : ''}</div>`;
    el.prepend(spritePokemon(p, 32));
    el.onclick = () => {
      if (on) {
        estado.ginasioTimeSel = estado.ginasioTimeSel.filter((id) => id !== p.id);
      } else {
        const porque = motivoForaDoGinasio(p, tipo, escolhidos);
        if (porque) return toast(t(`gin.recusa.${porque}`));
        estado.ginasioTimeSel = [...estado.ginasioTimeSel, p.id];
      }
      montarEditorDeGinasio(tipo);
    };
    lista.appendChild(el);
  }

  $('#gin-ed-voltar').onclick = fecharEditorDeGinasio;
  $('#gin-ed-cancelar').onclick = fecharEditorDeGinasio;
  $('#gin-ed-salvar').onclick = () => {
    pedirAoServidorGinasio({ t: 'ginasio.salvar', tipo, pokemonIds: estado.ginasioTimeSel });
  };
}

// ---------------------------------------------------------------- o desafio

function desafiarGinasio(tipo) {
  if (ginasioDesafiando) return;
  ginasioDesafiando = true;
  const bt = $('#gin-desafiar');
  if (bt) {
    bt.disabled = true;
    bt.textContent = t('gin.simulando');
  }
  enviar({ t: 'ginasio.desafiar', tipo });
  // A resposta pode não vir (socket caído, servidor recusando). Sem isto o botão ficaria mudo
  // para sempre depois de uma falha — a mesma trava do replay da Guerra de Guilds.
  setTimeout(() => {
    ginasioDesafiando = false;
    if (estado.modalAberto === 'ginasios') pintarGinasios();
  }, GINASIO_DESAFIO_ESPERA_MS);
}

/** O pacote do servidor: grade, painel, confirmação de gravação ou o replay do desafio. */
function aoReceberGinasio(m) {
  chegouRespostaGinasio();
  if (m.info) {
    estado.ginasioInfo = m.info;
    if (estado.modalAberto === 'ginasios') pintarGinasios();
  }
  if (m.painel) {
    estado.ginasioPainel = m.painel;
    // Só repinta se a tela ainda está NO ginásio que pediu: quem clicou em voltar enquanto o
    // pacote viajava não deve ver o painel reabrir sozinho por cima da grade.
    if (estado.modalAberto === 'ginasios' && estado.ginasioTipo === m.painel.tipo) pintarGinasios();
  }
  if (m.salvo) {
    toast(t('gin.salvoOk', { tipo: m.salvo.tipo }));
    // Salvou: o editor cumpriu o papel e sai de cena, dando lugar ao pódio já atualizado.
    estado.ginasioEditando = null;
    // Volta do editor para o painel do ginásio e recarrega a grade: o título pode ter mudado
    // de dono neste exato salvamento.
    estado.ginasioTipo = m.salvo.tipo;
    enviar({ t: 'ginasio.info' });
    if (estado.modalAberto === 'ginasios') pintarGinasios();
  }
  if (m.desafio) {
    ginasioDesafiando = false;
    const d = m.desafio;
    abrirReplayGuerra({
      replay: d.replay,
      titulo: t(
        d.venci
          ? (d.tomouLideranca ? 'gin.desafioVenciLider' : 'gin.desafioVenci')
          : 'gin.desafioPerdi',
        { tipo: d.tipo, lider: d.lider?.nick ?? '' },
      ),
    });
    if (d.tomouLideranca) {
      enviar({ t: 'ginasio.info' });
      if (estado.ginasioTipo === d.tipo) enviar({ t: 'ginasio.painel', tipo: d.tipo });
    } else if (estado.ginasioTipo === d.tipo) {
      enviar({ t: 'ginasio.painel', tipo: d.tipo });
    }
    if (estado.modalAberto === 'ginasios') pintarGinasios();
  }
}

/** Potência I–V (sorteada na captura, nunca muda). */
const POTENCIA_ROMANA = ['I', 'II', 'III', 'IV', 'V'];
const rotuloPotencia = (n) => POTENCIA_ROMANA[Math.max(1, Math.min(5, Number(n) || 1)) - 1];

// ------------------------------------------------------ painel de golpes do palco
//
// Mostra os golpes do pokémon ATIVO, um embaixo do outro, com o cooldown de cada um em forma
// de relógio — puro enfeite informativo (full idle: quem ataca é o próprio pokémon; clicar no
// ícone não faz nada). O cooldown é PREVISTO no cliente a partir do evento `ataque` que o
// servidor já manda a cada golpe: como o nome do golpe e o cooldown dele já estão no catálogo
// de espécies (o mesmo que a Pokédex usa), dá para desenhar o relógio sem o servidor precisar
// expor `cdGolpes` — que hoje é estado interno só do tick de combate.
const ICONE_TIPO = {
  NORMAL: '/img/tipos/normal.svg', FIRE: '/img/tipos/fire.svg', WATER: '/img/tipos/water.svg',
  GRASS: '/img/tipos/grass.svg', ELECTRIC: '/img/tipos/electric.svg', ICE: '/img/tipos/ice.svg',
  FIGHTING: '/img/tipos/fighting.svg', POISON: '/img/tipos/poison.svg', GROUND: '/img/tipos/ground.svg',
  FLYING: '/img/tipos/flying.svg', PSYCHIC: '/img/tipos/psychic.svg', BUG: '/img/tipos/bug.svg',
  ROCK: '/img/tipos/rock.svg', GHOST: '/img/tipos/ghost.svg', DRAGON: '/img/tipos/dragon.svg',
  DARK: '/img/tipos/dark.svg', STEEL: '/img/tipos/steel.svg', FAIRY: '/img/tipos/fairy.svg',
};


/** Bônus de cooldown pelo IV de Speed — mesma conta de `cooldownComSpeed` em `server/game/combate.mjs`. */
const IV_SPEED_CD_MAX_UI = 32;
const IV_SPEED_CD_MS_POR_PONTO_UI = 10;
const SPD_CD_MIN_MS_UI = 400;
function cooldownEfetivoUI(cooldownMs, ivSpeed) {
  const base = Math.max(0, Number(cooldownMs) || 0);
  if (base <= 0) return base;
  const iv = Math.min(IV_SPEED_CD_MAX_UI, Math.max(1, Math.round(Number(ivSpeed) || 1)));
  return Math.max(SPD_CD_MIN_MS_UI, base - iv * IV_SPEED_CD_MS_POR_PONTO_UI);
}

/** Golpes que o pokémon ativo tem AGORA: espécie no nível dele, mais o TM elemental (se houver). */
function golpesDoAtivo(p) {
  const esp = estado.especies.get(p.speciesId);
  if (!esp) return [];
  const golpes = (esp.attacks ?? [])
    .filter((a) => (a.learnLevel ?? 1) <= p.level)
    .map((a) => ({ ...a, cooldownMs: cooldownEfetivoUI(a.cooldownMs, p.ivs?.speed) }));
  if (p.tmElemental) {
    const tm = golpeTmElemental(p.tmElemental);
    tm.cooldownMs = cooldownEfetivoUI(tm.cooldownMs, p.ivs?.speed);
    golpes.push(tm);
  }
  return golpes;
}

let golpesPainelSig = null;
let golpesAtuaisCache = [];
const golpesCooldownFim = new Map(); // nome do golpe → { inicio, duracao }

// ------------------------------------------------- a recarga PAUSA fora de campo
//
// O relógio do painel acompanha o do servidor: a recarga é do POKÉMON e só corre com ele em
// campo (ver `shared/cooldown-ativo.mjs`). Trocar de ativo não zera nada e também não adianta
// nada — o que falta de cada golpe fica guardado por id de pokémon e volta a contar de onde
// parou quando ele entra em campo outra vez.
//
// Sem este espelho o painel MENTIRIA na direção pior: o ícone acenderia como "pronto" enquanto
// o servidor ainda cobra a recarga, e o jogador acharia que o golpe sumiu.
const golpesCooldownPausa = new Map(); // id do pokémon → Map(nome do golpe → ms que faltam)
let golpesCooldownDe = null; // de quem é o `golpesCooldownFim` acima

/** Troca de ativo: o saldo de quem saiu é guardado, o de quem entrou volta de onde parou. */
function sincronizarCooldownsDaUI(activeId) {
  const id = activeId ?? null;
  if (golpesCooldownDe === id) return;
  const agora = Date.now();
  if (golpesCooldownDe != null) {
    const resta = new Map();
    for (const [nome, cd] of golpesCooldownFim) {
      const falta = cd.duracao - (agora - cd.inicio);
      if (falta > 0) resta.set(nome, falta);
    }
    if (resta.size) golpesCooldownPausa.set(golpesCooldownDe, resta);
    else golpesCooldownPausa.delete(golpesCooldownDe);
  }
  golpesCooldownFim.clear();
  for (const [nome, falta] of golpesCooldownPausa.get(id) ?? []) {
    golpesCooldownFim.set(nome, { inicio: agora, duracao: falta });
  }
  golpesCooldownPausa.delete(id);
  golpesCooldownDe = id;
}

/** A entrada numa ARENA zera a recarga do time inteiro (a cura não) — ver `zerarCooldowns` no sim. */
function zerarCooldownsDaUI() {
  golpesCooldownFim.clear();
  golpesCooldownPausa.clear();
  golpesCooldownDe = estado.eu?.activeId ?? null;
}

/**
 * Chamado pelo `case 'ataque'` de `aoEvento` — arma o relógio do golpe que acabou de sair.
 *
 * O golpe é procurado primeiro na coluna montada e, se não estiver lá, na equipe. A coluna nem
 * sempre existe ainda: ela é montada pelo ESTADO, e o estado sai depois dos eventos do mesmo
 * tique. Quem sai do Centro (onde a coluna fica escondida) direto para um boss recebe o golpe de
 * abertura antes de ter coluna, e ele era descartado aqui em silêncio — o ícone ficava "pronto"
 * pelos 60 s da recarga. O mesmo vale para o primeiro golpe depois de uma troca de ativo, que
 * chega com a coluna do pokémon anterior.
 */
function registrarUsoDeGolpe(nome) {
  let golpe = golpesAtuaisCache.find((g) => g.name === nome);
  if (!golpe) {
    const e = estado.eu;
    const equipe = (e?.pokemons ?? []).filter((x) => x.id === e.activeId || x.slot != null);
    // O ativo na frente: é quase sempre ele, e o cooldown depende do IV de Speed de quem bateu.
    equipe.sort((a, b) => (b.id === e.activeId) - (a.id === e.activeId));
    for (const pk of equipe) {
      golpe = golpesDoAtivo(pk).find((g) => g.name === nome);
      if (golpe) break;
    }
  }
  if (!golpe) return;
  golpesCooldownFim.set(nome, { inicio: Date.now(), duracao: golpe.cooldownMs });
}

function esconderGolpeDica() {
  $('#golpe-dica')?.classList.add('hidden');
}

function mostrarGolpeDica(g, btnEl) {
  const dica = $('#golpe-dica');
  if (!dica) return;
  dica.innerHTML = `
    <div class="golpe-dica-nome">${escapar(g.name)}</div>
    <div class="golpe-dica-linha"><span>${t('dex.cooldown')}</span><b>${(g.cooldownMs / 1000).toFixed(1)}s</b></div>
    <div class="golpe-dica-linha"><span>${t('dex.danoBase')}</span><b>${num(g.power)}</b></div>`;
  // `offsetTop` é a posição no conteúdo INTEIRO da lista, sem descontar rolagem — com muitos
  // golpes (`.golpes-lista` agora rola) a dica saía grudada lá embaixo enquanto o ícone tocado
  // já tinha subido na tela. Subtrai o `scrollTop` pra ela seguir o ícone de verdade.
  const scrollTop = $('#golpes-lista')?.scrollTop ?? 0;
  dica.style.top = `${btnEl.offsetTop - scrollTop}px`;
  dica.classList.remove('hidden');
}

function construirGolpesPainel(p) {
  const lista = $('#golpes-lista');
  if (!lista) return;
  golpesAtuaisCache = golpesDoAtivo(p);
  lista.innerHTML = '';
  for (const g of golpesAtuaisCache) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'golpe-ico pronto';
    btn.dataset.golpe = g.name;
    btn.style.setProperty('--p', 1);
    // Não usa `iconeArquivo`: ela fixa `width`/`height` no `style` do `<img>`, e um `style`
    // inline vence a regra `.golpe-ico img` do CSS — sobrava uma margem torta em vez do ícone
    // preencher a bolinha até a borda. Aqui o `<img>` fica sem estilo próprio de propósito.
    const img = document.createElement('img');
    img.src = ICONE_TIPO[g.type] ?? ICONE_TIPO.NORMAL;
    img.alt = '';
    btn.appendChild(img);
    // Com mouse, a ficha segue o hover; no toque ela abre/fecha no próprio clique — a mesma
    // divisão que o Hunt Analyser do Mapa já usa entre desktop e celular.
    if (movelAtivo()) {
      btn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        const dica = $('#golpe-dica');
        if (dica && !dica.classList.contains('hidden') && dica.dataset.golpe === g.name) {
          return esconderGolpeDica();
        }
        mostrarGolpeDica(g, btn);
        if (dica) dica.dataset.golpe = g.name;
      });
    } else {
      btn.addEventListener('mouseenter', () => mostrarGolpeDica(g, btn));
      btn.addEventListener('mouseleave', () => esconderGolpeDica());
    }
    lista.appendChild(btn);
  }
}

/** Chamado por `pintarAtivo` a cada snapshot — só remonta os ícones quando o golpeset muda. */
function pintarGolpesPainel(e, p) {
  const painel = $('#golpes-painel');
  if (!painel) return;
  // Sem cena não há "ao lado da batalha": o Modo Economia cala o painel junto com ela.
  const visivel = golpesHudLigado() && !economiaLigado() && !!p && p.hp > 0 && !e.noCentro;
  painel.classList.toggle('hidden', !visivel);
  if (!visivel) {
    esconderGolpeDica();
    return;
  }

  // Só remonta os ÍCONES quando o golpeset muda (pokémon diferente, level up, TM novo) — o
  // relógio de cooldown de cada golpe (por nome) segue existindo por baixo, guardado por
  // pokémon: trocar de ativo e voltar não reseta nem adianta nada (ver `aplicarEstado`).
  const sig = `${p.id}|${p.level}|${p.tmElemental ?? ''}`;
  if (sig !== golpesPainelSig) {
    golpesPainelSig = sig;
    construirGolpesPainel(p);
  }
}

// Rolou a lista (moveset grande, `.golpes-lista` passou a rolar) com a dica aberta: a posição
// calculada ficaria presa ao ícone de antes, então fecha — mais simples que recalcular no scroll.
$('#golpes-lista')?.addEventListener('scroll', esconderGolpeDica);

/**
 * Encaixa a coluna no vão livre do palco: mede a borda de baixo de quem estiver empilhado no
 * topo (nome da hunt, aviso de saída, faixa de evento, log) e a borda de cima de quem estiver
 * na base (derrotados, e o log de novo — no celular ele mora lá embaixo) e usa isso como
 * `top`/`height` do painel. Só entram na conta os elementos que de fato SOMBREIAM a coluna
 * (mesma faixa horizontal) — o zoom e o "ir pro Centro", que ficam à direita, não contam.
 */
function reposicionarGolpesPainel() {
  const painel = $('#golpes-painel');
  const palco = $('#palco');
  if (!painel || !palco) return;
  const rPalco = palco.getBoundingClientRect();
  const colEsq = rPalco.left;
  const colDir = rPalco.left + 60; // ~10px de margem + a bolinha do golpe

  let topo = 8;
  let base = rPalco.height - 8;
  const meio = rPalco.top + rPalco.height / 2;
  const candidatos = palco.querySelectorAll(
    '.hud-hunt, .hunt-saida, .evento-faixa, .hud-log, .caidos',
  );
  for (const el of candidatos) {
    if (el.classList.contains('hidden') || el.offsetParent === null) continue;
    const r = el.getBoundingClientRect();
    if (r.right < colEsq || r.left > colDir) continue; // fora da faixa da nossa coluna
    if (r.top + r.height / 2 < meio) topo = Math.max(topo, r.bottom - rPalco.top + 8);
    else base = Math.min(base, r.top - rPalco.top - 8);
  }

  painel.style.top = `${topo}px`;
  painel.style.height = `${Math.max(40, base - topo)}px`;
}

/** O sweep horário do relógio — 10×/s é suave sem custar nada num painel de poucos ícones. */
setInterval(() => {
  const lista = $('#golpes-lista');
  if (!lista || $('#golpes-painel')?.classList.contains('hidden')) return;
  reposicionarGolpesPainel();
  const agora = Date.now();
  for (const btn of lista.children) {
    const cd = golpesCooldownFim.get(btn.dataset.golpe);
    const frac = cd ? Math.min(1, (agora - cd.inicio) / Math.max(1, cd.duracao)) : 1;
    btn.style.setProperty('--p', frac);
    btn.classList.toggle('pronto', frac >= 1);
  }
}, 100);

function pintarAtivo(e) {
  const el = $('#ativo-card');
  const p = e.pokemons.find((x) => x.id === e.activeId);
  if (!p) {
    el.className = 'ativo-card vazio';
    el.textContent = 'nenhum pokémon ativo';
    el.onclick = null;
    el.title = '';
    pintarBotaoEvoluir(null);
    pintarBotaoMega(null);
    pintarBotaoCompartilhar(e);
    pintarBotaoRefino(null);
    pintarGolpesPainel(e, null);
    return;
  }
  const dentro = p.xp - p.xpNivel;
  const faixa = Math.max(1, p.xpProximo - p.xpNivel);
  el.className = 'ativo-card' + (p.shiny ? ' brilho-shiny' : '');
  el.title = t('painel.verFicha');
  el.onclick = () => abrirFichaDoPokemon(p);
  el.innerHTML = `${p.shiny ? brilhoShiny() : ''}
    <div class="ativo-info">
      <div class="ativo-nome">${p.shiny ? prefixoShiny() : ''}${nomePkHtml(p)}${seloRefino(p)} <span class="pl-lv">${t('painel.nivelCurto')} ${p.level}</span></div>
      <div class="ativo-sub">${selosDeTipo(p.tipos)} ${selosTm(p)} ${seloGinasio(p)} ${t('painel.poder')} ${num(p.poder)}</div>
      ${selosAtributos(p)}
      <div class="barra hp ${p.hp / p.maxHp < 0.35 ? 'baixo' : ''}">
        <div class="fill" style="width:${(p.hp / p.maxHp) * 100}%"></div><span>${p.hp} / ${p.maxHp}</span>
      </div>
      <div class="barra xp"><div class="fill" style="width:${(dentro / faixa) * 100}%"></div><span>${num(dentro)} / ${num(faixa)} xp</span></div>
    </div>`;
  el.prepend(spritePokemon(p, 48));
  pintarBotaoEvoluir(p);
  pintarBotaoMega(p);
  pintarBotaoCompartilhar(e);
  pintarBotaoRefino(p);
  pintarGolpesPainel(e, p);
}

let compartilharTimer = null;
/** Id do pokémon da ficha aberta, quando é seu e pode ir pro chat. */
let fichaCompartilharPkId = null;

/**
 * O pokémon é MEU e ainda está comigo? — não anúncio, não ranking alheio, não ficha de espécie.
 *
 * `pk.dono` só existe nas fichas que vieram de fora (mercado, placar, chat); num pokémon do
 * próprio snapshot ele é `undefined`, e por isso a checagem do nick é condicional. A busca na
 * lista é o que fecha o resto: um anúncio meu já saiu do `pokemons` e não passa.
 */
function pokemonNaMinhaMao(pk) {
  if (!pk?.id) return false;
  const meuNick = (estado.eu?.nick ?? estado.nick ?? '').toLowerCase();
  if (pk.dono && pk.dono.toLowerCase() !== meuNick) return false;
  return (estado.eu?.pokemons ?? []).some((p) => p.id === pk.id);
}

/** Só pokémon que ainda estão na sua conta — não anúncio, ranking alheio nem ficha de espécie. */
function pokemonCompartilhavelNoChat(pk) {
  return pokemonNaMinhaMao(pk);
}

function estadoBotaoCompartilhar(e, { exigeAtivo = false } = {}) {
  if (!podeUsarChat()) return { ok: false, disabled: true, title: t('chat.nivelMinimo', { n: CHAT_NIVEL_MIN }) };
  if (exigeAtivo && !e?.pokemons?.find((x) => x.id === e?.activeId)) {
    return { ok: false, disabled: true, title: t('painel.compartilharPk') };
  }
  const ate = e?.compartilharPkAte ?? 0;
  const resta = ate - Date.now();
  if (resta > 0) {
    return { ok: true, disabled: true, title: t('chat.compartilharEspera', { tempo: faltaPara(ate) }) };
  }
  return { ok: true, disabled: false, title: t('painel.compartilharPk') };
}

function aplicarBotaoCompartilhar(btn, visivel, st) {
  if (!btn) return;
  btn.classList.toggle('hidden', !visivel);
  if (!visivel) {
    btn.disabled = true;
    return;
  }
  btn.disabled = st.disabled;
  btn.title = st.title;
  btn.setAttribute('aria-label', st.title);
}

function pintarBotaoCompartilharFicha() {
  const btn = $('#ficha-compartilhar');
  if (!btn) return;
  const visivel = fichaCompartilharPkId != null && pokemonCompartilhavelNoChat({ id: fichaCompartilharPkId });
  aplicarBotaoCompartilhar(btn, visivel, estadoBotaoCompartilhar(estado.eu));
}

function pintarBotaoCompartilhar(e) {
  const btn = $('#btn-compartilhar-pk');
  const st = estadoBotaoCompartilhar(e, { exigeAtivo: true });
  aplicarBotaoCompartilhar(btn, st.ok, st);
  pintarBotaoCompartilharFicha();
  if (!st.ok) {
    clearInterval(compartilharTimer);
    compartilharTimer = null;
    return;
  }
  if (st.disabled) {
    if (!compartilharTimer) {
      compartilharTimer = setInterval(() => {
        if (estado.eu) pintarBotaoCompartilhar(estado.eu);
      }, 1000);
    }
  } else {
    clearInterval(compartilharTimer);
    compartilharTimer = null;
  }
}

function compartilharPokemonNoChat(pokemonId = null) {
  if (!podeUsarChat()) return toast(t('chat.nivelMinimo', { n: CHAT_NIVEL_MIN }));
  const eu = estado.eu;
  if (!eu) return;
  if (Date.now() < (eu.compartilharPkAte ?? 0)) {
    return toast(t('chat.compartilharEspera', { tempo: faltaPara(eu.compartilharPkAte) }));
  }
  if (pokemonId != null) {
    if (!pokemonCompartilhavelNoChat({ id: pokemonId })) return;
  } else if (!eu.pokemons?.find((p) => p.id === eu.activeId)) {
    return;
  }
  const payload = { t: 'chat.compartilhar', canal: estado.canalChat, idioma: estado.idiomaChat };
  if (pokemonId != null) payload.pokemonId = pokemonId;
  enviar(payload);
}

function compartilharPokemonAtivo() {
  const btn = $('#btn-compartilhar-pk');
  if (!btn || btn.disabled || btn.classList.contains('hidden')) return;
  compartilharPokemonNoChat();
}

$('#btn-compartilhar-pk')?.addEventListener('click', (ev) => {
  ev.stopPropagation();
  compartilharPokemonAtivo();
});
$('#ficha-compartilhar')?.addEventListener('click', (ev) => {
  ev.stopPropagation();
  const btn = $('#ficha-compartilhar');
  if (!btn || btn.disabled || btn.classList.contains('hidden') || fichaCompartilharPkId == null) return;
  compartilharPokemonNoChat(fichaCompartilharPkId);
});

/**
 * Qual pedra a espécie precisa para evoluir — segue o tipo primário (`content.mjs`).
 *
 * Nas cadeias que abrem, o tipo é o do DESTINO: Vaporeon pede Water Stone e Flareon pede Fire
 * Stone, apesar de o Eevee ser NORMAL. Ver `tipoDaPedraDeEvolucao`.
 */
function pedraDaEspecie(especie, destino = null) {
  if (!especie?.evolvesToId) return null;
  const tipo = tipoDaPedraDeEvolucao(especie, destino);
  return estado.pedrasEvolucao[tipo] ?? estado.pedrasEvolucao.NORMAL ?? null;
}

/** Shiny evolui com Shiny Stone do tipo primário — espelha `shinyStoneDeEvolucao` no servidor. */
function pedraShinyDaEspecie(especie, destino = null) {
  if (!especie?.evolvesToId) return null;
  const tipo = tipoDaPedraDeEvolucao(especie, destino);
  const pedra = (estado.shinyStone?.pedras ?? []).find((p) => p.tipo === tipo);
  if (!pedra) return null;
  return {
    itemId: pedra.itemId,
    tipo,
    nome: nomeItem(pedra.itemId, `${tipo.charAt(0)}${tipo.slice(1).toLowerCase()} Shiny Stone`),
  };
}

/**
 * Espécies que evoluem com esta pedra — ordem alfabética.
 *
 * Só entra quem tem PARA ONDE evoluir hoje. Metade das cadeias de Galar e Paldea aponta para
 * um alvo ainda sem sprite (`looktype: 1`), e o servidor recusa essas: listar o Chespin na
 * Leaf Stone seria vender uma pedra por uma evolução que não acontece.
 */
function especiesQueUsamPedra(itemId) {
  const out = [];
  for (const esp of estado.especies.values()) {
    // Por DESTINO: o Eevee entra em oito pedras diferentes, uma por eeveelution, e em nenhuma
    // delas pela pedra do tipo dele. Só conta destino com arte — o resto o servidor recusa.
    const serve = destinosDeEvolucao(esp, (id) => estado.especies.get(id))
      .some((d) => d.temArte && pedraDaEspecie(esp, d.especie)?.itemId === itemId);
    if (serve) out.push(esp);
  }
  return out.sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'));
}

/**
 * A MEGA de uma espécie, do jeito que a FICHA precisa: no que ela vira e com que pedra.
 *
 * Irmã de `infoMega`, e separada dela de propósito: aquela responde "este pokémon PODE
 * megaevoluir agora?" e por isso olha o inventário, o shiny e a pedra certa do bicho. Esta
 * responde "esta espécie TEM mega?", que é uma verdade do catálogo — vale na Pokédex de quem
 * nunca viu um fragmento, e vale na ficha do bicho de outro jogador, onde não há inventário
 * nenhum para consultar.
 *
 * `null` para quem não tem mega, para a própria mega (não megaevolui de novo) e para as
 * variantes de Outland — as três recusas moram em `dexDaMega`, no `shared/megas.mjs`, que é
 * também quem deixa o clone de Orre passar.
 */
function megaDaFicha(especie) {
  const meta = especie ? megaDaEspecie(especie.pokeId) : null;
  if (!meta) return null;
  const mega = estado.especies.get(MEGA_POKE_BASE + meta.dex);
  // Sem arte jogável a mega não entra: seria prometer uma forma que o jogo ainda não desenha.
  if (!mega || !temSpriteJogo(mega)) return null;
  const linha = estado.mega?.pedras?.find((x) => x.dex === meta.dex) ?? null;
  const item = linha?.itemId != null ? estado.itens.get(linha.itemId) : null;
  return {
    pokeId: mega.pokeId,
    nome: mega.name,
    // O nome do item manda quando ele existe (é o que está traduzido e o que a bolsa mostra);
    // o da tabela é a reserva para o cliente que abriu antes de o catálogo de itens chegar.
    pedra: { itemId: linha?.itemId ?? null, nome: item?.name ?? meta.pedra },
  };
}

/**
 * A linha "Mega Evolução" das duas fichas — a da espécie e a de um bicho concreto.
 *
 * O nome é CLICÁVEL pela mesma razão do destino de evolução logo acima: a mega é uma espécie de
 * verdade, com ficha própria na faixa #3000, e quem lê "vira Mega Venusaur" quer ver os números
 * dela antes de gastar dez fragmentos de boss.
 */
const linhaMegaDaFicha = (mega) =>
  mega
    ? fichaLinha(
        t('dex.megaEvolucao'),
        `<span class="fi-evo-linha"><button class="fi-evo-link" data-especie="${mega.pokeId}">${escapar(mega.nome)}</button>`
        + ` · ${htmlPedraEvolucao(mega.pedra)}</span>`,
      )
    : '';

const htmlPedraEvolucao = (pedra) =>
  pedra
    ? `<span class="fi-pedra-evo"><span class="fi-drop-ico" data-item="${pedra.itemId}"></span>${escapar(pedra.nome)}</span>`
    : '';

/**
 * Dados para o modal de evolução do pokémon ativo.
 *
 * `opcoes` é sempre uma lista, mesmo quando tem um item só: a cadeia pode abrir em vários
 * destinos (`evolucoes-ramificadas.mjs`) e quem desenha não deveria ter dois caminhos de
 * código para o mesmo assunto. Cada opção já vem com o motivo de estar travada, porque o
 * jogador precisa saber POR QUE o Sylveon está apagado — se é nível, se é a arte que falta,
 * ou se é o shiny dele que não tem para onde ir.
 */
function infoEvolucao(pk) {
  if (!pk) return null;
  if (pk.speciesId >= OUTLAND_POKE_MIN && pk.speciesId < OUTLAND_POKE_MAX) return null;
  const esp = estado.especies.get(pk.speciesId);
  if (!esp) return null;
  const destinos = destinosDeEvolucao(esp, (id) => estado.especies.get(id));
  if (!destinos.length) return null;
  const pedra = pk.shiny ? pedraShinyDaEspecie(esp) : pedraDaEspecie(esp);
  if (!pedra) return null;

  const qtd = estado.eu?.items?.[pedra.itemId] ?? 0;
  const opcoes = destinos.map((d) => {
    const lookShiny = pk.shiny ? (estado.shinyLooks[dexExibicao(d.pokeId)] ?? null) : null;
    // Shiny sem forma shiny no destino é recusado pelo servidor, e com razão: a evolução
    // devolveria um bicho de cor comum e o item mais raro do jogador não volta.
    const semShiny = !!pk.shiny && lookShiny == null;
    const faltaNv = pk.level < d.nivel;
    // Cada destino tem a PRÓPRIA pedra numa cadeia que abre — e a própria contagem no inventário.
    const pd = (pk.shiny ? pedraShinyDaEspecie(esp, d.especie) : pedraDaEspecie(esp, d.especie)) ?? pedra;
    const qtdPedra = estado.eu?.items?.[pd.itemId] ?? 0;
    return {
      pokeId: d.pokeId,
      nome: d.especie.name,
      nivel: d.nivel,
      looktype: lookShiny ?? d.especie.looktype,
      tipos: [d.especie.type1, d.especie.type2].filter(Boolean),
      temArte: d.temArte,
      semShiny,
      faltaNv,
      pedra: pd.nome,
      itemId: pd.itemId,
      qtdPedra,
      /** Dá para escolher: a arte existe, o nível bate e o shiny tem para onde ir. */
      disponivel: d.temArte && !semShiny && !faltaNv,
    };
  });

  return {
    shiny: !!pk.shiny,
    tipo: pedra.tipo ?? esp.type1,
    pedra: pedra.nome,
    itemId: pedra.itemId,
    qtd,
    /** As cadeias que abrem podem pedir uma pedra por destino — a tela mostra carta a carta. */
    pedraPorDestino: new Set(opcoes.map((o) => o.itemId)).size > 1,
    opcoes,
  };
}

/** O motivo de uma opção estar travada, na ordem em que importa. `null` quando está livre. */
function travaDaOpcao(op) {
  if (!op.temArte) return t('evol.semSprite');
  if (op.semShiny) return t('evol.semShiny');
  if (op.faltaNv) return t('evol.faltaNv', { n: num(op.nivel) });
  return null;
}

function rotuloEvolModal(nome, shiny) {
  const n = escapar(nome);
  return shiny ? t('evol.nomeShiny', { nome: n }) : n;
}

function pintarBotaoEvoluir(pk) {
  const btn = $('#btn-evoluir');
  if (!btn) return;
  const info = pk ? infoEvolucao(pk) : null;
  btn.classList.toggle('hidden', !info);
  if (!info) return;
  btn.textContent = t('painel.evoluir');
  btn.onclick = () => abrirModalEvolucao(pk, info);
}

/**
 * A MEGA do pokémon aberto, com tudo o que o modal precisa dizer. `null` quando não há mega.
 *
 * Espelha `infoEvolucao` de perto porque as perguntas do jogador são as mesmas ("dá para
 * fazer?", "com o quê?", "quanto eu tenho?"), e a diferença é justamente o que precisa ficar
 * visível: a pedra é a DAQUELA espécie e, se o bicho é shiny, é a pedra shiny.
 *
 * As travas repetem as do servidor (`pokemon.mega` em `sim.mjs`) — aqui para explicar, lá
 * para valer. Uma tela que promete o que o servidor recusa é pior do que um botão escondido.
 */
function infoMega(pk) {
  if (!pk) return null;
  const meta = megaDaEspecie(pk.speciesId);
  if (!meta) return null;
  const mega = estado.especies.get(MEGA_POKE_BASE + meta.dex);
  if (!mega || !temSpriteJogo(mega)) return null;

  const semShiny = !!pk.shiny && !megaTemShiny(meta);
  const cfg = estado.mega;
  const linha = cfg?.pedras?.find((x) => x.dex === meta.dex) ?? null;
  const itemId = pk.shiny ? linha?.itemShinyId : linha?.itemId;
  if (itemId == null && !semShiny) return null;

  const item = itemId != null ? estado.itens.get(itemId) : null;
  return {
    dex: meta.dex,
    shiny: !!pk.shiny,
    semShiny,
    megaPokeId: mega.pokeId,
    nome: mega.name,
    looktype: pk.shiny ? (estado.shinyLooks[mega.pokeId] ?? mega.looktype) : mega.looktype,
    tipos: [mega.type1, mega.type2].filter(Boolean),
    itemId,
    pedra: item?.name ?? (pk.shiny ? `Shiny ${meta.pedra}` : meta.pedra),
    qtd: itemId != null ? Number(estado.eu?.items?.[itemId] ?? 0) : 0,
  };
}

function pintarBotaoMega(pk) {
  const btn = $('#btn-mega');
  if (!btn) return;
  const info = pk ? infoMega(pk) : null;
  btn.classList.toggle('hidden', !info);
  if (!info) return;
  btn.textContent = t('painel.mega');
  btn.onclick = () => abrirModalMega(pk, info);
}

/**
 * O aviso antes de megaevoluir. Diz as três coisas que não dá para desfazer depois:
 * a espécie muda, os tipos podem mudar e o pokémon fica TRANCADO na venda.
 *
 * Em desenho: o bicho de hoje à esquerda, a mega à direita, a pedra em cima da seta. Sem a pedra
 * a seta para e a mega aparece apagada — dá para ver o que vem, e que ainda não veio.
 */
function abrirModalMega(pk, info) {
  const falta = info.semShiny
    ? t('mega.semShiny', { nome: info.nome })
    : (info.qtd < 1 ? t('mega.faltaPedra', { pedra: info.pedra }) : null);
  const pode = !falta;
  const comum = estado.especies.get(info.megaPokeId)?.looktype;
  confirmar({
    titulo: t('mega.titulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({
          arte: dlgArtePk(pk, 64),
          nome: nomePkHtml(pk),
          sub: dlgSeloShiny(info.shiny) + selosDeTipo(tiposDaFicha(pk)),
        })}
        ${dlgSeta({ item: info.itemId, qtd: '×1', travada: !pode })}
        ${dlgAtor({
          arte: dlgArteLt(info.looktype, 72, comum),
          nome: escapar(info.nome),
          sub: dlgSeloShiny(info.shiny) + selosDeTipo(info.tipos),
          classe: pode ? 'novo' : 'travado',
        })}`, 'mega')}
      ${info.itemId != null ? dlgReqs(dlgReq({
        arte: dlgReqItem(info.itemId),
        nome: escapar(info.pedra),
        sub: escapar(t('dlg.naBolsa')),
        tem: info.qtd,
        precisa: 1,
        ok: info.qtd >= 1,
      })) : ''}
      ${info.semShiny ? dlgAviso(escapar(t('mega.semShiny', { nome: info.nome }))) : ''}
      ${dlgSelos(
        dlgSelo('cadeado', escapar(t('dlg.semVolta')), 'perigo'),
        dlgSelo('estrela', escapar(t('dlg.vaiColecao')), 'ouro'),
        info.shiny ? dlgSelo('brilho', escapar(t('dlg.shinyFica')), 'rx') : '',
      )}`,
    rotuloSim: pode ? t('mega.confirmar') : t('confirmar.sim'),
    aoConfirmar: pode
      ? () => enviar({ t: 'pokemon.mega', pokemonId: pk.id })
      : () => toast(falta),
  });
}

function abrirModalEvolucao(pk, info) {
  if (info.opcoes.length > 1) return abrirModalEscolhaEvolucao(pk, info);

  const op = info.opcoes[0];
  const trava = travaDaOpcao(op);
  const faltaPedra = op.qtdPedra < 1;
  const pode = !trava && !faltaPedra;
  // Nível e pedra têm linha própria, com a marca de ok/falta. A trava que não é nenhum dos dois
  // (a arte que ainda não existe, o shiny sem forma shiny) não caberia ali e vira aviso.
  const outraTrava = trava && !op.faltaNv ? trava : null;
  confirmar({
    titulo: t('evol.titulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({
          arte: dlgArtePk(pk, 64),
          nome: nomePkHtml(pk),
          sub: dlgSeloShiny(info.shiny) + selosDeTipo(tiposDaFicha(pk)),
        })}
        ${dlgSeta({ item: op.itemId, qtd: '×1', rotulo: dlgNivel(op.nivel), travada: !pode })}
        ${dlgAtor({
          arte: dlgArteLt(op.looktype, 64, estado.especies.get(op.pokeId)?.looktype),
          nome: escapar(op.nome),
          sub: dlgSeloShiny(info.shiny) + selosDeTipo(op.tipos),
          classe: pode ? 'novo' : 'travado',
        })}`)}
      ${dlgReqs(
        dlgReq({
          arte: dlgReqItem(op.itemId),
          nome: escapar(op.pedra),
          sub: escapar(t('dlg.naBolsa')),
          tem: op.qtdPedra,
          precisa: 1,
          ok: !faltaPedra,
        }),
        dlgReq({
          arte: dlgIcone('subir', 22),
          nome: dlgNivel(op.nivel),
          sub: escapar(t('dlg.nivelMin')),
          valor: `<span class="tem">${dlgNivel(pk.level)}</span>`,
          ok: !op.faltaNv,
        }),
      )}
      ${outraTrava ? dlgAviso(escapar(outraTrava)) : ''}`,
    rotuloSim: pode ? t('evol.confirmar') : t('confirmar.sim'),
    aoConfirmar: pode
      ? () => enviar({ t: 'pokemon.evoluir', pokemonId: pk.id, alvoId: op.pokeId })
      : () => toast(trava ?? t('evol.faltaPedra', { pedra: op.pedra })),
  });
}

/** O destino marcado na tela de escolha. Vive fora dela porque o botão do rodapé é do modal. */
let evolucaoEscolhida = null;

/**
 * A tela de "qual evolução" — Eevee e as outras dez cadeias que abrem em mais de um destino.
 *
 * Segue o desenho do seletor de starter, e não por economia: é a MESMA pergunta ("escolha um
 * pokémon entre estes"), e responder duas vezes com telas diferentes é como o jogador aprende
 * que o jogo não tem regra. Carta com a arte animada, nome, tipos e o nível que ela pede.
 *
 * A primeira opção disponível já vem marcada — quase sempre a que o `evolvesToId` do catálogo
 * apontava. Quem só quer o de sempre aperta Evoluir e pronto; quem quer trocar, troca. Sem isso
 * o botão precisaria nascer desabilitado, e um botão morto no primeiro quadro é a forma mais
 * fácil de o jogador achar que a tela travou.
 */
function abrirModalEscolhaEvolucao(pk, info) {
  // Marcada de saída: a primeira que dá para escolher E cuja pedra o jogador tem. Com uma pedra
  // por destino, escolher o Sylveon quando falta a Heart Stone seria começar num beco.
  evolucaoEscolhida = (info.opcoes.find((o) => o.disponivel && o.qtdPedra >= 1)
    ?? info.opcoes.find((o) => o.disponivel))?.pokeId ?? null;

  const cartas = info.opcoes
    .map((o) => {
      const trava = travaDaOpcao(o);
      const marcada = o.pokeId === evolucaoEscolhida;
      const semPedra = !trava && o.qtdPedra < 1;
      return `
        <button type="button" class="evo-op${marcada ? ' on' : ''}${semPedra ? ' sem-pedra' : ''}"
                data-alvo="${o.pokeId}" ${trava ? 'disabled' : ''}>
          <span class="evo-op-arte" data-lt="${o.looktype}"></span>
          <span class="evo-op-nome">${escapar(o.nome)}</span>
          <span class="evo-op-tipos">${selosDeTipo(o.tipos)}</span>
          <span class="evo-op-nv">${escapar(t('evol.nvMin', { n: num(o.nivel) }))}</span>
          <span class="evo-op-pedra"><span class="fi-drop-ico" data-item="${o.itemId}"></span>${escapar(o.pedra)} <em>×${num(o.qtdPedra)}</em></span>
          ${trava ? `<span class="evo-op-trava">${escapar(trava)}</span>` : ''}
        </button>`;
    })
    .join('');

  const escolhida = () => info.opcoes.find((o) => o.pokeId === evolucaoEscolhida) ?? null;

  // O cabeçalho é o pokémon de HOJE, de frente para as cartas. Com pedra por destino ele não pode
  // anunciar UMA pedra (ela está em cada carta); com pedra única, ela vira a linha de requisito.
  confirmar({
    largura: 'larga',
    titulo: t('evol.titulo'),
    texto: `
      <div class="dlg-pergunta">
        <span class="dlg-pergunta-arte">${dlgArtePk(pk, 56)}</span>
        <div class="dlg-pergunta-txt">
          <p class="dlg-lead">${t('evol.qualVira', { de: rotuloEvolModal(pk.nome, info.shiny) })}</p>
          ${info.pedraPorDestino
            ? `<p class="dlg-sub">${t('evol.cadaPedra')}</p>`
            : dlgReqs(dlgReq({
              arte: dlgReqItem(info.itemId),
              nome: escapar(info.pedra),
              sub: escapar(t('dlg.naBolsa')),
              tem: info.qtd,
              precisa: 1,
              ok: info.qtd >= 1,
            }))}
        </div>
      </div>
      <div class="evo-ops">${cartas}</div>`,
    rotuloSim: t('evol.confirmar'),
    aoConfirmar: () => {
      const o = escolhida();
      if (!o) return toast(t('evol.nenhumaDisponivel'));
      if (o.qtdPedra < 1) return toast(t('evol.faltaPedra', { pedra: o.pedra }));
      enviar({ t: 'pokemon.evoluir', pokemonId: pk.id, alvoId: o.pokeId });
    },
  });

  // A arte entra por marcação (`data-lt`), como as bolas e os drops da ficha: assim as cartas
  // continuam sendo template de string, que é como o resto da tela é escrito.
  const corpo = $('#confirmar-texto');
  for (const el of corpo.querySelectorAll('.evo-op-arte')) {
    el.appendChild(spriteAnimado(Number(el.dataset.lt), 56, 3, null, null, { encaixar: true }));
  }
  for (const el of corpo.querySelectorAll('.evo-op [data-item]')) {
    if (el.dataset.item) el.appendChild(imgItem(Number(el.dataset.item), 18));
  }
  for (const b of corpo.querySelectorAll('.evo-op:not([disabled])')) {
    b.onclick = () => {
      for (const outra of corpo.querySelectorAll('.evo-op')) outra.classList.remove('on');
      b.classList.add('on');
      evolucaoEscolhida = Number(b.dataset.alvo);
    };
  }
}

// --------------------------------------------------------------- refino (+1)
//
// A bancada do "+1": o jogador troca pedras de evolução por um ponto permanente num
// stat-BASE do pokémon. A regra e a tabela de custo moram em `shared/refino-stats.mjs` (o
// mesmo arquivo que o servidor importa); os NÚMEROS chegam pelo `welcome`, em
// `estado.refino`, porque quem cobra é o servidor e um preço escrito à mão aqui viraria
// mentira no primeiro ajuste de balanceamento.
//
// Duas portas para a mesma ação, e é de propósito:
//
//   · o "+" do painel **Em campo**, ao lado do botão de chat, abre a bancada inteira do
//     pokémon que está lutando — é o caminho do dia a dia;
//   · o "+" de cada linha da seção **Stats-base** na ficha de um pokémon SEU, para refinar
//     um bicho do depot sem ter de colocá-lo em campo antes.
//
// As duas passam por `pedirRefino`, que é onde a confirmação e o envio acontecem uma vez só.

/** A tabela do welcome, com o mesmo padrão do módulo compartilhado como rede de segurança. */
const cfgRefino = () => ({
  stats: STATS_REFINAVEIS,
  custoBase: REFINO_CUSTO_BASE,
  expoente: REFINO_EXPOENTE,
  tetoTecnico: REFINO_TETO_TECNICO,
  passo: REFINO_PASSO,
  ...(estado.refino ?? {}),
});

/**
 * Pedras que refinam uma espécie — espelho de `pedrasDeRefino` no servidor.
 */
function pedrasDeRefinoDaEspecie(especie) {
  if (!especie) return [];
  return pedrasRefinoResolvidas(especie, estado.pedrasEvolucao);
}

/** A versão VIVA do pokémon: a ficha pode ter sido montada antes do último snapshot. */
const pokemonAtualizado = (pk) =>
  (estado.eu?.pokemons ?? []).find((p) => p.id === pk?.id) ?? pk;

/** `spAtk` → `SP.ATK` — o rótulo curto que o jogo usa em toda tela de stat. */
const rotuloStat = (stat) =>
  STATS_ORDEM.find(([k]) => k === stat)?.[1] ?? String(stat ?? '').toUpperCase();

/** Classe CSS da faixa de IV na ficha (pisca vermelho → verde claro). */
function classeIvStat(valor) {
  const v = Math.round(Number(valor) || 0);
  if (v <= 5) return 'iv-p1';
  if (v <= 10) return 'iv-p2';
  if (v <= 15) return 'iv-p3';
  if (v <= 24) return 'iv-p4';
  return 'iv-p5';
}

/** `{ hp, atk, … }` sempre completo, mesmo em ficha velha de anúncio. */
const refinoDe = (pk) => normalizarRefino(pk?.refino);

/** `+N` do selo — zero quando o bicho nunca foi refinado (e aí nada é desenhado). */
const refinoTotalDe = (pk) => Number(pk?.refinoTotal) || totalDoRefino(pk?.refino);

/** O selo `+N` que aparece ao lado do nome. Vazio quando não há refino nenhum. */
const seloRefino = (pk) => {
  const n = refinoTotalDe(pk);
  return n > 0
    ? `<span class="selo-refino" title="${escapar(t('refino.seloTitulo', { n: num(n) }))}">+${num(n)}</span>`
    : '';
};

// ------------------------------------------------------ a MEDALHA DE GUERRA
//
// Quantas vezes o bicho foi o "Pokémon da Guerra" — o destaque de dano da Guerra de Guilds do
// dia, o do card com a estrelinha na tela de análise. Uma por guerra no mundo inteiro, então
// um pokémon com duas já é raro e um com cinco é história.
//
// O número vem do SERVIDOR em `medalhasGuerra` (a coluna `medalhas_guerra`), e a ficha de
// anúncio do Mercado lê a linha viva a cada consulta — ver `completarFichaPokemon` lá. Ficha
// velha, de antes disto existir, vem sem o campo e cai em 0, que não desenha nada.

/** Quantas medalhas o bicho tem. 0 para quem nunca ganhou — e aí nada é desenhado. */
const medalhasDe = (pk) => Math.max(0, Number(pk?.medalhasGuerra) || 0);

// ------------------------------------------------------- o APELIDO da Name Tag
//
// O nome cosmético que a etiqueta de 15 💎 grava na linha do pokémon. Vem do servidor no campo
// `apelido`, e só em quem tem um — snapshot, ficha de anúncio e bolha de chat de antes disto
// existir chegam sem a chave, o que é o mesmo que "não tem".
//
// Toda tela que mostra o nome de um bicho passa por `nomeExibidoPokemon` (o módulo shared), e
// nunca por `pk.nome` direto. É o que garante que o apelido não fique "meio real": pago,
// aparece em todo lugar que o nome aparecia.
//
// A ESPÉCIE nunca some. Na ficha ela ganha uma linha logo abaixo do nome grande e continua na
// linha "Espécie" com o número da dex; no card do Mercado, no chip logo embaixo. Um apelido que
// escondesse a espécie transformaria uma compra cosmética numa armadilha de vitrine.

/** O apelido, já normalizado, ou `''` para quem não tem. */
const apelidoDe = (pk) => normalizarApelido(pk?.apelido);

/**
 * O nome de um pokémon NO MERCADO: a espécie primeiro e o apelido entre parênteses —
 * "Dragonite (Trovão)". Decisão do dono do jogo: quem compra procura pela espécie, e o apelido
 * vai junto para a conta do comprador (ele é da linha do pokémon), então aparece também.
 */
const nomeNoAnuncio = (pk) => (apelidoDe(pk)
  ? t('nametag.nomeAnuncio', { especie: pk?.nome ?? '', apelido: apelidoDe(pk) })
  : (pk?.nome ?? ''));

/**
 * O nome do bicho pronto para entrar num template de HTML — apelido quando há, JÁ escapado.
 *
 * O escape não é zelo redundante. `pk.nome` sempre veio do catálogo de espécies, que é nosso, e
 * por isso meia dúzia de templates o interpolavam cru. O apelido vem de um campo de texto de um
 * jogador e atravessa o Mercado até a tela de um desconhecido — é a primeira string de outra
 * pessoa a ocupar esse lugar. `validarApelido` já barra `<`, `>` e `&`, e mesmo assim toda tela
 * que mostra o nome passa por aqui: a regra de validação pode ser afrouxada um dia por um
 * motivo qualquer, e nesse dia nada deve depender dela para não virar injeção.
 */
const nomePkHtml = (pk) => escapar(nomeExibidoPokemon(pk) || '—');

/** "1 vez" / "3 vezes". O `t()` não tem plural automático, então a escolha é feita aqui. */
const vezesMedalha = (n) => t(n === 1 ? 'medalha.vez' : 'medalha.vezes', { n: num(n) });

/**
 * O selo 🎖 que aparece ao lado do nome no Mercado (e no Depot, na Coleção…).
 *
 * O contador só entra a partir da SEGUNDA: com uma medalha o "1" não informa nada que o
 * próprio símbolo já não diga, e rouba um pedaço do nome num card de 150 px. A contagem
 * exata está sempre no título e, por extenso, na ficha — que é onde quem está pensando em
 * pagar mais caro vai olhar de qualquer jeito.
 */
const seloMedalhaGuerra = (pk) => {
  const n = medalhasDe(pk);
  if (n <= 0) return '';
  const titulo = escapar(t('medalha.seloTitulo', { vezes: vezesMedalha(n) }));
  return `<span class="selo-medalha" title="${titulo}">🎖️${n > 1 ? `<i>${num(n)}</i>` : ''}</span>`;
};

// ------------------------------------------------------ os TROFÉUS DE CAMPEONATO
//
// Quantas vezes o bicho estava na equipe campeã de um Mundial ou de um Amador — os cinco do
// retrato congelado do campeão levam um cada, quando a edição fecha. Moram na linha do pokémon
// como a medalha (e vão junto numa venda); o servidor manda `trofeusMundial`/`trofeusAmador` só
// para quem tem algum, e ausente é 0.
//
// Os ícones são os troféus do pódio do Rank: o dourado do 1º lugar para o Mundial, o prateado do
// 2º para o Amador.

const TROFEUS_CAMPEONATO = [
  { tipo: 'mundial', campo: 'trofeusMundial', icone: '/assets/site/assets/ui/trofeu-1.png' },
  { tipo: 'amador', campo: 'trofeusAmador', icone: '/assets/site/assets/ui/trofeu-2.png' },
];

/** `[{ tipo, icone, n }]` só dos troféus que o bicho TEM — vazio para quase todos. */
const trofeusDe = (pk) => TROFEUS_CAMPEONATO
  .map((tr) => ({ ...tr, n: Math.max(0, Number(pk?.[tr.campo]) || 0) }))
  .filter((tr) => tr.n > 0);

const imgTrofeu = (tr, classe = 'ico-trofeu') => `<img class="${classe}" src="${tr.icone}" alt="">`;

/** O selo ao lado do nome no card do Mercado, pela mesma régua da medalha (número só a partir de 2). */
const seloTrofeus = (pk) => trofeusDe(pk).map((tr) => {
  const titulo = escapar(t('trofeu.seloTitulo', { trofeu: t(`trofeu.${tr.tipo}`), vezes: vezesMedalha(tr.n) }));
  return `<span class="selo-trofeu" title="${titulo}">${imgTrofeu(tr)}${tr.n > 1 ? `<i>${num(tr.n)}</i>` : ''}</span>`;
}).join('');

// ------------------------------------------------------ o TROFÉU e as MEDALHAS do jogador
//
// Quem sobe no pódio de um campeonato leva, no perfil, o troféu (1º) ou a medalha de 2º ou de 3º
// daquele campeonato, com o nome dele ao lado. Vem do servidor como `[{ id, tipo, numero, dia,
// lugar }]` — no snapshot (`campConquistas`, o perfil próprio) e na ficha dos outros (`conquistas`).

const ICONE_LUGAR_CAMPEONATO = {
  1: '/assets/site/assets/ui/trofeu-1.png',
  2: '/img/medalha-2.png',
  3: '/img/medalha-3.png',
};

/** As conquistas de campeonato, em fila, para o cabeçalho do perfil. Nada para quem não tem. */
function htmlConquistasCampeonato(lista) {
  const validas = (Array.isArray(lista) ? lista : []).filter((c) => ICONE_LUGAR_CAMPEONATO[c?.lugar]);
  if (!validas.length) return '';
  return `<div class="pf-conquistas">${validas.map((c) => `
    <span class="pf-conquista lugar-${c.lugar}" title="${escapar(t('camp.conquistaTitulo', {
      lugar: c.lugar,
      dia: c.dia ? dataDaNovidade(c.dia) : '',
    }))}">
      <img src="${ICONE_LUGAR_CAMPEONATO[c.lugar]}" alt="${c.lugar}º">
      <span>${escapar(nomeDoCampeonato(c))}</span>
    </span>`).join('')}</div>`;
}

/**
 * Tudo que as duas telas precisam saber sobre o refino de UM pokémon.
 *
 * `null` quando o refino não se aplica: sem espécie no catálogo ou sem pedra. `meu: false`
 * marca a ficha de anúncio, de placar e de chat — elas MOSTRAM o "+N" que o bicho já tem,
 * mas não ganham o botão de comprar.
 */
function infoRefino(pk) {
  if (!pk) return null;
  const vivo = pokemonAtualizado(pk);
  const esp = estado.especies.get(vivo.speciesId);
  if (!esp) return null;
  const pedras = pedrasDeRefinoDaEspecie(esp);
  if (!pedras.length) return null;

  const cfg = cfgRefino();
  const bonus = refinoDe(vivo);
  const qtdPedra = saldoPedrasRefino(estado.eu?.items ?? {}, pedras);
  const pedra = pedras[0];

  return {
    pk: vivo,
    especie: esp,
    pedra,
    pedras,
    qtdPedra,
    rotuloPedras: rotuloPedrasRefino(pedras),
    meu: pokemonNaMinhaMao(pk),
    total: refinoTotalDe(vivo),
    // Quantas pedras já estão dentro deste bicho. Não existe teto de refino (a cúbica é que
    // segura o ritmo), então este número é o que substitui a antiga barra "x de 10": ele diz
    // o tamanho do investimento sem prometer um fim que não existe.
    investido: investidoNoRefino(bonus),
    linhas: cfg.stats.map((stat) => {
      const base = esp[CAMPO_BASE[stat]] ?? 0;
      const nivel = bonus[stat] ?? 0;
      const noTeto = nivel >= cfg.tetoTecnico;
      const custo = custoDoRefino(nivel);
      return {
        stat,
        rotulo: rotuloStat(stat),
        base,
        nivel,
        atual: base + nivel * cfg.passo,
        real: vivo.stats?.[stat] ?? null,
        investido: custoTotalDoRefino(nivel),
        noTeto,
        custo,
        podePagar: !noTeto && qtdPedra >= custo,
      };
    }),
  };
}

/**
 * Uma linha da bancada. É a MESMA marcação na ficha e no modal — o `+` só entra quando o
 * pokémon é seu, e é isso que separa "ver a ficha de um anúncio" de "mexer no seu bicho".
 *
 * A barra usa 200 como referência, igual à da Pokédex (`corpoDaEspecie`), para as duas telas
 * darem a mesma leitura de "isso é um stat alto".
 */
function linhaRefino(l, { comBotao, pedra, pedras, rotuloPedras }) {
  const rotulo = rotuloPedras ?? pedra?.nome ?? '';
  const ganho = l.nivel > 0
    ? `<em class="fi-refino-mais" title="${escapar(t('refino.grauTitulo', { n: num(l.nivel), pedras: num(l.investido), pedra: rotulo }))}">+${num(l.nivel)}</em>`
    : '<em class="fi-refino-mais zero">·</em>';
  const titulo = l.noTeto
    ? t('refino.noTeto')
    : (pedras?.length > 1
      ? t('refino.custoTituloMix', { n: num(l.custo), pedras: rotulo })
      : t('refino.custoTitulo', { n: num(l.custo), pedra: rotulo }));
  const botao = comBotao
    ? `<button type="button" class="fi-refino-bt${l.podePagar ? '' : ' sem-pedra'}" data-stat="${l.stat}"${l.noTeto ? ' disabled' : ''} title="${escapar(titulo)}">${
        l.noTeto ? t('refino.max') : '+1'
      }</button>`
    : '';
  return `
    <div class="fi-stat fi-stat-refino${l.nivel > 0 ? ' tem-refino' : ''}">
      <span class="fi-stat-nome">${l.rotulo}</span>
      <span class="fi-stat-barra"><i style="width:${Math.min(100, (l.atual / 200) * 100)}%"></i></span>
      <b class="fi-stat-num">${num(l.atual)}</b>
      ${ganho}
      ${botao}
    </div>`;
}

/**
 * A linha do SPD, sem "+" e sem barra de compra.
 *
 * Ela aparece porque esconder um dos seis stats faria o jogador procurar o que sumiu; e ela
 * não tem botão porque `stats.speed` **não entra em combate nenhum** — quem decide cadência
 * de ataque é o IV de speed, fixo no nascimento (ver `cooldownComSpeed` no servidor). Vender
 * "+1 SPD" seria vender um número que não faz nada, então a linha diz isso em vez de mentir.
 *
 * O "fixo" é um BOTÃO, e não um rótulo, por causa do celular: a explicação inteira morava no
 * `title` da linha, e num aparelho de toque `title` não existe. A única linha da bancada que
 * não tem o "+1" era também a única cuja razão de ser não tinha como ser lida — que é
 * exatamente a pergunta que ela levanta. Tocando, o toast responde; no desktop o `title`
 * continua respondendo antes do clique.
 */
const linhaBaseSpeed = (especie) => `
  <div class="fi-stat fi-stat-refino fi-stat-fixo" title="${escapar(t('refino.spdTitulo'))}">
    <span class="fi-stat-nome">SPD</span>
    <span class="fi-stat-barra"><i style="width:${Math.min(100, ((especie?.baseSpeed ?? 0) / 200) * 100)}%"></i></span>
    <b class="fi-stat-num">${num(especie?.baseSpeed ?? 0)}</b>
    <em class="fi-refino-mais zero"></em>
    <button type="button" class="fi-refino-fixo" title="${escapar(t('refino.spdTitulo'))}">${t('refino.spdCurto')}</button>
  </div>`;

/**
 * O saldo de pedras — qual é e quantas o jogador tem.
 *
 * Subiu do rodapé para o TOPO das duas telas quando o preço saiu dos botões: com o custo
 * escondido até a confirmação, quanto se tem na bolsa passou a ser o único número da tela que
 * responde "dá para eu comprar alguma coisa aqui?". Enterrado embaixo da tabela, ele obrigava
 * a ler de baixo para cima.
 */
const chipPedra = (info) => {
  if (info.pedras?.length > 1) {
    const linhas = info.pedras
      .map((p) => {
        const q = estado.eu?.items?.[p.itemId] ?? 0;
        return `<span class="fi-refino-pedra-linha"><span class="fi-drop-ico" data-item="${p.itemId}"></span>${escapar(p.nome)} <b>×${num(q)}</b></span>`;
      })
      .join('');
    return `<p class="fi-refino-pedra fi-refino-pedras-mix">${linhas}<span class="fi-refino-pedra-total">${t('refino.totalPedras', { n: num(info.qtdPedra) })}</span></p>`;
  }
  return `<p class="fi-refino-pedra"><span class="fi-drop-ico" data-item="${info.pedra.itemId}"></span>${escapar(info.pedra.nome)} <b>×${num(info.qtdPedra)}</b></p>`;
};

/**
 * Pede um degrau. Confirma primeiro — são centenas de pedras e não há desfazer.
 *
 * A conferência de saldo é repetida aqui (a linha já pinta o botão de "sem pedra") porque o
 * clique pode chegar depois de o jogador ter gasto as pedras noutra aba: recusar com um
 * toast é melhor que mandar ao servidor um pedido que ele vai negar.
 */
function pedirRefino(pk, stat) {
  const info = infoRefino(pk);
  if (!info?.meu) return;
  const l = info.linhas.find((x) => x.stat === stat);
  if (!l) return;
  if (l.noTeto) return toast(t('refino.noTeto'));
  // SEM pedra a caixa abre do mesmo jeito: é nela que o jogador vê quanto o degrau custa e
  // quanto falta de cada pedra — um toast de "faltam 500" não diz de qual. O que muda é que o
  // Refinar nasce desligado, a seta não anda e o pokémon fica apagado.
  const pode = l.podePagar;
  const consumo = pode ? simularConsumoPedrasRefino(estado.eu?.items ?? {}, info.pedras, l.custo) : null;
  const gastoDe = new Map((consumo ?? []).map((c) => [c.itemId, c.qtd]));
  const resta = info.qtdPedra - l.custo;
  const passo = cfgRefino().passo;
  const mix = info.pedras.length > 1;
  const subSaldo = escapar(pode ? t('refino.sobram', { n: num(resta) }) : t('refino.faltamN', { n: num(l.custo - info.qtdPedra) }));
  // DUAL-TYPE COM PEDRA SUFICIENTE: o jogador ESCOLHE quanto sai de cada pedra. Cada linha ganha o
  // contador − / campo / + / máx do Mercado; mexer numa faz as OUTRAS completarem o custo, maior pilha
  // primeiro (`completarUsoPedrasRefino`), e a caixa abre com a proposta de sempre (a mesma do
  // servidor sem escolha). A mistura vai no pedido e o servidor confere tudo de novo
  // (`validarUsoPedrasRefino`, com o inventário e o custo DELE).
  const escolhe = mix && pode;
  const itensAgora = () => estado.eu?.items ?? {};
  const saldoDe = (p) => Math.max(0, Math.floor(Number(itensAgora()[p.itemId]) || 0));
  let uso = escolhe ? completarUsoPedrasRefino(itensAgora(), info.pedras, l.custo) : null;
  // ± de um passo "redondo" do tamanho do degrau: 500 → 10, 3.500 → 100, 18.500 → 1.000.
  const passoQtd = 10 ** Math.max(0, Math.floor(Math.log10(Math.max(1, l.custo))) - 1);
  const contadorPedra = (p) => `
    <span class="mk-qtd rf-qtd" data-rf-item="${p.itemId}">
      <button type="button" class="mk-passo" data-passo="-1" aria-label="−${num(passoQtd)}">−</button>
      <input type="number" inputmode="numeric" min="0" max="${Math.min(saldoDe(p), l.custo)}" step="1" value="${uso[p.itemId] ?? 0}"
        aria-label="${escapar(p.nome)}">
      <button type="button" class="mk-passo" data-passo="1" aria-label="+${num(passoQtd)}">+</button>
      <button type="button" class="mk-passo rf-max" title="${escapar(t('refino.maxPedraTitulo'))}">${escapar(t('mk.max'))}</button>
    </span>`;
  // A linha do TOTAL, refeita a cada mudança: a soma escolhida contra o custo, com a marca de ok/falta.
  const linhaTotal = () => {
    const soma = escolhe ? Object.values(uso).reduce((s, q) => s + q, 0) : info.qtdPedra;
    const fecha = escolhe ? soma === l.custo : pode;
    return dlgReq({
      arte: `<span data-rf-total>${dlgIcone('soma', 20)}</span>`,
      nome: escapar(t('refino.totalAceito')),
      sub: escolhe
        ? escapar(fecha ? t('refino.sobram', { n: num(resta) }) : t('refino.faltamN', { n: num(l.custo - soma) }))
        : subSaldo,
      tem: soma,
      precisa: l.custo,
      ok: fecha,
    });
  };
  // Uma linha POR PEDRA aceita, uma embaixo da outra, com o saldo de cada uma. No dual-type o
  // jogador quer saber de qual das duas sai o pagamento (e, com pedra para pagar, escolhe), e a soma
  // vira a linha de baixo, com a marca de ok/falta.
  const reqs = escolhe
    ? [
      ...info.pedras.map((p) => dlgReq({
        arte: dlgReqItem(p.itemId),
        nome: escapar(p.nome),
        sub: `<span data-rf-fica="${p.itemId}">${escapar(t('refino.sobram', { n: num(saldoDe(p) - (uso[p.itemId] ?? 0)) }))}</span>`,
        valor: contadorPedra(p),
      })),
      linhaTotal(),
    ]
    : mix
    ? [
      ...info.pedras.map((p) => {
        const gasta = gastoDe.get(p.itemId) ?? 0;
        return dlgReq({
          arte: dlgReqItem(p.itemId),
          nome: escapar(p.nome),
          sub: escapar(gasta ? t('refino.vaiGastarN', { n: num(gasta) }) : t('dlg.naBolsa')),
          valor: `<span class="tem">${num(Math.max(0, Math.floor(Number(estado.eu?.items?.[p.itemId]) || 0)))}</span>`,
        });
      }),
      dlgReq({
        arte: dlgIcone('soma', 20),
        nome: escapar(t('refino.totalAceito')),
        sub: subSaldo,
        tem: info.qtdPedra,
        precisa: l.custo,
        ok: pode,
      }),
    ]
    : [dlgReq({
      arte: dlgReqItem(info.pedra.itemId),
      nome: escapar(info.pedra.nome),
      sub: subSaldo,
      tem: info.qtdPedra,
      precisa: l.custo,
      ok: pode,
    })];
  // A tela de "subiu um stat" dos jogos: o pokémon no palco com o "+1 ATK" subindo sobre ele, e
  // embaixo o número de hoje virando o de amanhã. As pedras são as linhas de requisito — com o
  // que sobra na bolsa, que é a conta que o jogador faz antes de clicar.
  confirmar({
    titulo: t('refino.confirmarTitulo', { nome: info.pk.nome ?? '—' }),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({
          arte: dlgArtePk(info.pk, 72),
          nome: nomePkHtml(info.pk),
          sub: dlgSeloShiny(info.pk.shiny) + dlgNivel(info.pk.level),
          classe: pode ? 'novo' : 'travado',
        })}
        ${pode ? `<span class="dlg-sobe-txt">+${num(passo)} ${escapar(l.rotulo)}</span>` : ''}`, 'ouro')}
      <div class="dlg-stat">
        <span class="dlg-stat-rot">${escapar(l.rotulo)}<small>${escapar(t('refino.base'))}</small></span>
        <span class="dlg-stat-de">${num(l.atual)}</span>
        ${dlgSeta({ travada: !pode })}
        <span class="dlg-stat-para">${num(l.atual + passo)}</span>
        <span class="dlg-stat-grau" title="${escapar(t('refino.grauSelo'))}">+${num(l.nivel)} → <b>+${num(l.nivel + 1)}</b></span>
      </div>
      ${dlgReqs(...reqs)}
      ${dlgSelos(
        dlgSelo('cadeado', escapar(t('dlg.permanente')), 'perigo'),
        // O TOTAL que fica dentro do stat, e não o custo do degrau: com o "antes → depois" escrito,
        // "4.000" ao lado de um custo de 3.500 não se passa pelo preço (era o que o selo sem o
        // "500 →" parecia dizer).
        dlgSelo('moedas', escapar(t('refino.investidoSelo', {
          stat: l.rotulo, de: num(l.investido), para: num(l.investido + l.custo),
        })), 'ouro'),
      )}`,
    rotuloSim: t('refino.confirmar'),
    // O botão nasce desligado sem pedra suficiente (o `confirmar` religa todo botão ao abrir).
    montar: () => {
      $('#confirmar-sim').disabled = !pode;
      if (escolhe) ligarMisturaRefino();
    },
    aoConfirmar: () => {
      // A conferência se repete no clique: o saldo pode ter mudado com a caixa aberta (venda
      // noutra aba, outra bancada). Quem decide de verdade é o `pokemon.refinar` do servidor.
      const agora = infoRefino(pk);
      const linha = agora?.linhas.find((x) => x.stat === stat);
      if (!linha?.podePagar) {
        return toast(t('refino.faltaPedraMix', {
          n: num(Math.max(0, (linha?.custo ?? l.custo) - (agora?.qtdPedra ?? 0))),
          pedras: info.rotuloPedras,
        }));
      }
      if (!escolhe) return enviar({ t: 'pokemon.refinar', pokemonId: info.pk.id, stat });
      // A mistura escolhida, conferida contra a bolsa e o custo de AGORA (outro degrau noutra aba
      // mudaria o custo; uma venda, o saldo). Fora disso, a caixa não manda nada.
      if (!validarUsoPedrasRefino(itensAgora(), info.pedras, linha.custo, uso).ok) return toast(t('refino.misturaMudou'));
      enviar({ t: 'pokemon.refinar', pokemonId: info.pk.id, stat, uso: { ...uso } });
    },
  });

  /** Liga os contadores das pedras: cada mudança refaz a mistura, as linhas e o botão. */
  function ligarMisturaRefino() {
    const caixa = $('#confirmar');
    if (!caixa) return;
    const repintar = (editado = null) => {
      for (const p of info.pedras) {
        const campo = caixa.querySelector(`.rf-qtd[data-rf-item="${p.itemId}"] input`);
        // O campo que a pessoa está digitando não é reescrito (o cursor pularia); ele é acertado no blur.
        if (campo && campo !== editado) campo.value = String(uso[p.itemId] ?? 0);
        const fica = caixa.querySelector(`[data-rf-fica="${p.itemId}"]`);
        if (fica) fica.textContent = t('refino.sobram', { n: num(saldoDe(p) - (uso[p.itemId] ?? 0)) });
      }
      const total = caixa.querySelector('[data-rf-total]')?.closest('.dlg-req');
      if (total) total.outerHTML = linhaTotal();
      const sim = $('#confirmar-sim');
      if (sim) sim.disabled = !validarUsoPedrasRefino(itensAgora(), info.pedras, l.custo, uso).ok;
    };
    const fixar = (itemId, qtd, editado = null) => {
      uso = completarUsoPedrasRefino(itensAgora(), info.pedras, l.custo, itemId, qtd);
      repintar(editado);
    };
    for (const cx of caixa.querySelectorAll('.rf-qtd')) {
      const itemId = cx.dataset.rfItem;
      const campo = cx.querySelector('input');
      campo.addEventListener('input', () => fixar(itemId, Number(campo.value), campo));
      campo.addEventListener('blur', () => repintar());
      cx.addEventListener('click', (ev) => {
        const b = ev.target.closest('.mk-passo');
        if (!b) return;
        const p = info.pedras.find((x) => String(x.itemId) === itemId);
        const atual = uso[itemId] ?? 0;
        fixar(itemId, b.classList.contains('rf-max') ? Math.min(saldoDe(p), l.custo) : atual + Number(b.dataset.passo) * passoQtd);
      });
    }
  }
}

/** Liga os "+" de um trecho de HTML já montado (ficha ou modal). */
function ligarBotoesRefino(raiz, pk) {
  if (!raiz) return;
  for (const el of raiz.querySelectorAll('.fi-refino-bt')) {
    el.onclick = (ev) => {
      ev.stopPropagation();
      pedirRefino(pk, el.dataset.stat);
    };
  }
  // O "fixo" do SPD: no toque não há `title`, então ele responde ao clique (ver
  // `linhaBaseSpeed`). Vale na ficha alheia também — lá não há "+1" nenhum para ligar, mas a
  // pergunta "por que este não tem botão?" é a mesma.
  for (const el of raiz.querySelectorAll('.fi-refino-fixo')) {
    el.onclick = (ev) => {
      ev.stopPropagation();
      toast(t('refino.spdToast'));
    };
  }
}

// ------------------------------------------------------------- o modal do "+"

/** Qual pokémon a bancada está mostrando. `null` = fechada. */
let refinoPkId = null;
/** Assinatura do último desenho — evita remontar o modal duas vezes por segundo à toa. */
let refinoAssinatura = '';

function fecharRefino() {
  refinoPkId = null;
  refinoAssinatura = '';
  $('#refino')?.classList.add('hidden');
}

function abrirRefino(pk) {
  const info = infoRefino(pk);
  if (!info) return toast(t('refino.indisponivel'));
  if (!info.meu) return;
  refinoPkId = info.pk.id;
  refinoAssinatura = '';
  $('#refino').classList.remove('hidden');
  desenharRefino();
}

/**
 * (Re)desenha a bancada. Chamado ao abrir e a cada snapshot, mas só refaz o HTML quando algo
 * que ele mostra mudou de verdade — senão os ícones de item seriam recriados duas vezes por
 * segundo enquanto a hunt roda por trás, e o sprite piscaria junto.
 */
function desenharRefino() {
  if (refinoPkId == null) return;
  const info = infoRefino({ id: refinoPkId });
  if (!info?.meu) return fecharRefino();

  const assinatura = `${info.qtdPedra}|${info.linhas.map((l) => `${l.nivel}:${l.real}`).join(',')}`;
  if (assinatura === refinoAssinatura) return;
  refinoAssinatura = assinatura;

  $('#refino-titulo').innerHTML = `${escapar(info.pk.nome ?? '—')} ${seloRefino(info.pk)}`;
  const corpo = $('#refino-corpo');
  corpo.innerHTML = `
    <div class="rf-topo">
      <div class="rf-arte" id="rf-arte"></div>
      <div class="rf-cabeca">
        <p class="rf-explica">${t('refino.explica', { base: num(cfgRefino().custoBase) })}</p>
        <div class="rf-chips">
          ${chipPedra(info)}
          ${info.investido > 0 ? `<p class="fi-refino-pedra rf-investido">${t('refino.investido')} <b>${num(info.investido)}</b></p>` : ''}
        </div>
      </div>
    </div>
    <div class="fi-stats fi-stats-refino">
      ${info.linhas.map((l) => linhaRefino(l, {
        comBotao: true,
        pedra: info.pedra,
        pedras: info.pedras,
        rotuloPedras: info.rotuloPedras,
      })).join('')}
      ${linhaBaseSpeed(info.especie)}
    </div>
    <p class="fi-nota">${t('refino.nota', { base: num(cfgRefino().custoBase) })}</p>`;

  corpo.querySelector('#rf-arte')?.appendChild(spritePokemon(info.pk, 64));
  for (const el of corpo.querySelectorAll('[data-item]')) {
    if (el.dataset.item) el.appendChild(imgItem(Number(el.dataset.item), 20));
  }
  ligarBotoesRefino(corpo, info.pk);
}

/**
 * Põe a bancada e a ficha em dia depois de uma compra. Roda a cada snapshot.
 *
 * A ficha é remontada só quando o refino DAQUELE pokémon mudou — remontar a cada snapshot
 * jogaria a rolagem de volta ao topo duas vezes por segundo, que é o mesmo motivo pelo qual
 * o Market e a Shop não entram no switch de `aplicarEstado`.
 */
function atualizarTelasDeRefino() {
  desenharRefino();
  if (!fichaPokemonAberto?.id) return;
  const vivo = pokemonAtualizado(fichaPokemonAberto);
  if (vivo === fichaPokemonAberto) return;
  // O NÍVEL entra na mesma conta desde o botão "Reduzir o nível": ele muda stats, XP e o
  // próprio estado do botão, e sem esta linha a ficha continuaria mostrando o nível de antes
  // até o jogador fechá-la e abrir de novo.
  const mudou = refinoTotalDe(vivo) !== refinoTotalDe(fichaPokemonAberto)
    || vivo.level !== fichaPokemonAberto.level;
  if (!mudou) return;
  reabrirFichaDoPokemon();
}

/** O "+" do painel Em campo: some quando não há pokémon em campo ou quando ele não é seu. */
function pintarBotaoRefino(pk) {
  const btn = $('#btn-refino-pk');
  if (!btn) return;
  const info = pk ? infoRefino(pk) : null;
  const visivel = !!info?.meu;
  btn.classList.toggle('hidden', !visivel);
  btn.disabled = !visivel;
  if (visivel) {
    btn.onclick = (ev) => {
      ev.stopPropagation();
      abrirRefino(info.pk);
    };
  }
}

$('#refino-fechar')?.addEventListener('click', (ev) => {
  ev.stopPropagation();
  fecharRefino();
});
$('#refino')?.addEventListener('click', (ev) => {
  if (ev.target !== $('#refino')) return;
  ev.stopPropagation();
  fecharRefino();
});

/** Tamanho da equipe. Precisa bater com MAX_EQUIPE no servidor, que é quem decide. */
const MAX_EQUIPE = 5;

function proximoSlotLivre() {
  const usados = new Set(estado.eu.pokemons.map((p) => p.slot).filter((s) => s != null));
  for (let i = 0; i < MAX_EQUIPE; i++) if (!usados.has(i)) return i;
  return null;
}

/**
 * A fração do nível já andada, e os dois números que a explicam.
 *
 * `xpNivel` e `xpProximo` vêm prontos do servidor em TODO pokémon (`pokemonParaCliente`), e
 * não só no que está em campo — é o que torna a barra da Equipe uma conta local, sem pedir
 * nada a mais. O `max(1, …)` é o mesmo cuidado da ficha: par nível/XP desencontrado não pode
 * virar divisão por zero nem barra negativa.
 */
function progressoDeXp(p) {
  if (p?.xp == null || p.xpNivel == null || p.xpProximo == null) return null;
  const dentro = Math.max(0, p.xp - p.xpNivel);
  const faixa = Math.max(1, p.xpProximo - p.xpNivel);
  return { dentro, faixa, frac: Math.min(1, dentro / faixa) };
}

/**
 * Uma linha de pokémon (barra lateral e Depot).
 *
 * `paraColecao` pendura a setinha da Coleção (`'colecao'` na aba Depot, `'depot'` na aba
 * Coleção). `colecao` é o Set que o chamador já montou; com ele, a linha de quem está na EQUIPE
 * ganha a ★ quando o pokémon é da Coleção — é para lá que ele vai quando sair do time.
 */
function linhaPokemon(p, ativoId, { mover = false, detalhes = false, selos = false, xp = false, colecao = null, paraColecao = null } = {}) {
  const el = document.createElement('div');
  const nvTreinador = estado.eu?.level ?? 0;
  const bloqueado = p.slot != null && !podeUsarPokemon(nvTreinador, p);
  // O brilho do shiny só nas listas da EQUIPE (as que têm XP): no Depot é uma coleção inteira,
  // e uma parede de shinys respirando ao mesmo tempo viraria ruído em vez de prêmio.
  const brilho = !!p.shiny && xp;
  el.className = 'poke-linha' + (detalhes ? ' depot-linha' : '') + (p.id === ativoId ? ' ativo' : '') + (bloqueado ? ' pl-bloqueado' : '') + (brilho ? ' brilho-shiny' : '');
  el.dataset.id = p.id;
  const btnMover = !mover
    ? ''
    : p.slot != null
      ? `<button class="pl-mover" type="button" data-para="depot" title="${t('painel.mandarDepot')}">→</button>`
      : `<button class="pl-mover" type="button" data-para="equipe" title="${t('painel.trazerEquipe')}">←</button>`;
  const dicaColecao = paraColecao ? t(paraColecao === 'depot' ? 'colecao.devolver' : 'colecao.enviar') : '';
  const btnColecao = paraColecao
    ? `<button class="pl-colecao${paraColecao === 'depot' ? ' volta' : ''}" type="button" title="${escapar(dicaColecao)}"
        aria-label="${escapar(dicaColecao)}"${colecaoPendente.has(p.id) ? ' disabled' : ''}>${SETA_COLECAO(paraColecao)}</button>`
    : '';
  const naColecaoEquipe = p.slot != null && (colecao ? colecao.has(p.id) : naColecaoCliente(p.id));
  const marcaEquipe = naColecaoEquipe
    ? ` <span class="pl-colecao-marca" title="${escapar(t('colecao.marcaEquipe'))}">★</span>`
    : '';
  // Os tipos e o ⚔ ficam na meta; qualidade, IV, nota e potência descem para a MESMA fileira
  // de selos dos cards do Market e do Mercado — antes cada um mostrava um conjunto diferente
  // dos mesmos quatro números, com a potência ainda por cima num canto só dela.
  const meta = detalhes
    ? `<div class="depot-meta">${selosDeTipo(p.tipos)} · ${t('painel.poder')} ${num(p.poder)}</div>`
    : '';
  const fileira = detalhes || selos ? selosAtributos(p, { compacto: true }) : '';
  const nome = `<div class="pl-nome">${p.shiny ? prefixoShiny() : ''}${nomePkHtml(p)} ${selosTm(p)} <span class="pl-lv">${t('painel.nivelCurto')}${p.level}</span>${marcaEquipe}</div>`;
  // No Depot a fileira fica onde sempre esteve: fita própria, embaixo da meta. Na EQUIPE da
  // barra lateral não existe meta, e uma linha só para os selos comeria altura de uma lista
  // que precisa caber cinco pokémon — então lá ela sobe para JUNTO do nome, e o `flex-wrap`
  // do `.pl-cabeca` a desce inteira quando o nome comprido não deixa espaço ao lado.
  const cabeca = detalhes
    ? `${nome}${meta}${fileira}`
    : `<div class="pl-cabeca">${nome}${fileira}</div>`;
  // A barra de XP só entra nas listas da EQUIPE. No Depot ela seria um enfeite que mente:
  // pokémon guardado não ganha XP nenhum (o posto de XP Share se esvazia sozinho quando o
  // bicho vai para lá — ver `limparXpShareInvalido` no servidor), então a barra ficaria
  // parada para sempre prometendo um avanço que não acontece.
  const px = xp ? progressoDeXp(p) : null;
  const barraXp = px
    ? `<div class="mini-xp" title="${escapar(`${num(px.dentro)} / ${num(px.faixa)} ${t('painel.xp')}`)}"><i style="width:${px.frac * 100}%"></i></div>`
    : '';
  el.innerHTML = `${brilho ? brilhoShiny() : ''}
    <div class="pl-info">
      ${cabeca}
      <div class="mini-hp ${p.hp / p.maxHp < 0.35 ? 'baixo' : ''}"><i style="width:${(p.hp / p.maxHp) * 100}%"></i></div>
      ${barraXp}
    </div>
    <div class="pl-acoes">
      <button class="pl-ficha" type="button" title="${t('cm.verFicha')}">i</button>
      ${btnColecao}
      ${btnMover}
    </div>`;
  el.prepend(spritePokemon(p, detalhes ? 32 : 28));
  // Apelidado, a ESPÉCIE abre o balão: a linha da lista só tem largura para um nome, e quem
  // batizou três Eevee precisa de alguma forma de lembrar qual é qual sem abrir ficha.
  el.title =
    (apelidoDe(p) ? `${p.nome}\n` : '') +
    `${t('painel.poder')} ${p.poder} · ${t('painel.qualidade')} ${p.quality} · ${rotuloPotencia(Number(p.potencia) || 1)} · ${p.tipos.join('/')}\n` +
    (mover && p.slot == null
        ? t('painel.cliqueTrazer')
        : t('painel.cliqueAtivar'));

  el.querySelector('.pl-ficha')?.addEventListener('click', (ev) => {
    ev.stopPropagation();
    abrirFichaDoPokemon(p);
  });

  el.querySelector('.pl-colecao')?.addEventListener('click', (ev) => {
    ev.stopPropagation();
    moverColecao(p.id, paraColecao);
  });

  // o botão de mover não pode disparar o clique da linha (que colocaria em campo)
  el.querySelector('.pl-mover')?.addEventListener('click', (ev) => {
    ev.stopPropagation();
    if (p.slot != null) return enviar({ t: 'team.move', pokemonId: p.id, slot: null });
    const slot = proximoSlotLivre();
    if (slot == null) return toast(t('ev.equipeCheia', { max: MAX_EQUIPE }));
    enviar({ t: 'team.move', pokemonId: p.id, slot });
  });

  el.onclick = () => {
    if (p.slot != null && !podeUsarPokemon(nvTreinador, p)) {
      return toast(t('ev.pokemonRecusaNivel', { nome: p.nome, nivel: p.level, min: nivelMinimoTreinador(p.level), seu: nvTreinador }));
    }
    if (p.slot != null) {
      // A pausa da recarga é adiantada no clique: o pokémon que entra ataca 300 ms depois, e o
      // snapshot que confirma a troca pode levar até 500 ms. Sem isto, esse primeiro golpe era
      // creditado ao relógio do pokémon anterior — e o do novo acendia como pronto. Se o
      // servidor recusar a troca, o `activeId` do snapshot seguinte desfaz.
      sincronizarCooldownsDaUI(p.id);
      enviar({ t: 'team.active', pokemonId: p.id });
      return;
    }
    if (!mover) return;
    const slot = proximoSlotLivre();
    if (slot == null) return toast(t('ev.equipeCheia', { max: MAX_EQUIPE }));
    enviar({ t: 'team.move', pokemonId: p.id, slot });
  };
  return el;
}

function pintarTime(e) {
  const time = e.pokemons.filter((p) => p.slot != null).sort((a, b) => a.slot - b.slot);

  $('#time-cnt').textContent = `${time.length}/${MAX_EQUIPE}`;

  const t = $('#time');
  t.innerHTML = '';
  for (const p of time) t.appendChild(linhaPokemon(p, e.activeId, { selos: true, xp: true }));
  if (!time.length) t.innerHTML = '<div class="vazio-msg">nenhum pokémon na equipe</div>';

  if (!$('#centro-depot-modal').classList.contains('hidden')) montarDepotModal();
}

// -------------------------------------------------------------- inventário (modal Bolsa)
// (funções do modal abaixo, junto do Market)

/**
 * Os elementos das duas áreas ANDÁVEIS de Cerulean: a praça e a casa do jogador.
 *
 * As duas dividem o direcional e o teclado (as duas são "área social andável", que é o que a
 * bandeira `centro: true` do pacote quer dizer), e diferem nos botões: na praça são a Joy, o
 * Professor e o Depot; em casa só a porta de saída (canto direito).
 */
function pintarCentro(e) {
  const emCasa = !!e.casa?.dentro;
  syncTreinosDaCasa(e);
  // Na praça, e não em casa: os três NPCs de Cerulean não existem dentro da sala de estar.
  const naPraca = !!e.noCentro && !emCasa;
  $('#centro-curar').classList.toggle('hidden', !naPraca);
  $('#centro-tm').classList.toggle('hidden', !naPraca);
  $('#centro-depot').classList.toggle('hidden', !naPraca);
  $('#casa-sair').classList.toggle('hidden', !emCasa);

  // O que vale para as DUAS: a barra de "W A S D", o direcional e o modo de palco.
  const andavel = naPraca || emCasa;
  $('#centro-barra').classList.toggle('hidden', !andavel);
  $('#centro-dpad').classList.toggle('hidden', !andavel);
  $('#palco')?.classList.toggle('centro-ativo', andavel);
  if (!andavel) {
    if (!$('#centro-depot-modal').classList.contains('hidden')) fecharDepotModal();
    return zerarDirecao();
  }
  if (emCasa) {
    // Dentro de casa não há sala nem contagem de gente: a instância é só sua.
    if (!$('#centro-depot-modal').classList.contains('hidden')) fecharDepotModal();
    $('#centro-sala').textContent = '';
    $('#centro-quantos').textContent = '';
    syncCasaBonecoBotoes();
    return;
  }
  syncCasaBonecoBotoes();

  // A sala só aparece quando existe mais de uma: dizer "sala 1" num servidor vazio só levanta
  // uma pergunta que não tem resposta interessante.
  const sala = e.centro?.sala ?? 0;
  $('#centro-sala').textContent = sala ? t('cena.centroSala', { n: sala + 1 }) : '';
}

/**
 * Quantos treinadores estão na praça, contados na CENA e não no estado.
 *
 * Quem entra e quem sai não suja o estado dos outros — mandar um snapshot para as 40 pessoas
 * da sala a cada chegada seria caro e chegaria atrasado de qualquer jeito. Os bonecos, esses,
 * já estão na tela: contá-los dá o número certo, de graça, a cada quadro.
 */
function tiqueCentro() {
  if (!estado.eu?.noCentro || !estado.campo) return;
  let n = 1; // o próprio jogador, que na praça é o "herói"
  for (const m of estado.campo.mobs.values()) if (m.ehTreinador) n++;
  $('#centro-quantos').textContent = t(n === 1 ? 'cena.centroSozinho' : 'cena.centroTreinadores', { n });
}
setInterval(tiqueCentro, 500);

/**
 * Curar é falar com a enfermeira, não apertar um botão de menu.
 *
 * O clique vai SEMPRE para o servidor, mesmo com o time visivelmente cheio: quem sabe o HP de
 * verdade é ele, e é ele que devolve a resposta da Joy (`k: 'joy'`) — inclusive a piada de
 * quando não há nada para curar. Conferir aqui e engolir o clique deixaria o botão mudo
 * justamente na hora em que ele tem algo divertido a dizer.
 */
$('#centro-curar').onclick = () => enviar({ t: 'centro.curar' });
$('#casa-sair').onclick = () => enviar({ t: 'casa.sair' });
$('#centro-tm').onclick = () => abrirTmResearcher();
$('#centro-depot')?.addEventListener('click', (ev) => {
  ev.stopPropagation();
  abrirDepotModal();
});

/**
 * O botão gruda na cabeça da Enfermeira Joy, quadro a quadro.
 *
 * Precisa ser a cada quadro porque a câmera se move continuamente enquanto o jogador anda —
 * não é a Joy que muda de lugar, é o mundo que desliza embaixo dela. O laço fica ligado o
 * tempo todo e sai na primeira linha fora da praça: um `requestAnimationFrame` que só testa
 * uma bandeira custa menos que ligar e desligar o laço a cada troca de cena.
 */
/** Gruda o botão na cabeça do NPC; se ele existir mas estiver fora da tela, cai num canto fixo. */
function seguirBotaoCentro(btn, tela, npc, cantoY) {
  if (!btn || btn.classList.contains('hidden')) return;
  const p = tela?.();
  if (p) {
    btn.classList.remove('fora');
    btn.style.transform = `translate(${Math.round(p.x)}px, ${Math.round(p.y)}px) translate(-50%, -100%)`;
    return;
  }
  if (npc) {
    const W = estado.campo?.W ?? 400;
    btn.classList.remove('fora');
    btn.style.transform = `translate(${W - 12}px, ${cantoY}px) translate(-100%, 0)`;
    return;
  }
  btn.classList.add('fora');
}

/** O laço está de pé? Duas chamadas de `ligarSeguirNpcs` dariam dois laços. */
let seguindoNpcs = false;

function seguirEnfermeira() {
  // MODO ECONOMIA: o laço sai de vez, e `sincronizarEconomia` o religa ao desligar o modo.
  // Um `rAF` que só testa uma bandeira parece de graça, mas acorda a tela 60 vezes por
  // segundo — é exatamente a conta de bateria que este modo existe para não pagar.
  if (economiaLigado()) {
    seguindoNpcs = false;
    return;
  }
  requestAnimationFrame(seguirEnfermeira);
  const c = estado.campo;
  seguirBotaoCentro($('#centro-curar'), () => c?.telaDaEnfermeira(), c?.enfermeira, 0);
  seguirBotaoCentro($('#centro-tm'), () => c?.telaDoTmResearcher(), c?.tmResearcher, 44);
  seguirBotaoCentro($('#centro-depot'), () => c?.telaDoDepot(), c?.depotNpc, 84);
  seguirBonecosCasa();
}

function ligarSeguirNpcs() {
  if (seguindoNpcs || economiaLigado()) return;
  seguindoNpcs = true;
  requestAnimationFrame(seguirEnfermeira);
}
ligarSeguirNpcs();

/**
 * O que a CENA precisa saber de cada treino: quanto do nível já andou e qual efeito sai no
 * soco no boneco.
 *
 * A conta vive aqui, e não no `campo.mjs`, porque a cena não conhece pokémon do jogador — ela
 * recebe `{ slot, frac, tipo }` e desenha. E não vive no servidor porque o pacote da casa já
 * evita repetir `xp`/`xpProximo`: eles chegam no snapshot, uma vez, para a lista inteira (ver
 * `xpShareParaCliente`, no sim).
 */
function syncTreinosDaCasa(e) {
  const c = estado.campo;
  if (!c) return;
  if (!e?.casa?.dentro) return c.atualizarTreinos([]);
  const lista = [];
  for (const s of e.xpShare?.slots ?? []) {
    if (!s?.id) continue;
    const pk = e.pokemons?.find((x) => x.id === s.id);
    if (!pk) continue;
    const dentro = Math.max(0, (pk.xp ?? 0) - (pk.xpNivel ?? 0));
    const faixa = Math.max(1, (pk.xpProximo ?? 1) - (pk.xpNivel ?? 0));
    // O primeiro tipo do pokémon é o elemento do golpe. Não há golpe de verdade aqui — o
    // boneco não tem vida nem tipo —, então o que a animação mostra é a cara de quem bate.
    lista.push({ slot: s.s, id: s.id, frac: Math.min(1, dentro / faixa), tipo: pk.tipos?.[0] ?? null });
  }
  c.atualizarTreinos(lista);
}

/** Um botão por posto de XP Share, grudado acima do boneco na cena da casa. */
function syncCasaBonecoBotoes() {
  const host = $('#casa-boneco-btns');
  if (!host) return;
  const emCasa = !!estado.eu?.casa?.dentro;
  host.classList.toggle('hidden', !emCasa);
  if (!emCasa) {
    host.replaceChildren();
    return;
  }
  // Os postos da casa em que ele ESTÁ — o servidor manda só os dela em `xpShare`.
  const slots = estado.eu?.xpShare?.slots ?? [];
  const cap = slots.length;
  const casaId = estado.eu?.xpShare?.casaId ?? estado.eu?.casa?.dentro ?? null;
  while (host.children.length < cap) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'casa-boneco-btn fora';
    btn.dataset.slot = host.children.length;
    host.appendChild(btn);
  }
  while (host.children.length > cap) host.lastChild.remove();
  for (let i = 0; i < cap; i++) {
    const btn = host.children[i];
    const ocupado = slots[i]?.id;
    btn.textContent = t(ocupado ? 'casa.tirar' : 'casa.escolher');
    // No celular o botão vira só um "+" ou "×" (ver `mobile.css`): a frase inteira sai do
    // desenho mas NÃO do documento, senão o botão ficaria mudo para leitor de tela e para o
    // toque-e-segure que mostra a dica.
    btn.title = btn.textContent;
    btn.setAttribute('aria-label', btn.textContent);
    btn.classList.toggle('casa-boneco-btn-tirar', !!ocupado);
    btn.onclick = () => {
      if (estado.eu?.xpShare?.slots?.[i]?.id) {
        enviar({ t: 'xpshare.escolher', casaId, slot: i, pokemonId: null });
      } else {
        abrirEscolhaDeTreino(casaId, i);
      }
    };
  }
}

function seguirBonecosCasa() {
  const host = $('#casa-boneco-btns');
  if (!host || host.classList.contains('hidden')) return;
  const c = estado.campo;
  if (!c?.centro || !estado.eu?.casa?.dentro) return;
  for (let i = 0; i < host.children.length; i++) {
    const btn = host.children[i];
    const p = c.telaDoBoneco(i);
    if (p) {
      btn.classList.remove('fora');
      btn.style.transform = `translate(${Math.round(p.x)}px, ${Math.round(p.y)}px) translate(-50%, -100%)`;
    } else {
      btn.classList.add('fora');
    }
  }
}

// ---------------------------------------------------------------- Depot (Centro Cerulean)

const ORDENS_IV_POR_STAT = {
  ivHp: 'hp',
  ivAtk: 'atk',
  ivDef: 'def',
  ivSpAtk: 'spAtk',
  ivSpDef: 'spDef',
  ivSpd: 'speed',
};
const IV_ORDEM_IDS = Object.keys(ORDENS_IV_POR_STAT);

const ivStatDoPokemon = (pk, stat) => Number(pk?.ivs?.[stat]) || 0;

const compararPorIvStat = (stat) => (a, b) =>
  ivStatDoPokemon(b, stat) - ivStatDoPokemon(a, stat) || b.level - a.level || b.id - a.id;

const DEPOT_ORDENS = ['nivel', 'qualidade', 'nota', 'iv', ...IV_ORDEM_IDS, 'potencia'];
const DEPOT_ORDEM_I18N = {
  nivel: 'depot.ordemNivel',
  qualidade: 'depot.ordemQualidade',
  nota: 'mk.ordemNota',
  iv: 'depot.ordemIv',
  ivHp: 'cm.ordIvHp',
  ivAtk: 'cm.ordIvAtk',
  ivDef: 'cm.ordIvDef',
  ivSpAtk: 'cm.ordIvSpAtk',
  ivSpDef: 'cm.ordIvSpDef',
  ivSpd: 'cm.ordIvSpd',
  potencia: 'depot.ordemPotencia',
};

// `iv` é a SOMA dos seis, antes deles na lista: quem ordena por IV quase sempre quer o total, e
// só depois o de um stat. Serve às folhas que usam esta lista (venda ao NPC, Coleção, anexo da
// DM, a escolha da Oferenda...).
const MK_POKEMON_ORDENS = ['padrao', 'qualidade', 'potencia', 'nota', 'iv', ...IV_ORDEM_IDS, 'dex', 'tipo', 'recentes'];
const MK_POKEMON_ORDEM_I18N = {
  padrao: 'mk.ordemPadrao',
  qualidade: 'depot.ordemQualidade',
  potencia: 'depot.ordemPotencia',
  nota: 'mk.ordemNota',
  iv: 'mk.ordemIvTotal',
  ivHp: 'cm.ordIvHp',
  ivAtk: 'cm.ordIvAtk',
  ivDef: 'cm.ordIvDef',
  ivSpAtk: 'cm.ordIvSpAtk',
  ivSpDef: 'cm.ordIvSpDef',
  ivSpd: 'cm.ordIvSpd',
  dex: 'mk.ordemDex',
  tipo: 'mk.ordemTipo',
  recentes: 'mk.ordemRecentes',
};

/**
 * O número da Pokédex de um pokémon — o MESMO que a ficha e a Pokédex mostram (`dexExibicao`):
 * nacional, Orre no nacional, Outland em #2001+ e mega em #3000+. Sem espécie, vai para o fim.
 */
const dexDaOrdem = (k) => {
  const id = Number(k?.speciesId ?? especieDe(k)?.pokeId);
  const n = Number.isFinite(id) && id > 0 ? Number(dexExibicao(id)) : NaN;
  return Number.isFinite(n) ? n : Number.MAX_SAFE_INTEGER;
};

const indiceTipo = (tipo) => {
  const i = TIPOS_FILTRO.indexOf(tipo);
  return i >= 0 ? i : TIPOS_FILTRO.length;
};

const ordenarMarketPokemon = (lista, ordem) => {
  const copia = [...lista];
  const statIv = ORDENS_IV_POR_STAT[ordem];
  if (statIv) return copia.sort(compararPorIvStat(statIv));
  switch (ordem) {
    case 'qualidade':
      return copia.sort(
        (a, b) => (b.quality ?? 0) - (a.quality ?? 0) || b.level - a.level || b.id - a.id,
      );
    case 'potencia':
      return copia.sort(
        (a, b) => (b.potencia ?? 1) - (a.potencia ?? 1) || b.level - a.level || b.id - a.id,
      );
    case 'nota':
      return copia.sort(
        (a, b) => (notaDoPokemon(b) ?? 0) - (notaDoPokemon(a) ?? 0) || b.level - a.level || b.id - a.id,
      );
    case 'iv':
      return copia.sort(
        (a, b) => (ivTotalDoPokemon(b) ?? 0) - (ivTotalDoPokemon(a) ?? 0) || b.level - a.level || b.id - a.id,
      );
    case 'tipo':
      return copia.sort((a, b) => {
        const ta = indiceTipo(a.tipos?.[0]) - indiceTipo(b.tipos?.[0]);
        if (ta !== 0) return ta;
        return (b.quality ?? 0) - (a.quality ?? 0) || b.level - a.level || b.id - a.id;
      });
    case 'dex':
      // CRESCENTE, como a própria Pokédex (#1 Bulbasaur primeiro) — a única da lista que não é
      // "maior primeiro". Dentro da mesma espécie, o de nível mais alto.
      return copia.sort((a, b) => dexDaOrdem(a) - dexDaOrdem(b) || b.level - a.level || b.id - a.id);
    case 'recentes':
      return copia.sort((a, b) => b.id - a.id);
    default:
      return copia.sort((a, b) => b.level - a.level || b.id - a.id);
  }
};

const htmlOpcoesTipo = (atual) =>
  `<option value="">${escapar(t('cm.todosTipos'))}</option>` +
  TIPOS_FILTRO.map(
    (tp) => `<option value="${tp}"${atual === tp ? ' selected' : ''}>${tp}</option>`,
  ).join('');

const htmlOpcoesOrdem = (ordens, mapa, atual) =>
  ordens.map(
    (id) => `<option value="${id}"${atual === id ? ' selected' : ''}>${escapar(t(mapa[id]))}</option>`,
  ).join('');

const htmlOpcoesRegistroOrdem = (atual) =>
  htmlOpcoesOrdem(REGISTRO_ORDENS, REGISTRO_ORDEM_I18N, atual);

/** As opções do filtro "Local". A primeira da lista (`todos`) é o padrão: nada some sem o jogador pedir. */
const LOCAIS_TODOS = ['todos', 'equipe', 'depot', 'colecao'];
const LOCAIS_SEM_EQUIPE = ['todos', 'depot', 'colecao'];
const LOCAL_I18N = {
  todos: 'colecao.localTodos',
  equipe: 'colecao.localEquipe',
  depot: 'colecao.localDepot',
  colecao: 'colecao.localColecao',
};
const htmlOpcoesLocal = (locais, atual) =>
  locais.map(
    (id) => `<option value="${id}"${(atual || 'todos') === id ? ' selected' : ''}>${escapar(t(LOCAL_I18N[id]))}</option>`,
  ).join('');

/**
 * A barra de filtros de tipo / IV mínimo / ordem, compartilhada pelo Depot e pela aba de venda.
 *
 * O IV é um CAMPO e não uma lista: a soma vai de 6 a 192 e qualquer recorte pré-fabricado
 * ("acima de 120", "acima de 150") erra o de alguém. Ordenar por IV já existia e não resolve
 * o mesmo problema — com 400 pokémon guardados, ordenar mostra os melhores mas continua
 * obrigando a rolar por todo o resto para achar o corte de onde começa o lixo.
 *
 * O `input` é tratado no `oninput` (e não no `onchange`) porque a lista tem de reagir ao
 * dígito, como a busca por nome logo acima dela já faz.
 */
function criarFiltrosSelect({ tipo, ordem, ivMin = '', ordens, ordemI18n, onChange, local = null, locais = null }) {
  const wrap = document.createElement('div');
  wrap.className = 'filtros-select';
  // O "Local" (Equipe / Depot / Coleção) só existe nas folhas que o pedem, com as opções que
  // fazem sentido nelas: a Oferenda, por exemplo, nem lista a equipe.
  const campoLocal = locais
    ? `<label class="filtros-select-campo filtros-select-local">
      <span>${t('colecao.filtroLocal')}</span>
      <select class="filtros-select-el" data-f="local">${htmlOpcoesLocal(locais, local)}</select>
    </label>`
    : '';
  wrap.innerHTML = `
    ${campoLocal}
    <label class="filtros-select-campo">
      <span>${t('depot.filtroTipo')}</span>
      <select class="filtros-select-el" data-f="tipo">${htmlOpcoesTipo(tipo)}</select>
    </label>
    <label class="filtros-select-campo filtros-select-num">
      <span>${t('depot.filtroIv')}</span>
      <input class="filtros-select-el" data-f="ivMin" type="number" inputmode="numeric" step="1"
             min="${IV_MIN}" max="${IV_MAX}" placeholder="${escapar(t('cm.filtroQualquer'))}"
             value="${escapar(String(ivMin ?? ''))}">
    </label>
    <label class="filtros-select-campo">
      <span>${t('depot.ordenarPor')}</span>
      <select class="filtros-select-el" data-f="ordem">${htmlOpcoesOrdem(ordens, ordemI18n, ordem)}</select>
    </label>`;
  wrap.onchange = (ev) => {
    const sel = ev.target.closest('select[data-f]');
    if (!sel) return;
    onChange(sel.dataset.f, sel.value);
  };
  wrap.oninput = (ev) => {
    const campo = ev.target.closest('input[data-f]');
    if (!campo) return;
    onChange(campo.dataset.f, campo.value);
  };
  return wrap;
}

/**
 * OS FILTROS DOS SELETORES DE POKÉMON, no celular, atrás de um botão.
 *
 * Toda folha de escolha (anúncio, anexo da DM, Oferenda, as três equipes, a Coleção da Bolsa,
 * a venda do Market) tem a mesma barra: "só shiny", Local, Tipo, IV mínimo e Ordem. Num monitor
 * ela é uma linha; num telefone eram ~300 px — mais da metade da folha —, e a grade, que é o
 * motivo da tela, começava rente ao pé dela com um card à vista (nenhum, na equipe do PvP).
 *
 * Aqui vale a gramática do Mercado da Comunidade: a busca fica onde está (é o filtro mais
 * usado) e ganha ao lado o funil, com a bolinha de quantos filtros estão ligados. O resto vai
 * para uma folha POR CIMA de `host`, com "Limpar" e "Pronto" no pé, debaixo do polegar.
 *
 * Os nós são MOVIDOS, e não recriados: os ouvintes que cada seletor pôs neles continuam
 * valendo, e o "Limpar" só precisa trocar o valor e disparar o evento que o campo já escuta.
 * O desktop nem passa por aqui.
 *
 * O "aberta" mora numa classe de `host`. Nas telas que repintam só a grade isso basta; o
 * Market, que refaz o `#mk-corpo` inteiro a cada repinte, chama de novo e a folha renasce
 * aberta, porque o `#mk-corpo` é o mesmo nó.
 */
function dobrarFiltrosNoCelular({ campos, botaoEm, host }) {
  if (!montagemMovel()) return;
  const nos = campos.filter(Boolean);
  if (!nos.length || !botaoEm || !host) return;
  host.querySelector(':scope > .pkf-folha')?.remove();
  host.classList.add('pkf-host');

  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = 'filtros-bt cm-ico-bt pkf-bt';
  bt.setAttribute('aria-label', t('mapa.filtros'));
  bt.title = t('mapa.filtros');
  bt.innerHTML = iconeFunil();
  botaoEm.appendChild(bt);

  const folha = document.createElement('div');
  folha.className = 'pkf-folha';
  folha.innerHTML = `
    <div class="filtros-folha-topo"><h3>${escapar(t('mapa.filtros'))}</h3></div>
    <div class="pkf-campos"></div>
    <div class="filtros-folha-rodape">
      <button type="button" class="cm-limpar pkf-limpar">${escapar(t('cm.limparFiltros'))}</button>
      <button type="button" class="filtros-pronto pkf-pronto">${escapar(t('filtros.pronto'))}</button>
    </div>`;
  // Os selects primeiro, o "só shiny" por último: é a ordem de uso, e o interruptor sozinho no
  // pé da lista não se perde entre dois campos.
  const caixa = folha.querySelector('.pkf-campos');
  for (const no of [...nos].sort((a, b) => Number(a.matches('.dmpk-shiny')) - Number(b.matches('.dmpk-shiny')))) {
    caixa.appendChild(no);
  }
  host.appendChild(folha);

  // Quantos estão ligados. A Ordem não conta: ela arruma a lista, não a encolhe — e é o
  // encolher esquecido que a bolinha existe para denunciar.
  const ligados = () => [...caixa.querySelectorAll('select[data-f], input[data-f], .dmpk-shiny input[type="checkbox"]')]
    .filter((el) => {
      if (el.type === 'checkbox') return el.checked;
      if (el.dataset.f === 'ordem') return false;
      if (el.dataset.f === 'local') return (el.value || 'todos') !== 'todos';
      return String(el.value ?? '').trim() !== '';
    });
  const contar = () => {
    const n = ligados().length;
    let selo = bt.querySelector('.filtros-conta');
    if (!n) selo?.remove();
    else {
      if (!selo) {
        selo = document.createElement('span');
        selo.className = 'filtros-conta';
        bt.appendChild(selo);
      }
      selo.textContent = n;
    }
    folha.querySelector('.pkf-limpar').classList.toggle('hidden', !n);
  };
  const abrir = (sim) => {
    // Quem rola é o próprio `host` em algumas telas (o Market, o passo do anúncio): a folha é
    // `inset: 0` sobre ele, então ele volta ao topo e para de rolar enquanto ela está aberta.
    if (sim) host.scrollTop = 0;
    host.classList.toggle('pkf-aberta', sim);
    bt.classList.toggle('on', sim);
  };
  bt.onclick = () => abrir(!host.classList.contains('pkf-aberta'));
  folha.querySelector('.pkf-pronto').onclick = () => abrir(false);
  folha.querySelector('.pkf-limpar').onclick = () => {
    for (const el of ligados()) {
      if (el.type === 'checkbox') el.checked = false;
      else if (el.dataset.f === 'local') el.value = 'todos';
      else el.value = '';
      el.dispatchEvent(new Event(el.matches('input[type="number"]') ? 'input' : 'change', { bubbles: true }));
    }
    contar();
  };
  folha.addEventListener('change', contar);
  folha.addEventListener('input', contar);
  contar();
  abrir(host.classList.contains('pkf-aberta'));
}

/**
 * Texto de apoio que, no celular, mostra duas linhas e abre no toque.
 *
 * As folhas de equipe e a do anúncio abrem com um parágrafo de regra que no desktop é uma
 * linha e meia e num telefone chega a cinco — a folha da guerra perdia 110 px para ele antes
 * da primeira casa. A primeira frase é a que diz o que fazer; o resto fica a um toque.
 * Texto que já cabe em duas linhas não ganha nada (nem o cursor de "tem mais").
 */
function dobrarNotaNoCelular(el) {
  if (!el || !montagemMovel()) return;
  el.classList.add('nota-dobravel');
  // A medida vai para o próximo quadro: a folha da guerra é montada com o modal ainda
  // escondido, e ali toda altura é zero.
  requestAnimationFrame(() => {
    if (!el.isConnected) return;
    if (el.scrollHeight <= el.clientHeight + 2) {
      el.classList.remove('nota-dobravel');
      return;
    }
    el.tabIndex = 0;
    el.setAttribute('role', 'button');
    el.setAttribute('aria-expanded', 'false');
    el.title = t('escolha.lerMais');
  });
  const alternar = () => {
    if (!el.classList.contains('nota-dobravel')) return;
    const aberta = el.classList.toggle('aberta');
    el.setAttribute('aria-expanded', String(aberta));
  };
  el.addEventListener('click', alternar);
  el.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      if (!el.classList.contains('nota-dobravel')) return;
      ev.preventDefault();
      alternar();
    }
  });
}

function criarMkPokemonFiltros() {
  const { tipo, ordem, ivMin } = estado.mkPokemonFiltro;
  return criarFiltrosSelect({
    tipo,
    ordem,
    ivMin,
    ordens: MK_POKEMON_ORDENS,
    ordemI18n: MK_POKEMON_ORDEM_I18N,
    onChange: (campo, valor) => {
      if (campo === 'tipo') estado.mkPokemonFiltro.tipo = valor;
      else if (campo === 'ivMin') estado.mkPokemonFiltro.ivMin = valor;
      else estado.mkPokemonFiltro.ordem = valor || 'padrao';
      pintarMarket();
    },
  });
}

/**
 * Devolve foco e cursor ao campo de IV depois de um repinte que o destruiu.
 *
 * Quem chama é o próprio `pintarMarket`, e não o `onChange` do campo. A diferença importa: a
 * assinatura da aba de venda inclui o NÍVEL de cada pokémon, então qualquer level-up remonta a
 * grade sozinho — num jogo idle, no meio da digitação. Se só o `onChange` devolvesse o foco,
 * quem digitasse "150" com a hunt rodando perderia o campo num dígito qualquer.
 *
 * O Depot não precisa de nada disso: lá a barra de filtros é HTML fixo do `index.html` e
 * `montarDepotModal` repinta só as duas listas.
 */
function devolverFocoAoFiltroIv() {
  const campo = document.querySelector('#mk-corpo input[data-f="ivMin"]');
  if (!campo) return;
  campo.focus();
  const fim = campo.value.length;
  // `type="number"` recusa `setSelectionRange` em alguns navegadores; sem ele o cursor já
  // cai no fim, que é o que interessa.
  try {
    campo.setSelectionRange(fim, fim);
  } catch { /* navegador que não deixa — o foco sozinho resolve */ }
}

const notaDoPokemon = (p) => notaDePokemon(p, especieDe(p));

const notaDoFicha = (ficha) => notaDePokemon(ficha, especieDe(ficha));

/**
 * O piso de IV digitado, já limpo (`null` = sem filtro), e o filtro de tipo + IV: as duas regras
 * moram em `shared/filtro-depot.mjs` porque o servidor refaz a MESMA conta no "Vender todo o
 * Depot (Filtrado)" — ver `vendaDepotDaTela`.
 */
const ivMinDoFiltro = pisoIvDoFiltro;

const depotPassaFiltros = (p, busca, tipo, ivMin = null) => {
  if (busca && !(p.nome ?? '').toLowerCase().includes(busca)) return false;
  return passaFiltroTipoIv(p, tipo, ivMin);
};

const ordenarDepot = (lista, ordem) => {
  const copia = [...lista];
  const statIv = ORDENS_IV_POR_STAT[ordem];
  if (statIv) return copia.sort(compararPorIvStat(statIv));
  switch (ordem) {
    case 'qualidade':
      return copia.sort(
        (a, b) => (b.quality ?? 0) - (a.quality ?? 0) || b.level - a.level || b.id - a.id,
      );
    case 'nota':
      return copia.sort(
        (a, b) => (notaDoPokemon(b) ?? 0) - (notaDoPokemon(a) ?? 0) || b.level - a.level || b.id - a.id,
      );
    case 'iv':
      return copia.sort(
        (a, b) => (ivTotalDoPokemon(b) ?? 0) - (ivTotalDoPokemon(a) ?? 0) || b.level - a.level || b.id - a.id,
      );
    case 'potencia':
      return copia.sort(
        (a, b) => (b.potencia ?? 1) - (a.potencia ?? 1) || b.level - a.level || b.id - a.id,
      );
    default:
      return copia.sort((a, b) => b.level - a.level || b.id - a.id);
  }
};

function montarDepotFiltrosUi() {
  const selTipo = $('#depot-sel-tipo');
  const selOrdem = $('#depot-sel-ordem');
  const campoIv = $('#depot-iv-min');
  if (!selTipo || !selOrdem) return;
  const { tipo, ordem, ivMin } = estado.depotFiltro;

  if (!selTipo.dataset.pronto) {
    selTipo.dataset.pronto = '1';
    selTipo.innerHTML = htmlOpcoesTipo(tipo);
    selOrdem.innerHTML = htmlOpcoesOrdem(DEPOT_ORDENS, DEPOT_ORDEM_I18N, ordem);
    selTipo.onchange = () => {
      estado.depotFiltro.tipo = selTipo.value;
      montarDepotModal();
    };
    selOrdem.onchange = () => {
      estado.depotFiltro.ordem = selOrdem.value || 'nivel';
      montarDepotModal();
    };
    // `input`, como a busca por nome logo acima: a lista reage ao dígito. Aqui dá para usar
    // sem truque nenhum porque `montarDepotModal` repinta só as duas listas — esta barra é
    // HTML fixo do index e sobrevive ao repinte.
    campoIv?.addEventListener('input', () => {
      estado.depotFiltro.ivMin = campoIv.value;
      montarDepotModal();
    });
    if (campoIv) campoIv.value = ivMin ?? '';
    return;
  }

  if (selTipo.value !== tipo) selTipo.value = tipo;
  if (selOrdem.value !== ordem) selOrdem.value = ordem;
  if (campoIv && campoIv.value !== (ivMin ?? '')) campoIv.value = ivMin ?? '';
}

function abrirDepotModal() {
  const modal = $('#centro-depot-modal');
  if (!modal) return;
  if (!estado.eu?.noCentro) return toast(t('depot.soCentro'));
  modal.classList.remove('hidden');
  montarDepotFiltrosUi();
  montarAbasDoDepot();
  montarDepotModal();
  // O foco automático abre o teclado do celular em cima da lista que a pessoa veio ver.
  if (!movelAtivo()) $('#depot-filtro')?.focus({ preventScroll: true });
}

/**
 * As duas listas do Depot viram ABAS no celular.
 *
 * Lado a lado elas cabem num monitor; num telefone o grid dá 300 px para cada, a lista da
 * equipe passa disso com quatro pokémon e — como a seção não recorta nada — vaza por cima da
 * lista de baixo. Empilhar as duas também não resolve: com 1.800 guardados, a segunda nasce
 * abaixo da dobra.
 *
 * Com abas, a lista escolhida fica com a altura inteira da folha. Começa em DEPOT porque é ele
 * que se veio olhar — a equipe já está na gaveta do jogo, a um toque.
 *
 * Monta uma vez só: `montarDepotModal` repinta o miolo das listas, nunca as seções, então a
 * escolha da aba sobrevive a cada repintura.
 */
function montarAbasDoDepot() {
  const colunas = $('#centro-depot-modal .depot-colunas');
  if (!colunas || !movelAtivo() || colunas.previousElementSibling?.classList.contains('depot-abas')) return;

  const abas = document.createElement('div');
  abas.className = 'depot-abas';
  abas.id = 'depot-abas';
  // "Guardados", e não "Depot": dentro dela moram as duas abas, Depot e Coleção.
  for (const [secao, chave] of [['guardados', 'colecao.abaGuardados'], ['equipe', 'depot.equipe']]) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = `depot-aba${secao === 'guardados' ? ' on' : ''}`;
    b.dataset.secao = secao;
    b.innerHTML = `<span>${t(chave)}</span><b class="depot-aba-cnt"></b>`;
    abas.appendChild(b);
  }
  abas.addEventListener('click', (ev) => {
    const b = ev.target.closest('.depot-aba');
    if (!b) return;
    for (const outro of abas.children) outro.classList.toggle('on', outro === b);
    for (const s of colunas.children) s.classList.toggle('on', s.dataset.secao === b.dataset.secao);
    // A busca e a ordenação são da lista guardada; na equipe (seis linhas) elas não fazem
    // sentido e roubariam meia tela. Quem as esconde é o CSS, por esta classe.
    $('#centro-depot-modal .modal-corpo')?.classList.toggle('na-equipe', b.dataset.secao === 'equipe');
  });

  colunas.parentElement.insertBefore(abas, colunas);
  for (const s of colunas.children) s.classList.toggle('on', s.dataset.secao === 'guardados');
}

const fecharDepotModal = () => {
  $('#centro-depot-modal').classList.add('hidden');
};

/**
 * As duas abas dos guardados: Depot e Coleção. Liga os cliques uma vez só — `montarDepotModal`
 * repinta o miolo, nunca os botões.
 */
function ligarLadosDoDepot() {
  const lados = $('#depot-lados');
  if (!lados || lados.dataset.pronto) return;
  lados.dataset.pronto = '1';
  lados.addEventListener('click', (ev) => {
    const b = ev.target.closest('.depot-lado');
    if (!b || b.dataset.lado === estado.depotLado) return;
    estado.depotLado = b.dataset.lado;
    const dg = $('#depot-guardados');
    if (dg) dg.scrollTop = 0;
    montarDepotModal();
  });
}

function montarDepotModal() {
  const e = estado.eu;
  if (!e?.pokemons) return;
  const filtroEl = $('#depot-filtro');
  const busca = (filtroEl?.value ?? '').trim().toLowerCase();
  const { tipo, ordem, ivMin } = estado.depotFiltro;
  const pisoIv = ivMinDoFiltro(ivMin);
  const lado = estado.depotLado === 'colecao' ? 'colecao' : 'depot';
  const colecao = conjuntoColecaoCliente();
  const time = e.pokemons.filter((p) => p.slot != null).sort((a, b) => a.slot - b.slot);
  const guardados = e.pokemons.filter((p) => p.slot == null);
  const doLado = guardados.filter((p) => colecao.has(p.id) === (lado === 'colecao'));
  const depot = ordenarDepot(
    doLado.filter((p) => depotPassaFiltros(p, busca, tipo, pisoIv)),
    ordem,
  );
  const naColecao = guardados.filter((p) => colecao.has(p.id)).length;
  const noDepot = guardados.length - naColecao;
  const ladoTotal = doLado.length;
  const temFiltro = !!busca || !!tipo || pisoIv != null;

  ligarLadosDoDepot();
  for (const b of document.querySelectorAll('#depot-lados .depot-lado')) {
    const on = b.dataset.lado === lado;
    b.classList.toggle('on', on);
    b.setAttribute('aria-selected', on ? 'true' : 'false');
  }
  const nota = $('#depot-lado-nota');
  if (nota) nota.textContent = t(lado === 'colecao' ? 'colecao.notaAbaColecao' : 'colecao.notaAbaDepot');

  const timeCnt = $('#depot-time-cnt');
  const guardCnt = $('#depot-guardados-cnt');
  const colCnt = $('#depot-colecao-cnt');
  const contagem = $('#depot-contagem');
  if (timeCnt) timeCnt.textContent = `${time.length}/${MAX_EQUIPE}`;
  if (guardCnt) guardCnt.textContent = num(noDepot);
  if (colCnt) colCnt.textContent = num(naColecao);
  // Os números nas abas do celular — lá o cabeçalho da equipe fica escondido. A aba dos
  // guardados conta os dois lados juntos: Depot e Coleção moram nela.
  const cntAba = (secao, txt) => {
    const el = document.querySelector(`.depot-aba[data-secao="${secao}"] .depot-aba-cnt`);
    if (el) el.textContent = txt;
  };
  cntAba('equipe', `${time.length}/${MAX_EQUIPE}`);
  cntAba('guardados', String(guardados.length));
  if (contagem) {
    contagem.textContent = temFiltro
      ? t('depot.contagemFiltro', { n: depot.length, total: ladoTotal })
      : t(lado === 'colecao' ? 'colecao.contagem' : 'depot.contagem', { n: ladoTotal });
  }

  const eq = $('#depot-equipe');
  if (eq) {
    eq.innerHTML = '';
    for (const p of time) eq.appendChild(linhaPokemon(p, e.activeId, { mover: true, detalhes: true, xp: true, colecao }));
    if (!time.length) eq.innerHTML = `<div class="vazio-msg">${t('depot.vazioEquipe')}</div>`;
  }

  const dg = $('#depot-guardados');
  if (dg) {
    const scroll = dg.scrollTop;
    dg.innerHTML = '';
    for (const p of depot) {
      dg.appendChild(linhaPokemon(p, e.activeId, {
        mover: true,
        detalhes: true,
        colecao,
        paraColecao: lado === 'colecao' ? 'depot' : 'colecao',
      }));
    }
    if (!depot.length) {
      const vazio = lado === 'colecao' ? 'colecao.vazia' : 'depot.vazioDepot';
      dg.innerHTML = `<div class="vazio-msg">${temFiltro ? t('depot.nenhumResultado') : t(vazio)}</div>`;
    } else {
      dg.scrollTop = scroll;
    }
  }
}

$('#depot-fechar')?.addEventListener('click', fecharDepotModal);
$('#centro-depot-modal')?.addEventListener('click', (ev) => {
  // Com ficha ou calculadora abertas, o clique no backdrop delas atravessava e fechava o depot.
  if (calcEmpilhada() || fichaAberta()) return;
  if (ev.target === $('#centro-depot-modal')) fecharDepotModal();
});
$('#depot-filtro')?.addEventListener('input', () => montarDepotModal());

/**
 * O que a Joy responde. O servidor manda só QUAL fala — a frase é do dicionário, senão o
 * balão sairia em português para quem joga em inglês.
 *
 * "Já está tudo curado" tem três versões sorteadas: é a fala que o jogador mais vai ver (é o
 * que acontece a cada clique curioso no botão), e repetir a mesma piada mata a piada.
 */
const FALAS_DA_JOY = {
  nocaute: () => t('centro.joyNocaute'),
  ola: () => t('centro.joyOla'),
  curou: () => t('centro.joyCurou'),
  jaCurado: () => t(`centro.joyJaCurado${1 + Math.floor(Math.random() * 3)}`),
};

// ------------------------------------------------- andar na praça do Centro
//
// O teclado é a ÚNICA coisa do jogo em que o jogador dirige alguém. Mesmo assim o cliente não
// move nada: manda a direção que está segurando e espera o servidor mandar o passo de volta,
// como faz com o pokémon na hunt. O que muda é o ritmo — a praça tem tick próprio de 100 ms
// justamente para essa ida e volta caber dentro do tempo em que a tecla parece responder.

/** `ev.code` é a POSIÇÃO da tecla: num teclado ABNT2, AZERTY ou Dvorak o WASD continua no W. */
const TECLA_DIRECAO = {
  ArrowUp: 1, KeyW: 1,
  ArrowRight: 2, KeyD: 2,
  ArrowDown: 3, KeyS: 3,
  ArrowLeft: 4, KeyA: 4,
};

/**
 * Pilha das teclas seguradas — vale a ÚLTIMA, não a primeira.
 *
 * Segurando W e apertando D, o boneco vira para a direita; soltando o D, ele volta a subir
 * sem precisar soltar e apertar o W de novo. É o que todo mundo espera de um jogo com WASD, e
 * uma variável só ("a direção atual") não consegue fazer.
 */
const teclasAndar = [];
let dirEnviada = 0;

function sincronizarDirecao() {
  const dir = teclasAndar.length ? TECLA_DIRECAO[teclasAndar.at(-1)] : 0;
  if (dir === dirEnviada) return;
  dirEnviada = dir;
  enviar({ t: 'centro.andar', dir });
}

/** Esquece o que estava segurado (sem avisar o servidor — quem chama já saiu da praça). */
function zerarDirecao() {
  teclasAndar.length = 0;
  dirEnviada = 0;
}

const digitando = () => {
  const el = document.activeElement;
  return !!el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || el.isContentEditable);
};

/** Praça do Centro ou sala de casa — as duas usam `centro.andar` no servidor. */
const areaAndavelCentro = () => !!estado.eu?.noCentro || !!estado.eu?.casa?.dentro;

document.addEventListener('keydown', (ev) => {
  if (!TECLA_DIRECAO[ev.code] || ev.ctrlKey || ev.altKey || ev.metaKey) return;
  // Digitando no chat, com um modal aberto ou fora da área andável, seta é seta: rola a lista.
  if (!areaAndavelCentro() || estado.modalAberto || digitando()) return;
  ev.preventDefault(); // as setas rolariam a página junto
  if (ev.repeat) return; // o auto-repeat do sistema não é uma tecla nova
  if (!teclasAndar.includes(ev.code)) teclasAndar.push(ev.code);
  sincronizarDirecao();
});

document.addEventListener('keyup', (ev) => {
  const i = teclasAndar.indexOf(ev.code);
  if (i < 0) return;
  teclasAndar.splice(i, 1);
  sincronizarDirecao();
});

/**
 * Trocar de janela no meio de um passo deixava o boneco andando para sempre: o `keyup` da
 * tecla acontece com a aba sem foco e nunca chega aqui.
 */
window.addEventListener('blur', () => {
  if (!teclasAndar.length) return;
  teclasAndar.length = 0;
  sincronizarDirecao();
});

/** Atalho M — abre/fecha o mapa mundi (fora de campos de texto). */
document.addEventListener('keydown', (ev) => {
  if (ev.key !== 'm' && ev.key !== 'M') return;
  if (ev.ctrlKey || ev.altKey || ev.metaKey) return;
  if (digitando()) return;
  if (!estado.eu) return;
  ev.preventDefault();
  if (estado.modalAberto === 'mapa') return fecharModal();
  abrirModal('mapa');
});

/**
 * O direcional do toque — a mesma mensagem da tecla, para quem não tem teclado.
 *
 * `pointerdown`/`pointerup` em vez de `click`: andar é segurar, e um clique só daria um passo
 * por toque. `setPointerCapture` garante o "soltar" mesmo que o dedo escorregue para fora do
 * botão — sem ele, arrastar o dedo para o lado deixava o boneco andando sozinho.
 */
{
  const dpad = $('#centro-dpad');
  let dedo = 0;
  dpad.addEventListener('pointerdown', (ev) => {
    const b = ev.target.closest('button[data-dir]');
    if (!b || !areaAndavelCentro() || estado.modalAberto) return;
    ev.preventDefault();
    b.setPointerCapture?.(ev.pointerId);
    dedo = Number(b.dataset.dir);
    dirEnviada = dedo;
    enviar({ t: 'centro.andar', dir: dedo });
  });
  const soltar = () => {
    if (!dedo) return;
    dedo = 0;
    dirEnviada = 0;
    enviar({ t: 'centro.andar', dir: 0 });
  };
  dpad.addEventListener('pointerup', soltar);
  dpad.addEventListener('pointercancel', soltar);
}

/**
 * Voltar ao Centro de dentro de uma hunt.
 *
 * Só aparece numa hunt de verdade: nas duas arenas a saída tem regra própria (a
 * do PvP inclusive tem os 10 s fora de combate), e um atalho aqui furaria aquilo.
 */
$('#ir-centro').onclick = () => enviar({ t: 'centro.ir' });
$('#desistir-combate').onclick = () => confirmarDesistenciaCombate();

// ------------------------------------------------------------- Escape Rope

/** O item, definido no servidor (`game/itens-nossos.mjs`). */
const ESCAPE_ROPE_ID = 70010;

/**
 * O botãozinho da corda: quantidade e estado.
 *
 * Ele NÃO some quando a quantidade é zero, fica apagado — é assim que quem nunca comprou
 * descobre que a corda existe, e a diferença entre "acabou" e "não existe" importa para um
 * item de loja. `disabled` também mata o clique, então não há toast de recusa para um botão
 * que a própria tela já sabe estar vazio.
 */
function pintarEscapeRope(e) {
  const btn = $('#escape-rope');
  if (!btn) return;
  const n = Number(e?.items?.[ESCAPE_ROPE_ID] ?? 0);
  btn.disabled = n <= 0;
  $('#er-qtd').textContent = String(n);
  btn.title = n > 0 ? t('cena.escapeRopeTem', { n }) : t('cena.escapeRopeVazio');
  // O ícone entra uma vez só — repintá-lo a cada snapshot criaria um `<img>` novo 2×/s.
  const cx = $('#er-ico');
  if (cx && !cx.dataset.pronto) {
    cx.dataset.pronto = '1';
    cx.appendChild(iconeArquivo('/img/itens/escape-rope.png', 20));
  }
}

$('#escape-rope').onclick = () => enviar({ t: 'item.use', itemId: ESCAPE_ROPE_ID });

/**
 * O aviso ao fechar a aba fora do Centro Pokémon.
 *
 * O servidor trata sumir do ar no meio de uma luta como morrer nela: o time vai ao chão, 10%
 * do XP do nível atual é descontado, e na arena o ELO e o XP também são cobrados (ver
 * `punirAbandonoDaLuta`). Fechar o jogo sem saber disso
 * seria uma pegadinha, então o navegador pergunta antes.
 *
 * O TEXTO do diálogo não é nosso: desde 2016 os navegadores ignoram a mensagem que a página
 * manda e mostram uma frase genérica ("as alterações podem não ser salvas"). Para desistir da
 * hunt com aviso de XP, o jogador usa o botão "Desistir do Combate".
 *
 * E só aparece quando há o que perder: no Centro, ou sem cena nenhuma, fechar é de graça e
 * uma pergunta a mais seria só barulho.
 */
window.addEventListener('beforeunload', (ev) => {
  const e = estado.eu;
  // Na Arena Mística fechar a aba é perder o lendário E o ticket — o caso mais caro de todos.
  const emRisco = !!e && !e.noCentro && (!!e.huntSlug || !!e.boss?.arena || !!e.mistico);
  if (!emRisco) return;
  ev.preventDefault();
  ev.returnValue = ''; // o Chrome só abre o diálogo se este campo for tocado
});

// ---------------------------------------------------- zoom da cena de batalha

const BOSS_TOKEN_ID = 70000;
const PVP_FICHA_ID = 70001;
const FRAGMENTO_CHAVE_ID = 70011;
const FRAGMENTO_SHINY_ID = 70012;
const FRAGMENTO_BICICLETA_ID = 70013;

/**
 * O id de cada drop raro que o servidor manda no `welcome` (o fragmento da Casa, o da Shiny Stone
 * e o da Bicicleta) — os outros saem de `DROPS_SESSAO` em `sessao-hunt.mjs`. Os contadores, a
 * prancheta nova e o que ela soma moram lá; aqui fica o desenho e o disco.
 */
const idsDropsSessao = () => ({
  bossTokens: BOSS_TOKEN_ID,
  fragChave: estado.casas?.fragmento?.itemId ?? FRAGMENTO_CHAVE_ID,
  fragShiny: estado.shinyStone?.fragmentoId ?? FRAGMENTO_SHINY_ID,
  fragBicicleta: estado.bicicletas?.fragmento?.itemId ?? FRAGMENTO_BICICLETA_ID,
});

/**
 * A prancheta ATRAVESSA o F5 e a queda do servidor.
 *
 * Ela vive no `localStorage`, por nick, e nada a zera além do botão "Reset" — nem o F5, nem o
 * deploy, nem a reconexão depois do wi-fi cair. Por nick porque duas contas no mesmo navegador
 * são duas hunts diferentes; e local porque a prancheta sempre foi coisa do cliente — o
 * servidor não conta nada disso.
 *
 * O tempo é gravado como DURAÇÃO (`ms`), nunca como o instante de início: na volta o `inicio`
 * é remontado para `agora − ms`, e assim o período em que o jogo esteve fora não entra no
 * relógio — o XP/hora do Pop-up continua certo mesmo depois de uma noite com a aba fechada.
 * Manter o campo `inicio` no formato de sempre é de propósito: todo o resto do código segue
 * lendo `Date.now() − s.inicio` sem saber que houve gravação no meio.
 */
const CHAVE_SESSAO_HUNT = 'sessao-hunt';
const SESSAO_SALVA_MS = 2000; // teto de gravação: uma hunt rápida não vai ao disco a cada kill
let sessaoSalvaEm = 0;

const chaveSessaoHunt = () => {
  const nick = estado.eu?.nick ?? '';
  return nick ? `${CHAVE_SESSAO_HUNT}:${nick.toLowerCase()}` : '';
};

/** Grava a prancheta. `forcar` pula o teto de 2 s — o Reset e o fechar da aba usam. */
function salvarSessaoHunt(agora = Date.now(), forcar = false) {
  const s = estado.sessao;
  const chave = chaveSessaoHunt();
  if (!s || !chave) return;
  if (!forcar && agora - sessaoSalvaEm < SESSAO_SALVA_MS) return;
  sessaoSalvaEm = agora;
  const { inicio, ...contadores } = s;
  try {
    localStorage.setItem(chave, JSON.stringify({ ...contadores, ms: Math.max(0, agora - inicio) }));
  } catch { /* privado / quota */ }
}

/**
 * A prancheta gravada deste nick, ou `null` se não houver (ou se o que há não presta). A conta
 * campo a campo — inclusive os gastos, que são mapas — é a de `sanearSessao`.
 */
function sessaoGuardada() {
  const chave = chaveSessaoHunt();
  if (!chave) return null;
  try {
    return sanearSessao(JSON.parse(localStorage.getItem(chave) ?? 'null'));
  } catch {
    return null;
  }
}

// Fechou, recarregou ou o celular mandou a aba para segundo plano: grava AGORA. `pagehide` é o
// único que o iOS entrega de verdade — lá o `beforeunload` simplesmente não roda.
window.addEventListener('pagehide', () => salvarSessaoHunt(Date.now(), true));

/**
 * Soma o evento na prancheta (a conta é `contarNaSessao`) e cuida do que é de TELA: o histórico de
 * capturas, o disco e a repintura. Evento que não mexe em contador nenhum (o `spawn`, o ataque de
 * cada golpe) não grava nem repinta.
 */
function registrarSessao(e) {
  const s = estado.sessao;
  if (!s) return;
  if (!contarNaSessao(s, e, idsDropsSessao())) return;
  if (e.k === 'capturado' && e.pokemon) {
    estado.capturasHist.unshift({
      em: Date.now(),
      id: e.pokemon.id ?? null,
      nome: e.pokemon.nome ?? '—',
      level: e.pokemon.level ?? 0,
      shiny: !!e.pokemon.shiny,
    });
    if (estado.capturasHist.length > 100) estado.capturasHist.length = 100;
    // Com o painel ABERTO a linha nova já está à vista e não há o que avisar. Fechado, a
    // captura é justamente o que o VIP de auto-bola sem parar não tem como perceber — a
    // cena rola sozinha e nada muda de lugar. Daí a bolinha.
    if (!estado.capturasHistAberta) {
      estado.capturasNaoVistas++;
      pintarSeloCapturas();
    }
    if (estado.capturasHistAberta) pintarCapturasHist();
  }
  salvarSessaoHunt();
  if (estado.sessaoAberta) agendarPintarSessao();
}

/**
 * A repintura da prancheta, uma por QUADRO. A automação gasta até vinte poções num tique e cada
 * abate traz XP, ouro e drops em eventos separados: repintar a cada um era montar os ícones do
 * painel inteiro dezenas de vezes num instante que o olho vê como um só.
 */
let pinturaSessaoAgendada = false;
function agendarPintarSessao() {
  if (pinturaSessaoAgendada) return;
  pinturaSessaoAgendada = true;
  requestAnimationFrame(() => {
    pinturaSessaoAgendada = false;
    if (estado.sessaoAberta) pintarSessao();
  });
}

function tempoSessao(ms) {
  const s = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const sec = s % 60;
  if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
  return `${m}:${String(sec).padStart(2, '0')}`;
}

/** Preço de LOJA de uma bola (o `priceGold` do catálogo) e de um item (o `npcPrice`); 0 = sem preço. */
const precoBolaSessao = (id) => Number(estado.catalogoBolas?.find((b) => b.id === id)?.priceGold) || 0;
const precoItemSessao = (id) => Number(estado.itens?.get(id)?.npcPrice) || 0;
const custosSessao = (s) => custosDaSessao(s, { precoBola: precoBolaSessao, precoItem: precoItemSessao });
const nomeBolaSessao = (id) => estado.catalogoBolas?.find((b) => b.id === id)?.nome ?? `Ball #${id}`;
const nomeItemSessao = (id) => nomeItem(id, estado.itens?.get(id)?.name ?? `#${id}`);

/**
 * O texto do botão "Copiar", em pares `[rótulo, valor]`.
 *
 * As quinze linhas de sempre vêm PRIMEIRO, na mesma ordem e com os mesmos rótulos: o texto é lido
 * em planilha e colado no chat, e quem já o processa conta com esse começo. O que a prancheta
 * passou a contar — os drops de boss, cada bola/poção/revive gasto, o gasto e o lucro — entra
 * DEPOIS. O desenho do painel (`pintarSessao`) é outro e não sai mais daqui: ele agrupa, põe
 * ícone e esconde o que é zero, e um texto para colar não pode mudar de forma a cada sessão.
 *
 * O `Tempo` é calculado na hora da chamada, então o texto copiado leva o relógio do clique. Os
 * `/h` são a conta de sempre (`ritmoDaSessao`, a do Pocket e do Hunt Analyser), com o piso de um
 * minuto no denominador que impede o primeiro abate de virar um "420.000/h".
 */
function linhasSessao(s, agora = Date.now()) {
  const ritmo = ritmoDaSessao(s, agora);
  const custos = custosSessao(s);
  const lucro = (s.gold || 0) - custos.total;
  const gastos = [
    ...custos.bolas.map((x) => [nomeBolaSessao(x.id), num(x.qtd)]),
    ...custos.pocoes.map((x) => [nomeItemSessao(x.id), num(x.qtd)]),
    ...custos.revives.map((x) => [nomeItemSessao(x.id), num(x.qtd)]),
  ];
  return [
    [t('sessao.tempo'), tempoSessao(agora - s.inicio)],
    [t('sessao.xpTreinador'), num(s.xpTreinador)],
    [t('sessao.xpTreinadorHora'), num(ritmo?.xpTreinadorH ?? 0)],
    [t('sessao.xpPokemon'), num(s.xpPokemon)],
    [t('sessao.xpPokemonHora'), num(ritmo?.xpPokemonH ?? 0)],
    [t('sessao.gold'), num(s.gold)],
    [t('sessao.goldHora'), num(ritmo?.ouroH ?? 0)],
    [t('sessao.abates'), num(s.abates)],
    [t('sessao.capturas'), num(s.capturas)],
    [t('sessao.shiniesVistos'), num(s.shiniesVistos)],
    [t('sessao.shinies'), num(s.shinies)],
    // Os quatro primeiros são os de sempre (Boss Tokens e os três fragmentos), na mesma ordem.
    ...DROPS_SESSAO.map((d) => [t(`sessao.${d.campo}`), num(s[d.campo] ?? 0)]),
    ...gastos,
    [t('sessao.gasto'), num(custos.total)],
    [t('sessao.gastoHora'), num(porHora(custos.total, s, agora))],
    [t('sessao.lucro'), num(lucro)],
    [t('sessao.lucroHora'), num(porHora(lucro, s, agora))],
  ];
}

/**
 * O texto que vai para a área de transferência: rótulo e valor em LINHAS SEPARADAS, sem cabeçalho
 * — o formato que o pessoal já cola no chat e joga em planilha desde quando o painel era copiado
 * com o mouse.
 */
const textoSessao = (s) => linhasSessao(s).map(([rotulo, valor]) => `${rotulo}\n${valor}`).join('\n');

/**
 * Copia texto, com o caminho de baixo para quem não tem a API moderna.
 *
 * `navigator.clipboard` só existe em contexto seguro, e é justamente no celular que ela falha
 * mais: numa WebView sem HTTPS, ou com a permissão negada, ela rejeita em silêncio. O
 * `execCommand` num textarea temporário ainda funciona nesses casos — e é o único caminho no
 * Safari antigo. O `font-size: 16px` não é enfeite: com menos que isso o iOS DÁ ZOOM ao focar
 * o campo, e o jogador veria a tela saltar ao copiar.
 */
async function copiarTexto(txt) {
  try {
    await navigator.clipboard.writeText(txt);
    return true;
  } catch {
    // O `ta` nasce FORA do try de baixo para o `finally` sempre alcançá-lo. Num navegador que
    // bloqueia a cópia por completo, `execCommand` LANÇA — e sem isto o textarea invisível
    // ficava no documento, um a cada toque no botão. `remove()` em nó nunca inserido é inócuo.
    const ta = document.createElement('textarea');
    try {
      ta.value = txt;
      ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;top:0;left:0;width:1px;height:1px;padding:0;border:0;opacity:0;font-size:16px';
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      // O iOS ignora `.select()` num campo readonly; o intervalo explícito é o que funciona lá.
      ta.setSelectionRange(0, txt.length);
      return document.execCommand('copy');
    } catch {
      return false;
    } finally {
      ta.remove();
    }
  }
}

async function copiarSessao() {
  const s = estado.sessao;
  if (!s) return;
  toast(t(await copiarTexto(textoSessao(s)) ? 'sessao.copiado' : 'sessao.copiaFalhou'));
}

/**
 * A PRANCHETA, desenhada em seções: Tempo (a informação principal), Treinador, Shiny, Drops raros
 * e Custos. Com largura são duas colunas da mesma altura — Treinador e Custos à esquerda; Tempo,
 * Shiny e Drops à direita, o Tempo no alto —; estreita (celular, Modo Economia), uma coluna só, com
 * o Tempo em primeiro. Quem decide é a container query do `.ss-grade` (ver o estilo).
 *
 * Dinâmica de propósito: o contador que SUBIU desde a última pintura acende por um instante
 * (`.ss-subiu`), o drop ainda não pego fica apagado e acende no primeiro, e os gastos aparecem
 * conforme a automação usa — um ícone por bola, poção ou revive, com a quantidade ao lado.
 *
 * Os ícones entram como marcador (`data-ss-*`) e são trocados pelos elementos de sempre
 * (`imgItem`, `iconeBola`, `iconeArquivo`) logo depois do `innerHTML` — o mesmo trato do resto da
 * interface, com o mesmo cache de imagem.
 */
function pintarSessao() {
  const painel = $('#sessao-painel');
  const s = estado.sessao;
  if (!painel || !s) return;
  const agora = Date.now();
  const ritmo = ritmoDaSessao(s, agora);
  const custos = custosSessao(s);
  const lucro = (s.gold || 0) - custos.total;
  const resetBloqueado = agora < estado.sessaoResetLivreEm;
  // O número de antes de cada contador: o que mudou desde a última pintura acende.
  const antes = new Map([...painel.querySelectorAll('[data-k]')].map((el) => [el.dataset.k, el.textContent]));

  const hora = (id, valor) => `<em class="ss-hora"><span id="${id}">${num(valor)}</span>/h</em>`;
  const linha = (k, ico, rotulo, valor, porHoraHtml = '', classe = '') => `
    <li class="ss-linha${classe ? ` ${classe}` : ''}">
      <span class="ss-ico" aria-hidden="true">${ico}</span>
      <span class="ss-rot">${rotulo}</span>
      <b data-k="${k}">${valor}</b>
      ${porHoraHtml}
    </li>`;
  const treinador = `
    <section class="ss-sec ss-treinador">
      <h4>${t('sessao.secTreinador')}</h4>
      <ul class="ss-linhas">
        ${linha('xpTreinador', dlgIcone('pessoa', 14), t('sessao.xpTreinador'), num(s.xpTreinador), hora('sessao-xp-treinador-h', ritmo?.xpTreinadorH ?? 0))}
        ${linha('xpPokemon', dlgIcone('estrela', 14), t('sessao.xpPokemon'), num(s.xpPokemon), hora('sessao-xp-pokemon-h', ritmo?.xpPokemonH ?? 0))}
        ${linha('gold', `<span data-ss-arq="${ICONE_OURO}" data-px="15"></span>`, t('sessao.gold'), num(s.gold), hora('sessao-gold-h', ritmo?.ouroH ?? 0))}
        ${linha('abates', dlgIcone('espadas', 14), t('sessao.abates'), num(s.abates), hora('sessao-abates-h', ritmo?.abatesH ?? 0))}
        ${linha('capturas', '<span data-ss-bola="1" data-px="15"></span>', t('sessao.capturas'), num(s.capturas))}
      </ul>
    </section>`;
  const cartaoShiny = (k, valor, rotulo) => `
    <div class="ss-shiny${valor ? ' tem' : ''}">
      <span class="ss-shiny-ico" aria-hidden="true">${dlgIcone('brilho', 18)}</span>
      <b data-k="${k}">${num(valor)}</b>
      <span>${rotulo}</span>
    </div>`;
  const shiny = `
    <section class="ss-sec ss-sec-shiny">
      <h4>${t('sessao.secShiny')}</h4>
      <div class="ss-shinies">
        ${cartaoShiny('shiniesVistos', s.shiniesVistos, t('sessao.shinyVistos'))}
        ${cartaoShiny('shinies', s.shinies, t('sessao.shinyCapturados'))}
      </div>
    </section>`;
  const ids = idsDropsSessao();
  const drops = `
    <section class="ss-sec ss-sec-drops">
      <h4>${t('sessao.secDrops')}</h4>
      <div class="ss-drops">
        ${DROPS_SESSAO.map((d) => {
          const n = s[d.campo] ?? 0;
          const nome = t(`sessao.${d.campo}`);
          return `<div class="ss-slot${n ? ' tem' : ''}" title="${escapar(`${nome}: ${num(n)}`)}">
            <span data-ss-item="${ids[d.campo] ?? d.id}" data-px="24"></span>
            <b data-k="${d.campo}">${num(n)}</b>
            <small>${t(`sessao.curto.${d.campo}`)}</small>
          </div>`;
        }).join('')}
      </div>
    </section>`;
  const chip = (k, iconeHtml, nome, x) => `
    <span class="ss-chip${x.unidade ? '' : ' sem-preco'}" title="${escapar(x.unidade
      ? t('sessao.custoItem', { nome, qtd: num(x.qtd), preco: num(x.unidade), custo: num(x.custo) })
      : t('sessao.custoSemPreco', { nome, qtd: num(x.qtd) }))}">
      ${iconeHtml}<b data-k="${k}">${num(x.qtd)}</b>
    </span>`;
  const grupo = (rotulo, itens, chipDe) => (itens.length ? `
    <div class="ss-gasto">
      <span class="ss-gasto-rot">${rotulo}</span>
      <div class="ss-chips">${itens.map(chipDe).join('')}</div>
    </div>` : '');
  const gastos = grupo(t('sessao.custoBolas'), custos.bolas,
    (x) => chip(`bola:${x.id}`, `<span data-ss-bola="${x.id}" data-px="18"></span>`, nomeBolaSessao(x.id), x))
    + grupo(t('sessao.custoPocoes'), custos.pocoes,
      (x) => chip(`pocao:${x.id}`, `<span data-ss-item="${x.id}" data-px="18"></span>`, nomeItemSessao(x.id), x))
    + grupo(t('sessao.custoRevives'), custos.revives,
      (x) => chip(`revive:${x.id}`, `<span data-ss-item="${x.id}" data-px="18"></span>`, nomeItemSessao(x.id), x));
  const custosHtml = `
    <section class="ss-sec ss-custos">
      <h4>${t('sessao.secCustos')}</h4>
      <div class="ss-caixa">
        ${gastos || `<p class="ss-vazio">${t('sessao.custoNada')}</p>`}
        <ul class="ss-linhas ss-totais">
          ${linha('gasto', dlgIcone('moedas', 14), t('sessao.gasto'),
            custos.total ? `−${num(custos.total)}` : '0', hora('sessao-gasto-h', porHora(custos.total, s, agora)), 'gasto')}
          ${linha('lucro', dlgIcone('trofeu', 14), t('sessao.lucro'), num(lucro),
            hora('sessao-lucro-h', porHora(lucro, s, agora)), lucro < 0 ? 'lucro negativo' : 'lucro')}
        </ul>
      </div>
    </section>`;

  painel.innerHTML = `
    <div class="sessao-topo">
      <h3>${t('sessao.titulo')}</h3>
      <div class="sessao-acoes">
        <button type="button" class="sessao-reset sessao-copiar" id="sessao-copiar"
          data-i18n-attr="title:tip.sessaoCopiar" title="${t('tip.sessaoCopiar')}">${t('sessao.copiar')}</button>
        <button type="button" class="sessao-reset" id="sessao-reset"${resetBloqueado ? ' disabled' : ''}
          data-i18n-attr="title:tip.sessaoReset" title="${t('tip.sessaoReset')}">${t('sessao.reset')}</button>
      </div>
    </div>
    <div class="ss-grade">
      <div class="ss-col">${treinador}${custosHtml}</div>
      <div class="ss-col">
        <section class="ss-sec ss-sec-tempo">
          <h4>${t('sessao.tempo')}<i class="ss-vivo" aria-hidden="true"></i></h4>
          <div class="ss-tempo">
            <span class="ss-tempo-ico" aria-hidden="true">${dlgIcone('relogio', 26)}</span>
            <b id="sessao-tempo">${tempoSessao(agora - s.inicio)}</b>
          </div>
        </section>
        ${shiny}${drops}
      </div>
    </div>`;

  for (const el of painel.querySelectorAll('[data-ss-item]')) {
    el.replaceWith(imgItem(Number(el.dataset.ssItem), Number(el.dataset.px) || 24));
  }
  for (const el of painel.querySelectorAll('[data-ss-bola]')) {
    el.replaceWith(iconeBola(Number(el.dataset.ssBola), Number(el.dataset.px) || 18));
  }
  for (const el of painel.querySelectorAll('[data-ss-arq]')) {
    el.replaceWith(iconeArquivo(el.dataset.ssArq, Number(el.dataset.px) || 15));
  }
  for (const el of painel.querySelectorAll('[data-k]')) {
    const v = antes.get(el.dataset.k);
    if (v !== undefined && v !== el.textContent) el.classList.add('ss-subiu');
  }
  $('#sessao-reset')?.addEventListener('click', resetarSessao);
  $('#sessao-copiar')?.addEventListener('click', copiarSessao);
}

/**
 * Os `/h` da prancheta, repintados a cada segundo.
 *
 * Eles andam SOZINHOS: o denominador é o relógio, então o ritmo cai a cada segundo em que nada
 * acontece. Repintar só no evento deixaria o número do último abate congelado na tela de quem
 * saiu da hunt — e é justamente aí que ele mente mais. São `textContent` no tique que já mexe no
 * `Tempo`, sem repintar o painel inteiro (o `innerHTML` de `pintarSessao` refaria os ícones).
 */
const SESSAO_RITMO_CELULAS = [
  ['sessao-xp-treinador-h', 'xpTreinadorH'],
  ['sessao-xp-pokemon-h', 'xpPokemonH'],
  ['sessao-gold-h', 'ouroH'],
  ['sessao-abates-h', 'abatesH'],
];

function pintarRitmoSessao(agora = Date.now()) {
  const s = estado.sessao;
  const ritmo = ritmoDaSessao(s, agora);
  if (!ritmo) return;
  for (const [id, chave] of SESSAO_RITMO_CELULAS) {
    const el = $(`#${id}`);
    if (el) el.textContent = num(ritmo[chave]);
  }
  const gastoEl = $('#sessao-gasto-h');
  const lucroEl = $('#sessao-lucro-h');
  if (!gastoEl && !lucroEl) return;
  const { total } = custosSessao(s);
  if (gastoEl) gastoEl.textContent = num(porHora(total, s, agora));
  if (lucroEl) lucroEl.textContent = num(porHora((s.gold || 0) - total, s, agora));
}

const SESSAO_RESET_MS = 5000;

function resetarSessao() {
  const agora = Date.now();
  if (agora < estado.sessaoResetLivreEm) return;
  estado.sessaoResetLivreEm = agora + SESSAO_RESET_MS;
  estado.sessao = sessaoNova();
  salvarSessaoHunt(agora, true); // o zero tem que ir ao disco, senão o F5 traz tudo de volta
  pintarSessao();
}

/**
 * A bolinha de "tem coisa nova" no botão do histórico.
 *
 * Só o CONTADOR mora no estado; o desenho é um `<i>` que entra e sai do botão. Guardar o nó
 * não vale: o botão é repintado por `iconeBola` no boot e mais nada mexe nele, então procurar
 * o filho a cada captura custa menos que manter uma referência que pode envelhecer.
 *
 * Passa de 9 vira "9+": o número exato não muda nenhuma decisão depois disso, e três dígitos
 * não cabem num botão de 36 px. O `data-novas` leva o número cru para fora do texto cortado —
 * fica visível para depurar e para o teste de UI, como o `data-zoom` do palco.
 */
const CAPTURAS_SELO_MAX = 9;

/** Desenha (ou apaga) a bolinha conforme `estado.capturasNaoVistas`. */
function pintarSeloCapturas() {
  const btn = $('#cena-capturas');
  if (!btn) return;
  const n = estado.capturasNaoVistas ?? 0;
  let selo = btn.querySelector('.sessao-selo');
  if (!n) {
    selo?.remove();
    btn.removeAttribute('data-novas');
    return;
  }
  if (!selo) {
    selo = document.createElement('i');
    selo.className = 'sessao-selo';
    btn.appendChild(selo);
  }
  selo.textContent = n > CAPTURAS_SELO_MAX ? `${CAPTURAS_SELO_MAX}+` : String(n);
  btn.setAttribute('data-novas', String(n));
}

/** Abriu o histórico: o que estava por ver está visto. */
function zerarSeloCapturas() {
  if (!estado.capturasNaoVistas) return;
  estado.capturasNaoVistas = 0;
  pintarSeloCapturas();
}

function fecharPainelCapturas() {
  estado.capturasHistAberta = false;
  $('#capturas-painel')?.classList.add('hidden');
  $('#capturas-painel')?.setAttribute('aria-hidden', 'true');
  $('#cena-capturas')?.classList.remove('on');
}

function fecharPainelSessao() {
  estado.sessaoAberta = false;
  $('#sessao-painel')?.classList.add('hidden');
  $('#sessao-painel')?.setAttribute('aria-hidden', 'true');
  $('#cena-sessao')?.classList.remove('on');
}

function alternarSessao() {
  estado.sessaoAberta = !estado.sessaoAberta;
  const painel = $('#sessao-painel');
  const btn = $('#cena-sessao');
  if (!painel || !btn) return;
  if (estado.sessaoAberta) fecharPainelCapturas();
  painel.classList.toggle('hidden', !estado.sessaoAberta);
  painel.setAttribute('aria-hidden', estado.sessaoAberta ? 'false' : 'true');
  btn.classList.toggle('on', estado.sessaoAberta);
  if (estado.sessaoAberta) pintarSessao();
}

const horaCaptura = (ms) => new Date(ms).toLocaleTimeString('pt-BR');

function pintarCapturasHist() {
  const painel = $('#capturas-painel');
  const lista = estado.capturasHist ?? [];
  if (!painel) return;
  const resetBloqueado = Date.now() < estado.capturasHistResetLivreEm;
  painel.innerHTML = `
    <div class="sessao-topo">
      <h3>${t('capturas.titulo')}</h3>
      <button type="button" class="sessao-reset" id="capturas-reset"${resetBloqueado ? ' disabled' : ''}
        data-i18n-attr="title:tip.capturasHistReset" title="${t('tip.capturasHistReset')}">${t('capturas.reset')}</button>
    </div>
    ${
      lista.length
        ? `<div class="capturas-corpo"><ul class="capturas-linhas">${lista
            .map(
              (c) =>
                `<li class="capturas-linha">
                  <span class="capturas-hora">${horaCaptura(c.em)}</span>
                  <b class="capturas-nome">${escapar(c.nome)} ${t('cm.nivel')} ${num(c.level)}${c.shiny ? ' ✨' : ''}</b>
                  <span class="capturas-info" role="button" data-id="${c.id ?? ''}"
                    title="${t('cm.verFicha')}">i</span>
                </li>`,
            )
            .join('')}</ul></div>`
        : `<div class="cm-vazio capturas-vazio">${t('capturas.vazio')}</div>`
    }`;
  $('#capturas-reset')?.addEventListener('click', resetarCapturasHist);
  painel.querySelector('.capturas-linhas')?.addEventListener('click', (ev) => {
    const info = ev.target.closest('.capturas-info');
    if (!info) return;
    ev.stopPropagation();
    const id = Number(info.dataset.id);
    if (!id) return toast(t('capturas.semFicha'));
    const pk = estado.eu?.pokemons?.find((p) => p.id === id);
    if (pk) abrirFichaDoPokemon(pk);
    else toast(t('capturas.semFicha'));
  });
}

function resetarCapturasHist() {
  const agora = Date.now();
  if (agora < estado.capturasHistResetLivreEm) return;
  estado.capturasHistResetLivreEm = agora + SESSAO_RESET_MS;
  estado.capturasHist = [];
  zerarSeloCapturas();
  pintarCapturasHist();
}

function alternarCapturasHist() {
  estado.capturasHistAberta = !estado.capturasHistAberta;
  const painel = $('#capturas-painel');
  const btn = $('#cena-capturas');
  if (!painel || !btn) return;
  if (estado.capturasHistAberta) fecharPainelSessao();
  painel.classList.toggle('hidden', !estado.capturasHistAberta);
  painel.setAttribute('aria-hidden', estado.capturasHistAberta ? 'false' : 'true');
  btn.classList.toggle('on', estado.capturasHistAberta);
  if (estado.capturasHistAberta) {
    zerarSeloCapturas();
    pintarCapturasHist();
  }
}


// ----------------------------------------------------------- Modo Economia
//
// O palco SEM cena, para celular e PC fraco.
//
// Não é o Modo otimizado com outro nome. Aquele desliga os ENFEITES — animação de golpe,
// número de dano — e continua desenhando o mapa, os sprites e todo mundo andando, 60 vezes por
// segundo. Este desliga o DESENHO, e é aí que está a conta:
//
//   · o laço de quadro do `campo.mjs` PARA (é ele que acorda a tela 60×/s);
//   · o `seguirEnfermeira` (o outro `rAF` permanente, o dos botões da praça) sai junto;
//   · o canvas de chão do mapa é devolvido ao navegador — são dezenas de MB, e `soltarMapas`
//     esvazia o cache de `mapa.mjs` porque `limpar()` sozinho só soltaria a referência daqui;
//   · o servidor deixa de mandar `campo` (ver `cliente.economia` no protocolo), que é a maior
//     fatia da banda de quem caça: menos rádio no celular e menos JSON para analisar.
//
// As folhas de sprite (`sprites.mjs`) NÃO são soltas: aquele cache é compartilhado com a
// equipe, a bolsa e a Pokédex, e limpá-lo cobraria uma redecodificação de telas que continuam
// à vista. O que o modo faz por elas é PARAR o crescimento — sem cena, nenhuma espécie nova de
// hunt entra ali, e é o crescimento que estoura a memória de quem deixa a aba aberta a noite
// toda. Medido no local: −99% de CPU de script, −87% de CPU da aba, −74% de socket.
//
// O JOGO não muda em nada: a caça continua no servidor, os eventos de `batalha` continuam
// chegando, e é deles que sai tudo o que a tela mostra aqui. Isto é tela, não regra.
//
// E o que fica é o que se acompanha num idle: o ritmo por hora (a mesma conta do cartão
// Pocket, `ritmoDaSessao`), a prancheta da sessão e o histórico de capturas. Os dois últimos
// são os MESMOS nós do HUD do palco, MOVIDOS para cá — a regra do `mobile.mjs`, e o que faz
// `pintarSessao`/`pintarCapturasHist` continuarem valendo sem saber que este modo existe.

/** De onde a prancheta e o histórico vieram, para poder devolvê-los na mesma ordem. */
let ecoDeVolta = null;
/** Os `<b>` da grade de ritmo. Trocar texto é TODO o repinte que este modo faz por segundo. */
let ecoRitmo = null;

/**
 * Monta a grade UMA vez. Daí para a frente só os `<b>` mudam. As células vêm de
 * `CELULAS_DO_RITMO` (popup.mjs) porque a janelinha de números do Modo Economia mostra as
 * mesmas seis, na mesma ordem.
 */
function montarRitmoEconomia() {
  const host = $('#eco-ritmo');
  if (!host || ecoRitmo) return;
  host.innerHTML = '';
  ecoRitmo = {};
  for (const [chave, rotulo] of CELULAS_DO_RITMO) {
    const cel = document.createElement('div');
    cel.className = 'eco-cel';
    const i = document.createElement('i');
    i.dataset.i18n = rotulo; // troca de idioma repassa por `aplicarI18n`
    i.textContent = t(rotulo);
    const b = document.createElement('b');
    b.textContent = '—';
    cel.append(i, b);
    host.appendChild(cel);
    ecoRitmo[chave] = b;
  }
}

function pintarRitmoEconomia() {
  const s = estado.sessao;
  const ritmo = ritmoDaSessao(s);
  if (!ecoRitmo || !s || !ritmo) return;
  ecoRitmo.xpTreinadorH.textContent = num(ritmo.xpTreinadorH);
  ecoRitmo.xpPokemonH.textContent = num(ritmo.xpPokemonH);
  ecoRitmo.ouroH.textContent = num(ritmo.ouroH);
  ecoRitmo.abatesH.textContent = num(ritmo.abatesH);
  ecoRitmo.capturasH.textContent = num(ritmo.capturasH);
  ecoRitmo.tempo.textContent = tempoSessao(Date.now() - s.inicio);
}

/** A linha de "onde estou" — o mesmo texto da plaquinha da cena, que aqui está escondida. */
function pintarOndeEconomia(e) {
  const bt = $('#eco-onde');
  if (!bt) return;
  bt.textContent = e ? rotuloDaCena(e) : t('eco.semArea');
}

/**
 * Traz a prancheta e o histórico para dentro do painel e os abre.
 *
 * Abrir na unha (em vez de chamar `alternarSessao`) é de propósito: os dois são MUTUAMENTE
 * exclusivos no canto da cena, onde há vaga para um cartãozinho só. Aqui há duas colunas.
 */
function montarEconomia() {
  const corpo = $('#eco-corpo');
  const lado = $('#eco-lado');
  const sessao = $('#sessao-painel');
  const capturas = $('#capturas-painel');
  if (!corpo || !lado || !sessao || !capturas) return;
  montarRitmoEconomia();
  // O irmão de baixo é a âncora da volta: `appendChild` devolveria os dois para o fim do
  // `.hud-zoom`, embaixo dos botões de zoom.
  ecoDeVolta ??= {
    sessao: [sessao.parentElement, sessao.nextElementSibling],
    capturas: [capturas.parentElement, capturas.nextElementSibling],
  };
  lado.appendChild(sessao); // embaixo do ritmo, na coluna dos números
  corpo.appendChild(capturas); // a coluna da direita, inteira
  estado.sessaoAberta = true;
  estado.capturasHistAberta = true;
  for (const el of [sessao, capturas]) {
    el.classList.remove('hidden');
    el.setAttribute('aria-hidden', 'false');
  }
  $('#eco-painel')?.setAttribute('aria-hidden', 'false');
  zerarSeloCapturas(); // o histórico está à vista o tempo todo: não há "por ver"
  pintarSessao();
  pintarCapturasHist();
  pintarRitmoEconomia();
  pintarOndeEconomia(estado.eu);
}

/** Devolve os dois painéis ao canto da cena, fechados, como o jogador os encontrou. */
function desmontarEconomia() {
  $('#eco-painel')?.setAttribute('aria-hidden', 'true');
  if (!ecoDeVolta) return;
  const sessao = $('#sessao-painel');
  const capturas = $('#capturas-painel');
  // O de baixo primeiro: a âncora da prancheta é o próprio histórico.
  const [paiCap, aposCap] = ecoDeVolta.capturas;
  if (capturas && paiCap) paiCap.insertBefore(capturas, aposCap);
  const [paiSes, aposSes] = ecoDeVolta.sessao;
  if (sessao && paiSes) paiSes.insertBefore(sessao, aposSes);
  ecoDeVolta = null;
  fecharPainelSessao();
  fecharPainelCapturas();
}

/** Avisa o sim para parar (ou voltar) a mandar o campo. Só isto sai daqui para o servidor. */
function avisarEconomiaAoServidor() {
  if (estado.ws?.readyState !== 1) return;
  enviar({ t: 'cliente.economia', ativo: economiaLigado() });
}

/**
 * Põe o jogo no estado que a preferência pede. Chamada pelo interruptor e pelo `welcome` —
 * este último porque toda reconexão reabre um socket novo (e, no sim, pode ser um jogador
 * novo em memória) que ainda não sabe da escolha desta aba.
 */
function sincronizarEconomia() {
  const ligado = economiaLigado();
  // A janelinha Pocket da cena não convive com a Economia, e a de números não sobrevive a ela
  // — mas a reconexão, que também passa aqui, não fecha nenhuma das duas.
  acertarPopupComEconomia(ligado);
  if (ligado) {
    // A fita do PvP e o termômetro de rank moram no palco. Escondê-los com o resto deixaria os
    // dois vivos por baixo — um deles desenhando a 60 Hz num canvas que ninguém vê.
    fecharMiniPvp();
    fecharTickDeRank();
  }
  estado.campo?.economia(ligado);
  if (ligado) montarEconomia();
  else desmontarEconomia();
  avisarEconomiaAoServidor();
  if (!ligado) {
    ligarSeguirNpcs(); // o `rAF` dos botões do Centro morreu junto com a cena
    estado.campo?.redimensionar();
  }
  pintarGolpesPainel(estado.eu, estado.eu?.pokemons?.find((x) => x.id === estado.eu?.activeId));
}

function definirEconomia(ligado) {
  aplicarEconomia(ligado);
  sincronizarEconomia();
}

$('#eco-sair')?.addEventListener('click', () => definirEconomia(false));
// O ATALHO da cena (ver o comentário do `#hunt-eco` no index.html). Só liga: ligado, a cena
// sai do ar e leva este botão junto, e a volta é o `#eco-sair` do painel de Economia — que é
// o único que continua na tela. Um toast porque o modo é grande demais para acontecer calado:
// a cena some, e sem uma frase o jogador não sabe se ligou algo ou se o jogo quebrou.
$('#hunt-eco')?.addEventListener('click', () => {
  if (economiaLigado()) return;
  definirEconomia(true);
  toast(t('eco.ligadoToast'));
});
// A plaquinha da hunt, no celular, é a porta do Mapa (ver DESIGN.md §8) — e ela está
// escondida aqui. Sem este botão, trocar de área no Modo Economia dependeria de lembrar da
// gaveta de menu.
$('#eco-onde')?.addEventListener('click', () => {
  if (!estado.eu) return;
  abrirModal('mapa');
});

// ------------------------------------------------------- Tela sempre acesa
//
// O Screen Wake Lock do celular — o porquê e o custo estão no cabeçalho de `tela-acesa.mjs`.
// Aqui só mora QUANDO ele vale: a escolha ligada, num aparelho de celular, com alguém dentro
// do jogo. É o mesmo critério que decide se a linha aparece nas Configurações; no computador
// a aba minimizada já continua conectada, e segurar a tela lá seria gastar à toa.

const telaAcesaSeAplica = () => aparelhoDeToque() || movelAtivo();

/** Põe a trava no estado que a escolha pede. Devolve se ela ficou presa. */
function sincronizarTelaAcesa() {
  return manterTelaAcesa(telaAcesaLigado() && telaAcesaSeAplica() && !!estado.eu);
}

$('#cena-sessao').innerHTML = iconePrancheta();
$('#cena-sessao').onclick = alternarSessao;
$('#cena-capturas').appendChild(iconeBola(1, 22));
$('#cena-capturas').onclick = alternarCapturasHist;

$('#cena-zoom-mais').innerHTML = lupa('+');
$('#cena-zoom-menos').innerHTML = lupa('-');

function ajustarZoomCena(passo) {
  if (!estado.campo) return;
  const z = estado.campo.mudarZoom(passo);
  $('#cena-zoom-mais').disabled = !estado.campo.podeAproximar;
  $('#cena-zoom-menos').disabled = !estado.campo.podeAfastar;
  $('#palco').dataset.zoom = z; // fica visível para depurar e para o teste de UI
}
$('#cena-zoom-mais').onclick = () => ajustarZoomCena(+1);
$('#cena-zoom-menos').onclick = () => ajustarZoomCena(-1);

$('#imersivo-sair').onclick = () => {
  definirImersivo(false);
  if (estado.modalAberto === 'configuracoes') pintarConfiguracoes();
};

// a roda sobre o palco também aproxima, igual ao mapa-múndi — exceto quando uma folha cobre a cena
$('#palco').addEventListener(
  'wheel',
  (ev) => {
    if (!estado.campo) return;
    if (
      ev.target.closest('.cm-folha') ||
      ev.target.closest('.caidos:not(.hidden)') ||
      ev.target.closest('#capturas-painel:not(.hidden)')
    )
      return;
    ev.preventDefault();
    ajustarZoomCena(ev.deltaY < 0 ? +1 : -1);
  },
  { passive: false },
);

/** A roda sobre "Proximidade para Capturar" rola a lista — não dá zoom na cena por baixo. */
(function ligarScrollCaidos() {
  const painel = $('#caidos');
  if (!painel) return;
  painel.addEventListener(
    'wheel',
    (ev) => {
      if (painel.classList.contains('hidden')) return;
      const lista = painel.querySelector('.caidos-lista');
      if (!lista) return;
      ev.preventDefault();
      ev.stopPropagation();
      if (lista.scrollHeight > lista.clientHeight) lista.scrollTop += ev.deltaY;
      else if (lista.scrollWidth > lista.clientWidth) lista.scrollLeft += ev.deltaY;
    },
    { passive: false },
  );
})();

/** A roda sobre o painel de Capturas rola a lista — não dá zoom na cena por baixo. */
(function ligarScrollCapturas() {
  const painel = $('#capturas-painel');
  if (!painel) return;
  painel.addEventListener(
    'wheel',
    (ev) => {
      if (painel.classList.contains('hidden')) return;
      const corpo = painel.querySelector('.capturas-corpo');
      if (!corpo) return;
      ev.preventDefault();
      ev.stopPropagation();
      if (corpo.scrollHeight > corpo.clientHeight) corpo.scrollTop += ev.deltaY;
    },
    { passive: false },
  );
})();

/** Ícones que o espelho não tem — arte do pokesprite, caminhos flat como o resto do espelho. */
const ICONES_ITEM_FIXOS = {
  30: 'site/assets/items/dark_gem.png', // Dark Gem (_loot_placeholder)
  63: 'site/assets/items/goggles.png', // Goggles (_loot_placeholder)
  47: 'site/assets/items/farfetchd_stick.png', // Farfetch'd Stick
  5041: 'site/assets/items/farfetchd_stick.png',
  70070: '/img/itens/golden-potion.png', // Golden Potion — arte nossa, fora do espelho
};

/**
 * Um ícone POR TIPO para os TM Disks elementais: "Fire-Type TM Disk" → `/img/itens/tm/fire.png`.
 *
 * O espelho dá a todos o mesmo disco, e na bolsa e no Mercado dezoito discos iguais só se
 * distinguiam lendo o nome. Os desenhos são do pokesprite (`items/tm/<tipo>.png`) e moram no
 * cliente, versionados, pela mesma razão das artes de `ICONES_ITEM_FIXOS`. Casa pelo NOME
 * porque os ids vêm do espelho; o disco AoE não tem "-Type" no nome e fica com o de sempre.
 */
function aplicarIconesTmElemental() {
  for (const item of estado.itens.values()) {
    const m = /^([A-Za-z]+)-Type TM Disk$/.exec(item?.name ?? '');
    if (m) estado.iconesItem[item.id] = `/img/itens/tm/${m[1].toLowerCase()}.png`;
  }
}

function registrarIconeDoCatalogo(mapa, id, icon) {
  if (!icon || mapa[id]) return;
  const rel = caminhoIconeRel(icon);
  if (rel) mapa[id] = rel;
}

/**
 * Caminho do ícone de um item.
 *
 * A barra inicial distingue arte NOSSA (`/img/itens/…`, servida junto do cliente e versionada)
 * do espelho de assets (`site/assets/…`, regenerável e fora do git) — a mesma convenção de
 * `iconeArquivo` e do `SPRITE_BOLA`. Sem este teste, o ícone de um item nosso virava
 * `/assets//img/itens/…` e caía no genérico.
 */
const iconeItem = (id) => {
  const rel = estado.iconesItem[id] ?? caminhoIconeRel(estado.itens.get(id)?.icon);
  if (!rel) return null;
  return rel.startsWith('/') ? rel : `/assets/${rel}`;
};

/** O ícone que entra no lugar de um item sem arte — a bolsa do menu, e não um quadrado vazio. */
const ICONE_ITEM_GENERICO = 'site/assets/ui/menu-bolsa.png';

/**
 * `<img>` do ícone de um item, com rede embaixo.
 *
 * Dois furos reais no espelho de assets justificam isto: itens sem entrada nenhuma em
 * `items-icons.json` (o Farfetch'd Stick; a Moon Stone era outro, antes de sair do jogo) e outros 4 apontam para um arquivo que
 * não existe (Crystal Cube, Dodo Cube, Goggles, Magnetic Cube). Nos seis o `<img>` quebrava e
 * o card ficava com o ícone estourado do navegador; agora cai na bolsa genérica.
 */
function imgItem(id, px = 34) {
  const el = iconeArquivo(iconeItem(id) ?? ICONE_ITEM_GENERICO, px);
  el.onerror = () => {
    el.onerror = null; // sem isto, um erro no próprio genérico vira laço infinito
    el.src = `/assets/${ICONE_ITEM_GENERICO}`;
  };
  return el;
}

function prioridadeItemInventario(item) {
  if (item?.category === 'revive') return 1;
  if (item?.category === 'heal') return 2;
  return 3;
}

/**
 * O que o NPC paga por uma unidade de item, pelo NOME. Zero = ele não compra.
 *
 * É o que o solver da economia de drop consulta, e espelha `precoDeVendaPorNome` do
 * `content.mjs`: consumível que o NPC vende ele não recompra, e pedra de evolução quem
 * precifica é a comunidade.
 */
function precoDeVendaPorNomeItem(nome) {
  if (itemMortoPorNome(nome)) return 0;
  // `itemPorNome` e não um mapa próprio: é ele que resolve os slugs legados do espelho
  // (`resolverNomeItem`) e carimba o apelido `band-aid`. Um segundo construtor de
  // `estado.itensPorNome` chegando primeiro deixaria o mapa sem esse apelido para sempre.
  const item = itemPorNome(nome);
  if (!item || CATEGORIAS_COMPRAVEIS.has(item.category) || ehPedraEvolucao(item)) return 0;
  return item.npcPrice ?? 0;
}

/** Sucata de drop — não evolui nada; espelha `SUCATA_STONE` do servidor. */

function ehBossTokenItem(item) {
  return !!item && /boss token$/i.test(item.name ?? '');
}

function ehPedraBolsa(item) {
  if (!item) return false;
  if (ehPedraEvolucao(item)) return true;
  return (estado.shinyStone?.pedras ?? []).some((p) => p.itemId === item.id);
}

function ehRaroBolsa(item) {
  if (!item) return false;
  const id = item.id;
  if (ehBossTokenItem(item)) return true;
  if (id === FRAGMENTO_CHAVE_ID || id === FRAGMENTO_SHINY_ID) return true;
  if (id === XP_SHARE_HELD_ID) return true;
  // A Name Tag. Esta lista é de IDS, e não do `rare: true` do catálogo — então um item nosso
  // marcado como raro no servidor cai em "Loots" se ninguém o acrescentar aqui, que é onde a
  // etiqueta de 15 💎 estava indo parar, no meio dos Bug Wings. A descrição da Loja manda o
  // jogador para "Bolsa → Itens raros"; é aqui que essa frase deixa de ser mentira.
  if (id === NAME_TAG_ID) return true;
  if (id === (estado.casas?.fragmento?.itemId ?? FRAGMENTO_CHAVE_ID)) return true;
  if (id === (estado.shinyStone?.fragmentoId ?? FRAGMENTO_SHINY_ID)) return true;
  if (RAR_POR_CASA_ITEM[id]) return true;
  if (id === (estado.bicicletas?.fragmento?.itemId ?? FRAGMENTO_BICICLETA_ID)) return true;
  if (RAR_POR_BICICLETA_ITEM[id]) return true;
  // A REGRA GERAL que faltava: item-chave NOSSO (faixa 70000–70099, ver `itens-nossos.mjs`)
  // marcado `rare: true` no catálogo do servidor. É o que os fragmentos de Mega e de Mega Shiny
  // (drop de boss) não tinham — nenhuma linha acima os citava, e eles caíam em "Loots" no meio
  // das asas e rabos. Com a regra, o próximo fragmento nasce na aba certa sem ninguém lembrar
  // de acrescentá-lo aqui. O `rare` do ESPELHO não serve para isto: ele marca 116 loots comuns.
  if (id >= 70000 && id < 70100 && item.category === 'key-item' && item.rare) return true;
  // O TM inteiro: as peças (drop de boss, ids do espelho) e os discos já trocados no TM Researcher.
  if (id === PIECE_ELEMENTAL_UI || id === PIECE_AOE_UI || item.category === 'tm') return true;
  // A Ficha PvP é o ingresso da arena aberta, como o Boss Token é o do boss — que já mora aqui.
  if (id === PVP_FICHA_ID) return true;
  return false;
}

/** Em qual aba do modal da bolsa cai — treinador, raros, pedras ou loots. */
function categoriaBolsa(ent) {
  if (ent.tipo === 'bola') return 'treinador';
  // A Caixa de Fundador cai em "Itens raros", junto do Fragmento de Chave e do Exp. Share.
  // Uma aba própria seria uma aba vazia para quase todo mundo — e são no máximo 150 caixas
  // no jogo inteiro.
  if (ent.tipo === 'caixa' || ent.tipo === 'casa' || ent.tipo === 'bicicleta') return 'raros';
  const item = ent.item;
  if (!item) return 'loots';
  if (ehItemSkin(item.id)) return 'skins';
  if (item.category === 'heal' || item.category === 'revive') return 'treinador';
  // A Escape Rope é ferramenta de treinador (tira da hunt na hora, pelo botão do palco), não
  // loot: mora com as poções.
  if (item.id === ESCAPE_ROPE_ID) return 'treinador';
  if (ehRaroBolsa(item)) return 'raros';
  if (ehPedraBolsa(item)) return 'pedras';
  if (item.category === 'loot') return 'loots';
  // TM, clan, card, sucata e o resto — bucket de loot/misc por enquanto.
  return 'loots';
}

function entradasBolsa(e) {
  const linhas = [];
  for (const bola of estado.catalogoBolas) {
    const q = e.balls[bola.id] ?? 0;
    if (q > 0) linhas.push({ tipo: 'bola', bola, q });
  }
  // As Caixas de Fundador não vêm de `e.items`: cada uma é uma peça com número próprio e chega
  // numa lista à parte (ver `caixas` no estado). Entram uma por card, e não somadas — a `#01`
  // e a `#02` são coisas diferentes.
  for (const caixa of e.caixas?.minhas ?? []) {
    linhas.push({ tipo: 'caixa', caixa, q: 1 });
  }
  // As Casas, pelo mesmo motivo: peças numeradas, uma por card — a mais rara primeiro, que é a
  // ordem em que o servidor as manda.
  for (const casa of e.casa?.lista ?? []) {
    linhas.push({ tipo: 'casa', casa, q: 1 });
  }
  // As Bicicletas também: cada uma com o número dela, e é pelo número que se equipa.
  for (const bici of e.bicicleta?.lista ?? []) {
    linhas.push({ tipo: 'bicicleta', bici, q: 1 });
  }
  const itens = Object.entries(e.items)
    .filter(([, q]) => q > 0)
    .map(([id, q]) => ({ tipo: 'item', item: estado.itens.get(Number(id)), id: Number(id), q }))
    .sort((a, b) => {
      const pa = prioridadeItemInventario(a.item);
      const pb = prioridadeItemInventario(b.item);
      if (pa !== pb) return pa - pb;
      return (a.item?.name ?? '').localeCompare(b.item?.name ?? '', undefined, { sensitivity: 'base' });
    });
  linhas.push(...itens);

  // Exp. Share: fica visível em Itens raros mesmo com 0 na bolsa — tudo equipado nos pokémon.
  if (xpShareHeldAtivo()) {
    const itemId = xpShareHeldItemId();
    const naBolsa = e.items[itemId] ?? 0;
    const equipados = (e.pokemons ?? []).filter((pk) => ehXpShareHeldItem(pk.heldItemId)).length;
    const existente = linhas.find((x) => x.tipo === 'item' && x.id === itemId);
    if (existente) existente.xshEquipados = equipados;
    else {
      linhas.push({
        tipo: 'item',
        item: estado.itens.get(itemId),
        id: itemId,
        q: naBolsa,
        xshEquipados: equipados,
      });
    }
  }

  return linhas;
}

function assinaturaBolsa() {
  const e = estado.eu;
  if (!e) return '';
  const xshEq = xpShareHeldAtivo()
    ? (e.pokemons ?? []).filter((pk) => ehXpShareHeldItem(pk.heldItemId)).length
    : 0;
  // As caixas entram na assinatura pelos IDS: comprar, abrir ou anunciar uma muda a lista, e
  // sem isto a bolsa só se redesenharia quando um item comum mudasse junto.
  const caixas = (e.caixas?.minhas ?? []).map((c) => c.id).join(',');
  // A aba da OFERENDA não lista item nenhum: ela lista POKÉMON. Sem os ids aqui, capturar (ou
  // vender) um não mexeria na assinatura e a lista do depot ficaria velha até o próximo drop.
  // Só nessa aba, para as outras quatro não pagarem uma varredura da coleção por snapshot.
  // A da COLEÇÃO também, e com o nível e o lugar de cada um (a lista mostra os dois) mais a
  // própria Coleção — é ela que decide quem aparece.
  const abaAtual = estado.abaBolsa ?? 'treinador';
  const pks = abaAtual === 'oferenda'
    ? (e.pokemons ?? []).map((pk) => pk.id).join(',')
    : abaAtual === 'colecao'
      // Da EQUIPE só o id: o nível dela sobe a cada abate e a aba não a mostra.
      ? `${(e.pokemons ?? []).map((pk) => (pk.slot == null ? `${pk.id}:${pk.level}` : `${pk.id}:e`)).join(',')}|${idsPokemonTravadoCliente().join(',')}|${[...colecaoPendente.keys()].join(',')}`
      : abaAtual === 'skins'
        // Na aba Skins o card diz em quem cada skin está — a marcação de cada pokémon entra aqui.
        ? (e.pokemons ?? []).filter((pk) => pk.skin).map((pk) => `${pk.id}:${pk.skin}:${pk.speciesId}`).join(',')
        : '';
  // A CHOCADEIRA entra na conta: um ovo que abre não mexe em `items`, e sem ela a aba ficaria
  // mostrando o ovo chocando depois de o pokémon já estar na Coleção. O ovo escolhido também.
  const choc = estado.abaBolsa === 'chocadeira' ? { c: e.chocadeira ?? null, s: estado.chcOvoSel ?? null } : null;
  return JSON.stringify({ balls: e.balls, items: e.items, caixas, pks, aba: estado.abaBolsa ?? 'treinador', xshEq, choc });
}

function pintarBolsa() {
  if (estado.modalAberto !== 'bolsa') return;
  const assinatura = assinaturaBolsa();
  if (assinatura === estado.assinaturaBolsa) return;
  estado.assinaturaBolsa = assinatura;
  pintarBolsaCorpo();
}

function atualizarBolsa() {
  if (estado.modalAberto !== 'bolsa') return;
  const assinatura = assinaturaBolsa();
  if (assinatura === estado.assinaturaBolsa) return;
  estado.assinaturaBolsa = assinatura;
  pintarBolsaCorpo();
}

// -------------------------------------------------------------- automações

/**
 * Os chips de ITEM da automação: quais revives e quais poções gastar, e em que ordem.
 *
 * Antes eram etiquetas decorativas — todas acesas, nenhuma clicável, e a automação usava o
 * primeiro item da categoria que achasse no inventário. Na prática isso queimava a Hyper
 * Potion antes da Small, que é o contrário do que qualquer um faria à mão.
 *
 * Agora clicar escolhe, e a ORDEM DE CLIQUE é a ordem de gasto: o servidor percorre a lista
 * e usa o primeiro que ainda tem na bolsa. Nada escolhido = "qualquer um", que continua sendo
 * o comportamento de quem nunca abriu isto.
 *
 * Um item que ACABOU mas está escolhido continua na fila, apagado: a preferência é do jogador
 * e não deve sumir porque o estoque zerou no meio de uma hunt.
 */
function chipsDeItens(host, categoria, escolhidos, campo) {
  host.innerHTML = '';
  // TODAS as poções (ou todos os revives) do catálogo, tenha o jogador ou não — igual à
  // fileira de pokébolas logo acima, que sempre mostra as cinco. Antes a lista só trazia o
  // que estava na bolsa, e o painel mudava de tamanho a cada item que acabava: a pessoa
  // marcava a Hyper Potion, gastava a última, e o chip sumia junto com a escolha dela.
  // Quem não tem aparece apagado, com o zero à mostra — que é a informação, não a ausência.
  //
  // Só o que o Market NPC vende (`npcPrice > 0`, o mesmo corte da vitrine dele): a Medicine
  // (`npcPrice: 0`) aparecia aqui como opção de um item que não há onde comprar. Quem já a
  // tinha marcado continua vendo o chip pela lista dos escolhidos, para poder desmarcar.
  const doCatalogo = [...estado.itens.values()].filter((i) => i.category === categoria && i.npcPrice > 0);
  // Os escolhidos primeiro, na ordem escolhida — é ela que vira a ordem de gasto.
  const ordenados = [
    ...escolhidos.map((id) => estado.itens.get(id)).filter(Boolean),
    ...doCatalogo.filter((i) => !escolhidos.includes(i.id)),
  ];

  if (!ordenados.length) {
    host.innerHTML = `<span class="txt-sec-vao">${t('painel.semItens')}</span>`;
    return;
  }
  for (const item of ordenados.slice(0, 10)) {
    const q = estado.eu.items[item.id] ?? 0;
    const on = escolhidos.includes(item.id);
    const b = document.createElement('button');
    b.className = 'auto-chip' + (on ? ' on' : '') + (q ? '' : ' vazio');
    b.title = `${nomeItem(item, item.name)}${q ? '' : ` — ${t('painel.acabou')}`}`;
    b.appendChild(imgItem(item.id, 20));
    const qtd = document.createElement('span');
    qtd.className = 'q';
    qtd.textContent = num(q);
    b.appendChild(qtd);
    b.onclick = () => {
      // `filter`/`push` em vez de `Set`: aqui a ordem É a informação, e um Set só a preserva
      // por acidente. Desmarcar e marcar de novo manda o item para o fim da fila, que é
      // exatamente o que a pessoa quer dizer com isso.
      const ids = escolhidos.includes(item.id)
        ? escolhidos.filter((x) => x !== item.id)
        : [...escolhidos, item.id];
      mandarAutomacao({ [campo]: ids });
    };
    host.appendChild(b);
  }
}

/** Limiar de HP da auto-cura — 10%–100%, passo 10. Espelha `limiarValido` no servidor. */
const LIMIAR_HP_PADRAO = 0.3;

function limiarHpPct(atual) {
  const pct = Math.round(Number(atual) * 100);
  if (!Number.isFinite(pct) || pct < 10 || pct > 100) return Math.round(LIMIAR_HP_PADRAO * 100);
  return Math.round(pct / 10) * 10;
}

function sliderDeLimiar(host, atual) {
  const pct = limiarHpPct(atual);
  let slider = host.querySelector('.auto-limiar-barra');
  if (!slider) {
    host.innerHTML = '';
    const rotulo = document.createElement('span');
    rotulo.className = 'auto-rotulo';
    rotulo.textContent = t('painel.usarQuandoAbaixo');
    host.appendChild(rotulo);

    slider = document.createElement('input');
    slider.type = 'range';
    slider.className = 'auto-limiar-barra qtd-barra';
    slider.min = '10';
    slider.max = '100';
    slider.step = '10';
    host.appendChild(slider);

    const valor = document.createElement('span');
    valor.className = 'auto-limiar-val';
    host.appendChild(valor);

    slider.oninput = () => {
      const p = Number(slider.value);
      valor.textContent = `${p}%`;
      valor.title = t('painel.limiarAjuda', { pct: p });
      slider.title = valor.title;
    };
    slider.onchange = () => {
      const p = Number(slider.value);
      mandarAutomacao({ hpLimiar: p / 100 });
    };
  }
  const valor = host.querySelector('.auto-limiar-val');
  if (Number(slider.value) !== pct) slider.value = String(pct);
  valor.textContent = `${pct}%`;
  valor.title = t('painel.limiarAjuda', { pct });
  slider.title = valor.title;
}

function pintarAutomacoes(e) {
  const a = e.automation;
  const vip = !!e.loja?.vip;

  // Os dois modos de bola são VIP e excludentes. Contas antigas com `autoBall` viram "sem parar".
  const ateCaptura = !!a.autoBallAteCapturar;
  const semParar = !!a.autoBallSemParar || (!!a.autoBall && !ateCaptura);
  $('#auto-ball-captura').checked = ateCaptura && vip;
  $('#auto-ball-sem-parar').checked = semParar && vip;
  // Os dois selos VIP ficam visíveis sempre — marcam que o recurso é de assinatura,
  // igual ao "Lançar sem Parar". Esconder quando o VIP está ativo sumia só o de cima.
  $('#auto-revive').checked = !!a.autoRevive;
  $('#auto-potion').checked = !!a.autoPotion;
  $('#auto-voltar-hunt').checked = !!a.autoVoltarHunt;

  const host = $('#auto-ball-opts');
  host.innerHTML = '';
  for (const bola of estado.catalogoBolas) {
    const q = e.balls[bola.id] ?? 0;
    const on = (a.ballIds ?? []).includes(bola.id);
    const b = document.createElement('button');
    b.className = 'auto-chip' + (on ? ' on' : '') + (q ? '' : ' vazio');
    // O ÍCONE, não o nome. "Pokeball/Greatball/Superball/Ultraball" escritos ocupavam a
    // largura do painel inteiro e ainda assim eram quatro palavras quase iguais de se ler de
    // relance; o desenho da bola se distingue no canto do olho.
    b.appendChild(iconeBola(bola.id, 20));
    const qtd = document.createElement('span');
    qtd.className = 'q';
    qtd.textContent = num(q);
    b.appendChild(qtd);
    b.title = `${bola.nome} — ${t('painel.eficiencia', { n: bola.catchRate })}`;
    b.onclick = () => {
      const ids = (a.ballIds ?? []).includes(bola.id)
        ? a.ballIds.filter((x) => x !== bola.id)
        : [...(a.ballIds ?? []), bola.id];
      mandarAutomacao({ ballIds: ids });
    };
    host.appendChild(b);
  }

  chipsDeItens($('#auto-revive-opts'), 'revive', a.reviveIds ?? [], 'reviveIds');
  sliderDeLimiar($('#auto-limiar'), a.hpLimiar);
  chipsDeItens($('#auto-potion-opts'), 'heal', a.potionIds ?? [], 'potionIds');
  pintarSeloAutomacoes();
}

/** Os interruptores do painel, na ordem em que aparecem. */
const INTERRUPTORES_AUTO = [
  '#auto-ball-captura', '#auto-ball-sem-parar', '#auto-revive', '#auto-potion', '#auto-voltar-hunt',
];

/**
 * O "3/5" no cabeçalho das Automações — só à vista com o painel recolhido.
 *
 * Fechar o painel não pode custar saber que a bola está sendo lançada sozinha: é a automação
 * que gasta item enquanto ninguém olha. Aberto, os próprios interruptores dizem, e o número
 * seria ruído; por isso quem o esconde é o CSS, e não um `if` aqui — assim o valor está certo
 * no instante em que o painel fecha.
 */
function pintarSeloAutomacoes() {
  const selo = $('#auto-cnt');
  if (!selo) return;
  const ligadas = INTERRUPTORES_AUTO.filter((sel) => $(sel)?.checked).length;
  selo.textContent = `${ligadas}/${INTERRUPTORES_AUTO.length}`;
  selo.classList.toggle('aceso', ligadas > 0);
  selo.title = t('painel.autoResumo', { n: ligadas, total: INTERRUPTORES_AUTO.length });
  // O gêmeo do rail. São DOIS nós e não um só porque vivem em caixas diferentes — este é uma
  // plaquinha no canto de um botão de 42 px, aquele é texto ao lado de um título — e cada um
  // precisa do seu lugar no HTML. Quem decide qual está à vista é o CSS.
  const railAuto = $('#auto-cnt-rail');
  if (railAuto) railAuto.textContent = `${ligadas}/${INTERRUPTORES_AUTO.length}`;
}
// Delegado, e não um `onchange` por interruptor: os cinco já têm o seu, e o painel repinta
// inteiro só quando o servidor responde — o número tem de andar junto com o dedo.
$('#p-auto')?.addEventListener('change', pintarSeloAutomacoes);

function mandarAutomacao(patch) {
  enviar({ t: 'auto.set', ...estado.eu.automation, ...patch });
}

/**
 * O convite: o recurso existe, é do VIP, e o botão leva direto ao produto.
 *
 * Aparece no CLIQUE de quem não assina — e não como um interruptor desabilitado. Um controle
 * morto não explica nada; esta caixa diz o que o recurso faz, que ele é do VIP e abre a Loja
 * na categoria certa.
 */
function convidarParaOVip() {
  // O VIP como vitrine: o selo dourado no palco e cada vantagem numa linha com o seu desenho —
  // "o que eu ganho" lido de relance, em vez de um parágrafo de propaganda.
  confirmar({
    titulo: t('vip.tituloConvite'),
    texto: `
      ${dlgPalco(dlgAtor({ arte: dlgArteArquivo(ICONE_VIP_PASSE, 64), nome: 'VIP', classe: 'novo' }), 'ouro')}
      ${dlgLista([
        { arte: `<span data-dlg-arquivo="${SPRITE_BOLA[1]}" data-dlg-px="22"></span>`, html: t('vip.perkCatch') },
        { icone: 'subir', html: t('vip.perkXp') },
        { icone: 'pessoa', html: t('vip.perkOutfit') },
        { icone: 'brilho', html: t('vip.perkEmojis') },
      ])}`,
    rotuloSim: t('vip.irParaLoja'),
    aoConfirmar: () => {
      // Abre a Loja já na seção do VIP — é o produto que o convite acabou de vender.
      estado.grupoLoja = 'vip';
      estado.boostLoja = '';
      abrirModal('shop');
    },
  });
}

function alternarAutoBall(modo, ligado) {
  if (ligado && !estado.eu?.loja?.vip) return convidarParaOVip();
  const patch = modo === 'captura'
    ? { autoBallAteCapturar: ligado, autoBallSemParar: false }
    : { autoBallSemParar: ligado, autoBallAteCapturar: false };
  mandarAutomacao(patch);
}

$('#auto-ball-captura').onchange = (ev) => {
  if (ev.target.checked && !estado.eu?.loja?.vip) {
    ev.target.checked = false;
    return convidarParaOVip();
  }
  if (ev.target.checked) $('#auto-ball-sem-parar').checked = false;
  alternarAutoBall('captura', ev.target.checked);
};
$('#auto-ball-sem-parar').onchange = (ev) => {
  if (ev.target.checked && !estado.eu?.loja?.vip) {
    ev.target.checked = false;
    return convidarParaOVip();
  }
  if (ev.target.checked) $('#auto-ball-captura').checked = false;
  alternarAutoBall('semParar', ev.target.checked);
};
$('#auto-revive').onchange = (ev) => mandarAutomacao({ autoRevive: ev.target.checked });
$('#auto-voltar-hunt').onchange = (ev) => mandarAutomacao({ autoVoltarHunt: ev.target.checked });
$('#auto-potion').onchange = (ev) => mandarAutomacao({ autoPotion: ev.target.checked });

// ---------------------------------------------------------------- eventos

function logCena(txt) {
  const el = document.createElement('div');
  el.textContent = txt;
  $('#hud-log').prepend(el);
  while ($('#hud-log').children.length > 6) $('#hud-log').lastChild.remove();
}

// ------------------------------------------------------- derrotados no chão
//
// Quem cai fica caído por 30 s antes de sumir. Nessa janela dá para arremessar bola no
// corpo — é assim que se captura de verdade, já que bater primeiro derruba o HP a zero e
// a chance por arremesso é a melhor possível nesse ponto.
//
// A lista é redesenhada por timer (não por evento): o tempo de chão corre sozinho e a
// barrinha precisa andar mesmo quando nada chega do servidor.

const TEMPO_CHAO_MS = 30000;

/**
 * O nível com que ESTE corpo entraria na equipe — ou `null` quando o teto não corta nada.
 *
 * O pacote de campo não carrega `speciesId` (ver `serializarMob`: é o pacote mais caro do
 * jogo e o nome já vai nele), então a espécie sai de `especiePorNome`. Os clones `13xxx` de
 * Hoenn dividem o nome com a linha nacional, e isso não muda a resposta: as duas entradas têm
 * a mesma cadeia, logo o mesmo teto.
 */
function nivelDeCapturaVisivel(nome, level) {
  if (!(level > TETO_CAPTURA_MAX)) return null;
  const esp = estado.especiePorNome.get(nome);
  const cap = nivelDeCaptura(level, esp?.tetoCaptura ?? TETO_CAPTURA_MAX);
  return cap < level ? cap : null;
}

/** Bola escolhida para o arremesso manual. Fica a mais fraca que ele tenha, por padrão. */
function bolaEscolhida() {
  const tem = (id) => (estado.eu?.balls?.[id] ?? 0) > 0;
  if (estado.bolaCaidos && tem(estado.bolaCaidos)) return estado.bolaCaidos;
  return estado.catalogoBolas.find((b) => tem(b.id))?.id ?? null;
}

function pintarCaidos() {
  const painel = $('#caidos');
  const corpos = estado.campo?.corpos() ?? [];
  if (!corpos.length || !estado.eu) return painel.classList.add('hidden');
  painel.classList.remove('hidden');

  // seletor de bola: só as que ele tem
  const escolhida = bolaEscolhida();
  const disponiveis = estado.catalogoBolas.filter((b) => (estado.eu.balls?.[b.id] ?? 0) > 0);
  const assinaturaBolas = disponiveis.map((b) => `${b.id}:${estado.eu.balls[b.id]}`).join(',') + `|${escolhida}`;
  if (assinaturaBolas !== estado.assinaturaBolasCaidos) {
    estado.assinaturaBolasCaidos = assinaturaBolas;
    const host = $('#caidos-bolas');
    host.innerHTML = '';
    for (const b of disponiveis) {
      const bt = document.createElement('button');
      bt.className = 'caidos-bola' + (b.id === escolhida ? ' on' : '');
      bt.title = `${b.nome} — você tem ${num(estado.eu.balls[b.id])}`;
      bt.appendChild(iconeBola(b.id, 18));
      bt.onclick = () => {
        estado.bolaCaidos = b.id;
        estado.assinaturaBolasCaidos = null;
        pintarCaidos();
      };
      host.appendChild(bt);
    }
  }

  // lista de corpos: reaproveita a linha que já existe, para o sprite não recarregar
  const lista = $('#caidos-lista');
  const vistos = new Set();
  for (const c of corpos.slice(0, 6)) {
    vistos.add(String(c.slot));
    let linha = lista.querySelector(`[data-slot="${c.slot}"]`);
    if (!linha) {
      linha = document.createElement('button');
      linha.className = 'caido';
      linha.dataset.slot = c.slot;
      // O nível que ele VAI TER na bola, quando o teto corta. É a única hora em que o jogador
      // ainda pode decidir se gasta a bola — descobrir depois, com o bicho já no depot, é o
      // caminho para achar que a captura veio bugada.
      const capturado = nivelDeCapturaVisivel(c.nome, c.level);
      // O nome vai num `<span>` próprio para o "→ Nv" NUNCA ser o pedaço cortado: no celular a
      // carta tem 150 px e a reticência come o fim da linha. Quem pode encolher é o nome da
      // espécie, que o sprite ao lado já identifica.
      linha.innerHTML = `
        <span class="caido-info">
          <span class="caido-nome">
            <span class="caido-quem">${c.nome} <b>Nv${c.level}</b></span>${
            capturado ? `<em class="caido-teto">${t('cena.tetoCaptura', { nv: num(capturado) })}</em>` : ''
          }</span>
          <span class="caido-tempo"><i></i></span>
        </span>`;
      linha.prepend(spritePokemon(c, 26));
      linha.title = capturado
        ? `${t('cena.arremessarCaido')} — ${t('cena.tetoCapturaTitulo', { nv: num(capturado) })}`
        : t('cena.arremessarCaido');
      linha.onclick = () => {
        const bola = bolaEscolhida();
        if (!bola) return toast(t('ev.semBola'));
        enviar({ t: 'ball.throw', ballId: bola, slot: c.slot });
      };
      lista.appendChild(linha);
    }
    linha.querySelector('.caido-tempo i').style.width = `${(c.resta / TEMPO_CHAO_MS) * 100}%`;
    linha.classList.toggle('acabando', c.resta < 6000);
  }
  for (const linha of [...lista.children]) {
    if (!vistos.has(linha.dataset.slot)) linha.remove();
  }
}

setInterval(pintarCaidos, 250);

function textoSelvagemDerrotado(e) {
  const auto = e.vendaAuto ?? [];
  const vendidos = new Set(auto.map((x) => x.nome));
  const drops = e.drops?.length
    ? ` · ${e.drops.map((x) => `${x.nome}×${x.qtd}${vendidos.has(x.nome) ? ' (auto)' : ''}`).join(', ')}`
    : '';
  return t('ev.selvagemDerrotado', {
    nome: e.nome ?? 'selvagem',
    xpTreinador: num(e.xpTreinador ?? e.xp),
    xpPokemon: num(e.xpPokemon ?? e.xp),
    ouro: num((e.ouro ?? 0) + (e.ouroVendaAuto ?? 0)),
    lootBoost: e.lootBoost ? t('ev.lootBoostTag') : '',
    drops,
  });
}

function aoEvento(e) {
  registrarSessao(e);
  const c = estado.campo;
  switch (e.k) {
    case 'spawn':
      if (estado.eu?.huntSlug && !estado.eu?.noCentro && !estado._spawnOndaAtual) {
        estado.ondaSeq = (estado.ondaSeq ?? 0) + 1;
        estado._spawnOndaAtual = true;
      }
      break;
    case 'ataque':
      c?.golpe(e);
      // Golpe MEU (hunt/boss = 'jogador', arena = 'pvp'): arma o relógio de cooldown do painel
      // de golpes do palco. O que o selvagem/oponente bate de volta não tem ícone para acender.
      if (e.por === 'jogador' || e.por === 'pvp') registrarUsoDeGolpe(e.golpe);
      // Dano trocado rearma a contagem de 3 s da saída da hunt, nos dois sentidos: o que eu
      // apliquei e o que eu levei. Mesma regra do servidor.
      rearmarCombate();
      break;
    case 'morte':
      if (e.quem === 'selvagem') {
        logCena(textoSelvagemDerrotado(e));
        if (e.drops?.some((d) => d.nome === 'Bronze Boss Token' || d.itemId === 70000)) {
          toast('Bronze Boss Token!');
        }
      } else {
        c?.texto('desmaiou!', '#ff5b3a');
        logCena(t('ev.desmaiou'));
      }
      break;
    case 'bola':
      // Na Arena Mística a bola pode ter saído sozinha (o prazo acabou): a escolha, se aberta, some.
      if (estado.eu?.mistico) fecharEscolhaMisticaSeAberta();
      c?.bola(e.sucesso, e.slot, e.ballId);
      break;
    case 'fugiu':
      logCena(t('ev.escapou', { nome: e.nome, nivel: e.level }));
      break;
    case 'capturado':
      if (e.pokemon.shiny) {
        // O som da vitória. Sai SÓ aqui: este evento chega no fluxo de batalha do dono da bola,
        // enquanto o `shiny.captura` do chat é o anúncio para o servidor inteiro. Pendurar o
        // efeito lá faria o jogo tocar no navegador de quem não capturou nada.
        if (somShinyLigado()) tocarShinyCaptura();
        logCena(t('ev.shinyCapturado', { nome: e.pokemon.nome, nivel: e.pokemon.level, qualidade: e.pokemon.quality }));
        toast(e.paraDepot
          ? t('ev.shinyCapturadoDepot', { nome: e.pokemon.nome })
          : t('ev.shinyCapturadoToast', { nome: e.pokemon.nome }));
      } else {
        if (somCapturaLigado()) tocarCaptura();
        logCena(t('ev.capturado', { nome: e.pokemon.nome, nivel: e.pokemon.level, qualidade: e.pokemon.quality }));
        toast(e.paraDepot ? `${e.pokemon.nome} capturado — foi para o Depot` : `${e.pokemon.nome} capturado!`);
      }
      // O teto cortou: o servidor manda o nível que ele TINHA no chão. Uma linha a mais no log,
      // e só quando corta — em Kanto este campo nunca vem.
      if (e.levelSelvagem) {
        logCena(t('ev.capturadoTeto', { nome: e.pokemon.nome, de: num(e.levelSelvagem), para: num(e.pokemon.level) }));
      }
      break;
    case 'levelup':
      c?.texto(e.quem === 'treinador' ? `Treinador Nv ${e.level}!` : `Nv ${e.level}!`, '#ffd166');
      logCena(e.quem === 'treinador' ? `você subiu para o nível ${e.level}` : `seu pokémon subiu para o nível ${e.level}`);
      break;
    case 'evolucao':
      toast(t('ev.evolveu', { de: e.de, nome: e.nome }));
      logCena(t('ev.evolveu', { de: e.de, nome: e.nome }));
      c?.texto(t('ev.evolveuCurto', { nome: e.nome }), '#c8a8ff');
      if (estado.eu?.activeId === e.id && deveUsarHeroiPokemon(estado.eu)) aplicarHeroiAtivo(estado.eu);
      if (estado.modalAberto === 'pokedex') ligarPokedex();
      break;
    // A MEGA é a mesma cena da evolução, em dourado — a cor da áurea das Mega Stones, para o
    // jogador distinguir de longe as duas coisas que trocam a espécie do bicho dele.
    case 'mega':
      toast(t('mega.feita', { de: e.de, nome: e.nome }));
      logCena(t('mega.feita', { de: e.de, nome: e.nome }));
      c?.texto(t('ev.evolveuCurto', { nome: e.nome }), '#ffd34d');
      if (estado.eu?.activeId === e.id && deveUsarHeroiPokemon(estado.eu)) aplicarHeroiAtivo(estado.eu);
      if (estado.modalAberto === 'pokedex') ligarPokedex();
      break;
    case 'bossEntrou':
      // A entrada zera `p.cdGolpes` no servidor. O evento chega ANTES do primeiro `ataque` do
      // boss (é a ordem da fila de eventos), então zerar aqui não apaga o golpe de abertura —
      // ver o comentário em `aplicarEstado`.
      zerarCooldownsDaUI();
      logCena(`⚔️ ${e.nome} — dano recebido ×${num(Math.round(e.penalidade.mult))}`);
      toast(`Arena de ${e.nome}!`);
      if (e.auto) fecharBossLoot();
      break;
    case 'bossMorto': {
      const d = e.drops?.length ? e.drops.map((x) => `${x.nome}×${x.qtd}`).join(', ') : 'nada';
      logCena(t('ev.bossMorto', {
        nome: e.nome,
        xpTreinador: num(e.xpTreinador ?? e.xp),
        xpPokemon: num(e.xpPokemon ?? e.xp),
        drops: d,
        lootBoost: e.lootBoost ? t('ev.lootBoostTag') : '',
      }));
      c?.texto('BOSS DERROTADO!', '#ffd166');
      // A PEÇA DE TM (Elemental ou AoE) toca o som próprio. O evento é só de quem derrotou o boss.
      if (somTmBossLigado() && dropouPecaDeTm(e.drops)) tocarTmBossDrop();
      // Contador "Vezes derrotado": o snapshot com o número novo chega logo atrás, mas pode
      // levar até meio segundo — então já incrementamos aqui, na mão, para a aba Bosses (se
      // estiver aberta) não mostrar o valor velho nesse intervalo.
      if (e.key && estado.eu?.boss) {
        const v = (estado.eu.boss.vitorias ??= {});
        v[e.key] = (Number(v[e.key]) || 0) + 1;
        if (estado.modalAberto === 'bosses') atualizarContadorBoss(e.key);
      }
      // Repetição automática: o sim cura no Centro e entra de novo — o modal "Continuar"
      // prende a tela e faz parecer que o auto quebrou.
      //
      // A PEÇA DE TM e os dois FRAGMENTOS DE MEGA ganham tela própria antes do resumo, em fila
      // (ver `revelarDropsDoBoss`). No automático só o que caiu aparece, empilhado, e a vitória
      // entra no placar da série (`loteBoss`), que vira o resumo quando o automático desligar.
      if (e.auto || estado.eu?.boss?.auto) {
        fecharBossLoot();
        somarNoLoteBoss(e.drops);
        revelarDropsDoBoss(e, { auto: true });
      } else if (!revelarDropsDoBoss(e, { aoFechar: () => abrirModalBossLoot(e) })) {
        abrirModalBossLoot(e);
      }
      break;
    }
    case 'bossPerdeu': logCena(t('ev.bossPerdeu', { nome: e.nome })); break;
    case 'bossSaiu': logCena(t('ev.bossSaiu')); break;
    // ---- Arena Mística
    case 'misticoEntrou':
      zerarCooldownsDaUI();
      misticoEscolha = null;
      fecharModal();
      logCena(t('mistico.entrouLog', { nome: e.nome, nivel: e.level ?? NIVEL_LENDARIO_MISTICO }));
      toast(t('mistico.entrouToast', { nome: e.nome }));
      break;
    case 'misticoCaiu':
      logCena(t('mistico.caiuLog', { nome: e.nome }));
      abrirEscolhaBolaMistica(e);
      break;
    case 'misticoFim':
      fecharEscolhaMisticaSeAberta();
      logCena(t(e.capturou ? 'mistico.capturouLog' : 'mistico.escapouLog', { nome: e.nome }));
      revelarFimMistico(e);
      break;
    case 'misticoPerdeu':
      fecharEscolhaMisticaSeAberta();
      logCena(t('mistico.perdeu', { nome: e.nome }));
      toast(t('mistico.perdeu', { nome: e.nome }));
      break;
    case 'misticoSaiu':
      fecharEscolhaMisticaSeAberta();
      logCena(t('mistico.saiu', { nome: e.nome }));
      break;
    // ---- Chocadeira
    case 'ovoColocado':
      toast(t('chocadeira.colocado', {
        ovo: nomeItem(OVO_POR_ID.get(e.ovo)?.itemId ?? 0, e.ovo), n: (Number(e.slot) || 0) + 1, quando: quandoAbre(e.fim),
      }));
      break;
    case 'ovoChocou':
      logCena(t('chocadeira.chocouLog', { nome: e.pokemon?.nome ?? '' }));
      revelarOvoChocado(e);
      break;
    case 'bossAuto':
      // Chega tanto do clique quanto do desligamento automático (acabaram os tokens). Nos dois
      // casos a ficha aberta precisa refletir o novo estado do interruptor — ela não remonta
      // sozinha a cada snapshot, senão a lista de 87 bosses perderia a rolagem.
      logCena(e.ativo ? t('ev.bossAutoLigado') : t('ev.bossAutoDesligado'));
      if (estado.modalAberto === 'bosses') pintarFichaDoBoss();
      // Ligou: série nova, placar do zero. Desligou (tokens no fim ou o jogador parou): o resumo.
      if (e.ativo) zerarLoteBoss();
      else fecharSerieDoBoss();
      break;
    case 'avatarTrocado':
      toast(t('av.trocado'));
      break;
    case 'evento':
      // O buff global entrou ou saiu. A faixa em si é desenhada pelo snapshot que vem logo
      // atrás; aqui é só o anúncio, que merece um toast por ser uma notícia e não um estado.
      if (e.evento) {
        toast(t('evt.comecou'));
        logCena(textoDoEvento(e.evento));
      } else {
        logCena(t('evt.acabou'));
      }
      break;
    case 'tmTrocado':
      toast(t('tm.trocado'));
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      break;
    case 'tmAplicado':
      toast(t('tm.aplicado', { nome: e.nome }));
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      break;
    case 'refino': {
      // `rotuloStat` e não `toUpperCase()`: o servidor manda a CHAVE (`spAtk`), e um
      // "SPATK" no toast não é o rótulo que o jogo usa em lugar nenhum.
      const rot = rotuloStat(e.stat);
      toast(t('ev.refinado', { nome: e.nome, stat: rot, n: num(e.nivel) }));
      logCena(t('ev.refinado', { nome: e.nome, stat: rot, n: num(e.nivel) }));
      c?.texto(`+${num(e.nivel)} ${rot}`, '#c8a8ff');
      // Quem redesenha a bancada e a ficha é `atualizarTelasDeRefino`, no snapshot seguinte:
      // no mesmo pacote os EVENTOS vêm antes do ESTADO, então aqui os números ainda são os
      // de antes da compra.
      break;
    }
    case 'nivelReduzido': {
      // Sem texto flutuante no campo: o pokémon que caiu de nível quase nunca é o que está
      // lutando — a ficha se abre do Depot, e quem está travado por nível nem consegue pôr
      // o bicho em campo. Um "−1 Nv" pairando sobre outro pokémon seria uma mentira visual.
      const frase = t('ev.nivelReduzido', { nome: e.nome, nv: num(e.para), xp: num(e.xpPerdido) });
      toast(frase);
      logCena(frase);
      break;
    }

    // ------------------------------------------------------------------ PvP
    case 'pvpEntrou':
      logCena(t('ev.pvpEntrou', { arena: e.arena, dentro: e.dentro }));
      toast(t('ev.pvpLute', { arena: e.arena }));
      break;
    case 'pvpAbate':
      c?.texto(`+${e.delta} ELO`, '#3ddc84');
      logCena(t('ev.pvpAbate', { alvo: e.alvo, elo: num(e.elo), delta: `${e.delta >= 0 ? '+' : ''}${e.delta}` }));
      break;
    case 'pvpMorte':
      c?.texto(`${e.delta} ELO`, '#ff5b3a');
      logCena(
        t('ev.pvpMorte', { por: e.por, elo: num(e.elo), delta: e.delta, xp: num(e.xpPerdido) }),
      );
      toast(t('ev.pvpMorteToast', { por: e.por, delta: e.delta, xp: num(e.xpPerdido) }));
      break;
    case 'pvpSaiu': {
      const min = Math.max(1, Math.round((e.cooldownAte - Date.now()) / 60000));
      logCena(
        e.motivo === 'morreu'
          ? t('ev.pvpExpulso', { min })
          : t('ev.pvpSaiu', { min }),
      );
      break;
    }
    case 'guildCriada':
      toast(t('ev.guildCriada', { nome: e.nome }));
      montarGuildPainel();
      break;
    case 'guildConviteEnviado':
      toast(t('ev.guildConviteEnviado', { nick: e.nick }));
      break;
    case 'guildConviteRecebido':
      toast(t('ev.guildConviteRecebido'));
      break;
    case 'guildPedidoRecebido':
      toast(t('ev.guildPedidoRecebido'));
      break;
    case 'guildEntrou':
      toast(t('ev.guildEntrou', { nome: e.nome }));
      // A aba volta para Membros: quem acabou de entrar quer ver com quem, e ele pode ter
      // chegado aqui a partir do Quadro, que continua existindo no painel de dentro.
      guildAba = 'membros';
      montarGuildPainel();
      break;
    case 'guildSaiu':
      toast(t('ev.guildSaiu'));
      // Não fecha mais a janela: `aoReceberGuild` troca para o painel do Quadro no mesmo pacote
      // (`guild: null`), que é para onde quem acabou de sair está indo.
      break;
    case 'guildExpulsou':
      toast(t('ev.guildExpulsou'));
      break;
    case 'guildLiderTransferido':
      toast(t('ev.guildLiderTransferido', { nick: e.nick ?? '' }));
      break;
    case 'guildApagada':
      toast(t('ev.guildApagada'));
      fecharGuild();
      break;
    case 'guildRegistrada':
      toast(t(e.amanha ? 'ev.guildRegistradaAmanha' : 'ev.guildRegistrada'));
      enviar({ t: 'guild.pvp.info' });
      break;

    // ------------------------------------------------------------------ amigos
    case 'amigoPedidoEnviado':
      toast(t('ev.amigoPedidoEnviado', { nick: e.nick }));
      if (estado.perfilOutroNick && e.nick?.toLowerCase() === estado.perfilOutroNick.toLowerCase()) {
        repintarAcoesPerfilOutro(estado.perfilOutroNick);
      }
      break;
    case 'amigoPedidoRecebido':
      toast(t('ev.amigoPedidoRecebido', { nick: e.nick }));
      break;
    case 'amigoAceito':
      toast(t('ev.amigoAceito', { nick: e.nick }));
      if (estado.perfilOutroNick && e.nick?.toLowerCase() === estado.perfilOutroNick.toLowerCase()) {
        repintarAcoesPerfilOutro(estado.perfilOutroNick);
      }
      break;
    case 'amigoRemovido':
      toast(t('ev.amigoRemovido', { nick: e.nick }));
      if (estado.perfilOutroNick && e.nick?.toLowerCase() === estado.perfilOutroNick.toLowerCase()) {
        repintarAcoesPerfilOutro(estado.perfilOutroNick);
      }
      break;
    case 'amigoCoinsEnviou':
      toast(t('ev.amigoCoinsEnviou', { nick: e.nick, v: num(e.valor), liq: num(e.liquido) }));
      break;
    case 'amigoCoinsRecebeu':
      toast(t('ev.amigoCoinsRecebeu', { nick: e.nick, v: num(e.valor) }));
      break;
    case 'guildEquipeSalva':
      toast(t('ev.guildEquipeSalva'));
      fecharEditorEquipeGuerra();
      break;
    case 'guildEscalacaoSalva':
      estado.guildSalvandoEscalacao = false;
      toast(t('guild.escalacaoSalva'));
      break;
    // A guerra acabou de rodar no servidor. Chega para quem estava online no momento — os
    // outros veem o resultado no painel de PvP quando entrarem.
    case 'guildWarResultado':
      toast(
        e.venceu
          ? t('ev.guildWarVenceu', { guild: e.guild, gp: num(e.gp ?? 0) })
          : t('ev.guildWarColocacao', { pos: e.pos, total: e.total, gp: num(e.gp ?? 0) }),
      );
      logCena(t('ev.guildWarLog', { pos: e.pos, total: e.total }));
      enviar({ t: 'guild.pvp.info' });
      break;
    // A MEDALHA DE GUERRA acabou de ser carimbada num bicho SEU: ele foi o Pokémon da Guerra
    // de hoje. Chega em qualquer shard (o aviso é do `CANAL_GUILD`), e o número novo já veio
    // no mesmo pacote de estado — aqui é só a comemoração.
    case 'trofeuCampeonato': {
      const trofeu = t(`trofeu.${e.tipo === 'amador' ? 'amador' : 'mundial'}`);
      toast(t('ev.trofeuCampeonato', { nome: e.nome, trofeu }));
      logCena(t('ev.trofeuCampeonato', { nome: e.nome, trofeu }));
      break;
    }
    case 'medalhaGuerra':
      toast(t('ev.medalhaGuerra', { nome: e.nome, n: num(e.total ?? 1) }));
      logCena(t('ev.medalhaGuerraLog', { nome: e.nome, n: num(e.total ?? 1) }));
      break;
    // O PRÊMIO DO MÊS da Temporada Global de Guilds caiu na carteira. O anúncio do fechamento
    // vai para o chat do servidor inteiro no mesmo segundo, e sem este aviso o premiado lia lá
    // que tinha recebido sem ver nada mudar na tela. O saldo novo vem no mesmo pacote de estado
    // (o sim releu o ledger antes de avisar) — aqui é só a comemoração, e a Loja aberta na hora
    // precisa redesenhar o que ela mostra de saldo, como no crédito de compra.
    case 'guildGlobalPremio':
      toast(t('ev.guildGlobalPremio', { qtd: num(e.qtd) }));
      logCena(t('ev.guildGlobalPremio', { qtd: num(e.qtd) }));
      if (estado.modalAberto === 'shop') montarLoja();
      if (estado.modalAberto === 'diamantes') atualizarDiamantes(estado.eu ?? {}, {});
      break;
    case 'starter': logCena(t('ev.starter', { nome: e.nome, nivel: e.level })); toast(t('ev.starterEscolhido', { nome: e.nome })); break;
    // Troca que o SERVIDOR decidiu: o suplente de um nocaute, na hunt e na arena. O evento chega
    // antes do primeiro `ataque` do suplente, então a pausa da recarga pega o pokémon certo sem
    // esperar o snapshot.
    case 'troca':
      sincronizarCooldownsDaUI(e.id);
      logCena(t('ev.troca', { nome: e.nome }));
      break;
    // "Nocauteado" só quando o time caiu de verdade: chegar ao Centro a pé, saindo do PvP ou
    // entrando no jogo é outra frase. A antiga anunciava um nocaute que não tinha acontecido.
    case 'centro':
      logCena(t(
        e.motivo === 'desistencia' ? 'ev.centroDesistiu'
          : e.motivo === 'morte' ? 'ev.centro'
            : e.motivo === 'vitoria' ? 'ev.centroVitoria'
              : 'ev.centroChegou',
      ));
      break;
    case 'xpPerdido':
      if (e.qtd > 0) logCena(t('ev.xpPerdido', { xp: num(e.qtd) }));
      break;
    // A enfermeira falando, em balão na cena. Se a fala chegar antes de a praça estar montada
    // (ou o jogador já tiver saído), `falarEnfermeira` simplesmente não acha ninguém.
    case 'joy': estado.campo?.falarEnfermeira(FALAS_DA_JOY[e.fala]?.() ?? ''); break;
    case 'curado':
      logCena(t('ev.curado'));
      toast(t('ev.timeCurado'));
      // A enfermeira cura o HP e nada mais: a recarga dos golpes NÃO é zerada aqui (ver
      // `curarEquipeNoCentro` no sim). Ela está pausada enquanto o pokémon não está em campo,
      // então o tempo no Centro não custa nada — e o painel continua de onde parou.
      if (estado.eu?.boss?.auto) fecharBossLoot();
      break;
    case 'revive': logCena(t('ev.revive')); break;
    case 'cura': logCena(t('ev.pocao')); break;
    case 'hunt':
      // Só a entrada pelo Mapa traz o carimbo — a volta automática depois de morrer não fecha a porta.
      if (e.trocaLivreEm) estado.trocaHuntLivreEm = e.trocaLivreEm;
      logCena(t('ev.hunt', { nome: e.nome }));
      break;
    // A automação de voltar à hunt travou por falta de item. Vai no LOG e em toast: quem
    // deixou farmando de madrugada lê o log de manhã, e quem está olhando precisa do aviso
    // agora — sem um dos dois, a única pista seria o treinador parado no Centro.
    case 'autoHuntSemItens':
      logCena(t('ev.autoHuntSemItens'));
      toast(t('ev.autoHuntSemItensToast'));
      break;
    case 'outlandTier':
      logCena(t('ev.outlandTier', { nome: e.nome }));
      toast(t('ev.outlandTier', { nome: e.nome }));
      break;
    case 'compra': toast(t('ev.compra', { nome: e.nome, qtd: e.qtd, gasto: num(e.gasto ?? 0) })); break;
    case 'venda': toast(t('ev.venda', { nome: e.nome, ganho: num(e.ganho) })); break;
    case 'descarte': toast(t('ev.descarte', { nome: e.nome, qtd: num(e.qtd) })); break;
    case 'marketCriado':
      toast(t('ev.marketCriado', { descricao: e.descricao }));
      // A casa anunciada soltou os pokémon dos postos no ato — dito na hora, não descoberto depois.
      if (e.soltosCasa) toast(t(e.soltosCasa === 1 ? 'casa.soltoAoAnunciar' : 'casa.soltosAoAnunciar', { n: e.soltosCasa }));
      break;
    case 'marketCancelado': toast(t('ev.marketCancelado')); break;
    // O prazo da vitrine acabou (ou o servidor fechou o anúncio por regra: curadoria, preço
    // abaixo do mínimo) e a mercadoria voltou — na hora, ou no login de quem estava fora.
    //
    // `marketDevolvidoColecao` é o pokémon que caiu abaixo da nota mínima da vitrine: ele volta
    // GUARDADO, e o aviso diz isso — quem o procurasse na aba de venda do Depot não o acharia.
    case 'marketExpirou':
    case 'marketDevolvido':
    case 'marketDevolvidoColecao':
      toast(t(`ev.${e.k}`, { descricao: e.descricao }));
      if (estado.modalAberto === 'community' && estado.cmAba === 'meus') pedirMercado();
      break;
    // A vitrine é repedida DAQUI, e não empurrada pelo servidor: só o cliente sabe em que
    // filtro e em que ordenação a tela está. O anúncio pode ter só encolhido (compra parcial),
    // então redesenhar é obrigatório mesmo quando ele não sumiu.
    case 'marketComprado':
      toast(t(e.trancado ? 'ev.marketCompradoTrancado' : 'ev.marketComprado', { descricao: e.descricao }));
      if (estado.modalAberto === 'community') pedirMercado();
      break;
    // A venda acontece com o vendedor OFFLINE — este aviso é o "enquanto você não estava".
    case 'marketVendido':
      toast(t('ev.marketVendido', {
        descricao: e.descricao,
        valor: e.moeda === 'orb' ? `${num(e.valor)} ${t('moeda.gemas')}` : num(e.valor),
      }));
      break;
    case 'orbsSaque':
      toast(`${t('orbs.pedirSaque')}: ${num(e.orbs)} ${t('moeda.gemas')}`);
      break;
    case 'orbsEstorno':
      toast(`${t('orbs.tipoEstorno')}: +${num(e.orbs)} ${t('moeda.gemas')}`);
      break;
    // O pagamento fechou por webhook, com o jogador já dentro do jogo: o sim recolheu o
    // crédito na varredura e avisa aqui. É o fim do caminho que começou no botão de PIX.
    case 'diamantesCreditados':
      toast(
        e.metodo === 'admin' && Number(e.qtd) < 0
          ? t('diamantes.debitadosAdmin', { qtd: num(Math.abs(Number(e.qtd))) })
          : t('diamantes.creditados', { qtd: num(e.qtd) }),
      );
      if (estado.modalAberto === 'shop') montarLoja();
      if (estado.modalAberto === 'diamantes') atualizarDiamantes(estado.eu ?? {}, {});
      break;
    // O voto no TopIdle fechou e o webhook creditou. O número da tela mudou de verdade, então
    // o painel é relido na marra — o cache de cinco minutos ficaria mostrando o anterior.
    case 'votoCreditado':
      toast(t('voto.creditado', { qtd: num(e.qtd) }));
      atualizarVoto(true).then(() => {
        if (estado.modalAberto === 'votar') montarVotar();
      });
      break;
    // O VIP de boas-vindas de quem criou a conta pelo link de um Referral Especial. O VIP em si já
    // veio no welcome (`vipAte`); isto é a comemoração, com o nome de quem trouxe o jogador.
    case 'vipBoasVindas':
      mostrarRecompensa({
        nivel: 2,
        faixa: t('vipRef.faixa'),
        lead: t('vipRef.lead', { padrinho: String(e.padrinho ?? '') }),
        nome: t('vipRef.nome', { tempo: diasDeVip(e.horas) }),
        sub: escapar(t('vipRef.sub')),
        arte: imagemRecompensa(srcIcone(ICONE_VIP_PASSE), 'rc-img-pixel'),
      });
      break;
    // Um resgate na Kick virou hora de bônus (o vigia creditou e o sim recebeu as horas novas). As
    // horas em si chegam pelo snapshot; isto é só o aviso de qual foi e até quando vale.
    case 'kickBonus': {
      const pct = Number(estado.eu?.kick?.pct) || 0;
      const nome = TIPOS_KICK_TELA.includes(e.tipo) ? t(`kick.bonus.${e.tipo}`, { pct }) : t('kick.linha');
      toast(t('kick.creditado', {
        nome,
        canal: e.canal || 'Kick',
        tempo: tempoCurto(Math.max(0, (Number(e.ate) || 0) - agoraDoServidor())),
      }));
      break;
    }
    case 'afiliadoComissao':
      toast(e.tipo === 'gema'
        ? t('af.comissaoGema', { qtd: num(e.qtd) })
        : t('af.comissaoDia', { qtd: num(e.qtd) }));
      if (estado.modalAberto === 'afiliados') montarAfiliados();
      break;
    case 'afiliadoRecolhido': {
      const partes = [];
      if (e.diamantes > 0) partes.push(t('af.recolhidoDia', { qtd: num(e.diamantes) }));
      if (e.gemas > 0) partes.push(t('af.recolhidoGema', { qtd: num(e.gemas) }));
      toast(partes.join(' · ') || t('af.recolhido'));
      afiliado.painel = null;
      pintarSeloAfiliado({ podeRecolher: false });
      sincronizarMobile();
      if (estado.modalAberto === 'afiliados') montarAfiliados();
      break;
    }
    case 'lojaCompra':
      toast(`${t('loja.comprado')}: ${e.nome}`);
      if (estado.modalAberto === 'shop') montarLoja();
      // O Fragmento de Chave comprado muda o contador do teto na tela da Casa.
      if (estado.modalAberto === 'casa') montarCasa();
      break;
    case 'casaFabricada':
      // O sorteio merece a própria tela, com a dopamina do tamanho da raridade — e o número.
      revelarCasa(e);
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      // O contador do servidor acabou de andar: com o modal aberto, ele sobe na frente do jogador.
      if (estado.modalAberto === 'casa') pedirRegistroCasas();
      break;
    case 'casaCraftada':
      // A seleção era das cinco que acabaram de sumir: a próxima volta à escolha padrão.
      if (estado.craftCasa) estado.craftCasa.sel = null;
      revelarCasa(e);
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      if (estado.modalAberto === 'casa') pedirRegistroCasas();
      break;
    case 'bicicletaFabricada':
      revelarBicicleta(e);
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      break;
    case 'bicicletaCraftada':
      // A seleção era das cinco que acabaram de sumir: a próxima volta à escolha padrão.
      if (estado.craftBicicleta) estado.craftBicicleta.sel = null;
      // A equipada virou a nova: entra já, para a bancada não se redesenhar com a de antes (os
      // EVENTOS vêm antes do ESTADO no mesmo pacote — ver `bicicletaEquipada`).
      if (e.equipada && estado.eu?.bicicleta) {
        estado.eu.bicicleta.equipada = e.bicicletaId;
        estado.eu.bicicleta.equipadaRar = e.raridade;
      }
      revelarBicicleta(e);
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      // O Registro de Bikes mora no modal da Casa: aberto, ele mostra a nova e as cinco fundidas.
      if (estado.modalAberto === 'casa') pedirRegistroBikes();
      break;
    case 'bicicletaEquipada': {
      // No mesmo pacote os EVENTOS vêm antes do ESTADO: a raridade confirmada entra aqui já, para
      // a bancada aberta não se redesenhar com a equipada de antes. A bolsa se refaz no snapshot.
      if (estado.eu?.bicicleta) {
        estado.eu.bicicleta.equipada = e.bicicletaId ?? null;
        estado.eu.bicicleta.equipadaRar = e.raridade ?? null;
      }
      const meta = (estado.bicicletas?.raridades ?? []).find((r) => r.id === e.raridade);
      toast(meta
        ? t('bicicleta.equipadaToast', { nome: nomeBicicletaRaridade(e.raridade), vel: resumoDaBicicleta(meta) })
        : t('bicicleta.desequipadaToast'));
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      if (estado.modalAberto === 'bolsa') pintarBolsaCorpo();
      break;
    }
    case 'shinyStoneFabricada':
      toast(t('pedra.fabricada', { tipo: e.tipo }));
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      break;
    case 'megaStoneFabricada':
      toast(t('mega.fabricada', { nome: nomeItem(e.itemId, e.nome) }));
      if (!$('#tm-researcher').classList.contains('hidden')) montarTmResearcher();
      break;
    // A OFERENDA girou. O evento traz a roleta que o SERVIDOR sorteou e o índice que saiu — a
    // animação vai até ali e só então revela. Os pokémon já saíram da coleção pelo delta de
    // estado, que vem no mesmo pacote.
    case 'oferenda':
      girarRoletaDaOferenda(e);
      break;
    case 'oferendaLote':
      revelarLoteDaOferenda(e);
      break;
    case 'escapeRope':
      toast(t('cena.escapeRopeUsada', { n: num(e.restam) }));
      break;
    case 'xpshare':
      // A fatia NÃO vira linha de log nem toast: ela pinga a cada abate, e narrar isso
      // enterraria a caçada — que é exatamente o que o jogador está fazendo quando ela cai.
      //
      // Dentro da casa, porém, ela é o espetáculo: o "+120 XP" sobe em cima do pokémon
      // registrado. Fora dela `treinoXp` não acha o posto na cena e não faz nada.
      // O `slot` é o posto DE UMA CASA: só pinga na cena se for a casa aberta, senão o "+XP" de
      // um pokémon da Casa #12 subiria em cima do boneco da Casa #40.
      if (e.casaId == null || e.casaId === estado.eu?.casa?.dentro) {
        c?.treinoXp(e.slot, e.xp);
        syncCasaBonecoBotoes();
      }
      break;
    // A etiqueta foi gasta. A ficha aberta é redesenhada porque é de lá que muita gente vai
    // apelidar (abre a ficha, vê o nome, decide) — e uma ficha que continua com o nome velho
    // depois do "confirmar" parece que a compra não pegou.
    case 'nameTagUsada':
      toast(t('nametag.pronto', { nome: e.apelido, especie: e.nome }));
      if (estado.modalAberto === 'bolsa') pintarBolsaCorpo();
      if (fichaPokemonAberto?.id === e.pokemonId) reabrirFichaDoPokemon();
      break;
    // A SKIN: o toast diz em quem ela ficou (e de quem saiu, no "mover para cá"). A folha e a
    // bolsa se redesenham no ESTADO que vem logo atrás — ver `repintarFolhaSkin`.
    case 'skinVestida': {
      const s = SKIN_POR_ID.get(e.skin);
      toast(e.deId != null
        ? t('skin.moveu', { skin: s ? nomeDaSkin(s) : e.skin, nome: rotuloPkDaSkin(e.pokemonId, e.nome), de: rotuloPkDaSkin(e.deId, e.deNome) })
        : t('skin.vestiu', { skin: s ? nomeDaSkin(s) : e.skin, nome: rotuloPkDaSkin(e.pokemonId, e.nome) }));
      break;
    }
    case 'skinTirada': {
      const s = SKIN_POR_ID.get(e.skin);
      toast(t('skin.tirou', { skin: s ? nomeDaSkin(s) : e.skin, nome: rotuloPkDaSkin(e.pokemonId, e.nome) }));
      break;
    }
    case 'xpshareheldEquipado':
      toast(t('xpshareheld.equipado', { nome: e.nome }));
      if (estado.modalAberto === 'bolsa') pintarBolsaCorpo();
      {
        const corpo = document.querySelector('#xsh-secoes')?.closest('.cm-folha-corpo');
        const folha = corpo?.closest('.cm-folha');
        if (corpo && folha && xpShareHeldAtivo()) {
          pintarXpShareHeld(corpo, () => folha.remove(), xpShareHeldItemId(), estado.xpShareHeld?.pct ?? 5);
        }
      }
      break;
    case 'xpshareheldRemovido':
      toast(t('xpshareheld.removido', { nome: e.nome }));
      if (estado.modalAberto === 'bolsa') pintarBolsaCorpo();
      {
        const corpo = document.querySelector('#xsh-secoes')?.closest('.cm-folha-corpo');
        const folha = corpo?.closest('.cm-folha');
        if (corpo && folha && xpShareHeldAtivo()) {
          pintarXpShareHeld(corpo, () => folha.remove(), xpShareHeldItemId(), estado.xpShareHeld?.pct ?? 5);
        }
      }
      break;
    case 'nomeTrocado':
      toast(e.nick);
      atualizarSessaoNick(e.nick, e.token);
      break;
    case 'outfitTrocada':
      if (estado.modalAberto === 'shop') montarLoja();
      if (estado.modalAberto === 'armario') montarArmario();
      break;
    case 'caixaComprada':
      toast(t('caixas.comprada', { nome: t(`caixas.nome.${e.tipo}`), serie: serieDaCaixa(e.tipo, e.serie) }));
      logCena(t('caixas.logComprada', {
        nome: t(`caixas.nome.${e.tipo}`), serie: serieDaCaixa(e.tipo, e.serie),
      }));
      if (estado.modalAberto === 'shop') montarLoja();
      break;
    case 'caixaAberta':
      // A abertura é o momento da caixa: três prêmios de uma vez, um deles irreversível. Um
      // toast de duas linhas não dá conta — abre-se a tela de "você recebeu".
      mostrarCaixaAberta(e);
      if (estado.modalAberto === 'shop') montarLoja();
      if (estado.modalAberto === 'armario') montarArmario();
      break;
    case 'colecao':
      aoResponderColecao(e);
      break;
    case 'aviso': {
      let msg = e.msg;
      if (/^[a-z][\w.-]*\.[\w.-]+$/i.test(msg)) {
        // `e.params` é o caso geral: o servidor manda os buracos da frase junto da chave
        // (os minutos que faltam na trava do mercado, por exemplo).
        //
        // O brasão veio ANTES do `params` e mandava o dele num campo próprio (`e.horas`). Isso
        // deixou de ser um detalhe histórico quando a espera da TAG chegou copiando a forma
        // antiga: ela caía no ramo geral, não achava `params`, e o jogador lia "Aguarde {horas} h".
        // Agora o servidor manda as duas pelo `params` (ver `avisoDeGuild` no sim), e o que
        // sobra aqui é só o FALLBACK do brasão — para um servidor velho, ou um `params` que não
        // trouxe o número.
        let params = e.params && typeof e.params === 'object' ? { ...e.params } : null;
        if (msg === 'guild.brasaoEspera' && params?.horas == null) {
          params = { ...(params ?? {}), horas: num(e.horas ?? horasRestantesBrasaoGuild()) };
        }
        // `restaMs` chega em milissegundos porque é assim que o servidor conta; nenhuma frase
        // quer ler "86400000". A conversão mora aqui, e não em cada recusa, para que uma espera
        // nova só precise mandar o número e ganhe o "23 h" de graça.
        if (params?.restaMs != null) params.tempo = tempoCurto(Number(params.restaMs));
        // O mesmo para um PREÇO (o alto-falante): o servidor manda o número, e o "10.000.000" com
        // o separador do idioma sai daqui.
        if (params?.custo != null) params.custo = num(Number(params.custo));
        msg = t(msg, params ?? undefined);
      }
      toast(msg);
      // A oferenda recusada volta como AVISO (posse, trava, roleta vazia), e não como um `k`
      // próprio: é o mesmo caminho de toda recusa do jogo. O que ela precisa a mais é soltar a
      // trava do botão — senão o jogador leria o motivo com a aba ainda travada.
      if (estado.ofrGirando) ofrDestravar();
      // A equipe de guerra recusada também volta como aviso: o "Salvar" destrava.
      if (estado.guildSalvandoTime) {
        estado.guildSalvandoTime = false;
        repintarEditorEquipeGuerra();
      }
      break;
    }
  }
}

// ------------------------------------------------------------------- chat

/** Igual a `CHAT_NIVEL_MIN` em `protocol.mjs` — trava no gateway e aqui na UI. */
const CHAT_NIVEL_MIN = 10;

const formatarRestanteMute = (ms) => {
  const s = Math.max(0, Math.ceil(ms / 1000));
  if (s >= 3600) {
    const h = Math.floor(s / 3600);
    const m = Math.ceil((s % 3600) / 60);
    return m ? `${h}h ${m}min` : `${h}h`;
  }
  if (s >= 60) return `${Math.ceil(s / 60)} min`;
  return `${s}s`;
};

let chatMuteTimer = null;

function aplicarMuteChat(ate) {
  estado.chatMutadoAte = Number(ate) || 0;
  if (chatMuteTimer) clearTimeout(chatMuteTimer);
  syncChatInput();
  const rest = estado.chatMutadoAte - Date.now();
  if (rest > 0) {
    mostrarAvisoChat('chat.mutadoAviso', { tempo: formatarRestanteMute(rest) });
    chatMuteTimer = setTimeout(() => {
      estado.chatMutadoAte = 0;
      syncChatInput();
    }, rest + 100);
  }
}

const chatMutado = () => (estado.chatMutadoAte ?? 0) > Date.now();

/** Lista pessoal de nicks silenciados — só no navegador, zero custo no servidor. */
const CHAVE_CHAT_IGNORADOS = 'chatIgnorados';
const CHAVE_CHAT_IGNORADOS_NOMES = 'chatIgnoradosNomes';

function carregarChatIgnorados() {
  try {
    const raw = JSON.parse(localStorage.getItem(CHAVE_CHAT_IGNORADOS) ?? '[]');
    return new Set(
      (Array.isArray(raw) ? raw : []).map((n) => String(n).trim().toLowerCase()).filter(Boolean),
    );
  } catch {
    return new Set();
  }
}

function carregarChatIgnoradosNomes() {
  try {
    const raw = JSON.parse(localStorage.getItem(CHAVE_CHAT_IGNORADOS_NOMES) ?? '{}');
    return raw && typeof raw === 'object' ? raw : {};
  } catch {
    return {};
  }
}

let chatIgnorados = carregarChatIgnorados();
let chatIgnoradosNomes = carregarChatIgnoradosNomes();

function salvarChatIgnorados() {
  localStorage.setItem(CHAVE_CHAT_IGNORADOS, JSON.stringify([...chatIgnorados]));
  localStorage.setItem(CHAVE_CHAT_IGNORADOS_NOMES, JSON.stringify(chatIgnoradosNomes));
}

function nickExibicaoIgnorado(chave) {
  return chatIgnoradosNomes[chave] || chave;
}

function nickIgnoradoNoChat(nick) {
  const n = String(nick ?? '').trim().toLowerCase();
  return !!n && chatIgnorados.has(n);
}

/** Liga/desliga o filtro local. Devolve `true` se ficou ignorado. */
function alternarIgnorarChat(nick) {
  const bruto = String(nick ?? '').trim();
  const n = bruto.toLowerCase();
  if (!n) return false;
  if (chatIgnorados.has(n)) {
    chatIgnorados.delete(n);
    delete chatIgnoradosNomes[n];
  } else {
    chatIgnorados.add(n);
    chatIgnoradosNomes[n] = bruto;
  }
  salvarChatIgnorados();
  return chatIgnorados.has(n);
}

function designorarChat(nick) {
  const n = String(nick ?? '').trim().toLowerCase();
  if (!n || !chatIgnorados.has(n)) return false;
  const exib = nickExibicaoIgnorado(n);
  alternarIgnorarChat(nickExibicaoIgnorado(n));
  return exib;
}

function autorIgnoravel(m) {
  return m?.de ?? null;
}

function msgIgnorada(m) {
  const autor = autorIgnoravel(m);
  return autor && nickIgnoradoNoChat(autor);
}

/**
 * "Esconder anúncios da comunidade" (a setinha ao lado do emoji, que só existe no Mundo): ligado, a
 * linha do ALTO-FALANTE do Market não aparece NO MUNDO. No Comércio ela sempre aparece — lá o
 * anúncio é o assunto do canal (ver `syncBotaoOpcoesChat`). Diferente do "Ignorar", ela NÃO é
 * descartada na chegada — fica guardada em `estado.mensagens` e só sai do desenho, para voltar
 * inteira no instante em que o interruptor desligar, com a meia hora de histórico que o Mundo guarda.
 */
let semAnunciosNoChat = anunciosChatEscondidos();
const anuncioEscondido = (m) => semAnunciosNoChat && !!m?.anuncioChat && m.canal === 'mundo';

/** Tudo o que o chat não desenha nem conta: autor ignorado e anúncio escondido. */
const msgForaDoChat = (m) => msgIgnorada(m) || anuncioEscondido(m);

function limparMsgsDeIgnorados() {
  for (const canal of Object.keys(estado.mensagens)) {
    estado.mensagens[canal] = (estado.mensagens[canal] ?? []).filter((m) => !msgIgnorada(m));
  }
}

const podeUsarChat = () => (estado.eu?.level ?? 0) >= CHAT_NIVEL_MIN && !chatMutado();

/**
 * Os canais do chat, na ordem do seletor. Espelha `CANAIS_CHAT` do `protocol.mjs`.
 *
 * `seloGeral`: o canal entra nas contas que aparecem com o menu FECHADO — o selo no botão do
 * seletor, o do chat recolhido e o da gaveta do celular. Comércio e Dúvidas ficam de fora de
 * propósito: o Comércio recebe anúncio o dia inteiro, e somar isso no selo do chat seria obrigar
 * quem só quer conversar a conviver com um número que nunca zera — o contrário do que separar o
 * canal prometeu. O número deles aparece dentro do menu, ao lado do nome, para quem for procurar.
 */
const CANAIS_DO_CHAT = [
  { id: 'mundo', emoji: '🌎', nome: 'chat.mundo', desc: 'chat.canalDescMundo', seloGeral: true },
  { id: 'comercio', emoji: '💰', nome: 'chat.comercio', desc: 'chat.canalDescComercio', seloGeral: false },
  { id: 'duvidas', emoji: '❓', nome: 'chat.duvidas', desc: 'chat.canalDescDuvidas', seloGeral: false },
  { id: 'guild', emoji: '⚔️', nome: 'chat.guild', desc: 'chat.canalDescGuild', seloGeral: true, soGuild: true },
];

const CANAIS_CHAT_PUBLICOS = CANAIS_DO_CHAT.map((c) => c.id);
const canalDoChat = (id) => CANAIS_DO_CHAT.find((c) => c.id === id) ?? CANAIS_DO_CHAT[0];
/** Os canais que o jogador pode abrir agora: a Guild só com guild. */
const canaisDoJogador = () => CANAIS_DO_CHAT.filter((c) => !c.soGuild || !!estado.eu?.guild?.id);

function syncChatGuildTab() {
  if (estado.canalChat === 'guild' && !estado.eu?.guild?.id) trocarCanalChat('mundo');
  else pintarSelosChatAbas();
}

function ehCanalPublico(canal) {
  return CANAIS_CHAT_PUBLICOS.includes(canal);
}

/** Mensagens do canal que o jogador ainda não viu (mesmo filtro de idioma da lista). */
function contarChatNaoLidas(canal) {
  if (!ehCanalPublico(canal)) return 0;
  const visto = estado.chatVistoEm?.[canal] ?? 0;
  return (estado.mensagens[canal] ?? []).filter(
    (m) => !msgForaDoChat(m) && idiomaDaMsg(m) === estado.idiomaChat && (m.ts ?? 0) > visto,
  ).length;
}

/** A soma dos canais com `seloGeral` — o que o chat fechado (e o botão do seletor) mostra. */
function naoLidasGerais({ exceto = null } = {}) {
  return canaisDoJogador()
    .filter((c) => c.seloGeral && c.id !== exceto)
    .reduce((n, c) => n + contarChatNaoLidas(c.id), 0);
}

function pintarSelo(selo, n) {
  if (!selo) return;
  selo.classList.toggle('hidden', n <= 0);
  selo.textContent = n > 99 ? '99+' : String(n);
}

/**
 * O selo de não-lidas do RAIL: a soma dos canais, numa plaquinha só.
 *
 * No rail o seletor some, e com ele os selos. Sem este substituto, fechar o chat com a coluna
 * estreita seria ficar cego para ele — que é justamente o que o modo recolhido não pode custar.
 */
function pintarSeloChatRail() {
  pintarSelo($('#chat-cnt-rail'), naoLidasGerais());
}

/**
 * O botão do seletor (emoji e nome do canal de agora, e o selo dos OUTROS canais) e, com o menu
 * aberto, o número de cada opção.
 *
 * O nome ainda diz "abas" porque ela é chamada de uma dúzia de lugares desde quando os canais
 * eram abas lado a lado — a pergunta que ela responde continua a mesma.
 */
function pintarSelosChatAbas() {
  // Fechado, não há canal "sendo visto": o painel virou uma fita e ninguém leu nada. Sem isto o
  // canal aberto ficaria eternamente sem selo e fechar o chat seria ficar cego para ele.
  const vendo = !chatRecolhido() && ehCanalPublico(estado.canalChat) ? estado.canalChat : null;
  const atual = canalDoChat(estado.canalChat);
  const emoji = $('#chat-canal-emoji');
  const nome = $('#chat-canal-nome');
  if (emoji) emoji.textContent = atual.emoji;
  if (nome) nome.textContent = t(atual.nome);
  pintarSelo($('#chat-canal-selo'), naoLidasGerais({ exceto: vendo }));
  const menu = $('#chat-canal-menu');
  if (menu && !menu.classList.contains('hidden')) {
    for (const op of menu.querySelectorAll('[data-canal]')) {
      const canal = op.dataset.canal;
      pintarSelo(op.querySelector('.chat-aba-selo'), canal === vendo ? 0 : contarChatNaoLidas(canal));
    }
  }
  pintarSeloChatRail();
}

function marcarCanalChatVisto(canal, ate = Date.now()) {
  if (!ehCanalPublico(canal)) return;
  if (!estado.chatVistoEm) estado.chatVistoEm = {};
  estado.chatVistoEm[canal] = Math.max(estado.chatVistoEm[canal] ?? 0, ate);
  pintarSelosChatAbas();
}

// ---- o menu do seletor de canal

function montarMenuCanais() {
  const menu = $('#chat-canal-menu');
  if (!menu) return;
  menu.innerHTML = canaisDoJogador().map((c) => {
    const on = c.id === estado.canalChat;
    return `<button type="button" role="option" class="chat-canal-op${on ? ' on' : ''}" data-canal="${c.id}"
        aria-selected="${on ? 'true' : 'false'}">
        <span class="chat-canal-emoji" aria-hidden="true">${c.emoji}</span>
        <span class="chat-canal-txt"><b>${escapar(t(c.nome))}</b><small>${escapar(t(c.desc))}</small></span>
        <span class="chat-aba-selo hidden" aria-hidden="true"></span>
      </button>`;
  }).join('');
}

function fecharMenuCanais() {
  const menu = $('#chat-canal-menu');
  if (!menu || menu.classList.contains('hidden')) return;
  menu.classList.add('hidden');
  $('#chat-canal-bt')?.setAttribute('aria-expanded', 'false');
  $('#chat-canal')?.classList.remove('aberto');
}

function abrirMenuCanais() {
  const menu = $('#chat-canal-menu');
  if (!menu) return;
  fecharPainelModChat();
  fecharPainelIgnorados();
  montarMenuCanais();
  menu.classList.remove('hidden');
  $('#chat-canal-bt')?.setAttribute('aria-expanded', 'true');
  $('#chat-canal')?.classList.add('aberto');
  pintarSelosChatAbas();
  (menu.querySelector('.chat-canal-op.on') ?? menu.querySelector('.chat-canal-op'))?.focus();
}

$('#chat-canal-bt')?.addEventListener('click', (ev) => {
  ev.stopPropagation();
  if ($('#chat-canal-menu')?.classList.contains('hidden')) abrirMenuCanais();
  else fecharMenuCanais();
});

$('#chat-canal-menu')?.addEventListener('click', (ev) => {
  const op = ev.target.closest('[data-canal]');
  if (!op) return;
  fecharMenuCanais();
  // Ordem importa: abrir ANTES de trocar. `trocarCanalChat` marca o canal como visto e rola a lista
  // ao fim, e as duas coisas só valem com a lista na tela.
  definirChatRecolhido(false);
  trocarCanalChat(op.dataset.canal);
  $('#chat-canal-bt')?.focus();
});

// As setas andam pelo menu; Esc fecha e devolve o foco ao botão.
$('#chat-canal-menu')?.addEventListener('keydown', (ev) => {
  const ops = [...ev.currentTarget.querySelectorAll('.chat-canal-op')];
  const i = ops.indexOf(document.activeElement);
  if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') {
    ev.preventDefault();
    const passo = ev.key === 'ArrowDown' ? 1 : -1;
    ops[(i + passo + ops.length) % ops.length]?.focus();
  } else if (ev.key === 'Escape') {
    ev.stopPropagation();
    fecharMenuCanais();
    $('#chat-canal-bt')?.focus();
  }
});

document.addEventListener('click', (ev) => {
  if (ev.target.closest('#chat-canal')) return;
  fecharMenuCanais();
});

/** O convite de cada canal no campo de digitar — diz para que ele serve antes da primeira fala. */
const PLACEHOLDER_DO_CANAL = { comercio: 'chat.placeholderComercio', duvidas: 'chat.placeholderDuvidas' };

/** O que a lista mostra vazia: o Comércio e as Dúvidas explicam como começar. */
const VAZIO_DO_CANAL = { comercio: 'chat.vazioComercio', duvidas: 'chat.vazioDuvidas' };
const textoChatVazio = () => t(VAZIO_DO_CANAL[estado.canalChat] ?? 'chat.vazio');

function syncChatInput() {
  const inp = $('#chat-input');
  const btn = $('#chat-enviar');
  if (!inp || !btn) return;
  const ok = podeUsarChat();
  const okGuild = estado.canalChat !== 'guild' || !!estado.eu?.guild?.id;
  inp.disabled = !ok || !okGuild;
  btn.disabled = !ok || !okGuild;
  if (chatMutado()) {
    inp.disabled = true;
    btn.disabled = true;
    inp.placeholder = t('chat.mutadoPlaceholder', {
      tempo: formatarRestanteMute(estado.chatMutadoAte - Date.now()),
    });
    return;
  }
  if (estado.canalChat === 'guild' && !estado.eu?.guild?.id) {
    inp.placeholder = t('chat.semGuild');
  } else if (!ok) {
    inp.placeholder = t('chat.nivelMinimo', { n: CHAT_NIVEL_MIN });
  } else {
    inp.placeholder = t(PLACEHOLDER_DO_CANAL[estado.canalChat] ?? 'chat.placeholder');
  }
}

/**
 * Chega tudo, guarda tudo — o filtro por idioma é de LEITURA.
 *
 * O servidor faz um fan-out só, com o idioma carimbado na mensagem, e cada cliente mostra o
 * que quer. Guardar as três línguas no histórico é o que permite trocar a bandeira do chat e
 * já ver a conversa que estava rolando, em vez de uma janela vazia esperando mensagem nova.
 */
function receberChat(m) {
  if (msgIgnorada(m)) return;
  if (m.canal === 'guild') {
    const gid = Number(m.guildId) || 0;
    if (!estado.eu?.guild?.id || gid !== estado.eu.guild.id) return;
  }
  const lista = (estado.mensagens[m.canal] ??= []);
  if (m.id && lista.some((x) => x.id === m.id)) return;
  lista.push(m);
  if (lista.length > 200) lista.shift();

  if (estado.modalAberto === 'amigos' && m.canal === 'guild' && amigosUI().sel === AMIGO_SEL_GUILD) {
    pintarThreadGuild(true);
  }

  // O anúncio escondido fica guardado acima, mas pára aqui: sem linha, sem pílula de novas e sem
  // selo — nem o do seletor nem o da gaveta do celular (ver `anuncioEscondido`). Com o painel das
  // opções aberto, o "N anúncios escondidos agora" acompanha.
  if (anuncioEscondido(m)) {
    if (!$('#chat-opcoes')?.classList.contains('hidden')) pintarOpcoesChat();
    return;
  }

  // Só a linha nova entra na tela; ver a nota em `pintarChat` sobre por que não se repinta.
  if (m.canal === estado.canalChat && idiomaDaMsg(m) === estado.idiomaChat) {
    const box = $('#chat-msgs');
    // Com o painel recolhido a lista é `display: none` e mede zero — `chatNoFim()` diria
    // "colado" e a linha entraria já como LIDA, sem nunca acender selo nenhum. A mensagem
    // continua entrando na lista (ela precisa estar lá quando o chat reabrir), mas nada de
    // rolagem, de "visto" nem da pílula de novas, que ninguém veria.
    const recolhido = chatRecolhido();
    const colado = !recolhido && chatNoFim();
    box.querySelector('.chat-vazio')?.remove();
    box.appendChild(linhaDeChat(m));
    while (box.children.length > 200) box.firstChild.remove();
    if (colado) {
      rolarChatAoFim();
      if (ehCanalPublico(m.canal)) marcarCanalChatVisto(m.canal, m.ts ?? Date.now());
    } else if (!recolhido) marcarChatNovas(estado.chatNovas + 1);
  }

  if (ehCanalPublico(m.canal) && idiomaDaMsg(m) === estado.idiomaChat) {
    pintarSelosChatAbas();
    // A gaveta do celular segue a mesma régua do selo do seletor: Comércio e Dúvidas não acendem
    // nada fora do menu (ver `seloGeral` em `CANAIS_DO_CHAT`).
    if (m.canal !== estado.canalChat && canalDoChat(m.canal).seloGeral) seloChatMobile();
  }

  // O balão em cima do boneco, na praça do Centro. Vale para os TRÊS canais — o balão é a
  // pessoa falando na sua frente, e ninguém troca de aba para ouvir quem está do lado. Mas
  // segue o filtro de IDIOMA: se a mensagem não aparece no chat, ela também não flutua na
  // cena, senão a bandeirinha deixaria de significar o que promete.
  // Com os apelidos já trocados: o balão é a MESMA fala da lista, e ver `:fire:` cru em
  // cima do boneco enquanto o chat mostra 🔥 é o tipo de incoerência que parece bug.
  if (idiomaDaMsg(m) === estado.idiomaChat && !msgIgnorada(m)) {
    const balao = textoBalaoChat(m);
    if (balao) estado.campo?.balao(m.de, balao);
  }
}

/**
 * Escapa texto que vai para dentro de HTML.
 *
 * Escapava só `< > &`, o que é seguro no CONTEÚDO de um elemento e furado dentro de um
 * ATRIBUTO — e este arquivo tem dezenas de `title="${escapar(x)}"`. Agora vem de `shared/`,
 * junto com a versão do painel admin, porque duas cópias da mesma função com regras diferentes
 * é o formato de um buraco que ninguém vê. O porquê inteiro está lá.
 */
const escapar = escaparHtml;

/** Mensagem antiga (de antes do idioma existir) conta como português. */
const idiomaDaMsg = (m) => m.idioma ?? 'pt';

/**
 * O selo que vai antes do nick. A cor de cada cargo é do CSS (`.chat-msg.vip` e irmãs).
 *
 * Sobrou o tutor. O 💎 do VIP saiu: o nick do VIP já é azul-claro COM BRILHO (`text-shadow` em
 * `.chat-msg.vip .m-de`), e o diamante repetia em desenho o que a cor dizia — numa linha que
 * ainda carrega a marca do cargo, a tag da guild e o nível, cada repetição dessas custa o
 * espaço da fala. O `vip` continua na lista de cargos SEM selo logo abaixo, que é o que mantém
 * a classe (e portanto a cor) na linha.
 */
const SELO_CARGO = { tutor: '🎓' };
const seloDeCargo = (cargo) => SELO_CARGO[cargo];

/**
 * Os cargos que viram DESENHO no começo da linha, no lugar de texto antes do nick.
 *
 * `[Moderador]` eram onze caracteres, `[STREAMER]` nove — e os dois diziam o que a cor do nick
 * já dizia, numa linha que ainda carrega a tag da guild e o nível. No lugar deles entra uma
 * marca de 14 px logo depois do horário: a plaquinha STAFF para quem é da equipe e o logo da
 * Twitch para o streamer.
 *
 * **Uma marca só para os três cargos de equipe, e não uma por cargo.** O que separa admin,
 * moderador e helper continua sendo a COR DO NICK (`.chat-msg.admin .m-de` e irmãs); a marca
 * responde a outra pergunta, a que o jogador faz de relance — "isso aí é da equipe do jogo?".
 * Três desenhos parecidos de 14 px não se distinguiriam no canto do olho de qualquer jeito, e
 * quem precisar do nome exato tem o `title`.
 */
const MARCAS_DE_CARGO = {
  admin: { arte: '/img/marca-staff.png', titulo: 'chat.seloAdmin' },
  moderador: { arte: '/img/marca-staff.png', titulo: 'chat.seloModerador' },
  helper: { arte: '/img/marca-staff.png', titulo: 'chat.seloHelper' },
  streamer: { arte: null, titulo: 'chat.seloStreamer' }, // a arte é o `:vip44:`, resolvido abaixo
};

/**
 * Cargos que pintam o NICK mas não escrevem nada antes dele — os quatro de cima e o VIP.
 *
 * A lista existe porque o `clsCargo` só acendia a cor de quem TINHA selo de texto: tirar o
 * texto tiraria a cor junto, e o cargo sumiria da tela inteiro. O `vip` entra à mão porque ele
 * não tem marca nenhuma (não está em `MARCAS_DE_CARGO`) — perdeu o 💎 e ficou só com a cor,
 * que é exatamente o caso que esta lista existe para segurar.
 */
const CARGOS_SEM_SELO = new Set([...Object.keys(MARCAS_DE_CARGO), 'vip']);

/**
 * A marca do cargo, depois do horário e antes de qualquer tag.
 *
 * FUNÇÃO, e não uma tabela de HTML pronta: o `artVip` do streamer é declarado mais abaixo neste
 * mesmo arquivo, e uma `const` no topo que o chamasse estouraria na avaliação do módulo (TDZ).
 * O `title` é o que devolve o nome exato do cargo, que o texto carregava.
 */
function marcaDeCargo(cargo) {
  const m = MARCAS_DE_CARGO[cargo];
  if (!m) return '';
  const nome = escapar(t(m.titulo));
  return `<img class="m-marca-cargo" src="${m.arte ?? artVip(44)}" alt="${nome}" title="${nome}">`;
}

/**
 * Os apelidos que viram figura: `:fire:` sai 🔥.
 *
 * Existem para quem digita rápido e para quem está num teclado sem painel de emoji — o
 * celular tem o dele, o de mesa não tem.
 *
 * A troca roda no ENVIO e de novo na EXIBIÇÃO. No envio para a mensagem já sair pronta
 * (quem recebe não depende de ter esta tabela); na exibição porque o histórico tem
 * mensagens de antes disto existir, e porque nada obriga um cliente a converter antes de
 * mandar. O que NÃO se faz é converter enquanto se digita: mexeria na posição do cursor no
 * meio da frase.
 */
const EMOJIS = {
  joy: '😂', rofl: '🤣', smile: '😄', grin: '😁', wink: '😉', blush: '😊',
  heart_eyes: '😍', kiss: '😘', thinking: '🤔', neutral: '😐', smirk: '😏',
  sob: '😭', cry: '😢', rage: '😡', angry: '😠', scream: '😱', sleeping: '😴',
  sunglasses: '😎', nerd: '🤓', clown: '🤡', skull: '💀', ghost: '👻', alien: '👽',
  robot: '🤖', heart: '❤️', broken_heart: '💔', fire: '🔥', star: '⭐',
  sparkles: '✨', zap: '⚡', boom: '💥', tada: '🎉', trophy: '🏆', crown: '👑',
  gem: '💎', moneybag: '💰', thumbsup: '👍', thumbsdown: '👎', ok_hand: '👌',
  clap: '👏', pray: '🙏', muscle: '💪', wave: '👋', eyes: '👀', gg: '🎮',
  sword: '⚔️', shield: '🛡️', potion: '🧪', ball: '🔴', check: '✅', x: '❌',
  warning: '⚠️', question: '❓', zzz: '💤', dog: '🐶', cat: '🐱', dragon: '🐉',
  turtle: '🐢', bird: '🐦', fish: '🐟', bug: '🐛', fox: '🦊', wolf: '🐺',
  frog: '🐸', snake: '🐍',
};
const trocarApelidos = (s) => s.replace(/:([a-z0-9_+-]+):/g, (todo, k) => EMOJIS[k] ?? todo);

/**
 * Emoji na fala fica um tico maior que a letra.
 *
 * O regex casa a SEQUÊNCIA inteira, e não o primeiro código: bandeira, tom de pele e os
 * compostos por ZWJ (👨‍👩‍👧) são vários pontos de código que desenham UM símbolo, e envolver
 * cada pedaço num `<span>` separado quebraria o desenho em três bonecos.
 *
 * Roda depois do `escapar()`, e isso é seguro: `\p{Extended_Pictographic}` não alcança
 * ASCII, então `&lt;` e companhia passam intactos.
 *
 * Os dois juntores vão escapados (`️` seletor de variação, `‍` ZWJ) de propósito:
 * escritos direto seriam dois caracteres INVISÍVEIS no meio do regex, que a primeira
 * edição desatenta apaga sem ninguém ver.
 */
const RE_EMOJI = /\p{Extended_Pictographic}(?:\uFE0F|[\u{1F3FB}-\u{1F3FF}]|\u200D\p{Extended_Pictographic})*/gu;
const comEmoji = (s) => s.replace(RE_EMOJI, (e) => `<span class="m-emoji">${e}</span>`);

/**
 * Os emojis VIP s\u00E3o FIGURA, n\u00E3o Unicode: `:vip7:` vira `img/emojis-vip/vip7.png`.
 *
 * \u00C9 o que torna a vantagem real. Emoji Unicode qualquer um cola no campo \u00E0 m\u00E3o, ent\u00E3o um
 * "emoji de VIP" feito de \uD83E\uDD84 seria s\u00F3 um teclado escondido \u2014 o cadeado enfeitaria sem
 * travar nada. Com figura pr\u00F3pria, o token `:vip7:` \u00E9 o que d\u00E1 direito ao desenho, e quem
 * recusa a mensagem de quem n\u00E3o assina \u00E9 o GATEWAY (ver `CLIENTE.CHAT_SEND` l\u00E1).
 *
 * As figuras v\u00EAm por `node tools/fetch-vip-emojis.mjs`.
 *
 * Roda depois do `escapar()` \u2014 o `<img>` precisa sair como tag, e `:vip7:` n\u00E3o tem nada
 * que o escape fosse mexer. O n\u00FAmero passa por `Number` e por uma faixa antes de virar
 * caminho de arquivo: `:vip999:` n\u00E3o pode virar requisi\u00E7\u00E3o a nada.
 */
const EMOJIS_VIP_QTD = 112;
const artVip = (n) => `img/emojis-vip/vip${n}.png`;
const comEmojiVip = (s) =>
  s.replace(/:vip(\d{1,3}):/g, (todo, cru) => {
    const n = Number(cru);
    return n >= 1 && n <= EMOJIS_VIP_QTD
      ? `<img class="m-vip" src="${artVip(n)}" alt="${todo}" title="${todo}" loading="lazy">`
      : todo;
  });

/**
 * As menções: `@fasi` vira um chip, e o SEU nick acende a linha inteira.
 *
 * Serve à conversa que o chat de verdade tem — alguém pergunta, outro responde meia dúzia
 * de linhas depois, e a resposta se perde na rolagem de quem ela era. Com a menção, quem
 * foi chamado enxerga isso de canto de olho, sem reler o bloco todo.
 *
 * O formato do nick é o do servidor (`nickValido` no gateway): `[a-zA-Z0-9_]{3,16}`. O
 * corte à direita é uma espiada, não um `{1,16}` guloso — sem ele `@nomedezessetechars`
 * casaria os 16 primeiros e pintaria como menção metade de uma palavra que nick nenhum é.
 *
 * À esquerda o `@` tem de vir depois de espaço, pontuação ou começo de linha — a mesma regra
 * do Twitter, e o que impede `contato@fasi.com` de virar uma menção no meio de um e-mail. Vai
 * como grupo que o replace devolve inteiro, e não como lookbehind: `(?<=…)` só existe no
 * Safari de 2023 para cá, e um regex que o navegador recusa não quebra a menção — quebra o
 * `app.js` inteiro, na linha em que é lido.
 *
 * Não há conferência de que o nick EXISTE: o cliente não tem a lista de contas, e ir
 * perguntar ao servidor a cada linha desenhada custaria mais do que o enfeite vale. Um
 * `@ninguem` sai pintado e não faz mal a ninguém — o que importa é o caso em que o nick é o
 * seu, e esse o cliente sabe sozinho.
 *
 * Roda DEPOIS do `escapar()` e antes dos emojis: nesse ponto o texto ainda não tem tag
 * nenhuma, então não há `<span>` para o regex atropelar, e `[a-zA-Z0-9_]` não alcança o
 * `&amp;` que o escape acabou de escrever.
 */
const RE_MENCAO = /(^|[^a-zA-Z0-9_@])@([a-zA-Z0-9_]{3,16})(?![a-zA-Z0-9_])/g;

const meuNickChat = () => String(estado.eu?.nick ?? estado.nick ?? '').trim().toLowerCase();

/** Devolve a fala com os `@nick` marcados e se ALGUM deles é você — numa passada só. */
function comMencoes(html) {
  const meu = meuNickChat();
  let paraMim = false;
  const texto = html.replace(RE_MENCAO, (todo, antes, nick) => {
    const eu = !!meu && nick.toLowerCase() === meu;
    if (eu) paraMim = true;
    return `${antes}<span class="m-mencao${eu ? ' eu' : ''}">@${nick}</span>`;
  });
  return { texto, paraMim };
}

/** Sempre 24 h, HH:MM:SS. A locale é fixa porque só interessa o FORMATO — deixar a do
 *  navegador decidir traz AM/PM e o ciclo `24:00` de algumas línguas. */
/**
 * O relógio da linha do chat — hora e minuto, sem SEGUNDOS.
 *
 * Os segundos custavam três caracteres em toda linha de uma coluna estreita, e respondiam a uma
 * pergunta que ninguém faz: o horário existe para situar a fala no dia ("isso foi antes ou
 * depois de eu entrar?"), e para isso o minuto basta.
 */
const horaDaMsg = (ts) =>
  new Date(ts ?? Date.now()).toLocaleTimeString('pt-BR', {
    hour: '2-digit', minute: '2-digit', hour12: false,
  });

const textoDeAnuncioPvp = (m) => {
  const nick = `<i>${escapar(m.nickDestaque ?? '')}</i>`;
  if (m.pvpEntrada === 'ancestral') return t('chat.pvpEntrouAncestral', { nick });
  if (m.pvpEntrada === 'flamejante') return t('chat.pvpEntrouFlamejante', { nick });
  return null;
};

const textoDeCompartilharPk = (m) => {
  if (!m.pkShare) return null;
  // O link leva o nome que o dono deu; a ESPÉCIE vem logo atrás, fora do botão. Quem lê a
  // conversa precisa das duas coisas — "olha o meu Brasa" não diz nada a quem está decidindo se
  // vale a pena clicar, e "olha o meu Charizard" esconde o que o dono quis mostrar.
  const apelido = normalizarApelido(m.pkShare.apelido);
  const nome = escapar(apelido || m.pkShare.nome || '');
  const link =
    `<button type="button" class="m-pk-link" data-nick="${escapar(m.pkShare.nick)}" data-pk="${Number(m.pkShare.pokemonId) || ''}">` +
    `<i>${nome}</i></button>`;
  const especie = apelido ? ` <span class="m-pk-especie">(${escapar(m.pkShare.nome ?? '')})</span>` : '';
  return `${t('chat.vejaMeuPokemon')} ${link}${especie}`;
};

const textoDeShinyCaptura = (m) => {
  if (!m.shinyCaptura) return null;
  const nick = `<i>${escapar(m.shinyCaptura.nick ?? '')}</i>`;
  const pokemon =
    `<button type="button" class="m-pk-link" data-nick="${escapar(m.shinyCaptura.nick)}" data-pk="${Number(m.shinyCaptura.pokemonId) || ''}">` +
    `<i>${escapar(m.shinyCaptura.nome ?? '')}</i></button>`;
  return t('chat.shinyCaptura', { nick, pokemon });
};

/**
 * "👑 X capturou o Pokémon Lendário Mewtwo na Arena Mística!" — o fato vem do servidor, a frase é
 * daqui, no idioma de quem lê. O nome do pokémon é link para a ficha, como no anúncio de shiny.
 */
const textoDeLendarioCaptura = (m) => {
  if (!m.lendarioCaptura) return null;
  const l = m.lendarioCaptura;
  const nick = `<i>${escapar(l.nick ?? '')}</i>`;
  const nome = `${l.shiny ? prefixoShiny() : ''}${l.nome ?? ''}`;
  const pokemon =
    `<button type="button" class="m-pk-link" data-nick="${escapar(l.nick ?? '')}" data-pk="${Number(l.pokemonId) || ''}">` +
    `<i>${escapar(nome)}</i></button>`;
  return t(l.mitico ? 'chat.miticoCaptura' : 'chat.lendarioCaptura', { nick, pokemon });
};

/** "[DROP Lendário] O jogador X dropou uma Casa Lendária!" — o fato vem do servidor, a frase é daqui. */
const textoDeDropLendario = (m) => {
  if (!m.dropLendario) return null;
  const nick = `<i>${escapar(m.dropLendario.nick ?? '')}</i>`;
  const item = t(m.dropLendario.tipo === 'bicicleta' ? 'chat.dropLendarioBicicleta' : 'chat.dropLendarioCasa');
  return t('chat.dropLendario', { nick, item: escapar(item) });
};

/**
 * "[Convide & Ganhe] O jogador X resgatou 5 diamantes convidando 1 pessoa…"
 *
 * O prêmio sai da MESMA escada que pagou (`shared/convites.mjs`), e não de um texto guardado:
 * mexer num degrau muda a frase junto. Marcos com vários prêmios mostram o primeiro e um
 * "+N" — a lista inteira do degrau de 100 são seis itens, e viraria um parágrafo no chat.
 *
 * A frase INTEIRA é o link do convite, e não só a palavra "Discord": ela termina chamando
 * ("Entre e convide para ganhar também!") e quem se anima clica onde o olho parou, não numa
 * palavra no meio. O endereço é a NOSSA constante — como no `/ticket`, nada do que vai para o
 * `href` sai do que alguém digitou; do jogador só vêm o nick e o prêmio, os dois escapados.
 */
const textoDeConviteResgate = (m) => {
  if (!m.conviteResgate) return null;
  const marco = marcoDeConvite(m.conviteResgate.marco);
  if (!marco) return null;
  const nick = `<i>${escapar(m.conviteResgate.nick ?? '')}</i>`;
  const primeiro = nomePremioConvite(marco.premios[0]);
  const sobra = marco.premios.length - 1;
  const premio = escapar(sobra > 0 ? t('chat.convitePremioMais', { premio: primeiro, n: sobra }) : primeiro);
  const n = num(marco.amigos);
  const frase = t(marco.amigos === 1 ? 'chat.conviteResgateUm' : 'chat.conviteResgate', { nick, premio, n });
  return `<a class="m-convite-link" href="${DISCORD_URL}" target="_blank" rel="noopener noreferrer"`
    + ` title="${escapar(t('discordPop.cta'))}">${frase}</a>`;
};

/**
 * "[Tag IDLE] X ganhou 5 💎 por manter a tag IDLE do nosso Discord por 10 dias!" — o período da
 * tag do perfil (`shared/tag-discord.mjs`). Mesmo desenho do convite: a frase inteira é o link do
 * Discord, e do servidor só vêm o nick (escapado) e dois números.
 */
const textoDeTagDiscord = (m) => {
  if (!m.tagDiscord) return null;
  const nick = `<i>${escapar(m.tagDiscord.nick ?? '')}</i>`;
  // A etiqueta como o Discord a desenha no perfil: o selo (o diamante) e o nome da tag, numa
  // pílula. É constante nossa — do jogador só vêm o nick (escapado) e dois números.
  const tag = `<span class="m-tag-idle"><img src="${ICONE_DIAMANTE}" alt="">IDLE</span>`;
  const frase = t('chat.tagDiscord', {
    nick, tag, qtd: num(Number(m.tagDiscord.qtd) || 0), dias: num(Number(m.tagDiscord.dias) || 0),
  });
  return `<a class="m-convite-link" href="${DISCORD_URL}" target="_blank" rel="noopener noreferrer"`
    + ` title="${escapar(t('discordPop.cta'))}">${frase}</a>`;
};

/**
 * O nome de uma oferta na frase do alto-falante. O servidor manda o nome do catálogo (e o da
 * espécie, no pokémon — nunca o apelido); o item comum troca pelo nome no idioma de quem lê. As
 * peças numeradas ficam com o do servidor, que é o que traz o número.
 */
function nomeDaOfertaNoChat(o) {
  if (o.tipo === 'diamante') return t('cm.diamantes');
  if (o.tipo === 'pokemon') {
    return `${o.shiny ? '✨ ' : ''}${o.nome ?? ''}${o.level ? ` ${t('cm.nivel')} ${num(o.level)}` : ''}`;
  }
  if (!o.numerado) {
    const item = itemDoMercado(o.itemId);
    if (item) return nomeItem(item, item.nome);
  }
  return o.nome ?? '';
}

/**
 * "estou anunciando 100x de Fire Stone por 20 Gemas cada, confira meu anúncio!" — a frase do
 * alto-falante. Serve à linha do chat e à prévia do diálogo de confirmação, para o vendedor ler
 * exatamente o que vai sair. O "cada" só entra no lote: o preço do Mercado é por unidade, e "100x
 * por 20 Gemas" sem ele diria que o lote inteiro sai por 20.
 */
function fraseDoAnuncioNoChat(o) {
  const nome = `<b class="m-anuncio-nome">${escapar(nomeDaOfertaNoChat(o))}</b>`;
  const orb = o.moeda === 'orb';
  const preco = `<b class="m-anuncio-preco${orb ? ' orb' : ''}">`
    + `<img src="${orb ? ICONE_GEMA : srcIcone(ICONE_OURO)}" alt="">${num(o.preco)} ${t(orb ? 'cm.emGemas' : 'cm.emCoins')}</b>`;
  return t(o.qtd > 1 ? 'chat.anuncioMercadoCada' : 'chat.anuncioMercado', { qtd: num(o.qtd), nome, preco });
}

/**
 * A linha do ALTO-FALANTE do Mercado. A frase inteira é o botão — quem se interessa clica onde o
 * olho parou, como no convite do Discord —, e o "Ver anúncio" no fim é o que diz que dá para
 * clicar. O id é o único dado do servidor que vira atributo, e passa por `Number`.
 */
const textoDeAnuncioMercado = (m) => {
  if (!m.anuncioChat?.id) return null;
  return `<button type="button" class="m-anuncio-link" data-anuncio="${Number(m.anuncioChat.id) || ''}">`
    + `${fraseDoAnuncioNoChat(m.anuncioChat)}<span class="m-anuncio-cta">${t('chat.anuncioVer')}</span></button>`;
};

function textoBalaoChat(m) {
  if (m.pkShare) return `${t('chat.vejaMeuPokemon')} ${nomeExibidoPokemon(m.pkShare) || ''}`;
  // O alto-falante traz um `texto` só como reserva para a aba de antes da feature (ver
  // `textoDoAltoFalante` no sim): é anúncio no chat, não fala do boneco na praça.
  if (m.anuncioChat) return null;
  // A captura de lendário também traz `texto` só de reserva (ver `anunciarLendarioCapturado`).
  if (m.lendarioCaptura) return null;
  // A da tag do Discord, idem (ver `anunciarTagDiscord`).
  if (m.tagDiscord) return null;
  if (m.texto) return trocarApelidos(m.texto);
  return null;
}

/** A setinha de RESPONDER (↩): a curva que volta para a esquerda, como nos chats que todo mundo usa. */
const GLIFO_RESPONDER = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 5L4 11l6 6" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><path d="M4.5 11H14a6 6 0 0 1 6 6v2" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg>';

/**
 * Para quem a linha pode ser RESPONDIDA — o jogador de quem ela fala —, ou `null`. Numa fala é o
 * autor; no ALTO-FALANTE do Mercado é o vendedor (o `de` do anúncio é o nick dele); nos avisos do
 * sistema (shiny, Lendário, drop, convite, tag, entrada no PvP) é o jogador do aviso — "@fulano
 * parabéns" é a resposta mais comum que essas linhas recebem.
 *
 * O remetente dos avisos ("⚔ PvP", "👑 Drop", "🌍 Temporada Global"…) não passa no filtro de nick
 * de `RE_MENCAO`, e é isso — não o cargo `anuncio`, que o alto-falante também usa — que tira o
 * sistema da conta. A própria fala não se responde.
 */
function alvoDeResposta(m, d) {
  const alvo = d.dataset.jogador || m.dropLendario?.nick || m.conviteResgate?.nick || m.tagDiscord?.nick
    || m.nickDestaque || d.dataset.de || '';
  if (!/^[a-zA-Z0-9_]{3,16}$/.test(alvo)) return null;
  return alvo.toLowerCase() === meuNickChat() ? null : alvo;
}

/** Uma linha da lista. Sai pronta para o `appendChild` — quem chama decide onde entra. */
function linhaDeChat(m) {
  const d = document.createElement('div');
  const selo = seloDeCargo(m.cargo);
  const clsCargo = selo || CARGOS_SEM_SELO.has(m.cargo)
    || m.cargo === 'anuncio' || m.cargo === 'compartilhar' || m.cargo === 'shiny' ? ` ${m.cargo}` : '';
  const clsPvp = m.pvpEntrada ? ` pvp-${m.pvpEntrada}`
    : m.dropLendario ? ' drop-lendario'
    : m.lendarioCaptura ? ' drop-lendario lendario-captura'
    : m.conviteResgate || m.tagDiscord ? ' convite-resgate'
    : m.anuncioChat ? ' anuncio-mercado' : '';
  if (m.id) d.dataset.msgId = m.id;
  // Quem escreveu, na própria linha: é daqui que o painel tira o alvo das ações, sem
  // ter de reencontrar a mensagem no `estado.mensagens` pelo id.
  if (m.de) d.dataset.de = m.de;
  // No anúncio de shiny quem "escreve" é o sistema (`de: '✨ Shiny'`), e o jogador da linha é
  // quem CAPTUROU. Sem isto o painel pedia o perfil (e a amizade) do treinador "✨ Shiny", que
  // não existe. Ver `abrirPainelModChat`.
  if (m.shinyCaptura?.nick) d.dataset.jogador = m.shinyCaptura.nick;
  if (m.lendarioCaptura?.nick) d.dataset.jogador = m.lendarioCaptura.nick;
  // As menções só valem na fala digitada. Anúncio de PvP, shiny e pokémon compartilhado já
  // chegam aqui como HTML montado por nós, com `<i>` e botão dentro — passar o regex por
  // cima seria pintar menção em pedaço de tag.
  const montado = textoDeAnuncioPvp(m) ?? textoDeCompartilharPk(m) ?? textoDeShinyCaptura(m)
    ?? textoDeDropLendario(m) ?? textoDeLendarioCaptura(m) ?? textoDeConviteResgate(m) ?? textoDeTagDiscord(m)
    ?? textoDeAnuncioMercado(m);
  const fala = montado ? null : comMencoes(escapar(trocarApelidos(m.texto)));
  const corpo = montado ?? comEmojiVip(comEmoji(fala.texto));
  // A linha acesa é para quem foi CHAMADO. Na sua própria mensagem ela não acende: você
  // sabe que escreveu o `@` e não precisa que a lista lhe avise disso.
  const chamaram = !!fala?.paraMim && String(m.de ?? '').toLowerCase() !== meuNickChat();
  d.className = 'chat-msg' + clsCargo + clsPvp + (chamaram ? ' mencao' : '');
  // A tag de FUNDADOR saiu daqui e foi para a FICHA do jogador (ver `htmlPerfilTreinador`).
  //
  // Ela dizia uma coisa verdadeira — quem bancou o jogo no começo —, mas dizia em toda linha,
  // para sempre, ao lado do selo de cargo, da tag da guild e do nível. Com quatro marcas antes
  // do nick, a coluna do chat virou mais etiqueta do que conversa, e a primeira coisa que se
  // perde numa linha assim é justamente o que a pessoa escreveu.
  //
  // Na ficha ela aparece uma vez, do lado do nick, para quem foi ver QUEM é aquele jogador —
  // que é a pergunta a que ela responde. O `m.fundador` continua viajando na mensagem e no
  // histórico: não custa nada e um dia pode voltar a ser desenhado sem migração nenhuma.
  // O drop Lendário e o Convite já são a frase inteira ("[DROP Lendário] O jogador …"): sem
  // remetente na frente.
  // A TAG DA GUILD, entre o selo de cargo e o nick — o lugar onde todo MMO a põe. A cor vem
  // da mensagem, mas passa por `corTagValida` aqui também: ela chega pelo fio, e a regra desta
  // tela é que nada que veio de fora entra num `style` sem peneira. Fora da paleta vira o ouro
  // padrão em vez de um `style` com texto de estranho dentro.
  const tagGuild = m.guildTag
    ? `<span class="m-guild-tag" style="--gt:${corTagValida(m.guildTagCor)}">`
      + `${escapar(String(m.guildTag).slice(0, MAX_TAG_GUILD))}</span>`
    : '';
  const deHtml = m.dropLendario || m.lendarioCaptura || m.conviteResgate || m.tagDiscord
    ? ''
    : `<span class="m-de">${m.anuncioChat ? '<span class="m-alto" aria-hidden="true">📢</span>' : ''}`
      + `${selo ? `<span class="m-selo">${selo}</span>` : ''}${tagGuild}` +
      `${escapar(m.de)}${m.nivel != null ? `<span class="m-nv"> [${m.nivel}]</span>` : ''}:</span> `;
  // A setinha de responder, no canto da linha — aparece no hover (ver `.m-responder`). Quem clica
  // começa a frase com "@nick" (`responderNoChat`); no celular a mesma ação mora no painel.
  const responder = alvoDeResposta(m, d);
  const btResponder = responder
    ? `<button type="button" class="m-responder" data-nick="${escapar(responder)}"
        title="${escapar(t('chat.responderA', { nick: responder }))}"
        aria-label="${escapar(t('chat.responderA', { nick: responder }))}">${GLIFO_RESPONDER}</button>`
    : '';
  d.innerHTML =
    `<span class="m-hora">${horaDaMsg(m.ts)}</span> ` +
    marcaDeCargo(m.cargo) +
    deHtml +
    `<span class="m-txt">${corpo}</span>` +
    btResponder;
  return d;
}

/**
 * Responder: o campo de digitar passa a começar com "@nick " e ganha o foco, com o cursor no fim.
 * Se a frase já começava com OUTRO "@alguém", a menção é trocada — e o que estava escrito fica.
 * Campo travado (nível, mute, guild que não existe) não muda: o aviso é o próprio motivo dele.
 */
function responderNoChat(nick, inp = $('#chat-input')) {
  if (!nick || !inp) return;
  fecharPainelModChat();
  if (inp.disabled) return toast(inp.placeholder || t('chat.nivelMinimo', { n: CHAT_NIVEL_MIN }));
  const menc = inp.value.match(/^@[a-zA-Z0-9_]{3,16} */);
  const resto = menc ? inp.value.slice(menc[0].length) : inp.value.replace(/^ +/, '');
  const max = Number(inp.maxLength) > 0 ? Number(inp.maxLength) : 200;
  inp.value = `@${nick} ${resto}`.slice(0, max);
  inp.focus();
  inp.setSelectionRange?.(inp.value.length, inp.value.length);
}

/**
 * Aviso local na lista — não vai pro histórico nem pro fan-out.
 *
 * `vars` carrega placeholders (nick, minutos…) nas traduções dos avisos locais.
 */
function linhaAvisoChat(chave, vars = {}) {
  const d = document.createElement('div');
  d.className = 'chat-msg aviso';
  d.innerHTML =
    `<span class="m-hora">${horaDaMsg(Date.now())}</span> ` +
    `<span class="m-txt">${comEmoji(escapar(t(chave ?? 'chat.nftBloqueado', vars)))}</span>`;
  return d;
}

/** O endereço como o jogador o lê. O `https://` não diz nada e a coluna do chat é estreita. */
const semEsquema = (url) => String(url).replace(/^https?:\/\//, '');

/**
 * O mesmo aviso local, com um LINK clicável no fim — a resposta do `/site` e do `/ticket`.
 *
 * O texto vem do dicionário e a URL de uma constante nossa: nada aqui sai do que alguém
 * digitou. Mesmo assim o `<a>` é montado como NÓ, com `textContent` — o resto do chat
 * escapa tudo, e uma segunda porta que aceitasse HTML seria justamente a que um dia
 * receberia texto de jogador.
 */
function linhaLinkChat(chave, url, { depois = null, classe = '' } = {}) {
  const d = document.createElement('div');
  d.className = `chat-msg aviso${classe ? ` ${classe}` : ''}`;

  const hora = document.createElement('span');
  hora.className = 'm-hora';
  hora.textContent = horaDaMsg(Date.now());

  const txt = document.createElement('span');
  txt.className = 'm-txt';
  txt.textContent = `${t(chave)} `;

  const a = document.createElement('a');
  a.href = url;
  a.target = '_blank';
  // Abre em aba nova; sem `noopener` a página de destino recebe uma referência ao nosso
  // `window` e pode reescrever a aba do jogo por baixo — ver `montarRedes`.
  a.rel = 'noopener noreferrer';
  a.textContent = semEsquema(url);
  txt.appendChild(a);

  // Uma segunda linha DEPOIS do endereço — hoje a sala do `/ticket`. Vai em `<br>` + nó de
  // texto, e não numa string de HTML, pelo mesmo motivo do `<a>`: nada aqui é montado a
  // partir de texto de jogador, e é assim que continua sendo.
  if (depois) {
    txt.appendChild(document.createElement('br'));
    txt.appendChild(document.createTextNode(t(depois)));
  }

  d.append(hora, document.createTextNode(' '), txt);
  return d;
}

/** Põe na lista uma linha que só existe AQUI: sem histórico, sem fan-out, sem servidor. */
function anexarLinhaLocalChat(linha) {
  const box = $('#chat-msgs');
  if (!box) return;
  const colado = chatNoFim();
  box.querySelector('.chat-vazio')?.remove();
  box.appendChild(linha);
  if (colado) rolarChatAoFim();
  else marcarChatNovas(estado.chatNovas + 1);
  seloChatMobile();
}

function mostrarAvisoChat(chave = 'chat.nftBloqueado', vars = {}) {
  anexarLinhaLocalChat(linhaAvisoChat(chave, vars));
}

function mostrarLinkChat(chave, url, opcoes) {
  anexarLinhaLocalChat(linhaLinkChat(chave, url, opcoes));
}

// ------------------------------------------------------------------ canal do chat (sessão)

const CHAVE_CANAL_CHAT_SESSAO = 'chatCanal';

function persistirCanalChatSessao() {
  try {
    if (ehCanalPublico(estado.canalChat)) {
      sessionStorage.setItem(CHAVE_CANAL_CHAT_SESSAO, estado.canalChat);
    }
  } catch { /* aba anônima / quota */ }
}

function limparCanalChatSessao() {
  try {
    sessionStorage.removeItem(CHAVE_CANAL_CHAT_SESSAO);
  } catch { /* ok */ }
}

function restaurarCanalChatSessao() {
  try {
    const canal = sessionStorage.getItem(CHAVE_CANAL_CHAT_SESSAO);
    if (ehCanalPublico(canal)) estado.canalChat = canal;
  } catch { /* ok */ }
  syncChatInput();
  syncBotaoOpcoesChat();
  pintarSelosChatAbas();
}

/** Troca de canal por código — o mesmo caminho de uma opção do seletor. */
function trocarCanalChat(canal) {
  // Um canal que o jogador não pode abrir (a Guild sem guild, um id velho da sessão) cai no Mundo.
  if (!canaisDoJogador().some((c) => c.id === canal)) canal = 'mundo';
  estado.canalChat = canal;
  if (ehCanalPublico(canal)) {
    marcarCanalChatVisto(canal);
    // O Mundo vem no login; os outros, na primeira vez que o canal é aberto — quem nunca abre o
    // Comércio não baixa duas horas de anúncio à toa.
    if (canal !== 'mundo') pedirHistoricoChat(canal);
  }
  syncChatInput();
  syncBotaoOpcoesChat();
  fecharPainelModChat();
  pintarChat();
  pintarSelosChatAbas();
  persistirCanalChatSessao();
}

let chatModAlvo = null;
/** Nick alvo do mute — preenchido ao abrir o sub-painel de duração. */
let chatMuteAlvo = null;
/** Nick alvo do ignorar pessoal — filtro só local. */
let chatIgnorarAlvo = null;
/** Nick alvo do Ver perfil — abre a ficha pública do treinador. */
let chatVerPerfilAlvo = null;
/** Nick alvo do Adicionar amigo — envia pedido de amizade. */
let chatAmigoAlvo = null;
/** Linha do chat usada para posicionar o painel (ações ou duração). */
let chatModLinha = null;
/** O que o botão Fixar do painel faz: `{ id }` fixa; `{ desafixar, canal, idioma }` tira. Só admin. */
let chatFixarAlvo = null;
/** Nick a quem o "Responder" do painel responde — o caminho do celular, que não tem hover. */
let chatResponderAlvo = null;

function voltarPainelModAcoes() {
  $('#chat-mod-view-mute')?.classList.add('hidden');
  $('#chat-mod-view-acoes')?.classList.remove('hidden');
}

function fecharPainelModChat() {
  chatModAlvo = null;
  chatMuteAlvo = null;
  chatIgnorarAlvo = null;
  chatVerPerfilAlvo = null;
  chatAmigoAlvo = null;
  chatModLinha = null;
  chatFixarAlvo = null;
  chatResponderAlvo = null;
  voltarPainelModAcoes();
  const painel = $('#chat-mod-panel');
  if (!painel) return;
  painel.classList.add('hidden');
  painel.setAttribute('aria-hidden', 'true');
}

function posicionarPainelModChat(linha) {
  const vao = document.querySelector('.chat-vao');
  const painel = $('#chat-mod-panel');
  if (!vao || !painel || !linha) return;
  const vr = vao.getBoundingClientRect();
  const lr = linha.getBoundingClientRect();
  const top = Math.max(4, Math.min(lr.top - vr.top, vr.height - painel.offsetHeight - 4));
  const left = Math.min(lr.right - vr.left + 6, vr.width - painel.offsetWidth - 4);
  painel.style.top = `${top}px`;
  painel.style.left = `${Math.max(4, left)}px`;
}

/**
 * O painel de ações de uma mensagem — ignorar, ver perfil, adicionar amigo (Mundo); moderador também muta e exclui.
 */
function abrirPainelModChat(linha) {
  if (!linha?.dataset.msgId) return;
  fecharPainelIgnorados();
  const de = linha.dataset.de ?? '';
  // O jogador de quem a linha FALA. Numa mensagem digitada é o autor; no anúncio de shiny é
  // quem capturou (`data-jogador`), porque o autor ali é o sistema. Perfil e amizade vão para
  // ele. Ignorar e mutar não entram no anúncio: os dois agem sobre o que alguém ESCREVEU, e
  // essa linha ninguém escreveu — mutar quem capturou um shiny seria punir por sorte.
  const doSistema = !!linha.dataset.jogador;
  const alvo = linha.dataset.jogador || de;
  const meu = String(estado.eu?.nick ?? estado.nick ?? '').toLowerCase();
  const alvoOutro = !!alvo && alvo.toLowerCase() !== meu && !linha.classList.contains('anuncio');
  const podeIgnorar = alvoOutro && !doSistema;
  const podeMutar = estado.chatMod && podeIgnorar;
  const podeVerPerfil = !!alvo && !linha.classList.contains('anuncio');
  const podeAdicionarAmigo = alvoOutro && estado.canalChat !== 'guild' && podePedirAmizadeNoChat(alvo);
  // RESPONDER vem da própria linha (`alvoDeResposta`): é o caminho do dedo, e é o único que o
  // anúncio do alto-falante oferece a quem não é moderador — sem ele, tocar no anúncio de outro
  // jogador no celular não abria nada.
  const responderAlvo = linha.querySelector(':scope > .m-responder')?.dataset.nick ?? null;
  if (!podeIgnorar && !estado.chatMod && !podeVerPerfil && !podeAdicionarAmigo && !responderAlvo) return;

  chatModAlvo = linha.dataset.msgId;
  chatMuteAlvo = podeMutar ? alvo : null;
  chatIgnorarAlvo = podeIgnorar ? alvo : null;
  chatVerPerfilAlvo = podeVerPerfil ? alvo : null;
  chatAmigoAlvo = podeAdicionarAmigo ? alvo : null;
  chatModLinha = linha;
  voltarPainelModAcoes();

  const painel = $('#chat-mod-panel');
  $('#chat-mod-mute').classList.toggle('hidden', !podeMutar);
  $('#chat-mod-excluir').classList.toggle('hidden', !estado.chatMod);
  $('#chat-ver-perfil')?.classList.toggle('hidden', !podeVerPerfil);
  $('#chat-adicionar-amigo')?.classList.toggle('hidden', !podeAdicionarAmigo);
  const btIgnorar = $('#chat-ignorar');
  if (btIgnorar) {
    btIgnorar.classList.toggle('hidden', !podeIgnorar);
    btIgnorar.textContent = t(podeIgnorar && nickIgnoradoNoChat(alvo) ? 'chat.designorar' : 'chat.ignorar');
  }
  // RESPONDER: o mesmo da setinha do hover, aqui para o dedo — no celular não existe hover.
  chatResponderAlvo = responderAlvo;
  $('#chat-responder')?.classList.toggle('hidden', !chatResponderAlvo);
  // FIXAR: só admin, e só nos canais abertos (a Guild é conversa de dentro). Na linha que já é a
  // fixada, o mesmo botão desafixa — é ali que o admin vai procurar a volta.
  const podeFixar = estado.souAdmin && estado.canalChat !== 'guild' && ehCanalPublico(estado.canalChat);
  const fixadaAgora = podeFixar ? fixadaNaTela() : null;
  chatFixarAlvo = !podeFixar ? null
    : fixadaAgora?.msg?.id === linha.dataset.msgId
      ? { desafixar: true, canal: fixadaAgora.canal, idioma: fixadaAgora.idioma }
      : { id: linha.dataset.msgId };
  const btFixar = $('#chat-mod-fixar');
  if (btFixar) {
    btFixar.classList.toggle('hidden', !podeFixar);
    btFixar.textContent = t(chatFixarAlvo?.desafixar ? 'chat.desafixar' : 'chat.fixar');
  }
  $('#chat-mod-titulo').textContent = alvo || t('chat.modTitulo');
  painel.classList.remove('hidden');
  painel.setAttribute('aria-hidden', 'false');
  posicionarPainelModChat(linha);
}

function abrirPainelMuteDuracao() {
  if (!chatMuteAlvo || !chatModLinha) return;
  $('#chat-mod-view-acoes').classList.add('hidden');
  $('#chat-mod-view-mute').classList.remove('hidden');
  $('#chat-mod-mute-titulo').textContent = t('chat.modMuteTitulo', { nick: chatMuteAlvo });
  posicionarPainelModChat(chatModLinha);
}

function excluirChat(id) {
  if (!id) return;
  for (const lista of Object.values(estado.mensagens)) {
    const i = lista.findIndex((m) => m.id === id);
    if (i >= 0) lista.splice(i, 1);
  }
  document.querySelector(`.chat-msg[data-msg-id="${CSS.escape(id)}"]`)?.remove();
  if (chatModAlvo === id) fecharPainelModChat();
  const box = $('#chat-msgs');
  if (box && !box.querySelector('.chat-msg') && !box.querySelector('.chat-vazio')) {
    const vazio = document.createElement('div');
    vazio.className = 'chat-vazio';
    vazio.textContent = textoChatVazio();
    box.appendChild(vazio);
  }
  if (estado.modalAberto === 'amigos' && amigosUI().sel === AMIGO_SEL_GUILD) pintarThreadGuild(false);
}

/** Pede ao servidor as mensagens persistidas de um canal público. */
function pedirHistoricoChat(canal, { forcar = false } = {}) {
  if (!CANAIS_CHAT_PUBLICOS.includes(canal)) return;
  if (canal === 'guild' && !estado.eu?.guild?.id) return;
  estado.chatHistoricoPedido ??= {};
  if (!forcar && estado.chatHistoricoPedido[canal]) return;
  estado.chatHistoricoPedido[canal] = true;
  enviar({ t: 'chat.historico', canal });
}

/** Funde histórico do banco com o buffer local, sem duplicar ids. */
function mesclarChatHistorico(canal, mensagens) {
  if (!ehCanalPublico(canal) || !mensagens?.length) return;
  const ids = new Set((estado.mensagens[canal] ?? []).map((m) => m.id));
  const novas = mensagens.filter((m) => m.id && !ids.has(m.id));
  if (!novas.length && (estado.mensagens[canal] ?? []).length) return;
  const lista = [...novas, ...(estado.mensagens[canal] ?? [])];
  lista.sort((a, b) => (a.ts ?? 0) - (b.ts ?? 0));
  while (lista.length > 200) lista.shift();
  estado.mensagens[canal] = lista;
  if (canal === estado.canalChat) pintarChat();
  if (estado.modalAberto === 'amigos' && canal === 'guild' && amigosUI().sel === AMIGO_SEL_GUILD) {
    pintarThreadGuild(true);
  }
}

// ------------------------------------------------------------- a MENSAGEM FIXADA
//
// O "pinned" da Twitch: um ADMIN prende uma mensagem no topo de um canal aberto e ela fica por
// cima da conversa, para todo mundo que lê aquele canal naquela língua, até alguém tirar. Quem
// decide quem pode é o gateway (ver `CHAT_FIXAR`); aqui só se desenha o que ele mandou.

const chaveFixada = (canal, idioma) => `${canal}:${idioma ?? 'pt'}`;

/** A lista inteira — na entrada, e de novo a cada reconexão (o que mudou fora, chega aqui). */
function receberChatFixadas(lista) {
  estado.chatFixadas = {};
  for (const f of lista) {
    if (f?.canal && f?.msg) estado.chatFixadas[chaveFixada(f.canal, f.idioma)] = f;
  }
  pintarChatFixada();
}

/** Uma troca ao vivo: `fixada` nula é desafixar (ou a mensagem foi apagada). */
function receberChatFixada(m) {
  const chave = chaveFixada(m.canal, m.idioma);
  if (m.fixada?.msg) estado.chatFixadas[chave] = m.fixada;
  else delete estado.chatFixadas[chave];
  pintarChatFixada();
}

/** A fixada do canal e da bandeira que estão na tela — ou `null`. O "ignorar" vale para ela também. */
function fixadaNaTela() {
  const f = estado.chatFixadas?.[chaveFixada(estado.canalChat, estado.idiomaChat)];
  if (!f?.msg || msgIgnorada(f.msg)) return null;
  return f;
}

/** Recolher é escolha de quem lê, e vale para AQUELA fixada: a próxima que um admin prender abre. */
const CHAVE_FIXADA_RECOLHIDA = 'chatFixadaRecolhida';
const fixadaRecolhida = () => {
  try { return localStorage.getItem(CHAVE_FIXADA_RECOLHIDA); } catch { return null; }
};
function guardarFixadaRecolhida(id) {
  try {
    if (id) localStorage.setItem(CHAVE_FIXADA_RECOLHIDA, id);
    else localStorage.removeItem(CHAVE_FIXADA_RECOLHIDA);
  } catch {}
}

const GLIFO_PINO = '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M14.6 2.4l7 7-1.8 1-3.4 3.4.6 4.8-1.7 1.7-4.4-4.4-5.6 5.6H3.9v-1.4l5.6-5.6-4.4-4.4 1.7-1.7 4.8.6 3.4-3.4z"/></svg>';
const GLIFO_DOBRA = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 15l6-6 6 6" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>';
/** O id da última fixada desenhada — a que é NOVA entra com o movimento; repintar a mesma, não. */
let fixadaDesenhada = null;

/**
 * O cartão no topo do chat. A linha de dentro é a MESMA da conversa (`linhaDeChat`: selo de
 * cargo, tag da guild, nick, emojis), sem o horário. Recolhido, ele vira uma linha só. Para
 * admin, o × desafixa ali mesmo.
 */
function pintarChatFixada() {
  const host = $('#chat-fixada');
  if (!host) return;
  const f = fixadaNaTela();
  if (!f) {
    host.classList.add('hidden');
    host.replaceChildren();
    fixadaDesenhada = null;
    ajustarRespiroFixada();
    return;
  }
  const recolhida = fixadaRecolhida() === f.msg.id;
  const nova = fixadaDesenhada !== f.msg.id;
  fixadaDesenhada = f.msg.id;
  const rotuloDobra = t(recolhida ? 'chat.fixadaAbrir' : 'chat.fixadaRecolher');
  host.className = `chat-fixada${recolhida ? ' recolhida' : ''}${nova ? ' entra' : ''}`;
  host.innerHTML = `
    <div class="chat-fixada-cab">
      <span class="chat-fixada-pino">${GLIFO_PINO}</span>
      <span class="chat-fixada-por">${t('chat.fixadaPor', { nick: `<b>${escapar(f.por ?? '')}</b>` })}</span>
      ${estado.souAdmin ? `<button type="button" class="chat-fixada-bt chat-fixada-tirar"
        title="${escapar(t('chat.desafixar'))}" aria-label="${escapar(t('chat.desafixar'))}">×</button>` : ''}
      <button type="button" class="chat-fixada-bt chat-fixada-dobrar" aria-expanded="${recolhida ? 'false' : 'true'}"
        title="${escapar(rotuloDobra)}" aria-label="${escapar(rotuloDobra)}">${GLIFO_DOBRA}</button>
    </div>`;
  const linha = linhaDeChat(f.msg);
  // A cópia do topo não é a linha da conversa: sem o id, o "excluir" e o painel de moderação
  // continuam achando só a de baixo.
  delete linha.dataset.msgId;
  linha.classList.add('chat-fixada-msg');
  host.appendChild(linha);
  host.querySelector('.chat-fixada-dobrar').onclick = () => {
    guardarFixadaRecolhida(recolhida ? null : f.msg.id);
    pintarChatFixada();
  };
  host.querySelector('.chat-fixada-tirar')?.addEventListener('click', () => {
    enviar({ t: 'chat.desafixar', canal: f.canal, idioma: f.idioma });
  });
  ajustarRespiroFixada();
}

/**
 * O respiro no topo da lista, da altura do cartão: subindo tudo, a primeira linha aparece
 * inteira embaixo dele em vez de ficar escondida para sempre. Quem estava colado no fim
 * continua colado — o respiro cresce a lista por cima, e a conversa nova não pode sumir.
 */
function ajustarRespiroFixada() {
  const host = $('#chat-fixada');
  const box = $('#chat-msgs');
  if (!host || !box) return;
  const colado = chatNoFim();
  const altura = host.classList.contains('hidden') ? 0 : host.offsetHeight;
  box.style.paddingTop = altura ? `${altura + 12}px` : '';
  if (colado) rolarChatAoFim();
}
// O cartão muda de altura sozinho (o chat que reabre, a fonte que carrega, a linha que quebra
// num celular girado) — e o respiro acompanha.
if (typeof ResizeObserver !== 'undefined' && $('#chat-fixada')) {
  new ResizeObserver(() => ajustarRespiroFixada()).observe($('#chat-fixada'));
}

/** Colado no fim? Só então a lista se move sozinha quando chega mensagem. */
const chatNoFim = () => {
  const box = $('#chat-msgs');
  return box.scrollHeight - box.scrollTop - box.clientHeight < 40;
};

const rolarChatAoFim = () => {
  const box = $('#chat-msgs');
  box.scrollTop = box.scrollHeight;
};

/**
 * A pílula "N novas mensagens".
 *
 * Existe porque as duas alternativas são piores: puxar a lista para baixo no meio de uma
 * leitura tira a linha dos olhos de quem estava lendo, e não fazer nada deixa a pessoa
 * parada num chat que ela pensa estar morto.
 */
function marcarChatNovas(n) {
  estado.chatNovas = Math.max(0, n);
  const btn = $('#chat-novas');
  btn.classList.toggle('hidden', estado.chatNovas === 0);
  if (estado.chatNovas === 1) btn.textContent = t('chat.novas1');
  else if (estado.chatNovas > 1) btn.textContent = t('chat.novasN', { n: estado.chatNovas });
}

/**
 * Redesenha a lista INTEIRA. Só para troca de canal ou de bandeira, que são os dois casos
 * em que o conjunto de mensagens muda de uma vez.
 *
 * Mensagem nova NÃO passa por aqui: `innerHTML = ''` zera o `scrollTop`, então repintar
 * tudo a cada linha jogaria de volta ao fim quem tivesse subido para ler. Quem chega
 * sozinha entra por `appendChild` em `receberChat`.
 */
function pintarChat() {
  fecharPainelModChat();
  const box = $('#chat-msgs');
  box.innerHTML = '';
  const doCanal = (estado.mensagens[estado.canalChat] ?? []).filter(
    (m) => !msgForaDoChat(m) && idiomaDaMsg(m) === estado.idiomaChat,
  );
  if (!doCanal.length) {
    const vazio = document.createElement('div');
    vazio.className = 'chat-vazio';
    vazio.textContent = textoChatVazio();
    box.appendChild(vazio);
  }
  for (const m of doCanal) box.appendChild(linhaDeChat(m));
  // A fixada é do canal E da bandeira: trocar qualquer um dos dois troca o cartão do topo.
  pintarChatFixada();
  rolarChatAoFim();
  marcarChatNovas(0);
  if (ehCanalPublico(estado.canalChat)) marcarCanalChatVisto(estado.canalChat);
}

$('#chat-msgs').addEventListener(
  'scroll',
  () => {
    if (estado.chatNovas > 0 && chatNoFim()) marcarChatNovas(0);
  },
  { passive: true },
);

$('#chat-novas').onclick = () => {
  rolarChatAoFim();
  marcarChatNovas(0);
};

$('#chat-msgs').addEventListener('click', (ev) => {
  // A setinha de responder é do ouvinte do documento (ela também mora no cartão fixado e na
  // conversa da guild); aqui ela só não pode abrir o painel da linha por baixo.
  if (ev.target.closest('.m-responder')) return;
  const link = ev.target.closest('.m-pk-link');
  if (link) {
    ev.stopPropagation();
    const nick = link.dataset.nick;
    const pokemonId = Number(link.dataset.pk);
    if (!nick || !pokemonId) return;
    const meuNick = estado.eu?.nick ?? estado.nick;
    if (meuNick && meuNick.toLowerCase() === nick.toLowerCase()) {
      const local = estado.eu?.pokemons?.find((p) => p.id === pokemonId);
      if (local) return abrirFichaDoPokemon(local);
    }
    enviar({ t: 'chat.verPokemon', nick, pokemonId });
    return;
  }
  // O ALTO-FALANTE do Mercado: a frase leva ao anúncio. Antes do painel de moderação, pelo mesmo
  // motivo do convite logo abaixo — o clique é do link, e não da linha.
  const anuncio = ev.target.closest('.m-anuncio-link');
  if (anuncio) {
    ev.stopPropagation();
    abrirAnuncioNoMercado(Number(anuncio.dataset.anuncio));
    return;
  }
  // O convite do Discord no anúncio do Convide & Ganhe é um `<a>` de verdade, e abrir a aba é
  // trabalho dele. Sem esta saída o MESMO clique escorregaria para a linha e abriria o painel
  // de moderação por baixo da aba nova — o jogador voltaria do Discord para um painel que não
  // pediu.
  if (ev.target.closest('.m-convite-link')) {
    ev.stopPropagation();
    return;
  }
  // Quem decide o que aparece lá dentro é `abrirPainelModChat`.
  const linha = ev.target.closest('.chat-msg[data-msg-id]');
  if (!linha) return;
  ev.stopPropagation();
  abrirPainelModChat(linha);
});

$('#chat-ver-perfil')?.addEventListener('click', () => {
  const nick = chatVerPerfilAlvo;
  fecharPainelModChat();
  if (!nick) return;
  const meu = String(estado.eu?.nick ?? estado.nick ?? '').toLowerCase();
  if (nick.toLowerCase() === meu) abrirModal('perfil');
  else pedirPerfil(nick);
});

$('#chat-adicionar-amigo')?.addEventListener('click', () => {
  const nick = chatAmigoAlvo;
  fecharPainelModChat();
  if (!nick) return;
  if ((estado.eu?.level ?? 0) < CHAT_NIVEL_MIN && !estado.souAdmin) {
    toast(t('amigos.nivelMinimo'));
    return;
  }
  enviar({ t: 'amigo.pedir', nick });
});

$('#chat-ignorar')?.addEventListener('click', () => {
  const nick = chatIgnorarAlvo;
  if (!nick) return;
  const ignorado = alternarIgnorarChat(nick);
  limparMsgsDeIgnorados();
  toast(t(ignorado ? 'chat.ignoradoOk' : 'chat.designoradoOk', { nick }));
  fecharPainelModChat();
  pintarChat();
  pintarSelosChatAbas();
  pintarPainelIgnorados();
});

$('#chat-mod-mute')?.addEventListener('click', () => {
  if (!chatMuteAlvo) return;
  abrirPainelMuteDuracao();
});

$('#chat-mod-mute-voltar')?.addEventListener('click', () => {
  voltarPainelModAcoes();
  if (chatModLinha) posicionarPainelModChat(chatModLinha);
});

document.querySelectorAll('.chat-mod-mute-opt').forEach((btn) => {
  btn.addEventListener('click', () => {
    const nick = chatMuteAlvo;
    const minutos = Number(btn.dataset.min);
    if (!nick || !minutos) return;
    if (!enviar({ t: 'chat.mute', nick, minutos })) return;
    fecharPainelModChat();
  });
});

// RESPONDER — a setinha das linhas. Um ouvinte só, no documento: as três listas que desenham
// `linhaDeChat` (o chat, o cartão fixado e a conversa da guild no painel de amigos) usam a mesma
// linha, e a da guild escreve no campo DELA.
document.addEventListener('click', (ev) => {
  const bt = ev.target.closest('.m-responder');
  if (!bt) return;
  ev.stopPropagation();
  responderNoChat(bt.dataset.nick, bt.closest('#guild-chat-thread') ? $('#guild-chat-input') : $('#chat-input'));
});

$('#chat-responder')?.addEventListener('click', () => responderNoChat(chatResponderAlvo));

$('#chat-mod-fixar')?.addEventListener('click', () => {
  const alvo = chatFixarAlvo;
  fecharPainelModChat();
  if (!alvo) return;
  if (alvo.desafixar) enviar({ t: 'chat.desafixar', canal: alvo.canal, idioma: alvo.idioma });
  else enviar({ t: 'chat.fixar', id: alvo.id });
});

$('#chat-mod-excluir')?.addEventListener('click', () => {
  if (!chatModAlvo) return;
  const id = chatModAlvo;
  if (!enviar({ t: 'chat.delete', id })) return;
  excluirChat(id);
  toast(t('chat.modExcluido'));
});

document.addEventListener('click', (ev) => {
  if ($('#chat-mod-panel')?.classList.contains('hidden')) return;
  if (ev.target.closest('#chat-mod-panel') || ev.target.closest('.chat-msg[data-msg-id]')) return;
  fecharPainelModChat();
});

document.addEventListener('click', (ev) => {
  if ($('#chat-ignorados-panel')?.classList.contains('hidden')) return;
  if (ev.target.closest('#chat-ignorados-panel') || ev.target.closest('#chat-ignorados-btn')) return;
  fecharPainelIgnorados();
});

/**
 * As bandeirinhas do chat, ao lado das abas de canal.
 *
 * São SEPARADAS das bandeiras do canto inferior esquerdo de propósito: a língua da interface
 * e a língua em que se conversa não são a mesma escolha. Quem joga em inglês e conversa em
 * português é o caso comum aqui, não a exceção.
 */
function fecharPainelIgnorados() {
  $('#chat-ignorados-panel')?.classList.add('hidden');
  $('#chat-ignorados-panel')?.setAttribute('aria-hidden', 'true');
  $('#chat-ignorados-btn')?.classList.remove('on');
}

function pintarPainelIgnorados() {
  const lista = $('#chat-ignorados-lista');
  const vazio = $('#chat-ignorados-vazio');
  const titulo = $('#chat-ignorados-titulo');
  const btn = $('#chat-ignorados-btn');
  if (!lista || !vazio) return;
  titulo && (titulo.textContent = t('chat.ignoradosTitulo'));
  btn && (btn.title = t('chat.ignoradosBtn'));
  btn?.setAttribute('aria-label', t('chat.ignoradosBtn'));
  const nicks = [...chatIgnorados].sort((a, b) =>
    nickExibicaoIgnorado(a).localeCompare(nickExibicaoIgnorado(b), undefined, { sensitivity: 'base' }),
  );
  btn?.classList.toggle('tem-itens', nicks.length > 0);
  vazio.textContent = t('chat.ignoradosVazio');
  vazio.classList.toggle('hidden', nicks.length > 0);
  lista.innerHTML = '';
  for (const chave of nicks) {
    const exib = nickExibicaoIgnorado(chave);
    const item = document.createElement('button');
    item.type = 'button';
    item.className = 'chat-ignorados-item';
    item.title = t('chat.ignoradosDesignorar');
    item.textContent = exib;
    item.onclick = (ev) => {
      ev.stopPropagation();
      const nick = designorarChat(chave);
      if (!nick) return;
      toast(t('chat.designoradoOk', { nick }));
      limparMsgsDeIgnorados();
      pintarChat();
      pintarSelosChatAbas();
      pintarPainelIgnorados();
      if (!chatIgnorados.size) fecharPainelIgnorados();
    };
    lista.appendChild(item);
  }
}

function alternarPainelIgnorados(ancora) {
  const painel = $('#chat-ignorados-panel');
  const btn = $('#chat-ignorados-btn');
  if (!painel || !btn) return;
  if (!painel.classList.contains('hidden')) {
    fecharPainelIgnorados();
    return;
  }
  fecharPainelModChat();
  pintarPainelIgnorados();
  painel.classList.remove('hidden');
  painel.setAttribute('aria-hidden', 'false');
  btn.classList.add('on');
  const alvo = ancora ?? btn;
  const abas = document.querySelector('.chat-abas');
  const host = abas?.getBoundingClientRect();
  const r = alvo.getBoundingClientRect();
  if (host) {
    const larg = painel.offsetWidth || 160;
    painel.style.left = `${Math.max(4, r.right - host.left - larg)}px`;
    painel.style.top = `${r.bottom - host.top + 4}px`;
  }
}

function montarIdiomasDoChat() {
  const abas = document.querySelector('.chat-abas');
  abas.querySelector('.chat-idiomas-wrap')?.remove();
  abas.querySelector('#chat-ignorados-panel')?.remove();

  const wrap = document.createElement('div');
  wrap.className = 'chat-idiomas-wrap';

  const caixa = document.createElement('div');
  caixa.className = 'chat-idiomas';
  caixa.title = t('chat.idioma');

  for (const l of IDIOMAS_DO_CHAT()) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chat-idioma' + (l.id === estado.idiomaChat ? ' on' : '');
    b.dataset.idiomaChat = l.id;
    b.title = l.nome;
    b.innerHTML = l.bandeira;
    b.onclick = () => {
      estado.idiomaChat = l.id;
      localStorage.setItem('idiomaChat', l.id);
      for (const outro of caixa.children) {
        outro.classList.toggle('on', outro.dataset.idiomaChat === l.id);
      }
      fecharPainelModChat();
      fecharPainelIgnorados();
      // A bandeira segue visível com o chat fechado (é ela que diz por qual idioma o selo de
      // não-lidas está contando). Escolher uma e continuar sem ver a conversa não faz sentido.
      definirChatRecolhido(false);
      pintarChat();
      pintarSelosChatAbas();
    };
    caixa.appendChild(b);
  }
  wrap.appendChild(caixa);

  const btnIgn = document.createElement('button');
  btnIgn.type = 'button';
  btnIgn.id = 'chat-ignorados-btn';
  btnIgn.className = 'chat-ignorados-btn';
  btnIgn.title = t('chat.ignoradosBtn');
  btnIgn.setAttribute('aria-label', t('chat.ignoradosBtn'));
  btnIgn.textContent = '×';
  btnIgn.onclick = (ev) => {
    ev.stopPropagation();
    alternarPainelIgnorados(btnIgn);
  };
  wrap.appendChild(btnIgn);
  abas.appendChild(wrap);

  const painel = document.createElement('div');
  painel.id = 'chat-ignorados-panel';
  painel.className = 'chat-ignorados-panel hidden';
  painel.setAttribute('role', 'dialog');
  painel.setAttribute('aria-hidden', 'true');
  painel.innerHTML = `
    <div class="chat-ignorados-titulo" id="chat-ignorados-titulo"></div>
    <div class="chat-ignorados-vazio hidden" id="chat-ignorados-vazio"></div>
    <div class="chat-ignorados-lista" id="chat-ignorados-lista"></div>`;
  abas.appendChild(painel);
  pintarPainelIgnorados();
}
montarIdiomasDoChat();
restaurarCanalChatSessao();

/** Os do teclado, em oito colunas: seis fileiras de rosto, reação e bicho. */
const EMOJIS_TECLADO = [
  '😂', '🤣', '😄', '😉', '😊', '😍', '🤔', '😏',
  '😭', '😡', '😱', '😴', '😎', '🤡', '💀', '👻',
  '❤️', '🔥', '⭐', '✨', '⚡', '🎉', '🏆', '👑',
  '💎', '💰', '👍', '👎', '👌', '👏', '🙏', '💪',
  '👋', '👀', '🎮', '⚔️', '🛡️', '🧪', '✅', '❌',
  '⚠️', '❓', '💤', '🐉', '🦊', '🐺', '🐸', '🐍',
];

const souVip = () => !!estado.eu?.loja?.vip;

/** Escreve na posição do cursor, e não no fim — quem esqueceu um emoji no meio da frase
 *  volta lá, clica, e continua de onde estava. */
function inserirNoChat(txt) {
  const inp = $('#chat-input');
  const i = inp.selectionStart ?? inp.value.length;
  const j = inp.selectionEnd ?? i;
  inp.value = (inp.value.slice(0, i) + txt + inp.value.slice(j)).slice(0, 200);
  const pos = Math.min(i + txt.length, inp.value.length);
  inp.focus();
  inp.setSelectionRange(pos, pos);
}

/** Monta o teclado uma vez; o cadeado do VIP é reavaliado a cada abertura. */
function montarTecladoEmoji() {
  const painel = $('#chat-emojis');
  if (painel.children.length) return;

  for (const e of EMOJIS_TECLADO) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chat-emoji';
    b.textContent = e;
    b.onclick = () => inserirNoChat(e);
    painel.appendChild(b);
  }

  const sec = document.createElement('div');
  sec.className = 'chat-emojis-sec';
  sec.id = 'chat-emojis-sec';
  painel.appendChild(sec);

  for (let n = 1; n <= EMOJIS_VIP_QTD; n++) {
    const token = `:vip${n}:`;
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chat-emoji vip';
    // `lazy` importa: são 112 PNGs, e o painel abre com 8 deles à vista. Sem isso, o
    // primeiro clique no 😊 dispara 112 requisições de uma vez.
    b.innerHTML = `<img src="${artVip(n)}" alt="${token}" loading="lazy">`;
    b.onclick = () => {
      if (!souVip()) return toast(t('chat.vipEmojiTravado'));
      inserirNoChat(token);
    };
    painel.appendChild(b);
  }
}

/** O cadeado e o rótulo da seção VIP, conforme a assinatura de AGORA. */
function pintarTecladoVip() {
  const vip = souVip();
  const sec = $('#chat-emojis-sec');
  if (sec) {
    sec.innerHTML =
      `💎 ${t('chat.vipEmojis')} ` +
      `<span class="${vip ? 'ok' : 'off'}">${t(vip ? 'chat.vipEmojisSeus' : 'chat.vipEmojisTravados')}</span>`;
  }
  for (const b of document.querySelectorAll('.chat-emoji.vip')) {
    b.classList.toggle('travado', !vip);
    b.title = vip ? (b.querySelector('img')?.alt ?? '') : t('chat.vipEmojiTravado');
  }
}


// ---- as OPÇÕES do chat: a setinha ao lado do emoji, só no Mundo
//
// Um painel no mesmo lugar do teclado de emoji (os dois se revezam), com o interruptor
// "Esconder anúncios da comunidade". A seta aponta para cima fechado e vira para baixo aberto —
// o mesmo gesto do chevron que recolhe o chat, no sentido de "abre para cima da linha de digitar".
//
// O alto-falante sai nos DOIS canais, Mundo e Comércio, mas a escolha de esconder é só do Mundo:
// lá o anúncio divide espaço com a conversa; no Comércio ele é o assunto do canal, e quem abriu o
// Comércio foi atrás justamente dele.

/** A setinha aparece só no Mundo; fora dele, o painel que estiver aberto fecha junto. */
function syncBotaoOpcoesChat() {
  const noMundo = estado.canalChat === 'mundo';
  $('#chat-opcoes-btn')?.classList.toggle('hidden', !noMundo);
  if (!noMundo) fecharOpcoesChat();
}

/** O interruptor e a linha de estado ("3 anúncios escondidos agora"), conforme a preferência. */
function pintarOpcoesChat() {
  const bt = $('#chat-sem-anuncios');
  if (bt) {
    bt.classList.toggle('on', semAnunciosNoChat);
    bt.setAttribute('aria-checked', String(semAnunciosNoChat));
  }
  const est = $('#chat-sem-anuncios-estado');
  if (!est) return;
  const n = (estado.mensagens.mundo ?? []).filter(
    (m) => m.anuncioChat && !msgIgnorada(m) && idiomaDaMsg(m) === estado.idiomaChat,
  ).length;
  est.hidden = !semAnunciosNoChat;
  est.textContent = semAnunciosNoChat
    ? n ? t('chat.semAnunciosEscondidos', { n: num(n) }) : t('chat.semAnunciosLigado')
    : '';
}

function fecharOpcoesChat() {
  $('#chat-opcoes')?.classList.add('hidden');
  const b = $('#chat-opcoes-btn');
  b?.classList.remove('on');
  b?.setAttribute('aria-expanded', 'false');
}

$('#chat-opcoes-btn').onclick = () => {
  const painel = $('#chat-opcoes');
  const abrindo = painel.classList.contains('hidden');
  // O painel rouba altura da lista, como o teclado: quem via a última linha continua vendo.
  const colado = chatNoFim();
  $('#chat-emojis').classList.add('hidden');
  $('#chat-emoji').classList.remove('on');
  if (abrindo) pintarOpcoesChat();
  painel.classList.toggle('hidden', !abrindo);
  $('#chat-opcoes-btn').classList.toggle('on', abrindo);
  $('#chat-opcoes-btn').setAttribute('aria-expanded', String(abrindo));
  if (colado) rolarChatAoFim();
};
$('#chat-opcoes-fechar').onclick = fecharOpcoesChat;

$('#chat-sem-anuncios').onclick = () => {
  semAnunciosNoChat = !semAnunciosNoChat;
  definirAnunciosChatEscondidos(semAnunciosNoChat);
  pintarOpcoesChat();
  // A lista inteira muda na hora: cada anúncio que já estava nela some (ou volta).
  pintarChat();
  pintarSelosChatAbas();
};

// Fora do painel, ou Esc: fecha. A própria seta fica de fora — ela já alterna sozinha.
document.addEventListener('click', (ev) => {
  if ($('#chat-opcoes')?.classList.contains('hidden')) return;
  if (ev.target.closest('#chat-opcoes') || ev.target.closest('#chat-opcoes-btn')) return;
  fecharOpcoesChat();
});
document.addEventListener('keydown', (ev) => {
  if (ev.key === 'Escape' && !$('#chat-opcoes')?.classList.contains('hidden')) fecharOpcoesChat();
});

$('#chat-emoji').onclick = () => {
  montarTecladoEmoji();
  fecharOpcoesChat();
  const painel = $('#chat-emojis');
  const abrindo = painel.classList.contains('hidden');
  // O teclado rouba altura da lista, então quem estava vendo a última mensagem precisa
  // continuar vendo — senão abrir o painel corta a linha mais recente ao meio.
  const colado = chatNoFim();
  if (abrindo) pintarTecladoVip();
  painel.classList.toggle('hidden', !abrindo);
  $('#chat-emoji').classList.toggle('on', abrindo);
  if (colado) rolarChatAoFim();
  if (abrindo) $('#chat-input').focus();
};

/**
 * O texto do último envio de chat, guardado até o servidor aceitar (ou recusar). Se a
 * mensagem bater no intervalo de 5 s — ou noutra recusa de envio —, ela volta pro input em
 * vez de sumir. Ver o tratamento de `m.t === 'erro'` no `onmessage`.
 */
let ultimoChatTentado = '';
const CHAVES_ERRO_CHAT = new Set([
  'chat.espera', 'chat.semGuild', 'chat.nivelMinimo', 'chat.vipEmojiTravado',
]);

/**
 * OS COMANDOS DE BARRA — `/mute <nick> <minutos>`, `/unmute <nick>`, `/site`, `/ticket` e `/guia`.
 *
 * Nasceram do caminho da denúncia: quando alguém enche o Mundo de propaganda, o relato
 * chega em PRIVADO — hoje pela DM da Lista de Amigos —, e o menu de moderação só abre em
 * cima de uma MENSAGEM do infrator no chat. Quando ele já parou de falar, ou quando a
 * punição não cabe nas quatro durações prontas do menu, não havia por onde: o moderador
 * tinha de chamar um admin. Digitar o nick resolve os dois casos sem sair da conversa.
 *
 * Por isso a interceptação vive em TRÊS entradas de texto — o chat, o painel da guild e a
 * DM da lista de amigos. Uma delas de fora é o caso em que o comando vira mensagem literal
 * na cara de quem denunciou.
 *
 * Devolve `true` quando a linha ERA um comando — e aí ela não vira mensagem, aconteça o que
 * acontecer. Isso vale inclusive para quem não tem permissão: melhor a recusa em toast do
 * que "/mute Fulano 30" publicado no Mundo para todo mundo ler.
 *
 * A permissão real é do servidor (`CHAT_COMANDO` no gateway). `estado.chatCmd` aqui é só
 * para responder na hora, sem uma ida ao servidor para dizer não.
 *
 * `/site`, `/ticket` e `/guia` são os que qualquer jogador digita, e os únicos que não falam com
 * o servidor: eles só desenham uma linha na lista de quem digitou. Entram aqui, e não em outro
 * lugar, para herdar de graça a regra que importa — linha que começa com barra NÃO vira
 * mensagem. É isso que impede os três de virarem megafone de link no Mundo.
 */
const COMANDOS_CHAT = new Set(['mute', 'unmute', 'site', 'ticket', 'guia', 'resgatar']);

/**
 * O guia do jogo para quem está começando — a resposta do `/guia` e a dica que passa no chat.
 * Desde 28/09/2026 é o site da comunidade (antes, `pokeidle-guia.vercel.app`).
 */
const GUIA_URL = 'https://guiapokeidlehardtocapture.site/';

/**
 * O site de hunts X4 é da COMUNIDADE, não nosso. Vive num comando (e não num botão fixo da
 * interface) exatamente por isso: quem pergunta recebe o endereço, sem o jogo carimbar como
 * seu um endereço que ele não controla.
 */
const SITE_HUNTS_URL = 'https://pokeidlehunts.pages.dev/';

/** O convite do Discord. Mesma fonte para o `/ticket` e para o botão da barra de redes. */
const DISCORD_URL = 'https://discord.gg/pokeidle';

/** Onde o botão "Copiar toda a Wiki" larga o jogador, com o manual já na área de transferência. */
const URL_CHATGPT = 'https://chatgpt.com/';

// ------------------------------------------------------- as dicas que o chat dá sozinho
//
// A cada 30 minutos de jogo o chat mostra uma dica — o guia de hunts aos 30 min, o Discord aos
// 60, e assim por diante. Uma hora fecha o par, e a segunda hora recomeça pelo guia.
//
// ### Por que aqui, e não um anúncio do servidor
//
// Um fan-out no chat do Mundo mostraria a mesma linha a todo mundo ao mesmo tempo — inclusive a
// quem acabou de entrar, que ainda não teve dúvida nenhuma, e a quem já leu a dica seis vezes
// hoje. Aqui o relógio é DE CADA SESSÃO: a dica chega depois de meia hora de jogo de VERDADE, que
// é quando a pergunta ("onde eu farmo isso?") costuma aparecer. E não custa nada ao servidor:
// a linha nasce no navegador, como a resposta do `/site` e do `/guia`, sem histórico e sem
// fan-out (ver `anexarLinhaLocalChat`).
//
// As URLs são as MESMAS do `/guia` e do `/ticket`, de propósito: se um dia o endereço mudar, ele
// muda num lugar só e as duas portas continuam apontando para o mesmo lugar.
const DICA_CHAT_MS = 30 * 60_000;

/** A roda das dicas, na ordem em que elas aparecem. */
const DICAS_CHAT = [
  () => mostrarLinkChat('chat.dicaGuia', GUIA_URL, { depois: 'chat.dicaGuia2', classe: 'dica' }),
  () => mostrarLinkChat('chat.dicaDiscord', DISCORD_URL, { classe: 'dica' }),
];

let dicaChatTimer = null;
let dicaChatIdx = 0;

/**
 * Liga a roda das dicas. Idempotente: o `welcome` chega de novo em toda reconexão (deploy, rede
 * que caiu, F5), e sem esta guarda cada queda do socket somaria mais um relógio — meia hora
 * depois, a mesma dica sairia três vezes seguidas.
 */
function iniciarDicasDoChat() {
  if (dicaChatTimer) return;
  dicaChatTimer = setInterval(() => {
    DICAS_CHAT[dicaChatIdx % DICAS_CHAT.length]();
    dicaChatIdx++;
  }, DICA_CHAT_MS);
}

function interpretarComandoChat(bruto) {
  if (!bruto.startsWith('/')) return false;
  const partes = bruto.slice(1).trim().split(/\s+/);
  const cmd = (partes[0] ?? '').toLowerCase();
  if (!COMANDOS_CHAT.has(cmd)) return false;

  // `/site` e `/ticket` são de TODO MUNDO, e por isso vêm ANTES da trava de cargo. A resposta
  // é desenhada na lista de quem digitou e para por aí: não passa pelo servidor, não entra no
  // histórico e não aparece para mais ninguém — senão qualquer um dos dois viraria megafone
  // de link no Mundo, aberto a qualquer jogador e repetível sem limite.
  if (cmd === 'site') {
    mostrarLinkChat('chat.cmdSite', SITE_HUNTS_URL);
    return true;
  }
  if (cmd === 'ticket') {
    mostrarLinkChat('chat.cmdTicket', DISCORD_URL, { depois: 'chat.cmdTicketSala' });
    return true;
  }
  if (cmd === 'guia') {
    mostrarLinkChat('chat.cmdGuia', GUIA_URL);
    return true;
  }
  // `/resgatar <codigo>` — o marco de convites do Discord. Também é de TODO MUNDO, e por isso
  // vem antes da trava de cargo. O código é conferido no SERVIDOR: o que se faz aqui é tirar
  // espaço e hífen e barrar o que nem tem o formato, para não gastar uma ida ao banco por
  // engano de digitação (ver `shared/convites.mjs`).
  if (cmd === 'resgatar') {
    const codigo = normalizarCodigoConvite(partes.slice(1).join(''));
    // `/resgatar` sozinho abre a ESCADA. É a pergunta que o comando provoca — "resgatar o
    // quê?" — e responder com "uso: /resgatar <codigo>" deixaria quem nunca ouviu falar do
    // programa sem saber que ele existe.
    if (!codigo) {
      mostrarEscadaDeConvites();
      return true;
    }
    if (!CODIGO_CONVITE_OK.test(codigo)) {
      mostrarAvisoChat('chat.cmdUsoResgatar');
      return true;
    }
    enviar({ t: 'convite.resgatar', codigo });
    return true;
  }

  if (!estado.chatCmd) {
    toast(t('chat.cmdSemPermissao'));
    return true;
  }
  // O `@` da menção é opcional: quem copia o nick do chat traz o arroba junto.
  const nick = (partes[1] ?? '').replace(/^@/, '');
  const uso = cmd === 'mute' ? 'chat.cmdUsoMute' : 'chat.cmdUsoUnmute';
  if (!nick) {
    toast(t(uso));
    return true;
  }
  if (cmd === 'unmute') {
    enviar({ t: 'chat.comando', cmd, nick });
    return true;
  }
  const minutos = Math.floor(Number(partes[2]));
  if (!Number.isFinite(minutos) || minutos < 1) {
    toast(t(uso));
    return true;
  }
  enviar({ t: 'chat.comando', cmd, nick, minutos });
  return true;
}

function enviarChat() {
  const inp = $('#chat-input');
  const bruto = inp.value.trim().slice(0, 200);
  if (!bruto) return;
  // ANTES das travas de mute e de nível: um comando não é uma mensagem, e um moderador
  // mutado por um admin continua tendo de poder desfazer o mute que aplicou por engano.
  if (interpretarComandoChat(bruto)) {
    inp.value = '';
    $('#chat-emojis').classList.add('hidden');
    $('#chat-emoji').classList.remove('on');
    return;
  }
  if (chatMutado()) {
    return toast(t('chat.mutado', { tempo: formatarRestanteMute(estado.chatMutadoAte - Date.now()) }));
  }
  if (!podeUsarChat()) return toast(t('chat.nivelMinimo', { n: CHAT_NIVEL_MIN }));
  if (estado.canalChat === 'guild' && !estado.eu?.guild?.id) return toast(t('chat.semGuild'));
  const texto = trocarApelidos(bruto);
  if (chatContemNft(bruto) || chatContemNft(texto)) {
    mostrarAvisoChat('chat.nftBloqueado');
    inp.value = '';
    $('#chat-emojis').classList.add('hidden');
    $('#chat-emoji').classList.remove('on');
    return;
  }
  enviar({ t: 'chat.send', canal: estado.canalChat, idioma: estado.idiomaChat, texto });
  ultimoChatTentado = bruto;
  inp.value = '';
  // O teclado fecha ao enviar: ele come um terço da altura da lista, e quem acabou de
  // mandar quer ver a própria mensagem chegar.
  $('#chat-emojis').classList.add('hidden');
  $('#chat-emoji').classList.remove('on');
}
$('#chat-enviar').onclick = enviarChat;
$('#chat-input').onkeydown = (e) => {
  if (e.key === 'Enter') enviarChat();
  if (e.key === 'Escape' && !$('#chat-emojis').classList.contains('hidden')) {
    $('#chat-emojis').classList.add('hidden');
    $('#chat-emoji').classList.remove('on');
  }
};

// ------------------------------------------------------------------ lista de amigos
//
// UI no molde da lista de amigos da Steam: a lista à esquerda, a conversa (ou o formulário de
// adicionar) à direita. No celular é uma coluna só que alterna lista ⇄ painel (classe
// `.ver-painel` na caixa do modal, ver `mobile.css`).
//
// O estado da TELA (quem está selecionado, qual aba, o cache de conversas) mora em
// `estado.amigosUI`. A lista, os pedidos e os "enviados" moram em `estado.amigos` — um store
// próprio, e NÃO no snapshot: reenviar 100 amigos a cada 0,5 s com dados que só mudam por
// ação era desperdício. O servidor manda `SERVIDOR.AMIGOS` logo após o welcome e a cada
// mudança; `aoReceberAmigos` é o único que escreve aqui.

const AMIGO_SEL_GUILD = '__guild__';

function ehConversaGuild(sel) {
  return sel === AMIGO_SEL_GUILD;
}

function amigosUI() {
  estado.amigosUI ??= {
    sel: null, aba: 'lista', add: false, busca: '', conversas: {},
    // A busca do "+ Adicionar amigo" (a da BASE de jogadores, não o filtro da lista ao lado).
    // `achados` nasce `null` de propósito: "ainda não pesquisei" e "pesquisei e não achei
    // ninguém" são duas telas diferentes.
    buscaAdd: { termo: '', achados: null, pedindo: false, prazo: 0 },
    // O COMÉRCIO, a outra metade da tela: qual das duas está à vista, a aba de dentro dele
    // ('ofertas' = sou o comprador, 'produtos' = sou o vendedor), a busca própria e a conversa
    // aberta — ver `aoReceberComercio`.
    modo: 'amigos', abaCom: 'ofertas', buscaCom: '', comConversa: null,
  };
  return estado.amigosUI;
}

function amigosStore() {
  // `max` = o teto da lista, que o servidor manda junto (0 = ainda não veio, e o rodapé some).
  estado.amigos ??= { lista: [], pedidos: [], enviados: [], max: 0 };
  return estado.amigos;
}

const amigosLista = () => amigosStore().lista;
const amigosPedidos = () => amigosStore().pedidos;
const amigoPorId = (id) => amigosLista().find((a) => a.id === Number(id)) ?? null;
const amigoPorNick = (nick) => {
  const n = String(nick ?? '').toLowerCase();
  if (!n) return null;
  return amigosLista().find((a) => a.nick.toLowerCase() === n) ?? null;
};

/** Dá para pedir amizade a esse nick pelo chat? (não eu, não amigo, não pedido já enviado.) */
function podePedirAmizadeNoChat(nick) {
  const bruto = String(nick ?? '').trim();
  if (!bruto) return false;
  const meu = String(estado.eu?.nick ?? estado.nick ?? '').toLowerCase();
  if (bruto.toLowerCase() === meu) return false;
  if (amigoPorNick(bruto)) return false;
  return !(amigosStore().enviados ?? []).some((e) => String(e).toLowerCase() === bruto.toLowerCase());
}
const totalNaoLidasAmigos = () => amigosLista().reduce((s, a) => s + (a.naoLidas || 0), 0);

/** A partir daqui o "visto há" da lista acende na cor de alerta: é quem dá para tirar. */
const AMIGO_SUMIDO_MS = 7 * 86_400_000;

/**
 * A ORDEM da lista de amigos. Primeiro quem mandou mensagem que eu não li; depois as conversas
 * da semana, a mais recente em cima; depois quem está online; e por fim os offline, do visto
 * mais recente ao mais antigo — quem sumiu há mais tempo fica no fundo, que é onde se procura
 * quem tirar.
 *
 * As conversas da semana vêm antes do online para a linha não fugir de baixo do dedo: abrir a
 * conversa zera as não lidas, e sem esse degrau o amigo que estava no topo despencaria para o
 * meio da lista no mesmo clique. A semana é a retenção das DMs — conversa mais velha que isso o
 * servidor já apagou.
 *
 * Quem ordena é o cliente, e não o SQL: uma DM que chega reordena a lista na hora (o
 * `aoReceberAmigos` carimba o `ultimaDm`), sem outra viagem ao banco.
 */
function compararAmigos(a, b) {
  const na = (a.naoLidas || 0) > 0;
  const nb = (b.naoLidas || 0) > 0;
  if (na !== nb) return na ? -1 : 1;
  const da = Number(a.ultimaDm) || 0;
  const db = Number(b.ultimaDm) || 0;
  if (da !== db) return db - da;
  if (!!a.online !== !!b.online) return a.online ? -1 : 1;
  if (!a.online) {
    const va = Number(a.visto) || 0;
    const vb = Number(b.visto) || 0;
    if (va !== vb) return vb - va;
  }
  const x = String(a.nick).toLowerCase();
  const y = String(b.nick).toLowerCase();
  return x < y ? -1 : x > y ? 1 : 0;
}

/** O tempo do "visto há", numa unidade só para caber na linha da lista: 12min, 3h, 40d. */
function tempoVistoAmigo(ms) {
  const min = Math.floor(ms / 60_000);
  if (min < 60) return `${min}min`;
  const h = Math.floor(min / 60);
  return h < 24 ? `${h}h` : `${Math.floor(h / 24)}d`;
}

/**
 * Online, ou há quanto tempo o amigo foi visto (`visto` = o `last_seen` dele, no minuto cheio).
 * `classe`: `on` (online) ou `sumido` (offline há uma semana ou mais).
 */
function vistoDoAmigo(a) {
  if (a.online) return { texto: t('amigos.online'), classe: 'on' };
  const visto = Number(a.visto) || 0;
  if (!visto) return { texto: t('amigos.offline'), classe: '' };
  const ms = Math.max(0, agoraDoServidor() - visto);
  return {
    texto: ms < 60_000 ? t('amigos.vistoAgora') : t('amigos.vistoHa', { tempo: tempoVistoAmigo(ms) }),
    classe: ms >= AMIGO_SUMIDO_MS ? 'sumido' : '',
  };
}

function renderAmigos() {
  // A chave de cima separa as duas metades da tela: os AMIGOS (lista, pedidos, DM) e o COMÉRCIO
  // (as conversas presas a um anúncio do Mercado). É o mesmo switch Coins/Gemas do painel de
  // ofertas do Mercado — duas opções que se excluem, com a manopla deslizando para a escolhida.
  return `<div class="amigos-wrap">
    <aside class="amigos-lado">
      <div class="cmp-switch amigos-modos" id="amigos-modos" data-lado="esq">
        <button type="button" class="cmp-op on" data-modo="amigos">${t('amigos.modoAmigos')}
          <span class="amigos-cnt" id="amigos-cnt-modo-amigos" hidden></span></button>
        <button type="button" class="cmp-op" data-modo="comercio"><span aria-hidden="true">⇄</span> ${t('amigos.modoComercio')}
          <span class="amigos-cnt" id="amigos-cnt-modo-comercio" hidden></span></button>
        <span class="cmp-manopla"></span>
      </div>
      <div class="amigos-lado-topo">
        <div class="amigos-abas">
          <button type="button" class="amigos-aba on" data-aba="lista">${t('amigos.abaLista')}</button>
          <button type="button" class="amigos-aba" data-aba="pedidos">${t('amigos.abaPendentes')}
            <span class="amigos-cnt" id="amigos-cnt-ped" hidden></span></button>
        </div>
        <button type="button" class="amigos-add-bt" id="amigos-add" data-i18n-attr="title:amigos.adicionar" title="${t('amigos.adicionar')}">+</button>
      </div>
      <input type="text" class="amigos-busca" id="amigos-busca" data-i18n-attr="placeholder:amigos.buscar" placeholder="${t('amigos.buscar')}" autocomplete="off">
      <div class="amigos-rol" id="amigos-rol"></div>
    </aside>
    <section class="amigos-painel" id="amigos-painel"></section>
  </div>`;
}

function ligarAmigos() {
  const ui = amigosUI();
  ui.add = false;
  ui.aba = 'lista';
  // A busca zera junto: o `renderAmigos` redesenha o campo VAZIO, e um filtro que sobrevivesse
  // ao fechar esconderia amigos atrás de uma caixa que não mostra texto nenhum.
  ui.busca = '';
  ui.buscaCom = '';
  // A busca de treinador também: resultado de ontem mostra relação de ontem (quem já virou
  // amigo no meio-tempo apareceria com "Adicionar amigo").
  clearTimeout(ui.buscaAdd?.prazo);
  ui.buscaAdd = { termo: '', achados: null, pedindo: false, prazo: 0 };
  // não zera `sel` nem `conversas` — reabrir o modal deve cair na última conversa
  enviar({ t: 'amigos.info' });
  // O modo também fica onde estava: quem fechou a tela negociando volta negociando.
  if (ui.modo === 'comercio') enviar({ t: 'comercio.info' });

  // A busca é uma caixa só para as duas metades, cada uma com o seu texto.
  $('#amigos-busca').oninput = (ev) => {
    if (ui.modo === 'comercio') ui.buscaCom = ev.target.value;
    else ui.busca = ev.target.value;
    pintarRolAmigos();
  };
  $('#amigos-modos').onclick = (ev) => {
    const b = ev.target.closest('[data-modo]');
    if (!b || b.dataset.modo === ui.modo) return;
    ui.modo = b.dataset.modo === 'comercio' ? 'comercio' : 'amigos';
    ui.add = false;
    $('#amigos-busca').value = ui.modo === 'comercio' ? ui.buscaCom : ui.busca;
    if (ui.modo === 'comercio') enviar({ t: 'comercio.info' });
    verPainelAmigos(false);
    montarAmigos();
  };
  $('.amigos-abas').onclick = (ev) => {
    const b = ev.target.closest('.amigos-aba');
    if (!b) return;
    if (b.dataset.abaCom) {
      ui.abaCom = b.dataset.abaCom === 'produtos' ? 'produtos' : 'ofertas';
      pintarAbasAmigos();
      pintarRolAmigos();
      return;
    }
    ui.aba = b.dataset.aba;
    ui.add = false;
    montarAmigos();
  };
  $('#amigos-add').onclick = () => {
    ui.add = true;
    ui.sel = null;
    verPainelAmigos(true);
    montarPainelAmigos();
  };
  $('#amigos-rol').onclick = (ev) => {
    const com = ev.target.closest('.com-linha');
    if (com) {
      // A linha do rascunho (a conversa que ainda não nasceu) já é a que está no painel.
      if (com.dataset.com) abrirConversaComercio(Number(com.dataset.com));
      else verPainelAmigos(true);
      return;
    }
    const aceitar = ev.target.closest('[data-aceitar]');
    if (aceitar) return enviar({ t: 'amigo.aceitar', pedidoId: Number(aceitar.dataset.aceitar) });
    const recusar = ev.target.closest('[data-recusar]');
    if (recusar) return enviar({ t: 'amigo.recusar', pedidoId: Number(recusar.dataset.recusar) });
    if (ev.target.closest('[data-guild]')) return abrirConversaGuild();
    const linha = ev.target.closest('.amigo-linha');
    if (!linha) return;
    abrirConversaAmigo(Number(linha.dataset.id));
  };
  // Painel: ações, composer, voltar (celular). Delegação — o conteúdo é remontado sempre.
  $('#amigos-painel').onclick = (ev) => {
    if (ev.target.closest('[data-voltar]')) return verPainelAmigos(false);
    if (ev.target.closest('[data-com-market]')) return abrirOfertaDoComercio();
    const acao = ev.target.closest('[data-acao]')?.dataset.acao;
    if (acao === 'coins') return abrirEnvioDeCoins(ui.sel);
    if (acao === 'pvp') return desafiarAmigo(ui.sel);
    const pvpa = ev.target.closest('[data-pvpa]');
    if (pvpa) return acaoDoConviteAmistoso(pvpa.dataset.pvpa, pvpa.dataset.cid);
    // A ficha pública do amigo — a mesma do chat e do ranking, com as estatísticas e a vitrine.
    // Ela abre POR CIMA do modal de amigos, então fechar a ficha devolve a conversa.
    if (acao === 'perfil') {
      const a = amigoPorId(ui.sel);
      return a ? pedirPerfil(a.nick) : undefined;
    }
    if (acao === 'excluir') {
      const a = amigoPorId(ui.sel);
      if (!a) return;
      return confirmarExcluirAmigo(a);
    }
    if (ev.target.closest('#amigos-buscar-bt')) return buscarTreinadores();
    // As ações de uma linha da busca. São as mesmas três da ficha pública (ver
    // `ligarAcoesPerfilOutro`) — aqui elas só chegam sem precisar abrir a ficha antes.
    const verPerfil = ev.target.closest('[data-ach-perfil]')?.dataset.achPerfil;
    if (verPerfil) {
      const meu = String(estado.eu?.nick ?? estado.nick ?? '').toLowerCase();
      return verPerfil.toLowerCase() === meu ? abrirModal('perfil') : pedirPerfil(verPerfil);
    }
    const pedirNick = ev.target.closest('[data-ach-pedir]')?.dataset.achPedir;
    if (pedirNick) {
      if ((estado.eu?.level ?? 0) < CHAT_NIVEL_MIN && !estado.souAdmin) return toast(t('amigos.nivelMinimo'));
      return enviar({ t: 'amigo.pedir', nick: pedirNick });
    }
    const bloquearNick = ev.target.closest('[data-ach-bloquear]')?.dataset.achBloquear;
    if (bloquearNick) {
      const bloqueado = alternarIgnorarChat(bloquearNick);
      limparMsgsDeIgnorados();
      toast(t(bloqueado ? 'pf.bloqueadoOk' : 'pf.desbloqueadoOk', { nick: bloquearNick }));
      pintarChat();
      pintarSelosChatAbas();
      pintarPainelIgnorados();
      return pintarAchadosAmigos();
    }
    if (ev.target.closest('[data-ach-pendentes]')) {
      ui.add = false;
      ui.aba = 'pedidos';
      verPainelAmigos(false);
      return montarAmigos();
    }
    if (ev.target.closest('#dm-anexo')) return abrirSeletorPokemonDM();
    const pkCard = ev.target.closest('.dm-pk-card');
    if (pkCard) {
      enviar({ t: 'chat.verPokemon', nick: pkCard.dataset.nick, pokemonId: Number(pkCard.dataset.pk) });
    }
  };
  $('#amigos-painel').addEventListener('submit', (ev) => {
    if (ev.target.id === 'dm-form') {
      ev.preventDefault();
      return enviarDMAmigo();
    }
    if (ev.target.id === 'guild-chat-form') {
      ev.preventDefault();
      return enviarChatGuildPainel();
    }
    if (ev.target.id === 'com-form') {
      ev.preventDefault();
      return enviarMsgComercio();
    }
  });

  montarAmigos();
}

/** Alterna, no celular, entre a coluna da lista e o painel (no desktop os dois estão à vista). */
function verPainelAmigos(sim) {
  $('#modal .modal-caixa')?.classList.toggle('ver-painel', !!sim);
}

function abrirConversaAmigo(id) {
  const ui = amigosUI();
  ui.modo = 'amigos';
  ui.sel = id;
  ui.add = false;
  verPainelAmigos(true);
  // Carrega o histórico (7 dias) e zera as não lidas no servidor — que avisa o amigo (os
  // tracinhos dele ficam azuis). O zero local é só para o selo sumir já, sem esperar a volta, e
  // para o `montarPainelAmigos` abaixo não mandar um `amigo.dm.ler` repetido.
  const a = amigoPorId(id);
  if (a) a.naoLidas = 0;
  enviar({ t: 'amigo.dm.abrir', amigoId: id });
  montarAmigos();
}

/**
 * A conversa com este amigo está À VISTA agora? É o que decide o "lida" — os dois tracinhos
 * azuis do outro lado. Não basta estar escolhida: o modal aberto no modo Amigos, sem o painel de
 * adicionar por cima, a aba do navegador em primeiro plano e, no celular, o painel deslizado
 * para a conversa (o "voltar" mostra a lista, mas não esquece quem estava escolhido).
 */
function conversaAmigoAVista(id) {
  const ui = amigosUI();
  if (estado.modalAberto !== 'amigos' || ui.modo !== 'amigos' || ui.add || ui.sel !== id) return false;
  if (document.hidden) return false;
  return !montagemMovel() || !!$('#modal .modal-caixa')?.classList.contains('ver-painel');
}

/**
 * Marca como lida a conversa À VISTA que ainda tem não lidas — a volta para a aba, ou para a
 * conversa depois do Comércio ou do "+ Adicionar". Nada à vista, nada pendente: não manda nada.
 */
function lerConversaAVista() {
  const a = amigoPorId(amigosUI().sel);
  if (!a?.naoLidas || !conversaAmigoAVista(a.id)) return;
  a.naoLidas = 0;
  enviar({ t: 'amigo.dm.ler', amigoId: a.id });
  pintarBadgeAmigos();
  if (estado.modalAberto === 'amigos') {
    pintarAbasAmigos();
    pintarRolAmigos();
  }
}
document.addEventListener('visibilitychange', () => {
  if (!document.hidden) lerConversaAVista();
});

function abrirConversaGuild() {
  if (!estado.eu?.guild?.id) return;
  const ui = amigosUI();
  ui.modo = 'amigos';
  ui.sel = AMIGO_SEL_GUILD;
  ui.add = false;
  verPainelAmigos(true);
  pedirHistoricoChat('guild', { forcar: true });
  montarAmigos();
  pintarThreadGuild(true);
}

function montarAmigos() {
  if (estado.modalAberto !== 'amigos') return;
  pintarAbasAmigos();
  pintarRolAmigos();
  montarPainelAmigos();
}

/** Um contador de aba: o número, ou some quando é zero. */
function pintarContador(el, n) {
  if (!el) return;
  el.textContent = n > 99 ? '99+' : n;
  el.hidden = !n;
}

function pintarAbasAmigos() {
  const ui = amigosUI();
  const comercio = ui.modo === 'comercio';
  $('.amigos-wrap')?.classList.toggle('modo-comercio', comercio);

  const modos = $('#amigos-modos');
  if (modos) {
    modos.dataset.lado = comercio ? 'dir' : 'esq';
    for (const b of modos.querySelectorAll('[data-modo]')) b.classList.toggle('on', b.dataset.modo === ui.modo);
  }
  pintarContador($('#amigos-cnt-modo-amigos'), amigosPedidos().length + totalNaoLidasAmigos());
  pintarContador($('#amigos-cnt-modo-comercio'), naoLidasComercio());

  // As abas de dentro trocam com o modo. Só são redesenhadas quando o modo muda — o resto do
  // tempo o que muda é a aba acesa e os contadores.
  const abas = $('.amigos-abas');
  if (abas && abas.dataset.modo !== ui.modo) {
    abas.dataset.modo = ui.modo;
    abas.innerHTML = comercio
      ? `<button type="button" class="amigos-aba" data-aba-com="ofertas">${t('comercio.abaOfertas')}
           <span class="amigos-cnt" id="com-cnt-ofertas" hidden></span></button>
         <button type="button" class="amigos-aba" data-aba-com="produtos">${t('comercio.abaProdutos')}
           <span class="amigos-cnt" id="com-cnt-produtos" hidden></span></button>`
      : `<button type="button" class="amigos-aba" data-aba="lista">${t('amigos.abaLista')}</button>
         <button type="button" class="amigos-aba" data-aba="pedidos">${t('amigos.abaPendentes')}
           <span class="amigos-cnt" id="amigos-cnt-ped" hidden></span></button>`;
  }
  for (const b of document.querySelectorAll('.amigos-aba')) {
    b.classList.toggle('on', comercio ? b.dataset.abaCom === ui.abaCom : b.dataset.aba === ui.aba);
  }
  const add = $('#amigos-add');
  if (add) add.hidden = comercio;
  const busca = $('#amigos-busca');
  if (busca) busca.placeholder = t(comercio ? 'comercio.buscar' : 'amigos.buscar');

  pintarContador($('#amigos-cnt-ped'), amigosPedidos().length);
  pintarContador($('#com-cnt-ofertas'), naoLidasDaAba('comprador'));
  pintarContador($('#com-cnt-produtos'), naoLidasDaAba('vendedor'));
}

function pintarRolAmigos() {
  const rol = $('#amigos-rol');
  if (!rol) return;
  const ui = amigosUI();

  if (ui.modo === 'comercio') return pintarRolComercio(rol);

  if (ui.aba === 'pedidos') {
    const ped = amigosPedidos();
    rol.innerHTML = ped.length
      ? ped
          .map(
            (p) => `<div class="amigo-pedido">
              <span class="amigo-av" data-lt="${p.deLooktype || 0}"></span>
              <div class="amigo-meta"><b>${escapar(p.deNick)}</b><span>${t('painel.nivelCurto')} ${num(p.deLevel)}</span></div>
              <div class="amigo-pedido-bts">
                <button type="button" class="amigo-mini ok amigo-mini-ico" data-aceitar="${p.id}"
                        aria-label="${t('amigos.aceitar')}" title="${t('amigos.aceitar')}">✓</button>
                <button type="button" class="amigo-mini amigo-mini-ico perigo" data-recusar="${p.id}"
                        aria-label="${t('amigos.recusar')}" title="${t('amigos.recusar')}">×</button>
              </div>
            </div>`,
          )
          .join('')
      : `<p class="amigos-vazio">${t('amigos.semPedidos')}</p>`;
    for (const el of rol.querySelectorAll('.amigo-av')) {
      el.replaceWith(retratoDeLooktype(Number(el.dataset.lt) || 0, 30));
    }
    return;
  }

  const busca = ui.busca.trim().toLowerCase();
  const lista = amigosLista().filter((a) => !busca || a.nick.toLowerCase().includes(busca)).sort(compararAmigos);
  const guild = estado.eu?.guild;
  const linhaGuild = guild && (!busca || t('amigos.guildChat').toLowerCase().includes(busca) || guild.nome.toLowerCase().includes(busca))
    ? `<div class="amigo-linha guild${ehConversaGuild(ui.sel) ? ' on' : ''}" data-guild="1">
        <span class="amigo-av amigo-av-guild" aria-hidden="true"></span>
        <div class="amigo-meta"><b>${escapar(guild.nome)}</b><span>${t('amigos.guildDica')}</span></div>
      </div>`
    : '';
  if (!lista.length && !linhaGuild) {
    rol.innerHTML = `<p class="amigos-vazio">${t(amigosLista().length ? 'amigos.buscaVazia' : 'amigos.semAmigos')}</p>`;
    return;
  }
  // O rodapé com o teto ("98 de 300 amigos") fica no fim da rolagem, junto de quem sumiu há mais
  // tempo — é ali que se decide quem tirar para abrir vaga.
  const { max } = amigosStore();
  const rodape = max ? `<p class="amigos-total">${t('amigos.total', { n: num(amigosLista().length), max: num(max) })}</p>` : '';
  rol.innerHTML = linhaGuild + lista
    .map((a) => {
      const visto = vistoDoAmigo(a);
      return `<div class="amigo-linha${a.id === ui.sel ? ' on' : ''}" data-id="${a.id}">
        <span class="amigo-av" data-lt="${a.looktype || 0}"></span>
        <span class="amigo-status ${a.online ? 'on' : ''}"></span>
        <div class="amigo-meta"><b>${escapar(a.nick)}</b><span class="amigo-sub">${t('painel.nivelCurto')} ${num(a.level)} · <i class="amigo-visto ${visto.classe}">${escapar(visto.texto)}</i></span></div>
        ${a.naoLidas ? `<span class="amigo-badge">${a.naoLidas > 9 ? '9+' : a.naoLidas}</span>` : ''}
      </div>`;
    })
    .join('') + rodape;
  for (const el of rol.querySelectorAll('.amigo-av:not(.amigo-av-guild)')) {
    el.replaceWith(retratoDeLooktype(Number(el.dataset.lt) || 0, 30));
  }
  const guildAv = rol.querySelector('.amigo-linha.guild .amigo-av-guild');
  if (guildAv) pintarBrasao(guildAv, guild?.brasao, 30);
}

function montarPainelAmigos() {
  const host = $('#amigos-painel');
  if (!host) return;
  const ui = amigosUI();

  if (ui.modo === 'comercio') return montarPainelComercio(host);

  if (ui.add) return montarPainelAdicionar(host);

  if (ehConversaGuild(ui.sel)) return montarPainelGuild(host);

  const a = amigoPorId(ui.sel);
  if (!a) {
    host.innerHTML = `<div class="amigos-painel-vazio">${t('amigos.escolhaAmigo')}</div>`;
    return;
  }

  // Uma DM nova traz `lista` no mesmo pacote e cairia aqui remontando o painel — o que apagaria
  // o que o jogador está digitando. Guarda o rascunho e o scroll da thread para devolver depois.
  // Sem thread ainda (primeira abertura) → rola para o fim, que é onde a conversa "está".
  const rascunho = $('#dm-input')?.value ?? '';
  const thread = $('#dm-thread');
  const coladoNoFim = !thread || thread.scrollHeight - thread.scrollTop - thread.clientHeight < 24;
  const visto = vistoDoAmigo(a);

  host.innerHTML = `
    <div class="amigo-cab">
      <button type="button" class="amigo-voltar" data-voltar aria-label="${t('amigos.voltar')}">‹</button>
      <span class="amigo-av amigo-av-g" data-lt="${a.looktype || 0}"></span>
      <div class="amigo-meta">
        <b>${escapar(a.nick)}</b>
        <span>${t('painel.nivelCurto')} ${num(a.level)} · <i class="amigo-visto ${visto.classe}">${escapar(visto.texto)}</i></span>
      </div>
    </div>
    <div class="amigo-acoes">
      <button type="button" class="amigo-acao on" data-acao="dm">${t('amigos.enviarDM')}</button>
      <button type="button" class="amigo-acao" data-acao="coins">${t('amigos.enviarCoins')}</button>
      <button type="button" class="amigo-acao amigo-acao-pvp" data-acao="pvp" id="amigo-pvp-bt"
              title="${escapar(t('amigos.pvpa.dica', { nick: a.nick }))}">${rotuloBotaoAmistoso()}</button>
      <button type="button" class="amigo-acao" data-acao="perfil">${t('amigos.verPerfil')}</button>
      <button type="button" class="amigo-acao perigo" data-acao="excluir">${t('amigos.excluir')}</button>
    </div>
    <div class="dm-thread" id="dm-thread"></div>
    <form class="dm-composer" id="dm-form" autocomplete="off">
      <button type="button" class="dm-anexo" id="dm-anexo" title="${t('amigos.anexarPokemon')}" aria-label="${t('amigos.anexarPokemon')}">📎</button>
      <input type="text" id="dm-input" maxlength="500" placeholder="${t('amigos.dmPlaceholder')}">
      <button type="submit" class="dm-enviar">${t('amigos.dmEnviar')}</button>
    </form>`;
  host.querySelector('.amigo-av')?.replaceWith(retratoDeLooktype(a.looktype || 0, 40));
  pintarThreadDM(a.id, coladoNoFim);
  if (rascunho) {
    const inp = $('#dm-input');
    if (inp) {
      inp.value = rascunho;
      inp.setSelectionRange?.(rascunho.length, rascunho.length);
    }
  }
  // A conversa voltou à tela (do Comércio, do "+ Adicionar") com mensagens que chegaram enquanto
  // ela estava escondida: agora sim elas foram vistas.
  lerConversaAVista();
}

function montarPainelGuild(host) {
  const g = estado.eu?.guild;
  if (!g?.id) {
    host.innerHTML = `<div class="amigos-painel-vazio">${t('chat.semGuild')}</div>`;
    return;
  }
  const rascunho = $('#guild-chat-input')?.value ?? '';
  const thread = $('#guild-chat-thread');
  const coladoNoFim = !thread || thread.scrollHeight - thread.scrollTop - thread.clientHeight < 24;

  host.innerHTML = `
    <div class="amigo-cab">
      <button type="button" class="amigo-voltar" data-voltar aria-label="${t('amigos.voltar')}">‹</button>
      <span class="amigo-av amigo-av-guild amigo-av-g" aria-hidden="true"></span>
      <div class="amigo-meta">
        <b>${escapar(g.nome)}</b>
        <span>${t('amigos.guildDica')}</span>
      </div>
    </div>
    <div class="dm-thread guild-chat-thread" id="guild-chat-thread"></div>
    <form class="dm-composer" id="guild-chat-form" autocomplete="off">
      <input type="text" id="guild-chat-input" maxlength="200" placeholder="${t('amigos.guildPlaceholder')}">
      <button type="submit" class="dm-enviar">${t('amigos.dmEnviar')}</button>
    </form>`;
  pintarBrasao(host.querySelector('.amigo-av-guild'), g.brasao, 40);
  pintarThreadGuild(coladoNoFim);
  if (rascunho) {
    const inp = $('#guild-chat-input');
    if (inp) {
      inp.value = rascunho;
      inp.setSelectionRange?.(rascunho.length, rascunho.length);
    }
  }
}

function pintarThreadGuild(rolarAoFim = true) {
  const thread = $('#guild-chat-thread');
  if (!thread) return;
  const msgs = (estado.mensagens.guild ?? []).filter(
    (m) => !msgForaDoChat(m) && idiomaDaMsg(m) === estado.idiomaChat,
  );
  thread.innerHTML = '';
  if (!msgs.length) {
    thread.innerHTML = `<p class="dm-vazio">${t('amigos.guildVazio')}</p>`;
    return;
  }
  const antes = thread.scrollTop;
  for (const m of msgs) thread.appendChild(linhaDeChat(m));
  thread.scrollTop = rolarAoFim ? thread.scrollHeight : antes;
}

function enviarChatGuildPainel() {
  const inp = $('#guild-chat-input');
  const bruto = (inp?.value ?? '').trim().slice(0, 200);
  if (!bruto) return;
  if (interpretarComandoChat(bruto)) {
    if (inp) inp.value = '';
    return;
  }
  if (chatMutado()) {
    return toast(t('chat.mutado', { tempo: formatarRestanteMute(estado.chatMutadoAte - Date.now()) }));
  }
  if (!podeUsarChat()) return toast(t('chat.nivelMinimo', { n: CHAT_NIVEL_MIN }));
  if (!estado.eu?.guild?.id) return toast(t('chat.semGuild'));
  const texto = trocarApelidos(bruto);
  if (chatContemNft(bruto) || chatContemNft(texto)) {
    toast(t('chat.nftBloqueado'));
    if (inp) inp.value = '';
    return;
  }
  enviar({ t: 'chat.send', canal: 'guild', idioma: estado.idiomaChat, texto });
  if (inp) inp.value = '';
}

/**
 * O "+ Adicionar amigo", que é uma BUSCA e não um envio às cegas.
 *
 * Antes, o botão mandava o pedido direto para o que estivesse escrito: quem não lembrasse o nick
 * inteiro (ou errasse uma letra) só descobria pelo "Treinador não encontrado", e não tinha como
 * ver com quem estava falando antes de pedir. Agora o campo PROCURA por pedaço do nick, e cada
 * achado traz as três ações no lugar onde elas fazem sentido: ver o perfil, pedir amizade,
 * bloquear.
 *
 * Três letras é o mínimo — o servidor recusa menos que isso, porque abaixo disso a consulta
 * deixa de usar o índice e vira uma varredura da tabela de jogadores por tecla digitada.
 */
const AMIGO_BUSCA_MIN = 3;

function montarPainelAdicionar(host) {
  const ui = amigosUI();
  const enviados = (amigosStore().enviados ?? [])
    .map((n) => `<li>${escapar(n)} <em>${t('amigos.aguardando')}</em></li>`)
    .join('');
  host.innerHTML = `
    <div class="amigo-cab">
      <button type="button" class="amigo-voltar" data-voltar aria-label="${t('amigos.voltar')}">‹</button>
      <div class="amigo-meta"><b>${t('amigos.adicionar')}</b><span>${t('amigos.adicionarDica', { n: AMIGO_BUSCA_MIN })}</span></div>
    </div>
    <div class="amigo-add-form">
      <input type="text" id="amigos-pedir" maxlength="16" placeholder="${t('amigos.pedirPlaceholder')}"
             autocomplete="off" value="${escapar(ui.buscaAdd.termo)}">
      <button type="button" id="amigos-buscar-bt" class="dm-enviar">${t('amigos.pesquisar')}</button>
    </div>
    <div class="amigo-achados" id="amigo-achados"></div>
    ${enviados ? `<ul class="amigo-enviados">${enviados}</ul>` : ''}`;
  pintarAchadosAmigos();
  const inp = $('#amigos-pedir');
  inp?.focus();
  inp?.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      buscarTreinadores();
    }
  });
}

function buscarTreinadores() {
  const ui = amigosUI();
  const termo = ($('#amigos-pedir')?.value ?? '').trim();
  if (termo.length < AMIGO_BUSCA_MIN) {
    ui.buscaAdd = { termo, achados: null, pedindo: false };
    return pintarAchadosAmigos();
  }
  // O termo fica guardado: o pacote de volta remonta o painel, e um campo que se esvaziasse
  // sozinho obrigaria a digitar de novo para refazer a busca.
  clearTimeout(ui.buscaAdd.prazo);
  ui.buscaAdd = { termo, achados: ui.buscaAdd.achados, pedindo: true, prazo: 0 };
  if (!enviar({ t: 'amigo.busca', termo })) {
    ui.buscaAdd.pedindo = false;
  } else {
    // O servidor pode engolir a mensagem calado — é o que o balde de `busca` faz com quem
    // martela o botão. Sem este prazo, o "Procurando…" ficaria para sempre na tela de quem
    // apanhou do limite; com ele, a lista volta ao que era e o botão serve de novo.
    ui.buscaAdd.prazo = setTimeout(() => {
      const b = amigosUI().buscaAdd;
      if (!b.pedindo) return;
      b.pedindo = false;
      pintarAchadosAmigos();
    }, 8000);
  }
  pintarAchadosAmigos();
}

/**
 * Uma linha de achado. O botão do meio é o estado da relação, não um botão sempre igual: quem
 * já é amigo não tem o que adicionar, e quem já me pediu amizade merece um atalho para a aba
 * de Pendentes em vez de um pedido cruzado.
 */
function htmlLinhaAchado(a) {
  const meu = String(estado.eu?.nick ?? estado.nick ?? '').toLowerCase();
  const souEu = a.nick.toLowerCase() === meu;
  const nick = escapar(a.nick);

  // A relação vem do servidor (`a.amigo`, `a.pedi`, `a.mePediu`), mas a LISTA local manda quando
  // ela já andou: clicar em Adicionar devolve `enviados` na hora, e o achado em mãos ainda é o
  // de antes do clique. Sem isto, o botão continuaria dizendo "Adicionar amigo" depois do pedido.
  const localmente = estadoAmizadePerfil(a.nick); // null = sou eu
  const jaAmigo = a.amigo || localmente === 'amigo';
  const jaPedi = a.pedi || localmente === 'pedido_enviado';

  let acaoAmizade = '';
  if (souEu) acaoAmizade = `<span class="pf-soc-badge">${escapar(t('amigos.souEu'))}</span>`;
  else if (jaAmigo) acaoAmizade = `<span class="pf-soc-badge ok">${escapar(t('pf.jaAmigo'))}</span>`;
  else if (a.mePediu) {
    acaoAmizade = `<button type="button" class="amigo-mini ok" data-ach-pendentes="1">${escapar(t('amigos.responder'))}</button>`;
  } else if (jaPedi) {
    acaoAmizade = `<span class="pf-soc-badge pend">${escapar(t('pf.pedidoEnviado'))}</span>`;
  } else {
    acaoAmizade = `<button type="button" class="amigo-mini ok" data-ach-pedir="${nick}">${escapar(t('pf.adicionarAmigo'))}</button>`;
  }

  const bloqueio = souEu ? '' : `<button type="button" class="amigo-mini perigo" data-ach-bloquear="${nick}">${
    escapar(t(nickIgnoradoNoChat(a.nick) ? 'pf.desbloquear' : 'pf.bloquear'))
  }</button>`;

  return `<div class="amigo-achado">
    <span class="amigo-av" data-lt="${a.looktype || 0}"></span>
    <span class="amigo-status ${a.online ? 'on' : ''}" title="${t(a.online ? 'amigos.online' : 'amigos.offline')}"></span>
    <div class="amigo-meta"><b>${nick}</b><span>${t('painel.nivelCurto')} ${num(a.level)}</span></div>
    <div class="amigo-achado-bts">
      <button type="button" class="amigo-mini" data-ach-perfil="${nick}">${escapar(t('amigos.verPerfil'))}</button>
      ${acaoAmizade}${bloqueio}
    </div>
  </div>`;
}

function pintarAchadosAmigos() {
  const host = $('#amigo-achados');
  if (!host) return;
  const { termo, achados, pedindo } = amigosUI().buscaAdd;

  if (termo && termo.length < AMIGO_BUSCA_MIN) {
    host.innerHTML = `<p class="amigos-vazio">${t('amigos.buscaCurta', { n: AMIGO_BUSCA_MIN })}</p>`;
    return;
  }
  if (pedindo && !achados) {
    host.innerHTML = `<p class="amigos-vazio">${t('amigos.buscando')}</p>`;
    return;
  }
  if (!achados) {
    host.innerHTML = '';
    return;
  }
  host.innerHTML = achados.length
    ? achados.map(htmlLinhaAchado).join('')
    : `<p class="amigos-vazio">${t('amigos.buscaSemNinguem', { termo: escapar(termo) })}</p>`;
  for (const el of host.querySelectorAll('.amigo-av')) {
    el.replaceWith(retratoDeLooktype(Number(el.dataset.lt) || 0, 30));
  }
}

function pintarThreadDM(id, rolarAoFim = true) {
  const thread = $('#dm-thread');
  if (!thread) return;
  const msgs = amigosUI().conversas[id] ?? [];
  if (!msgs.length) {
    thread.innerHTML = `<p class="dm-vazio">${t('amigos.dmVazio')}</p>`;
    return;
  }
  const antes = thread.scrollTop;
  const nickAmigo = amigoPorId(id)?.nick ?? '';
  thread.innerHTML = msgs.map((mm) => bolhaDM(mm, nickAmigo)).join('');
  pintarSpritesDosAnexos(thread);
  thread.scrollTop = rolarAoFim ? thread.scrollHeight : antes;
}

/**
 * A hora da bolha e, nas MINHAS mensagens, os dois tracinhos do WhatsApp: cinza = enviada,
 * azul = o amigo já leu (abriu a conversa depois dela — ver `lerConversaAVista` do lado de lá).
 * Só texto e pokémon anexado: a nota de coins e o convite de PvP têm o estado próprio.
 */
function horaDM(mm) {
  const hora = `<time>${horaCurta(mm.ts)}</time>`;
  if (!mm.mine) return hora;
  const rotulo = escapar(t(mm.lido ? 'amigos.dmLida' : 'amigos.dmEnviada'));
  return `<span class="dm-hora">${hora}<svg class="dm-check${mm.lido ? ' lida' : ''}" viewBox="0 0 16 11" width="16" height="11" role="img" aria-label="${rotulo}"><title>${rotulo}</title><path d="M1.2 6.2l3.2 3.2 6-7.6M6.9 7.9l1.5 1.5 6-7.6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>`;
}

/** Uma linha da thread: bolha de texto, nota de coins, pokémon anexado ou convite de PvP amistoso. */
function bolhaDM(mm, nickAmigo) {
  if (mm.tipo === 3) return bolhaConviteAmistoso(mm, nickAmigo);
  if (mm.tipo === 1) {
    const v = Math.max(0, Math.floor(Number(mm.valor) || 0));
    const taxa = Math.ceil(v * TAXA_COINS_AMIGO);
    const liq = Math.max(0, v - taxa);
    const chave = mm.mine ? 'amigos.dmCoinsEnviei' : 'amigos.dmCoinsRecebi';
    const txt = t(chave, { nick: nickAmigo, v: num(v), taxa: num(taxa), liq: num(liq) });
    return `<div class="dm-nota"><span>${escapar(txt)}</span><time>${horaCurta(mm.ts)}</time></div>`;
  }
  if (mm.tipo === 2) {
    let pk;
    try { pk = JSON.parse(mm.texto); } catch { pk = null; }
    if (!pk?.pokemonId) {
      return `<div class="dm-bolha ${mm.mine ? 'eu' : 'ele'}"><span class="dm-txt">${escapar(mm.texto)}</span>${horaDM(mm)}</div>`;
    }
    const nick = escapar(pk.nick ?? (mm.mine ? estado.eu?.nick : nickAmigo) ?? '');
    const nome = escapar(pk.nome ?? '?');
    // A MESMA fileira P·IV·Q·N dos cards, no formato compacto — a bolha divide 78% da largura
    // da conversa com o sprite. Ela cai fora sozinha nas DMs antigas, gravadas antes de o
    // anexo carregar qualidade e IV: lá sobram nome, nível e o selo de shiny, como era.
    const selos = selosAtributos(pk, { compacto: true });
    return `<div class="dm-bolha dm-pk ${mm.mine ? 'eu' : 'ele'}">
      <button type="button" class="dm-pk-card" data-nick="${nick}" data-pk="${Number(pk.pokemonId)}"
              data-sp="${Number(pk.speciesId) || ''}" data-look="${Number(pk.looktype) || ''}"${pk.shiny ? ' data-shiny="1"' : ''}>
        <span class="dm-pk-arte"></span>
        <span class="dm-pk-txt">
          <span class="dm-pk-nome">${pk.shiny ? '✨' : ''}${nome}${seloRefino(pk)}</span>
          <span class="dm-pk-nv">${t('painel.nivelCurto')} ${num(pk.level ?? 1)}</span>
          ${selos}
        </span>
      </button>
      ${horaDM(mm)}
    </div>`;
  }
  return `<div class="dm-bolha ${mm.mine ? 'eu' : 'ele'}">
    <span class="dm-txt">${escapar(mm.texto)}</span>
    ${horaDM(mm)}
  </div>`;
}

// ------------------------------------------------------------- PvP amistoso
//
// O desafio entre amigos pela conversa. O servidor guarda o convite (5 min) e arma a espera dos
// dois (5 min) — ver `server/game/pvp-amistoso.mjs`. Aqui só se desenha: o botão, a bolha do
// convite com o relógio e a fita no fim. Nenhuma trava daqui vale nada sozinha; elas só evitam
// o clique que o servidor recusaria.

/** Folga do relógio da bolha — a hora do navegador pode estar um pouco à frente. */
const CONVITE_AMISTOSO_FITA_MS = 30 * 60_000;

/** "4:32" — quanto falta até `ms` (relógio do servidor). */
const faltaAmistoso = (ate) => tempoFita(Math.max(0, ate - agoraDoServidor()));

function rotuloBotaoAmistoso() {
  const espera = (estado.pvpa?.esperaAte ?? 0) - agoraDoServidor();
  return espera > 0
    ? t('amigos.pvpa.btEspera', { t: tempoFita(espera) })
    : t('amigos.pvpa.bt');
}

function atualizarBotaoAmistoso() {
  const bt = $('#amigo-pvp-bt');
  if (!bt) return;
  const espera = (estado.pvpa?.esperaAte ?? 0) - agoraDoServidor();
  bt.textContent = rotuloBotaoAmistoso();
  bt.classList.toggle('esperando', espera > 0);
}

function desafiarAmigo(id) {
  const a = amigoPorId(id);
  if (!a) return;
  const espera = (estado.pvpa?.esperaAte ?? 0) - agoraDoServidor();
  if (espera > 0) return toast(t('amigos.pvpa.euEspero', { min: Math.ceil(espera / 60_000) }));
  const saida = estado.pvpa?.saida;
  if (saida && saida.expiraEm > agoraDoServidor()) return toast(t('amigos.pvpa.jaTemConvite', { nick: saida.para }));
  if (!a.online) return toast(t('amigos.pvpa.offline', { nick: a.nick }));
  confirmarDesafioAmigo(a);
}

/**
 * A tela de desafio dos jogos de luta: você de um lado, o amigo do outro, o VS no meio. As três
 * regras (prazo do convite, qual equipe luta, a espera depois) viram uma linha cada.
 */
function confirmarDesafioAmigo(a) {
  confirmar({
    titulo: t('amigos.pvpa.titulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteTreinador(null, null, 64), nome: escapar(estado.eu?.nick ?? '') })}
        <span class="dlg-vs" aria-hidden="true">VS</span>
        ${dlgAtor({ arte: dlgArteTreinador(a.looktype || LOOKTYPE_TREINADOR, null, 64), nome: escapar(a.nick), sub: dlgNivel(a.level ?? 1), classe: 'novo' })}`)}
      ${dlgFrase(t('amigos.pvpa.lead', { nick: escapar(a.nick) }))}
      ${dlgLista([
        { icone: 'relogio', html: t('amigos.pvpa.regraConvite') },
        { icone: 'espadas', html: t('amigos.pvpa.regraEquipe') },
        { icone: 'ampulheta', html: t('amigos.pvpa.regraEspera') },
      ])}`,
    aoConfirmar: () => enviar({ t: 'amigo.pvp.convidar', amigoId: a.id }),
  });
}

/**
 * Excluir um amigo: o retrato dele sem cor, com o "−" no canto, e há quanto tempo ele não
 * aparece — é a informação que decide a exclusão. A conversa fica guardada.
 */
function confirmarExcluirAmigo(a) {
  const visto = vistoDoAmigo(a);
  confirmar({
    titulo: t('amigos.excluir'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArteTreinador(a.looktype || LOOKTYPE_TREINADOR, null, 64),
        nome: escapar(a.nick),
        sub: `${dlgNivel(a.level ?? 1)} · <i class="amigo-visto ${visto.classe}">${escapar(visto.texto)}</i>`,
        classe: 'sai',
        marca: dlgIcone('pessoaMenos', 15),
      }), 'perigo')}
      ${dlgFrase('', t('amigos.excluirConfirma', { nick: `<b>${escapar(a.nick)}</b>` }))}`,
    tom: 'perigo',
    aoConfirmar: () => enviar({ t: 'amigo.remover', amigoId: a.id }),
  });
}

function acaoDoConviteAmistoso(acao, cid) {
  if (!/^[0-9a-f]{32}$/.test(String(cid ?? ''))) return;
  if (acao === 'aceitar') return enviar({ t: 'amigo.pvp.responder', conviteId: cid, aceitar: true });
  if (acao === 'recusar') return enviar({ t: 'amigo.pvp.responder', conviteId: cid, aceitar: false });
  if (acao === 'cancelar') return enviar({ t: 'amigo.pvp.cancelar', conviteId: cid });
  if (acao === 'assistir') return enviar({ t: 'amigo.pvp.fita', conviteId: cid });
}

/** A bolha do convite: quem desafiou quem, o relógio, e o que dá para fazer agora. */
function bolhaConviteAmistoso(mm, nickAmigo) {
  let c;
  try { c = JSON.parse(mm.texto); } catch { c = null; }
  if (!c?.cid) return '';
  const cid = /^[0-9a-f]{32}$/.test(String(c.cid)) ? c.cid : '';
  const eu = !!mm.mine;
  const expirou = c.estado === 'pendente' && agoraDoServidor() >= Number(c.expiraEm || 0);
  const estadoVisto = expirou ? 'expirado' : String(c.estado ?? 'pendente');
  const quem = eu
    ? t('amigos.pvpa.voceDesafiou', { nick: escapar(c.para ?? nickAmigo) })
    : t('amigos.pvpa.teDesafiou', { nick: escapar(c.de ?? nickAmigo) });
  let meio = '';
  if (estadoVisto === 'pendente') {
    meio = `<span class="dm-pvpa-relogio" data-expira="${Number(c.expiraEm) || 0}">${t('amigos.pvpa.expiraEm', { t: faltaAmistoso(Number(c.expiraEm) || 0) })}</span>
      <span class="dm-pvpa-bts">${eu
        ? `<button type="button" class="amigo-acao perigo" data-pvpa="cancelar" data-cid="${cid}">${t('amigos.pvpa.cancelar')}</button>`
        : `<button type="button" class="amigo-acao on dm-pvpa-aceitar" data-pvpa="aceitar" data-cid="${cid}">⚔ ${t('amigos.pvpa.aceitar')}</button>
           <button type="button" class="amigo-acao perigo" data-pvpa="recusar" data-cid="${cid}">${t('amigos.pvpa.recusar')}</button>`}</span>`;
  } else if (estadoVisto === 'aceito') {
    const venci = String(c.venc ?? '').toLowerCase() === String(estado.eu?.nick ?? '').toLowerCase();
    const aindaTemFita = agoraDoServidor() < (Number(c.expiraEm) || 0) + CONVITE_AMISTOSO_FITA_MS;
    meio = `<span class="dm-pvpa-fim ${venci ? 'venci' : 'perdi'}">${t('amigos.pvpa.venceu', { nick: escapar(c.venc ?? '?') })}</span>
      ${aindaTemFita ? `<span class="dm-pvpa-bts"><button type="button" class="amigo-acao on" data-pvpa="assistir" data-cid="${cid}">${t('amigos.pvpa.assistir')}</button></span>` : ''}`;
  } else {
    const chave = { expirado: 'amigos.pvpa.expirou', recusado: 'amigos.pvpa.recusado', cancelado: 'amigos.pvpa.cancelado' }[estadoVisto]
      ?? 'amigos.pvpa.falhou';
    meio = `<span class="dm-pvpa-fim">${t(chave)}</span>`;
  }
  return `<div class="dm-pvpa ${eu ? 'eu' : 'ele'} est-${escapar(estadoVisto)}">
    <span class="dm-pvpa-topo"><i aria-hidden="true">⚔</i><b>${t('amigos.pvpa.titulo')}</b></span>
    <span class="dm-pvpa-quem">${quem}</span>
    ${meio}
    <time>${horaCurta(mm.ts)}</time>
  </div>`;
}

/**
 * A fita da luta amistosa. Respeita a escolha de "como a batalha aparece" do PvP: sem tela, vira
 * um toast com o resultado; com tela, é o player de sempre com o cartão de vitória no fim.
 */
function abrirPartidaAmistosa(p) {
  if (!p?.replay) return;
  const nick = p.oponente?.nick ?? '';
  if (!p.reprise && telaDeBatalha() === TELA_BATALHA.OFF) {
    return toast(t(p.venci ? 'amigos.pvpa.resultadoVitoria' : 'amigos.pvpa.resultadoDerrota', { nick: escapar(nick) }));
  }
  abrirReplayGuerra({
    replay: p.replay,
    titulo: t('amigos.pvpa.tituloFita', { nick: escapar(nick) }),
    aoPronto: acelerarParaCaber,
  });
  partidaPvpAtual = { ...p, amistoso: true, id: `a:${p.id}` };
}

// O relógio das bolhas de convite e do botão: um tique por segundo, só com a conversa aberta.
setInterval(() => {
  if (estado.modalAberto !== 'amigos') return;
  atualizarBotaoAmistoso();
  let virou = false;
  for (const el of document.querySelectorAll('.dm-pvpa-relogio[data-expira]')) {
    const ate = Number(el.dataset.expira) || 0;
    if (agoraDoServidor() >= ate) virou = true;
    else el.textContent = t('amigos.pvpa.expiraEm', { t: faltaAmistoso(ate) });
  }
  // Um convite acabou de expirar: repinta a conversa para os botões virarem "Expirou".
  const ui = amigosUI();
  if (virou && ui.sel != null && !ehConversaGuild(ui.sel)) pintarThreadDM(ui.sel, false);
}, 1000);

/**
 * Enfia os sprites animados nas bolhas de pokémon anexado.
 *
 * A thread é pintada de uma vez com `innerHTML` (é a única forma barata de redesenhar uma
 * conversa inteira a cada mensagem que chega), e `spritePokemon` devolve um ELEMENTO — daí
 * este segundo passe, sobre os dados que a bolha deixou nos `data-`.
 */
function pintarSpritesDosAnexos(thread) {
  for (const card of thread.querySelectorAll('.dm-pk-card')) {
    const arte = card.querySelector('.dm-pk-arte');
    if (!arte || arte.childElementCount) continue;
    arte.appendChild(spritePokemon({
      speciesId: Number(card.dataset.sp) || null,
      looktype: Number(card.dataset.look) || null,
      shiny: card.dataset.shiny === '1',
    }, 38));
  }
}

const horaCurta = (ms) =>
  new Date(ms).toLocaleTimeString(idioma() === 'pt' ? 'pt-BR' : idioma(), {
    hour: '2-digit',
    minute: '2-digit',
  });

// Espelho local das travas do servidor (5 s). Aqui é só pra UX: não perder o texto digitado
// nem fechar o diálogo de coins num envio que o servidor recusaria — quem manda é o servidor.
const ESPERA_AMIGO_MS = 5000;
let ultimoEnvioDM = 0;
let ultimoEnvioCoinAmigo = 0;

function enviarDMAmigo() {
  const ui = amigosUI();
  const inp = $('#dm-input');
  const texto = (inp?.value ?? '').trim().slice(0, 500);
  if (!texto || !ui.sel) return;
  // O `/mute` também vale AQUI, e não é conveniência: desde que o sussurro saiu do chat, a
  // DM da Lista de Amigos é por onde a denúncia de propaganda chega. Sem esta linha o
  // moderador que lesse o relato e respondesse com o comando estaria mandando "/mute Fulano
  // 30" como mensagem para quem denunciou — e o infrator seguiria falando.
  if (interpretarComandoChat(texto)) {
    if (inp) inp.value = '';
    return;
  }
  if (chatContemNft(texto)) {
    toast(t('chat.nftBloqueado'));
    return;
  }
  if (Date.now() - ultimoEnvioDM < ESPERA_AMIGO_MS) {
    toast(t('amigos.dmEspera')); // não limpa o campo — o texto fica pra reenviar
    return;
  }
  ultimoEnvioDM = Date.now();
  enviar({ t: 'amigo.dm.enviar', amigoId: ui.sel, texto });
  if (inp) inp.value = '';
}

function enviarPokemonDMAmigo(pokemonId) {
  const ui = amigosUI();
  if (!ui.sel || !pokemonId) return;
  if (Date.now() - ultimoEnvioDM < ESPERA_AMIGO_MS) {
    toast(t('amigos.dmEspera'));
    return;
  }
  ultimoEnvioDM = Date.now();
  enviar({ t: 'amigo.dm.enviar', amigoId: ui.sel, pokemonId });
}

/**
 * Os filtros do anexo, guardados FORA da função: quem mostra três pokémon seguidos para o
 * mesmo amigo filtra uma vez só.
 */
const dmPkFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', soShiny: false, local: 'todos' };

/**
 * A escolha do pokémon a anexar na DM.
 *
 * Era uma lista de botões com "nome · Nv 40" e mais nada — dava para saber QUAL pokémon, e não
 * QUANTO ele vale, que é exatamente o que se manda um amigo olhar. Agora é a mesma folha de
 * escolha do Mercado da Comunidade: cards com sprite e a fileira P·IV·Q·N, busca por nome,
 * filtro de tipo e IV mínimo, ordenação — e o (i) de cada card abre a ficha completa antes
 * de enviar.
 *
 * A lista é a caixa INTEIRA, ativo e starter inclusos: aqui não se vende nada, só se mostra,
 * e o pokémon que está lutando é justamente o que se quer mostrar.
 */
function abrirSeletorPokemonDM() {
  const todos = estado.eu?.pokemons ?? [];
  if (!todos.length) return toast(t('amigos.semPokemonAnexar'));
  const { corpo, fechar } = folhaMercado(t('amigos.anexarPokemonTitulo'));
  corpo.classList.add('dmpk');
  corpo.innerHTML = `
    <div class="dmpk-topo">
      <span class="cm-busca-caixa">${lupa()}<input id="dmpk-busca" class="cm-busca" autocomplete="off"
             maxlength="32" placeholder="${escapar(t('amigos.anexarBuscar'))}" value="${escapar(dmPkFiltro.busca)}"></span>
      <label class="auto-linha dmpk-shiny"><span>${t('amigos.anexarSoShiny')}</span>
        <input type="checkbox" id="dmpk-shiny"${dmPkFiltro.soShiny ? ' checked' : ''}></label>
      <span class="shl-conta" id="dmpk-conta"></span>
    </div>
    <div class="dmpk-filtros" id="dmpk-filtros"></div>
    <div class="mk-grade cm-pk-escolha-grade cm-rolagem" id="dmpk-grade"></div>`;

  const grade = corpo.querySelector('#dmpk-grade');
  const conta = corpo.querySelector('#dmpk-conta');

  // Só a GRADE é repintada. A barra de filtros sobrevive, e por isso o campo de IV pode reagir
  // ao dígito sem perder o foco — o mesmo motivo pelo qual o Depot não precisa do
  // `devolverFocoAoFiltroIv` que a aba de venda do Market precisa.
  function pintar() {
    const busca = dmPkFiltro.busca.trim().toLowerCase();
    const piso = ivMinDoFiltro(dmPkFiltro.ivMin);
    const colecao = conjuntoColecaoCliente();
    const lista = ordenarMarketPokemon(
      todos.filter(
        (k) => (!dmPkFiltro.soShiny || k.shiny) && passaLocal(k, dmPkFiltro.local, colecao)
          && depotPassaFiltros(k, busca, dmPkFiltro.tipo, piso),
      ),
      dmPkFiltro.ordem,
    );
    conta.textContent = t('amigos.anexarConta', { n: num(lista.length), total: num(todos.length) });
    grade.innerHTML = '';
    if (!lista.length) {
      grade.innerHTML = `<div class="cm-vazio">${t('amigos.anexarVazio')}</div>`;
      return;
    }
    for (const k of lista) {
      grade.appendChild(cardPokemonEscolha(k, {
        colecao,
        aoVerFicha: () => abrirFichaDoPokemon(k),
        aoSelecionar: () => {
          enviarPokemonDMAmigo(k.id);
          fechar();
        },
      }));
    }
  }
  repintarComAColecao(corpo, pintar);

  corpo.querySelector('#dmpk-filtros').appendChild(criarFiltrosSelect({
    tipo: dmPkFiltro.tipo,
    ordem: dmPkFiltro.ordem,
    ivMin: dmPkFiltro.ivMin,
    local: dmPkFiltro.local,
    locais: LOCAIS_TODOS,
    ordens: MK_POKEMON_ORDENS,
    ordemI18n: MK_POKEMON_ORDEM_I18N,
    onChange: (campo, valor) => {
      if (campo === 'ordem') dmPkFiltro.ordem = valor || 'padrao';
      else dmPkFiltro[campo] = valor;
      pintar();
    },
  }));

  const campoBusca = corpo.querySelector('#dmpk-busca');
  campoBusca.oninput = (ev) => {
    dmPkFiltro.busca = ev.target.value;
    pintar();
  };
  corpo.querySelector('#dmpk-shiny').onchange = (ev) => {
    dmPkFiltro.soShiny = ev.target.checked;
    pintar();
  };
  dobrarFiltrosNoCelular({
    campos: [corpo.querySelector('.dmpk-shiny'), corpo.querySelector('#dmpk-filtros')],
    botaoEm: corpo.querySelector('.dmpk-topo'),
    host: corpo,
  });

  pintar();
  // No celular o foco abriria o teclado por cima da grade que ele acabou de pedir para ver.
  if (!movelAtivo()) campoBusca.focus();
}

// ---- envio de coins (diálogo empilhado por cima da lista) ----

const TAXA_COINS_AMIGO = 0.15;
const MIN_COINS_AMIGO = 1000;

function abrirEnvioDeCoins(id) {
  const a = amigoPorId(id);
  if (!a) return;
  $('#acoin-titulo').textContent = t('amigos.coinsTitulo', { nick: a.nick });
  // A viagem das moedas: você, a seta com a moeda (e a mordida da taxa), o amigo. Embaixo, o
  // recibo anda com o número digitado — o que sai do seu saldo, o que a taxa queima e o que
  // chega do outro lado.
  const pct = Math.round(TAXA_COINS_AMIGO * 100);
  $('#acoin-corpo').innerHTML = `
    ${dlgPalco(`
      ${dlgAtor({ arte: dlgArteTreinador(null, null, 60), nome: escapar(estado.eu?.nick ?? '') })}
      ${dlgSeta({ arquivo: ICONE_OURO, rotulo: `−${pct}%` })}
      ${dlgAtor({ arte: dlgArteTreinador(a.looktype || LOOKTYPE_TREINADOR, null, 60), nome: escapar(a.nick), classe: 'novo' })}`, 'ouro')}
    <label class="acoin-campo">
      <span>${t('amigos.coinsValor')}</span>
      <input type="number" id="acoin-valor" min="${MIN_COINS_AMIGO}" step="100" inputmode="numeric" placeholder="${MIN_COINS_AMIGO}">
    </label>
    <div class="acoin-resumo" id="acoin-resumo"></div>
    <button type="button" id="acoin-enviar" class="dm-enviar" disabled>${t('amigos.coinsConfirmar')}</button>`;
  hidratarDialogo($('#acoin-corpo'));
  const campo = $('#acoin-valor');
  const bt = $('#acoin-enviar');
  // O saldo é lido a cada pintura (e não guardado na abertura): o ouro anda durante a hunt, e o
  // snapshot repinta o recibo pelo `acoinRepintar` enquanto a caixa está aberta.
  const atualizar = () => {
    const saldo = Math.floor(estado.eu?.gold ?? 0);
    const v = Math.floor(Number(campo.value) || 0);
    const ok = v >= MIN_COINS_AMIGO && v <= saldo;
    const taxa = Math.ceil(v * TAXA_COINS_AMIGO);
    const liq = Math.max(0, v - taxa);
    // O nick vai ESCAPADO: o recibo agora é marcação, e o nick é texto de outra pessoa.
    $('#acoin-resumo').innerHTML = `
      ${dlgCusto({ moeda: 'ouro', valor: v, saldo, rotulo: t('amigos.coinsVoceEnvia') })}
      ${dlgReqs(
        dlgReq({
          arte: dlgIcone('chama', 20),
          nome: escapar(t('amigos.coinsTaxa', { pct })),
          sub: escapar(t('amigos.coinsQueimada')),
          valor: `<span class="tem">−${num(taxa)}</span>`,
        }),
        dlgReq({
          arte: dlgIcone('pessoa', 20),
          nome: escapar(t('amigos.coinsRecebe', { nick: a.nick })),
          valor: `<span class="tem">+${num(liq)}</span>`,
          ok: v ? ok : null,
        }),
      )}`;
    bt.disabled = !ok;
  };
  campo.oninput = atualizar;
  campo.onkeydown = (ev) => {
    if (ev.key === 'Enter' && !bt.disabled) bt.click();
  };
  bt.onclick = () => {
    const v = Math.floor(Number(campo.value) || 0);
    if (v < MIN_COINS_AMIGO) return;
    if (Date.now() - ultimoEnvioCoinAmigo < ESPERA_AMIGO_MS) {
      toast(t('amigos.coinsEspera')); // mantém o diálogo aberto com o valor digitado
      return;
    }
    ultimoEnvioCoinAmigo = Date.now();
    enviar({ t: 'amigo.coins', amigoId: a.id, valor: v });
    fecharEnvioDeCoins();
  };
  atualizar();
  acoinRepintar = atualizar;
  $('#amigo-coins').classList.remove('hidden');
  campo.focus();
}

/** O recibo da caixa "enviar coins" aberta — `null` com ela fechada. */
let acoinRepintar = null;

function fecharEnvioDeCoins() {
  $('#amigo-coins').classList.add('hidden');
  $('#acoin-corpo').innerHTML = '';
  acoinRepintar = null;
}

$('#acoin-fechar').onclick = (ev) => {
  ev.stopPropagation();
  fecharEnvioDeCoins();
};
$('#amigo-coins').onclick = (ev) => {
  if (ev.target === $('#amigo-coins')) fecharEnvioDeCoins();
};

/**
 * Refresh barato da Lista de Amigos no snapshot: a tela é alimentada pelas mensagens `amigos`
 * do servidor, não pelo estado do jogador. A única coisa que segue o ouro é o saldo escrito
 * no diálogo "enviar coins", e só enquanto ele está aberto. Nada aqui remonta o painel —
 * senão a DM sendo digitada some.
 */
function atualizarAmigos(e, anterior) {
  if (e?.gold === anterior?.gold) return;
  const cx = $('#amigo-coins');
  if (!cx || cx.classList.contains('hidden')) return;
  acoinRepintar?.();
}

/** O pontinho no botão da HUD: pedidos pendentes, DMs não lidas OU mensagens do Comércio. */
function pintarBadgeAmigos() {
  const el = $('#btn-amigos');
  if (!el) return;
  const pend = amigosPedidos().length;
  const naoLidas = totalNaoLidasAmigos();
  const comercio = naoLidasComercio();
  el.classList.toggle('tem-pedido', pend > 0 || naoLidas > 0 || comercio > 0);
  el.title = pend ? t('amigos.pendentesDica', { n: pend })
    : comercio ? t('comercio.dicaHud', { n: comercio })
      : t('tip.amigos');
}

function aoReceberAmigos(m) {
  const store = amigosStore();
  const ui = amigosUI();

  if (m.lista !== undefined) store.lista = m.lista;
  if (m.pedidos !== undefined) store.pedidos = m.pedidos;
  if (m.enviados !== undefined) store.enviados = m.enviados; // nicks para quem já mandei pedido
  if (m.max !== undefined) store.max = Number(m.max) || 0;

  if (m.conversa) {
    ui.conversas[m.conversa.amigoId] = m.conversa.mensagens ?? [];
    if (estado.modalAberto === 'amigos' && ui.sel === m.conversa.amigoId) pintarThreadDM(ui.sel);
  }

  if (m.dm) {
    const meu = m.dm.de && estado.eu?.nick && m.dm.de.toLowerCase() === estado.eu.nick.toLowerCase();
    const nota = m.dm.tipo === 1; // linha de auditoria de coins, não uma mensagem de texto
    // O id do amigo nesta conversa: se a DM é minha, o outro é `para`; senão é `de`.
    const outroNick = (meu ? m.dm.para : m.dm.de) ?? '';
    const amigo = amigosLista().find((a) => a.nick.toLowerCase() === outroNick.toLowerCase());
    if (amigo) {
      // A conversa sobe para o topo da lista já nesta repintura (ver `compararAmigos`).
      amigo.ultimaDm = Math.max(Number(amigo.ultimaDm) || 0, Number(m.dm.ts) || agoraDoServidor());
      (ui.conversas[amigo.id] ??= []).push({
        id: m.dm.id, mine: !!meu, texto: m.dm.texto ?? '', ts: m.dm.ts,
        tipo: m.dm.tipo ?? 0, valor: m.dm.valor ?? null,
      });
      if (estado.modalAberto === 'amigos' && ui.sel === amigo.id) pintarThreadDM(amigo.id);
      // A nota de coins não incrementa não lidas nem faz toast próprio — o `amigoCoinsRecebeu`
      // já avisa, e ela fica guardada na conversa para quando o jogador abrir.
      if (!meu && !nota) {
        if (conversaAmigoAVista(amigo.id)) {
          // Estou vendo: marca lida — e os tracinhos do outro lado ficam azuis.
          enviar({ t: 'amigo.dm.ler', amigoId: amigo.id });
        } else {
          // Fechada, ou aberta mas escondida (outra aba, o Comércio, a lista do celular): conta
          // como não lida até ser vista de verdade (`lerConversaAVista` cuida da volta).
          amigo.naoLidas = (amigo.naoLidas || 0) + 1;
          toast(m.dm.tipo === 3 ? t('amigos.pvpa.recebido', { nick: amigo.nick }) : t('ev.amigoDM', { nick: amigo.nick }));
        }
      }
    } else if (!meu && !nota) {
      toast(t('ev.amigoDM', { nick: m.dm.de }));
    }
  }

  // O amigo LEU o que eu mandei (até a mensagem `ateId`): os tracinhos ficam azuis. Só repinta a
  // thread se for esta a conversa na tela — as outras ficam marcadas no cache para quando abrir.
  if (m.lidas) {
    const amigoId = Number(m.lidas.amigoId);
    const ate = Number(m.lidas.ateId) || 0;
    let mudou = false;
    for (const mm of ui.conversas[amigoId] ?? []) {
      if (mm.mine && !mm.lido && Number(mm.id) <= ate) {
        mm.lido = true;
        mudou = true;
      }
    }
    if (mudou && estado.modalAberto === 'amigos' && ui.sel === amigoId) pintarThreadDM(amigoId, false);
  }

  // O resultado da busca do "+ Adicionar amigo". O termo volta junto para a resposta de uma
  // busca antiga (a rede atrasou, o jogador já digitou outra coisa) não sobrescrever a nova.
  if (m.busca) {
    if (!ui.buscaAdd.termo || ui.buscaAdd.termo === m.busca.termo) {
      clearTimeout(ui.buscaAdd.prazo);
      ui.buscaAdd.achados = m.busca.achados ?? [];
      ui.buscaAdd.pedindo = false;
      if (estado.modalAberto === 'amigos' && ui.add) pintarAchadosAmigos();
    }
  }

  if (m.coins) toast(t('ev.amigoCoinsRecebeu', { nick: m.coins.de, v: num(m.coins.valor) }));

  // ---- PvP amistoso
  if (m.pvpa) {
    estado.pvpa = { ...(estado.pvpa ?? {}), ...m.pvpa };
    if (m.pvpa.recusou) toast(t('amigos.pvpa.recusou', { nick: m.pvpa.recusou }));
    atualizarBotaoAmistoso();
  }
  if (m.dmAtualizada) {
    // A linha de um convite mudou de estado (aceito, recusado, cancelado): troca o texto dela
    // onde estiver e repinta a conversa aberta — sem remontar o painel, que apagaria o rascunho.
    for (const lista of Object.values(ui.conversas)) {
      const linha = lista.find((x) => x.id === m.dmAtualizada.id);
      if (linha) linha.texto = m.dmAtualizada.texto;
    }
    if (estado.modalAberto === 'amigos' && ui.sel != null && !ehConversaGuild(ui.sel)) pintarThreadDM(ui.sel, false);
  }
  if (m.pvpAmistoso) abrirPartidaAmistosa(m.pvpAmistoso);

  pintarBadgeAmigos();
  if (estado.perfilOutroNick && !$('#perfil').classList.contains('hidden')) {
    repintarAcoesPerfilOutro(estado.perfilOutroNick);
  }
  if (estado.modalAberto === 'amigos') {
    pintarAbasAmigos();
    // No Comércio, a lista e o painel são de lá: um pacote de amigos só mexe nos contadores.
    if (ui.modo === 'comercio') return;
    pintarRolAmigos();
    // Se uma conversa está aberta com um amigo que ainda existe, NÃO remonta o painel — um pacote
    // com `lista` (o sync de outro shard, um pedido aceito) chega a qualquer hora, e remontar
    // apagaria o rascunho.
    const conversaViva =
      !ui.add && ui.sel != null && (
        ehConversaGuild(ui.sel)
          ? $('#amigos-painel #guild-chat-form')
          : amigoPorId(ui.sel) && $('#amigos-painel #dm-form')
      );
    if (!conversaViva && (m.lista !== undefined || m.enviados !== undefined || m.pedidos !== undefined)) {
      montarPainelAmigos();
    }
  }
}

// ------------------------------------------------------------------ Comércio
//
// A outra metade da Lista de Amigos: o chat entre quem quer comprar e quem vende, preso a UM
// anúncio do Mercado. Nasce no "Enviar DM" do anúncio e morre com ele — vendido, removido ou
// vencido, a conversa some para todo mundo que estava nela (o servidor avisa com `fechou`).
//
// Duas abas, pelo papel: "Minhas Ofertas" são as conversas em que eu sou o COMPRADOR (fui eu que
// chamei o vendedor), e "Meus Produtos" as em que eu sou o VENDEDOR (os compradores chegaram em
// mim). O que encabeça o chat é a OFERTA — a arte, o preço e o botão de volta ao Market —, porque
// é sobre ela que se conversa.
//
// O estado mora em dois lugares, como o dos amigos: `estado.comercio` guarda o que o servidor
// manda (a lista e o total de não lidas), e `amigosUI()` a tela (o modo, a aba, a conversa aberta).

/** Espelho da folga do servidor (`ESPERA_COMERCIO_MS` no sim) — só para não perder o texto. */
const ESPERA_COMERCIO_MS = 2500;
let ultimoEnvioComercio = 0;

function comercioStore() {
  // `lista` nasce `null` (nunca pedida), e não `[]`: "carregando" e "você não tem negociações"
  // são duas telas diferentes.
  estado.comercio ??= { lista: null, naoLidas: 0 };
  return estado.comercio;
}

const conversasComercio = () => comercioStore().lista ?? [];
const conversaComercioPorId = (id) => conversasComercio().find((c) => c.id === Number(id)) ?? null;
const naoLidasComercio = () => comercioStore().naoLidas || 0;
const papelDaAba = (aba) => (aba === 'produtos' ? 'vendedor' : 'comprador');
const naoLidasDaAba = (papel) =>
  conversasComercio().filter((c) => c.papel === papel).reduce((s, c) => s + (c.naoLidas || 0), 0);

/**
 * A mesma conversa? Com os dois ids, pelo id. A que ainda não nasceu (o rascunho do "Enviar DM")
 * não tem id — e aí é o anúncio que a identifica, porque um comprador tem no máximo uma por anúncio.
 */
const mesmaConversa = (x, y) =>
  !!x && !!y && (x.id && y.id ? x.id === y.id : x.anuncioId === y.anuncioId && x.papel === y.papel);

/** O nome da oferta como a lista e o cabeçalho do chat a leem. */
function nomeDaOferta(a) {
  if (!a) return '';
  if (a.tipo === 'pokemon') {
    return `${nomeNoAnuncio(a.ficha)} · ${t('cm.nivel')} ${num(a.ficha?.level ?? 1)}`;
  }
  if (ehAnuncioDiamante(a)) return t('cm.diamanteLote', { n: num(a.qtd) });
  return nomeAnuncioItem(a);
}

/** A arte da oferta: o sprite do pokémon, ou o ícone do item / do diamante. */
const arteDaOferta = (a, px) => (a?.tipo === 'pokemon' ? spritePokemon(a.ficha, px) : arteItemAnuncio(a, px));

/** "22:14" hoje, "23/09 22:14" nos outros dias — a conversa guarda uma semana. */
function horaDaNegociacao(ts) {
  const d = new Date(ts);
  if (d.toDateString() === new Date().toDateString()) return horaCurta(ts);
  const dia = d.toLocaleDateString(idioma() === 'pt' ? 'pt-BR' : idioma(), { day: '2-digit', month: '2-digit' });
  return `${dia} ${horaCurta(ts)}`;
}

/** Pede a lista de novo — com folga, para três mensagens seguidas virarem um pedido só. */
let pedidoListaComercio = 0;
function pedirListaComercio() {
  clearTimeout(pedidoListaComercio);
  pedidoListaComercio = setTimeout(() => enviar({ t: 'comercio.info' }), 300);
}

/**
 * O "Enviar DM" de um anúncio do Mercado: abre a Lista de Amigos no Comércio, com a conversa
 * daquele anúncio já no painel. Se ela ainda não existe, o painel mostra o rascunho — a oferta e
 * a caixa de texto — e ela só nasce no servidor quando a primeira mensagem sair.
 */
function abrirDmDoAnuncio(a) {
  if (!a?.id) return;
  if ((estado.eu?.level ?? 0) < CHAT_NIVEL_MIN && !estado.souAdmin) {
    return toast(t('comercio.nivelMinimo', { n: CHAT_NIVEL_MIN }));
  }
  if (ehMeuAnuncio(a)) return toast(t('comercio.seuAnuncio'));
  const ui = amigosUI();
  const ja = conversasComercio().find((c) => c.anuncioId === a.id && c.papel === 'comprador');
  ui.modo = 'comercio';
  ui.abaCom = 'ofertas';
  ui.add = false;
  ui.comConversa = ja
    ? { ...ja, mensagens: null }
    : {
      id: null, anuncioId: a.id, papel: 'comprador',
      outro: { id: a.vendedorId, nick: a.vendedor, looktype: 0 },
      anuncio: a, mensagens: [],
    };
  abrirModal('amigos');
  verPainelAmigos(true);
  enviar({ t: 'comercio.abrir', anuncioId: a.id });
  // No celular o foco abriria o teclado por cima da oferta, que é o que ele veio ver.
  if (!movelAtivo()) $('#com-input')?.focus();
}

/** Abre uma conversa da lista. O histórico vem do servidor, que também zera as não lidas dela. */
function abrirConversaComercio(id) {
  const c = conversaComercioPorId(id);
  if (!c) return;
  const ui = amigosUI();
  if (!mesmaConversa(ui.comConversa, c)) ui.comConversa = { ...c, mensagens: null };
  verPainelAmigos(true);
  enviar({ t: 'comercio.conversa', conversaId: c.id });
  pintarRolAmigos();
  montarPainelAmigos();
}

/** O botão da oferta no topo do chat: o comprador cai no anúncio, o vendedor nos seus anúncios. */
function abrirOfertaDoComercio() {
  const c = amigosUI().comConversa;
  if (c) abrirAnuncioNoMercado(c.anuncioId);
}

/** Uma linha da lista: a oferta à esquerda, quem está do outro lado, o preço, e quando foi. */
function linhaComercio(c, { on = false, rascunho = false } = {}) {
  const a = c.anuncio;
  const lado = rascunho
    ? `<span class="com-novo">${t('comercio.nova')}</span>`
    : `<time>${c.ultima ? quandoFoi(c.ultima.ts) : ''}</time>`
      + (c.naoLidas ? `<span class="amigo-badge">${c.naoLidas > 9 ? '9+' : c.naoLidas}</span>` : '');
  return `<div class="com-linha${on ? ' on' : ''}"${rascunho ? '' : ` data-com="${c.id}"`}>
    <span class="com-arte" data-arte></span>
    <div class="com-meta">
      <b><span class="amigo-status${c.outro?.online ? ' on' : ''}"></span><span class="com-nick">${escapar(c.outro?.nick ?? '')}</span></b>
      <span class="com-nome">${escapar(nomeDaOferta(a))}</span>
      <span class="com-preco">${precoComMoeda(a.preco, a.moeda)}</span>
    </div>
    <div class="com-lado">${lado}</div>
  </div>`;
}

function pintarRolComercio(rol) {
  const ui = amigosUI();
  const lista = comercioStore().lista;
  const papel = papelDaAba(ui.abaCom);
  const atual = ui.comConversa;
  // A conversa que ainda não nasceu fica no topo de "Minhas Ofertas" enquanto está aberta: é ela
  // que está no painel, e a lista diz isso.
  const rascunho = atual && !atual.id && atual.papel === papel ? atual : null;
  if (lista == null && !rascunho) {
    rol.innerHTML = `<p class="amigos-vazio">${t('comercio.carregando')}</p>`;
    return;
  }
  const busca = (ui.buscaCom ?? '').trim().toLowerCase();
  const daAba = (lista ?? []).filter((c) => c.papel === papel);
  const visiveis = daAba.filter((c) => !busca
    || String(c.outro?.nick ?? '').toLowerCase().includes(busca)
    || nomeDaOferta(c.anuncio).toLowerCase().includes(busca));
  if (!visiveis.length && !rascunho) {
    const vazio = daAba.length ? 'comercio.buscaVazia'
      : papel === 'comprador' ? 'comercio.vazioOfertas' : 'comercio.vazioProdutos';
    rol.innerHTML = `<p class="amigos-vazio">${t(vazio)}</p>`;
    return;
  }
  const todas = rascunho ? [rascunho, ...visiveis] : visiveis;
  rol.innerHTML = todas
    .map((c) => linhaComercio(c, { on: mesmaConversa(atual, c), rascunho: c === rascunho }))
    .join('');
  rol.querySelectorAll('.com-arte').forEach((slot, i) => slot.appendChild(arteDaOferta(todas[i].anuncio, 34)));
}

function montarPainelComercio(host) {
  const ui = amigosUI();
  const c = ui.comConversa;
  if (!c) {
    host.innerHTML = `<div class="amigos-painel-vazio">${t('comercio.escolha')}</div>`;
    return;
  }
  // O mesmo cuidado da DM: remontar o painel (o preço mudou, a conversa ganhou id) não pode apagar
  // o que o jogador está digitando, nem tirar a leitura do lugar.
  const rascunho = $('#com-input')?.value ?? '';
  const focado = document.activeElement?.id === 'com-input';
  const thread = $('#com-thread');
  const coladoNoFim = !thread || thread.scrollHeight - thread.scrollTop - thread.clientHeight < 24;
  const scrollAntes = thread?.scrollTop ?? 0;

  const a = c.anuncio;
  const comprador = c.papel === 'comprador';
  const pk = a.tipo === 'pokemon';
  const online = c.outro?.online == null ? '' : ` · ${t(c.outro.online ? 'amigos.online' : 'amigos.offline')}`;
  host.innerHTML = `
    <div class="amigo-cab com-cab">
      <button type="button" class="amigo-voltar" data-voltar aria-label="${t('amigos.voltar')}">‹</button>
      <span class="com-cab-ico" aria-hidden="true">⇄</span>
      <div class="amigo-meta">
        <b>${t('comercio.titulo')}</b>
        <span>${t(comprador ? 'comercio.subComprador' : 'comercio.subVendedor')}</span>
      </div>
    </div>
    <div class="com-oferta${pk && a.ficha?.shiny ? ' shiny' : ''}">
      <div class="com-oferta-arte"></div>
      <div class="com-oferta-info">
        <b class="com-oferta-nome">${escapar(nomeDaOferta(a))}${numeroDoAnuncio(a) ? ` ${plaquinhaDoAnuncio(a)}` : ''}</b>
        ${pk ? selosAtributos({ ...a.ficha, nota: notaDoFicha(a.ficha) }, { compacto: true }) : ''}
        ${!pk && a.qtd > 1 ? `<span class="com-oferta-sub">${t('cm.emEstoque', { n: num(a.qtd) })}</span>` : ''}
        <span class="com-oferta-preco">${precoComMoeda(a.preco, a.moeda)}${a.qtd > 1 ? `<i>${t('cm.porUnidade')}</i>` : ''}</span>
        <span class="com-oferta-quem">${t(comprador ? 'comercio.vendedor' : 'comercio.comprador', {
          nick: `<b>${escapar(c.outro?.nick ?? '')}</b>`,
        })}${online}</span>
      </div>
      <button type="button" class="dm-enviar com-oferta-bt" data-com-market>
        <span aria-hidden="true">↗</span>${t(comprador ? 'comercio.abrirMarket' : 'comercio.verMeuAnuncio')}
      </button>
    </div>
    <div class="dm-thread com-thread" id="com-thread"></div>
    <p class="com-nota"><span class="com-nota-ico" aria-hidden="true">!</span><span>${t('comercio.nota')}</span></p>
    <form class="dm-composer" id="com-form" autocomplete="off">
      <input type="text" id="com-input" maxlength="500" placeholder="${t('comercio.placeholder')}">
      <button type="submit" class="dm-enviar">${t('amigos.dmEnviar')}</button>
    </form>`;
  host.querySelector('.com-oferta-arte').appendChild(arteDaOferta(a, 56));
  pintarThreadComercio(coladoNoFim, scrollAntes);
  const inp = $('#com-input');
  if (inp && rascunho) {
    inp.value = rascunho;
    inp.setSelectionRange?.(rascunho.length, rascunho.length);
  }
  if (inp && focado) inp.focus();
}

/** A conversa: o nick e a hora em cima de cada fala, a minha à direita e em roxo, como na DM. */
function pintarThreadComercio(rolarAoFim = true, scrollAntes = null) {
  const thread = $('#com-thread');
  if (!thread) return;
  const c = amigosUI().comConversa;
  const msgs = c?.mensagens;
  if (msgs == null) {
    thread.innerHTML = `<p class="dm-vazio">${t('comercio.carregando')}</p>`;
    return;
  }
  if (!msgs.length) {
    thread.innerHTML = `<p class="dm-vazio">${t(c.papel === 'comprador' ? 'comercio.vazioThread' : 'comercio.vazioThreadVendedor')}</p>`;
    return;
  }
  const antes = scrollAntes ?? thread.scrollTop;
  const eu = estado.eu?.id;
  const meuNick = estado.eu?.nick ?? estado.nick ?? '';
  thread.innerHTML = msgs.map((mm) => {
    const minha = mm.deId === eu;
    return `<div class="com-msg ${minha ? 'eu' : 'ele'}">
      <div class="com-msg-quem"><b>${escapar(minha ? meuNick : c.outro?.nick ?? '')}</b><time>${horaDaNegociacao(mm.ts)}</time></div>
      <div class="dm-bolha ${minha ? 'eu' : 'ele'}"><span class="dm-txt">${escapar(mm.texto)}</span></div>
    </div>`;
  }).join('');
  thread.scrollTop = rolarAoFim ? thread.scrollHeight : antes;
}

function enviarMsgComercio() {
  const c = amigosUI().comConversa;
  const inp = $('#com-input');
  const texto = (inp?.value ?? '').trim().slice(0, 500);
  if (!texto || !c) return;
  if (chatContemNft(texto)) return toast(t('chat.nftBloqueado'));
  if (Date.now() - ultimoEnvioComercio < ESPERA_COMERCIO_MS) {
    toast(t('comercio.espera')); // não limpa o campo — o texto fica para reenviar
    return;
  }
  ultimoEnvioComercio = Date.now();
  // Sem id, a conversa ainda não existe: vai o anúncio, e o servidor a cria com esta mensagem.
  enviar(c.id
    ? { t: 'comercio.enviar', conversaId: c.id, texto }
    : { t: 'comercio.enviar', anuncioId: c.anuncioId, texto });
  if (inp) inp.value = '';
}

/** Uma mensagem ao vivo — a minha de volta (eco) ou a do outro lado. */
function receberMsgComercio(msg, nova) {
  const store = comercioStore();
  const ui = amigosUI();
  const minha = msg.deId === estado.eu?.id;
  const atual = ui.comConversa;
  // A conversa em branco do "Enviar DM" acabou de nascer: ganha o id, e entra na lista na hora em
  // vez de esperar a lista inteira voltar do servidor.
  if (minha && nova && atual && !atual.id && atual.papel === 'comprador' && atual.anuncioId === msg.anuncioId) {
    atual.id = msg.conversaId;
    if (store.lista && !conversaComercioPorId(msg.conversaId)) {
      store.lista.unshift({
        id: msg.conversaId, anuncioId: msg.anuncioId, papel: 'comprador',
        outro: atual.outro, anuncio: atual.anuncio, ultima: null, naoLidas: 0, atualizadoEm: msg.ts,
      });
    }
  }
  const aberta = !!atual?.id && atual.id === msg.conversaId;
  const vendo = aberta && estado.modalAberto === 'amigos' && ui.modo === 'comercio' && !document.hidden;
  if (aberta) {
    atual.mensagens ??= [];
    if (!atual.mensagens.some((x) => x.id === msg.id)) {
      atual.mensagens.push({ id: msg.id, deId: msg.deId, texto: msg.texto, ts: msg.ts });
    }
  }

  const c = conversaComercioPorId(msg.conversaId);
  if (c) {
    c.ultima = { texto: msg.texto, minha, ts: msg.ts };
    c.atualizadoEm = msg.ts;
    store.lista = [c, ...store.lista.filter((x) => x !== c)];
    if (!minha && !vendo) c.naoLidas = (c.naoLidas || 0) + 1;
  } else if (store.lista != null) {
    // Uma conversa que a lista não conhece: um comprador novo chegando no meu anúncio.
    pedirListaComercio();
  }

  if (vendo) {
    const th = $('#com-thread');
    const colado = !th || th.scrollHeight - th.scrollTop - th.clientHeight < 24;
    // Na conversa em branco o painel ainda diz "nenhuma mensagem": a primeira troca o texto.
    pintarThreadComercio(minha || colado);
  }
  if (minha) return;
  if (vendo) {
    enviar({ t: 'comercio.ler', conversaId: msg.conversaId });
  } else {
    store.naoLidas = (store.naoLidas || 0) + 1;
    toast(t('comercio.toastMsg', { nick: msg.de ?? '' }));
  }
}

function aoReceberComercio(m) {
  const store = comercioStore();
  const ui = amigosUI();
  let remontar = false;

  if (m.lista !== undefined) {
    store.lista = m.lista;
    const atual = ui.comConversa;
    // O rascunho que nasceu por outro caminho (outra aba do navegador) ganha o id pela lista.
    if (atual && !atual.id) {
      const nasceu = m.lista.find((x) => x.papel === atual.papel && x.anuncioId === atual.anuncioId);
      if (nasceu) atual.id = nasceu.id;
    }
    // A conversa aberta acompanha o que a lista sabe dela: a oferta e o pontinho de online.
    const viva = atual?.id ? m.lista.find((x) => x.id === atual.id) : null;
    if (viva) {
      atual.anuncio = viva.anuncio;
      atual.outro = viva.outro;
      remontar = true;
    }
  }
  if (m.naoLidas !== undefined) store.naoLidas = m.naoLidas;

  // O histórico de uma conversa. Só entra se é a que a tela está esperando: a resposta de um
  // clique antigo não pode tomar o painel de outra.
  if (m.conversa && mesmaConversa(ui.comConversa, m.conversa)) {
    ui.comConversa = m.conversa;
    const c = conversaComercioPorId(m.conversa.id);
    if (c) c.naoLidas = 0;
    remontar = true;
  }

  if (m.msg) receberMsgComercio(m.msg, !!m.nova);

  // O anúncio mudou sem sair (preço editado, compra parcial): a oferta acompanha.
  if (m.anuncio) {
    for (const c of conversasComercio()) if (c.anuncioId === m.anuncio.id) c.anuncio = m.anuncio;
    if (ui.comConversa?.anuncioId === m.anuncio.id) {
      ui.comConversa.anuncio = m.anuncio;
      remontar = true;
    }
  }

  // Saíram do Market: as conversas deles somem — para mim e para todo mundo que estava nelas.
  if (m.fechou?.length) {
    const fora = new Set(m.fechou.map(Number));
    if (store.lista) {
      store.lista = store.lista.filter((c) => !fora.has(c.anuncioId));
      store.naoLidas = store.lista.reduce((s, c) => s + (c.naoLidas || 0), 0);
    } else if (store.naoLidas > 0) {
      // Sem a lista não há como saber quantas das não lidas eram das conversas que fecharam.
      pedirListaComercio();
    }
    if (ui.comConversa && fora.has(ui.comConversa.anuncioId)) {
      ui.comConversa = null;
      remontar = true;
      if (estado.modalAberto === 'amigos' && ui.modo === 'comercio') {
        toast(t('comercio.fechouAberta'));
        verPainelAmigos(false);
      }
    }
  }

  pintarBadgeAmigos();
  if (estado.modalAberto !== 'amigos') return;
  pintarAbasAmigos();
  if (ui.modo !== 'comercio') return;
  pintarRolAmigos();
  if (remontar || !$('#com-form')) montarPainelAmigos();
}

// ---- o Comércio e o alto-falante dentro do Mercado

/**
 * Leva a UM anúncio — o link do alto-falante no chat e o "Abrir no Market" do Comércio.
 *
 * O anúncio vem do servidor na hora (`market.anuncio`), e não de cache nenhum: a linha do chat
 * pode ter meia hora, e o anúncio pode já ter saído, mudado de preço ou encolhido. O de ITEM abre
 * o painel de ofertas dele por trás — fechar a folha deixa o jogador comparando com os outros
 * vendedores, que é a pergunta seguinte. O próprio anúncio vai para "Meus anúncios".
 */
function abrirAnuncioNoMercado(id) {
  if (!Number.isSafeInteger(id) || id <= 0) return;
  estado.cmVerAnuncio = id;
  enviar({ t: 'market.anuncio', id });
}

function mostrarAnuncioAvulso(m) {
  if (estado.cmVerAnuncio !== m.id) return;
  estado.cmVerAnuncio = null;
  const a = m.anuncio;
  if (!a || a.estado !== 'aberto') return toast(t('comercio.anuncioSaiu'));
  if (ehMeuAnuncio(a)) {
    estado.cmAba = 'meus';
    estado.cmPagina = 0;
    return abrirModal('community');
  }
  if (a.tipo === 'item' && itemDoMercado(a.itemId)) {
    estado.cmItemMoeda = a.moeda === 'orb' ? 'orb' : 'gold';
    irParaOfertasDoItem(a.itemId);
  } else if (estado.modalAberto !== 'community') {
    abrirModal('community');
  }
  const { corpo } = folhaMercado(t('cm.anuncioTitulo'));
  corpo.classList.add('cm-avulso');
  corpo.appendChild(cardAnuncio(a, false));
}

/** O "Enviar DM" em HTML, para as linhas de oferta (painel de item, diamantes). */
const htmlBotaoDm = (a) =>
  `<button type="button" class="cmv-dm" data-dm="${a.id}" title="${escapar(t('cm.enviarDMDica', { nick: a.vendedor ?? '' }))}">`
  + `<span aria-hidden="true">💬</span>${t('cm.enviarDM')}</button>`;

/** O "Enviar DM" do card, numa fileira própria logo abaixo do Comprar. */
function linhaDmDoCard(a) {
  const linha = document.createElement('div');
  linha.className = 'cm-botoes cm-botoes-dm';
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'cm-btn cm-dm';
  b.title = t('cm.enviarDMDica', { nick: a.vendedor ?? '' });
  b.innerHTML = `<span aria-hidden="true">💬</span> ${escapar(t('cm.enviarDM'))}`;
  b.onclick = (ev) => {
    ev.stopPropagation();
    abrirDmDoAnuncio(a);
  };
  linha.appendChild(b);
  return linha;
}

/**
 * O ALTO-FALANTE, no canto de um card de "Meus anúncios" — o lugar da estrela nos cards dos
 * outros. A espera é da CONTA: um anúncio no chat apaga o botão de todos os cards juntos.
 */
function botaoAltoFalante(a) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'cm-alto';
  b.innerHTML = '<span aria-hidden="true">📢</span>';
  pintarBotaoAltoFalante(b);
  b.onclick = (ev) => {
    ev.stopPropagation();
    pedirAltoFalante(a);
  };
  return b;
}

function pintarBotaoAltoFalante(b) {
  const resta = (estado.cmAltoFalanteAte ?? 0) - agoraDoServidor();
  const espera = resta > 0;
  b.classList.toggle('esperando', espera);
  b.title = espera
    ? t('cm.altoFalanteEsperaDica', { tempo: tempoCurto(resta) })
    : t('cm.altoFalante', { custo: num(CUSTO_ALTO_FALANTE) });
  b.setAttribute('aria-label', b.title);
  let relogio = b.querySelector('.cm-alto-t');
  if (!espera) {
    relogio?.remove();
    return;
  }
  if (!relogio) {
    relogio = document.createElement('i');
    relogio.className = 'cm-alto-t';
    b.appendChild(relogio);
  }
  relogio.textContent = `${Math.ceil(resta / 60_000)}m`;
}

function atualizarAltoFalantes() {
  if (document.hidden) return;
  for (const b of document.querySelectorAll('.cm-alto')) pintarBotaoAltoFalante(b);
}
setInterval(atualizarAltoFalantes, 1000);

/** O que o chat vai mostrar deste anúncio — a fôrma de `ofertaParaOChat` no sim, para a prévia. */
function ofertaDoAnuncio(a) {
  const f = a.ficha ?? {};
  return {
    id: a.id, tipo: a.tipo, qtd: a.qtd, preco: a.preco, moeda: a.moeda, itemId: a.itemId ?? null,
    numerado: !!(f.caixaId || f.casaId || f.bicicletaId),
    nome: a.tipo === 'pokemon' ? f.nome ?? '' : nomeAnuncioItem(a),
    level: a.tipo === 'pokemon' ? f.level ?? null : null,
    shiny: a.tipo === 'pokemon' && !!f.shiny,
  };
}

/**
 * O clique no alto-falante. A espera e o saldo são conferidos aqui só para o "não" vir antes do
 * diálogo — quem cobra e trava é o servidor. O diálogo mostra a frase EXATA que vai para o chat.
 */
function pedirAltoFalante(a) {
  const resta = (estado.cmAltoFalanteAte ?? 0) - agoraDoServidor();
  if (resta > 0) return toast(t('cm.altoFalanteEspera', { tempo: tempoCurto(resta) }));
  if ((estado.eu?.gold ?? 0) < CUSTO_ALTO_FALANTE) {
    return toast(t('cm.altoFalanteSemSaldo', { custo: num(CUSTO_ALTO_FALANTE) }));
  }
  const nick = escapar(estado.eu?.nick ?? estado.nick ?? '');
  // O megafone e, ao lado, a linha EXATA que vai cair no chat — a prévia é a parte que decide.
  // O preço sai da frase e vira a etiqueta com o saldo; a espera e os canais, selos.
  confirmar({
    titulo: t('cm.altoFalanteTitulo'),
    texto: `
      <div class="dlg-palco tom-ouro dlg-megafone">
        ${dlgMedalha({ icone: 'megafone', tom: 'ouro', px: 34 })}
        <span class="cm-alto-previa"><b>📢 ${nick}:</b> ${fraseDoAnuncioNoChat(ofertaDoAnuncio(a))}</span>
      </div>
      ${dlgFrase('', t('cm.altoFalanteLead'))}
      ${dlgCusto({ moeda: 'ouro', valor: CUSTO_ALTO_FALANTE, saldo: Math.floor(estado.eu?.gold ?? 0) })}
      ${dlgSelos(
        dlgSelo('olho', escapar(t('cm.altoFalanteSeloCanais')), 'rx'),
        dlgSelo('relogio', escapar(t('cm.altoFalanteSeloEspera')), 'info'),
      )}`,
    rotuloSim: t('cm.altoFalanteSim', { custo: num(CUSTO_ALTO_FALANTE) }),
    aoConfirmar: () => enviar({ t: 'market.anunciarChat', id: a.id }),
  });
}

// ------------------------------------------------------------- Passe de Batalha
//
// A trilha de 30 dias de login (ver `shared/passe-batalha.mjs`). A tela calcula TUDO com as mesmas
// funções do servidor — o degrau de hoje, se a sequência quebrou, o alcance do VIP — a partir do
// campo `passe` do snapshot e do relógio do servidor (`agoraDoServidor`). Quem entrega é o
// servidor: o botão manda `passe.resgatar` sem campo nenhum.
//
// A tela é feita para dar vontade de voltar amanhã: o Dia 30 à vista desde o Dia 1, a contagem
// regressiva de quando a sequência zera, e o painel do VIP dizendo quanto ele vale na Loja.

const ICONE_PASSE_FREE = '/img/passe-free.png';
const ICONE_PASSE_VIP = '/img/passe-vip.png';
/** Os ícones dos boosts são os da Loja (`TIPOS_BOOST` em `game/loja.mjs`). */
const ICONE_BOOST_PASSE = {
  xp: 'site/assets/loja/exp.png',
  pokexp: 'site/assets/loja/boost.png',
  loot: 'site/assets/loja/loot.png',
  captura: 'site/assets/loja/catch.png',
  shiny: 'site/assets/loja/shinysecretlure.png',
};
const ICONE_VIP_PASSE = 'site/assets/loja/vip.png';
const NOME_BOOST_PASSE = {
  xp: 'passe.boost.xp', pokexp: 'passe.boost.pokexp', loot: 'passe.boost.loot', captura: 'passe.boost.captura', shiny: 'passe.boost.shiny',
};

let ultimaAssinaturaPasse = '';
/** O resgate em andamento — trava o botão até a resposta (ou 8 s, se ela não vier). */
let passeResgatando = false;

const estadoPasseTela = () => estadoDoPasse({ passe: estado.eu?.passe }, agoraDoServidor());
const passeNivelOk = () => !!estado.eu?.admin || (estado.eu?.level ?? 0) >= PASSE_NIVEL_MIN;
/** Tem resgate esperando? É o que acende o selo do botão do menu. */
const passeTemResgate = () => {
  if (!estado.eu || !passeNivelOk()) return false;
  const st = estadoPasseTela();
  return !st.jaPegouHoje || st.vipPendenteHoje;
};

function pintarSeloPasse() {
  const bt = $('.menu-topo button[data-modal="passe"]');
  if (bt) bt.classList.toggle('tem-premio', passeTemResgate());
}
// O dia vira sozinho à meia-noite de Brasília: sem snapshot nenhum chegando, o selo tem de
// acender mesmo assim. Meio minuto de atraso na virada é invisível.
setInterval(pintarSeloPasse, 30_000);

/** "1:02:33" — relógio de quanto falta até `ate` (pelo relógio do servidor). */
function relogioPasse(ate) {
  const s = Math.max(0, Math.floor((ate - agoraDoServidor()) / 1000));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const ss = String(s % 60).padStart(2, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`;
}

/** "12d 4h" — quanto falta de VIP. */
function restantePasseVip(ate) {
  const ms = Math.max(0, ate - agoraDoServidor());
  const d = Math.floor(ms / 86_400_000);
  const h = Math.floor((ms % 86_400_000) / 3_600_000);
  return d ? t('passe.dh', { d, h }) : t('passe.h', { h: Math.max(1, h) });
}

function nomePremioPasse(pr) {
  if (pr.tipo === 'coins') return t('passe.pr.coins', { v: num(pr.qtd) });
  if (pr.tipo === 'bola' || pr.tipo === 'item') return `${num(pr.qtd)}× ${nomeDoPremio(pr)}`;
  if (pr.tipo === 'boost') return t('passe.pr.boost', { nome: t(NOME_BOOST_PASSE[pr.boost] ?? pr.boost), h: pr.horas });
  if (pr.tipo === 'vip') return t('passe.pr.vip', { d: pr.dias });
  return '?';
}

/** O rótulo curtinho da célula da trilha: "250 mil", "×30", "3h", "3d". */
function rotuloCurtoPasse(pr) {
  if (pr.tipo === 'coins') return numCurto(pr.qtd);
  if (pr.tipo === 'boost') return `${pr.horas}h`;
  if (pr.tipo === 'vip') return `${pr.dias}d`;
  return `×${num(pr.qtd)}`;
}

/** O ícone de um prêmio do Passe (elemento). */
function iconePremioPasse(pr, px = 28) {
  if (pr.tipo === 'coins') return iconeArquivo(ICONE_OURO, px);
  if (pr.tipo === 'bola' || pr.tipo === 'item') return iconeDoPremio(pr, px);
  if (pr.tipo === 'boost') return iconeArquivo(ICONE_BOOST_PASSE[pr.boost] ?? ICONE_BOOST_PASSE.xp, px);
  if (pr.tipo === 'vip') return iconeArquivo(ICONE_VIP_PASSE, px);
  return document.createElement('span');
}

// ---------------------------------------------- Convites do Discord (/resgatar)
//
// O prêmio de um marco usa o MESMO vocabulário do Passe (ver `shared/convites.mjs`), com dois
// tipos a mais: `diamante` e `vipPermanente`. Por isso as duas funções abaixo delegam ao Passe
// no caso geral em vez de repetir a lista — um boost de 6h tem de ser escrito e desenhado igual
// nas duas telas.

function nomePremioConvite(pr) {
  if (pr.tipo === 'diamante') return t('convite.pr.diamante', { v: num(pr.qtd) });
  if (pr.tipo === 'vipPermanente') return t('convite.pr.vipPermanente');
  return nomePremioPasse(pr);
}

function iconePremioConvite(pr, px = 28) {
  if (pr.tipo === 'diamante') return iconeArquivo(ICONE_DIAMANTE, px);
  if (pr.tipo === 'vipPermanente') return iconeArquivo(ICONE_VIP_PASSE, px);
  return iconePremioPasse(pr, px);
}

/**
 * A resposta do `/resgatar`. Recusa vira aviso na própria lista do chat (foi lá que o comando
 * foi digitado); sucesso abre a caixa com o que entrou na conta.
 */
function aoReceberConvite(m) {
  if (m.recusa) return mostrarAvisoChat(m.recusa);
  if (m.marco == null) return;
  const premios = Array.isArray(m.premios) ? m.premios : [];
  tocarShinyCaptura();
  const linhas = premios.map((pr, i) => `
    <div class="cv-premio">
      <span class="cv-premio-ico" data-i="${i}"></span>
      <b>${escapar(nomePremioConvite(pr))}</b>
    </div>`).join('');
  // O marco é o ATOR (a medalha de quem trouxe gente, acesa no palco de ouro) e os prêmios, as
  // cartas embaixo — a mesma leitura de "você recebeu" do resto do jogo.
  confirmar({
    titulo: t('convite.resgatouTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArteHtml(dlgMedalha({ icone: 'pessoaMais', tom: 'ouro' })),
        nome: escapar(t('convite.degrau', { n: num(m.marco) })),
        sub: escapar(t('convite.marcoSub')),
        classe: 'novo',
      }), 'ouro')}
      <p class="cv-entrou">${escapar(t('convite.entrouNaConta'))}</p>
      <div class="cv-premios">${linhas}</div>`,
    soOk: true,
    rotuloSim: t('convite.resgatouOk'),
    aoConfirmar: null,
  });
  // Os ícones entram como NÓ depois do innerHTML, como no Passe: `iconeArquivo` monta um
  // elemento, e concatenar HTML de ícone aqui abriria uma segunda porta que aceita markup.
  for (const el of document.querySelectorAll('#confirmar-texto .cv-premio-ico')) {
    const pr = premios[Number(el.dataset.i)];
    if (pr) el.appendChild(iconePremioConvite(pr, 26));
  }
}

/**
 * A ESCADA inteira, como resposta a um `/resgatar` sem código.
 *
 * A tabela vem de `shared/convites.mjs` — a mesma que o bot consulta para decidir quando gerar
 * um código e que o servidor consulta para entregar. Escrever os degraus à mão aqui seria uma
 * promessa que desanda do resto no primeiro ajuste.
 */
function mostrarEscadaDeConvites() {
  // Os dois degraus de cima (o VIP de 90 dias e o PERMANENTE) ganham o anel de ouro: é para
  // eles que a escada aponta.
  const degraus = MARCOS_CONVITE.map((mc, iDeg) => `
    <div class="cv-degrau${iDeg >= MARCOS_CONVITE.length - 2 ? ' topo' : ''}">
      <b class="cv-degrau-n"><span class="cv-degrau-ico">${dlgIcone('pessoaMais', 15)}</span>${t(iDeg === MARCOS_CONVITE.length - 1 ? 'convite.degrauMais' : 'convite.degrau', { n: num(mc.amigos) })}</b>
      <div class="cv-degrau-premios">
        ${mc.premios.map((pr, i) => `<span class="cv-premio-linha">
            <span class="cv-premio-ico" data-deg="${iDeg}" data-i="${i}"></span>${escapar(nomePremioConvite(pr))}
          </span>`).join('')}
      </div>
    </div>`).join('');
  // O parágrafo de instrução virou os três passos, um por linha com ícone, e a regra da conta
  // de Discord (a que mais derruba convite) ficou numa faixa própria.
  confirmar({
    titulo: t('convite.escadaTitulo'),
    texto: `
      ${dlgLista([
        { icone: 'pessoaMais', html: t('convite.passoChamar') },
        { icone: 'bandeira', html: t('convite.passoCodigo') },
        { icone: 'check', html: t('convite.passoResgatar') },
      ])}
      ${dlgAviso(escapar(t('convite.regraConta')), { icone: 'relogio', tom: 'info' })}
      <div class="cv-escada">${degraus}</div>`,
    soOk: true,
    largura: 'larga',
    rotuloSim: t('convite.resgatouOk'),
    aoConfirmar: null,
  });
  for (const el of document.querySelectorAll('#confirmar-texto .cv-premio-ico')) {
    const pr = MARCOS_CONVITE[Number(el.dataset.deg)]?.premios[Number(el.dataset.i)];
    if (pr) el.appendChild(iconePremioConvite(pr, 22));
  }
}

/** Lugar de um ícone de prêmio, trocado pelo elemento depois do innerHTML. */
const lugarPremioPasse = (trilha, dia, i, px) =>
  `<span class="ps-ico" data-trilha="${trilha}" data-dia="${dia}" data-i="${i}" data-px="${px}"></span>`;

function pintarIconesPasse(host) {
  for (const el of host.querySelectorAll('.ps-ico:not(.pronto)')) {
    el.classList.add('pronto');
    const d = degrauDaTrilha(Number(el.dataset.dia));
    const pr = d?.[el.dataset.trilha]?.[Number(el.dataset.i)];
    if (pr) el.appendChild(iconePremioPasse(pr, Number(el.dataset.px) || 28));
  }
}

/**
 * Quanto a trilha VIP vale na LOJA, em diamantes: boosts pelo preço da mesma duração, dias de
 * VIP pelo VIP de 30 dias, Beast Ball pelo pacote de 500 (a faixa sem desconto, que é a régua
 * da prateleira — avaliar pela faixa grande inflaria o prêmio de um punhado de bolas). É o
 * número do "vale X 💎" — calculado
 * pela tabela de preços que o servidor mandou, e não escrito à mão.
 */
function valorVipNaLoja() {
  const produtos = estado.lojaProdutos ?? [];
  const preco = (id) => produtos.find((p) => p.id === id)?.preco ?? null;
  const idBoost = { xp: 'xp', pokexp: 'pokexp', loot: 'loot', captura: 'capture', shiny: 'shinycharm' };
  let total = 0;
  for (const d of TRILHA_PASSE) {
    for (const pr of d.vip) {
      if (pr.tipo === 'boost') {
        const sufixo = pr.horas === 1 ? '' : `_${pr.horas}h`;
        total += preco(`boost_${idBoost[pr.boost]}${sufixo}`) ?? 0;
      } else if (pr.tipo === 'vip') {
        total += ((preco('vip30') ?? 10) / 30) * pr.dias;
      } else if (pr.tipo === 'bola' && pr.id === 5) {
        total += ((preco('beast500') ?? 10) / 500) * pr.qtd;
      }
    }
  }
  return Math.floor(total / 10) * 10;
}

function renderPasse() {
  return `<div class="ps" id="ps-corpo"></div>`;
}

function montarPasse() {
  ultimaAssinaturaPasse = `${JSON.stringify(estado.eu?.passe ?? null)}|${estado.eu?.diamonds ?? 0}|${estado.eu?.level ?? 0}`;
  pintarPasse({ rolarParaHoje: true });
}

function htmlCelulaPasse(d, trilha, st, vipAtivo) {
  const premios = d[trilha];
  const feito = d.dia < st.degrau || (d.dia === st.degrau && st.jaPegouHoje && (trilha === 'free' || !st.vipPendenteHoje));
  const hoje = d.dia === st.degrau && (!st.jaPegouHoje || (trilha === 'vip' && st.vipPendenteHoje));
  const trancada = trilha === 'vip' && !vipAtivo;
  // VIP que acaba antes deste degrau: a célula avisa com a ampulheta.
  const foraDoVip = trilha === 'vip' && vipAtivo && st.alcanceVip > 0 && d.dia > st.alcanceVip && d.dia > st.degrau;
  const classes = ['ps-cel', trilha, d.tier, feito ? 'feito' : '', hoje ? 'hoje' : '', trancada ? 'trancada' : '', foraDoVip ? 'fora' : '']
    .filter(Boolean).join(' ');
  const titulo = premios.map(nomePremioPasse).join(' + ');
  return `<div class="${classes}" title="${escapar(titulo)}">
      ${premios.map((pr, i) => `<span class="ps-pr">${lugarPremioPasse(trilha, d.dia, i, d.bau ? 30 : 24)}<em>${escapar(rotuloCurtoPasse(pr))}</em></span>`).join('')}
      ${feito && trilha === 'free' ? '<i class="ps-ok" aria-hidden="true">✓</i>' : ''}
      ${trancada ? '<i class="ps-cadeado" aria-hidden="true">🔒</i>' : ''}
      ${foraDoVip ? '<i class="ps-cadeado" aria-hidden="true">⌛</i>' : ''}
    </div>`;
}

function htmlTrilhaPasse(st, vipAtivo) {
  return TRILHA_PASSE.map((d) => `
    <div class="ps-col ${d.tier}${d.bau ? ' bau' : ''}${d.dia === st.degrau ? ' atual' : ''}" data-dia="${d.dia}">
      <span class="ps-dia">${d.bau ? '<i aria-hidden="true">🎁</i>' : ''}${t('passe.diaN', { n: d.dia })}</span>
      ${htmlCelulaPasse(d, 'free', st, vipAtivo)}
      ${htmlCelulaPasse(d, 'vip', st, vipAtivo)}
    </div>`).join('');
}

function htmlPremiosDoDia(d, trilha, trancada) {
  return `<div class="ps-hoje-lista ${trilha}${trancada ? ' trancada' : ''}">
    <span class="ps-hoje-rot"><img src="${trilha === 'vip' ? ICONE_PASSE_VIP : ICONE_PASSE_FREE}" alt="">${t(trilha === 'vip' ? 'passe.trilhaVip' : 'passe.trilhaFree')}${trancada ? ' 🔒' : ''}</span>
    ${d[trilha].map((pr, i) => `<span class="ps-hoje-pr">${lugarPremioPasse(trilha, d.dia, i, 30)}<b>${escapar(nomePremioPasse(pr))}</b></span>`).join('')}
  </div>`;
}

/**
 * Comprar (ou estender) o Passe VIP: o selo do passe no palco com os dias que ele vale, a etiqueta
 * de diamantes com o saldo que fica e a frase de sempre embaixo.
 */
function confirmarPasseVip(vipAtivo) {
  confirmar({
    titulo: t('passe.vipTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArteArquivo(ICONE_PASSE_VIP, 64, true),
        nome: escapar(t('passe.vipTitulo')),
        classe: 'novo',
        qtd: `+${num(PASSE_VIP_DIAS)}d`,
      }), 'ouro')}
      ${dlgCusto({ moeda: 'diamante', valor: PASSE_VIP_PRECO, saldo: Number(estado.eu?.diamonds ?? 0) })}
      ${dlgFrase('', t(vipAtivo ? 'passe.confirmaEstender' : 'passe.confirmaComprar', { d: PASSE_VIP_DIAS }))}`,
    aoConfirmar: () => enviar({ t: 'passe.comprarVip' }),
  });
}

function pintarPasse({ rolarParaHoje = false } = {}) {
  const host = $('#ps-corpo');
  if (!host) return;
  const st = estadoPasseTela();
  const nivelOk = passeNivelOk();
  const vipAtivo = st.vipAtivo;
  const d = degrauDaTrilha(st.degrau);
  const hoje = diaDoPasse(agoraDoServidor());
  const proximo = st.degrau >= PASSE_DIAS ? 1 : st.degrau + 1;
  // Quando a sequência ZERA se o jogador não voltar: o fim de hoje (se ainda não pegou) ou o fim
  // de amanhã (se já pegou hoje). Com a trilha no Dia 1 e nada pego, não há o que perder.
  const zeraEm = st.jaPegouHoje ? inicioDoDiaDoPasse(hoje + 2) : inicioDoDiaDoPasse(hoje + 1);
  const temSequencia = st.jaPegouHoje || st.degrau > 1;
  const saldo = estado.eu?.diamonds ?? 0;

  let botao;
  if (!nivelOk) {
    botao = `<button type="button" class="ps-resgatar" disabled>${t('passe.nivelMin', { n: PASSE_NIVEL_MIN })}</button>`;
  } else if (!st.jaPegouHoje) {
    botao = `<button type="button" class="ps-resgatar pulsa" id="ps-resgatar"${passeResgatando ? ' disabled' : ''}>
      ${t('passe.resgatarDia', { n: st.degrau })}</button>`;
  } else if (st.vipPendenteHoje) {
    botao = `<button type="button" class="ps-resgatar vip pulsa" id="ps-resgatar"${passeResgatando ? ' disabled' : ''}>
      👑 ${t('passe.resgatarVipDia', { n: st.degrau })}</button>`;
  } else {
    botao = `<button type="button" class="ps-resgatar" disabled>
      ${t('passe.volteEm', { n: proximo })} <b data-ps-relogio="${inicioDoDiaDoPasse(hoje + 1)}">${relogioPasse(inicioDoDiaDoPasse(hoje + 1))}</b></button>`;
  }

  const somaVip = somaDaTrilha('vip');
  const horasBoostVip = Object.values(somaVip.boosts).reduce((s, h) => s + h, 0);
  const valorLoja = valorVipNaLoja();
  // Comprando AGORA, o VIP cobre de hoje (o VIP de hoje sai na hora, mesmo depois do grátis) até
  // 30 dias corridos para a frente — quase sempre a trilha inteira até o 30.
  const alcanceSeComprar = Math.min(PASSE_DIAS, st.degrau + PASSE_VIP_DIAS - 1);

  const painelVip = vipAtivo
    ? `<div class="ps-vip ativo">
        <img class="ps-vip-coroa" src="${ICONE_PASSE_VIP}" alt="">
        <div class="ps-vip-txt">
          <b>${t('passe.vipAtivo')}</b>
          <span>${t('passe.vipFaltam', { t: restantePasseVip(st.vipAte) })}</span>
          <span class="ps-vip-alcance">${st.alcanceVip >= PASSE_DIAS ? t('passe.alcance30') : t('passe.alcanceAte', { n: st.alcanceVip })}</span>
        </div>
        <button type="button" class="ps-vip-bt estender" id="ps-comprar-vip">${t('passe.estender', { n: PASSE_VIP_PRECO })} ${seloDiamante(16)}</button>
      </div>`
    : `<div class="ps-vip">
        <span class="ps-vip-brilho" aria-hidden="true"></span>
        <img class="ps-vip-coroa" src="${ICONE_PASSE_VIP}" alt="">
        <div class="ps-vip-txt">
          <b>${t('passe.vipTitulo')}</b>
          ${valorLoja > PASSE_VIP_PRECO ? `<span class="ps-vip-vale">${t('passe.vipVale', { v: num(valorLoja), p: PASSE_VIP_PRECO })}</span>` : ''}
          <ul class="ps-vip-lista">
            <li>✨ ${t('passe.vipFragmento')}</li>
            <li>👑 ${t('passe.vipDiasVip', { d: somaVip.vipDias })}</li>
            <li>⚡ ${t('passe.vipBoosts', { h: horasBoostVip })}</li>
            <li>🪙 ${t('passe.vipCoins', { v: numCurto(somaVip.coins) })}</li>
            <li>🔴 ${t('passe.vipBeast', { n: num(somaVip.bolas[5] ?? 0) })} · 🎟 ${t('passe.vipTokens', { n: num(somaVip.itens[70000] ?? 0) })}</li>
          </ul>
          <span class="ps-vip-alcance">${t('passe.vipDesdeHoje', { de: st.degrau, ate: alcanceSeComprar, d: PASSE_VIP_DIAS })}</span>
        </div>
        <button type="button" class="ps-vip-bt" id="ps-comprar-vip"${nivelOk ? '' : ' disabled'}>
          ${saldo >= PASSE_VIP_PRECO ? t('passe.comprar', { n: PASSE_VIP_PRECO }) : t('passe.comprarDiamantes')} ${seloDiamante(18)}
        </button>
      </div>`;

  const rolagemAntes = host.querySelector('.ps-trilha')?.scrollLeft ?? null;
  host.innerHTML = `
    <div class="ps-topo">
      <div class="ps-heroi ${d.tier}${st.jaPegouHoje && !st.vipPendenteHoje ? ' pego' : ''}">
        <div class="ps-heroi-cab">
          <span class="ps-heroi-dia">${t('passe.diaDe', { n: st.degrau, total: PASSE_DIAS })}</span>
          ${d.bau ? `<span class="ps-selo-bau">🎁 ${t(st.degrau === PASSE_DIAS ? 'passe.lendario' : 'passe.bau')}</span>` : ''}
          ${temSequencia ? `<span class="ps-fogo">🔥 ${t('passe.sequencia', { n: st.jaPegouHoje ? st.degrau : st.degrau - 1 })}</span>` : ''}
        </div>
        ${st.quebrou ? `<p class="ps-quebrou">${t('passe.quebrou')}</p>` : ''}
        <div class="ps-hoje">
          ${htmlPremiosDoDia(d, 'free', false)}
          ${htmlPremiosDoDia(d, 'vip', !vipAtivo)}
        </div>
        ${botao}
        ${temSequencia && nivelOk
          ? `<p class="ps-zera">⏱ ${t('passe.zeraEm')} <b data-ps-relogio="${zeraEm}">${relogioPasse(zeraEm)}</b></p>`
          : `<p class="ps-zera">${t('passe.viraMeiaNoite')}</p>`}
      </div>
      ${painelVip}
    </div>
    <div class="ps-barra" aria-hidden="true">
      <i style="width:${(((st.jaPegouHoje ? st.degrau : st.degrau - 1) / PASSE_DIAS) * 100).toFixed(1)}%"></i>
      ${[7, 14, 21, 28, 30].map((n) => `<span class="ps-marco${n <= (st.jaPegouHoje ? st.degrau : st.degrau - 1) ? ' ok' : ''}" style="left:${((n / PASSE_DIAS) * 100).toFixed(1)}%">${n === 30 ? '🏆' : '🎁'}</span>`).join('')}
    </div>
    <div class="ps-trilha-cab">
      <span><img src="${ICONE_PASSE_FREE}" alt="">${t('passe.trilhaFree')}</span>
      <span><img src="${ICONE_PASSE_VIP}" alt="">${t('passe.trilhaVip')}</span>
    </div>
    <div class="ps-trilha" id="ps-trilha">${htmlTrilhaPasse(st, vipAtivo)}</div>
    <p class="ps-regras">${t('passe.regras', { n: PASSE_NIVEL_MIN })}</p>
    <div class="ps-abrir hidden" id="ps-abrir"></div>`;

  pintarIconesPasse(host);
  const trilha = host.querySelector('#ps-trilha');
  if (rolarParaHoje || rolagemAntes == null) {
    const atual = trilha.querySelector('.ps-col.atual');
    if (atual) trilha.scrollLeft = Math.max(0, atual.offsetLeft - trilha.clientWidth / 2 + atual.clientWidth / 2);
  } else {
    trilha.scrollLeft = rolagemAntes;
  }

  host.querySelector('#ps-resgatar')?.addEventListener('click', () => {
    if (passeResgatando) return;
    passeResgatando = true;
    enviar({ t: 'passe.resgatar' });
    pintarPasse();
    setTimeout(() => {
      if (!passeResgatando) return;
      passeResgatando = false;
      pintarPasse();
    }, 8000);
  });
  host.querySelector('#ps-comprar-vip')?.addEventListener('click', () => {
    if ((estado.eu?.diamonds ?? 0) < PASSE_VIP_PRECO) {
      return abrirCompraDeDiamantes(PASSE_VIP_PRECO - (estado.eu?.diamonds ?? 0));
    }
    confirmarPasseVip(vipAtivo);
  });
  // A roda do mouse sobre a trilha anda para os lados — ela é uma fita horizontal.
  trilha.addEventListener('wheel', (ev) => {
    if (Math.abs(ev.deltaY) <= Math.abs(ev.deltaX)) return;
    ev.preventDefault();
    trilha.scrollLeft += ev.deltaY;
  }, { passive: false });
}

/** A resposta do servidor: a animação de abertura, ou a confirmação do VIP. */
function aoReceberPasse(m) {
  if (m.resgate) {
    passeResgatando = false;
    const r = m.resgate;
    const d = degrauDaTrilha(r.degrau);
    const grande = !!d.bau || r.premios.some((x) => x.trilha === 'vip');
    if (grande) tocarShinyCaptura(); else tocarCaptura();
    pintarSeloPasse();
    if (estado.modalAberto !== 'passe') abrirModal('passe');
    else pintarPasse();
    mostrarAberturaPasse(r);
  }
  if (m.vipComprado) {
    toast(t('passe.vipComprado', { t: restantePasseVip(m.vipComprado.vipAte) }));
    tocarShinyCaptura();
    pintarSeloPasse();
    if (estado.modalAberto === 'passe') pintarPasse();
  }
}

/** A comemoração: os prêmios entrando um a um, com a moldura da raridade do dia. */
function mostrarAberturaPasse(r) {
  const host = $('#ps-abrir');
  if (!host) return;
  const d = degrauDaTrilha(r.degrau);
  const tituloChave = r.degrau === PASSE_DIAS ? 'passe.abrirLendario' : d.bau ? 'passe.abrirBau' : 'passe.abrirDia';
  host.innerHTML = `
    <div class="ps-abrir-caixa ${d.tier}">
      <span class="ps-raios" aria-hidden="true"></span>
      <b class="ps-abrir-tit">${t(tituloChave, { n: r.degrau })}</b>
      ${r.fechouCiclo ? `<span class="ps-abrir-sub">${t('passe.fechouCiclo')}</span>` : ''}
      <div class="ps-abrir-lista">
        ${r.premios.map((pr, i) => `<div class="ps-abrir-pr ${pr.trilha}" style="animation-delay:${(i * 0.14).toFixed(2)}s">
            <span class="ps-abrir-ico" data-i="${i}"></span>
            <b>${escapar(nomePremioPasse(pr))}</b>
            ${pr.trilha === 'vip' ? '<i class="ps-abrir-vip">VIP</i>' : ''}
          </div>`).join('')}
      </div>
      <button type="button" class="ps-abrir-ok" id="ps-abrir-ok">${t('passe.abrirOk')}</button>
    </div>`;
  host.querySelectorAll('.ps-abrir-ico').forEach((el) => {
    const pr = r.premios[Number(el.dataset.i)];
    if (pr) el.appendChild(iconePremioPasse(pr, 40));
  });
  host.classList.remove('hidden');
  host.querySelector('#ps-abrir-ok').onclick = () => host.classList.add('hidden');
  host.onclick = (ev) => { if (ev.target === host) host.classList.add('hidden'); };
}

// Os relógios da tela (volte em, zera em): um tique por segundo, só com o Passe aberto. Na virada
// do dia a tela inteira é repintada — o botão de resgatar acende de novo.
let passeDiaPintado = null;
setInterval(() => {
  if (estado.modalAberto !== 'passe') return;
  const hoje = diaDoPasse(agoraDoServidor());
  if (passeDiaPintado != null && hoje !== passeDiaPintado) {
    passeDiaPintado = hoje;
    return pintarPasse();
  }
  passeDiaPintado = hoje;
  for (const el of document.querySelectorAll('#ps-corpo [data-ps-relogio]')) {
    el.textContent = relogioPasse(Number(el.dataset.psRelogio) || 0);
  }
}, 1000);

// ------------------------------------------------------------------ modais

const emBreve = (nome, desc) =>
  `<div class="aviso-modal"><b>${nome}</b><br><br>${desc}<br><br>
   Ainda não implementado nesta fatia — a aba já está no lugar e o protocolo comporta.</div>`;

const MODAIS = {
  mapa: { titulo: 'modal.mapa', render: renderMapa },
  pokedex: { titulo: 'modal.pokedex', render: renderPokedex },
  // O registro de shinys do SERVIDOR — não é a dex do jogador, é a de todo mundo. Quadrado
  // porque é uma grade de cards, o mesmo motivo do Mercado da Comunidade.
  shinys: { titulo: 'modal.shinys', render: renderShinys, quadrado: true },
  p5s: { titulo: 'modal.p5s', render: renderP5s, quadrado: true },
  // Quadrado: o manual é duas colunas (menu e texto) e precisa de altura, não de largura.
  pokepedia: { titulo: 'modal.pokepedia', render: renderPokepedia, quadrado: true },
  market: { titulo: 'modal.market', render: renderMarket },
  bolsa: { titulo: 'modal.bolsa', render: renderBolsa, quadrado: true },
  // Altura fixa: a Loja virou duas colunas (seções + vitrine) e cada uma rola por dentro.
  shop: { titulo: 'modal.shop', render: renderLoja, quadrado: true },
  // Quadrado: cabeçalho, abas e um painel que rola por dentro — a grade de inscritos e a
  // chave precisam de ALTURA, e a caixa não pode pular de tamanho na troca de aba.
  campeonato: { titulo: 'modal.campeonato', render: renderCampeonato, quadrado: true },
  ranking: { titulo: 'modal.ranking', render: renderRanking },
  bosses: { titulo: 'modal.bosses', render: renderBosses },
  pvp: { titulo: 'modal.pvp', render: renderPvp },
  // Quadrado: a grade dos 18 ginásios só fecha em três ou quatro colunas, e o pódio de um
  // ginásio aberto é uma lista que precisa de altura — o mesmo motivo da Bolsa e do Mercado.
  ginasios: { titulo: 'modal.ginasios', render: renderGinasios, quadrado: true },
  deposito: { titulo: 'modal.deposito', render: renderDeposito },
  withdraw: { titulo: 'modal.withdraw', render: renderWithdraw },
  diamantes: { titulo: 'modal.diamantes', render: renderCompraDiamantes },
  community: { titulo: 'modal.community', render: renderComunidade, quadrado: true },
  // Quadrado: são duas listas empilhadas (as casas que ele tem e os postos de XP Share), e
  // o que falta é altura para as duas caberem sem rolagem — largura não resolve.
  casa: { titulo: 'modal.casa', render: renderCasa, quadrado: true },
  afiliados: { titulo: 'modal.afiliados', render: renderAfiliados },
  votar: { titulo: 'modal.votar', render: renderVotar },
  twitch: { titulo: 'modal.twitch', render: renderTwitch },
  kick: { titulo: 'modal.kick', render: renderKick },
  calculadora: { titulo: 'modal.calculadora', render: renderCalculadora },
  configuracoes: { titulo: 'modal.configuracoes', render: renderConfiguracoes },
  perfil: { titulo: 'modal.perfil', render: renderPerfilProprio },
  // Quadrado: é uma grade de bonecos, o mesmo motivo do Mercado e da Bolsa — numa caixa larga
  // e baixa a coleção vira uma tira de duas fileiras que rola sem fim.
  armario: { titulo: 'modal.armario', render: renderArmario, quadrado: true },
  // Quadrado: são dois painéis lado a lado (lista de amigos + conversa), e o que falta é
  // altura para a thread respirar — largura não resolve. No celular vira uma coluna só.
  amigos: { titulo: 'modal.amigos', render: renderAmigos, quadrado: true },
  // Quadrado: o herói do dia, o painel VIP e a trilha de 30 dias precisam de altura.
  passe: { titulo: 'modal.passe', render: renderPasse, quadrado: true },
};

// ------------------------------------------------------------------- CASA
//
// O botão "Casa" abre as casas do jogador — todas, cada uma com o NÚMERO dela no servidor, os
// postos de XP Share e a porta de entrada — e o registro do servidor, as casas abertas mais
// recentes. Escalar um pokémon dá para fazer daqui, sem entrar: com várias casas valendo ao
// mesmo tempo, obrigar a visitar cada sala para mexer num posto seria uma viagem por casa.

const raridadesCasa = () => estado.casas?.raridades ?? [];
const metaRaridade = (id) => raridadesCasa().find((r) => r.id === id) ?? null;

/** O nome traduzido de uma raridade (`casa.rar.comum`, `casa.rar.lendaria`, …). */
const nomeRaridade = (id) => t(`casa.rar.${id}`);

/**
 * O que a casa DÁ, em uma linha: "1 pokémon · 75% do XP da hunt".
 *
 * Os dois números juntos porque separados mentem. Quatro das cinco casas têm um posto só, e
 * uma tabela que mostrasse apenas isso faria a Comum e a Mítica parecerem a mesma coisa — o
 * que muda entre elas é a fatia de XP Share. `r` é a linha que o welcome manda em
 * `casas.raridades` (ver `shared/casas.mjs`).
 */
const resumoDaCasa = (r) =>
  t('casa.bonecosXp', { n: r.bonecos, pct: Math.round((r.xpShare ?? 0) * 100) });

/** Nome completo da casa na bolsa/mercado — "Casa Comum", não só "Comum". */
const nomeCasaRaridade = (rarId) => nomeItem(CASA_ITEM_POR_RAR[rarId] ?? 0, nomeRaridade(rarId));

/** As casas do jogador como o snapshot manda — a mais rara primeiro —, ou `[]`. */
const minhasCasas = () => estado.eu?.casa?.lista ?? [];

/** Uma casa do jogador pelo número. */
const minhaCasaPorId = (id) => minhasCasas().find((c) => c.id === Number(id)) ?? null;
/** O teto de casas em uso, do servidor (snapshot, e o welcome como reserva). */
const maxCasasEmUso = () => estado.eu?.casa?.maxEmUso ?? estado.casas?.maxEmUso ?? 5;
/** As casas que repartem XP agora. Servidor que não manda o campo: todas as da mão. */
const casasEmUsoNaTela = () => minhasCasas().filter((c) => !c.anunciada && c.emUso !== false);

/** A arte grande de uma raridade — a mesma da tela de "você recebeu". */
const arteDaCasa = (rar) => `/img/itens/casa-${RC_NIVEIS.includes(rar) ? rar : 'comum'}.png`;
const arteDaBicicleta = (rar) => `/img/itens/bicicleta-${RC_NIVEIS.includes(rar) ? rar : 'comum'}.png`;

/**
 * O estado da tela: a aba aberta, o registro recebido, o filtro e a ASSINATURA do que o painel
 * desenhou por último.
 *
 * A assinatura existe por causa das Míticas e Lendárias. O snapshot chega duas vezes por segundo e
 * `montarCasa` roda em todos; repintar sempre reiniciaria o anel girando, o brilho e as faíscas a
 * cada meio segundo — a dopamina viraria tremedeira. O painel só repinta quando muda algo que ele
 * MOSTRA.
 */
const casaTela = {
  aba: 'minhas', assinatura: '', registro: null, filtro: null, pagina: 0, painelDe: null, topo: false,
  // O Registro de Bikes, na aba ao lado: os mesmos três campos do registro de casas.
  registroBikes: null, filtroBikes: null, paginaBikes: 0,
};

function renderCasa() {
  return `<div class="casa-modal" id="casa-corpo"></div>`;
}

/**
 * O modal acabou de abrir: pinta do zero, pede ao servidor que releia as casas (uma vendida no
 * Mercado muda de dono noutro jogador) e pede o registro — é ele que traz o contador do servidor.
 */
function aoAbrirCasa() {
  casaTela.assinatura = '';
  montarCasa();
  enviar({ t: 'casa.sincronizar' });
  pedirRegistroCasas();
}

/** Monta a moldura uma vez (topo, abas, painel) e deixa o painel da aba se repintar sozinho. */
function montarCasa() {
  const host = $('#casa-corpo');
  if (!host) return;
  if (!host.dataset.pronto) {
    host.dataset.pronto = '1';
    host.innerHTML = `
      <header class="csm-topo">
        <p class="csm-topo-sub" id="csm-topo-sub"></p>
        <div class="csm-contador" id="csm-contador-caixa" title="${escapar(t('casa.contadorDica'))}">
          <b class="csm-contador-num" id="csm-contador">—</b>
          <span class="csm-contador-rot" id="csm-contador-rot">${escapar(t('casa.contadorServidor'))}</span>
        </div>
      </header>
      <nav class="csm-abas" role="tablist">
        <button type="button" class="csm-aba" data-aba="minhas" role="tab">${escapar(t('casa.abaMinhas'))}</button>
        <button type="button" class="csm-aba" data-aba="registro" role="tab">${escapar(t('casa.abaRegistro'))}</button>
        <button type="button" class="csm-aba" data-aba="bikes" role="tab">${escapar(t('casa.abaRegistroBikes'))}</button>
      </nav>
      <div class="csm-painel" id="csm-painel"></div>`;
    host.onclick = cliqueNaCasa;
    casaTela.assinatura = '';
  }
  for (const b of host.querySelectorAll('.csm-aba')) {
    const on = b.dataset.aba === casaTela.aba;
    b.classList.toggle('on', on);
    b.setAttribute('aria-selected', on ? 'true' : 'false');
  }
  pintarTopoCasa();
  if (casaTela.aba === 'registro') pintarRegistroCasas();
  else if (casaTela.aba === 'bikes') pintarRegistroBikes();
  else pintarMinhasCasas();
}

/** O subtítulo ("3 casas · 4 pokémon no XP Share") e o contador do servidor. */
function pintarTopoCasa() {
  const lista = minhasCasas();
  const recebendo = lista.reduce((s, c) => s + (c.postos ?? []).filter((id) => id != null).length, 0);
  const sub = $('#csm-topo-sub');
  if (sub) {
    sub.textContent = !lista.length
      ? t('casa.nenhumaAinda')
      : t(lista.length === 1 ? 'casa.resumoTopoUma' : 'casa.resumoTopo', {
        n: num(lista.length), p: num(recebendo), u: num(casasEmUsoNaTela().length), max: num(maxCasasEmUso()),
      });
  }
  // O número é FIXO, escrito como chega — sem animação. Ele só muda quando o registro volta do
  // servidor (abrir o modal, uma casa nova), e fica guardado entre uma abertura e outra para o
  // modal já nascer com ele em vez de piscar um "—".
  // Na aba de bikes o contador é o das bikes: o número do topo é sempre o do registro à vista.
  const bikes = casaTela.aba === 'bikes';
  const total = (bikes ? casaTela.registroBikes : casaTela.registro)?.contagem?.total;
  const el = $('#csm-contador');
  if (el && total != null) el.textContent = num(total);
  const rot = $('#csm-contador-rot');
  if (rot) rot.textContent = t(bikes ? 'bicicleta.contadorServidor' : 'casa.contadorServidor');
  const caixaContador = $('#csm-contador-caixa');
  if (caixaContador) caixaContador.title = t(bikes ? 'bicicleta.contadorDica' : 'casa.contadorDica');
}

/**
 * Troca o conteúdo do painel sem jogar o jogador de volta ao topo.
 *
 * O painel repinta quando algo que ele mostra muda — um pokémon escalado, um nível que subiu, uma
 * página do registro que chegou —, e quem estava lá embaixo lendo a lista tem de continuar lá.
 * Só vai ao topo quando é OUTRA lista: troca de aba, de filtro ou de página (`casaTela.topo`).
 */
function repintarPainelCasa(painel, aba, html) {
  const manter = casaTela.painelDe === aba && !casaTela.topo;
  const rolagem = painel.scrollTop;
  painel.innerHTML = html;
  painel.scrollTop = manter ? rolagem : 0;
  casaTela.painelDe = aba;
  casaTela.topo = false;
}

/** A aba "Minhas casas": um card por casa, com os postos e a porta. */
function pintarMinhasCasas() {
  const painel = $('#csm-painel');
  if (!painel) return;
  const e = estado.eu;
  const lista = e?.casa?.lista ?? null;
  const frag = estado.casas?.fragmento ?? {};
  const nFrag = Number(e?.items?.[frag.itemId] ?? 0);
  const pks = new Map((e?.pokemons ?? []).map((pk) => [pk.id, pk]));

  // Só o que o painel desenha: as casas e os postos, quem está em cada posto (nome, nível, shiny,
  // se é o de batalha), a casa em que ele está e se está no Centro. O XP que sobe a cada abate
  // fica de fora — ele não aparece aqui, e entrar na assinatura repintaria a tela a cada golpe.
  const assinatura = JSON.stringify([
    'minhas', lista, e?.casa?.dentro ?? null, !!e?.noCentro, e?.activeId ?? null, nFrag,
    document.documentElement.lang,
    (lista ?? []).flatMap((c) => (c.postos ?? []).map((id) => {
      const pk = id != null ? pks.get(id) : null;
      return pk ? [pk.id, pk.level, !!pk.shiny, pk.nome] : null;
    })),
  ]);
  if (assinatura === casaTela.assinatura) return;
  casaTela.assinatura = assinatura;

  if (lista == null) {
    repintarPainelCasa(painel, 'minhas', `<div class="cm-vazio">${t('cm.carregando')}</div>`);
    return;
  }
  if (!lista.length) {
    repintarPainelCasa(painel, 'minhas', htmlSemCasa(nFrag, frag));
    ligarArtesDaCasa(painel, pks);
    return;
  }
  // Duas prateleiras: as EM USO (as que repartem XP, até o teto) e o resto — guardadas e no
  // Mercado. A de cima é a que o jogador escala; a de baixo é o estoque de onde ele troca.
  const emUso = lista.filter((c) => !c.anunciada && c.emUso !== false);
  const resto = lista.filter((c) => c.anunciada || c.emUso === false);
  const max = maxCasasEmUso();
  const cheia = emUso.length >= max;
  repintarPainelCasa(painel, 'minhas', `
    <p class="csm-regra">${escapar(t('casa.todasValem', { max: num(max) }))}</p>
    <h4 class="csm-grupo">${escapar(t('casa.grupoEmUso', { u: num(emUso.length), max: num(max) }))}</h4>
    ${emUso.length
      ? `<div class="csm-grade">${emUso.map((c) => htmlCardCasa(c, pks, e, cheia)).join('')}</div>`
      : `<p class="csm-grupo-vazio">${escapar(t('casa.nenhumaEmUso'))}</p>`}
    ${resto.length
      ? `<h4 class="csm-grupo">${escapar(t('casa.grupoGuardadas', { n: num(resto.length) }))}</h4>
         <div class="csm-grade">${resto.map((c) => htmlCardCasa(c, pks, e, cheia)).join('')}</div>`
      : ''}`);
  ligarArtesDaCasa(painel, pks);
}

/**
 * As faíscas das casas raras, com posição e tempo sorteados a cada pintura — quem anima é o CSS.
 * A quantidade é a escada da tela de recompensa: nada até a Rara, poucas na Mítica, muitas na
 * Lendária. Se a Comum brilhasse, a Lendária não teria para onde subir.
 */
function faiscasDaCasa(n) {
  const s = (a, b) => (a + Math.random() * (b - a)).toFixed(2);
  let html = '';
  for (let i = 0; i < n; i++) {
    html += `<i class="csm-faisca" style="--x:${s(6, 92)}%;--y:${s(4, 62)}%;--t:${s(6, 13)}px;--d:${s(1.4, 2.8)}s;--a:${s(0, 2.6)}s"></i>`;
  }
  return html;
}

function htmlCardCasa(c, pks, e, cheia = false) {
  const meta = metaRaridade(c.rar);
  const dentro = e?.casa?.dentro === c.id;
  const guardada = !c.anunciada && c.emUso === false;
  const faiscas = c.anunciada || guardada ? 0 : c.rar === 'lendaria' ? 14 : c.rar === 'mitica' ? 7 : 0;
  const classes = ['csm-card', `rar-${c.rar}`, dentro ? 'dentro' : '', c.anunciada ? 'anunciada' : '', guardada ? 'guardada' : '']
    .filter(Boolean).join(' ');
  const postos = c.anunciada
    ? `<p class="csm-mercado-txt">${escapar(t('casa.noMercadoDica'))}</p>`
    : guardada
      ? `<p class="csm-mercado-txt">${escapar(t('casa.guardadaDica'))}</p>`
      : `<div class="csm-postos">${(c.postos ?? [])
        .map((id, slot) => htmlPostoDaCasa(c, slot, id != null ? pks.get(id) : null, e)).join('')}</div>`;
  // O pé: no Mercado, o selo; guardada, "Pôr em uso" (travado com as vagas cheias); em uso, a porta
  // e o "Guardar" — que some na casa em que ele está, porque dela é preciso sair antes.
  const limite = escapar(t('casa.limiteEmUso', { n: num(maxCasasEmUso()) }));
  const pe = c.anunciada
    ? `<span class="csm-selo csm-selo-mercado">${escapar(t('casa.noMercado'))}</span>`
    : guardada
      ? `<button type="button" class="casa-entrar csm-usar" data-usar="${c.id}"${cheia ? ` disabled title="${limite}"` : ''}>${escapar(t('casa.porEmUso'))}</button>`
      : dentro
        ? `<span class="csm-selo csm-selo-dentro">${escapar(t('casa.dentro'))}</span>`
        : `<button type="button" class="casa-entrar" data-entrar="${c.id}">${escapar(t('casa.entrar'))}</button>
           <button type="button" class="csm-guardar" data-guardar="${c.id}" title="${escapar(t('casa.guardarDica'))}">${escapar(t('casa.guardar'))}</button>`;
  return `
    <article class="${classes}" data-casa="${c.id}">
      ${faiscas ? `<div class="csm-fx" aria-hidden="true">${faiscasDaCasa(faiscas)}</div>` : ''}
      <div class="csm-miolo">
        <div class="csm-card-topo">
          <span class="csm-rar">${escapar(nomeRaridade(c.rar))}</span>
          <span class="csm-num">${escapar(numeroDaCasa(c.id))}</span>
        </div>
        <div class="csm-arte"><img src="${arteDaCasa(c.rar)}" alt="" draggable="false"></div>
        <div class="csm-nome">${escapar(nomeCasaRaridade(c.rar))}</div>
        <div class="csm-resumo">${meta ? escapar(resumoDaCasa(meta)) : ''}</div>
        ${postos}
        <div class="csm-pe">${pe}</div>
      </div>
    </article>`;
}

/** Um posto: livre ("+ Escolher pokémon") ou ocupado (sprite, nome, nível, trocar e tirar). */
function htmlPostoDaCasa(c, slot, pk, e) {
  if (!pk) {
    return `
      <button type="button" class="csm-posto livre" data-escolher="${c.id}" data-slot="${slot}">
        <span class="csm-posto-mais" aria-hidden="true">+</span>
        <span class="csm-posto-livre-txt">${escapar(t('casa.escolher'))}</span>
      </button>`;
  }
  const ativo = e?.activeId === pk.id;
  const nome = `${pk.shiny ? '★ ' : ''}${pk.nome}`;
  return `
    <div class="csm-posto ocupado${ativo ? ' ativo' : ''}">
      <button type="button" class="csm-posto-troca" data-escolher="${c.id}" data-slot="${slot}"
              title="${escapar(t('casa.trocarPokemon'))}">
        <span class="csm-posto-sprite" data-pk-sprite="${pk.id}"></span>
        <span class="csm-posto-txt">
          <b>${escapar(nome)}</b>
          <em>${escapar(ativo ? t('casa.ehOAtivo') : `${t('cm.nivel')} ${num(pk.level)}`)}</em>
        </span>
      </button>
      <button type="button" class="csm-posto-tirar" data-tirar="${c.id}" data-slot="${slot}"
              title="${escapar(t('casa.tirar'))}" aria-label="${escapar(t('casa.tirar'))}">×</button>
    </div>`;
}

/** Quem ainda não tem casa: a arte apagada, o caminho e quanto falta de fragmento. */
function htmlSemCasa(nFrag, frag) {
  const custo = frag.custo ?? 10;
  const pct = Math.min(100, Math.round((nFrag / custo) * 100));
  const chance = ((frag.chanceDrop ?? 0) * 100).toFixed(3).replace(/0+$/, '').replace(/\.$/, '');
  return `
    <div class="csm-vazio">
      <img class="csm-vazio-arte" src="${arteDaCasa('comum')}" alt="" draggable="false">
      <p class="csm-vazio-tit">${escapar(t('casa.nenhumaAinda'))}</p>
      <p class="csm-vazio-txt">${escapar(t('casa.nenhuma', { n: custo, tem: nFrag }))}</p>
      <div class="csm-frag">
        <span class="csm-frag-ico" data-frag-ico></span>
        <span class="csm-frag-barra"><i style="width:${pct}%"></i></span>
        <b>${num(Math.min(nFrag, custo))}/${num(custo)}</b>
      </div>
      <p class="txt-sec">${escapar(t('casa.fragComo', { chance }))}</p>
      <p class="txt-sec">${escapar(t('casa.fabricarOnde', { n: custo }))}</p>
    </div>`;
}

/** Os sprites e ícones que não cabem em template de texto. */
function ligarArtesDaCasa(painel, pks) {
  for (const el of painel.querySelectorAll('[data-pk-sprite]')) {
    const pk = pks.get(Number(el.dataset.pkSprite));
    if (pk) el.appendChild(spritePokemon(pk, 40));
  }
  const frag = painel.querySelector('[data-frag-ico]');
  if (frag) frag.appendChild(imgItem(estado.casas?.fragmento?.itemId ?? FRAGMENTO_CHAVE_ID, 26));
}

/**
 * Guardar uma casa que tem gente nos postos: a casa à esquerda, e os pokémon que saem do XP Share
 * do outro lado da seta, sem cor. A casa continua sua — quem perde alguma coisa são eles.
 */
function confirmarGuardarCasa(casa, pedir) {
  const pks = new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  const ocupantes = (casa.postos ?? []).filter((id) => id != null).map((id) => pks.get(id)).filter(Boolean);
  const n = (casa.postos ?? []).filter((id) => id != null).length;
  confirmar({
    titulo: t('casa.guardarTitulo', { numero: numeroDaCasa(casa.id) }),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({
          arte: dlgArteItem(CASA_ITEM_POR_RAR[casa.rar] ?? 0, 64),
          nome: escapar(`${nomeCasaRaridade(casa.rar)} ${numeroDaCasa(casa.id)}`),
        })}
        ${dlgSeta()}
        ${dlgAtor({ arte: dlgFila(ocupantes), nome: 'XP Share', classe: 'sai', qtd: ocupantes.length ? '' : `×${num(n)}` })}`, 'ouro')}
      ${dlgFrase('', escapar(t(n === 1 ? 'casa.guardarAvisoUm' : 'casa.guardarAviso', { n: num(n) })))}`,
    aoConfirmar: pedir,
  });
}

function cliqueNaCasa(ev) {
  const aba = ev.target.closest('.csm-aba');
  if (aba) {
    if (aba.dataset.aba === casaTela.aba) return;
    casaTela.aba = aba.dataset.aba;
    casaTela.assinatura = '';
    montarCasa();
    if (casaTela.aba === 'registro') pedirRegistroCasas();
    else if (casaTela.aba === 'bikes') pedirRegistroBikes();
    return;
  }
  const usar = ev.target.closest('[data-usar]');
  if (usar) {
    if (usar.disabled) return;
    return enviar({ t: 'casa.usar', casaId: Number(usar.dataset.usar), usar: true });
  }
  const guardar = ev.target.closest('[data-guardar]');
  if (guardar) {
    const casa = minhaCasaPorId(guardar.dataset.guardar);
    if (!casa) return;
    const ocupados = (casa.postos ?? []).filter((id) => id != null).length;
    const pedir = () => enviar({ t: 'casa.usar', casaId: casa.id, usar: false });
    // Casa vazia guarda direto; com gente nos postos, confirma — eles saem do XP Share.
    if (!ocupados) return pedir();
    return confirmarGuardarCasa(casa, pedir);
  }
  const entrar = ev.target.closest('[data-entrar]');
  if (entrar) {
    // De dentro de outra casa o servidor troca de sala direto; de resto, só a partir do Centro.
    if (!estado.eu?.noCentro && !estado.eu?.casa?.dentro) return toast(t('casa.soDoCentro'));
    enviar({ t: 'casa.entrar', casaId: Number(entrar.dataset.entrar) });
    return fecharModal();
  }
  const tirar = ev.target.closest('[data-tirar]');
  if (tirar) {
    return enviar({ t: 'xpshare.escolher', casaId: Number(tirar.dataset.tirar), slot: Number(tirar.dataset.slot), pokemonId: null });
  }
  const escolher = ev.target.closest('[data-escolher]');
  if (escolher) return abrirEscolhaDeTreino(Number(escolher.dataset.escolher), Number(escolher.dataset.slot));
  const ver = ev.target.closest('[data-ver-anuncio]');
  if (ver) return verAnuncioDaCasa(ver.dataset);
  // Filtro e página valem para o registro À VISTA — o de casas ou o de bikes.
  const bikes = casaTela.aba === 'bikes';
  const filtro = ev.target.closest('[data-filtro-rar]');
  if (filtro) {
    casaTela.topo = true;
    if (bikes) {
      casaTela.filtroBikes = filtro.dataset.filtroRar || null;
      casaTela.paginaBikes = 0;
      return pedirRegistroBikes();
    }
    casaTela.filtro = filtro.dataset.filtroRar || null;
    casaTela.pagina = 0;
    return pedirRegistroCasas();
  }
  const pag = ev.target.closest('[data-reg-pag]');
  if (pag && !pag.disabled) {
    casaTela.topo = true;
    if (bikes) {
      casaTela.paginaBikes = Number(pag.dataset.regPag);
      return pedirRegistroBikes();
    }
    casaTela.pagina = Number(pag.dataset.regPag);
    pedirRegistroCasas();
  }
}

// ---------------------------------------------------- o registro do servidor

function pedirRegistroCasas() {
  enviar({ t: 'casas.listar', raridade: casaTela.filtro, pagina: casaTela.pagina });
}

function pedirRegistroBikes() {
  enviar({ t: 'bicicletas.listar', raridade: casaTela.filtroBikes, pagina: casaTela.paginaBikes });
}

/**
 * O CTA "Ver anúncio" de uma casa à venda no registro: leva direto ao anúncio no Mercado.
 *
 * Anúncio dos outros: o Mercado abre na aba de itens, na casa daquela raridade e na moeda do
 * anúncio, e a folha de COMPRA dele abre sozinha assim que os vendedores chegam (ver
 * `abrirAnuncioPendente`). É o caminho de menos cliques entre "achei a Lendária #000012 à venda"
 * e comprá-la. Os filtros que poderiam esconder a casa do catálogo (busca, elemento) saem.
 *
 * O anúncio do próprio jogador não se compra — abre "Meus anúncios", onde se edita ou cancela.
 */
function verAnuncioDaCasa({ verAnuncio, rar, moeda, minha, peca }) {
  estado.cmPagina = 0;
  if (minha) {
    estado.cmAba = 'meus';
    return abrirModal('community');
  }
  // O mesmo caminho serve à bicicleta do Registro de Bikes: mudam só a aba do Mercado e o item.
  const bike = peca === 'bicicleta';
  const itemId = bike ? BICICLETA_ITEM_POR_RAR[rar] : CASA_ITEM_POR_RAR[rar];
  if (!itemId) return;
  estado.cmAba = 'vitrine';
  estado.cmFiltro.tipo = 'item';
  estado.cmFiltro.categoria = 'casa';
  if (bike) estado.cmFiltro.categoria = 'bicicleta';
  estado.cmFiltro.elemento = '';
  estado.cmFiltro.busca = '';
  // Sai da aba de pokémon: a espécie aberta fecha junto, como em qualquer troca de aba.
  estado.cmEspecieSel = null;
  estado.cmItemSel = itemId;
  estado.cmItemMoeda = moeda === 'orb' ? 'orb' : 'gold';
  estado.cmAbrirAnuncio = { id: Number(verAnuncio), itemId };
  abrirModal('community');
}

/** Os vendedores do item chegaram: se havia um "Ver anúncio" esperando, abre a compra dele. */
function abrirAnuncioPendente(m) {
  const pendente = estado.cmAbrirAnuncio;
  if (!pendente || m.itemId !== pendente.itemId) return;
  estado.cmAbrirAnuncio = null;
  if (estado.modalAberto !== 'community') return;
  const a = (m.linhas ?? []).find((x) => x.id === pendente.id);
  if (!a) return toast(t('casa.anuncioSaiu'));
  abrirCompra(a);
}

function receberRegistroCasas(m) {
  casaTela.registro = m;
  casaTela.pagina = m.pagina ?? casaTela.pagina;
  if (estado.modalAberto !== 'casa') return;
  pintarTopoCasa();
  if (casaTela.aba === 'registro') pintarRegistroCasas();
}

/** O Registro de Bikes chegou — o espelho de `receberRegistroCasas`, na aba ao lado. */
function receberRegistroBikes(m) {
  casaTela.registroBikes = m;
  casaTela.paginaBikes = m.pagina ?? casaTela.paginaBikes;
  if (estado.modalAberto !== 'casa') return;
  pintarTopoCasa();
  if (casaTela.aba === 'bikes') pintarRegistroBikes();
}

/**
 * Os dois REGISTROS do servidor — de casas e de bikes — e o que muda de um para o outro. O resto (os
 * filtros com a contagem de cada raridade, a lista, as páginas, o "Ver anúncio") é o mesmo desenho.
 */
const REGISTROS_DE_PECA = {
  registro: {
    peca: 'casa',
    dados: () => casaTela.registro,
    filtro: () => casaTela.filtro,
    vazio: 'casa.registroVazio',
    arte: (rar) => arteDaCasa(rar),
    nome: (rar) => nomeCasaRaridade(rar),
    numero: (id) => numeroDaCasa(id),
  },
  bikes: {
    peca: 'bicicleta',
    dados: () => casaTela.registroBikes,
    filtro: () => casaTela.filtroBikes,
    vazio: 'bicicleta.registroVazio',
    arte: (rar) => arteDaBicicleta(rar),
    nome: (rar) => nomeBicicletaRaridade(rar),
    numero: (id) => numeroDaBicicleta(id),
  },
};

/**
 * A aba "Registro de Casas": as casas mais novas primeiro, como o registro de shinys da Pokédex. Os
 * filtros trazem a contagem de cada raridade — é o que diz, antes de clicar, que existem só três
 * Lendárias no servidor inteiro.
 */
function pintarRegistroCasas() {
  pintarRegistroDePeca('registro');
}

/** A aba "Registro de Bikes": o mesmo desenho, com as bicicletas numeradas. */
function pintarRegistroBikes() {
  pintarRegistroDePeca('bikes');
}

function pintarRegistroDePeca(aba) {
  const painel = $('#csm-painel');
  if (!painel) return;
  const cfg = REGISTROS_DE_PECA[aba];
  const d = cfg.dados();
  const filtroAtual = cfg.filtro();
  const assinatura = JSON.stringify([aba, d, filtroAtual, document.documentElement.lang]);
  if (assinatura === casaTela.assinatura) return;
  casaTela.assinatura = assinatura;

  const cont = d?.contagem ?? {};
  const chips = [{ id: '', n: cont.total }, ...raridadesCasa().map((r) => ({ id: r.id, n: cont[r.id] }))]
    .map((x) => `
      <button type="button" class="csm-chip${x.id ? ` rar-${x.id}` : ''}${(filtroAtual ?? '') === x.id ? ' on' : ''}"
              data-filtro-rar="${x.id}">${escapar(x.id ? nomeRaridade(x.id) : t('casa.todas'))}${
        x.n == null ? '' : `<em>${num(x.n)}</em>`}</button>`)
    .join('');
  const linhas = !d
    ? `<div class="cm-vazio">${t('cm.carregando')}</div>`
    : !d.linhas.length
      ? `<div class="cm-vazio">${escapar(t(cfg.vazio))}</div>`
      : `<ol class="csm-reg-lista">${d.linhas.map((l) => htmlLinhaDoRegistro(l, cfg)).join('')}</ol>`;
  const paginas = d ? Math.max(1, Math.ceil((d.total ?? 0) / (d.porPagina ?? 30))) : 1;
  const atual = d?.pagina ?? 0;
  repintarPainelCasa(painel, aba, `
    <div class="csm-reg-filtros">${chips}</div>
    ${linhas}
    ${paginas > 1 ? `
      <div class="cm-paginas">
        <button class="cm-pag" type="button" ${atual <= 0 ? 'disabled' : ''} data-reg-pag="${atual - 1}">‹</button>
        <span>${t('cm.paginaDe', { a: atual + 1, b: paginas })}</span>
        <button class="cm-pag" type="button" ${atual + 1 >= paginas ? 'disabled' : ''} data-reg-pag="${atual + 1}">›</button>
      </div>` : ''}`);
}

function htmlLinhaDoRegistro(l, cfg = REGISTROS_DE_PECA.registro) {
  const rar = RC_NIVEIS.includes(l.raridade) ? l.raridade : 'comum';
  // A casa consumida num craft fica no registro, sem dono: no lugar dele, a casa que nasceu dela.
  const dono = l.fundidaNa
    ? t('casa.fundidaNa', { numero: `<b>${escapar(cfg.numero(l.fundidaNa))}</b>` })
    : l.minha
      ? `<b class="csm-reg-sua">${escapar(t('casa.suaNoRegistro'))}</b>`
      : l.dono ? t('casa.deDono', { nick: `<b>${escapar(l.dono)}</b>` }) : '';
  // "Tirada por" só quando não é o dono de hoje: numa casa que nunca mudou de mão a frase repetiria
  // o mesmo nick duas vezes na linha.
  const tirou = l.criador && l.criador !== l.dono
    ? t('casa.tiradaPor', { nick: `<b>${escapar(l.criador)}</b>` })
    : '';
  const meta = [dono, tirou, l.criadaEm ? escapar(quandoFoi(l.criadaEm)) : ''].filter(Boolean).join(' · ');
  return `
    <li class="csm-reg-linha rar-${rar}${l.minha ? ' minha' : ''}">
      <span class="csm-num">${escapar(cfg.numero(l.id))}</span>
      <img class="csm-reg-ico" src="${cfg.arte(rar)}" alt="" loading="lazy" draggable="false">
      <span class="csm-reg-info">
        <b class="csm-reg-nome">${escapar(cfg.nome(rar))}</b>
        <span class="csm-reg-meta">${meta}</span>
      </span>
      ${l.anuncio ? `
        <span class="csm-reg-venda">
          <span class="csm-reg-preco">${escapar(t('casa.aVenda'))} ${precoComMoeda(l.anuncio.preco, l.anuncio.moeda)}</span>
          <button type="button" class="csm-ver-anuncio" data-ver-anuncio="${l.anuncio.id}" data-rar="${rar}" data-peca="${cfg.peca}"
                  data-moeda="${l.anuncio.moeda === 'orb' ? 'orb' : 'gold'}"${l.minha ? ' data-minha="1"' : ''}>
            ${escapar(t(l.minha ? 'casa.verMeuAnuncio' : 'casa.verAnuncio'))}
          </button>
        </span>` : ''}
    </li>`;
}

function xpShareHeldAtivo() {
  return true;
}
function xpShareHeldItemId() {
  return estado.xpShareHeld?.itemId ?? XP_SHARE_HELD_ID;
}
function pokemonTemXpShareHeld(pk) {
  return xpShareHeldAtivo() && ehXpShareHeldItem(pk?.heldItemId);
}

/** Registrado num posto de XP Share de QUALQUER casa — não pode equipar held (e vice-versa). */
function pokemonNoPostoCasaXpShare(pk) {
  if (!pk) return false;
  return postoDoPokemonNaTela(pk.id) != null;
}

/** Onde este pokémon está escalado: `{ casaId, slot }`, ou `null`. `exceto` é o posto sendo trocado. */
function postoDoPokemonNaTela(pkId, exceto = null) {
  for (const c of minhasCasas()) {
    const postos = c.postos ?? [];
    for (let slot = 0; slot < postos.length; slot++) {
      if (postos[slot] !== pkId) continue;
      if (exceto && exceto.casaId === c.id && exceto.slot === slot) continue;
      return { casaId: c.id, slot };
    }
  }
  return null;
}

const seloXpShareHeld = () =>
  `<span class="pk-selo xsh-selo" title="${escapar(t('xpshareheld.selo'))}">${t('xpshareheld.seloCurto')}</span>`;

/** Exp. Share (held): equipar ou remover em pokémon da equipe e do depot. */
function abrirXpShareHeld() {
  if (!xpShareHeldAtivo()) return;
  const itemId = xpShareHeldItemId();
  const pct = estado.xpShareHeld?.pct ?? 5;
  const { corpo, fechar } = folhaMercado(t('xpshareheld.titulo'));
  pintarXpShareHeld(corpo, fechar, itemId, pct);
}

function pintarXpShareHeld(corpo, fechar, itemId, pct) {
  const naBolsa = estado.eu?.items?.[itemId] ?? 0;
  const equipados = (estado.eu?.pokemons ?? []).filter(pokemonTemXpShareHeld).length;
  const todos = [...(estado.eu?.pokemons ?? [])].sort((a, b) => {
    const oa = a.slot == null ? 100 : a.slot;
    const ob = b.slot == null ? 100 : b.slot;
    return oa - ob || a.nome.localeCompare(b.nome, undefined, { sensitivity: 'base' });
  });
  const equipe = todos.filter((p) => p.slot != null && (pokemonTemXpShareHeld(p) || !pokemonNoPostoCasaXpShare(p)));
  const guardados = todos.filter((p) => p.slot == null && (pokemonTemXpShareHeld(p) || !pokemonNoPostoCasaXpShare(p)));
  // Os guardados em duas seções, como no Depot: a Coleção à parte.
  //
  // Quem decide de que lado cada um cai é `localDoPokemon`, o MESMO do filtro "Local" das
  // folhas de escolha — e não um `colecao.has(p.id)` escrito aqui. A regra duplicada tinha uma
  // diferença de uma palavra: lá o id passa por `Number()` antes de bater no `Set` (que é de
  // números), aqui não. Enquanto o id chegar como número as duas concordam; no dia em que ele
  // vier como texto — e `player_pokemon.id` é BIGINT, que o driver do Postgres já devolve como
  // string em outras consultas — esta aqui jogaria a Coleção inteira para dentro do Depot, e a
  // outra não. Com uma função só, não há dia em que elas discordem.
  const colecao = conjuntoColecaoCliente();
  const depot = guardados.filter((p) => localDoPokemon(p, colecao) === 'depot');
  const naColecao = guardados.filter((p) => localDoPokemon(p, colecao) === 'colecao');
  const ocultosCasa = todos.filter((p) => !pokemonTemXpShareHeld(p) && pokemonNoPostoCasaXpShare(p)).length;

  corpo.innerHTML = `
    <div class="xsh-topo">
      <div class="xsh-ico" id="xsh-ico"></div>
      <div class="xsh-resumo">
        <p class="xsh-bolsa">${t('xpshareheld.naBolsa', { n: num(naBolsa) })}</p>
        ${equipados > 0 ? `<p class="xsh-equipados">${escapar(t('xpshareheld.equipados', { n: equipados }))}</p>` : ''}
        <p class="xsh-intro">${escapar(t('xpshareheld.intro', { pct }))}</p>
      </div>
    </div>
    <p class="xsh-trava cm-nota">${escapar(t('xpshareheld.travaVendaCurta'))}</p>
    ${ocultosCasa ? `<p class="cm-nota dim">${escapar(t('xpshareheld.ocultosCasa', { n: ocultosCasa }))}</p>` : ''}
    <div id="xsh-secoes"></div>`;
  corpo.querySelector('#xsh-ico')?.appendChild(imgItem(itemId, 44));

  const host = corpo.querySelector('#xsh-secoes');
  if (!todos.length) {
    host.innerHTML = `<div class="aviso-modal">${t('xpshareheld.semPokemon')}</div>`;
    return;
  }
  const montarSecao = (titulo, lista) => {
    if (!lista.length) return;
    const sec = document.createElement('section');
    sec.className = 'xsh-secao';
    sec.innerHTML = `<h4 class="xsh-secao-titulo">${escapar(titulo)}</h4><div class="mk-grade xsh-grade"></div>`;
    const grade = sec.querySelector('.xsh-grade');
    for (const p of lista) {
      grade.appendChild(cardXpShareHeld(p, naBolsa, pct, () => pintarXpShareHeld(corpo, fechar, itemId, pct)));
    }
    host.appendChild(sec);
  };
  montarSecao(t('painel.equipe'), equipe);
  montarSecao(t('painel.depot'), depot);
  montarSecao(t('colecao.titulo'), naColecao);
  if (!equipe.length && !depot.length && !naColecao.length) {
    host.innerHTML = `<div class="aviso-modal">${t('xpshareheld.semPokemonElegivel')}</div>`;
  }
}

function cardXpShareHeld(p, naBolsa, pct, repintar) {
  const equipado = pokemonTemXpShareHeld(p);
  const ehAtivo = estado.eu?.activeId === p.id;
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = `mk-acao${equipado ? ' apagado' : ''}`;
  if (equipado) {
    bt.textContent = t('xpshareheld.remover');
    bt.onclick = () => enviar({ t: 'xpshareheld.remover', pokemonId: p.id });
  } else {
    bt.textContent = t('xpshareheld.equipar');
    bt.disabled = naBolsa < 1;
    if (naBolsa < 1) bt.title = t('xpshareheld.semNaBolsa');
    bt.onclick = () => enviar({ t: 'xpshareheld.equipar', pokemonId: p.id });
  }

  const card = cardMarket({
    chave: `xsh${p.id}`,
    nome: `${p.shiny ? prefixoShiny() : ''}${nomePkHtml(p)}`,
    sub: t('mk.subPokemonCurta', {
      level: p.level,
      onde: t(LOCAL_I18N[localDoPokemon(p)]),
    }),
    atributos: selosAtributos(p),
    preco: 0,
    rotulo: equipado
      ? t('xpshareheld.equipadoTag', { pct })
      : ehAtivo
        ? t('casa.ehOAtivo')
        : t('xpshareheld.disponivelTag', { pct }),
    acao: [bt],
    aoVerFicha: () => abrirFichaDoPokemon(p),
    classe: equipado ? 'xsh-card-on' : ehAtivo ? 'mk-card-alerta' : '',
  });
  const topo = card.querySelector('.mk-card-topo');
  topo.querySelector('.mk-ico').appendChild(spritePokemon(p, 44));
  return card;
}

// ------------------------------------------------------------------ SKINS
//
// As skins de pokémon (`shared/skins.mjs`). Três telas usam as peças daqui:
//
//   · o CARD da Loja — a arte (a shiny com o anel dourado), o relógio da venda limitada e o preço;
//   · a aba SKINS da bolsa — as que o jogador tem, com quantas estão em uso e em quem;
//   · a FOLHA de uma skin — os pokémon da espécie e da cor dela, com Vestir, Tirar e Mover para cá.
//
// A unidade NUNCA sai da bolsa: vestir é uma marcação (ver o cabeçalho de `shared/skins.mjs`).
// Por isso a tela fala em "N na bolsa · M em uso", e não em "equipadas" contra "na bolsa" como
// a Exp. Share — ali a unidade de fato muda de lugar, aqui não.

/**
 * "Dragonite Uchiha" / "Uchiha Dragonite" — o nome da skin no idioma da aba. A shiny leva o
 * "Shiny" na frente, como o pokémon: cada cor é uma skin separada, e o nome é o que as distingue
 * na bolsa, no Mercado e no aviso.
 */
function nomeDaSkin(s) {
  const nome = t('skin.nome', { especie: s.especie, estilo: t(`skin.estilo.${s.estilo}`) });
  return s.shiny ? t('skin.nomeShiny', { nome }) : nome;
}

/** "Dragonite" / "Shiny Dragonite" — o pokémon que ESTA skin veste (espécie e cor). */
const especieDaSkin = (s) => (s.shiny ? t('skin.nomeShiny', { nome: s.especie }) : s.especie);

/**
 * "Dragonite Nv 120" — como o aviso de vestir chama um pokémon. Com o NÍVEL (e o apelido, se
 * houver) porque o "mover para cá" é quase sempre entre dois bichos da MESMA espécie, e "saiu
 * de Dragonite e foi para Dragonite" não diz nada.
 */
function rotuloPkDaSkin(id, reserva) {
  const pk = (estado.eu?.pokemons ?? []).find((x) => x.id === Number(id));
  // O "✨ Shiny" entra porque o caso mais comum de mover é justamente entre o comum e o shiny da
  // mesma espécie — e "de Dragonite Nv 400 para Dragonite Nv 400" não diz para qual foi.
  return pk
    ? `${pk.shiny ? prefixoShiny() : ''}${nomeExibidoPokemon(pk)} ${t('cm.nivel')} ${num(pk.level)}`
    : (reserva ?? '');
}

/** Quantas unidades desta skin o jogador tem, quem as veste e quantas sobram livres. */
function contagemDaSkin(s, e = estado.eu) {
  const tem = Number(e?.items?.[s.itemId]) || 0;
  const vestidos = (e?.pokemons ?? []).filter((pk) => pk.skin === s.id && skinVestida(pk));
  return { tem, vestidos, livres: Math.max(0, tem - vestidos.length) };
}

/** 'antes' | 'aberta' | 'encerrada' — pelo relógio do SERVIDOR e pela janela que ele mandou. */
const situacaoSkinNaLoja = (prod) =>
  situacaoDaVenda(SKIN_POR_ID.get(prod?.skin), agoraDoServidor(), prod?.vendaSkin);

/**
 * "01/10" / "Oct 1" — a data de um carimbo no fuso de Brasília, que é o fuso do anúncio.
 *
 * Em inglês o mês vai por extenso: "10/01" seria lido como 10 de janeiro, e uma data de fim de
 * venda lida ao contrário é exatamente o erro que faz alguém perder a skin.
 */
const dataCurtaBr = (ms) => (idioma() === 'en'
  ? new Date(ms).toLocaleDateString('en-US', { day: 'numeric', month: 'short', timeZone: 'America/Sao_Paulo' })
  : new Date(ms).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', timeZone: 'America/Sao_Paulo' }));

/** A arte de uma skin, recortada da moldura: as megas vêm em quadro de 128 px e sairiam miúdas. */
const arteDaSkin = (looktype, px) => spriteAnimado(looktype, px, 3, null, null, { encaixar: true });

/** A janela de venda por extenso: "de 01/10 a 31/10". `fechaEm` é exclusivo, daí o −1 ms. */
const periodoDaVendaSkin = (janela) =>
  t('skin.periodo', { de: dataCurtaBr(janela.abreEm), ate: dataCurtaBr(janela.fechaEm - 1) });

/** O relógio da venda: "chega em 5d 12h" antes, "termina em 20d 3h" durante. */
const relogioDaVendaSkin = (prod) => (situacaoSkinNaLoja(prod) === 'antes'
  ? t('skin.chegaEm', { tempo: faltaParaServidor(prod.vendaSkin.abreEm) })
  : t('skin.terminaEm', { tempo: faltaParaServidor(prod.vendaSkin.fechaEm) }));

/**
 * A faixa do evento no topo da vitrine — "Skins de Halloween · edição limitada · termina em…".
 *
 * Existe porque o que torna a skin diferente de todo o resto da Loja é o PRAZO, e o prazo
 * repetido em treze cards é ruído: aqui ele é dito uma vez, grande, com a regra do depois
 * (só no Mercado da Comunidade) na mesma linha.
 */
function faixaSkinsDaLoja(prodRef) {
  const el = document.createElement('div');
  el.className = 'skin-faixa';
  el.innerHTML = `
    <span class="skin-faixa-abobora" aria-hidden="true">🎃</span>
    <div class="skin-faixa-txt">
      <b>${escapar(t('skin.faixaTitulo'))}</b>
      <span>${escapar(t('skin.faixaTexto', { periodo: periodoDaVendaSkin(prodRef.vendaSkin) }))}</span>
    </div>
    <span class="skin-faixa-relogio"></span>`;
  const relogio = el.querySelector('.skin-faixa-relogio');
  relogio.textContent = relogioDaVendaSkin(prodRef);
  const timer = setInterval(() => {
    if (!el.isConnected) return clearInterval(timer);
    relogio.textContent = relogioDaVendaSkin(prodRef);
  }, 1000);
  return el;
}

/** O card de uma skin na Loja. */
function cardSkinDaLoja(prod, saldo) {
  const s = SKIN_POR_ID.get(prod.skin);
  const sit = situacaoSkinNaLoja(prod);
  const { tem } = contagemDaSkin(s);
  const card = document.createElement('div');
  card.className = `loja-card skin-card${s.shiny ? ' skin-card-shiny' : ''}`;
  card.innerHTML = `
    <span class="loja-tag skin-selo">${escapar(t('skin.limitada'))}</span>
    <div class="loja-arte skin-arte">
      <span class="skin-arte-lado" data-lt="${s.looktype}"></span>
    </div>
    <div class="loja-nome">${escapar(nomeDaSkin(s))}</div>
    <div class="skin-para">${escapar(t('skin.para', { especie: especieDaSkin(s) }))}</div>
    <div class="skin-relogio"></div>
    <div class="loja-desc">${escapar(textoDaLoja(prod.i18n?.desc, prod.i18n?.params, prod.descricao ?? ''))}</div>
    ${tem ? `<div class="skin-tem">${escapar(t('skin.voceTem', { n: num(tem) }))}</div>` : ''}
    <button class="loja-btn" type="button"></button>`;
  for (const el of card.querySelectorAll('[data-lt]')) el.appendChild(arteDaSkin(Number(el.dataset.lt), 64));

  const relogio = card.querySelector('.skin-relogio');
  relogio.textContent = relogioDaVendaSkin(prod);
  // O relógio anda com a Loja aberta, e a VIRADA (abriu às 00h de 01/10, fechou às 00h de 01/11)
  // remonta a vitrine: o botão morto vira preço, ou o card sai. Sem isto o jogador que ficou
  // olhando a contagem chegar a zero teria de fechar e abrir a Loja para poder comprar.
  const timer = setInterval(() => {
    if (!card.isConnected) return clearInterval(timer);
    if (situacaoSkinNaLoja(prod) !== sit) {
      clearInterval(timer);
      return montarLoja();
    }
    relogio.textContent = relogioDaVendaSkin(prod);
  }, 1000);

  const bt = card.querySelector('.loja-btn');
  const preco = `${num(prod.preco)} ${seloDiamante(22)}`;
  if (sit === 'antes') {
    bt.disabled = true;
    bt.classList.add('cx-espera');
    bt.textContent = t('skin.emBreve');
  } else if (saldo < prod.preco) {
    bt.innerHTML = preco;
    bt.classList.add('sem-saldo');
    bt.title = t('loja.semDiamantes');
    bt.onclick = () => abrirCompraDeDiamantes(prod.preco - saldo);
  } else {
    bt.innerHTML = preco;
    bt.onclick = () => confirmarCompra(prod, saldo);
  }
  return card;
}

/** A aba SKINS da bolsa. */
function montarSkinsBolsa(host) {
  const e = estado.eu;
  const minhas = SKINS.filter((s) => (Number(e?.items?.[s.itemId]) || 0) > 0);
  const prodAVenda = (estado.lojaProdutos ?? []).find((x) => x.skin && situacaoSkinNaLoja(x) !== 'encerrada');
  host.innerHTML = `
    <div class="skin-bolsa-topo">
      <span class="skin-bolsa-ico" data-ico="img:${ICONE_COSMETICOS}" data-ico-px="30"></span>
      <p>${escapar(t('skin.bolsaIntro'))}</p>
      ${prodAVenda ? `<button type="button" class="cm-btn" id="skin-ir-loja">${escapar(t('skin.verLoja'))}</button>` : ''}
    </div>
    <div class="mk-grade bolsa-grade skin-grade" id="skin-grade"></div>`;
  for (const el of host.querySelectorAll('[data-ico]')) pintarIcone(el);
  const irLoja = host.querySelector('#skin-ir-loja');
  if (irLoja) {
    irLoja.onclick = () => {
      estado.grupoLoja = 'cosmeticos';
      abrirModal('shop');
    };
  }
  const grade = host.querySelector('#skin-grade');
  if (!minhas.length) {
    grade.innerHTML = `<div class="aviso-modal">${escapar(prodAVenda
      ? t('skin.bolsaVaziaComVenda', { periodo: periodoDaVendaSkin(prodAVenda.vendaSkin) })
      : t('skin.bolsaVazia'))}</div>`;
    return;
  }
  for (const s of minhas) grade.appendChild(cardSkinDaBolsa(s));
}

/** Um card da aba Skins: a skin animada, quantas o jogador tem e em quem ela está. */
function cardSkinDaBolsa(s) {
  const { tem, vestidos } = contagemDaSkin(s);
  const el = document.createElement('div');
  el.className = `mk-card bolsa-card bolsa-card-usavel skin-card-bolsa${vestidos.length ? ' skin-em-uso' : ''}`;
  el.dataset.chave = `skin${s.id}`;
  el.tabIndex = 0;
  el.title = t('skin.gerenciar');
  const quem = vestidos.map((pk) => escapar(nomeExibidoPokemon(pk))).join(', ');
  el.innerHTML = `
    <div class="mk-card-topo"><div class="mk-ico skin-ico"></div></div>
    <div class="mk-nome" title="${escapar(nomeDaSkin(s))}">${escapar(nomeDaSkin(s))}</div>
    <div class="mk-preco bolsa-qtd"><b>${num(tem)}</b>
      <em class="skin-uso">${escapar(vestidos.length
        ? t('skin.emUsoDe', { n: vestidos.length, total: tem })
        : t('skin.livre'))}</em></div>
    ${quem ? `<div class="skin-quem" title="${quem}">${quem}</div>` : ''}`;
  el.querySelector('.skin-ico').appendChild(arteDaSkin(s.looktype, 52));
  const abrir = () => abrirFolhaSkin(s);
  el.onclick = abrir;
  el.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      abrir();
    }
  };
  return el;
}

/**
 * A folha de UMA skin: a arte em cima, e embaixo os pokémon da espécie E da cor dela que o
 * jogador tem — Equipe, Depot e Coleção, as mesmas seções da Name Tag.
 *
 * A folha se REDESENHA sozinha quando o estado muda (`repintarFolhaSkin`, chamado a cada
 * snapshot), porque a resposta do servidor chega em dois pacotes: o aviso e o estado. Redesenhar
 * no aviso mostraria a folha de antes do clique.
 */
function abrirFolhaSkin(s) {
  const { corpo, fechar } = folhaMercado(escapar(nomeDaSkin(s)));
  estado.folhaSkin = { s, corpo, fechar, assinatura: null };
  repintarFolhaSkin();
}

/** O que a folha mostra muda com a bolsa, com as marcações e com os pokémon que a skin veste. */
function assinaturaFolhaSkin(s) {
  const e = estado.eu;
  const pks = (e?.pokemons ?? []).filter((pk) => skinServe(s, pk));
  return JSON.stringify([
    e?.items?.[s.itemId] ?? 0,
    pks.map((pk) => `${pk.id}:${pk.skin ?? ''}:${pk.slot ?? ''}:${pk.level}`),
  ]);
}

function repintarFolhaSkin() {
  const f = estado.folhaSkin;
  if (!f) return;
  if (!f.corpo.isConnected) {
    estado.folhaSkin = null;
    return;
  }
  const assinatura = assinaturaFolhaSkin(f.s);
  if (assinatura === f.assinatura) return;
  f.assinatura = assinatura;
  const rolagem = f.corpo.scrollTop;
  pintarFolhaSkin(f.corpo, f.s);
  f.corpo.scrollTop = rolagem;
}

function pintarFolhaSkin(corpo, s) {
  const { tem, vestidos, livres } = contagemDaSkin(s);
  // Só a espécie E a cor da skin: a shiny só veste o pokémon shiny, a comum só o comum.
  const todos = (estado.eu?.pokemons ?? [])
    .filter((pk) => skinServe(s, pk))
    .sort((a, b) => {
      const oa = a.slot == null ? 100 : a.slot;
      const ob = b.slot == null ? 100 : b.slot;
      return oa - ob || (b.level ?? 0) - (a.level ?? 0);
    });

  corpo.innerHTML = `
    <div class="skin-folha-topo">
      <div class="skin-folha-artes${s.shiny ? ' skin-folha-shiny' : ''}">
        <span data-lt="${s.looktype}"></span>
      </div>
      <div class="skin-folha-resumo">
        <p class="xsh-bolsa">${escapar(t('skin.naBolsa', { n: num(tem), uso: num(vestidos.length) }))}</p>
        <p class="xsh-intro">${escapar(t('skin.folhaIntro', { especie: especieDaSkin(s) }))}</p>
      </div>
    </div>
    ${tem < 1 ? `<p class="xsh-trava cm-nota">${escapar(t('skin.semItem'))}</p>` : ''}
    <div id="skin-secoes"></div>`;
  for (const el of corpo.querySelectorAll('[data-lt]')) el.appendChild(arteDaSkin(Number(el.dataset.lt), 70));

  const host = corpo.querySelector('#skin-secoes');
  if (!todos.length) {
    host.innerHTML = `<div class="aviso-modal">${escapar(t('skin.semPokemon', { especie: especieDaSkin(s) }))}</div>`;
    return;
  }
  const colecao = conjuntoColecaoCliente();
  const montarSecao = (titulo, lista) => {
    if (!lista.length) return;
    const sec = document.createElement('section');
    sec.className = 'xsh-secao';
    sec.innerHTML = `<h4 class="xsh-secao-titulo">${escapar(titulo)}</h4><div class="mk-grade xsh-grade"></div>`;
    const grade = sec.querySelector('.xsh-grade');
    for (const pk of lista) grade.appendChild(cardPokemonDaSkin(pk, s, { tem, livres, vestidos, colecao }));
    host.appendChild(sec);
  };
  const guardados = todos.filter((pk) => pk.slot == null);
  montarSecao(t('painel.equipe'), todos.filter((pk) => pk.slot != null));
  montarSecao(t('painel.depot'), guardados.filter((pk) => localDoPokemon(pk, colecao) === 'depot'));
  montarSecao(t('colecao.titulo'), guardados.filter((pk) => localDoPokemon(pk, colecao) === 'colecao'));
}

/**
 * Um pokémon da espécie, com o botão do que dá para fazer com ele:
 *
 *   Tirar         ele está com ESTA skin;
 *   Vestir        há unidade livre na bolsa (se ele veste a outra skin da espécie, troca);
 *   Mover p/ cá   todas as unidades estão em uso — tira do primeiro que a veste e põe neste.
 *                 O nome de quem perde a skin vai no botão: a mudança é em DOIS bichos, e o
 *                 jogador precisa ver os dois antes de clicar.
 */
function cardPokemonDaSkin(pk, s, { tem, livres, vestidos, colecao }) {
  const comEsta = pk.skin === s.id && !!skinVestida(pk);
  const outra = !comEsta && skinVestida(pk) ? SKIN_POR_ID.get(pk.skin) : null;
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = 'mk-acao';
  if (comEsta) {
    bt.textContent = t('skin.tirar');
    bt.classList.add('apagado');
    bt.onclick = () => enviar({ t: 'skin.tirar', pokemonId: pk.id });
  } else if (tem < 1) {
    bt.textContent = t('skin.vestir');
    bt.disabled = true;
  } else if (livres > 0) {
    bt.textContent = t('skin.vestir');
    bt.onclick = () => enviar({ t: 'skin.vestir', pokemonId: pk.id, skinId: s.id });
  } else {
    const de = vestidos[0];
    bt.textContent = t('skin.moverDe', { nome: `${de.shiny ? prefixoShiny() : ''}${nomeExibidoPokemon(de)}` });
    bt.onclick = () => enviar({ t: 'skin.vestir', pokemonId: pk.id, skinId: s.id, deId: de.id });
  }

  const onde = t(LOCAL_I18N[localDoPokemon(pk, colecao)]);
  const card = cardMarket({
    chave: `skinpk${pk.id}`,
    nome: `${pk.shiny ? prefixoShiny() : ''}${nomePkHtml(pk)}`,
    sub: t('mk.subPokemonCurta', { level: pk.level, onde }),
    atributos: selosAtributos(pk),
    preco: 0,
    rotulo: comEsta
      ? escapar(t('skin.vestindo'))
      : outra ? escapar(t('skin.comOutra', { nome: nomeDaSkin(outra) })) : '',
    acao: [bt],
    aoVerFicha: () => abrirFichaDoPokemon(pk),
    classe: comEsta ? 'xsh-card-on' : '',
  });
  card.querySelector('.mk-card-topo').querySelector('.mk-ico').appendChild(spritePokemon(pk, 44));
  return card;
}

// ------------------------------------------------------------------ NAME TAG
//
// A etiqueta de 15 💎 que dá um NOME a um pokémon. A folha tem dois passos, e a ordem importa:
//
//   1. QUAL pokémon — a mesma grade de cards do Exp. Share, pelas mesmas seções (Equipe, Depot,
//      Coleção). Quem abre a bolsa está olhando para a etiqueta, não para um bicho específico;
//   2. QUAL nome — com o aviso de conduta acima do campo, e não depois dele.
//
// O aviso vem ANTES de digitar de propósito. Posto embaixo, ele seria lido (na melhor das
// hipóteses) depois de a pessoa já ter escolhido a graça que ia escrever — e o texto não está
// ali para recusar o nome, está ali para a escolha ser informada. Ele é repetido na caixa de
// confirmação, que é o instante em que a etiqueta some.
//
// A folha NÃO valida por vontade própria: quem diz se o nome serve é `validarApelido`, o mesmo
// módulo que o servidor chama. A tela só desenha a resposta enquanto se digita, para o "não"
// chegar antes do clique em vez de voltar como toast depois dele.

/** A etiqueta está viva neste servidor? (O item precisa existir no catálogo carregado.) */
const nameTagAtiva = () => estado.itens?.has(NAME_TAG_ID) ?? false;

/** Quantas etiquetas ele tem na bolsa. */
const nameTagsNaBolsa = () => estado.eu?.items?.[NAME_TAG_ID] ?? 0;

function abrirNameTag() {
  if (!nameTagAtiva()) return;
  const { corpo, fechar } = folhaMercado(t('nametag.titulo'));
  pintarNameTagEscolha(corpo, fechar);
}

/** Passo 1 — qual pokémon. */
function pintarNameTagEscolha(corpo, fechar) {
  const naBolsa = nameTagsNaBolsa();
  const todos = [...(estado.eu?.pokemons ?? [])].sort((a, b) => {
    const oa = a.slot == null ? 100 : a.slot;
    const ob = b.slot == null ? 100 : b.slot;
    return oa - ob || nomeExibidoPokemon(a).localeCompare(nomeExibidoPokemon(b), undefined, { sensitivity: 'base' });
  });

  corpo.innerHTML = `
    <div class="xsh-topo">
      <div class="xsh-ico" id="ntag-ico"></div>
      <div class="xsh-resumo">
        <p class="xsh-bolsa">${t('nametag.naBolsa', { n: num(naBolsa) })}</p>
        <p class="xsh-intro">${escapar(t('nametag.intro'))}</p>
      </div>
    </div>
    <p class="xsh-trava cm-nota">${escapar(t('nametag.usoUnico'))}</p>
    <div id="ntag-secoes"></div>`;
  corpo.querySelector('#ntag-ico')?.appendChild(imgItem(NAME_TAG_ID, 44));

  const host = corpo.querySelector('#ntag-secoes');
  if (!todos.length) {
    host.innerHTML = `<div class="aviso-modal">${t('nametag.semPokemon')}</div>`;
    return;
  }
  // As mesmas três seções do Exp. Share, pela mesma função de `localDoPokemon` — a Coleção é
  // onde mora quase todo bicho que vale a pena batizar, e escondê-la aqui seria esconder o uso
  // principal do produto.
  const colecao = conjuntoColecaoCliente();
  const equipe = todos.filter((p) => p.slot != null);
  const guardados = todos.filter((p) => p.slot == null);
  const montarSecao = (titulo, lista) => {
    if (!lista.length) return;
    const sec = document.createElement('section');
    sec.className = 'xsh-secao';
    sec.innerHTML = `<h4 class="xsh-secao-titulo">${escapar(titulo)}</h4><div class="mk-grade xsh-grade"></div>`;
    const grade = sec.querySelector('.xsh-grade');
    for (const p of lista) grade.appendChild(cardNameTag(p, naBolsa, colecao, corpo, fechar));
    host.appendChild(sec);
  };
  montarSecao(t('painel.equipe'), equipe);
  montarSecao(t('painel.depot'), guardados.filter((p) => localDoPokemon(p, colecao) === 'depot'));
  montarSecao(t('colecao.titulo'), guardados.filter((p) => localDoPokemon(p, colecao) === 'colecao'));
}

function cardNameTag(p, naBolsa, colecao, corpo, fechar) {
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = 'mk-acao';
  bt.textContent = t(apelidoDe(p) ? 'nametag.trocar' : 'nametag.nomear');
  bt.disabled = naBolsa < 1;
  if (naBolsa < 1) bt.title = t('nametag.semItem');
  bt.onclick = () => pintarNameTagNome(corpo, fechar, p);

  const card = cardMarket({
    chave: `ntag${p.id}`,
    nome: `${p.shiny ? prefixoShiny() : ''}${nomePkHtml(p)}`,
    // A ESPÉCIE entra no subtítulo de quem já tem apelido. É a única tela em que o jogador
    // escolhe UM bicho entre trinta parecidos, e se todos estiverem batizados o nome de cima
    // deixa de ajudar a distinguir "qual Eevee é o que eu quero renomear".
    sub: apelidoDe(p)
      ? `${escapar(p.nome)} · ${t('mk.subPokemonCurta', { level: p.level, onde: t(LOCAL_I18N[localDoPokemon(p, colecao)]) })}`
      : t('mk.subPokemonCurta', { level: p.level, onde: t(LOCAL_I18N[localDoPokemon(p, colecao)]) }),
    atributos: selosAtributos(p),
    preco: 0,
    rotulo: apelidoDe(p) ? t('nametag.jaTemTag') : '',
    acao: [bt],
    aoVerFicha: () => abrirFichaDoPokemon(p),
    classe: apelidoDe(p) ? 'xsh-card-on' : '',
  });
  card.querySelector('.mk-card-topo').querySelector('.mk-ico').appendChild(spritePokemon(p, 44));
  return card;
}

/** Passo 2 — qual nome. */
function pintarNameTagNome(corpo, fechar, pk) {
  const anterior = apelidoDe(pk);
  corpo.innerHTML = `
    <div class="ntag-alvo">
      <div class="ntag-alvo-arte" id="ntag-arte"></div>
      <div class="ntag-alvo-txt">
        <div class="ntag-alvo-nome">${pk.shiny ? prefixoShiny() : ''}${nomePkHtml(pk)}</div>
        <div class="ntag-alvo-especie">${t('nametag.fichaEspecie', { especie: escapar(pk.nome ?? '') })}
          · ${t('cm.nivel')} ${num(pk.level)}</div>
      </div>
    </div>

    <div class="ntag-aviso">
      <b>${escapar(t('nametag.avisoTitulo'))}</b>
      <p>${escapar(t('nametag.avisoTexto'))}</p>
    </div>

    <label class="ntag-campo">
      <span class="ntag-rotulo">${escapar(t('nametag.rotuloCampo'))}</span>
      <input type="text" id="ntag-input" class="ntag-input" maxlength="${APELIDO_MAX}"
             autocomplete="off" spellcheck="false" value="${escapar(anterior)}"
             placeholder="${escapar(pk.nome ?? '')}">
    </label>
    <p class="ntag-dica" id="ntag-dica"></p>

    <div class="ntag-acoes">
      <button type="button" class="cm-btn" id="ntag-voltar">${escapar(t('nametag.voltar'))}</button>
      <button type="button" class="cm-btn comprar" id="ntag-ok">${escapar(t('nametag.confirmar'))}</button>
    </div>`;
  corpo.querySelector('#ntag-arte')?.appendChild(spritePokemon(pk, 64));

  const campo = corpo.querySelector('#ntag-input');
  const dica = corpo.querySelector('#ntag-dica');
  const ok = corpo.querySelector('#ntag-ok');

  // A conferência roda a cada tecla, pelo MESMO validador do servidor. O objetivo não é
  // impedir o envio (o servidor decide), é o jogador nunca descobrir que o nome não serve
  // depois de a etiqueta ter sumido.
  const conferir = () => {
    const v = validarApelido(campo.value);
    const igual = v.ok && v.apelido === anterior;
    ok.disabled = !v.ok || igual;
    if (!campo.value.trim()) {
      dica.textContent = t('nametag.dicaRegras', { min: APELIDO_MIN, max: APELIDO_MAX });
      dica.className = 'ntag-dica';
      return;
    }
    if (!v.ok) {
      dica.textContent = t(v.erro, { min: APELIDO_MIN, max: APELIDO_MAX });
      dica.className = 'ntag-dica ruim';
      return;
    }
    dica.textContent = igual ? t('nametag.mesmoNome') : t('nametag.dicaPreview', { nome: v.apelido });
    dica.className = `ntag-dica ${igual ? 'ruim' : 'bom'}`;
  };
  campo.oninput = conferir;
  campo.onkeydown = (ev) => {
    if (ev.key === 'Enter' && !ok.disabled) ok.click();
  };
  conferir();
  campo.focus();
  campo.select();

  corpo.querySelector('#ntag-voltar').onclick = () => pintarNameTagEscolha(corpo, fechar);
  ok.onclick = () => {
    const v = validarApelido(campo.value);
    if (!v.ok) return toast(t(v.erro, { min: APELIDO_MIN, max: APELIDO_MAX }));
    confirmarNameTag(pk, v.apelido, () => {
      enviar({ t: 'nametag.usar', pokemonId: pk.id, apelido: v.apelido });
      fechar();
    });
  };
}

/**
 * O bicho com o nome de hoje, a etiqueta em cima da seta, e ele de novo com o nome novo numa
 * plaquinha — a troca inteira cabe num olhar. O aviso de conduta é REPETIDO aqui: é a última tela
 * antes de a etiqueta sumir, e é a única que o jogador não pode passar sem ler — na folha ele pode
 * ter rolado direto para o campo.
 */
function confirmarNameTag(pk, apelido, aoConfirmar) {
  confirmar({
    titulo: t('nametag.confirmarTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArtePk(pk, 64), nome: nomePkHtml(pk), sub: apelidoDe(pk) ? escapar(pk.nome ?? '') : '' })}
        ${dlgSeta({ item: NAME_TAG_ID, qtd: '×1' })}
        ${dlgAtor({
          arte: dlgArtePk(pk, 64),
          nome: `<span class="dlg-etiqueta">${escapar(apelido)}</span>`,
          sub: escapar(pk.nome ?? ''),
          classe: 'novo',
        })}`)}
      ${dlgFrase('', `${t('nametag.confirmarTexto', {
        especie: `<b>${escapar(pk.nome ?? '')}</b>`,
        nome: `<b>${escapar(apelido)}</b>`,
      })} ${escapar(t('nametag.confirmarCosmetico'))}`)}
      ${dlgAviso(escapar(t('nametag.avisoTexto')))}`,
    aoConfirmar,
  });
}

/**
 * Escolha de quem recebe o XP Share — a EQUIPE, cards no estilo do Market.
 *
 * Só a equipe, e não o Depot: é a regra do servidor (`xpshare.escolher` recusa quem está no
 * Depot), e repetir a trava aqui é o que evita o pior tipo de tela — a que oferece uma escolha
 * e depois avisa que não pode.
 *
 * O pokémon de BATALHA aparece na lista, marcado. Ele pode ser registrado — só não recebe
 * enquanto for o ativo, e escondê-lo faria a lista mudar de tamanho a cada troca de time, o
 * que é mais confuso do que o aviso.
 *
 * Quem já está noutro posto também aparece, com a casa em que está e um "Mover para cá": com
 * várias casas, esconder os já escalados deixaria a lista vazia justamente para quem quer
 * reorganizar. Mover são duas mensagens na MESMA conexão — tirar de lá, pôr aqui —, e o servidor
 * as processa na ordem em que chegaram.
 */
function abrirEscolhaDeTreino(casaId, slot) {
  const casa = minhaCasaPorId(casaId);
  if (!casa || casa.anunciada) return toast(t('casa.naoDisponivel'));
  const equipeBase = (estado.eu?.pokemons ?? []).filter((p) => p.slot != null);
  const lista = equipeBase
    .filter((p) => !pokemonTemXpShareHeld(p))
    .sort((a, b) => (a.slot ?? 0) - (b.slot ?? 0));
  const ocultosHeld = equipeBase.length - lista.length;

  if (!lista.length) {
    return toast(ocultosHeld ? t('casa.semPokemonEquipeHeld') : t('casa.semPokemonEquipe'));
  }

  const pct = Math.round((metaRaridade(casa.rar)?.xpShare ?? 0) * 100);
  const { corpo, fechar } = folhaMercado(escapar(t('casa.escolherTituloNum', { numero: numeroDaCasa(casa.id) })));
  // A conta da casa desenhada: o XP do pokémon de BATALHA → a fatia da casa → quem for escolhido
  // aqui embaixo. O "?" é o lugar que a grade vai preencher.
  const ativo = (estado.eu?.pokemons ?? []).find((p) => p.id === estado.eu?.activeId);
  corpo.innerHTML = `
    ${dlgPalco(`
      ${dlgAtor({
        arte: ativo ? dlgArtePk(ativo, 56) : dlgArteTreinador(null, null, 56),
        nome: ativo ? nomePkHtml(ativo) : escapar(estado.eu?.nick ?? ''),
        sub: escapar(t('casa.xpDaBatalha')),
      })}
      ${dlgSeta({ rotulo: escapar(t('casa.pctDoXp', { pct })) })}
      ${dlgAtor({
        arte: dlgArteHtml(dlgMedalha({ icone: 'interrogacao', tom: 'ouro', px: 34 })),
        nome: escapar(t('casa.quemEscolher')),
        classe: 'novo',
      })}`, 'ouro')}
    ${dlgAviso(escapar(t('casa.escolherEquipeDica')), { icone: 'pessoa', tom: 'info' })}
    ${ocultosHeld ? dlgAviso(escapar(t('casa.ocultosHeld', { n: ocultosHeld })), { icone: 'alerta', tom: 'ouro' }) : ''}
    <div class="mk-grade" id="aca-mk-grade"></div>`;
  hidratarDialogo(corpo);
  const grade = corpo.querySelector('#aca-mk-grade');

  for (const p of lista) {
    const ehAtivo = estado.eu?.activeId === p.id;
    const aqui = casa.postos?.[slot] === p.id;
    const noutro = aqui ? null : postoDoPokemonNaTela(p.id, { casaId: casa.id, slot });
    const bt = document.createElement('button');
    bt.className = `mk-acao${aqui ? ' apagado' : ''}`;
    bt.textContent = t(aqui ? 'casa.jaAqui' : noutro ? 'casa.moverParaCa' : 'casa.escolher');
    bt.disabled = aqui;
    bt.onclick = () => {
      if (noutro) enviar({ t: 'xpshare.escolher', casaId: noutro.casaId, slot: noutro.slot, pokemonId: null });
      enviar({ t: 'xpshare.escolher', casaId: casa.id, slot, pokemonId: p.id });
      fechar();
    };

    const card = cardMarket({
      chave: `aca${p.id}`,
      nome: `${p.shiny ? prefixoShiny() : ''}${nomePkHtml(p)}`,
      sub: t('mk.subPokemonCurta', { level: p.level, onde: t('painel.equipe') }),
      atributos: selosAtributos(p),
      preco: 0,
      // O rótulo diz o que ele VAI ganhar. No ativo, diz por que não vai ganhar nada agora; no
      // escalado noutra casa, diz onde ele está — é o que o jogador precisa para decidir mover.
      rotulo: ehAtivo
        ? t('casa.ehOAtivo')
        : noutro ? t('casa.naCasa', { numero: numeroDaCasa(noutro.casaId) }) : t('casa.xpShareTag', { n: pct }),
      acao: [bt],
      aoVerFicha: () => abrirFichaDoPokemon(p),
    });
    if (ehAtivo) card.classList.add('mk-card-alerta');
    const topo = card.querySelector('.mk-card-topo');
    topo.querySelector('.mk-ico').appendChild(spritePokemon(p, 44));
    grade.appendChild(card);
  }
}

// ------------------------------------------------------ indique & ganhe

const afiliado = { painel: null, pedidoEm: 0 };

async function atualizarSeloAfiliado(forcar = false) {
  if (!forcar && afiliado.painel && Date.now() - afiliado.pedidoEm < 5 * 60_000) {
    pintarSeloAfiliado(afiliado.painel);
    return afiliado.painel;
  }
  try {
    afiliado.painel = await pedirAfiliado('me');
    afiliado.pedidoEm = Date.now();
    pintarSeloAfiliado(afiliado.painel);
  } catch {
    afiliado.painel = null;
  }
  return afiliado.painel;
}

function pintarSeloAfiliado(painel) {
  $('#btn-afiliados')?.classList.toggle('tem-af-pendente', !!painel?.podeRecolher);
}

function renderAfiliados() {
  return `<div class="af-modal" id="af-corpo"><div class="pf-carregando">${t('af.carregando')}</div></div>`;
}

function resumoRecolherAf(d) {
  if (!d.podeRecolher) return t('af.nadaPendente');
  const partes = [];
  if (d.pendenteDiamantes > 0) partes.push(`${seloDiamante(16)} ${num(d.pendenteDiamantes)}`);
  if (d.pendenteGemas > 0) partes.push(`${seloGema(14)} ${num(d.pendenteGemas)}`);
  return t('af.prontoRecolher', { lista: partes.join(' · ') });
}

async function montarAfiliados() {
  const host = $('#af-corpo');
  if (!host) return;
  try {
    const d = await pedirAfiliado('me');
    afiliado.painel = d;
    afiliado.pedidoEm = Date.now();
    pintarSeloAfiliado(d);
    const aplicar = d.podeAplicar
      ? `<div class="af-secao">
           <div class="af-secao-titulo">${t('af.alguemIndicou')}</div>
           <div class="af-aplicar">
             <input id="af-codigo" maxlength="20" autocomplete="off" placeholder="${t('af.placeholderCodigo')}">
             <button type="button" id="af-aplicar" disabled>${t('af.confirmar')}</button>
           </div>
           <div class="af-aviso-pequeno">${t('af.antesPrimeiraCompra')}</div>
           <div class="af-erro" id="af-erro"></div>
         </div>`
      : d.indicadoPor
        ? `<div class="af-indicado-por">${t('af.jaIndicadoPor', { code: escapar(d.indicadoPor) })}</div>`
        : '';

    // As porcentagens vêm do SERVIDOR (painelDe), e não de um número cravado na tradução: com
    // taxa por indicador, um "5%" literal no i18n vira promessa falsa para todo streamer com
    // acordo especial — e para todo mundo, no dia em que a constante mudar.
    const pctTexto = (v) => `${(Number(v ?? 0) * 100).toFixed(Number(v ?? 0) * 1000 % 10 ? 1 : 0)}`;
    // "Influenciador Oficial" é o nome que o JOGADOR vê; no banco e no painel o campo continua
    // sendo `streamer_oficial`, porque é para streamer que o acordo existe. Os dois nomes
    // convivem de propósito — renomear a coluna de uma migração já publicada custaria mais do
    // que vale, e a tag roxa [STREAMER] do chat é outra coisa, com i18n próprio.
    const faixaInfluenciador = d.streamerOficial
      ? `<div class="af-influenciador">
           <div class="af-influenciador-selo">${t('af.influenciadorSelo')}</div>
           <div class="af-influenciador-txt">${t('af.influenciadorTexto', {
             pctOrb: pctTexto(d.taxaGema),
             pctDia: pctTexto(d.taxaDiamante),
           })}</div>
           ${d.taxaDiaExtra > 0
             ? `<div class="af-aviso-pequeno">${t('af.influenciadorBonus', {
                 pct: pctTexto(d.taxaDiaExtra),
                 gemas: num(d.gemasPorDiamante ?? 7),
               })}</div>`
             : ''}
         </div>`
      : '';

    host.innerHTML = `
      <p class="af-intro">${t('af.intro', { pctDia: pctTexto(d.taxaDiamante), pctOrb: pctTexto(d.taxaGema) })}</p>
      ${faixaInfluenciador}
      <div class="af-secao">
        <div class="af-secao-titulo">${t('af.seuLink')}</div>
        <div class="af-link-linha">
          <input id="af-link" readonly value="${escapar(d.link)}">
          <button type="button" id="af-copiar">${t('af.copiar')}</button>
        </div>
        <div class="af-codigo">${t('af.codigo', { code: escapar(d.code) })}</div>
        <div class="af-aviso-pequeno">${t('af.visitasAoLink', { n: num(d.visitas ?? 0) })}</div>
      </div>
      <div class="af-stats">
        <div class="af-stat">
          <span class="af-stat-titulo">${t('af.indicados')}</span>
          <span class="af-stat-valor">${num(d.indicados)}</span>
        </div>
        <div class="af-stat">
          <span class="af-stat-titulo">${t('af.pendente')} · ${t('moeda.diamantes')}</span>
          <span class="af-stat-valor">${seloDiamante(18)} ${num(d.pendenteDiamantes ?? 0)}</span>
        </div>
        <div class="af-stat">
          <span class="af-stat-titulo">${t('af.pendente')} · ${t('moeda.gemas')}</span>
          <span class="af-stat-valor">${seloGema(16)} ${num(d.pendenteGemas ?? 0)}</span>
        </div>
      </div>
      <div class="af-recolher">
        <div class="af-recolher-resumo">${resumoRecolherAf(d)}</div>
        <button type="button" id="af-recolher" class="login-acao" ${d.podeRecolher ? '' : 'disabled'}>${t('af.recolher')}</button>
      </div>
      ${(d.ganhosDiamantes > 0 || d.ganhosGemas > 0)
        ? `<div class="af-total-vida">${t('af.totalVida', {
            dia: num(d.ganhosDiamantes ?? 0),
            gema: num(d.ganhosGemas ?? 0),
          })}</div>`
        : ''}
      ${aplicar}`;

    $('#af-copiar').onclick = async () => {
      try {
        await navigator.clipboard.writeText(d.link);
        toast(t('af.copiado'));
      } catch {
        $('#af-link').select();
        document.execCommand('copy');
        toast(t('af.copiado'));
      }
    };

    $('#btn-afiliados')?.classList.toggle('tem-af-pendente', !!d.podeRecolher);

    const recolher = $('#af-recolher');
    if (recolher) {
      recolher.onclick = () => {
        if (!d.podeRecolher || recolher.disabled) return;
        recolher.disabled = true;
        if (estado.ws?.readyState === 1) {
          enviar({ t: 'afiliado.recolher' });
          setTimeout(() => { recolher.disabled = false; }, 1200);
        } else {
          pedirAfiliado('recolher')
            .then((r) => {
              if (r.recolhido?.length) {
                const dia = r.recolhido.filter((i) => i.tipo === 'diamante').reduce((s, i) => s + i.qtd, 0);
                const gema = r.recolhido.filter((i) => i.tipo === 'gema').reduce((s, i) => s + i.qtd, 0);
                const partes = [];
                if (dia > 0) partes.push(t('af.recolhidoDia', { qtd: num(dia) }));
                if (gema > 0) partes.push(t('af.recolhidoGema', { qtd: num(gema) }));
                toast(partes.join(' · ') || t('af.recolhido'));
              }
              afiliado.painel = null;
              sincronizarMobile();
              montarAfiliados();
            })
            .catch((err) => {
              toast(err.message);
              recolher.disabled = false;
            });
        }
      };
    }

    if (d.podeAplicar) {
      const input = $('#af-codigo');
      const botao = $('#af-aplicar');
      const erro = $('#af-erro');
      const atualizar = () => {
        // A mesma forma frouxa do `?ref=`: o campo aceita código gerado e slug de streamer, e
        // quem recusa de verdade é o servidor. Antes o botão acendia para 4 caracteres e o
        // servidor exigia 6 — o jogador levava um 400 num código que a tela dizia estar válido.
        botao.disabled = !/^[a-z0-9][a-z0-9_-]{1,18}[a-z0-9]$/i.test(input.value.trim());
        erro.textContent = '';
      };
      input.oninput = atualizar;
      atualizar();
      botao.onclick = async () => {
        botao.disabled = true;
        erro.textContent = '';
        try {
          // Sem `toUpperCase()`: o servidor compara por `lower()` nos dois lados, e maiúscula
          // aqui transformava o slug "matta" em "MATTA" antes de a regex do slug o ver.
          await pedirAfiliado('aplicar', { code: input.value.trim() });
          localStorage.removeItem(CHAVE_REF);
          montarAfiliados();
          toast(t('af.confirmar'));
        } catch (err) {
          erro.textContent = err.message;
          botao.disabled = false;
        }
      };
    }
  } catch {
    host.innerHTML = `<div class="pf-aviso">${t('af.falhou')}</div>`;
  }
}

// ----------------------------------------------------------- vote & ganhe
//
// O voto acontece FORA daqui: o botão leva ao topidle.com com o nick já preenchido, a pessoa
// autoriza lá com a conta Google dela, e o TopIdle avisa o nosso servidor por webhook. O
// diamante cai sozinho — esta tela não confirma nada, ela só explica, leva para lá e mostra o
// que já foi ganho.
//
// É por isso que não existe botão de "resgatar": um botão assim sugeriria que o jogador pode
// perder a recompensa se esquecer de voltar, e ele não pode.

/** Estado do selo do botão, para não pedir o painel a cada abertura da aba. */
const voto = { painel: null, pedidoEm: 0 };

/** O pontinho vermelho no Vote & Ganhe: só quando há voto disponível de verdade. */
function pintarSeloVoto(painel) {
  const btn = $('#btn-votar');
  if (!btn) return;
  const disponivel = !!painel?.ativo && painel.esperaMs <= 0;
  btn.classList.toggle('tem-voto', disponivel);
}

/**
 * Busca o painel do voto e guarda.
 *
 * `forcar` pula o cache de cinco minutos — usado depois de um voto cair, quando o número na
 * tela mudou de verdade.
 */
async function atualizarVoto(forcar = false) {
  if (!forcar && voto.painel && Date.now() - voto.pedidoEm < 5 * 60_000) return voto.painel;
  try {
    voto.painel = await pedirVoto('me');
    voto.pedidoEm = Date.now();
    pintarSeloVoto(voto.painel);
  } catch {
    // Sem sessão ou servidor fora: o botão continua lá, sem selo. A tela do modal é que
    // conta o que houve, e aqui não há nada a avisar.
  }
  return voto.painel;
}

function renderVotar() {
  return `<div class="vt-modal" id="vt-corpo"><div class="pf-carregando">${t('af.carregando')}</div></div>`;
}

async function montarVotar() {
  const host = $('#vt-corpo');
  if (!host) return;
  // `atualizarVoto` engole o erro (ela também roda no login, onde não há tela para avisar).
  // Aqui HÁ tela, então a ausência de painel vira a mensagem — e não um modal em branco.
  const d = await atualizarVoto(true);
  if (!d) {
    host.innerHTML = `<div class="pf-aviso">${t('voto.falhou')}</div>`;
    return;
  }

  // Uma pergunta só, e a MESMA que o servidor faz na chegada do voto: já passou a recarga?
  const podeVotar = d.ativo && d.esperaMs <= 0;
  const estadoTxt = !d.ativo ? ''
    : d.esperaMs > 0
      ? `<div class="vt-estado esperando">${t('voto.volteEm', { tempo: duracaoCurta(d.esperaMs) })}</div>`
      : `<div class="vt-estado pronto">${t('voto.disponivel')}</div>`;

  // A barra do PAR. Com o prêmio saindo a cada dois votos, o jogador que votou uma vez
  // precisa ver que o voto entrou — senão a tela parece dizer que ele não ganhou nada.
  const faltam = d.votosPorDiamante - d.noPar;
  const passos = Array.from({ length: d.votosPorDiamante }, (_, i) =>
    `<i class="${i < d.noPar ? 'on' : ''}"></i>`).join('');

  host.innerHTML = `
    <p class="vt-intro">${t('voto.intro')}</p>
    <div class="vt-premio">
      <span class="vt-premio-qtd">${seloDiamante(26)} ${num(d.porPar)}</span>
      <span class="vt-premio-txt">${t('voto.premio', {
        n: num(d.porPar),
        votos: num(d.votosPorDiamante),
        // Dias por diamante: votos que fecham o par ÷ votos que contam por dia. Sai da conta
        // e não de um número escrito na frase, para a tela não mentir se a regra mudar.
        // Um voto por recarga, então dias por diamante = votos que fecham o par.
        dias: num(d.votosPorDiamante),
      })}</span>
    </div>
    <div class="vt-par">
      <div class="vt-par-passos">${passos}</div>
      <span class="vt-par-txt">${faltam === 1 ? t('voto.falta1') : t('voto.faltaN', { n: num(faltam) })}</span>
    </div>
    ${d.ativo ? '' : `<div class="vt-desligado">${t('voto.desligado')}</div>`}
    ${estadoTxt}
    <a class="pf-acao vt-ir${podeVotar ? '' : ' travado'}" id="vt-ir"
       href="${escapar(d.url)}" target="_blank" rel="noopener noreferrer"
       ${podeVotar ? '' : 'aria-disabled="true" tabindex="-1"'}>${t('voto.ir')}</a>
    <div class="vt-stats">
      <div class="af-stat">
        <span class="af-stat-titulo">${t('voto.total')}</span>
        <span class="af-stat-valor">${num(d.votos)}</span>
      </div>
      <div class="af-stat">
        <span class="af-stat-titulo">${t('moeda.diamantes')}</span>
        <span class="af-stat-valor">${seloDiamante(18)} ${num(d.diamantes)}</span>
      </div>
    </div>
    <div>
      <div class="af-secao-titulo">${t('voto.comoTitulo')}</div>
      <ol class="vt-passos">
        <li>${t('voto.passo1')}</li>
        <li>${t('voto.passo2', { nick: `<span class="vt-nick">${escapar(d.identificador)}</span>` })}</li>
        <li>${t('voto.passo3')}</li>
      </ol>
    </div>
    <div class="af-aviso-pequeno">${t('voto.rodape')}</div>`;

  // Clicar no botão travado não pode simplesmente não fazer nada: sem uma resposta, a pessoa
  // clica de novo achando que a tela travou.
  if (!podeVotar) {
    $('#vt-ir').onclick = (ev) => {
      ev.preventDefault();
      toast(d.ativo ? t('voto.aindaNao') : t('voto.desligado'));
    };
  }
}

// ---------------------------------------------------- arena mística & chocadeira
//
// O MYSTICTICKET cai na vitória de boss e abre a ARENA MÍSTICA: um lendário de nível 100 numa sala
// roxa, e UMA bola. A CHOCADEIRA choca os Mystery Eggs do Market NPC pela data — o pokémon nasce na
// Coleção com o dono online ou não. As regras moram em `shared/mistico.mjs` e
// `shared/chocadeira.mjs`, que o servidor também importa: a tela nunca tem uma cópia dos números.

/** "0,5%" — as chances da arena são frações de por cento, e o `num` inteiro as zeraria. */
const pctMistico = (ch) => `${(Number(ch) * 100).toLocaleString('pt-BR', { maximumFractionDigits: 2 })}%`;

/** O nome da bola, do catálogo que o servidor mandou. */
const nomeDaBola = (id) => estado.catalogoBolas?.find((b) => b.id === Number(id))?.nome ?? `Ball ${id}`;

/**
 * Quem a Arena Mística pode sortear. É daqui que sai o "1 em N" da ficha da Pokédex: a chance
 * de o ticket trazer justamente ESTE lendário.
 *
 * A lista vem do SERVIDOR (`misticoPool`, no welcome), que é quem sorteia. Rodar
 * `poolLendariosMisticos` sobre o catálogo desta aba parece a mesma conta — o cliente monta o
 * catálogo dos mesmos JSONs —, mas não é: o caminho é outro, e as duas contas divergiam em
 * duas espécies. Um "1 em 61" numa arena de 59 é a ficha mentindo em número redondo. A conta
 * local fica só de reserva, para o servidor que ainda não manda o campo.
 *
 * Memoizado porque a ficha é remontada a cada abertura e nada disso muda depois do welcome.
 */
let poolMisticoCache = null;
function poolMistico() {
  const doServidor = estado.misticoPool;
  const chave = doServidor ? `s${doServidor.size}` : `c${estado.especies.size}`;
  if (poolMisticoCache?.chave !== chave) {
    const ids = doServidor ?? new Set(poolLendariosMisticos(estado.especies).map((e) => e.pokeId));
    poolMisticoCache = { chave, ids, n: ids.size };
  }
  return poolMisticoCache;
}

/** Esta espécie pode sair da Arena Mística? */
const noSorteioMistico = (pokeId) => poolMistico().ids.has(Number(pokeId));

/**
 * Usar o ticket: a confirmação diz tudo o que está em jogo ANTES do clique — o ticket some na
 * entrada, a tentativa é uma só, e perder a luta ou sair é perder o ticket. Sem bola na bolsa, o
 * servidor recusa; a caixa já avisa para o jogador não descobrir isso depois de abrir.
 */
function abrirUsoTicketMistico() {
  const temBola = BOLAS_MISTICAS_DA_MELHOR.some((id) => (estado.eu?.balls?.[id] ?? 0) > 0);
  // O ticket vira a sala roxa (o "?" é o lendário que o sorteio ainda não disse), e a chance de
  // cada bola sai da frase para uma fileira: as cinco bolas com o número embaixo, a que a pessoa
  // não tem apagada. É a tabela que ela ia montar de cabeça antes de entrar.
  const bolas = [...BOLAS_MISTICAS_DA_MELHOR].reverse().map((id) => `
    <span class="dlg-bola${(estado.eu?.balls?.[id] ?? 0) > 0 ? '' : ' sem'}">
      <span data-dlg-arquivo="${SPRITE_BOLA[id]}" data-dlg-px="28"></span>
      <b>${pctMistico(CAPTURA_MISTICA_POR_BOLA[id])}</b>
    </span>`).join('');
  confirmar({
    titulo: t('mistico.usarTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteItem(MYSTIC_TICKET_ID, 64), nome: 'MysticTicket', classe: 'sai' })}
        ${dlgSeta()}
        ${dlgAtor({
          arte: dlgArteHtml(dlgMedalha({ icone: 'interrogacao', tom: 'mega', px: 40 })),
          nome: escapar(t('mistico.lendarioNv', { nivel: NIVEL_LENDARIO_MISTICO })),
          classe: 'novo',
        })}`, 'mega')}
      ${dlgFrase('', t('mistico.usarLead'))}
      <div class="dlg-bolas">${bolas}</div>
      <p class="dlg-bolas-nota">${t('mistico.usarBoost', { boost: pctMistico(chanceCapturaMistica(5, 2)) })}</p>
      ${dlgSelos(
        dlgSelo('cadeado', escapar(t('mistico.seloTicket')), 'perigo'),
        dlgSelo('alerta', escapar(t('mistico.seloUmaBola')), 'ouro'),
      )}
      ${temBola ? '' : dlgAviso(t('mistico.semBola'))}`,
    rotuloSim: t('mistico.entrar'),
    aoConfirmar: () => enviar({ t: 'mistico.entrar' }),
  });
}

/**
 * A escolha da bola, com o lendário no chão. Aberta pelo evento `misticoCaiu` e, na falta dele
 * (aba recarregada no meio), pelo snapshot — o `prazo` é a chave que impede abrir duas vezes.
 *
 * Fechar a janela de qualquer jeito (o botão, o fundo, o Esc) arremessa a MELHOR bola: é a mesma
 * escolha que o servidor faz sozinho quando o prazo acaba, e não há jeito de fechar que desperdice
 * a tentativa. Clicar numa bola específica arremessa aquela.
 */
let misticoEscolha = null;

function abrirEscolhaBolaMistica(info) {
  if (!info || misticoEscolha?.prazo === info.prazo) return;
  const escolha = { prazo: info.prazo, feito: false };
  misticoEscolha = escolha;
  const jogar = (ballId) => {
    if (escolha.feito) return;
    escolha.feito = true;
    enviar({ t: 'mistico.bola', ballId });
  };
  const bolas = estado.eu?.balls ?? {};
  const melhor = BOLAS_MISTICAS_DA_MELHOR.find((id) => (bolas[id] ?? 0) > 0) ?? null;

  const arte = document.createElement('div');
  arte.className = 'mst-escolha';
  const sprite = spritePokemon({ speciesId: info.speciesId }, 96);
  sprite.classList.add('mst-lendario');
  arte.appendChild(sprite);
  const fila = document.createElement('div');
  fila.className = 'mst-bolas';
  for (const id of [...BOLAS_MISTICAS_DA_MELHOR].reverse()) {
    const qtd = bolas[id] ?? 0;
    const bt = document.createElement('button');
    bt.type = 'button';
    bt.className = `mst-bola${id === melhor ? ' melhor' : ''}`;
    bt.disabled = qtd <= 0;
    bt.title = nomeDaBola(id);
    bt.appendChild(iconeBola(id, 32));
    bt.insertAdjacentHTML('beforeend',
      `<b>${escapar(pctMistico(info.chances?.[id] ?? 0))}</b><small>×${num(qtd)}</small>`);
    bt.onclick = (ev) => {
      ev.stopPropagation();
      jogar(id);
      fecharRecompensa();
    };
    fila.appendChild(bt);
  }
  arte.appendChild(fila);

  const segundos = () => Math.max(0, Math.ceil((info.prazo - agoraSincronizado()) / 1000));
  mostrarRecompensa({
    nivel: 3,
    confete: 0,
    classe: 'rc-mistico',
    faixa: t('mistico.caiuFaixa'),
    lead: t('mistico.caiuLead'),
    nome: info.nome,
    sub: `<span class="mst-prazo">${t('mistico.caiuSub', { s: segundos() })}</span>`
      + (info.boost ? `<br><span class="mst-boost">${t('mistico.comBoost')}</span>` : ''),
    arte,
    rotuloOk: melhor
      ? t('mistico.jogarMelhor', { bola: nomeDaBola(melhor), pct: pctMistico(info.chances?.[melhor] ?? 0) })
      : t('mistico.semBolaOk'),
    aoFechar: () => { if (melhor != null) jogar(melhor); },
  });
  // O relógio do arremesso automático, enquanto esta janela estiver aberta.
  const relogio = setInterval(() => {
    const el = document.querySelector('.recompensa.rc-mistico .mst-prazo');
    if (!el || escolha.feito) return clearInterval(relogio);
    el.textContent = t('mistico.caiuSub', { s: segundos() });
  }, 500);
}

/** A bola saiu (escolhida ou automática): a janela de escolha, se ainda aberta, some. */
function fecharEscolhaMisticaSeAberta() {
  if (!misticoEscolha || misticoEscolha.feito) return;
  misticoEscolha.feito = true;
  if (document.querySelector('.recompensa.rc-mistico')) fecharRecompensa();
}

/**
 * O fim da arena: capturou (a revelação mais alta do jogo, com confete) ou escapou. Espera a
 * animação da bola terminar na cena antes de cobrir a tela — o suspense é a parte boa.
 */
function revelarFimMistico(e) {
  setTimeout(() => {
    if (e.capturou) {
      mostrarRecompensa({
        nivel: 4,
        confete: 140,
        faixa: t('mistico.capturouFaixa'),
        lead: t('mistico.capturouLead'),
        nome: `${e.shiny ? prefixoShiny() : ''}${e.nome}`,
        sub: t('mistico.capturouSub', { nivel: num(e.level ?? NIVEL_LENDARIO_MISTICO), pot: e.potencia ?? '?' }),
        arte: spritePokemon({ speciesId: e.speciesId, shiny: !!e.shiny }, 128),
      });
      return;
    }
    const sprite = spritePokemon({ speciesId: e.speciesId, shiny: !!e.shiny }, 112);
    sprite.classList.add('mst-fugiu');
    mostrarRecompensa({
      nivel: -1,
      faixa: t(e.erro ? 'mistico.erroFaixa' : 'mistico.escapouFaixa'),
      lead: t(e.semBola ? 'mistico.semBolaLead' : e.erro ? 'mistico.erroLead' : 'mistico.escapouLead'),
      nome: `${e.shiny ? prefixoShiny() : ''}${e.nome ?? ''}`,
      sub: t(e.erro ? 'mistico.erroSub' : 'mistico.escapouSub'),
      arte: sprite,
    });
  }, e.capturou || !e.semBola ? 1600 : 200);
}

/**
 * O MysticTicket que caiu do boss ganha tela própria, como a peça de TM — é o drop mais raro do
 * boss por muito, e passar batido numa linha de log seria desperdiçar o momento.
 */
function mostrarRevelacaoTicketMistico({ qtd = 1, aoFechar = null, lote = false } = {}) {
  mostrarRecompensa({
    nivel: 4,
    confete: 90,
    faixa: t('mistico.ticketFaixa'),
    lead: t('mistico.ticketLead'),
    nome: qtd > 1 ? `${nomeItem(MYSTIC_TICKET_ID, 'MysticTicket')} ×${qtd}` : nomeItem(MYSTIC_TICKET_ID, 'MysticTicket'),
    sub: t('mistico.ticketSub'),
    arte: imagemRecompensa(iconeItem(MYSTIC_TICKET_ID) ?? '/img/itens/mystic-ticket.png', 'rc-img-pixel'),
    aoFechar,
    lote,
  });
}

// ---------------------------------------------------------------- chocadeira

/** O estado da chocadeira no snapshot, sempre limpo (a tela não confia em campo nenhum cru). */
const chocadeiraDe = (e) => normalizarChocadeira(e?.chocadeira);

/** "abre em 02/10, 18:30" — o dia e a hora locais em que o ovo abre. */
const quandoAbre = (fim) => new Date(fim).toLocaleString(undefined, {
  day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit',
});

/** Um ovo clicado na bolsa: abre a aba Chocadeira já com ele escolhido. */
function abrirChocadeiraComOvo(ovoId) {
  estado.chcOvoSel = OVO_POR_ID.has(ovoId) ? ovoId : null;
  if (primeiroSlotLivre(chocadeiraDe(estado.eu)) == null) toast(t('chocadeira.semLivre'));
  estado.abaBolsa = 'chocadeira';
  // `abrirModal`, e não só o corpo: a fileira de abas também precisa acender a Chocadeira.
  abrirModal('bolsa');
}

/** Liberar mais uma chocadeira: a mesma compra do card da Loja VIP, com a confirmação de preço. */
function comprarChocadeira() {
  const total = chocadeiraDe(estado.eu).total;
  if (total >= CHOCADEIRAS_MAX) return toast(t('chocadeira.limite'));
  // As vagas da conta como fileira de luzes: as que já são suas acesas, a que está sendo
  // liberada piscando, o resto apagado. "3 de 6" vira desenho.
  const vagas = Array.from({ length: CHOCADEIRAS_MAX }, (_, i) =>
    `<i class="${i < total ? 'tem' : i === total ? 'nova' : ''}"></i>`).join('');
  confirmar({
    titulo: t('chocadeira.liberarTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArteArquivo('/img/itens/chocadeira.png', 64),
        nome: escapar(t('chocadeira.nomeN', { n: total + 1, max: CHOCADEIRAS_MAX })),
        sub: `<span class="dlg-vagas">${vagas}</span>`,
        classe: 'novo',
      }), 'ouro')}
      ${dlgCusto({ moeda: 'diamante', valor: PRECO_CHOCADEIRA_DIAMANTES, saldo: Number(estado.eu?.diamonds ?? 0) })}
      ${dlgSelos(dlgSelo('check', escapar(t('chocadeira.seloSempre')), 'bom'))}`,
    rotuloSim: t('chocadeira.liberarSim', { preco: PRECO_CHOCADEIRA_DIAMANTES }),
    aoConfirmar: () => enviar({ t: 'loja.comprar', id: 'chocadeira' }),
  });
}

function colocarOvo(slot, ovoId) {
  estado.chcOvoSel = null;
  enviar({ t: 'chocadeira.colocar', slot, ovo: ovoId });
}

/** Os "25%" escritos na tela saem do MESMO fator que o servidor usa para descontar a espera. */
const PCT_BULBO = Math.round((1 - BULBO_FATOR) * 100);

/**
 * Aquecer o ovo de uma chocadeira com o Absorb Bulb: 3 💎, a espera cai 25% na hora, e a lamparina
 * quebra quando esse ovo abrir.
 *
 * A confirmação diz as TRÊS coisas — o preço que sai agora, o que ele ganha e que a lamparina não
 * sobrevive ao ovo. É uma compra pequena e repetível: quem clica sem ler isso compraria a segunda
 * achando que ainda tem a primeira.
 *
 * `chcAcendendo` guarda o espaço pedido para a montagem seguinte saber que a luz é NOVA e rodar a
 * animação de acender. Ele fica marcado enquanto a compra não volta: quem decide se acendeu é o
 * snapshot, não o clique — uma compra recusada (sem saldo) nunca acende nada.
 */
function aquecerOvo(slot, def) {
  const horas = def ? Math.round(def.horas * BULBO_FATOR) : 0;
  // O ovo frio, a lamparina em cima da seta com o "−25%", e o ovo aquecido do outro lado: o
  // relógio de cada um é o que muda, então é ele que vai embaixo de cada ovo.
  const ovo = (h, classe) => dlgAtor({
    arte: def?.itemId ? dlgArteItem(def.itemId, 56) : dlgArteArquivo('/img/itens/mystery-egg.png', 56),
    nome: `${num(h)}h`,
    sub: escapar(nomeItem(def?.itemId ?? 0, def?.nome ?? '')),
    classe,
  });
  confirmar({
    titulo: t('chocadeira.acenderTitulo'),
    texto: `
      ${dlgPalco(`
        ${ovo(def?.horas ?? 0, '')}
        ${dlgSeta({ arquivo: '/img/itens/absorb-bulb.png', qtd: '×1', rotulo: `−${PCT_BULBO}%` })}
        ${ovo(horas, 'novo')}`, 'ouro')}
      ${dlgCusto({ moeda: 'diamante', valor: PRECO_BULBO_DIAMANTES, saldo: Number(estado.eu?.diamonds ?? 0) })}
      ${dlgFrase('', t('chocadeira.acenderLead', { n: slot + 1, pct: PCT_BULBO }))}
      ${dlgSelos(dlgSelo('alerta', escapar(t('chocadeira.seloQuebra')), 'perigo'))}`,
    rotuloSim: t('chocadeira.acenderSim', { preco: PRECO_BULBO_DIAMANTES }),
    aoConfirmar: () => {
      estado.chcAcendendo = slot;
      enviar({ t: 'loja.comprar', id: 'bulbo', slot });
    },
  });
}

/**
 * A linha da lamparina no pé de um espaço: o selo de quem já está aquecido, ou o botão de aquecer.
 *
 * SÓ EM ESPAÇO COM OVO. É a regra do servidor desenhada na tela (ver `motivoRecusaAcender`): a
 * lamparina não existe fora de um ovo, então num espaço livre ou trancado não há botão nenhum para
 * clicar — e não há como comprar antes para usar depois.
 */
function montarLuzDoSlot(card, slot, ovo, def) {
  if (!ovo) return;
  if (ovo.luz === true) {
    card.insertAdjacentHTML('beforeend', `
      <div class="chc-luz acesa" title="${escapar(t('chocadeira.luzAcesaDica', { pct: PCT_BULBO }))}">
        <img class="chc-bulbo" src="/img/itens/absorb-bulb.png" width="18" height="18" alt="">
        <span>${t('chocadeira.luzAcesa', { pct: PCT_BULBO })}</span>
      </div>`);
    return;
  }
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = 'chc-luz apagada';
  bt.innerHTML = `<img class="chc-bulbo" src="/img/itens/absorb-bulb.png" width="18" height="18" alt="">
    <span>${t('chocadeira.acender', { preco: PRECO_BULBO_DIAMANTES })}</span>`;
  bt.title = t('chocadeira.luzDica', { pct: PCT_BULBO, preco: PRECO_BULBO_DIAMANTES });
  bt.onclick = () => aquecerOvo(slot, def);
  card.appendChild(bt);
}

/**
 * A aba CHOCADEIRA da bolsa: os seis espaços lado a lado — chocando (com a barra e a hora em que
 * abre), livre (com os ovos que o jogador tem para pôr ali) ou trancado (50 💎 para liberar).
 *
 * Remontada a cada snapshot, como a grade da bolsa: ela não tem campo de texto nem rolagem que se
 * perca. O que anda sozinho entre um snapshot e outro é só o relógio (`tiqueChocadeira`).
 */
function montarChocadeira(host) {
  const e = estado.eu;
  const est = chocadeiraDe(e);
  const itens = e?.items ?? {};
  const meusOvos = OVOS.map((o) => ({ ...o, q: Number(itens[o.itemId]) || 0 }));
  const sel = estado.chcOvoSel && (itens[OVO_POR_ID.get(estado.chcOvoSel)?.itemId] ?? 0) > 0 ? estado.chcOvoSel : null;
  if (!sel) estado.chcOvoSel = null;
  const agora = agoraSincronizado();

  const raiz = document.createElement('div');
  raiz.className = 'chc';
  raiz.innerHTML = `
    <div class="chc-topo">
      <img class="chc-topo-ico" src="/img/itens/chocadeira.png" width="48" height="48" alt="">
      <div class="chc-topo-txt">
        <b>${t('chocadeira.titulo')}</b>
        <span>${t('chocadeira.intro', { p2: OVO_POR_ID.get('p2').horas, p3: OVO_POR_ID.get('p3').horas, p4: OVO_POR_ID.get('p4').horas })}</span>
      </div>
      <div class="chc-conta">${num(est.total)}/${CHOCADEIRAS_MAX}</div>
    </div>
    ${sel ? `<div class="chc-sel pot-${escapar(sel)}">
      <img src="/img/itens/ovo-${escapar(sel)}.png" width="28" height="28" alt="">
      <span>${t('chocadeira.escolhaSlot', { ovo: escapar(nomeItem(OVO_POR_ID.get(sel).itemId)) })}</span>
      <button type="button" class="chc-sel-cancelar" id="chc-cancelar">${t('chocadeira.cancelar')}</button>
    </div>` : ''}`;

  const grade = document.createElement('div');
  grade.className = 'chc-grade';
  for (let slot = 0; slot < CHOCADEIRAS_MAX; slot++) {
    const card = document.createElement('div');
    const ovo = slot < est.total ? ovoNoSlot(est, slot) : null;
    const aceso = ovo?.luz === true;
    const numero = `<span class="chc-num">${slot + 1}</span>`;
    if (slot >= est.total) {
      card.className = 'chc-slot trancado';
      card.innerHTML = `${numero}
        <img class="chc-maquina" src="/img/itens/chocadeira.png" width="56" height="56" alt="">
        <span class="chc-cadeado" aria-hidden="true">🔒</span>
        <b>${t('chocadeira.trancada')}</b>
        <button type="button" class="chc-liberar">${t('chocadeira.liberar', { preco: PRECO_CHOCADEIRA_DIAMANTES })}</button>`;
      card.querySelector('.chc-liberar').onclick = comprarChocadeira;
    } else if (ovo) {
      const def = OVO_POR_ID.get(ovo.ovo);
      const pct = Math.max(0, Math.min(100, ((agora - ovo.inicio) / (ovo.fim - ovo.inicio)) * 100));
      card.className = `chc-slot ocupado pot-${def.id}${aceso ? ' aceso' : ''}`;
      card.innerHTML = `${numero}
        <img class="chc-ovo" src="/img/itens/ovo-${def.id}.png" width="56" height="56" alt="">
        <b>${escapar(nomeItem(def.itemId))}</b>
        <div class="chc-barra" data-inicio="${ovo.inicio}" data-fim="${ovo.fim}"><i style="width:${pct.toFixed(1)}%"></i></div>
        <span class="chc-falta" data-fim="${ovo.fim}">${escapar(t('chocadeira.falta', { tempo: tempoCurto(ovo.fim - agora) }))}</span>
        <small>${escapar(t('chocadeira.abreEm', { quando: quandoAbre(ovo.fim) }))}</small>`;
      montarLuzDoSlot(card, slot, ovo, def);
    } else {
      card.className = `chc-slot livre${sel ? ' alvo' : ''}`;
      card.innerHTML = `${numero}
        <img class="chc-maquina" src="/img/itens/chocadeira.png" width="56" height="56" alt="">
        <b>${t('chocadeira.livre')}</b>
        <div class="chc-acoes"></div>`;
      const acoes = card.querySelector('.chc-acoes');
      if (sel) {
        const bt = document.createElement('button');
        bt.type = 'button';
        bt.className = `chc-por pot-${sel}`;
        bt.textContent = t('chocadeira.chocarAqui');
        bt.onclick = () => colocarOvo(slot, sel);
        acoes.appendChild(bt);
      } else if (meusOvos.some((o) => o.q > 0)) {
        for (const o of meusOvos.filter((x) => x.q > 0)) {
          const bt = document.createElement('button');
          bt.type = 'button';
          bt.className = `chc-por pot-${o.id}`;
          bt.innerHTML = `<img src="/img/itens/ovo-${o.id}.png" width="18" height="18" alt=""> ${escapar(t('chocadeira.chocarOvo', { pot: o.potencia, n: num(o.q) }))}`;
          bt.onclick = () => colocarOvo(slot, o.id);
          acoes.appendChild(bt);
        }
      } else {
        acoes.innerHTML = `<small>${t('chocadeira.semOvos')}</small>`;
      }
    }
    // A luz que ACABOU de chegar ganha a piscada de lâmpada velha firmando (`chc-acende`), uma vez
    // só: a classe sai no fim da animação e a montagem seguinte já encontra `chcAcendendo` nulo.
    if (aceso && estado.chcAcendendo === slot) {
      card.classList.add('acendendo');
      estado.chcAcendendo = null;
      card.addEventListener('animationend', () => card.classList.remove('acendendo'), { once: true });
    }
    grade.appendChild(card);
  }
  raiz.appendChild(grade);

  // Os ovos na bolsa e o caminho para comprar mais.
  const rodape = document.createElement('div');
  rodape.className = 'chc-rodape';
  rodape.innerHTML = `
    <span class="chc-rodape-rot">${t('chocadeira.seusOvos')}</span>
    ${meusOvos.map((o) => `<span class="chc-meu pot-${o.id}${o.q ? '' : ' zero'}">
      <img src="/img/itens/ovo-${o.id}.png" width="22" height="22" alt="">P${o.potencia} ×${num(o.q)}</span>`).join('')}
    <button type="button" class="chc-comprar" id="chc-ir-market">${t('chocadeira.irMarket')}</button>`;
  raiz.appendChild(rodape);
  raiz.insertAdjacentHTML('beforeend', `<div class="af-aviso-pequeno">${t('chocadeira.rodape')}</div>`);

  host.appendChild(raiz);
  $('#chc-cancelar')?.addEventListener('click', () => {
    estado.chcOvoSel = null;
    pintarBolsaCorpo();
  });
  $('#chc-ir-market')?.addEventListener('click', () => {
    estado.abaMarket = 'compra';
    estado.catCompra = 'ovos';
    abrirModal('market');
  });
}

/** O relógio da aba: o tempo que falta e a barra de cada ovo, a cada segundo, sem remontar nada. */
function tiqueChocadeira() {
  if (estado.modalAberto !== 'bolsa' || estado.abaBolsa !== 'chocadeira') return;
  const agora = agoraSincronizado();
  for (const el of document.querySelectorAll('.chc-falta[data-fim]')) {
    el.textContent = t('chocadeira.falta', { tempo: tempoCurto(Number(el.dataset.fim) - agora) });
  }
  for (const el of document.querySelectorAll('.chc-barra[data-fim]')) {
    const ini = Number(el.dataset.inicio);
    const fim = Number(el.dataset.fim);
    const pct = Math.max(0, Math.min(100, ((agora - ini) / (fim - ini)) * 100));
    const barra = el.querySelector('i');
    if (barra) barra.style.width = `${pct.toFixed(1)}%`;
  }
}
setInterval(tiqueChocadeira, 1000);

/** Os ovos no Market NPC: um card por potência, com o tempo de choca e a cor do card de potência. */
function pintarOvosNpc(grade) {
  grade.classList.add('mk-grade-ovos');
  const precoServidor = new Map((estado.itensCompraveis ?? []).map((x) => [x.itemId, x.preco]));
  const aviso = document.createElement('div');
  aviso.className = 'mk-ovos-aviso';
  const est = chocadeiraDe(estado.eu);
  aviso.innerHTML = t('chocadeira.avisoMarket', { livres: est.total - est.ovos.length, total: est.total });
  grade.appendChild(aviso);
  for (const o of OVOS) {
    // O preço cobrado é o do SERVIDOR (`itensCompraveis`); o do módulo é só a reserva de uma aba
    // que ainda não recebeu o welcome.
    const preco = precoServidor.get(o.itemId) ?? o.preco;
    const ctd = contadorCompra(preco);
    const { total, bt } = acaoComTotal(t('mk.comprar'), preco, ctd, { validarOuro: true });
    bt.onclick = () => enviar({ t: 'shop.buy', kind: 'item', id: o.itemId, qty: ctd.ler() });
    const card = cardMarket({
      chave: `ovo${o.id}`,
      nome: nomeItem(o.itemId, o.nome),
      sub: t('chocadeira.subMarket', { pot: o.potencia, horas: o.horas }),
      preco,
      acao: [ctd.cx, total, bt],
      classe: `mk-ovo pot-${o.id}`,
    });
    card.querySelector('.mk-ico').appendChild(iconeArquivo(`/img/itens/ovo-${o.id}.png`, 48));
    grade.appendChild(card);
  }
}

/** O ovo abriu: a revelação do pokémon, no nível de raridade da potência (shiny é o topo). */
function revelarOvoChocado(e) {
  const def = OVO_POR_ID.get(e.ovo);
  const pk = e.pokemon ?? {};
  mostrarRecompensa({
    nivel: pk.shiny ? 4 : ({ 2: 1, 3: 2, 4: 3 })[def?.potencia] ?? 1,
    confete: pk.shiny ? 90 : def?.potencia === 4 ? 30 : 0,
    faixa: t('chocadeira.chocouFaixa'),
    lead: t('chocadeira.chocouLead', { ovo: nomeItem(def?.itemId ?? 0, def?.nome ?? '') }),
    nome: `${pk.shiny ? prefixoShiny() : ''}${pk.nome ?? ''}`,
    // O ovo aquecido diz, aqui, que a lamparina foi junto com ele: é o único momento em que dá
    // para avisar sem atrapalhar, e evita o "cadê a minha lamparina?" no ovo seguinte.
    sub: t('chocadeira.chocouSub', { nivel: num(pk.level ?? 1), pot: pk.potencia ?? def?.potencia ?? '?' })
      + (e.luz ? ` ${t('chocadeira.luzQuebrou')}` : ''),
    arte: spritePokemon({ speciesId: pk.speciesId, shiny: !!pk.shiny }, 112),
  });
}

// ------------------------------------------------------------- bônus Twitch
//
// +15% de XP do treinador e do pokémon para quem assiste a uma live oficial LOGADO numa conta da
// Twitch vinculada, e +1% por live oficial a mais aberta ao mesmo tempo. O vínculo sai daqui (o botão leva ao site da Twitch e volta em
// `/app?twitch=<resultado>`); quem acha o jogador no chat é o vigia do servidor, uma vez por
// minuto. Esta tela não confirma nada — ela explica, leva para a Twitch e mostra o que o
// servidor achou, do mesmo jeito que o Vote & Ganhe.

/** O que a tela desenhou por último — o snapshot só a remonta quando o bloco `twitch` muda. */
let ultimaAssinaturaTwitch = '';

/** O bonequinho de "espectadores", ao lado do número de quem assiste a uma live (como na Twitch). */
const GLIFO_ESPECTADOR = `<svg class="tw-espect-ico" viewBox="0 0 20 20" aria-hidden="true"><path fill="currentColor" d="M10 2.5a3.8 3.8 0 1 1 0 7.6 3.8 3.8 0 0 1 0-7.6zM3 17c0-3.2 3.1-5.1 7-5.1s7 1.9 7 5.1v.8H3z"/></svg>`;

function renderTwitch() {
  return `<div class="vt-modal tw-modal" id="tw-corpo"></div>`;
}

function montarTwitch() {
  const host = $('#tw-corpo');
  if (!host) return;
  const tw = estado.eu?.twitch ?? null;
  ultimaAssinaturaTwitch = JSON.stringify(tw);
  if (!tw) {
    host.innerHTML = `<div class="vt-desligado">${t('twitch.desligado')}</div>`;
    return;
  }
  const pct = Number(tw.pct) || 0;
  const extra = Number(tw.extra) || 0;
  const emLives = Number(tw.emLives) || 0;
  const linkDe = (canal) => `https://www.twitch.tv/${encodeURIComponent(String(canal ?? ''))}`;
  const login = `<b>${escapar(tw.login ?? '')}</b>`;
  const lives = Array.isArray(tw.lives) ? tw.lives : [];
  const oficiais = Array.isArray(tw.oficiais) ? tw.oficiais : [];

  // OS CANAIS OFICIAIS, um por linha e cada linha é o link do canal. Quem está no ar ganha o selo
  // verde "AO VIVO" e sobe para o topo; o resto fica apagado, com "offline". A ordem dentro de cada
  // grupo é a do servidor — o faasii primeiro, depois os streamers na ordem em que entraram.
  // Ao vivo primeiro, e entre os ao vivo quem tem mais espectadores em cima — a mesma ordem da Twitch.
  const noAr = new Map(lives.map((l) => [l.login, l]));
  const canais = oficiais.map((o) => {
    const l = noAr.get(o.login);
    return { ...o, nome: l?.nome || o.nome, aoVivo: !!l, espectadores: Number(l?.espectadores) || 0 };
  });
  for (const l of lives) {
    if (!canais.some((c) => c.login === l.login)) canais.push({ ...l, aoVivo: true, espectadores: Number(l.espectadores) || 0 });
  }
  canais.sort((a, b) => Number(b.aoVivo) - Number(a.aoVivo) || b.espectadores - a.espectadores);
  // O comando que liga o bônus na live de um streamer: o faasii como moderador do canal dele.
  const comandoMod = `/mod ${tw.canal ?? 'faasii'}`;
  // EM QUAL DELAS ELE JÁ ESTÁ. O servidor manda os logins (`assistindoEm`), e todos eles são de
  // canal com bônus — o vigia só consegue detectar alguém no chat que ele lê. Então a linha tem
  // três leituras, e nenhuma repete a outra:
  //
  //   já está lá   → o selo verde no lugar do dourado. O dourado existe para ele ESCOLHER uma live;
  //                  nesta ele já escolheu, e repeti-lo só tiraria espaço do que falta decidir.
  //   falta ele    → o ponto vermelho na frente da linha. É o convite do +1%.
  //   sem bônus    → nada de novo: continua o "Falta a ativação", que é problema do streamer.
  const jaEstouEm = new Set((tw.assistindoEm ?? []).map((x) => String(x).toLowerCase()));
  const linhaCanal = (c) => {
    const jaEstou = jaEstouEm.has(String(c.login).toLowerCase());
    const faltaEle = !!tw.login && c.aoVivo && c.bonus === true && !jaEstou;
    return `
        <a class="tw-canal${c.aoVivo ? ' ao-vivo' : ''}${c.bonus ? ' com-bonus' : ''}${jaEstou ? ' tw-aqui' : ''}${faltaEle ? ' tw-falta-eu' : ''}"
           href="${escapar(linkDe(c.login))}" target="_blank" rel="noopener noreferrer"
           ${faltaEle ? `title="${escapar(t('twitch.vaAte', { extra }))}"` : ''}>
          ${faltaEle ? '<i class="tw-ponto" aria-hidden="true"></i>' : ''}
          ${GLIFO_TWITCH}
          <span class="tw-canal-nome">${escapar(c.nome || c.login)}</span>
          ${jaEstou
            ? `<span class="tw-canal-aqui" title="${escapar(t('twitch.jaEstaLaDica'))}">✓ <b class="tw-aqui-longo">${t('twitch.jaEstaLa')}</b><b class="tw-aqui-curto">${t('twitch.jaEstaLaCurto')}</b></span>`
            : c.bonus === true
            // O SELO do bônus: só nos canais em que assistir dá o bônus de verdade (o faasii é
            // moderador lá). Sem o "+15%": as lives se somam (15 + 1 + 1...), e um "+15%" em cada
            // canal leria como 15 por live. No celular o "BÔNUS ATIVADO" encurta para "BÔNUS".
            ? `<span class="tw-canal-bonus" title="${escapar(t('twitch.bonusAtivadoDica', { pct, extra }))}"><i class="tw-bonus-brilho" aria-hidden="true"></i>⚡ <b class="tw-bonus-longo">${t('twitch.bonusAtivado')}</b><b class="tw-bonus-curto">${t('twitch.bonusAtivadoCurto')}</b></span>`
            // E quem ainda não deu o `/mod faasii`: o aviso aponta para a instrução logo abaixo da
            // lista. `false` de verdade, e não "sem informação" — antes da primeira apuração (o
            // boot) o campo nem vem, e aí não há selo nenhum em vez de um "falta" que pode ser falso.
            : c.bonus === false
              ? `<span class="tw-canal-falta"><span class="tw-falta-longo">${t('twitch.faltaAtivacao')}</span><span class="tw-falta-curto">${t('twitch.faltaAtivacaoCurto')}</span></span>`
              : ''}
          ${c.aoVivo
            ? `<span class="tw-canal-espect" title="${escapar(t('twitch.espectadores', { n: num(c.espectadores) }))}">${GLIFO_ESPECTADOR}${num(c.espectadores)}</span>`
            : ''}
          <span class="tw-canal-selo">${c.aoVivo
            ? `<i class="tw-verde" aria-hidden="true"></i>${t('twitch.aoVivo')}`
            : t('twitch.valorOffline')}</span>
        </a>`;
  };

  // OS OFFLINE FICAM DOBRADOS, e fechados por padrão.
  //
  // A lista oficial cresce a cada streamer parceiro novo, e quase todos estão offline a qualquer
  // hora: sem a dobra, quem abre a tela para achar uma live rola por oito linhas apagadas até a
  // única que está no ar. Fechado, sobra o que ele veio ver — e o botão continua dizendo quantos
  // existem, para a lista não parecer menor do que é.
  //
  // `estado.twOfflineAberto` guarda a escolha da sessão: o modal é remontado a cada snapshot do
  // servidor (a contagem de espectadores muda sozinha), e sem isso a lista se fecharia na cara de
  // quem acabou de abri-la.
  const aoVivo = canais.filter((c) => c.aoVivo);
  const offline = canais.filter((c) => !c.aoVivo);
  const offlineAberto = !!estado.twOfflineAberto;
  const listaCanais = `
    <div class="tw-canais">
      <div class="af-secao-titulo">${t('twitch.oficiais')}</div>
      ${aoVivo.map(linhaCanal).join('')}
      ${!aoVivo.length ? `<div class="tw-ninguem">${t('twitch.ninguemAoVivo')}</div>` : ''}
      ${offline.length ? `
        <button type="button" class="tw-offline-btn${offlineAberto ? ' aberto' : ''}" id="tw-offline-btn"
                aria-expanded="${offlineAberto}" aria-controls="tw-offline-lista">
          <span>${t('twitch.offlineDobra', { n: num(offline.length) })}</span>
          <i class="tw-seta" aria-hidden="true">▾</i>
        </button>
        <div class="tw-offline-lista${offlineAberto ? ' aberto' : ''}" id="tw-offline-lista">
          <div class="tw-offline-dentro">${offline.map(linhaCanal).join('')}</div>
        </div>` : ''}
      <div class="tw-mod-dica">
        <p>${t('twitch.modDica')}</p>
        <button type="button" class="tw-mod-cmd" id="tw-copiar-mod" title="${escapar(t('twitch.copiar'))}">
          <code>${escapar(comandoMod)}</code><span>${t('twitch.copiar')}</span>
        </button>
      </div>
    </div>`;

  // O convite para virar Streamer Parceiro Oficial, logo abaixo da lista — é "entrar NESTA lista".
  // Feito para chamar o olho de propósito (moldura correndo, brilho, faíscas): é um anúncio, e o
  // público dele — quem faz live — está justamente lendo esta tela.
  const parceiro = `
    <div class="tw-parceiro">
      <span class="tw-parceiro-brilho" aria-hidden="true"></span>
      <div class="tw-parceiro-ico" aria-hidden="true">
        ${GLIFO_TWITCH}
        <i class="tw-faisca f1">✦</i><i class="tw-faisca f2">✦</i><i class="tw-faisca f3">✦</i>
      </div>
      <div class="tw-parceiro-txt">
        <span class="tw-parceiro-selo">★ ${t('twitch.parceiroSelo')}</span>
        <b>${t('twitch.parceiroTitulo')}</b>
        <span>${t('twitch.parceiroTexto', { pct })}</span>
      </div>
      <a class="tw-parceiro-btn" href="${escapar(DISCORD_URL)}" target="_blank" rel="noopener noreferrer">
        <img src="/img/social-discord.svg" width="20" height="20" alt="">
        <span>Discord</span>
      </a>
    </div>`;

  // A SOMA DAS LIVES, dentro do prêmio: a escadinha 15 → 16 → 17% e um "4+" que diz "+1% cada",
  // com o degrau em que ele está AGORA aceso e marcado "você". Quem está em 4 lives ou mais acende o
  // último, com o número dele. Um ícone da Twitch por live, para a conta se ler sem o texto.
  const degrau = ({ icones, valor, rotulo, aceso }) => `
    <div class="tw-degrau${aceso ? ' aceso' : ''}">
      ${aceso ? `<span class="tw-degrau-voce">${t('twitch.somaVoce')}</span>` : ''}
      <span class="tw-degrau-ico" aria-hidden="true">${icones}</span>
      <b class="tw-degrau-pct">${valor}</b>
      <span class="tw-degrau-rot">${rotulo}</span>
    </div>`;
  const seta = '<i class="tw-soma-seta" aria-hidden="true">›</i>';
  const soma = extra > 0 ? `
    <div class="tw-soma">
      <div class="tw-soma-titulo"><i class="tw-bonus-brilho" aria-hidden="true"></i>⚡ ${t('twitch.somaTitulo', { extra })}</div>
      <div class="tw-soma-degraus">
        ${[1, 2, 3].map((n) => degrau({
          icones: GLIFO_TWITCH.repeat(n),
          valor: `+${pct + (n - 1) * extra}%`,
          rotulo: n === 1 ? t('twitch.somaUma') : t('twitch.somaVarias', { n }),
          aceso: emLives === n,
        })).join(seta)}
        ${seta}
        ${degrau({
          icones: `${GLIFO_TWITCH.repeat(3)}<i class="tw-degrau-mais">+</i>`,
          valor: emLives >= 4 ? `+${Number(tw.pctAtual) || pct}%` : t('twitch.somaCada', { extra }),
          rotulo: t('twitch.somaVarias', { n: emLives >= 4 ? emLives : '4+' }),
          aceso: emLives >= 4,
        })}
      </div>
    </div>` : '';

  const topo = `
    <div class="vt-premio tw-premio">
      <div class="tw-premio-linha">
        <span class="vt-premio-qtd tw-premio-qtd">${GLIFO_TWITCH} +${pct}%</span>
        <span class="vt-premio-txt">${t('twitch.intro', { pct, extra })}</span>
      </div>
      ${soma}
    </div>`;

  // Sem vínculo: o convite e o botão. Com vínculo: o que o servidor achou AGORA e a conta vinculada
  // (com o desfazer ao lado, para quem vinculou a conta errada). A lista de canais e o convite de
  // parceiro valem para os dois — quem ainda não vinculou também precisa ver quem está no ar.
  const corpo = !tw.login
    ? `
      <button type="button" class="tw-botao" id="tw-vincular">${GLIFO_TWITCH}<span>${t('twitch.vincular')}</span></button>
      <div class="vt-estado tw-aviso"><span>${t('twitch.logado')}</span></div>
      ${listaCanais}
      ${parceiro}`
    : `
      ${tw.assistindo
        // Em duas lives ou mais, o status diz em quantas — é a conta que explica o 16%, 17%...
        ? `<div class="vt-estado pronto">${emLives > 1
          ? t('twitch.statusAtivoVarias', { pct: Number(tw.pctAtual) || pct, n: emLives })
          : t('twitch.statusAtivo', { pct: Number(tw.pctAtual) || pct })}</div>`
        : tw.aoVivo
          ? `<div class="vt-estado tw-procurando"><i class="tw-ponto" aria-hidden="true"></i><span>${t('twitch.statusProcurando', { login })}</span></div>`
          : `<div class="vt-estado esperando">${t('twitch.statusOffline')}</div>`}
      ${listaCanais}
      ${parceiro}
      <div class="tw-conta">
        <span>${t('twitch.vinculada', { login })}</span>
        <button type="button" class="tw-link" id="tw-desvincular">${t('twitch.desvincular')}</button>
      </div>`;

  const passos = `
    <div>
      <div class="af-secao-titulo">${t('twitch.comoTitulo')}</div>
      <ol class="vt-passos">
        <li>${t('twitch.passo1')}</li>
        <li>${t('twitch.passo2')}</li>
        <li>${t('twitch.passo3')}</li>
        <li>${t('twitch.acumula', { extra, pct2: pct + extra, pct3: pct + 2 * extra })}</li>
      </ol>
    </div>
    <div class="af-aviso-pequeno">${t('twitch.rodape')}</div>`;

  host.innerHTML = topo + corpo + passos;
  $('#tw-vincular')?.addEventListener('click', (ev) => irParaTwitch(ev.currentTarget));
  // Abrir e fechar os offline: troca a classe nos dois elementos em vez de remontar o modal — uma
  // repintura aqui recalcularia a lista inteira (e a ordem por espectadores) no meio do clique.
  $('#tw-offline-btn')?.addEventListener('click', (ev) => {
    const aberto = !estado.twOfflineAberto;
    estado.twOfflineAberto = aberto;
    ev.currentTarget.classList.toggle('aberto', aberto);
    ev.currentTarget.setAttribute('aria-expanded', String(aberto));
    $('#tw-offline-lista')?.classList.toggle('aberto', aberto);
  });
  // Copiar o `/mod faasii` num clique: é o que o streamer vai colar no chat da própria live.
  $('#tw-copiar-mod')?.addEventListener('click', () => {
    // Sem área de transferência (http puro, navegador antigo), o aviso mostra o comando para copiar à mão.
    (navigator.clipboard?.writeText(comandoMod) ?? Promise.reject(new Error('sem clipboard')))
      .then(() => toast(t('twitch.copiado', { cmd: comandoMod })))
      .catch(() => toast(comandoMod));
  });
  $('#tw-desvincular')?.addEventListener('click', () => confirmarDesvincularTwitch(login));
}

/** A corrente partida entre o seu boneco e a conta da Twitch: é isto que o botão desfaz. */
function confirmarDesvincularTwitch(login) {
  confirmar({
    titulo: t('twitch.desvincularTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteTreinador(null, null, 64), nome: escapar(estado.eu?.nick ?? '') })}
        <span class="dlg-elo" aria-hidden="true">${dlgIcone('corrente', 30)}</span>
        ${dlgAtor({
          arte: dlgArteHtml(dlgMedalha({ arte: `<span class="dlg-twitch">${GLIFO_TWITCH}</span>`, tom: 'mega' })),
          nome: escapar(login ?? ''),
          classe: 'sai',
        })}`, 'mega')}
      ${dlgFrase('', t('twitch.desvincularTexto', { login: `<b>${escapar(login ?? '')}</b>` }))}`,
    rotuloSim: t('twitch.desvincular'),
    aoConfirmar: desvincularTwitch,
  });
}

/**
 * Pede ao servidor o endereço da Twitch e troca de página. Na MESMA aba, como o login do Google:
 * um pop-up bloqueado é um botão que não faz nada. (Numa conta de admin, a mesma ida também
 * conecta o canal faasii — quem decide é o servidor, ver `/auth/twitch/iniciar`.)
 */
async function irParaTwitch(botao) {
  botao.disabled = true;
  try {
    const r = await pedirAuth('twitch/iniciar', { token: sessaoSalva()?.token });
    location.href = r.url;
  } catch (err) {
    toast(err.message);
    botao.disabled = false;
  }
}

async function desvincularTwitch() {
  try {
    await pedirAuth('twitch/desvincular', { token: sessaoSalva()?.token });
    toast(t('twitch.desvinculada'));
  } catch (err) {
    toast(err.message);
  }
}

/**
 * O aviso da volta do OAuth. Sai depois do `welcome` (e não no carregamento) porque é aí que o
 * snapshot já traz o vínculo novo — abrir o modal antes mostraria "Conectar Twitch" para quem
 * acabou de conectar.
 */
function avisarRetornoTwitch(resultado) {
  const chave = `twitch.retorno.${resultado}`;
  toast(temChave(chave) ? t(chave) : t('twitch.retorno.erro'));
  if (resultado === 'ok') abrirModal('twitch');
}

// ------------------------------------------------------------- bônus na Kick
//
// Horas de bônus compradas com os PONTOS DO CANAL de um streamer oficial na Kick: cada resgate vale
// 1 hora de +15% (XP, Capture Boost ou Secret Lure), e as horas se somam. Quem credita é o vigia do
// servidor, que lê os resgates na Kick. Esta tela explica, leva à Kick para o vínculo (que é PARA
// SEMPRE — uma conta da Kick por treinador) e mostra as horas que ele tem. Quem vinculou a conta de
// um streamer oficial vê também a caixa do canal dele.

/** O que a tela desenhou por último — o snapshot só a remonta quando o bloco `kick` muda. */
let ultimaAssinaturaKick = '';

function renderKick() {
  return `<div class="vt-modal kk-modal" id="kk-corpo"></div>`;
}

function montarKick() {
  const host = $('#kk-corpo');
  if (!host) return;
  const kk = estado.eu?.kick ?? null;
  ultimaAssinaturaKick = JSON.stringify(kk);
  if (!kk) {
    host.innerHTML = `<div class="vt-desligado">${t('kick.desligado')}</div>`;
    return;
  }
  const pct = Number(kk.pct) || 0;
  const minutos = Number(kk.minutos) || 60;
  // '1h': o tempo de UM resgate, escrito como a ficha escreve os prazos.
  const tempoResgate = tempoCurto(minutos * 60_000);
  const agora = agoraDoServidor();
  const recompensas = Array.isArray(kk.recompensas) ? kk.recompensas : [];
  const oficiais = Array.isArray(kk.oficiais) ? kk.oficiais : [];
  const nomeBonus = (tp) => escapar(t(`kick.bonus.${tp}`, { pct }));
  const linkDe = (slug) => `https://kick.com/${encodeURIComponent(String(slug ?? ''))}`;

  // AS TRÊS RECOMPENSAS: o ícone do boost da Loja de mesmo nome, quanto custa na Kick e, se ele
  // tem horas valendo, a contagem regressiva (anda no `tiqueModalKick`).
  const cartao = (r) => {
    const ate = Number(kk.bonus?.[r.tipo]) || 0;
    const ativo = ate > agora;
    return `
      <div class="kk-rec${ativo ? ' ativo' : ''}">
        <span class="kk-rec-ico" data-kk-ico="${escapar(r.tipo)}"></span>
        <b class="kk-rec-nome">${nomeBonus(r.tipo)}</b>
        <span class="kk-rec-custo">${num(r.custo)} <small>${t('kick.pontos')}</small></span>
        <span class="kk-rec-estado">${ativo
          ? `${dlgIcone('relogio', 13)}<span class="kk-tempo" data-ate="${ate}">${tempoCurto(ate - agora)}</span>`
          : escapar(t('kick.porResgate', { tempo: tempoResgate }))}</span>
      </div>`;
  };
  const topo = `
    <div class="vt-premio kk-premio">
      <div class="kk-premio-linha">
        <span class="vt-premio-qtd kk-premio-qtd">${GLIFO_KICK} +${pct}%</span>
        <span class="vt-premio-txt">${t('kick.intro', { pct, tempo: tempoResgate })}</span>
      </div>
      <div class="kk-recs">${recompensas.map(cartao).join('')}</div>
      <div class="kk-acumula">${dlgIcone('relogio', 14)}<span>${t('kick.acumula', { pct })}</span></div>
    </div>`;

  // O VÍNCULO. Sem ele, o botão e o aviso de que é para sempre — antes do clique, e não só na
  // confirmação; com ele, a conta, sem "desvincular": não existe.
  const vinculo = !(kk.vinculado ?? !!kk.login)
    ? `
      <button type="button" class="kk-botao" id="kk-vincular">${GLIFO_KICK}<span>${t('kick.vincular')}</span></button>
      <div class="kk-permanente">${dlgIcone('cadeado', 16)}<span>${t('kick.permanenteAviso')}</span></div>`
    : `
      <div class="kk-conta">${dlgIcone('cadeado', 14)}<span>${kk.login
        ? t('kick.vinculada', { login: `<b>${escapar(kk.login)}</b>` })
        : t('kick.vinculadaSemNome')}</span></div>`;

  // O CANAL DELE, para quem vinculou a conta de um streamer oficial: diz se as recompensas estão de
  // pé lá e, se não estiverem (autorização caiu, ou ele cancelou na hora do vínculo), o botão.
  const st = kk.streamer;
  const canalSt = st ? `<b>${escapar(st.nome || st.slug)}</b>` : '';
  const streamer = st ? `
    <div class="kk-streamer${st.ativo ? ' ok' : ''}">
      ${GLIFO_KICK}
      <span>${st.ativo ? t('kick.streamerOk', { canal: canalSt }) : t('kick.streamerFalta', { canal: canalSt })}</span>
      ${st.ativo ? '' : `<button type="button" class="kk-botao-mini" id="kk-conectar-canal">${t('kick.conectarCanal')}</button>`}
    </div>` : '';

  // OS CANAIS OFICIAIS: ao vivo em cima (os mais assistidos primeiro), offline dobrados — a mesma
  // gramática da lista da Twitch. O selo verde é "o resgate funciona aqui".
  const canais = [...oficiais].sort((a, b) => Number(b.aoVivo) - Number(a.aoVivo) || b.espectadores - a.espectadores);
  const linhaCanal = (c) => `
      <a class="kk-canal${c.aoVivo ? ' ao-vivo' : ''}${c.ativo ? ' com-pontos' : ''}"
         href="${escapar(linkDe(c.slug))}" target="_blank" rel="noopener noreferrer">
        ${GLIFO_KICK}
        <span class="kk-canal-nome">${escapar(c.nome || c.slug)}</span>
        ${c.ativo
          ? `<span class="kk-canal-pontos" title="${escapar(t('kick.pontosAtivosDica'))}">${t('kick.pontosAtivos')}</span>`
          : `<span class="kk-canal-falta">${t('kick.aguardandoStreamer')}</span>`}
        ${c.aoVivo
          ? `<span class="tw-canal-espect" title="${escapar(t('twitch.espectadores', { n: num(c.espectadores) }))}">${GLIFO_ESPECTADOR}${num(c.espectadores)}</span>`
          : ''}
        <span class="kk-canal-selo">${c.aoVivo ? `<i class="kk-verde" aria-hidden="true"></i>${t('twitch.aoVivo')}` : t('twitch.valorOffline')}</span>
      </a>`;
  const aoVivo = canais.filter((c) => c.aoVivo);
  const offline = canais.filter((c) => !c.aoVivo);
  const offlineAberto = !!estado.kkOfflineAberto;
  const listaCanais = `
    <div class="kk-canais">
      <div class="af-secao-titulo">${t('kick.oficiais')}</div>
      ${aoVivo.map(linhaCanal).join('')}
      ${!aoVivo.length ? `<div class="tw-ninguem">${t(canais.length ? 'kick.ninguemAoVivo' : 'kick.semCanais')}</div>` : ''}
      ${offline.length ? `
        <button type="button" class="tw-offline-btn kk-offline-btn${offlineAberto ? ' aberto' : ''}" id="kk-offline-btn"
                aria-expanded="${offlineAberto}" aria-controls="kk-offline-lista">
          <span>${t('twitch.offlineDobra', { n: num(offline.length) })}</span>
          <i class="tw-seta" aria-hidden="true">▾</i>
        </button>
        <div class="tw-offline-lista${offlineAberto ? ' aberto' : ''}" id="kk-offline-lista">
          <div class="tw-offline-dentro">${offline.map(linhaCanal).join('')}</div>
        </div>` : ''}
    </div>`;

  // O convite para virar Streamer Parceiro Oficial na Kick, logo abaixo da lista — é "entrar NESTA
  // lista". O MESMO anúncio da Twitch (moldura correndo, a caixa respirando, a faixa de luz, o ícone
  // quicando com faíscas, o botão que chacoalha), com o K no lugar do glifo e o verde da Kick no
  // lugar do roxo (`.kk-tom`): quem faz live está justamente lendo esta tela.
  const parceiro = `
    <div class="tw-parceiro kk-tom">
      <span class="tw-parceiro-brilho" aria-hidden="true"></span>
      <div class="tw-parceiro-ico" aria-hidden="true">
        ${GLIFO_KICK}
        <i class="tw-faisca f1">✦</i><i class="tw-faisca f2">✦</i><i class="tw-faisca f3">✦</i>
      </div>
      <div class="tw-parceiro-txt">
        <span class="tw-parceiro-selo">★ ${t('kick.parceiroSelo')}</span>
        <b>${t('kick.parceiroTitulo')}</b>
        <span>${t('kick.parceiroTexto', { pct })}</span>
      </div>
      <a class="tw-parceiro-btn" href="${escapar(DISCORD_URL)}" target="_blank" rel="noopener noreferrer">
        <img src="/img/social-discord.svg" width="20" height="20" alt="">
        <span>Discord</span>
      </a>
    </div>`;

  const passos = `
    <div>
      <div class="af-secao-titulo">${t('kick.comoTitulo')}</div>
      <ol class="vt-passos">
        <li>${t('kick.passo1')}</li>
        <li>${t('kick.passo2')}</li>
        <li>${t('kick.passo3', { lista: recompensas.map((r) => `<b>${nomeBonus(r.tipo)}</b> (${num(r.custo)})`).join(' · ') })}</li>
        <li>${t('kick.passo4', { tempo: tempoResgate })}</li>
      </ol>
    </div>
    <div class="af-aviso-pequeno">${t('kick.rodape')}</div>`;

  host.innerHTML = topo + vinculo + streamer + listaCanais + parceiro + passos;
  for (const el of host.querySelectorAll('[data-kk-ico]')) {
    el.replaceChildren(iconeArquivo(tipoDeBoost(el.dataset.kkIco)?.icone ?? ICONE_DIAMANTE, 28));
  }
  $('#kk-vincular')?.addEventListener('click', (ev) => irParaKick(ev.currentTarget));
  $('#kk-conectar-canal')?.addEventListener('click', (ev) => irParaKick(ev.currentTarget, { canal: true }));
  // Abrir e fechar os offline sem remontar — o mesmo cuidado do modal da Twitch.
  $('#kk-offline-btn')?.addEventListener('click', (ev) => {
    const aberto = !estado.kkOfflineAberto;
    estado.kkOfflineAberto = aberto;
    ev.currentTarget.classList.toggle('aberto', aberto);
    ev.currentTarget.setAttribute('aria-expanded', String(aberto));
    $('#kk-offline-lista')?.classList.toggle('aberto', aberto);
  });
}

/**
 * A contagem regressiva das horas no modal, no relógio do `tiqueAtivos`. Uma hora que acaba remonta
 * a tela (o cartão volta a dizer "1 h por resgate").
 */
function tiqueModalKick() {
  if (estado.modalAberto !== 'kick') return;
  const host = $('#kk-corpo');
  if (!host) return;
  const agora = agoraDoServidor();
  let venceu = false;
  for (const el of host.querySelectorAll('.kk-tempo[data-ate]')) {
    const resta = Number(el.dataset.ate) - agora;
    if (resta <= 0) venceu = true;
    else el.textContent = tempoCurto(resta);
  }
  if (venceu) montarKick();
}

/**
 * Pede ao servidor o endereço da Kick e troca de página, na MESMA aba (o motivo da Twitch).
 * `canal: true` é o "Conectar canal" do streamer oficial que já vinculou.
 */
async function irParaKick(botao, { canal = false } = {}) {
  botao.disabled = true;
  try {
    const r = await pedirAuth('kick/iniciar', { token: sessaoSalva()?.token, canal });
    location.href = r.url;
  } catch (err) {
    toast(err.message);
    botao.disabled = false;
  }
}

/**
 * A volta do OAuth da Kick. Sai depois do `welcome`, pelo motivo da Twitch. Primeiro o que
 * aconteceu com o CANAL (só para streamer oficial), depois o vínculo: `confirmar` abre a caixa que
 * mostra QUAL conta da Kick vai ficar presa a este treinador.
 */
function avisarRetornoKick({ resultado, kv, canal }) {
  if (canal) {
    const chaveCanal = `kick.canal.${canal}`;
    toast(temChave(chaveCanal) ? t(chaveCanal) : t('kick.canal.erro'));
  }
  if (resultado === 'confirmar' && kv) {
    confirmarVinculoKick(kv);
    return;
  }
  // O "Conectar canal" do modal: o aviso já saiu acima; a tela volta para o modal.
  if (resultado === 'canal') {
    abrirModal('kick');
    return;
  }
  const chave = `kick.retorno.${resultado}`;
  toast(temChave(chave) ? t(chave) : t('kick.retorno.erro'));
  if (resultado === 'ok') abrirModal('kick');
}

/**
 * O nome da conta da Kick que veio no vínculo pendente, para a caixa de confirmação. Só para
 * MOSTRAR: o pendente é assinado, e quem confere é `/auth/kick/confirmar`.
 */
function loginDoPendente(kv) {
  try {
    const corpo = String(kv).split('.')[0].replace(/-/g, '+').replace(/_/g, '/');
    const bin = atob(corpo + '='.repeat((4 - (corpo.length % 4)) % 4));
    const json = new TextDecoder().decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
    return String(JSON.parse(json)?.login ?? '');
  } catch {
    return '';
  }
}

/**
 * A confirmação do vínculo — o passo que não tem volta. O seu boneco preso pela corrente à conta
 * da Kick que voltou do OAuth, o aviso de que é para sempre e os selos.
 */
function confirmarVinculoKick(kv) {
  const login = loginDoPendente(kv);
  const nick = estado.eu?.nick ?? '';
  confirmar({
    titulo: t('kick.confirmarTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteTreinador(null, null, 64), nome: escapar(nick) })}
        <span class="dlg-elo" aria-hidden="true">${dlgIcone('corrente', 30)}</span>
        ${dlgAtor({
          arte: dlgArteHtml(dlgMedalha({ arte: `<span class="dlg-kick">${GLIFO_KICK}</span>`, tom: 'verde' })),
          nome: escapar(login),
          classe: 'novo',
        })}`, 'verde')}
      ${dlgFrase(t('kick.confirmarFrase', { login: `<b>${escapar(login)}</b>`, nick: `<b>${escapar(nick)}</b>` }))}
      ${dlgAviso(t('kick.confirmarAviso'), { icone: 'cadeado' })}
      ${dlgSelos(dlgSelo('cadeado', t('kick.seloPermanente'), 'perigo'), dlgSelo('pessoa', t('kick.seloUmaConta'), 'info'))}`,
    rotuloSim: t('kick.confirmarSim'),
    aoConfirmar: () => confirmarKickNoServidor(kv),
  });
}

async function confirmarKickNoServidor(kv) {
  try {
    const r = await pedirAuth('kick/confirmar', { token: sessaoSalva()?.token, kv });
    toast(t('kick.retorno.ok', { login: r.login ?? '' }));
    abrirModal('kick');
  } catch (err) {
    toast(err.message);
  }
}

// ------------------------------------------------------------- o holofote
//
// O PEDESTAL COM HOLOFOTE da Calculadora, do Comparar e das duas fichas: o vão escuro, o feixe
// caindo de cima, o pedestal aceso e o pokémon em pé nele. A luz tem a COR DA NOTA — a mesma
// paleta das dez faixas (`--calc-cor`, ver `.calc-nota` no estilo) — e o quanto ela FAZ sobe com
// a nota pela escada de raridade do DESIGN.md §1: nas faixas de baixo é só a cor; Bom e Forte
// ganham o halo; Poderoso e Mítico, os raios girando; Lendário e Divino, raios mais depressa e
// faíscas. Se o Fraco brilhasse, o Divino não teria para onde subir. Tudo para em
// `prefers-reduced-motion` (no CSS).

/** De 0 a 4: o degrau da escada em que cada faixa da nota acende o holofote. */
const NIVEL_HOLOFOTE = {
  'extremamente-fraco': 0,
  fraco: 0,
  mediano: 1,
  razoavel: 1,
  bom: 2,
  forte: 2,
  poderoso: 3,
  mitico: 3,
  legendario: 4,
  divino: 4,
};

/** As classes do holofote para uma faixa da nota — ou para um `tom` fixo quando não há nota. */
function classesHolofote(faixa, tom = null) {
  if (faixa && NIVEL_HOLOFOTE[faixa] != null) return `hf hf-n${NIVEL_HOLOFOTE[faixa]} ${faixa}`;
  return `hf hf-n1 hf-tom-${tom ?? 'vazio'}`;
}

/**
 * O palco. `arte` é marcação `data-dlg-*` (o `hidratarDialogo` desenha) ou um nó posto depois
 * em `.hf-arte`; `rodape` vai embaixo do pedestal (a placa da nota, o nome). As três camadas de
 * luz são `span` vazios de propósito: o CSS liga cada uma conforme o degrau (`hf-n0`…`hf-n4`).
 */
function holofoteHtml({ id = '', faixa = null, tom = null, classe = '', arte = '', rodape = '' } = {}) {
  return `
    <div class="${classesHolofote(faixa, tom)}${classe ? ` ${classe}` : ''}"${id ? ` id="${id}"` : ''}${faixa ? ` data-faixa="${faixa}"` : ''}>
      <div class="hf-cena">
        <span class="hf-feixe" aria-hidden="true"></span>
        <span class="hf-raios" aria-hidden="true"></span>
        <span class="hf-faiscas" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></span>
        <span class="hf-pedestal" aria-hidden="true"></span>
        <span class="hf-arte">${arte}</span>
      </div>
      ${rodape}
    </div>`;
}

/**
 * Troca a faixa de um holofote já na tela, sem refazer o palco — o sprite fica onde está (refazer
 * o canvas a cada tecla recomeçaria a animação dele). Devolve `+1`/`-1`/`0`: se a nota subiu,
 * desceu ou ficou na mesma faixa, para quem quiser comemorar a subida.
 */
function pintarFaixaHolofote(el, faixa, tom = null) {
  if (!el) return 0;
  const ordem = FAIXAS_NOTA.map((f) => f.id);
  const antes = ordem.indexOf(el.dataset.faixa ?? '');
  const depois = ordem.indexOf(faixa ?? '');
  const extras = [...el.classList].filter((c) => !/^(hf|hf-n\d|hf-tom-.+|hf-sobe|hf-desce)$/.test(c) && !ordem.includes(c));
  el.className = `${classesHolofote(faixa, tom)}${extras.length ? ` ${extras.join(' ')}` : ''}`;
  el.dataset.faixa = faixa ?? '';
  if (antes < 0 || depois < 0 || antes === depois) return 0;
  const sentido = depois > antes ? 1 : -1;
  // A subida de faixa ganha o estalo; a descida, só um afundar curto. A classe sai sozinha no fim
  // da animação, e recolocá-la exige um reflow para o navegador recomeçar o desenho.
  el.classList.remove('hf-sobe', 'hf-desce');
  void el.offsetWidth;
  el.classList.add(sentido > 0 ? 'hf-sobe' : 'hf-desce');
  return sentido;
}

/** O sprite do pedestal: encaixado (o bicho enche a caixa, como no ator do diálogo) e animado. */
function spritePedestal(looktype, px, comum = null) {
  const reserva = comum ?? looktype;
  return spriteAnimado(looktype, px, 3, () => iconeEspecie(reserva, px), null, { encaixar: true });
}

/**
 * Põe o sprite no pedestal só quando ele MUDA. A chave (`looktype:px`) fica no próprio nó: a
 * Calculadora repinta o palco a cada dígito, e um canvas novo por tecla reiniciaria a animação e
 * piscaria o bicho.
 */
function porNoPedestal(alvo, looktype, px, comum = null) {
  if (!alvo) return;
  const chave = `${Number(looktype) || 0}:${px}`;
  if (alvo.dataset.sprite === chave) return;
  alvo.dataset.sprite = chave;
  alvo.replaceChildren(looktype ? spritePedestal(looktype, px, comum) : silhuetaPedestal());
}

/** O "?" do pedestal vazio: ainda não há quem pôr em cima. */
const silhuetaPedestal = () => {
  const el = document.createElement('span');
  el.className = 'hf-silhueta';
  el.textContent = '?';
  return el;
};

/**
 * A ESCADA DAS DEZ FAIXAS, embaixo do número: os degraus até a faixa atual acesos, cada um na
 * cor dele, e a marca no ponto exato da nota (6,482 cai a 64,8% da régua). É o que transforma
 * "6,482" em "falta pouco para o Mítico".
 */
function escadaDaNota(nota) {
  const n = Number(nota);
  const idx = Number.isFinite(n) ? FAIXAS_NOTA.findIndex((f) => n <= f.ate) : -1;
  const atual = idx < 0 ? (Number.isFinite(n) ? FAIXAS_NOTA.length - 1 : -1) : idx;
  const pos = Number.isFinite(n) ? Math.max(0, Math.min(100, n * 10)) : null;
  return `
    <div class="calc-escada" aria-hidden="true">
      ${FAIXAS_NOTA.map((f, i) => `<i class="nota-tinta ${f.id}${i <= atual ? ' on' : ''}${i === atual ? ' aqui' : ''}"></i>`).join('')}
      ${pos != null ? `<b class="calc-escada-marca" style="left:${pos.toFixed(1)}%"></b>` : ''}
    </div>`;
}

/**
 * Repinta a escada no lugar quando ela já está na tela: os degraus trocam de classe e a marca
 * DESLIZA até a nota nova (o `transition` do `left`). Refeita por `innerHTML`, a marca pularia.
 */
function pintarEscadaDaNota(host, nota) {
  if (!host) return;
  const escada = host.querySelector('.calc-escada');
  const marca = escada?.querySelector('.calc-escada-marca');
  const n = Number(nota);
  if (!escada || !marca || !Number.isFinite(n)) {
    host.innerHTML = escadaDaNota(nota);
    return;
  }
  const idx = FAIXAS_NOTA.findIndex((f) => n <= f.ate);
  const atual = idx < 0 ? FAIXAS_NOTA.length - 1 : idx;
  [...escada.querySelectorAll('i')].forEach((el, i) => {
    el.classList.toggle('on', i <= atual);
    el.classList.toggle('aqui', i === atual);
  });
  marca.style.left = `${Math.max(0, Math.min(100, n * 10)).toFixed(1)}%`;
}

/** Quem pediu menos movimento não vê o número correndo — ele só troca. */
const menosMovimento = () => matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ?? false;

/**
 * Anima o número da nota até `para`, com três casas e vírgula. Uma animação por elemento: o
 * dígito seguinte cancela a anterior e parte do número que está NA TELA, então digitar rápido
 * não empilha nada nem faz o número voltar.
 */
function animarNota(el, para, ms = 420) {
  if (!el) return;
  const de = Number(el.dataset.valor);
  el.dataset.valor = String(para);
  cancelAnimationFrame(el._raf ?? 0);
  if (!Number.isFinite(de) || de === para || menosMovimento()) {
    el.textContent = notaEmTexto(para);
    return;
  }
  const t0 = performance.now();
  const passo = (agora) => {
    const p = Math.min(1, (agora - t0) / ms);
    const e = 1 - (1 - p) ** 3;
    el.textContent = notaEmTexto(de + (para - de) * e);
    if (p < 1) el._raf = requestAnimationFrame(passo);
  };
  el._raf = requestAnimationFrame(passo);
}

/** A nota de um pokémon (ou `null`) e a faixa dela — a conta da Calculadora, para as fichas. */
function notaEFaixa(pk) {
  const nota = notaDoPokemon(pk);
  if (nota == null || !Number.isFinite(Number(nota))) return null;
  return { nota: Number(nota), faixa: faixaDaNota(nota) };
}

// ---------------------------------------------------- calculadora pokémon
//
// A nota mora em `shared/nota-pokemon.mjs` porque é regra, não desenho — e porque o servidor
// pode querer usá-la um dia (ordenar o Mercado por nota, por exemplo). Aqui só entram os três
// campos, o placar e as barras.

/**
 * O que os campos têm agora. Sobrevive a fechar e reabrir o modal, dentro da sessão.
 *
 * `origem` é preenchida quando os números vieram da FICHA de um pokémon (o botão "Calcular
 * pokémon", em `calcularEstePokemon`). Serve para a tela dizer de quem é a nota — sem isso o
 * jogador que abre a calculadora minutos depois não tem como saber se aqueles três números
 * ainda são os do bicho que ele estava avaliando.
 */
/**
 * O nível com que a aba "Comparar" nasce preenchida.
 *
 * Era `GINASIO_CAP_NIVEL` — enquanto o ginásio tinha teto, começar no teto era começar no
 * único nível em que a comparação valia para todo mundo. Sem teto isso deixou de ser uma
 * regra e virou o que sempre foi na prática: um ponto de partida razoável, que o jogador
 * troca no campo ao lado. Fica 150 porque é o nível mínimo de treinador para registrar time
 * (`GINASIO_NIVEL_MIN`), ou seja, o piso de quem abre esta tela para decidir um time.
 */
const CALC_NIVEL_PADRAO = 150;

const calc = {
  aba: 'nota',
  speciesId: null,
  iv: 99,
  ivs: null,
  ivManual: false,
  qualidade: 1.1,
  potencia: 1,
  shiny: false,
  origem: null,
  especieBusca: '',
  comp: {
    a: { speciesId: null, level: CALC_NIVEL_PADRAO, iv: 99, ivs: null, ivManual: false, qualidade: 1.1, potencia: 1, shiny: false, tm: null, especieBusca: '' },
    b: { speciesId: null, level: CALC_NIVEL_PADRAO, iv: 99, ivs: null, ivManual: false, qualidade: 1.1, potencia: 1, shiny: false, tm: null, especieBusca: '' },
  },
};

const CALC_IV_KEYS = ['hp', 'atk', 'def', 'spAtk', 'spDef', 'speed'];

/** Decimal com vírgula, como o resto do jogo escreve número (`num` também é sempre pt-BR). */
const virgula = (s) => String(s).replace('.', ',');

/** "6,482" — três casas, que é a resolução em que a nota separa dois pokémon parecidos. */
const notaEmTexto = (n) => virgula(n.toFixed(3));

const ROTULO_POTENCIA_CALC = ['I', 'II', 'III', 'IV', 'V'];

/** Espécies da Pokédex com sprite registrado — o mesmo catálogo da dex. */
function especiesCalculadora() {
  return especiesPokedex();
}

function filtrarEspeciesCalculadora(q) {
  const busca = String(q ?? '').trim().toLowerCase();
  if (!busca) return especiesCalculadora().slice(0, 40);
  return especiesCalculadora().filter((c) => {
    const dex = String(dexExibicao(c.pokeId));
    return c.name.toLowerCase().includes(busca) || dex.includes(busca);
  }).slice(0, 40);
}

function especieCalcAtual() {
  return calc.speciesId ? estado.especies.get(calc.speciesId) ?? null : null;
}

/**
 * Os IVs da Calculadora. A ENTRADA é só a grade "IV por stat" — a soma deixou de ser digitada —,
 * então o que vale é o que está nela (`calc.ivs`); antes da primeira mexida, a grade nasce com a
 * soma padrão repartida pelos seis stats.
 */
function ivsDaCalculadora() {
  return calc.ivs ?? ivsDeSoma(calc.iv);
}

/**
 * Uma grade "IV por stat" como está na TELA: os seis valores (cada um preso entre 1 e 32) e se
 * todos ali são de fato inteiros dessa faixa — o que estiver fora vira o aviso de sempre, e a
 * nota espera o número ficar certo em vez de ser calculada com um valor que a tela não mostra.
 */
function ivsDaGrade(grade) {
  const ivs = {};
  let valido = true;
  for (const el of grade?.querySelectorAll('[data-iv-stat]') ?? []) {
    const n = Number(el.value);
    if (!Number.isInteger(n) || n < IV_POR_STAT.min || n > IV_POR_STAT.max) valido = false;
    ivs[el.dataset.ivStat] = Math.min(IV_POR_STAT.max, Math.max(IV_POR_STAT.min, Math.round(n) || IV_POR_STAT.min));
  }
  return { ivs, valido };
}

/** A soma, só para ler: fica ao lado do título da grade e anda junto com ela. */
const textoSomaIv = (ivs) => t('calc.ivSoma', { n: num(somaIv(ivs)) });

function sincronizarIvSomaCalc() {
  const soma = CALC_IV_KEYS.reduce((s, k) => s + (Number(calc.ivs?.[k]) || 0), 0);
  if (Number.isFinite(soma) && soma >= IV_MIN && soma <= IV_MAX) calc.iv = soma;
}

function htmlEspecieAtualCalc() {
  const esp = especieCalcAtual();
  if (!esp) return '';
  const dex = dexExibicao(esp.pokeId);
  return `
    <div class="calc-especie-atual" id="calc-especie-atual">
      <span class="calc-especie-ico" id="calc-especie-ico-atual"></span>
      <span class="calc-especie-nome">#${num(dex)} ${escapar(esp.name)}</span>
      <button type="button" class="calc-especie-limpar" id="calc-especie-limpar" title="${t('calc.especieLimpar')}">×</button>
    </div>`;
}

function cfgComp(lado) {
  return calc.comp[lado];
}

function especieLadoComp(lado) {
  const id = cfgComp(lado).speciesId;
  return id ? estado.especies.get(id) ?? null : null;
}

/** Os IVs de um lado do Comparar — a mesma regra de `ivsDaCalculadora`: a grade é a entrada. */
function ivsLadoComp(lado) {
  const cfg = cfgComp(lado);
  return cfg.ivs ?? ivsDeSoma(cfg.iv);
}

function sincronizarIvSomaComp(lado) {
  const cfg = cfgComp(lado);
  const soma = CALC_IV_KEYS.reduce((s, k) => s + (Number(cfg.ivs?.[k]) || 0), 0);
  if (Number.isFinite(soma) && soma >= IV_MIN && soma <= IV_MAX) cfg.iv = soma;
}

function htmlEspecieAtualComp(lado) {
  const esp = especieLadoComp(lado);
  if (!esp) return '';
  const dex = dexExibicao(esp.pokeId);
  return `
    <div class="calc-especie-atual" id="calc-comp-${lado}-especie-atual">
      <span class="calc-especie-ico" id="calc-comp-${lado}-especie-ico"></span>
      <span class="calc-especie-nome">#${num(dex)} ${escapar(esp.name)}</span>
      <button type="button" class="calc-especie-limpar" data-comp-limpar="${lado}" title="${t('calc.especieLimpar')}">×</button>
    </div>`;
}

function chipsPotComp(lado) {
  const cfg = cfgComp(lado);
  return ROTULO_POTENCIA_CALC
    .map((r, i) => `<button type="button" class="calc-pot${cfg.potencia === i + 1 ? ' on' : ''}" data-comp-pot="${lado}" data-pot="${i + 1}">${r}</button>`)
    .join('');
}

/**
 * Os botões da TM elemental — um por tipo da ESPÉCIE escolhida, e nenhum a mais.
 *
 * O disco só existe nos tipos do próprio pokémon (`tipoTmPermitido`, no servidor), então
 * oferecer os 18 aqui seria oferecer o que o jogo recusa. Com tipo duplo dá para comparar os
 * dois discos, que é uma pergunta real: num Tyranitar (ROCK/DARK) o disco de ROCK e o de DARK
 * batem diferente conforme quem está do outro lado.
 */
function chipsTmComp(lado) {
  const cfg = cfgComp(lado);
  const esp = especieLadoComp(lado);
  const tipos = esp ? [esp.type1, esp.type2].filter(Boolean) : [];
  if (!tipos.length) return '';
  const botao = (tipo, rotulo) => {
    const on = (cfg.tm ?? null) === tipo;
    return `<button type="button" class="calc-tm${on ? ' on' : ''}" aria-pressed="${on}"
      data-comp-tm="${lado}" data-tm="${tipo ?? ''}">${rotulo}</button>`;
  };
  return botao(null, t('calc.tmNenhum')) + tipos.map((tp) => botao(tp, `TM ${tp}`)).join('');
}

/** Quanto da barrinha de um IV está cheia (1 a 32 → 3% a 100%). */
const pctIvCalc = (v) =>
  Math.round((Math.min(IV_POR_STAT.max, Math.max(0, Number(v) || 0)) / IV_POR_STAT.max) * 100);

/**
 * Uma célula da grade "IV por stat": o rótulo, o campo e uma barrinha que enche de 1 a 32 na cor
 * da ficha (vermelho → verde, `classeIvStat`). A barra é o que deixa ler a grade de relance — seis
 * números iguais na largura escondem que o ATK está em 4 e o resto em 30.
 */
function celulaIvCalc(k, valor) {
  const v = Number(valor) || 1;
  return `<label class="calc-iv-stat">
    <span class="calc-iv-stat-nome">${rotuloStat(k)}</span>
    <input class="calc-iv-inp" type="number" inputmode="numeric" min="1" max="32" step="1"
           data-iv-stat="${k}" value="${v}">
    <span class="calc-iv-barra ${classeIvStat(v)}" aria-hidden="true"><i style="width:${pctIvCalc(v)}%"></i></span>
  </label>`;
}

/** As barrinhas andam junto com o dígito, sem refazer a grade (o foco ficaria no caminho). */
function pintarBarrasIv(grade) {
  for (const inp of grade?.querySelectorAll('[data-iv-stat]') ?? []) {
    const barra = inp.parentElement?.querySelector('.calc-iv-barra');
    if (!barra) continue;
    const v = Number(inp.value);
    barra.className = `calc-iv-barra ${classeIvStat(v)}`;
    barra.firstElementChild.style.width = `${pctIvCalc(v)}%`;
  }
}

/**
 * A QUALIDADE: o campo de sempre (é nele que se cola "1,37" lido de um anúncio) e, ao lado, a
 * régua de 0,80 a 1,80 para quem quer ARRASTAR e ver o holofote mudar de cor. Os dois andam
 * juntos — quem digita move a régua, quem arrasta reescreve o campo.
 */
function campoQualidadeCalc(id, valor, desligado) {
  const v = Number(valor) || 1;
  return `<div class="calc-campo calc-campo-q">
    <span class="calc-campo-topo">
      <span>${t('calc.qualidade')}</span>
      <em>${virgula(QUALIDADE_MIN.toFixed(2))}–${virgula(QUALIDADE_MAX.toFixed(2))}</em>
    </span>
    <div class="calc-q-linha">
      <input id="${id}" class="calc-q-num" type="text" inputmode="decimal" value="${virgula(v)}"${desligado ? ' disabled' : ''}>
      <input id="${id}-range" class="calc-q-range" type="range" min="${QUALIDADE_MIN}" max="${QUALIDADE_MAX}" step="0.01"
             value="${v}" aria-label="${escapar(t('calc.qualidade'))}"${desligado ? ' disabled' : ''}>
    </div>
  </div>`;
}

/** Liga o par campo ↔ régua da qualidade. `aoMudar` é quem repinta a tela. */
function ligarQualidadeCalc(id, aoMudar) {
  const campo = $(`#${id}`);
  const regua = $(`#${id}-range`);
  if (!campo || !regua) return;
  regua.oninput = () => {
    campo.value = virgula(Number(regua.value).toFixed(2));
    aoMudar();
  };
  campo.addEventListener('input', () => {
    const n = Number(String(campo.value).replace(',', '.'));
    if (Number.isFinite(n) && n >= QUALIDADE_MIN && n <= QUALIDADE_MAX) regua.value = String(n);
    aoMudar();
  });
}

function htmlIvGridComp(lado) {
  const ivs = ivsLadoComp(lado);
  return `<div class="calc-campo">
    <span class="calc-campo-topo">
      <span>${t('calc.ivPorStat')}</span>
      <em id="calc-comp-${lado}-ivsoma">${textoSomaIv(ivs)}</em>
    </span>
    <div class="calc-iv-grid calc-iv-grid-comp" id="calc-comp-${lado}-iv-grid">
      ${CALC_IV_KEYS.map((k) => celulaIvCalc(k, ivs[k])).join('')}
    </div>
  </div>`;
}

function renderLadoComp(lado, rotulo) {
  const cfg = cfgComp(lado);
  const esp = especieLadoComp(lado);
  return `
    <div class="calc-comp-lado lado-${lado}" data-comp-lado="${lado}">
      <p class="calc-comp-lado-titulo"><span class="calc-comp-letra">${lado.toUpperCase()}</span>${rotulo}</p>
      <div class="calc-campos calc-comp-campos">
        <div class="calc-campo">
          <span class="calc-campo-topo"><span>${t('calc.especie')}</span></span>
          <div class="calc-especie-caixa" id="calc-comp-${lado}-especie-caixa">
            ${htmlEspecieAtualComp(lado)}
            <input id="calc-comp-${lado}-especie-busca" class="calc-especie-busca" type="search"
              placeholder="${t('calc.especieBuscar')}" autocomplete="off"
              value="${escapar(cfg.especieBusca)}"${esp ? ' hidden' : ''}>
            <div class="calc-especie-lista hidden" id="calc-comp-${lado}-especie-lista"></div>
          </div>
        </div>
        <label class="calc-campo">
          <span class="calc-campo-topo">
            <span>${t('calc.compNivel')}</span><em>${t('calc.compNivelCap', { cheio: ARENA_NIVEL_CHEIO })}</em>
          </span>
          <input id="calc-comp-${lado}-nivel" type="number" inputmode="numeric" min="1" max="999999" step="1" value="${cfg.level}"${esp ? '' : ' disabled'}>
        </label>
        ${esp ? htmlIvGridComp(lado) : ''}
        ${campoQualidadeCalc(`calc-comp-${lado}-q`, cfg.qualidade, !esp)}
        <div class="calc-campo">
          <span class="calc-campo-topo"><span>${t('calc.potencia')}</span><em>I–V</em></span>
          <div class="calc-pots" id="calc-comp-${lado}-pots">${chipsPotComp(lado)}</div>
        </div>
        <div class="calc-campo">
          <span class="calc-campo-topo">
            <span>${t('calc.shiny')}</span><em>${t('calc.shinyHint')}</em>
          </span>
          <button type="button" id="calc-comp-${lado}-shiny" class="calc-shiny${cfg.shiny ? ' on' : ''}" aria-pressed="${cfg.shiny}" data-comp-shiny="${lado}"${esp ? '' : ' disabled'}>✨ ${t('calc.shiny')}</button>
        </div>
        ${esp ? `<div class="calc-campo">
          <span class="calc-campo-topo">
            <span>${t('calc.tm')}</span><em>${t('calc.tmHint', { power: num(TM_ELEMENTAL_POWER) })}</em>
          </span>
          <div class="calc-tms" id="calc-comp-${lado}-tms">${chipsTmComp(lado)}</div>
        </div>` : ''}
      </div>
    </div>`;
}

/**
 * A aba Comparar: a ARENA em cima (os dois no pedestal, cada holofote na cor da nota DELE, e o VS
 * no meio), o resultado logo abaixo — o cabo de guerra das chances — e os campos dos dois lados
 * embaixo. A ordem é a da pergunta: "quem ganha?" primeiro, "com que números?" depois.
 */
function renderCalculadoraComparar() {
  const palco = (lado) => holofoteHtml({
    id: `calc-comp-${lado}-palco`,
    tom: 'vazio',
    classe: `calc-comp-palco lado-${lado}`,
    // A coroa mora no palco desde o começo e só aparece no `.vence` — pendurá-la na hora do
    // resultado faria o palco do vencedor mudar de altura a cada dígito.
    rodape: `<span class="calc-comp-coroa" aria-hidden="true">${dlgIcone('coroa', 22)}</span>
      <div class="calc-comp-placa" id="calc-comp-${lado}-placa"></div>`,
  });
  return `
    <p class="calc-ajuda calc-intro">${t('calc.compIntro')}</p>
    <div class="calc-comp-arena">
      ${palco('a')}
      <div class="calc-comp-vs" aria-hidden="true"><span>${t('calc.compVs')}</span></div>
      ${palco('b')}
    </div>
    <div class="calc-comp-resultado" id="calc-comp-resultado"></div>
    <div class="calc-comp-grid">
      ${renderLadoComp('a', t('calc.compLadoA'))}
      ${renderLadoComp('b', t('calc.compLadoB'))}
    </div>
    <div class="calc-rodape">
      <button type="button" class="calc-limpar" id="calc-comp-limpar">${t('calc.compLimpar')}</button>
      <span class="calc-erro" id="calc-comp-erro"></span>
    </div>
    <p class="calc-ajuda calc-comp-variacao">${t('calc.compVariacao', {
      min: virgula(String(VARIACAO_DANO_MIN)),
      max: virgula(String(VARIACAO_DANO_MAX)),
    })}</p>`;
}

function renderCalculadora() {
  return `
    <div class="calc-modal">
      <div class="calc-abas" role="tablist">
        <button type="button" class="calc-aba${calc.aba === 'nota' ? ' on' : ''}" data-calc-aba="nota" role="tab" aria-selected="${calc.aba === 'nota'}">${t('calc.abaNota')}</button>
        <button type="button" class="calc-aba${calc.aba === 'comparar' ? ' on' : ''}" data-calc-aba="comparar" role="tab" aria-selected="${calc.aba === 'comparar'}">${t('calc.abaComparar')}</button>
      </div>
      ${calc.aba === 'comparar' ? renderCalculadoraComparar() : renderCalculadoraNota()}
    </div>`;
}

function renderCalculadoraNota() {
  const chips = ROTULO_POTENCIA_CALC
    .map((r, i) => `<button type="button" class="calc-pot p${i + 1}${calc.potencia === i + 1 ? ' on' : ''}" data-pot="${i + 1}">${r}</button>`)
    .join('');
  const o = calc.origem;
  const origem = o
    ? `<p class="calc-origem">${dlgIcone('copia', 14)}<span>${t('calc.daFicha', {
        nome: `${o.shiny ? prefixoShiny() : ''}${escapar(o.nome)}${o.nivel ? ` ${t('painel.nivelCurto')}${num(o.nivel)}` : ''}`,
      })}${o.dono ? ` · ${escapar(o.dono)}` : ''}</span></p>`
    : '';
  const esp = especieCalcAtual();
  const ivs = ivsDaCalculadora();
  // `calc-campo-largo`: ocupa a linha inteira da bancada (ver `.calc-campos` no estilo). A grade
  // de IV é a única entrada de IV — a soma só aparece para ler, ao lado do título.
  const ivGrid = esp
    ? `<div class="calc-campo calc-campo-largo">
        <span class="calc-campo-topo">
          <span>${t('calc.ivPorStat')}</span>
          <em id="calc-iv-soma">${textoSomaIv(ivs)}</em>
        </span>
        <div class="calc-iv-grid" id="calc-iv-grid">
          ${CALC_IV_KEYS.map((k) => celulaIvCalc(k, ivs[k])).join('')}
        </div>
      </div>`
    : '';
  const statsCaixa = esp
    ? `<section class="calc-cartao calc-stats-caixa" id="calc-stats">
        <h4 class="calc-cartao-tit">${dlgIcone('estrela', 14)}${t('calc.statsTitulo')}</h4>
        <p class="calc-stats-lider" id="calc-stats-lider"></p>
        <div class="calc-stats-lista" id="calc-stats-lista"></div>
        <p class="calc-stats-rodape">${t('calc.statsRodape')}</p>
      </section>`
    : '';
  // O PALCO: o holofote com o bicho no pedestal e, embaixo dele, a placa da nota, a escada das
  // dez faixas, quanto falta para a próxima e se ele passa no Mercado. Nasce apagado ("?"); quem
  // acende é `pintarCalculadora`, que só troca o sprite quando a espécie ou o shiny mudam.
  const palco = holofoteHtml({
    id: 'calc-palco',
    tom: 'vazio',
    classe: 'calc-palco',
    rodape: `
      <div class="calc-placa">
        <div class="calc-nota calc-nota-vazia extremamente-fraco" id="calc-nota">
          <span class="calc-nota-valor"><b id="calc-valor">${esp ? '—' : t('calc.semEspecie')}</b><span class="calc-nota-de">${t('calc.de10')}</span></span>
          <span class="calc-nota-rotulo" id="calc-rotulo"></span>
        </div>
        <div class="calc-escada-host" id="calc-escada">${escadaDaNota(null)}</div>
        <p class="calc-prox" id="calc-prox"></p>
        <p class="calc-mercado" id="calc-mercado"></p>
      </div>`,
  });
  return `
      <p class="calc-ajuda calc-intro">${t('calc.intro')}</p>
      ${origem}
      <div class="calc-estudio">
        <div class="calc-bancada">
          <div class="calc-campos">
            <div class="calc-campo calc-campo-largo">
              <span class="calc-campo-topo"><span>${t('calc.especie')}</span></span>
              <div class="calc-especie-caixa" id="calc-especie-caixa">
                ${htmlEspecieAtualCalc()}
                <input id="calc-especie-busca" class="calc-especie-busca" type="search"
                  placeholder="${t('calc.especieBuscar')}" autocomplete="off"
                  value="${escapar(calc.especieBusca)}"${esp ? ' hidden' : ''}>
                <div class="calc-especie-lista hidden" id="calc-especie-lista"></div>
              </div>
            </div>
            ${ivGrid}
            ${campoQualidadeCalc('calc-q', calc.qualidade, !esp)}
            <div class="calc-campo">
              <span class="calc-campo-topo"><span>${t('calc.potencia')}</span><em>I–V</em></span>
              <div class="calc-pots" id="calc-pots">${chips}</div>
            </div>
            <div class="calc-campo calc-campo-largo">
              <span class="calc-campo-topo">
                <span>${t('calc.shiny')}</span><em>${t('calc.shinyHint')}</em>
              </span>
              <button type="button" id="calc-shiny" class="calc-shiny${calc.shiny ? ' on' : ''}" aria-pressed="${calc.shiny}"${esp ? '' : ' disabled'}>✨ ${t('calc.shiny')}</button>
            </div>
          </div>
          <div class="calc-rodape">
            <button type="button" class="calc-limpar" id="calc-limpar">${t('calc.limpar')}</button>
            <span class="calc-erro" id="calc-erro"></span>
          </div>
        </div>
        <div class="calc-palco-col">${palco}</div>
      </div>

      <div class="calc-res" id="calc-res">
        <div class="calc-potenciais">
          <section class="calc-cartao calc-potencial hidden" id="calc-potencial"></section>
          <section class="calc-cartao calc-potencial calc-potencial-mega hidden" id="calc-potencial-mega"></section>
        </div>
        ${esp ? `<div class="calc-dupla">
          <section class="calc-cartao calc-cartao-eixos">
            <h4 class="calc-cartao-tit">${dlgIcone('soma', 14)}${t('calc.eixosTitulo')}</h4>
            <div class="calc-eixos" id="calc-eixos"></div>
          </section>
          ${statsCaixa}
        </div>
        <section class="calc-cartao calc-combate" id="calc-combate"></section>` : `<div id="calc-eixos" hidden></div>
        <div id="calc-combate" hidden></div>`}
      </div>
      <p class="calc-ajuda">${esp ? t('calc.rodapeEspecie', { nome: esp.name }) : t('calc.rodape')}</p>`;
}

/** "faltam 0,883 para Mediano" — a próxima faixa, na cor dela. No Divino, o topo da escada. */
function pintarProximaFaixa(el, nota) {
  if (!el) return;
  const i = FAIXAS_NOTA.findIndex((f) => nota <= f.ate);
  const prox = i >= 0 ? FAIXAS_NOTA[i + 1] : null;
  if (!prox) {
    el.innerHTML = `${dlgIcone('coroa', 12)}<span>${t('calc.topoEscada')}</span>`;
    return;
  }
  // A faixa é "até" inclusive: para entrar na próxima, a nota tem de passar do teto desta — na
  // resolução de três casas em que ela é mostrada, um milésimo acima.
  const falta = Math.max(0.001, FAIXAS_NOTA[i].ate - nota + 0.001);
  el.innerHTML = `${dlgIcone('subir', 12)}<span>${t('calc.faltaFaixa', {
    n: notaEmTexto(falta),
    faixa: `<b class="nota-tinta ${prox.id}">${escapar(t(`calc.faixa.${prox.id}`))}</b>`,
  })}</span>`;
}

/** O selo do Mercado embaixo da nota: passa (✓) ou fica de fora (✗) — shiny e P5 passam sempre. */
function pintarMercadoCalc(el, nota, usado) {
  if (!el) return;
  const ok = usado.shiny || usado.potencia >= POTENCIA_MAX || atendeNotaMercado(nota);
  el.className = `calc-mercado${ok ? ' ok' : ''}`;
  el.innerHTML = `${dlgIcone(ok ? 'check' : 'xis', 12)}<span>${escapar(t(
    ok ? 'calc.potencialMercadoOk' : 'calc.potencialMercadoNao',
    { min: virgula(String(MERCADO_POKEMON_MIN.nota)) },
  ))}</span>`;
}

/**
 * As caixas de POTENCIAL (evolução final e mega): um cartão por destino, com o sprite, a nota que
 * este MESMO nascimento teria lá e se ela passa no Mercado. A conta é a de sempre — o mesmo
 * nascimento medido na régua de outra espécie, com o piso DELA (`notaAncestrais`).
 *
 * O cartão é botão: leva a Calculadora para aquele destino com os mesmos números, que é a pergunta
 * seguinte de quem leu "Venusaur 4,2". E os cartões só são REFEITOS quando a espécie ou o shiny
 * mudam — cada um tem um sprite animado, e refazê-los a cada dígito recriaria os canvas. No resto
 * das vezes só a nota, a faixa e o selo de cada um trocam.
 *
 * A MEGA não sai de `evolucoesFinais`: o elo "espécie → mega" mora fora do `evolvesToId` de
 * propósito (ver `shared/megas.mjs`). Ela é procurada na espécie escolhida E em cada forma final —
 * um Larvitar lê a Mega Tyranitar, uma Kirlia lê as do Gardevoir e do Gallade.
 */
function pintarPotenciais(esp, usado, ivs, refino) {
  const finais = evolucoesFinais(esp, (id) => estado.especies.get(id));
  const megas = [];
  for (const base of [esp, ...finais]) {
    const info = megaDaFicha(base);
    const mega = info ? estado.especies.get(info.pokeId) : null;
    if (mega && !megas.some((m) => m.pokeId === mega.pokeId)) megas.push(mega);
  }
  const projetar = (alvo) => {
    const basesAlvo = basesDaEspecie(alvo);
    const basesRef = refino ? basesComRefino(alvo, refino) : basesAlvo;
    return notaPokemon({
      ...usado,
      ivs,
      bases: basesRef,
      basesLimites: basesAlvo,
      basesAncestrais: alvo?.notaAncestrais ?? null,
    });
  };
  const caixas = [
    ['#calc-potencial', 'calc.potencialTitulo', 'subir', finais],
    ['#calc-potencial-mega', 'calc.potencialMegaTitulo', 'raio', megas],
  ];
  for (const [sel, titulo, icone, alvos] of caixas) {
    const el = $(sel);
    if (!el) continue;
    if (!alvos.length) {
      el.innerHTML = '';
      el.classList.add('hidden');
      delete el.dataset.chave;
      continue;
    }
    const ordenados = [...alvos].sort((a, b) => a.name.localeCompare(b.name));
    const chave = `${esp.pokeId}:${calc.shiny ? 1 : 0}`;
    if (el.dataset.chave !== chave) {
      el.dataset.chave = chave;
      el.innerHTML = `
        <h4 class="calc-cartao-tit">${dlgIcone(icone, 14)}${t(titulo)}</h4>
        <div class="calc-pot-cards">${ordenados.map((alvo) => `
          <button type="button" class="calc-pot-card" data-calc-ir="${alvo.pokeId}"
                  title="${escapar(t('calc.potencialVer', { nome: alvo.name }))}">
            <span class="calc-pot-card-arte">${dlgArteLt(calc.shiny ? (lookShinyFicha(alvo) ?? alvo.looktype) : alvo.looktype, 46, alvo.looktype)}</span>
            <span class="calc-pot-card-txt">
              <b class="calc-pot-card-nome">${escapar(alvo.name)}</b>
              <span class="calc-pot-card-nota"></span>
              <em class="calc-potencial-mercado"></em>
            </span>
          </button>`).join('')}</div>`;
      hidratarDialogo(el);
      for (const b of el.querySelectorAll('[data-calc-ir]')) b.onclick = () => irParaEspecieCalc(Number(b.dataset.calcIr));
    }
    el.classList.remove('hidden');
    for (const alvo of ordenados) {
      const card = el.querySelector(`[data-calc-ir="${alvo.pokeId}"]`);
      if (!card) continue;
      const proj = projetar(alvo);
      const mercadoOk = usado.shiny || usado.potencia >= POTENCIA_MAX || atendeNotaMercado(proj.nota);
      card.className = `calc-pot-card nota-tinta ${proj.faixa}`;
      card.querySelector('.calc-pot-card-nota').innerHTML =
        `N= <b>${notaEmTexto(proj.nota)}</b> <em>${escapar(t(`calc.faixa.${proj.faixa}`))}</em>`;
      const m = card.querySelector('.calc-potencial-mercado');
      m.className = `calc-potencial-mercado${mercadoOk ? ' ok' : ''}`;
      m.textContent = t(mercadoOk ? 'calc.potencialMercadoOk' : 'calc.potencialMercadoNao', {
        min: virgula(String(MERCADO_POKEMON_MIN.nota)),
      });
    }
  }
}

/** O cartão de potencial leva a Calculadora para o destino, com o MESMO nascimento da grade. */
function irParaEspecieCalc(pokeId) {
  if (!estado.especies.get(pokeId)) return;
  calc.ivs = ivsDaCalculadora();
  calc.ivManual = true;
  // Os números deixam de ser "os da ficha": agora são uma projeção noutra espécie.
  calc.origem = null;
  calc.speciesId = pokeId;
  calc.especieBusca = '';
  montarCalculadora(hostCalculadora());
}

/** Lê os campos e pinta o palco, a placa da nota e os cartões. */
function pintarCalculadora() {
  const erro = $('#calc-erro');
  if (!erro) return;

  const esp = especieCalcAtual();
  const icoAtual = $('#calc-especie-ico-atual');
  if (icoAtual && esp?.looktype && !icoAtual.firstChild) {
    icoAtual.appendChild(spriteAnimado(esp.looktype, 30));
  }
  const palco = $('#calc-palco');
  const arte = palco?.querySelector('.hf-arte');

  if (!esp) {
    erro.textContent = t('calc.avisoEspecie');
    pintarFaixaHolofote(palco, null, 'vazio');
    porNoPedestal(arte, 0, 96);
    const caixa = $('#calc-nota');
    if (caixa) {
      caixa.className = 'calc-nota calc-nota-vazia extremamente-fraco';
      const valor = $('#calc-valor');
      valor.textContent = t('calc.semEspecie');
      delete valor.dataset.valor;
      $('#calc-rotulo').textContent = '';
    }
    const escada = $('#calc-escada');
    if (escada) escada.innerHTML = escadaDaNota(null);
    for (const id of ['#calc-prox', '#calc-mercado']) {
      const el = $(id);
      if (el) el.innerHTML = '';
    }
    $('#calc-eixos').innerHTML = '';
    for (const id of ['#calc-potencial', '#calc-potencial-mega']) {
      const potencial = $(id);
      if (!potencial) continue;
      potencial.innerHTML = '';
      potencial.classList.add('hidden');
      delete potencial.dataset.chave;
    }
    const combate = $('#calc-combate');
    if (combate) combate.innerHTML = '';
    pintarListaEspeciesCalc();
    return;
  }

  // O bicho no pedestal: a forma shiny quando o interruptor está ligado (e ela existe).
  porNoPedestal(arte, calc.shiny ? (lookShinyFicha(esp) ?? esp.looktype) : esp.looktype, 96, esp.looktype);
  palco?.classList.toggle('hf-shiny', !!calc.shiny);

  // A soma que a nota usa é a da GRADE — é a única entrada de IV (ver `ivsDaGrade`).
  const gradeEl = $('#calc-iv-grid');
  const grade = ivsDaGrade(gradeEl);
  pintarBarrasIv(gradeEl);
  const ivBruto = somaIv(grade.ivs);
  const qBruto = Number(String($('#calc-q')?.value ?? '').replace(',', '.'));

  const avisos = [];
  if (!grade.valido) avisos.push(t('calc.avisoIv', { min: IV_POR_STAT.min, max: IV_POR_STAT.max }));
  if (!Number.isFinite(qBruto) || qBruto < QUALIDADE_MIN || qBruto > QUALIDADE_MAX) {
    avisos.push(t('calc.avisoQualidade', {
      min: virgula(QUALIDADE_MIN.toFixed(2)),
      max: virgula(QUALIDADE_MAX.toFixed(2)),
    }));
  }
  erro.textContent = avisos.join(' · ');

  const usado = {
    iv: Number.isFinite(ivBruto) ? ivBruto : calc.iv,
    qualidade: Number.isFinite(qBruto) ? qBruto : calc.qualidade,
    potencia: calc.potencia,
    shiny: calc.shiny,
  };
  if (!avisos.length) {
    calc.iv = usado.iv;
    calc.qualidade = usado.qualidade;
  }

  const ivs = ivsDaCalculadora();

  const pkOrigem = calc.origem && fichaPokemonAberto?.speciesId === calc.speciesId
    ? fichaPokemonAberto
    : null;
  const basesOrigem = basesDaEspecie(esp);
  const basesComRef = pkOrigem?.refino
    ? basesComRefino(esp, pkOrigem.refino)
    : basesOrigem;

  if (avisos.length) return;

  const r = notaPokemon({
    ...usado,
    ivs,
    bases: basesComRef,
    basesLimites: basesOrigem,
    basesAncestrais: esp?.notaAncestrais ?? null,
  });
  const caixa = $('#calc-nota');
  caixa.className = `calc-nota ${r.faixa}`;
  animarNota($('#calc-valor'), r.nota);
  $('#calc-rotulo').textContent = t(`calc.faixa.${r.faixa}`);
  // O palco e os cartões de baixo ficam na cor da faixa: a tela inteira responde ao número.
  pintarFaixaHolofote(palco, r.faixa);
  const res = $('#calc-res');
  if (res) res.className = `calc-res nota-tinta ${r.faixa}`;
  pintarEscadaDaNota($('#calc-escada'), r.nota);
  pintarProximaFaixa($('#calc-prox'), r.nota);
  pintarMercadoCalc($('#calc-mercado'), r.nota, usado);
  pintarPotenciais(esp, usado, ivs, pkOrigem?.refino ?? null);

  const barra = (rotulo, v) => `
    <div class="calc-eixo">
      <span class="calc-eixo-nome">${rotulo}<em>${Math.round(v * 100)}%</em></span>
      <span class="calc-eixo-trilho"><i style="width:${(v * 100).toFixed(1)}%"></i></span>
      <span class="calc-eixo-pct">${Math.round(v * 100)}%</span>
    </div>`;
  $('#calc-eixos').innerHTML =
    barra(t('calc.iv'), r.eixos.iv)
    + barra(t('calc.qualidade'), r.eixos.qualidade)
    + barra(t('calc.potencia'), r.eixos.potencia)
    + barra(t('calc.shiny'), r.eixos.shiny);

  const fatias = fatiasNascimentoPorStat({
    ivs,
    qualidade: usado.qualidade,
    potencia: usado.potencia,
    shiny: usado.shiny,
    bases: basesOrigem,
  });
  const lider = fatias[0];
  const liderEl = $('#calc-stats-lider');
  if (liderEl && lider) {
    liderEl.innerHTML = t('calc.statsLider', { stat: rotuloStat(lider.key), pct: Math.round(lider.pct * 100) });
  }
  const statsLista = $('#calc-stats-lista');
  if (statsLista) {
    statsLista.innerHTML = fatias.map((f, i) => `
      <div class="calc-eixo calc-stat-eixo${i === 0 ? ' lider' : ''}">
        <span class="calc-eixo-nome">${rotuloStat(f.key)}<em>${Math.round(f.pct * 100)}%</em></span>
        <span class="calc-eixo-trilho"><i style="width:${(f.pct * 100).toFixed(1)}%"></i></span>
        <span class="calc-eixo-pct">${num(f.valor)}</span>
      </div>`).join('');
  }

  const combate = $('#calc-combate');
  if (combate) {
    const multPot = multDaPotencia(calc.potencia);
    const multShCombate = calc.shiny ? estado.multShinyStats : 1;
    const multTotal = multPot * multShCombate;
    const o = calc.origem;
    const nivelEst = o?.nivel ?? o?.level ?? 1;
    const pkCalc = {
      iv: usado.iv,
      ivs,
      quality: usado.qualidade,
      potencia: calc.potencia,
      shiny: calc.shiny,
      refino: pkOrigem?.refino,
    };
    const poderEst = poderDePokemon({ ...pkCalc, level: nivelEst }, esp);
    const poderGin = poderNoGinasio({
      ivs,
      quality: usado.qualidade,
      qualidade: usado.qualidade,
      potencia: calc.potencia,
      shiny: calc.shiny,
      level: nivelEst,
      refino: pkOrigem?.refino,
    }, esp);
    // O HP de combate só existe quando os números vieram de um bicho de verdade (a ficha traz o
    // `maxHp` dele); o shiny ligado/desligado aqui escala a partir do que ele é.
    let hpEst = null;
    if (o?.maxHp != null) {
      const baseSh = o.shiny ? estado.multShinyStats : 1;
      hpEst = Math.round(Number(o.maxHp) * (multShCombate / baseSh));
    }
    // Sem o "150 <s>300</s>": o ginásio deixou de ter teto, e o nível medido é sempre o real.
    // As duas placas de poder ficam com o MESMO nível de propósito — o que as separa é só a
    // métrica (⚔ do ranking × ⚔ de batalha), que é o que elas sempre quiseram comparar.
    const placa = (rot, valor, sub = '') => `
      <div class="calc-tile">
        <small>${rot}</small>
        <b>${valor}</b>
        ${sub ? `<em>${sub}</em>` : ''}
      </div>`;
    combate.innerHTML = `
      <h4 class="calc-cartao-tit">${dlgIcone('espadas', 14)}${t('calc.combateTitulo')}</h4>
      <div class="calc-tiles">
        ${placa(t('calc.multCombate'), `×${virgula(multTotal.toFixed(2))}`,
          `${t('calc.potencia')} ×${virgula(multPot.toFixed(2))}${calc.shiny ? ` · ${t('calc.shiny')} ×${estado.multShinyStats}` : ''}`)}
        ${placa(t('calc.poderEstimado'), `⚔ ${num(poderEst)}`, `${t('painel.nivelCurto')}${num(nivelEst)}`)}
        ${placa(t('calc.poderGinasio'), `⚔ ${num(poderGin)}`, `${t('painel.nivelCurto')}${num(nivelEst)}`)}
        ${hpEst != null ? placa(t('calc.hpCombate'), num(hpEst)) : ''}
      </div>
      <p class="calc-ajuda">${t('calc.combateNota')}</p>`;
  }

  pintarListaEspeciesCalc();
}

function pintarListaEspeciesCalc() {
  const lista = $('#calc-especie-lista');
  const busca = $('#calc-especie-busca');
  if (!lista || !busca || especieCalcAtual()) return;

  const q = busca.value;
  const resultados = filtrarEspeciesCalculadora(q);
  if (document.activeElement !== busca && !q.trim()) {
    lista.classList.add('hidden');
    lista.innerHTML = '';
    return;
  }

  lista.classList.remove('hidden');
  if (!resultados.length) {
    lista.innerHTML = `<div class="calc-especie-vazio">${t('calc.especieVazio')}</div>`;
    return;
  }

  lista.innerHTML = resultados.map((c) => {
    const dex = dexExibicao(c.pokeId);
    return `<button type="button" class="calc-especie-linha" data-poke-id="${c.pokeId}">
      <span class="calc-especie-linha-ico" data-lt="${c.looktype}"></span>
      <span class="calc-especie-linha-txt"><em>#${num(dex)}</em>${escapar(c.name)}</span>
    </button>`;
  }).join('');

  for (const linha of lista.querySelectorAll('.calc-especie-linha')) {
    const lt = linha.querySelector('[data-lt]');
    const looktype = Number(lt?.dataset.lt);
    if (lt && looktype) {
      lt.innerHTML = '';
      lt.appendChild(spriteAnimado(looktype, 28));
    }
    linha.onmousedown = (ev) => {
      ev.preventDefault();
      selecionarEspecieCalc(Number(linha.dataset.pokeId));
    };
  }
}

function pkDeLadoComp(lado) {
  const cfg = cfgComp(lado);
  const esp = especieLadoComp(lado);
  if (!esp) return null;
  const nivel = Math.max(1, Math.floor(Number($(`#calc-comp-${lado}-nivel`)?.value) || cfg.level || 1));
  const qBruto = Number(String($(`#calc-comp-${lado}-q`)?.value ?? '').replace(',', '.'));
  cfg.level = nivel;
  if (Number.isFinite(qBruto)) cfg.qualidade = qBruto;
  return {
    speciesId: cfg.speciesId,
    level: nivel,
    ivs: ivsLadoComp(lado),
    qualidade: cfg.qualidade,
    quality: cfg.qualidade,
    potencia: cfg.potencia,
    shiny: cfg.shiny,
    tmElemental: cfg.tm ?? null,
  };
}

function pintarListaEspeciesComp(lado) {
  const lista = $(`#calc-comp-${lado}-especie-lista`);
  const busca = $(`#calc-comp-${lado}-especie-busca`);
  if (!lista || !busca || especieLadoComp(lado)) return;

  const q = busca.value;
  const resultados = filtrarEspeciesCalculadora(q);
  if (document.activeElement !== busca && !q.trim()) {
    lista.classList.add('hidden');
    lista.innerHTML = '';
    return;
  }

  lista.classList.remove('hidden');
  if (!resultados.length) {
    lista.innerHTML = `<div class="calc-especie-vazio">${t('calc.especieVazio')}</div>`;
    return;
  }

  lista.innerHTML = resultados.map((c) => {
    const dex = dexExibicao(c.pokeId);
    return `<button type="button" class="calc-especie-linha" data-comp-especie="${lado}" data-poke-id="${c.pokeId}">
      <span class="calc-especie-linha-ico" data-lt="${c.looktype}"></span>
      <span class="calc-especie-linha-txt"><em>#${num(dex)}</em>${escapar(c.name)}</span>
    </button>`;
  }).join('');

  for (const linha of lista.querySelectorAll('.calc-especie-linha')) {
    const lt = linha.querySelector('[data-lt]');
    const looktype = Number(lt?.dataset.lt);
    if (lt && looktype) {
      lt.innerHTML = '';
      lt.appendChild(spriteAnimado(looktype, 28));
    }
    linha.onmousedown = (ev) => {
      ev.preventDefault();
      selecionarEspecieComp(linha.dataset.compEspecie, Number(linha.dataset.pokeId));
    };
  }
}

/**
 * A nota de um lado do Comparar — a MESMA conta da aba Nota, com a grade e a qualidade que estão
 * na tela. `null` sem espécie ou com campo inválido (aí o holofote fica apagado, em vez de mostrar
 * a cor de um número que a tela não mostra).
 */
function notaLadoComp(lado) {
  const esp = especieLadoComp(lado);
  if (!esp) return null;
  const grade = ivsDaGrade($(`#calc-comp-${lado}-iv-grid`));
  const q = Number(String($(`#calc-comp-${lado}-q`)?.value ?? '').replace(',', '.'));
  if (!grade.valido || !Number.isFinite(q) || q < QUALIDADE_MIN || q > QUALIDADE_MAX) return null;
  const cfg = cfgComp(lado);
  const bases = basesDaEspecie(esp);
  return notaPokemon({
    iv: somaIv(grade.ivs),
    ivs: grade.ivs,
    qualidade: q,
    potencia: cfg.potencia,
    shiny: cfg.shiny,
    bases,
    basesLimites: bases,
    basesAncestrais: esp.notaAncestrais ?? null,
  });
}

/** O pedestal de um lado: o bicho (a forma shiny quando ligada), a cor da nota DELE e a placa. */
function pintarPalcoComp(lado) {
  const palco = $(`#calc-comp-${lado}-palco`);
  if (!palco) return;
  const esp = especieLadoComp(lado);
  const cfg = cfgComp(lado);
  const placa = $(`#calc-comp-${lado}-placa`);
  const arte = palco.querySelector('.hf-arte');
  if (!esp) {
    pintarFaixaHolofote(palco, null, 'vazio');
    porNoPedestal(arte, 0, 80);
    palco.classList.remove('hf-shiny');
    if (placa) placa.innerHTML = `<span class="calc-comp-placa-vazia">${t(lado === 'a' ? 'calc.compEscolhaA' : 'calc.compEscolhaB')}</span>`;
    return;
  }
  porNoPedestal(arte, cfg.shiny ? (lookShinyFicha(esp) ?? esp.looktype) : esp.looktype, 80, esp.looktype);
  palco.classList.toggle('hf-shiny', !!cfg.shiny);
  const r = notaLadoComp(lado);
  pintarFaixaHolofote(palco, r?.faixa ?? null, r ? null : 'vazio');
  if (!placa) return;
  const nivel = Math.max(1, Math.floor(Number($(`#calc-comp-${lado}-nivel`)?.value) || cfg.level || 1));
  placa.innerHTML = `
    <b class="calc-comp-placa-nome">${cfg.shiny ? prefixoShiny() : ''}${escapar(esp.name)}</b>
    <span class="calc-comp-placa-linha">
      <em class="calc-comp-placa-nv">${t('painel.nivelCurto')}${num(nivel)}</em>
      ${r ? `<span class="calc-comp-placa-nota nota-tinta ${r.faixa}">N= ${notaEmTexto(r.nota)}</span>` : ''}
    </span>`;
}

function pintarCompararCalc() {
  const erro = $('#calc-comp-erro');
  const host = $('#calc-comp-resultado');
  if (!erro || !host) return;

  for (const lado of ['a', 'b']) {
    const esp = especieLadoComp(lado);
    const ico = $(`#calc-comp-${lado}-especie-ico`);
    if (ico && esp?.looktype && !ico.firstChild) ico.appendChild(spriteAnimado(esp.looktype, 30));
    pintarBarrasIv($(`#calc-comp-${lado}-iv-grid`));
    pintarPalcoComp(lado);
    $(`#calc-comp-${lado}-palco`)?.classList.remove('vence', 'perde');
    pintarListaEspeciesComp(lado);
  }

  const espA = especieLadoComp('a');
  const espB = especieLadoComp('b');
  if (!espA || !espB) {
    erro.textContent = t('calc.compSemLado');
    host.innerHTML = `<p class="calc-comp-vazio">${dlgIcone('espadas', 16)}<span>${t('calc.compSemLado')}</span></p>`;
    return;
  }

  const avisos = [];
  for (const lado of ['a', 'b']) {
    const qBruto = Number(String($(`#calc-comp-${lado}-q`)?.value ?? '').replace(',', '.'));
    if (!ivsDaGrade($(`#calc-comp-${lado}-iv-grid`)).valido) {
      avisos.push(t('calc.avisoIv', { min: IV_POR_STAT.min, max: IV_POR_STAT.max }));
    }
    if (!Number.isFinite(qBruto) || qBruto < QUALIDADE_MIN || qBruto > QUALIDADE_MAX) {
      avisos.push(t('calc.avisoQualidade', {
        min: virgula(QUALIDADE_MIN.toFixed(2)),
        max: virgula(QUALIDADE_MAX.toFixed(2)),
      }));
    }
  }
  erro.textContent = [...new Set(avisos)].join(' · ');
  if (avisos.length) {
    host.innerHTML = '';
    return;
  }

  const pkA = pkDeLadoComp('a');
  const pkB = pkDeLadoComp('b');
  const cmp = compararDuelo1v1(pkA, espA, pkB, espB, { tabelaTipos: estado.tabelaTipos });
  if (!cmp) {
    host.innerHTML = '';
    return;
  }

  const nomeA = espA.name;
  const nomeB = espB.name;
  const pctA = Math.round(cmp.pctA * 100);
  const pctB = Math.round(cmp.pctB * 100);
  const pctMinA = Math.round(cmp.pctMinA * 100);
  const pctMaxA = Math.round(cmp.pctMaxA * 100);
  const vencedor = cmp.empate ? null : (cmp.pctA > cmp.pctB ? 'a' : 'b');
  const nomeV = vencedor === 'a' ? nomeA : vencedor === 'b' ? nomeB : '';
  const pctV = vencedor === 'a' ? pctA : vencedor === 'b' ? pctB : 50;
  // Quem vence ganha a coroa e flutua; quem perde perde a cor. É o palco do diálogo de evolução
  // (`novo`/`sai`) aplicado ao duelo — o olho lê o resultado antes do número.
  if (vencedor) {
    $(`#calc-comp-${vencedor}-palco`)?.classList.add('vence');
    $(`#calc-comp-${vencedor === 'a' ? 'b' : 'a'}-palco`)?.classList.add('perde');
  }

  const detalhe = (lado, nome, pk, poder, met) => {
    // O nível sai inteiro: o duelo do ginásio deixou de ter teto, então não há mais o
    // "150 <s>300</s>" — o número mostrado é o mesmo que entrou na conta.
    const nvTxt = `${t('painel.nivelCurto')}${num(Math.max(1, Math.floor(Number(pk.level) || 1)))}`;
    // Com QUE golpe ele bate. É a linha que responde "por que esse ganha" quando o ⚔ do
    // outro é maior: a TM elemental bate com 2.800 onde o melhor golpe da espécie bate com
    // 600, e sem isto escrito a conta parece mágica.
    const g = met?.golpe ?? null;
    const golpeTxt = !g
      ? ''
      : met.golpeDaTm
        ? t('calc.compGolpeTm', { tipo: escapar(met.tm ?? g.type ?? ''), power: num(g.power ?? 0) })
        : t('calc.compGolpe', { golpe: escapar(g.name ?? '—'), power: num(g.power ?? 0) });
    return `
      <div class="calc-comp-det lado-${lado}${vencedor === lado ? ' vence' : ''}">
        <span class="calc-comp-det-topo"><span class="calc-comp-letra">${lado.toUpperCase()}</span><b>${escapar(nome)}</b></span>
        <span class="calc-comp-barra-poder">⚔ ${num(poder)} · ${nvTxt}</span>
        ${golpeTxt ? `<span class="calc-comp-barra-golpe${met.golpeDaTm ? ' tm' : ''}">${golpeTxt}</span>` : ''}
      </div>`;
  };

  let titulo = cmp.empate
    ? t('calc.compEmpate')
    : t('calc.compVence', { nome: nomeV, pct: pctV });
  if (pctMinA !== pctMaxA) {
    titulo += `<span class="calc-comp-faixa">${t('calc.compFaixa', {
      nome: nomeA,
      min: pctMinA,
      max: pctMaxA,
    })}</span>`;
  }

  // O CABO DE GUERRA é montado uma vez e depois só anda: refazer o HTML a cada dígito faria a
  // barra pular em vez de deslizar até o número novo.
  let cabo = host.querySelector('.calc-cabo');
  if (!cabo) {
    host.innerHTML = `
      <p class="calc-comp-resultado-titulo"></p>
      <div class="calc-cabo" role="img">
        <span class="calc-cabo-a" style="width:50%"></span>
        <span class="calc-cabo-b"></span>
        <b class="calc-cabo-pa"></b>
        <b class="calc-cabo-pb"></b>
      </div>
      <div class="calc-comp-dets"></div>
      <p class="calc-comp-base">${t('calc.compBase')}</p>`;
    cabo = host.querySelector('.calc-cabo');
  }
  host.querySelector('.calc-comp-resultado-titulo').innerHTML = `${vencedor ? dlgIcone('coroa', 16) : dlgIcone('espadas', 16)}<span>${titulo}</span>`;
  cabo.classList.toggle('empate', !!cmp.empate);
  cabo.classList.toggle('vence-a', vencedor === 'a');
  cabo.classList.toggle('vence-b', vencedor === 'b');
  cabo.setAttribute('aria-label', `${nomeA} ${pctA}% × ${nomeB} ${pctB}%`);
  cabo.querySelector('.calc-cabo-pa').textContent = `${pctA}%`;
  cabo.querySelector('.calc-cabo-pb').textContent = `${pctB}%`;
  const meta = cabo.querySelector('.calc-cabo-a');
  requestAnimationFrame(() => { meta.style.width = `${Math.max(4, Math.min(96, pctA))}%`; });
  host.querySelector('.calc-comp-dets').innerHTML =
    detalhe('a', nomeA, pkA, cmp.poderA, cmp.a) + detalhe('b', nomeB, pkB, cmp.poderB, cmp.b);
}

function selecionarEspecieComp(lado, pokeId) {
  const cfg = cfgComp(lado);
  cfg.speciesId = pokeId;
  cfg.especieBusca = '';
  if (!cfg.ivManual) cfg.ivs = null;
  // A TM é do TIPO do pokémon: trocar Tyranitar por Gyarados deixaria um "TM ROCK" que o jogo
  // nunca deixaria existir. Só sobrevive se a espécie nova também tiver aquele tipo.
  const esp = estado.especies.get(pokeId) ?? null;
  if (cfg.tm && !pokemonDoTipo([esp?.type1, esp?.type2].filter(Boolean), cfg.tm)) cfg.tm = null;
  montarCalculadora(hostCalculadora());
}

function limparEspecieComp(lado) {
  const cfg = cfgComp(lado);
  cfg.speciesId = null;
  cfg.especieBusca = '';
  cfg.ivs = null;
  cfg.ivManual = false;
  cfg.tm = null;
  montarCalculadora(hostCalculadora());
}

function selecionarEspecieCalc(pokeId) {
  calc.speciesId = pokeId;
  calc.especieBusca = '';
  if (!calc.ivManual) calc.ivs = null;
  montarCalculadora(hostCalculadora());
}

function limparEspecieCalc() {
  calc.speciesId = null;
  calc.especieBusca = '';
  calc.ivs = null;
  calc.ivManual = false;
  calc.origem = null;
  montarCalculadora(hostCalculadora());
}

const calcEmpilhada = () => !$('#calc').classList.contains('hidden');
const fichaAberta = () => !$('#ficha').classList.contains('hidden');

function hostCalculadora() {
  return calcEmpilhada() ? $('#calc-corpo') : $('#modal-corpo');
}

function montarCalculadora(host) {
  host.innerHTML = renderCalculadora();
  ligarCalculadora();
}

/** Calculadora por cima da ficha — o Market (ou o que estiver atrás) continua onde estava. */
function abrirCalculadoraEmpilhada() {
  $('#calc-titulo').textContent = t('modal.calculadora');
  montarCalculadora($('#calc-corpo'));
  $('#calc').classList.remove('hidden');
}

function fecharCalculadora() {
  $('#calc').classList.add('hidden');
  $('#calc-corpo').innerHTML = '';
}

function ligarCalculadora() {
  for (const aba of document.querySelectorAll('[data-calc-aba]')) {
    aba.onclick = () => {
      const id = aba.dataset.calcAba;
      if (id === calc.aba) return;
      calc.aba = id;
      montarCalculadora(hostCalculadora());
    };
  }

  if (calc.aba === 'comparar') {
    ligarCompararCalc();
    return;
  }

  ligarCalculadoraNota();
}

function ligarCompararCalc() {
  for (const lado of ['a', 'b']) {
    const busca = $(`#calc-comp-${lado}-especie-busca`);
    if (busca) {
      busca.onfocus = () => pintarListaEspeciesComp(lado);
      busca.oninput = () => {
        cfgComp(lado).especieBusca = busca.value;
        pintarListaEspeciesComp(lado);
      };
      busca.onkeydown = (ev) => {
        if (ev.key === 'Escape') {
          busca.blur();
          $(`#calc-comp-${lado}-especie-lista`)?.classList.add('hidden');
        }
      };
      busca.onblur = () => {
        setTimeout(() => $(`#calc-comp-${lado}-especie-lista`)?.classList.add('hidden'), 120);
      };
    }

    $(`#calc-comp-${lado}-nivel`)?.addEventListener('input', pintarCompararCalc);
    for (const inp of $(`#calc-comp-${lado}-iv-grid`)?.querySelectorAll('[data-iv-stat]') ?? []) {
      inp.addEventListener('input', () => {
        const cfg = cfgComp(lado);
        cfg.ivManual = true;
        cfg.ivs = ivsDaGrade($(`#calc-comp-${lado}-iv-grid`)).ivs;
        sincronizarIvSomaComp(lado);
        const soma = $(`#calc-comp-${lado}-ivsoma`);
        if (soma) soma.textContent = textoSomaIv(cfg.ivs);
        pintarCompararCalc();
      });
    }
    ligarQualidadeCalc(`calc-comp-${lado}-q`, pintarCompararCalc);

    $(`#calc-comp-${lado}-pots`)?.addEventListener('click', (ev) => {
      const b = ev.target.closest('.calc-pot');
      if (!b) return;
      const cfg = cfgComp(lado);
      cfg.potencia = Math.min(POTENCIA_MAX, Math.max(POTENCIA_MIN, Number(b.dataset.pot)));
      for (const c of $(`#calc-comp-${lado}-pots`).querySelectorAll('.calc-pot')) {
        c.classList.toggle('on', Number(c.dataset.pot) === cfg.potencia);
      }
      pintarCompararCalc();
    });

    $(`#calc-comp-${lado}-shiny`)?.addEventListener('click', () => {
      if (!especieLadoComp(lado)) return;
      const cfg = cfgComp(lado);
      cfg.shiny = !cfg.shiny;
      const btn = $(`#calc-comp-${lado}-shiny`);
      btn?.classList.toggle('on', cfg.shiny);
      btn?.setAttribute('aria-pressed', String(cfg.shiny));
      pintarCompararCalc();
    });

    $(`#calc-comp-${lado}-tms`)?.addEventListener('click', (ev) => {
      const b = ev.target.closest('.calc-tm');
      if (!b) return;
      const cfg = cfgComp(lado);
      cfg.tm = b.dataset.tm || null;
      for (const c of $(`#calc-comp-${lado}-tms`).querySelectorAll('.calc-tm')) {
        const ligado = (c.dataset.tm || null) === cfg.tm;
        c.classList.toggle('on', ligado);
        c.setAttribute('aria-pressed', String(ligado));
      }
      pintarCompararCalc();
    });
  }

  for (const btn of document.querySelectorAll('[data-comp-limpar]')) {
    btn.onclick = () => limparEspecieComp(btn.dataset.compLimpar);
  }

  $('#calc-comp-limpar')?.addEventListener('click', () => {
    for (const lado of ['a', 'b']) {
      const cfg = cfgComp(lado);
      cfg.speciesId = null;
      cfg.level = CALC_NIVEL_PADRAO;
      cfg.iv = 99;
      cfg.ivs = null;
      cfg.ivManual = false;
      cfg.qualidade = 1.1;
      cfg.potencia = 1;
      cfg.shiny = false;
      cfg.tm = null;
      cfg.especieBusca = '';
    }
    montarCalculadora(hostCalculadora());
  });

  pintarCompararCalc();
}

function ligarCalculadoraNota() {
  const desligarOrigem = () => {
    if (!calc.origem) return;
    calc.origem = null;
    hostCalculadora()?.querySelector('.calc-origem')?.remove();
  };

  const busca = $('#calc-especie-busca');
  if (busca) {
    busca.onfocus = () => pintarListaEspeciesCalc();
    busca.oninput = () => {
      calc.especieBusca = busca.value;
      pintarListaEspeciesCalc();
    };
    busca.onkeydown = (ev) => {
      if (ev.key === 'Escape') {
        busca.blur();
        $('#calc-especie-lista')?.classList.add('hidden');
      }
    };
    busca.onblur = () => {
      setTimeout(() => $('#calc-especie-lista')?.classList.add('hidden'), 120);
    };
  }
  $('#calc-especie-limpar')?.addEventListener('click', limparEspecieCalc);

  ligarQualidadeCalc('calc-q', () => {
    desligarOrigem();
    pintarCalculadora();
  });
  for (const inp of $('#calc-iv-grid')?.querySelectorAll('[data-iv-stat]') ?? []) {
    inp.addEventListener('input', () => {
      desligarOrigem();
      calc.ivManual = true;
      calc.ivs = ivsDaGrade($('#calc-iv-grid')).ivs;
      sincronizarIvSomaCalc();
      const soma = $('#calc-iv-soma');
      if (soma) soma.textContent = textoSomaIv(calc.ivs);
      pintarCalculadora();
    });
  }
  $('#calc-pots').onclick = (ev) => {
    const b = ev.target.closest('.calc-pot');
    if (!b) return;
    desligarOrigem();
    calc.potencia = Math.min(POTENCIA_MAX, Math.max(POTENCIA_MIN, Number(b.dataset.pot)));
    for (const c of $('#calc-pots').querySelectorAll('.calc-pot')) {
      c.classList.toggle('on', Number(c.dataset.pot) === calc.potencia);
    }
    pintarCalculadora();
  };
  $('#calc-shiny')?.addEventListener('click', () => {
    if (!especieCalcAtual()) return;
    calc.shiny = !calc.shiny;
    $('#calc-shiny')?.classList.toggle('on', calc.shiny);
    $('#calc-shiny')?.setAttribute('aria-pressed', String(calc.shiny));
    pintarCalculadora();
  });
  $('#calc-limpar').onclick = () => {
    calc.speciesId = null;
    calc.iv = 99;
    calc.ivs = null;
    calc.ivManual = false;
    calc.qualidade = 1.1;
    calc.potencia = 1;
    calc.shiny = false;
    calc.origem = null;
    calc.especieBusca = '';
    if (calcEmpilhada()) abrirCalculadoraEmpilhada();
    else abrirModal('calculadora');
  };
  pintarCalculadora();
}

function renderConfiguracoes() {
  return `<div class="cfg-corpo" id="cfg-corpo"></div>`;
}

function pintarConfiguracoes() {
  const host = $('#cfg-corpo');
  if (!host) return;
  const otim = otimizadoLigado();
  const economia = economiaLigado();
  const night = nightLigado();
  const imersivo = imersivoLigado();
  const som = somLigado();
  const somShiny = somShinyLigado();
  const somCaptura = somCapturaLigado();
  const somTmBoss = somTmBossLigado();
  const golpesHud = golpesHudLigado();
  const movel = movelAtivo();
  // O interruptor aparece em aparelho de toque ou tela estreita — e também quando o layout
  // mobile já está ligado, senão quem testou no celular (ou com janela estreita) fica preso
  // no mobile no monitor sem conseguir desligar (a pref fica em `localStorage`).
  // TELA SEMPRE ACESA: mesmo critério da linha do layout (ver `telaAcesaSeAplica`). Num
  // navegador sem a API a linha aparece mesmo assim, travada e dizendo o porquê — escondê-la
  // deixaria quem viu a opção no celular do amigo procurando por ela no próprio.
  const telaAcesa = telaAcesaLigado();
  const temTelaAcesa = telaAcesaSuportada();
  const linhaTelaAcesa = telaAcesaSeAplica()
    ? `<div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.telaAcesa')}</span>
      <button type="button" class="cfg-toggle${telaAcesa && temTelaAcesa ? ' on' : ''}" id="cfg-tela-acesa" role="switch"
        aria-checked="${telaAcesa && temTelaAcesa}"${temTelaAcesa ? '' : ' disabled'}></button>
      <span class="cfg-desc">${t(temTelaAcesa ? 'cfg.telaAcesaAjuda' : 'cfg.telaAcesaSemSuporte')}</span>
    </div>`
    : '';
  const linhaMovel = aparelhoDeToque() || movel
    ? `<div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.movel')}</span>
      <button type="button" class="cfg-toggle${movel ? ' on' : ''}" id="cfg-movel" role="switch" aria-checked="${movel}"></button>
      <span class="cfg-desc">${t('cfg.movelAjuda')}</span>
    </div>`
    : '';
  host.innerHTML = `
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.otimizado')}</span>
      <button type="button" class="cfg-toggle${otim ? ' on' : ''}" id="cfg-otimizado" role="switch" aria-checked="${otim}"></button>
      <span class="cfg-desc">${t('cfg.otimizadoAjuda')}</span>
    </div>
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.economia')}</span>
      <button type="button" class="cfg-toggle${economia ? ' on' : ''}" id="cfg-economia" role="switch" aria-checked="${economia}"></button>
      <span class="cfg-desc">${t('cfg.economiaAjuda')}</span>
    </div>
    ${linhaTelaAcesa}
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.night')}</span>
      <button type="button" class="cfg-toggle${night ? ' on' : ''}" id="cfg-night" role="switch" aria-checked="${night}"></button>
      <span class="cfg-desc">${t('cfg.nightAjuda')}</span>
    </div>
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.imersivo')}</span>
      <button type="button" class="cfg-toggle${imersivo ? ' on' : ''}" id="cfg-imersivo" role="switch" aria-checked="${imersivo}"></button>
      <span class="cfg-desc">${t('cfg.imersivoAjuda')}</span>
    </div>
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.som')}</span>
      <button type="button" class="cfg-toggle${som ? ' on' : ''}" id="cfg-som" role="switch" aria-checked="${som}"></button>
      <span class="cfg-desc">${t('cfg.somAjuda')}</span>
    </div>
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.somShiny')}</span>
      <button type="button" class="cfg-toggle${somShiny ? ' on' : ''}" id="cfg-som-shiny" role="switch" aria-checked="${somShiny}"></button>
      <span class="cfg-desc">${t('cfg.somShinyAjuda')}</span>
    </div>
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.somCaptura')}</span>
      <button type="button" class="cfg-toggle${somCaptura ? ' on' : ''}" id="cfg-som-captura" role="switch" aria-checked="${somCaptura}"></button>
      <span class="cfg-desc">${t('cfg.somCapturaAjuda')}</span>
    </div>
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.somTmBoss')}</span>
      <button type="button" class="cfg-toggle${somTmBoss ? ' on' : ''}" id="cfg-som-tm-boss" role="switch" aria-checked="${somTmBoss}"></button>
      <span class="cfg-desc">${t('cfg.somTmBossAjuda')}</span>
    </div>
    <div class="cfg-linha">
      <span class="cfg-nome">${t('cfg.golpesHud')}</span>
      <button type="button" class="cfg-toggle${golpesHud ? ' on' : ''}" id="cfg-golpes-hud" role="switch" aria-checked="${golpesHud}"></button>
      <span class="cfg-desc">${t('cfg.golpesHudAjuda')}</span>
    </div>
    ${linhaMovel}`;
}

function ligarConfiguracoes() {
  pintarConfiguracoes();
  const host = $('#cfg-corpo');
  if (!host) return;
  host.onclick = (ev) => {
    const b = ev.target.closest('.cfg-toggle');
    if (!b) return;
    if (b.id === 'cfg-otimizado') definirOtimizado(!otimizadoLigado());
    else if (b.id === 'cfg-economia') {
      const ligando = !economiaLigado();
      definirEconomia(ligando);
      // Ligou: a tela que ele quer ver está ATRÁS deste modal. Sair dele é a única forma de
      // mostrar o resultado da escolha — o mesmo gesto do Modo Imersivo aqui embaixo.
      if (ligando) fecharModal();
    }
    else if (b.id === 'cfg-tela-acesa') {
      const ligando = !telaAcesaLigado();
      definirTelaAcesa(ligando);
      // O pedido sai DENTRO deste clique de propósito: é o gesto que os navegadores mais
      // exigentes pedem. Se mesmo assim o aparelho recusar (economia de bateria do sistema),
      // quem ligou precisa saber — o interruptor aceso sozinho diria que está funcionando.
      if (ligando) {
        sincronizarTelaAcesa().then((presa) => {
          if (!presa) toast(t('cfg.telaAcesaRecusada'));
        });
      } else sincronizarTelaAcesa();
    }
    else if (b.id === 'cfg-night') aplicarNight(!nightLigado());
    else if (b.id === 'cfg-imersivo') {
      const ligando = !imersivoLigado();
      definirImersivo(ligando);
      if (ligando) fecharModal();
    }
    else if (b.id === 'cfg-som') {
      const ligando = !somLigado();
      definirSom(ligando);
      sincronizarSom(ligando);
    }
    else if (b.id === 'cfg-som-shiny') {
      const ligando = !somShinyLigado();
      definirSomShiny(ligando);
      // Ligou aqui, provavelmente para ouvir: toca uma vez como prévia. O clique no
      // interruptor é o gesto que o navegador exige, então esta é a única chamada que tem
      // autoplay garantido — e de quebra o jogador confere o volume antes do shiny real.
      if (ligando) {
        prepararSons({ shiny: true, captura: somCapturaLigado() });
        tocarShinyCaptura();
      }
    }
    else if (b.id === 'cfg-som-captura') {
      const ligando = !somCapturaLigado();
      definirSomCaptura(ligando);
      if (ligando) {
        prepararSons({ shiny: somShinyLigado(), captura: true });
        tocarCaptura();
      }
    }
    else if (b.id === 'cfg-som-tm-boss') {
      const ligando = !somTmBossLigado();
      definirSomTmBoss(ligando);
      // Mesma prévia dos outros efeitos: o clique é o gesto que libera o autoplay.
      if (ligando) {
        prepararSons({ shiny: false, captura: false, tmBoss: true });
        tocarTmBossDrop();
      }
    }
    else if (b.id === 'cfg-golpes-hud') {
      definirGolpesHud(!golpesHudLigado());
      pintarGolpesPainel(estado.eu, estado.eu?.pokemons?.find((x) => x.id === estado.eu.activeId));
    }
    else if (b.id === 'cfg-movel') {
      // Trocar de layout desmonta e remonta a tela inteira; o modal de configurações vai
      // junto. Reabri-lo devolve o jogador exatamente onde ele estava — do outro lado.
      definirPreferenciaMovel(movelAtivo() ? '0' : '1');
      return abrirModal('configuracoes');
    }
    pintarConfiguracoes();
  };
}

// ------------------------------------------------------ a ficha do treinador
//
// Abre no retrato do canto superior esquerdo. Junta o que estava espalhado pela interface —
// pokédex, boss, arena — num lugar só, e é onde ficam as opções da CONTA (que não têm
// nada a ver com o jogo em si, mas também não têm outro lugar para morar).
//
// Tudo que é NÚMERO DE JOGO sai do snapshot que já está em memória: nenhum pedido ao servidor
// para abrir. Só a parte de conta (e-mail, provedor) precisa de uma ida ao `/auth/conta`, e ela
// chega depois, sem segurar a tela.

/** O intervalo entre dois pedidos de troca de senha. O servidor cobra o mesmo (ver `auth.mjs`). */
const UMA_HORA_MS = 60 * 60 * 1000;

/** Um número grande com rótulo embaixo. */
const fichaBloco = (rotulo, valor, extra = '') =>
  `<div class="pf-bloco"><b>${valor}</b><span>${rotulo}</span>${extra ? `<em>${extra}</em>` : ''}</div>`;

/** Uma linha de "coisa: valor" dentro de uma seção. */
const fichaLinha = (rotulo, valor) =>
  `<div class="pf-linha"><span>${rotulo}</span><b>${valor}</b></div>`;

/**
 * O bloco de ELO: o tier do PvP ranqueado com o emblema, e os pontos (PR) ao lado.
 *
 * Já foi o número da arena aposentada, que parou de se mover — e como o pacote novo não tem
 * `elo`, a ficha mostrava o `1.000` de reserva para todo mundo. A leitura é a mesma do emblema
 * do canto (`pintarRankDoTreinador`): durante o posicionamento não há tier nem PR a mostrar.
 */
function fichaBlocoElo(rank) {
  const semRank = posicionando(rank);
  const vd = rank?.partidas
    ? t('pf.vitDerr', { v: num(rank.vitorias ?? 0), d: num(rank.derrotas ?? 0) })
    : '';
  return `<div class="pf-bloco pf-bloco-elo">
      <div class="pf-elo">
        ${semRank ? '' : `<img class="pf-elo-emblema" src="${iconeDoRank(rank.tierId)}" alt="" loading="lazy">`}
        <b>${escapar(semRank ? t('pvp.naoClassificado') : rotuloDoRank(rank))}</b>
        ${semRank ? '' : `<small>${num(rank.pontos)} ${t('pvp.pr')}</small>`}
      </div>
      <span>${t('pf.elo')}</span>${vd ? `<em>${vd}</em>` : ''}
    </div>`;
}

/** Monta o HTML da ficha do treinador — próprio (modal) ou de outro jogador (overlay). */
function htmlPerfilTreinador(d, {
  retratoId = 'pf-retrato',
  mostrarAvatarBtn = false,
  mostrarVitrine = false,
  vitrineId = 'pf-vitrine',
  mostrarPvpTime = false,
  pvpTimeId = 'pf-pvptime',
  acoesSociais = '',
} = {}) {
  const dentro = Math.max(0, (d.xp ?? 0) - (d.xpNivel ?? 0));
  const faixa = Math.max(1, (d.xpProximo ?? 1) - (d.xpNivel ?? 0));
  const livreEm = d.visualTrocaLivreEm ?? 0;
  const restaTroca = livreEm - Date.now();
  const podeTrocar = restaTroca <= 0;
  const mostrarColecao = d.shinysVistos != null || d.shinysTem != null || d.p5Tem != null;

  return `
    <div class="pf-topo">
      <div class="pf-retrato" id="${retratoId}"></div>
      <div class="pf-id">
        <div class="pf-nick">${
          // A TAG DA GUILD vem ANTES do nick, como no chat — mesmo lugar, mesma leitura. O
          // `title` traz o nome da guild por extenso, que três letras não cabem.
          d.guildTag
            ? `<span class="pf-guild-tag" style="--gt:${corTagValida(d.guildTagCor)}"`
              + ` title="${escapar(d.guildNome ?? '')}">`
              + `${escapar(String(d.guildTag).slice(0, MAX_TAG_GUILD))}</span> `
            : ''
        }${escapar(d.nick ?? '—')}${
          // A tag de FUNDADOR/COFUNDADOR, que saiu do chat e mora aqui. A cor vem de
          // `CAIXAS_BETA` (a mesma tabela que o servidor lê), por `--cx-cor` — duas caixas, duas
          // cores, uma tabela só.
          d.fundador && CAIXAS_BETA[d.fundador.tipo]
            ? ` <span class="pf-fundador" style="--cx-cor:${CAIXAS_BETA[d.fundador.tipo].cor}"`
              + ` title="${escapar(CAIXAS_BETA[d.fundador.tipo].nome ?? '')}">`
              + `${escapar(serieDaCaixa(d.fundador.tipo, d.fundador.serie))}</span>`
            : ''
        }</div>
        ${htmlConquistasCampeonato(d.conquistas)}
        <div class="pf-nivel">${t('painel.nivelCurto')} <b>${num(d.level ?? 1)}</b></div>
        <div class="barra xp"><div class="fill" style="width:${(dentro / faixa) * 100}%"></div>
          <span>${num(dentro)} / ${num(faixa)} xp</span></div>
        ${acoesSociais}
        ${mostrarAvatarBtn
          ? `<div class="pf-botoes">
               <button class="pf-avatar" id="pf-avatar" type="button" ${podeTrocar ? '' : 'disabled'}>
                 ${podeTrocar
                   ? t('av.mudar')
                   : t('av.espere', { horas: num(Math.ceil(restaTroca / 3_600_000)) })}
               </button>
               <!-- Armário ao lado de "Mudar avatar" porque as duas respondem à mesma
                    pergunta ("como eu quero aparecer?") — só que uma muda o CORPO (e custa
                    24 h de espera) e a outra muda a ROUPA (e é de graça, à vontade). -->
               <button class="pf-avatar pf-armario" id="pf-armario" type="button">${t('armario.botao')}</button>
             </div>`
          : ''}
      </div>
    </div>

    ${mostrarPvpTime ? htmlEquipePvpPerfil({ id: pvpTimeId }) : ''}
    ${mostrarVitrine ? htmlVitrinePerfil({ id: vitrineId, meu: mostrarAvatarBtn }) : ''}

    <div class="pf-blocos">
      ${fichaBloco(t('pf.especies'), `${num(d.capturadasDex ?? 0)} / ${num(d.totalDex ?? 0)}`)}
      ${fichaBloco(t('pf.capturas'), num(d.capturas ?? 0))}
      ${fichaBloco(t('pf.derrotados'), num(d.derrotas ?? 0))}
      ${fichaBloco(t('pf.bossPontos'), num(d.bossPontos ?? 0))}
      ${fichaBlocoElo(d.pvpRank)}
    </div>

    ${mostrarColecao ? `
    <h3>${t('pf.secaoColecao')}</h3>
    <div class="pf-blocos">
      ${fichaBloco(t('pf.shinysVistos'), num(d.shinysVistos ?? 0))}
      ${fichaBloco(t('pf.shinysTem'), num(d.shinysTem ?? 0))}
      ${fichaBloco(t('pf.p5Tem'), num(d.p5Tem ?? 0))}
    </div>` : d.statsOcultos ? `<p class="pf-stats-ocultos">${t('pf.statsOcultos')}</p>` : ''}

    ${mostrarAvatarBtn ? `
    <label class="pf-priv-stats">
      <input type="checkbox" id="pf-stats-publico"${d.statsPublico !== false ? ' checked' : ''}>
      <span>${t('pf.statsPublico')}</span>
    </label>` : ''}

    <h3>${t('pf.secaoJogo')}</h3>
    <div class="pf-secao">
      ${fichaLinha(t('pf.time'), `${num(d.time ?? 0)} ${t('pf.pokemon')}`)}
      ${fichaLinha(t('pf.ouro'), moeda(d.gold ?? 0))}
      ${fichaLinha(t('pf.orbs'), num(d.orbs ?? 0))}
      ${fichaLinha(t('pf.vip'), d.vip ? t('pf.vipAtivo') : t('pf.vipNao'))}
    </div>`;
}

// ---------------------------------------------------------------- a vitrine
//
// A VITRINE POKÉMON da Ficha do Treinador: os bichos que o jogador ESCOLHEU exibir.
//
// A ficha respondia "quanto" — níveis, capturas, elo, shinies — e não respondia "quem". Só que
// o que uma pessoa mostra quando abre o perfil dela não é o número de capturas: é a coleção.
// Daí a vitrine vir ANTES dos blocos de número, colada no retrato — retrato + vitrine é o
// cartão do treinador, e o resto é o histórico dele.
//
// A escolha é DELE, e não a equipe. As duas coisas quase nunca são a mesma: o shiny raro e o
// P5 de coleção costumam estar guardados no Depot justamente por serem raros demais para
// levar à hunt, e uma vitrine que mostrasse só quem está lutando deixaria de fora exatamente
// aquilo que se quer exibir. Quem nunca montou a sua vê a equipe atual — assim ninguém tem
// vitrine vazia, e montar a própria é melhoria, não requisito.
//
// Os cards não inventam desenho nenhum. A fileira de selos é a MESMA de `selosAtributos` — a
// que o Market, o Mercado da Comunidade e a linha do Depot já usam —, na mesma ordem
// (potência, IV, qualidade, nota) e nas mesmas cinco cores. Quem aprendeu que laranja é topo
// numa vitrine lê esta sem reaprender nada. O clique abre a MESMA ficha do (i) do Depot, e o
// "+" abre a MESMA bancada de refino do painel "Em campo".
//
// As casas VAZIAS aparecem de propósito. Três cards e um buraco à direita parecem uma grade
// quebrada; seis casas com três cheias dizem quantas faltam — que é justamente o convite a
// abrir o editor.

/** Quantos cabem na vitrine. Precisa bater com `MAX_VITRINE` no servidor, que é quem decide. */
const MAX_VITRINE = 6;

/**
 * Os pokémon da vitrine, na ordem escolhida.
 *
 * Ids que já não são dele (vendido, anunciado, evoluído) caem fora aqui — o servidor faz a
 * mesma limpeza na leitura, e repeti-la na tela evita uma casa fantasma no meio segundo entre
 * a venda e o snapshot seguinte.
 */
function pokemonsDaVitrine(e = estado.eu) {
  const todos = e?.pokemons ?? [];
  const ids = e?.vitrine ?? [];
  if (ids.length) {
    const porId = new Map(todos.map((p) => [p.id, p]));
    return ids.map((id) => porId.get(id)).filter(Boolean).slice(0, MAX_VITRINE);
  }
  // Nunca montou a sua: cai na equipe. Ver o bloco de comentário acima.
  return todos.filter((p) => p.slot != null).sort((a, b) => a.slot - b.slot).slice(0, MAX_VITRINE);
}

/**
 * A moldura da vitrine. O miolo é montado em JS: sprite animado é canvas, não string.
 *
 * O `id` é parâmetro porque as DUAS fichas podem estar abertas ao mesmo tempo — o cartão de
 * outro treinador (`#perfil`) empilha sobre a ficha própria (`#modal`), e dois `#pf-vitrine`
 * na mesma página fariam o `$()` devolver sempre o de trás.
 */
/**
 * A EQUIPE DE PVP na ficha do treinador.
 *
 * Bloco separado da vitrine, e não no lugar dela, porque as duas respondem a perguntas
 * diferentes. A vitrine é o que o jogador ESCOLHE exibir — a coleção, o shiny raro, o P5 que
 * quase nunca luta. Esta é com o que ele GANHA. Quem abre o perfil de um Challenger vindo da
 * tabela do ranqueado está perguntando a segunda, e até aqui só recebia a primeira.
 *
 * Vem ANTES da vitrine quando existe: nesse contexto é a informação principal.
 *
 * Mostra QUEM está na equipe, e não a ORDEM de entrada: o servidor manda os cinco na ordem da
 * Pokédex (ver `timePublicoLinhas`), e o aviso no cabeçalho diz isso — sem ele, a ordem da
 * Pokédex seria lida como a escalação.
 */
const htmlEquipePvpPerfil = ({ id }) => `
  <div class="pf-vitrine-cabeca">
    <h3>${t('pf.pvpTime')}</h3>
    <div class="pf-vitrine-acoes">
      <span class="pf-pvptime-sem-ordem" title="${escapar(t('pf.pvpTimeSemOrdemDica'))}">${escapar(t('pf.pvpTimeSemOrdem'))}</span>
      <span class="pf-vitrine-conta" id="${id}-conta"></span>
    </div>
  </div>
  <div class="pf-vitrine" id="${id}"></div>`;

const htmlVitrinePerfil = ({ id, meu }) => `
  <div class="pf-vitrine-cabeca">
    <h3>${t('pf.vitrine')}</h3>
    <div class="pf-vitrine-acoes">
      <span class="pf-vitrine-conta" id="${id}-conta"></span>
      ${meu ? `<button type="button" class="pf-vitrine-editar" id="pf-vitrine-editar">${escapar(t('pf.vitrineEditar'))}</button>` : ''}
    </div>
  </div>
  <div class="pf-vitrine" id="${id}"></div>`;

/**
 * O que a vitrine mostra AGORA, em uma linha.
 *
 * `atualizarPerfil` roda a cada snapshot — duas vezes por segundo enquanto a hunt anda — e cada
 * card tem um canvas animado dentro. Remontar sempre reiniciaria os seis sprites e a vitrine
 * piscaria sem parar. Entra na assinatura só o que ela desenha: quem está em cada casa, o
 * nível, a vida, o refino e quem está em campo.
 */
function assinaturaVitrinePerfil(e) {
  return `${e?.activeId ?? ''}|${pokemonsDaVitrine(e)
    .map((p) => [
      p.id, p.level, p.hp, p.maxHp, p.shiny ? 1 : 0,
      refinoTotalDe(p), looktypeDe(p), p.tmElemental ?? '', p.tmAoe ? 1 : 0,
    ].join(':'))
    .join(',')}`;
}

/** A pokébola apagada da casa livre — desenho, não asset: é decoração de espaço vazio. */
const SVG_CASA_LIVRE = `
  <svg viewBox="0 0 24 24" aria-hidden="true" class="pf-vt-bola">
    <circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" stroke-width="2"/>
    <path d="M2 12h20" stroke="currentColor" stroke-width="2"/>
    <circle cx="12" cy="12" r="3.4" fill="none" stroke="currentColor" stroke-width="2"/>
  </svg>`;

/**
 * Uma casa livre da vitrine. Botão: a casa vazia é o convite mais direto que existe para
 * preenchê-la, e ela abre o editor. Só aparece na ficha PRÓPRIA (ver `pintarGradeVitrine`).
 */
function casaLivreVitrine() {
  const el = document.createElement('button');
  el.type = 'button';
  el.className = 'pf-vt-card vazia';
  el.innerHTML = `
    <span class="pf-vt-palco">${SVG_CASA_LIVRE}</span>
    <span class="pf-vt-nome">${escapar(t('pf.vitrineLivre'))}</span>
    <span class="pf-vt-vazia-nota">${escapar(t('pf.vitrineLivreNota'))}</span>`;
  el.onclick = abrirEditorVitrine;
  return el;
}

/**
 * Um card da vitrine.
 *
 * `div` com `role="button"` em vez de `<button>` por causa do "+": botão dentro de botão é
 * HTML inválido, e o refino precisa ser um alvo próprio (ver `cardPokemonEscolha`, que resolve
 * o mesmo conflito do mesmo jeito).
 *
 * `meu: false` é a ficha de OUTRO treinador — lá não há "+" (a bancada é do dono), não há
 * cadeado de nível (o nível que importa é o dele) e o clique abre a ficha que veio no pacote,
 * e não uma busca na coleção de quem está olhando.
 */
function cardVitrinePerfil(pk, { ativoId = null, meu = true } = {}) {
  const emCampo = meu && pk.id === ativoId;
  const bloqueada = meu && !podeUsarPokemon(estado.eu?.level ?? 0, pk);
  const vida = pk.maxHp > 0 ? pk.hp / pk.maxHp : 0;
  const info = meu ? infoRefino(pk) : null;

  const el = document.createElement('div');
  el.className = `pf-vt-card${emCampo ? ' em-campo' : ''}${bloqueada ? ' bloqueada' : ''}`;
  el.tabIndex = 0;
  el.setAttribute('role', 'button');
  el.title =
    `${t('painel.poder')} ${num(pk.poder ?? 0)} · ${(pk.tipos ?? []).join('/')}\n${t('cm.verFicha')}`;
  el.innerHTML = `
    <span class="pf-vt-palco">
      ${pk.shiny ? `<span class="pf-vt-shiny" title="${escapar(t('pf.vitrineShiny'))}">✨</span>` : ''}
      <span class="pf-vt-arte"></span>
      ${seloRefino(pk)}
      ${selosTm(pk) ? `<span class="pf-vt-tm">${selosTm(pk)}</span>` : ''}
    </span>
    <span class="pf-vt-nome">${escapar(pk.nome ?? '—')}</span>
    <span class="pf-vt-tipos">${selosDeTipo(pk.tipos)}</span>
    <span class="pf-vt-nv">${t('painel.nivelCurto')} <b>${num(pk.level ?? 1)}</b></span>
    ${selosAtributos(pk)}
    <span class="mini-hp ${vida < 0.35 ? 'baixo' : ''}"><i style="width:${Math.max(0, Math.min(1, vida)) * 100}%"></i></span>
    <span class="pf-vt-rodape">${
      emCampo
        ? `<b class="pf-vt-emcampo">${escapar(t('pf.vitrineEmCampo'))}</b>`
        : bloqueada
          ? `<i class="pf-vt-travado">${escapar(t('pf.vitrineTravado'))}</i>`
          : `<i>${escapar(t('pf.vitrineVerFicha'))}</i>`
    }</span>`;

  // O sprite é a estrela do card: 68 px, mais que o dobro da linha do painel. É a única tela do
  // jogo em que a coleção escolhida aparece grande, toda de uma vez.
  el.querySelector('.pf-vt-arte').appendChild(spritePokemon(pk, 68));

  // O "+" só existe onde a bancada existe: pokémon SEU, espécie no catálogo e pedra de refino.
  // Sem essa guarda ele apareceria em metade dos cards só para abrir um "indisponível".
  if (info?.meu) {
    const bt = document.createElement('button');
    bt.type = 'button';
    bt.className = 'pf-vt-mais';
    bt.title = t('refino.botao');
    bt.setAttribute('aria-label', t('refino.botao'));
    bt.innerHTML = '<svg class="ico-mais" viewBox="0 0 24 24" aria-hidden="true"><path d="M10.5 4h3v6.5H20v3h-6.5V20h-3v-6.5H4v-3h6.5z" fill="currentColor"/></svg>';
    bt.onclick = (ev) => {
      ev.stopPropagation();
      abrirRefino(pokemonAtualizado(pk));
    };
    el.querySelector('.pf-vt-palco').appendChild(bt);
  }

  const abrir = (ev) => {
    if (ev.target.closest?.('.pf-vt-mais')) return;
    abrirFichaDoPokemon(meu ? pokemonAtualizado(pk) : pk);
  };
  el.addEventListener('click', abrir);
  el.addEventListener('keydown', (ev) => {
    if (ev.key !== 'Enter' && ev.key !== ' ') return;
    ev.preventDefault();
    abrir(ev);
  });
  return el;
}

/**
 * Enche uma grade de vitrine.
 *
 * As casas livres só entram na ficha PRÓPRIA. Elas existem para convidar o dono a preenchê-las
 * — na ficha de outro treinador não há convite nenhum a fazer, e cinco recortes hachurados ao
 * lado do único bicho que ele expôs falam mais alto que o bicho.
 */
function pintarGradeVitrine(host, lista, opcoes) {
  const cards = lista.map((p) => cardVitrinePerfil(p, opcoes));
  if (opcoes.meu) {
    for (let i = lista.length; i < MAX_VITRINE; i++) cards.push(casaLivreVitrine());
  } else if (!lista.length) {
    const vazio = document.createElement('p');
    vazio.className = 'pf-vitrine-vazia';
    // `vazioChave` porque "este treinador ainda não montou a vitrine" e "não tem equipe de PvP
    // salva" são coisas diferentes, e a mesma grade desenha as duas.
    vazio.textContent = t(opcoes.vazioChave ?? 'pf.vitrineVaziaOutro');
    return host.replaceChildren(vazio);
  }
  host.replaceChildren(...cards);
}

/** (Re)desenha a vitrine da ficha PRÓPRIA. */
function montarVitrinePerfil() {
  const host = $('#pf-vitrine');
  if (!host) return;
  const e = estado.eu ?? {};
  estado.assinaturaVitrinePerfil = assinaturaVitrinePerfil(e);

  const lista = pokemonsDaVitrine(e);
  const conta = $('#pf-vitrine-conta');
  if (conta) conta.textContent = `${num(lista.length)}/${num(MAX_VITRINE)}`;
  pintarGradeVitrine(host, lista, { ativoId: e.activeId, meu: true });
}

/**
 * A equipe de PvP no cartão de outro treinador. Mesma grade da vitrine, só leitura.
 *
 * Sem casas vazias: a vitrine tem seis lugares fixos (e o buraco é convite a preencher), mas
 * uma equipe de PvP de três pokémon é uma escolha, não uma equipe pela metade.
 */
function montarEquipePvpDoPerfil(p) {
  const host = $('#pf-pvptime-outro');
  if (!host) return;
  const lista = p.pvpTime ?? [];
  const conta = $('#pf-pvptime-outro-conta');
  if (conta) conta.textContent = lista.length ? `${num(lista.length)}` : '';
  pintarGradeVitrine(host, lista, { meu: false, vazioChave: 'pf.pvpTimeVazio' });
}

/** A vitrine do cartão de OUTRO treinador. Só leitura: sem "+", sem cadeado, sem casa clicável. */
function montarVitrineDoPerfilPublico(p) {
  const host = $('#pf-vitrine-outro');
  if (!host) return;
  const lista = (p.vitrine ?? []).slice(0, MAX_VITRINE);
  const conta = $('#pf-vitrine-outro-conta');
  if (conta) conta.textContent = `${num(lista.length)}/${num(MAX_VITRINE)}`;
  pintarGradeVitrine(host, lista, { meu: false });
}

// -------------------------------------------------- o editor ("Montar vitrine")
//
// Um modal EMPILHADO sobre a ficha, como a bancada de refino: quem monta a vitrine está
// olhando para ela, e fechar o editor tem de devolver a ficha embaixo, não a tela do jogo.
//
// A escolha é um RASCUNHO até o "Salvar". Mandar cada clique ao servidor seria seis mensagens
// para montar uma vitrine de seis, e nenhuma delas teria como desfazer — e a ordem, que aqui é
// a ordem dos cliques, viraria uma corrida entre pacotes.

/** Ids escolhidos no editor aberto agora. `null` = editor fechado. */
let vitrineRascunho = null;

function abrirEditorVitrine() {
  vitrineRascunho = pokemonsDaVitrine().map((p) => p.id);
  const busca = $('#vte-busca');
  if (busca) busca.value = '';
  const local = $('#vte-local');
  if (local) local.innerHTML = htmlOpcoesLocal(LOCAIS_TODOS, 'todos');
  $('#vitrine-editor').classList.remove('hidden');
  montarEditorVitrine();
  busca?.focus?.();
}

function fecharEditorVitrine() {
  vitrineRascunho = null;
  $('#vitrine-editor')?.classList.add('hidden');
}

/** Alterna um pokémon no rascunho. Cheia, o clique avisa em vez de trocar alguém por sorteio. */
function alternarNaVitrine(id) {
  if (!vitrineRascunho) return;
  const i = vitrineRascunho.indexOf(id);
  if (i >= 0) {
    vitrineRascunho.splice(i, 1);
  } else {
    if (vitrineRascunho.length >= MAX_VITRINE) return toast(t('pf.vitrineCheia', { n: num(MAX_VITRINE) }));
    vitrineRascunho.push(id);
  }
  montarEditorVitrine();
}

/**
 * A tira dos ESCOLHIDOS, no topo do editor.
 *
 * Existe por causa da ordem: a vitrine é exibida na ordem dos cliques, e sem um lugar que
 * mostre essa fila o jogador só descobriria a ordem depois de salvar. Clicar num chip tira
 * aquele bicho — é o "desfazer" mais curto possível.
 */
function pintarEscolhidosVitrine() {
  const host = $('#vte-escolhidos');
  if (!host) return;
  const porId = new Map((estado.eu?.pokemons ?? []).map((p) => [p.id, p]));
  host.replaceChildren(...vitrineRascunho.map((id, i) => {
    const pk = porId.get(id);
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'vte-chip';
    chip.title = t('pf.vitrineTirar');
    chip.innerHTML = `
      <span class="vte-chip-pos">${num(i + 1)}</span>
      <span class="vte-chip-arte"></span>
      <span class="vte-chip-nome">${escapar(pk?.nome ?? '—')}</span>
      <span class="vte-chip-x">×</span>`;
    if (pk) chip.querySelector('.vte-chip-arte').appendChild(spritePokemon(pk, 28));
    chip.onclick = () => alternarNaVitrine(id);
    return chip;
  }));
  const vazio = $('#vte-vazio');
  if (vazio) vazio.classList.toggle('hidden', vitrineRascunho.length > 0);
}

function montarEditorVitrine() {
  if (!vitrineRascunho) return;
  const grade = $('#vte-grade');
  if (!grade) return;

  const conta = $('#vte-conta');
  if (conta) conta.textContent = `${num(vitrineRascunho.length)}/${num(MAX_VITRINE)}`;
  pintarEscolhidosVitrine();

  // A busca é obrigatória, não enfeite: uma conta de um mês passa de 200 bichos, e sem ela
  // achar o Gengar shiny custaria uma rolagem inteira. É o mesmo campo do Depot.
  const busca = ($('#vte-busca')?.value ?? '').trim().toLowerCase();
  const local = $('#vte-local')?.value || 'todos';
  const colecao = conjuntoColecaoCliente();
  const lista = (estado.eu?.pokemons ?? [])
    .filter((p) => (!busca || (p.nome ?? '').toLowerCase().includes(busca)) && passaLocal(p, local, colecao))
    // Escolhidos primeiro, depois os mais fortes: a vitrine é sobre o que se tem de melhor, e
    // quem já está nela precisa ficar à vista para poder sair.
    .sort((a, b) => {
      const na = vitrineRascunho.includes(a.id) ? 0 : 1;
      const nb = vitrineRascunho.includes(b.id) ? 0 : 1;
      return na - nb || (b.poder ?? 0) - (a.poder ?? 0);
    });

  const vazioBusca = $('#vte-sem-resultado');
  if (vazioBusca) vazioBusca.classList.toggle('hidden', lista.length > 0);

  grade.replaceChildren(...lista.map((pk) => {
    const pos = vitrineRascunho.indexOf(pk.id);
    const card = cardPokemonEscolha(pk, {
      colecao,
      aoVerFicha: () => abrirFichaDoPokemon(pk),
      aoSelecionar: () => alternarNaVitrine(pk.id),
    });
    if (pos >= 0) {
      card.classList.add('vte-on');
      const selo = document.createElement('span');
      selo.className = 'vte-pos';
      selo.textContent = num(pos + 1);
      card.querySelector('.mk-card-topo').appendChild(selo);
    }
    return card;
  }));
}

function salvarVitrine() {
  if (!vitrineRascunho) return;
  enviar({ t: 'perfil.vitrine', ids: vitrineRascunho.slice(0, MAX_VITRINE) });
  fecharEditorVitrine();
  toast(t('pf.vitrineSalva'));
}

// ---------------------------------------------------------------- o armário
//
// A coleção de outfits do jogador, num lugar só.
//
// Antes dela, trocar de roupa era um caminho torto: abrir a Loja, ir à seção Outfits, achar no
// meio dos produtos à venda aquela que já tinha sido comprada e clicar em "Equipar". Ou seja,
// para vestir o que já era seu você passava por uma vitrine — e o que estava no armário
// dependia de lembrar o nome dela.
//
// Aqui a pergunta é a outra: "o que eu tenho?". As que dão para vestir agora vêm na grade de
// cima, com o boneco animado e um clique para equipar. As que faltam vêm embaixo, apagadas,
// com o atalho para a Loja — não para vender à força, mas porque uma coleção que esconde o que
// falta não parece uma coleção.

/** O looktype padrão do gênero — a "roupa de sempre", que ninguém compra e ninguém perde. */
const looktypePadrao = () => LOOK_DO_GENERO[estado.eu?.loja?.gender ?? 'male'] ?? 159;

/**
 * Tudo que é outfit, com o estado de cada uma.
 *
 * `{ looktype, nome, tenho, equipada, motivo }` — `motivo` só existe para as que faltam, e diz
 * POR QUE faltam ('vip', 'caixa' ou o preço em diamante). A ordem é a de leitura: a padrão
 * primeiro (é a âncora, e é a que se usa para "tirar" uma skin), depois as que ele tem, depois
 * as que faltam.
 */
function outfitsDoArmario() {
  const l = estado.eu?.loja ?? {};
  const padrao = looktypePadrao();
  const tenho = new Set([padrao]);
  // Outfit de caixa NÃO vale pelo `ownedOutfits` sozinho — só pela tag (caixa aberta). A lista
  // em memória pode ficar desatualizada se alguém apagou linhas de teste no banco.
  for (const lt of l.ownedOutfits ?? []) {
    if (!LOOKTYPES_CAIXA_BETA.has(lt)) tenho.add(lt);
  }
  for (const tag of estado.eu?.caixas?.tags ?? []) {
    const def = CAIXAS_BETA[tag.tipo];
    if (def) tenho.add(def.looktype);
  }

  const lista = [{
    looktype: padrao,
    nome: t('armario.padrao'),
    tenho: true,
    padrao: true,
  }];

  const vistos = new Set([padrao]);
  for (const prod of estado.lojaProdutos ?? []) {
    if (prod.looktype == null || vistos.has(prod.looktype)) continue;
    vistos.add(prod.looktype);
    // A outfit de VIP só é vestível com assinatura ATIVA: tê-la "comprada" não basta, e é
    // isso que o servidor responde. Mostrá-la como disponível seria prometer um "Equipar"
    // que volta com "essa outfit é exclusiva de VIP".
    const daVip = !!prod.vipExclusive;
    const disponivel = daVip ? !!l.vip : tenho.has(prod.looktype);
    lista.push({
      looktype: prod.looktype,
      nome: prod.nome,
      tenho: disponivel,
      motivo: disponivel ? null : daVip ? 'vip' : prod.betaExclusive ? 'beta' : 'preco',
      preco: prod.preco ?? 0,
    });
  }

  for (const def of LISTA_CAIXAS) {
    if (vistos.has(def.looktype)) continue;
    vistos.add(def.looktype);
    lista.push({
      looktype: def.looktype,
      nome: t(`caixas.outfit.${def.tipo}`),
      tenho: tenho.has(def.looktype),
      motivo: tenho.has(def.looktype) ? null : 'caixa',
      caixa: def.tipo,
    });
  }

  return lista;
}

function renderArmario() {
  return `<div id="armario-corpo" class="armario"></div>`;
}

function montarArmario() {
  const host = $('#armario-corpo');
  if (!host) return;
  const equipada = estado.eu?.loja?.looktype;
  const lista = outfitsDoArmario();
  const minhas = lista.filter((o) => o.tenho);
  const faltam = lista.filter((o) => !o.tenho);

  host.innerHTML = `
    <div class="armario-cabeca">
      <h4>${escapar(t('armario.minhas'))}</h4>
      <span class="armario-conta">${escapar(t('armario.conta', { n: num(minhas.length), total: num(lista.length) }))}</span>
    </div>
    <div class="armario-grade" id="armario-minhas"></div>
    ${faltam.length
      ? `<div class="armario-cabeca segunda">
           <h4>${escapar(t('armario.faltam'))}</h4>
           <button class="armario-loja" id="armario-loja">${escapar(t('armario.verLoja'))}</button>
         </div>
         <div class="armario-grade apagada" id="armario-faltam"></div>`
      : ''}`;

  const cartao = (o) => {
    const el = document.createElement(o.tenho ? 'button' : 'div');
    el.className = `armario-card ${o.tenho ? '' : 'travada'} ${o.looktype === equipada ? 'on' : ''}`;
    if (o.caixa) el.style.setProperty('--cx-cor', CAIXAS_BETA[o.caixa]?.cor ?? 'var(--rx)');
    // A TAG que vem junto da roupa. Só nas outfits de caixa que ele tem, e é a informação que
    // faz a tela inteira fazer sentido: vestir esta skin é assinar o chat com ESTA tag (ver
    // `tagDoLooktype` no servidor). Sem o selo aqui, a troca de etiqueta ao trocar de roupa
    // pareceria efeito colateral em vez de escolha.
    const tag = o.tenho && o.caixa ? tagDaCaixaDoJogador(o.caixa) : null;
    el.innerHTML = `
      <span class="armario-boneco"></span>
      <span class="armario-nome">${escapar(o.nome)}</span>
      ${tag ? `<span class="armario-tag">${tagDaCaixaHtml(o.caixa, tag.serie)}</span>` : ''}
      <span class="armario-rodape">${
        o.looktype === equipada
          ? `<b class="armario-vestindo">${escapar(t('armario.vestindo'))}</b>`
          : o.tenho
            ? `<b class="armario-equipar">${escapar(t('armario.equipar'))}</b>`
            : `<i>${escapar(rotuloTravaOutfit(o))}</i>`
      }</span>`;
    // O boneco vai VESTIDO com as cores do jogador (`empacotarVisual`): é a mesma roupa que
    // ele vai ver no campo, e não uma prévia num boneco de outra pessoa. As outfits que já
    // trazem cor própria (caixa, cosplay) ignoram a máscara sozinhas.
    el.querySelector('.armario-boneco').appendChild(
      spriteAnimado(o.looktype, 62, 3, null, empacotarVisual(estado.eu?.loja?.visual)),
    );
    if (o.tenho && o.looktype !== equipada) {
      el.onclick = () => enviar({ t: 'loja.equipar', looktype: o.looktype });
    } else if (o.tenho) {
      el.disabled = true;
    }
    return el;
  };

  const gradeMinhas = host.querySelector('#armario-minhas');
  for (const o of minhas) gradeMinhas.appendChild(cartao(o));
  const gradeFaltam = host.querySelector('#armario-faltam');
  if (gradeFaltam) for (const o of faltam) gradeFaltam.appendChild(cartao(o));

  const irLoja = host.querySelector('#armario-loja');
  if (irLoja) {
    irLoja.onclick = () => {
      estado.grupoLoja = 'outfits';
      abrirModal('shop');
    };
  }
}

/** Por que esta outfit não está disponível — o texto pequeno do card apagado. */
function rotuloTravaOutfit(o) {
  if (o.motivo === 'vip') return t('armario.soVip');
  // A caixa entra pelo NOME dela: dizer "vem numa Caixa de Fundador" embaixo da outfit de
  // CoFundador manda a pessoa comprar a caixa errada.
  if (o.motivo === 'caixa') return t('armario.soCaixa', { nome: t(`caixas.nome.${o.caixa}`) });
  if (o.motivo === 'beta') return t('armario.soBeta');
  return t('armario.custa', { n: num(o.preco ?? 0) });
}

function statsColecaoPerfil(e = estado.eu) {
  const entradas = Object.values(e?.pokedex ?? {});
  const poks = e?.pokemons ?? [];
  return {
    shinysVistos: entradas.reduce((s, d) => s + (Number(d.sv) || 0), 0),
    shinysTem: poks.filter((p) => p.shiny).length,
    p5Tem: poks.filter((p) => Number(p.potencia) === 5).length,
  };
}

function renderPerfilProprio() {
  const e = estado.eu ?? {};
  const dex = e.pokedex ?? {};
  const entradas = Object.values(dex);
  const capturas = entradas.reduce((s, d) => s + (d.c ?? 0), 0);
  const derrotas = entradas.reduce((s, d) => s + (d.k ?? 0), 0);
  const { capturadas, total } = contagemEspeciesDexPerfil();
  const col = statsColecaoPerfil(e);

  const corpo = htmlPerfilTreinador({
    nick: e.nick,
    // O troféu e as medalhas de campeonato, que o perfil de OUTRO jogador recebe em `conquistas`.
    conquistas: e.campConquistas,
    level: e.level,
    xp: e.xp,
    xpNivel: e.xpNivel,
    xpProximo: e.xpProximo,
    visualTrocaLivreEm: e.loja?.visualTrocaLivreEm,
    capturadasDex: capturadas,
    totalDex: total,
    capturas,
    derrotas,
    bossPontos: e.boss?.pontos ?? 0,
    // `estado.pvpRank`, e não `e.pvp`: o snapshot é só a semente, e quem fica em dia depois de
    // cada partida é o estado (ver `aoReceberPvp`).
    pvpRank: estado.pvpRank ?? e.pvp ?? null,
    time: (e.pokemons ?? []).length,
    gold: e.gold ?? 0,
    orbs: e.orbs ?? 0,
    vip: e.loja?.vip,
    statsPublico: e.loja?.perfilStatsPublico !== false,
    // A tag de FUNDADOR na ficha própria. Sai de `e.caixas.tag`, que é a MESMA fonte que o
    // chat usava antes de a etiqueta sair de lá (`tagDoLooktype` no servidor): vale a caixa da
    // roupa que ele está vestindo e, fora dela, a melhor que ele tem.
    fundador: e.caixas?.tag ?? null,
    // E a TAG DA GUILD, nas duas fichas: é o que diz de que clã a pessoa é sem ter de abrir o
    // ranking de guilds e procurar o nick lá dentro.
    guildTag: e.guild?.tag ?? null,
    guildTagCor: e.guild?.tagCor ?? null,
    guildNome: e.guild?.nome ?? null,
    ...col,
  }, { mostrarAvatarBtn: true, mostrarVitrine: true });

  // As ESTATÍSTICAS DA CONTA existem só aqui, na ficha do próprio jogador: a ficha pública
  // (`mostrarPerfil`) não tem esta seção, e o servidor só responde sobre quem pediu.
  return `${corpo}
    <h3>${t('pf.secaoEstatisticas')}</h3>
    <div id="pf-estat">
      <div class="pf-carregando">${t('pf.carregandoEstatisticas')}</div>
    </div>
    <h3>${t('pf.secaoConta')}</h3>
    <div class="pf-secao" id="pf-conta">
      <div class="pf-carregando">${t('pf.carregandoConta')}</div>
    </div>`;
}

/** "312 h 05 min" / "45 min" — horas, e não dias: é a régua com que todo jogo conta tempo jogado. */
function tempoJogadoTexto(segundos) {
  const min = Math.floor(Math.max(0, Number(segundos) || 0) / 60);
  const h = Math.floor(min / 60);
  if (min < 1) return t('pf.estatMenosMin');
  if (h < 1) return t('pf.estatMin', { m: num(min) });
  return t('pf.estatHoras', { h: num(h), m: String(min % 60).padStart(2, '0') });
}

/** Pede as estatísticas da conta. A resposta (`estatisticas`) pinta `#pf-estat` se ela ainda estiver na tela. */
function pedirEstatisticasDaConta() {
  enviar({ t: 'perfil.estatisticas' });
  // Sem resposta em 10 s (banco fora, socket caído no meio), a seção diz isso em vez de ficar
  // "carregando" para sempre.
  setTimeout(() => {
    const host = $('#pf-estat');
    if (host?.querySelector('.pf-carregando')) host.innerHTML = `<div class="pf-aviso">${t('pf.estatFalhou')}</div>`;
  }, 10_000);
}

/**
 * O quadro das ESTATÍSTICAS DA CONTA: o que já entrou (coins, diamantes, gemas) e o tempo jogado.
 *
 * Coins e tempo têm a data do começo da medição embaixo: o jogo só passou a contá-los numa versão
 * recente (ver `game/vitalicio.mjs` no servidor), e apresentar como "a vida inteira" o que é só
 * a parte medida enganaria justamente o veterano. Diamantes e gemas saem dos extratos, que guardam
 * tudo desde a criação da conta — esses não precisam de data.
 */
function pintarEstatisticasDaConta(m) {
  const host = $('#pf-estat');
  if (!host) return;
  const desde = m.desde ? new Date(m.desde).toLocaleDateString(localeData()) : null;
  const nota = desde ? t('pf.estatDesde', { data: desde }) : '';
  host.innerHTML = `
    <div class="pf-blocos">
      ${fichaBloco(t('pf.estatOuro'), num(m.ouro ?? 0), nota)}
      ${fichaBloco(t('pf.estatDiamantes'), num(m.diamantes ?? 0))}
      ${fichaBloco(t('pf.estatGemas'), num(m.gemas ?? 0))}
      ${fichaBloco(t('pf.estatTempo'), tempoJogadoTexto(m.tempoS), nota)}
    </div>
    <p class="pf-ajuda">${t('pf.estatNota')}</p>`;
}

/** Refresh barato da Ficha do Treinador — números e barra de XP, sem remontar o modal. */
function atualizarPerfil(e, anterior) {
  if (!$('#pf-retrato')) return;

  const cara = `${e.loja?.looktype}|${empacotarVisual(e.loja?.visual).join(',')}`;
  if (estado.caraPerfilDesenhada !== cara) {
    estado.caraPerfilDesenhada = cara;
    $('#pf-retrato').replaceChildren(spriteDeMim(56));
  }

  // A vitrine só é remontada quando o time muda de verdade — cada card tem um canvas animado,
  // e refazer os cinco a cada snapshot faria os sprites reiniciarem duas vezes por segundo.
  if (assinaturaVitrinePerfil(e) !== estado.assinaturaVitrinePerfil) montarVitrinePerfil();

  const dentro = Math.max(0, (e.xp ?? 0) - (e.xpNivel ?? 0));
  const faixa = Math.max(1, (e.xpProximo ?? 1) - (e.xpNivel ?? 0));
  const nvEl = document.querySelector('#modal-corpo .pf-nivel b');
  if (nvEl && e.level !== anterior?.level) nvEl.textContent = num(e.level ?? 1);
  const fill = document.querySelector('#modal-corpo .pf-id .barra.xp .fill');
  if (fill) fill.style.width = `${Math.min(100, (dentro / faixa) * 100)}%`;
  const xpSpan = document.querySelector('#modal-corpo .pf-id .barra.xp span');
  if (xpSpan) xpSpan.textContent = `${num(dentro)} / ${num(faixa)} xp`;

  const dex = e.pokedex ?? {};
  const entradas = Object.values(dex);
  const capturas = entradas.reduce((s, d) => s + (d.c ?? 0), 0);
  const derrotas = entradas.reduce((s, d) => s + (d.k ?? 0), 0);
  const { capturadas, total } = contagemEspeciesDexPerfil();
  const blocos = document.querySelector('#modal-corpo .pf-blocos');
  if (blocos) {
    blocos.innerHTML =
      fichaBloco(t('pf.especies'), `${num(capturadas)} / ${num(total)}`) +
      fichaBloco(t('pf.capturas'), num(capturas)) +
      fichaBloco(t('pf.derrotados'), num(derrotas)) +
      fichaBloco(t('pf.bossPontos'), num(e.boss?.pontos ?? 0)) +
      fichaBlocoElo(estado.pvpRank ?? e.pvp ?? null);
  }

  const jogo = document.querySelector('#modal-corpo .pf-secao:not(#pf-conta):not(#pf-estat)');
  if (jogo) {
    const time = (e.pokemons ?? []).length;
    jogo.innerHTML =
      fichaLinha(t('pf.time'), `${num(time)} ${t('pf.pokemon')}`) +
      fichaLinha(t('pf.ouro'), moeda(e.gold ?? 0)) +
      fichaLinha(t('pf.orbs'), num(e.orbs ?? 0)) +
      fichaLinha(t('pf.vip'), e.loja?.vip ? t('pf.vipAtivo') : t('pf.vipNao'));
  }
}

/**
 * Excluir a conta, primeiro degrau (o segundo é digitar o nick no formulário). O boneco sem cor com
 * a lixeira no canto, e cada perda numa linha vermelha com o seu desenho — é a única caixa do jogo
 * em que TUDO o que ela lista some.
 */
function confirmarExcluirConta(nickCru, aoConfirmar) {
  const nick = escapar(nickCru ?? '');
  confirmar({
    titulo: t('pf.excluirContaTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({ arte: dlgArteTreinador(null, null, 72), nome: nick, classe: 'sai', marca: dlgIcone('lixeira', 14) }), 'perigo')}
      <p class="dlg-lead dlg-perigo-lead">${escapar(t('pf.excluirAtencao'))}</p>
      ${dlgLista([
        { icone: 'pessoaMenos', html: t('pf.excluirPerdaPersonagem', { nick }), perigo: true },
        { icone: 'lixeira', html: t('pf.excluirPerdaProgresso'), perigo: true },
        { icone: 'moedas', html: t('pf.excluirPerdaGemas'), perigo: true },
        { icone: 'relogio', html: t('pf.excluirReembolso') },
      ])}
      ${dlgFrase('', t('pf.excluirContinue'))}`,
    rotuloSim: t('pf.excluirContaConfirmar'),
    tom: 'perigo',
    aoConfirmar,
  });
}

/**
 * A parte de CONTA do modal, que chega depois do resto.
 *
 * O botão de trocar senha só existe para conta com senha: quem entra pelo Google não tem uma
 * para trocar, e oferecer o botão mandaria a pessoa a um e-mail que não resolve nada. Para
 * esses, a linha diz por onde ela entra — que é a informação útil ali.
 */
async function montarContaDoPerfil() {
  const host = $('#pf-conta');
  if (!host) return;
  const sessao = sessaoSalva();
  const nickJogador = estado.eu?.nick ?? '';

  if (!sessao?.token) {
    host.innerHTML = `<div class="pf-aviso">${t('pf.semConta')}</div>`;
    return;
  }

  let conta;
  try {
    const r = await fetch('/auth/conta', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ token: sessao.token }),
    });
    if (!r.ok) throw new Error('conta');
    conta = await r.json();
  } catch {
    host.innerHTML = `<div class="pf-aviso">${t('pf.contaFalhou')}</div>`;
    return;
  }

  const PROVEDOR = { google: 'Google', discord: 'Discord', local: t('pf.provedorSenha') };
  const provedorNome = PROVEDOR[conta.provedor] ?? conta.provedor;
  const podeEmail = conta.emailLigado && conta.temEmail;
  const oauth = !!conta.oauth;
  const pedeSenhaNova = !conta.temSenha;
  // A senha só entra no formulário de excluir quando é ELA que abre a conta. Conta ligada a
  // um provedor pode carregar um `senha_hash` antigo (criou com senha, depois entrou pelo
  // Google) — e pedir ali uma senha que a pessoa não usa desde então trancava a exclusão.
  // O espelho desta regra mora em `excluirMinhaConta` (`server/auth.mjs`), que é quem decide.
  const pedeSenhaExcluir = conta.temSenha && !oauth;
  const ajudaTrocarEmail = !podeEmail
    ? t('pf.trocarEmailIndisponivel')
    : (pedeSenhaNova && oauth
      ? t('pf.trocarEmailOAuthAjuda', { provedor: provedorNome })
      : t('pf.trocarEmailAjuda'));

  host.innerHTML =
    fichaLinha(t('pf.entraPor'), provedorNome) +
    (conta.temEmail
      ? fichaLinha(
          t('pf.email'),
          `${escapar(conta.email)} ${conta.emailOk
            ? `<em class="pf-ok">${t('pf.emailConfirmado')}</em>`
            : `<em class="pf-pendente">${t('pf.emailPendente')}</em>`}`,
        )
      : '') +
    (conta.temSenha
      ? `<button class="pf-acao" id="pf-trocar-senha" ${conta.temEmail && podeEmail ? '' : 'disabled'}>
           ${t('pf.trocarSenha')}</button>
         <p class="pf-ajuda">${conta.temEmail && podeEmail ? t('pf.trocarSenhaAjuda') : t('pf.trocarSenhaIndisponivel')}</p>`
      : `<p class="pf-ajuda">${t('pf.semSenhaAjuda', { provedor: provedorNome })}</p>`) +
    `<button class="pf-acao" id="pf-trocar-email" ${podeEmail ? '' : 'disabled'}>${t('pf.trocarEmail')}</button>
     <p class="pf-ajuda">${ajudaTrocarEmail}</p>
     <form class="pf-email-form hidden" id="pf-email-form">
       <label class="pf-campo"><span>${t('pf.novoEmail')}</span>
         <input type="email" id="pf-email-novo" maxlength="120" autocomplete="email"></label>
       ${pedeSenhaNova
         ? `<label class="pf-campo"><span>${t('pf.novaSenhaLogin')}</span>
              <input type="password" id="pf-email-senha-nova" maxlength="72" autocomplete="new-password"></label>
            <label class="pf-campo"><span>${t('pf.novaSenhaLogin2')}</span>
              <input type="password" id="pf-email-senha-nova2" maxlength="72" autocomplete="new-password"></label>`
         : `<label class="pf-campo"><span>${t('pf.senhaAtual')}</span>
              <input type="password" id="pf-email-senha-atual" maxlength="72" autocomplete="current-password"></label>`}
       <button type="submit" class="pf-acao" id="pf-email-enviar">${t('pf.trocarEmail')}</button>
     </form>
     <div class="pf-zona-perigo">
       <h4 class="pf-perigo-titulo">${t('pf.secaoPerigo')}</h4>
       <button type="button" class="pf-acao pf-acao-perigo" id="pf-excluir-conta">${t('pf.excluirConta')}</button>
       <form class="pf-excluir-form hidden" id="pf-excluir-form">
         <p class="pf-excluir-resumo">${t('pf.excluirContaTexto', { nick: escapar(nickJogador || conta.nick) })}</p>
         <label class="pf-campo"><span>${t('pf.excluirNickLabel')}</span>
           <input type="text" id="pf-excluir-nick" maxlength="16" autocomplete="off" spellcheck="false"></label>
         ${pedeSenhaExcluir
           ? `<label class="pf-campo"><span>${t('pf.excluirSenhaLabel')}</span>
                <input type="password" id="pf-excluir-senha" maxlength="72" autocomplete="current-password"></label>`
           : `<p class="pf-ajuda">${t('pf.excluirOAuthAjuda', { provedor: provedorNome })}</p>`}
         <button type="submit" class="pf-acao pf-acao-perigo" id="pf-excluir-final">${t('pf.excluirFinal')}</button>
       </form>
     </div>`;

  /** Contagem regressiva compartilhada — senha e e-mail usam o mesmo padrão de botão. */
  const contarAte = (botao, ms, rotulo, chaveEspera) => {
    let esperaAte = Date.now() + ms;
    const pintar = () => {
      const resta = esperaAte - Date.now();
      if (resta <= 0) {
        botao.disabled = false;
        botao.textContent = rotulo;
        return false;
      }
      const min = Math.floor(resta / 60000);
      const seg = Math.floor((resta % 60000) / 1000);
      botao.disabled = true;
      botao.textContent = t(chaveEspera, { tempo: `${min}:${String(seg).padStart(2, '0')}` });
      return true;
    };
    clearInterval(botao._timerConta);
    if (!pintar()) return;
    botao._timerConta = setInterval(() => {
      if (!botao.isConnected || !pintar()) clearInterval(botao._timerConta);
    }, 1000);
  };

  const botaoSenha = $('#pf-trocar-senha');
  if (botaoSenha) {
    contarAte(botaoSenha, conta.senhaEsperaMs ?? 0, t('pf.trocarSenha'), 'pf.trocarSenhaEspera');
    botaoSenha.onclick = async () => {
      botaoSenha.disabled = true;
      botaoSenha.textContent = t('pf.enviando');
      try {
        const r = await fetch('/auth/recuperar', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ token: sessao.token }),
        });
        const dados = await r.json().catch(() => ({}));
        if (!r.ok) {
          contarAte(botaoSenha, dados.esperaMs ?? 0, t('pf.trocarSenha'), 'pf.trocarSenhaEspera');
          throw new Error(dados.erro ?? 'login.falhou');
        }
        contarAte(botaoSenha, UMA_HORA_MS, t('pf.trocarSenha'), 'pf.trocarSenhaEspera');
        toast(t('pf.enviadoPara', { email: conta.email }));
      } catch (err) {
        toast(t(String(err.message)));
      }
    };
  }

  const botaoEmail = $('#pf-trocar-email');
  const formEmail = $('#pf-email-form');
  const enviarEmail = $('#pf-email-enviar');
  if (botaoEmail && formEmail) {
    contarAte(botaoEmail, conta.emailEsperaMs ?? 0, t('pf.trocarEmail'), 'pf.trocarEmailEspera');
    botaoEmail.onclick = () => {
      formEmail.classList.toggle('hidden');
      if (!formEmail.classList.contains('hidden')) $('#pf-email-novo')?.focus();
    };
    formEmail.onsubmit = async (ev) => {
      ev.preventDefault();
      const novoEmail = $('#pf-email-novo')?.value?.trim() ?? '';
      const senha = $('#pf-email-senha-atual')?.value ?? '';
      const senhaNova = $('#pf-email-senha-nova')?.value ?? '';
      const senhaNova2 = $('#pf-email-senha-nova2')?.value ?? '';
      if (!emailPermitidoCadastro(novoEmail)) return toast(t('login.emailDominio'));
      if (pedeSenhaNova) {
        if (senhaNova.length < 8) return toast(t('login.senhaCurta'));
        if (senhaNova !== senhaNova2) return toast(t('login.senhasDiferentes'));
      } else if (!senha) {
        return toast(t('login.credenciaisInvalidas'));
      }
      enviarEmail.disabled = true;
      enviarEmail.textContent = t('pf.enviando');
      try {
        const r = await fetch('/auth/trocar-email/pedir', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({
            token: sessao.token,
            novoEmail,
            senha: pedeSenhaNova ? undefined : senha,
            senhaNova: pedeSenhaNova ? senhaNova : undefined,
          }),
        });
        const dados = await r.json().catch(() => ({}));
        if (!r.ok) {
          contarAte(botaoEmail, dados.esperaMs ?? 0, t('pf.trocarEmail'), 'pf.trocarEmailEspera');
          throw new Error(dados.erro ?? 'login.falhou');
        }
        formEmail.classList.add('hidden');
        contarAte(botaoEmail, UMA_HORA_MS, t('pf.trocarEmail'), 'pf.trocarEmailEspera');
        toast(t('pf.enviadoEmailAtual', { email: dados.email ?? conta.email }));
      } catch (err) {
        toast(t(String(err.message)));
      } finally {
        enviarEmail.disabled = false;
        enviarEmail.textContent = t('pf.trocarEmail');
      }
    };
  }

  const botaoExcluir = $('#pf-excluir-conta');
  const formExcluir = $('#pf-excluir-form');
  if (botaoExcluir && formExcluir) {
    botaoExcluir.onclick = () => confirmarExcluirConta(nickJogador || conta.nick, () => {
      formExcluir.classList.remove('hidden');
      botaoExcluir.classList.add('hidden');
      $('#pf-excluir-nick')?.focus();
    });
    formExcluir.onsubmit = async (ev) => {
      ev.preventDefault();
      const final = $('#pf-excluir-final');
      final.disabled = true;
      final.textContent = t('pf.excluirExcluindo');
      try {
        const r = await fetch('/auth/excluir', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({
            token: sessao.token,
            nickConfirmacao: $('#pf-excluir-nick')?.value?.trim() ?? '',
            senha: $('#pf-excluir-senha')?.value ?? '',
          }),
        });
        const dados = await r.json().catch(() => ({}));
        if (!r.ok) throw new Error(dados.erro ?? 'login.falhou');
        limparSessao();
        toast(t('conta.excluirOk'));
        location.replace('/');
      } catch (err) {
        toast(t(String(err.message)));
        final.disabled = false;
        final.textContent = t('pf.excluirFinal');
      }
    };
  }
}

// ------------------------------------------------------- Mercado Global
//
// Anúncios entre jogadores. A vitrine, o anunciar em três passos e os meus anúncios moram
// todos neste modal — são o mesmo assunto e trocar de tela para publicar tiraria da vista
// justamente o preço dos outros, que é a referência de quanto cobrar.
//
// Nada aqui decide nada: preço, taxa e escrow são do servidor (`market-db.mjs`). Esta tela
// só desenha o que ele manda e pede o que o jogador clicou.

/**
 * As duas vitrines. NÃO existe "Todos", e é de propósito.
 *
 * Pokémon e item se leem de formas diferentes: o pokémon é uma linha por bicho, com nível,
 * potência e IV; o item é o CATÁLOGO (pedra, TM, ficha), agrupado por espécie de item e com
 * as duas colunas de preço. Misturar os dois numa lista só dava a vitrine que motivou este
 * corte — pedras e fichas empilhadas entre pokémon, sem a grade de nenhum dos dois.
 *
 * Também não havia ordenação honesta para a mistura: "maior nível" e "maior IV" não querem
 * dizer nada num Fire Stone, e a barra caía nas duas ordenações que sobravam.
 */
const FILTROS_TIPO = [
  { id: 'pokemon', nome: 'cm.pokemon', ico: 'img:site/assets/ui/ball-poke.png' },
  { id: 'item', nome: 'cm.itens', ico: 'img:site/assets/ui/menu-bolsa.png' },
  // DIAMANTES — a terceira mercadoria. Só o diamante COMPRADO (ou vindo de indicação) entra;
  // a regra e o porquê estão em `MOTIVOS_DA_COTA_DE_VENDA` (`server/game/diamantes.mjs`), e a
  // tela de anunciar a escreve por extenso antes de deixar escolher a quantidade.
  { id: 'diamante', nome: 'cm.diamantes', ico: `img:${ICONE_DIAMANTE}` },
];

/**
 * Abas que mandam UMA moeda ao servidor — é o que faz "menor preço" querer dizer alguma coisa
 * (900 Coins e 3 gemas não se comparam por número).
 *
 * Diamante entra aqui, mas NÃO na barra lateral: a chave dele mora dentro do painel de
 * ofertas (`.cmp-switch`, em `pintarVitrineDiamantes`), como no mercado de itens. Duas chaves
 * para a mesma coisa na mesma tela é uma a mais.
 */
const abaFiltraMoeda = (tipo) => tipo === 'pokemon' || tipo === 'diamante';

/**
 * "Todas" — Coins E gemas na mesma vitrine. Só na aba de POKÉMON.
 *
 * A escolha exclusiva existe porque os dois preços não se comparam por número, e ela continua
 * sendo o padrão. Só que na grade por ESPÉCIE a comparação deixa de ser o produto: o card diz "a
 * partir de X Coins" e "a partir de Y gemas" em linhas separadas, e quem procura um Dragonite não
 * quer descobrir na terceira tentativa que o único à venda está anunciado na outra moeda.
 *
 * Na lista de ofertas de uma espécie o cuidado volta, e mora no servidor: sem moeda escolhida,
 * "mais barato" ordena DENTRO de cada moeda (ver `ORDENS_DUAS_MOEDAS`, em `market-db.mjs`).
 *
 * Diamante fica de fora: ali a lista inteira é uma comparação de preço por unidade — é para isso
 * que a aba existe —, e misturar as moedas nela desfaria a única leitura que ela oferece.
 */
const MOEDA_TODAS = 'todas';
const abaAceitaTodasMoedas = (tipo) => tipo === 'pokemon';
const moedaDoPedido = (f) =>
  !abaFiltraMoeda(f.tipo) || (f.moeda === MOEDA_TODAS && abaAceitaTodasMoedas(f.tipo))
    ? ''
    : f.moeda === 'orb' ? 'orb' : 'gold';

/** Quem desenha a chave de moeda NA BARRA LATERAL. Só pokémon. */
const abaEscolheMoeda = (tipo) => tipo === 'pokemon';
/** Filtros extras da Tabela de preços — depósitos e saques de gemas (RMT). */
const FILTROS_HIST_GLOBAL = [
  ...FILTROS_TIPO,
  { id: 'deposito', nome: 'cm.historicoDeposito', ico: `img:${ICONE_GEMA}` },
  { id: 'saque', nome: 'cm.historicoSaque', ico: `img:${ICONE_GEMA}` },
];
const FILTROS_MOEDA = [
  { id: 'gold', nome: 'cm.emCoins', ico: `img:${ICONE_OURO}` },
  { id: 'orb', nome: 'cm.emGemas', ico: `img:${ICONE_GEMA}` },
];

/**
 * As DUAS listas de ordenação da vitrine — o espelho de `CRITERIOS` e `ORDENS` em
 * `server/market-db.mjs`, que é quem as transforma em SQL.
 *
 * ### Por que deixaram de ser uma
 *
 * Havia um só "Ordenar por" com dezesseis opções misturando duas naturezas: coisas do MERCADO
 * (preço, recência) e coisas do POKÉMON (IV, nota, qualidade, potência, refino). Como o
 * `<select>` escolhe UMA, as perguntas que o jogador de fato faz não cabiam:
 *
 *     "o de melhor nota que esteja mais barato"
 *     "P5 primeiro, e entre os P5 o de IV mais alto, e entre esses o mais barato"
 *
 * Elas não competiam pelo mesmo lugar: uma é o CRITÉRIO e a outra é o DESEMPATE. Separando, o
 * "Filtrar por" aceita vários (na ordem em que forem ligados, que vira a prioridade) e o
 * "Ordenar por" fecha a conta.
 *
 * ### Por que o empate deixa de ser detalhe
 *
 * `potencia` tem cinco valores e `ivTotal` é inteiro: há centenas de anúncios empatados em cada
 * degrau, e é o "Ordenar por" no fim que decide o que aparece primeiro dentro do degrau. É daí
 * que sai o "P5 mais barato" que antes não existia.
 */

/** O eixo do MERCADO — um só, e é ele que fecha o `ORDER BY`. */
const ORDENS_MERCADO = [
  { id: 'recentes', nome: 'cm.ordRecentes' },
  { id: 'baratos', nome: 'cm.ordBaratos' },
  { id: 'caros', nome: 'cm.ordCaros' },
];

/**
 * Os critérios do POKÉMON — combináveis, e só na aba de pokémon.
 *
 * A ordem desta lista é a que o menu mostra; a ordem de PRIORIDADE é a de clique, guardada em
 * `cmFiltro.criterios`. As duas são diferentes de propósito: quem liga "potência" e depois
 * "IV" está dizendo "potência primeiro", e reordenar pela lista fixa apagaria essa escolha.
 */
const CRITERIOS_MERCADO = [
  { id: 'nota', nome: 'cm.ordNota' },
  { id: 'iv', nome: 'cm.ordIv' },
  { id: 'qualidade', nome: 'cm.ordQualidade' },
  { id: 'potencia', nome: 'cm.ordPotencia' },
  { id: 'nivel', nome: 'cm.ordNivel' },
  { id: 'refino', nome: 'cm.ordRefino' },
  { id: 'ivHp', nome: 'cm.ordIvHp' },
  { id: 'ivAtk', nome: 'cm.ordIvAtk' },
  { id: 'ivDef', nome: 'cm.ordIvDef' },
  { id: 'ivSpAtk', nome: 'cm.ordIvSpAtk' },
  { id: 'ivSpDef', nome: 'cm.ordIvSpDef' },
  { id: 'ivSpd', nome: 'cm.ordIvSpd' },
];

/** Teto de critérios por consulta — o mesmo `MAX_CRITERIOS` do servidor. */
const MAX_CRITERIOS_MERCADO = 6;

const criterioMercado = (id) => CRITERIOS_MERCADO.find((c) => c.id === id) ?? null;

/** Os critérios ligados agora, na ordem de prioridade, já sem lixo de versão antiga. */
const criteriosDoMercado = () =>
  (estado.cmFiltro.criterios ?? []).filter(criterioMercado).slice(0, MAX_CRITERIOS_MERCADO);

/**
 * Liga ou desliga um critério, preservando a ordem de clique.
 *
 * Ligar quando o teto já está cheio derruba o MAIS ANTIGO em vez de recusar em silêncio: o
 * jogador acabou de clicar e precisa ver algo acontecer, e o que ele quer é sempre o clique
 * novo — recusar deixaria um botão que não faz nada e nenhuma pista do porquê.
 */
function alternarCriterioMercado(id) {
  const atuais = criteriosDoMercado();
  if (atuais.includes(id)) {
    estado.cmFiltro.criterios = atuais.filter((x) => x !== id);
    return;
  }
  const novos = [...atuais, id];
  estado.cmFiltro.criterios = novos.slice(-MAX_CRITERIOS_MERCADO);
}

/**
 * O rótulo do botão de "Filtrar por": nenhum, um pelo nome, ou "N critérios".
 *
 * Escrever os três nomes por extenso ("Maior nota, Maior IV, Maior qualidade") estoura a
 * largura do botão no celular e, no desktop, empurra o "Ordenar por" para a linha de baixo. Com
 * dois ou mais o botão vira contador — os nomes continuam à vista, marcados, no menu que ele
 * abre, e a ORDEM deles aparece lá como número.
 */
function rotuloCriteriosMercado() {
  const ligados = criteriosDoMercado();
  if (!ligados.length) return t('cm.filtrarNenhum');
  if (ligados.length === 1) return t(criterioMercado(ligados[0]).nome);
  return t('cm.filtrarN', { n: ligados.length });
}

/**
 * O menu de critérios: um `<details>`, e não um `<select multiple>`.
 *
 * `<select multiple>` é a peça errada por três motivos que aparecem todos aqui: no celular ele
 * vira uma lista de rolagem sem marca de seleção óbvia, exige Ctrl/Cmd+clique no desktop (que
 * ninguém descobre), e não tem onde mostrar a ORDEM de prioridade — que é justamente o que
 * este filtro tem de comunicar.
 *
 * `<details>` fecha sozinho no clique fora, abre no teclado e é uma tag nativa: o mesmo
 * comportamento de um dropdown sem uma linha de JS de posicionamento.
 */
function htmlFiltrarPorMiolo() {
  const ligados = criteriosDoMercado();
  const opcoes = CRITERIOS_MERCADO.map((c) => {
    const i = ligados.indexOf(c.id);
    return `<button type="button" class="cm-crit ${i >= 0 ? 'on' : ''}" data-crit="${c.id}">
              <span class="cm-crit-ordem">${i >= 0 ? i + 1 : ''}</span>${t(c.nome)}
            </button>`;
  }).join('');

  return `
      <summary>
        <span class="cm-drop-rot">${t('cm.filtrarPor')}</span>
        <b class="cm-drop-val">${escapar(rotuloCriteriosMercado())}</b>
        ${ligados.length ? `<span class="cm-drop-conta">${ligados.length}</span>` : ''}
      </summary>
      <div class="cm-drop-corpo">
        <!-- A dica da prioridade fica DENTRO do menu, e não como title do botão: no celular
             não há hover, e sem ela o número ao lado do critério não se explica. -->
        <p class="cm-drop-dica">${t('cm.filtrarDica')}</p>
        <div class="cm-crits">${opcoes}</div>
        ${ligados.length
          ? `<button type="button" class="cm-crit-limpar" id="cm-crit-limpar">${t('cm.filtrarLimpar')}</button>`
          : ''}
      </div>`;
}

/** O dropdown inteiro, para o primeiro desenho. Depois disso só o miolo é trocado. */
const htmlFiltrarPorMercado = () =>
  `<details class="cm-drop cm-drop-crit" id="cm-filtrar">${htmlFiltrarPorMiolo()}</details>`;

/**
 * Redesenha SÓ o dropdown de "Filtrar por", mantendo-o aberto.
 *
 * O redesenho normal da vitrine passa por `abrirModal('community')`, que troca o HTML do modal
 * inteiro — e um `<details open>` trocado por outro nasce fechado. Como este é o único filtro
 * em que o jogador clica várias vezes seguidas (é para isso que ele é composto), aqui a
 * substituição é cirúrgica: o `<details>` novo entra no lugar do velho já com o `open` que o
 * velho tinha, e o menu não pisca entre um critério e o outro.
 */
function repintarFiltrarPor() {
  const drop = document.querySelector('#cm-filtrar');
  if (!drop) return;
  // `innerHTML`, e NÃO `outerHTML`: o `<details>` em si tem de sobreviver. É nele que o
  // `addEventListener` do clique está pendurado, e trocar o elemento levaria o ouvinte junto —
  // o primeiro critério funcionaria e o segundo clique não faria nada. Manter o elemento
  // preserva de quebra o `open`, sem ter de salvar e restaurar.
  drop.innerHTML = htmlFiltrarPorMiolo();
  // O contador do funil (celular) conta os critérios: mudou um, mudou ele.
  const n = contarFiltrosDoMercado(estado.cmFiltro);
  const conta = document.querySelector('.filtros-conta');
  if (conta) conta.textContent = n || '';
}

/**
 * O filtro de TIPO como dropdown, e não mais como fileira de 19 chips.
 *
 * Os chips coloridos eram bonitos e custavam caro: quatro fileiras no desktop e três no
 * celular, ~120 px antes do primeiro anúncio, numa tela cujo produto é a vitrine. O dropdown
 * ocupa uma linha e mantém a COR — o `data-elem` no `<summary>` pinta a plaquinha do tipo
 * escolhido, que é o que fazia os chips serem lidos de relance.
 */
function htmlTipoMercado(elemento) {
  const opcoes = [
    `<button type="button" class="cm-elem ${elemento ? '' : 'on'}" data-elem="">${t('cm.todosTipos')}</button>`,
    ...TIPOS_FILTRO.map(
      (x) => `<button type="button" class="cm-elem tipo ${x} ${elemento === x ? 'on' : ''}" data-elem="${x}">${x}</button>`,
    ),
  ].join('');

  return `
    <details class="cm-drop cm-drop-elem" id="cm-tipos">
      <summary data-elem="${escapar(elemento)}">
        <span class="cm-drop-rot">${t('cm.tipoElemental')}</span>
        <b class="cm-drop-val ${elemento ? `tipo ${elemento}` : ''}">${elemento || t('cm.todosTipos')}</b>
      </summary>
      <div class="cm-drop-corpo"><div class="cm-elems">${opcoes}</div></div>
    </details>`;
}

/**
 * As abas de item da vitrine.
 *
 * `loot`, `clan` e `card` saíram junto com a curadoria do servidor: drop de pokémon não se
 * anuncia mais (ver `ITENS_MERCADO` em `content.mjs`), e sem eles as três abas ficariam
 * sempre vazias. Sobra o que dá para negociar — e cada uma casa com uma família de
 * `categoriaMercado`.
 */
const CATEGORIAS_ITEM = [
  { id: '', nome: 'cm.catTodas' },
  // Boxes — as Caixas de Fundador. Aba própria porque é a única em que cada anúncio é uma
  // PEÇA numerada: dois anúncios de "Founder Box" são caixas diferentes, e o número na frente
  // é o que os distingue. Ver `shared/caixas-beta.mjs`.
  { id: 'box', nome: 'cm.catBox' },
  { id: 'casa', nome: 'cm.catCasa' },
  { id: 'bicicleta', nome: 'cm.catBicicleta' },
  // As SKINS de pokémon: nascem numa venda limitada da Loja, e depois dela é aqui que existem.
  // (A aba `beast` saiu em 30/09/2026: das coisas de diamante, só as skins e as Caixas de Fundador
  // ficam na vitrine — ver `ITENS_MERCADO` em `content.mjs`.)
  { id: 'skin', nome: 'cm.catSkin' },
  { id: 'fragment', nome: 'cm.catFragment' },
  // As Mega Stones têm aba própria em vez de dividir a de Pedras: são 63, contra as 21 pedras
  // de evolução de sempre, e juntas enterravam a Water Stone de todo dia numa lista de 84
  // linhas. Ver `categoriaMercado` em `content.mjs`.
  { id: 'mega', nome: 'cm.catMega' },
  // A aba `held` saiu com a Exp. Share: ela era a única moradora, e o item deixou de ser
  // negociável para a auditoria dele caber numa conta por jogador. Ver `shared/xp-share-held.mjs`.
  { id: 'stone', nome: 'cm.catStone' },
  { id: 'tm', nome: 'cm.catTm' },
  { id: 'boss', nome: 'cm.catBoss' },
];

// ------------------------------------------- vitrine de itens (lista + painel)
//
// A aba de ITENS não é mais uma grade de anúncios. Ela desenha o CATÁLOGO — toda pedra,
// todo TM, toda ficha de boss —, inclusive o que ninguém está vendendo, e só ao clicar
// abre os anúncios daquele item, como a Comunidade da Steam.
//
// A razão é de leitura: a grade antiga mostrava "Water Stone" cinco vezes seguidas, uma por
// vendedor, e escondia as outras dezoito pedras atrás da paginação. Quem entra no mercado de
// item está procurando UMA pedra e quer saber por quanto sai — não folhear anúncios.
//
// `estado.cmItens` é o resumo (nº de anúncios e menor preço por moeda, vindo do servidor) e
// `estado.cmItemSel` é a linha aberta. O catálogo em si vem do welcome e nunca muda.

const catalogoMercado = () => estado.mercado?.catalogo ?? [];

/** O item do catálogo, pelo id. */
const itemDoMercado = (id) => catalogoMercado().find((i) => i.id === Number(id)) ?? null;

/** Ícone na vitrine de itens — a Beast Ball mora em `catalogoBolas`, não em `iconesItem`. */
const icoVitrineItem = (item) =>
  item.id === BEAST_BALL_ID
    ? 'img:/img/ball-beast.png'
    : `img:${estado.iconesItem[item.id] ?? ICONE_ITEM_GENERICO}`;

/** "A partir de" — o menor preço unitário numa moeda, ou null se ninguém vende. */
function apartirDe(resumo, moedaId) {
  const v = moedaId === 'orb' ? resumo?.minOrb : resumo?.minGold;
  return v == null ? null : v;
}

/** Pelo menos um anúncio ativo deste item no resumo do servidor. */
const itemTemEstoque = (item) => {
  const r = estado.cmItens?.[item.id];
  return !!(r && r.anuncios);
};

/** Catálogo filtrado da vitrine de itens (categoria, tipo, busca, estoque). */
function itensDaVitrineItens() {
  const cat = estado.cmFiltro.categoria;
  const elem = estado.cmFiltro.elemento;
  const busca = estado.cmFiltro.busca.trim().toLowerCase();
  return catalogoMercado().filter((i) =>
    (!cat || i.categoria === cat) &&
    (!elem || i.tipo === elem) &&
    (!busca || nomeItem(i, i.nome).toLowerCase().includes(busca) || i.nome.toLowerCase().includes(busca)) &&
    (!estado.cmFiltro.soComEstoque || itemTemEstoque(i)));
}

function scrollCatalogoItens(host) {
  return host?.querySelector('.cmi-tabela')?.scrollTop ?? 0;
}

function restaurarScrollCatalogoItens(host, top) {
  const tabela = host?.querySelector('.cmi-tabela');
  if (tabela && top > 0) tabela.scrollTop = top;
}

function linhaVitrineItem(item) {
  const r = estado.cmItens?.[item.id] ?? null;
  const gold = apartirDe(r, 'gold');
  const orb = apartirDe(r, 'orb');
  const vazio = !r || !r.anuncios;
  const sel = estado.cmItemSel === item.id;

  // Os dois "a partir de" ficam SEMPRE na linha, mesmo sem anúncio: a ausência de preço é
  // informação (ninguém vende), e some-la faria a linha mudar de altura ao vender o primeiro.
  const preco = (moedaId, v) => `
    <span class="cmi-de ${v == null ? 'nada' : ''}">
      <i>${t('cm.apartirDe')}</i>
      ${v == null ? `<b>—</b>` : precoComMoeda(v, moedaId)}
    </span>`;

  return `
    <button class="cmi-linha ${sel ? 'on' : ''} ${vazio ? 'sem' : ''}" data-item="${item.id}">
      <span class="cmi-ico" data-ico="${icoVitrineItem(item)}" data-ico-px="32"></span>
      <span class="cmi-nome">
        <b>${escapar(nomeItem(item, item.nome))}</b>
        <i>${vazio ? t('cm.semVendedores') : t('cm.nVendendo', { n: r.anuncios, u: num(r.unidades) })}</i>
      </span>
      <span class="cmi-precos">${preco('gold', gold)}${preco('orb', orb)}</span>
    </button>`;
}

/** O painel do item aberto: switch de moeda + a lista de vendedores. */
function painelItemMercado() {
  const item = itemDoMercado(estado.cmItemSel);
  if (!item) return '';
  const moedaId = estado.cmItemMoeda === 'orb' ? 'orb' : 'gold';
  const linhas = estado.cmItemLinhas?.[`${item.id}:${moedaId}`] ?? null;

  const vendedores = linhas == null
    ? `<div class="cm-vazio">${t('cm.carregando')}</div>`
    : !linhas.length
      ? `<div class="cm-vazio">${t(moedaId === 'orb' ? 'cm.semVendedoresGema' : 'cm.semVendedoresCoin')}</div>`
      : linhas.map((a) => `
          <div class="cmv-linha ${ehMeuAnuncio(a) ? 'meu' : ''} ${numeroDoAnuncio(a) ? 'cmv-cx' : ''}">
            <span class="cmv-quem">${escapar(a.vendedor)}${
              diasRestantes(a) == null ? '' : `<i class="cmv-dias">${t('cm.duracao', { d: diasRestantes(a) })}</i>`
            }</span>
            <!-- Numa caixa ou casa o NÚMERO ocupa o lugar da quantidade: "1× unidade" não diz nada,
                 e a posição é o que separa este anúncio do de baixo. -->
            <span class="cmv-qtd">${numeroDoAnuncio(a)
              ? plaquinhaDoAnuncio(a)
              : `${num(a.qtd)}× ${t('cm.unidades')}`}</span>
            <span class="cmv-preco">${precoComMoeda(a.preco, a.moeda)} <i>${t('cm.porUnidade')}</i></span>
            <!-- O "Enviar DM" do Comércio mora do lado do Comprar, e os dois vão numa caixa só: a
                 grade da linha continua com quatro colunas, e no celular os dois caem juntos na
                 área do botão. Na linha do próprio anúncio não há com quem conversar. -->
            <span class="cmv-bts">${ehMeuAnuncio(a) ? '' : htmlBotaoDm(a)}<button class="cm-acao destaque cmv-comprar${anuncioEmRetencao(a) ? ' cm-retido' : ''}" data-anuncio="${a.id}"${attrRetencao(a)}${anuncioEmRetencao(a) ? ' disabled title="' + escapar(t('cm.retencaoComprar')) + '"' : ''}>${anuncioEmRetencao(a) ? rotuloRetencao(a) : t('cm.comprar')}</button></span>
          </div>`).join('');

  const evolui = item.categoria === 'stone' ? especiesQueUsamPedra(item.id) : [];
  const blocoPedra = evolui.length
    ? `<p class="cmp-pedra-info">${t('cm.pedraUsadaPor', {
        lista: evolui.map((e) => escapar(e.name)).join(', '),
      })}</p>`
    : '';

  // O trilho anda com `transform`, e não trocando o conteúdo: é o deslize que diz que a
  // lista mudou de moeda. Os dois painéis existem ao mesmo tempo, um fora do quadro.
  return `
    <div class="cmp-cabeca">
      <span class="cmp-ico" data-ico="${icoVitrineItem(item)}" data-ico-px="40"></span>
      <div class="cmp-tit">
        <b>${escapar(nomeItem(item, item.nome))}</b>
        <i>${(() => { const k = `cm.cat.${item.categoria}`; const tr = t(k); return tr !== k ? tr : item.categoria; })()}</i>
      </div>
      <!-- A estrela do ITEM (não de um anúncio): guarda o atalho para estas ofertas na aba Favoritos. -->
      <span class="cmp-fav-slot" data-fav-slot="${item.id}"></span>
      <button class="cmp-fechar" id="cmp-fechar" aria-label="${t('cm.voltar')}"><span class="cmp-fx">×</span><span class="cmp-fv">‹ ${escapar(t('cm.voltar'))}</span></button>
    </div>
    ${blocoPedra}
    <div class="cmp-switch" data-moeda="${moedaId}">
      <button class="cmp-op ${moedaId === 'gold' ? 'on' : ''}" data-swmoeda="gold">
        <img src="${srcIcone(ICONE_OURO)}" alt="">${t('cm.emCoins')}
      </button>
      <button class="cmp-op ${moedaId === 'orb' ? 'on' : ''}" data-swmoeda="orb">
        <img src="${ICONE_GEMA}" alt="">${t('cm.emGemas')}
      </button>
      <span class="cmp-manopla"></span>
    </div>
    <p class="cmp-media">${htmlMediaDeVenda(mediaDoItem(item.id), moedaId)}</p>
    <div class="cmp-trilho ${moedaId === 'orb' ? 'dir' : ''}">
      <div class="cmp-vagao">${vendedores}</div>
    </div>`;
}

function ligarEventosVitrineItens(host) {
  for (const b of host.querySelectorAll('.cmi-linha')) {
    b.onclick = () => abrirItemMercado(Number(b.dataset.item));
  }
  $('#cmp-fechar') && ($('#cmp-fechar').onclick = () => fecharItemMercado({ animar: movelAtivo() }));
  for (const slot of host.querySelectorAll('[data-fav-slot]')) {
    slot.replaceWith(botaoFavoritoItemMercado(Number(slot.dataset.favSlot)));
  }
  for (const b of host.querySelectorAll('[data-swmoeda]')) {
    b.onclick = () => trocarMoedaItem(b.dataset.swmoeda);
  }
  for (const b of host.querySelectorAll('.cmv-comprar')) {
    b.onclick = () => {
      const a = (estado.cmItemLinhas?.[`${estado.cmItemSel}:${estado.cmItemMoeda}`] ?? [])
        .find((x) => x.id === Number(b.dataset.anuncio));
      if (!a || anuncioEmRetencao(a)) return;
      abrirCompra(a);
    };
  }
  for (const b of host.querySelectorAll('.cmv-dm')) {
    b.onclick = () => {
      const a = (estado.cmItemLinhas?.[`${estado.cmItemSel}:${estado.cmItemMoeda}`] ?? [])
        .find((x) => x.id === Number(b.dataset.dm));
      if (a) abrirDmDoAnuncio(a);
    };
  }
  for (const el of host.querySelectorAll('[data-ico]')) pintarIcone(el);
}

function repintarPainelItem(host) {
  const painel = host?.querySelector('.cmi-painel');
  if (!painel) return;
  const sel = estado.cmItemSel;
  painel.classList.toggle('aberto', !!sel);
  painel.innerHTML = sel ? painelItemMercado() : `<div class="cm-vazio">${t('cm.escolhaItem')}</div>`;
}

/** Atualiza catálogo + painel sem remontar o trilho — preserva o scroll da lista. */
function atualizarVitrineItens({ scrollTop = null } = {}) {
  const host = $('#cm-lista');
  const slider = host?.querySelector('.cmi-slider');
  if (!host || !slider) return false;

  const scroll = scrollTop ?? scrollCatalogoItens(host);
  const itens = itensDaVitrineItens();
  if (estado.cmItemSel && !itens.some((i) => i.id === estado.cmItemSel)) estado.cmItemSel = null;

  const tabela = host.querySelector('.cmi-tabela');
  if (tabela) {
    tabela.innerHTML = itens.length
      ? itens.map(linhaVitrineItem).join('')
      : `<div class="cm-vazio">${t('cm.semAnuncios')}</div>`;
    restaurarScrollCatalogoItens(host, scroll);
  }

  repintarPainelItem(host);
  slider.classList.toggle('mostra-painel', !!estado.cmItemSel);
  ligarEventosVitrineItens(host);
  return true;
}

function pintarVitrineItens(opts = {}) {
  const host = $('#cm-lista');
  if (!host) return;
  const scrollTop = scrollCatalogoItens(host);
  const itens = itensDaVitrineItens();

  if (estado.cmItemSel && !itens.some((i) => i.id === estado.cmItemSel)) estado.cmItemSel = null;

  const sel = estado.cmItemSel;
  host.classList.add('cm-lista-itens');
  // O trilho de dois painéis. No desktop ele é `display:contents` e `.cmi-tabela` +
  // `.cmi-painel` continuam sendo as duas colunas da grade. No celular ele vira um carrossel:
  // o catálogo ocupa a tela toda, tocar numa pedra desliza para o painel de anúncios e
  // arrastar da borda esquerda para a direita volta (ver `ligarGestoVoltarItem`).
  host.innerHTML = itens.length
    ? `<div class="cmi-slider ${sel ? 'mostra-painel' : ''}">
         <div class="cmi-tabela">${itens.map(linhaVitrineItem).join('')}</div>
         <aside class="cmi-painel ${sel ? 'aberto' : ''}">
           ${sel ? painelItemMercado() : `<div class="cm-vazio">${t('cm.escolhaItem')}</div>`}
         </aside>
       </div>`
    : `<div class="cm-vazio">${t('cm.semAnuncios')}</div>`;

  restaurarScrollCatalogoItens(host, scrollTop);

  const slider = host.querySelector('.cmi-slider');
  // Entrada pelo toque num item: tira a classe, força um reflow e recoloca — assim a
  // transição do CSS corre a partir do estado "catálogo à vista" em vez de já nascer no lugar.
  if (slider && sel && opts.animarEntrada) {
    slider.classList.remove('mostra-painel');
    void slider.offsetWidth;
    slider.classList.add('mostra-painel');
  }
  if (slider && movelAtivo()) ligarGestoVoltarItem(slider);

  ligarEventosVitrineItens(host);
}

function abrirItemMercado(itemId) {
  const host = $('#cm-lista');
  const jaEstavaAberto = estado.cmItemSel === itemId;
  const antigo = estado.cmItemSel;
  estado.cmItemSel = itemId;
  estado.cmItemMoeda = estado.cmItemMoeda ?? 'gold';

  const slider = host?.querySelector('.cmi-slider');
  const tabela = host?.querySelector('.cmi-tabela');
  if (slider && tabela) {
    if (antigo != null) {
      tabela.querySelector(`.cmi-linha[data-item="${antigo}"]`)?.classList.remove('on');
    }
    tabela.querySelector(`.cmi-linha[data-item="${itemId}"]`)?.classList.add('on');
    repintarPainelItem(host);
    slider.classList.add('mostra-painel');
    ligarEventosVitrineItens(host);
    if (movelAtivo() && !jaEstavaAberto) {
      slider.classList.remove('mostra-painel');
      void slider.offsetWidth;
      slider.classList.add('mostra-painel');
    }
  } else {
    pintarVitrineItens({ animarEntrada: movelAtivo() && !jaEstavaAberto });
  }
  pedirAnunciosItem();
}

/**
 * Volta do painel de anúncios para o catálogo.
 *
 * No celular o painel toma a tela inteira, então a volta desliza de volta antes de repintar
 * — repintar direto faz o catálogo "piscar" no lugar. `animar` tira a classe que segura o
 * trilho à direita, deixa a transição do CSS terminar e só então zera o item selecionado.
 */
function fecharItemMercado({ animar = false } = {}) {
  const slider = $('#cm-lista .cmi-slider');
  if (animar && slider && slider.classList.contains('mostra-painel')) {
    slider.style.transition = '';
    slider.style.transform = '';
    slider.classList.remove('mostra-painel');
    let feito = false;
    const encerrar = (ev) => {
      if (feito || (ev && ev.target !== slider)) return;
      feito = true;
      slider.removeEventListener('transitionend', encerrar);
      estado.cmItemSel = null;
      if (!atualizarVitrineItens()) pintarVitrineItens();
    };
    slider.addEventListener('transitionend', encerrar);
    setTimeout(encerrar, 340);
    return;
  }
  estado.cmItemSel = null;
  if (!atualizarVitrineItens()) pintarVitrineItens();
}

/**
 * Gesto de "voltar" do celular: arrastar da borda esquerda para a direita traz o catálogo de
 * volta. Só arma perto da borda (é o mesmo gesto do sistema) e só com um item aberto; um
 * movimento mais vertical do que horizontal é rolagem da lista e desarma na hora.
 */
function ligarGestoVoltarItem(slider) {
  if (!slider || slider.dataset.gesto === '1') return;
  slider.dataset.gesto = '1';
  const quadro = () => slider.parentElement; // #cm-lista — a janela visível de um painel
  let x0 = 0, y0 = 0, armado = false, arrastando = false, dx = 0;

  slider.addEventListener('touchstart', (ev) => {
    arrastando = false; armado = false; dx = 0;
    if (!estado.cmItemSel || ev.touches.length !== 1) return;
    const p = ev.touches[0];
    const esq = quadro().getBoundingClientRect().left;
    armado = p.clientX - esq <= 36;
    x0 = p.clientX; y0 = p.clientY;
  }, { passive: true });

  slider.addEventListener('touchmove', (ev) => {
    if (!armado || ev.touches.length !== 1) return;
    const p = ev.touches[0];
    const mx = p.clientX - x0;
    const my = p.clientY - y0;
    if (!arrastando) {
      if (Math.abs(mx) < 8 && Math.abs(my) < 8) return;
      if (Math.abs(my) >= Math.abs(mx)) { armado = false; return; }
      arrastando = true;
      slider.style.transition = 'none';
    }
    ev.preventDefault();
    dx = Math.max(0, mx);
    const w = quadro().clientWidth || 1;
    const pct = Math.min(50, (dx / w) * 50);
    slider.style.transform = `translateX(calc(-50% + ${pct}%))`;
  }, { passive: false });

  const soltar = () => {
    if (!arrastando) { armado = false; return; }
    arrastando = false; armado = false;
    const w = quadro().clientWidth || 1;
    slider.style.transition = '';
    if (dx > w * 0.33) {
      fecharItemMercado({ animar: true });
    } else {
      slider.style.transform = ''; // volta sozinho para -50% (a classe continua)
    }
  };
  slider.addEventListener('touchend', soltar, { passive: true });
  slider.addEventListener('touchcancel', soltar, { passive: true });
}

function trocarMoedaItem(moedaId) {
  estado.cmItemMoeda = moedaId === 'orb' ? 'orb' : 'gold';
  if (!atualizarVitrineItens()) pintarVitrineItens();
  pedirAnunciosItem();
}

function pedirAnunciosItem() {
  if (!estado.cmItemSel) return;
  enviar({ t: 'market.item', itemId: estado.cmItemSel, moeda: estado.cmItemMoeda });
}

/** A comissão que o servidor cobra em Coins. Só para MOSTRAR — quem desconta é `market-db.mjs`. */
const TAXA_GOLD_PADRAO = TAXA_GOLD;

/**
 * Comissão em Coins.
 *
 * Prefere o número que o servidor mandou no welcome (`economia.taxaMercadoGoldPct`), porque a
 * constante já ficou defasada uma vez: o servidor mudou de 30% para 15% na gema e a tela
 * continuaria prometendo um líquido menor do que o jogador de fato receberia. O valor fixo
 * acima é só a rede de baixo, para antes de o welcome chegar.
 *
 * A GEMA não passa por aqui: a taxa dela é por faixa e a conta vem de
 * `shared/taxa-mercado.mjs`, o mesmo arquivo que o servidor usa para cobrar — ali a defasagem
 * não tem como acontecer.
 */
const taxaGoldCliente = () => {
  const pct = estado.economia?.taxaMercadoGoldPct ?? estado.mercado?.taxaGoldPct;
  return Number.isFinite(pct) ? pct / 100 : TAXA_GOLD_PADRAO;
};

const precoMinOrb = () => estado.mercado?.precoMinOrb ?? PRECO_MIN_ORB;
const precoMinGold = () => estado.mercado?.precoMinGold ?? PRECO_MIN_GOLD;

const precoMinMercado = (moeda) => (moeda === 'orb' ? precoMinOrb() : precoMinGold());
const totalLiquidoMercado = (preco, qtd, moeda, tipo) =>
  moeda === 'orb'
    ? liquidoOrbDaVenda(qtd * preco, tipo)
    : Math.floor(qtd * preco * (1 - taxaGoldCliente()));

/** "13", "7,5", "11,5" — inteiro sem `.0`, fração com vírgula. */
const pctTaxa = (n) => Number(n).toLocaleString('pt-BR', { maximumFractionDigits: 2 });

/**
 * "7,5–13" — o intervalo da comissão da gema, do topo à entrada. O painel do caixa mostra um
 * número só, e com faixa marginal o número único honesto é o intervalo.
 */
const intervaloFaixasOrb = (faixas) => {
  const pcts = (faixas?.length ? faixas : faixasOrbParaTela()).map((f) => f.pct);
  const min = Math.min(...pcts);
  const max = Math.max(...pcts);
  return min === max ? pctTaxa(max) : `${pctTaxa(min)}–${pctTaxa(max)}`;
};

/** A tabela da gema em uma linha: "13% até 500 · 10% até 5.000 · 7,5% acima". */
const faixasOrbEmTexto = () =>
  faixasOrbParaTela()
    .map((f) => (f.ate
      ? t('cm.faixaAte', { pct: pctTaxa(f.pct), ate: num(f.ate) })
      : t('cm.faixaAcima', { pct: pctTaxa(f.pct) })))
    .join(' · ');

const ajudaPrecoMercado = (moeda, npc, tipo) => {
  if (moeda === 'orb') {
    // Só o pokémon vê a tabela de faixas; item e diamante veem a alíquota única que pagam.
    return temFaixaOrb(tipo)
      ? t('cm.precoMinOrbAjuda', { min: num(precoMinOrb()), faixas: faixasOrbEmTexto() })
      : t('cm.precoMinOrbAjudaPlana', { min: num(precoMinOrb()), taxa: pctTaxa(TAXA_ORB_PLANA * 100) });
  }
  if (moeda === 'gold') {
    return t('cm.precoMinGoldAjuda', { min: num(precoMinGold()), taxa: Math.round(taxaGoldCliente() * 100) });
  }
  return npc ? t('cm.npcPaga', { v: num(npc) }) : t('cm.precoUnitAjuda');
};

/**
 * O PREÇO MÉDIO DE VENDA dos últimos 7 dias numa moeda — a linha que fica embaixo do "menor preço
 * anunciado" na folha de anunciar, e no alto da lista de vendedores do item e do diamante.
 *
 * O menor anúncio diz quanto alguém PEDE; esta linha diz quanto se PAGOU. É a régua de quem chega
 * sem conhecer o mercado: não trava preço nenhum, só dá contra o que comparar. A conta (média
 * ponderada por unidade) é do servidor — ver `mediasDeVenda` em `market-db.mjs`.
 *
 * `media` é o `{ gold?, orb? }` do item ou do diamante; `undefined` enquanto a resposta não chegou,
 * e aí a linha fica vazia em vez de afirmar "nenhuma venda" sem saber.
 */
function htmlMediaDeVenda(media, moeda, { diamante = false } = {}) {
  if (media === undefined) return '';
  const m = moeda === 'orb' ? media?.orb : media?.gold;
  if (!m) return t(moeda === 'orb' ? 'cm.semVendas7dOrb' : 'cm.semVendas7dGold');
  return t(diamante ? 'cm.mediaVendidaDiamante' : 'cm.mediaVendida', {
    preco: precoComMoeda(m.media, moeda),
    u: num(m.unidades),
  });
}

/** A média de um item — `undefined` enquanto o resumo da vitrine não chegou. */
const mediaDoItem = (itemId) => (estado.cmMedias === undefined ? undefined : estado.cmMedias?.[itemId] ?? null);

let cmPassoPrecoAtualizar = null;

/**
 * O número CURTO dos cards: "220M", "1,5B", "12,5K" — o K/M/B/T dos jogos grandes.
 *
 * O card do Mercado tem a largura de um sprite, e "1.500.000.000" ao lado do "A partir de:"
 * estoura a coluna. Abaixo de 10.000 o número sai inteiro (cabe, e é exato); dali para cima,
 * três dígitos significativos e a letra. O arredondamento vem ANTES de escolher a letra, senão
 * 999.999 viraria "1.000K" em vez de "1M". O valor exato não some: fica no balão do preço, e a
 * folha de compra — que é onde o jogador decide — mostra o número inteiro.
 */
const UNIDADES_CURTAS = [[1e12, 'T'], [1e9, 'B'], [1e6, 'M'], [1e3, 'K']];
let fmtNumAbrev = null;
function numAbrev(n) {
  const v = Number(n) || 0;
  if (Math.abs(v) < 10_000) return num(v);
  const r = Number(v.toPrecision(3));
  const [base, letra] = UNIDADES_CURTAS.find(([b]) => Math.abs(r) >= b);
  const loc = localeData();
  if (fmtNumAbrev?.loc !== loc) fmtNumAbrev = { loc, f: new Intl.NumberFormat(loc, { maximumFractionDigits: 2 }) };
  return `${fmtNumAbrev.f.format(r / base)}${letra}`;
}

/**
 * O preço com a moeda. `curto` é o dos CARDS (ver `numAbrev`): o número abreviado, com o valor
 * inteiro no balão — que só aparece quando a abreviação escondeu alguma coisa.
 */
const precoComMoeda = (v, moedaId, { curto = false } = {}) => {
  const exato = num(v);
  const txt = curto ? numAbrev(v) : exato;
  const dica = txt !== exato ? ` title="${exato}"` : '';
  if (moedaId === 'orb') return `<span class="cm-preco orb"${dica}><img src="${ICONE_GEMA}" alt="${t('moeda.gemas')}">${txt}</span>`;
  return `<span class="cm-preco"${dica}>${curto
    ? `<span class="mk-moeda"><img src="${srcIcone(ICONE_OURO)}" alt="ouro">${txt}</span>`
    : moeda(v)}</span>`;
};

/** O bônus de uma potência, para o rótulo do selo ("+25%"). A tabela vem do servidor. */
const bonusDaPotencia = (n) =>
  Math.round(((estado.potencias.find((p) => p.n === n)?.bonus ?? 0) * 100));

/**
 * Selo de POTÊNCIA (P1–P5). P1 é cinza — é o padrão comum, mas ainda vale mostrar
 * para comparar com os outros sem esconder quem não tem sorte nenhuma.
 */
const seloPotencia = (n) => {
  const p = Math.max(1, Math.min(5, Number(n) || 1));
  const titulo =
    p === 1 ? t('cm.potenciaP1') : t('cm.potenciaAjuda', { n: p, b: bonusDaPotencia(p) });
  return `<span class="cm-pot p${p}" title="${titulo}">P${p}</span>`;
};

const seloShiny = () => `<span class="cm-selo-shiny" title="${t('cm.shinyAjuda')}">✨ SHINY</span>`;

// ------------------------------------------------- os selos de atributo (P · IV · Q · Nota)
//
// ### O problema que isto resolve
//
// O jogo tinha TRÊS cards de pokémon desenhados de forma diferente e mostrando conjuntos
// diferentes de números: o do Market ("Venda Pokémon") trazia nível, qualidade e nota; o "Em
// Campo" trazia poder e qualidade; o do Mercado da Comunidade trazia nível, IV e nota. Nenhum
// mostrava os quatro, e nenhum mostrava os mesmos que o vizinho. Quem quisesse comparar dois
// bichos tinha de abrir a ficha de cada um e decorar os números no caminho.
//
// A saída é UM componente: a fileira P · IV · Q · Nota, sempre nesta ordem, sempre com a mesma
// cara, em todo lugar que desenha um pokémon. Aprender a ler uma vez passa a valer em todos.
//
// ### Por que a cor é a MESMA escada nos quatro
//
// A potência já tinha cor por nível (cinza → azul → verde → roxo → laranja) e os jogadores já
// leem essa escada. Reusá-la nos outros três transforma quatro escalas independentes numa só:
// laranja é topo em qualquer um dos selos, cinza é fundo em qualquer um deles. Um card com
// quatro selos laranja é um bicho excepcional sem que ninguém precise saber que 182 de IV é
// muito e 1,52 de qualidade também.
//
// ### Onde cada corte foi posto
//
// Nenhum dos três é linear, porque a distribuição de nenhum deles é:
//
// - **IV** é % do teto (192). Linear serve aqui — o sorteio é uniforme por stat.
// - **Qualidade** sai de `percentilQualidade`, a raridade real do sorteio. Os cortes
//   (44/74/94/99) caem exatamente nas bordas de banda: 1,1 · 1,3 · 1,5 · 1,6 — e t5 fica
//   valendo 1% dos nascimentos, que é a mesma ordem de raridade de um P5.
// - **Nota** ancora o primeiro degrau em `MERCADO_POKEMON_MIN.nota` (3,0), que é o piso do
//   Mercado e o do auto-lock. Cinza passa a significar "isto é pra vender pro NPC" — que é
//   a pergunta que o jogador estava tentando responder quando pediu estes selos.

/** Onde cada atributo troca de degrau. Sempre 4 cortes = 5 degraus, como P1–P5. */
const CORTES_IV_PCT = [0.5, 0.7, 0.85, 0.95];
const CORTES_QUALIDADE_PCT = [0.44, 0.74, 0.94, 0.99];
const CORTES_NOTA = [MERCADO_POKEMON_MIN.nota, 5.5, 7, 8.5];

/** Em que degrau (1–5) um valor cai, dados os quatro cortes. */
const degrauPorCortes = (v, cortes) => cortes.reduce((n, corte) => (v >= corte ? n + 1 : n), 1);

/** A soma de IV de um pokémon, venha ele do snapshot (`ivs`) ou de uma ficha (`ivTotal`). */
function ivTotalDoPokemon(pk) {
  if (!pk) return null;
  const direto = pk.iv ?? pk.ivTotal;
  if (direto != null && Number.isFinite(Number(direto))) return Math.round(Number(direto));
  if (!pk.ivs) return null;
  return Object.values(pk.ivs).reduce((soma, v) => soma + (Number(v) || 0), 0);
}

/** Um selo da fileira. `pot` reaproveita as classes que a potência já tinha. */
const seloAtributo = (chave, degrau, texto, titulo) =>
  `<span class="pk-selo pk-selo-${chave} t${degrau}" title="${escapar(titulo)}">${texto}</span>`;

const seloIv = (ivTotal) => {
  const iv = Math.round(Number(ivTotal) || 0);
  const pct = (iv - IV_MIN) / (IV_MAX - IV_MIN);
  return seloAtributo(
    'iv',
    degrauPorCortes(pct, CORTES_IV_PCT),
    `IV ${num(iv)}`,
    t('selo.ivAjuda', { v: num(iv), max: num(IV_MAX), pct: Math.round(pct * 100) }),
  );
};

const seloQualidade = (q) => {
  const v = Number(q) || QUALIDADE_MIN;
  const pct = percentilQualidade(v);
  return seloAtributo(
    'q',
    degrauPorCortes(pct, CORTES_QUALIDADE_PCT),
    `Q ${virgula(v.toFixed(3))}`,
    t('selo.qualidadeAjuda', { v: virgula(v.toFixed(3)), pct: Math.max(1, Math.round((1 - pct) * 100)) }),
  );
};

const seloNota = (nota) => {
  const n = Number(nota) || 0;
  return seloAtributo(
    'n',
    degrauPorCortes(n, CORTES_NOTA),
    `N ${notaEmTexto(n)}`,
    t('selo.notaAjuda', { v: notaEmTexto(n), min: MERCADO_POKEMON_MIN.nota }),
  );
};

/**
 * A FILEIRA. É o que os três cards (e a linha do Depot) desenham — sempre a mesma, sempre nesta
 * ordem: potência, IV, qualidade, nota.
 *
 * Cada selo cai fora sozinho quando o dado não existe, em vez de virar um "—". Uma ficha de
 * anúncio antigo sem `ivTotal` mostra três selos e ninguém sente falta do quarto; um traço no
 * lugar dele só gastaria espaço dizendo "não sei".
 *
 * `compacto` tira o título textual dos selos e encolhe a fonte — é o modo da linha do Depot,
 * onde a fileira divide 300 px com sprite, nome, barra de vida e dois botões.
 */
function selosAtributos(pk, { compacto = false } = {}) {
  if (!pk) return '';
  const iv = ivTotalDoPokemon(pk);
  const q = Number(pk.quality ?? pk.qualidade);
  const nota = notaDoPokemon(pk);
  const partes = [
    seloPotencia(Number(pk.potencia) || 1),
    iv != null ? seloIv(iv) : '',
    Number.isFinite(q) && q > 0 ? seloQualidade(q) : '',
    nota != null && Number.isFinite(Number(nota)) ? seloNota(nota) : '',
    pokemonTemXpShareHeld(pk) ? seloXpShareHeld() : '',
  ].filter(Boolean);
  if (!partes.length) return '';
  // `span`, e não `div`: na tabela de preços a fileira entra DENTRO da célula do item, que é
  // inline. O CSS já dá `display: flex` (ou `grid`, nos cards), então o desenho é o mesmo em
  // todo lugar — muda só o fato de o HTML passar a ser válido nos seis pontos que a usam.
  return `<span class="pk-selos${compacto ? ' compacto' : ''}">${partes.join('')}</span>`;
}

/** Os selos de tipo, no formato pequeno do card. */
const chipsDeTipo = (tipos) =>
  (tipos ?? []).filter(Boolean).map((x) => `<span class="cm-chip tipo ${x}">${x}</span>`).join('');

/**
 * Os tipos de um pokémon anunciado.
 *
 * A ficha dos anúncios NOVOS já traz `tipos`; os abertos antes desta versão não têm, e para
 * esses o catálogo de espécies que a tela carregou no login responde igual. Sem essa queda,
 * meia vitrine ficaria sem selo até os anúncios velhos rodarem.
 */
function tiposDaFicha(ficha) {
  if (ficha.tipos?.length) return ficha.tipos;
  const esp = especieDe(ficha); // pelo id e, nas fichas velhas que não o têm, pelo nome
  return esp ? [esp.type1, esp.type2] : [];
}

/**
 * As FAIXAS da barra lateral do Mercado, cada uma com piso e teto ("nota de 3,8 a 4,1", "IV
 * acima de 166", "potência de P3 para cima"). A ordem é a da fileira de selos do card —
 * potência, IV, qualidade, nota —, com o nível na frente. `id` monta o id das caixas
 * (`cm-iv-min`, `cm-iv-max`); `decimal` troca a caixa numérica por texto (ver
 * `htmlFaixaMercado`). O servidor tem a mesma lista em `market-db.mjs` → `FAIXAS`.
 */
const FAIXAS_MERCADO = [
  { id: 'nivel', rotulo: 'cm.faixaNivel', min: 1, campos: ['nivelMin', 'nivelMax'] },
  { id: 'pot', rotulo: 'cm.faixaPotencia', min: POTENCIA_MIN, max: POTENCIA_MAX, campos: ['potenciaMin', 'potenciaMax'] },
  { id: 'iv', rotulo: 'cm.faixaIv', min: IV_MIN, max: IV_MAX, campos: ['ivMin', 'ivMax'] },
  { id: 'qual', rotulo: 'cm.faixaQualidade', decimal: true, campos: ['qualidadeMin', 'qualidadeMax'] },
  { id: 'nota', rotulo: 'cm.faixaNota', decimal: true, campos: ['notaMin', 'notaMax'] },
];

const zerarFaixasDoMercado = (f) => {
  for (const { campos } of FAIXAS_MERCADO) for (const c of campos) f[c] = '';
};

/**
 * As faixas como vão ao servidor — só na aba de pokémon. O campo guarda o que foi DIGITADO
 * ("1,3" no teclado em português); a troca por ponto acontece só aqui, na saída, e assim a caixa
 * continua mostrando o que a pessoa escreveu.
 */
const faixasDoPedido = (f) => Object.fromEntries(FAIXAS_MERCADO.flatMap(({ decimal, campos }) =>
  campos.map((c) => [c, f.tipo !== 'pokemon' ? '' : decimal ? String(f[c] ?? '').replace(',', '.') : f[c]])));

/**
 * Uma faixa da barra lateral: o rótulo e as duas caixas, "mín – máx".
 *
 * As decimais (qualidade, nota) são `text`, e não `number`, pelo mesmo motivo da calculadora:
 * no teclado de um celular em português o separador é VÍRGULA, e um campo number devolve string
 * vazia quando o valor tem vírgula. O jogador digitava 1,3 e o filtro simplesmente não
 * acontecia, sem nenhum aviso.
 */
function htmlFaixaMercado({ id, rotulo, min, max, decimal, campos }, f) {
  const caixa = (ponta, campo) => {
    const valor = String(f[campo] ?? '');
    const dica = t(ponta === 'min' ? 'cm.faixaMin' : 'cm.faixaMax');
    const tipo = decimal
      ? 'type="text" inputmode="decimal" maxlength="5"'
      : `type="number" inputmode="numeric" step="1"${min != null ? ` min="${min}"` : ''}${max != null ? ` max="${max}"` : ''}`;
    return `<input id="cm-${id}-${ponta}" ${tipo} placeholder="${escapar(dica)}"
                   aria-label="${escapar(`${t(rotulo)} — ${dica}`)}"
                   value="${escapar(decimal ? virgula(valor) : valor)}">`;
  };
  return `
    <div class="cm-filtro-num cm-faixa">
      <span>${t(rotulo)}</span>
      <div class="cm-faixa-caixas">${caixa('min', campos[0])}<i aria-hidden="true">–</i>${caixa('max', campos[1])}</div>
    </div>`;
}

/**
 * Quantos filtros da vitrine estão ligados.
 *
 * A BUSCA e a ORDENAÇÃO ficam de fora de propósito: as duas estão sempre visíveis na barra de
 * cima, então nunca são a surpresa que esvazia a lista. Os que contam são os que se escondem
 * atrás da folha no celular.
 */
function contarFiltrosDoMercado(f) {
  if (f.tipo === 'item') return (f.categoria ? 1 : 0) + (f.soComEstoque ? 1 : 0);
  if (f.tipo !== 'pokemon') return 0;
  return [
    f.elemento, f.soShiny, f.soP5, f.soTmElemental, f.soTmAoe, f.semOutland,
    // Escolher UMA moeda é que conta como filtro agora: "Todas" é o ponto de partida, e uma
    // vitrine recortada a Coins (ou a gemas) é o que precisa se explicar no celular, onde a
    // chave mora dentro da folha que fecha.
    f.moeda !== MOEDA_TODAS ? f.moeda : '',
    // O agrupamento DESLIGADO conta pela mesma razão: no celular ele mora dentro da folha, e
    // uma vitrine que de repente tem onze páginas do mesmo Scizor precisa dizer por quê.
    !f.agregarEspecies ? 'lista' : '',
  ].filter((v) => v !== '' && v != null && v !== false).length
    // Uma faixa conta UMA vez, com piso, teto ou os dois: na tela ela é um filtro só.
    + FAIXAS_MERCADO.filter(({ campos }) => campos.some((c) => String(f[c] ?? '') !== '')).length
    // Cada critério de "Filtrar por" conta um. No celular a barra da vitrine mora DENTRO da
    // folha que fecha, então um "maior potência" esquecido lá dentro reordena a lista sem
    // nenhuma pista na tela — é exatamente o que este contador existe para evitar.
    + criteriosDoMercado().length;
}

/**
 * Zera tudo que `contarFiltrosDoMercado` conta, sem mexer na aba nem na busca.
 *
 * `agregarEspecies` fica DE FORA de propósito, mesmo contando no número: ele não é um recorte da
 * vitrine, é o formato dela. Quem desligou o agrupamento e clica em "Limpar filtros" quer tirar o
 * "só shiny acima de IV 150" — não quer a tela inteira trocando de forma debaixo dele.
 */
function limparFiltrosDoMercado() {
  Object.assign(estado.cmFiltro, {
    moeda: MOEDA_TODAS, elemento: '', categoria: '', soShiny: false, soP5: false,
    soTmElemental: false, soTmAoe: false, semOutland: false, criterios: [],
    soComEstoque: false,
  });
  zerarFaixasDoMercado(estado.cmFiltro);
}

/**
 * A MEMÓRIA dos filtros do Mercado da Comunidade (o "RMT" do menu).
 *
 * Quem compra sempre o mesmo tipo de coisa ("P5 em gemas, sem Outland, do mais barato") tinha de
 * remontar tudo a cada F5, e no celular a cada vez que o navegador descartava a aba. Fica no
 * navegador, como as outras preferências de tela: não vai ao servidor e não segue a conta para
 * outro aparelho.
 *
 * A BUSCA fica de fora de propósito: é uma pergunta de agora ("charizard"), e reabrir o Mercado
 * amanhã com a vitrine presa nela mostraria uma lista quase vazia sem motivo aparente. O resto
 * volta, inclusive a aba (Pokémon, Itens, Diamantes) — é o "onde eu estava".
 *
 * Grava em `pedirMercado`, e não em cada botão, porque TODA mudança de filtro termina lá: os
 * botões, a ordenação, os critérios, as faixas e o "Limpar". Um controle novo entra na memória
 * sem ninguém lembrar de ligá-lo aqui.
 */
const CHAVE_FILTROS_MERCADO = 'cm-filtros';

/**
 * A versão do que está guardado, e para que ela serve.
 *
 * Quando a MOEDA abria em Coins, ninguém escolhia Coins — era só o padrão, e é isso que está
 * gravado no navegador de todo mundo que já abriu o Mercado. Com "Todas" no lugar, ler aquele
 * "gold" como escolha manteria a metade em gemas escondida justamente de quem nunca mexeu no
 * botão. Então o `v` marca o que foi gravado JÁ SABENDO que "Todas" existe: abaixo disso, a
 * moeda salva é ignorada e vale o padrão novo. O resto dos filtros (que não mudaram de sentido)
 * volta inteiro.
 */
const VERSAO_FILTROS_MERCADO = 2;

function guardarFiltrosDoMercado() {
  const { busca, ...resto } = estado.cmFiltro;
  try {
    localStorage.setItem(CHAVE_FILTROS_MERCADO, JSON.stringify({ ...resto, v: VERSAO_FILTROS_MERCADO }));
  } catch { /* privado / quota */ }
}

/**
 * Relê o que foi guardado POR CIMA do padrão, campo a campo: só entra campo que o padrão tem, com
 * o mesmo tipo dele, e valor que a tela sabe desenhar. Um campo renomeado numa versão futura, ou
 * um valor que não existe mais, cai fora em vez de virar uma vitrine vazia sem explicação.
 */
function restaurarFiltrosDoMercado() {
  let salvo;
  try {
    salvo = JSON.parse(localStorage.getItem(CHAVE_FILTROS_MERCADO) ?? 'null');
  } catch {
    return;
  }
  if (!salvo || typeof salvo !== 'object') return;
  const f = estado.cmFiltro;
  // A moeda de uma gravação anterior a "Todas" não entra — ver `VERSAO_FILTROS_MERCADO`.
  const moedaVale = Number(salvo.v) >= VERSAO_FILTROS_MERCADO;
  for (const [campo, padrao] of Object.entries(f)) {
    if (campo === 'busca' || !Object.hasOwn(salvo, campo)) continue;
    if (campo === 'moeda' && !moedaVale) continue;
    const v = salvo[campo];
    if (Array.isArray(padrao)) {
      if (Array.isArray(v)) f[campo] = v;
    } else if (typeof v === typeof padrao) f[campo] = v;
  }
  if (!FILTROS_TIPO.some((x) => x.id === f.tipo)) f.tipo = 'pokemon';
  // "Todas" é um valor válido em qualquer aba: as que não a oferecem (itens, diamantes) a leem
  // como Coins sozinhas (ver `moedaDoPedido` e o switch do painel de diamantes). Converter aqui
  // faria o jogador que passou pela aba de itens voltar para Pokémon com o padrão trocado.
  if (f.moeda !== 'orb' && f.moeda !== 'gold' && f.moeda !== MOEDA_TODAS) f.moeda = MOEDA_TODAS;
  if (!ORDENS_MERCADO.some((o) => o.id === f.ordem)) f.ordem = ORDENS_MERCADO[0].id;
  if (f.elemento && !TIPOS_FILTRO.includes(f.elemento)) f.elemento = '';
  if (!CATEGORIAS_ITEM.some((c) => c.id === f.categoria)) f.categoria = '';
  f.criterios = f.criterios.filter(criterioMercado).slice(0, MAX_CRITERIOS_MERCADO);
}
restaurarFiltrosDoMercado();

/**
 * Coins × Gemas — sidebar (desktop) e barra rápida (celular).
 *
 * A escolha é EXCLUSIVA, e é o que faz "menor preço" querer dizer alguma coisa: um anúncio de
 * 900 Coins e um de 3 gemas não se comparam por número, e misturar os dois numa lista ordenada
 * por preço produziria uma ordem sem sentido nenhum. Vale nas duas abas em que existe preço
 * unitário comparável — pokémon e diamante.
 */
function htmlFiltroMoedaMercado(moeda, { inline = false, comTodas = false } = {}) {
  const todas = comTodas && moeda === MOEDA_TODAS;
  const botoes = `<div class="cm-moedas cm-moedas-filtro${comTodas ? ' cm-moedas-tres' : ''}">
    ${comTodas
      ? `<button type="button" class="cm-moeda ${todas ? 'on' : ''}" data-moeda-filtro="${MOEDA_TODAS}">
           ${t('cm.moedaTodas')}
         </button>`
      : ''}
    <button type="button" class="cm-moeda ${!todas && moeda !== 'orb' ? 'on' : ''}" data-moeda-filtro="gold">
      ${seloOuro(18)}${t('cm.emCoins')}
    </button>
    <button type="button" class="cm-moeda ${moeda === 'orb' ? 'on' : ''}" data-moeda-filtro="orb">
      ${seloGema(20)}${t('cm.emGemas')}
    </button>
  </div>`;
  if (inline) return `<span class="cm-moeda-lbl">${t('cm.moeda')}</span>${botoes}`;
  return `<div class="cm-fgrupo">${t('cm.moeda')}</div>${botoes}`;
}

function renderComunidade() {
  const f = estado.cmFiltro;
  const meus = estado.cmAba === 'meus';
  const favoritos = estado.cmAba === 'favoritos';
  // As três opções de mercado (recentes, mais barato, mais caro) valem para as duas abas: elas
  // falam do ANÚNCIO, não da mercadoria. O que era exclusivo de pokémon virou critério e mora
  // no seletor de "Filtrar por", que só aparece na aba de pokémon.
  const ordens = ORDENS_MERCADO;
  const movel = movelAtivo();
  // Quantos filtros estão ligados AGORA. No desktop a barra lateral está sempre à vista e o
  // número não faria falta; no celular ela é uma folha que fecha, e sem esse contador um
  // "IV mínimo 150" esquecido vira uma vitrine vazia sem explicação nenhuma.
  const ativos = contarFiltrosDoMercado(f);
  const btLimpar = ativos
    ? `<button type="button" class="cm-limpar" id="cm-limpar">${t('cm.limparFiltros')}</button>`
    : '';
  const rodapeDaFolha = folhaDeFiltrosRodape(btLimpar);

  // Os 18 selos de elemento e o "ordenar por" ficam ACIMA da vitrine no desktop e dentro da
  // folha de filtros no celular — sozinhos eles são quatro fileiras, e ali empurravam o
  // primeiro anúncio para fora da tela. Mesmo HTML, endereço diferente.
  const barraDaVitrine = `
        <div class="cm-barra">
          <!-- O tipo ELEMENTAL vale para pokémon (a espécie tem tipo) e para item (a pedra e o
               TM têm), e não para diamante — não existe diamante de fogo. Mostrar o seletor ali
               seria oferecer um recorte que sempre devolve a lista inteira. -->
          ${f.tipo === 'diamante' ? '' : htmlTipoMercado(f.elemento)}
          ${f.tipo === 'pokemon' ? htmlFiltrarPorMercado() : ''}
          ${f.tipo === 'diamante'
            ? ''
            : `<label class="cm-ordenar">${t('cm.ordenarPor')}
                <select id="cm-ordem">
                  ${ordens.map((o) => `<option value="${o.id}" ${f.ordem === o.id ? 'selected' : ''}>${t(o.nome)}</option>`).join('')}
                </select>
              </label>`}
        </div>`;

  // No celular o campo perde ~100 px para a lupa e para os dois botões ao lado: "buscar
  // pokémon pelo nome…" morria no meio da palavra. A lupa dentro do campo já diz o verbo.
  const dicaBusca = f.tipo === 'pokemon'
    ? (movel ? 'cm.buscarPokemonCurto' : 'cm.buscarPokemon')
    : 'cm.buscar';
  const busca = `<input id="cm-busca" class="cm-busca" placeholder="${t(dicaBusca)}"
             value="${escapar(f.busca)}" autocomplete="off">`;

  /*
   * A BARRA DE CIMA, e ela é DUAS peças diferentes — não a mesma com CSS por cima.
   *
   * No desktop são seis botões escritos, e escrito está certo: há largura de sobra e a palavra
   * não deixa dúvida. No celular os mesmos seis, em duas colunas, custavam ~300 px — mais da
   * metade da tela — antes do primeiro anúncio aparecer, e a vitrine (que é o produto desta
   * tela) ficava com uma fileira e meia de card.
   *
   * A montagem de celular é a de qualquer vitrine de aplicativo:
   *
   *   [ 🔍 buscar…            ] [ ☲² ] [ + ]   busca + filtro + anunciar
   *   [ 🪙 1.838.751.096  💎 1.116   ↓  ↑ ]   a carteira, numa linha só
   *   [ etiqueta │ ↑ │ ↓ │ prancheta ]      as quatro portas secundárias, em ícone
   *
   * As quatro de baixo continuam com RÓTULO, miúdo, embaixo do ícone: ícone sozinho é charada
   * quando quatro deles são vizinhos, e "vendas" e "compras" são justamente o par que ninguém
   * acerta no chute. O que sai é a frase longa ("Histórico de vendas"), não a palavra.
   */
  const barraTopo = movel
    ? `
    <div class="cm-topo cm-topo-movel">
      <div class="cm-busca-linha">
        <span class="cm-busca-caixa">${lupa()}${busca}</span>
        <button type="button" class="filtros-bt cm-ico-bt" id="filtros-bt"
                aria-label="${t('mapa.filtros')}" title="${t('mapa.filtros')}">
          ${iconeFunil()}${ativos ? `<span class="filtros-conta">${ativos}</span>` : ''}
        </button>
        <button id="cm-anunciar" class="cm-acao destaque cm-ico-bt"
                aria-label="${t('cm.anunciar')}" title="${t('cm.anunciar')}">${iconeMais()}</button>
      </div>
      <!-- A carteira. Depositar e sacar SÃO A ÚNICA porta para pôr e tirar gema do jogo — não
           existe outro botão em lugar nenhum —, então aqui eles não podem virar ícone pelado:
           levam a seta em cima e a palavra embaixo, a mesma fôrma dos quatro atalhos. A seta é
           o caractere, e não o desenho de bandeja do histórico: na fileira de baixo aquela
           mesma bandeja já quer dizer "vendas" e "compras", e repeti-la aqui com outro
           sentido seria trocar as bolas de propósito. -->
      <span class="cm-carteira">
        ${seloOuro(18)} <b id="cm-gold" class="cm-gold">${num(estado.eu?.gold ?? 0)}</b>
        ${seloGema(22)} <b id="cm-gemas">${num(estado.eu?.orbs ?? 0)}</b>
        <button id="cm-deposito" class="cm-acao cm-atalho cm-carteira-bt"
                aria-label="${t('orbs.deposito')}"><i>↓</i><span>${t('orbs.depositoCurto')}</span></button>
        <button id="cm-withdraw" class="cm-acao cm-atalho cm-carteira-bt"
                aria-label="${t('orbs.withdraw')}"><i>↑</i><span>${t('orbs.withdrawCurto')}</span></button>
      </span>
      <div class="cm-atalhos">
        <button id="cm-meus" class="cm-acao cm-atalho ${meus ? 'on' : ''}"
                aria-label="${t('cm.meusAnuncios')}">${iconeEtiqueta()}<span>${t('cm.meusCurto')}</span></button>
        <button id="cm-favoritos-atalho" class="cm-acao cm-atalho ${favoritos ? 'on' : ''}"
                aria-label="${t('cm.favoritos')}"><i class="cm-fav-ico" aria-hidden="true">★</i><span>${t('cm.favoritosCurto')}</span></button>
        <button id="cm-historico" class="cm-acao cm-atalho"
                aria-label="${t('cm.historicoVendas')}">${iconeFluxo('cima')}<span>${t('cm.vendasCurto')}</span></button>
        <button id="cm-historico-compras" class="cm-acao cm-atalho"
                aria-label="${t('cm.historicoCompras')}">${iconeFluxo('baixo')}<span>${t('cm.comprasCurto')}</span></button>
        <button id="cm-historico-global" class="cm-acao cm-atalho"
                aria-label="${t('cm.historicoGlobal')}">${iconePrancheta()}<span>${t('cm.precosCurto')}</span></button>
      </div>
    </div>`
    : `
    <div class="cm-topo">
      ${busca}
      <button id="cm-anunciar" class="cm-acao destaque">${t('cm.anunciar')}</button>
      <button id="cm-meus" class="cm-acao ${meus ? 'on' : ''}">${t('cm.meusAnuncios')}</button>
      <button id="cm-historico" class="cm-acao">${t('cm.historicoVendas')}</button>
      <button id="cm-historico-compras" class="cm-acao">${t('cm.historicoCompras')}</button>
      <!-- A tabela de preços. Prancheta e não palavra: a barra já tem cinco botões de texto e
           um sexto "Histórico de vendas do servidor" ao lado de "Histórico de vendas" viraria
           duas frases quase iguais que ninguém para para distinguir. É a MESMA prancheta das
           estatísticas da sessão — no jogo, prancheta já quer dizer "os números disto aqui". -->
      <button id="cm-historico-global" class="cm-acao cm-acao-ico" title="${t('cm.historicoGlobal')}"
        aria-label="${t('cm.historicoGlobal')}">${iconePrancheta()}<span class="cm-acao-rot">${t('cm.historicoGlobalTitulo')}</span></button>
      <!-- Carteira de ouro e gemas: as duas moedas que circulam neste mercado. -->
      <span class="cm-carteira">
        ${seloOuro(28)} <b id="cm-gold" class="cm-gold">${num(estado.eu?.gold ?? 0)}</b>
        ${seloGema(28)} <b id="cm-gemas">${num(estado.eu?.orbs ?? 0)}</b>
        <button id="cm-deposito" class="cm-acao">${t('orbs.deposito')}</button>
        <button id="cm-withdraw" class="cm-acao">${t('orbs.withdraw')}</button>
      </span>
    </div>`;

  return `
    ${barraTopo}
    ${movel && abaEscolheMoeda(f.tipo) && !meus
      ? `<div class="cm-moeda-bar">${htmlFiltroMoedaMercado(f.moeda, { inline: true, comTodas: abaAceitaTodasMoedas(f.tipo) })}</div>`
      : ''}
    <div class="cm-corpo">
      <div class="cm-filtros">
        ${movel ? `<div class="filtros-folha-topo"><h3>${t('mapa.filtros')}</h3></div>` : ''}
        <!-- FAVORITOS, acima do Tipo: é uma lista do jogador, não um recorte da vitrine — e é o
             atalho para não rolar trinta páginas atrás do pokémon que ele viu ontem. -->
        <div class="cm-fgrupo">${t('cm.favoritosGrupo')}</div>
        <button class="cm-filtro cm-fav-filtro ${favoritos ? 'on' : ''}" id="cm-favoritos">
          <span class="cm-fico cm-fav-ico" aria-hidden="true">★</span>${t('cm.favoritos')}<em class="cm-fav-conta">${num(totalFavoritosMercado())}</em></button>
        <div class="cm-fgrupo">${t('cm.tipo')}</div>
        ${FILTROS_TIPO.map(
          (x) => `<button class="cm-filtro ${f.tipo === x.id ? 'on' : ''}" data-tipo="${x.id}">
                    <span class="cm-fico" data-ico="${x.ico}" data-ico-px="16"></span>${t(x.nome)}</button>`,
        ).join('')}

        ${abaEscolheMoeda(f.tipo) && !movel ? htmlFiltroMoedaMercado(f.moeda, { comTodas: abaAceitaTodasMoedas(f.tipo) }) : ''}

        ${f.tipo === 'pokemon'
          ? `<div class="cm-fgrupo">${t('cm.raridade')}</div>
             <button class="cm-filtro ${f.soShiny ? 'on' : ''}" id="cm-shiny">✨ ${t('cm.soShiny')}</button>
             <button class="cm-filtro ${f.soP5 ? 'on' : ''}" id="cm-p5">${seloPotencia(5)} ${t('cm.soP5')}</button>
             <button class="cm-filtro ${f.soTmElemental ? 'on' : ''}" id="cm-tm-elemental"><span class="tm-selo">TM</span> ${t('cm.soTmElemental')}</button>
             <button class="cm-filtro ${f.soTmAoe ? 'on' : ''}" id="cm-tm-aoe"><span class="tm-selo aoe">AoE</span> ${t('cm.soTmAoe')}</button>
             <!-- ESPÉCIE: dois interruptores. O primeiro decide o FORMATO da vitrine (uma linha
                  por espécie, ou a lista de anúncios de sempre) e o segundo tira as variantes de
                  Outland (#2001+) — a busca por texto casa "pupitar" com "Ancient Pupitar", e
                  quem quer o Pupitar para evoluir em Tyranitar rolaria por cima de todos eles. -->
             <div class="cm-fgrupo">${t('cm.especie')}</div>
             <button class="cm-filtro ${f.agregarEspecies ? 'on' : ''}" id="cm-agregar" aria-pressed="${f.agregarEspecies ? 'true' : 'false'}"
                     title="${escapar(t('cm.agregarDica'))}"><span class="cm-fico cm-agregar-ico" aria-hidden="true">▦</span>${t('cm.agregar')}</button>
             <button class="cm-filtro ${f.semOutland ? 'on' : ''}" id="cm-sem-outland" aria-pressed="${f.semOutland ? 'true' : 'false'}"
                     title="${escapar(t('cm.semOutlandDica'))}"><span class="tm-selo outland">#2001+</span> ${t('cm.semOutland')}</button>
             <div class="cm-fgrupo">${t('cm.faixas')}</div>
             ${FAIXAS_MERCADO.map((x) => htmlFaixaMercado(x, f)).join('')}`
          : ''}

        ${f.tipo === 'diamante'
          ? `<div class="cm-fgrupo">${t('cm.diamantes')}</div>
             <p class="cm-nota cm-dia-nota">${t('cm.diamanteVitrineNota')}</p>
             <!-- O aviso de que o diamante não volta ao Mercado mora do lado da COMPRA, e não
                  só no modal de anunciar: quem precisa saber disso antes de decidir é quem
                  está com o dedo no botão de comprar. Descobrir depois, ao tentar revender, é
                  o caminho do ticket no Discord. -->
             <p class="cm-nota cm-dia-nota">${t('cm.diamanteCompraAviso')}</p>
             <button type="button" class="cm-filtro cm-dia-vender" id="cm-dia-vender">
               <span class="cm-fico" data-ico="img:${ICONE_DIAMANTE}" data-ico-px="16"></span>${t('cm.diamanteVender')}
             </button>`
          : ''}

        ${f.tipo === 'item'
          ? `<div class="cm-fgrupo">${t('cm.categoria')}</div>
             ${CATEGORIAS_ITEM.map(
               (c) => `<button class="cm-filtro ${f.categoria === c.id ? 'on' : ''}" data-cat="${c.id}">${t(c.nome)}</button>`,
             ).join('')}
             <button class="cm-filtro ${f.soComEstoque ? 'on' : ''}" id="cm-so-estoque">${t('cm.soComEstoque')}</button>`
          : ''}
        ${movel ? barraDaVitrine + rodapeDaFolha : btLimpar}
      </div>

      <div class="cm-painel">
        ${movel ? '' : barraDaVitrine}
        <div class="cm-lista" id="cm-lista"></div>
        <div class="cm-paginas" id="cm-paginas"></div>
      </div>
    </div>`;
}

/**
 * Pede ao servidor o que a aba atual mostra. Toda mudança de filtro passa por aqui.
 *
 * O filtro de ELEMENTO e o de CATEGORIA só descem quando fazem sentido para a aba: guardá-los
 * no estado (em vez de zerar ao trocar de aba) faz o jogador voltar para "Pokémon de fogo"
 * depois de dar uma olhada nos itens, mas mandá-los na aba errada pediria ao servidor uma
 * interseção vazia e a vitrine viria em branco sem explicação.
 */
function pedirMercado() {
  guardarFiltrosDoMercado();
  if (estado.cmAba === 'meus') return enviar({ t: 'market.meus' });
  if (estado.cmAba === 'favoritos') {
    // Os cards de ITEM favorito mostram quantos vendem e a partir de quanto: é o resumo da
    // vitrine de itens, pedido inteiro (sem o filtro de categoria da vitrine).
    if (favoritosItensMercado().length) enviar({ t: 'market.itens' });
    // O mesmo para as ESPÉCIES favoritas, na lista à parte que o servidor guarda.
    if (favoritosEspeciesMercado().length) enviar({ t: 'market.especies', favoritos: 1 });
    return enviar({ t: 'market.favoritos' });
  }
  // A aba de itens não pagina anúncio a anúncio: pede o resumo do catálogo e, se já houver
  // um item aberto, os vendedores dele.
  if (vitrineDeItens()) {
    const f = estado.cmFiltro;
    enviar({ t: 'market.itens', elemento: f.elemento, categoria: f.categoria });
    pedirAnunciosItem();
    return;
  }
  const f = estado.cmFiltro;
  // Os mesmos filtros descem nas duas leituras da aba de pokémon — a grade de espécies e a
  // lista de ofertas de uma delas. É o que faz o "Só shiny" da grade e o da lista contarem a
  // mesma história: o servidor recorta as duas com o mesmo `WHERE`.
  const pedido = {
    tipo: f.tipo,
    moeda: moedaDoPedido(f),
    busca: f.busca,
    // Diamante é sempre do mais barato para o mais caro — é a mesma ordem fixa do painel de
    // item, e a razão é a mesma: quem abre a aba está comprando diamante, não escolhendo um
    // exemplar. Por isso o "Ordenar por" nem aparece nessa aba.
    ordem: f.tipo === 'diamante' ? 'baratos' : f.ordem,
    // Os critérios do pokémon vão à parte do `ordem`: lá o servidor põe um só (o eixo do
    // mercado, que fecha o ORDER BY) e aqui vários, na ordem de prioridade. Só na aba de
    // pokémon — item não tem IV nem nota para ordenar.
    criterios: f.tipo === 'pokemon' ? criteriosDoMercado() : [],
    elemento: f.tipo === 'pokemon' ? f.elemento : '',
    categoria: f.tipo === 'item' ? f.categoria : '',
    soShiny: f.tipo === 'pokemon' ? f.soShiny : false,
    soP5: f.tipo === 'pokemon' ? f.soP5 : false,
    soTmElemental: f.tipo === 'pokemon' ? f.soTmElemental : false,
    soTmAoe: f.tipo === 'pokemon' ? f.soTmAoe : false,
    semOutland: f.tipo === 'pokemon' ? f.semOutland : false,
    ...faixasDoPedido(f),
    pagina: estado.cmPagina,
  };
  // A aba de pokémon abre na grade de ESPÉCIES (uma por card) e só desce à lista de anúncios
  // quando o jogador escolhe uma.
  if (vitrineDeEspecies()) return enviar({ t: 'market.especies', ...pedido });
  enviar({
    t: 'market.listar',
    ...pedido,
    especieId: estado.cmEspecieSel?.id ?? 0,
  });
}

/** Chegou resposta do servidor. `aba` diz o que veio. */
function receberMercado(m) {
  if (m.aba === 'criado') {
    // Publicou: volta para "meus anúncios", que é onde a pessoa quer conferir o que fez.
    estado.cmAba = 'meus';
    if (estado.modalAberto === 'community') abrirModal('community');
    return;
  }
  // UM anúncio pedido pelo link do chat ou pelo "Abrir no Market" do Comércio.
  if (m.aba === 'anuncio') return mostrarAnuncioAvulso(m);
  // A espera do alto-falante: chega sozinha (depois de anunciar, ou de uma recusa por espera) e de
  // carona em "Meus anúncios", que é onde o botão mora.
  if (m.aba === 'altoFalante') {
    estado.cmAltoFalanteAte = Number(m.ate) || 0;
    atualizarAltoFalantes();
    return;
  }
  if ('altoFalanteAte' in m) estado.cmAltoFalanteAte = Number(m.altoFalanteAte) || 0;
  if (m.aba === 'historico' || m.aba === 'historicoCompras' || m.aba === 'historicoGlobal') {
    estado.cmHistDados = m;
    estado.cmHistPagina = m.pagina ?? estado.cmHistPagina;
    estado.cmHistModo = HIST_MODO_POR_ABA[m.aba] ?? 'vendas';
    pintarHistoricoMercado();
    return;
  }
  // O preço médio de venda do diamante chega de carona em duas respostas: na cota (que abre a
  // folha de anunciar) e na vitrine da aba de diamantes (que é onde se compra).
  if ('mediaDiamante' in m) estado.cmMediaDiamante = m.mediaDiamante;
  // Vitrine de itens: `itens` é o resumo do catálogo (quantos anúncios, menor preço) e
  // `item` são os vendedores de UM item numa moeda. Guardados em chaves separadas porque
  // trocar de moeda no painel não pode apagar o resumo da lista da esquerda.
  if (m.aba === 'diamantesCota') {
    // Quem espera é a folha de anunciar, que se registrou em `cmCotaDiamantes`. Se ela já
    // fechou (ou o jogador voltou ao primeiro passo), a resposta é descartada em silêncio —
    // redesenhar por cima do que ele está fazendo agora seria pior que perder o pacote.
    cmCotaDiamantes?.(m.cota);
    return;
  }
  if (m.aba === 'itens') {
    estado.cmItens = m.resumo ?? {};
    estado.cmMedias = m.medias ?? null;
    cmPassoPrecoAtualizar?.();
    if (estado.modalAberto === 'community') pintarMercado();
    return;
  }
  if (m.aba === 'item') {
    estado.cmItemLinhas = { ...(estado.cmItemLinhas ?? {}), [`${m.itemId}:${m.moeda}`]: m.linhas ?? [] };
    if (estado.modalAberto === 'community') pintarMercado();
    abrirAnuncioPendente(m);
    return;
  }
  // O resumo das ESPÉCIES favoritas, para os cards da aba Favoritos. Mapa próprio, como o dos
  // itens (`cmItens`): ele não é a grade, é o que cada card daquela grade diz.
  if (m.aba === 'especiesFav') {
    estado.cmEspeciesFav = Object.fromEntries((m.linhas ?? []).map((l) => [l.speciesId, l]));
    if (estado.modalAberto === 'community') pintarMercado();
    return;
  }
  // Resposta de uma GRADE que o jogador já deixou: a lista dos Favoritos chegando depois de ele
  // voltar à vitrine (ou as espécies depois de ele abrir uma) desenharia a grade errada por cima
  // da certa. As quatro dividem o mesmo `cmDados` e o mesmo `#cm-lista`, então cada uma só entra
  // se ainda for a que está na tela.
  if (m.aba === 'favoritos' || m.aba === 'especies' || m.aba === 'vitrine' || m.aba === 'meus') {
    if (m.aba !== gradeEsperadaDoMercado()) return;
  }
  // Página que ficou FORA DO FIM: o jogador estava na 3 e as espécies de lá saíram (venderam, ou
  // um filtro encolheu a lista). A grade agrupada conta os grupos da própria consulta, então uma
  // página vazia volta sem total — e sem total não há paginação desenhada, o que deixaria a
  // pessoa presa numa grade vazia sem botão de voltar. Volta ao começo e pede de novo; a página 0
  // vazia é o "não há nada", e aí não repete.
  if (m.aba === 'especies' && !m.linhas?.length && (m.pagina ?? 0) > 0) {
    estado.cmPagina = 0;
    return pedirMercado();
  }
  estado.cmDados = m;
  if (estado.modalAberto === 'community') pintarMercado();
}

/**
 * A última resposta, se ela for do FORMATO que a tela desenha agora — senão, "carregando".
 *
 * As duas vitrines de pokémon dividem `cmDados` e `#cm-lista`, e as linhas de uma não servem na
 * outra: um grupo de espécie não tem `ficha`, e desenhá-lo como card de anúncio estoura no
 * `a.ficha.shiny`. Isso acontece na janela entre o clique que troca o formato e a resposta nova
 * — a tela repinta na hora, com o que tem na memória. Aqui o descompasso vira a espera que ele
 * de fato é.
 */
function dadosDaGradeCerta() {
  const d = estado.cmDados;
  if (!d) return { linhas: [] };
  // `aba` só falta em `{ linhas: [], carregando: true }`, que já é a espera.
  if (d.aba && (d.aba === 'especies') !== vitrineDeEspecies()) return { linhas: [], carregando: true };
  return d;
}

/** Qual das grades o `#cm-lista` está mostrando agora — o crachá que as respostas têm de trazer. */
function gradeEsperadaDoMercado() {
  if (estado.cmAba === 'favoritos') return 'favoritos';
  if (estado.cmAba === 'meus') return 'meus';
  return vitrineDeEspecies() ? 'especies' : 'vitrine';
}

/** A aba de itens usa a vitrine em lista; pokémon, "meus anúncios" e Favoritos seguem na grade. */
const vitrineDeItens = () => estado.cmFiltro.tipo === 'item' && estado.cmAba === 'vitrine';

/**
 * A grade de ESPÉCIES: a primeira tela da aba de pokémon.
 *
 * Um card por espécie, com "12 ofertas · a partir de X" e o botão "Ver ofertas" — e não trinta
 * cards do mesmo Scizor empurrando todo o resto para a página onze. A lista de anúncios continua
 * existindo inteira; ela passou a ser o SEGUNDO passo (`cmEspecieSel`), como na aba de itens.
 *
 * "Meus anúncios" e os Favoritos ficam de fora: lá a lista é curta e é do jogador — agrupar as
 * suas três vendas por espécie esconderia cada uma atrás de um clique sem economizar nada.
 *
 * E o jogador pode desligar (`agregarEspecies`, na barra lateral). Quando a vitrine agrupada
 * entrou, metade dos jogadores gostou e a outra metade quis a lista de volta — e as duas razões
 * são boas: quem procura UMA espécie economiza dez páginas de rolagem, e quem gosta de varrer a
 * feira inteira atrás de uma pechincha perdeu justamente a tela que servia para isso. Desligado,
 * a aba volta a ser a lista de anúncios de sempre, com os mesmos filtros e a mesma ordenação.
 */
const vitrineDeEspecies = () =>
  estado.cmFiltro.tipo === 'pokemon' && estado.cmFiltro.agregarEspecies
  && estado.cmAba === 'vitrine' && !estado.cmEspecieSel;

/** A ESPÉCIE de um card da grade agrupada, do catálogo do cliente — nome, tipos e arte. */
const especieDoCard = (e) => estado.especies?.get(Number(e?.speciesId)) ?? null;

/**
 * O nome de uma espécie na grade. O catálogo manda; o que o servidor mandou é a queda.
 *
 * Os dois deveriam bater sempre — o servidor já resolve pelo catálogo dele no caminho de volta
 * (ver `market.especies`) —, e é justamente por isso que a preferência é local: numa janela de
 * deploy os dois catálogos podem estar uma versão distantes, e quem desenha a grade é este.
 */
const nomeDaEspecieCard = (e) => especieDoCard(e)?.name ?? e?.nome ?? `#${e?.speciesId ?? '?'}`;

/**
 * A ficha de mentira que desenha o sprite do card de espécie.
 *
 * `shiny` só quando TODA oferta do grupo é shiny — o que acontece com o "Só shiny" ligado, e é
 * exatamente quando a arte shiny é a arte certa. Com um shiny entre dez comuns, o card mostra o
 * comum e o selo ✨ diz que há shiny lá dentro; desenhar o dourado ali prometeria uma vitrine
 * inteira de shinys por um único anúncio.
 */
const fichaDoCardEspecie = (e) => ({
  speciesId: Number(e.speciesId),
  nome: nomeDaEspecieCard(e),
  shiny: !!e.shinys && e.shinys === e.anuncios,
});

/** Os tipos elementais do card de espécie — do catálogo, com queda no que o servidor mandou. */
const tiposDaEspecieCard = (e) => {
  const esp = especieDoCard(e);
  return esp ? [esp.type1, esp.type2].filter(Boolean) : (e.tipos ?? []);
};

/**
 * Entra nas ofertas de uma espécie: a lista de anúncios, com os filtros da vitrine mantidos.
 *
 * Os filtros FICAM de propósito. Quem está com "Só shiny · em gemas" ligado e clica em Dragonite
 * pediu os Dragonite shiny em gemas — e foi um card que o servidor só desenhou porque existe pelo
 * menos um. Zerar aqui abriria uma lista que não é a que o card prometeu.
 */
function irParaOfertasDaEspecie(speciesId, nome) {
  const id = Number(speciesId);
  if (!Number.isFinite(id) || id <= 0) return;
  estado.cmAba = 'vitrine';
  estado.cmFiltro.tipo = 'pokemon';
  estado.cmEspecieSel = { id, nome: String(nome ?? '') };
  estado.cmPagina = 0;
  estado.cmDados = { linhas: [], carregando: true };
  abrirModal('community');
}

/** Volta da lista de ofertas para a grade de espécies. */
function voltarParaEspecies() {
  if (!estado.cmEspecieSel) return;
  estado.cmEspecieSel = null;
  estado.cmPagina = 0;
  estado.cmDados = { linhas: [], carregando: true };
  abrirModal('community');
}

/**
 * A faixa que abre a lista de ofertas de uma espécie: o caminho de volta, o nome e a conta.
 *
 * Ocupa a linha inteira da grade (é a mesma fôrma dos títulos da aba Favoritos) porque ela é o
 * cabeçalho desta tela — sem ela, a segunda tela e a primeira são duas grades de cards iguais e
 * nada diz ao jogador onde ele está nem como sair.
 */
function faixaDaEspecieAberta(dados) {
  const sel = estado.cmEspecieSel;
  const el = document.createElement('div');
  el.className = 'cm-esp-faixa';
  const total = Number(dados?.total);
  const conta = Number.isFinite(total) && !dados?.carregando
    ? `<em>${t(total === 1 ? 'cm.especieOferta' : 'cm.especieOfertas', { n: num(total) })}</em>`
    : '';
  // Com o agrupamento DESLIGADO (o jogador chegou aqui pela estrela de uma espécie favorita), o
  // botão não volta para grade nenhuma — volta para a lista. O rótulo diz o que ele faz.
  const voltar = estado.cmFiltro.agregarEspecies ? t('cm.voltarEspecies') : t('cm.voltarVitrine');
  el.innerHTML = `
    <button type="button" class="cm-esp-voltar">‹ ${voltar}</button>
    <b>${escapar(sel?.nome ?? '')}</b>${conta}`;
  el.querySelector('.cm-esp-voltar').onclick = voltarParaEspecies;
  el.appendChild(botaoFavoritoEspecieMercado(sel?.id));
  return el;
}

/**
 * "A partir de" nas moedas que o filtro deixa passar — o rodapé dos cards de espécie.
 *
 * Com uma moeda escolhida sai UMA linha: mostrar "💎 —" numa vitrine filtrada por Coins diria
 * "ninguém vende em gemas", que é falso — o filtro é que não deixou passar. Em "Todas" saem as
 * duas, e é aí que a linha vazia passa a ser informação de verdade.
 */
function precosDaEspecie(resumo, { moedas = ['gold', 'orb'] } = {}) {
  return moedas.map((moedaId) => {
    const v = apartirDe(resumo, moedaId);
    const ico = moedaId === 'orb' ? ICONE_GEMA : srcIcone(ICONE_OURO);
    const valor = v == null
      ? `<span class="cm-preco${moedaId === 'orb' ? ' orb' : ''}"><img src="${ico}" alt="">—</span>`
      : precoComMoeda(v, moedaId, { curto: true });
    return `<div class="cm-fav-item-preco${v == null ? ' nada' : ''}"><i>${t('cm.apartirDe')}</i>${valor}</div>`;
  }).join('');
}

/**
 * Os SELOS do card de espécie: o que existe lá dentro sem ter de entrar.
 *
 * "Tem um shiny", "tem um P5", "tem TM" é a informação que o card de anúncio dava de graça (ele
 * mostra UM bicho) e que o agrupamento esconderia. São pistas, não filtros: quem quer só os shiny
 * liga o "Só shiny" na barra e a grade inteira passa a ser de espécies que têm.
 */
function selosDaEspecie(e) {
  return [
    // O ✨ leva o NÚMERO: "há shiny aqui dentro" é a pista, e "há dois" é a pista inteira — num
    // selo que já existe, sem custar uma linha a mais no card.
    e.shinys ? `<span class="cm-selo-shiny" title="${escapar(t('cm.especieTemShiny', { n: num(e.shinys) }))}">✨ ${num(e.shinys)}</span>` : '',
    e.temP5 ? `<span class="cm-pot p5" title="${escapar(t('cm.especieTemP5'))}">P5</span>` : '',
    e.temTmElemental ? `<span class="tm-selo" title="${escapar(t('cm.especieTemTmElemental'))}">TM</span>` : '',
    e.temTmAoe ? `<span class="tm-selo aoe" title="${escapar(t('cm.especieTemTmAoe'))}">AoE</span>` : '',
  ].filter(Boolean).join('');
}

/**
 * O card de uma ESPÉCIE na grade.
 *
 * É o card de pokémon que já existia, com o miolo trocado: onde havia a fileira P·IV·Q·N de UM
 * exemplar e o botão "Comprar", há quantas ofertas existem, a partir de quanto, e "Ver ofertas".
 * Aqueles números são de um indivíduo e não existem para uma espécie — a média de dez Dragonite
 * diferentes não descreve nenhum deles.
 */
function cardEspecieMercado(e, { moedas = null } = {}) {
  const ficha = fichaDoCardEspecie(e);
  const daVitrine = moedaDoPedido(estado.cmFiltro);
  const linhas = moedas ?? (daVitrine ? [daVitrine] : ['gold', 'orb']);
  const nome = nomeDaEspecieCard(e);

  const el = document.createElement('div');
  el.className = 'cm-card poke cm-card-especie tem-fav' + (ficha.shiny ? ' shiny' : '');
  el.tabIndex = 0;
  el.setAttribute('role', 'button');
  el.innerHTML = `
    <div class="cm-arte-slot"></div>
    <div class="cm-selos">${selosDaEspecie(e)}</div>
    <div class="cm-info">
      <div class="cm-nome" title="${escapar(nome)}"><span class="cm-nome-txt">${escapar(nome)}</span></div>
      <div class="cm-chips">${chipsDeTipo(tiposDaEspecieCard(e))}</div>
      <div class="cm-sub">${t(e.anuncios === 1 ? 'cm.especieOferta' : 'cm.especieOfertas', { n: num(e.anuncios) })}</div>
    </div>
    <div class="cm-rodape">${precosDaEspecie(e, { moedas: linhas })}</div>
    <div class="cm-botoes"><button type="button" class="cm-btn comprar">${t('cm.verOfertas')}</button></div>`;

  const arte = document.createElement('div');
  arte.className = 'cm-arte';
  arte.appendChild(spritePokemon(ficha, 64));
  el.querySelector('.cm-arte-slot').replaceWith(arte);
  el.appendChild(botaoFavoritoEspecieMercado(e.speciesId));

  const abrir = (ev) => {
    if (ev.target.closest('.cm-fav')) return;
    irParaOfertasDaEspecie(e.speciesId, nome);
  };
  el.onclick = abrir;
  el.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      abrir(ev);
    }
  };
  return el;
}

/**
 * O card de uma espécie FAVORITA, na aba Favoritos.
 *
 * Mesmo card da grade, com os números vindos do resumo à parte (`cmEspeciesFav`) — que o servidor
 * monta SEM os filtros da vitrine. A estrela é sobre a espécie, e o que ela guarda é "quero saber
 * o preço de Dragonite", não "de Dragonite P5 em gemas".
 *
 * Espécie favoritada sem nenhuma oferta hoje continua na grade, com "nenhuma oferta agora": é
 * justamente a pergunta que a estrela existe para responder.
 */
function cardEspecieFavorita(speciesId) {
  const esp = estado.especies?.get(Number(speciesId));
  const resumo = estado.cmEspeciesFav?.[speciesId] ?? null;
  if (!esp && !resumo) return null;
  const e = resumo ?? { speciesId: Number(speciesId), anuncios: 0, shinys: 0, minGold: null, minOrb: null };
  // As DUAS moedas, sempre: o resumo desta grade vem sem os filtros da vitrine (ver
  // `market.especies`), e mostrar só a moeda escolhida lá esconderia metade do que ele traz.
  const card = cardEspecieMercado(e, { moedas: ['gold', 'orb'] });
  if (!e.anuncios) {
    card.classList.add('cm-esp-vazia');
    const sub = card.querySelector('.cm-sub');
    if (sub) sub.textContent = t('cm.especieSemOfertas');
  }
  return card;
}

// ------------------------------------------------- vitrine de DIAMANTES (lista)
//
// A aba de diamantes é a vitrine da Steam SEM o catálogo à esquerda.
//
// No mercado de ITENS há duas colunas porque há o que ESCOLHER: qual pedra, qual TM, qual
// ficha de boss — e só depois de escolher é que faz sentido ver quem vende. Diamante é uma
// mercadoria só. Um catálogo de uma linha ("Diamantes") seria um clique obrigatório para
// chegar à única tela que interessa.
//
// Então a coluna da esquerda simplesmente não existe, e o que sobra é o PAINEL DE OFERTAS
// ocupando a largura toda: cabeçalho, a chave Coins/Gemas e a lista de anúncios. A grade de
// cards (a de pokémon) não serve aqui pelo motivo oposto: card existe para mostrar um bicho,
// e aqui todo anúncio tem a mesma arte — o que os distingue são três números em coluna, que
// é exatamente o que uma LINHA compara bem e um card não.
//
// **Sempre do mais barato para o mais caro.** É a mesma ordem fixa do painel de item
// (`anunciosDoItem`, `ORDER BY preco ASC`), e pela mesma razão: quem abre esta tela está
// comprando diamante, não escolhendo um exemplar. Por isso o "Ordenar por" some da barra na
// aba de diamantes — ver `renderComunidade`.

/** A aba de diamantes, fora de "meus anúncios" (que segue na grade de cards). */
const vitrineDeDiamantes = () => estado.cmFiltro.tipo === 'diamante' && estado.cmAba === 'vitrine';

/**
 * Uma oferta de diamante. Mesma fôrma do vendedor de item (`.cmv-linha`), com uma coluna a
 * mais: o TOTAL DO LOTE.
 *
 * As duas colunas de preço não são redundância. O preço por diamante é o que se compara entre
 * as linhas (é por ele que a lista está ordenada); o total é o que sai da carteira, e num lote
 * de 500 os dois números são muito diferentes — quem lê "4.200" e tem 1 milhão acha que pode.
 */
function linhaVitrineDiamante(a) {
  const meu = ehMeuAnuncio(a);
  const retido = anuncioEmRetencao(a);
  return `
    <div class="cmv-linha cmd-linha ${meu ? 'meu' : ''}">
      <span class="cmv-quem">${meu ? t('cm.seuAnuncio') : escapar(a.vendedor)}</span>
      <span class="cmv-qtd">${t('cm.diamanteQtdLinha', { n: num(a.qtd) })}</span>
      <!-- Vão elástico: sem ele o 1fr teria de morar no nick, e num painel de largura
           inteira isso dava 800 px de nada entre o nome e os números. -->
      <span class="cmd-vao"></span>
      <span class="cmv-preco">${precoComMoeda(a.preco, a.moeda)} <i>${t('cm.porDiamante')}</i></span>
      <span class="cmd-total">${t('cm.loteTotal')} ${precoComMoeda(a.preco * a.qtd, a.moeda)}</span>
      ${meu
        ? `<button class="cm-acao cmd-remover" data-remover="${a.id}">${t('cm.remover')}</button>`
        : `<span class="cmv-bts">${htmlBotaoDm(a)}<button class="cm-acao destaque cmv-comprar${retido ? ' cm-retido' : ''}" data-anuncio="${a.id}"${attrRetencao(a)}${
            retido ? ` disabled title="${escapar(t('cm.retencaoComprar'))}"` : ''
          }>${retido ? rotuloRetencao(a) : t('cm.comprar')}</button></span>`}
    </div>`;
}

function pintarVitrineDiamantes() {
  const host = $('#cm-lista');
  if (!host) return;
  const f = estado.cmFiltro;
  const moedaId = f.moeda === 'orb' ? 'orb' : 'gold';
  const linhas = estado.cmDados?.linhas ?? [];
  const total = estado.cmDados?.total ?? linhas.length;

  const ofertas = linhas.length
    ? linhas.map(linhaVitrineDiamante).join('')
    : `<div class="cm-vazio">${t('cm.semDiamantes')}</div>`;

  host.classList.add('cm-lista-dia');
  // `.cmi-painel` de propósito: é a MESMA caixa do painel de ofertas do mercado de itens, com
  // o mesmo acabamento e o mesmo trilho animado na troca de moeda. `.cmd-painel` só a faz
  // ocupar a coluna inteira, já que aqui não há catálogo ao lado dela.
  host.innerHTML = `
    <div class="cmi-painel cmd-painel">
      <div class="cmp-cabeca">
        <span class="cmp-ico" data-ico="img:${ICONE_DIAMANTE}" data-ico-px="40"></span>
        <div class="cmp-tit">
          <b>${t('cm.diamantes')}</b>
          <i>${t('cm.diamanteOfertas', { n: num(total) })}</i>
        </div>
      </div>
      <div class="cmp-switch" data-moeda="${moedaId}">
        <button class="cmp-op ${moedaId === 'gold' ? 'on' : ''}" data-swmoeda="gold">
          <img src="${srcIcone(ICONE_OURO)}" alt="">${t('cm.emCoins')}
        </button>
        <button class="cmp-op ${moedaId === 'orb' ? 'on' : ''}" data-swmoeda="orb">
          <img src="${ICONE_GEMA}" alt="">${t('cm.emGemas')}
        </button>
        <span class="cmp-manopla"></span>
      </div>
      <p class="cmp-media">${htmlMediaDeVenda(estado.cmMediaDiamante, moedaId, { diamante: true })}</p>
      <div class="cmp-trilho ${moedaId === 'orb' ? 'dir' : ''}">
        <div class="cmp-vagao">${ofertas}</div>
      </div>
    </div>`;

  for (const el of host.querySelectorAll('[data-ico]')) pintarIcone(el);

  // A chave de moeda daqui é a MESMA de `htmlFiltroMoedaMercado` do lado de pokémon: as duas
  // escrevem em `cmFiltro.moeda` e repedem a lista. Muda o desenho, não o estado.
  for (const b of host.querySelectorAll('[data-swmoeda]')) {
    b.onclick = () => {
      if (f.moeda === b.dataset.swmoeda) return;
      f.moeda = b.dataset.swmoeda;
      estado.cmPagina = 0;
      pedirMercado();
      pintarVitrineDiamantes(); // pinta o switch já na posição nova; a lista chega em seguida
    };
  }

  for (const b of host.querySelectorAll('.cmv-comprar')) {
    b.onclick = () => {
      const a = linhas.find((x) => x.id === Number(b.dataset.anuncio));
      if (!a || anuncioEmRetencao(a)) return;
      abrirCompra(a);
    };
  }
  for (const b of host.querySelectorAll('.cmv-dm')) {
    b.onclick = () => {
      const a = linhas.find((x) => x.id === Number(b.dataset.dm));
      if (a) abrirDmDoAnuncio(a);
    };
  }
  // O próprio anúncio aparece na vitrine (é uma lista de preços, e esconder o seu tiraria a
  // referência de quem quer se posicionar), então o botão dele é o de cancelar.
  for (const b of host.querySelectorAll('[data-remover]')) {
    b.onclick = () => {
      const a = linhas.find((x) => x.id === Number(b.dataset.remover));
      if (!a) return;
      confirmarRemoverDiamantes(a);
    };
  }
}

function pintarMercado() {
  pintarVitrineDoMercado();
  // Depois da grade, nunca antes: a animação de entrada precisa do elemento com o conteúdo
  // novo já dentro. Só faz alguma coisa quando a pintura veio de uma troca de página.
  animarEntradaDaVitrine();
}

function pintarVitrineDoMercado() {
  const host = $('#cm-lista');
  if (!host) return;
  // As três vitrines vivem no MESMO `#cm-lista` e cada uma pede um `display` diferente da
  // grade de cards. Zerar as duas classes aqui, antes de qualquer desvio, é o que impede a
  // aba nova nascer com o layout da anterior quando a tela é repintada sem passar pelo
  // `abrirModal` (a resposta do servidor chegando, por exemplo).
  host.classList.toggle('cm-lista-itens', vitrineDeItens());
  host.classList.toggle('cm-lista-dia', vitrineDeDiamantes());

  if (vitrineDeItens()) {
    if (!atualizarVitrineItens()) pintarVitrineItens();
    return;
  }
  if (vitrineDeDiamantes()) {
    pintarVitrineDiamantes();
    pintarPaginas();
    return;
  }
  const dados = dadosDaGradeCerta();
  const meus = estado.cmAba === 'meus';
  const favoritos = estado.cmAba === 'favoritos';
  const especies = vitrineDeEspecies();
  host.innerHTML = '';

  // A ESPÉCIE ABERTA: a faixa de volta fica ACIMA da grade, e fora do `if` do vazio — "nenhum
  // anúncio de Dragonite com esses filtros" sem o caminho de volta seria um beco.
  if (estado.cmEspecieSel && estado.cmAba === 'vitrine' && estado.cmFiltro.tipo === 'pokemon') {
    host.appendChild(faixaDaEspecieAberta(dados));
  }

  // Acabou de trocar para os Favoritos: a lista ainda está a caminho, e a grade vazia diria
  // "nenhum favorito" a quem tem vinte.
  if (dados.carregando) {
    host.insertAdjacentHTML('beforeend', `<div class="cm-vazio">…</div>`);
    pintarPaginas();
    return;
  }

  // Os ITENS e as ESPÉCIES favoritas vêm antes dos anúncios: são poucos, não saem da lista quando
  // alguém vende, e são o atalho que o jogador mais usa — "quanto está o Boss Token hoje?".
  const itensFav = favoritos ? favoritosItensMercado().map(cardItemFavorito).filter(Boolean) : [];
  const especiesFav = favoritos ? favoritosEspeciesMercado().map(cardEspecieFavorita).filter(Boolean) : [];

  if (!dados.linhas?.length && !itensFav.length && !especiesFav.length) {
    const f = estado.cmFiltro;
    const msgVazio = favoritos
      ? 'cm.semFavoritos'
      : meus
      ? 'cm.semMeus'
      : f.tipo === 'diamante'
        ? 'cm.semDiamantes'
        // Com "Todas" ligada não há o que dizer sobre a moeda: a frase que sugere trocar de
        // moeda só ajuda quem está com uma escolhida.
        : f.tipo === 'pokemon' && f.moeda === MOEDA_TODAS
          ? 'cm.semPokemon'
          : f.tipo === 'pokemon' && f.moeda === 'orb'
            ? 'cm.semPokemonGema'
            : f.tipo === 'pokemon'
              ? 'cm.semPokemonCoin'
              : 'cm.semAnuncios';
    host.insertAdjacentHTML('beforeend', `<div class="cm-vazio">${t(msgVazio)}</div>`);
    pintarPaginas();
    return;
  }

  // A grade por ESPÉCIE: um card por espécie, e o clique abre as ofertas dela.
  if (especies) {
    for (const e of dados.linhas ?? []) host.appendChild(cardEspecieMercado(e));
    pintarPaginas();
    return;
  }

  if (favoritos) {
    // Com os três tipos na grade, cada um ganha um título: sem ele, o card de espécie e o de item
    // (que levam às ofertas) e o de anúncio (que compra) pareceriam a mesma coisa lado a lado.
    const titulo = (chave) => {
      const h = document.createElement('div');
      h.className = 'cm-fav-secao';
      h.textContent = t(chave);
      return h;
    };
    // O título só aparece quando há MAIS DE UM grupo na grade: com só espécies favoritas, um
    // "ESPÉCIES" sozinho em cima da grade inteira não separa nada de nada.
    const grupos = [especiesFav.length, itensFav.length, dados.linhas?.length].filter(Boolean).length;
    if (especiesFav.length && grupos > 1) host.appendChild(titulo('cm.favEspeciesTitulo'));
    for (const card of especiesFav) host.appendChild(card);
    if (itensFav.length && grupos > 1) host.appendChild(titulo('cm.favItensTitulo'));
    for (const card of itensFav) host.appendChild(card);
    if (dados.linhas?.length && grupos > 1) host.appendChild(titulo('cm.favAnunciosTitulo'));
    // O aviso de quem saiu: vendido ou retirado desde que o jogador favoritou. Os cards ficam na
    // grade, apagados, até ele limpar — ou até a poda do servidor, dias depois.
    const fechados = (dados.linhas ?? []).filter((a) => a.estado && a.estado !== 'aberto');
    if (fechados.length) {
      const aviso = document.createElement('div');
      aviso.className = 'cm-fav-aviso';
      aviso.innerHTML = `<span>${t(fechados.length === 1 ? 'cm.favSaiu' : 'cm.favSairam', { n: num(fechados.length) })}</span>
        <button type="button" class="cm-btn">${t('cm.favLimpar')}</button>`;
      aviso.querySelector('button').onclick = () => {
        for (const a of fechados) alternarFavoritoMercado(a, false);
      };
      host.appendChild(aviso);
    }
  }
  for (const a of dados.linhas ?? []) host.appendChild(cardAnuncio(a, meus));
  pintarPaginas();
}

/**
 * Card quadrado de pokémon — vitrine do Mercado, escolha ao anunciar e Market NPC.
 * Fileira P · IV · Q · Nota, tipos elementais, selo shiny e botão de ficha.
 */
function cardPokemonCm(pk, {
  selosExtra = '',
  duracaoHtml = '',
  rodapeHtml = '',
  atributosHtml = null,
  aoVerFicha = null,
  selecionavel = false,
  aoSelecionar = null,
} = {}) {
  const el = document.createElement('div');
  el.className = 'cm-card poke' + (pk.shiny ? ' shiny' : '') + (selecionavel ? ' cm-card-selecao' : '');

  const arte = document.createElement('div');
  arte.className = 'cm-arte';
  arte.appendChild(spritePokemon(pk, 64));
  const tmHtml = selosTm(pk);
  if (tmHtml || duracaoHtml) {
    const faixa = document.createElement('div');
    faixa.className = 'cm-arte-base';
    faixa.innerHTML = `${tmHtml ? `<span class="cm-tm">${tmHtml}</span>` : '<span></span>'}${duracaoHtml ?? ''}`;
    arte.appendChild(faixa);
  }

  const selos = [pk.shiny ? seloShiny() : '', selosExtra].filter(Boolean).join('');
  const atributos = atributosHtml ?? selosAtributos(pk);

  // O `+N` do refino entra AO LADO DO NOME, e não na fileira de atributos: ele é o que
  // distingue dois anúncios do mesmo bicho no mesmo nível, e a fileira P·IV·Q·N já está cheia.
  // O nome vai num `<span>` próprio para o corte por reticências pegar SÓ ele — um "Chandelure"
  // comendo o selo esconderia justamente o dado pelo qual o comprador está pagando a mais.
  //
  // A MEDALHA 🎖 entra na frente do `+N` pela mesma lógica, e ainda mais forte: ela não se
  // compra nem se farma — é a prova de que aquele indivíduo já foi o Pokémon da Guerra —, e
  // quem está varrendo a vitrine precisa vê-la sem abrir ficha nenhuma. Quantas, exatamente,
  // é a pergunta seguinte, e essa a ficha responde.
  el.innerHTML = `
    <div class="cm-arte-slot"></div>
    <div class="cm-selos">${selos}</div>
    <div class="cm-info">
      <div class="cm-nome" title="${escapar(nomeNoAnuncio(pk))}"><span class="cm-nome-txt">${escapar(nomeNoAnuncio(pk) || '—')}</span>${seloMedalhaGuerra(pk)}${seloTrofeus(pk)}${seloRefino(pk)}</div>
      <div class="cm-chips">${chipsDeTipo(tiposDaFicha(pk))}</div>
      <div class="cm-sub">${t('cm.nivel')} ${num(pk.level)}</div>
      ${atributos}
      ${aoVerFicha ? `<button class="cm-ficha" type="button">${t('cm.verFicha')}</button>` : ''}
    </div>
    ${rodapeHtml ? `<div class="cm-rodape">${rodapeHtml}</div>` : ''}
    <div class="cm-botoes"></div>`;
  el.querySelector('.cm-arte-slot').replaceWith(arte);

  if (aoVerFicha) {
    el.querySelector('.cm-ficha').onclick = (ev) => {
      ev.stopPropagation();
      aoVerFicha();
    };
  }

  if (selecionavel && aoSelecionar) {
    el.tabIndex = 0;
    el.setAttribute('role', 'button');
    const escolher = (ev) => {
      if (ev.target.closest('.cm-ficha, .mk-ficha-btn')) return;
      aoSelecionar(ev);
    };
    el.addEventListener('click', escolher);
    el.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        escolher(ev);
      }
    });
  }

  return el;
}

/**
 * Tirar um anúncio do Mercado: a mercadoria faz a viagem de volta — ela à esquerda, a seta, e o
 * inventário do outro lado. Uma caixa só para pokémon e item (eram duas cópias da mesma frase).
 *
 * O nome é ESCAPADO: desde a Name Tag ele pode ser texto de outro jogador (o apelido viaja com o
 * anúncio). `validarApelido` já barra `<`, `>`, `&` e as aspas — o escape é o que impede que
 * afrouxar aquele alfabeto um dia abra um buraco aqui, em silêncio.
 */
function confirmarRemoverAnuncio(a) {
  const pokemon = a.tipo === 'pokemon';
  const nome = pokemon ? nomeNoAnuncio(a.ficha) : nomeAnuncioItem(a);
  const destino = pokemon
    ? `<span data-dlg-arquivo="${SPRITE_BOLA[1]}" data-dlg-px="36"></span>`
    : `<span data-dlg-arquivo="${ICONE_ITEM_GENERICO}" data-dlg-px="36"></span>`;
  confirmar({
    titulo: t('cm.removerTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({
          arte: pokemon ? dlgArtePk(a.ficha, 64) : '<span class="dlg-ator-fig" data-dlg-anuncio></span>',
          nome: escapar(nome || '—'),
          sub: pokemon ? dlgSeloShiny(a.ficha?.shiny) + dlgNivel(a.ficha?.level ?? 1) : '',
          qtd: !pokemon && a.qtd > 1 ? `×${num(a.qtd)}` : '',
        })}
        ${dlgSeta()}
        ${dlgAtor({
          arte: dlgArteHtml(dlgMedalha({ arte: destino, tom: 'verde' })),
          nome: escapar(t('cm.removerDestino')),
          classe: 'novo',
        })}`, 'verde')}
      ${dlgFrase('', t('cm.removerTexto', { nome: escapar(nome || '—') }))}`,
    aoConfirmar: () => enviar({ t: 'market.cancelar', id: a.id }),
    // A arte do item é a mesma do card (casa, bicicleta e caixa têm desenho próprio) — e ela é
    // um NÓ, por isso entra depois do template.
    montar: pokemon ? null : (corpo) => penduraArteDoAnuncio(corpo, a),
  });
}

/**
 * Tirar um anúncio de DIAMANTES: o que volta é saldo, então a etiqueta é a de quem RECEBE — o
 * número sobe em verde. Numa compra parcial volta só o que sobrou; `a.qtd` já é isso.
 */
function confirmarRemoverDiamantes(a) {
  confirmar({
    titulo: t('cm.removerTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArteArquivo(ICONE_DIAMANTE, 64),
        nome: `${num(a.qtd)} ${escapar(t('moeda.diamantes'))}`,
        classe: 'novo',
        marca: dlgIcone('volta', 14),
      }), 'azul')}
      ${dlgCusto({ moeda: 'diamante', valor: a.qtd, saldo: Number(estado.eu?.diamonds ?? 0), ganha: true, rotulo: t('cm.removerVolta') })}
      ${dlgFrase('', t('cm.removerDiamanteTexto', { n: num(a.qtd) }))}`,
    aoConfirmar: () => enviar({ t: 'market.cancelar', id: a.id }),
  });
}

/**
 * Comprar o pokémon de outro jogador (a vitrine, os Shinys e os P5 do servidor). O bicho no palco
 * dourado com os selos que o card mostrava, a etiqueta na moeda do anúncio com o saldo que fica,
 * e de quem se compra. Nome e vendedor são texto de outra pessoa — vão escapados.
 */
function confirmarCompraAnuncio({ pk, nome, preco, moeda, vendedor = null, aoConfirmar }) {
  const gema = moeda === 'orb';
  const pot = Number(pk?.potencia) || 0;
  confirmar({
    titulo: t('cm.comprarTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({
        arte: dlgArtePk(pk, 72),
        nome: escapar(nome || '—'),
        sub: dlgSeloShiny(pk?.shiny) + dlgNivel(pk?.level ?? 1) + (pot >= 2 ? ` ${seloPotencia(pot)}` : ''),
        classe: 'novo',
      }), 'ouro')}
      ${dlgCusto({
        moeda: gema ? 'gema' : 'ouro',
        valor: preco,
        saldo: Math.floor(gema ? estado.eu?.orbs ?? 0 : estado.eu?.gold ?? 0),
        rotulo: t('cm.precoDoPokemon'),
      })}
      ${vendedor ? dlgFrase('', t('cm.comprarDe', { nick: `<b>${escapar(vendedor)}</b>` })) : ''}`,
    rotuloSim: t('cm.comprar'),
    aoConfirmar,
  });
}

/**
 * O card de um anúncio de DIAMANTES.
 *
 * ### Por que ele é o único card com preço em dois tamanhos
 *
 * Pokémon e item se compram por peça: o preço do card É o que vai sair da carteira. Diamante
 * se compra por LOTE, e o que se compara entre dois anúncios é o preço da UNIDADE — 900 Coins
 * por diamante contra 850. Só que o número que decide se dá para comprar é o TOTAL, e quem lê
 * "900 Coins" num lote de 500 e tem 1.000 no bolso acha que pode.
 *
 * Então saem os dois, com hierarquia: a unidade grande (é o que se compara) e o total logo
 * abaixo, miúdo (é o que se paga). É a mesma leitura de uma prateleira de supermercado, e pelo
 * mesmo motivo.
 */
function cardAnuncioDiamante(a, meus) {
  const el = document.createElement('div');
  el.className = 'cm-card cm-card-dia';

  const total = a.preco * a.qtd;
  el.innerHTML = `
    <div class="cm-arte cm-dia-arte"><span class="cm-dia-qtd">${num(a.qtd)}</span></div>
    <div class="cm-selos">${
      anuncioEmRetencao(a) ? `<span class="cm-retencao"${attrRetencao(a)}>${rotuloRetencao(a)}</span>` : ''
    }</div>
    <div class="cm-info">
      <div class="cm-nome">${t('cm.diamanteLote', { n: num(a.qtd) })}</div>
      <div class="cm-sub">${t('cm.emEstoque', { n: num(a.qtd) })}</div>
    </div>
    <div class="cm-rodape">
      ${precoComMoeda(a.preco, a.moeda, { curto: true })}
      <div class="cm-unit">${t('cm.porDiamante')}</div>
      <div class="cm-dia-total"><span>${t('cm.loteTotal')}</span>${precoComMoeda(total, a.moeda, { curto: true })}</div>
      <div class="cm-vend">${meus ? t('cm.seuAnuncio') : `${t('cm.de')} <b>${escapar(a.vendedor)}</b>`}</div>
    </div>
    <div class="cm-botoes"></div>`;
  el.querySelector('.cm-dia-arte').prepend(iconeArquivo(ICONE_DIAMANTE, 46));

  const botoes = el.querySelector('.cm-botoes');
  if (meus) {
    el.classList.add('tem-fav');
    el.appendChild(botaoAltoFalante(a));
    const ed = document.createElement('button');
    ed.className = 'cm-btn';
    ed.textContent = t('cm.editar');
    ed.onclick = () => abrirEdicao(a);
    // Na retenção nasce escondido; o contador mostra quando libera (`atualizarContadoresRetencao`).
    if (anuncioEmRetencao(a)) {
      ed.style.display = 'none';
      ed.dataset.mostrarAte = String(Number(a.compravelEm));
    }
    botoes.appendChild(ed);
    const rm = document.createElement('button');
    rm.className = 'cm-btn perigo';
    rm.textContent = t('cm.remover');
    // Cancelar devolve o que SOBROU: numa compra parcial o comprador já levou a fatia dele.
    rm.onclick = () => confirmarRemoverDiamantes(a);
    botoes.appendChild(rm);
  } else {
    const bt = document.createElement('button');
    bt.className = 'cm-btn comprar';
    bt.textContent = t('cm.comprar');
    // A mesma folha de compra do item: diamante é lote e compra parcial faz todo o sentido —
    // ninguém tem Coin para os 5.000 de uma vez, e obrigar a levar tudo seria o mesmo que não
    // ter a aba.
    aplicarRetencaoCompra(bt, a, () => abrirCompra(a));
    botoes.appendChild(bt);
    if (!ehMeuAnuncio(a)) el.appendChild(linhaDmDoCard(a));
  }
  return el;
}

function cardAnuncio(a, meus) {
  if (a.tipo === 'diamante') return cardAnuncioDiamante(a, meus);
  const ehPoke = a.tipo === 'pokemon';
  if (ehPoke) {
    const el = cardPokemonCm(
      a.ficha,
      {
        selosExtra: anuncioEmRetencao(a) ? `<span class="cm-retencao"${attrRetencao(a)}>${rotuloRetencao(a)}</span>` : '',
        duracaoHtml: duracaoSelo(a),
        atributosHtml: selosAtributos({ ...a.ficha, nota: notaDoFicha(a.ficha) }),
        rodapeHtml: `${precoComMoeda(a.preco, a.moeda, { curto: true })}<div class="cm-vend">${meus ? t('cm.seuAnuncio') : `${t('cm.de')} <b>${escapar(a.vendedor)}</b>`}</div>`,
        aoVerFicha: () => abrirFichaDoPokemon({ ...a.ficha, id: a.ficha.id ?? a.pokemonId }),
      },
    );
    const botoes = el.querySelector('.cm-botoes');
    // A ESTRELA dos Favoritos: em todo anúncio de pokémon que não é do próprio jogador.
    if (!meus && !ehMeuAnuncio(a)) {
      el.classList.add('tem-fav');
      el.appendChild(botaoFavoritoMercado(a));
    }
    // QUANTOS FAVORITARAM, colado à estrela (ou ao alto-falante, no anúncio do próprio jogador —
    // para ele é o termômetro do interesse). Só no anúncio aberto e quando o servidor contou.
    if (a.favoritos != null && (!a.estado || a.estado === 'aberto')) {
      el.classList.add('tem-fav-n');
      el.appendChild(seloFavoritosAnuncio(a, { doVendedor: meus || ehMeuAnuncio(a) }));
    }
    // Favorito que saiu do Mercado: o card fica, apagado e com o selo do que aconteceu, e o único
    // botão é tirá-lo da lista. Não há o que comprar.
    if (a.estado && a.estado !== 'aberto') {
      el.classList.add('cm-fechado');
      el.querySelector('.cm-selos')?.insertAdjacentHTML('afterbegin',
        `<span class="cm-fechado-selo">${t(a.estado === 'vendido' ? 'cm.favVendido' : 'cm.favIndisponivel')}</span>`);
      const rm = document.createElement('button');
      rm.className = 'cm-btn';
      rm.textContent = t('cm.favRemover');
      rm.onclick = () => alternarFavoritoMercado(a, false);
      botoes.appendChild(rm);
      return el;
    }
    if (meus) {
      // O ALTO-FALANTE no canto em que os cards dos outros têm a estrela.
      el.classList.add('tem-fav');
      el.appendChild(botaoAltoFalante(a));
      const ed = document.createElement('button');
      ed.className = 'cm-btn';
      ed.textContent = t('cm.editar');
      ed.onclick = () => abrirEdicao(a);
      // Na retenção nasce escondido; o contador mostra quando libera (`atualizarContadoresRetencao`).
      if (anuncioEmRetencao(a)) {
        ed.style.display = 'none';
        ed.dataset.mostrarAte = String(Number(a.compravelEm));
      }
      botoes.appendChild(ed);
      const rm = document.createElement('button');
      rm.className = 'cm-btn perigo';
      rm.textContent = t('cm.remover');
      rm.onclick = () => confirmarRemoverAnuncio(a);
      botoes.appendChild(rm);
    } else {
      const bt = document.createElement('button');
      bt.className = 'cm-btn comprar';
      bt.textContent = t('cm.comprar');
      aplicarRetencaoCompra(bt, a, () => confirmarCompraAnuncio({
        pk: a.ficha,
        nome: nomeNoAnuncio(a.ficha),
        preco: a.preco * a.qtd,
        moeda: a.moeda,
        vendedor: a.vendedor,
        aoConfirmar: () => enviar({ t: 'market.comprar', id: a.id, qtd: a.qtd, preco: a.preco, moeda: a.moeda }),
      }));
      botoes.appendChild(bt);
      // O "Enviar DM", embaixo do Comprar — a conversa com o vendedor sobre ESTE pokémon.
      if (!ehMeuAnuncio(a)) el.appendChild(linhaDmDoCard(a));
    }
    return el;
  }

  const el = document.createElement('div');
  el.className = 'cm-card' + (a.ficha.shiny ? ' shiny' : '');

  const arte = document.createElement('div');
  arte.className = 'cm-arte';
  arte.appendChild(arteItemAnuncio(a, 52));
  const duracao = duracaoSelo(a);
  if (duracao) {
    const faixa = document.createElement('div');
    faixa.className = 'cm-arte-base';
    faixa.innerHTML = `<span></span>${duracao}`;
    arte.appendChild(faixa);
  }

  const selos = [
    a.ficha.shiny ? seloShiny() : '',
    anuncioEmRetencao(a) ? `<span class="cm-retencao"${attrRetencao(a)}>${rotuloRetencao(a)}</span>` : '',
    // Numa caixa, o SELO carrega o número — não a quantidade (que é sempre 1). Fora do
    // nome de propósito: `.cm-nome` corta com reticências num card estreito, e "Caixa de
    // CoFundador #…" esconde justamente o que distingue este anúncio do de baixo.
    numeroDoAnuncio(a)
      ? plaquinhaDoAnuncio(a, 'cm-qtd cmv-serie')
      : a.qtd > 1 ? `<span class="cm-qtd">${num(a.qtd)}×</span>` : '',
  ].join('');

  const tipos = [a.ficha.tipo ?? estado.itensTipos[a.itemId]];
  const npc = a.ficha.npc ? `<em class="cm-npc">${t('cm.npcPaga', { v: num(a.ficha.npc) })}</em>` : '';
  const sub = `${a.qtd > 1 ? `${t('cm.emEstoque', { n: num(a.qtd) })} · ` : ''}${npc}`;

  el.innerHTML = `
    <div class="cm-arte-slot"></div>
    <div class="cm-selos">${selos}</div>
    <div class="cm-info">
      <div class="cm-nome" title="${escapar(nomeAnuncioItem(a))}">${escapar(nomeAnuncioItem(a) || '—')}</div>
      <div class="cm-chips">${chipsDeTipo(tipos)}</div>
      <div class="cm-sub">${sub}</div>
    </div>
    <div class="cm-rodape">
      ${precoComMoeda(a.preco, a.moeda, { curto: true })}
      ${a.qtd > 1 ? `<div class="cm-unit">${t('cm.porUnidade')}</div>` : ''}
      <div class="cm-vend">${meus ? t('cm.seuAnuncio') : `${t('cm.de')} <b>${escapar(a.vendedor)}</b>`}</div>
    </div>
    <div class="cm-botoes"></div>`;
  el.querySelector('.cm-arte-slot').replaceWith(arte);

  const botoes = el.querySelector('.cm-botoes');
  if (meus) {
    el.classList.add('tem-fav');
    el.appendChild(botaoAltoFalante(a));
    const ed = document.createElement('button');
    ed.className = 'cm-btn';
    ed.textContent = t('cm.editar');
    ed.onclick = () => abrirEdicao(a);
    // Na retenção nasce escondido; o contador mostra quando libera (`atualizarContadoresRetencao`).
    if (anuncioEmRetencao(a)) {
      ed.style.display = 'none';
      ed.dataset.mostrarAte = String(Number(a.compravelEm));
    }
    botoes.appendChild(ed);
    const rm = document.createElement('button');
    rm.className = 'cm-btn perigo';
    rm.textContent = t('cm.remover');
    rm.onclick = () => confirmarRemoverAnuncio(a);
    botoes.appendChild(rm);
  } else {
    const bt = document.createElement('button');
    bt.className = 'cm-btn comprar';
    bt.textContent = t('cm.comprar');
    aplicarRetencaoCompra(bt, a, () => abrirCompra(a));
    botoes.appendChild(bt);
    if (!ehMeuAnuncio(a)) el.appendChild(linhaDmDoCard(a));
  }
  return el;
}

// ------------------------------------------------------ seletor de quantidade
//
// Barrinha que arrasta + o número exato ao lado, sempre os dois em sincronia. Vale para
// vender ("quantos deste lote eu ponho à venda") e para comprar ("quantos deste lote eu
// levo"), que são a mesma pergunta vista dos dois lados do balcão.
//
// A barra sozinha não serve: em um lote de 500, cada pixel vale 3 unidades e não há como
// parar em 200 exatos. O campo sozinho também não: para levar "mais ou menos metade" ninguém
// quer digitar. Os dois juntos cobrem a intenção grossa e a fina.

/**
 * Monta o seletor dentro de `host`.
 *
 * `aoMudar(n)` roda a cada mexida, já com o valor saneado. Devolve `{ ler, pôr }` para quem
 * precisar do número depois (o botão de publicar/comprar) ou quiser mexer de fora.
 */
function seletorQuantidade(host, { max, inicial = 1, rotulo, aoMudar }) {
  const limite = Math.max(1, Math.floor(max));
  host.innerHTML = `
    <label class="qtd-bloco">
      <span class="qtd-topo">${rotulo}<em id="qtd-max">${t('cm.ateN', { n: num(limite) })}</em></span>
      <span class="qtd-linha">
        <input type="range" class="qtd-barra" id="qtd-barra" min="1" max="${limite}" value="${inicial}" step="1">
        <input type="number" class="qtd-num" id="qtd-num" min="1" max="${limite}" value="${inicial}" inputmode="numeric">
      </span>
      <span class="qtd-atalhos">
        <button type="button" class="qtd-atalho" data-frac="0.25">25%</button>
        <button type="button" class="qtd-atalho" data-frac="0.5">50%</button>
        <button type="button" class="qtd-atalho" data-frac="1">${t('cm.tudo')}</button>
      </span>
    </label>`;

  const barra = host.querySelector('#qtd-barra');
  const campo = host.querySelector('#qtd-num');
  let valor = Math.min(limite, Math.max(1, inicial));

  const aplicar = (n, focoNoCampo) => {
    valor = Math.min(limite, Math.max(1, Math.floor(n) || 1));
    barra.value = valor;
    // Enquanto a pessoa DIGITA, não sobrescrevemos o campo: apagar tudo para escrever "20"
    // passa por vazio, e reescrever "1" ali faria o cursor pular e travar a digitação.
    if (!focoNoCampo) campo.value = valor;
    aoMudar?.(valor);
  };

  barra.oninput = () => aplicar(Number(barra.value), false);
  campo.oninput = () => aplicar(Number(campo.value), true);
  // Ao sair do campo o valor é normalizado: quem deixou vazio ou digitou 999 num lote de 10
  // vê o número virar o que de fato vai ser cobrado.
  campo.onblur = () => aplicar(Number(campo.value), false);
  host.querySelector('.qtd-atalhos').onclick = (ev) => {
    const b = ev.target.closest('.qtd-atalho');
    if (b) aplicar(Math.round(limite * Number(b.dataset.frac)), false);
  };

  aoMudar?.(valor);
  return { ler: () => valor, pôr: (n) => aplicar(n, false) };
}

// ------------------------------------------------- anunciar, em três passos
//
// Item ou pokémon → qual → por quanto. Em passos, e não num formulário só, porque o
// segundo passo é uma GRADE do inventário: espremê-la ao lado dos campos de preço daria
// uma coluna de 80 px para escolher entre trinta itens.

/** Quanto a roda pediu, em pixels — o Firefox manda em LINHAS (`deltaMode` 1), e há o modo página. */
const pixelsDaRoda = (ev, alvo) =>
  ev.deltaMode === 1 ? ev.deltaY * 16 : ev.deltaMode === 2 ? ev.deltaY * alvo.clientHeight : ev.deltaY;

/**
 * O primeiro elemento com rolagem, do cursor para fora até `limite` (inclusive), que ainda
 * consegue andar no sentido da roda. `null` = nenhum.
 */
function rolavelSobOCursor(inicio, limite, sentido) {
  for (let el = inicio; el; el = el.parentElement) {
    if (el.scrollHeight > el.clientHeight + 1) {
      const oy = getComputedStyle(el).overflowY;
      if (oy === 'auto' || oy === 'scroll') {
        const desce = el.scrollTop + el.clientHeight < el.scrollHeight - 1;
        const sobe = el.scrollTop > 0;
        if ((sentido > 0 && desce) || (sentido < 0 && sobe)) return el;
      }
    }
    if (el === limite) break;
  }
  return null;
}

/** A folha que cobre o modal. Some no Esc, no clique fora e ao publicar. */
function folhaMercado(titulo) {
  document.querySelector('.cm-folha')?.remove();
  const f = document.createElement('div');
  f.className = 'cm-folha';
  f.innerHTML = `
    <div class="cm-folha-caixa">
      <div class="cm-folha-topo"><b>${titulo}</b><button class="cm-fechar" type="button">×</button></div>
      <div class="cm-folha-corpo"></div>
    </div>`;
  const fechar = () => f.remove();
  f.querySelector('.cm-fechar').onclick = fechar;
  f.onclick = (ev) => { if (ev.target === f) fechar(); };
  // No palco a roda do mouse dá zoom na cena — capturar aqui e rolar o alvo certo.
  //
  // O alvo é o que está DEBAIXO DO CURSOR: há folhas com duas rolagens, uma dentro da outra (o
  // passo "qual pokémon?" do anúncio: o corpo rola, e a grade dos pokémon também), e rolar
  // sempre o de fora deixava a lista de dentro morta com o mouse em cima dela. Como no
  // navegador, quando o de dentro chega ao fim a roda passa para o de fora.
  f.addEventListener(
    'wheel',
    (ev) => {
      const corpo = f.querySelector('.cm-folha-corpo');
      if (!corpo) return;
      ev.preventDefault();
      ev.stopPropagation();
      const sob = corpo.contains(ev.target) ? rolavelSobOCursor(ev.target, corpo, ev.deltaY) : null;
      if (sob) {
        sob.scrollTop += pixelsDaRoda(ev, sob);
        return;
      }
      // Fora de qualquer rolagem (o topo, os filtros): `.cm-rolagem` é a saída para as folhas em
      // que o corpo NÃO rola (ele é uma coluna flex com `overflow: hidden`) e quem rola é um
      // filho — a grade do anexo de pokémon. Sem isto a roda do mouse ficaria morta ali.
      const lista = corpo.querySelector('.cm-hist-lista') ?? corpo.querySelector('.cm-rolagem');
      const alvo = lista ?? corpo;
      if (alvo.scrollHeight > alvo.clientHeight) alvo.scrollTop += pixelsDaRoda(ev, alvo);
    },
    { passive: false },
  );
  // No modal quando ele está aberto; no palco quando a escolha vem de dentro de casa (XP Share).
  const ancorar = (estado.modalAberto ? $('#modal .modal-caixa') : null) ?? $('#palco');
  ancorar?.appendChild(f);
  return { folha: f, corpo: f.querySelector('.cm-folha-corpo'), fechar };
}

/**
 * A SETA DE "TEM MAIS COISA AQUI EMBAIXO".
 *
 * Uma folha que rola corta o último item no meio, e um corte reto no pé do quadro não parece
 * rolagem: parece defeito. Isto põe no pé um afogamento (o conteúdo some no fundo em vez de ser
 * decepado) e uma seta que pula — e que leva para baixo quando clicada.
 *
 * Ela só existe enquanto sobra o que ver: quando a pessoa chega ao fim, some. Seta parada num
 * canto que já acabou é ruído, e ensina a ignorar a próxima.
 *
 * Devolve o `medir`, para quem muda o conteúdo DEPOIS (a abertura da caixa, que revela os
 * prêmios 750 ms mais tarde) poder refazer a conta na hora certa.
 */
function setaDeRolagem(corpo) {
  const caixa = corpo.closest('.cm-folha-caixa') ?? corpo.parentElement;
  if (!caixa) return () => {};
  corpo.classList.add('cm-rolo');

  const seta = document.createElement('div');
  seta.className = 'cm-mais';
  seta.setAttribute('aria-hidden', 'true');
  seta.innerHTML = '<button type="button" class="cm-mais-bt" tabindex="-1">▾</button>';
  seta.querySelector('.cm-mais-bt').onclick = () => {
    corpo.scrollBy({ top: Math.round(corpo.clientHeight * 0.8), behavior: 'smooth' });
  };
  caixa.appendChild(seta);

  // 12 px de folga: meia linha de sobra é arredondamento de layout, não conteúdo escondido.
  const medir = () => {
    const sobra = corpo.scrollHeight - corpo.scrollTop - corpo.clientHeight;
    caixa.classList.toggle('tem-mais', sobra > 12);
  };
  corpo.addEventListener('scroll', medir, { passive: true });
  // Os sprites chegam depois do HTML e mudam a altura: o observer refaz a conta sozinho, em vez
  // de um `setTimeout` chutado que erra nos aparelhos lentos.
  if (window.ResizeObserver) {
    const ro = new ResizeObserver(medir);
    ro.observe(corpo);
    for (const filho of corpo.children) ro.observe(filho);
  }
  requestAnimationFrame(medir);
  return medir;
}

/**
 * Os dois botões de moeda do anúncio, com o ícone de cada uma.
 *
 * Mesmo desenho do filtro da vitrine (`htmlFiltroMoedaMercado`) — e o mesmo par de tamanhos:
 * a gema sai um pouco maior que a moeda de ouro porque a arte dela tem mais respiro em volta,
 * e no mesmo `px` pesaria menos na tela.
 *
 * Anunciar e EDITAR usam o mesmo helper de propósito: são o mesmo par de botões, e quando um
 * ganha um ícone o outro tem de ganhar junto.
 */
const htmlMoedasAnuncio = (moeda = 'gold') => `
    <div class="cm-moedas cm-moedas-anuncio">
      <button type="button" class="cm-moeda${moeda !== 'orb' ? ' on' : ''}" data-moeda="gold">
        ${seloOuro(18)}${t('cm.emCoins')}
      </button>
      <button type="button" class="cm-moeda${moeda === 'orb' ? ' on' : ''}" data-moeda="orb">
        ${seloGema(20)}${t('cm.emGemas')}
      </button>
    </div>`;

function abrirAnuncio(tipoInicial = null) {
  const { corpo, fechar } = folhaMercado(t('cm.anunciarTitulo'));
  // A folha pode nascer já no passo certo — é o que o botão "vender diamantes" da barra
  // lateral da aba de Diamantes usa, para não cobrar um clique num menu de três opções em que
  // o jogador acabou de dizer qual das três quer.
  if (tipoInicial === 'diamante') return passoEscolherDiamantes(corpo, fechar);

  corpo.innerHTML = `
    <p class="cm-passo-txt">${t('cm.oQueAnunciar')}</p>
    <div class="cm-escolha">
      <button class="cm-grande" data-tipo="item"><span>${t('cm.umItem')}</span></button>
      <button class="cm-grande" data-tipo="pokemon"><span>${t('cm.umPokemon')}</span></button>
      <button class="cm-grande" data-tipo="diamante"><span>${t('cm.diamantes')}</span></button>
    </div>`;
  // Os ícones do jogo, não emoji: a bolsa do menu, a pokébola e o diamante do HUD. Eram 🧪 e
  // 🔴, que além de não dizerem "item" nem "pokémon" são desenhados pela fonte do sistema — ou
  // seja, mudam de cara em cada máquina, e nenhuma delas é a nossa.
  corpo.querySelector('[data-tipo="item"]').prepend(iconeArquivo(ICONE_ITEM_GENERICO, 38));
  corpo.querySelector('[data-tipo="pokemon"]').prepend(iconeBola(1, 38));
  corpo.querySelector('[data-tipo="diamante"]').prepend(iconeArquivo(ICONE_DIAMANTE, 38));

  corpo.onclick = (ev) => {
    const b = ev.target.closest('[data-tipo]');
    if (!b) return;
    if (b.dataset.tipo === 'item') passoEscolherItem(corpo, fechar);
    else if (b.dataset.tipo === 'diamante') passoEscolherDiamantes(corpo, fechar);
    else passoEscolherPokemon(corpo, fechar);
  };
}

/**
 * O passo de DIAMANTES: quantos, dos que podem ser vendidos.
 *
 * ### Por que este passo existe e o de item não precisa de um igual
 *
 * Escolher um item é escolher um ícone numa grade: o jogador vê o que tem e clica. Aqui não há
 * o que escolher — diamante é um só —, mas há uma REGRA que ele não tem como adivinhar
 * olhando o saldo: **só o que foi comprado (ou veio de indicação) pode ser vendido.** Quem
 * tem 300 no HUD e 40 vendáveis precisa ver os dois números e a razão da diferença ANTES de
 * digitar preço, e não depois de levar um "não" do servidor.
 *
 * Por isso a tela quebra a cota em parcelas — comprados, indicação, já em anúncio — em vez de
 * mostrar só o total: "você pode vender 40" sozinho lê como bug para quem tem 300.
 *
 * ### O número vem do servidor, e é uma sugestão
 *
 * A cota é um `SUM` sobre o ledger e chega por `market.diamantes.cota`. Como todo filtro do
 * cliente, ela existe para dizer "não" antes do clique — quem decide é `criarAnuncio`, que
 * relê a mesma cota dentro da transação, com o lock do vendedor na mão. Um cliente adulterado
 * mandando 10.000 esbarra lá.
 */
function passoEscolherDiamantes(corpo, fechar) {
  corpo.onclick = null;
  corpo.innerHTML = `<p class="cm-passo-txt">${t('cm.diamanteCarregando')}</p>`;
  // Guardado no estado para a resposta saber que ainda é esta folha que está na tela — uma
  // cota que chega depois de o jogador ter fechado (ou voltado ao passo 1) não pode redesenhar
  // por cima do que ele está fazendo agora.
  cmCotaDiamantes = (cota) => {
    if (!corpo.isConnected) return;
    pintarPassoDiamantes(corpo, fechar, cota);
  };
  enviar({ t: 'market.diamantes.cota' });
}

/** Quem redesenha o passo quando a cota chega. `null` quando a folha não está mais aberta. */
let cmCotaDiamantes = null;

function pintarPassoDiamantes(corpo, fechar, cota) {
  const vendavel = Math.max(0, Math.floor(Number(cota?.vendavel) || 0));
  const saldo = Math.max(0, Math.floor(Number(cota?.saldo) || 0));

  // A decomposição (os selos de baixo da barra) só mostra a parcela que existe: para quem comprou
  // e não ganhou nada de indicação nem tem anúncio aberto, ela repetiria o mesmo número. O BRINDE,
  // quando há, é o que explica por que o vendável é menor que a carteira — sem ele o jogador lê
  // "você tem 4, pode vender 1" e conclui que a tela está quebrada (foi exatamente o relato).
  //
  // A regra é a única coisa desta tela que o jogador não descobriria sozinho, e é a que produz o
  // "por que só 40?". Ela vinha em dois parágrafos; agora é uma linha por ORIGEM do diamante, com
  // a marca de "vende" ou "não vende" — o olho acha a dele sem ler as outras. A cota vira uma
  // barra: quanto do saldo pode ir ao Mercado, e as parcelas como selos logo embaixo.
  const pct = saldo ? Math.max(0, Math.min(100, (vendavel / saldo) * 100)) : 0;
  corpo.innerHTML = `
    <div class="dlg-cota${vendavel ? '' : ' vazia'}">
      <span class="dlg-cota-arte">${dlgArteArquivo(ICONE_DIAMANTE, 48)}</span>
      <span class="dlg-cota-rot">${t('cm.diamanteVendaveis')}</span>
      <b class="dlg-cota-num">${num(vendavel)}</b>
      <span class="dlg-cota-barra" title="${escapar(t('cm.diamanteDeSaldo', { v: num(vendavel), s: num(saldo) }))}"><i style="width:${pct.toFixed(1)}%"></i></span>
      <span class="dlg-cota-legenda">${escapar(t('cm.diamanteDeSaldo', { v: num(vendavel), s: num(saldo) }))}</span>
    </div>
    ${dlgSelos(
      cota?.deCompra > 0 ? dlgSelo('moedas', escapar(t('cm.diamanteDeCompra', { n: num(cota.deCompra) })), 'bom') : '',
      cota?.deAfiliado > 0 ? dlgSelo('pessoaMais', escapar(t('cm.diamanteDeAfiliado', { n: num(cota.deAfiliado) })), 'bom') : '',
      cota?.emAnuncios > 0 ? dlgSelo('megafone', escapar(t('cm.diamanteEmAnuncios', { n: num(cota.emAnuncios) })), 'info') : '',
      cota?.brindes > 0 ? dlgSelo('xis', escapar(t('cm.diamanteBrindesCurto', { n: num(cota.brindes) })), 'perigo') : '',
    )}
    ${dlgLista([
      { icone: 'check', html: t('cm.diaRegraCompra') },
      { icone: 'check', html: t('cm.diaRegraIndicacao') },
      { icone: 'xis', html: t('cm.diaRegraBrinde'), perigo: true },
      { icone: 'volta', html: t('cm.diaRegraUmaVolta') },
    ])}
    ${vendavel
      ? `<div class="cm-form">
           <div id="cm-qtd-host"></div>
           <button class="cm-publicar" id="cm-dia-seguir">${t('cm.diamanteSeguir')}</button>
         </div>`
      : `${dlgAviso(t('cm.diamanteSemCota'), { tom: 'ouro' })}
         <button class="cm-publicar" id="cm-dia-comprar">${t('diamantes.comprar')}</button>`}`;
  hidratarDialogo(corpo);

  if (!vendavel) {
    // Sem cota o caminho não é um botão morto: é a porta de comprar diamante, que é o que ele
    // precisaria fazer para ter o que vender.
    corpo.querySelector('#cm-dia-comprar').onclick = () => {
      fechar();
      abrirCompraDeDiamantes();
    };
    return;
  }

  const seletor = seletorQuantidade(corpo.querySelector('#cm-qtd-host'), {
    max: vendavel,
    inicial: vendavel,
    rotulo: t('cm.diamanteQuantos'),
  });

  corpo.querySelector('#cm-dia-seguir').onclick = () => {
    cmCotaDiamantes = null;
    const qtd = seletor.ler();
    passoPreco(corpo, fechar, {
      tipo: 'diamante',
      nome: t('cm.diamanteLote', { n: num(qtd) }),
      // `maximo: 1` de propósito: a quantidade JÁ foi escolhida aqui, contra a cota. Deixar o
      // `passoPreco` montar um segundo seletor (agora sem a cota em mãos, porque ele não a
      // conhece) permitiria voltar a subir o número para além do que pode ser vendido.
      maximo: 1,
      qtdFixa: qtd,
      npc: 0,
    });
  };
}

/**
 * Espelho da curadoria do servidor (`ITENS_MERCADO`, em content.mjs): só pedra que evolui,
 * disco de TM e ficha de boss.
 *
 * Está repetida aqui de propósito. Quem decide continua sendo o servidor — mas deixar a
 * tela oferecer um Bug Wing, o jogador escolher a quantidade, digitar o preço e só então
 * levar um "não pode" é gastar quatro cliques da pessoa para dizer não. A lista vem pronta
 * no welcome, então os dois lados leem a MESMA fonte e não têm como divergir.
 */
const anunciavelNaTela = (item) => {
  if (!item) return false;
  // id 5 = Band Aid no inventário (o mesmo id da Beast Ball, que saiu da vitrine em 30/09/2026).
  if (item.id === BEAST_BALL_ID && item.category === 'loot') return false;
  return catalogoMercado().some((i) => i.id === item.id);
};

/**
 * Espelho da faixa mínima de pokémon (`motivoNaoAnunciavel`, em sim.mjs).
 *
 * Sem ele o filtro FALHAVA ABERTO: quando o welcome ainda não trouxera `mercado` (cliente
 * novo contra servidor antigo, que é o estado normal logo depois de um deploy), `min` vinha
 * indefinido e a função devolvia "pode" para todo mundo — foi assim que um Nv 3 · IV 100
 * apareceu na lista. Regra que não carregou tem de barrar, não liberar.
 */
const MERCADO_PK_MIN_PADRAO = MERCADO_POKEMON_MIN;
const faixaMinimaPk = () => estado.mercado?.pokemonMin ?? MERCADO_PK_MIN_PADRAO;

/**
 * `null` = pode anunciar. Nível mínimo e nota da calculadora (IV, qualidade, potência, shiny).
 */
function pokemonForaDaFaixa(pk) {
  if (!pk) return 'sumiu';
  if (pokemonTemXpShareHeld(pk)) return 'xpshareheld';
  // Vestido não se anuncia (o servidor recusa com `skin.travaVenda`): tira-se a skin antes.
  if (skinVestida(pk)) return 'skin';
  if (pk.shiny) return null;
  if (Number(pk.potencia) === 5) return null;
  const min = faixaMinimaPk();
  if ((pk.level ?? 0) < min.level) return 'nivel';
  const nota = notaMercadoDoPokemon(pk, estado.especies);
  if (!atendeNotaMercado(nota)) return 'nota';
  return null;
}
const pokemonAnunciavelNaTela = (pk) => pokemonForaDaFaixa(pk) === null;

/**
 * Quantos dias o anúncio ainda tem de pé — o selo do canto superior direito.
 *
 * Arredonda para CIMA: faltando 6 horas ainda é "1d", porque o anúncio de fato só cai no
 * fim do dia contratado. Arredondar para baixo mostraria "0d" num anúncio que ainda está
 * vendendo. Anúncio anterior à taxa não tem prazo (`expiraEm` nulo) e não ganha selo.
 */
function diasRestantes(a) {
  if (!a?.expiraEm) return null;
  const ms = a.expiraEm - Date.now();
  return ms <= 0 ? 0 : Math.ceil(ms / 86_400_000);
}

function duracaoSelo(a) {
  const d = diasRestantes(a);
  if (d == null) return '';
  return `<div class="cm-duracao ${d <= 1 ? 'acabando' : ''}" title="${t('cm.duracaoTitulo')}">
            ${t('cm.duracao', { d })}
          </div>`;
}

// A retenção compara com o relógio do SERVIDOR (`agoraDoServidor`, o mesmo da Loja): um PC adiantado
// liberava o botão antes da hora e levava a recusa do servidor; um atrasado prendia o botão já liberado.
/** A retenção inteira em texto ("2 min") — vem do servidor no welcome. */
const tempoRetencao = () => {
  const ms = estado.mercado?.cooldownCompraMs ?? 2 * 60_000;
  return ms % 3_600_000 === 0 ? `${ms / 3_600_000} h` : `${Math.round(ms / 60_000)} min`;
};
const anuncioEmRetencao = (a) => !!(a?.compravelEm && agoraDoServidor() < a.compravelEm);
const segundosRetencao = (a) => {
  if (!anuncioEmRetencao(a)) return 0;
  return Math.max(1, Math.ceil((a.compravelEm - agoraDoServidor()) / 1000));
};
/** Marca o selo ou o botão para o contador andar sozinho (ver `atualizarContadoresRetencao`). */
const attrRetencao = (a) => (anuncioEmRetencao(a) ? ` data-retido-ate="${Number(a.compravelEm)}"` : '');
// "Retido · 7:59:30" quando falta hora, "Retido · 4:05" quando falta menos — a mesma chave de
// sempre: as horas entram junto dos minutos, no `{m}`.
const rotuloRetencao = (a) => {
  const s = segundosRetencao(a);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const r = s % 60;
  return t('cm.retencaoBadge', { m: h ? `${h}:${String(m).padStart(2, '0')}` : m, s: String(r).padStart(2, '0') });
};
const avisoRetencaoAnuncio = () =>
  `<p class="cm-nota cm-retencao-aviso">${dlgIcone('ampulheta', 16)}<span>${t('cm.retencaoAviso', { tempo: tempoRetencao() })}</span></p>`;

/**
 * Desabilita o botão de compra enquanto o anúncio está em retenção (servidor também bloqueia). O
 * clique já fica ligado: quando o contador zera, `atualizarContadoresRetencao` só reabilita o botão e
 * devolve o texto de antes — sem redesenhar a vitrine.
 */
function aplicarRetencaoCompra(bt, a, aoComprar) {
  bt.onclick = aoComprar;
  if (anuncioEmRetencao(a)) {
    bt.dataset.rotuloLivre = bt.textContent;
    bt.dataset.retidoAte = String(Number(a.compravelEm));
    bt.disabled = true;
    bt.classList.add('cm-retido');
    bt.textContent = rotuloRetencao(a);
    bt.title = t('cm.retencaoComprar');
  }
}

/**
 * Os contadores de retenção andam sozinhos, um tique por segundo.
 *
 * Antes o "Retido · 4:05" era escrito uma vez, quando a vitrine era montada, e ficava parado até o
 * jogador fechar e abrir o item de novo — e o botão continuava travado depois de liberar. Agora todo
 * selo e botão de retenção carrega `data-retido-ate` (o `compravelEm`), e este tique reescreve o
 * tempo pelo relógio do servidor. Quando zera: o botão volta a "Comprar" (ou ao texto que tinha) e
 * destrava; o selo some. O clique de compra já confere a retenção na hora, e o servidor também.
 *
 * Custa um `querySelectorAll` por segundo, e nada com a aba escondida.
 */
function atualizarContadoresRetencao() {
  if (document.hidden) return;
  const marcados = document.querySelectorAll('[data-retido-ate], [data-mostrar-ate]');
  if (!marcados.length) return;
  const agora = agoraDoServidor();
  for (const el of marcados) {
    // O "Editar" do próprio anúncio: nasce escondido na retenção e aparece quando libera.
    if (el.dataset.mostrarAte) {
      if (Number(el.dataset.mostrarAte) > agora) continue;
      delete el.dataset.mostrarAte;
      el.style.display = '';
      continue;
    }
    const ate = Number(el.dataset.retidoAte);
    if (ate > agora) {
      el.textContent = rotuloRetencao({ compravelEm: ate });
      continue;
    }
    delete el.dataset.retidoAte;
    if (el.tagName === 'BUTTON') {
      el.disabled = false;
      el.classList.remove('cm-retido');
      el.removeAttribute('title');
      el.textContent = el.dataset.rotuloLivre ?? t('cm.comprar');
    } else {
      el.remove();
    }
  }
}
setInterval(atualizarContadoresRetencao, 1000);

/** id 5 — Beast Ball, comprada com diamante na loja; a única bola anunciável no Market. */
const BEAST_BALL_ID = 5;
/**
 * O anúncio é do jogador que está olhando?
 *
 * `estado.eu.id` e NÃO `estado.eu.dbId`: o snapshot manda o id do jogador no campo `id` (ver
 * `id: p.dbId` no `snapshot` do sim) e nunca existiu um `dbId` no cliente. A comparação com o
 * campo errado dava `undefined` sempre, então o vendedor não via o próprio anúncio marcado na
 * lista de vendedores de um item — e o botão dele dizia "Comprar" numa linha que ele não pode
 * comprar (o servidor recusa com "esse anúncio é seu").
 */
const ehMeuAnuncio = (a) => a?.vendedorId != null && a.vendedorId === estado.eu?.id;

// ------------------------------------------------------------------ favoritos
//
// A estrela mora na CONTA (`automation.mercadoFavoritos`, gravada pelo servidor): favoritar no PC e
// abrir no celular dá a mesma lista. A tela muda na hora e o snapshot seguinte confirma.

/** Teto da lista — o mesmo do servidor (`MAX_FAVORITOS`, em `market-db.mjs`). */
const MAX_FAVORITOS_MERCADO = 60;

const favoritosMercado = () => estado.eu?.automation?.mercadoFavoritos ?? [];
const ehFavoritoMercado = (id) => favoritosMercado().includes(Number(id));

/**
 * Os ITENS do catálogo marcados com a estrela — lista à parte da de anúncios
 * (`automation.mercadoFavItens`). O item favorito não é uma oferta: é o atalho para o painel de
 * ofertas daquele item, e continua valendo quando alguém vende.
 */
const favoritosItensMercado = () => estado.eu?.automation?.mercadoFavItens ?? [];
const ehItemFavoritoMercado = (itemId) => favoritosItensMercado().includes(Number(itemId));

/**
 * As ESPÉCIES marcadas com a estrela (`automation.mercadoFavEspecies`) — terceira lista, pela
 * mesma razão da de itens: o que se guarda é o atalho para as ofertas de Dragonite, e ele não
 * morre quando o último Dragonite à venda é comprado.
 */
const favoritosEspeciesMercado = () => estado.eu?.automation?.mercadoFavEspecies ?? [];
const ehEspecieFavoritaMercado = (speciesId) => favoritosEspeciesMercado().includes(Number(speciesId));

/** O número do botão "Meus favoritos": anúncios, itens e espécies somados. */
const totalFavoritosMercado = () =>
  favoritosMercado().length + favoritosItensMercado().length + favoritosEspeciesMercado().length;

/**
 * Acende ou apaga uma estrela. `chaves` troca o texto do título — a estrela de uma ESPÉCIE guarda
 * "as ofertas de Dragonite", e não aquele anúncio ali: dizer "guardar nos favoritos" nas duas faria
 * o jogador achar que perdeu o anúncio quando ele for vendido.
 */
function pintarBotaoFavorito(b, on, chaves = ['cm.favoritar', 'cm.desfavoritar']) {
  b.classList.toggle('on', on);
  b.setAttribute('aria-pressed', on ? 'true' : 'false');
  b.title = t(on ? chaves[1] : chaves[0]);
  b.setAttribute('aria-label', b.title);
}

/** As duas frases da estrela de uma espécie. */
const CHAVES_FAV_ESPECIE = ['cm.favoritarEspecie', 'cm.desfavoritarEspecie'];

/**
 * Liga ou desliga a estrela de um anúncio. Sem `ativo`, inverte.
 *
 * Na aba Favoritos, desfavoritar tira o card da grade na mesma hora — esperar a lista voltar do
 * servidor deixaria ali um card "desfavoritado", parecendo que o clique não pegou.
 */
function alternarFavoritoMercado(a, ativo = !ehFavoritoMercado(a.id)) {
  const auto = estado.eu?.automation;
  if (!auto) return;
  const lista = (auto.mercadoFavoritos ??= []);
  const id = Number(a.id);
  const i = lista.indexOf(id);
  if (ativo) {
    if (i >= 0) return;
    if (lista.length >= MAX_FAVORITOS_MERCADO) return toast(t('cm.favLimite', { n: num(MAX_FAVORITOS_MERCADO) }));
    lista.push(id);
  } else {
    if (i < 0) return;
    lista.splice(i, 1);
  }
  enviar({ t: 'market.favoritar', id, ativo });
  for (const b of document.querySelectorAll(`.cm-fav[data-fav="${id}"]`)) pintarBotaoFavorito(b, ativo);
  // A contagem de interessados anda junto, na hora: a estrela dele é uma das que ela conta. O
  // anúncio em memória também, senão a próxima repintura da grade voltaria o número velho.
  const delta = ativo ? 1 : -1;
  for (const s of document.querySelectorAll(`.cm-fav-n[data-fav-n="${id}"]`)) {
    pintarSeloFavoritos(s, Math.max(0, (Number(s.dataset.n) || 0) + delta));
  }
  const naLista = estado.cmDados?.linhas?.find((x) => x.id === id);
  if (naLista && naLista.favoritos != null) naLista.favoritos = Math.max(0, naLista.favoritos + delta);
  const conta = $('#cm-favoritos .cm-fav-conta');
  if (conta) conta.textContent = num(totalFavoritosMercado());
  if (!ativo && estado.cmAba === 'favoritos' && estado.cmDados?.linhas) {
    estado.cmDados = { ...estado.cmDados, linhas: estado.cmDados.linhas.filter((x) => x.id !== id) };
    pintarMercado();
  }
}

/** Liga ou desliga a estrela de um ITEM do catálogo. Mesma regra da de anúncio, logo acima. */
function alternarFavoritoItemMercado(itemId, ativo = !ehItemFavoritoMercado(itemId)) {
  const auto = estado.eu?.automation;
  if (!auto) return;
  const lista = (auto.mercadoFavItens ??= []);
  const id = Number(itemId);
  const i = lista.indexOf(id);
  if (ativo) {
    if (i >= 0) return;
    if (lista.length >= MAX_FAVORITOS_MERCADO) return toast(t('cm.favLimite', { n: num(MAX_FAVORITOS_MERCADO) }));
    lista.push(id);
  } else {
    if (i < 0) return;
    lista.splice(i, 1);
  }
  enviar({ t: 'market.favoritarItem', itemId: id, ativo });
  for (const b of document.querySelectorAll(`.cm-fav[data-fav-item="${id}"]`)) pintarBotaoFavorito(b, ativo);
  const conta = $('#cm-favoritos .cm-fav-conta');
  if (conta) conta.textContent = num(totalFavoritosMercado());
  // Na aba Favoritos o card sai na hora, como o de anúncio.
  if (!ativo && estado.cmAba === 'favoritos') pintarMercado();
}

/** Liga ou desliga a estrela de uma ESPÉCIE. Mesma regra das duas de cima. */
function alternarFavoritoEspecieMercado(speciesId, ativo = !ehEspecieFavoritaMercado(speciesId)) {
  const auto = estado.eu?.automation;
  if (!auto) return;
  const lista = (auto.mercadoFavEspecies ??= []);
  const id = Number(speciesId);
  if (!Number.isFinite(id) || id <= 0) return;
  const i = lista.indexOf(id);
  if (ativo) {
    if (i >= 0) return;
    if (lista.length >= MAX_FAVORITOS_MERCADO) return toast(t('cm.favLimite', { n: num(MAX_FAVORITOS_MERCADO) }));
    lista.push(id);
  } else {
    if (i < 0) return;
    lista.splice(i, 1);
  }
  enviar({ t: 'market.favoritarEspecie', speciesId: id, ativo });
  // Todas as estrelas daquela espécie na tela, e não só a clicada: a mesma espécie pode estar na
  // grade E na faixa da lista de ofertas aberta.
  for (const b of document.querySelectorAll(`.cm-fav[data-fav-especie="${id}"]`)) pintarBotaoFavorito(b, ativo, CHAVES_FAV_ESPECIE);
  const conta = $('#cm-favoritos .cm-fav-conta');
  if (conta) conta.textContent = num(totalFavoritosMercado());
  // Na aba Favoritos o card sai na hora, como o de item.
  if (!ativo && estado.cmAba === 'favoritos') pintarMercado();
}

/** A estrela de uma ESPÉCIE — no card da grade e na faixa da lista de ofertas dela. */
function botaoFavoritoEspecieMercado(speciesId) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'cm-fav';
  b.dataset.favEspecie = speciesId;
  b.textContent = '★';
  pintarBotaoFavorito(b, ehEspecieFavoritaMercado(speciesId), CHAVES_FAV_ESPECIE);
  b.onclick = (ev) => {
    ev.stopPropagation();
    alternarFavoritoEspecieMercado(speciesId);
  };
  return b;
}

/** A estrela de um item — no cabeçalho do painel de ofertas e no card da aba Favoritos. */
function botaoFavoritoItemMercado(itemId) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'cm-fav';
  b.dataset.favItem = itemId;
  b.textContent = '★';
  pintarBotaoFavorito(b, ehItemFavoritoMercado(itemId));
  b.onclick = (ev) => {
    ev.stopPropagation();
    alternarFavoritoItemMercado(itemId);
  };
  return b;
}

/**
 * Leva ao PAINEL DE OFERTAS de um item — o clique no card de item da aba Favoritos.
 *
 * É o mesmo caminho do clique em "Itens" na barra (zera o que só vale para pokémon) e mais três
 * coisas, para o item estar de fato na lista quando ela abrir: a categoria dele, sem tipo nem
 * busca, e o "Ocultar sem estoque" desligado se ele não tem estoque agora. Sem isso a vitrine
 * abria filtrada por outra coisa e o painel fechava sozinho (`cmItemSel` fora da lista).
 */
function irParaOfertasDoItem(itemId) {
  const item = itemDoMercado(itemId);
  if (!item) return;
  const f = estado.cmFiltro;
  estado.cmAba = 'vitrine';
  f.tipo = 'item';
  f.soShiny = false;
  f.soP5 = false;
  f.soTmElemental = false;
  f.soTmAoe = false;
  f.semOutland = false;
  // Como no clique em "Itens" da barra: sair da aba de pokémon fecha a espécie aberta. A moeda
  // não é tocada — a vitrine de itens tem a chave dela dentro do painel de ofertas.
  estado.cmEspecieSel = null;
  zerarFaixasDoMercado(f);
  f.criterios = [];
  f.categoria = item.categoria ?? '';
  f.elemento = '';
  f.busca = '';
  if (f.soComEstoque && !itemTemEstoque(item)) f.soComEstoque = false;
  estado.cmPagina = 0;
  estado.cmItemSel = item.id;
  estado.cmItemMoeda = estado.cmItemMoeda ?? 'gold';
  abrirModal('community');
  pedirAnunciosItem();
}

/**
 * O card de um ITEM favorito, na aba Favoritos — a mesma fôrma do card de anúncio, com o que a
 * vitrine de itens diz na linha dele: quantos vendem e a partir de quanto, nas duas moedas. O card
 * inteiro leva às ofertas; a estrela tira dos favoritos.
 */
function cardItemFavorito(itemId) {
  const item = itemDoMercado(itemId);
  if (!item) return null;
  const r = estado.cmItens?.[item.id] ?? null;
  const vazio = !r || !r.anuncios;
  // Sem vendedor, a linha ainda mostra o ÍCONE da moeda: são duas linhas iguais de "a partir de",
  // e um "—" sem ícone não diria se o que falta é o anúncio em Coins ou em Gemas.
  const preco = (moedaId) => {
    const v = apartirDe(r, moedaId);
    const ico = moedaId === 'orb' ? ICONE_GEMA : srcIcone(ICONE_OURO);
    const valor = v == null
      ? `<span class="cm-preco${moedaId === 'orb' ? ' orb' : ''}"><img src="${ico}" alt="">—</span>`
      : precoComMoeda(v, moedaId, { curto: true });
    return `<div class="cm-fav-item-preco${v == null ? ' nada' : ''}"><i>${t('cm.apartirDe')}</i>${valor}</div>`;
  };
  const categoria = (() => { const k = `cm.cat.${item.categoria}`; const tr = t(k); return tr !== k ? tr : item.categoria; })();

  const el = document.createElement('div');
  el.className = 'cm-card cm-card-item-fav tem-fav';
  el.tabIndex = 0;
  el.innerHTML = `
    <div class="cm-arte"><span data-ico="${icoVitrineItem(item)}" data-ico-px="52"></span></div>
    <div class="cm-selos"></div>
    <div class="cm-info">
      <div class="cm-nome" title="${escapar(nomeItem(item, item.nome))}">${escapar(nomeItem(item, item.nome))}</div>
      <div class="cm-chips">${chipsDeTipo([estado.itensTipos[item.id]])}</div>
      <div class="cm-sub">${escapar(categoria)} · ${vazio ? t('cm.semVendedores') : t('cm.nVendendo', { n: r.anuncios, u: num(r.unidades) })}</div>
    </div>
    <div class="cm-rodape">${preco('gold')}${preco('orb')}</div>
    <div class="cm-botoes"><button type="button" class="cm-btn">${t('cm.verOfertas')}</button></div>`;
  for (const ico of el.querySelectorAll('[data-ico]')) pintarIcone(ico);
  el.appendChild(botaoFavoritoItemMercado(item.id));
  el.onclick = () => irParaOfertasDoItem(item.id);
  el.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      irParaOfertasDoItem(item.id);
    }
  };
  return el;
}

/**
 * Quantas PESSOAS favoritaram o anúncio — o número ao lado da estrela, e o "12 pessoas estão
 * interessadas" ao passar o mouse. É o empurrão de quem está em dúvida: outros estão de olho.
 *
 * Só aparece com 1 ou mais. Um "0" ao lado da estrela diria "ninguém quer este pokémon", que é o
 * contrário do que o selo existe para dizer. A contagem vem do servidor (`market_favoritos`, sem a
 * estrela do próprio vendedor); a partir de 5 ele esquenta, para o anúncio disputado saltar na grade.
 */
function seloFavoritosAnuncio(a, { doVendedor = false } = {}) {
  const s = document.createElement('span');
  s.className = 'cm-fav-n';
  s.dataset.favN = a.id;
  if (doVendedor) s.dataset.vendedor = '1';
  pintarSeloFavoritos(s, Number(a.favoritos) || 0);
  return s;
}

function pintarSeloFavoritos(s, n) {
  s.dataset.n = String(n);
  s.classList.toggle('hidden', n <= 0);
  s.classList.toggle('quente', n >= 5);
  s.textContent = num(n);
  const chave = s.dataset.vendedor
    ? (n === 1 ? 'cm.favInteressadoSeu' : 'cm.favInteressadosSeu')
    : (n === 1 ? 'cm.favInteressado' : 'cm.favInteressados');
  s.title = t(chave, { n: num(n) });
  s.setAttribute('aria-label', s.title);
}

/** A estrela no canto do card. */
function botaoFavoritoMercado(a) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'cm-fav';
  b.dataset.fav = a.id;
  b.textContent = '★';
  pintarBotaoFavorito(b, ehFavoritoMercado(a.id));
  b.onclick = (ev) => {
    ev.stopPropagation();
    alternarFavoritoMercado(a);
  };
  return b;
}

/** Entra na aba Favoritos, ou volta para a vitrine — o botão da barra lateral e o atalho do celular. */
function alternarAbaFavoritos() {
  estado.cmAba = estado.cmAba === 'favoritos' ? 'vitrine' : 'favoritos';
  estado.cmPagina = 0;
  estado.cmDados = { linhas: [], carregando: true };
  abrirModal('community');
}

const ehAnuncioBola = (a) => !!a?.ficha?.bola;
const ehAnuncioDiamante = (a) => a?.tipo === 'diamante' || !!a?.ficha?.diamante;
/**
 * A arte de um anúncio que não é de pokémon.
 *
 * O diamante entra primeiro porque ele NÃO tem `itemId` — `imgItem(null, px)` cairia no ícone
 * genérico de item, e o card de diamante ficaria com cara de pedra sem nome.
 */
const arteItemAnuncio = (a, px) =>
  ehAnuncioDiamante(a) ? iconeArquivo(ICONE_DIAMANTE, px)
    : ehAnuncioBola(a) ? iconeBola(a.ficha.ballId ?? a.itemId, px)
      : imgItem(a.itemId, px);

/**
 * O nome de um anúncio de item, do jeito que ele precisa ser lido.
 *
 * Para tudo o mais é o nome do catálogo. Para a Caixa de Fundador ele traz a SÉRIE: dois
 * anúncios de "Founder Box" são caixas diferentes, e sem o número o card de baixo é
 * indistinguível do de cima — inclusive na hora de cancelar o anúncio certo.
 */
function nomeAnuncioItem(a) {
  if (a?.ficha?.caixaId) {
    return `${t(`caixas.nome.${a.ficha.caixaTipo}`)} ${serieDaCaixa(a.ficha.caixaTipo, a.ficha.serie)}`;
  }
  if (a?.ficha?.casaId) return `${nomeCasaRaridade(a.ficha.casaRaridade)} ${numeroDaCasa(a.ficha.casaId)}`;
  return a?.ficha?.nome ?? '';
}

/**
 * O NÚMERO de um anúncio de peça numerada — Caixa de Fundador ou Casa — e a cor da plaquinha, ou
 * `null` para o resto. A cor da casa é a variável da raridade: nada de hex no template.
 */
function numeroDoAnuncio(a) {
  if (a?.ficha?.caixaId) {
    return { rotulo: serieDaCaixa(a.ficha.caixaTipo, a.ficha.serie), cor: CAIXAS_BETA[a.ficha.caixaTipo]?.cor ?? 'var(--rx)' };
  }
  if (a?.ficha?.casaId) {
    const rar = RC_NIVEIS.includes(a.ficha.casaRaridade) ? a.ficha.casaRaridade : 'comum';
    return { rotulo: numeroDaCasa(a.ficha.casaId), cor: `var(--rar-${rar})` };
  }
  if (a?.ficha?.bicicletaId) {
    const rar = RC_NIVEIS.includes(a.ficha.bicicletaRaridade) ? a.ficha.bicicletaRaridade : 'comum';
    return { rotulo: numeroDaBicicleta(a.ficha.bicicletaId), cor: `var(--rar-${rar})` };
  }
  return null;
}

/** A plaquinha pronta: `<b class="cmv-serie">#000042</b>`, ou `''`. */
function plaquinhaDoAnuncio(a, classe = 'cmv-serie') {
  const n = numeroDoAnuncio(a);
  return n ? `<b class="${classe}" style="--cx-cor:${n.cor}">${escapar(n.rotulo)}</b>` : '';
}

function passoEscolherItem(corpo, fechar) {
  const disponiveis = Object.entries(estado.eu.items ?? {})
    .map(([id, q]) => ({ item: estado.itens.get(Number(id)), q }))
    .filter((x) => x.q > 0 && anunciavelNaTela(x.item));

  // A Beast Ball não entra mais: saiu da vitrine em 30/09/2026 (das coisas de diamante, só as skins
  // e as Caixas de Fundador ficam).
  // As caixas FECHADAS. Vêm de `caixas.minhas` e não de `items`, e cada uma é um slot próprio:
  // é a série que o vendedor está escolhendo, não "quantas caixas".
  const caixas = estado.eu.caixas?.minhas ?? [];
  // As casas, uma por botão e com o número: é a PEÇA que vai para a vitrine. Só as da mão — a que
  // já está anunciada não se anuncia de novo.
  const casasVenda = minhasCasas().filter((c) => !c.anunciada);
  // As bicicletas, pelo mesmo motivo: a PEÇA numerada é o que vai para a vitrine.
  const bikesVenda = (estado.eu.bicicleta?.lista ?? []).filter((b) => !b.anunciada);

  if (!disponiveis.length && !caixas.length && !casasVenda.length && !bikesVenda.length) {
    corpo.innerHTML = `<p class="cm-passo-txt">${t('cm.bagVazia')}</p>`;
    return;
  }
  // A regra do "um anúncio por item" fica à vista ANTES da escolha, do mesmo jeito que a
  // faixa mínima do pokémon: quem já tem uma pedra na vitrine precisa saber que o caminho é
  // editar o preço dela, e não descobrir isso depois de escolher preço e quantidade.
  corpo.innerHTML = `<p class="cm-passo-txt">${t('cm.qualItem')}</p>`
    + `<p class="cm-nota dim">${t('cm.travaUmPorItem', { min: estado.mercado?.reanuncioMin ?? 30 })}</p>`
    + `<div class="cm-grade" id="cm-itens"></div>`;
  const grade = corpo.querySelector('#cm-itens');
  for (const caixa of caixas) {
    const def = CAIXAS_BETA[caixa.tipo];
    const b = document.createElement('button');
    b.className = 'cm-slot cm-slot-cx';
    b.dataset.caixa = caixa.id;
    b.style.setProperty('--cx-cor', def?.cor ?? 'var(--rx)');
    b.appendChild(iconeArquivo(`/img/itens/caixa-${caixa.tipo}.png`, 34));
    b.insertAdjacentHTML(
      'beforeend',
      `<span class="cm-slot-nome">${escapar(t(`caixas.nome.${caixa.tipo}`))}</span>`
        + `<b class="cmv-serie" style="--cx-cor:${def?.cor ?? 'var(--rx)'}">${
          escapar(serieDaCaixa(caixa.tipo, caixa.serie))}</b>`,
    );
    grade.appendChild(b);
  }
  for (const casa of casasVenda) {
    const b = document.createElement('button');
    b.className = `cm-slot cm-slot-cx cm-slot-casa rar-${casa.rar}`;
    b.dataset.casa = casa.id;
    b.style.setProperty('--cx-cor', `var(--rar-${casa.rar})`);
    b.appendChild(imgItem(CASA_ITEM_POR_RAR[casa.rar], 34));
    b.insertAdjacentHTML(
      'beforeend',
      `<span class="cm-slot-nome">${escapar(nomeCasaRaridade(casa.rar))}</span>`
        + `<b class="cmv-serie" style="--cx-cor:var(--rar-${casa.rar})">${escapar(numeroDaCasa(casa.id))}</b>`,
    );
    grade.appendChild(b);
  }
  for (const bici of bikesVenda) {
    const b = document.createElement('button');
    b.className = `cm-slot cm-slot-cx rar-${bici.rar}`;
    b.dataset.bici = bici.id;
    b.style.setProperty('--cx-cor', `var(--rar-${bici.rar})`);
    b.appendChild(imgItem(BICICLETA_ITEM_POR_RAR[bici.rar], 34));
    b.insertAdjacentHTML(
      'beforeend',
      `<span class="cm-slot-nome">${escapar(nomeBicicletaRaridade(bici.rar))}</span>`
        + `<b class="cmv-serie" style="--cx-cor:var(--rar-${bici.rar})">${escapar(numeroDaBicicleta(bici.id))}</b>`,
    );
    grade.appendChild(b);
  }
  for (const { item, q } of disponiveis) {
    const b = document.createElement('button');
    b.className = 'cm-slot';
    b.dataset.id = item.id;
    b.appendChild(imgItem(item.id, 34));
    const tipo = estado.itensTipos[item.id];
    b.insertAdjacentHTML(
      'beforeend',
      `<span class="cm-slot-nome">${escapar(nomeItem(item, item.name))}</span>` +
        `${tipo ? `<span class="cm-chip tipo ${tipo}">${tipo}</span>` : ''}<b>${num(q)}</b>`,
    );
    grade.appendChild(b);
  }
  corpo.onclick = (ev) => {
    const b = ev.target.closest('.cm-slot');
    if (!b) return;
    if (b.dataset.casa) {
      const casa = minhaCasaPorId(b.dataset.casa);
      if (!casa || casa.anunciada) return;
      const soltos = (casa.postos ?? []).filter((id) => id != null).length;
      passoPreco(corpo, fechar, {
        tipo: 'item',
        // `itemId` traz a referência de preço das casas daquela raridade; `casaId` é o que o
        // servidor usa — ele desvia para o escrow da casa numerada antes de olhar o item.
        itemId: CASA_ITEM_POR_RAR[casa.rar],
        casaId: casa.id,
        nome: `${nomeCasaRaridade(casa.rar)} ${numeroDaCasa(casa.id)}`,
        maximo: 1,
        npc: 0,
        // A regra que dói se descoberta depois: anunciar solta os pokémon, e cancelar não os traz.
        nota: soltos ? t(soltos === 1 ? 'casa.avisoAnunciarUm' : 'casa.avisoAnunciar', { n: soltos }) : '',
      });
      return;
    }
    if (b.dataset.bici) {
      const bici = (estado.eu.bicicleta?.lista ?? []).find((x) => x.id === Number(b.dataset.bici));
      if (!bici || bici.anunciada) return;
      passoPreco(corpo, fechar, {
        tipo: 'item',
        // `itemId` traz a referência de preço das bicicletas daquela raridade; `bicicletaId` é o que
        // o servidor usa — ele desvia para o escrow da bicicleta numerada antes de olhar o item.
        itemId: BICICLETA_ITEM_POR_RAR[bici.rar],
        bicicletaId: bici.id,
        nome: `${nomeBicicletaRaridade(bici.rar)} ${numeroDaBicicleta(bici.id)}`,
        maximo: 1,
        npc: 0,
        // Anunciar a equipada tira a velocidade na hora — melhor saber antes de pôr o preço.
        nota: estado.eu.bicicleta?.equipada === bici.id ? t('bicicleta.avisoAnunciarEquipada') : '',
      });
      return;
    }
    if (b.dataset.caixa) {
      const caixa = caixas.find((c) => c.id === Number(b.dataset.caixa));
      if (!caixa) return;
      passoPreco(corpo, fechar, {
        tipo: 'item',
        caixaId: caixa.id,
        // Só para o DESENHO da barraca (a arte da caixa é por tipo); o servidor não lê.
        caixaTipo: caixa.tipo,
        // O nome que a tela de preço mostra traz o número: é a peça que está sendo posta à
        // venda, e sem ele o vendedor não sabe qual das caixas dele escolheu.
        nome: `${t(`caixas.nome.${caixa.tipo}`)} ${serieDaCaixa(caixa.tipo, caixa.serie)}`,
        maximo: 1,
        npc: 0,
      });
      return;
    }
    const item = estado.itens.get(Number(b.dataset.id));
    passoPreco(corpo, fechar, {
      tipo: 'item',
      itemId: item.id,
      nome: nomeItem(item, item.name),
      maximo: estado.eu.items[item.id] ?? 1,
      npc: item.npcPrice ?? 0,
    });
  };
}

function passoEscolherPokemon(corpo, fechar) {
  // O ativo fica de fora: é o que está lutando, e o servidor recusaria de qualquer jeito.
  // O starter do onboarding também fica de fora — trade lock contra reroll de alt (ver sim.mjs).
  const todos = (estado.eu.pokemons ?? []).filter((k) => k.id !== estado.eu.activeId);
  const starters = todos.filter((k) => k.starter);
  const semStarter = todos.filter((k) => !k.starter);
  const lista = semStarter.filter(pokemonAnunciavelNaTela);
  const foraDaFaixa = semStarter.filter((k) => ['nivel', 'nota'].includes(pokemonForaDaFaixa(k))).length;
  const min = estado.mercado?.pokemonMin;

  if (!lista.length) {
    const regra = { level: min?.level ?? 50, nota: min?.nota ?? MERCADO_POKEMON_MIN.nota };
    const msg = !semStarter.length && starters.length
      ? t('cm.starterTravado')
      : !semStarter.length
      ? t(todos.length ? 'cm.starterTravado' : 'cm.semPokemon')
      : t('cm.pkNenhumElegivel', regra);
    corpo.innerHTML = `<p class="cm-passo-txt">${msg}</p>` +
      (starters.length ? `<p class="cm-nota dim">${t('cm.pkStarterEscondidos', { n: starters.length })}</p>` : '') +
      (min && semStarter.length ? `<p class="cm-nota">${t('cm.pkRegra', regra)}</p>` : '');
    return;
  }

  // A regra fica À VISTA, e não só quando barra: o jogador precisa entender por que a
  // lista está menor que a caixa dele antes de achar que sumiu pokémon. (No celular ela mostra
  // duas linhas e abre no toque — ver `dobrarNotaNoCelular`.)
  corpo.innerHTML = `<div class="cmpk">` +
    `<p class="cm-passo-txt">${t('cm.qualPokemon')}</p>` +
    `<div class="cmpk-notas">` +
    (min ? `<p class="cm-nota">${t('cm.pkRegra', { level: min.level ?? 50, nota: min.nota ?? MERCADO_POKEMON_MIN.nota })}</p>` : '') +
    (starters.length
      ? `<p class="cm-nota dim">${t('cm.pkStarterEscondidos', { n: starters.length })}</p>`
      : '') +
    // Só quem ficou abaixo da FAIXA: o vestido e o da Exp. Share têm nota própria logo abaixo,
    // e contá-los aqui diria "não atingiu a faixa" de um Shiny P5 que atinge.
    (foraDaFaixa
      ? `<p class="cm-nota dim">${t('cm.pkEscondidos', { n: foraDaFaixa })}</p>`
      : '') +
    (semStarter.some(pokemonTemXpShareHeld)
      ? `<p class="cm-nota dim">${t('xpshareheld.pkEscondidosAnuncio')}</p>`
      : '') +
    (semStarter.some((k) => skinVestida(k))
      ? `<p class="cm-nota dim">${t('skin.pkEscondidosAnuncio')}</p>`
      : '') +
    `</div>` +
    // A busca pelo nome, como em toda folha de escolha: com duzentos anunciáveis, achar o
    // Gengar shiny pela rolagem era a única saída.
    `<div class="dmpk-topo">
      <span class="cm-busca-caixa">${lupa()}<input id="cm-pks-busca" class="cm-busca" type="search" autocomplete="off"
             maxlength="32" placeholder="${escapar(t('amigos.anexarBuscar'))}" value="${escapar(cmPkFiltro.busca)}"></span>
      <span class="shl-conta" id="cm-pks-conta"></span>
    </div>` +
    `<div class="dmpk-filtros" id="cm-pks-filtros"></div>` +
    `<div class="mk-grade cm-pk-escolha-grade" id="cm-pks"></div>` +
    `</div>`;
  const grade = corpo.querySelector('#cm-pks');
  const conta = corpo.querySelector('#cm-pks-conta');

  // Os filtros da escolha — o "Local" separa a Equipe, o Depot e a Coleção. A Coleção ENTRA no
  // Mercado: ela só fica fora da venda ao NPC. A ★ no card lembra que aquele foi separado.
  const pintar = () => {
    if (!grade.isConnected) return;
    const colecao = conjuntoColecaoCliente();
    const piso = ivMinDoFiltro(cmPkFiltro.ivMin);
    const busca = cmPkFiltro.busca.trim().toLowerCase();
    const visiveis = ordenarMarketPokemon(
      lista.filter((k) => passaLocal(k, cmPkFiltro.local, colecao) && depotPassaFiltros(k, busca, cmPkFiltro.tipo, piso)),
      cmPkFiltro.ordem,
    );
    conta.textContent = t('amigos.anexarConta', { n: num(visiveis.length), total: num(lista.length) });
    grade.innerHTML = '';
    if (!visiveis.length) {
      grade.innerHTML = `<div class="cm-vazio">${t('amigos.anexarVazio')}</div>`;
      return;
    }
    for (const k of visiveis) {
      grade.appendChild(cardPokemonEscolha(k, {
        colecao,
        aoVerFicha: () => abrirFichaDoPokemon(k),
        aoSelecionar: () => passoPreco(corpo, fechar, {
          // Com o nome que o dono deu — é o que ele acabou de clicar no card. "Por quanto
          // vender Dragonite?" depois de escolher um card escrito "Trovão" faz duvidar se o
          // clique pegou o bicho certo, na única tela do jogo em que isso custa caro.
          tipo: 'pokemon', pokemonId: k.id, nome: `${nomeNoAnuncio(k)} Nv ${k.level}`, maximo: 1,
          // O bicho em si, para a folha dos dias desenhá-lo na barraca da feira.
          pk: k,
        }),
      }));
    }
  };
  corpo.querySelector('#cm-pks-filtros').appendChild(criarFiltrosSelect({
    tipo: cmPkFiltro.tipo,
    ordem: cmPkFiltro.ordem,
    ivMin: cmPkFiltro.ivMin,
    local: cmPkFiltro.local,
    locais: LOCAIS_TODOS,
    ordens: MK_POKEMON_ORDENS,
    ordemI18n: MK_POKEMON_ORDEM_I18N,
    onChange: (campo, valor) => {
      if (campo === 'ordem') cmPkFiltro.ordem = valor || 'padrao';
      else cmPkFiltro[campo] = valor;
      pintar();
    },
  }));
  corpo.querySelector('#cm-pks-busca').oninput = (ev) => {
    cmPkFiltro.busca = ev.target.value;
    pintar();
  };
  const passo = corpo.querySelector('.cmpk');
  dobrarFiltrosNoCelular({
    campos: [corpo.querySelector('#cm-pks-filtros')],
    botaoEm: passo.querySelector('.dmpk-topo'),
    host: passo,
  });
  dobrarNotaNoCelular(passo.querySelector('.cmpk-notas'));
  repintarComAColecao(grade, pintar);
  pintar();
}

/** Os filtros da escolha de pokémon do anúncio, fora da função: quem anuncia três seguidos filtra uma vez. */
const cmPkFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', local: 'todos' };

/**
 * O terceiro passo: por quanto, e quantos.
 *
 * A ordem na tela é PREÇO DA UNIDADE primeiro, quantidade depois — é a ordem em que a decisão
 * acontece ("quanto vale um destes?" vem antes de "quantos eu solto?"), e deixa claro que o
 * número digitado é por unidade e não pelo lote. O resumo fecha a conta com o total.
 */
function passoPreco(corpo, fechar, alvo) {
  corpo.onclick = null;
  cmPassoPrecoAtualizar = null;
  // DUAS perguntas diferentes, e elas se separaram quando o diamante chegou:
  //
  //   `emLote`     o resumo fala em LOTE ("532 × 2 por unidade") em vez de um preço só?
  //   `temSeletor` esta tela ainda precisa PERGUNTAR a quantidade?
  //
  // No diamante a resposta é "sim" e "não": o lote foi escolhido no passo anterior, contra a
  // cota (`qtdFixa`), e montar aqui uma barra travada em 1 era ruído — pior, ruído que parecia
  // dizer que ele ia anunciar um diamante só.
  const emLote = alvo.maximo > 1 || (alvo.qtdFixa ?? 1) > 1;
  const temSeletor = alvo.qtdFixa == null && alvo.maximo > 1;
  // A mercadoria vai para a BARRACA da feira, e a placa do preço pendurada nela anda com o que
  // se digita — o vendedor vê o anúncio como o comprador vai ver. A pergunta "por quanto vender
  // X?" virou isso: o X está ali em pé, com o preço no pescoço.
  const pk = alvo.tipo === 'pokemon' ? alvo.pk : null;
  corpo.innerHTML = `
    ${barraca({
      ator: dlgAtor({
        arte: arteDoAlvoAnuncio(alvo),
        nome: pk ? nomePkHtml(pk) : escapar(alvo.nome),
        sub: pk ? dlgSeloShiny(pk.shiny) + dlgNivel(pk.level) : '',
        classe: 'novo',
      }),
      idPlaca: 'cm-placa',
      idSelo: 'cm-placa-qtd',
      compacta: true,
    })}
    ${alvo.nota ? `<p class="cm-nota cm-nota-alerta">${escapar(alvo.nota)}</p>` : ''}
    <div class="cm-form">
      <label>${t(alvo.tipo === 'diamante' ? 'cm.precoPorDiamante' : 'cm.precoUnit')}
        <input id="cm-preco" type="number" value="${alvo.npc || 1}" min="1" inputmode="numeric">
        <em id="cm-preco-ajuda">${alvo.npc ? t('cm.npcPaga', { v: num(alvo.npc) }) : t('cm.precoUnitAjuda')}</em>
      </label>
      ${alvo.itemId || alvo.tipo === 'diamante' ? '<div class="dlg-refs" id="cm-preco-refs"></div>' : ''}
      ${htmlMoedasAnuncio('gold')}
      <div id="cm-qtd-host"></div>
      <div id="cm-resumo"></div>
      ${avisoRetencaoAnuncio()}
      <button class="cm-publicar" id="cm-publicar">${t('cm.publicar')}</button>
    </div>`;
  hidratarDialogo(corpo);

  let moedaEscolhida = 'gold';
  const resumo = corpo.querySelector('#cm-resumo');
  const inpPreco = corpo.querySelector('#cm-preco');
  const minMoeda = () => precoMinMercado(moedaEscolhida);
  const precoDe = () => Math.max(minMoeda(), Math.floor(Number(inpPreco?.value)) || 1);
  // Declarado ANTES de `atualizar` porque `seletorQuantidade` dispara `aoMudar` uma vez ao
  // montar, para o resumo já nascer preenchido — e nesse instante a atribuição do `const` que
  // estava aqui embaixo ainda não aconteceu. Era um ReferenceError por zona morta temporal, e
  // o sintoma era o resumo da venda vindo em branco.
  let seletor = null;

  const atualizar = () => {
    if (!corpo.isConnected) {
      cmPassoPrecoAtualizar = null;
      return;
    }
    const preco = precoDe();
    // `qtdFixa` é o lote de diamantes, já escolhido contra a cota no passo anterior. Sem ela o
    // resumo diria "1 × 900 = 900" para um lote de 500 — o preço aqui é sempre por UNIDADE, e
    // o total que o vendedor precisa ver é o do lote.
    const qtd = alvo.qtdFixa ?? seletor?.ler() ?? 1;
    inpPreco.min = String(minMoeda());
    const ajuda = corpo.querySelector('#cm-preco-ajuda');
    if (ajuda) ajuda.textContent = ajudaPrecoMercado(moedaEscolhida, alvo.npc, alvo.tipo);
    const refs = corpo.querySelector('#cm-preco-refs');
    if (refs) refs.innerHTML = refsDePrecoHtml({ itemId: alvo.itemId, diamante: alvo.tipo === 'diamante' }, moedaEscolhida);
    corpo.querySelector('#cm-placa').innerHTML = placaDePreco(preco, moedaEscolhida, { porUn: emLote });
    corpo.querySelector('#cm-placa-qtd').textContent = emLote ? `×${num(qtd)}` : '';
    resumo.innerHTML = reciboAnuncioHtml({ moeda: moedaEscolhida, preco, qtd, tipo: alvo.tipo });
    corpo.querySelector('#cm-publicar').disabled =
      totalLiquidoMercado(preco, qtd, moedaEscolhida, alvo.tipo) < 1;
  };
  // A régua de preço é um BOTÃO: um toque copia o menor anúncio (ou a média vendida) para o
  // campo, e daí o vendedor só ajusta.
  corpo.querySelector('#cm-preco-refs')?.addEventListener('click', (ev) => {
    const b = ev.target.closest('[data-usar-preco]');
    if (!b) return;
    inpPreco.value = String(Math.max(minMoeda(), Math.round(Number(b.dataset.usarPreco) || 0)));
    atualizar();
  });

  // Só existe seletor quando há mais de uma unidade A ESCOLHER — para um pokémon (ou um item
  // único) uma barra travada em 1 é ruído, e no diamante a escolha já aconteceu.
  seletor = temSeletor
    ? seletorQuantidade(corpo.querySelector('#cm-qtd-host'), {
        max: alvo.maximo,
        inicial: alvo.maximo,
        rotulo: t('cm.quantosVender'),
        aoMudar: () => atualizar(),
      })
    : null;

  corpo.querySelector('.cm-moedas').onclick = (ev) => {
    const b = ev.target.closest('.cm-moeda');
    if (!b) return;
    moedaEscolhida = b.dataset.moeda;
    for (const outro of b.parentElement.children) outro.classList.toggle('on', outro === b);
    if (moedaEscolhida === 'orb' && Number(inpPreco.value) < precoMinOrb()) inpPreco.value = precoMinOrb();
    if (moedaEscolhida === 'gold' && Number(inpPreco.value) < precoMinGold()) inpPreco.value = precoMinGold();
    atualizar();
  };
  inpPreco.oninput = atualizar;
  atualizar();
  if (alvo.itemId) {
    cmPassoPrecoAtualizar = atualizar;
    // A média guardada pode ser de uma vitrine filtrada por categoria, sem este item: zerada, a
    // linha espera o resumo completo em vez de afirmar "nenhuma venda" por um instante.
    estado.cmMedias = undefined;
    enviar({ t: 'market.itens' });
  }

  corpo.querySelector('#cm-publicar').onclick = () => {
    const qtd = alvo.qtdFixa ?? seletor?.ler() ?? 1;
    const preco = precoDe();
    const publicar = (dias) => {
      enviar({
        t: 'market.criar',
        tipo: alvo.tipo, itemId: alvo.itemId, pokemonId: alvo.pokemonId,
        // `caixaId` desvia o servidor para o escrow da peça numerada — sem ele a caixa seria
        // procurada em `items`, onde ela não mora. Ver `market.criar` no sim.
        caixaId: alvo.caixaId ?? null,
        // O mesmo desvio, para a casa numerada (ver `market.criar`).
        casaId: alvo.casaId ?? null,
        // E para a bicicleta numerada.
        bicicletaId: alvo.bicicletaId ?? null,
        qtd, preco, moeda: moedaEscolhida, dias,
      });
      cmPassoPrecoAtualizar = null;
      fechar();
    };

    // Só POKÉMON passa pela pensão da feira: item fica na prateleira sem prazo nem custo.
    // Perguntar os dias depois do preço é de propósito — é aí que o custo aparece, e decidir
    // o prazo antes de saber quanto vai pedir pelo bicho é decidir no escuro.
    const seguir = () => {
      if (alvo.tipo === 'pokemon') abrirDiasAnuncio(publicar, { pk: alvo.pk, preco: preco * qtd, moeda: moedaEscolhida });
      else publicar(null);
    };

    // O aviso de moeda vem ANTES dos dias, e não no fim: é aqui que a moeda foi escolhida, e
    // é para cá que o "Cancelar" precisa voltar — com o par de botões Coins/Gemas na tela.
    if (moedaEscolhida === 'gold') {
      return avisarAnuncioEmCoins({ nome: alvo.nome, preco, qtd, aoSeguir: seguir });
    }
    seguir();
  };
}

/**
 * O aviso grande de "isto é COINS, não Gema".
 *
 * ### Por que existe
 *
 * O seletor de moeda nasce em **Coins**, e o campo de preço aceita o mesmo número nas duas:
 * `500` é um preço plausível em Gemas e é quase nada em Coins. Quem digita o valor pensando
 * em Gema e não olha o par de botões publica um pokémon de gema por trocado — e o anúncio é
 * comprado em segundos por quem está de olho. Aconteceu duas vezes.
 *
 * Nada no caminho pegava isso: os dois mínimos do mercado são ~2, então o preço "errado" é
 * perfeitamente válido, e o resumo de taxa/líquido fala na moeda escolhida sem dizer que a
 * escolha pode ter sido sem querer.
 *
 * ### Por que em TODO anúncio, item incluído
 *
 * Começou só em pokémon (o caso relatado) e diamante (o mesmo dedo no mesmo botão, com
 * dinheiro de verdade por trás); item ficava de fora para o aviso não virar rotina. Só que item
 * também vale gema — Casa e Bicicleta Lendária, Boss Token, peça de TM —, e anunciar um desses
 * por trocado dá o mesmo prejuízo do pokémon. Uma confirmação a mais para quem vende em Coins de
 * propósito custa menos que um item de gema vendido por engano.
 *
 * ### Por que não tem um botão "trocar para Gemas"
 *
 * O seletor está logo atrás desta caixa, a um toque. Um terceiro botão aqui empurraria a
 * decisão para o diálogo e deixaria a tela de trás parecendo enfeite — e "Cancelar" já leva
 * exatamente para onde a correção acontece. O texto diz isso com todas as letras.
 */
function avisarAnuncioEmCoins({ nome, preco, qtd = 1, aoSeguir }) {
  const total = preco * (qtd || 1);
  const lote = (qtd || 1) > 1;
  const linha = (classe, icone, alt, valor, moedaNome, nota) => `
    <div class="cm-moeda-aviso ${classe}">
      <img src="${icone}" alt="${escapar(alt)}">
      <div>
        <b>${num(valor)} ${escapar(moedaNome)}</b>
        <span>${nota}</span>
      </div>
    </div>`;
  confirmar({
    largura: 'larga',
    titulo: t('cm.coinsTitulo'),
    texto: `
      <p class="cm-coins-intro">${t('cm.coinsIntro', { nome: `<b>${escapar(nome ?? '')}</b>` })}</p>
      ${linha('sim', srcIcone(ICONE_OURO), t('cm.emCoins'), total, t('cm.emCoins'), t('cm.coinsEhJogo'))}
      ${linha('nao', ICONE_GEMA, t('cm.emGemas'), total, t('cm.emGemas'), t('cm.coinsNaoEhGema'))}
      ${lote ? `<p class="cm-coins-lote">${t('cm.coinsLote', { qtd: num(qtd), unit: num(preco) })}</p>` : ''}
      <p class="cm-coins-saida">${t('cm.coinsComoTrocar')}</p>`,
    rotuloSim: t('cm.coinsSim'),
    aoConfirmar: aoSeguir,
  });
}

/**
 * A BARRACA da feira: o toldo listrado, quem está à venda e as duas plaquinhas — o preço
 * pendurado à direita e o selo à esquerda (os dias da pensão, o tamanho do lote, o estoque).
 *
 * É o MESMO desenho em toda folha do Mercado (anunciar, editar, comprar, os dias da feira): a feira
 * é uma só, e quem já viu o bicho debaixo do toldo entende de relance que está numa venda. Nasceu
 * como o desenho da pensão ("não fica numa prateleira: fica na feira, e os tratadores cuidam
 * dele"). `idPlaca`/`idSelo` deixam a folha repintar as plaquinhas enquanto o jogador mexe.
 */
function barraca({ ator, placa = '', selo = '', idPlaca = '', idSelo = '', compacta = false }) {
  return `
    <div class="dlg-palco tom-ouro dlg-feira${compacta ? ' compacta' : ''}">
      <span class="dlg-toldo" aria-hidden="true"></span>
      ${ator}
      <span class="dlg-placa"${idPlaca ? ` id="${idPlaca}"` : ''}>${placa}</span>
      <span class="dlg-placa-dias"${idSelo ? ` id="${idSelo}"` : ''}>${selo}</span>
    </div>`;
}

/**
 * A plaquinha do PREÇO: a moeda e o número, "/un." quando é preço de lote — e, na edição, o preço
 * de antes riscado em cima, enquanto ele for diferente do novo.
 */
const placaDePreco = (preco, moeda, { porUn = false, era = null } = {}) => `
  ${era != null && era !== preco ? `<s>${num(era)}</s>` : ''}
  <img src="${moeda === 'orb' ? ICONE_GEMA : srcIcone(ICONE_OURO)}" alt="">${num(preco)}${porUn ? `<small>${escapar(t('cm.porUnCurto'))}</small>` : ''}`;

/** A barraca da folha dos DIAS (a pensão do pokémon anunciado). */
function barracaDaFeira({ pk = null, preco = null, moeda = 'gold', dias = null }) {
  return barraca({
    ator: pk
      ? dlgAtor({
        arte: dlgArtePk(pk, 64),
        nome: nomePkHtml(pk),
        sub: dlgSeloShiny(pk.shiny) + dlgNivel(pk.level),
        classe: 'novo',
      })
      : dlgAtor({ arte: dlgArteHtml(dlgMedalha({ icone: 'moedas', tom: 'ouro' })), classe: 'novo' }),
    placa: preco != null ? placaDePreco(preco, moeda) : '',
    selo: dias != null ? diasNaFeira(dias) : '',
    idSelo: 'cm-dias-selo',
  });
}

/**
 * A arte de quem vai à feira num anúncio NOVO (o `alvo` do passo do preço): o pokémon animado, o
 * diamante, a caixa, ou o ícone do item — casa e bicicleta numeradas são itens com desenho próprio.
 */
function arteDoAlvoAnuncio(alvo) {
  if (alvo.tipo === 'pokemon' && alvo.pk) return dlgArtePk(alvo.pk, 52);
  if (alvo.tipo === 'diamante') return dlgArteArquivo(ICONE_DIAMANTE, 44);
  if (alvo.caixaId) return dlgArteArquivo(`/img/itens/caixa-${alvo.caixaTipo ?? 'fundador'}.png`, 52, true);
  if (alvo.itemId) return dlgArteItem(alvo.itemId, 44);
  return dlgArteArquivo(ICONE_ITEM_GENERICO, 40);
}

/**
 * O ator da barraca para um anúncio que JÁ existe (editar, comprar): a ficha congelada nele. A arte
 * do item é a do card (`arteItemAnuncio`) e é um NÓ — entra por `penduraArteDoAnuncio`.
 */
function atorDoAnuncio(a, { sub = '' } = {}) {
  const pokemon = a.tipo === 'pokemon';
  const nome = pokemon ? nomeNoAnuncio(a.ficha) : ehAnuncioDiamante(a) ? t('cm.diamantes') : nomeAnuncioItem(a);
  return dlgAtor({
    arte: pokemon ? dlgArtePk(a.ficha, 52) : '<span class="dlg-ator-fig" data-dlg-anuncio></span>',
    nome: escapar(nome || '—'),
    sub: (pokemon ? dlgSeloShiny(a.ficha?.shiny) + dlgNivel(a.ficha?.level ?? 1) : '') + sub,
    classe: 'novo',
  });
}
const penduraArteDoAnuncio = (raiz, a, px = 56) => raiz?.querySelector('[data-dlg-anuncio]')?.appendChild(arteItemAnuncio(a, px));

/**
 * O RECIBO do anúncio: o total do lote, a mordida da taxa e o que cai na sua mão — uma conta por
 * linha, a última grande e verde. Era uma frase ("Total: 104 Coins · taxa de 15% · você recebe
 * 88"), e a frase escondia justamente o número que decide o preço.
 *
 * No POKÉMON em gema a alíquota depende do TOTAL (faixa marginal), então a linha mostra a efetiva
 * daquele total; item e diamante têm alíquota única. Preço que não deixa nem 1 de líquido vira o
 * aviso do mínimo, e o Publicar desliga (quem faz isso é o passo do preço).
 */
function reciboAnuncioHtml({ moeda, preco, qtd = 1, tipo }) {
  const orb = moeda === 'orb';
  const total = qtd * preco;
  const taxaPct = orb ? pctEfetivoOrb(total, tipo) : taxaGoldCliente() * 100;
  const liq = totalLiquidoMercado(preco, qtd, moeda, tipo);
  if (liq < 1) {
    return dlgAviso(t(orb ? 'cm.resumoOrbBaixo' : 'cm.resumoGoldBaixo', {
      min: num(precoMinMercado(moeda)), taxa: pctTaxa(taxaPct),
    }), { tom: 'ouro' });
  }
  const ico = `<img src="${orb ? ICONE_GEMA : srcIcone(ICONE_OURO)}" alt="">`;
  return `
    <div class="dlg-recibo">
      <div class="dlg-recibo-linha">
        <span>${escapar(t('cm.reciboTotal'))}${qtd > 1 ? `<small>${num(qtd)} × ${num(preco)}</small>` : ''}</span>
        <b>${ico}${num(total)}</b>
      </div>
      <div class="dlg-recibo-linha menos">
        <span>${escapar(t('cm.reciboTaxa', { pct: pctTaxa(taxaPct) }))}<small>${escapar(t('cm.reciboTaxaSub'))}</small></span>
        <b>−${num(total - liq)}</b>
      </div>
      <div class="dlg-recibo-linha fim">
        <span>${escapar(t('cm.reciboRecebe'))}</span>
        <b>${ico}${num(liq)}</b>
      </div>
    </div>`;
}

/**
 * As RÉGUAS DE PREÇO como botões: o menor anúncio aberto e a média vendida nos últimos 7 dias, na
 * moeda escolhida. Um toque copia o número para o campo — é a conta que todo vendedor faz de
 * cabeça ("vou pôr um pouco abaixo do menor"), sem precisar redigitar 109.000.
 *
 * `estado.cmItens` (o menor anúncio) e a média chegam depois da folha abrir; quem repinta quando
 * eles chegam é o `cmPassoPrecoAtualizar`.
 */
function refsDePrecoHtml({ itemId = null, diamante = false }, moeda) {
  const orb = moeda === 'orb';
  const icone = `<img src="${orb ? ICONE_GEMA : srcIcone(ICONE_OURO)}" alt="">`;
  const chip = (rotulo, valor, sub = '') => `
    <button type="button" class="dlg-ref" data-usar-preco="${Math.round(valor)}">
      <span class="dlg-ref-rot">${escapar(rotulo)}${sub ? `<small>${escapar(sub)}</small>` : ''}</span>
      <span class="dlg-ref-v">${icone}${num(Math.round(valor))}</span>
      <span class="dlg-ref-usar">${escapar(t('cm.refUsar'))}</span>
    </button>`;
  const vazio = (texto) => `<span class="dlg-ref vazio">${escapar(texto)}</span>`;
  // Com o resumo a caminho (`cmMedias` zerado no pedido), afirmar "ninguém anuncia" seria mentir
  // por meio segundo: os dois lugares esperam com reticências.
  if (itemId && estado.cmMedias === undefined) return vazio('…') + vazio('…');
  const chips = [];
  if (itemId) {
    const r = estado.cmItens?.[itemId];
    const v = r?.anuncios ? (orb ? r.minOrb : r.minGold) : null;
    if (v != null) chips.push(chip(t('cm.refMenor'), v));
    else if (!r?.anuncios) chips.push(vazio(t('cm.semAnunciosReferencia')));
    else chips.push(vazio(t(orb ? 'cm.semAnunciosMoedaOrb' : 'cm.semAnunciosMoedaGold')));
  }
  const media = diamante ? estado.cmMediaDiamante : itemId ? mediaDoItem(itemId) : undefined;
  if (media !== undefined) {
    const m = orb ? media?.orb : media?.gold;
    if (m) chips.push(chip(t('cm.refMedia'), m.media, t(diamante ? 'cm.refMediaSubDiamante' : 'cm.refMediaSub', { u: num(m.unidades) })));
    else chips.push(vazio(t(orb ? 'cm.semVendas7dOrb' : 'cm.semVendas7dGold')));
  }
  return chips.join('');
}

/** "1 dia" / "7 dias" — o `t()` não tem plural automático. */
const diasNaFeira = (n) => t(n === 1 ? 'cm.diaN' : 'cm.diasN', { n: num(n) });

/**
 * Por quantos dias o anúncio fica de pé — e quanto isso custa.
 *
 * A diária é sempre em Coins, mesmo quando o anúncio cobra em gema (ver `TAXA_DIARIA` no
 * servidor). O total anda junto com o cursor e o botão morre se o saldo não cobre: descobrir
 * que faltava ouro só depois de confirmar seria descobrir tarde.
 *
 * O prazo se escolhe de três jeitos, e cada um serve a um jogador: o − e o + para o ajuste fino,
 * os atalhos para quem pensa em "uma semana", e a barra para arrastar. Os três mexem no MESMO
 * `input[type=range]`, que continua sendo o valor de verdade.
 */
function abrirDiasAnuncio(aoConfirmar, { pk = null, preco = null, moeda = 'gold' } = {}) {
  const reg = estado.mercado ?? {};
  const diaria = reg.taxaDiaria ?? 100000;
  const dMin = reg.diasMin ?? 1;
  const dMax = reg.diasMax ?? 30;
  const saldo = Math.floor(estado.eu?.gold ?? 0);
  // Os prazos em que se pensa: um dia, um fim de semana, uma semana, quinze dias, o mês — só os
  // que cabem na faixa que o servidor aceita.
  const atalhos = [...new Set([dMin, 3, 7, 15, dMax])]
    .filter((d) => d >= dMin && d <= dMax)
    .sort((a, b) => a - b);
  const custo = (dias) => dlgCusto({
    moeda: 'ouro',
    valor: diaria * dias,
    saldo,
    rotulo: t('cm.diasPensao'),
    extra: `${num(diaria)} × ${num(dias)}`,
  });
  // As duas regras que o prazo decide, em selo: o que se perde se vender cedo, e o que acontece
  // se ninguém levar. São as mesmas da confirmação que vem depois — lidas aqui, onde se escolhe.
  const regras = (dias) => dlgSelos(
    dlgSelo('moedas', escapar(t('cm.diasSeloPago')), 'perigo'),
    dlgSelo('volta', escapar(t('cm.diasSeloVolta', { dias: diasNaFeira(dias) })), 'bom'),
  );

  const { corpo, fechar } = folhaMercado(t('cm.diasTitulo'));
  corpo.innerHTML = `
    ${barracaDaFeira({ pk, preco, moeda, dias: dMin })}
    <p class="dlg-sub">${t('cm.diasLead')}</p>
    <div class="dlg-dias">
      <span class="dlg-dias-rot">${dlgIcone('calendario', 15)}${t('cm.diasQuantos')}</span>
      <div class="dlg-dias-linha">
        <button type="button" class="mk-passo" data-passo="-1" aria-label="−1">−</button>
        <span class="dlg-dias-num"><b id="cm-dias-v">${dMin}</b><small id="cm-dias-un"></small></span>
        <button type="button" class="mk-passo" data-passo="1" aria-label="+1">+</button>
      </div>
      <input type="range" class="qtd-barra" id="cm-dias" min="${dMin}" max="${dMax}" step="1" value="${dMin}"
             aria-label="${escapar(t('cm.diasQuantos'))}">
      <div class="qtd-atalhos">${atalhos.map((d) =>
        `<button type="button" class="qtd-atalho" data-dias="${d}">${diasNaFeira(d)}</button>`).join('')}</div>
    </div>
    <div id="cm-dias-resumo"></div>
    <div id="cm-dias-regras"></div>
    ${avisoRetencaoAnuncio()}
    <div class="confirmar-botoes dlg-botoes">
      <button type="button" class="btn-apagado" id="cm-dias-cancelar">${t('cm.cancelar')}</button>
      <button type="button" id="cm-dias-ok">${t('cm.publicar')}</button>
    </div>`;
  hidratarDialogo(corpo);

  const faixa = corpo.querySelector('#cm-dias');
  const ok = corpo.querySelector('#cm-dias-ok');
  const pintar = () => {
    const dias = Number(faixa.value);
    const cabe = diaria * dias <= saldo;
    corpo.querySelector('#cm-dias-v').textContent = num(dias);
    corpo.querySelector('#cm-dias-un').textContent = t(dias === 1 ? 'cm.diaUm' : 'cm.diasVarios');
    corpo.querySelector('#cm-dias-selo').textContent = diasNaFeira(dias);
    corpo.querySelector('#cm-dias-resumo').innerHTML = custo(dias)
      + (cabe ? '' : `<p class="cm-erro dlg-erro">${t('cm.diasSemSaldo')}</p>`);
    corpo.querySelector('#cm-dias-regras').innerHTML = regras(dias);
    for (const b of corpo.querySelectorAll('[data-dias]')) b.classList.toggle('on', Number(b.dataset.dias) === dias);
    ok.disabled = !cabe;
  };
  faixa.oninput = pintar;
  corpo.querySelector('.dlg-dias').onclick = (ev) => {
    const passo = ev.target.closest('[data-passo]');
    const atalho = ev.target.closest('[data-dias]');
    if (!passo && !atalho) return;
    const alvo = atalho ? Number(atalho.dataset.dias) : Number(faixa.value) + Number(passo.dataset.passo);
    faixa.value = String(Math.min(dMax, Math.max(dMin, alvo)));
    pintar();
  };
  pintar();

  corpo.querySelector('#cm-dias-cancelar').onclick = fechar;

  // Última parada antes de publicar. O que precisa estar dito aqui é o que o jogador não
  // consegue desfazer: vender no primeiro dia NÃO devolve os outros dias já pagos, e não
  // vender devolve a mercadoria (mas não o aluguel). Descobrir isso depois de pagar 30 dias
  // e vender em duas horas seria descobrir tarde.
  ok.onclick = () => {
    const dias = Number(faixa.value);
    fechar();
    confirmar({
      titulo: t('cm.confirmaTitulo', { dias: diasNaFeira(dias) }),
      texto: `
        ${barracaDaFeira({ pk, preco, moeda, dias })}
        ${custo(dias)}
        ${regras(dias)}`,
      rotuloSim: t('cm.publicar'),
      aoConfirmar: () => aoConfirmar(dias),
    });
  };
}

/**
 * Comprar UMA FATIA de um lote.
 *
 * O anúncio é estoque, não pacote fechado: quem anunciou 100 Water Stone a 200 cada não está
 * pedindo 20.000 de uma pessoa só. A folha abre em 1 unidade — quem quiser mais ajusta na
 * barra; "Tudo" e 100% limitam ao que o saldo cobre, não ao estoque inteiro do vendedor.
 */
function abrirCompra(a) {
  if (anuncioEmRetencao(a)) {
    toast(t('cm.retencaoComprar'));
    return;
  }
  const { corpo, fechar } = folhaMercado(t('cm.comprarTitulo'));
  const saldo = a.moeda === 'orb' ? estado.eu?.orbs ?? 0 : estado.eu?.gold ?? 0;
  // A caixa é peça única: não há fatia que faça sentido pedir, e a linha de estoque ("1 em
  // estoque") diria menos que o número dela. No lugar das duas vai a série e o que vem dentro.
  const caixaTipo = a.ficha?.caixaId ? a.ficha.caixaTipo : null;
  // A casa, idem: peça única com número, sem estoque para mostrar.
  const ehCasa = !!a.ficha?.casaId;
  // A bicicleta também: peça única com número.
  const ehBike = !!a.ficha?.bicicletaId;

  // A barraca de quem vende: a mercadoria debaixo do toldo, o preço da unidade pendurado e o
  // estoque no selo do outro lado. A peça numerada (caixa, casa, bicicleta) leva o número como sub.
  const unica = caixaTipo || ehCasa || ehBike;
  corpo.innerHTML = `
    ${barraca({
      ator: dlgAtor({
        arte: a.tipo === 'pokemon' ? dlgArtePk(a.ficha, 52) : '<span class="dlg-ator-fig" data-dlg-anuncio></span>',
        nome: escapar(
          caixaTipo ? t(`caixas.nome.${caixaTipo}`)
            : ehCasa ? nomeCasaRaridade(a.ficha.casaRaridade)
            : ehBike ? nomeBicicletaRaridade(a.ficha.bicicletaRaridade)
              : ehAnuncioDiamante(a) ? t('cm.diamantes')
                : nomeNoAnuncio(a.ficha),
        ),
        sub: `${numeroDoAnuncio(a) ? plaquinhaDoAnuncio(a) : ''}<span class="dlg-vendedor">${t('cm.de')} <b>${escapar(a.vendedor)}</b></span>`,
        classe: 'novo',
      }),
      placa: placaDePreco(a.preco, a.moeda, { porUn: !unica }),
      selo: unica ? '' : t('cm.emEstoque', { n: num(a.qtd) }),
      compacta: true,
    })}
    ${caixaTipo
      ? `<p class="cm-passo-txt">${escapar(t('caixas.vemDentro'))}</p>
         ${conteudoDaCaixaHtml(caixaTipo, { serie: a.ficha.serie })}
         <p class="cm-nota">${escapar(t('caixas.compraFechada'))}</p>`
      : ehCasa ? `<p class="cm-nota">${escapar(t('casa.compraVazia'))}</p>` : ''}
    <div class="cm-form">
      <div id="cm-qtd-host"></div>
      <div id="cm-resumo"></div>
      <button class="cm-publicar" id="cm-confirmar">${t('cm.comprar')}</button>
    </div>`;
  hidratarDialogo(corpo);
  penduraArteDoAnuncio(corpo, a, 44);
  if (caixaTipo) pintarConteudoDaCaixa(corpo);

  const resumo = corpo.querySelector('#cm-resumo');
  const botao = corpo.querySelector('#cm-confirmar');
  // A etiqueta de preço do diálogo de jogo: o total da compra e o saldo antes → depois, vermelha
  // quando não cobre — e a conta "3 × 120.000" embaixo do número, que era a frase de antes.
  const etiqueta = (n) => dlgCusto({
    moeda: a.moeda === 'orb' ? 'gema' : 'ouro',
    valor: n * a.preco,
    saldo: Math.floor(saldo),
    extra: n > 1 ? `${num(n)} × ${num(a.preco)}` : '',
  });

  // Caixa e casa são peça única: sem seletor de quantidade ("até 1" é só ruído), compra de uma.
  if (unica) {
    const falta = a.preco > saldo;
    resumo.innerHTML = etiqueta(1);
    botao.disabled = falta;
    botao.onclick = () => {
      enviar({ t: 'market.comprar', id: a.id, qtd: 1, preco: a.preco, moeda: a.moeda });
      fechar();
    };
    return;
  }

  const maxCompra = maxCompraMercado(a.preco, a.moeda, a.qtd);
  const seletor = seletorQuantidade(corpo.querySelector('#cm-qtd-host'), {
    max: Math.max(1, maxCompra),
    inicial: 1,
    rotulo: t('cm.quantosComprar'),
    aoMudar: (n) => {
      const total = n * a.preco;
      const falta = total > saldo || maxCompra < 1;
      resumo.innerHTML = etiqueta(n);
      // Desabilitar em vez de deixar o servidor recusar: o "não" fica visível ANTES do clique.
      botao.disabled = falta;
    },
  });

  botao.onclick = () => {
    enviar({ t: 'market.comprar', id: a.id, qtd: seletor.ler(), preco: a.preco, moeda: a.moeda });
    fechar();
  };
}

/** Editar só mexe em preço e moeda — trocar quantidade é cancelar e reanunciar. */
function abrirEdicao(a) {
  if (anuncioEmRetencao(a)) {
    toast(t('cm.retencaoEditar'));
    return;
  }
  const { corpo, fechar } = folhaMercado(t('cm.editarTitulo'));
  // A mesma barraca do anúncio novo, com o preço de HOJE riscado na placa enquanto o novo for
  // diferente: editar é comparar os dois, e a placa é onde o comprador vai ler.
  const lote = (a.qtd ?? 1) > 1;
  corpo.innerHTML = `
    ${barraca({ ator: atorDoAnuncio(a), idPlaca: 'cm-placa', selo: lote ? `×${num(a.qtd)}` : '', compacta: true })}
    <div class="cm-form">
      <label>${t('cm.precoUnit')}
        <input id="cm-preco" type="number" value="${a.preco}" min="1" inputmode="numeric">
        <em></em>
      </label>
      ${a.itemId || ehAnuncioDiamante(a) ? '<div class="dlg-refs" id="cm-preco-refs"></div>' : ''}
      ${htmlMoedasAnuncio(a.moeda)}
      <div id="cm-resumo"></div>
      ${avisoRetencaoAnuncio()}
      <button class="cm-publicar" id="cm-salvar">${t('cm.salvar')}</button>
    </div>`;
  hidratarDialogo(corpo);
  penduraArteDoAnuncio(corpo, a, 44);
  let moedaEscolhida = a.moeda;
  const inpPreco = corpo.querySelector('#cm-preco');
  const minMoeda = () => precoMinMercado(moedaEscolhida);
  const precoDe = () => Math.max(minMoeda(), Math.floor(Number(inpPreco?.value)) || 1);
  const atualizar = () => {
    if (!corpo.isConnected) {
      cmPassoPrecoAtualizar = null;
      return;
    }
    const preco = precoDe();
    inpPreco.min = String(minMoeda());
    const ajuda = corpo.querySelector('label em');
    if (ajuda) ajuda.textContent = ajudaPrecoMercado(moedaEscolhida, null, a.tipo);
    const refs = corpo.querySelector('#cm-preco-refs');
    if (refs) refs.innerHTML = refsDePrecoHtml({ itemId: a.itemId, diamante: ehAnuncioDiamante(a) }, moedaEscolhida);
    // O "era" só faz sentido na MESMA moeda: trocar de Coins para Gemas não é baixar o preço.
    corpo.querySelector('#cm-placa').innerHTML = placaDePreco(preco, moedaEscolhida, {
      porUn: lote, era: moedaEscolhida === a.moeda ? a.preco : null,
    });
    corpo.querySelector('#cm-resumo').innerHTML = reciboAnuncioHtml({
      moeda: moedaEscolhida, preco, qtd: a.qtd ?? 1, tipo: a.tipo,
    });
    corpo.querySelector('#cm-salvar').disabled =
      totalLiquidoMercado(preco, a.qtd ?? 1, moedaEscolhida, a.tipo) < 1;
  };
  corpo.querySelector('#cm-preco-refs')?.addEventListener('click', (ev) => {
    const b = ev.target.closest('[data-usar-preco]');
    if (!b) return;
    inpPreco.value = String(Math.max(minMoeda(), Math.round(Number(b.dataset.usarPreco) || 0)));
    atualizar();
  });
  corpo.querySelector('.cm-moedas').onclick = (ev) => {
    const b = ev.target.closest('.cm-moeda');
    if (!b) return;
    moedaEscolhida = b.dataset.moeda;
    for (const outro of b.parentElement.children) outro.classList.toggle('on', outro === b);
    if (moedaEscolhida === 'orb' && Number(inpPreco.value) < precoMinOrb()) inpPreco.value = precoMinOrb();
    if (moedaEscolhida === 'gold' && Number(inpPreco.value) < precoMinGold()) inpPreco.value = precoMinGold();
    atualizar();
  };
  inpPreco.oninput = atualizar;
  atualizar();
  // As réguas (menor anúncio, média vendida) vêm do resumo do catálogo — o mesmo pedido do
  // anúncio novo. A resposta repinta esta folha pelo `cmPassoPrecoAtualizar`.
  if (a.itemId) {
    cmPassoPrecoAtualizar = atualizar;
    estado.cmMedias = undefined;
    enviar({ t: 'market.itens' });
  }
  corpo.querySelector('#cm-salvar').onclick = () => {
    const salvar = () => {
      enviar({ t: 'market.editar', id: a.id, preco: precoDe(), moeda: moedaEscolhida });
      fechar();
    };
    // Aqui o aviso só aparece na TROCA de gema para coin: editar um anúncio que já era em
    // Coins é mexer no preço, e avisar nisso seria só barulho. O que se está desfazendo com um
    // toque é a decisão de vender em gema — e é isso que merece a pergunta.
    if (moedaEscolhida === 'gold' && a.moeda !== 'gold' && (a.tipo === 'pokemon' || a.tipo === 'diamante')) {
      return avisarAnuncioEmCoins({
        nome: nomeNoAnuncio(a.ficha), preco: precoDe(), qtd: a.qtd ?? 1, aoSeguir: salvar,
      });
    }
    salvar();
  };
}

/**
 * TROCAR DE PÁGINA DEVOLVE A VITRINE AO TOPO — e mostra que devolveu.
 *
 * Sem isto, quem rolava até o fim da página 1 para achar o botão "›" caía na página 2 na mesma
 * altura de rolagem: os primeiros doze anúncios da página nova nasciam ACIMA da dobra, e a tela
 * parecia não ter mudado. O jogador rolava para cima à mão toda vez, ou — pior — concluía que o
 * botão não tinha funcionado e apertava de novo, pulando uma página.
 *
 * São duas metades, e as duas são necessárias:
 *
 *   · a ROLAGEM sobe suave (`behavior: 'smooth'`), e ela começa no CLIQUE, antes de a resposta
 *     do servidor chegar. É o movimento que diz "eu te ouvi" no meio segundo em que a vitrine
 *     ainda mostra a página velha;
 *   · a lista nova ENTRA subindo (`.cm-subindo`, a animação `cm-subir` no estilo). Só a rolagem
 *     não bastaria para quem já estava no topo — trocar de página lá em cima não move nada, e
 *     o card de baixo trocando de conteúdo em silêncio é justamente o que a pessoa não vê.
 *
 * A classe é REMOVIDA antes de ser posta de novo (com um reflow no meio) porque trocar de
 * página duas vezes seguidas reusa o mesmo elemento: sem isso o navegador entende que a
 * animação já está rodando e a segunda troca não anima nada.
 */
function subirVitrineAoTopo() {
  const lista = $('#cm-lista');
  if (!lista) return;
  // `behavior: 'smooth'` EXPLÍCITO vence o `scroll-behavior` do CSS, então a preferência de
  // menos movimento não pode ser respeitada só na folha de estilo — é lida aqui.
  const behavior = matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';
  // A grade é o que rola (`overflow-y: auto` no `.cm-lista`), mas a folha do celular e o corpo
  // do modal também podem estar rolados — subir só a de dentro deixaria o topo da vitrine
  // escondido atrás da barra de filtros. Sobe todo mundo até a caixa do modal.
  for (let el = lista; el && el !== document.body; el = el.parentElement) {
    if (el.scrollTop > 0) el.scrollTo({ top: 0, behavior });
    if (el.classList?.contains('modal-caixa')) break;
  }
}

/** Marca que a próxima pintura da vitrine é uma troca de página, e deve entrar subindo. */
let vitrineVaiSubir = false;

/** A entrada da página nova. Chamada pelo `pintarMercado`, depois de a grade existir. */
function animarEntradaDaVitrine() {
  if (!vitrineVaiSubir) return;
  // A pintura do "…" não é a página nova, é a espera. Animar aqui gastaria a marca com o
  // placeholder e a grade de verdade entraria sem movimento nenhum meio segundo depois.
  if (estado.cmDados?.carregando) return;
  vitrineVaiSubir = false;
  const lista = $('#cm-lista');
  if (!lista) return;
  lista.classList.remove('cm-subindo');
  void lista.offsetWidth; // reinicia a animação quando a troca é repetida
  lista.classList.add('cm-subindo');
}

/** Troca a página da vitrine: pede a nova e já começa a subir. */
function irParaPaginaDoMercado(passo) {
  estado.cmPagina = Math.max(0, estado.cmPagina + passo);
  vitrineVaiSubir = true;
  subirVitrineAoTopo();
  pedirMercado();
}

function pintarPaginas() {
  const host = $('#cm-paginas');
  if (!host) return;
  // Pela mesma porta da grade: a contagem de páginas de uma vitrine não vale na outra, e
  // enquanto a resposta nova não chega é melhor não desenhar paginação nenhuma.
  const d = dadosDaGradeCerta();
  if (estado.cmAba !== 'vitrine' || !d.total || d.total <= (d.porPagina ?? 24)) {
    host.innerHTML = '';
    return;
  }
  const paginas = Math.ceil(d.total / d.porPagina);
  host.innerHTML = `
    <button class="cm-pag" data-ir="-1" ${d.pagina <= 0 ? 'disabled' : ''}>‹</button>
    <span>${t('cm.paginaDe', { a: d.pagina + 1, b: paginas })}</span>
    <button class="cm-pag" data-ir="1" ${d.pagina + 1 >= paginas ? 'disabled' : ''}>›</button>`;
  host.onclick = (ev) => {
    const b = ev.target.closest('.cm-pag');
    if (!b || b.disabled) return;
    irParaPaginaDoMercado(Number(b.dataset.ir));
  };
}

const localeData = () => ({ pt: 'pt-BR', en: 'en-US', es: 'es-ES' }[idioma()] ?? 'pt-BR');

const formatarDataHora = (ms) =>
  ms
    ? new Date(ms).toLocaleString(localeData(), {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      })
    : '—';
const formatarDataCaptura = (ms) =>
  ms ? new Date(ms).toLocaleDateString(localeData(), { day: '2-digit', month: '2-digit', year: 'numeric' }) : '—';

/** Data de captura/nascimento — aceita `caughtAt` ou legado `capturadoEm` (registro). */
const caughtAtDoPokemon = (pk) => pk?.caughtAt ?? pk?.capturadoEm ?? null;

/**
 * O TREINADOR que capturou este bicho, como nome na tela. `null` quando não se sabe.
 *
 * `caughtBy === true` é o sentinela do servidor para "quem capturou é o dono de hoje" — ele o
 * manda assim em vez do nick porque o nick já está aqui, e repeti-lo nos ~300 bichos de uma
 * coleção seria peso de rede por nada (ver `capturadorDaLinha` em `server/db.mjs`). Quem
 * resolve o sentinela é esta linha: `pk.dono` nas fichas de outros jogadores (ranking, guild,
 * perfil, Registro), e o próprio nick na coleção de quem está olhando.
 *
 * Uma string é o nick de OUTRO treinador — o bicho mudou de mão no Mercado, e é exatamente o
 * caso que a linha existe para contar. Ausente é pokémon anterior à coluna `caught_by`: a ficha
 * omite a linha em vez de chutar que foi o dono atual.
 */
const capturadorDoPokemon = (pk) =>
  pk?.caughtBy === true ? (pk.dono ?? estado.eu?.nick ?? null) : (pk?.caughtBy || null);

/** Linha de data/hora nas vitrines globais de shiny e P5 da Pokédex. */
const subDataCapturaRegistro = (s) => {
  const ms = caughtAtDoPokemon(s);
  if (!ms) return '';
  return `<div class="cm-sub shl-captura">${t('dex.capturadoEm')} ${formatarDataHora(ms)}</div>`;
};

/**
 * Os três históricos do Mercado, na mesma folha.
 *
 * `vendas` e `compras` são o extrato do próprio jogador. `global` é a TABELA DE PREÇOS: as
 * vendas mais recentes do servidor inteiro, de todo mundo, que é a única referência que existe
 * para saber por quanto anunciar um pokémon (item tem o preço do NPC no próprio card; pokémon
 * não tem nada).
 */
const HIST_MODOS = {
  vendas: { msg: 'market.historico', titulo: 'cm.historicoTitulo', vazio: 'cm.historicoVazio' },
  compras: { msg: 'market.historicoCompras', titulo: 'cm.historicoComprasTitulo', vazio: 'cm.historicoComprasVazio' },
  global: { msg: 'market.historicoGlobal', titulo: 'cm.historicoGlobalTitulo', vazio: 'cm.historicoGlobalVazio' },
};

const HIST_MODO_POR_ABA = {
  historico: 'vendas',
  historicoCompras: 'compras',
  historicoGlobal: 'global',
};

function pedirHistoricoMercado() {
  const modo = HIST_MODOS[estado.cmHistModo] ?? HIST_MODOS.vendas;
  const msg = { t: modo.msg, pagina: estado.cmHistPagina };
  if (estado.cmHistModo === 'global') {
    const tipo = estado.cmHistFiltroTipo;
    if (tipo) msg.tipo = tipo;
    // Depósito e saque são sempre em gema e não têm item: os dois recortes só descem nas vendas.
    if (estado.cmHistFiltroMoeda && tipo !== 'deposito' && tipo !== 'saque') msg.moeda = estado.cmHistFiltroMoeda;
    if (tipo === 'item' && estado.cmHistFiltroFav) msg.favoritos = 1;
    else if (tipo === 'item' && estado.cmHistFiltroItem) msg.itemId = estado.cmHistFiltroItem;
  }
  enviar(msg);
}

function abrirHistoricoMercado(qual) {
  estado.cmHistModo = qual;
  estado.cmHistPagina = 0;
  estado.cmHistFiltroTipo = '';
  estado.cmHistFiltroMoeda = '';
  estado.cmHistFiltroItem = 0;
  estado.cmHistFiltroFav = false;
  estado.cmHistDados = null;
  const { corpo } = folhaMercado(t(HIST_MODOS[qual].titulo));
  // `cm-hist-global` é o que dá à Tabela de preços a folha grande (ver o estilo); os dois
  // extratos pessoais seguem na folha de 600 px.
  corpo.innerHTML = `<div class="cm-hist${qual === 'global' ? ' cm-hist-global' : ''}" id="cm-hist-corpo"></div>`;
  pedirHistoricoMercado();
  pintarHistoricoMercado();
}

const abrirHistoricoVendas = () => abrirHistoricoMercado('vendas');
const abrirHistoricoCompras = () => abrirHistoricoMercado('compras');
const abrirHistoricoGlobal = () => abrirHistoricoMercado('global');

const chaveAjudaHistoricoGlobal = (filtro) =>
  filtro === 'deposito'
    ? 'cm.historicoDepositosAjuda'
    : filtro === 'saque'
      ? 'cm.historicoSaquesAjuda'
      : 'cm.historicoGlobalAjuda';

const chaveVazioHistoricoGlobal = (filtro) =>
  filtro === 'deposito'
    ? 'cm.historicoDepositoVazio'
    : filtro === 'saque'
      ? 'cm.historicoSaqueVazio'
      : estado.cmHistFiltroFav
        ? 'cm.historicoFavVazio'
        : estado.cmHistFiltroMoeda || estado.cmHistFiltroItem
          ? 'cm.historicoFiltroVazio'
          : 'cm.historicoGlobalVazio';

const itemHistoricoGlobal = (l) => {
  if (l.tipo === 'deposito') {
    return `<span class="cm-hist-orb">${seloGema(14)} ${t('cm.histDeposito')} · ${usd(l.usdt)} · ${escapar(l.rede ?? '')}</span>`;
  }
  if (l.tipo === 'saque') {
    const st =
      l.status && l.status !== 'confirmado'
        ? ` · <span class="cm-hist-orb-st">${t(ROTULO_STATUS[l.status] ?? l.status)}</span>`
        : '';
    return `<span class="cm-hist-orb">${seloGema(14)} ${t('cm.histSaque')} · ${usd(l.usdt)} · ${escapar(l.rede ?? '')}${st}</span>`;
  }
  // Os selos P·IV·Q·N só descrevem POKÉMON. A condição segue a mesma que a linha e o `title`
  // desta tabela já usam duas linhas acima (`l.tipo === 'pokemon' && l.ficha`) — sem ela,
  // `selosAtributos` cai no `seloPotencia(… || 1)` e carimba um "P1" na ficha de um item ou num
  // lote de diamantes, que não têm potência nenhuma.
  const selos = l.tipo === 'pokemon' && l.ficha
    ? selosAtributos({ ...l.ficha, nota: notaDoFicha(l.ficha) }, { compacto: true })
    : '';
  // ✨Shiny na frente do nome: na tabela o shiny é o atributo que mais mexe no preço, e sem ele um
  // "Charizard Nv 80" por 40 milhões ao lado de outro por 1 milhão não tem explicação.
  const shiny = l.tipo === 'pokemon' && l.ficha?.shiny ? `<span class="cm-hist-shiny">${t('cm.histShiny')}</span> ` : '';
  return `${shiny}${escapar(l.descricao ?? '—')}${selos}`;
};

const tituloHistoricoGlobal = (l) => {
  if (l.tipo === 'deposito') return `${t('cm.histDeposito')} · ${usd(l.usdt)} · ${l.rede ?? ''}`;
  if (l.tipo === 'saque') return `${t('cm.histSaque')} · ${usd(l.usdt)} · ${l.rede ?? ''}`;
  if (l.tipo === 'pokemon' && l.ficha) return `${l.ficha.shiny ? `${t('cm.histShiny')} ` : ''}${l.descricao ?? ''} · ${t('cm.verFicha')}`;
  return l.descricao ?? '';
};

/** Volta a tabela à primeira página com os filtros de agora e pede de novo. */
function recarregarHistoricoGlobal() {
  estado.cmHistPagina = 0;
  estado.cmHistDados = null;
  pintarHistoricoMercado();
  pedirHistoricoMercado();
}

/**
 * O seletor de UM item na Tabela de preços: todo item que o Mercado da Comunidade negocia, nas
 * categorias e na ordem da vitrine, com os Diamantes no topo — eles são outra aba do Mercado, mas
 * quem procura "por quanto sai um diamante" procura aqui.
 *
 * Os FAVORITOS (a estrela da vitrine de Itens) vêm antes de tudo, de dois jeitos: "todos os meus
 * favoritos" numa tabela só, e cada um no grupo ★, para não ter de rolar seiscentos itens atrás
 * da pedra que se acompanha todo dia. Sem favorito nenhum, a linha ★ fica apagada e diz como ter
 * um — é o único lugar em que a Tabela conta que a estrela existe.
 */
function htmlSeletorItemHistorico() {
  const valor = estado.cmHistFiltroTipo === 'diamante'
    ? 'diamante'
    : estado.cmHistFiltroFav ? 'favoritos' : String(estado.cmHistFiltroItem || '');
  const favs = new Set(favoritosItensMercado());
  const itensFav = catalogoMercado().filter((i) => favs.has(Number(i.id)));
  // O mesmo item aparece duas vezes (no ★ e na categoria dele): só a primeira leva o `selected`.
  let marcado = false;
  const opcao = (i) => {
    const sel = !marcado && valor === String(i.id);
    if (sel) marcado = true;
    return `<option value="${i.id}"${sel ? ' selected' : ''}>${escapar(nomeItem(i))}</option>`;
  };
  const grupoFav = itensFav.length
    ? `<optgroup label="${escapar(t('cm.histFavoritosGrupo'))}">${itensFav.map(opcao).join('')}</optgroup>`
    : '';
  const grupos = CATEGORIAS_ITEM.filter((c) => c.id).map((c) => {
    const itens = catalogoMercado().filter((i) => i.categoria === c.id);
    if (!itens.length) return '';
    return `<optgroup label="${escapar(t(c.nome))}">${itens.map(opcao).join('')}</optgroup>`;
  }).join('');
  return `<div class="cm-hist-barra">
      <span class="cm-hist-barra-tit">${t('cm.historicoItem')}</span>
      <select class="cm-hist-item-sel" id="cm-hist-item">
        <option value=""${!valor ? ' selected' : ''}>${t('cm.histTodosItens')}</option>
        ${itensFav.length
          ? `<option value="favoritos"${valor === 'favoritos' ? ' selected' : ''}>${escapar(t('cm.histFavoritos', { n: itensFav.length }))}</option>`
          : `<option value="" disabled>${escapar(t('cm.histFavoritosNenhum'))}</option>`}
        <option value="diamante"${valor === 'diamante' ? ' selected' : ''}>💎 ${t('cm.diamantes')}</option>
        ${grupoFav}
        ${grupos}
      </select>
    </div>`;
}

function pintarHistoricoMercado() {
  const host = document.querySelector('#cm-hist-corpo');
  if (!host) return;

  const modo = estado.cmHistModo;
  const global = modo === 'global';

  const tipoHist = estado.cmHistFiltroTipo;
  const moedaHist = estado.cmHistFiltroMoeda;
  const filtroGlobal = global
    ? `<div class="cm-hist-topo">
         <p class="cm-hist-nota">${t(chaveAjudaHistoricoGlobal(tipoHist))}</p>
         <div class="cm-hist-barra">
           <span class="cm-hist-barra-tit">${t('cm.tipo')}</span>
           <div class="cm-hist-tipos">
             <button type="button" class="cm-filtro${!tipoHist ? ' on' : ''}" data-hist-tipo="">${t('cm.tudo')}</button>
             ${FILTROS_HIST_GLOBAL.map(
               (x) => `<button type="button" class="cm-filtro${tipoHist === x.id ? ' on' : ''}" data-hist-tipo="${x.id}">
                         <span class="cm-fico" data-ico="${x.ico}" data-ico-px="16"></span>${t(x.nome)}</button>`,
             ).join('')}
           </div>
         </div>
         ${tipoHist === 'deposito' || tipoHist === 'saque'
           ? ''
           : `<div class="cm-hist-barra">
               <span class="cm-hist-barra-tit">${t('cm.moeda')}</span>
               <div class="cm-hist-tipos cm-hist-moedas">
                 <button type="button" class="cm-filtro${!moedaHist ? ' on' : ''}" data-hist-moeda="">${t('cm.histTodasMoedas')}</button>
                 ${FILTROS_MOEDA.map(
                   (x) => `<button type="button" class="cm-filtro${moedaHist === x.id ? ' on' : ''}" data-hist-moeda="${x.id}">
                             <span class="cm-fico" data-ico="${x.ico}" data-ico-px="16"></span>${t(x.nome)}</button>`,
                 ).join('')}
               </div>
             </div>`}
         ${tipoHist === 'item' || tipoHist === 'diamante' ? htmlSeletorItemHistorico() : ''}
       </div>`
    : '';

  const ligarFiltroGlobal = () => {
    host.querySelectorAll('[data-ico]').forEach((el) => pintarIcone(el));
    host.querySelector('.cm-hist-tipos')?.addEventListener('click', (ev) => {
      const b = ev.target.closest('[data-hist-tipo]');
      if (!b) return;
      const tipo = b.dataset.histTipo ?? '';
      if (tipo === estado.cmHistFiltroTipo) return;
      estado.cmHistFiltroTipo = tipo;
      // O item escolhido é da aba de itens: trocar de tipo o solta.
      estado.cmHistFiltroItem = 0;
      estado.cmHistFiltroFav = false;
      recarregarHistoricoGlobal();
    });
    host.querySelector('.cm-hist-moedas')?.addEventListener('click', (ev) => {
      const b = ev.target.closest('[data-hist-moeda]');
      if (!b) return;
      const moeda = b.dataset.histMoeda ?? '';
      if (moeda === estado.cmHistFiltroMoeda) return;
      estado.cmHistFiltroMoeda = moeda;
      recarregarHistoricoGlobal();
    });
    host.querySelector('#cm-hist-item')?.addEventListener('change', (ev) => {
      const v = ev.target.value;
      estado.cmHistFiltroTipo = v === 'diamante' ? 'diamante' : 'item';
      estado.cmHistFiltroFav = v === 'favoritos';
      estado.cmHistFiltroItem = v === 'diamante' || v === 'favoritos' || !v ? 0 : Number(v);
      recarregarHistoricoGlobal();
    });
  };

  if (!estado.cmHistDados) {
    host.innerHTML = global
      ? `${filtroGlobal}<div class="cm-vazio">…</div>`
      : `<div class="cm-vazio">…</div>`;
    ligarFiltroGlobal();
    return;
  }

  const d = estado.cmHistDados;
  const compras = modo === 'compras';

  const ligarHistoricoMercadoUi = () => {
    ligarFiltroGlobal();

    host.querySelector('.cm-hist-pags')?.addEventListener('click', (ev) => {
      const b = ev.target.closest('.cm-pag');
      if (!b || b.disabled) return;
      estado.cmHistPagina = Math.max(0, d.pagina + Number(b.dataset.ir));
      pedirHistoricoMercado();
    });

    host.querySelectorAll('.cm-hist-item-poke').forEach((el) => {
      el.addEventListener('click', () => {
        const l = d.linhas[Number(el.dataset.idx)];
        if (!l?.ficha || l.tipo !== 'pokemon') return;
        // O dono é quem ficou com o bicho: no extrato de vendas é o comprador, no de compras
        // sou eu. A Tabela de preços mostra o anunciante, como sempre mostrou.
        const dono = modo === 'vendas' ? l.comprador : modo === 'compras' ? estado.eu?.nick : l.vendedor;
        abrirFichaDoPokemon({ ...l.ficha, id: l.ficha.id ?? l.pokemonId, nota: notaDoFicha(l.ficha), dono });
      });
    });
  };

  if (!d.linhas?.length) {
    host.innerHTML = `
      ${global ? filtroGlobal : ''}
      <div class="cm-vazio">${t(global ? chaveVazioHistoricoGlobal(estado.cmHistFiltroTipo) : (HIST_MODOS[modo]?.vazio ?? 'cm.historicoVazio'))}</div>`;
    ligarHistoricoMercadoUi();
    return;
  }

  // O global tem uma coluna a mais: no extrato pessoal um dos dois lados da transação é
  // sempre o próprio jogador e não precisa ser escrito. Aqui os dois lados são estranhos.
  const cabecalho = global
    ? [t('cm.historicoData'), t('cm.historicoItem'), t('cm.historicoVendedor'), t('cm.historicoComprador'), t('cm.historicoValor')]
    : [t('cm.historicoItem'), t('cm.historicoData'), t('cm.historicoValor'), t(compras ? 'cm.historicoVendedor' : 'cm.historicoComprador')];

  const linha = (l, i) => (global
    ? `<div class="cm-hist-linha">
         <span class="cm-hist-data">${formatarDataHora(l.em)}</span>
         <span class="cm-hist-item${l.tipo === 'pokemon' && l.ficha ? ' cm-hist-item-poke' : ''}" data-idx="${i}"
               title="${escapar(tituloHistoricoGlobal(l))}">${itemHistoricoGlobal(l)}</span>
         <span class="cm-hist-nick vend" data-rotulo="${escapar(t('cm.historicoVendedor'))}">${escapar(l.vendedor ?? '—')}</span>
         <span class="cm-hist-nick comp" data-rotulo="${escapar(t('cm.historicoComprador'))}">${escapar(l.comprador ?? '—')}</span>
         <span class="cm-hist-valor">${precoComMoeda(l.bruto, l.moeda)}</span>
       </div>`
    // O extrato pessoal usa a MESMA célula de item da Tabela de preços: nome, ✨ e a fileira
    // P·IV·Q·N quando é pokémon, e o clique abre a ficha congelada do anúncio. Linha antiga
    // (anúncio sem ficha) cai no texto puro, como era.
    : `<div class="cm-hist-linha">
         <span class="cm-hist-item${l.tipo === 'pokemon' && l.ficha ? ' cm-hist-item-poke' : ''}" data-idx="${i}"
               title="${escapar(tituloHistoricoGlobal(l))}">${itemHistoricoGlobal(l)}</span>
         <span class="cm-hist-data">${formatarDataHora(l.em)}</span>
         <span class="cm-hist-valor">${precoComMoeda(l.bruto, l.moeda)}</span>
         <span class="cm-hist-comp">${escapar((compras ? l.vendedor : l.comprador) ?? '—')}</span>
       </div>`);

  // Paginação: o extrato pessoal sabe o TOTAL (o `count` por jogador é barato) e mostra
  // "página 2 de 7". O global não conta nada — contar as vendas do servidor inteiro a cada
  // abertura seria o único ponto do painel com custo proporcional à idade do jogo. Lá o
  // servidor devolve `temMais`, e a barra vira só "‹ 2 ›". Ver `historicoGlobal`.
  const paginas = Math.ceil((d.total ?? 0) / (d.porPagina ?? 30));
  const temAnterior = (d.pagina ?? 0) > 0;
  const temProxima = global ? !!d.temMais : d.pagina + 1 < paginas;
  const mostrarPags = global ? temAnterior || temProxima : paginas > 1;

  // Cinco colunas só cabem no desktop. `estreito` troca a linha por um cartão (ver o bloco
  // `.cm-hist-lista.global.estreito` no estilo) e quem decide é `movelAtivo()`, não uma media
  // query: a montagem de celular também sobe num tablet largo, onde a largura da janela
  // sozinha diria "cabe" e não caberia.
  const classeGlobal = global ? ` global${movelAtivo() ? ' estreito' : ''}` : '';

  host.innerHTML = `
    ${global ? filtroGlobal : ''}
    <div class="cm-hist-cab${classeGlobal}">
      ${cabecalho.map((c) => `<span>${c}</span>`).join('')}
    </div>
    <div class="cm-hist-lista${classeGlobal}">
      ${d.linhas.map((l, i) => linha(l, i)).join('')}
    </div>
    ${
      mostrarPags
        ? `<div class="cm-hist-pags">
             <button class="cm-pag" data-ir="-1" ${temAnterior ? '' : 'disabled'}>‹</button>
             <span>${global ? t('cm.paginaN', { a: d.pagina + 1 }) : t('cm.paginaDe', { a: d.pagina + 1, b: paginas })}</span>
             <button class="cm-pag" data-ir="1" ${temProxima ? '' : 'disabled'}>›</button>
           </div>`
        : ''
    }`;

  ligarHistoricoMercadoUi();
}

// ---------------------------------------------------------------- o mapa
//
// O mapa-múndi de verdade, com um marcador por área — a imagem e os pixels vêm do próprio
// espelho (`world/map-markers.json` traz slug, área, nível, looktype e o pixel na imagem).
// Cada marcador é o retrato da espécie que mora ali, e o filtro corta por nível e por tipo.

/**
 * As abas do mapa são por GERAÇÃO, não pela `area` do espelho.
 *
 * A `area` continua sendo o que era (`kanto`, `orre`, `outland`) porque o servidor lê esse
 * campo — `bosses.mjs` só solta token de boss em `outland`, e mexer nele quebraria isso.
 * Aqui em cima dela desenhamos a divisão que o jogador entende: uma aba por temporada.
 *
 * O espelho já vinha misturado: a imagem de `kanto` guarda Gen 1 E Gen 2 (139 + 85 hunts), e
 * a de `orre` guarda Hoenn com dois intrusos de Sinnoh (Riolu e Lucario). Separar por geração
 * dá 4 abas com conteúdo, sem mapa novo — as mesmas imagens, recortadas por quem mora nelas.
 *
 * `outland` fica fora da régua de geração de propósito: lá moram as VARIANTES (Brave
 * Blastoise, Ancient Meganium…), que são bosses de Gen 1 e 2 repaginados, não uma temporada.
 *
 * `nivel` é o degrau da ESCADA de temporadas, e vale por aba — não é mais herdado da área.
 * Ele tranca a aba visualmente; quem barra a entrada de verdade é o servidor, hunt a hunt
 * (`areaLiberada` em sim.mjs compara `p.level >= hunt.nivel`).
 *
 * Sinnoh usa `4sinnoh.png`; Riolu e Lucario tinham pixel calibrado em `3hoenn.png` — ver
 * PIXEL_POR_REGIAO. Gens 7–9 compartilham `8alola.png` (Galar/Paldea ficam só como estoque).
 */
const REGIOES_MAPA = [
  { id: 'kanto', rotulo: 'Kanto', area: 'kanto', ger: 'kanto', img: '1kantoe2johto.png', nivel: 1 },
  { id: 'johto', rotulo: 'Johto', area: 'kanto', ger: 'johto', img: '1kantoe2johto.png', nivel: 1 },
  { id: 'outland', rotulo: 'Outland', area: 'outland', ger: null, img: 'outland.png', nivel: 150 },
  { id: 'hoenn', rotulo: 'Hoenn', area: 'orre', ger: 'hoenn', img: '3hoenn.png', nivel: 500 },
  { id: 'sinnoh', rotulo: 'Sinnoh', area: 'orre', ger: 'sinnoh', img: '4sinnoh.png', nivel: 1000 },
  { id: 'unova', rotulo: 'Unova', area: 'orre', ger: 'unova', img: '5unova.png', nivel: 5000 },
  { id: 'kalos', rotulo: 'Kalos', area: 'orre', ger: 'kalos', img: '7kalos.png', nivel: 10000 },
  { id: 'alola', rotulo: 'Alola', area: 'orre', ger: 'alola', img: '8alola.png', nivel: 25000 },
];
const regiaoMapaPorId = new Map(REGIOES_MAPA.map((r) => [r.id, r]));

/**
 * Onde o marcador fica QUANDO a região empresta outra imagem.
 *
 * O `pixel` de `map-markers.json` é relativo à imagem da área de origem — Riolu e Lucario
 * moram em `3hoenn.png` (719×666). Em `4sinnoh.png` eles precisam de coordenadas próprias.
 * Aqui reposicionamos os dois numa ilha, com `translate(-50%,-50%)` no CSS
 * fazendo o pixel ser o CENTRO do marcador.
 *
 * Mora no cliente, e não no espelho, porque `public/data/` é regenerável: um `npm run fetch`
 * reescreve `map-markers.json` e levaria o ajuste junto.
 */
const PIXEL_POR_REGIAO = {
  sinnoh: { riolu: [319, 215], lucario: [328, 260] },
};

/**
 * A ESCADA DAS OUTLANDS — o seletor que mora na aba Outland do mapa.
 *
 * Mesmo mapa, mesmos pokémon, mesmo nível 150 em todos os degraus. O que o degrau muda é a
 * chance dos três drops raros da área (Bronze Boss Token, Fragmento de Chave, Fragmento de
 * Shiny Stone). Quem manda nos números é o servidor (`welcome.outlandTiers`); a
 * tabela do `shared` é só a rede de baixo para o caso de a tela abrir antes do welcome.
 *
 * Nada aqui conta degraus nem repete um multiplicador à mão: a lista que chega manda em
 * quantas opções o `<select>` tem e no que cada uma promete.
 */
const outlandTiersUi = () => estado.outlandTiers ?? OUTLAND_TIERS;

const fichaOutlandUi = (tier) => {
  const lista = outlandTiersUi();
  return lista.find((x) => x.tier === Number(tier)) ?? lista[0];
};

/** O tier ESCOLHIDO, já podado pelo nível — a tela nunca promete um multiplicador travado. */
function tierOutlandUi() {
  const escolhido = fichaOutlandUi(estado.eu?.outlandTier ?? OUTLAND_TIER_PADRAO);
  if ((estado.eu?.level ?? 0) >= escolhido.nivel) return escolhido.tier;
  const lista = outlandTiersUi();
  for (let i = lista.length - 1; i >= 0; i--) {
    if ((estado.eu?.level ?? 0) >= lista[i].nivel) return lista[i].tier;
  }
  return OUTLAND_TIER_PADRAO;
}

/** O que multiplica as chances mostradas na ficha da área e na Pokédex. */
const multOutlandUi = () => fichaOutlandUi(tierOutlandUi()).mult ?? 1;

const rotuloOutlandUi = () => fichaOutlandUi(tierOutlandUi()).rotulo ?? rotuloOutlandTier(1);

/**
 * A etiqueta da cena, no canto do palco: área, a Outland em que ela está, e o nível.
 *
 * NO CELULAR O NÍVEL CAI quando há degrau de Outland a mostrar. O chip é `nowrap` com
 * reticências e cabe em ~260 px; com três segmentos, "Taekwondo Hitmonchan · Outland 5 ·
 * nível 150" perde o fim — e o fim é justamente o degrau que o jogador acabou de escolher.
 * Na Outland TODA hunt é nível 150, então ele é o segmento que menos informa ali, e o número
 * continua no marcador do mapa e na ficha da área. No desktop o chip não tem teto de largura
 * e os três segmentos cabem inteiros.
 */
function rotuloCenaHunt(h) {
  if (!h) return '';
  if (h.area !== 'outland' || tierOutlandUi() === OUTLAND_TIER_PADRAO) {
    return t('cena.huntNivel', { nome: h.nome, nivel: h.nivel });
  }
  const outland = rotuloOutlandUi();
  return movelAtivo()
    ? t('cena.huntOutland', { nome: h.nome, outland })
    : t('cena.huntNivelOutland', { nome: h.nome, outland, nivel: h.nivel });
}

/**
 * ONDE o jogador está, numa linha: arena de boss, dentro de casa, no Centro ou na hunt.
 *
 * Mora fora do `pintarHudHunt` porque tem dois leitores: a plaquinha do canto da cena e o
 * cabeçalho do Modo Economia, que é justamente a tela em que a plaquinha não existe. Uma
 * segunda cópia da escada de cenas divergiria na primeira cena nova.
 */
function rotuloDaCena(e) {
  const arena = e.boss?.arena ?? null;
  const boss = arena && fichaDoBoss(arena.key);
  const h = huntEmCampo(e);
  return arena
    ? t('cena.arenaBoss', { nome: boss?.nome ?? arena.key, nivel: num(boss?.level ?? 0) })
    : e.mistico
      ? t('cena.arenaMistica', { nome: e.mistico.nome ?? '', nivel: NIVEL_LENDARIO_MISTICO })
    : e.casa?.dentro
      ? t('cena.casaDentro', {
        rar: t(`casa.rar.${(e.casa.lista ?? []).find((c) => c.id === e.casa.dentro)?.rar ?? 'comum'}`),
        numero: numeroDaCasa(e.casa.dentro),
      })
      : e.noCentro
        ? t('cena.centroCerulean')
        : h
          ? rotuloCenaHunt(h)
          : t('cena.escolhaMapa');
}

/** Plaquinha do canto — texto e atalho à Pokédex. Sem `data-i18n`: o rótulo é 100% JS. */
function pintarHudHunt(e) {
  const chip = $('#hud-hunt');
  if (!chip) return;

  chip.textContent = rotuloDaCena(e);
  // O Modo Economia esconde a plaquinha e mostra o mesmo texto no cabeçalho dele.
  pintarOndeEconomia(e);

  pintarAtalhoHuntCena(e);
}

/** Hunt normal em campo — fora de centro, casa, boss e Arena Mística. */
function huntEmCampo(e) {
  if (!e?.huntSlug || e.noCentro || e.casa?.dentro || e.boss?.arena || e.mistico) {
    return null;
  }
  return estado.hunts.find((x) => x.slug === e.huntSlug) ?? null;
}

/** Espécie principal da hunt para atalho à Pokédex — nome que bate ou maior peso de spawn. */
function pokeIdPrincipalDaHunt(h) {
  const lista = h?.especies;
  if (!lista?.length) return null;
  let pokeId;
  if (lista.length === 1) pokeId = lista[0].pokeId;
  else {
    const nome = h.nome?.trim().toLowerCase();
    const porNome = lista.find((e) => e.nome?.trim().toLowerCase() === nome);
    pokeId = porNome
      ? porNome.pokeId
      : [...lista].sort((a, b) => (b.pontos ?? 0) - (a.pontos ?? 0))[0].pokeId;
  }
  return pokeId != null ? remapOutlandPokeId(pokeId) : null;
}

/** A plaquinha da hunt vira atalho para a ficha da espécie na Pokédex. */
function pintarAtalhoHuntCena(e) {
  const chip = $('#hud-hunt');
  if (!chip) return;
  const h = huntEmCampo(e);
  const pokeId = h ? pokeIdPrincipalDaHunt(h) : null;
  chip.classList.toggle('hud-clicavel', !!pokeId);
  if (pokeId) {
    chip.dataset.pokeId = String(pokeId);
    chip.setAttribute('role', 'button');
    chip.setAttribute('tabindex', '0');
    chip.title = t('cena.abrirPokedex', { nome: h.nome });
  } else {
    delete chip.dataset.pokeId;
    chip.removeAttribute('role');
    chip.removeAttribute('tabindex');
    chip.removeAttribute('title');
  }
}

function abrirPokedexDaHuntCena() {
  const pokeId = Number($('#hud-hunt')?.dataset.pokeId);
  if (pokeId) abrirFichaDaEspecie(pokeId);
}

$('#hud-hunt')?.addEventListener('click', abrirPokedexDaHuntCena);
$('#hud-hunt')?.addEventListener('keydown', (ev) => {
  if (ev.key === 'Enter' || ev.key === ' ') {
    ev.preventDefault();
    abrirPokedexDaHuntCena();
  }
});

/**
 * As três opções da lista.
 *
 * A travada nasce `disabled` E com o nível no rótulo: um cadeado sem o número diz "não pode"
 * e esconde justamente a informação pela qual o jogador abriu a lista.
 */
function htmlOpcoesOutland() {
  const nivel = estado.eu?.level ?? 0;
  const atual = tierOutlandUi();
  return outlandTiersUi()
    .map((x) => {
      const livre = nivel >= x.nivel;
      // `num` no multiplicador porque a escada tem degraus fracionários: cru, o 1.25 sairia
      // com ponto no meio de uma tela que escreve todo número com vírgula.
      const rotulo = livre
        ? t('mapa.outland.opcao', { nome: x.rotulo, mult: num(x.mult) })
        : t('mapa.outland.opcaoTravada', { nome: x.rotulo, mult: num(x.mult), n: num(x.nivel) });
      return `<option value="${x.tier}"${livre ? '' : ' disabled'}${x.tier === atual ? ' selected' : ''}>${escapar(rotulo)}</option>`;
    })
    .join('');
}

/**
 * O seletor em si. Só é desenhado na aba Outland — nas outras não há degrau que escolher.
 *
 * A explicação sai DUAS vezes de propósito, e só uma delas aparece por vez. No desktop ela é
 * o `title` do rótulo, que o mouse revela. No celular não existe passar o mouse por cima, e um
 * `title` ali seria letra morta: quem joga no dedo nunca leria o que as Outlands têm de
 * diferente. Então a versão curta vira uma linha visível, que o `mobile.css` acende (ver
 * `.mapa-outland-dica`) e o desktop mantém escondida para não repetir o que o tooltip já diz.
 */
function htmlSeletorOutland() {
  return `
      <label class="mapa-outland" title="${escapar(t('mapa.outland.dica'))}">
        <span class="mapa-outland-titulo">${t('mapa.outland.titulo')}</span>
        <select class="filtros-select-el mapa-outland-sel" id="f-outland">${htmlOpcoesOutland()}</select>
        <small class="mapa-outland-dica">${escapar(t('mapa.outland.dicaCurta'))}</small>
      </label>`;
}

/**
 * Repinta as opções sem trocar o `<select>`.
 *
 * Trocar o elemento inteiro (outerHTML) levaria junto o `onchange` ligado na abertura do
 * modal — e o `montarMapaMundi` roda de novo a cada level up, que é justamente quando uma das
 * opções destrava.
 */
function pintarSeletorOutland() {
  const sel = $('#f-outland');
  if (sel) sel.innerHTML = htmlOpcoesOutland();
}

/** Faixas da Pokédex nacional. Galar e Paldea aparecem no mapa Alola (8alola.png). */
const FAIXA_GERACAO = [
  [1, 151, 'kanto'], [152, 251, 'johto'], [252, 386, 'hoenn'],
  [387, 493, 'sinnoh'], [494, 649, 'unova'], [650, 721, 'kalos'],
  [722, 809, 'alola'], [810, 905, 'alola'], [906, 1025, 'alola'],
];

/** Aba do mapa-múndi para hunts das gens 8 e 9 (marcadores em 8alola.png). */
const MAPA_REGIAO_POR_GER = { galar: 'alola', paldea: 'alola' };

/**
 * O número de dex por trás do `pokeId`.
 *
 * Hoenn são os `13xxx` (Treecko é 13252 = 13000 + 252). Outland usa faixa própria #2001+.
 *
 * A MEGA (#3026…#3780) é a exceção que o `% 1000` estragaria: `3094 % 1000` é 94, o dex do
 * Gengar comum — e com isso o Mega Gengar apareceria na Pokédex como "#094", pegaria a arte
 * shiny do Gengar e cairia na mesma casa dele na grade. O número dela É o pokeId, como o da
 * Outland. Ver `shared/megas.mjs`.
 */
const dexDoPokeId = (id) => (id < 1000 || isMegaPokeId(id) ? id : id % 1000);

/** Número exibido na ficha/Pokédex — nacional, Orre ou Outland (#2001+). */
function dexExibicao(pokeId) {
  if (isOutlandPokeId(pokeId)) return estado.outlandDex?.pokeToDex?.[pokeId] ?? dexDoPokeId(pokeId);
  return dexDoPokeId(pokeId);
}

function temFormaShinyFicha(especie) {
  const id = especie.pokeId;
  if (isOutlandPokeId(id)) return estado.shinyLooksOutland[id] != null;
  const dex = dexExibicao(id);
  return dex != null && estado.shinyLooks[dex] != null;
}

function lookShinyFicha(especie) {
  if (isOutlandPokeId(especie.pokeId)) return null;
  return estado.shinyLooks[dexExibicao(especie.pokeId)] ?? especie.looktype;
}

/**
 * Progresso da Pokédex — chave nacional (#xxx); Outland (10xxx) não grava.
 *
 * `sv`/`sc` são os SHINY vistos e capturados desta espécie. Vêm ausentes no save de quem
 * nunca viu um (o servidor só grava o que passou de zero — ver `somarEntrada` em
 * `shared/pokedex.mjs`), por isso o `?? 0` em vez de assumir que a chave existe.
 */
const VAZIO_POKEDEX = { k: 0, c: 0, sv: 0, sc: 0 };
const entradaPokedex = (pokeId) => {
  const dex = estado.eu?.pokedex ?? {};
  const n = chavePokedex(pokeId);
  if (n == null) return { ...VAZIO_POKEDEX };
  const a = dex[n];
  const leg = pokeId !== n ? dex[pokeId] : null;
  if (!a && !leg) return { ...VAZIO_POKEDEX };
  return {
    k: (a?.k ?? 0) + (leg?.k ?? 0),
    c: (a?.c ?? 0) + (leg?.c ?? 0),
    sv: (a?.sv ?? 0) + (leg?.sv ?? 0),
    sc: (a?.sc ?? 0) + (leg?.sc ?? 0),
  };
};

const geracaoDoDex = (d) => FAIXA_GERACAO.find(([a, b]) => d >= a && d <= b)?.[2] ?? null;

/** Região da aba do mapa onde a hunt aparece. */
function regiaoMapaDoHunt(h) {
  if (h?.regiao) {
    if (h.regiao === 'galar' || h.regiao === 'paldea') return 'alola';
    return h.regiao;
  }
  return null;
}

/** A geração que MANDA na hunt: a das espécies com mais pontos de spawn. */
function geracaoDaHunt(h) {
  const peso = new Map();
  for (const e of h?.especies ?? []) {
    const g = geracaoDoDex(dexDoPokeId(e.pokeId));
    if (g) peso.set(g, (peso.get(g) ?? 0) + (e.pontos ?? 1));
  }
  let melhor = null;
  let max = -1;
  for (const [g, n] of peso) if (n > max) [melhor, max] = [g, n];
  return melhor;
}

/**
 * A hunt pertence à aba?
 *
 * Hunt nossa declara `regiao` e manda nela — são as de Sinnoh, que juntam bicho de várias
 * gerações de propósito e cairiam na aba errada se fossem pela regra automática (um Ditto de
 * Gen 1 iria parar em Kanto). O resto do catálogo segue área + geração.
 */
const naRegiao = (m, h, reg) => {
  const rm = regiaoMapaDoHunt(h);
  if (rm) return rm === reg.id;
  if (reg.ger == null) return m.area === reg.area;
  const g = geracaoDaHunt(h);
  const mapGer = MAPA_REGIAO_POR_GER[g] ?? g;
  return m.area === reg.area && mapGer === reg.ger;
};

/**
 * Quantas hunts a aba tem. `null` = ainda não dá para saber (marcadores não chegaram).
 *
 * A diferença entre `null` e `0` importa: com `0` a aba nasce desabilitada, e no primeiro
 * render — antes do fetch dos marcadores — isso desabilitaria TODAS elas.
 */
/**
 * Os marcadores do espelho MAIS os das hunts nossas.
 *
 * `map-markers.json` só conhece o que veio de poke.idleworld.online. As hunts que criamos
 * trazem o próprio `pixel` e `looktype` dentro de `estado.hunts` (ver content.mjs), e aqui
 * viram marcador no mesmo formato para o resto da tela não precisar saber a diferença.
 */
function todosMarcadores() {
  const doEspelho = estado.marcadores?.hunts ?? [];
  const nossos = (estado.hunts ?? [])
    .filter((h) => h.pixel && h.regiao)
    .map((h) => ({
      slug: h.slug,
      nome: h.nome,
      area: h.regiao === 'outland' ? 'outland' : 'orre',
      pixel: h.pixel,
      looktype: h.looktype,
    }));
  return nossos.length ? [...doEspelho, ...nossos] : doEspelho;
}

/**
 * Retrato no mapa-múndi: o espelho (`map-markers.json`) traz looktypes antigos (ex.: 318),
 * mas o atlas de marcadores indexa os do catálogo atual (ex.: 40018). Sem isto, cai no fallback
 * runtime e o sprite nasce desalinhado — “saindo da bola”.
 */
/** A espécie que dá a CARA do marcador: a de maior peso de spawn da área. */
const especiePrincipal = (h) => [...(h?.especies ?? [])].sort((a, b) => b.pontos - a.pontos)[0];

function looktypeDoMarcador(m, h) {
  const principal = especiePrincipal(h);
  const lt = estado.especies.get(principal?.pokeId)?.looktype;
  if (lt > 1) return lt;
  return m.looktype;
}

/**
 * O marcador mostra uma espécie que esta conta já capturou?
 *
 * É a espécie do DESENHO, e não "a área inteira já foi coletada": o anel fica em volta de um
 * sprite só, e prometer com ele alguma coisa sobre as outras cinco espécies da área seria um
 * enfeite que mente. Quem quer o detalhe abre a ficha da área ao passar o mouse.
 *
 * `c` é a contagem de capturas da Pokédex. Outland (10xxx) não grava na dex — `entradaPokedex`
 * devolve zero e o marcador nunca doura, que é o certo: lá não há coleção para completar.
 */
function marcadorCapturado(h) {
  const pokeId = especiePrincipal(h)?.pokeId;
  return pokeId != null && (entradaPokedex(pokeId).c ?? 0) > 0;
}

function contarHunts(reg) {
  const marcas = estado.marcadores ? todosMarcadores() : null;
  if (!marcas || !estado.hunts?.length) return null;
  const porSlug = new Map(estado.hunts.map((h) => [h.slug, h]));
  let n = 0;
  for (const m of marcas) {
    const h = porSlug.get(m.slug);
    if (h && naRegiao(m, h, reg)) n++;
  }
  return n;
}

/** A fila de abas. Sai daqui (e não de dentro do template) para poder ser repintada. */
function htmlAbasMapa() {
  const f = estado.filtroMapa;
  const nivel = estado.eu.level;
  // A fila é a ordem do array, e ela segue o NÍVEL de entrada, não a cronologia das gerações:
  // Outland é nível 150 e entra entre Johto e Hoenn. Ordenar pela temporada colocaria uma
  // parada de nível 150 depois de uma de 1000, e a aba é justamente onde se lê a progressão.
  return REGIOES_MAPA.map((reg) => {
    const quantas = contarHunts(reg);
    const trancada = nivel < reg.nivel;
    // Em obra é diferente de trancada: Unova e Kalos não têm uma hunt sequer, então o degrau
    // de nível é só o plano — dizer "Nv 5000" ali prometeria algo que ainda não existe.
    const dica = reg.emObra
      ? `${reg.rotulo} — em desenvolvimento (previsto para Nv ${num(reg.nivel)})`
      : trancada
        ? t('mapa.areaTravada', { n: reg.nivel })
        : `${reg.rotulo}${quantas == null ? '' : ` — ${quantas} áreas`}`;
    // O nível fica SEMPRE visível, e não só quando tranca: é a escada da progressão, e o
    // jogador precisa dela para planejar aonde vai — não só para descobrir onde esbarrou.
    const sufixo = ` · Nv ${num(reg.nivel)}${reg.emObra ? ' · desenvolvendo…' : ''}`;
    return `<button class="mapa-area ${reg.id === f.regiao ? 'on' : ''}${
      trancada || reg.emObra ? ' mapa-area-travada' : ''
    }" data-regiao="${reg.id}"${reg.emObra ? ' disabled' : ''} title="${escapar(dica)}">${
      escapar(reg.rotulo)
    }${sufixo}</button>`;
  }).join('');
}

/**
 * Zoom do mapa-múndi: roda do mouse (`zoom × e^(-0,0016·deltaY)`) e arrastar para mover.
 *
 * O mínimo é o "cobrir": a imagem nunca fica menor que a janela. O máximo é 5× isso (ou 2,5,
 * o que for maior). Ao mudar o zoom, guardamos a FRAÇÃO do mapa que estava sob o cursor e
 * recolocamos o scroll ali — sem isso o mapa foge da mão a cada scroll.
 */
const mapaZoom = { w: 1788, h: 3364, z: 0, ancora: null };

const zoomMinimo = (vp) => Math.max(vp.clientWidth / mapaZoom.w, vp.clientHeight / mapaZoom.h);
const zoomMaximo = (min) => Math.max(5 * min, 2.5);

function aplicarZoom(alvo, px, py) {
  const vp = $('#mapa-mundi');
  if (!vp) return;
  const min = zoomMinimo(vp);
  const z = Math.min(zoomMaximo(min), Math.max(min, alvo));
  if (Math.abs(z - mapaZoom.z) < 1e-4) return;
  mapaZoom.ancora = {
    fx: (vp.scrollLeft + px) / (mapaZoom.w * mapaZoom.z),
    fy: (vp.scrollTop + py) / (mapaZoom.h * mapaZoom.z),
    cx: px,
    cy: py,
  };
  mapaZoom.z = z;
  plotarMarcadores();
}

/**
 * Área liberada = nível do treinador ≥ nível da área.
 *
 * Estava com uma folga de +15 níveis, herdada da primeira versão da tela — no nível 10 dava
 * para entrar numa área de 20. A regra do cliente deles é a comparação seca (`t >= e.level`
 * é o que pinta o selo de nível de verde ou vermelho), e agora o servidor recusa também.
 */
const liberada = (h) => estado.eu.level >= h.nivel;

/** Tipos de todas as espécies que aparecem numa hunt (para o filtro por classificação). */
function tiposDaHunt(h) {
  const s = new Set();
  for (const e of h.especies ?? []) {
    const c = estado.especies.get(e.pokeId);
    if (c?.type1) s.add(c.type1);
    if (c?.type2) s.add(c.type2);
  }
  return s;
}

/** Hunt passa no filtro de tipo: espécie do tipo, ou fraca/forte aos tipos marcados (efetividade real). */
function passaFiltroTipo(h, f) {
  if (!f.tipos.length) return true;
  if (!f.modoMatchup) return f.tipos.some((tp) => tiposDaHunt(h).has(tp));
  for (const e of h.especies ?? []) {
    const esp = estado.especies.get(e.pokeId);
    if (especiePassaFiltroMatchup(esp, f.tipos, f.modoMatchup, estado.tabelaTipos)) return true;
  }
  return false;
}

const ctxHuntAnalyser = () => ({
  especies: estado.especies,
  tabelaTipos: estado.tabelaTipos,
  eu: estado.eu,
  tiposBoost: estado.tiposBoost,
});

function especieDaHunt(h, looktypeMarcador) {
  const principal = [...(h.especies ?? [])].sort((a, b) => b.pontos - a.pontos)[0];
  const espPrincipal = estado.especies.get(principal?.pokeId);
  if (looktypeMarcador > 1) {
    for (const e of h.especies ?? []) {
      const esp = estado.especies.get(e.pokeId);
      if (esp?.looktype === looktypeMarcador) return esp;
    }
  }
  return espPrincipal ?? null;
}

function looktypeDaHunt(h, looktypeMarcador) {
  const esp = especieDaHunt(h, looktypeMarcador);
  const lt = esp?.looktype ?? looktypeMarcador;
  return lt > 1 ? lt : null;
}

function tiposDaEspecie(esp) {
  return esp ? [esp.type1, esp.type2].filter(Boolean) : [];
}

const rotuloMultTipo = (mult) => {
  if (mult === 0) return '×0';
  if (mult <= 0.5) return '×0,5';
  if (mult >= 4) return '×4';
  if (mult >= 2) return '×2';
  return `×${mult}`;
};

function blocoTiposAnalyser(itens, ruim = false, bom = false) {
  if (!itens.length) return `<div class="ha-vazio">${t('mapa.analyser.semTipos')}</div>`;
  return `<div class="ha-tipos${ruim ? ' ruim' : ''}${bom ? ' bom' : ''}">${itens
    .map(
      ({ tipo, mult }) =>
        `<span class="ha-tipo" title="${rotuloMultTipo(mult)}">${selosDeTipo([tipo])}<em>${rotuloMultTipo(mult)}</em></span>`,
    )
    .join('')}</div>`;
}

function htmlDropsAnalyser(h) {
  const naHunt = [...(h.especies ?? [])].sort((a, b) => b.pontos - a.pontos);
  if (!naHunt.length) return `<div class="ha-vazio">${t('mapa.analyser.semDrops')}</div>`;

  const emOutland = h.area === 'outland';
  // O degrau escolhido no seletor da barra multiplica os três raros — a ficha tem de mostrar
  // a chance que o jogador VAI ter, e não a da Outland 1.
  const multOutland = emOutland ? multOutlandUi() : 1;
  const rotuloOutland = emOutland ? rotuloOutlandUi() : t('mapa.analyser.bossToken');
  const chanceBoss = (estado.chanceBossToken ?? 0.0005) * multOutland;
  const chanceFragChave = (estado.casas?.fragmento?.chanceDrop ?? 0.000005) * multOutland;
  const chanceFragShiny = (estado.shinyStone?.chanceDrop ?? 0.000005) * multOutland;
  // O Fragmento de Bicicleta cai de todo abate na Outland com a mesma conta dos outros dois
  // (ver `rolarFragmentoBicicleta`, no servidor) — e faltava aqui.
  const chanceFragBicicleta = (estado.bicicletas?.fragmento?.chanceDrop ?? 0.000005) * multOutland;
  const fragChaveId = estado.casas?.fragmento?.itemId ?? 70011;
  const fragShinyId = estado.shinyStone?.fragmentoId ?? 70012;
  const fragBicicletaId = estado.bicicletas?.fragmento?.itemId ?? FRAGMENTO_BICICLETA_ID;
  const bossItem = itemPorNome('Bronze Boss Token');
  const bossId = bossItem?.id ?? BOSS_TOKEN_ID;
  const bossNome = bossItem?.name ?? 'Bronze Boss Token';

  const linhaDropOutland = (itemId, nomeEn, chance) => {
    const nome = nomeItem(itemId, nomeEn);
    return `<li class="ha-drop-boss"><span class="ha-drop-ico" data-item="${itemId}"></span><span class="ha-drop-nome">${escapar(nome)} <em>${escapar(rotuloOutland)}</em></span><b>${pct(chance)} · ${umEm(chance)}</b></li>`;
  };

  return naHunt
    .map((e) => {
      const esp = estado.especies.get(e.pokeId);
      const drops = listaDropsEspecie(esp);
      const linhas = drops.map(
        (d) => {
          const item = itemPorNome(d.name);
          const rotulo = item ? nomeItem(item, item.name) : d.name;
          const pctTxt = d.pct > 0 ? pct(d.pct / 100) : t('dex.nuncaCai');
          return `<li><span class="ha-drop-ico" data-item="${item?.id ?? ''}"></span><span class="ha-drop-nome">${escapar(rotulo)}</span><b>${pctTxt}</b></li>`;
        },
      );
      if (emOutland) {
        linhas.push(linhaDropOutland(fragChaveId, 'Key Fragment', chanceFragChave));
        linhas.push(linhaDropOutland(fragShinyId, 'Shiny Stone Fragment', chanceFragShiny));
        linhas.push(linhaDropOutland(fragBicicletaId, 'Bicycle Fragment', chanceFragBicicleta));
        linhas.push(
          `<li class="ha-drop-boss"><span class="ha-drop-ico" data-item="${bossId}"></span><span class="ha-drop-nome">${escapar(bossNome)} <em>${escapar(rotuloOutland)}</em></span><b>${pct(chanceBoss)} · ${umEm(chanceBoss)}</b></li>`,
        );
      }
      if (!linhas.length) return '';
      return `<div class="ha-pk-drops"><div class="ha-pk-nome">${escapar(e.nome ?? esp?.name ?? '?')}</div><ul class="ha-drops">${linhas.join('')}</ul></div>`;
    })
    .filter(Boolean)
    .join('');
}

function pintarIconesDropsAnalyser(raiz) {
  for (const el of raiz.querySelectorAll('.ha-drop-ico[data-item]')) {
    const id = Number(el.dataset.item);
    if (id) el.appendChild(imgItem(id, 18));
  }
}

function htmlSecaoFiltroMatchup(esp) {
  const f = estado.filtroMapa;
  if (!f.tipos.length || !f.modoMatchup || !esp) return '';
  const mult = melhorEfetividadeContra(f.tipos, esp.type1, esp.type2, estado.tabelaTipos);
  const modo = f.modoMatchup === 'fraco' ? t('mapa.filtro.fracoContra') : t('mapa.filtro.forteContra');
  const cls = mult >= 2 ? ' bom' : mult <= 0.5 ? ' ruim' : '';
  return `
    <div class="ha-sec">${t('mapa.analyser.filtroTitulo', { tipos: f.tipos.join(', '), modo })}</div>
    <div class="ha-filtro-matchup${cls}">
      <span class="ha-filtro-lado">${selosDeTipo(f.tipos)}</span>
      <span class="ha-filtro-seta">→</span>
      <span class="ha-filtro-lado">${selosDeTipo(tiposDaEspecie(esp))}</span>
      <em>${rotuloMultTipo(mult)}</em>
    </div>`;
}

/**
 * O RITMO MEDIDO, embaixo das três estimativas.
 *
 * As linhas de cima dizem o que a área PROMETE, com os boosts que o jogador tem ligados; estas
 * duas dizem o que ele está de fato tirando desta sessão. São os mesmos dois números da
 * janelinha Pocket, e a conta é a mesma função (`ritmoDaSessao`) — o pessoal pediu justamente
 * para poder comparar as duas colunas sem abrir o Pocket ao lado.
 *
 * Some quando não há prancheta (antes do welcome). Nos primeiros segundos de sessão o piso de
 * um minuto do `ritmoDaSessao` segura o número — e é por isso que a legenda diz "nesta sessão"
 * em vez de deixar o jogador achar que é a média dele de sempre.
 */
function htmlRitmoAnalyser() {
  const ritmo = ritmoDaSessao(estado.sessao);
  if (!ritmo) return '';
  return `
    <div class="ha-sec">${t('mapa.analyser.ritmoTitulo')}</div>
    <div class="ha-linha ritmo"><span>${t('mapa.analyser.ritmoXp')}</span><b>${num(ritmo.xpH)}</b></div>
    <div class="ha-linha ritmo"><span>${t('mapa.analyser.ritmoOuro')}</span><b>${num(ritmo.ouroH)}</b></div>`;
}

function renderHuntAnalyser(h, looktypeMarcador, marcadorEl) {
  const painel = $('#hunt-analyser');
  const corpo = $('#hunt-analyser-corpo');
  if (!painel || !corpo) return;

  const esp = especieDaHunt(h, looktypeMarcador);
  const tiposMon = tiposDaEspecie(esp);
  const r = analisarHunt(h, ctxHuntAnalyser(), tiposMon);
  corpo.innerHTML = `
    <div class="ha-cabecalho">
      <div class="ha-retrato" id="ha-retrato"></div>
      <div class="ha-ident">
        <div class="ha-area">${escapar(h.nome)}</div>
        <div class="ha-nivel">Nv ${h.nivel}</div>
        ${tiposMon.length ? `<div class="ha-tipos-mon">${selosDeTipo(tiposMon)}</div>` : ''}
      </div>
    </div>
    <div class="ha-linha"><span>${t('mapa.analyser.xpTreinador')}</span><b>${num(r.xpTreinadorH)}</b></div>
    <div class="ha-linha"><span>${t('mapa.analyser.xpPokemon')}</span><b>${num(r.xpPokemonH)}</b></div>
    <div class="ha-linha"><span>${t('mapa.analyser.gold')}</span><b>${num(r.goldH)}</b></div>
    ${htmlRitmoAnalyser()}
    ${htmlSecaoFiltroMatchup(esp)}
    <div class="ha-sec">${t('mapa.analyser.fracoA')}</div>
    ${blocoTiposAnalyser(r.tiposFracos, false, true)}
    <div class="ha-sec">${t('mapa.analyser.resisteA')}</div>
    ${blocoTiposAnalyser(r.tiposResiste, true)}
    <div class="ha-sec">${t('mapa.analyser.drops')}</div>
    ${htmlDropsAnalyser(h) || `<div class="ha-vazio">${t('mapa.analyser.semDrops')}</div>`}
    <div class="ha-nota">${t('mapa.analyser.estimativa')}</div>`;

  // No celular não existe "passar o mouse por cima": o toque no marcador ABRE esta ficha, e
  // quem escolhe a área é este botão. Sem ele, tocar num marcador trocaria de hunt na hora e
  // a análise (que é justamente o que ajuda a escolher) nunca seria lida.
  //
  // Ele mora FORA do corpo rolável, como rodapé do painel: a ficha tem drops, fraquezas e
  // resistências, e um botão no fim dessa lista obrigaria a rolar até o fim para caçar.
  painel.querySelector('.ha-cacar')?.remove();
  if (movelAtivo()) {
    const pode = liberada(h);
    const bt = document.createElement('button');
    bt.type = 'button';
    bt.className = `ha-cacar${pode ? '' : ' travada'}`;
    bt.textContent = pode ? t('mapa.analyser.cacar') : t('mapa.precisaNv', { n: h.nivel });
    bt.disabled = !pode;
    bt.onclick = () => {
      if (avisoTrocaDeHuntBloqueada()) return;
      enviar({ t: 'hunt.select', slug: h.slug });
      esconderHuntAnalyser();
      fecharModal();
    };
    painel.appendChild(bt);
  }

  const lt = looktypeDaHunt(h, looktypeMarcador);
  const retrato = corpo.querySelector('#ha-retrato');
  if (retrato && lt) {
    retrato.appendChild(spriteAnimado(lt, 44, 2, () => iconeEspecie(lt, 44)));
  }
  pintarIconesDropsAnalyser(corpo);

  posicionarHuntAnalyser(marcadorEl);
  painel.classList.remove('hidden');
}

/** Hunt à direita do mapa → painel à esquerda; à esquerda (ou no centro) → direita. */
function posicionarHuntAnalyser(marcadorEl) {
  const painel = $('#hunt-analyser');
  const vp = $('#mapa-mundi');
  if (!painel || !vp || movelAtivo()) return;

  painel.classList.remove('ha-lado-esq');
  if (!marcadorEl) return;

  const vpRect = vp.getBoundingClientRect();
  const mkRect = marcadorEl.getBoundingClientRect();
  const cx = mkRect.left + mkRect.width / 2 - vpRect.left;
  // No centro exato (metade da largura) fica à direita — padrão histórico do mapa.
  if (cx > vpRect.width / 2) painel.classList.add('ha-lado-esq');
}

let esconderAnalyserTimer = null;

function cancelarEsconderHuntAnalyser() {
  clearTimeout(esconderAnalyserTimer);
  esconderAnalyserTimer = null;
}

/** Pequena folga para o mouse ir do marcador ao painel sem apagar o analyser. */
function agendarEsconderHuntAnalyser() {
  cancelarEsconderHuntAnalyser();
  esconderAnalyserTimer = setTimeout(esconderHuntAnalyser, 120);
}

function huntAnalyserVisivel() {
  const painel = $('#hunt-analyser');
  return !!painel && !painel.classList.contains('hidden');
}

function rolarHuntAnalyser(deltaY) {
  const corpo = $('#hunt-analyser-corpo');
  if (!corpo) return;
  corpo.scrollTop += deltaY;
}

function esconderHuntAnalyser() {
  cancelarEsconderHuntAnalyser();
  const corpo = $('#hunt-analyser-corpo');
  if (corpo) corpo.scrollTop = 0;
  const painel = $('#hunt-analyser');
  painel?.classList.add('hidden');
  painel?.classList.remove('ha-lado-esq');
}

function htmlBotoesTipoMapa(selecionados, dataF) {
  const on = (t) => (t === '' ? !selecionados.length : selecionados.includes(t));
  return `<button class="tipo-btn ${on('') ? 'on' : ''}" data-f="${dataF}" data-tipo="">${t('cm.todosTipos')}</button>` +
    TIPOS_FILTRO.map(
      (tp) => `<button class="tipo-btn tipo ${tp} ${on(tp) ? 'on' : ''}" data-f="${dataF}" data-tipo="${tp}">${tp}</button>`,
    ).join('');
}

function alternarFiltroTiposMapa(arr, valor) {
  if (valor === '') {
    arr.length = 0;
    return;
  }
  const i = arr.indexOf(valor);
  if (i >= 0) arr.splice(i, 1);
  else arr.push(valor);
}

function pintarFiltrosTipoMapa() {
  const f = estado.filtroMapa;
  for (const b of $('#f-tipos')?.querySelectorAll('[data-f="tipo"]') ?? []) {
    const tp = b.dataset.tipo;
    b.classList.toggle('on', tp === '' ? !f.tipos.length : f.tipos.includes(tp));
  }
}

function renderMapa() {
  const f = estado.filtroMapa;
  const movel = movelAtivo();

  // Nível e "só liberadas" moram na BARRA no desktop e dentro da folha de filtros no celular.
  // O HTML é o mesmo texto nos dois casos — só muda de endereço —, então o desktop continua
  // recebendo exatamente a marcação de antes. Ver a nota da folha no `mobile.css`.
  const nivelECheck = `
      <div class="mapa-nivel">
        <span class="mapa-nivel-titulo">${t('mapa.filtro.nivel')}</span>
        <label class="mapa-nivel-campo"><span>${t('mapa.filtro.min')}</span><input id="f-nivel-min" type="number" min="1" step="1" placeholder="1" value="${f.nivelMin ?? ''}"></label>
        <label class="mapa-nivel-campo"><span>${t('mapa.filtro.max')}</span><input id="f-nivel-max" type="number" min="1" step="1" placeholder="30" value="${f.nivelMax ?? ''}"></label>
      </div>
      <label class="mapa-check"><input type="checkbox" id="f-liberadas" ${f.soLiberadas ? 'checked' : ''}> só liberadas</label>`;

  const avisoOutland = f.regiao === 'outland'
    ? `<p class="mapa-outland-aviso" role="note">${escapar(t('mapa.outland.avisoShiny'))}</p>`
    : '';

  return `
    <div class="mapa-barra">
      <div class="mapa-areas">${htmlAbasMapa()}</div>
      ${f.regiao === 'outland' ? htmlSeletorOutland() : ''}
      <input id="f-mapa" placeholder="buscar área…" autocomplete="off" value="${f.busca}">
      ${movel ? `<button type="button" class="filtros-bt" id="filtros-bt">${t('mapa.filtros')}</button>` : ''}
      ${movel ? '' : nivelECheck}
    </div>
    ${avisoOutland}
    <div class="mapa-filtros-grupo">
      ${movel ? `<div class="filtros-folha-topo"><h3>${t('mapa.filtros')}</h3></div>${nivelECheck}` : ''}
      <span class="mapa-filtros-titulo">${t('mapa.filtro.tipo')}</span>
      <div class="mapa-tipos" id="f-tipos">${htmlBotoesTipoMapa(f.tipos, 'tipo')}</div>
      <div class="mapa-matchup-filtros">
        <label class="mapa-check"><input type="checkbox" id="f-fraco-contra" ${f.tipos.length ? '' : 'disabled'} ${f.modoMatchup === 'fraco' ? 'checked' : ''}> ${t('mapa.filtro.fracoContra')}</label>
        <label class="mapa-check"><input type="checkbox" id="f-forte-contra" ${f.tipos.length ? '' : 'disabled'} ${f.modoMatchup === 'forte' ? 'checked' : ''}> ${t('mapa.filtro.forteContra')}</label>
      </div>
      ${movel ? folhaDeFiltrosRodape() : ''}
    </div>
    <div class="mapa-principal">
      <div class="mapa-mundi" id="mapa-mundi">
        <div class="mapa-tela" id="mapa-tela"><img id="mapa-img" alt="mapa de ${escapar(regiaoMapaPorId.get(f.regiao)?.rotulo ?? f.regiao)}"></div>
      </div>
      <div id="hunt-analyser" class="hunt-analyser hidden" aria-live="polite">
        <div class="ha-topo">
          <h3>${t('mapa.analyser.titulo')}</h3>
          <button type="button" class="ha-fechar" id="ha-fechar" title="${escapar(t('comum.fechar'))}"
                  aria-label="${escapar(t('comum.fechar'))}">×</button>
        </div>
        <div class="ha-corpo" id="hunt-analyser-corpo"></div>
      </div>
    </div>
    <div class="mapa-rodape" id="mapa-rodape">
      <span id="mapa-rodape-txt"></span>
      <span class="mapa-legenda hidden" id="mapa-legenda"><i aria-hidden="true"></i>${t('mapa.legendaCapturado')}</span>
    </div>`;
}

/** Marcadores da área atual, já filtrados — recalculado a cada mudança de filtro. */
let marcadoresVisiveis = [];

/** Área entra no intervalo de nível do filtro (vazio = sem limite naquela ponta). */
function passaFiltroNivel(nivel, f) {
  const min = f.nivelMin === '' || f.nivelMin == null ? null : Number(f.nivelMin);
  const max = f.nivelMax === '' || f.nivelMax == null ? null : Number(f.nivelMax);
  if (min == null && max == null) return true;
  if (min != null && !Number.isFinite(min)) return true;
  if (max != null && !Number.isFinite(max)) return true;
  let lo = min;
  let hi = max;
  if (lo != null && hi != null && lo > hi) [lo, hi] = [hi, lo];
  if (lo != null && nivel < lo) return false;
  if (hi != null && nivel > hi) return false;
  return true;
}

/**
 * Redesenha a tela do mapa no zoom atual: dimensiona a imagem, replanta os marcadores no
 * pixel × zoom e recoloca o scroll na âncora guardada pelo `aplicarZoom`.
 */
function plotarMarcadores() {
  esconderHuntAnalyser();
  const vp = $('#mapa-mundi');
  const tela = $('#mapa-tela');
  if (!vp || !tela) return;

  const larg = mapaZoom.w * mapaZoom.z;
  const alt = mapaZoom.h * mapaZoom.z;
  tela.style.width = `${larg}px`;
  tela.style.height = `${alt}px`;

  for (const velho of tela.querySelectorAll('.marcador')) velho.remove();

  // o marcador acompanha o zoom, mas com freio nas pontas (a conta é a deles)
  const escalaMk = Math.max(0.4, Math.min(1.25, mapaZoom.z / 0.6));
  const tam = Math.round(40 * escalaMk);

  let dourados = 0;
  for (const { m, h, livre } of marcadoresVisiveis) {
    const b = document.createElement('button');
    const capturado = marcadorCapturado(h);
    if (capturado) dourados++;
    b.className = `marcador${livre ? '' : ' travado'}${capturado ? ' capturado' : ''}`
      + `${h.slug === estado.eu.huntSlug ? ' on' : ''}`;
    b.style.left = `${m.pixel[0] * mapaZoom.z}px`;
    b.style.top = `${m.pixel[1] * mapaZoom.z}px`;
    b.style.width = b.style.height = `${tam}px`;
    b.dataset.slug = h.slug;
    b.dataset.travado = livre ? '0' : '1';
    // O anel dourado é cor, e cor sozinha não é informação acessível: quem não distingue o
    // tom (ou está no celular, onde não há `hover`) recebe a mesma notícia escrita.
    const selo = capturado
      ? `\n${t('mapa.jaCapturado', { nome: especiePrincipal(h)?.nome ?? '' })}`
      : '';
    b.title = (livre
      ? `${h.nome} — nível ${h.nivel}\n${h.especies.map((e) => e.nome).join(', ')}`
      : `${h.nome} — ${t('mapa.precisaNv', { n: h.nivel })}\n${h.especies.map((e) => e.nome).join(', ')}`) + selo;
    const ltMarc = looktypeDoMarcador(m, h);
    // 86% = o mesmo tamanho que `.marcador > .ico-poke` força no CSS; antes era 78% no JS e
    // 86% na tela — o recorte do atlas ficava desalinhado dentro da bola.
    b.appendChild(iconeEspecie(ltMarc, Math.round(tam * 0.86)));
    if (escalaMk > 0.6) b.insertAdjacentHTML('beforeend', `<b class="mk-nv">${h.nivel}</b>`);
    // Com mouse, a ficha da área segue o ponteiro. Com dedo, ela abre no TOQUE e fica —
    // `mouseenter`/`mouseleave` sintéticos do toque a fariam piscar e sumir no mesmo gesto.
    if (movelAtivo()) {
      b.addEventListener('click', () => {
        cancelarEsconderHuntAnalyser();
        renderHuntAnalyser(h, ltMarc, b);
      });
    } else {
      b.addEventListener('mouseenter', () => {
        cancelarEsconderHuntAnalyser();
        renderHuntAnalyser(h, ltMarc, b);
      });
      b.addEventListener('mouseleave', (ev) => {
        if (ev.relatedTarget?.closest('#hunt-analyser')) return;
        agendarEsconderHuntAnalyser();
      });
    }
    tela.appendChild(b);
  }

  $('#mapa-legenda')?.classList.toggle('hidden', dourados === 0);

  const a = mapaZoom.ancora;
  if (a) {
    vp.scrollLeft = a.fx * larg - a.cx;
    vp.scrollTop = a.fy * alt - a.cy;
    mapaZoom.ancora = null;
  }
}

/** Aplica os filtros e (re)desenha. A imagem só é trocada quando muda de região. */
async function montarMapaMundi(areaNova = false) {
  const f = estado.filtroMapa;
  const vp = $('#mapa-mundi');
  const img = $('#mapa-img');

  estado.marcadores ??= await fetch('/assets/world/map-markers.json', SEM_CACHE).then((r) => r.json());
  const porSlug = new Map(estado.hunts.map((h) => [h.slug, h]));
  const reg = regiaoMapaPorId.get(f.regiao) ?? REGIOES_MAPA[0];
  const daArea = todosMarcadores().filter((m) => porSlug.has(m.slug) && naRegiao(m, porSlug.get(m.slug), reg));

  // Os marcadores acabaram de chegar: agora dá para contar as hunts de cada aba e mostrar
  // quais estão vazias (Unova e Kalos, hoje). No primeiro render essa conta ainda era `null`.
  const barra = $('.mapa-areas');
  if (barra) barra.innerHTML = htmlAbasMapa();
  pintarSeletorOutland();

  marcadoresVisiveis = [];
  for (const m of daArea) {
    const h = porSlug.get(m.slug);
    const busca = !f.busca || h.nome.toLowerCase().includes(f.busca.toLowerCase());
    const tipoOk = passaFiltroTipo(h, f);
    const livre = liberada(h);
    const nivelOk = passaFiltroNivel(h.nivel, f);
    if (!busca || !tipoOk || !nivelOk || (f.soLiberadas && !livre)) continue;
    // Região que empresta imagem de outra tem o pixel recalculado (ver PIXEL_POR_REGIAO).
    const pixel = PIXEL_POR_REGIAO[reg.id]?.[m.slug] ?? m.pixel;
    marcadoresVisiveis.push({ m: pixel === m.pixel ? m : { ...m, pixel }, h, livre });
  }

  const minN = f.nivelMin === '' || f.nivelMin == null ? null : Number(f.nivelMin);
  const maxN = f.nivelMax === '' || f.nivelMax == null ? null : Number(f.nivelMax);
  let txtNivel = '';
  if (Number.isFinite(minN) || Number.isFinite(maxN)) {
    let lo = Number.isFinite(minN) ? minN : null;
    let hi = Number.isFinite(maxN) ? maxN : null;
    if (lo != null && hi != null && lo > hi) [lo, hi] = [hi, lo];
    if (lo != null && hi != null) txtNivel = lo === hi ? ` · ${t('mapa.filtro.nivel')} ${lo}` : ` · ${t('mapa.filtro.nivel')} ${lo}–${hi}`;
    else if (lo != null) txtNivel = ` · ${t('mapa.filtro.nivel')} ≥ ${lo}`;
    else txtNivel = ` · ${t('mapa.filtro.nivel')} ≤ ${hi}`;
  }

  const txtTipos = f.tipos.length ? ` · ${t('mapa.filtro.tipo')}: ${f.tipos.join(', ')}` : '';
  const txtMatchup =
    f.modoMatchup === 'fraco'
      ? ` · ${t('mapa.filtro.fracoContra')}`
      : f.modoMatchup === 'forte'
        ? ` · ${t('mapa.filtro.forteContra')}`
        : '';

  $('#mapa-rodape-txt').textContent =
    `${marcadoresVisiveis.length} de ${daArea.length} áreas em ${reg.rotulo}` +
    txtTipos +
    txtNivel +
    txtMatchup +
    // A dica ensina o GESTO, e o gesto não é o mesmo nos dois: no celular não existe roda.
    (movelAtivo() ? ` · ${t('mapa.gestoToque')}` : ' · roda do mouse para zoom, arraste para mover');

  const pronto = () => {
    // o pixel do marcador é relativo ao tamanho NATURAL da imagem daquela área
    mapaZoom.w = img.naturalWidth;
    mapaZoom.h = img.naturalHeight;
    if (areaNova || !mapaZoom.z) {
      mapaZoom.z = zoomMinimo(vp);
      mapaZoom.ancora = null;
    }
    plotarMarcadores();
    // abre já mostrando onde o jogador está caçando
    if (areaNova || !mapaZoom.ancorou) {
      mapaZoom.ancorou = true;
      $('#mapa-tela .marcador.on')?.scrollIntoView({ block: 'center', inline: 'center' });
    }
  };

  const src = `/assets/site/assets/maps/${reg.img}`;
  if (!img.src.endsWith(src)) {
    img.onload = pronto;
    img.src = src;
  } else if (img.complete && img.naturalWidth) pronto();
  else img.onload = pronto;
}

/** Quanto falta da trava de 3 s da hunt (0 = livre). Ignora a trava de 10 s do PvP. */
function restaCombateHuntMs() {
  if (huntSaidaLivreAgora()) return 0;
  return Math.max(0, estado.centroLivreEm - agoraSincronizado());
}

/**
 * As travas de trocar de área pelo Mapa: a do Centro Pokémon (3 s sem trocar dano) e a porta
 * de 10 s desde a última entrada. As duas também moram no servidor — aqui é para o Mapa
 * não fechar numa troca que ele vai recusar.
 */
function avisoTrocaDeHuntBloqueada() {
  const resta = restaCombateHuntMs();
  if (resta > 0) {
    toast(t('mapa.travaCombate', { s: (resta / 1000).toFixed(1) }));
    return true;
  }
  const porta = estado.trocaHuntLivreEm - agoraSincronizado();
  if (porta > 0) {
    toast(t('hunt.trocaEspera', { s: Math.ceil(porta / 1000) }));
    return true;
  }
  return false;
}

function ligarHoverHuntAnalyser() {
  const painel = $('#hunt-analyser');
  if (!painel || painel.dataset.hover) return;
  painel.dataset.hover = '1';
  // O × da ficha. Só aparece no celular (ver `mobile.css`): lá a ficha é uma folha que cobre o
  // mapa quase inteiro, e o "toque no mapa vazio fecha" não tem mapa vazio à vista para tocar —
  // quem abria uma área ficava preso nela até escolher caçar. No desktop ela some sozinha
  // quando o mouse sai do marcador.
  painel.querySelector('#ha-fechar')?.addEventListener('click', (ev) => {
    ev.stopPropagation();
    esconderHuntAnalyser();
  });
  painel.addEventListener('mouseenter', cancelarEsconderHuntAnalyser);
  painel.addEventListener('mouseleave', (ev) => {
    if (ev.relatedTarget?.closest('.marcador')) return;
    agendarEsconderHuntAnalyser();
  });
  painel.addEventListener(
    'wheel',
    (ev) => {
      if (!huntAnalyserVisivel()) return;
      ev.preventDefault();
      ev.stopPropagation();
      rolarHuntAnalyser(ev.deltaY);
    },
    { passive: false },
  );
}

function ligarGestosDoMapa() {
  const vp = $('#mapa-mundi');
  let arrasto = null;
  ligarHoverHuntAnalyser();

  vp.addEventListener(
    'wheel',
    (ev) => {
      // Com o analyser aberto sobre um marcador, a roda rola o painel — não dá zoom no mapa.
      if (huntAnalyserVisivel() && ev.target.closest('.marcador')) {
        ev.preventDefault();
        rolarHuntAnalyser(ev.deltaY);
        return;
      }
      ev.preventDefault();
      const r = vp.getBoundingClientRect();
      aplicarZoom(mapaZoom.z * Math.exp(-0.0016 * ev.deltaY), ev.clientX - r.left, ev.clientY - r.top);
    },
    { passive: false },
  );

  // A PINÇA. No celular não existe roda do mouse, e sem ela o mapa fica preso num único nível
  // de zoom — que num viewport de 380 px é o mapa inteiro em miniatura, com 139 marcadores
  // empilhados. Dois dedos na tela suspendem o arrasto e passam a mandar no zoom; o ponto
  // fixo é o MEIO entre os dedos, que é o que faz o mapa crescer de onde se está olhando.
  const dedos = new Map();
  let pinca = null;
  const meio = () => {
    const [a, b] = [...dedos.values()];
    return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, d: Math.hypot(a.x - b.x, a.y - b.y) };
  };

  vp.onpointerdown = (ev) => {
    // Só DEDO entra na conta da pinça. Com mouse o mapa se comporta exatamente como antes
    // desta função existir — e isso não é só elegância: um `pointerup` perdido (a janela some
    // no meio de um arrasto, o botão é solto fora da aba) deixaria um ponteiro velho no mapa,
    // e o próximo clique de mouse viraria "dois dedos" e daria um salto de zoom do nada.
    if (ev.pointerType === 'mouse') dedos.clear();
    else dedos.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    if (dedos.size === 2) {
      arrasto = null;
      vp.classList.remove('arrastando');
      pinca = { ...meio(), z: mapaZoom.z };
      return;
    }
    if (dedos.size > 2) return;
    if (ev.target.closest('.marcador')) return; // clicar num marcador não é arrastar
    arrasto = { x: ev.clientX, y: ev.clientY, sl: vp.scrollLeft, st: vp.scrollTop, moveu: false };
    vp.setPointerCapture(ev.pointerId);
    vp.classList.add('arrastando');
  };
  vp.onpointermove = (ev) => {
    if (dedos.has(ev.pointerId)) dedos.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    if (pinca && dedos.size >= 2) {
      const agora = meio();
      if (!pinca.d || !agora.d) return;
      // Um degrau de zoom refaz os 139 marcadores; a 60 Hz isso engasga o gesto. Uma
      // aplicação por quadro é o bastante — o dedo não anda mais rápido que a tela.
      pinca.pendente = agora;
      if (pinca.agendado) return;
      pinca.agendado = requestAnimationFrame(() => {
        if (!pinca) return;
        pinca.agendado = 0;
        const p = pinca.pendente;
        const r = vp.getBoundingClientRect();
        aplicarZoom(pinca.z * (p.d / pinca.d), p.x - r.left, p.y - r.top);
      });
      return;
    }
    if (!arrasto) return;
    const dx = ev.clientX - arrasto.x;
    const dy = ev.clientY - arrasto.y;
    if (Math.abs(dx) + Math.abs(dy) > 3) arrasto.moveu = true;
    vp.scrollLeft = arrasto.sl - dx;
    vp.scrollTop = arrasto.st - dy;
  };
  const soltar = (ev) => {
    if (ev) dedos.delete(ev.pointerId);
    if (dedos.size < 2) pinca = null;
    arrasto = null;
    vp.classList.remove('arrastando');
  };
  vp.onpointerup = soltar;
  vp.onpointercancel = soltar;

  vp.onclick = (ev) => {
    const b = ev.target.closest('.marcador');
    // Tocar no mapa vazio fecha a ficha. Com mouse ela some sozinha ao sair do marcador; com
    // dedo, sem esta saída, ela ficaria pendurada sobre metade do mapa até a próxima escolha.
    if (!b) {
      if (movelAtivo()) esconderHuntAnalyser();
      return;
    }
    // No celular quem escolhe a área é o botão da ficha, que o toque no marcador acabou de
    // abrir (ver `plotarMarcadores`) — trocar de hunt aqui puxaria o tapete de quem só quis
    // conferir quanto XP a área rende.
    if (movelAtivo()) return;
    if (avisoTrocaDeHuntBloqueada()) return;
    const h = estado.hunts.find((x) => x.slug === b.dataset.slug);
    if (!h || !liberada(h)) {
      if (h) toast(t('mapa.precisaNv', { n: h.nivel }));
      return;
    }
    enviar({ t: 'hunt.select', slug: b.dataset.slug });
    fecharModal();
  };
}

// -------------------------------------------------------------- Campeonato
//
// O TORNEIO — inscrição, lista de inscritos, a chave de eliminação dupla e a premiação.
//
// A tela segue a gramática das plataformas de torneio (start.gg, Battlefy): um CABEÇALHO com
// o que todo mundo quer saber de relance (fase, data, inscritos, formato, prêmio) e o botão de
// inscrição sempre à vista, e embaixo três abas — Participantes, Bracket e Premiação. O
// cabeçalho fica fora das abas de propósito: "estou inscrito?" é a pergunta de qualquer aba.
//
// Tudo o que é regra vem de `shared/campeonato.mjs`, o mesmo módulo que o servidor usa para
// recusar a inscrição e congelar as seeds. A chave desenhada aqui é a que `montarChave` monta
// no servidor, com as mesmas seeds.
//
// Na barra do topo o botão fica DEPOIS do Ginásio, fechando o trio da competição: PvP é o
// 1v1 ranqueado, Ginásio é o título de um tipo, e o Campeonato é a briga com dinheiro na
// mesa. O ícone é a King's Rock do pokesprite — a coroa, que é o que o torneio entrega.

/**
 * O pódio: posição, prêmio e a altura do degrau. O 1º no meio, como num pódio de verdade.
 *
 * Virou função quando o Amador chegou: os prêmios são de cada edição (1000/500/250 no Mundial,
 * 300/150/50 no Amador) e não mais uma constante do jogo. O `filter` deixa a porta aberta para
 * uma premiação de dois degraus sem precisar mexer no desenho.
 */
const podioDosPremios = (premios = []) => [
  { pos: 2, premio: premios[1], classe: 'prata', medalha: '🥈' },
  { pos: 1, premio: premios[0], classe: 'ouro', medalha: '🥇' },
  { pos: 3, premio: premios[2], classe: 'bronze', medalha: '🥉' },
].filter((d) => Number(d.premio) > 0);

/** `R$ 1.000` — o separador de milhar sai do idioma da tela, o símbolo é fixo (é real). */
const premioEmReais = (v) => `R$ ${num(v)}`;

const CAMP_ABAS = [
  { id: 'lista', ico: '📋', rotulo: 'camp.abaLista' },
  { id: 'participantes', ico: '👥', rotulo: 'camp.abaParticipantes' },
  { id: 'chave', ico: '🏆', rotulo: 'camp.abaChave' },
  { id: 'premiacao', ico: '💰', rotulo: 'camp.abaPremiacao' },
];

/** `#07` — a seed com dois dígitos, como as plataformas de torneio escrevem. */
const rotuloSeed = (s) => (s == null ? '—' : `#${String(s).padStart(2, '0')}`);

/** O pacote atual, ou um esqueleto com as regras fixas enquanto o primeiro não chega. */
const dadosCampeonato = () => estado.campeonato;

/**
 * As REGRAS da edição que a tela está mostrando, como o servidor as mandou.
 *
 * Enquanto o primeiro pacote não chega — ou quando o jogador clica numa linha da lista antes de
 * a resposta voltar —, vale o CALENDÁRIO local. É o mesmo módulo que o servidor usa, então as
 * datas, os prêmios e as restrições batem: é isso que permite desenhar o cabeçalho inteiro sem
 * esperar a rede, e é o mesmo contrato que a chave já tinha.
 */
function campAtual() {
  const doPacote = estado.campeonato?.campeonato;
  if (doPacote && (!estado.campSelecionado || doPacote.id === estado.campSelecionado)) return doPacote;
  return (estado.campSelecionado ? campeonatoPorId(estado.campSelecionado) : null)
    ?? doPacote ?? campeonatoAtivo(agoraDoServidor());
}

/** O tipo da edição aberta, para as classes de CSS e as chaves de texto. */
const campTipo = () => campAtual()?.tipo ?? 'mundial';

/** A fase pelo relógio do SERVIDOR — a tela vira sozinha na meia-noite do dia da luta. */
const faseCampeonatoAgora = () => faseDoCampeonato(agoraDoServidor(), campAtual());

/** O que `campeonato.*` manda junto: a edição que a tela está olhando. */
const idDoCampAberto = () => estado.campSelecionado ?? campAtual()?.id ?? null;

/**
 * A fase que o SELO mostra: a do relógio, refinada pelo andamento da chave — "Ao vivo" desde a
 * primeira onda, "Concluído" quando a grande final foi jogada.
 */
function faseVisivelCampeonato(d, fase) {
  if (fase === 'inscricoes') return fase;
  if (d?.chave?.concluidaEm) return 'concluido';
  if ((d?.chave?.onda ?? 0) > 0) return 'aoVivo';
  return fase;
}

/**
 * O que a chave já decidiu, do jeito que o módulo compartilhado come: `Map` de id →
 * resultado, as derrotas de cada seed e o pódio. Um cálculo por pintura — a lista é pequena.
 */
function contextoDaChave(d) {
  const res = new Map((d?.partidas ?? []).map((p) => [p.id, p]));
  return {
    res,
    derrotas: derrotasPorSeed(res),
    podio: d?.chave?.podio ?? null,
    andando: (d?.chave?.onda ?? 0) > 0,
  };
}

/** O nick de uma seed, pela lista de inscritos do pacote. */
const nickDaSeed = (d, seed) => (d?.inscritos ?? []).find((i) => i.seed === seed)?.nick ?? null;

function renderCampeonato() {
  const abas = CAMP_ABAS.map((a) => `
    <button type="button" class="camp-aba" data-camp-aba="${a.id}" role="tab">
      <span class="camp-aba-ico" aria-hidden="true">${a.ico}</span>${t(a.rotulo)}
      ${a.id === 'participantes' ? '<span class="camp-aba-n" id="camp-aba-n"></span>' : ''}
    </button>`).join('');
  return `
    <div class="camp-tela">
      <header class="camp-cab" id="camp-cab"></header>
      <div class="camp-faixa" id="camp-faixa" hidden></div>
      <div class="camp-abas" id="camp-abas" role="tablist">${abas}</div>
      <div class="camp-painel" id="camp-painel" role="tabpanel"></div>
    </div>`;
}

/** Abre a tela: liga as abas, pede o pacote e desenha o que já dá para desenhar. */
function montarCampeonato() {
  for (const bt of document.querySelectorAll('.camp-aba')) {
    bt.onclick = () => {
      if (estado.campAba === bt.dataset.campAba) return;
      estado.campAba = bt.dataset.campAba;
      pintarCampeonato();
    };
  }
  enviar({ t: 'campeonato.info', id: idDoCampAberto() });
  pintarCampeonato();
}

/**
 * Abre UMA edição a partir da lista: guarda o id, pula para os Participantes e pede o pacote
 * dela. O pacote velho é mantido na tela até o novo chegar — trocar por um esqueleto faria a
 * aba piscar em branco a cada clique.
 */
function abrirCampeonato(id) {
  if (!id) return;
  estado.campSelecionado = id;
  estado.campAba = 'participantes';
  estado.campBusca = '';
  enviar({ t: 'campeonato.info', id });
  pintarCampeonato();
}

/** Volta para a lista. */
function voltarParaListaDeCampeonatos() {
  estado.campAba = 'lista';
  pintarCampeonato();
}

function aoReceberCampeonato(m) {
  if (m.recusa) {
    estado.campEnviando = false;
    if (estado.campSalvandoEquipe) {
      estado.campSalvandoEquipe = false;
      pintarFolhaDaEquipe?.();
    }
    toast(t(m.recusa, { nivel: num(campAtual().nivelMin), max: PVP_TIME_MAX }));
    if (estado.modalAberto === 'campeonato') pintarCabecalhoCampeonato();
    return;
  }
  // A fita de uma partida vai direto para o player, sem mexer na aba.
  if (m.fita) return abrirFitaDoCampeonato(m.fita);
  // O AVISO global de que a chave andou. Não traz a chave: só quem está olhando pede a aba de
  // novo, e com um atraso sorteado — sem ele, a onda viraria mil pedidos no mesmo segundo.
  if (m.andou) {
    // O aviso diz QUAL edição andou. Com dois campeonatos por mês, um deles pode estar lutando
    // enquanto o jogador olha o outro — e pedir a aba de novo aí seria uma repintura à toa.
    // A lista também importa: ela mostra a fase e o pódio de todas.
    const olhando = m.andou.id && m.andou.id === idDoCampAberto();
    if (estado.modalAberto === 'campeonato' && (olhando || estado.campAba === 'lista')) {
      setTimeout(() => {
        if (estado.modalAberto === 'campeonato') enviar({ t: 'campeonato.info', id: idDoCampAberto() });
      }, Math.random() * 4000);
    }
    return;
  }
  const { t: _tipo, acao, ...pacote } = m;
  estado.campeonato = pacote;
  // O servidor manda de volta QUAL edição respondeu (ele resolve o id, e cai no ativo quando o
  // pedido veio sem um). Seguir a resposta é o que mantém a tela e o servidor falando da mesma
  // edição mesmo quando duas respostas chegam fora de ordem.
  if (pacote.campeonato?.id) estado.campSelecionado = pacote.campeonato.id;
  estado.campEnviando = false;
  if (acao === 'inscreveu') toast(t('camp.inscreveuOk', { seed: rotuloSeed(pacote.eu?.seed) }));
  if (acao === 'cancelou') toast(t('camp.cancelouOk'));
  if (acao === 'equipe' || acao === 'equipePvp') {
    estado.campSalvandoEquipe = false;
    estado.campEquipeSel = null;
    document.querySelector('.cm-folha:has(.campeq)')?.remove();
    toast(t(acao === 'equipe' ? 'camp.equipeSalva' : 'camp.equipeVoltouPvp'));
  }
  if (estado.modalAberto === 'campeonato') pintarCampeonato();
}

/**
 * Quem da equipe anunciada pelo servidor REALMENTE entra em campo.
 *
 * Duas peneiras, e as duas valem para o congelamento também: quem já não está na coleção (foi
 * vendido ou anunciado depois da escolha) e quem a restrição do campeonato barra. A segunda é a
 * que faltava: a equipe de reserva é a do PvP Ranqueado, que nunca passou por conferência
 * nenhuma, e num Amador o congelamento deixa o shiny e o P5 dela de fora
 * (`equipesDaPartida`). Sem ela a faixa mostrava cinco casas cheias para quem vai lutar com
 * três — e mentia justamente no número que ela existe para dizer. A regra é a MESMA do
 * servidor, de `shared/campeonato.mjs`.
 */
function equipeQueVaiLutar(eu) {
  const porId = new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  const regras = campAtual();
  const ids = eu?.equipe?.ids ?? [];
  const naColecao = ids.map((id) => porId.get(id)).filter(Boolean);
  const vivos = naColecao.filter((pk) => !porQueNaoPodeLutar(pk, regras));
  return { vivos, barrados: naColecao.length - vivos.length, sumiram: ids.length - naColecao.length };
}

/**
 * A equipe que vai lutar, na faixa abaixo do cabeçalho — só para o inscrito, e só até o prazo.
 *
 * Cinco casas na ordem de luta, a FONTE ("escolhida para o campeonato" ou "a do PvP") e o botão
 * que abre a escolha. Os ids vêm do servidor e o desenho sai da coleção desta tela: quem foi
 * vendido, anunciado ou barrado pela restrição some da casa e ganha o aviso — o congelamento
 * também o deixaria de fora. Os sprites entram depois do HTML, em `pintarCasasDaEquipe`.
 */
function htmlEquipeDoCampeonato(eu) {
  const { vivos, barrados, sumiram } = equipeQueVaiLutar(eu);
  const casas = Array.from({ length: PVP_TIME_MAX }, (_, i) => {
    const pk = vivos[i];
    return pk
      ? `<span class="camp-eq-casa cheia" data-pk="${pk.id}"
               title="${escapar(`${pk.shiny ? '✨ ' : ''}${pk.nome} · ${t('painel.nivelCurto')}${pk.level}`)}"></span>`
      : '<span class="camp-eq-casa"></span>';
  }).join('');
  // Barrado todo mundo, a faixa não diz "você não tem equipe" (ele tem, e cheia): diz que ela
  // não serve para ESTE campeonato, que é a frase que leva ao botão de escolher outra.
  const fonte = vivos.length
    ? (eu.equipe?.fonte === 'campeonato' ? 'camp' : 'pvp')
    : (barrados ? 'barrada' : 'vazia');
  const nota = {
    camp: t('camp.equipeFonteCamp', PRAZO_EQUIPE()),
    pvp: t('camp.equipeFontePvp'),
    vazia: t('camp.equipeVazia'),
    barrada: t('camp.equipeBarradaToda'),
  }[fonte];
  const alerta = fonte === 'vazia' || fonte === 'barrada';
  return `
    <div class="camp-eq">
      <span class="camp-eq-titulo">${t('camp.equipeTitulo')}</span>
      <div class="camp-eq-casas">${casas}</div>
      <span class="camp-eq-nota${alerta ? ' alerta' : ''}">${alerta ? '⚠ ' : ''}${nota}${
        barrados && vivos.length ? ` <b>${t('camp.equipeBarrados', { n: barrados })}</b>` : ''}${
        sumiram ? ` <b>${t('camp.equipeSumiu', { n: sumiram })}</b>` : ''}</span>
    </div>
    <button type="button" class="camp-btn camp-btn-mini" id="camp-equipe-abrir">${t('camp.equipeSelecionar')}</button>`;
}

function pintarCasasDaEquipe(host) {
  const porId = new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  for (const casa of host.querySelectorAll('.camp-eq-casa[data-pk]')) {
    const pk = porId.get(Number(casa.dataset.pk));
    if (pk) casa.appendChild(spritePokemon(pk, 32));
  }
}

/** Os filtros da folha de equipe, fora da função (como os da Oferenda): sobrevivem ao repinte. */
const campEqFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', soShiny: false, local: 'todos' };

/** Repinta a folha de equipe aberta, se houver uma. Trocada por `null` quando ela fecha. */
let pintarFolhaDaEquipe = null;

/**
 * A folha "Selecionar minha Equipe".
 *
 * A coleção inteira — equipe e depot, como no seletor do PvP Ranqueado, porque a luta é a mesma —
 * com até cinco escolhidos na ORDEM do clique (o número no card é a ordem em que entram em campo).
 * Nada é gravado ao clicar: o rascunho só vai ao servidor no "Salvar equipe", que confere tudo de
 * novo (`campeonato.equipe`). "Usar a equipe do PvP" apaga a escolha e volta a valer a do
 * Ranqueado — é o que acontece com quem nunca abre esta folha.
 */
function abrirEquipeDoCampeonato() {
  const d = estado.campeonato;
  if (!d?.eu?.inscrito) return;
  const todos = [...(estado.eu?.pokemons ?? [])];
  if (!todos.length) return toast(t('pvp.semPokemon'));
  const porId = new Map(todos.map((pk) => [pk.id, pk]));
  // O rascunho parte da equipe que vale hoje (a escolhida ou, sem ela, a do PvP), só com quem
  // ainda está na coleção.
  // Num campeonato com restrição (o Amador), o que não pode lutar já sai do rascunho: a equipe
  // de partida pode ser a do PvP, e ela não passou por conferência nenhuma.
  const regras = campAtual();
  estado.campEquipeSel = (d.eu.equipe?.ids ?? [])
    .filter((id) => porId.has(id) && !porQueNaoPodeLutar(porId.get(id), regras))
    .slice(0, PVP_TIME_MAX);

  const { corpo, fechar } = folhaMercado(t('camp.equipeFolhaTitulo'));
  corpo.classList.add('dmpk', 'campeq');
  corpo.innerHTML = `
    <p class="dlg-aviso info campeq-nota">${dlgIcone('trofeu', 18)}<span>${t('camp.equipeFolhaNota', { max: PVP_TIME_MAX, ...PRAZO_EQUIPE() })}</span></p>
    ${temRestricao(regras)
      ? `<p class="dlg-aviso campeq-restr">${dlgIcone('xis', 18)}<span>${t('camp.equipeFolhaRestricao')}</span></p>`
      : ''}
    <div class="campeq-forms" id="campeq-forms" hidden></div>
    <div class="dmpk-topo">
      <span class="cm-busca-caixa">${lupa()}<input id="campeq-busca" class="cm-busca" autocomplete="off"
             maxlength="32" placeholder="${escapar(t('camp.equipeBusca'))}" value="${escapar(campEqFiltro.busca)}"></span>
      <label class="auto-linha dmpk-shiny"><span>${t('amigos.anexarSoShiny')}</span>
        <input type="checkbox" id="campeq-shiny"${campEqFiltro.soShiny ? ' checked' : ''}></label>
      <span class="shl-conta" id="campeq-conta"></span>
    </div>
    <div class="dmpk-filtros" id="campeq-filtros"></div>
    <div class="mk-grade cm-pk-escolha-grade cm-rolagem" id="campeq-grade"></div>
    <div class="campeq-rodape">
      <button type="button" class="camp-btn sec camp-btn-mini" id="campeq-pvp">${t('camp.equipeUsarPvp')}</button>
      <button type="button" class="camp-btn" id="campeq-salvar">${t('camp.equipeSalvar')}</button>
    </div>`;

  const grade = corpo.querySelector('#campeq-grade');
  const conta = corpo.querySelector('#campeq-conta');
  const btSalvar = corpo.querySelector('#campeq-salvar');
  const btPvp = corpo.querySelector('#campeq-pvp');
  const forms = corpo.querySelector('#campeq-forms');
  // O armário de formações do PvP vem com a aba PvP; quem abre esta folha sem ter passado por lá
  // pede só a lista. A resposta repinta a folha (ver `aoReceberPvp`).
  if (estado.pvpFormacoes == null) enviar({ t: 'pvp.formacoes' });

  /**
   * As FORMAÇÕES salvas, uma por botão: o clique preenche a seleção com a escalação (na ordem),
   * sem gravar — o "Salvar equipe" continua sendo o único que grava, como no resto da folha. Quem
   * não pode lutar aqui (restrição do Amador) ou saiu da coleção fica de fora, com aviso.
   */
  function pintarFormacoes() {
    const lista = estado.pvpFormacoes ?? [];
    forms.hidden = !lista.length;
    if (!lista.length) return;
    const sel = estado.campEquipeSel ?? [];
    forms.innerHTML = `<span class="campeq-forms-rot">${t('camp.equipeFormacoes')}</span>${lista.map((f) => {
      const taxa = taxaDaFormacao(f);
      return `<button type="button" class="camp-btn sec camp-btn-mini campeq-form${mesmaEscalacao(f.ids, sel) ? ' on' : ''}" data-slot="${f.slot}"
                title="${escapar(t('camp.equipeFormacaoDica'))}">
                <b>${escapar(f.nome)}</b>${taxa != null ? `<span class="pvp-form-pct ${classeDaTaxa(taxa)}">${taxa}%</span>` : ''}
              </button>`;
    }).join('')}`;
    for (const bt of forms.querySelectorAll('[data-slot]')) {
      bt.onclick = () => {
        if (estado.campSalvandoEquipe) return;
        const f = lista.find((x) => x.slot === Number(bt.dataset.slot));
        if (!f) return;
        const ids = f.ids
          .filter((id) => porId.has(id) && !porQueNaoPodeLutar(porId.get(id), regras))
          .slice(0, PVP_TIME_MAX);
        if (!ids.length) return toast(t('camp.equipeFormacaoNada'));
        estado.campEquipeSel = ids;
        if (ids.length < f.ids.length) toast(t('camp.equipeFormacaoFora', { n: f.ids.length - ids.length }));
        pintar();
      };
    }
  }

  function pintar() {
    pintarFormacoes();
    const sel = estado.campEquipeSel ?? [];
    const busca = campEqFiltro.busca.trim().toLowerCase();
    const piso = ivMinDoFiltro(campEqFiltro.ivMin);
    const colecao = conjuntoColecaoCliente();
    // A RESTRIÇÃO do campeonato entra ANTES de qualquer filtro do jogador: no Amador, shiny e P5
    // simplesmente não existem nesta folha. Esconder é cortesia — quem recusa de verdade é o
    // servidor, com a mesma `porQueNaoPodeLutar` (ver `conferirTime`).
    const podem = todos.filter((k) => !porQueNaoPodeLutar(k, regras));
    const lista = ordenarMarketPokemon(
      podem.filter(
        (k) => (!campEqFiltro.soShiny || k.shiny) && passaLocal(k, campEqFiltro.local, colecao)
          && depotPassaFiltros(k, busca, campEqFiltro.tipo, piso),
      ),
      campEqFiltro.ordem,
    );
    const fora = todos.length - podem.length;
    conta.textContent = t('camp.equipeContagem', { n: sel.length, max: PVP_TIME_MAX });
    btSalvar.disabled = !!estado.campSalvandoEquipe;
    btPvp.disabled = !!estado.campSalvandoEquipe;
    btSalvar.textContent = estado.campSalvandoEquipe ? t('camp.enviando') : t('camp.equipeSalvar');
    grade.innerHTML = '';
    if (!lista.length) {
      // Grade vazia tem duas causas bem diferentes, e dizer a errada manda o jogador procurar
      // o filtro que não é: a coleção INTEIRA barrada pela restrição, ou só o filtro apertado.
      grade.innerHTML = `<div class="cm-vazio">${
        fora && !podem.length ? t('camp.equipeTodosBarrados') : t('amigos.anexarVazio')
      }</div>`;
      return;
    }
    for (const k of lista) {
      const idx = sel.indexOf(k.id);
      const on = idx >= 0;
      const cheio = !on && sel.length >= PVP_TIME_MAX;
      const card = cardPokemonEscolha(k, {
        colecao,
        aoVerFicha: () => abrirFichaDoPokemon(k),
        // A seleção é lida NA HORA do clique, e não a do desenho: o card pode ser de uma pintura
        // anterior (dois cliques rápidos), e o rascunho velho apagaria o clique do meio.
        aoSelecionar: () => {
          if (estado.campSalvandoEquipe) return;
          const atual = estado.campEquipeSel ?? [];
          if (atual.includes(k.id)) estado.campEquipeSel = atual.filter((x) => x !== k.id);
          else if (atual.length >= PVP_TIME_MAX) return toast(t('camp.equipeCheia', { max: PVP_TIME_MAX }));
          else estado.campEquipeSel = [...atual, k.id];
          pintar();
        },
      });
      card.dataset.id = k.id;
      if (on) card.classList.add('ofrpk-on');
      if (cheio) card.classList.add('ofrpk-bloqueado');
      if (on) {
        const marca = document.createElement('span');
        marca.className = 'ofrpk-ordem';
        marca.textContent = idx + 1;
        card.appendChild(marca);
      }
      grade.appendChild(card);
    }
  }

  const salvar = (ids) => {
    if (estado.campSalvandoEquipe) return;
    estado.campSalvandoEquipe = true;
    pintar();
    enviar({ t: 'campeonato.equipe', id: idDoCampAberto(), pokemonIds: ids });
    // Resposta perdida não pode deixar o botão preso.
    setTimeout(() => {
      if (!estado.campSalvandoEquipe) return;
      estado.campSalvandoEquipe = false;
      pintarFolhaDaEquipe?.();
    }, 10_000);
  };
  btSalvar.onclick = () => salvar(estado.campEquipeSel ?? []);
  btPvp.onclick = () => salvar([]);

  corpo.querySelector('#campeq-filtros').appendChild(criarFiltrosSelect({
    tipo: campEqFiltro.tipo,
    ordem: campEqFiltro.ordem,
    ivMin: campEqFiltro.ivMin,
    local: campEqFiltro.local,
    locais: LOCAIS_TODOS,
    ordens: MK_POKEMON_ORDENS,
    ordemI18n: MK_POKEMON_ORDEM_I18N,
    onChange: (campo, valor) => {
      if (campo === 'ordem') campEqFiltro.ordem = valor || 'padrao';
      else campEqFiltro[campo] = valor;
      pintar();
    },
  }));
  const campoBusca = corpo.querySelector('#campeq-busca');
  campoBusca.oninput = (ev) => {
    campEqFiltro.busca = ev.target.value;
    pintar();
  };
  corpo.querySelector('#campeq-shiny').onchange = (ev) => {
    campEqFiltro.soShiny = ev.target.checked;
    pintar();
  };
  dobrarFiltrosNoCelular({
    campos: [corpo.querySelector('.dmpk-shiny'), corpo.querySelector('#campeq-filtros')],
    botaoEm: corpo.querySelector('.dmpk-topo'),
    host: corpo,
  });
  dobrarNotaNoCelular(corpo.querySelector('.campeq-nota'));

  pintarFolhaDaEquipe = () => {
    if (!corpo.isConnected) {
      pintarFolhaDaEquipe = null;
      return;
    }
    pintar();
  };
  repintarComAColecao(corpo, pintar);
  corpo.closest('.cm-folha')?.querySelector('.cm-fechar')?.addEventListener('click', () => {
    pintarFolhaDaEquipe = null;
    estado.campEquipeSel = null;
    fechar();
  });

  pintar();
  if (!movelAtivo()) campoBusca.focus();
}

/** Abre o player na fita de uma partida da chave. */
/**
 * O prazo da EQUIPE para os textos: dia 29 e a hora em que ela trava.
 *
 * É outro prazo que o das inscrições — elas fecham na virada do 28 para o 29, e a equipe
 * segue aberta o dia 29 inteiro. Um helper só para os dois nunca saírem trocados na tela.
 */
const PRAZO_EQUIPE = () => ({
  dia: escapar(dataDaNovidade(campAtual().diaEquipe)),
  hora: escapar(campAtual().horaEquipe),
});

function abrirFitaDoCampeonato(f) {
  estado.campPedindoFita = null;
  const nome = (lado) => lado?.nick ?? t('camp.vagaVazia');
  abrirReplayGuerra({
    replay: f.replay,
    titulo: t('camp.replayTitulo', { partida: idDaPartida(f.partida), a: nome(f.a), b: nome(f.b) }),
  });
}

function pedirFitaDoCampeonato(id) {
  if (!id || estado.campPedindoFita === id) return;
  estado.campPedindoFita = id;
  enviar({ t: 'campeonato.fita', id: idDoCampAberto(), partida: id });
  // Resposta perdida não pode travar o botão para sempre.
  setTimeout(() => {
    if (estado.campPedindoFita === id) estado.campPedindoFita = null;
  }, 8000);
}

/** Repinta a tela inteira: cabeçalho, marcação das abas e a aba aberta. */
function pintarCampeonato() {
  if (!$('.camp-tela')) return;
  const aba = CAMP_ABAS.some((a) => a.id === estado.campAba) ? estado.campAba : 'lista';
  estado.campAba = aba;
  const naLista = aba === 'lista';
  // A BARRA DE ABAS inteira sai de cena na lista. Participantes, Bracket e Premiação são de UMA
  // edição, e antes de o jogador escolher uma elas não têm o que mostrar; deixá-las ali (ainda
  // que apagadas) era oferecer três botões que não levam a lugar nenhum logo acima da única
  // coisa que a tela quer que se clique, que é a lista. Com uma edição aberta, a barra volta
  // inteira — e a aba "Campeonatos" é o segundo caminho de volta, ao lado do ‹ do cabeçalho.
  const barra = $('#camp-abas');
  if (barra) barra.hidden = naLista;
  for (const bt of document.querySelectorAll('.camp-aba')) {
    const on = bt.dataset.campAba === aba;
    bt.classList.toggle('on', on);
    bt.setAttribute('aria-selected', on ? 'true' : 'false');
  }
  const n = $('#camp-aba-n');
  if (n) n.textContent = naLista || !dadosCampeonato() ? '' : num(dadosCampeonato().total ?? 0);
  pintarCabecalhoCampeonato();
  const painel = $('#camp-painel');
  if (!painel) return;
  painel.scrollTop = 0;
  if (naLista) pintarListaDeCampeonatos(painel);
  else if (aba === 'participantes') pintarParticipantes(painel);
  else if (aba === 'chave') pintarAbaChave(painel);
  else pintarPremiacao(painel);
}

// ------------------------------------------------------------- aba: a LISTA
//
// A porta de entrada. Com Mundial e Amador todo mês, "Torneio" não abre mais num campeonato: abre
// na LISTA deles — o que está acontecendo, o que vem a seguir e o que já passou.
//
// Cada linha carrega o que decide o clique: qual é, quando, quanto paga, se aceita shiny, em que
// pé está e — nas que já acabaram — quem ganhou e se as fitas ainda abrem.

/** `Campeonato Mundial #3`. */
const nomeDoCampeonato = (c) => t('camp.tituloTipo', { tipo: t(`camp.tipo.${c.tipo}`), n: num(c.numero) });

/** O selo de fase de uma linha da lista, já refinado pelo andamento. */
function faseDaLinha(c, agora) {
  const fase = faseDoCampeonato(agora, c);
  if (fase !== 'chaveado') return fase;
  if (c.concluidaEm) return 'concluido';
  return (c.onda ?? 0) > 0 ? 'aoVivo' : fase;
}

function pintarListaDeCampeonatos(painel) {
  const d = dadosCampeonato();
  const lista = d?.lista ?? [];
  if (!lista.length) {
    painel.innerHTML = `<p class="camp-vazio">${t('camp.carregando')}</p>`;
    return;
  }
  const agora = agoraDoServidor();
  const linhas = lista.map((c) => {
    const fase = faseDaLinha(c, agora);
    const encerrado = agora >= c.fimEm;
    const podio = c.podio;
    // As fitas: `replaysAbertos` é do servidor (ele calcula com o mesmo calendário), e `comFita`
    // diz se ainda existe alguma no banco. As duas coisas precisam ser verdade para o botão de
    // assistir aparecer lá dentro — aqui a linha só conta ao jogador qual das duas é.
    // `Infinity` só acontece se o calendário não achar um campeonato seguinte, o que não ocorre
    // no calendário real — mas uma data vazia na tela é pior do que não dizer o prazo.
    const ateQuando = diaIsoDe(c.replaysAte);
    const fitas = !encerrado ? ''
      : c.replaysAbertos && c.comFita > 0
        ? `<span class="camp-lin-fitas ok">▶ ${ateQuando
            ? t('camp.replaysAte', { dia: escapar(dataDaNovidade(ateQuando)) })
            : t('camp.replaysAbertos')}</span>`
        : `<span class="camp-lin-fitas">${t('camp.replaysFechados')}</span>`;
    return `
      <button type="button" class="camp-linha tipo-${escapar(c.tipo)}${encerrado ? ' passado' : ''}" data-camp="${escapar(c.id)}">
        <img class="camp-lin-logo" src="${escapar(c.logo)}" alt="" width="72" height="74" loading="lazy">
        <div class="camp-lin-corpo">
          <div class="camp-lin-topo">
            <b class="camp-lin-nome">${escapar(nomeDoCampeonato(c))}</b>
            <span class="camp-fase fase-${fase}">${t(`camp.fase.${fase}`)}</span>
          </div>
          <div class="camp-lin-fatos">
            <span>📅 ${escapar(dataDaNovidade(c.dia))}</span>
            <span>👥 ${num(encerrado ? (c.participantes ?? c.inscritos) : c.inscritos)}</span>
            <span class="ouro">${escapar(premioEmReais((c.premios ?? []).reduce((a, b) => a + b, 0)))}</span>
            ${temRestricao(c) ? `<span class="camp-lin-restr">🚫 ${t('camp.semShinyP5')}</span>` : ''}
          </div>
          ${podio?.campeao != null
            ? `<div class="camp-lin-podio">🏆 ${t('camp.campeao')}: <b>${escapar(nickDoPodio(c, podio.campeao))}</b></div>`
            : ''}
          ${fitas}
        </div>
        <span class="camp-lin-seta" aria-hidden="true">›</span>
      </button>`;
  }).join('');
  painel.innerHTML = `<div class="camp-lista">${linhas}</div>`;
  for (const bt of painel.querySelectorAll('.camp-linha')) {
    bt.addEventListener('click', () => abrirCampeonato(bt.dataset.camp));
  }
}

/** `2026-10-14` a partir de um instante — para escrever a data do fim das fitas. */
const diaIsoDe = (ms) => (Number.isFinite(ms) ? new Date(ms - 3 * 3600_000).toISOString().slice(0, 10) : '');

/**
 * O nick do campeão de uma linha da lista.
 *
 * A lista NÃO carrega os inscritos de cada edição — seriam centenas de cards por linha —, então
 * o nick só é conhecido quando a edição em questão é a que está carregada. Nas outras, a seed
 * (`#03`) é o que dá para mostrar, e ela some assim que o jogador abre a edição.
 */
function nickDoPodio(c, seed) {
  // O resumo da lista já traz o nick do campeão (`campeaoNick`, em `resumos`). Os outros dois
  // lugares do pódio não: eles só aparecem na aba Premiação, com a edição carregada.
  if (c.podio?.campeao === seed && c.podio.campeaoNick) return c.podio.campeaoNick;
  const d = dadosCampeonato();
  if (d?.campeonato?.id === c.id) return nickDaSeed(d, seed) ?? rotuloSeed(seed);
  return rotuloSeed(seed);
}

// ------------------------------------------------------------ o cabeçalho

function pintarCabecalhoCampeonato() {
  const host = $('#camp-cab');
  if (!host) return;
  // Na LISTA não há edição aberta: nem cabeçalho nem faixa da equipe. A saída fica AQUI, e não
  // só em `pintarCampeonato`, porque esta função tem outros chamadores — o `aplicarEstado`
  // repinta o cabeçalho a cada mudança de nível, e sem esta linha a faixa voltava por cima da
  // lista alguns segundos depois de ela ter sido desenhada.
  if (estado.campAba === 'lista') {
    host.hidden = true;
    const f = $('#camp-faixa');
    if (f) f.hidden = true;
    return;
  }
  host.hidden = false;
  const d = dadosCampeonato();
  const C = campAtual();
  const fase = faseCampeonatoAgora();
  const faseVisivel = faseVisivelCampeonato(d, fase);
  const total = d?.total;
  const premioTotal = (C.premios ?? []).reduce((s, v) => s + v, 0);
  const fatos = [
    { v: total == null ? '…' : num(total), r: t('camp.fatoInscritos') },
    { v: t('camp.fatoFormatoV'), r: t('camp.fatoFormato') },
    { v: t('camp.fatoNivelV', { n: num(C.nivelMin) }), r: t('camp.fatoNivel') },
    { v: premioEmReais(premioTotal), r: t('camp.fatoPremio'), classe: 'ouro' },
  ];
  host.className = `camp-cab tipo-${C.tipo}`;
  host.innerHTML = `
    <button type="button" class="camp-voltar" id="camp-voltar" title="${escapar(t('camp.voltarLista'))}">‹</button>
    <img class="camp-cab-logo" src="${escapar(C.logo ?? '/img/campeonato-logo.png')}" alt="" width="200" height="204">
    <div class="camp-cab-info">
      <div class="camp-cab-selos">
        <span class="camp-fase fase-${faseVisivel}">${t(`camp.fase.${faseVisivel}`)}</span>
        <span class="camp-cab-data">📅 ${escapar(dataDaNovidade(C.dia))}</span>
        ${temRestricao(C) ? `<span class="camp-cab-restr">🚫 ${t('camp.semShinyP5')}</span>` : ''}
      </div>
      <h3 class="camp-cab-titulo">${escapar(nomeDoCampeonato(C))}</h3>
      <div class="camp-fatos">
        ${fatos.map((f) => `
          <div class="camp-fato${f.classe ? ` ${f.classe}` : ''}">
            <b>${escapar(f.v)}</b><span>${escapar(f.r)}</span>
          </div>`).join('')}
      </div>
    </div>
    <div class="camp-cab-acao">${htmlAcaoCampeonato(d, fase)}</div>`;
  // A FAIXA do inscrito: a equipe que vai lutar. Fica fora do cabeçalho, com a largura toda:
  // dentro da coluna da ação ela dobrava a altura do cabeçalho e espremia a chave logo abaixo.
  // Enquanto a equipe abre ela mostra a equipe e a escolha; depois, a equipe já congelou, e o
  // que resta é dizer com quantos ela congelou — ou que as partidas desse inscrito são W.O.
  //
  // O que manda aqui é o PRAZO DA EQUIPE, não a fase: no dia de análise a fase já é "chaveado"
  // e a escolha continua aberta até as 23h. Travar pela fase esconderia a escolha exatamente
  // no dia em que a chave existe e ela finalmente importa.
  const faixa = $('#camp-faixa');
  if (faixa) {
    const eu = d?.eu ?? {};
    const abre = d?.campeonato ? d.campeonato.equipeAberta !== false : fase === 'inscricoes';
    let html = '';
    let tipo = 'aviso';
    if (abre && eu.inscrito) {
      html = htmlEquipeDoCampeonato(eu);
      // Pela equipe que de fato LUTA, e não pelos ids anunciados: quem só tem shiny e P5 num
      // Amador vai a W.O., e a faixa verde de "equipe pronta" diria o contrário.
      tipo = equipeQueVaiLutar(eu).vivos.length ? 'equipe' : 'aviso';
    } else if (!abre && eu.inscrito && eu.timeCongelado === 0) {
      html = `<span>⚠ ${t('camp.semEquipeWo')}</span>`;
    } else if (!abre && eu.inscrito && eu.timeCongelado > 0) {
      html = `<span>🔒 ${t('camp.equipeCongelou', { n: eu.timeCongelado })}</span>`;
      tipo = 'equipe';
    }
    faixa.hidden = !html;
    faixa.classList.toggle('camp-faixa-equipe', tipo === 'equipe');
    faixa.innerHTML = html;
    pintarCasasDaEquipe(faixa);
  }
  ligarAcaoCampeonato();
  tiqueCampeonato();
}

/**
 * O canto da ação — o único lugar da tela que muda o estado do jogador.
 *
 * Os casos seguem a pergunta que o jogador tem na cabeça: "posso entrar?" (botão ou o motivo
 * do não), "já entrei?" (a seed e a saída) e, depois do prazo, "onde eu caí?".
 */
function htmlAcaoCampeonato(d, fase) {
  const contagem = '<div class="camp-contagem" id="camp-contagem"></div>';
  if (!d) {
    return `<button type="button" class="camp-btn" disabled>${t('camp.carregando')}</button>${contagem}`;
  }
  const eu = d.eu ?? {};

  // Ainda nem abriu: o que há para dizer é QUANDO abre, e o relógio embaixo diz o resto.
  if (fase === 'futuro') {
    return `
      <div class="camp-fechado">${t('camp.aindaNaoAbriu', {
        dia: escapar(dataDaNovidade(diaIsoDe(campAtual().inscricoesDe))),
      })}</div>
      ${contagem}`;
  }

  if (fase === 'inscricoes') {
    if (eu.inscrito) {
      return `
        <div class="camp-inscrito">
          <span class="camp-inscrito-ok">✔ ${t('camp.inscrito')}</span>
          <span class="camp-inscrito-seed">${t('camp.suaSeed')} <b>${rotuloSeed(eu.seed)}</b></span>
        </div>
        <button type="button" class="camp-btn sec camp-btn-mini" id="camp-cancelar" ${estado.campEnviando ? 'disabled' : ''}>
          ${t('camp.cancelar')}
        </button>
        ${contagem}`;
    }
    const nivel = estado.eu?.level ?? 0;
    const falta = nivel < campAtual().nivelMin;
    return `
      <button type="button" class="camp-btn camp-btn-registrar" id="camp-registrar"
              ${falta || estado.campEnviando ? 'disabled' : ''}>
        ${estado.campEnviando ? t('camp.enviando') : t('camp.registrar')}
      </button>
      ${falta
        ? `<div class="camp-requisito">${t('camp.requisitoNivel', { n: num(campAtual().nivelMin), atual: num(nivel) })}</div>`
        : ''}
      ${contagem}`;
  }

  // Acabou: o campeão toma o canto, e quem subiu ao pódio ganha a frase dele.
  const podio = d.chave?.concluidaEm ? d.chave.podio : null;
  if (podio) {
    const meu = eu.inscrito
      ? { [podio.campeao]: 'camp.voceCampeao', [podio.vice]: 'camp.voceVice', [podio.terceiro]: 'camp.voceTerceiro' }[eu.seed]
      : null;
    return `
      <div class="camp-campeao">
        <span>🏆 ${t('camp.campeao')}</span>
        <b>${escapar(nickDaSeed(d, podio.campeao) ?? '—')}</b>
      </div>
      ${meu ? `<div class="camp-meu-podio">${t(meu)}</div>` : ''}
      <button type="button" class="camp-btn sec camp-btn-mini" id="camp-ver-chave">${t('camp.verChave')}</button>
      ${contagem}`;
  }

  if (eu.inscrito) {
    const { derrotas, andando } = contextoDaChave(d);
    const n = derrotas.get(eu.seed) ?? 0;
    const situacao = andando ? (n >= 2 ? 'eliminado' : n === 1 ? 'perdedores' : 'invicto') : null;
    return `
      <div class="camp-inscrito${situacao ? ` sit-${situacao}` : ''}">
        <span class="camp-inscrito-ok">${situacao ? t(`camp.status.${situacao}`) : `✔ ${t('camp.inscrito')}`}</span>
        <span class="camp-inscrito-seed">${t('camp.suaSeed')} <b>${rotuloSeed(eu.seed)}</b></span>
      </div>
      ${d.chave ? `<button type="button" class="camp-btn sec camp-btn-mini" id="camp-ver-minha">${t('camp.verMinhaChave')}</button>` : ''}
      ${contagem}`;
  }
  return `
    <div class="camp-fechado">${t(fase === 'encerrado' ? 'camp.encerrado' : 'camp.inscricoesEncerradas')}</div>
    ${d.chave ? `<button type="button" class="camp-btn sec camp-btn-mini" id="camp-ver-chave">${t('camp.verChave')}</button>` : ''}
    ${contagem}`;
}

/** O emblema do torneio, como arte de ator do palco. */
const dlgArteCampeonato = (C) =>
  `<span class="dlg-ator-fig"><img class="dlg-camp-logo" src="${escapar(C?.logo ?? '/img/campeonato-logo.png')}" alt=""></span>`;

/**
 * Inscrever-se: o emblema do torneio no palco dourado, e cada regra numa linha com o seu desenho
 * — a restrição (quando há) em vermelho e primeiro, porque é a única que pode barrar a equipe.
 */
function confirmarInscricaoCampeonato(C, aoConfirmar) {
  confirmar({
    titulo: t('camp.confirmarTitulo'),
    texto: `
      ${dlgPalco(dlgAtor({ arte: dlgArteCampeonato(C), classe: 'novo' }), 'ouro')}
      ${dlgFrase(t('camp.confirmarTexto', {
        nome: escapar(nomeDoCampeonato(C)),
        dia: escapar(dataDaNovidade(C.dia)),
      }))}
      ${dlgLista([
        temRestricao(C) ? { icone: 'alerta', html: `<b>${t('camp.confirmarRestricao')}</b>`, perigo: true } : null,
        { icone: 'espadas', html: t('camp.confirmarEquipe', PRAZO_EQUIPE()) },
        { icone: 'trofeu', html: t('camp.confirmarSeed') },
        { icone: 'calendario', html: t('camp.confirmarPrazo', { dia: escapar(dataDaNovidade(C.ultimoDiaInscricao)) }) },
      ])}`,
    rotuloSim: t('camp.registrar'),
    aoConfirmar,
  });
}

/** Sair da lista: o torneio de um lado, você saindo pela porta do outro. */
function confirmarCancelarCampeonato(C, aoConfirmar) {
  confirmar({
    titulo: t('camp.cancelarTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArteCampeonato(C) })}
        ${dlgSeta()}
        ${dlgAtor({ arte: dlgArteTreinador(null, null, 64), nome: escapar(estado.eu?.nick ?? ''), marca: dlgIcone('porta', 14) })}`, 'perigo')}
      ${dlgFrase('', t('camp.cancelarTexto', { dia: escapar(dataDaNovidade(C.ultimoDiaInscricao)) }))}`,
    rotuloSim: t('camp.cancelarSim'),
    tom: 'perigo',
    aoConfirmar,
  });
}

function ligarAcaoCampeonato() {
  $('#camp-registrar')?.addEventListener('click', () => confirmarInscricaoCampeonato(campAtual(), () => {
    estado.campEnviando = true;
    pintarCabecalhoCampeonato();
    enviar({ t: 'campeonato.inscrever', id: idDoCampAberto() });
  }));
  $('#camp-cancelar')?.addEventListener('click', () => confirmarCancelarCampeonato(campAtual(), () => {
    estado.campEnviando = true;
    pintarCabecalhoCampeonato();
    enviar({ t: 'campeonato.cancelar', id: idDoCampAberto() });
  }));
  $('#camp-voltar')?.addEventListener('click', voltarParaListaDeCampeonatos);
  $('#camp-equipe-abrir')?.addEventListener('click', abrirEquipeDoCampeonato);
  $('#camp-ver-minha')?.addEventListener('click', () => {
    estado.campAba = 'chave';
    // A primeira partida do jogador pode estar numa rodada que o corte "Top N" escondeu.
    estado.campChaveCorte = 0;
    pintarCampeonato();
    realcarMinhaChave();
  });
  $('#camp-ver-chave')?.addEventListener('click', () => {
    estado.campAba = 'chave';
    pintarCampeonato();
  });
}

/**
 * O relógio do cabeçalho, uma vez por segundo, e a VIRADA: quando o prazo passa com a tela
 * aberta, ela pede o pacote de novo — é ele que traz a chave congelada.
 */
function tiqueCampeonato() {
  if (estado.modalAberto !== 'campeonato') return;
  // Na lista não há relógio de edição nenhuma: os selos de fase dela são repintados quando o
  // pacote chega, e uma repintura por segundo da lista inteira seria desperdício.
  if (estado.campAba === 'lista') return;
  const el = $('#camp-contagem');
  const agora = agoraDoServidor();
  const C = campAtual();
  const fase = faseDoCampeonato(agora, C);
  const d = dadosCampeonato();
  if (d && d.campeonato?.fase !== fase && estado.campViradaPedida !== fase) {
    // UM pedido por virada, mesmo que o relógio daqui e o do servidor discordem por alguns
    // segundos — sem a marca, a tela pediria o pacote a cada tique até eles concordarem. O
    // atraso sorteado espalha os pedidos de quem estava com a aba aberta na meia-noite.
    estado.campViradaPedida = fase;
    setTimeout(() => enviar({ t: 'campeonato.info', id: idDoCampAberto() }), 1500 + Math.random() * 3000);
  }
  // A virada das 23h NÃO muda a fase — ela continua "chaveado" o dia inteiro —, então o laço
  // acima não a pega. Sem esta, a faixa seguiria oferecendo a escolha da equipe com o pacote
  // velho, e só o servidor recusaria: o jogador trocaria o time e levaria um erro sem entender.
  if (d?.campeonato?.equipeAberta === true && agora >= (d.campeonato.equipeAte ?? Infinity)
      && !estado.campEquipeTravaPedida) {
    estado.campEquipeTravaPedida = true;
    setTimeout(() => enviar({ t: 'campeonato.info', id: idDoCampAberto() }), 1500 + Math.random() * 3000);
  }
  // A REDE DE SEGURANÇA do aviso de onda: se ele se perdeu (socket caindo no segundo errado),
  // a tela percebe o horário vencido e busca sozinha — uma vez por onda.
  const chave = d?.chave;
  const lutas = d?.campeonato?.lutasEm ?? C.lutasEm;
  const vencida = chave && !chave.concluidaEm
    && (chave.onda > 0 ? (chave.proximaOndaEm ?? 0) : lutas) + 20_000 < agora;
  if (vencida && estado.campOndaPedida !== chave.onda) {
    estado.campOndaPedida = chave.onda;
    enviar({ t: 'campeonato.info', id: idDoCampAberto() });
  }
  if (!el) return;
  if (fase === 'futuro') {
    el.textContent = t('camp.abremEm', { tempo: tempoCurto(C.inscricoesDe - agora) });
  } else if (fase === 'inscricoes') {
    el.textContent = t('camp.encerramEm', { tempo: tempoCurto(C.inscricoesAte - agora) });
  } else if (!chave || chave.concluidaEm) {
    el.textContent = '';
  } else if (chave.onda > 0) {
    const falta = (chave.proximaOndaEm ?? 0) - agora;
    el.textContent = falta > 0
      ? t('camp.proximaRodadaEm', { tempo: tempoCurto(falta) })
      : t('camp.rodadaRodando');
  } else if (agora >= lutas) {
    el.textContent = t('camp.lutasVaoComecar');
  } else {
    // Dia de análise. Enquanto a equipe abre, o relógio que interessa é o DELA: é a última
    // coisa que o jogador ainda decide. Travada, volta a contar para a primeira onda.
    const equipeAte = d?.campeonato?.equipeAte ?? C.equipeAte;
    el.textContent = agora < equipeAte
      ? t('camp.equipeTravaEm', { tempo: tempoCurto(equipeAte - agora) })
      : t('camp.lutasComecamEm', { tempo: tempoCurto(lutas - agora) });
  }
}
setInterval(tiqueCampeonato, 1000);

// ------------------------------------------------------- aba: Participantes

/** Quem desenha os sprites: só os cards que aparecem na tela (cada sprite tem o próprio relógio). */
let campObservador = null;

function pintarParticipantes(painel) {
  const d = dadosCampeonato();
  if (!d) {
    painel.innerHTML = `<p class="camp-vazio">${t('camp.carregando')}</p>`;
    return;
  }
  const congelado = !!d.chave;
  painel.innerHTML = `
    <div class="camp-part-barra">
      <input type="search" class="camp-busca" id="camp-busca" autocomplete="off"
             placeholder="${escapar(t('camp.buscaPlaceholder'))}" value="${escapar(estado.campBusca ?? '')}">
      <span class="camp-part-conta" id="camp-part-conta"></span>
    </div>
    <p class="camp-part-nota">${congelado
      ? t('camp.seedsCongeladas', PRAZO_EQUIPE())
      : t('camp.seedsProvisorias', { dia: escapar(dataDaNovidade(campAtual().ultimoDiaInscricao)) })}</p>
    <div class="camp-grade" id="camp-grade"></div>`;
  $('#camp-busca').addEventListener('input', (ev) => {
    estado.campBusca = ev.target.value;
    pintarGradeParticipantes();
  });
  pintarGradeParticipantes();
}

function pintarGradeParticipantes() {
  const grade = $('#camp-grade');
  const d = dadosCampeonato();
  if (!grade || !d) return;
  const busca = String(estado.campBusca ?? '').trim().toLowerCase();
  const lista = (d.inscritos ?? []).filter((i) => !busca || String(i.nick).toLowerCase().includes(busca));
  const conta = $('#camp-part-conta');
  if (conta) {
    conta.textContent = busca
      ? t('camp.contaFiltro', { n: num(lista.length), total: num(d.total ?? 0) })
      : t('camp.conta', { n: num(d.total ?? 0) });
  }
  campObservador?.disconnect();
  if (!lista.length) {
    grade.innerHTML = `<div class="camp-vazio">${
      busca ? t('camp.buscaVazia') : t(faseCampeonatoAgora() === 'inscricoes' ? 'camp.ninguemAinda' : 'camp.ninguem')
    }</div>`;
    return;
  }
  const ctx = contextoDaChave(d);
  grade.innerHTML = lista.map((i) => htmlCardParticipante(i, ctx)).join('');

  campObservador = new IntersectionObserver((entradas) => {
    for (const ent of entradas) {
      if (!ent.isIntersecting) continue;
      const card = ent.target;
      campObservador.unobserve(card);
      const i = lista[Number(card.dataset.i)];
      const host = card.querySelector('.camp-card-sprite');
      if (!i || !host || host.childElementCount) continue;
      host.appendChild(spriteAnimado(i.looktype ?? LOOKTYPE_TREINADOR, 64, 3, null, i.vs, { treinador: true }));
    }
  // `root: null` (a janela) e não o painel: no desktop quem rola é o painel, no celular é a
  // folha inteira — e a interseção com a janela já desconta o recorte de qualquer um dos dois.
  }, { root: null, rootMargin: '120px' });
  grade.querySelectorAll('.camp-card').forEach((card, k) => {
    card.dataset.i = String(k);
    campObservador.observe(card);
    card.addEventListener('click', () => pedirPerfil(card.dataset.nick));
  });
}

/** A situação de um inscrito na chave, ou `null` enquanto nada foi jogado. */
function situacaoNaChave(seed, ctx) {
  if (seed == null || !ctx) return null;
  const { podio, derrotas, andando } = ctx;
  if (podio?.campeao === seed) return 'campeao';
  if (podio?.vice === seed) return 'vice';
  if (podio?.terceiro === seed) return 'terceiro';
  if (!andando && !podio) return null;
  const n = derrotas.get(seed) ?? 0;
  if (n >= 2) return 'eliminado';
  return n === 1 ? 'perdedores' : 'invicto';
}

function htmlCardParticipante(i, ctx = null) {
  const r = i.rank;
  const situacao = situacaoNaChave(i.seed, ctx);
  const classificado = r && (r.partidas ?? 0) >= PVP_PARTIDAS_POSICIONAMENTO;
  const tier = classificado ? r.tierId : null;
  const emblema = classificado
    ? `<img class="camp-card-emblema" src="${iconeDoRank(r.tierId)}" alt="" loading="lazy">`
    : '<span class="camp-card-emblema vazio" aria-hidden="true">?</span>';
  const elo = classificado ? escapar(rotuloDoRank(r)) : t('pvp.naoClassificado');
  const topo = i.seed != null && i.seed <= 4 ? ` topo topo-${i.seed}` : '';
  return `
    <button type="button" class="camp-card${i.eu ? ' eu' : ''}${topo}${situacao ? ` sit-${situacao}` : ''}" data-nick="${escapar(i.nick)}"
            ${tier ? `data-tier="${escapar(tier)}"` : ''} title="${escapar(t('camp.verPerfil'))}">
      <span class="camp-card-seed"><small>${t('camp.seed')}</small>${rotuloSeed(i.seed)}</span>
      ${emblema}
      ${i.eu ? `<span class="camp-card-voce">${t('camp.voce')}</span>` : ''}
      <span class="camp-card-sprite"></span>
      ${situacao ? `<span class="camp-card-sit">${t(`camp.status.${situacao}`)}</span>` : ''}
      <span class="camp-card-nick">${escapar(i.nick)}</span>
      <span class="camp-card-nv">${t('painel.nivelCurto')} ${num(i.nivel ?? 0)}</span>
      <span class="camp-card-elo">
        <span class="camp-card-tier">${elo}</span>
        <span class="camp-card-pr"><b>${num(r?.pontos ?? 0)}</b> ${t('pvp.pr')}</span>
      </span>
    </button>`;
}

// ------------------------------------------------------------- aba: Bracket

function pintarAbaChave(painel) {
  const d = dadosCampeonato();
  if (!d) {
    painel.innerHTML = `<p class="camp-vazio">${t('camp.carregando')}</p>`;
    return;
  }
  if (!d.chave) {
    painel.innerHTML = htmlChaveAindaNaoGerada();
    return;
  }
  const chave = montarChave(d.chave.participantes);
  if (!chave) {
    painel.innerHTML = `
      <div class="camp-aviso-chave">
        <span class="camp-aviso-ico" aria-hidden="true">⚠</span>
        <div><b>${t('camp.poucosTitulo')}</b><p>${t('camp.poucosTexto')}</p></div>
      </div>`;
    return;
  }
  // A seed é o elo entre a chave (que só conhece números) e os inscritos.
  const porSeed = new Map((d.inscritos ?? []).filter((i) => i.seed != null).map((i) => [i.seed, i]));
  const ctx = contextoDaChave(d);
  const jogo = { porSeed, chave, estado: resolverChave(chave, ctx.res), andando: ctx.andando, concluida: !!d.chave.concluidaEm };
  // O DIA DE ANÁLISE, no topo da chave: é a primeira coisa que quem abre a aba no dia 29 vê, e
  // a única que explica por que a chave está de pé sem nenhuma partida jogada. Some quando as
  // lutas começam — dali em diante a chave fala por si.
  const analise = d.campeonato?.equipeAberta === true && !ctx.andando && !d.chave.concluidaEm
    ? `<div class="camp-aviso-chave camp-aviso-analise">
        <span class="camp-aviso-ico" aria-hidden="true">🔍</span>
        <div>
          <b>${t('camp.analiseTitulo')}</b>
          <p>${t('camp.analiseTexto', PRAZO_EQUIPE())}</p>
        </div>
      </div>`
    : '';
  // O CORTE: só entram no seletor os "Top N" menores que a chave (numa de 16 vagas, "Top 32"
  // seria a chave inteira com outro nome).
  const cortes = CORTES_CHAVE.filter((n) => !n || n < chave.tamanho);
  const corte = cortes.includes(estado.campChaveCorte) ? estado.campChaveCorte : 0;
  const inicio = inicioDoCorte(chave, corte);
  const seletor = cortes.length > 1
    ? `<label class="chv-corte">
        <span>${t('camp.corteRotulo')}</span>
        <select class="filtros-select-el" id="chv-corte">${cortes.map((n) => `
          <option value="${n}"${n === corte ? ' selected' : ''}>${n ? t('camp.corteTop', { n }) : t('camp.corteTudo')}</option>`).join('')}
        </select>
      </label>`
    : '';
  painel.innerHTML = `
    ${analise}
    <div class="chv-barra">
      <span>${t('camp.chaveResumo', {
        n: num(chave.participantes),
        tamanho: num(chave.tamanho),
        dia: escapar(dataDaNovidade(campAtual().ultimoDiaInscricao)),
      })}</span>
      ${seletor}
      <span class="chv-legenda">${t(d.campeonato?.replaysAbertos === false ? 'camp.chaveSemFitas' : 'camp.chaveLegenda')}</span>
    </div>
    <section class="chv-bloco">
      <h4 class="chv-bloco-titulo">${t('camp.chaveVencedores')}</h4>
      <div class="chv-rolagem">${htmlArvore([...chave.vencedores.slice(inicio.v), chave.final], 'V', jogo, inicio.v)}</div>
    </section>
    ${chave.perdedores.length ? `
    <section class="chv-bloco perdedores">
      <h4 class="chv-bloco-titulo">${t('camp.chavePerdedores')}</h4>
      <div class="chv-rolagem">${htmlArvore(chave.perdedores.slice(inicio.p), 'P', jogo, inicio.p)}</div>
    </section>` : ''}`;
  ligarChave(painel);
}

/** As opções do seletor da Bracket: 0 = a chave inteira; N = o "Top N". */
const CORTES_CHAVE = [0, 32, 16, 8, 4];

/**
 * De que rodada cada lado da chave começa no "Top N" (N potência de 2): é o corte que as
 * plataformas de torneio chamam de "Top 8" na eliminação dupla. Ficam as rodadas dos vencedores
 * que começam com N/2 treinadores ou menos, e as dos perdedores idem — na soma, o instante em que
 * restam N vivos no campeonato. `{ v, p }` são índices em `chave.vencedores` e `chave.perdedores`.
 *
 * Numa chave de `2^k` vagas, a rodada `r` dos vencedores (a partir de 0) começa com `2^(k−r)`
 * treinadores, e a `j` dos perdedores com `2^(k−1−⌊j/2⌋)`. Top 8 numa de 512: semifinal e final
 * dos vencedores; as quatro últimas dos perdedores.
 */
function inicioDoCorte(chave, n) {
  if (!n || n >= chave.tamanho) return { v: 0, p: 0 };
  const k = chave.vencedores.length;
  const t = Math.log2(n);
  return { v: k - t + 1, p: 2 * (k - t) };
}

/**
 * Antes do prazo: o aviso de que a chave não existe ainda, e as duas explicações que o
 * jogador precisa para entender a que vai aparecer — como as seeds se distribuem e como a
 * eliminação dupla funciona.
 */
function htmlChaveAindaNaoGerada() {
  const exemplo = ordemDasSeeds(8);
  const pares = [];
  for (let i = 0; i < exemplo.length; i += 2) {
    pares.push(`<span class="camp-par"><b>${exemplo[i]}</b><i>×</i><b>${exemplo[i + 1]}</b></span>`);
  }
  const itens = (chaves) => chaves.map((k) => `<li>${t(k)}</li>`).join('');
  return `
    <div class="camp-aviso-chave">
      <span class="camp-aviso-ico" aria-hidden="true">🔒</span>
      <div>
        <b>${t('camp.chaveNaoGerada')}</b>
        <p>${t('camp.chaveNaoGeradaTexto', { dia: escapar(dataDaNovidade(campAtual().ultimoDiaInscricao)) })}</p>
      </div>
    </div>
    <div class="camp-info-grade">
      <section class="camp-info">
        <h4>${t('camp.seedsTitulo')}</h4>
        <ul class="camp-regras">${itens(['camp.seed1', 'camp.seed2', 'camp.seed3', 'camp.seed4'])}</ul>
        <div class="camp-exemplo">
          <span class="camp-exemplo-rot">${t('camp.exemploRotulo')}</span>
          <div class="camp-exemplo-pares">${pares.join('')}</div>
        </div>
      </section>
      <section class="camp-info">
        <h4>${t('camp.formatoTitulo')}</h4>
        <ul class="camp-regras">${itens(['camp.fmtElim', 'camp.fmtAuto', 'camp.fmtEquipe', 'camp.fmtFinal', 'camp.fmtTerceiro', 'camp.fmtLuta'])}</ul>
        ${htmlChaveCampeonato()}
      </section>
    </div>`;
}

/** O nome de uma rodada. As últimas ganham nome próprio, como em qualquer chave. */
function nomeDaRodada(lado, indice, total) {
  if (lado === 'F') return t('camp.grandeFinal');
  const falta = total - indice;
  if (lado === 'V') {
    if (falta === 1) return t('camp.finalVencedores');
    if (falta === 2 && total >= 3) return t('camp.semifinal');
  } else {
    if (falta === 1) return t('camp.finalPerdedores');
    if (falta === 2) return t('camp.semifinalPerdedores');
  }
  return t('camp.rodada', { n: indice + 1 });
}

/** `V1·2` — o id da partida como a tela escreve. */
const idDaPartida = (id) => String(id).replace('-', '·');

/**
 * Uma árvore: colunas de rodadas, com as partidas agrupadas em PARES quando a coluna seguinte
 * tem a metade delas — é o par que ganha a linha vertical ligando os dois ao jogo de onde sai
 * o vencedor. Quando a seguinte tem o mesmo número, cada partida vai reto para a sua.
 */
function htmlArvore(rodadas, lado, jogo, inicio = 0) {
  // `inicio`: quantas rodadas o corte da Bracket tirou da frente. Os nomes ("Rodada 6",
  // "Semifinal") contam da chave INTEIRA, não da fatia que sobrou.
  const totalChave = lado === 'V' ? jogo.chave.vencedores.length : jogo.chave.perdedores.length;
  return `<div class="chv-arvore">${rodadas.map((rodada, r) => {
    const prox = rodadas[r + 1];
    const emPares = !!prox && prox.length * 2 === rodada.length;
    const grupos = [];
    for (let i = 0; i < rodada.length; i += emPares ? 2 : 1) grupos.push(rodada.slice(i, i + (emPares ? 2 : 1)));
    const ehFinal = rodada[0].lado === 'F';
    const titulo = ehFinal ? nomeDaRodada('F') : nomeDaRodada(lado, inicio + r, totalChave);
    const classes = ['chv-col', r === 0 ? 'sem-entrada' : '', !prox ? 'sem-saida' : '', ehFinal ? 'final' : ''].filter(Boolean).join(' ');
    return `
      <div class="${classes}">
        <div class="chv-col-titulo">${escapar(titulo)}</div>
        <div class="chv-col-corpo">
          ${grupos.map((g) => `
            <div class="chv-grupo${g.length === 2 ? ' par' : ''}">
              ${g.map((p) => htmlPartida(p, jogo)).join('')}
            </div>`).join('')}
        </div>
      </div>`;
  }).join('')}</div>`;
}

/**
 * Uma partida: os dois lados JÁ com os resultados aplicados (quem saiu da partida anterior
 * aparece pelo nome), o vencedor aceso, o perdedor apagado, o placar de abates e o botão de
 * assistir. A que está com os dois lados definidos e ainda não foi jogada ganha o selo "na
 * próxima rodada" — é a próxima onda.
 */
function htmlPartida(p, jogo) {
  const { chave } = jogo;
  const info = jogo.estado.get(p.id);
  const r = info?.resultado ?? null;
  const a = info?.a ?? p.a;
  const b = info?.b ?? p.b;
  const marca = (lado) => (!r || lado.seed == null ? null : lado.seed === r.vencedor ? 'venceu' : 'perdeu');
  const pontos = (lado) => {
    if (!r?.placar || lado.seed == null) return null;
    if (lado.seed === r.a) return r.placar.a;
    return lado.seed === r.b ? r.placar.b : null;
  };
  const ultimaPerdedores = chave.perdedores.length && p.id === chave.perdedores.at(-1)[0].id;
  // Tudo o que não é um dos dois lados vira ETIQUETA presa na borda do card, e não linha nova
  // dentro dele: todo card fica com a mesma altura, e é da altura que sai o ponto onde as linhas
  // da chave encostam. No alto à esquerda, o que se faz com a partida (assistir, ou "na próxima
  // rodada"); embaixo, o que ela vale (título, 3º lugar) ou como acabou (W.O.).
  const selos = [];
  if (p.id === 'GF') selos.push(`<span class="chv-selo ouro">🥇 ${t('camp.seloCampeao')}</span>`);
  else if (ultimaPerdedores) selos.push(`<span class="chv-selo bronze">🥉 ${t('camp.seloTerceiro')}</span>`);
  if (r?.estado === 'wo') selos.push(`<span class="chv-selo wo">${t('camp.wo')}</span>`);
  let alto = '';
  if (r?.temReplay) {
    alto = `<button type="button" class="chv-assistir" data-fita="${escapar(p.id)}">▶ ${t('camp.assistir')}</button>`;
  } else if (info?.pronta && jogo.andando && !jogo.concluida) {
    alto = `<span class="chv-selo proxima chv-alto">${t('camp.aJogar')}</span>`;
  }
  const classes = ['chv-jogo', p.bye ? 'bye' : '', r ? 'jogada' : '', info?.pronta && jogo.andando ? 'pronta' : '']
    .filter(Boolean).join(' ');
  return `
    <div class="${classes}" data-partida="${escapar(p.id)}">
      <span class="chv-jogo-id">${escapar(idDaPartida(p.id))}</span>
      ${htmlLado(a, jogo.porSeed, p, marca(a), pontos(a))}
      ${htmlLado(b, jogo.porSeed, p, marca(b), pontos(b))}
      ${alto}
      ${selos.length ? `<div class="chv-rodape">${selos.join('')}</div>` : ''}
    </div>`;
}

function htmlLado(lado, porSeed, partida, marca = null, pontos = null) {
  if (lado.seed != null) {
    const i = porSeed.get(lado.seed);
    const nome = i ? escapar(i.nick) : `<i>${t('camp.vagaVazia')}</i>`;
    const classes = ['chv-lado', i?.eu ? 'eu' : '', marca ?? ''].filter(Boolean).join(' ');
    return `
      <div class="${classes}"${i ? ` data-nick="${escapar(i.nick)}"` : ''}>
        <span class="chv-seed">${lado.seed}</span>
        <span class="chv-nome">${nome}</span>
        ${i?.rank && (i.rank.partidas ?? 0) >= PVP_PARTIDAS_POSICIONAMENTO
          ? `<img class="chv-emblema" src="${iconeDoRank(i.rank.tierId)}" alt="" loading="lazy">`
          : ''}
        ${pontos != null ? `<span class="chv-pontos">${num(pontos)}</span>` : ''}
      </div>`;
  }
  if (lado.bye) {
    return `<div class="chv-lado vazio"><span class="chv-seed">—</span><span class="chv-nome">${t('camp.bye')}</span></div>`;
  }
  const chaveTexto = lado.vence ? 'camp.vencedorDe' : 'camp.perdedorDe';
  const deOnde = partida.id === 'GF' && lado.vence?.startsWith('P')
    ? t('camp.campeaoPerdedores')
    : t(chaveTexto, { id: idDaPartida(lado.vence ?? lado.perde) });
  return `<div class="chv-lado espera"><span class="chv-seed">·</span><span class="chv-nome">${escapar(deOnde)}</span></div>`;
}

/** Passar o mouse num nome acende o caminho dele na chave inteira — o truque do Battlefy. */
function ligarChave(painel) {
  // As caixas de rolagem nascem de novo a cada pintura (o `innerHTML` as recria), então o
  // arrasto é religado sempre. Os listeners do PAINEL, não: ele é o mesmo elemento desde que a
  // aba abriu, e religá-los a cada onda jogada empilharia uma cópia por repintura — três ondas
  // depois, um clique num nome abriria a mesma ficha quatro vezes.
  ligarArrasteDaChave(painel);
  if (painel.dataset.chaveLigada) return;
  painel.dataset.chaveLigada = '1';

  // O seletor "Bracket inteira / Top 32 / … / Top 4" repinta só a aba, com o corte novo.
  painel.addEventListener('change', (ev) => {
    const sel = ev.target.closest('#chv-corte');
    if (!sel) return;
    estado.campChaveCorte = Number(sel.value) || 0;
    pintarAbaChave(painel);
  });

  const acender = (nick, on) => {
    if (!nick) return;
    for (const el of painel.querySelectorAll(`.chv-lado[data-nick="${CSS.escape(nick)}"]`)) {
      el.classList.toggle('realce', on);
    }
  };
  painel.addEventListener('mouseover', (ev) => acender(ev.target.closest('.chv-lado')?.dataset.nick, true));
  painel.addEventListener('mouseout', (ev) => acender(ev.target.closest('.chv-lado')?.dataset.nick, false));
  // Na fase de CAPTURA, antes do handler de baixo: é aqui que o clique que fecha um arrasto é
  // comido, e ele precisa morrer antes de qualquer um que abra perfil ou replay.
  painel.addEventListener('click', (ev) => {
    if (!chaveArrastou) return;
    chaveArrastou = false;
    ev.stopPropagation();
    ev.preventDefault();
  }, true);
  painel.addEventListener('click', (ev) => {
    const fita = ev.target.closest('.chv-assistir');
    if (fita) return pedirFitaDoCampeonato(fita.dataset.fita);
    const nick = ev.target.closest('.chv-lado')?.dataset.nick;
    if (nick) pedirPerfil(nick);
  });
}

/**
 * Quantos pixels o ponteiro precisa andar para aquilo virar um ARRASTO em vez de um clique.
 *
 * Quatro. Um mouse comum treme um ou dois pixels entre o apertar e o soltar, e com o limite em
 * zero metade dos cliques em nome viraria arrasto e não abriria ficha nenhuma.
 */
const CHAVE_ARRASTE_MIN = 4;

/** O arrasto que acabou de terminar ainda não foi "gasto" por um clique. */
let chaveArrastou = false;

/**
 * ARRASTAR para navegar na chave — o gesto de mapa.
 *
 * Uma chave de 168 inscritos tem 256 vagas: oito colunas de largura e sessenta e quatro partidas
 * de altura. Com as barras de rolagem como única saída, seguir o caminho de um jogador vira um
 * ping-pong entre duas barras que ficam em bordas opostas da tela. Pegar a chave e puxar é o que
 * as plataformas de torneio fazem, e é o que o `overflow` sozinho não dá.
 *
 * As duas direções andam JUNTAS, e em elementos diferentes: o horizontal é da `.chv-rolagem` (cada
 * bloco tem a sua) e o vertical é do painel inteiro, que é quem de fato rola. Mexer só numa delas
 * daria a sensação de arrastar a caixa, e não a chave.
 *
 * **Toque fica de fora de propósito.** No celular o navegador já rola com inércia e com o
 * `touch-action` dele; entrar na frente disso deixaria a chave mais difícil de navegar no
 * telefone, não mais fácil. Só mouse e caneta passam por aqui.
 */
function ligarArrasteDaChave(painel) {
  let ativo = null;

  const parar = () => {
    if (!ativo) return;
    ativo.caixa.classList.remove('arrastando');
    // `releasePointerCapture` estoura se o ponteiro já foi solto pelo navegador (a janela perdeu
    // o foco no meio do arrasto, por exemplo). Não é erro: é o estado que se queria.
    try { ativo.caixa.releasePointerCapture(ativo.id); } catch { /* já solto */ }
    // A marca sobrevive ao `pointerup`: o `click` vem DEPOIS dele, e é ele que precisa morrer.
    chaveArrastou = ativo.arrastou;
    ativo = null;
  };

  for (const caixa of painel.querySelectorAll('.chv-rolagem')) {
    caixa.addEventListener('pointerdown', (ev) => {
      if (ev.pointerType === 'touch' || ev.button !== 0) return;
      // Um arrasto anterior que não terminou em clique (o ponteiro saiu da chave) não pode comer
      // o clique DESTE gesto.
      chaveArrastou = false;
      ativo = {
        caixa,
        id: ev.pointerId,
        x: ev.clientX,
        y: ev.clientY,
        esq: caixa.scrollLeft,
        topo: painel.scrollTop,
        arrastou: false,
      };
      // SEM captura aqui: com o ponteiro capturado, o Chrome entrega o `pointerup` e o `click` à
      // CAIXA, e não ao botão sob o cursor — o "▶ Assistir" e o clique em nome não achavam o
      // `closest` e morriam calados. A captura entra só quando o gesto vira arrasto (abaixo).
    });

    caixa.addEventListener('pointermove', (ev) => {
      if (!ativo || ev.pointerId !== ativo.id) return;
      // Soltou fora da caixa antes de virar arrasto (sem captura, o `pointerup` não chegou aqui).
      if (!(ev.buttons & 1)) return parar();
      const dx = ev.clientX - ativo.x;
      const dy = ev.clientY - ativo.y;
      if (!ativo.arrastou) {
        if (Math.hypot(dx, dy) < CHAVE_ARRASTE_MIN) return;
        ativo.arrastou = true;
        // A classe só entra DEPOIS do limite: pôr o `grabbing` e o `user-select: none` no
        // `pointerdown` faria a mão fechar em todo clique de nome.
        ativo.caixa.classList.add('arrastando');
        // A captura é o que segue mandando `pointermove` quando o cursor sai da caixa no meio do
        // gesto. Capturar um ponteiro que o navegador já soltou estoura — e o arrasto segue sem ela.
        try { ativo.caixa.setPointerCapture(ativo.id); } catch { /* ponteiro já solto */ }
      }
      ativo.caixa.scrollLeft = ativo.esq - dx;
      painel.scrollTop = ativo.topo - dy;
      // Sem isto o navegador começa a selecionar os nomes por onde o cursor passa.
      ev.preventDefault();
    });

    caixa.addEventListener('pointerup', parar);
    caixa.addEventListener('pointercancel', parar);
  }
}

/** "Ver minha chave": rola até a minha primeira partida e a deixa piscando um instante. */
function realcarMinhaChave() {
  const minha = $('#camp-painel .chv-lado.eu');
  if (!minha) return;
  minha.scrollIntoView({ block: 'center', inline: 'center', behavior: 'smooth' });
  for (const el of document.querySelectorAll('#camp-painel .chv-lado.eu')) {
    el.classList.remove('pisca');
    void el.offsetWidth;
    el.classList.add('pisca');
  }
}

// ----------------------------------------------------------- aba: Premiação

/**
 * A PREMIAÇÃO: o pódio, o que cada degrau leva e — encerrado — a equipe campeã.
 *
 * Encerrado, cada degrau ganha o BONECO e o nick de quem subiu nele, e vira botão: o clique abre o
 * perfil, onde o troféu ou a medalha já estão ao lado do nick. Antes do fim, o mesmo pódio com os
 * degraus vagos — é a promessa, e o que está em jogo fica à vista.
 */
function pintarPremiacao(painel) {
  const dados = dadosCampeonato();
  const C = campAtual();
  const podio = dados?.chave?.concluidaEm ? dados.chave.podio : null;
  const seedDoLugar = { 1: podio?.campeao, 2: podio?.vice, 3: podio?.terceiro };
  const inscritoDaSeed = (seed) =>
    (seed == null ? null : (dados?.inscritos ?? []).find((i) => i.seed === seed) ?? null);
  const nomeCamp = t(`camp.tipo.${C.tipo}`);
  const trofeu = TROFEUS_CAMPEONATO.find((tr) => tr.tipo === C.tipo) ?? TROFEUS_CAMPEONATO[0];
  const nomeTrofeu = t(`trofeu.${trofeu.tipo}`);
  const premios = podioDosPremios(C.premios);

  const degraus = premios.map((d) => {
    const quem = podio ? inscritoDaSeed(seedDoLugar[d.pos]) : null;
    const abre = quem ? `button type="button" data-nick="${escapar(quem.nick)}" title="${escapar(t('camp.verPerfil'))}"` : 'div';
    return `
      <${abre} class="cp-lugar ${d.classe}${quem ? ' com-dono' : ''}${quem?.eu ? ' eu' : ''}" data-seed="${quem ? quem.seed : ''}">
        <div class="cp-palco">
          ${quem ? `<img class="cp-coroa" src="/assets/site/assets/ui/coroa-${d.pos}.png" alt="" aria-hidden="true">` : ''}
          <div class="cp-boneco">${quem ? '' : '<span class="cp-vago" aria-hidden="true">?</span>'}</div>
          ${d.pos === 1 && quem ? '<i class="cp-faisca f1"></i><i class="cp-faisca f2"></i><i class="cp-faisca f3"></i>' : ''}
        </div>
        <img class="cp-icone" src="${ICONE_LUGAR_CAMPEONATO[d.pos]}" alt="${d.pos}º">
        <span class="cp-nick">${quem ? escapar(quem.nick) : t('camp.aDefinir')}</span>
        <span class="cp-premio">${premioEmReais(d.premio)}</span>
        <div class="cp-degrau"><span>${d.pos}º</span></div>
      </${quem ? 'button' : 'div'}>`;
  }).join('');

  // O que cada degrau leva, com o ícone de verdade de cada coisa: o dinheiro, o troféu ou a
  // medalha do perfil — e o troféu que a equipe campeã carrega na ficha de cada bicho.
  const recompensas = premios
    .slice()
    .sort((a, b) => a.pos - b.pos)
    .map((d) => `
      <li>
        <img class="cr-ico lugar-${d.pos}" src="${ICONE_LUGAR_CAMPEONATO[d.pos]}" alt="">
        <span>${t(`camp.rec${d.pos}`, { premio: premioEmReais(d.premio), campeonato: escapar(nomeCamp) })}</span>
      </li>`).join('');

  const equipe = podio && Array.isArray(dados?.campea) && dados.campea.length
    ? `<section class="camp-equipe-campea">
        <h4>${imgTrofeu(trofeu, 'cec-trofeu')}${t('camp.equipeCampea', { trofeu: escapar(nomeTrofeu) })}</h4>
        <div class="cec-fila">${dados.campea.map((k, i) => `
          <div class="cec-pk" data-i="${i}" title="${escapar(`${k.shiny ? prefixoShiny() : ''}${estado.especies.get(k.speciesId)?.name ?? ''} · ${t('painel.nivelCurto')}${num(k.level)}`)}">
            <div class="cec-sprite"></div>
            ${imgTrofeu(trofeu, 'cec-selo')}
            <span class="cec-nv">${t('painel.nivelCurto')} ${num(k.level)}</span>
          </div>`).join('')}
        </div>
      </section>`
    : '';

  const total = (C.premios ?? []).reduce((s, v) => s + v, 0);
  painel.innerHTML = `
    <div class="camp-premiacao">
      <p class="camp-chamada">${t('camp.chamada')}</p>
      ${temRestricao(C) ? `<p class="camp-nota camp-nota-restr">🚫 ${t('camp.restricaoNota')}</p>` : ''}
      <div class="camp-podio2${podio ? ' encerrado' : ''}">${degraus}</div>
      <p class="camp-nota">${t('camp.premiosNota')}</p>
      ${equipe}
      <section class="camp-recompensas">
        <h4>${t('camp.recompensasTitulo')}</h4>
        <ul>
          ${recompensas}
          <li class="cr-equipe">
            ${imgTrofeu(trofeu, `cr-ico trofeu-${trofeu.tipo}`)}
            <span>${t('camp.recEquipe', { trofeu: escapar(nomeTrofeu) })}</span>
          </li>
        </ul>
      </section>
      <ul class="camp-regras camp-quem">
        <li>${t('camp.quem1')}</li>
        <li>${t('camp.quem2')}</li>
        <li>${t('camp.quem3')}</li>
      </ul>
      <div class="camp-total"><span>${t('camp.premioTotal')}</span><b>${premioEmReais(total)}</b></div>
    </div>`;

  // Os bonecos, com a roupa e as cores de cada um — o mesmo desenho do pódio do Rank.
  for (const el of painel.querySelectorAll('.cp-lugar.com-dono')) {
    const quem = inscritoDaSeed(Number(el.dataset.seed));
    // No celular a coluna tem um terço da tela: o boneco encolhe para não invadir a do vizinho.
    const px = el.classList.contains('ouro') ? (movelAtivo() ? 64 : 88) : (movelAtivo() ? 50 : 68);
    el.querySelector('.cp-boneco')
      .appendChild(spriteAnimado(quem?.looktype ?? LOOKTYPE_TREINADOR, px, 3, null, quem?.vs, { treinador: true }));
    // `onclick` e não `addEventListener`: o painel é o mesmo entre as abas, mas este botão nasce
    // de novo a cada pintura — um listener por botão, nunca empilhado.
    el.onclick = () => pedirPerfil(el.dataset.nick);
  }
  for (const el of painel.querySelectorAll('.cec-pk')) {
    el.querySelector('.cec-sprite').appendChild(spritePokemon(dados.campea[Number(el.dataset.i)], 56));
  }
}

/**
 * O desenho da chave — oito entradas, a queda para a chave dos perdedores e a final.
 *
 * É ILUSTRAÇÃO, não dado: mora na explicação da eliminação dupla, antes de a chave existir.
 * "Eliminação dupla" é uma frase que metade dos jogadores nunca leu, e o desenho explica em um
 * segundo o que o parágrafo leva quatro linhas para dizer.
 */
function htmlChaveCampeonato() {
  const vaga = (n = 1) => '<i class="cv-vaga"></i>'.repeat(n);
  return `
    <div class="camp-chave" aria-hidden="true">
      <div class="cv-lado vencedores">
        <span class="cv-rotulo">${t('camp.chaveVencedores')}</span>
        <div class="cv-rodada">${vaga(8)}</div>
        <div class="cv-rodada">${vaga(4)}</div>
        <div class="cv-rodada">${vaga(2)}</div>
      </div>
      <div class="cv-final">
        <span class="cv-taca">🏆</span>
        <span class="cv-rotulo">${t('camp.chaveFinal')}</span>
      </div>
      <div class="cv-lado perdedores">
        <span class="cv-rotulo">${t('camp.chavePerdedores')}</span>
        <div class="cv-rodada">${vaga(4)}</div>
        <div class="cv-rodada">${vaga(2)}</div>
        <div class="cv-rodada">${vaga(1)}</div>
      </div>
    </div>`;
}

// ------------------------------------------------------------------ bosses
//
// A galeria vem do `bossCatalog.json` deles: 87 bosses com arte, categoria e nível. Só uns
// poucos têm ficha de verdade (arena, entrada, golpes e drops) — no original também é assim,
// lá são 2 de 87. Quem não tem ficha aparece esmaecido, como vitrine do que vem por aí.

/** Ficha jogável de um boss da galeria, ou `null` se ele é só arte. */
const fichaDoBoss = (key) => estado.bossesJogaveis.find((b) => b.key === key) ?? null;

/** Entrada do catálogo de bosses para uma espécie (Kyogre, Regice…). */
const bossDaEspecie = (pokeId) => estado.bossesCatalogo?.find((b) => b.pokeId === pokeId) ?? null;

/**
 * É um boss que ainda NÃO tem arena — o de evento (Mewtwo, Lugia, Celebi…).
 *
 * Quem já virou arena responde `false` aqui, porque `bossDaEspecie` o encontra primeiro; a
 * lista de evento é só o que falta. Variante de Outland nunca é boss de evento — o #2001+ não
 * é número nacional, e `dexDoPokeId` daria um dex de outra espécie.
 */
const ehBossDeEvento = (pokeId) =>
  !isOutlandPokeId(pokeId) && !bossDaEspecie(pokeId) && ehBossEventoDex(dexDoPokeId(pokeId));

/** Quantas vezes esta conta já derrotou o boss `key` (contador vitalício do servidor). */
const vezesDerrotadoBoss = (key) => Number(estado.eu?.boss?.vitorias?.[key] ?? 0) || 0;

/**
 * A penalidade de equipe, calculada no cliente só para MOSTRAR antes de entrar.
 * Espelha `penalidadeDeEquipe` no servidor, que é quem manda de verdade.
 */
function penalidadeDaMinhaEquipe(ficha) {
  const time = (estado.eu?.pokemons ?? []).filter((k) => k.slot != null);
  const forca = time.reduce((s, k) => s + Math.min(1, k.level / ficha.teamLevel), 0);
  const deficit = Math.max(0, ficha.equipeIdeal - forca);
  return { membros: time.length, forca, deficit, mult: Math.pow(3, deficit) };
}

/** Equipe na ficha do boss — mesma ordem do painel da esquerda. */
const equipeDoBoss = () =>
  (estado.eu?.pokemons ?? []).filter((k) => k.slot != null).sort((a, b) => a.slot - b.slot);

/** % de HP seguro — evita `NaN%` quando `maxHp` ainda não veio no snapshot. */
const pctHpPokemon = (k) => {
  const max = Math.max(1, Number(k.maxHp) || 1);
  const hp = Math.max(0, Number(k.hp) || 0);
  return Math.min(100, (hp / max) * 100);
};

/** Um pokémon na fileira da ficha do boss — sprite, barra e nível (vivo ou desmaiado). */
function pipEquipeBoss(k) {
  const pip = document.createElement('div');
  const pct = pctHpPokemon(k);
  const morto = pct <= 0;
  pip.className = 'boss-pip' + (morto ? ' caido' : '');
  pip.title = `${k.nome} · Nv ${k.level}`;

  const arte = document.createElement('div');
  arte.className = 'boss-pip-arte';
  arte.appendChild(spritePokemon(k, 36));
  pip.appendChild(arte);

  const barra = document.createElement('div');
  barra.className = 'mini-hp boss-pip-hp' + (pct < 35 ? ' baixo' : '');
  barra.innerHTML = `<i style="width:${pct}%"></i>`;
  pip.appendChild(barra);

  const nv = document.createElement('span');
  nv.className = 'boss-pip-nv';
  nv.textContent = k.level;
  pip.appendChild(nv);

  return pip;
}

/** Só a fileira de pokémon — atualiza HP sem remontar entrada/botão/auto. */
function pintarEquipeDoBoss() {
  const pips = document.querySelector('#boss-equipe');
  if (!pips) return;
  const time = equipeDoBoss();
  pips.replaceChildren();
  if (!time.length) {
    pips.innerHTML = `<span class="boss-semtime">${t('boss.semTime')}</span>`;
    return;
  }
  for (const k of time) pips.appendChild(pipEquipeBoss(k));
}

let assinaturaEquipeBoss = '';
function assinaturaEquipeBossDe(eu) {
  return (eu?.pokemons ?? [])
    .filter((k) => k.slot != null)
    .sort((a, b) => a.slot - b.slot)
    .map((k) => `${k.id}:${k.hp ?? 0}:${k.maxHp ?? 0}:${k.level}`)
    .join('|');
}

/**
 * Lista à esquerda, ficha à direita — o mesmo desenho do original.
 *
 * A grade de 87 cartões que existia aqui gastava a tela inteira mostrando 85 fantasmas
 * cinzentos: quem abria a aba via um mural de "em breve" e tinha de caçar, no meio dele,
 * os dois que dão para jogar. Numa LISTA os 87 nomes cabem numa coluna estreita e rolam
 * rápido, e a área grande fica para o que interessa — a ficha de quem foi escolhido, com
 * arte grande, drops, entrada e o estado da SUA equipe antes de gastar o token.
 */
function renderBosses() {
  return `
    <p class="boss-intro">${t('boss.intro', { ideal: estado.maxEquipe ?? 5 })}</p>
    <p class="boss-intro boss-intro-tm">${t('boss.introTm')}</p>
    <div class="boss-corpo">
      <div class="boss-lista" id="boss-lista"></div>
      <div class="boss-ficha" id="boss-ficha"></div>
    </div>`;
}

/** Qual boss está aberto na ficha. Começa no primeiro DESAFIÁVEL, não no primeiro da lista. */
let bossAberto = null;

/** Galeria ordenada: jogáveis por nível mínimo, depois vitrine. */
function bossesOrdenados() {
  return [...estado.bossesCatalogo].sort((a, b) => {
    const ja = !!fichaDoBoss(a.key);
    const jb = !!fichaDoBoss(b.key);
    if (ja !== jb) return jb - ja;
    return a.level - b.level || a.name.localeCompare(b.name);
  });
}

function preencherArteBoss(el, b, px = 96) {
  el.replaceChildren();
  if (b?.looktype) {
    el.appendChild(spriteAnimado(b.looktype, px, 3, () => iconeEspecie(b.looktype, px)));
    return;
  }
  if (b?.img) {
    const img = document.createElement('img');
    img.src = `/assets/site${b.img}`;
    img.alt = b.name ?? '';
    el.appendChild(img);
  }
}

function montarBosses() {
  const lista = $('#boss-lista');
  if (!lista) return;

  const catalogo = bossesOrdenados();

  if (!bossAberto || !estado.bossesCatalogo.some((b) => b.key === bossAberto)) {
    bossAberto = catalogo.find((b) => fichaDoBoss(b.key))?.key ?? catalogo[0]?.key ?? null;
  }

  lista.innerHTML = '';
  for (const b of catalogo) {
    const ficha = fichaDoBoss(b.key);
    const item = document.createElement('button');
    item.type = 'button';
    item.dataset.key = b.key;
    item.className =
      'boss-item' + (ficha ? '' : ' embreve') + (b.key === bossAberto ? ' on' : '');
    const ico = document.createElement('span');
    ico.className = 'boss-item-ico';
    if (b.looktype) ico.appendChild(iconeEspecie(b.looktype, 40));
    else if (b.img) {
      const img = document.createElement('img');
      img.src = `/assets/site${b.img}`;
      img.alt = '';
      img.loading = 'lazy';
      ico.appendChild(img);
    }
    const nome = document.createElement('span');
    nome.className = 'boss-item-nome';
    nome.textContent = b.name;
    const nv = document.createElement('span');
    nv.className = 'boss-item-nv';
    nv.textContent = `Nv ${num(b.level)}`;
    // Contador de vitórias: só aparece depois da primeira derrota, para a lista não virar
    // uma coluna de "🏆 0". O texto completo fica no `title` e na ficha à direita.
    const venc = document.createElement('span');
    venc.className = 'boss-item-venc';
    const nVenc = vezesDerrotadoBoss(b.key);
    venc.classList.toggle('hidden', !nVenc);
    venc.textContent = nVenc ? `🏆 ${num(nVenc)}` : '';
    venc.title = t('boss.vitorias', { n: num(nVenc) });
    item.append(ico, nome, venc, nv);
    item.onclick = () => {
      bossAberto = b.key;
      for (const outro of lista.children) outro.classList.toggle('on', outro === item);
      pintarFichaDoBoss();
    };
    lista.appendChild(item);
  }
  pintarFichaDoBoss();
}

/**
 * Atualiza só o "Vezes derrotado" de um boss — no chip da lista e na ficha, se for o aberto —
 * sem remontar a aba inteira (o que zeraria a rolagem dos 87 e reiniciaria os sprites).
 */
function atualizarContadorBoss(key) {
  const n = vezesDerrotadoBoss(key);
  const chip = $('#boss-lista')?.querySelector(`.boss-item[data-key="${CSS.escape(key)}"] .boss-item-venc`);
  if (chip) {
    chip.textContent = n ? `🏆 ${num(n)}` : '';
    chip.title = t('boss.vitorias', { n: num(n) });
    chip.classList.toggle('hidden', !n);
  }
  if (key === bossAberto) {
    const selo = $('#boss-ficha')?.querySelector('.boss-vitorias');
    if (selo) selo.textContent = t('boss.vitorias', { n: num(n) });
  }
}

/** A ficha do boss aberto: arte, selos, drops, entrada, a sua equipe e o botão. */
function pintarFichaDoBoss() {
  const host = $('#boss-ficha');
  if (!host) return;

  const b = estado.bossesCatalogo.find((x) => x.key === bossAberto);
  if (!b) return void (host.innerHTML = '');
  const ficha = fichaDoBoss(b.key);

  // Drops: os da ficha vêm com ícone, quantidade e chance; os da galeria são só nomes —
  // é o que o original também mostra para quem ainda não abriu.
  //
  // DUAS casas, e sem zero à direita. Uma casa só arredondava o Fragmento de Mega Shiny Stone
  // de 0,25% para "0,3%" — um número que o jogador compara lado a lado com os 0,5% do
  // fragmento comum, e em que meio ponto percentual muda a conta do quanto vai farmar. O corte
  // dos zeros é o que mantém "0,5%" e "1%" curtos em vez de "0,50%" e "1,00%".
  const fmtChance = (chance) => {
    const pct = (chance ?? 0) * 100;
    // Abaixo de 0,1% vão QUATRO casas: é a faixa do MysticTicket (0,0005% a ~0,02%), e duas casas
    // arredondariam os 0,005% de um boss alto para "0,01%" — o dobro do que cai de verdade.
    const casas = pct > 0 && pct < 0.1 ? 4 : 2;
    const txt = pct.toFixed(casas).replace(/0+$/, '').replace(/\.$/, '');
    return `${txt.replace('.', ',')}%`;
  };
  const fmtDrop = (d) => {
    const ico = iconeItem(d.itemId);
    const qtd = d.qtd ? (d.qtd[0] === d.qtd[1] ? `×${d.qtd[0]}` : `×${d.qtd[0]}–${d.qtd[1]}`) : '';
    const chance = d.chance != null
      ? `<em>${t('boss.chancePorVitoria', { pct: fmtChance(d.chance) })}</em>`
      : `<em>${t('boss.sempreDrop')}</em>`;
    // `nomeItem` e não `d.nome`: o catálogo do servidor é todo em inglês, e era por isso que
    // "Fragmento de Chave" aparecia traduzido na bolsa e "Mega Stone Fragment" cru aqui.
    return `<span class="boss-drop">
      ${ico ? `<img src="${ico}" alt="">` : ''}${escapar(nomeItem(d.itemId, d.nome))}
      <b>${qtd}</b>${chance}</span>`;
  };
  const drops = ficha
    ? ficha.drops.map(fmtDrop).join('')
    : (b.drops ?? []).map((d) => `<span class="boss-drop">${escapar(d)}</span>`).join('');
  const tmPecas = ficha?.drops?.filter((d) => /tm|piece/i.test(d.nome)) ?? [];
  const blocoTm = tmPecas.length
    ? `<div class="boss-tm-pecas">
        <b>${t('boss.tmPecas')}</b>
        <div class="boss-droplista">${tmPecas.map((d) => {
          const ico = iconeItem(d.itemId);
          const pct = d.chance != null ? fmtChance(d.chance) : '—';
          return `<span class="boss-drop boss-drop-tm">
            ${ico ? `<img src="${ico}" alt="">` : ''}${escapar(nomeItem(d.itemId, d.nome))}
            <b>${t('boss.chancePorVitoria', { pct })}</b></span>`;
        }).join('')}</div>
      </div>`
    : '';

  // A arte e os drops rolam; a entrada, a equipe e o botão NÃO. O que decide se vale a
  // pena entrar tem de estar sempre à vista — um "Desafiar" que só aparece depois de rolar
  // é um botão que metade das pessoas não encontra.
  const nvMin = ficha?.minNivelTreinador ?? b.minNivelTreinador ?? b.level ?? 0;
  const nvTreinador = estado.eu?.level ?? 0;
  const nvOk = nvTreinador >= nvMin;
  const tiposBoss = [ficha?.type1 ?? b.type1, ficha?.type2 ?? b.type2].filter(Boolean);
  const { fracos: fraquezasBoss } = tiposBoss.length
    ? matchupDefensivo(tiposBoss, estado.tabelaTipos)
    : { fracos: [] };
  const blocoTiposBoss = tiposBoss.length
    ? `<div class="boss-tipos">
        <b>${t('boss.tipos')}</b>
        <div class="boss-tipos-linha">${selosDeTipo(tiposBoss)}</div>
      </div>`
    : '';
  const blocoFraquezas = fraquezasBoss.length
    ? `<div class="boss-fraquezas">
        <b>${t('boss.fraquezas')}</b>
        ${blocoTiposAnalyser(fraquezasBoss, false, true)}
      </div>`
    : '';

  host.innerHTML = `
    <div class="boss-rolagem">
      <div class="boss-arte"></div>
      <h4 class="boss-nome">${escapar(b.name)}</h4>
      <div class="boss-selos">
        <span class="boss-cat">${escapar(b.category)}</span>
        <span class="boss-nv">${t('boss.nivel', { nv: num(b.level) })}</span>
        ${ficha ? `<span class="boss-nv-min ${nvOk ? '' : 'travado'}">${t('boss.nivelMinTreinador', { nv: num(nvMin) })}</span>` : ''}
        ${ficha ? '' : `<span class="boss-embreve">${t('boss.emBreve')}</span>`}
        <span class="boss-vitorias">${t('boss.vitorias', { n: num(vezesDerrotadoBoss(b.key)) })}</span>
      </div>
      ${blocoTiposBoss}
      ${blocoFraquezas}
      <div class="boss-drops">
        <b>${t('boss.recompensas')}</b>
        <div class="boss-droplista">${drops || `<span class="boss-drop">—</span>`}</div>
      </div>
      ${blocoTm}
    </div>
    <div class="boss-rodape"></div>`;

  preencherArteBoss(host.querySelector('.boss-arte'), b, 96);

  const rodape = host.querySelector('.boss-rodape');

  if (!ficha) {
    rodape.innerHTML = `<p class="boss-semarena">${t('boss.semArena')}</p>`;
    return;
  }

  const pen = penalidadeDaMinhaEquipe(ficha);
  const tem = estado.eu?.items?.[ficha.entrada.itemId] ?? 0;
  const podeEntrar = tem >= ficha.entrada.qtd && nvOk;
  const ico = iconeItem(ficha.entrada.itemId);

  rodape.innerHTML = `
    <div class="boss-entrada ${podeEntrar ? '' : 'falta'}">
      ${ico ? `<img src="${ico}" alt="">` : ''}
      <span>${t('boss.entrada')} <b>${ficha.entrada.qtd}× ${escapar(ficha.entrada.nome)}</b></span>
      <em>${t('boss.voceTem', { n: num(tem) })}</em>
    </div>
    <div class="boss-equipe" id="boss-equipe"></div>
    <div class="boss-aviso ${pen.mult >= 2 ? 'ruim' : ''}">
      ${t('boss.penalidade', {
        membros: pen.membros,
        ideal: ficha.equipeIdeal,
        nivel: num(ficha.teamLevel),
        mult: pen.mult >= 10 ? num(Math.round(pen.mult)) : pen.mult.toFixed(2),
      })}
    </div>`;

  // As pastilhas do time: o mesmo sprite + barra do painel da equipe, em fileira horizontal.
  pintarEquipeDoBoss();
  assinaturaEquipeBoss = assinaturaEquipeBossDe(estado.eu);

  const bt = document.createElement('button');
  bt.className = 'boss-desafiar';
  bt.textContent = !nvOk
    ? t('boss.nivelTreinadorInsuficiente', { nv: num(nvMin) })
    : podeEntrar
      ? t('boss.desafiar')
      : t('boss.semEntrada');
  bt.disabled = !podeEntrar;
  bt.onclick = () => {
    enviar({ t: 'boss.entrar', key: b.key });
    fecharModal();
  };
  rodape.appendChild(bt);
  rodape.appendChild(linhaAutoBoss(b, tem));
}

/**
 * O interruptor de REPETIR o boss.
 *
 * Quem junta trinta tokens não quer clicar trinta vezes em "Desafiar", esperar a luta, ir ao
 * Centro, curar e voltar — é a mesma sequência sempre, e é justamente o tipo de coisa que um
 * jogo idle deve fazer sozinho. Ligado, o servidor repete a série até o último token.
 *
 * O rótulo diz quantas lutas ainda cabem: é a informação que decide se vale ligar agora ou
 * juntar mais um pouco. Quem manda no ciclo é o sim (`boss.auto`) — aqui é só o botão.
 */
function linhaAutoBoss(b, tokens) {
  const ligado = !!estado.eu?.boss?.auto;
  const key = estado.eu?.boss?.autoKey ?? null;
  const el = document.createElement('label');
  el.className = 'auto-linha boss-auto' + (ligado ? ' on' : '');
  el.innerHTML = `
    <span>
      ${t('boss.repetir')}
      <em>${ligado && key && key !== b.key
        ? t('boss.repetindoOutro', { nome: escapar(nomeDoBoss(key)) })
        : t('boss.repetirAjuda', { n: num(tokens) })}</em>
    </span>
    <input type="checkbox" ${ligado ? 'checked' : ''}>`;
  el.querySelector('input').onchange = (ev) => {
    const ativo = ev.target.checked;
    // Ligar manda a chave do boss ABERTO na ficha: é o que o jogador está olhando quando
    // clica, e sem ela o servidor cairia no último boss enfrentado — que pode ser outro.
    enviar({ t: 'boss.auto', ativo, key: b.key });
    if (ativo) toast(t('boss.repetirLigado', { nome: b.name }));
  };
  return el;
}

const nomeDoBoss = (key) => estado.bossesCatalogo.find((x) => x.key === key)?.name ?? key;

// ----------------------------------------------------------------- ranking
//
// O placar do mundo, no molde do `/api/game/rankings` deles: abas por métrica, os três
// primeiros num pódio (com troféu e coroa de louros), o resto em lista, busca por nome e um
// cartão de perfil ao clicar num treinador.
//
// Seis abas — as métricas do placar global. As deles que dependem de sistemas
// que não temos (Pokelog, Nightmare, Boss Points, profissões) ficam de fora — abas vazias só
// ocupariam a barra.

const ABAS_RANKING = [
  // `nome` e `destaque` são CHAVES de i18n, não texto: quem desenha resolve com `t()`. Guardar
  // a frase pronta aqui congelaria o idioma do primeiro render.
  { id: 'nivel', nome: 'rk.treinadores', destaque: 'rk.maiorNivel' },
  { id: 'poder', nome: 'rk.pokemonForte', destaque: 'rk.maisForte' },
  { id: 'capturas', nome: 'rk.topCatch', destaque: 'rk.maisEspecies' },
  { id: 'coins', nome: 'rk.topCoins', destaque: 'rk.maisCoins' },
  { id: 'elo', nome: 'rk.arenaPvp', destaque: 'rk.maiorElo' },
  { id: 'bosses', nome: 'rk.bosses', destaque: 'rk.maisVitoriasBoss' },
  { id: 'guild', nome: 'rk.guild', destaque: 'rk.maisGp' },
  { id: 'guildGlobal', nome: 'rk.guildGlobal', destaque: 'rk.maisGpGlobal' },
];

/**
 * Como cada aba escreve o número da direita. É a tabela deles:
 * nível → "{xp} XP", poder → "⚔ {power}", o resto → o número puro.
 */
const VALOR_RANKING = {
  nivel: (l) => `${num(l.valor)} ${t('painel.xp')}`,
  poder: (l) => `⚔ ${num(l.valor)}`,
  capturas: (l) => t('rk.especies', { n: num(l.valor) }),
  coins: (l) => `${num(l.valor)} ${t('cm.emCoins')}`,
  // A aba de PvP mostra o RANK, não um número solto: "Ouro II · 1.240 PR" diz o que 1.240
  // significa, e é o mesmo rótulo que o jogador vê na aba de PvP e na ficha do treinador.
  elo: (l) => {
    const rank = l.tierId
      ? `${t(`pvp.tier.${l.tierId}`)} · ${num(l.valor)} ${t('pvp.pr')}`
      : `${num(l.valor)} ${t('pvp.pr')}`;
    // Quem decaiu continua listado pelos pontos que tem, e a linha diz por quê: sem a marca,
    // um Challenger que sumiu há duas semanas apareceria no topo com emblema de Diamante e
    // ninguém entenderia a diferença.
    return l.inativo ? `${rank} · ${t('pvp.inativo')}` : rank;
  },
  bosses: (l) => t('rk.bossVitorias', { n: num(l.valor) }),
  guild: (l) => {
    const gp = `${num(l.valor ?? l.gp)} GP`;
    const pct = Number(l.bonusPct) || 0;
    const rank = Number(l.rank) || 0;
    if (pct > 0 && rank > 0) return `${gp} · ${rotuloTopGuild(rank)} — +${pct}%`;
    return gp;
  },
  // Sem bônus de %: o pódio Global leva diamante só no fechamento do mês (ver a legenda).
  guildGlobal: (l) => `${num(l.valor ?? l.gp)} GP`,
};

/**
 * Rótulo "TOP n" para o bônus de guild no ranking de GP.
 *
 * Da 1ª à última posição com % próprio o rótulo é a posição; da primeira do piso em diante
 * (hoje o 10º) todas dividem a mesma linha, e o rótulo vira "TOP >9". Quem diz onde está essa
 * fronteira é `PRIMEIRA_POS_RESTO`, no mesmo arquivo da tabela — mudou a escada, muda o rótulo.
 */
function rotuloTopGuild(rank) {
  const r = Number(rank) || 0;
  if (r <= 0) return '';
  if (r >= PRIMEIRA_POS_RESTO) return `TOP >${PRIMEIRA_POS_RESTO - 1}`;
  return `TOP ${r}`;
}

/** Uma linha é de POKÉMON (aba de poder) ou de TREINADOR. Muda o avatar e o que é clicável. */
const ehLinhaPokemon = (l) => l.speciesId != null;

const gpRankingGuild = (l) => Number(l?.valor ?? l?.gp ?? 0);

/** As duas abas de guild (Diário e Global) desenham igual — brasão, nome, dono — só o número muda. */
const ehAbaGuild = (aba) => aba === 'guild' || aba === 'guildGlobal';

// As duas legendas saem das MESMAS tabelas com que o servidor paga (`shared/guild-premios.mjs`),
// pelo motivo de sempre: uma lista de `<li>` escrita no i18n prometeria, ao primeiro ajuste de
// balanceamento, um número que o servidor não paga mais. Cada escada tem quantas linhas tiver,
// e a classe `duas` reparte a lista em duas colunas para elas não empurrarem o ranking para
// baixo — no celular ela volta a ser uma coluna só (`mobile.css`).

function pintarLegendaGuild() {
  const el = $('#rk-guild-legenda');
  if (!el) return;
  el.classList.remove('hidden');
  const linhas = [...POSICOES_BONUS_GP, PRIMEIRA_POS_RESTO]
    .map((pos) => `<li>${t('rk.guildBonusLinha', {
      top: rotuloTopGuild(pos),
      n: bonusPctPorPosRanking(pos),
    })}</li>`)
    .join('');
  el.innerHTML = `
    <p class="rk-guild-legenda-tit">${t('rk.guildBonusTitulo')}</p>
    <ul class="rk-guild-legenda-lista duas">${linhas}</ul>
    <p class="rk-guild-legenda-nota">${t('rk.guildBonusZero')}</p>`;
}

function pintarLegendaGuildGlobal() {
  const el = $('#rk-guild-global-legenda');
  if (!el) return;
  el.classList.remove('hidden');
  const linhas = Object.entries(PREMIOS_GLOBAL)
    .map(([pos, qtd]) => `<li>${t('rk.guildGlobalBonusLinha', { top: `TOP ${Number(pos)}`, n: qtd })}</li>`)
    .join('');
  el.innerHTML = `
    <p class="rk-guild-legenda-tit">${t('rk.guildGlobalTitulo')}</p>
    <ul class="rk-guild-legenda-lista duas">${linhas}</ul>
    <p class="rk-guild-legenda-nota">${t('rk.guildGlobalBonusZero')}</p>`;
}

function pintarLegendaPvp() {
  const el = $('#rk-pvp-legenda');
  if (!el) return;
  el.classList.remove('hidden');
  // A legenda mostra o que ESTÁ EM JOGO, e não mais um bônus permanente de farm: a posição
  // agora paga uma vez, na virada da semana, em boost. As três linhas são as três faixas de
  // `PVP_PREMIOS` — se elas mudarem no shared, este texto tem de mudar junto.
  el.innerHTML = `
    <p class="rk-guild-legenda-tit">${t('rk.pvpPremiosTitulo')}</p>
    <ul class="rk-guild-legenda-lista">
      <li>${t('rk.pvpPremio1')}</li>
      <li>${t('rk.pvpPremio2')}</li>
      <li>${t('rk.pvpPremio3')}</li>
    </ul>
    <p class="rk-guild-legenda-nota">${t('rk.pvpPremiosNota', { horas: PVP_DECAIMENTO_HORAS })}</p>`;
}

function pintarLegendaPoder() {
  const el = $('#rk-poder-legenda');
  if (!el) return;
  el.classList.remove('hidden');
  el.innerHTML = `
    <p class="rk-guild-legenda-tit">${t('rk.poderFormulaTitulo')}</p>
    <pre class="rk-formula">${escapar(t('rk.poderFormula'))}</pre>`;
}

function linhasPodioRanking(aba, linhas) {
  if (!ehAbaGuild(aba)) return linhas;
  return linhas.filter((l) => gpRankingGuild(l) > 0);
}

function renderRanking() {
  const aba = estado.abaRanking ?? 'nivel';
  return `
    <div class="rk-abas">
      ${ABAS_RANKING.map(
        (a) => `<button class="rk-aba ${a.id === aba ? 'on' : ''}" data-aba="${a.id}">${t(a.nome)}</button>`,
      ).join('')}
    </div>
    <div class="rk-corpo">
      <div class="rk-principal">
        <div class="filtro-linha rk-boss-filtro hidden" id="rk-boss-filtro">
          <label class="rk-boss-label" for="rk-boss-select">${t('rk.bossEscolher')}</label>
          <select id="rk-boss-select" class="rk-boss-select"></select>
        </div>
        <div class="rk-guild-legenda hidden" id="rk-guild-legenda"></div>
        <div class="rk-guild-legenda hidden" id="rk-guild-global-legenda"></div>
        <div class="rk-guild-legenda hidden" id="rk-pvp-legenda"></div>
        <div class="rk-guild-legenda hidden" id="rk-poder-legenda"></div>
        <div class="rk-podio" id="rk-podio"></div>
        <div class="filtro-linha"><input id="rk-busca" placeholder="buscar treinador…" autocomplete="off"></div>
        <div class="rk-linhas" id="rk-linhas"></div>
      </div>
      <aside class="rk-destaques" id="rk-destaques"></aside>
    </div>`;
}

/** Avatar da linha: pokémon, treinador ou brasão de guild. */
function avatarRanking(l, px, aba) {
  if (ehAbaGuild(aba)) {
    const span = document.createElement('span');
    span.className = 'rk-brasao';
    pintarBrasao(span, l.brasao, px);
    return span;
  }
  if (ehLinhaPokemon(l)) return spritePokemon(l, px);
  return spriteAnimado(l.looktype ?? LOOKTYPE_TREINADOR, px, 3, null, l.vs, { treinador: true });
}

const souEu = (l, aba) =>
  ehAbaGuild(aba)
    ? estado.eu?.guild?.id === l.id
    : (ehLinhaPokemon(l) ? l.nick : l.nick) === estado.eu?.nick;

/** Boss padrão do placar — o primeiro jogável, ou regice se existir. */
function bossKeyRankingPadrao() {
  const lista = estado.bossesJogaveis ?? [];
  if (!lista.length) return '';
  return lista.find((b) => b.key === 'regice')?.key ?? lista[0].key;
}

/** Linhas do placar da aba atual — bosses usa cache por `bossKey`. */
function linhasRankingAba(aba) {
  if (aba === 'bosses') {
    const key = estado.rankingBossKey || bossKeyRankingPadrao();
    return key ? estado.rankingBoss?.[key] : null;
  }
  return estado.ranking[aba];
}

function pintarSelectBossRanking() {
  const host = $('#rk-boss-select');
  if (!host) return;
  const atual = estado.rankingBossKey || bossKeyRankingPadrao();
  if (!estado.rankingBossKey && atual) estado.rankingBossKey = atual;
  const ordenados = [...(estado.bossesJogaveis ?? [])].sort(
    (a, b) => (a.minNivelTreinador ?? a.level ?? 0) - (b.minNivelTreinador ?? b.level ?? 0)
      || String(a.nome ?? a.name ?? '').localeCompare(String(b.nome ?? b.name ?? '')),
  );
  host.innerHTML = ordenados.map(
    (b) => `<option value="${escapar(b.key)}"${b.key === atual ? ' selected' : ''}>${escapar(b.nome ?? b.name ?? b.key)}</option>`,
  ).join('');
}

function pedirRankingBoss(key) {
  if (!key) return;
  estado.rankingBossKey = key;
  if (estado.rankingBoss?.[key]) return;
  enviar({ t: 'ranking.pedir', aba: 'bosses', bossKey: key });
}

function pintarRanking() {
  const aba = estado.abaRanking ?? 'nivel';
  const linhas = linhasRankingAba(aba);
  const podio = $('#rk-podio');
  const lista = $('#rk-linhas');
  if (!podio || !lista) return;

  $('#rk-boss-filtro')?.classList.toggle('hidden', aba !== 'bosses');
  if (aba === 'bosses') pintarSelectBossRanking();

  $('#rk-guild-legenda')?.classList.toggle('hidden', aba !== 'guild');
  $('#rk-guild-global-legenda')?.classList.toggle('hidden', aba !== 'guildGlobal');
  $('#rk-pvp-legenda')?.classList.toggle('hidden', aba !== 'elo');
  $('#rk-poder-legenda')?.classList.toggle('hidden', aba !== 'poder');
  if (aba === 'guild') pintarLegendaGuild();
  if (aba === 'guildGlobal') pintarLegendaGuildGlobal();
  if (aba === 'elo') pintarLegendaPvp();
  if (aba === 'poder') pintarLegendaPoder();

  if (!linhas) {
    podio.innerHTML = '';
    lista.innerHTML = '<div class="aviso-modal">carregando o placar…</div>';
    return;
  }
  if (!linhas.length) {
    podio.innerHTML = '';
    const msg = aba === 'bosses'
      ? t('rk.bossVazio', { boss: nomeDoBoss(estado.rankingBossKey || bossKeyRankingPadrao()) })
      : 'ninguém no ranking ainda. Seja o primeiro! 🚀';
    lista.innerHTML = `<div class="aviso-modal">${msg}</div>`;
    return;
  }

  const valor = VALOR_RANKING[aba];
  const podioLinhas = linhasPodioRanking(aba, linhas);
  const idsPodio = new Set(podioLinhas.slice(0, 3).map((l) => l.id ?? l.nick));

  // Pódio: 2º à esquerda, 1º no meio (maior), 3º à direita — a mesma montagem deles.
  podio.innerHTML = '';
  for (const pos of [2, 1, 3]) {
    const l = podioLinhas[pos - 1];
    const caixa = document.createElement('div');
    caixa.className = `rk-pod lugar-${pos}`;
    if (!l) {
      caixa.classList.add('vazio');
      podio.appendChild(caixa);
      continue;
    }
    caixa.innerHTML = `
      <img class="rk-pod-trofeu" src="/assets/site/assets/ui/trofeu-${pos}.png" alt="${pos}º lugar">
      <div class="rk-pod-lugar">${pos}º Lugar</div>
      <div class="rk-pod-ava">
        <img class="rk-pod-coroa" src="/assets/site/assets/ui/coroa-${pos}.png" alt="" aria-hidden="true">
      </div>
      <div class="rk-pod-nome">${escapar(ehAbaGuild(aba) ? l.nome : ehLinhaPokemon(l) ? l.nome : l.nick)}</div>
      ${ehLinhaPokemon(l) ? `<div class="rk-pod-dono">${escapar(l.nick)}</div>` : ehAbaGuild(aba) ? `<div class="rk-pod-dono">${escapar(l.ownerNick ?? '')}</div>` : ''}
      <div class="rk-pod-val">${valor(l)}</div>`;
    caixa.querySelector('.rk-pod-ava').appendChild(avatarRanking(l, pos === 1 ? 64 : 48, aba));
    if (souEu(l, aba)) caixa.classList.add('eu');
    caixa.onclick = () => aoClicarLinhaRanking(l, aba);
    podio.appendChild(caixa);
  }

  // Lista: do 4º em diante (guild: todos fora do pódio, inclusive 0 GP).
  const busca = (estado.buscaRanking ?? '').trim().toLowerCase();
  const resto = (
    ehAbaGuild(aba)
      ? linhas.filter((l) => !idsPodio.has(l.id ?? l.nick))
      : linhas.slice(3)
  ).filter(
    (l) => !busca || l.nick.toLowerCase().includes(busca) || (l.nome ?? '').toLowerCase().includes(busca),
  );
  lista.innerHTML = '';
  for (const l of resto) {
    const el = document.createElement('div');
    el.className = 'rk-linha' + (souEu(l, aba) ? ' eu' : '');
    el.innerHTML = `
      <span class="rk-pos">${l.rank}</span>
      <span class="rk-ava"></span>
      <span class="rk-main">
        <b>${escapar(ehAbaGuild(aba) ? l.nome : ehLinhaPokemon(l) ? l.nome : l.nick)}</b>
        <small>${
          ehAbaGuild(aba)
            ? escapar(l.ownerNick ?? '')
            : ehLinhaPokemon(l)
              ? `${escapar(l.nick)} · Nv ${num(l.level)}`
              : `Nv ${num(l.level)}`
        }</small>
      </span>
      <span class="rk-val">${valor(l)}</span>`;
    el.querySelector('.rk-ava').appendChild(avatarRanking(l, 30, aba));
    el.onclick = () => aoClicarLinhaRanking(l, aba);
    lista.appendChild(el);
  }
  if (!resto.length) lista.innerHTML = '<div class="aviso-modal">— fim do ranking —</div>';

  pintarDestaques();
}

/** Coluna da direita: o primeiro colocado de cada aba, de relance. */
function pintarDestaques() {
  const host = $('#rk-destaques');
  if (!host) return;
  host.innerHTML = '<h3>Destaques</h3>';
  for (const a of ABAS_RANKING) {
    const topo = a.id === 'bosses'
      ? estado.rankingBoss?.[estado.rankingBossKey || bossKeyRankingPadrao()]?.[0]
      : estado.ranking[a.id]?.[0];
    const el = document.createElement('div');
    el.className = 'rk-destaque';
    el.innerHTML = `
      <span class="rk-d-rot">${t(a.destaque)}</span>
      <span class="rk-d-val">${
        topo && (!ehAbaGuild(a.id) || gpRankingGuild(topo) > 0)
          ? `${escapar(ehAbaGuild(a.id) ? topo.nome : ehLinhaPokemon(topo) ? topo.nome : topo.nick)} · ${VALOR_RANKING[a.id](topo)}`
          : '—'
      }</span>`;
    host.appendChild(el);
  }
}

/** Pede uma aba ao servidor (se ainda não veio) e desenha o que já tem. */
function abrirAbaRanking(aba) {
  estado.abaRanking = aba;
  if (aba === 'bosses') {
    const key = estado.rankingBossKey || bossKeyRankingPadrao();
    if (key) pedirRankingBoss(key);
  } else if (!estado.ranking[aba]) {
    enviar({ t: 'ranking.pedir', aba });
  }
  pintarRanking();
}

function pedirPerfil(nick) {
  if (!nick) return;
  enviar({ t: 'ranking.perfil', nick });
}

function pedirFichaRanking(l) {
  enviar({
    t: 'ranking.pokemon',
    nick: l.nick,
    speciesId: l.speciesId,
    level: l.level,
    power: l.valor,
  });
}

/**
 * O clique numa linha do placar. Cada aba abre a ficha do que ela LISTA.
 *
 * A de guild não abria nada até aqui — era a única lista do jogo em que clicar não fazia
 * coisa alguma, e justamente aquela em que o nome sozinho diz menos: `l.nick` numa linha de
 * guild é o dono, e abrir o perfil dele não responde nada sobre a guild.
 */
function aoClicarLinhaRanking(l, aba) {
  if (ehAbaGuild(aba)) return pedirDetalheGuild(l.id);
  if (aba === 'poder' && ehLinhaPokemon(l)) return pedirFichaRanking(l);
  pedirPerfil(l.nick);
}

/** Amizade com o nick da ficha pública aberta — `null` se for você mesmo. */
function estadoAmizadePerfil(nick) {
  const bruto = String(nick ?? '').trim();
  if (!bruto) return null;
  const meu = String(estado.eu?.nick ?? estado.nick ?? '').toLowerCase();
  if (bruto.toLowerCase() === meu) return null;
  if (amigoPorNick(bruto)) return 'amigo';
  if ((amigosStore().enviados ?? []).some((e) => String(e).toLowerCase() === bruto.toLowerCase())) {
    return 'pedido_enviado';
  }
  return 'pode_pedir';
}

/** Atalhos sociais na ficha de OUTRO treinador — amigo e bloqueio de chat. */
function htmlAcoesPerfilOutro(nick) {
  const est = estadoAmizadePerfil(nick);
  if (!est) return '';
  const nivelOk = (estado.eu?.level ?? 0) >= CHAT_NIVEL_MIN || estado.souAdmin;
  const bloqueado = nickIgnoradoNoChat(nick);

  let amigoHtml = '';
  if (est === 'amigo') {
    amigoHtml = `<span class="pf-soc-badge ok">${escapar(t('pf.jaAmigo'))}</span>`;
  } else if (est === 'pedido_enviado') {
    amigoHtml = `<span class="pf-soc-badge pend">${escapar(t('pf.pedidoEnviado'))}</span>`;
  } else {
    amigoHtml = `<button type="button" class="pf-soc-bt" id="pf-adicionar-amigo"${
      nivelOk ? '' : ` disabled title="${escapar(t('amigos.nivelMinimo'))}"`
    }>${escapar(t('pf.adicionarAmigo'))}</button>`;
  }

  const bloqueioHtml = `<button type="button" class="pf-soc-bt perigo" id="pf-bloquear">${
    escapar(t(bloqueado ? 'pf.desbloquear' : 'pf.bloquear'))
  }</button>`;

  return `<div class="pf-acoes-sociais">${amigoHtml}${bloqueioHtml}</div>`;
}

function repintarAcoesPerfilOutro(nick) {
  const host = $('#perfil-corpo .pf-acoes-sociais');
  if (!host || !nick) return;
  host.outerHTML = htmlAcoesPerfilOutro(nick);
  ligarAcoesPerfilOutro(nick);
}

function ligarAcoesPerfilOutro(nick) {
  $('#pf-adicionar-amigo')?.addEventListener('click', () => {
    if ((estado.eu?.level ?? 0) < CHAT_NIVEL_MIN && !estado.souAdmin) {
      toast(t('amigos.nivelMinimo'));
      return;
    }
    enviar({ t: 'amigo.pedir', nick });
  });
  $('#pf-bloquear')?.addEventListener('click', () => {
    const bloqueado = alternarIgnorarChat(nick);
    limparMsgsDeIgnorados();
    toast(t(bloqueado ? 'pf.bloqueadoOk' : 'pf.desbloqueadoOk', { nick }));
    pintarChat();
    pintarSelosChatAbas();
    pintarPainelIgnorados();
    repintarAcoesPerfilOutro(nick);
  });
}

/** Cartão de perfil: mesma ficha do treinador, sem dados de conta. */
function mostrarPerfil(p) {
  estado.perfilOutroNick = p.nick ?? null;
  $('#perfil-titulo').textContent = p.nick;
  const totalDex = especiesPokedex().length;
  const statsOcultos = p.statsPublico === false;
  $('#perfil-corpo').innerHTML = htmlPerfilTreinador({
    ...p,
    capturadasDex: p.capturasEsp ?? 0,
    totalDex,
    statsOcultos,
  }, {
    retratoId: 'pf-retrato-outro',
    mostrarVitrine: true,
    vitrineId: 'pf-vitrine-outro',
    // Sempre a equipe do PvP Ranqueado, inscrito no campeonato ou não. A do campeonato não
    // vem no pacote (ver `ranking.perfil` no sim).
    mostrarPvpTime: true,
    pvpTimeId: 'pf-pvptime-outro',
    acoesSociais: htmlAcoesPerfilOutro(p.nick),
  });
  ligarAcoesPerfilOutro(p.nick);
  montarEquipePvpDoPerfil(p);
  montarVitrineDoPerfilPublico(p);
  $('#pf-retrato-outro')?.replaceChildren(
    spriteAnimado(p.looktype ?? LOOKTYPE_TREINADOR, 56, 3, null, p.vs, { treinador: true }),
  );
  $('#perfil').classList.remove('hidden');
}

const fecharPerfil = () => {
  estado.perfilOutroNick = null;
  $('#perfil').classList.add('hidden');
};

/** Faixas da Pokédex nacional por aba (1–9). */
const POKEDEX_GERACOES = [
  { id: 1, min: 1, max: 151, rotulo: 'dex.ger1' },
  { id: 2, min: 152, max: 251, rotulo: 'dex.ger2' },
  { id: 3, min: 252, max: 386, rotulo: 'dex.ger3' },
  { id: 4, min: 387, max: 493, rotulo: 'dex.ger4' },
  { id: 5, min: 494, max: 649, rotulo: 'dex.ger5' },
  { id: 6, min: 650, max: 721, rotulo: 'dex.ger6' },
  { id: 7, min: 722, max: 809, rotulo: 'dex.ger7' },
  { id: 8, min: 810, max: 905, rotulo: 'dex.ger8' },
  { id: 9, min: 906, max: 1025, rotulo: 'dex.ger9' },
  { id: 10, min: 2001, max: 2058, rotulo: 'dex.gerOutland' },
  // As MEGAS, na faixa #3026…#3780 (`3000 + dex`). Aba própria ao lado da de Outland, pela
  // mesma razão que a de Outland existe: são espécies que não pertencem a geração nenhuma e
  // que, espalhadas pelas nove abas nacionais, apareceriam como um segundo Gengar sem
  // explicação. Ver `shared/megas.mjs`.
  { id: 11, min: 3001, max: 3999, rotulo: 'dex.gerMega' },
];

const geracaoPokedex = (c) => {
  if (isOutlandPokeId(c.pokeId)) return 10;
  if (isMegaPokeId(c.pokeId)) return 11;
  return POKEDEX_GERACOES.find((g) => c.pokeId >= g.min && c.pokeId <= g.max)?.id ?? null;
};

/** Só listamos quem tem sprite no jogo — ver `sprite-jogo.mjs`. */

/** Uma entrada por número de dex — nacional ou Outland (#2001+). Clones Orre (13xxx) ficam de fora. */
function especiesPokedex() {
  const porDex = new Map();
  for (const c of estado.especies.values()) {
    if (isOutlandPokeId(c.pokeId)) continue;
    if (isEspelhoFantasmaPokeId(c.pokeId)) continue;
    if (!temSpriteJogo(c)) continue;
    const chave = chavePokedex(c.pokeId);
    if (chave == null) continue;
    const ant = porDex.get(chave);
    if (!ant || c.pokeId < ant.pokeId) porDex.set(chave, c);
  }
  for (const c of estado.especies.values()) {
    if (!isOutlandPokeId(c.pokeId)) continue;
    if (!temSpriteJogo(c)) continue;
    const dex = estado.outlandDex?.pokeToDex?.[c.pokeId];
    if (!dex) continue;
    porDex.set(`o${dex}`, c);
  }
  return [...porDex.values()].sort((a, b) => dexExibicao(a.pokeId) - dexExibicao(b.pokeId));
}

/** Espécies únicas capturadas vs total do catálogo jogável — o mesmo critério da tela da Pokédex. */
function contagemEspeciesDexPerfil(pokedex = estado.eu?.pokedex ?? {}) {
  const catalogo = especiesPokedex();
  const total = catalogo.length;
  let capturadas = 0;
  for (const c of catalogo) {
    const n = chavePokedex(c.pokeId);
    if (n == null) continue;
    const a = pokedex[n] ?? pokedex[String(n)];
    const leg = c.pokeId !== n ? pokedex[c.pokeId] ?? pokedex[String(c.pokeId)] : null;
    if (((a?.c ?? 0) + (leg?.c ?? 0)) > 0) capturadas++;
  }
  return { capturadas, total };
}

function contagemPokedexPorGeracao() {
  const n = new Map();
  for (const c of especiesPokedex()) {
    const g = geracaoPokedex(c);
    if (g) n.set(g, (n.get(g) ?? 0) + 1);
  }
  return n;
}

function tiposDaEspecieDex(c) {
  return [c.type1, c.type2].filter(Boolean);
}

/**
 * O selinho BOSS do card da grade.
 *
 * O boss de evento leva o mesmo selo — ele É um boss — mas em tom apagado, para o card não
 * prometer uma arena que ainda não existe. Quem quiser o porquê abre a ficha, que explica.
 */
function selinhoBossGrade(pokeId) {
  if (bossDaEspecie(pokeId)) return '<span class="dx-boss">BOSS</span>';
  if (ehBossDeEvento(pokeId)) return `<span class="dx-boss evento" title="${escapar(t('dex.bossEventoTag'))}">BOSS</span>`;
  return '';
}

function montarGradePokedex() {
  const grade = $('#grade-dex');
  if (!grade) return;
  const q = (estado.filtroPokedex.busca || '').trim().toLowerCase();
  const buscaGlobal = q.length > 0;
  const ger = estado.filtroPokedex.ger;
  const elem = estado.filtroPokedex.elemento;

  grade.innerHTML = '';
  let n = 0;
  for (const c of especiesPokedex()) {
    if (!buscaGlobal && geracaoPokedex(c) !== ger) continue;
    if (elem && !pokemonDoTipo(tiposDaEspecieDex(c), elem)) continue;
    const d = entradaPokedex(c.pokeId);
    const visto = d.k > 0 || d.c > 0;
    if (estado.filtroPokedex.somenteConhecidos && !visto) continue;
    const numDex = dexExibicao(c.pokeId);
    if (buscaGlobal && !c.name.toLowerCase().includes(q) && !String(numDex).includes(q)) continue;

    const card = document.createElement('div');
    card.className = `dex-card ${d.c > 0 ? 'pego' : visto ? 'visto' : 'desconhecido'}`;
    card.title = visto ? `${d.k} derrotas · ${d.c} capturas` : 'não encontrado ainda';
    const pad = isOutlandPokeId(c.pokeId) || isMegaPokeId(c.pokeId) ? 4 : 3;
    card.innerHTML = `
      <div class="dx-n">#${String(numDex).padStart(pad, '0')}${selinhoBossGrade(c.pokeId)}</div>
      <div class="dx-nome">${visto ? escapar(c.name) : '???'}</div>`;
    card.prepend(spriteAnimado(c.looktype, 40));
    card.onclick = () => abrirFichaDaEspecie(c.pokeId);
    grade.appendChild(card);
    n++;
  }

  const vazio = grade.parentElement.querySelector('.dex-vazio');
  if (vazio) vazio.remove();
  if (!n) {
    const msg = document.createElement('p');
    msg.className = 'dex-vazio fi-vazio';
    const filtrado = buscaGlobal || elem || estado.filtroPokedex.somenteConhecidos;
    msg.textContent = filtrado ? t('dex.semResultado') : t('dex.semGeracao');
    grade.after(msg);
  }
}

/**
 * "Copiar Pokédex para o ChatGPT": leva a tabela inteira de espécies para a área de
 * transferência e abre o ChatGPT numa aba nova.
 *
 * Gêmea de `copiarWikiParaGpt`, e pelas mesmas duas razões de mecânica: o texto passa de 100
 * mil caracteres (não cabe numa URL, que trunca no meio de uma linha da tabela), e o
 * `window.open` sai ANTES do `await` porque o navegador só deixa abrir aba enquanto o clique
 * ainda está quente — esperar a promessa da área de transferência joga a abertura para o
 * quadro seguinte, onde o bloqueador de pop-up come.
 *
 * O que muda em relação à Wiki é a FONTE: aqui não há texto de manual nenhum, só o catálogo do
 * `welcome`, e é ele que `pokedex-gpt.mjs` transforma em tabela.
 */
async function copiarPokedexParaGpt() {
  const lang = idioma();
  const texto = pokedexEmTexto({
    lang,
    especies: especiesPokedex(),
    dexDe: (esp) => dexExibicao(esp.pokeId),
    golpesDe: (esp) => golpesDaFicha(esp),
    // `huntsComEspecie` devolve as hunts inteiras (com o mapa, os spawns e tudo); daqui só
    // saem o nome e o nível, que é o que o arquivo precisa e o que o mantém legível.
    huntsDe: (esp) => huntsComEspecie(esp.pokeId).map((h) => ({ nome: h.nome, nivel: h.nivel })),
    nivelCapturaDe: (esp, nivelHunt) => nivelDeCaptura(nivelHunt, esp?.tetoCaptura ?? TETO_CAPTURA_MAX),
    chanceDe: (esp, catchRate) => chanceDeCaptura(esp, catchRate),
    temShiny: (esp) => temFormaShinyFicha(esp),
    bossDe: (esp) => bossDaEspecie(esp.pokeId),
    bossEventoDe: (esp) => ehBossDeEvento(esp.pokeId),
    // As megas (#3000+) não se capturam — se fabricam. Sem isto o arquivo entregava ao modelo
    // um "Nv de hunt" e uma chance de pokébola para elas. Ver `shared/megas.mjs`.
    megaDe: (esp) => isMegaPokeId(esp.pokeId),
    progressoDe: (esp) => entradaPokedex(esp.pokeId),
    bolas: estado.catalogoBolas ?? [],
    chanceShiny: Number(estado.chanceShiny) || 0,
    cabecalho: t('dex.gptCabecalho'),
  });

  const copia = copiarTexto(texto);
  window.open(URL_CHATGPT, '_blank', 'noopener');
  toast(t(await copia ? 'dex.copiado' : 'wiki.copiaFalhou'));
}

/**
 * A Pokédex como planilha, para ANEXAR na IA em vez de colar.
 *
 * O botão ao lado copia ~590 kB de texto, e é aí que a coisa falha: isso não cabe numa
 * conversa, é cortado na colagem, e o modelo completa o que faltou com o que ele sabe de
 * Pokémon em geral — que não são os números daqui. Anexado, o CSV é CONSULTADO em vez de lido,
 * e "todo golpe com cooldown abaixo de 5 s" vira uma resposta exata.
 *
 * Não custa banda: o catálogo já está no navegador desde o login, e o arquivo é montado em
 * memória. Ver o cabeçalho de `pokedex-csv.mjs`.
 */
function baixarPokedexCsv() {
  const csv = pokedexEmCsv({
    especies: especiesPokedex(),
    // A MESMA função que desenha a ficha — o arquivo não pode divergir do que está na tela.
    golpesDe: (esp) => golpesDaFicha(esp),
    dexDe: (esp) => dexExibicao(esp.pokeId),
    nivelHuntDe: (esp) => {
      const hunts = huntsComEspecie(esp.pokeId);
      return hunts.length ? Math.min(...hunts.map((h) => Number(h.nivel) || 1)) : null;
    },
  });
  baixarCsv(`pokeidle-pokedex-${new Date().toISOString().slice(0, 10)}.csv`, csv);
  toast(t('dex.csvBaixado'));
}

function ligarPokedex() {
  const dex = estado.eu.pokedex ?? {};
  const entradasDex = Object.values(dex);
  const catalogo = especiesPokedex();
  const porGer = contagemPokedexPorGeracao();
  const abasVisiveis = POKEDEX_GERACOES.filter((g) => (porGer.get(g.id) ?? 0) > 0);
  if (!abasVisiveis.some((g) => g.id === estado.filtroPokedex.ger)) {
    estado.filtroPokedex.ger = abasVisiveis[0]?.id ?? 1;
  }

  const ids = new Set(catalogo.map((c) => c.pokeId));
  const total = catalogo.length;
  const vistos = catalogo.filter((c) => entradaPokedex(c.pokeId).k > 0 || entradaPokedex(c.pokeId).c > 0).length;
  const pegos = catalogo.filter((c) => entradaPokedex(c.pokeId).c > 0).length;
  const derrotas = entradasDex.reduce((s, d) => s + (Number(d.k) || 0), 0);
  const capturas = entradasDex.reduce((s, d) => s + (Number(d.c) || 0), 0);
  const shinysVistos = entradasDex.reduce((s, d) => s + (Number(d.sv) || 0), 0);
  const shinysCapt = entradasDex.reduce((s, d) => s + (Number(d.sc) || 0), 0);
  const cont = $('#dex-contagem');
  if (cont) {
    const linha1 = `${t('dex.vistos')} <b class="txt-num">${vistos}</b> · ${t('dex.capturados')} <b class="txt-num">${pegos}</b> ${t('dex.de')} ${total}`;
    const linha2 = `${t('dex.resumoDerrotas', { n: num(derrotas) })} · ${t('dex.resumoCapturas', { n: num(capturas) })} · ${t('dex.resumoShVistos', { n: num(shinysVistos) })} · ${t('dex.resumoShCapt', { n: num(shinysCapt) })}`;
    cont.innerHTML = movelAtivo()
      ? `${linha1}<span class="dex-stats-sub">${linha2}</span>`
      : `${linha1} · ${linha2}`;
  }

  const abas = $('#dex-geracoes');
  if (abas) {
    abas.innerHTML = abasVisiveis.map((g) =>
      `<button type="button" class="mapa-area${g.id === estado.filtroPokedex.ger ? ' on' : ''}" data-ger="${g.id}">${t(g.rotulo)} <span class="txt-sec">${porGer.get(g.id)}</span></button>`,
    ).join('');
    abas.onclick = (ev) => {
      const b = ev.target.closest('[data-ger]');
      if (!b) return;
      estado.filtroPokedex.ger = Number(b.dataset.ger);
      ligarPokedex();
    };
  }

  const inp = $('#f-dex');
  if (inp) {
    inp.value = estado.filtroPokedex.busca;
    inp.oninput = (ev) => {
      estado.filtroPokedex.busca = ev.target.value;
      montarGradePokedex();
    };
  }

  const btGpt = $('#dex-gpt');
  if (btGpt) btGpt.onclick = copiarPokedexParaGpt;
  const btCsv = $('#dex-csv');
  if (btCsv) btCsv.onclick = baixarPokedexCsv;

  const chk = $('#dex-somente-conhecidos');
  if (chk) {
    chk.checked = !!estado.filtroPokedex.somenteConhecidos;
    chk.onchange = (ev) => {
      estado.filtroPokedex.somenteConhecidos = ev.target.checked;
      montarGradePokedex();
    };
  }

  const tipos = $('#dex-tipos');
  if (tipos) {
    const elem = estado.filtroPokedex.elemento;
    for (const b of tipos.querySelectorAll('[data-elem]')) {
      b.classList.toggle('on', elem ? b.dataset.elem === elem : b.dataset.elem === '');
    }
    tipos.onclick = (ev) => {
      const b = ev.target.closest('[data-elem]');
      if (!b) return;
      const val = b.dataset.elem;
      estado.filtroPokedex.elemento = estado.filtroPokedex.elemento === val ? '' : val;
      for (const outro of tipos.children) {
        outro.classList.toggle('on', outro.dataset.elem === estado.filtroPokedex.elemento
          || (!estado.filtroPokedex.elemento && outro.dataset.elem === ''));
      }
      montarGradePokedex();
    };
  }

  montarGradePokedex();
}

function renderPokedex() {
  const elem = estado.filtroPokedex.elemento;
  return `
    <div class="dex-topo">
      <div class="dex-filtros">
        <input id="f-dex" class="cm-busca" placeholder="${t('dex.buscar')}" autocomplete="off">
        <label class="auto-linha dex-filtro-conhecido">
          <span>${t('dex.somenteConhecidos')}</span>
          <input type="checkbox" id="dex-somente-conhecidos">
        </label>
        <!-- O mesmo botão da Wiki, e de propósito: quem já usou um sabe o que o outro faz.
             A Wiki leva as REGRAS, a Pokédex leva os DADOS — e o jogador que quer comparar
             espécies precisa dos dois no mesmo chat. -->
        <button type="button" id="dex-gpt" class="wk-gpt dex-gpt" title="${escapar(t('dex.copiarGptAjuda'))}">
          ${escapar(t('dex.copiarGpt'))}
        </button>
        <!-- Para PERGUNTA DE CONTA ("quais golpes têm cooldown < 5 s"), anexar a planilha
             funciona e colar o texto não: 590 kB não cabem num chat, e o que o modelo não lê
             ele inventa. Os dois botões coexistem porque servem a perguntas diferentes. -->
        <button type="button" id="dex-csv" class="wk-gpt dex-gpt" title="${escapar(t('dex.baixarCsvAjuda'))}">
          ${escapar(t('dex.baixarCsv'))}
        </button>
      </div>
      <p class="dex-stats" id="dex-contagem"></p>
    </div>
    <div class="dex-geracoes mapa-areas" id="dex-geracoes"></div>
    <div class="cm-tipos dex-tipos" id="dex-tipos">
      <button type="button" class="tipo-btn ${elem ? '' : 'on'}" data-elem="">${t('cm.todosTipos')}</button>
      ${TIPOS_FILTRO.map(
        (x) => `<button type="button" class="tipo-btn tipo ${x} ${elem === x ? 'on' : ''}" data-elem="${x}">${x}</button>`,
      ).join('')}
    </div>
    <div class="grade-dex" id="grade-dex"></div>`;
}

// --------------------------------------------------- registro de shinys
//
// A lista de TODOS os shinys do servidor: qual espécie, de quem, e — quando o dono anunciou —
// um botão para comprar ali mesmo.
//
// Ela mora ao lado do fechar da Pokédex porque é a mesma pergunta vista do outro lado: a dex
// diz o que EU já vi, esta diz o que EXISTE. Antes, a única forma de saber se alguém tinha um
// Dratini shiny era ver a mensagem do anúncio de captura passar no chat e lembrar.
//
// A busca e o filtro de tipo vão ao SERVIDOR (e não filtram uma lista já baixada): são
// milhares de linhas e a paginação é dele. É por isso que digitar tem `debounce` — sem ele,
// cada tecla viraria uma consulta.

/** O estado da tela: filtros, página e a última resposta. */
const shinysEstado = { busca: '', tipo: '', soAVenda: false, ordem: 'recentes', pagina: 0, dados: null, timer: 0 };

function renderShinys() {
  const f = shinysEstado;
  return `
    <div class="shl-topo">
      <input id="shl-busca" class="cm-busca" placeholder="${t('shl.buscar')}"
             value="${escapar(f.busca)}" autocomplete="off" maxlength="32">
      <label class="auto-linha shl-avenda">
        <span>${t('shl.soAVenda')}</span>
        <input type="checkbox" id="shl-avenda"${f.soAVenda ? ' checked' : ''}>
      </label>
      <span class="shl-conta" id="shl-conta"></span>
    </div>
    <div class="shl-barra">
      <label class="cm-ordenar">${t('cm.ordenarPor')}
        <select id="shl-ordem">${htmlOpcoesRegistroOrdem(f.ordem)}</select>
      </label>
    </div>
    <div class="cm-tipos shl-tipos" id="shl-tipos">
      <button class="tipo-btn ${f.tipo ? '' : 'on'}" data-elem="">${t('cm.todosTipos')}</button>
      ${TIPOS_FILTRO.map(
        (x) => `<button class="tipo-btn tipo ${x} ${f.tipo === x ? 'on' : ''}" data-elem="${x}">${x}</button>`,
      ).join('')}
    </div>
    <div class="shl-lista" id="shl-lista"><div class="cm-vazio">${t('cm.carregando')}</div></div>
    <div class="cm-paginas" id="shl-paginas"></div>`;
}

function ligarShinys() {
  const busca = $('#shl-busca');
  if (busca) {
    // 300 ms depois da última tecla. O jogador digita "gyara" em meio segundo, e sem a espera
    // isso seriam cinco consultas ao banco para mostrar o resultado de uma.
    busca.oninput = (ev) => {
      shinysEstado.busca = ev.target.value;
      clearTimeout(shinysEstado.timer);
      shinysEstado.timer = setTimeout(() => {
        shinysEstado.pagina = 0;
        pedirShinys();
      }, 300);
    };
  }
  $('#shl-avenda')?.addEventListener('change', (ev) => {
    shinysEstado.soAVenda = ev.target.checked;
    shinysEstado.pagina = 0;
    pedirShinys();
  });
  $('#shl-ordem')?.addEventListener('change', (ev) => {
    shinysEstado.ordem = ev.target.value || 'recentes';
    shinysEstado.pagina = 0;
    pedirShinys();
  });
  const tipos = $('#shl-tipos');
  if (tipos) {
    tipos.onclick = (ev) => {
      const b = ev.target.closest('[data-elem]');
      if (!b) return;
      shinysEstado.tipo = b.dataset.elem;
      shinysEstado.pagina = 0;
      for (const outro of tipos.children) outro.classList.toggle('on', outro === b);
      pedirShinys();
    };
  }
  pedirShinys();
}

function pedirShinys() {
  enviar({
    t: 'shiny.listar',
    busca: shinysEstado.busca,
    tipo: shinysEstado.tipo,
    soAVenda: shinysEstado.soAVenda,
    ordem: shinysEstado.ordem,
    pagina: shinysEstado.pagina,
  });
}

function receberShinys(m) {
  shinysEstado.dados = m;
  shinysEstado.pagina = m.pagina ?? shinysEstado.pagina;
  if (estado.modalAberto === 'shinys') pintarShinys();
}

function pintarShinys() {
  const host = $('#shl-lista');
  if (!host) return;
  const d = shinysEstado.dados ?? { linhas: [], total: 0 };

  const conta = $('#shl-conta');
  if (conta) conta.textContent = t('shl.total', { n: num(d.total ?? 0) });

  host.innerHTML = '';
  if (!d.linhas?.length) {
    host.innerHTML = `<div class="cm-vazio">${t('shl.vazio')}</div>`;
    pintarPaginasShinys();
    return;
  }
  for (const s of d.linhas) host.appendChild(cardShiny(s));
  pintarPaginasShinys();
}

/**
 * Um shiny na lista: arte, dono e — se estiver anunciado — o preço com o botão de comprar.
 *
 * O card inteiro abre a FICHA (nível, IV, potência, stats), porque comprar um shiny sem ver
 * isso é apostar. Só o botão de comprar não a abre: um clique que gasta gema não pode ser o
 * mesmo gesto de um clique que só informa.
 */
function cardShiny(s) {
  const el = document.createElement('div');
  el.className = 'cm-card poke shiny shl-card' + (s.meu ? ' shl-meu' : '');

  const arte = document.createElement('div');
  arte.className = 'cm-arte';
  arte.appendChild(spritePokemon({ ...s, shiny: true }, 64));

  const aVenda = s.anuncio;
  el.innerHTML = `
    <div class="cm-arte-slot"></div>
    <div class="cm-selos">${seloShiny()}</div>
    <div class="cm-info">
      <div class="cm-nome" title="${escapar(s.nome ?? '')}"><span class="cm-nome-txt">${escapar(s.nome ?? '—')}</span></div>
      <div class="cm-chips">${chipsDeTipo(s.tipos)}</div>
      <div class="cm-sub">${t('cm.nivel')} ${num(s.level)}</div>
      ${subDataCapturaRegistro(s)}
      ${selosAtributos(s)}
      <button class="cm-ficha" type="button">${t('cm.verFicha')}</button>
    </div>
    <div class="cm-rodape">
      ${aVenda ? precoComMoeda(s.anuncio.preco, s.anuncio.moeda, { curto: true }) : `<div class="shl-nao-venda">${t('shl.naoEstaVenda')}</div>`}
      <!-- "seu anúncio" só serviria para o que está à venda; a maior parte dos shinys da lista
           está no depot de alguém, e dizer "é seu" é o que responde à pergunta de quem procura
           os próprios no meio de centenas. -->
      <div class="cm-vend">${s.meu ? t('shl.seu') : `${t('shl.de')} <b>${escapar(s.dono)}</b>`}</div>
    </div>
    <div class="cm-botoes"></div>`;
  el.querySelector('.cm-arte-slot').replaceWith(arte);

  const abrirFicha = (ev) => {
    ev.stopPropagation();
    // A ficha espera o formato do Mercado; a linha já vem com quase tudo, só o `dono` é que
    // ali se chama assim e é o que vira o subtítulo do modal.
    abrirFichaDoPokemon({ ...s, shiny: true, dono: s.dono });
  };
  arte.onclick = abrirFicha;
  arte.style.cursor = 'pointer';
  el.querySelector('.cm-ficha').onclick = abrirFicha;

  // Comprar só existe para anúncio de OUTRO jogador. No próprio, o botão levaria a um erro do
  // servidor ("não dá para comprar o próprio anúncio") — melhor não oferecer.
  if (aVenda && !s.meu) {
    const bt = document.createElement('button');
    bt.className = 'cm-btn comprar';
    bt.textContent = t('cm.comprar');
    aplicarRetencaoCompra(bt, s.anuncio, () => confirmarCompraAnuncio({
      pk: { ...s, shiny: true },
      nome: s.nome ?? '',
      preco: s.anuncio.preco,
      moeda: s.anuncio.moeda,
      vendedor: s.dono,
      aoConfirmar: () => {
        enviar({
          t: 'market.comprar',
          id: s.anuncio.id,
          qtd: 1,
          preco: s.anuncio.preco,
          moeda: s.anuncio.moeda,
        });
        setTimeout(pedirShinys, 1000);
      },
    }));
    el.querySelector('.cm-botoes').appendChild(bt);
  }
  return el;
}

function pintarPaginasShinys() {
  const host = $('#shl-paginas');
  if (!host) return;
  const d = shinysEstado.dados;
  const porPagina = d?.porPagina ?? 40;
  const paginas = Math.max(1, Math.ceil((d?.total ?? 0) / porPagina));
  const atual = shinysEstado.pagina;
  if (paginas <= 1) return void (host.innerHTML = '');

  host.innerHTML = `
    <button class="cm-pag" ${atual <= 0 ? 'disabled' : ''} data-ir="${atual - 1}">‹</button>
    <span>${t('cm.paginaDe', { a: atual + 1, b: paginas })}</span>
    <button class="cm-pag" ${atual + 1 >= paginas ? 'disabled' : ''} data-ir="${atual + 1}">›</button>`;
  host.onclick = (ev) => {
    const b = ev.target.closest('[data-ir]');
    if (!b || b.disabled) return;
    shinysEstado.pagina = Number(b.dataset.ir);
    pedirShinys();
  };
}

// --------------------------------------------------- registro de P5 (potência máxima)
