function cardP5(s) {
  const el = document.createElement('div');
  el.className = 'cm-card poke shl-card' + (s.shiny ? ' shiny' : '') + (s.meu ? ' shl-meu' : '');

  const arte = document.createElement('div');
  arte.className = 'cm-arte';
  arte.appendChild(spritePokemon({ ...s, shiny: !!s.shiny }, 64));

  const aVenda = s.anuncio;
  el.innerHTML = `
    <div class="cm-arte-slot"></div>
    <div class="cm-selos">${s.shiny ? seloShiny() : ''}</div>
    <div class="cm-info">
      <div class="cm-nome" title="${escapar(s.nome ?? '')}"><span class="cm-nome-txt">${escapar(s.nome ?? '—')}</span></div>
      <div class="cm-chips">${chipsDeTipo(s.tipos)}</div>
      <div class="cm-sub">${t('cm.nivel')} ${num(s.level)}</div>
      ${subDataCapturaRegistro(s)}
      ${selosAtributos(s)}
      <button class="cm-ficha" type="button">${t('cm.verFicha')}</button>
    </div>
    <div class="cm-rodape">
      ${aVenda ? precoComMoeda(s.anuncio.preco, s.anuncio.moeda, { curto: true }) : `<div class="shl-nao-venda">${t('p5l.naoEstaVenda')}</div>`}
      <div class="cm-vend">${s.meu ? t('p5l.seu') : `${t('p5l.de')} <b>${escapar(s.dono)}</b>`}</div>
    </div>
    <div class="cm-botoes"></div>`;
  el.querySelector('.cm-arte-slot').replaceWith(arte);

  const abrirFicha = (ev) => {
    ev.stopPropagation();
    abrirFichaDoPokemon({ ...s, dono: s.dono });
  };
  arte.onclick = abrirFicha;
  arte.style.cursor = 'pointer';
  el.querySelector('.cm-ficha').onclick = abrirFicha;

  if (aVenda && !s.meu) {
    const bt = document.createElement('button');
    bt.className = 'cm-btn comprar';
    bt.textContent = t('cm.comprar');
    aplicarRetencaoCompra(bt, s.anuncio, () => confirmarCompraAnuncio({
      pk: { potencia: 5, ...s },
      nome: s.nome ?? '',
      preco: s.anuncio.preco,
      moeda: s.anuncio.moeda,
      vendedor: s.dono,
      aoConfirmar: () => {
        enviar({
          t: 'market.comprar',
          id: s.anuncio.id,
          qtd: 1,
          preco: s.anuncio.preco,
          moeda: s.anuncio.moeda,
        });
        setTimeout(pedirP5s, 1000);
      },
    }));
    el.querySelector('.cm-botoes').appendChild(bt);
  }
  return el;
}

function pintarPaginasP5s() {
  const host = $('#p5l-paginas');
  if (!host) return;
  const d = p5sEstado.dados;
  const porPagina = d?.porPagina ?? 40;
  const paginas = Math.max(1, Math.ceil((d?.total ?? 0) / porPagina));
  const atual = p5sEstado.pagina;
  if (paginas <= 1) return void (host.innerHTML = '');

  host.innerHTML = `
    <button class="cm-pag" ${atual <= 0 ? 'disabled' : ''} data-ir="${atual - 1}">‹</button>
    <span>${t('cm.paginaDe', { a: atual + 1, b: paginas })}</span>
    <button class="cm-pag" ${atual + 1 >= paginas ? 'disabled' : ''} data-ir="${atual + 1}">›</button>`;
  host.onclick = (ev) => {
    const b = ev.target.closest('[data-ir]');
    if (!b || b.disabled) return;
    p5sEstado.pagina = Number(b.dataset.ir);
    pedirP5s();
  };
}

// ------------------------------------------------------------------- ficha
//
// Tudo que se sabe sobre um pokémon, numa tela só. Dois donos, o mesmo modal:
//
//   `abrirFichaDaEspecie(pokeId)`  o que a Pokédex sabe — stats-base, drops com a
//                                  porcentagem de cada um, chance de captura por pokébola,
//                                  se existe forma shiny e o que cada potência faria.
//   `abrirFichaDoPokemon(pk)`      um bicho CONCRETO — nível, XP para o próximo, a potência
//                                  que saiu na captura dele e os stats que ele tem de fato.
//                                  É o que a vitrine do Mercado abre ao clicar num anúncio.
//
// **Nada aqui é chutado.** As constantes de captura, a tabela de potência e a chance de shiny
// por tier vêm todas do `welcome` — o mesmo lugar de onde o servidor as lê. A única coisa
// duplicada é o FORMATO da conta de captura, e ela está marcada como espelho logo abaixo.

/**
 * Chance de captura por arremesso. **Espelho de `chanceCaptura` em `sim.mjs`** — se a fórmula
 * mudar lá, muda aqui.
 *
 * Os NÚMEROS (base, piso, teto) não estão duplicados: vêm em `estado.captura`, do welcome.
 * O que se repete é só o desenho da conta, e ela vive aqui porque a tabela da ficha mostra
 * dez células por espécie e perguntar ao servidor por cada uma seria uma ida de rede para
 * desenhar um número que não muda nunca.
 */
function chanceDeCaptura(especie, catchRate, hpFrac = 0) {
  const c = estado.captura ?? { base: 0.0075, piso: 0.003, teto: 0.1, raridadeDiv: 17, precoSemPreco: 6.5e9 };
  if (catchRate >= 255) return 1;
  // `priceNpc` zero é "não está à venda" (os lendários, o Ditto e o Unown), não "barato" —
  // ver `PRECO_MAIS_RARO` no servidor.
  const preco = especie.priceNpc > 0 ? especie.priceNpc : c.precoSemPreco;
  const raridade = Math.log10(Math.max(100, preco)) - 1;
  const fator = 1 + raridade ** 3 / (c.raridadeDiv ?? 17);
  return Math.max(c.piso, Math.min(c.teto, c.base * (catchRate / fator) * (1.4 - hpFrac)));
}

/**
 * "12,4%" — porcentagem com as casas que o número merece.
 *
 * A escada existe por causa da potência 5: ela é 0,005%, e com duas casas fixas virava
 * "0,01%" — o dobro do valor real, justamente no número mais raro da tabela.
 */
const pct = (v) => {
  const casas = v >= 0.1 ? 1 : v >= 0.001 ? 2 : v >= 0.00001 ? 4 : 6;
  return `${(v * 100).toFixed(casas).replace('.', ',')}%`;
};

/** "1 em 24.000" — a leitura que se entende de uma chance minúscula. */
const umEm = (chance) => (chance > 0 ? t('dex.umEm', { n: num(Math.round(1 / chance)) }) : '—');

/** Os seis stats na ordem em que o jogo os mostra, com o rótulo curto de cada um. */
const STATS_ORDEM = [
  ['hp', 'HP', 'baseHp'],
  ['atk', 'ATK', 'baseAtk'],
  ['def', 'DEF', 'baseDef'],
  ['spAtk', 'SP.ATK', 'baseSpAtk'],
  ['spDef', 'SP.DEF', 'baseSpDef'],
  ['speed', 'SPD', 'baseSpeed'],
];

/**
 * O IV de referência da ficha de ESPÉCIE.
 *
 * A espécie não tem IV — cada bicho sorteia o dele, de 1 a 32 por stat. Para a tabela de
 * potência valer alguma coisa é preciso fixar um ponto de comparação, e 16 é o meio exato
 * da faixa. A qualidade de referência é 1,00 pelo mesmo motivo, e com ela os expoentes por
 * stat somem da conta (1 elevado a qualquer coisa é 1) — é por isso que a tabela de
 * expoentes não precisa trafegar até aqui.
 */
const IV_REFERENCIA = 16;

/** Stat de referência: a mesma conta do servidor, com IV 16 e qualidade 1. */
const statDeReferencia = (base, nivel, mult) =>
  Math.round((base + 2 * IV_REFERENCIA) * (nivel / 100) * mult);

/** O poder da espécie num nível, para uma potência (e opcionalmente shiny). */
function poderDeReferencia(especie, nivel, mult) {
  return STATS_ORDEM.reduce((s, [, , campo]) => s + statDeReferencia(especie[campo], nivel, mult), 0);
}

/** O multiplicador de uma potência, da tabela que veio do servidor. */
const multDaPotencia = (n) => 1 + (estado.potencias.find((p) => p.n === n)?.bonus ?? 0);

/** As hunts em que a espécie aparece — "onde encontrar". */
const huntsComEspecie = (pokeId) => {
  if (isOutlandPokeId(pokeId)) {
    return estado.hunts.filter((h) => h.especies?.some((e) => e.pokeId === pokeId));
  }
  const dex = dexDoPokeId(pokeId);
  return estado.hunts.filter((h) =>
    h.especies?.some((e) => !isOutlandPokeId(e.pokeId) && dexDoPokeId(e.pokeId) === dex),
  );
};

/** itemId a partir do NOME, que é como o loot do catálogo referencia os itens. */
function itemPorNome(nome) {
  if (!estado.itensPorNome) {
    estado.itensPorNome = new Map([...estado.itens.values()].map((i) => [i.name.toLowerCase(), i]));
    const bandAid = estado.itensPorNome.get('band aid');
    if (bandAid) estado.itensPorNome.set('band-aid', bandAid);
  }
  const canon = resolverNomeItem(nome);
  return estado.itensPorNome.get(String(canon).toLowerCase())
    ?? estado.itensPorNome.get(String(nome).toLowerCase())
    ?? null;
}

/** Cabeçalho de uma seção da ficha. */
const fichaSecao = (titulo, corpo, extra = '') =>
  `<section class="fi-secao">
     <h3>${titulo}${extra ? ` <em>${extra}</em>` : ''}</h3>
     ${corpo}
   </section>`;

// ------------------------------------------------------------ tabela de captura

/**
 * A tabela de captura: uma linha por pokébola.
 *
 * A chance é sempre a do CORPO NO CHÃO, e não há coluna para o alvo de pé: o painel de
 * captura do palco só oferece os derrotados, então a outra coluna descrevia uma jogada que
 * a tela não deixa fazer. (A fórmula continua com o termo de HP — quem arremessa pela Bolsa,
 * no selvagem em combate, ainda leva a penalidade.)
 *
 * A coluna "derrotas" é 1/chance: como é UMA tentativa por corpo, ela é o número de bichos
 * que se precisa derrubar, na média, até um ficar na bola.
 */
function tabelaDeCaptura(especie) {
  const linhas = estado.catalogoBolas
    .map((b) => {
      const noChao = chanceDeCaptura(especie, b.catchRate);
      const custo = b.compravel && b.priceGold ? moeda(b.priceGold) : `<em>${t('dex.soDiamante')}</em>`;
      return `
        <tr>
          <td class="fi-bola"><span class="fi-bola-ico" data-bola="${b.id}"></span>${escapar(b.nome)}</td>
          <td>×${b.catchRate}</td>
          <td class="destaque">${pct(noChao)}</td>
          <td>${num(Math.ceil(1 / noChao))}</td>
          <td>${custo}</td>
        </tr>`;
    })
    .join('');

  return `
    <table class="fi-tabela">
      <thead><tr>
        <th>${t('dex.bola')}</th><th>${t('dex.eficiencia')}</th>
        <th>${t('dex.chanceCaptura')}</th>
        <th>${t('dex.derrotasMedia')}</th><th>${t('dex.preco')}</th>
      </tr></thead>
      <tbody>${linhas}</tbody>
    </table>
    <p class="fi-nota">${t('dex.notaCaptura')}</p>`;
}

/**
 * A segunda tabela: shiny.
 *
 * O brilho só rola na captura bem-sucedida — junto com qualidade, IV e potência. A coluna
 * composta mostra captura comum × chance shiny (1/24.000, ou 1/12.000 com Shiny Secret Lure).
 */
function tabelaDeCapturaShiny(especie, chanceCaptura) {
  const linhas = estado.catalogoBolas
    .map((b) => {
      const noChao = chanceDeCaptura(especie, b.catchRate);
      const junto = chanceCaptura * noChao;
      return `
        <tr>
          <td class="fi-bola"><span class="fi-bola-ico" data-bola="${b.id}"></span>${escapar(b.nome)}</td>
          <td>×${b.catchRate}</td>
          <td class="destaque">${pct(noChao)}</td>
          <td>${umEm(junto)}</td>
        </tr>`;
    })
    .join('');

  return `
    <table class="fi-tabela">
      <thead><tr>
        <th>${t('dex.bola')}</th><th>${t('dex.eficiencia')}</th>
        <th>${t('dex.chanceCaptura')}</th><th>${t('dex.encontrarECapturar')}</th>
      </tr></thead>
      <tbody>${linhas}</tbody>
    </table>
    <p class="fi-nota">${t('dex.notaShiny')}</p>`;
}

// ------------------------------------------------------------ peças das fichas
//
// As duas fichas (a da ESPÉCIE e a de um BICHO) são montadas com as mesmas peças: o HERÓI no topo
// (quem é, à esquerda; o pedestal com holofote, à direita — o mesmo da Calculadora), PLACAS para
// os números, CARTÕES para os assuntos, o HEXÁGONO dos stats, a CADEIA de evolução em cartões e a
// ESCADA das cinco potências. As tabelas que são mesmo tabela (captura, drops, golpes) continuam.

/** Uma PLACA de número: o rótulo miúdo em cima, o valor grande, o detalhe embaixo. */
const fiPlaca = (rotulo, valor, { sub = '', icone = '', classe = '', titulo = '' } = {}) => `
  <div class="fi-placa${classe ? ` ${classe}` : ''}"${titulo ? ` title="${escapar(titulo)}"` : ''}>
    <small>${icone ? dlgIcone(icone, 12) : ''}<span>${rotulo}</span></small>
    <b>${valor}</b>
    ${sub ? `<em>${sub}</em>` : ''}
  </div>`;

/** Um CARTÃO da ficha: o vão escuro com o título (e o ícone dele) em cima. */
const fiCartao = (titulo, corpo, { icone = '', extra = '', classe = '' } = {}) => `
  <section class="fi-cartao${classe ? ` ${classe}` : ''}">
    <h3 class="fi-cartao-tit">${icone ? dlgIcone(icone, 14) : ''}<span>${titulo}</span>${extra ? `<em>${extra}</em>` : ''}</h3>
    ${corpo}
  </section>`;

/** A ordem do HEXÁGONO, no sentido do relógio a partir do topo — a mesma dos jogos de pokémon. */
const ORDEM_RADAR = ['hp', 'atk', 'def', 'speed', 'spDef', 'spAtk'];

/**
 * O HEXÁGONO dos stats: um polígono por série, sobre os anéis de 25/50/75/100%. `series` é
 * `[{ valores: { hp, atk, … } de 0 a 1, classe }]`. É SVG puro e as cores moram no CSS — a forma
 * se lê de relance ("bate forte e é lento") onde seis barras pedem leitura linha a linha.
 */
function radarStats(series) {
  const R = 84;
  const ponto = (i, v) => {
    const ang = ((-90 + i * 60) * Math.PI) / 180;
    return [Math.cos(ang) * R * v, Math.sin(ang) * R * v];
  };
  const poligono = (f) => ORDEM_RADAR
    .map((k, i) => ponto(i, f(k)).map((n) => n.toFixed(1)).join(','))
    .join(' ');
  const aneis = [0.25, 0.5, 0.75, 1].map((v) => `<polygon class="fi-radar-anel" points="${poligono(() => v)}"/>`).join('');
  const eixos = ORDEM_RADAR.map((_, i) => {
    const [x, y] = ponto(i, 1);
    return `<line class="fi-radar-eixo" x1="0" y1="0" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>`;
  }).join('');
  const rotulos = ORDEM_RADAR.map((k, i) => {
    const [x, y] = ponto(i, 1.22);
    return `<text class="fi-radar-rot" x="${x.toFixed(1)}" y="${y.toFixed(1)}">${rotuloStat(k)}</text>`;
  }).join('');
  const formas = series.map((s) => `<polygon class="fi-radar-forma ${s.classe ?? ''}" points="${poligono(
    (k) => Math.max(0.04, Math.min(1, Number(s.valores?.[k]) || 0)),
  )}"/>`).join('');
  return `<svg class="fi-radar" viewBox="-124 -116 248 232" role="img" aria-label="${escapar(t('dex.radarAria'))}">
    ${aneis}${eixos}<g class="fi-radar-formas">${formas}</g>${rotulos}</svg>`;
}

/**
 * A espécie que EVOLUI PARA esta, quando há — a ficha da Ivysaur mostra a Bulbasaur antes dela.
 * Entre clones do catálogo (Orre, espelho) fica a de menor pokeId com arte: é a nacional.
 */
function antecessorDe(especie) {
  if (!especie) return null;
  let melhor = null;
  for (const x of estado.especies.values()) {
    if (x.pokeId === especie.pokeId || (melhor && x.pokeId >= melhor.pokeId)) continue;
    if (!temSpriteJogo(x)) continue;
    if (destinosDeEvolucao(x, (id) => estado.especies.get(id)).some((d) => d.pokeId === especie.pokeId)) melhor = x;
  }
  return melhor;
}

/**
 * A CADEIA DE EVOLUÇÃO em cartões: quem vem antes, a espécie desta ficha (acesa) e para onde ela
 * vai — cada destino com o nível e, quando é por destino, a pedra. A pedra única da família vai na
 * seta. Os cartões das outras espécies são `fi-evo-link`: o mesmo clique da linha antiga, que troca
 * a ficha pela daquela espécie. Destino sem arte aparece apagado, com o porquê.
 *
 * `destinos`: `[{ pokeId, nome, nivel, temArte, looktype, pedra }]`; `mega`: `{ pokeId, nome, pedra }`.
 */
function cadeiaEvolucaoHtml({ antes = null, atual, destinos = [], pedraUnica = null, mega = null }) {
  const arte = (lt, comum, px = 46) => (lt ? dlgArteLt(lt, px, comum) : `<span class="fi-cadeia-vazio">?</span>`);
  const no = ({ pokeId, nome, lt, comum, sub = '', classe = '', link = true }) => {
    const miolo = `
      <span class="fi-cadeia-arte">${arte(lt, comum)}</span>
      <b class="fi-cadeia-nome">${escapar(nome)}</b>
      ${sub ? `<em class="fi-cadeia-sub">${sub}</em>` : ''}`;
    return link
      ? `<button type="button" class="fi-evo-link fi-cadeia-no${classe ? ` ${classe}` : ''}" data-especie="${pokeId}" title="${escapar(t('dex.verFichaDe', { nome }))}">${miolo}</button>`
      : `<div class="fi-cadeia-no${classe ? ` ${classe}` : ''}">${miolo}</div>`;
  };
  const seta = (rotulo = '') => `
    <span class="fi-cadeia-seta" aria-hidden="true">
      <span class="dlg-seta-divisas"><i></i><i></i><i></i></span>
      ${rotulo ? `<span class="fi-cadeia-seta-rot">${rotulo}</span>` : ''}
    </span>`;
  const partes = [];
  if (antes) {
    partes.push(no({ pokeId: antes.pokeId, nome: antes.name, lt: antes.looktype, comum: antes.looktype, sub: `#${num(dexExibicao(antes.pokeId))}`, classe: 'antes' }));
    partes.push(seta());
  }
  partes.push(no({ ...atual, classe: 'atual', link: false }));
  if (destinos.length) {
    partes.push(seta(pedraUnica ? htmlPedraEvolucao(pedraUnica) : ''));
    partes.push(`<div class="fi-cadeia-destinos${destinos.length > 2 ? ' muitos' : ''}">${destinos.map((d) => no({
      pokeId: d.pokeId,
      nome: d.nome,
      lt: d.temArte ? d.looktype : null,
      comum: d.looktype,
      sub: d.temArte
        ? `${escapar(t('dex.nvArea', { n: num(d.nivel) }))}${d.pedra ? ` · ${htmlPedraEvolucao(d.pedra)}` : ''}`
        : escapar(t('dex.semSprite')),
      classe: d.temArte ? 'destino' : 'destino sem-arte',
      link: d.temArte,
    })).join('')}</div>`);
  }
  const linhaMega = mega
    ? `<div class="fi-cadeia-mega">
        <span class="fi-cadeia-mega-rot">${dlgIcone('raio', 14)}${escapar(t('dex.megaEvolucao'))}</span>
        ${no({
          pokeId: mega.pokeId,
          nome: mega.nome,
          lt: estado.especies.get(mega.pokeId)?.looktype ?? null,
          comum: estado.especies.get(mega.pokeId)?.looktype ?? null,
          sub: htmlPedraEvolucao(mega.pedra),
          classe: 'mega',
        })}
      </div>`
    : '';
  // Com mais de dois destinos (a Eevee tem oito) a cadeia vira COLUNA, com a seta apontando para
  // baixo: em linha, a seta apontava para a direita e os destinos caíam na fileira de baixo.
  return `<div class="fi-cadeia${destinos.length > 2 ? ' vertical' : ''}">${partes.join('')}</div>${linhaMega}`;
}

/**
 * A ESCADA DAS CINCO POTÊNCIAS em degraus: a chance de nascer em cada uma, o bônus e o ⚔ que ela
 * daria — na ficha do bicho com a DELE acesa ("que sorte ele deu"), na da espécie com a coluna do
 * shiny quando há forma shiny. Os degraus crescem com a potência, na cor da escada de raridade.
 */
function escadaPotenciasHtml({ especie, nivel, aqui = null, shiny = false, comShiny = false }) {
  const mults = estado.potencias.map((p) => 1 + p.bonus);
  const maior = Math.max(...mults, 1);
  return `<ol class="fi-potescada">${estado.potencias.map((p, i) => {
    const mult = (1 + p.bonus) * (shiny ? estado.multShinyStats : 1);
    const poder = especie ? num(poderDeReferencia(especie, nivel, mult)) : '—';
    const poderSh = comShiny && especie ? num(poderDeReferencia(especie, nivel, mult * estado.multShinyStats)) : null;
    const alt = 34 + Math.round((mults[i] / maior) * 46);
    return `
      <li class="fi-potdegrau p${p.n}${aqui === p.n ? ' aqui' : ''}">
        ${aqui === p.n ? `<span class="fi-potdegrau-selo">${escapar(t('dex.potenciaAqui'))}</span>` : ''}
        <span class="fi-potdegrau-barra" style="height:${alt}px"><b>P${p.n}</b></span>
        <span class="fi-potdegrau-chance">${pct(p.chance / 100)}</span>
        <span class="fi-potdegrau-bonus">${p.bonus ? `+${Math.round(p.bonus * 100)}%` : '—'}</span>
        <span class="fi-potdegrau-poder">⚔ ${poder}</span>
        ${poderSh ? `<span class="fi-potdegrau-poder sh">✨ ⚔ ${poderSh}</span>` : ''}
      </li>`;
  }).join('')}</ol>`;
}

/** A placa da nota embaixo do pedestal da ficha: o número (que conta até ele ao abrir) e a escada. */
function placaNotaFicha(nf) {
  if (!nf) return '';
  return `
    <div class="fi-palco-placa">
      <div class="calc-nota ${nf.faixa}">
        <span class="calc-nota-valor"><b class="fi-nota-num" data-nota="${nf.nota}">${notaEmTexto(nf.nota)}</b><span class="calc-nota-de">${t('calc.de10')}</span></span>
        <span class="calc-nota-rotulo">${escapar(t(`calc.faixa.${nf.faixa}`))}</span>
      </div>
      <div class="calc-escada-host">${escadaDaNota(nf.nota)}</div>
    </div>`;
}

/**
 * Liga o que a ficha nova tem de vivo: os sprites de marcação (cadeia, pedestal), a nota contando
 * de zero até a dela e o hexágono abrindo. Chamado pelo `aoMontar` das duas fichas.
 */
function ligarFichaNova(corpo) {
  hidratarDialogo(corpo);
  const elNota = corpo.querySelector('.fi-nota-num[data-nota]');
  if (elNota) {
    elNota.dataset.valor = '0';
    elNota.textContent = notaEmTexto(0);
    requestAnimationFrame(() => animarNota(elNota, Number(elNota.dataset.nota), 900));
  }
}

// ------------------------------------------------------------ ficha da ESPÉCIE

/**
 * A linha "Nível ao capturar" da ficha.
 *
 * Quando o teto corta, o número do teto vem em destaque e o nível da hunt fica ao lado,
 * riscado — é a forma mais curta de explicar as duas metades da regra (ele LUTA em 2.000 e
 * ENTRA em 100) sem um parágrafo de texto. Quando não corta, a linha diz o nível de sempre e
 * não chama atenção nenhuma, que é o caso de toda Kanto.
 */
/**
 * O MENOR degrau entre as hunts em que a espécie aparece — o nível em que o jogador de fato a
 * encontra pela primeira vez, e o mesmo número que `NIVEIS_POR_ONDE_O_ALVO_APARECE` usa para
 * dizer em que nível a pré-evolução vira ela. Era `Math.max`, e as dezoito espécies que moram
 * em duas hunts de eras diferentes contavam duas histórias: a lista mostrava "Carracosta —
 * Nv 1.125" enquanto a ficha dele dizia 6.950 e o Tirtouga prometia evoluir nesse 6.950.
 *
 * Sem hunt nenhuma (variante de Outland, lendário fora do mapa) sobra o `huntLevel` do catálogo.
 */
function nivelDeHuntDaEspecie(especie) {
  const hunts = especie ? huntsComEspecie(especie.pokeId) : [];
  return hunts.length
    ? Math.min(...hunts.map((h) => h.nivel))
    : Math.max(1, especie?.huntLevel ?? 5);
}

function textoNivelCaptura(especie, nivelRef) {
  const teto = especie?.tetoCaptura ?? TETO_CAPTURA_MAX;
  const cap = nivelDeCaptura(nivelRef, teto);
  if (cap >= nivelRef) return num(cap);
  // `<span>`, e não `<b>`: `fichaLinha` já embrulha o valor inteiro num `<b>`. Aqui só falta cor.
  return `<span class="fi-teto">${num(cap)}</span><s class="fi-teto-antes">${num(nivelRef)}</s>`;
}

/**
 * O painel de "boss de evento" — o primeiro bloco da ficha de quem ainda não tem arena.
 *
 * Vem antes dos stats de propósito: é a resposta para a pergunta que o selo BOSS acabou de
 * criar ("então onde eu luto com ele?"), e ela precisa chegar antes de o jogador descer a
 * ficha atrás de uma tabela de captura que não está mais lá.
 */
function avisoBossDeEvento() {
  return `
    <section class="fi-secao fi-boss-evento">
      <h3>${escapar(t('dex.bossEvento'))}</h3>
      <p class="fi-boss-evento-txt">${t('dex.bossEventoAviso')}</p>
    </section>`;
}

/**
 * O painel ROXO do MysticTicket — o que substituiu o "em breve" na ficha de todo boss.
 *
 * Até o ticket existir, a ficha de um boss era um beco: nem hunt, nem bola, nem drop, e o
 * painel amarelo dizia com todas as letras que ele "não tem chance de captura". Hoje tem — a
 * mesma para os dois lados do catálogo, o boss que já tem arena e o que ainda vai ter —, e o
 * que falta na ficha é justamente o número que decide se o jogador guarda ou vende o ticket:
 * a chance de sair ESTE lendário entre os do sorteio, e a chance de a bola segurar.
 *
 * Roxo porque é a cor da Arena Mística (`rc-mistico`): a ficha e a sala têm de ler como a
 * mesma coisa. Os números saem todos de `shared/mistico.mjs`, que o servidor também importa.
 *
 * @param bossCat     a entrada do catálogo de bosses, quando ele já tem arena
 * @param bossEvento  `true` para o boss cuja arena ainda não abriu
 */
function secaoMisticaDaFicha(bossCat, bossEvento) {
  const { n } = poolMistico();
  const chanceSorteio = n > 0 ? 1 / n : 0;
  const tickets = estado.eu?.items?.[MYSTIC_TICKET_ID] ?? 0;

  // De onde vem o ticket. Com arena, a ficha diz a chance DESTE boss (é a mesma linha que a
  // tabela de drops logo abaixo mostra); sem arena, a regra geral — qualquer boss, e a chance
  // sobe com o nível dele.
  const chanceTicket = bossCat?.dropsDetalhe?.find((d) => d.itemId === MYSTIC_TICKET_ID)?.chance ?? null;
  // "0,0005%", e não "0,000500%": nessa faixa o `pct` geral abre seis casas, e os três zeros à
  // direita fazem o número parecer outro na leitura rápida. Mesmo corte da aba Bosses.
  const pctEnxuto = (v) => pct(v).replace(/(,\d*?)0+%$/, '$1%').replace(/,%$/, '%');
  const comoObter = chanceTicket != null
    ? t('dex.mstDesteBoss', { pct: pctEnxuto(chanceTicket) })
    : t('dex.mstDeQualquerBoss');

  const linhasBola = BOLAS_MISTICAS_DA_MELHOR.slice().reverse().map((id) => `
    <tr>
      <td class="fi-bola"><span class="fi-bola-ico" data-bola="${id}"></span>${escapar(nomeDaBola(id))}</td>
      <td class="destaque">${pct(chanceCapturaMistica(id))}</td>
      <td>${pct(chanceCapturaMistica(id, 2))}</td>
    </tr>`).join('');

  return `
    <section class="fi-secao fi-mistico">
      <h3>${escapar(t('dex.mstTitulo'))}</h3>
      <p class="fi-mistico-txt">${t('dex.mstTexto', { nivel: num(NIVEL_LENDARIO_MISTICO) })}</p>
      ${bossEvento ? `<p class="fi-mistico-txt">${t('dex.mstSemArena')}</p>` : ''}
      <div class="fi-linhas">
        ${fichaLinha(t('dex.mstComoObter'), comoObter)}
        ${fichaLinha(t('dex.mstSorteio'), `${umEm(chanceSorteio)} · ${pct(chanceSorteio)} <em class="fi-mistico-pool">${t('dex.mstPool', { n: num(n) })}</em>`)}
        ${fichaLinha(t('dex.mstNivel'), num(NIVEL_LENDARIO_MISTICO))}
        ${fichaLinha(t('dex.mstTentativas'), t('dex.mstUmaBola'))}
        ${fichaLinha(t('dex.mstVoceTem'), `<span class="fi-mistico-tem"><span class="fi-drop-ico" data-item="${MYSTIC_TICKET_ID}"></span>${num(tickets)}</span>`)}
      </div>
      <table class="fi-tabela">
        <thead><tr>
          <th>${t('dex.bola')}</th><th>${t('dex.chanceCaptura')}</th><th>${t('dex.mstComBoost')}</th>
        </tr></thead>
        <tbody>${linhasBola}</tbody>
      </table>
      <p class="fi-nota">${t('dex.mstNota')}</p>
      ${tickets > 0 ? `<button type="button" class="fi-hunt fi-mistico-cta">${escapar(t('mistico.usar'))}</button>` : ''}
    </section>`;
}

function corpoDaEspecie(especie) {
  const pokeId = especie.pokeId;
  const bossCat = bossDaEspecie(pokeId);
  // O boss de evento (Mewtwo, Lugia, Celebi…) ainda não tem arena. A ficha dele é a de boss —
  // sem captura, sem drop, sem shiny, sem "onde encontrar" —, só que sem o "Ir para Boss",
  // porque não há para onde ir. `ehBoss` é o que apaga as seções nos dois casos.
  const bossEvento = ehBossDeEvento(pokeId);
  const ehBoss = !!bossCat || bossEvento;
  // O MYSTICTICKET é o que tirou o boss do beco. Ele não aparece em hunt nenhuma e continua
  // sem tabela de pokébola — a da hunt sai do preço da espécie e aqui não vale —, mas a Arena
  // Mística o sorteia como qualquer outro Lendário ou Mítico, e isso faz dele um pokémon
  // CAPTURÁVEL: o contador de capturados, o shiny e o painel roxo voltam para a ficha.
  const noMistico = ehBoss && noSorteioMistico(pokeId);
  // A MEGA não se captura — ela se fabrica com a Mega Stone. Tudo o que só faz sentido para
  // quem leva pokébola (as duas tabelas de chance, o "onde encontrar") sai da ficha, como já
  // sai na do boss. Mostrar "Beast Ball 2,77%" num Mega Gengar é convidar o jogador a gastar
  // bola num bicho que nunca vai aparecer numa hunt. Ver `shared/megas.mjs`.
  const ehMega = isMegaPokeId(pokeId);
  const semCaptura = ehBoss || ehMega;
  // Quem tem contador de capturados e seção de shiny: todo mundo menos o boss que a arena não
  // sorteia (o sem sprite) e a mega, que se fabrica.
  const capturavel = !ehBoss || noMistico;
  const dexN = dexExibicao(pokeId);
  const dex = entradaPokedex(pokeId);
  const hunts = huntsComEspecie(pokeId);
  const golpes = golpesDaFicha(especie);
  const nivelRef = nivelDeHuntDaEspecie(especie);
  const outlandVariante = isOutlandPokeId(pokeId);
  const temShiny = !outlandVariante && temFormaShinyFicha(especie);
  const chanceShiny = temShiny ? Number(estado.chanceShiny) : 0;

  // ---- stats-base, com barra proporcional ao maior stat do catálogo (255)
  const barras = STATS_ORDEM.map(
    ([, rotulo, campo]) => `
      <div class="fi-stat">
        <span class="fi-stat-nome">${rotulo}</span>
        <span class="fi-stat-barra"><i style="width:${Math.min(100, (especie[campo] / 200) * 100)}%"></i></span>
        <b class="fi-stat-num">${num(especie[campo])}</b>
      </div>`,
  ).join('');

  // ---- drops. `chance` do catálogo é percentual × 1000 (ver MECANICAS §6).
  const drops = listaDropsEspecie(especie).map((l) => ({
    name: l.name,
    chance: l.pct * 1000,
    pctReal: l.pct,
    minCount: l.minCount,
    maxCount: l.maxCount,
    item: itemPorNome(l.name),
    rotulo: (() => {
      const item = itemPorNome(l.name);
      return item ? nomeItem(item, item.name) : l.name;
    })(),
  }));

  const linhasDrop = drops.length
    ? drops
        .map(
          (d) => `
          <tr>
            <td class="fi-drop"><span class="fi-drop-ico" data-item="${d.item?.id ?? ''}"></span>${escapar(d.rotulo)}</td>
            <td class="fi-num ${d.pctReal >= 50 ? 'destaque' : ''}">${d.pctReal > 0 ? pct(d.pctReal / 100) : t('dex.nuncaCai')}</td>
            <td class="fi-num">${d.minCount === d.maxCount ? num(d.minCount) : `${num(d.minCount)}–${num(d.maxCount)}`}</td>
            <td class="fi-num">${ehPedraEvolucao(d.item) ? escapar(t('dex.vendaMercado')) : (d.item?.npcPrice ? moeda(d.item.npcPrice) : '—')}</td>
          </tr>`,
        )
        .join('')
    : '';

  const emOutland = hunts.some((h) => h.area === 'outland');
  // Mesma regra da ficha da área: a chance mostrada é a da Outland escolhida.
  const multOutland = emOutland ? multOutlandUi() : 1;
  const rotuloOutland = emOutland ? rotuloOutlandUi() : t('dex.dropOutland');
  const chanceBoss = (estado.chanceBossToken ?? 0.0005) * multOutland;
  const chanceFragChave = (estado.casas?.fragmento?.chanceDrop ?? 0.000005) * multOutland;
  const chanceFragShiny = (estado.shinyStone?.chanceDrop ?? 0.000005) * multOutland;
  const fragChaveId = estado.casas?.fragmento?.itemId ?? FRAGMENTO_CHAVE_ID;
  const fragShinyId = estado.shinyStone?.fragmentoId ?? FRAGMENTO_SHINY_ID;
  const chanceFragBicicleta = (estado.bicicletas?.fragmento?.chanceDrop ?? 0.000005) * multOutland;
  const fragBicicletaId = estado.bicicletas?.fragmento?.itemId ?? FRAGMENTO_BICICLETA_ID;
  const bossItem = itemPorNome('Bronze Boss Token');
  const linhaDropOutland = (itemId, nomeEn, chance) => {
    const nome = nomeItem(itemId, nomeEn);
    return `
          <tr class="fi-drop-global">
            <td class="fi-drop"><span class="fi-drop-ico" data-item="${itemId}"></span>${escapar(nome)} <em>${escapar(rotuloOutland)}</em></td>
            <td class="fi-num">${pct(chance)} · ${umEm(chance)}</td>
            <td class="fi-num">1</td>
            <td class="fi-num">—</td>
          </tr>`;
  };
  const linhasDropOutland = emOutland && !ehBoss
    ? linhaDropOutland(fragChaveId, 'Key Fragment', chanceFragChave)
      + linhaDropOutland(fragShinyId, 'Shiny Stone Fragment', chanceFragShiny)
      + linhaDropOutland(fragBicicletaId, 'Bicycle Fragment', chanceFragBicicleta)
      + linhaDropOutland(bossItem?.id ?? BOSS_TOKEN_ID, bossItem?.name ?? 'Bronze Boss Token', chanceBoss)
    : '';

  let corpoDrops;
  if (bossCat) {
    const det = bossCat.dropsDetalhe ?? [];
    corpoDrops = det.length
      ? det.map((d) => {
          const item = d.itemId ? estado.itens.get(d.itemId) : itemPorNome(d.nome);
          const rotulo = item ? nomeItem(item, d.nome) : d.nome;
          const ch = d.chance ?? bossCat.chanceTm ?? 0;
          return `
          <tr>
            <td class="fi-drop"><span class="fi-drop-ico" data-item="${item?.id ?? d.itemId ?? ''}"></span>${escapar(rotulo)}</td>
            <td class="fi-num destaque">${pct(ch)} · ${umEm(ch)}</td>
            <td class="fi-num">1</td>
            <td class="fi-num">—</td>
          </tr>`;
        }).join('')
      : `<tr><td colspan="4" class="fi-vazio">${t('dex.semDrops')}</td></tr>`;
  } else {
    corpoDrops = linhasDrop || linhasDropOutland
      ? `${linhasDrop}${linhasDropOutland}`
      : `<tr><td colspan="4" class="fi-vazio">${t('dex.semDrops')}</td></tr>`;
  }

  const botaoIrBoss = bossCat
    ? `<button type="button" class="fi-hunt fi-boss-cta" data-boss="${escapar(bossCat.key)}">
         ${escapar(t('dex.irBoss'))} <em>${t('dex.nvArea', { n: num(bossCat.level ?? 0) })}</em>
       </button>`
    : '';

  // ---- onde encontrar
  const ondeAchar = hunts.length
      ? hunts
          .map(
            (h) =>
              `<button class="fi-hunt${estado.eu.level >= h.nivel ? '' : ' travada'}" data-hunt="${h.slug}">
                 ${escapar(h.nome)} <em>${t('dex.nvArea', { n: num(h.nivel) })}</em>
               </button>`,
          )
          .join('')
      : `<span class="fi-vazio">${t('dex.semHunt')}</span>`;

  const pedra = pedraDaEspecie(especie);
  // Cada destino vira uma linha, e o nome é CLICÁVEL: abre a ficha dele.
  //
  // O link é indispensável nas cadeias que atravessam geração (Sneasel → Weavile, Ursaring →
  // Ursaluna) — o alvo mora numa região que o jogador talvez nem tenha aberto, e ler "vira
  // Weavile no Nv 1.500" sem poder conferir quem é Weavile é a metade inútil do aviso. E as
  // linhas são VÁRIAS porque a cadeia pode abrir: a Pokédex do Eevee que só falasse do
  // Vaporeon estaria escondendo sete pokémon que o jogo tem.
  //
  // Destino sem arte aparece assim mesmo, marcado — esconder faria a Pokédex mentir por
  // omissão sobre uma evolução que existe e que um dia vai abrir.
  const destinosDex = destinosDeEvolucao(especie, (id) => estado.especies.get(id));
  const pedrasDex = destinosDex.map((d) => pedraDaEspecie(especie, d.especie));
  // Uma pedra por destino (o Eevee) não cabe na linha única "Pedra: X" — ela vai para dentro de
  // cada linha de evolução. Quando a família toda usa a mesma, a linha única continua melhor.
  const pedraPorDestino = new Set(pedrasDex.map((x) => x?.itemId)).size > 1;
  // A MEGA não é uma evolução por nível, então ela ganha linha PRÓPRIA em vez de entrar na
  // lista acima: "evolui para Mega Venusaur no Nv 0" seria falso nas duas metades — não há
  // nível que a dispare, e o que a dispara (a Venusaurite) não aparece em lugar nenhum da
  // linha de evolução comum.
  const megaFicha = megaDaFicha(especie);
  const tiposEspecie = [especie.type1, especie.type2].filter(Boolean);
  const { fracos: fracoContra } = tiposEspecie.length
    ? matchupDefensivo(tiposEspecie, estado.tabelaTipos)
    : { fracos: [] };
  const { fortes: forteContra } = tiposEspecie.length
    ? matchupTiposHunt(tiposEspecie, estado.tabelaTipos)
    : { fortes: [] };

  // ---- o HERÓI: quem é (à esquerda) e a arte nos pedestais (à direita). O holofote da forma
  // comum fica DOURADO quando a espécie já foi capturada — o ouro do jogo é "o que já é seu"
  // (DESIGN.md §1) —, e o da forma shiny acende em ouro com as faíscas.
  const capturado = capturavel && (dex.c ?? 0) > 0;
  const comPalcoShiny = temShiny && capturavel;
  const tags = `${ehBoss ? ` <span class="fi-tag-boss">BOSS</span>` : ''}${
    // O selo ao lado do BOSS diz como se chega nele. Era um "EM BREVE" dourado, de quando
    // a única resposta possível era "espere o evento"; hoje a resposta é o MysticTicket, e
    // ela vale para TODO boss — o que já tem arena também só se captura por ele. O dourado
    // fica de reserva para o boss que a arena não sorteia (o que ainda não tem sprite).
    noMistico
      ? ` <span class="fi-tag-mistico" title="${escapar(t('dex.mstTitulo'))}">${escapar(t('dex.mstTag'))}</span>`
      : bossEvento
        ? ` <span class="fi-tag-evento">${escapar(t('dex.bossEventoTag'))}</span>`
        : ''
  }`;
  const contadores = `
    <div class="fi-placas fi-placas-dex">
      ${fiPlaca(t('dex.derrotados'), num(dex.k ?? 0), { icone: 'espadas' })}
      ${capturavel ? fiPlaca(t('dex.capturados'), num(dex.c ?? 0), { icone: 'check', classe: capturado ? 'ouro' : '' }) : ''}
      ${comPalcoShiny
        ? fiPlaca(t('dex.shinysVistos'), num(dex.sv ?? 0), { classe: 'shiny' })
          + fiPlaca(t('dex.shinysCapturados'), num(dex.sc ?? 0), { classe: 'shiny' })
        : ''}
    </div>`;

  // ---- o RESUMO em placas — as linhas de "coisa: valor" de antes. A MEGA não aparece em hunt
  // nem sai de pokébola: ela se FABRICA, e as duas placas que só fazem sentido para quem é caçado
  // dão lugar a uma que diz de onde ela vem. O XP e o valor de NPC ficam: os dois valem.
  const resumo = bossCat
    ? fiPlaca(t('dex.nivelBossFight'), num(bossCat.level ?? 0), { icone: 'coroa' })
    : bossEvento
      ? fiPlaca(t('dex.nivelBossFight'), `<span class="fi-a-definir">${escapar(t('dex.aDefinir'))}</span>`, { icone: 'coroa' })
      : ehMega
        ? `${fiPlaca(t('dex.comoObter'), t('dex.megaComoObter'), { icone: 'raio', classe: 'largo texto' })}
           ${fiPlaca(t('dex.xpPorDerrota'), num(xpDoNivel(nivelRef)), { icone: 'estrela' })}
           ${fiPlaca(t('dex.valorNpc'), moeda(especie.sellValue ?? 0), { icone: 'moedas' })}`
        : `${fiPlaca(t('dex.nivelHunt'), num(nivelRef), { icone: 'bandeira' })}
           ${fiPlaca(t('dex.nivelCaptura'), textoNivelCaptura(especie, nivelRef), { icone: 'subir' })}
           ${fiPlaca(t('dex.xpPorDerrota'), num(xpDoNivel(nivelRef)), { icone: 'estrela' })}
           ${fiPlaca(t('dex.valorNpc'), moeda(especie.sellValue ?? 0), { icone: 'moedas' })}`;

  // ---- a CADEIA DE EVOLUÇÃO em cartões. "Não evolui" ao lado de uma mega seria a ficha se
  // contradizendo — foi o que um jogador viu e reportou —, então ele só aparece sem as duas.
  const antes = antecessorDe(especie);
  const cadeia = destinosDex.length || megaFicha || antes
    ? fiCartao(t('dex.evolucao'), `
        ${cadeiaEvolucaoHtml({
          antes,
          atual: { pokeId, nome: especie.name, lt: especie.looktype, comum: especie.looktype, sub: `#${num(dexN)}` },
          destinos: destinosDex.map((d, i) => ({
            pokeId: d.pokeId,
            nome: d.especie.name,
            nivel: d.nivel,
            temArte: d.temArte,
            looktype: d.especie.looktype,
            pedra: pedraPorDestino ? pedrasDex[i] : null,
          })),
          pedraUnica: pedraPorDestino ? null : pedra,
          mega: megaFicha,
        })}
        ${!destinosDex.length && !megaFicha ? `<p class="fi-nota">${t('dex.naoEvolui')}</p>` : ''}`, { icone: 'subir' })
    : '';

  const matchup = tiposEspecie.length
    ? fiCartao(t('dex.matchupTitulo'), `
        <div class="fi-matchup">
          <div class="fi-matchup-linha">
            <b>${t('dex.forteContra')}</b>
            ${forteContra.length ? blocoTiposAnalyser(forteContra, false, true) : `<span class="fi-vazio">${t('dex.semMatchup')}</span>`}
          </div>
          <div class="fi-matchup-linha">
            <b>${t('dex.fracoContra')}</b>
            ${fracoContra.length ? blocoTiposAnalyser(fracoContra, true) : `<span class="fi-vazio">${t('dex.semMatchup')}</span>`}
          </div>
        </div>`, { icone: 'escudo' })
    : '';

  // O hexágono da base, na régua de 200 das barras (o maior stat do catálogo passa disso, e
  // encosta no anel de fora).
  const radarBase = radarStats([{
    valores: Object.fromEntries(STATS_ORDEM.map(([k, , campo]) => [k, (Number(especie[campo]) || 0) / 200])),
    classe: 'base',
  }]);

  return `
    <div class="fi-heroi">
      <div class="fi-heroi-info">
        <span class="fi-dex-num">#${num(dexN)}</span>
        <div class="fi-nome">${escapar(especie.name)}${tags}</div>
        <div class="fi-tipos">${selosDeTipo(tiposEspecie)}</div>
        ${botaoIrBoss ? `<div class="fi-boss-topo">${botaoIrBoss}</div>` : ''}
        ${contadores}
      </div>
      <div class="fi-heroi-palcos${comPalcoShiny ? ' duplo' : ''}">
        ${holofoteHtml({
          id: 'fi-palco',
          tom: capturado ? 'ouro' : 'rx',
          classe: 'fi-palco',
          rodape: `<span class="fi-palco-rot">${escapar(t(comPalcoShiny ? 'dex.formaNormal' : 'dex.especie'))}</span>`,
        })}
        ${comPalcoShiny ? holofoteHtml({
          id: 'fi-palco-shiny',
          tom: 'shiny',
          classe: 'fi-palco hf-shiny',
          rodape: `<span class="fi-palco-rot sh">✨ ${escapar(t('dex.formaShinyRot'))}</span>`,
        }) : ''}
      </div>
    </div>

    <div class="fi-placas fi-resumo">${resumo}</div>

    ${noMistico ? secaoMisticaDaFicha(bossCat, bossEvento) : bossEvento ? avisoBossDeEvento() : ''}

    ${cadeia}

    <div class="fi-grade-2">
      ${fiCartao(t('dex.statsBase'), `<div class="fi-stats-duo">${radarBase}<div class="fi-stats">${barras}</div></div>
        <p class="fi-nota">${t('dex.statsNota')}</p>`, { icone: 'estrela' })}
      ${matchup}
    </div>

    ${fiCartao(
      t('dex.golpes'),
      golpes.length
        ? `<table class="fi-tabela">
             <thead><tr>
               <th>${t('dex.nomeGolpe')}</th><th>${t('dex.tipoGolpe')}</th>
               <th>${t('dex.categoria')}</th><th>${t('dex.danoBase')}</th><th>${t('dex.cooldown')}</th>
             </tr></thead>
             <tbody>${golpes.map((a) => `
               <tr>
                 <td>${escapar(a.name)}</td>
                 <td>${selosDeTipo([a.type])}</td>
                 <td>${a.category === 'SPECIAL' ? t('dex.catEspecial') : t('dex.catFisico')}</td>
                 <td class="fi-num destaque">${num(a.power)}</td>
                 <td class="fi-num">${(a.cooldownMs / 1000).toFixed(0)}s</td>
               </tr>`).join('')}</tbody>
           </table>
           <p class="fi-nota">${t('dex.notaGolpes')}</p>`
        : `<p class="fi-vazio">${t('dex.semGolpes')}</p>`,
      { icone: 'espadas' },
    )}

    ${!ehBoss ? fiCartao(
      t('dex.potencia'),
      // A coluna do poder SHINY só existe para as espécies que têm forma shiny. Nas outras ela
      // era uma promessa falsa: mostrava o triplo do poder para um brilho que não existe.
      `${escadaPotenciasHtml({ especie, nivel: nivelRef, comShiny: temShiny })}
       <p class="fi-nota">${t('dex.notaPotencia')}</p>`,
      { icone: 'raio', extra: t('dex.refNivel', { nv: num(nivelRef) }) },
    ) : ''}

    ${capturavel && !outlandVariante ? fiCartao(
      t('dex.shiny'),
      // A MEGA tem forma shiny, mas ela não vem de sorteio no encontro: vem do pokémon que
      // JÁ era shiny antes de megaevoluir, com a Shiny Mega Stone. As duas linhas de chance
      // são de captura e sairiam mentindo aqui; o bônus de stats fica, porque esse vale.
      //
      // O BOSS entrou aqui com o MysticTicket: o brilho dele rola no arremesso da arena, com a
      // chance cheia do jogo e o Shiny Secret Lure dobrando — os mesmos dois números abaixo.
      !temShiny
        ? `<p class="fi-vazio">${t('dex.semShiny')}</p>`
        : `<div class="fi-placas">
             ${ehMega
               ? fiPlaca(t('dex.comoObter'), t('dex.megaShinyComoObter'), { icone: 'brilho', classe: 'largo texto shiny' })
               : `${fiPlaca(t('dex.chanceEncontro'), umEm(chanceShiny), { icone: 'olho', sub: pct(chanceShiny), classe: 'shiny' })}
                  ${fiPlaca(t('dex.comIsca'), umEm(chanceShiny * 2), { icone: 'brilho', sub: pct(chanceShiny * 2), classe: 'shiny' })}`}
             ${fiPlaca(t('dex.bonusShiny'), `×${estado.multShinyStats}`, { icone: 'subir', sub: t('dex.emTodosStats'), classe: 'shiny' })}
           </div>`,
      { icone: 'brilho', classe: 'fi-cartao-shiny' },
    ) : ''}

    ${bossEvento ? '' : fiCartao(
      t('dex.drops'),
      `<table class="fi-tabela">
         <thead><tr>
           <th>${t('dex.item')}</th><th>${t('dex.chance')}</th>
           <th>${t('dex.quantidade')}</th><th>${t('dex.npcPaga')}</th>
         </tr></thead>
         <tbody>${corpoDrops}</tbody>
       </table>
       <p class="fi-nota">${bossCat ? t('dex.notaDropsBoss') : emOutland ? t('dex.notaDropsOutland') : t('dex.notaDrops')}</p>`,
      { icone: 'bolsa' },
    )}

    ${semCaptura ? '' : fiCartao(t('dex.captura'), tabelaDeCaptura(especie), { icone: 'check' })}

    ${!semCaptura && temShiny && !outlandVariante ? fiCartao(t('dex.capturaShiny'), tabelaDeCapturaShiny(especie, chanceShiny), { icone: 'brilho', classe: 'fi-cartao-shiny' }) : ''}

    ${semCaptura ? '' : fiCartao(t('dex.ondeAchar'), `<div class="fi-hunts">${ondeAchar}</div>`, { icone: 'bandeira' })}`;
}

// ----------------------------------------------------------- ficha de um BICHO

/**
 * A ficha de um pokémon CONCRETO: o do depot, o da equipe, o que está à venda na vitrine.
 *
 * Aceita tanto um pokémon do snapshot quanto a `ficha` congelada de um anúncio — os dois
 * carregam os mesmos campos. Anúncio aberto antes de a ficha detalhada existir não tem
 * `stats`, `ivs` nem `xp`, e as seções que dependem deles simplesmente não aparecem, em vez
 * de mostrarem zero (que seria mentira sobre o bicho que alguém vai comprar).
 */
function corpoDoPokemon(pk) {
  const especie = estado.especies.get(pk.speciesId) ?? estado.especiePorNome.get(pk.nome);
  const nivel = pk.level ?? 1;
  const potencia = Number(pk.potencia) || 1;
  const multProprio = multDaPotencia(potencia) * (pk.shiny ? estado.multShinyStats : 1);
  // A NOTA dele — a mesma conta da Calculadora — pinta o holofote do pedestal. `null` num
  // anúncio velho sem IV: aí a luz fica no roxo da casa, em vez de inventar uma faixa.
  const nf = notaEFaixa(pk);

  // ---- stats de verdade, quando o anúncio (ou o snapshot) os traz: o hexágono (a forma dos
  // stats e, por cima, a dos IVs) e as barras com o IV de cada um ao lado.
  const stats = pk.stats ?? null;
  const maiorStat = stats ? Math.max(1, ...Object.values(stats).map(Number).filter(Number.isFinite)) : 1;
  const blocoStats = stats
    ? `<div class="fi-stats-duo">
         ${radarStats([
           { valores: Object.fromEntries(STATS_ORDEM.map(([k]) => [k, (Number(stats[k]) || 0) / maiorStat])), classe: 'stats' },
           ...(pk.ivs ? [{ valores: Object.fromEntries(STATS_ORDEM.map(([k]) => [k, (Number(pk.ivs[k]) || 0) / IV_POR_STAT.max])), classe: 'iv' }] : []),
         ])}
         <div class="fi-stats">
           ${STATS_ORDEM.map(
             ([chave, rotulo]) => `
               <div class="fi-stat">
                 <span class="fi-stat-nome">${rotulo}</span>
                 <span class="fi-stat-barra"><i style="width:${Math.min(100, ((Number(stats[chave]) || 0) / maiorStat) * 100)}%"></i></span>
                 <b class="fi-stat-num">${num(stats[chave])}</b>
                 ${pk.ivs ? `<em class="fi-iv ${classeIvStat(pk.ivs[chave])}" title="${t('dex.ivStatTitle')}">IV ${num(pk.ivs[chave])}</em>` : ''}
               </div>`,
           ).join('')}
         </div>
       </div>
       ${pk.ivs ? `<p class="fi-radar-legenda"><i class="stats"></i>${t('dex.legendaStats')}<i class="iv"></i>${t('dex.legendaIv')}</p>
       <p class="fi-nota">${t('dex.notaIvPorStat')}</p>` : ''}`
    : `<p class="fi-vazio">${t('dex.semStatsAnuncio')}</p>`;

  // ---- XP: quanto falta para o próximo nível
  const xpNivel = pk.xpNivel ?? (pk.xp != null ? xpTotalParaNivelCliente(nivel) : null);
  const xpProx = pk.xpProximo ?? (pk.xp != null ? xpTotalParaNivelCliente(nivel + 1) : null);
  const dentro = xpNivel != null ? Math.max(0, (pk.xp ?? 0) - xpNivel) : null;
  const faixa = xpNivel != null ? Math.max(1, xpProx - xpNivel) : null;

  // A barra é limitada à faixa do nível, e o que falta nunca é negativo. Não deveria
  // acontecer — `ganharXp` recalcula o nível a cada ganho, então XP e nível andam juntos —,
  // mas uma linha importada de fora (ou um anúncio velho) pode trazer o par desencontrado, e
  // "faltam −127.200 xp" é o tipo de número que faz o jogador achar que a ficha está mentindo
  // sobre o resto também. O total verdadeiro continua logo abaixo, em "XP acumulado".
  const naFaixa = dentro == null ? null : Math.min(dentro, faixa);

  const blocoXp =
    dentro == null
      ? `<p class="fi-vazio">${t('dex.semXpAnuncio')}</p>`
      : `<div class="barra xp fi-xp"><div class="fill" style="width:${Math.min(100, (naFaixa / faixa) * 100)}%"></div>
           <span>${num(naFaixa)} / ${num(faixa)} xp</span></div>
         <div class="fi-placas">
           ${fiPlaca(t('dex.xpTotal'), num(pk.xp ?? 0), { icone: 'estrela' })}
           ${fiPlaca(t('dex.faltamXp'), num(Math.max(0, faixa - dentro)), { icone: 'ampulheta' })}
           ${fiPlaca(t('dex.proximoNivel'), num(nivel + 1), { icone: 'subir' })}
         </div>`;

  const ivTotal = pk.ivs
    ? Object.values(pk.ivs).reduce((s, v) => s + v, 0)
    : (pk.ivTotal ?? null);
  const qualidade = Number(pk.quality ?? pk.qualidade);

  // ---- stats-BASE da espécie, com o refino deste bicho ao lado
  //
  // A Pokédex já mostra a base da espécie; o que só existe aqui é a COLUNA do "+N", porque
  // ela é do indivíduo e não da espécie. E quando a ficha é do próprio dono, cada linha ganha
  // o botão de comprar o degrau seguinte — é o atalho que evita ter de pôr o bicho em campo
  // só para chegar na bancada (ver o cabeçalho do bloco de refino).
  const infoRf = infoRefino(pk);
  const blocoRefino = infoRf
    ? fiCartao(
        t('dex.statsBase'),
        `${infoRf.meu ? chipPedra(infoRf) : ''}
         <div class="fi-stats fi-stats-refino">
           ${infoRf.linhas.map((l) => linhaRefino(l, {
             comBotao: infoRf.meu,
             pedra: infoRf.pedra,
             pedras: infoRf.pedras,
             rotuloPedras: infoRf.rotuloPedras,
           })).join('')}
           ${linhaBaseSpeed(infoRf.especie)}
         </div>
         <p class="fi-nota">${infoRf.meu ? t('refino.nota', { base: num(cfgRefino().custoBase) }) : t('refino.notaAlheio')}</p>`,
        { icone: 'subir', extra: t('dex.statsNota') },
      )
    : '';

  // A calculadora só faz sentido com os TRÊS eixos na mão. Sem IV ou sem qualidade — um
  // anúncio da vitrine anterior à ficha detalhada, por exemplo — o botão não aparece, em vez
  // de abrir a ferramenta com um número inventado e dar uma nota que não é deste bicho.
  const podeCalcular = ivTotal != null && Number.isFinite(Number(pk.quality));
  // O botão de derrubar um nível. Só na ficha de um pokémon SEU: no anúncio do Mercado, na
  // ficha do ranking e na compartilhada no chat ele seria um botão que não faz nada — e o
  // servidor recusaria de qualquer forma, porque o bicho não está na coleção de quem clicou.
  const infoRed = infoReducaoNivel(pk);
  const capturador = capturadorDoPokemon(pk);
  const megaFicha = megaDaFicha(especie);
  const evo = infoEvolucao(pk);
  const poder = pk.poder ?? (especie ? poderDeReferencia(especie, nivel, multProprio) : 0);

  // ---- a IDENTIDADE em placas: o código, quando e por quem foi capturado, as medalhas e os
  // troféus que ele carrega, e a espécie.
  const identidade = [
    codigoPokemon(pk.id) ? fiPlaca(t('dex.identidade'), `<span class="txt-num">${codigoPokemon(pk.id)}</span>`, { icone: 'copia' }) : '',
    codigoPokemon(pk.id) && caughtAtDoPokemon(pk)
      ? fiPlaca(t('dex.capturadoEm'), `<span class="txt-num">${formatarDataCaptura(caughtAtDoPokemon(pk))}</span>`, { icone: 'calendario' })
      : '',
    capturador ? fiPlaca(t('dex.capturadoPor'), `<span class="txt-num">${escapar(capturador)}</span>`, { icone: 'pessoa' }) : '',
    medalhasDe(pk) > 0
      ? fiPlaca(t('medalha.ficha'), `<span class="txt-num fi-medalha">🎖️ ${escapar(vezesMedalha(medalhasDe(pk)))}</span>`, { classe: 'ouro' })
      : '',
    ...trofeusDe(pk).map((tr) => fiPlaca(
      t(`trofeu.${tr.tipo}`),
      `<span class="txt-num fi-trofeu">${imgTrofeu(tr)} ${escapar(vezesMedalha(tr.n))}</span>`,
      { classe: 'ouro' },
    )),
    especie ? fiPlaca(t('dex.especie'), `#${num(dexExibicao(especie.pokeId))} ${escapar(especie.name)}`, { icone: 'olho' }) : '',
  ].filter(Boolean).join('');

  // ---- a CADEIA de evolução (o destino e a mega levam à ficha DA ESPÉCIE deles, como o "Ver
  // espécie"). Para um shiny, os destinos já vêm na forma shiny (`infoEvolucao`).
  const cadeia = evo || megaFicha
    ? fiCartao(t('dex.evolucao'), cadeiaEvolucaoHtml({
        atual: {
          pokeId: especie?.pokeId ?? pk.speciesId,
          nome: nomeExibidoPokemon(pk) || pk.nome || '—',
          lt: looktypeDe(pk),
          comum: especie?.looktype ?? pk.looktype,
          sub: dlgNivel(nivel),
        },
        destinos: (evo?.opcoes ?? []).map((o) => ({
          pokeId: o.pokeId,
          nome: o.nome,
          nivel: o.nivel,
          temArte: o.temArte,
          looktype: o.looktype,
          pedra: evo.pedraPorDestino ? { itemId: o.itemId, nome: o.pedra } : null,
        })),
        pedraUnica: evo && !evo.pedraPorDestino ? { itemId: evo.itemId, nome: evo.pedra } : null,
        mega: megaFicha,
      }), { icone: 'subir' })
    : '';

  // ---- as AÇÕES, todas juntas embaixo do nome: as que só leem (Calcular, Comparar, Ver
  // espécie) e a única que mexe no bicho (Reduzir o nível), em âmbar.
  const acoes = [
    podeCalcular ? `<button type="button" class="fi-calc fi-acao" id="fi-calc">${dlgIcone('soma', 14)}<span>${t('dex.calcular')}</span></button>` : '',
    podeCalcular ? `<button type="button" class="fi-calc fi-calc-comp-bt fi-acao" id="fi-comp-a">${t('dex.compararA')}</button>` : '',
    podeCalcular ? `<button type="button" class="fi-calc fi-calc-comp-bt fi-acao" id="fi-comp-b">${t('dex.compararB')}</button>` : '',
    infoRed ? `<button type="button" class="fi-calc fi-calc-comp-bt fi-baixar-nv fi-acao" id="fi-baixar-nv"
      title="${escapar(t('dex.reduzirNivelAjuda', { piso: num(infoRed.piso) }))}">${t('dex.reduzirNivel')}</button>` : '',
    especie ? `<button class="fi-verdex fi-acao" id="fi-verdex" type="button">${dlgIcone('olho', 14)}<span>${t('dex.verEspecie')}</span></button>` : '',
  ].filter(Boolean).join('');

  return `
    <div class="fi-heroi">
      <div class="fi-heroi-info">
        <div class="fi-nome">${pk.shiny ? prefixoShiny() : ''}${escapar(nomeExibidoPokemon(pk) || '—')}${seloRefino(pk)}</div>
        <div class="fi-heroi-sub">
          <span class="fi-nivel-chip">${t('cm.nivel')} ${num(nivel)}</span>
          ${apelidoDe(pk) ? `<span class="fi-apelido">${t('nametag.fichaEspecie', { especie: escapar(pk.nome ?? '—') })}</span>` : ''}
        </div>
        <div class="fi-tipos">${selosDeTipo(pk.tipos?.length ? pk.tipos : especie ? [especie.type1, especie.type2].filter(Boolean) : [])}</div>
        ${pk.shiny || selosTm(pk) || pokemonTemXpShareHeld(pk)
          ? `<div class="fi-selos-linha">${pk.shiny ? seloShiny() : ''}${selosTm(pk)}${pokemonTemXpShareHeld(pk) ? seloXpShareHeld() : ''}</div>`
          : ''}
        <!-- Duas fileiras: as placas de METAL juntas (Potência, Qualidade, IV — a mesma escada de
             cor do card, lida de uma vez) e, embaixo, Poder e HP de combate lado a lado. -->
        <div class="fi-placas-heroi">
          <div class="fi-placas-linha">
            ${fiPlaca(t('dex.potencia'), `P${potencia}`, {
              classe: `pk-selo pk-selo-pot t${potencia}`,
              titulo: potencia === 1 ? t('cm.potenciaP1') : t('cm.potenciaAjuda', { n: potencia, b: bonusDaPotencia(potencia) }),
            })}
            ${Number.isFinite(qualidade) && qualidade > 0 ? fiPlaca(t('dex.qualidade'), virgula(qualidade.toFixed(3)), {
              classe: `pk-selo pk-selo-q t${degrauPorCortes(percentilQualidade(qualidade), CORTES_QUALIDADE_PCT)}`,
              titulo: t('selo.qualidadeAjuda', { v: virgula(qualidade.toFixed(3)), pct: Math.max(1, Math.round((1 - percentilQualidade(qualidade)) * 100)) }),
            }) : ''}
            ${ivTotal != null ? fiPlaca(t('dex.ivTotal'), `${num(ivTotal)}<small>/192</small>`, {
              classe: `pk-selo pk-selo-iv t${degrauPorCortes((ivTotal - IV_MIN) / (IV_MAX - IV_MIN), CORTES_IV_PCT)}`,
              titulo: t('selo.ivAjuda', { v: num(ivTotal), max: num(IV_MAX), pct: Math.round(((ivTotal - IV_MIN) / (IV_MAX - IV_MIN)) * 100) }),
            }) : ''}
          </div>
          <div class="fi-placas-linha">
            ${fiPlaca(t('dex.poder'), `⚔ ${num(poder)}`, { classe: 'destaque' })}
            ${pk.maxHp ? fiPlaca(t('dex.hpCombate'), num(pk.maxHp), { icone: 'cura' }) : ''}
          </div>
        </div>
        ${acoes ? `<div class="fi-acoes">${acoes}</div>` : ''}
      </div>
      <div class="fi-heroi-palcos">
        ${holofoteHtml({
          id: 'fi-palco',
          faixa: nf?.faixa ?? null,
          tom: nf ? null : 'rx',
          classe: `fi-palco${pk.shiny ? ' hf-shiny' : ''}`,
          rodape: placaNotaFicha(nf),
        })}
      </div>
    </div>

    ${fiCartao(t('dex.statsAtuais'), blocoStats, { icone: 'estrela', classe: nf ? `nota-tinta ${nf.faixa}` : '' })}
    ${blocoRefino}
    ${cadeia}
    <div class="fi-grade-2">
      ${fiCartao(t('dex.experiencia'), blocoXp, { icone: 'subir' })}
      ${identidade ? fiCartao(t('dex.identidadeTitulo'), `<div class="fi-placas">${identidade}</div>`, { icone: 'pessoa' }) : ''}
    </div>
    ${fiCartao(
      t('dex.potenciaDele'),
      `${escadaPotenciasHtml({ especie, nivel, aqui: potencia, shiny: !!pk.shiny })}
       <p class="fi-nota">${t('dex.notaPotenciaDele')}</p>`,
      { icone: 'raio' },
    )}`;
}

/** A curva de XP do jogo — a mesma de `xpTotalParaNivel` no servidor. */
const xpTotalParaNivelCliente = (L) =>
  L <= 1 ? 0 : Math.round((50 / 3) * (L ** 3 - 6 * L ** 2 + 17 * L - 12));

/** Espelha `aplicarPerdaDeXpTreinador` + frações da Bless (`loja.mjs`). Só para o aviso. */
const FRAC_MORTE_BLESS = { blessplus: 0.08, blessultra: 0.03, blessmax: 0 };
const FRAC_MORTE_PADRAO = 0.1;
function xpPerdaDesistenciaPrevista(e) {
  if (!e) return { xp: 0, pct: 10 };
  const piso = xpTotalParaNivelCliente(e.level ?? 1);
  const dentro = Math.max(0, (e.xp ?? 0) - piso);
  const frac = e.bless != null ? (FRAC_MORTE_BLESS[e.bless] ?? FRAC_MORTE_PADRAO) : FRAC_MORTE_PADRAO;
  return { xp: Math.floor(dentro * frac), pct: Math.round(frac * 100) };
}

function confirmarDesistenciaCombate() {
  const e = estado.eu;
  if (!e?.huntSlug || e.noCentro || e.boss?.arena || e.mistico) return;
  const { xp, pct } = xpPerdaDesistenciaPrevista(e);
  const ativo = e.pokemons?.find((p) => p.id === e.activeId) ?? e.pokemons?.[0] ?? null;
  // A bandeira branca: o pokémon que está lutando, sem cor, e a seta para o Centro. O preço da
  // desistência (o XP) é o aviso em caixa — é o número que a pessoa precisa ler antes do clique.
  confirmar({
    titulo: t('cena.desistirTitulo'),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({
          arte: ativo ? dlgArtePk(ativo, 64) : dlgArteTreinador(null, null, 64),
          nome: ativo ? nomePkHtml(ativo) : escapar(e.nick ?? ''),
          classe: 'sai',
          marca: dlgIcone('bandeira', 15),
        })}
        ${dlgSeta()}
        ${dlgAtor({ arte: dlgArteHtml(dlgMedalha({ icone: 'cura', tom: 'verde' })), nome: escapar(t('dlg.centro')) })}`, 'perigo')}
      ${dlgFrase('', escapar(t('cena.desistirTexto')))}
      ${xp > 0
        ? dlgAviso(t('cena.desistirXpPerda', { xp: num(xp), pct }))
        : dlgAviso(t('cena.desistirXpZero'), { icone: 'check', tom: 'info' })}
      <p class="confirmar-desistir-nota">${t('cena.desistirAutoHunt')}</p>`,
    tom: 'perigo',
    aoConfirmar: () => enviar({ t: 'centro.desistir' }),
  });
}

// ---------------------------------------------------------- reduzir o nível
//
// A saída de quem pôs o boost de XP no POKÉMON em vez de na conta: o bicho passa do teto de
// `podeUsarPokemon` (treinador + 5) e vira enfeite, porque a única forma de destravá-lo era
// subir milhões de XP de treinador com outro pokémon nível 1. A regra inteira está em
// `shared/reduzir-nivel.mjs`; aqui é só a superfície.

/**
 * Nível, piso e a faixa que dá para escolher — ou `null` quando o pokémon não é seu.
 *
 * O piso é o "Nível ao capturar" da espécie — a mesma linha que a ficha dela mostra — e vem
 * pronto do SERVIDOR, no campo `pisoNivel` do snapshot. Não é calculado aqui porque o catálogo
 * desta tela é montado por conta própria (`carregarCatalogoEspecies`) e não aplica o degrau
 * das hunts legadas de `hunts-sinnoh.json`: o `huntLevel` de oito espécies (Blissey, Ditto,
 * Porygon…) diverge do que o servidor tem. A conta local fica de reserva, para uma aba aberta
 * contra um servidor que ainda não manda o campo.
 */
function infoReducaoNivel(pk) {
  if (!pokemonNaMinhaMao(pk)) return null;
  const vivo = pokemonAtualizado(pk);
  const nivel = Math.max(1, Math.floor(Number(vivo.level) || 1));
  const esp = especieDe(vivo);
  const piso = vivo.pisoNivel ?? pisoReducaoNivel(esp, nivelDeHuntDaEspecie(esp));
  return {
    pk: vivo,
    nivel,
    piso,
    faixa: faixaReducaoNivel(nivel, piso),
    pode: podeReduzirNivel(nivel, piso),
  };
}

/**
 * Abre a caixa com o CAMPO do nível e pede a queda direto para ele.
 *
 * O campo nasce com o maior nível que cabe no treinador, e a cada tecla a caixa refaz o "vai
 * do Nv X para o Nv Y, −xp" e trava o botão quando o número não vale. Essa checagem é só
 * conforto: a mensagem leva `nivelAlvo`, e quem decide se ele passa é o `validarNivelAlvo` do
 * SERVIDOR, com o nível e o piso de lá (ver o cabeçalho de `shared/reduzir-nivel.mjs`). Um
 * pedido adulterado com `-40` ou `999` é recusado lá, não aqui.
 */
function pedirReducaoNivel(pk) {
  const info = infoReducaoNivel(pk);
  if (!info) return;
  if (!info.pode) {
    // Toast, e não um botão desabilitado: no toque não há `title` para explicar por que o
    // botão não responde, e "já está no piso" é justamente a informação que falta. Mesma
    // decisão do "+" do refino quando o stat chega ao teto.
    return toast(t('dex.reduzirNivelNoPiso', { nome: info.pk.nome ?? '—', piso: num(info.piso) }));
  }
  const { min, max } = info.faixa;
  const nome = escapar(info.pk.nome ?? '—');
  const meuNv = estado.eu?.level ?? 0;
  let alvo = nivelSugeridoReducao(info.nivel, info.piso, meuNv);

  // O mesmo bicho dos dois lados da seta: o nível de hoje à esquerda e, à direita, o que está
  // no campo — ele anda junto com a digitação (`#rnv-para`), e o boneco apaga quando o número
  // não vale.
  confirmar({
    titulo: t('dex.reduzirNivelTitulo', { nome: info.pk.nome ?? '—' }),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({ arte: dlgArtePk(info.pk, 64), nome: nomePkHtml(info.pk), sub: dlgNivel(info.nivel) })}
        ${dlgSeta({ rotulo: '−XP' })}
        <div class="dlg-ator novo" id="rnv-ator">
          <span class="dlg-ator-arte">${dlgArtePk(info.pk, 64)}</span>
          <span class="dlg-ator-nome">${nomePkHtml(info.pk)}</span>
          <span class="dlg-ator-sub" id="rnv-para">${dlgNivel(alvo)}</span>
        </div>`)}
      <label class="qtd-bloco reduzir-nv-bloco">
        <span class="qtd-topo">${t('dex.reduzirNivelCampo')}<em>${t('dex.reduzirNivelFaixa', { min: num(min), max: num(max) })}</em></span>
        <span class="qtd-linha">
          <input type="number" class="qtd-num" id="rnv-alvo" min="${min}" max="${max}" step="1" value="${alvo}" inputmode="numeric">
        </span>
      </label>
      <p id="rnv-resumo"></p>
      <p class="confirmar-aviso-xp" id="rnv-destrava" hidden>${t('dex.reduzirNivelDestrava', { nome })}</p>
      <p class="confirmar-nota">${t('dex.reduzirNivelPiso', { piso: num(info.piso) })}</p>`,
    rotuloSim: t('dex.reduzirNivelConfirmar'),
    aoConfirmar: () => {
      if (!validarNivelAlvo(info.nivel, info.piso, alvo).ok) return;
      enviar({ t: 'pokemon.reduzirNivel', pokemonId: info.pk.id, nivelAlvo: alvo });
    },
  });

  const campo = $('#rnv-alvo');
  const resumo = $('#rnv-resumo');
  const destrava = $('#rnv-destrava');
  const sim = $('#confirmar-sim');
  const repintar = () => {
    // Campo vazio é `NaN`, e não o `0` que `Number('')` daria: o 0 cairia no "fora da faixa"
    // por acaso, e o NaN cai no "inválido" de propósito.
    const digitado = campo.value.trim() === '' ? Number.NaN : Number(campo.value);
    const r = validarNivelAlvo(info.nivel, info.piso, digitado);
    sim.disabled = !r.ok;
    $('#rnv-ator')?.classList.toggle('travado', !r.ok);
    $('#rnv-ator')?.classList.toggle('novo', r.ok);
    if (!r.ok) {
      alvo = null;
      resumo.innerHTML = t('dex.reduzirNivelInvalido', { min: num(min), max: num(max) });
      $('#rnv-para').textContent = '—';
      destrava.hidden = true;
      return;
    }
    alvo = r.novo;
    $('#rnv-para').textContent = dlgNivel(alvo);
    resumo.innerHTML = t('dex.reduzirNivelTexto', {
      nome,
      de: num(info.nivel),
      para: num(alvo),
      xp: num(Math.max(0, (info.pk.xp ?? 0) - xpTotalParaNivelCliente(alvo))),
    });
    // A promessa de destravar só aparece quando é VERDADE: quem escolhe um nível ainda acima
    // do treinador continua travado, e prometer o contrário seria mentir na caixa.
    destrava.hidden = !(!podeUsarPokemon(meuNv, info.pk) && meuNv >= nivelMinimoTreinador(alvo));
  };
  campo.oninput = repintar;
  campo.onkeydown = (ev) => {
    if (ev.key === 'Enter' && !sim.disabled) sim.click();
  };
  repintar();
}

// -------------------------------------------------------------- abrir/fechar

const fecharFicha = () => {
  fecharCalculadora();
  fichaPokemonAberto = null;
  fichaCompartilharPkId = null;
  $('#ficha-compartilhar')?.classList.add('hidden');
  $('#ficha').classList.add('hidden');
};

/** Põe a ficha na tela e liga o que dentro dela precisa de JS (sprites, ícones, botões). */
function mostrarFicha(titulo, html, aoMontar) {
  $('#ficha-titulo').textContent = titulo;
  // O invólucro `.fi-corpo` é o container das `@container` da ficha. Fica DENTRO do elemento que
  // rola, e não nele: contenção no próprio rolador atrapalhava a conta da rolagem, e o fim da
  // ficha ficava cortado.
  $('#ficha-corpo').innerHTML = `<div class="fi-corpo">${html}</div>`;
  // Os ícones marcados no HTML viram desenho aqui: `data-bola` nas linhas de captura e
  // `data-item` nas de drop. Fazer isto por marcação (em vez de montar cada `<td>` no DOM)
  // é o que deixa as tabelas serem template de string, que é como o resto da tela é escrito.
  for (const el of $('#ficha-corpo').querySelectorAll('[data-bola]')) {
    el.appendChild(iconeBola(Number(el.dataset.bola), 18));
  }
  for (const el of $('#ficha-corpo').querySelectorAll('[data-item]')) {
    if (el.dataset.item) el.appendChild(imgItem(Number(el.dataset.item), 22));
  }
  aoMontar?.();
  $('#ficha').classList.remove('hidden');
}

/** Fecha a ficha da Pokédex e abre a aba Bosses com o boss da espécie selecionado. */
function abrirBossDaPokedex(key) {
  if (!key || !estado.bossesCatalogo?.some((b) => b.key === key)) return;
  bossAberto = key;
  fecharFicha();
  abrirModal('bosses');
}

function abrirFichaDaEspecie(pokeId) {
  const id = remapOutlandPokeId(Number(pokeId));
  let especie = estado.especies.get(id);
  if (!especie && isOutlandPokeId(id)) {
    const pid = estado.outlandDex?.dexToPoke?.[id];
    if (pid) especie = estado.especies.get(remapOutlandPokeId(pid));
  }
  if (!especie && !isOutlandPokeId(id)) especie = estado.especies.get(dexDoPokeId(id));
  if (!especie) return;

  fichaPokemonAberto = null;
  fichaCompartilharPkId = null;
  mostrarFicha(especie.name, corpoDaEspecie(especie), () => {
    porNoPedestal($('#fi-palco .hf-arte'), especie.looktype, 104);
    const palcoShiny = $('#fi-palco-shiny .hf-arte');
    if (palcoShiny) porNoPedestal(palcoShiny, lookShinyFicha(especie), 104, especie.looktype);
    ligarFichaNova($('#ficha-corpo'));

    // Clicar na evolução TROCA a ficha pela dela — mesma janela, sem perder o lugar.
    for (const b of $('#ficha-corpo').querySelectorAll('.fi-evo-link')) {
      b.onclick = () => abrirFichaDaEspecie(Number(b.dataset.especie));
    }

    // Clicar numa hunt da lista LEVA para ela — a ficha é onde o jogador decide para onde ir.
    for (const b of $('#ficha-corpo').querySelectorAll('.fi-hunt')) {
      b.onclick = () => {
        if (b.classList.contains('fi-boss-cta')) return abrirBossDaPokedex(b.dataset.boss);
        // O ticket na mão, a ficha aberta: a confirmação da arena abre daqui mesmo. A ficha
        // fecha antes porque a entrada troca a cena — voltar dela para uma ficha esquecida
        // por cima do campo é o tipo de janela que ninguém sabe de onde veio.
        if (b.classList.contains('fi-mistico-cta')) {
          fecharFicha();
          fecharModal();
          return abrirUsoTicketMistico();
        }
        if (b.classList.contains('travada')) return toast(t('dex.areaTravada'));
        if (avisoTrocaDeHuntBloqueada()) return;
        enviar({ t: 'hunt.select', slug: b.dataset.hunt });
        fecharFicha();
        fecharModal();
      };
    }
  });
}

/**
 * O pokémon da ficha aberta agora, ou `null`. Existe por causa do refino: a ficha é montada
 * uma vez e não remonta a cada snapshot (senão a rolagem voltaria ao topo duas vezes por
 * segundo), então quem compra um degrau de dentro dela precisa de alguém para redesenhar.
 */
let fichaPokemonAberto = null;

function abrirFichaDoPokemon(pk) {
  fichaPokemonAberto = pk;
  fichaCompartilharPkId = pokemonCompartilhavelNoChat(pk) ? pk.id : null;
  const nomeTit = nomeExibidoPokemon(pk) || '—';
  const titulo = pk.dono ? `${nomeTit} · ${pk.dono}` : nomeTit;
  mostrarFicha(titulo, corpoDoPokemon(pk), () => {
    pintarBotaoCompartilharFicha();
    porNoPedestal($('#fi-palco .hf-arte'), looktypeDe(pk), 104, especieDe(pk)?.looktype ?? pk.looktype);
    ligarFichaNova($('#ficha-corpo'));
    const verDex = $('#fi-verdex');
    if (verDex) verDex.onclick = () => abrirFichaDaEspecie(pk.speciesId);
    // O destino da evolução e a mega levam à ficha DA ESPÉCIE deles, como o "Ver espécie".
    for (const b of $('#ficha-corpo').querySelectorAll('.fi-evo-link')) {
      b.onclick = () => abrirFichaDaEspecie(Number(b.dataset.especie));
    }
    const calcular = $('#fi-calc');
    if (calcular) calcular.onclick = () => calcularEstePokemon(pk);
    const compA = $('#fi-comp-a');
    if (compA) compA.onclick = () => compararEstePokemon(pk, 'a');
    const compB = $('#fi-comp-b');
    if (compB) compB.onclick = () => compararEstePokemon(pk, 'b');
    const baixarNv = $('#fi-baixar-nv');
    if (baixarNv) baixarNv.onclick = () => pedirReducaoNivel(pk);
    ligarBotoesRefino($('#ficha-corpo'), pk);
  });
}

/** Redesenha a ficha aberta com o estado novo — usada depois de um refino. */
function reabrirFichaDoPokemon() {
  if (!fichaPokemonAberto) return;
  abrirFichaDoPokemon(pokemonAtualizado(fichaPokemonAberto));
}

/**
 * IV, qualidade, potência e espécie da ficha — o que a calculadora precisa.
 * `null` quando a ficha não traz IV (anúncio velho, por exemplo).
 */
function dadosCalcDePokemon(pk) {
  const ivTotal = pk.ivs
    ? Object.values(pk.ivs).reduce((s, v) => s + v, 0)
    : (pk.ivTotal ?? null);
  if (ivTotal == null) return null;
  return {
    speciesId: pk.speciesId ?? especieDe(pk)?.pokeId ?? null,
    iv: Math.round(ivTotal),
    ivs: pk.ivs ? { ...pk.ivs } : null,
    ivManual: !!pk.ivs,
    qualidade: Number(pk.quality) || 1,
    potencia: Math.min(POTENCIA_MAX, Math.max(POTENCIA_MIN, Number(pk.potencia) || 1)),
    shiny: !!pk.shiny,
    level: pk.level ?? CALC_NIVEL_PADRAO,
  };
}

/**
 * Leva os três eixos da ficha para a calculadora e abre a ferramenta já preenchida.
 *
 * IV somado, qualidade e potência são exatamente os campos que a calculadora pede, e são
 * exatamente os que a ficha já mostra — digitá-los de novo, olhando de uma tela para a outra,
 * era o passo bobo que faltava tirar. A calculadora abre EMPILHADA por cima da ficha para
 * fechar com Esc/voltar e comparar vários pokémon do Market sem perder o lugar.
 */
function calcularEstePokemon(pk) {
  const dados = dadosCalcDePokemon(pk);
  if (!dados) return;
  calc.aba = 'nota';
  calc.speciesId = dados.speciesId;
  calc.iv = dados.iv;
  calc.ivs = dados.ivs;
  calc.ivManual = dados.ivManual;
  calc.qualidade = dados.qualidade;
  calc.potencia = dados.potencia;
  calc.shiny = dados.shiny;
  calc.especieBusca = '';
  calc.origem = {
    nome: pk.nome ?? '—',
    nivel: pk.level ?? null,
    shiny: !!pk.shiny,
    dono: pk.dono ?? null,
    poder: pk.poder ?? null,
    maxHp: pk.maxHp ?? null,
  };
  abrirCalculadoraEmpilhada();
}

/** Atalho da ficha: preenche o lado A ou B da aba Comparar e abre a calculadora. */
function compararEstePokemon(pk, lado) {
  const dados = dadosCalcDePokemon(pk);
  if (!dados) return;
  const cfg = cfgComp(lado);
  cfg.speciesId = dados.speciesId;
  cfg.level = dados.level;
  cfg.iv = dados.iv;
  cfg.ivs = dados.ivs;
  cfg.ivManual = dados.ivManual;
  cfg.qualidade = dados.qualidade;
  cfg.potencia = dados.potencia;
  cfg.shiny = dados.shiny;
  cfg.especieBusca = '';
  calc.aba = 'comparar';
  abrirCalculadoraEmpilhada();
}

$('#ficha-fechar').onclick = (ev) => {
  ev.stopPropagation();
  fecharFicha();
};
$('#ficha').onclick = (ev) => {
  // Bloco, e não expressão — ver a nota em `#confirmar`.
  if (calcEmpilhada()) return;
  if (ev.target !== $('#ficha')) return;
  ev.stopPropagation();
  fecharFicha();
};
$('#calc-fechar').onclick = (ev) => {
  ev.stopPropagation();
  fecharCalculadora();
};
$('#calc').onclick = (ev) => {
  if (ev.target !== $('#calc')) return;
  ev.stopPropagation();
  fecharCalculadora();
};

// -------------------------------------------------------------- Pokepédia
//
// O manual do jogo. O CONTEÚDO mora em `pokepedia.mjs` (é texto longo, em três línguas, e não
// tinha por que disputar espaço no dicionário de rótulos); aqui fica só a casca: a barra de
// capítulos, a busca e a navegação entre eles.
//
// As tabelas de lá são montadas a partir do `welcome` — por isso o `estado` inteiro é passado
// como fonte de dados. Nenhum número do manual é escrito à mão.

function renderPokepedia() {
  const lang = idioma();
  const atual = estado.capPokepedia ?? CAPITULOS[0].id;

  // Os capítulos agrupados, na ordem em que foram declarados.
  let html = '';
  let grupoAberto = null;
  for (const cap of CAPITULOS) {
    if (cap.grupo !== grupoAberto) {
      grupoAberto = cap.grupo;
      html += `<div class="wk-grupo">${escapar(tituloDoGrupo(cap.grupo, lang))}</div>`;
    }
    html += `<button class="wk-item ${cap.id === atual ? 'on' : ''}" data-cap="${cap.id}">
               ${escapar(tituloDoCapitulo(cap.id, lang))}
             </button>`;
  }

  return `
    <div class="wk-corpo">
      <nav class="wk-menu">
        <input id="wk-busca" class="wk-busca" type="search" placeholder="${t('wiki.buscar')}" autocomplete="off">
        <button type="button" id="wk-gpt" class="wk-gpt" title="${escapar(t('wiki.copiarGptAjuda'))}">
          ${escapar(t('wiki.copiarGpt'))}
        </button>
        <div class="wk-lista" id="wk-lista">${html}</div>
      </nav>
      <article class="wk-texto" id="wk-texto"></article>
    </div>`;
}

/** Desenha o capítulo escolhido e liga os links internos. */
function pintarCapitulo(id) {
  const lang = idioma();
  estado.capPokepedia = id;
  const alvo = $('#wk-texto');
  if (!alvo) return;

  // O manual lê os catálogos do `welcome` direto do estado. O `textoDaLoja` vai junto para a
  // tabela da Loja sair no idioma da tela, como a vitrine.
  const dados = { ...estado, textoDaLoja };

  alvo.innerHTML = `
    <h2 class="wk-titulo">${escapar(tituloDoCapitulo(id, lang))}</h2>
    ${corpoDoCapitulo(id, lang, dados)}`;
  // Volta ao topo: sem isto, pular de um capítulo longo para um curto deixa a tela no meio do
  // nada e parece que o clique não fez nada.
  alvo.scrollTop = 0;

  for (const b of $('#wk-lista').querySelectorAll('.wk-item')) {
    b.classList.toggle('on', b.dataset.cap === id);
  }
  // Os `<a data-cap="…">` do próprio texto navegam entre capítulos — é o que faz o manual ser
  // navegável em vez de uma lista de páginas soltas.
  for (const a of alvo.querySelectorAll('a[data-cap]')) {
    a.onclick = (ev) => {
      ev.preventDefault();
      pintarCapitulo(a.dataset.cap);
    };
  }
}

/**
 * "Copiar toda a Wiki para GPT": leva o manual inteiro para a área de transferência e abre o
 * ChatGPT numa aba nova.
 *
 * Por que COPIAR e não mandar o texto na URL: o manual passa de 100 mil caracteres e não
 * existe navegador que aceite isso num endereço — o limite prático fica na casa dos milhares.
 * Qualquer tentativa de empurrar o conteúdo pela URL chegaria truncada no meio de um
 * capítulo, que é pior do que não chegar. Então a aba abre vazia e o texto já está no Ctrl+V.
 *
 * O `window.open` sai ANTES do `await` da cópia de propósito: o navegador só deixa abrir aba
 * enquanto o clique do jogador ainda está "quente", e esperar a promessa da área de
 * transferência jogaria a abertura para o quadro seguinte — onde o bloqueador de pop-up come.
 */
async function copiarWikiParaGpt() {
  const lang = idioma();
  const dados = { ...estado, textoDaLoja };
  const texto = wikiEmTexto(lang, dados, t('wiki.gptCabecalho'));

  const copia = copiarTexto(texto);
  window.open(URL_CHATGPT, '_blank', 'noopener');
  toast(t(await copia ? 'wiki.copiado' : 'wiki.copiaFalhou'));
}

function montarPokepedia() {
  pintarCapitulo(estado.capPokepedia ?? CAPITULOS[0].id);
  $('#wk-gpt').onclick = copiarWikiParaGpt;

  $('#wk-lista').onclick = (ev) => {
    const b = ev.target.closest('.wk-item');
    if (b) pintarCapitulo(b.dataset.cap);
  };

  // A busca filtra os TÍTULOS da barra. Buscar dentro do texto exigiria montar os 19 capítulos
  // a cada tecla; o título já resolve "onde é que fala de saque".
  $('#wk-busca').oninput = (ev) => {
    const q = ev.target.value.trim().toLowerCase();
    for (const b of $('#wk-lista').children) {
      if (b.classList.contains('wk-grupo')) continue;
      b.classList.toggle('hidden', !!q && !b.textContent.toLowerCase().includes(q));
    }
    // Cabeçalho de grupo sem nenhum capítulo visível embaixo some junto.
    let grupo = null;
    let temFilho = false;
    const fechar = () => grupo && grupo.classList.toggle('hidden', !temFilho);
    for (const b of $('#wk-lista').children) {
      if (b.classList.contains('wk-grupo')) {
        fechar();
        grupo = b;
        temFilho = false;
      } else if (!b.classList.contains('hidden')) temFilho = true;
    }
    fechar();
  };
}

// ------------------------------------------------------------------ bolsa
//
// Modal com quatro abas: consumíveis do treinador, itens raros, pedras de evolução e loot.

const ABAS_BOLSA = [
  { id: 'treinador', nome: 'bolsa.catTreinador', ico: 'pokebola' },
  { id: 'raros', nome: 'bolsa.catRaros', ico: 'shiny' },
  { id: 'pedras', nome: 'bolsa.catPedras', ico: 'fire-stone' },
  { id: 'loots', nome: 'bolsa.catLoots', ico: 'bag-pollen' },
  // As SKINS de pokémon: aba própria porque o card delas não é um item de quantidade — é a skin
  // animada, quantas estão em uso e em quem, e o clique abre a folha de vestir. Ver `montarSkinsBolsa`.
  { id: 'skins', nome: 'bolsa.catSkins', ico: 'skins' },
  // A OFERENDA é a única aba que não lista itens: é uma OFICINA. Fica na bolsa, e depois de
  // Pedras, porque é de onde vem a pedra — quem abre a aba Pedras e vê que falta a Fire Stone
  // tem a resposta na aba ao lado, e não num NPC do outro lado do Centro Pokémon.
  { id: 'oferenda', nome: 'bolsa.catOferenda', ico: 'wide-lens' },
  // A CHOCADEIRA, outra oficina: os seis espaços de chocar Mystery Eggs. Ao lado da Oferenda pelo
  // mesmo motivo — não é lista de itens, é bancada. Ver `montarChocadeira`.
  { id: 'chocadeira', nome: 'bolsa.catChocadeira', ico: 'chocadeira' },
  // A COLEÇÃO: os pokémon do depot que o jogador separou para não vender. A mesma lista da aba
  // Coleção do Depot, mas aqui ela abre de qualquer lugar — o Depot só abre em Cerulean.
  { id: 'colecao', nome: 'bolsa.catColecao', ico: 'colecao' },
];

function icoAbaBolsa(tipo) {
  if (tipo === 'pokebola') return 'img:site/assets/ui/ball-poke.png';
  if (tipo === 'fire-stone') {
    const id = itemPorNome('Fire Stone')?.id;
    return id ? `img:${estado.iconesItem[id] ?? ICONE_ITEM_GENERICO}` : 'img:site/assets/ui/ball-poke.png';
  }
  if (tipo === 'bag-pollen') {
    const id = itemPorNome('Bag of Pollen')?.id;
    return id ? `img:${estado.iconesItem[id] ?? ICONE_ITEM_GENERICO}` : 'img:site/assets/ui/menu-bolsa.png';
  }
  return null;
}

function htmlIcoAbaBolsa(aba) {
  if (aba.ico === 'shiny') return '<span class="bolsa-aba-ico bolsa-aba-shiny" aria-hidden="true">✨</span>';
  // A Wide Lens da Oferenda vem de `src/client/img/`, e não do espelho de assets: o espelho tem
  // 335 ícones e nenhum deles é este, e além disso ele é gitignorado — arte posta lá some no
  // primeiro `npm run fetch`. Caminho absoluto é o que `iconeArquivo` usa para distinguir as
  // duas origens.
  if (aba.ico === 'wide-lens') return '<span class="bolsa-aba-ico" data-ico="img:/img/itens/wide-lens.png" data-ico-px="18"></span>';
  // O ícone do Depot de quando ele morava embaixo da Bolsa — o espelho ainda o baixa
  // (`tools/fetch-ui-icons.mjs`, `menu-depot.png`).
  if (aba.ico === 'colecao') return `<span class="bolsa-aba-ico" data-ico="${ICONE_COLECAO}" data-ico-px="18"></span>`;
  if (aba.ico === 'skins') return `<span class="bolsa-aba-ico" data-ico="img:${ICONE_COSMETICOS}" data-ico-px="18"></span>`;
  if (aba.ico === 'chocadeira') return '<span class="bolsa-aba-ico" data-ico="img:/img/itens/chocadeira.png" data-ico-px="18"></span>';
  const pedido = icoAbaBolsa(aba.ico);
  return pedido
    ? `<span class="bolsa-aba-ico" data-ico="${pedido}" data-ico-px="18"></span>`
    : '';
}

function renderBolsa() {
  const aba = estado.abaBolsa ?? 'treinador';
  return `
    <div class="bolsa-topo">
      <div class="bolsa-abas mk-abas">
        ${ABAS_BOLSA.map(
          (a) => `<button type="button" class="mk-aba bolsa-aba ${a.id === aba ? 'on' : ''}" data-aba="${a.id}">
            ${htmlIcoAbaBolsa(a)}
            <span>${t(a.nome)}</span>
          </button>`,
        ).join('')}
      </div>
    </div>
    <div id="bolsa-corpo"></div>`;
}

/**
 * O card de uma Caixa de Fundador na bolsa.
 *
 * Não é o `cardBolsa` comum porque o número ocupa o lugar da quantidade: onde um item mostra
 * "×12", a caixa mostra "#01", que é o que ela é. Clicar abre o diálogo de abrir — com o
 * aviso de que a partir dali nada mais é transferível.
 */
function cardCaixaDaBolsa(caixa) {
  const def = CAIXAS_BETA[caixa.tipo];
  const el = document.createElement('div');
  el.className = 'mk-card bolsa-card bolsa-card-usavel bolsa-card-cx';
  el.dataset.chave = `caixa${caixa.id}`;
  el.style.setProperty('--cx-cor', def?.cor ?? 'var(--rx)');
  const nome = t(`caixas.nome.${caixa.tipo}`);
  el.innerHTML = `
    <div class="mk-card-topo"><div class="mk-ico"></div></div>
    <div class="mk-nome" title="${escapar(nome)}">${escapar(nome)}</div>
    <div class="mk-preco bolsa-qtd cx-qtd"><b>${escapar(serieDaCaixa(caixa.tipo, caixa.serie))}</b></div>`;
  el.querySelector('.mk-ico').appendChild(iconeArquivo(`/img/itens/caixa-${caixa.tipo}.png`, 44));
  el.tabIndex = 0;
  el.title = t('caixas.abrirDica');
  const abrir = () => abrirDialogoCaixa(caixa.tipo, { modo: 'abrir', caixaId: caixa.id, serie: caixa.serie });
  el.onclick = abrir;
  el.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      abrir();
    }
  };
  return el;
}

function cardBolsa({ chave, nome, q, montarIco, extraHtml = '' }) {
  const el = document.createElement('div');
  el.className = 'mk-card bolsa-card';
  el.dataset.chave = chave;
  el.innerHTML = `
    <div class="mk-card-topo"><div class="mk-ico"></div></div>
    <div class="mk-nome" title="${escapar(nome)}">${escapar(nome)}</div>
    <div class="mk-preco bolsa-qtd"><b>${num(q)}</b>${extraHtml}</div>`;
  montarIco(el.querySelector('.mk-ico'));
  return el;
}

/**
 * O card de uma BICICLETA em Itens Raros: uma por card, com o NÚMERO no lugar da quantidade — como
 * a Casa. Clicar numa que não está equipada troca para ela; clicar na equipada guarda (a pé). Nunca
 * soma: equipar outra substitui a anterior, e quem decide é o servidor (`bicicleta.equipar`, que só
 * aceita bicicleta NA MÃO). A anunciada no Mercado só mostra o selo — não se equipa o que está à venda.
 */
function cardBicicletaDaBolsa(bici) {
  const el = document.createElement('div');
  const equipada = estado.eu?.bicicleta?.equipada === bici.id;
  el.className = `mk-card bolsa-card bolsa-card-cx rar-${bici.rar}`
    + `${bici.anunciada ? '' : ' bolsa-card-usavel'}${equipada ? ' bolsa-card-bicicleta-eq' : ''}`;
  el.dataset.chave = `bike${bici.id}`;
  el.style.setProperty('--cx-cor', `var(--rar-${bici.rar})`);
  const nome = nomeBicicletaRaridade(bici.rar);
  el.innerHTML = `
    <div class="mk-card-topo"><div class="mk-ico"></div></div>
    <div class="mk-nome" title="${escapar(nome)}">${escapar(nome)}</div>
    <div class="mk-preco bolsa-qtd cx-qtd"><b>${escapar(numeroDaBicicleta(bici.id))}</b></div>
    ${bici.anunciada
      ? `<em class="bolsa-xsh-eq">${escapar(t('casa.noMercado'))}</em>`
      : equipada ? `<em class="bolsa-xsh-eq">${escapar(t('bicicleta.equipadaSelo'))}</em>` : ''}`;
  el.querySelector('.mk-ico').appendChild(imgItem(BICICLETA_ITEM_POR_RAR[bici.rar], 44));
  if (bici.anunciada) return el;
  const meta = (estado.bicicletas?.raridades ?? []).find((r) => r.id === bici.rar);
  el.tabIndex = 0;
  el.title = equipada
    ? t('bicicleta.desequiparDica')
    : t('bicicleta.equiparDica', { vel: meta ? resumoDaBicicleta(meta) : '' });
  const acao = () => pedirEquiparBicicleta(equipada ? null : bici);
  el.onclick = acao;
  el.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      acao();
    }
  };
  return el;
}

/**
 * O card de uma Casa na bolsa: um por casa, com o NÚMERO no lugar da quantidade — como a Caixa de
 * Fundador. Não há mais nada a equipar (todas valem), então clicar abre o modal da Casa, que é
 * onde ela se usa.
 */
function cardCasaDaBolsa(casa) {
  const el = document.createElement('div');
  el.className = `mk-card bolsa-card bolsa-card-usavel bolsa-card-cx bolsa-card-casa rar-${casa.rar}`;
  el.dataset.chave = `casa${casa.id}`;
  el.style.setProperty('--cx-cor', `var(--rar-${casa.rar})`);
  const nome = nomeCasaRaridade(casa.rar);
  el.innerHTML = `
    <div class="mk-card-topo"><div class="mk-ico"></div></div>
    <div class="mk-nome" title="${escapar(nome)}">${escapar(nome)}</div>
    <div class="mk-preco bolsa-qtd cx-qtd"><b>${escapar(numeroDaCasa(casa.id))}</b></div>
    ${casa.anunciada
      ? `<em class="bolsa-xsh-eq">${escapar(t('casa.noMercado'))}</em>`
      : casa.emUso === false ? `<em class="bolsa-xsh-eq">${escapar(t('casa.guardadaSelo'))}</em>` : ''}`;
  el.querySelector('.mk-ico').appendChild(imgItem(CASA_ITEM_POR_RAR[casa.rar], 44));
  el.tabIndex = 0;
  el.title = t('casa.bolsaDica');
  const abrir = () => abrirModal('casa');
  el.onclick = abrir;
  el.onkeydown = (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      abrir();
    }
  };
  return el;
}

/** "4min 05s", "32s" — o que falta de um intervalo de troca. O mesmo formato do aviso do servidor. */
function tempoDeEspera(ms) {
  const s = Math.ceil(ms / 1000);
  const m = Math.floor(s / 60);
  return m ? `${m}min ${String(s % 60).padStart(2, '0')}s` : `${s}s`;
}

/**
 * Pede a troca de bicicleta — equipar `bici` (pelo número), ou guardar a equipada com `null`.
 *
 * Como a casa, toda troca confirma: depois dela a bicicleta fica travada por 5 minutos (ver
 * `bicicleta.equipar`, no sim). Durante a espera, o clique só diz quanto falta.
 */
function pedirEquiparBicicleta(bici) {
  const info = estado.eu?.bicicleta ?? {};
  const falta = (info.trocaLiberaEm ?? 0) - Date.now();
  if (falta > 0) return toast(t('bicicleta.trocaEspera', { tempo: tempoDeEspera(falta) }));
  const min = Math.round((info.intervaloTrocaMs ?? 300_000) / 60_000);
  // Equipar: a bicicleta chega (luz, flutuação). Guardar: ela sai, sem cor, e você segue a pé.
  // A trava de 5 minutos é o selo — é a parte que pega quem troca por impulso.
  const rarEquipada = info.equipadaRar ?? null;
  const arteBici = (rar) => dlgArteArquivo(arteDaBicicleta(rar), 64, true);
  confirmar({
    titulo: t(bici ? 'bicicleta.trocarTitulo' : 'bicicleta.guardarTitulo'),
    texto: `
      ${dlgPalco(bici
        ? dlgAtor({
          arte: arteBici(bici.rar),
          nome: escapar(`${nomeBicicletaRaridade(bici.rar)} ${numeroDaBicicleta(bici.id)}`),
          classe: 'novo',
        })
        : `
          ${dlgAtor({
            arte: arteBici(rarEquipada),
            nome: escapar(rarEquipada ? `${nomeBicicletaRaridade(rarEquipada)} ${numeroDaBicicleta(info.equipada)}` : ''),
            classe: 'sai',
          })}
          ${dlgSeta()}
          ${dlgAtor({ arte: dlgArteTreinador(null, null, 64), nome: escapar(t('bicicleta.aPe')) })}`, 'ouro')}
      ${dlgFrase('', escapar(bici
        ? t('bicicleta.trocarTexto', { nome: `${nomeBicicletaRaridade(bici.rar)} ${numeroDaBicicleta(bici.id)}`, min })
        : t('bicicleta.guardarTexto', { min })))}
      ${dlgSelos(dlgSelo('relogio', escapar(t('bicicleta.seloTrava', { min })), 'info'))}`,
    rotuloSim: t(bici ? 'bicicleta.trocarSim' : 'bicicleta.guardarSim'),
    aoConfirmar: () => enviar({ t: 'bicicleta.equipar', bicicletaId: bici ? bici.id : null }),
  });
}

// ------------------------------------------------------ a aba Coleção da Bolsa

const ICONE_COLECAO = 'img:site/assets/ui/menu-depot.png';

/** Os filtros da aba, fora da função: sobrevivem a trocar de aba e voltar. */
const colbFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', soShiny: false };

/** Abre a Bolsa já na aba Coleção — o atalho da faixa de venda do Market. */
function abrirColecao() {
  estado.abaBolsa = 'colecao';
  abrirModal('bolsa');
}

/** Os pokémon da Coleção que estão no DEPOT — é o que a aba lista. */
function pokemonsDaColecao(colecao = conjuntoColecaoCliente()) {
  return (estado.eu?.pokemons ?? []).filter((pk) => pk.slot == null && colecao.has(pk.id));
}

function montarColecaoBolsa(host) {
  host.innerHTML = `
    <div class="colb dmpk">
      <div class="colb-topo">
        <span class="colb-ico" data-ico="${ICONE_COLECAO}" data-ico-px="34"></span>
        <p class="colb-intro">${t('colecao.intro')}</p>
      </div>
      <div class="dmpk-topo">
        <span class="cm-busca-caixa">${lupa()}<input id="colb-busca" class="cm-busca" type="search" autocomplete="off"
               maxlength="32" placeholder="${escapar(t('colecao.buscar'))}" value="${escapar(colbFiltro.busca)}"></span>
        <label class="auto-linha dmpk-shiny"><span>${t('amigos.anexarSoShiny')}</span>
          <input type="checkbox" id="colb-shiny"${colbFiltro.soShiny ? ' checked' : ''}></label>
        <span class="shl-conta" id="colb-conta"></span>
      </div>
      <div class="dmpk-filtros" id="colb-filtros"></div>
      <div class="mk-grade colb-grade" id="colb-grade"></div>
    </div>`;
  for (const el of host.querySelectorAll('[data-ico]')) pintarIcone(el);
  host.querySelector('#colb-filtros').appendChild(criarFiltrosSelect({
    tipo: colbFiltro.tipo,
    ordem: colbFiltro.ordem,
    ivMin: colbFiltro.ivMin,
    ordens: MK_POKEMON_ORDENS,
    ordemI18n: MK_POKEMON_ORDEM_I18N,
    onChange: (campo, valor) => {
      if (campo === 'ordem') colbFiltro.ordem = valor || 'padrao';
      else colbFiltro[campo] = valor;
      pintarGradeColecao();
    },
  }));
  host.querySelector('#colb-busca').oninput = (ev) => {
    colbFiltro.busca = ev.target.value;
    pintarGradeColecao();
  };
  host.querySelector('#colb-shiny').onchange = (ev) => {
    colbFiltro.soShiny = ev.target.checked;
    pintarGradeColecao();
  };
  const colb = host.querySelector('.colb');
  dobrarFiltrosNoCelular({
    campos: [colb.querySelector('.dmpk-shiny'), colb.querySelector('#colb-filtros')],
    botaoEm: colb.querySelector('.dmpk-topo'),
    host: colb,
  });
  dobrarNotaNoCelular(colb.querySelector('.colb-intro'));
  pintarGradeColecao();
}

/** A grade da aba Coleção: um card por pokémon, com "Devolver ao Depot". */
function pintarGradeColecao() {
  const grade = $('#colb-grade');
  if (!grade) return;
  const todos = pokemonsDaColecao();
  const busca = colbFiltro.busca.trim().toLowerCase();
  const piso = ivMinDoFiltro(colbFiltro.ivMin);
  const lista = ordenarMarketPokemon(
    todos.filter((k) => (!colbFiltro.soShiny || k.shiny) && depotPassaFiltros(k, busca, colbFiltro.tipo, piso)),
    colbFiltro.ordem,
  );
  const conta = $('#colb-conta');
  if (conta) conta.textContent = t('amigos.anexarConta', { n: num(lista.length), total: num(todos.length) });
  const rolagem = grade.scrollTop;
  grade.innerHTML = '';
  if (!lista.length) {
    grade.innerHTML = `<div class="aviso-modal">${t(todos.length ? 'depot.nenhumResultado' : 'colecao.vazia')}</div>`;
    return;
  }
  for (const pk of lista) {
    const pendente = colecaoPendente.has(pk.id);
    const bt = document.createElement('button');
    bt.type = 'button';
    bt.className = 'mk-acao colb-devolver';
    bt.innerHTML = `${SETA_COLECAO('depot')}<span>${t('colecao.devolverCurto')}</span>`;
    bt.title = t('colecao.devolver');
    bt.disabled = pendente;
    bt.onclick = () => moverColecao(pk.id, 'depot');
    const card = cardMarket({
      chave: `colb${pk.id}`,
      nome: `${pk.shiny ? prefixoShiny() : ''}${nomePkHtml(pk)}`,
      sub: t('mk.subPokemonCurta', { level: pk.level, onde: t('colecao.localColecao') }),
      atributos: selosAtributos(pk),
      preco: 0,
      acao: [bt],
      classe: 'colb-card',
      aoVerFicha: () => abrirFichaDoPokemon(pk),
    });
    card.querySelector('.mk-preco')?.remove();
    card.querySelector('.mk-ico').appendChild(spritePokemon(pk, 44));
    grade.appendChild(card);
  }
  grade.scrollTop = rolagem;
}

function pintarBolsaCorpo() {
  const host = $('#bolsa-corpo');
  if (!host || !estado.eu) return;
  const aba = estado.abaBolsa ?? 'treinador';
  // A Oferenda não é uma grade de cards: é a oficina inteira (roleta, casas e a lista do depot).
  // Sai ANTES do `innerHTML = ''` por duas razões, e as duas são visíveis na tela:
  //
  //   · durante o GIRO nada é remontado. O evento da oferenda chega no mesmo pacote que o delta
  //     de estado (os eventos primeiro), então remontar aqui arrancaria a roda no meio da volta;
  //   · com o esqueleto já montado, só as partes que mudam são repintadas. A bolsa se redesenha a
  //     cada drop da hunt, e remontar tudo a cada snapshot tiraria o cursor de quem está digitando
  //     na busca e a rolagem de quem está no meio da lista.
  if (aba === 'oferenda') {
    if ($('#ofr-casas')) {
      if (estado.ofrGirando) return;
      pintarOferendaPalco();
      return;
    }
    host.innerHTML = '';
    return montarOferenda(host);
  }
  // A Coleção segue a mesma lógica: o esqueleto (busca e filtros) fica, só a grade repinta.
  if (aba === 'colecao') {
    if ($('#colb-grade')) return pintarGradeColecao();
    host.innerHTML = '';
    return montarColecaoBolsa(host);
  }
  if (aba === 'skins') {
    estado.bolsaLixeira = false;
    return montarSkinsBolsa(host);
  }
  if (aba === 'chocadeira') {
    estado.bolsaLixeira = false;
    host.innerHTML = '';
    return montarChocadeira(host);
  }
  host.innerHTML = '';
  // A LIXEIRA só existe na aba Treinador: é lá que moram as bolas e as poções, que se acumulam
  // aos milhares e se repõem farmando. Item raro, pedra e loot ficam de fora de propósito — o
  // arrependimento ali é caro, e o servidor recusa mesmo que o pacote peça.
  if (aba === 'treinador') host.appendChild(barraDaLixeira());
  else estado.bolsaLixeira = false;

  const grade = document.createElement('div');
  grade.className = `mk-grade bolsa-grade${estado.bolsaLixeira ? ' bolsa-lixeira-on' : ''}`;
  const filtrados = entradasBolsa(estado.eu).filter((ent) => categoriaBolsa(ent) === aba);

  for (const ent of filtrados) {
    if (ent.tipo === 'bola') {
      grade.appendChild(cardBolsa({
        chave: `b${ent.bola.id}`,
        nome: ent.bola.nome,
        q: ent.q,
        montarIco: (cx) => cx.appendChild(iconeBola(ent.bola.id, 40)),
      }));
    } else if (ent.tipo === 'caixa') {
      grade.appendChild(cardCaixaDaBolsa(ent.caixa));
    } else if (ent.tipo === 'casa') {
      grade.appendChild(cardCasaDaBolsa(ent.casa));
    } else if (ent.tipo === 'bicicleta') {
      grade.appendChild(cardBicicletaDaBolsa(ent.bici));
    } else {
      const nome = nomeItem(ent.item ?? ent.id, ent.item?.name ?? `item ${ent.id}`);
      const ehXpShare = xpShareHeldAtivo() && ent.id === xpShareHeldItemId();
      const equipados = ent.xshEquipados ?? 0;
      const card = cardBolsa({
        chave: `i${ent.id}`,
        nome,
        q: ent.q,
        extraHtml: ehXpShare && equipados > 0
          ? `<em class="bolsa-xsh-eq">${escapar(t('xpshareheld.equipados', { n: equipados }))}</em>`
          : '',
        montarIco: (cx) => cx.appendChild(imgItem(ent.id, 40)),
      });

      // A NAME TAG abre a folha de apelidar. Mesmo desenho do Exp. Share — um card de bolsa que
      // é um BOTÃO —, porque é o mesmo tipo de objeto: o que se compra na Loja é o direito, e o
      // uso acontece aqui, com o pokémon escolhido na hora.
      if (nameTagAtiva() && ent.id === NAME_TAG_ID) {
        card.classList.add('bolsa-card-usavel');
        card.tabIndex = 0;
        card.title = t('nametag.usar');
        card.onclick = () => abrirNameTag();
        card.onkeydown = (ev) => {
          if (ev.key === 'Enter' || ev.key === ' ') {
            ev.preventDefault();
            abrirNameTag();
          }
        };
      }

      // O MYSTICTICKET abre a confirmação da Arena Mística; o OVO, a Chocadeira já com ele escolhido.
      // O mesmo desenho da Name Tag: um card de bolsa que é um botão.
      const usoRaro = ent.id === MYSTIC_TICKET_ID
        ? { titulo: t('mistico.usar'), acao: abrirUsoTicketMistico }
        : ehItemOvo(ent.id)
          ? { titulo: t('chocadeira.chocarEste'), acao: () => abrirChocadeiraComOvo(OVO_POR_ITEM.get(ent.id).id) }
          : null;
      if (usoRaro) {
        card.classList.add('bolsa-card-usavel');
        card.tabIndex = 0;
        card.title = usoRaro.titulo;
        card.onclick = () => usoRaro.acao();
        card.onkeydown = (ev) => {
          if (ev.key === 'Enter' || ev.key === ' ') {
            ev.preventDefault();
            usoRaro.acao();
          }
        };
      }

      if (ehXpShare) {
        card.classList.add('bolsa-card-usavel', 'bolsa-card-xpshare');
        if (ent.q < 1 && equipados > 0) card.classList.add('bolsa-card-xpshare-so-equip');
        card.tabIndex = 0;
        card.title = equipados > 0
          ? t('xpshareheld.gerenciarEquipados', { n: equipados })
          : t('xpshareheld.usar');
        card.onclick = () => abrirXpShareHeld();
        card.onkeydown = (ev) => {
          if (ev.key === 'Enter' || ev.key === ' ') {
            ev.preventDefault();
            abrirXpShareHeld();
          }
        };
      }
      grade.appendChild(card);
    }
  }

  // No modo lixeira TODO card da aba vira alvo, e o clique de usar (o Exp. Share) é trocado
  // pelo de jogar fora — dois destinos no mesmo toque seriam um pedido de clique errado.
  if (estado.bolsaLixeira) {
    for (const [i, ent] of filtrados.entries()) {
      const card = grade.children[i];
      if (!card) continue;
      const tipo = ent.tipo === 'bola' ? 'bola' : 'item';
      const id = ent.tipo === 'bola' ? ent.bola.id : ent.id;
      const nome = ent.tipo === 'bola' ? ent.bola.nome : nomeItem(ent.item ?? id, ent.item?.name ?? `#${id}`);
      card.classList.add('bolsa-card-lixo');
      card.classList.remove('bolsa-card-usavel');
      card.onkeydown = null;
      card.onclick = () => abrirLixeira({ tipo, id, nome, q: ent.q });
    }
  }

  if (!filtrados.length) grade.innerHTML = `<div class="aviso-modal">${t('bolsa.vazia')}</div>`;
  host.appendChild(grade);
}

/**
 * A barra da LIXEIRA, no topo da aba Treinador.
 *
 * Desligada, é um botão discreto. LIGADA, ela fica vermelha e diz o que está acontecendo — o modo
 * muda o que um toque num card faz, e modo destrutivo que não se anuncia é como o jogador perde
 * item sem entender o que aconteceu.
 */
function barraDaLixeira() {
  const barra = document.createElement('div');
  barra.className = `bolsa-lixeira${estado.bolsaLixeira ? ' on' : ''}`;
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = 'bolsa-lixeira-bt';
  bt.textContent = estado.bolsaLixeira ? t('bolsa.lixeira.sair') : t('bolsa.lixeira.abrir');
  bt.onclick = () => {
    estado.bolsaLixeira = !estado.bolsaLixeira;
    pintarBolsaCorpo();
  };
  barra.appendChild(bt);
  if (estado.bolsaLixeira) {
    const dica = document.createElement('span');
    dica.className = 'bolsa-lixeira-dica';
    dica.textContent = t('bolsa.lixeira.dica');
    barra.appendChild(dica);
  }
  return barra;
}

/**
 * A folha de "jogar fora": quanto, e a confirmação.
 *
 * O botão diz o NÚMERO que vai sumir ("Jogar fora 180.000 Poké Ball") em vez de um "Confirmar"
 * genérico. É irreversível, e o último texto que a pessoa lê antes do toque tem de ser o que ela
 * vai perder — não a palavra "confirmar".
 *
 * A quantidade que sobe é a do contador, e o servidor a prende no que ele VÊ na mochila: a tela
 * aqui não é a defesa, é a cortesia.
 */
function abrirLixeira({ tipo, id, nome, q }) {
  const { corpo, fechar } = folhaMercado(escapar(t('bolsa.lixeira.titulo')));
  // O palco do diálogo de jogo, no tom vermelho: o item → a quantidade → a lixeira. O saldo da
  // bolsa ("12 → 11") mora embaixo do item e anda junto com o contador.
  corpo.innerHTML = `
    ${dlgPalco(`
      ${dlgAtor({ arte: '<span class="dlg-ator-fig" data-lix-arte></span>', nome: escapar(nome), sub: '<span id="lix-sobra"></span>' })}
      ${dlgSeta({ rotulo: '<b class="lix-n" id="lix-n"></b>' })}
      ${dlgAtor({ arte: dlgArteHtml(dlgMedalha({ icone: 'lixeira', tom: 'perigo' })), nome: escapar(t('bolsa.lixeira.destino')), classe: 'lix-destino' })}`, 'perigo')}
    ${dlgAviso(escapar(t('bolsa.lixeira.aviso')))}
    <div class="lix-qtd"></div>
    <div class="cm-botoes">
      <button type="button" class="cm-acao sec" id="lix-nao">${escapar(t('confirmar.nao'))}</button>
      <button type="button" class="cm-acao lix-sim" id="lix-sim"></button>
    </div>`;
  // A arte é um NÓ (bola vem de outro atlas que o item), por isso entra depois do template.
  corpo.querySelector('[data-lix-arte]').appendChild(tipo === 'bola' ? iconeBola(id, 48) : imgItem(id, 48));

  const ctd = contador(q);
  const tudo = document.createElement('button');
  tudo.type = 'button';
  tudo.className = 'mk-max';
  tudo.textContent = t('bolsa.lixeira.tudo');
  tudo.onclick = () => {
    ctd.campo.value = q;
    ctd.campo.dispatchEvent(new Event('input'));
  };
  ctd.cx.appendChild(tudo);
  corpo.querySelector('.lix-qtd').appendChild(ctd.cx);

  const sim = corpo.querySelector('#lix-sim');
  const repintar = () => {
    const n = ctd.ler();
    sim.textContent = t('bolsa.lixeira.jogarFora', { n: num(n), nome });
    corpo.querySelector('#lix-n').textContent = `×${num(n)}`;
    corpo.querySelector('#lix-sobra').innerHTML = t('bolsa.lixeira.naBolsa', { de: num(q), para: num(Math.max(0, q - n)) });
  };
  ctd.campo.addEventListener('input', repintar);
  repintar();

  corpo.querySelector('#lix-nao').onclick = fechar;
  sim.onclick = () => {
    enviar({ t: 'bolsa.descartar', tipo, id, qtd: ctd.ler() });
    fechar();
  };
}

// ---------------------------------------------------------------- oferenda
//
// A OFERENDA: até cinco pokémon do depot viram UMA pedra de evolução, sorteada numa roleta que os
// TIPOS deles pintam. Dois Charmander deixam 40% do círculo de Fire Stone; um Gengar pinta
// Darkness e Venom ao mesmo tempo, porque é GHOST/POISON.
//
// ### Esta tela não decide nada
//
// A roleta que aparece aqui é uma PRÉVIA, montada pelo `montarRoleta` de `shared/oferenda.mjs` —
// o mesmo módulo que o sim usa para girar. Quem confere posse, quem sorteia e quem credita é o
// servidor; quando a resposta chega, ela vem com a roleta INTEIRA e o índice que saiu, e é essa
// roleta (não a prévia) que a agulha percorre. É o que mantém a animação honesta mesmo se o
// snapshot daqui estiver um segundo atrasado — um pokémon vendido noutra aba, por exemplo.
//
// ### O que NÃO pode entrar some da lista, com aviso
//
// A equipe, o ativo, quem segura Exp. Share e quem está no posto de uma Casa ficam fora da folha
// de escolha: escolher um deles só levaria à recusa do servidor. Para o jogador não procurar um
// pokémon que ele TEM e concluir "bugou", a folha diz quantos ficaram de fora e por quê (ver
// `abrirSeletorPokemonOferenda`).
//
// ### Auto Selecionar
//
// Enche as casas vazias com os pokémon de menor nota (N=), com uma régua mais dura que a da mão:
// ver `ofrAutoSelecionar` e `escolherPioresDaOferenda`.

const ofrCasas = () => Number(estado.oferenda?.casas) || OFERENDA_CASAS;

/**
 * Por que este pokémon não pode ser oferecido, como chave de i18n — ou `null` se pode.
 *
 * O CADEADO de venda não está aqui: ele é do Mercado NPC, onde existe um botão que apaga o depot
 * inteiro de uma vez. Aqui cada pokémon entra por uma escolha própria, num card que mostra a
 * ficha dele, e ainda há um diálogo no fim. Ver `validarOferenda`, no servidor, que é quem de
 * fato decide — isto aqui é só a tela adiantando a resposta.
 */
function ofrMotivoBloqueio(pk) {
  if (pk.id === estado.eu?.activeId) return 'oferenda.erroAtivo';
  if (pokemonNoPostoCasaXpShare(pk)) return 'oferenda.erroCasa';
  if (pk.slot != null) return 'oferenda.erroEquipe';
  if (ehXpShareHeldItem(pk.heldItemId)) return 'oferenda.erroXpShare';
  return null;
}

/**
 * Os escolhidos, NA ORDEM em que entraram nas casas, e só os que ainda existem.
 *
 * Quem saiu da coleção depois de entrar numa casa — anunciado no Mercado, vendido noutra aba —
 * sai da LISTA também, e não só do desenho. O mesmo vale para quem passou a ser recusado: ganhou
 * um Exp. Share, foi para a equipe ou para o posto de uma Casa. O giro manda estes ids ao
 * servidor, e um que ficasse para trás faria a oferenda inteira ser recusada até o jogador
 * esvaziar a roleta, sem nada na tela explicando por quê.
 */
function ofrEscolhidos() {
  const porId = new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  const sel = estado.ofrSel ?? [];
  const vivos = sel.filter((id) => porId.has(id) && !ofrMotivoBloqueio(porId.get(id)));
  if (vivos.length !== sel.length) estado.ofrSel = vivos;
  return vivos.map((id) => porId.get(id));
}

/**
 * As duas prateleiras de pedra, no formato que `montarRoleta` espera.
 *
 * A comum já chega pronta no welcome (`pedrasEvolucao`); a shiny vem como LISTA
 * (`shinyStone.pedras`, que é o que a aba do Professor Carvalho consome) e vira mapa aqui. O
 * `??=` guarda o resultado porque as duas são conteúdo fixo da sessão e a roleta é remontada a
 * cada snapshot — varrer dezoito entradas duas vezes por segundo por nada é desperdício.
 */
function ofrPedras() {
  estado.ofrShinyPorTipo ??= Object.fromEntries(
    (estado.shinyStone?.pedras ?? []).map((p) => [p.tipo, p.itemId]),
  );
  return { normal: estado.pedrasEvolucao, shiny: estado.ofrShinyPorTipo };
}

/** A prévia: a mesma conta do servidor, com os mapas de pedra que vieram no welcome. */
const ofrPrevia = () => montarRoleta(ofrEscolhidos(), ofrPedras());

/**
 * Um setor da roleta, em SVG.
 *
 * O caso de UMA fatia só (cinco Charmander = 100% Fire Stone) não passa por aqui: um arco de 0 a
 * 360° começa e termina no mesmo ponto e o navegador desenha NADA. Quem trata é `svgRoleta`,
 * com um `<circle>`.
 */
function ofrSetor(cx, cy, r, a0, a1) {
  const x0 = cx + r * Math.cos(a0);
  const y0 = cy + r * Math.sin(a0);
  const x1 = cx + r * Math.cos(a1);
  const y1 = cy + r * Math.sin(a1);
  return `M${cx} ${cy}L${x0.toFixed(2)} ${y0.toFixed(2)}`
    + `A${r} ${r} 0 ${a1 - a0 > Math.PI ? 1 : 0} 1 ${x1.toFixed(2)} ${y1.toFixed(2)}Z`;
}

/** A cor de uma fatia: a do tipo que a pediu (a primeira, quando são dois). */
const ofrCorDaFatia = (f) => (f.vazio ? 'var(--vao2)' : `var(--t-${f.tipos?.[0] ?? 'NORMAL'}, var(--mad))`);

/**
 * A classe da fatia. A SHINY leva contorno de ouro.
 *
 * Sem isso, uma roleta com Charmander e Shiny Charmander juntos teria duas fatias laranja
 * idênticas pagando coisas MUITO diferentes (Fire Stone e Fire Shiny Stone). A cor continua
 * sendo a do tipo — é assim que o jogador liga a fatia ao bicho —, e o ouro é o que o jogo já
 * usa para "isto é raro" em toda a interface.
 */
const ofrClasseDaFatia = (f) => (f.vazio ? 'ofr-fatia-vazia' : f.shiny ? 'ofr-fatia-shiny' : '');

/**
 * O ângulo do MEIO de uma fatia, em graus, contado do topo no sentido do relógio.
 *
 * É o número de que a animação precisa: a roda girada em `−meio` põe aquela fatia embaixo da
 * agulha. Os setores são desenhados a partir de `−90°` justamente para o zero daqui ser o topo.
 */
function ofrMeioDaFatia(roleta, indice) {
  let antes = 0;
  for (let i = 0; i < indice; i++) antes += roleta.fatias[i].peso;
  const meio = antes + (roleta.fatias[indice]?.peso ?? 0) / 2;
  return (meio / roleta.total) * 360;
}

/** Desenha a roda dentro da caixa e devolve o `<g>` que gira. */
function ofrDesenharRoda(caixa, roleta) {
  caixa.innerHTML = svgRoleta(roleta);
  return caixa.querySelector('.ofr-roda-gira');
}

/**
 * A roda desenhada, ou o círculo vazio de quando nada foi carregado ainda.
 *
 * A AGULHA vai por último no SVG (e fora do `<g>`): último quer dizer por cima, e fora quer
 * dizer que ela não gira — uma agulha que girasse junto nunca apontaria fatia nenhuma.
 */
function svgRoleta(roleta) {
  const R = 96;
  const c = 104;
  const agulha = `<polygon class="ofr-agulha" points="${c},${c - R + 16} ${c - 9},${c - R - 6} ${c + 9},${c - R - 6}"/>`;
  if (!roleta) {
    return `<svg class="ofr-roda" viewBox="0 0 208 208" aria-hidden="true">
      <circle cx="${c}" cy="${c}" r="${R}" class="ofr-roda-vazia"/>
      <circle cx="${c}" cy="${c}" r="${R}" class="ofr-roda-aro"/>
      ${agulha}
    </svg>`;
  }
  // Uma fatia só: círculo cheio. Ver o cabeçalho de `ofrSetor`.
  //
  // E com ele vai um RAIO, que não é enfeite: cinco Charmander pintam o círculo inteiro de Fire
  // Stone, e um disco liso girando é um disco parado. O raio é a única coisa na roda que diz ao
  // jogador que ela está de fato rodando.
  const corpo = roleta.fatias.length === 1
    ? `<circle cx="${c}" cy="${c}" r="${R}" fill="${ofrCorDaFatia(roleta.fatias[0])}"`
      + `${ofrClasseDaFatia(roleta.fatias[0]) ? ` class="${ofrClasseDaFatia(roleta.fatias[0])}"` : ''}/>`
      + `<path class="ofr-roda-raio" d="M${c} ${c}L${c} ${c - R}"/>`
    : roleta.fatias.map((f, i) => {
      let antes = 0;
      for (let k = 0; k < i; k++) antes += roleta.fatias[k].peso;
      const a0 = (antes / roleta.total) * Math.PI * 2 - Math.PI / 2;
      const a1 = ((antes + f.peso) / roleta.total) * Math.PI * 2 - Math.PI / 2;
      const classe = ofrClasseDaFatia(f);
      return `<path d="${ofrSetor(c, c, R, a0, a1)}" fill="${ofrCorDaFatia(f)}"`
        + `${classe ? ` class="${classe}"` : ''}/>`;
    }).join('');
  return `<svg class="ofr-roda" viewBox="0 0 208 208" aria-hidden="true">
    <g class="ofr-roda-gira">${corpo}</g>
    <circle cx="${c}" cy="${c}" r="${R}" class="ofr-roda-aro"/>
    <circle cx="${c}" cy="${c}" r="15" class="ofr-roda-eixo"/>
    ${agulha}
  </svg>`;
}

/** O esqueleto da oficina. Montado uma vez por abertura da aba; o resto repinta por dentro. */
function montarOferenda(host) {
  estado.ofrSel ??= [];
  const casas = ofrCasas();
  host.innerHTML = `
    <div class="ofr">
      <div class="ofr-palco">
        <div class="ofr-roda-caixa" id="ofr-roda-caixa"></div>
        <p class="ofr-chance" id="ofr-chance" aria-live="polite"></p>
        <div class="ofr-legenda" id="ofr-legenda"></div>
        <div class="ofr-botoes">
          <button type="button" class="ofr-girar" id="ofr-girar"></button>
          <button type="button" class="ofr-rapida" id="ofr-rapida"
                  title="${escapar(t('oferenda.rapidaDica'))}">⚡ ${escapar(t('oferenda.rapida'))}</button>
        </div>
        <div class="ofr-botoes ofr-botoes-lote">
          <button type="button" class="ofr-tudo" id="ofr-tudo"
                  title="${escapar(t('oferenda.tudoDica'))}">${escapar(t('oferenda.tudo'))}</button>
        </div>
        <p class="ofr-nota">${escapar(t('oferenda.nota', { casas }))}</p>
      </div>
      <div class="ofr-carga">
        <div class="ofr-carga-topo">
          <span class="ofr-carga-titulo" id="ofr-carga-titulo"></span>
          <span class="ofr-carga-acoes">
            <button type="button" class="ofr-auto" id="ofr-auto"
                    title="${escapar(t('oferenda.autoDica', { nota: virgula(String(notaAutoLockDoJogador())) }))}">${escapar(t('oferenda.auto'))}</button>
            <button type="button" class="ofr-limpar" id="ofr-limpar">${escapar(t('oferenda.limpar'))}</button>
          </span>
        </div>
        <div class="ofr-casas" id="ofr-casas"></div>
      </div>
    </div>`;

  $('#ofr-limpar').onclick = () => {
    if (estado.ofrGirando) return;
    estado.ofrSel = [];
    pintarOferendaPalco();
  };
  $('#ofr-girar').onclick = () => confirmarOferenda();
  $('#ofr-rapida').onclick = () => confirmarOferenda({ rapida: true });
  // O depot inteiro, sem os filtros da folha: eles são guardados entre aberturas, e um filtro
  // esquecido lá dentro não pode mudar o que este botão escolhe sem estar à vista.
  $('#ofr-auto').onclick = () => ofrAutoSelecionar(ofrCandidatos);
  $('#ofr-tudo').onclick = () => ofrLotePedir();

  pintarOferendaPalco();
}

/**
 * Uma casa da roleta.
 *
 * VAZIA é um botão de "+": ele abre o seletor, que é a mesma folha de escolha de pokémon do
 * Mercado e do anexo da DM (cards com sprite grande e a fileira P·IV·Q·N, busca, filtro de tipo,
 * IV mínimo e ordenação). Antes daqui a escolha era uma lista de linhas embaixo da roleta — dava
 * para saber QUAL pokémon, e não QUANTO ele vale, que é justamente o que decide quem se oferenda.
 *
 * CHEIA mostra o bicho do tamanho que dá para ver e os quatro selos, e clicar tira. É a mesma
 * informação do card do seletor, para a conferência final não exigir reabrir nada.
 */
function casaDaOferenda(i, pk) {
  const casas = ofrCasas();
  if (!pk) {
    const vazia = document.createElement('button');
    vazia.type = 'button';
    vazia.className = 'ofr-casa ofr-casa-vazia';
    vazia.dataset.casa = String(i + 1);
    vazia.title = t('oferenda.porDica');
    vazia.innerHTML = `<span class="ofr-casa-mais" aria-hidden="true">+</span>`
      + `<span class="ofr-casa-num">${i + 1}/${casas}</span>`;
    vazia.onclick = () => {
      if (estado.ofrGirando) return;
      abrirSeletorPokemonOferenda();
    };
    return vazia;
  }

  const casa = document.createElement('div');
  casa.className = 'ofr-casa ofr-casa-cheia';
  casa.dataset.id = pk.id;
  casa.dataset.casa = String(i + 1);
  casa.title = t('oferenda.tirarDica', { nome: nomeExibidoPokemon(pk) });
  // A faísca na casa não é enfeite: é o último aviso, antes de confirmar, de que ali dentro tem
  // um shiny — e o shiny paga noutra prateleira.
  if (pk.shiny) casa.classList.add('ofr-casa-shiny');
  if (naColecaoCliente(pk.id)) casa.classList.add('ofr-casa-trancada');

  const ico = document.createElement('div');
  ico.className = 'ofr-casa-ico';
  ico.appendChild(spritePokemon(pk, 52));
  casa.appendChild(ico);

  // Barras de cor do TIPO, logo abaixo do sprite. Não são os selos de texto de propósito: aqui a
  // cor não é para ler, é para casar o bicho com a FATIA que ele pintou na roda ao lado.
  const tipos = document.createElement('span');
  tipos.className = 'ofr-casa-tipos';
  tipos.innerHTML = (pk.tipos ?? [])
    .map((tp) => `<i class="ofr-casa-cor" style="background:var(--t-${tp}, var(--mad))"></i>`)
    .join('');
  casa.appendChild(tipos);

  const nome = document.createElement('div');
  nome.className = 'ofr-casa-nome';
  nome.textContent = nomeExibidoPokemon(pk);
  casa.appendChild(nome);

  const selos = document.createElement('div');
  selos.className = 'ofr-casa-selos';
  selos.innerHTML = selosAtributos(pk, { compacto: true });
  casa.appendChild(selos);

  // A QUINA de cima à direita é uma fileira, e não três coisas empilhadas no mesmo pixel: o ×
  // fica na ponta (é a ação) e as marcas entram à esquerda dele, na ordem em que importam. Eram
  // dois `::after` antes — e um elemento só tem UM, então shiny + trancado se anulavam.
  const quina = document.createElement('div');
  quina.className = 'ofr-casa-quina';
  if (pk.shiny) {
    const selo = document.createElement('span');
    selo.className = 'ofr-casa-marca';
    selo.textContent = '✨';
    selo.title = t('oferenda.shinyMarca');
    quina.appendChild(selo);
  }
  if (naColecaoCliente(pk.id)) {
    const cad = document.createElement('span');
    cad.className = 'ofr-casa-marca ofr-casa-colecao';
    cad.textContent = '★';
    cad.title = t('oferenda.trancadoAviso');
    quina.appendChild(cad);
  }

  const tirar = document.createElement('button');
  tirar.type = 'button';
  tirar.className = 'ofr-casa-tirar';
  tirar.textContent = '×';
  tirar.title = t('oferenda.tirarDica', { nome: nomeExibidoPokemon(pk) });
  quina.appendChild(tirar);
  casa.appendChild(quina);

  const sair = () => {
    if (estado.ofrGirando) return;
    ofrAlternar(pk.id);
  };
  casa.onclick = sair;
  tirar.onclick = (ev) => {
    ev.stopPropagation();
    sair();
  };
  return casa;
}

/** A roda, a chance, a legenda, as casas e o botão — tudo que depende da SELEÇÃO. */
function pintarOferendaPalco() {
  const caixa = $('#ofr-roda-caixa');
  if (!caixa) return;
  const casas = ofrCasas();
  const roleta = ofrPrevia();
  const n = roleta?.oferecidos ?? 0;

  // Durante o giro a roda NÃO é redesenhada: arrancar o `<g>` no meio da transição faria a
  // agulha pular para o resultado sem girar. A exceção é a caixa VAZIA — quando o jogador troca
  // de aba e volta durante os quatro segundos, o esqueleto é outro e sem isto ele ficaria sem
  // roda nenhuma até o giro terminar.
  if (!estado.ofrGirando || !caixa.querySelector('svg')) {
    ofrDesenharRoda(caixa, roleta);
    estado.ofrAngulo = 0;
  }

  const pct = Math.round((n / casas) * 100);
  $('#ofr-chance').textContent = n
    ? t('oferenda.chance', { n, casas, pct })
    : t('oferenda.chanceVazia', { casas });

  const legenda = $('#ofr-legenda');
  legenda.replaceChildren();
  for (const f of roleta?.fatias ?? []) {
    const linha = document.createElement('div');
    linha.className = `ofr-leg${f.vazio ? ' ofr-leg-vazio' : ''}`;
    linha.innerHTML = `
      <i class="ofr-leg-cor${f.shiny ? ' ofr-leg-cor-shiny' : ''}" style="background:${ofrCorDaFatia(f)}"></i>
      <span class="ofr-leg-nome">${f.shiny ? '✨ ' : ''}${escapar(f.vazio
        ? t('oferenda.fatiaVazia')
        : nomeItem(f.itemId ?? 0, f.nome))}</span>
      <b class="ofr-leg-pct">${Math.round(f.pct * 100)}%</b>`;
    if (!f.vazio && f.itemId) {
      linha.prepend(imgItem(f.itemId, 22));
      linha.title = t('oferenda.fatiaDica', { tipos: f.tipos.join(' · '), n: f.pokemons });
    } else if (f.vazio) {
      linha.title = t('oferenda.fatiaVaziaDica', { casas });
    }
    legenda.appendChild(linha);
  }

  const casasEl = $('#ofr-casas');
  casasEl.replaceChildren();
  const escolhidos = ofrEscolhidos();
  for (let i = 0; i < casas; i++) casasEl.appendChild(casaDaOferenda(i, escolhidos[i]));

  const titulo = $('#ofr-carga-titulo');
  if (titulo) titulo.textContent = t('oferenda.carga', { n, casas });
  const limpar = $('#ofr-limpar');
  if (limpar) limpar.disabled = !n || estado.ofrGirando;
  pintarBotaoAuto($('#ofr-auto'));

  const bt = $('#ofr-girar');
  bt.disabled = !n || estado.ofrGirando;
  bt.textContent = estado.ofrGirando ? t('oferenda.girando') : t('oferenda.girar', { n, casas });
  const rapida = $('#ofr-rapida');
  if (rapida) rapida.disabled = bt.disabled;
  // A folha de escolha fica aberta enquanto se enche a roleta; ela repinta junto para os cards
  // já escolhidos mostrarem o número da casa sem o jogador ter de fechar e reabrir.
  ofrRepintarSeletor?.();
}

/**
 * Os filtros do seletor, guardados FORA da função: quem enche cinco casas filtra uma vez só.
 *
 * Mesmo desenho do `dmPkFiltro` do anexo da DM, e pelo mesmo motivo — a folha é remontada a cada
 * escolha, e um filtro que morresse junto obrigaria a redigitar "tyranitar" cinco vezes.
 */
const ofrFiltro = { busca: '', tipo: '', ivMin: '', ordem: 'padrao', soShiny: false, local: 'todos' };

/** Repinta a grade da folha aberta, se houver uma. Trocada por `null` quando ela fecha. */
let ofrRepintarSeletor = null;

/**
 * O DEPOT, sem o ativo. `activeId` entra na conta à parte porque o ativo nem sempre ocupa uma vaga
 * de equipe.
 */
const ofrDoDepot = () => (estado.eu?.pokemons ?? []).filter(
  (k) => k.slot == null && k.id !== estado.eu?.activeId,
);

/** Quem pode ir para a roleta: o depot menos o que `ofrMotivoBloqueio` recusa. */
const ofrCandidatos = () => ofrDoDepot().filter((k) => !ofrMotivoBloqueio(k));

/**
 * A folha de escolha — a mesma do Mercado e do anexo da DM, com duas diferenças que a oferenda
 * exige:
 *
 * 1. **ela não fecha ao escolher.** São até cinco casas; fechar a cada clique custaria cinco
 *    aberturas e cinco rolagens até o mesmo ponto da lista. Escolher alterna (clicar de novo tira),
 *    o card mostra o NÚMERO da casa, e o contador do topo diz quanto falta.
 * 2. **o que não pode entrar NÃO aparece.** A equipe, o ativo, quem segura Exp. Share e quem está
 *    no posto de XP Share de uma Casa ficam fora da lista: escolher um deles só levaria à recusa
 *    do servidor, e um Exp. Share (50 💎) queimado por engano não tem volta. Para o jogador não
 *    procurar um pokémon que ele TEM e concluir "bugou", a folha diz quantos ficaram de fora e
 *    por quê. O cadeado do Mercado NPC não barra — ele vira selo no card.
 */
function abrirSeletorPokemonOferenda() {
  // SÓ O DEPOT, e só quem pode entrar. A equipe some sem aviso (ela é uma tela, com cinco vagas à
  // vista); os outros ocultos ganham a nota.
  const doDepot = ofrDoDepot();
  const todos = ofrCandidatos();
  const ocultos = doDepot.length - todos.length;
  if (!todos.length) return toast(t(ocultos ? 'oferenda.soOcultos' : 'oferenda.semDepot'));
  const casas = ofrCasas();
  const notaTeto = virgula(String(notaAutoLockDoJogador()));
  const { corpo, fechar } = folhaMercado(t('oferenda.seletorTitulo'));
  corpo.classList.add('dmpk', 'ofrpk');
  corpo.innerHTML = `
    <div class="dmpk-topo">
      <span class="cm-busca-caixa">${lupa()}<input id="ofrpk-busca" class="cm-busca" autocomplete="off"
             maxlength="32" placeholder="${escapar(t('oferenda.buscaPlaceholder'))}" value="${escapar(ofrFiltro.busca)}"></span>
      <label class="auto-linha dmpk-shiny"><span>${t('amigos.anexarSoShiny')}</span>
        <input type="checkbox" id="ofrpk-shiny"${ofrFiltro.soShiny ? ' checked' : ''}></label>
      <span class="shl-conta" id="ofrpk-conta"></span>
    </div>
    ${ocultos ? `<p class="cm-nota dim ofrpk-ocultos">${escapar(t('oferenda.ocultos', { n: ocultos }))}</p>` : ''}
    <div class="dmpk-filtros" id="ofrpk-filtros"></div>
    <div class="ofrpk-auto">
      <span class="ofrpk-auto-nota">${escapar(t('oferenda.autoLista', { nota: notaTeto }))}</span>
      <button type="button" class="ofr-auto" id="ofrpk-auto"
              title="${escapar(t('oferenda.autoDicaLista', { nota: notaTeto }))}">${escapar(t('oferenda.auto'))}</button>
    </div>
    <div class="mk-grade cm-pk-escolha-grade cm-rolagem" id="ofrpk-grade"></div>`;

  const grade = corpo.querySelector('#ofrpk-grade');
  const conta = corpo.querySelector('#ofrpk-conta');
  const botaoAuto = corpo.querySelector('#ofrpk-auto');
  /** Os ids que a grade está mostrando, na ordem da tela. É deles que o Auto Selecionar daqui escolhe. */
  let idsNaLista = [];

  function pintar() {
    const busca = ofrFiltro.busca.trim().toLowerCase();
    const piso = ivMinDoFiltro(ofrFiltro.ivMin);
    const sel = estado.ofrSel ?? [];
    const colecao = conjuntoColecaoCliente();
    const lista = ordenarMarketPokemon(
      todos.filter(
        (k) => (!ofrFiltro.soShiny || k.shiny) && passaLocal(k, ofrFiltro.local, colecao)
          && depotPassaFiltros(k, busca, ofrFiltro.tipo, piso),
      ),
      ofrFiltro.ordem,
    );
    idsNaLista = lista.map((k) => k.id);
    conta.textContent = t('oferenda.seletorConta', { n: sel.length, casas });
    pintarBotaoAuto(botaoAuto, { semLista: !lista.length });
    grade.innerHTML = '';
    if (!lista.length) {
      grade.innerHTML = `<div class="cm-vazio">${t('amigos.anexarVazio')}</div>`;
      return;
    }
    for (const k of lista) {
      const idx = sel.indexOf(k.id);
      const on = idx >= 0;
      const motivo = ofrMotivoBloqueio(k);
      const cheio = !on && !motivo && sel.length >= casas;
      // A COLEÇÃO não barra a oferenda, mas continua sendo informação que muda a decisão: quem
      // separou aquele bicho separou por algum motivo. A ★ do card (`cardPokemonEscolha`) é o
      // selo; a dica diz que ele entra mesmo assim.
      const card = cardPokemonEscolha(k, {
        colecao,
        aoVerFicha: () => abrirFichaDoPokemon(k),
        aoSelecionar: () => {
          if (estado.ofrGirando) return;
          if (motivo) return toast(t(motivo));
          if (cheio) return toast(t('oferenda.roletaCheia', { casas }));
          ofrAlternar(k.id); // repinta a roleta E esta grade (ver `ofrRepintarSeletor`)
        },
      });
      card.dataset.id = k.id;
      if (on) card.classList.add('ofrpk-on');
      if (motivo || cheio) card.classList.add('ofrpk-bloqueado');
      if (motivo) card.title = t(motivo);
      const marca = card.querySelector('.pk-colecao-marca');
      if (marca) marca.title = t('oferenda.trancadoAviso');
      if (on) {
        const marca = document.createElement('span');
        marca.className = 'ofrpk-ordem';
        marca.textContent = idx + 1;
        card.appendChild(marca);
      }
      grade.appendChild(card);
    }
  }

  corpo.querySelector('#ofrpk-filtros').appendChild(criarFiltrosSelect({
    tipo: ofrFiltro.tipo,
    ordem: ofrFiltro.ordem,
    ivMin: ofrFiltro.ivMin,
    // Sem "Equipe": a oferenda só aceita o depot.
    local: ofrFiltro.local,
    locais: LOCAIS_SEM_EQUIPE,
    ordens: MK_POKEMON_ORDENS,
    ordemI18n: MK_POKEMON_ORDEM_I18N,
    onChange: (campo, valor) => {
      if (campo === 'ordem') ofrFiltro.ordem = valor || 'padrao';
      else ofrFiltro[campo] = valor;
      pintar();
    },
  }));

  const campoBusca = corpo.querySelector('#ofrpk-busca');
  campoBusca.oninput = (ev) => {
    ofrFiltro.busca = ev.target.value;
    pintar();
  };
  corpo.querySelector('#ofrpk-shiny').onchange = (ev) => {
    ofrFiltro.soShiny = ev.target.checked;
    pintar();
  };
  dobrarFiltrosNoCelular({
    campos: [corpo.querySelector('.dmpk-shiny'), corpo.querySelector('#ofrpk-filtros')],
    botaoEm: corpo.querySelector('.dmpk-topo'),
    host: corpo,
  });
  // Os ids da lista viram os pokémon de AGORA na hora da escolha: entre o clique e a resposta do
  // servidor um deles pode ter sido vendido, ou ganhado um Exp. Share.
  botaoAuto.onclick = () => ofrAutoSelecionar(() => {
    const porId = new Map(ofrCandidatos().map((k) => [k.id, k]));
    return idsNaLista.map((id) => porId.get(id)).filter(Boolean);
  });

  // A grade repinta de fora quando a roleta muda — inclusive quando o jogador tira um pokémon
  // clicando na CASA, com a folha aberta por cima.
  ofrRepintarSeletor = () => {
    if (!corpo.isConnected) {
      ofrRepintarSeletor = null;
      return;
    }
    // Só a GRADE, e não a folha inteira: a barra de filtros sobrevive, e é isso que deixa o campo
    // de busca reagir ao dígito sem perder o foco.
    pintar();
  };
  repintarComAColecao(corpo, pintar);
  const fecharDeVez = () => {
    ofrRepintarSeletor = null;
    fechar();
  };
  corpo.closest('.cm-folha')?.querySelector('.cm-fechar')?.addEventListener('click', fecharDeVez);

  pintar();
  // No celular o foco abriria o teclado por cima da grade que ele acabou de pedir para ver.
  if (!movelAtivo()) campoBusca.focus();
}

/**
 * O botão Auto Selecionar (o da roleta e o da folha): apagado com a roleta cheia, durante o giro
 * e enquanto a resposta do servidor não volta. `semLista` é a folha com o filtro sem resultado.
 */
function pintarBotaoAuto(bt, { semLista = false } = {}) {
  if (!bt) return;
  const cheia = ofrEscolhidos().length >= ofrCasas();
  bt.disabled = cheia || semLista || !!estado.ofrGirando || !!estado.ofrAuto;
  bt.textContent = t(estado.ofrAuto ? 'oferenda.autoConferindo' : 'oferenda.auto');
}

/**
 * AUTO SELECIONAR: enche as casas vazias com os pokémon de menor nota (N=).
 *
 * `fonte()` diz de onde escolher: o depot inteiro (o botão da roleta) ou o que a folha de escolha
 * está mostrando (o botão de lá, que respeita a busca e os filtros; é assim que se pede "os cinco
 * piores de FIRE" para a roda ser toda de Fire Stone). Ela é chamada na RESPOSTA, e não no clique.
 *
 * A ida ao servidor existe por causa das duas equipes que moram no banco, a do PvP Ranqueado e a
 * do campeonato (ver `oferenda.protegidos` no sim). Sem resposta, NÃO escolhe nada: na dúvida,
 * não se põe um titular na roda. O cadeado e a vitrine são conhecidos aqui mesmo. O teto é a nota
 * do Auto Lock N do jogador: o botão só pega o que o Auto Lock deixaria destrancado. A regra do que
 * fica de fora e a ordem são de `escolherPioresDaOferenda`, em `shared/oferenda.mjs`.
 */
function ofrAutoSelecionar(fonte) {
  if (estado.ofrGirando || estado.ofrAuto) return;
  const casas = ofrCasas();
  if (ofrEscolhidos().length >= casas) return toast(t('oferenda.roletaCheia', { casas }));
  // Rede caída ou pedido recusado pelo limite: sem o prazo, o botão ficaria em "Conferindo…" até
  // um F5.
  estado.ofrAuto = { fonte, prazo: setTimeout(() => ofrAutoTerminar(undefined), 8000) };
  pintarOferendaPalco();
  enviar({ t: 'oferenda.protegidos' });
}

/** A resposta de `oferenda.protegidos`: a lista, `null` (a leitura falhou) ou nada (o prazo). */
function ofrAutoTerminar(protegidos) {
  const pedido = estado.ofrAuto;
  if (!pedido) return;
  clearTimeout(pedido.prazo);
  estado.ofrAuto = null;
  if (!Array.isArray(protegidos)) {
    toast(t('oferenda.autoFalhou'));
  } else if (!estado.ofrGirando) {
    const casas = ofrCasas();
    const ja = ofrEscolhidos();
    // O último pokémon da conta não sai (`validarOferenda`). Com a equipe fora do depot isto
    // quase nunca aperta, mas a tela não deve montar uma roda que o servidor vai recusar.
    const total = estado.eu?.pokemons?.length ?? 0;
    const vagas = Math.min(casas - ja.length, total - 1 - ja.length);
    const teto = notaAutoLockDoJogador();
    const novos = escolherPioresDaOferenda(pedido.fonte(), {
      nota: notaDoPokemon,
      notaMax: teto,
      vagas,
      jaEscolhidos: ja.map((pk) => pk.id),
      protegidos: [...protegidos, ...idsPokemonTravadoCliente(), ...(estado.eu?.vitrine ?? [])],
    });
    const nota = virgula(String(teto));
    if (!novos.length) {
      toast(t('oferenda.autoNada', { nota }));
    } else {
      estado.ofrSel = [...ja.map((pk) => pk.id), ...novos.map((pk) => pk.id)];
      toast(t(novos.length < vagas ? 'oferenda.autoParcial' : 'oferenda.autoOk', { n: novos.length, nota }));
    }
  }
  pintarOferendaPalco();
}

/** Põe ou tira um pokémon das casas. */

function ofrAlternar(id) {
  const sel = estado.ofrSel ?? [];
  estado.ofrSel = sel.includes(id) ? sel.filter((x) => x !== id) : [...sel, id];
  // Só o palco: ele já repinta a folha de escolha aberta, se houver uma.
  pintarOferendaPalco();
}

/**
 * Confirma antes de mandar. A oferenda NÃO tem volta: os pokémon são apagados.
 *
 * O diálogo diz os dois números que decidem — quantos vão e qual a chance de sair pedra. É de
 * propósito que a roleta pela metade tenha de ser confirmada assim: "50%" lido numa frase é mais
 * difícil de ignorar do que uma fatia cinza no canto da roda.
 *
 * A OFERENDA RÁPIDA (`rapida`) passa pelo mesmo diálogo: o que ela pula é a animação da roda, não
 * a confirmação — os pokémon somem do mesmo jeito. O sorteio também é o mesmo, e é do servidor;
 * a roda nunca decidiu nada, então pular o giro não muda a chance de coisa nenhuma.
 */
function confirmarOferenda({ rapida = false } = {}) {
  const roleta = ofrPrevia();
  if (!roleta || estado.ofrGirando) return;
  const casas = ofrCasas();
  const pct = Math.round((roleta.oferecidos / casas) * 100);
  // O SHINY ganha uma linha própria no diálogo. Ele já passou pelo cadeado (shiny nasce trancado
  // e a oferenda recusa trancado), mas destravar acontece noutra tela e noutro momento — a
  // última chance de ler "3 shinys" antes de eles sumirem tem de ser aqui.
  const shinys = ofrEscolhidos().filter((pk) => pk.shiny).length;
  // Os que vão, sem cor, de um lado; a chance de pedra do outro. Embaixo, a roleta em fileira:
  // cada pedra possível com a fatia dela, e o "nada" da casa vazia — a mesma conta da roda.
  const chances = roleta.fatias.map((f) => (f.vazio
    ? `<span class="dlg-bola vazio" title="${escapar(t('oferenda.fatiaVazia'))}">${dlgIcone('xis', 22)}<b>${Math.round(f.pct * 100)}%</b></span>`
    : `<span class="dlg-bola${f.shiny ? ' shiny' : ''}" title="${escapar(nomeItem(f.itemId ?? 0, f.nome ?? ''))}">
        <span data-dlg-item="${Number(f.itemId) || 0}" data-dlg-px="32"></span><b>${Math.round(f.pct * 100)}%</b>
      </span>`)).join('');
  const texto = `
    ${dlgPalco(`
      ${dlgAtor({ arte: dlgFila(ofrEscolhidos(), 34, 5), nome: escapar(t('oferenda.nPokemon', { n: roleta.oferecidos })), classe: 'sai' })}
      ${dlgSeta()}
      ${dlgAtor({
        arte: dlgArteHtml(dlgMedalha({ icone: 'interrogacao', tom: 'mega', px: 40 })),
        nome: `${pct}%`,
        sub: escapar(t('oferenda.chancePedra')),
        classe: 'novo',
      })}`, 'mega')}
    <div class="dlg-bolas">${chances}</div>
    ${dlgFrase('', escapar(t('oferenda.confirmarTexto', { n: roleta.oferecidos, pct })))}
    ${shinys ? dlgAviso(escapar(t('oferenda.confirmarShiny', { n: shinys })), { icone: 'brilho', classe: 'ofr-aviso-shiny' }) : ''}
    ${dlgSelos(dlgSelo('cadeado', escapar(t('dlg.semVolta')), 'perigo'))}`;
  confirmar({
    titulo: t('oferenda.confirmarTitulo'),
    texto,
    rotuloSim: t('oferenda.confirmarSim'),
    aoConfirmar: () => {
      // A trava é da TELA (o botão). Quem recusa de verdade é o limite por conta no gateway e a
      // fila de economia no sim; esta existe para o clique duplo não gastar duas oferendas.
      estado.ofrGirando = true;
      // Lido (e consumido) por `girarRoletaDaOferenda` quando a resposta chegar. A trava acima
      // garante uma oferenda por vez, então não há duas respostas para confundir o modo.
      estado.ofrRapida = rapida;
      // A folha de escolha não pode ficar aberta por cima da roda que vai girar.
      document.querySelector('.cm-folha')?.remove();
      ofrRepintarSeletor = null;
      pintarOferendaPalco();
      clearTimeout(estado.ofrTimeout);
      // Rede caída, ou mensagem recusada pelo limite: sem isto o botão ficaria desabilitado para
      // sempre e a aba só voltaria a funcionar depois de um F5.
      estado.ofrTimeout = setTimeout(() => ofrDestravar(), 12_000);
      // Os MESMOS que a roda e o diálogo mostraram — não a lista crua das casas.
      enviar({ t: 'oferenda.girar', pokemonIds: ofrEscolhidos().map((pk) => pk.id) });
    },
  });
}


/**
 * OFERENDAR TUDO DO DEPOT — o pedido, a prévia e a confirmação.
 *
 * O fluxo é o do Auto Selecionar, e de propósito: pede `oferenda.protegidos` (as duas equipes
 * que só o banco conhece), e só com a resposta na mão monta os grupos. Sem elas não se escolhe
 * nada — na dúvida não se põe um titular na roda, e aqui a roda tem cinquenta giros.
 *
 * A prévia sai de `montarLoteDaOferenda` + `previaDoLote`, o MESMO código que o sim vai rodar.
 * O cliente não manda id nenhum no `oferenda.tudo`: quem escolhe de verdade é o servidor, e esta
 * tela existe para o jogador saber o que vai acontecer antes de dizer sim.
 */
function ofrLotePedir() {
  if (estado.ofrGirando || estado.ofrAuto || estado.ofrLote) return;
  // Rede caída ou pedido recusado pelo limite: sem o prazo, o botão ficaria travado até um F5.
  estado.ofrLote = { prazo: setTimeout(() => ofrLoteTerminar(undefined), 8000) };
  pintarOferendaPalco();
  enviar({ t: 'oferenda.protegidos' });
}

/** A resposta: a lista, `null` (a leitura falhou) ou nada (o prazo venceu). */
function ofrLoteTerminar(protegidos) {
  const pedido = estado.ofrLote;
  if (!pedido) return;
  clearTimeout(pedido.prazo);
  estado.ofrLote = null;
  pintarOferendaPalco();
  if (!Array.isArray(protegidos)) return toast(t('oferenda.autoFalhou'));
  if (estado.ofrGirando) return;

  const teto = notaAutoLockDoJogador();
  const { grupos, fora, restantes } = montarLoteDaOferenda(ofrCandidatos(), {
    nota: notaDoPokemon,
    notaMax: teto,
    // A Coleção e a vitrine entram como protegidas aqui pela mesma razão do Auto Selecionar: o
    // servidor já as exclui por conta própria, e a prévia tem de enxergar o mesmo que ele.
    protegidos: [...protegidos, ...idsPokemonTravadoCliente(), ...(estado.eu?.vitrine ?? [])],
    totalNaConta: estado.eu?.pokemons?.length ?? 0,
  });
  if (!grupos.length) return toast(t('oferenda.loteNada', { nota: virgula(String(teto)) }));
  confirmarLoteDaOferenda(previaDoLote(grupos, ofrPedras()), fora, restantes);
}

/** "3 shiny, 2 refinados, 10 acima da sua régua" — o que ficou de fora, por motivo. */
function ofrLoteForaEmTexto(fora) {
  const rotulos = {
    shiny: 'oferenda.foraShiny', p5: 'oferenda.foraP5', item: 'oferenda.foraItem',
    refino: 'oferenda.foraRefino', tm: 'oferenda.foraTm', starter: 'oferenda.foraStarter',
    semPedra: 'oferenda.foraSemPedra', semNota: 'oferenda.foraSemNota',
    protegido: 'oferenda.foraProtegido', regua: 'oferenda.foraRegua',
  };
  const partes = Object.entries(fora ?? {})
    .filter(([motivo, n]) => n > 0 && rotulos[motivo])
    .sort((a, b) => b[1] - a[1])
    .map(([motivo, n]) => t(rotulos[motivo], { n }));
  return partes.length ? t('oferenda.loteFora', { lista: partes.join(', ') }) : '';
}

/**
 * O diálogo do lote: quantos vão, em quantos giros, o que se espera de cada pedra e o que ficou
 * de fora.
 *
 * Os números por pedra são ESPERANÇA, não promessa (ver `previaDoLote`), e é por isso que a
 * frase os apresenta como "esperado". O grupo incompleto do fim ganha linha própria e em
 * negrito: ele é o único que pode sumir com pokémon e não devolver nada, e descobrir isso
 * depois seria descobrir tarde.
 */
function confirmarLoteDaOferenda(previa, fora, restantes) {
  // O Depot sem cor de um lado, as pedras do outro — e embaixo cada pedra com o quanto se ESPERA
  // dela ("≈ 3,2"). É esperança, não promessa (ver `previaDoLote`), e o "≈" diz isso no número.
  const pedras = previa.pedras.map((x) => `
    <span class="dlg-bola" title="${escapar(nomeItem(x.itemId, x.nome))}">
      <span data-dlg-item="${Number(x.itemId) || 0}" data-dlg-px="32"></span><b>≈${escapar(virgula(x.esperado.toFixed(1)))}</b>
    </span>`).join('');
  const foraTxt = ofrLoteForaEmTexto(fora);
  const texto = `
    ${dlgPalco(`
      ${dlgAtor({
        arte: dlgArteHtml(dlgMedalha({ arte: '<span data-dlg-arquivo="site/assets/ui/menu-depot.png" data-dlg-px="40"></span>', tom: 'perigo' })),
        nome: escapar(t('oferenda.nPokemon', { n: previa.oferecidos })),
        sub: escapar(t('oferenda.nGiros', { n: previa.giros })),
        classe: 'sai',
      })}
      ${dlgSeta()}
      ${dlgAtor({
        arte: dlgArteHtml(dlgMedalha({ icone: 'interrogacao', tom: 'mega', px: 40 })),
        nome: escapar(t('oferenda.pedrasEsperadas')),
        classe: 'novo',
      })}`, 'mega')}
    ${pedras ? `<div class="dlg-bolas">${pedras}</div>` : ''}
    ${dlgFrase('', escapar(t('oferenda.loteResumo', { n: previa.oferecidos, giros: previa.giros })))}
    ${previa.parcial ? dlgAviso(escapar(t('oferenda.loteParcial', {
      n: previa.parcial.pokemons, pct: Math.round(previa.parcial.chance * 100),
    }))) : ''}
    ${foraTxt ? `<p class="dlg-nota">${escapar(foraTxt)}</p>` : ''}
    ${restantes > 0 ? `<p class="dlg-nota">${escapar(t('oferenda.loteRestantes', { n: restantes }))}</p>` : ''}
    ${dlgSelos(dlgSelo('cadeado', escapar(t('dlg.semVolta')), 'perigo'))}`;

  confirmar({
    titulo: t('oferenda.loteTitulo'),
    texto,
    rotuloSim: t('oferenda.loteSim'),
    aoConfirmar: () => {
      estado.ofrGirando = true;
      document.querySelector('.cm-folha')?.remove();
      ofrRepintarSeletor = null;
      pintarOferendaPalco();
      clearTimeout(estado.ofrTimeout);
      // Prazo maior que o do giro de um: são até cinquenta roletas e um `DELETE` de 250 linhas.
      estado.ofrTimeout = setTimeout(() => ofrDestravar(), 30_000);
      // Sem `pokemonIds`: a escolha é toda do servidor. Ver `oferenda.tudo`, no sim.
      enviar({ t: 'oferenda.tudo' });
    },
  });
}

/**
 * O resultado do lote: uma tela de prêmio só, com a soma.
 *
 * Quarenta telas de "você recebeu" seguidas seriam quarenta cliques para fechar — exatamente o
 * que o botão veio resolver. O degrau sobe para 4 (a faixa da Lendária) quando saiu alguma Shiny
 * Stone, pela mesma razão do giro de um.
 */
function revelarLoteDaOferenda(e) {
  ofrDestravar();
  estado.ofrSel = [];
  const pedras = e.pedras ?? [];
  const total = pedras.reduce((s, x) => s + (Number(x.qtd) || 0), 0);
  if (!total) {
    return mostrarRecompensa({
      nivel: -1,
      lead: t('oferenda.loteVazioLead', { giros: e.giros }),
      nome: t('oferenda.revelaVazioNome'),
      sub: escapar(t('oferenda.revelaVazioSub')),
    });
  }
  const temShiny = pedras.some((x) => x.shiny);
  toast(t('oferenda.loteToast', { n: total, giros: e.giros }));
  mostrarRecompensa({
    nivel: temShiny ? 4 : 2,
    faixa: temShiny ? faixaDaRaridade(4) : '',
    lead: t('oferenda.loteLead', { giros: e.giros, n: e.oferecidos }),
    nome: t('oferenda.lotePedras', { n: total }),
    sub: escapar(pedras.map((x) => `${x.qtd}x ${nomeItem(x.itemId, x.nome)}`).join(' . ')),
    arte: arteDeItemNaRecompensa(pedras[0].itemId),
  });
  if (e.restantes > 0) setTimeout(() => toast(t('oferenda.loteRestantes', { n: e.restantes })), 1500);
}

/** Solta a trava da tela — pela resposta, por um aviso do servidor, ou pelo prazo. */
function ofrDestravar() {
  if (!estado.ofrGirando) return;
  clearTimeout(estado.ofrTimeout);
  estado.ofrGirando = false;
  // Recusa ou prazo vencido: o modo morre com a tentativa, e a próxima começa do normal.
  estado.ofrRapida = false;
  if (estado.modalAberto === 'bolsa' && (estado.abaBolsa ?? 'treinador') === 'oferenda') {
    pintarOferendaPalco();
  }
}

/**
 * A resposta do servidor: redesenha a roda COM A ROLETA DELE e gira até o índice sorteado.
 *
 * Quatro voltas e para com o meio do setor sorteado embaixo da agulha. O ângulo final tem de ser
 * `−meio` módulo 360, e o inicial é onde a roda ficou da última vez — daí o `ajuste`: sem ele, a
 * segunda oferenda pararia deslocada da anterior, porque `ofrAngulo` não é múltiplo de 360.
 */
function girarRoletaDaOferenda(e) {
  clearTimeout(estado.ofrTimeout);
  const naTela = estado.modalAberto === 'bolsa' && (estado.abaBolsa ?? 'treinador') === 'oferenda';
  const caixa = $('#ofr-roda-caixa');
  const fim = () => {
    estado.ofrSel = [];
    ofrDestravar();
    revelarOferenda(e);
  };

  // Oferenda Rápida, aba fechada (ou trocada no meio do caminho) e quem pediu menos movimento: o
  // prêmio vem direto, sem a roda.
  const rapida = estado.ofrRapida;
  estado.ofrRapida = false;
  if (rapida || !naTela || !caixa || matchMedia('(prefers-reduced-motion: reduce)').matches) return fim();

  const roleta = { fatias: e.fatias ?? [], total: e.total ?? 0 };
  if (!roleta.total || !roleta.fatias.length || !roleta.fatias[e.indice]) return fim();

  const g = ofrDesenharRoda(caixa, roleta);
  if (!g) return fim();

  const inicio = estado.ofrAngulo ?? 0;
  const alvo = -ofrMeioDaFatia(roleta, e.indice);
  const ajuste = (((alvo - inicio) % 360) + 360) % 360;
  const destino = inicio + 360 * 4 + ajuste;
  estado.ofrAngulo = destino;

  g.style.transform = `rotate(${inicio}deg)`;
  // Dois quadros entre o ângulo inicial e o final: no mesmo quadro o navegador mescla as duas
  // mudanças de estilo numa só e a transição não acontece.
  requestAnimationFrame(() => requestAnimationFrame(() => {
    g.classList.add('girando');
    g.style.transform = `rotate(${destino}deg)`;
  }));

  let terminou = false;
  const acabar = () => {
    if (terminou) return;
    terminou = true;
    fim();
  };
  g.addEventListener('transitionend', acabar, { once: true });
  // Reserva: `transitionend` não dispara com a aba do navegador em segundo plano.
  setTimeout(acabar, 5200);
}

/** O ícone de um item, grande e pixelado, para a tela de "você recebeu". */
function arteDeItemNaRecompensa(itemId) {
  const el = imgItem(itemId, 128);
  el.classList.add('rc-img-item');
  return el;
}

/** A tela de "você recebeu" — a mesma do sorteio da Casa e da Bicicleta. */
function revelarOferenda(e) {
  if (!e.itemId) {
    return mostrarRecompensa({
      nivel: -1,
      lead: t('oferenda.revelaVazioLead'),
      nome: t('oferenda.revelaVazioNome'),
      sub: escapar(t('oferenda.revelaVazioSub')),
    });
  }
  const nome = nomeItem(e.itemId, e.pedra ?? '');
  toast(t('oferenda.ganhouToast', { nome }));
  mostrarRecompensa({
    // Nível 2 (rara) para a pedra comum: halo, mas não os raios da Lendária — ela é o prêmio
    // ESPERADO da mecânica. A SHINY STONE sobe para 4: ela custa cinco shinys (ou 10 fragmentos a
    // 0,0005% na Outland), e é a única coisa que esta tela entrega que merece o degrau de cima.
    nivel: e.pedraShiny ? 4 : 2,
    faixa: e.pedraShiny ? faixaDaRaridade(4) : '',
    lead: t('recompensa.recebeuUma'),
    nome,
    sub: e.tipos?.length ? selosDeTipo(e.tipos) : '',
    // 128 px PIXELADO, como a Casa e a Bicicleta fazem: o ícone de item tem 32 px de origem, e
    // ampliá-lo com a interpolação do navegador entrega uma pedra borrada no único quadro da
    // mecânica em que o jogador está olhando para ela.
    arte: arteDeItemNaRecompensa(e.itemId),
  });
}

// ------------------------------------------------------------------ market
//
// Três abas: comprar consumíveis, vender loot e vender pokémon. Cada linha é um card
// quadrado com ícone, preço, quantidade e a ação embaixo.
//
// Os preços aqui são só para MOSTRAR. Quem cobra e credita é o servidor, que recalcula
// tudo a partir do catálogo — o cliente só manda "quantos".

/** Categorias que o Market vende. Espelha COMPRAVEIS no servidor. */
const CATEGORIAS_COMPRAVEIS = new Set(['heal', 'revive']);

/** Texto do efeito de poção/revive no card de compra do Market. */
function subItemMarket(item) {
  // A porcentagem vem antes do valor fixo pelo mesmo motivo do `usarPocao` no servidor: é ela
  // que manda quando o item declara as duas coisas.
  if (item.category === 'heal' && item.healPct > 0) {
    return t('mk.curaPct', { pct: Math.round(item.healPct * 100) });
  }
  if (item.category === 'heal' && item.healAmount > 0) {
    return t('mk.curaHp', { hp: num(item.healAmount) });
  }
  if (item.category === 'revive' && item.revivePct != null) {
    return t('mk.revivePct', { pct: Math.round(item.revivePct * 100) });
  }
  return '';
}

const ABAS_MARKET = [
  { id: 'compra', nome: 'mk.compra' },
  { id: 'venda', nome: 'mk.venda' },
  { id: 'pokemons', nome: 'mk.vendaPokemons' },
];

/**
 * Menu lateral da aba de compra. `heal` e `revive` são as categorias do items.json.
 *
 * A categoria `bosses` ("Arena") saiu daqui: ela listava `ITENS_COMPRAVEIS` do servidor, que é
 * um Map declarado vazio e que nada preenche — a aba só sabia dizer "nada à venda aqui ainda".
 * O Map continua no servidor, porque `shop.buy` ainda o consulta para precificar; no dia em que
 * a entrada das arenas voltar a ser vendida, é este array que ganha a linha de volta.
 */
const CATEGORIAS_COMPRA = [
  { id: 'bolas', nome: 'mk.catBolas' },
  { id: 'potions', nome: 'mk.catPotions' },
  { id: 'revives', nome: 'mk.catRevives' },
  { id: 'caixas', nome: 'mk.caixas' },
  // Os MYSTERY EGGS da Chocadeira: P2, P3 e P4 (ver `pintarOvosNpc`).
  { id: 'ovos', nome: 'mk.catOvos' },
];

/** Mesma conta do `precoDoPokemon` no servidor — se mudar lá, muda aqui. */
function precoDoPokemon(p) {
  const esp = estado.especies.get(p.speciesId);
  return precoVendaPokemon(esp, p);
}

const moeda = (v) => `<span class="mk-moeda"><img src="${srcIcone(ICONE_OURO)}" alt="ouro">${num(v)}</span>`;

function renderMarket() {
  const aba = estado.abaMarket ?? 'compra';
  return `
    <div class="mk-topo">
      <div class="mk-abas">
        ${ABAS_MARKET.map(
          (a) => `<button class="mk-aba ${a.id === aba ? 'on' : ''}" data-aba="${a.id}">${t(a.nome)}</button>`,
        ).join('')}
      </div>
      <div class="mk-saldo">${moeda(estado.eu.gold)}</div>
    </div>
    <div id="mk-corpo"></div>`;
}

/**
 * Card quadrado. `extras` entra entre o preço e a ação (contador ou ficha do pokémon).
 *
 * `atributos` é a fileira P · IV · Q · Nota (`selosAtributos`), entre o subtítulo e o preço.
 * Decidir se um Charizard nv 70 vale mais que outro nv 70 depende desses quatro números, e
 * antes nenhum deles cabia no card: o jeito de descobrir era abrir o Depot noutra aba e
 * procurar o mesmo bicho.
 *
 * `aoVerFicha` pendura o (i) no canto e continua valendo para o que a fileira NÃO resume —
 * stats por linha, XP, refino e o IV separado por stat. É a mesma ficha que o Mercado da
 * Comunidade abre ao anunciar.
 */
function cardMarket({ chave, nome, sub, preco, acao, classe = '', travado = false, aoTravar = null, aoVerFicha = null, rotulo = null, atributos = '' }) {
  const el = document.createElement('div');
  el.className = `mk-card ${classe}${travado ? ' mk-travado' : ''}`;
  el.dataset.chave = chave;
  el.innerHTML = `
    <div class="mk-card-topo">
      <div class="mk-ico"></div>
    </div>
    <div class="mk-nome" title="${nome}">${nome}</div>
    <div class="mk-sub">${sub ?? ''}</div>
    ${atributos}
    <div class="mk-preco${rotulo ? ' aca-alvo' : ''}">${rotulo ?? moeda(preco)}</div>
    <div class="mk-rodape"></div>`;
  if (aoTravar) el.querySelector('.mk-card-topo').appendChild(botaoCadeadoVenda(travado, aoTravar));
  if (aoVerFicha) el.querySelector('.mk-card-topo').appendChild(botaoFichaVenda(aoVerFicha));
  el.querySelector('.mk-rodape').append(...acao);
  return el;
}

/** O (i) do card — abre a ficha completa do pokémon antes de decidir vender ou travar. */
function botaoFichaVenda(aoAbrir) {
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = 'mk-ficha-btn';
  bt.title = t('cm.verFicha');
  bt.textContent = 'i';
  bt.onclick = (ev) => {
    ev.stopPropagation();
    aoAbrir();
  };
  return bt;
}

/**
 * Card de escolha ao anunciar pokémon — o mesmo layout da aba Venda Pokémons do Market NPC,
 * sem cadeado: clicar no card escolhe; só o (i) abre a ficha.
 */
function cardPokemonEscolha(pk, { aoSelecionar, aoVerFicha, colecao = null }) {
  const naCol = pk.slot == null && (colecao ? colecao.has(Number(pk.id)) : naColecaoCliente(pk.id));
  const card = cardMarket({
    chave: `cm-sel${pk.id}`,
    nome: `${pk.shiny ? prefixoShiny() : ''}${nomePkHtml(pk)}`,
    sub: t('mk.subPokemonCurta', {
      level: pk.level,
      onde: pk.slot != null ? t('mk.equipe') : naCol ? t('colecao.localColecao') : t('painel.depot'),
    }),
    atributos: selosAtributos(pk),
    preco: 0,
    acao: [],
    classe: `cm-pk-escolha${pk.slot != null ? ' mk-card-equipe' : ''}`,
    aoVerFicha,
  });
  card.querySelector('.mk-preco')?.remove();
  card.querySelector('.mk-rodape')?.remove();
  card.querySelector('.mk-ico').appendChild(spritePokemon(pk, 44));
  // A ★ de quem está na Coleção — em TODO seletor que usa este card. `colecao` é o Set que a
  // folha já montou para o filtro; sem ele, a pergunta vai à lista crua.
  marcaColecao(card, pk, colecao);
  card.tabIndex = 0;
  card.setAttribute('role', 'button');
  const escolher = (ev) => {
    if (ev.target.closest('.mk-ficha-btn')) return;
    aoSelecionar(ev);
  };
  card.addEventListener('click', escolher);
  card.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault();
      escolher(ev);
    }
  });
  return card;
}

function idsLootTravadoCliente() {
  return estado.eu?.automation?.lootTravado ?? [];
}
function idsPokemonTravadoCliente() {
  return estado.eu?.automation?.pokemonTravado ?? [];
}
function itemLootTravadoCliente(id) {
  return idsLootTravadoCliente().includes(Number(id));
}
function pokemonVendaTravadoCliente(id) {
  const n = Number(id);
  return idsPokemonTravadoCliente().some((x) => Number(x) === n);
}

/** Cadeado no canto do card — tranca o item/pokémon contra venda individual e em lote. */
function alternarTravaLootCliente(id) {
  if (!estado.eu?.automation) return;
  const arr = (estado.eu.automation.lootTravado ??= []);
  const n = Number(id);
  const i = arr.indexOf(n);
  if (i >= 0) arr.splice(i, 1);
  else arr.push(n);
  estado.assinaturaMarket = assinaturaMarket();
  if ($('#mk-corpo')) pintarMarket();
  enviar({ t: 'shop.lockLoot', id: n });
}

// ------------------------------------------------------------------ a Coleção
//
// O antigo cadeado de venda, com outra cara. A lista é a mesma (`automation.pokemonTravado`) e a
// regra também: pokémon da Coleção não é vendido ao NPC. Na tela, ele SAI da aba de venda e vai
// para a aba Coleção do Depot (e da Bolsa); nos seletores ele continua, com a ★, e um filtro
// "Local" separa Equipe, Depot e Coleção.
//
// Mover é otimista: o card muda na hora e o pedido vai ao servidor. A resposta (`k: 'colecao'`)
// traz o estado REAL do pokémon e é ela que manda — inclusive na recusa (a espera de 3 s por
// pokémon). Se nada voltar em `COLECAO_PRAZO_MS` (o gateway recusou a rajada sem dizer qual
// pacote), a mudança se desfaz sozinha. E um snapshot que chegue no meio do caminho não apaga o
// que ainda está pendente (`reaplicarColecaoPendente`).

const COLECAO_PRAZO_MS = 6000;
/** id → { dentro, timer }: os pedidos que ainda não tiveram resposta. */
const colecaoPendente = new Map();
/** As folhas de escolha abertas que desenham a ★ ou filtram por local. Repintam quando a Coleção muda. */
const repintesDaColecao = new Set();

const naColecaoCliente = (id) => pokemonVendaTravadoCliente(id);
/** Os ids da Coleção num `Set`, para as listas que perguntam por centenas de pokémon. */
const conjuntoColecaoCliente = () => new Set(idsPokemonTravadoCliente().map(Number));

/** Onde o pokémon está, para o filtro "Local": `equipe`, `colecao` ou `depot`. */
function localDoPokemon(pk, colecao = conjuntoColecaoCliente()) {
  if (pk.slot != null) return 'equipe';
  return colecao.has(Number(pk.id)) ? 'colecao' : 'depot';
}

/** `local` vazio ou `todos` deixa passar qualquer um. */
const passaLocal = (pk, local, colecao) => !local || local === 'todos' || localDoPokemon(pk, colecao) === local;

function marcarColecaoLocal(id, dentro) {
  const auto = estado.eu?.automation;
  if (!auto) return;
  const arr = (auto.pokemonTravado ??= []);
  const n = Number(id);
  const i = arr.findIndex((x) => Number(x) === n);
  if (dentro && i < 0) arr.push(n);
  if (!dentro && i >= 0) arr.splice(i, 1);
}

/** Leva o pokémon para a Coleção (`para: 'colecao'`) ou de volta ao Depot (`'depot'`). */
function moverColecao(id, para) {
  const n = Number(id);
  if (!estado.eu?.automation || colecaoPendente.has(n)) return;
  const antes = naColecaoCliente(n);
  const dentro = para === 'colecao';
  if (antes === dentro) return;
  marcarColecaoLocal(n, dentro);
  const timer = setTimeout(() => {
    if (colecaoPendente.get(n)?.timer !== timer) return;
    colecaoPendente.delete(n);
    marcarColecaoLocal(n, antes);
    repintarColecao();
  }, COLECAO_PRAZO_MS);
  colecaoPendente.set(n, { dentro, timer });
  enviar({ t: 'colecao.mover', pokemonId: n, para });
  repintarColecao();
}

/** A resposta do servidor para um pedido de Coleção: o estado de verdade daquele pokémon. */
function aoResponderColecao(e) {
  const n = Number(e.id);
  const pend = colecaoPendente.get(n);
  if (pend) {
    clearTimeout(pend.timer);
    colecaoPendente.delete(n);
  }
  if (e.recusado && !estado.eu?.pokemons?.some((pk) => pk.id === n)) return repintarColecao();
  marcarColecaoLocal(n, !!e.naColecao);
  repintarColecao();
}

/** Um snapshot que chega com o `automation` do servidor não desfaz o que ainda está a caminho. */
function reaplicarColecaoPendente() {
  for (const [id, { dentro }] of colecaoPendente) marcarColecaoLocal(id, dentro);
}

/** Tudo o que desenha a Coleção, se estiver aberto. */
function repintarColecao() {
  estado.assinaturaMarket = assinaturaMarket();
  if ($('#mk-corpo')) pintarMarket();
  if ($('#centro-depot-modal') && !$('#centro-depot-modal').classList.contains('hidden')) montarDepotModal();
  if (estado.modalAberto === 'bolsa' && (estado.abaBolsa ?? 'treinador') === 'colecao') pintarBolsa();
  for (const fn of [...repintesDaColecao]) fn();
}

/**
 * Registra o repinte de uma folha de escolha enquanto ela estiver na tela. O registro se desfaz
 * sozinho quando o corpo da folha sai do documento.
 */
function repintarComAColecao(corpo, fn) {
  const repinte = () => {
    if (!corpo.isConnected) {
      repintesDaColecao.delete(repinte);
      return;
    }
    fn();
  };
  repintesDaColecao.add(repinte);
}

/**
 * A setinha da Coleção. `para` é o destino: `colecao` na aba de venda e no Depot, `depot` na
 * aba Coleção. O desenho é um SVG (e não um caractere) para sair igual em qualquer fonte.
 */
const SETA_COLECAO = (para) => `<svg class="seta-colecao${para === 'depot' ? ' volta' : ''}" viewBox="0 0 16 16" width="14" height="14" aria-hidden="true">
  <path d="M2 8h8.5M7.5 4.5 11 8l-3.5 3.5" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="square"/>
  <path d="M13.5 2.5v11" fill="none" stroke="currentColor" stroke-width="2.4"/>
</svg>`;

function botaoColecao(para, aoMover, { classe = 'mk-colecao' } = {}) {
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = `${classe}${para === 'depot' ? ' volta' : ''}`;
  const dica = t(para === 'depot' ? 'colecao.devolver' : 'colecao.enviar');
  bt.title = dica;
  bt.setAttribute('aria-label', dica);
  bt.innerHTML = SETA_COLECAO(para);
  bt.onclick = (ev) => {
    ev.stopPropagation();
    aoMover();
  };
  return bt;
}

/** A ★ em HTML, para as listas que se montam por texto (linhas do ginásio e das equipes). */
const htmlMarcaColecao = (pk, colecao) =>
  (colecao ? colecao.has(Number(pk.id)) : naColecaoCliente(pk.id))
    ? ` <span class="pl-colecao-marca" title="${escapar(t(pk.slot != null ? 'colecao.marcaEquipe' : 'colecao.marca'))}">★</span>`
    : '';

/** A ★ de quem está na Coleção, para os cards dos seletores. */
function marcaColecao(card, pk, colecao) {
  const dentro = colecao ? colecao.has(Number(pk.id)) : naColecaoCliente(pk.id);
  card.querySelector('.pk-colecao-marca')?.remove();
  if (!dentro) return;
  const marca = document.createElement('span');
  marca.className = 'pk-colecao-marca';
  marca.textContent = '★';
  marca.title = t(pk.slot != null ? 'colecao.marcaEquipe' : 'colecao.marca');
  card.appendChild(marca);
}

function botaoCadeadoVenda(travado, aoToggle) {
  const bt = document.createElement('button');
  bt.type = 'button';
  bt.className = 'mk-cadeado' + (travado ? ' on' : '');
  bt.title = t(travado ? 'mk.destravar' : 'mk.travar');
  bt.textContent = travado ? '🔒' : '🔓';
  bt.onclick = (ev) => {
    ev.stopPropagation();
    aoToggle();
  };
  return bt;
}

/** Contador − / campo / + . Devolve o bloco e uma função que lê a quantidade atual. */
function contador(maximo) {
  const cx = document.createElement('div');
  cx.className = 'mk-qtd';
  cx.innerHTML = `
    <button class="mk-passo" data-passo="-1" type="button">−</button>
    <input type="number" value="1" min="1" ${maximo ? `max="${maximo}"` : ''} inputmode="numeric">
    <button class="mk-passo" data-passo="1" type="button">+</button>`;
  const campo = cx.querySelector('input');
  const limitar = (n) => Math.max(1, Math.min(maximo || 9999, Math.floor(n) || 1));

  cx.onclick = (ev) => {
    const b = ev.target.closest('.mk-passo');
    if (!b) return;
    campo.value = limitar(Number(campo.value) + Number(b.dataset.passo));
    campo.dispatchEvent(new Event('input'));
  };
  campo.onblur = () => (campo.value = limitar(Number(campo.value)));
  return { cx, campo, ler: () => limitar(Number(campo.value)) };
}

/** Quantos dá para comprar com o ouro atual (teto 9999, igual ao servidor). */
function maxCompraPorOuro(precoUnit) {
  if (!(precoUnit > 0)) return 0;
  return Math.min(9999, Math.floor((estado.eu?.gold ?? 0) / precoUnit));
}

/** Quantas unidades dá para comprar no Mercado da Comunidade — saldo (ouro ou gema) × estoque. */
function maxCompraMercado(precoUnit, moeda, estoque) {
  if (!(precoUnit > 0) || !(estoque > 0)) return 0;
  const saldo = moeda === 'orb' ? (estado.eu?.orbs ?? 0) : (estado.eu?.gold ?? 0);
  return Math.min(estoque, Math.floor(saldo / precoUnit));
}

/** Contador da aba Compra — inclui o atalho Máx na mesma linha do − / +. */
function contadorCompra(precoUnit) {
  const maxQtd = maxCompraPorOuro(precoUnit);
  const ctd = contador(maxQtd > 0 ? maxQtd : 1);
  const btnMax = document.createElement('button');
  btnMax.type = 'button';
  btnMax.className = 'mk-max';
  btnMax.textContent = t('mk.max');
  btnMax.title = t('mk.maxTitulo');
  btnMax.disabled = maxQtd < 1;
  btnMax.onclick = () => {
    if (maxQtd < 1) return;
    ctd.campo.value = maxQtd;
    ctd.campo.dispatchEvent(new Event('input'));
  };
  ctd.cx.appendChild(btnMax);
  return ctd;
}

/** Botão de ação com o total embutido, que acompanha o contador. */
function acaoComTotal(rotulo, precoUnit, ctd, { validarOuro = false } = {}) {
  const total = document.createElement('div');
  total.className = 'mk-total';
  const bt = document.createElement('button');
  bt.className = 'mk-acao';
  bt.textContent = rotulo;

  const repintar = () => {
    const q = ctd.ler();
    total.innerHTML = `total ${moeda(precoUnit * q)}`;
    if (validarOuro) bt.disabled = precoUnit * q > (estado.eu?.gold ?? 0);
  };
  ctd.campo.addEventListener('input', repintar);
  repintar();
  return { total, bt };
}

// ------------------------------------------------------- as CAIXAS do Market
//
// O ralo de Coins: duas caixas que trocam ouro (e, na VIP, diamante) por sorte.
//
// UM prêmio por caixa, e todos os prêmios dividem os mesmos 100% — é o que deixa a tabela honesta
// (a porcentagem ao lado de cada linha é a chance DELA sair) e a abertura legível. A tabela e o
// sorteio moram em `shared/caixas-npc.mjs`: esta tela mostra exatamente o número que o servidor
// vai usar, antes do clique, no botão "Ver Conteúdo". Caixa que esconde porcentagem é outro tipo
// de produto, e não é o que este jogo quer ser.
//
// O card é o card do Market — mesmo `cardMarket`, mesmo contador, mesmo botão de ação. A caixa é
// um produto da loja, e produto da loja aqui tem uma forma só; o que a distingue é a arte e o
// "Ver Conteúdo" no rodapé.

const nomeDaCaixa = (id) => t(id === 'vip' ? 'caixa.nome.vip' : 'caixa.nome.free');

/** Nome de um prêmio (bola ou item), para o conteúdo e para o resultado. */
function nomeDoPremio(premio) {
  if (premio.tipo === 'bola') {
    return (estado.catalogoBolas ?? []).find((b) => b.id === premio.id)?.nome ?? `#${premio.id}`;
  }
  const item = estado.itens.get(premio.id);
  return nomeItem(item, item?.name ?? `#${premio.id}`);
}

/** O ícone de um prêmio, no tamanho pedido. */
function iconeDoPremio(premio, px = 28) {
  if (premio.tipo === 'bola') return iconeBola(premio.id, px);
  const src = iconeItem(premio.id);
  return src ? iconeArquivo(src, px) : document.createElement('span');
}

/**
 * "22,3%" ou "0,08%" — o mesmo número que o servidor sorteia.
 *
 * Duas casas abaixo de 1% porque é ali que moram os lendários: com uma casa, o fragmento de chave
 * e a peça de TM virariam o mesmo "0,1%", e eles não têm a mesma chance.
 */
const pctDaChance = (c) => {
  const v = Math.max(0, Number(c) || 0) * 100;
  const casas = v >= 1 ? 1 : 2;
  return `${v.toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas })}%`;
};

/** O preço de uma caixa como o Market escreve preço: o ouro, e o diamante ao lado quando há. */
const precoDaCaixa = (coins, diamantes) => moeda(coins)
  + (diamantes ? `<span class="cxm-dia"><img src="${ICONE_DIAMANTE}" alt="">${num(diamantes)}</span>` : '');

/**
 * O contador do card. O "Máx" enche com o que o BOLSO paga — o mesmo que `contadorCompra` faz no
 * resto do Market —, limitado pelo teto de 9999 que o jogo usa para tudo.
 *
 * Quem tem três bilhões de Coins põe três mil caixas num clique, que é o ponto da feature: ela
 * existe para queimar o ouro parado, e obrigar a clicar trezentas vezes só faria o ralo entupir.
 */
function contadorDeCaixa(caixa) {
  const porOuro = Math.floor((estado.eu?.gold ?? 0) / caixa.coins);
  const porDia = caixa.diamantes ? Math.floor((estado.eu?.diamonds ?? 0) / caixa.diamantes) : QTD_MAX_CAIXA;
  const cabe = Math.min(QTD_MAX_CAIXA, porOuro, porDia);
  const ctd = contador(Math.max(1, cabe));
  const btMax = document.createElement('button');
  btMax.type = 'button';
  btMax.className = 'mk-max';
  btMax.textContent = t('mk.max');
  btMax.title = t('mk.maxTitulo');
  btMax.disabled = cabe < 1;
  btMax.onclick = () => {
    if (cabe < 1) return;
    ctd.campo.value = cabe;
    ctd.campo.dispatchEvent(new Event('input'));
  };
  ctd.cx.appendChild(btMax);
  return ctd;
}

/**
 * O total e o botão Abrir, no formato do Market (`acaoComTotal`) — com duas diferenças: o total
 * pode ter diamante, e o botão pode estar trancado por não ser VIP.
 */
function acaoDeCaixa(caixa, ctd) {
  const vipOk = !caixa.vip || souVip();
  const total = document.createElement('div');
  total.className = 'mk-total';
  const bt = document.createElement('button');
  bt.className = 'mk-acao';
  bt.type = 'button';

  const repintar = () => {
    const c = custoDaCaixa(caixa.id, ctd.ler());
    total.innerHTML = `total ${precoDaCaixa(c.coins, c.diamantes)}`;
    const paga = (estado.eu?.gold ?? 0) >= c.coins && (estado.eu?.diamonds ?? 0) >= c.diamantes;
    bt.textContent = vipOk ? t('caixa.abrir') : t('caixa.soVip');
    bt.disabled = !vipOk || !paga || estado.caixaAbrindo;
  };
  ctd.campo.addEventListener('input', repintar);
  repintar();

  bt.onclick = () => {
    if (estado.caixaAbrindo || bt.disabled) return;
    estado.caixaAbrindo = true;
    bt.disabled = true;
    enviar({ t: 'caixa.npc.abrir', caixaId: caixa.id, qtd: ctd.ler() });
    // Sem resposta (socket caído), o botão volta sozinho — a mesma trava do desafio de ginásio.
    setTimeout(() => {
      if (!estado.caixaAbrindo) return;
      estado.caixaAbrindo = false;
      if (estado.modalAberto === 'market') pintarMarket();
    }, 10_000);
  };
  return { total, bt };
}

function pintarCaixasNpc(grade) {
  for (const caixa of CAIXAS) {
    const vipOk = !caixa.vip || souVip();
    const ctd = contadorDeCaixa(caixa);
    const { total, bt } = acaoDeCaixa(caixa, ctd);

    // O "Ver Conteúdo" é o botão que a caixa quer que seja clicado PRIMEIRO: ninguém deveria
    // gastar um milhão sem ter visto a tabela. Por isso ele abre o rodapé, acima do contador.
    const ver = document.createElement('button');
    ver.type = 'button';
    ver.className = 'cxm-ver';
    ver.textContent = t('caixa.verConteudo');
    ver.onclick = () => abrirConteudoDaCaixa(caixa);

    const card = cardMarket({
      chave: `caixa-${caixa.id}`,
      nome: escapar(nomeDaCaixa(caixa.id)),
      sub: escapar(t(caixa.vip ? 'caixa.sub.vip' : 'caixa.sub.free')),
      preco: caixa.coins,
      rotulo: precoDaCaixa(caixa.coins, caixa.diamantes),
      classe: `cxm-card cxm-${caixa.id}${vipOk ? '' : ' cxm-travada'}`,
      acao: [ver, ctd.cx, total, bt],
    });
    // O ícone é uma PLATE do pokesprite, uma por caixa: dois cards com o mesmo desenho obrigariam
    // a ler para escolher.
    card.querySelector('.mk-ico').appendChild(iconeArquivo(`/img/caixas/${caixa.plate}.png`, 40));
    grade.appendChild(card);
  }
}

/** A ordem em que o conteúdo é mostrado: o que a pessoa quer ver primeiro. */
const TIERS_NA_TELA = [TIER_LENDARIO, TIER_RARO, TIER_COMUM];

/**
 * "Ver Conteúdo": TUDO o que pode sair, item por item, com a chance de cada um.
 *
 * Agrupado por raridade e com a soma de cada grupo no título — é a leitura que interessa antes de
 * clicar ("quanto dessa caixa é lendário?"), e ela não existiria numa lista corrida.
 */
function abrirConteudoDaCaixa(caixa) {
  const { corpo } = folhaMercado(escapar(nomeDaCaixa(caixa.id)));
  corpo.innerHTML = `
    <p class="cm-nota">${escapar(t('caixa.conteudoNota'))}</p>
    <div class="cxm-conteudo"></div>`;
  const lista = corpo.querySelector('.cxm-conteudo');
  const tabela = conteudoDaCaixa(caixa.id);

  for (const tier of TIERS_NA_TELA) {
    const linhas = tabela.filter((l) => l.tier === tier);
    if (!linhas.length) continue;
    const grupo = document.createElement('div');
    grupo.className = `cxm-grupo cxm-t-${tier}`;
    grupo.innerHTML = `
      <div class="cxm-grupo-tit">
        <span class="cxm-selo">${escapar(t(`caixa.tier.${tier}`))}</span>
        <b>${escapar(pctDaChance(linhas.reduce((soma, l) => soma + l.chance, 0)))}</b>
      </div>`;
    for (const linha of linhas) {
      const el = document.createElement('div');
      el.className = 'cxm-linha';
      el.innerHTML = `
        <span class="cxm-linha-ico"></span>
        <span class="cxm-linha-nome">${escapar(nomeDoPremio(linha))}${linha.qtd > 1 ? ` <b>×${num(linha.qtd)}</b>` : ''}</span>
        <b class="cxm-linha-pct">${escapar(pctDaChance(linha.chance))}</b>`;
      el.querySelector('.cxm-linha-ico').appendChild(iconeDoPremio(linha, 24));
      grupo.appendChild(el);
    }
    lista.appendChild(grupo);
  }
  // São 16 linhas em três grupos: em quase toda tela sobra conteúdo embaixo.
  setaDeRolagem(corpo);
}

/** A resposta do servidor: a abertura, ou a recusa. */
function aoReceberCaixaNpc(m) {
  estado.caixaAbrindo = false;
  if (m.recusa) {
    toast(t(m.recusa.chave));
    if (estado.modalAberto === 'market') pintarMarket();
    return;
  }
  const r = m.aberta;
  if (!r) return;
  // O saldo vem do servidor — o mesmo que ele acabou de descontar.
  if (estado.eu) {
    estado.eu.gold = r.gold ?? estado.eu.gold;
    estado.eu.diamonds = r.diamonds ?? estado.eu.diamonds;
  }
  abrirAberturaDeCaixa(r);
  if (estado.modalAberto === 'market') pintarMarket();
}

/**
 * A ABERTURA — a parte que precisa dar prazer.
 *
 * Três tempos: a caixa treme, a caixa estoura, o prêmio aparece. A pausa de 750 ms entre o clique
 * e a revelação é metade do efeito: sem ela o prêmio já está na tela antes de a pessoa terminar de
 * olhar, e abrir caixa vira preencher formulário.
 *
 * O que saiu manda no tamanho da festa: lendário ganha raios, confete, grito e o som de shiny;
 * raro ganha raios e o som de drop de TM; comum abre em silêncio, com o mesmo pop. Comemorar tudo
 * é o mesmo que não comemorar nada.
 */
function abrirAberturaDeCaixa(r) {
  const caixa = caixaPorId(r.caixaId);
  const tier = r.tier ?? TIER_COMUM;
  const { corpo } = folhaMercado(escapar(nomeDaCaixa(r.caixaId)));
  corpo.innerHTML = `
    <div class="cxm-palco cxm-t-${escapar(tier)}" data-fase="fechada">
      <div class="ab-raios" aria-hidden="true"></div>
      <div class="ab-confete" aria-hidden="true">${'<i></i>'.repeat(14)}</div>
      <div class="cxm-arte"><img src="/img/caixas/${escapar(caixa?.plate ?? 'iron')}.png" alt="" width="96" height="96"></div>
      <b class="cxm-grito">${escapar(t(`caixa.grito.${tier}`))}</b>
      <div class="cxm-premios"></div>
    </div>
    <p class="cm-nota cxm-gastou">${escapar(t('caixa.gastou', {
      n: num(r.qtd ?? 1),
      coins: num(r.custo?.coins ?? 0),
      dia: r.custo?.diamantes ? t('caixa.eDiamantes', { n: num(r.custo.diamantes) }) : '',
    }))}</p>`;

  const palco = corpo.querySelector('.cxm-palco');
  const lista = corpo.querySelector('.cxm-premios');
  // O melhor primeiro: com dez caixas de uma vez, o fragmento não pode cair na décima linha.
  const ordem = { [TIER_LENDARIO]: 0, [TIER_RARO]: 1, [TIER_COMUM]: 2 };
  const premios = [...(r.premios ?? [])].sort((a, b) => (ordem[a.tier] ?? 2) - (ordem[b.tier] ?? 2));

  premios.forEach((premio, i) => {
    const el = document.createElement('div');
    el.className = `cxm-premio cxm-t-${escapar(premio.tier ?? TIER_COMUM)}`;
    // O atraso é por card: os prêmios entram em cascata, e o melhor (que está em primeiro) entra
    // no tempo do estouro.
    el.style.setProperty('--i', String(i));
    // `vezes` só aparece quando passa de uma: com uma caixa aberta, a linha é a de sempre.
    el.innerHTML = `
      <span class="cxm-premio-ico"></span>
      <span class="cxm-premio-nome">${escapar(nomeDoPremio(premio))}${
  premio.vezes > 1 ? `<i class="cxm-premio-vezes">${escapar(t('caixa.saiuVezes', { n: num(premio.vezes) }))}</i>` : ''
}</span>
      <b class="cxm-premio-qtd">×${num(premio.qtd)}</b>`;
    el.querySelector('.cxm-premio-ico').appendChild(iconeDoPremio(premio, 40));
    lista.appendChild(el);
  });
  if (!premios.length) lista.innerHTML = `<p class="vazio-msg">${escapar(t('caixa.vazia'))}</p>`;

  // Dez caixas são dez prêmios: a lista passa da tela, e o pé precisa dizer isso.
  const medir = setaDeRolagem(corpo);

  // O estouro. `isConnected` porque a folha pode ter sido fechada durante os 750 ms.
  setTimeout(() => {
    if (!palco.isConnected) return;
    palco.dataset.fase = 'aberta';
    if (tier === TIER_LENDARIO) tocarShinyCaptura();
    else if (tier === TIER_RARO) tocarTmBossDrop();
    else tocarCaptura();
    // A lista só existe a partir de agora (antes do estouro ela nem ocupa espaço).
    medir();
  }, 750);
}

function pintarMarket() {
  const aba = estado.abaMarket ?? 'compra';
  const host = $('#mk-corpo');
  // O `innerHTML = ''` abaixo mata o campo de IV que está sendo digitado. Anotar aqui que ele
  // tinha o foco é o que permite devolvê-lo no fim — ver `devolverFocoAoFiltroIv`.
  const filtroIvComFoco = !!document.activeElement?.matches?.('#mk-corpo input[data-f="ivMin"]');
  // O mesmo para a nota do Auto Lock — guardando o que JÁ foi digitado, que ainda não chegou
  // ao estado (só chega no `change`) e sumiria no campo novo.
  const notaAutoLockDigitando = document.activeElement?.id === 'mk-auto-lock-nota-min'
    ? document.activeElement.value
    : null;
  host.innerHTML = '';
  // A folha de filtros é da aba Venda Pokémons: trocar de aba não pode deixá-la aberta por cima.
  if (aba !== 'pokemons') host.classList.remove('pkf-aberta');
  // Qual aba está desenhada, para o CSS poder dar a cada uma a forma que ela pede no celular:
  // Compra e Venda viram LINHA (o ícone do item é pequeno e o que importa é preço e contador),
  // e Venda Pokémons continua GRADE (ali o sprite é metade da decisão). Sem esta marca as três
  // dividiriam a mesma regra e uma das duas formas sairia errada.
  host.dataset.aba = aba;
  const grade = document.createElement('div');
  grade.className = 'mk-grade';

  if (aba === 'compra') {
    // A aba de compra ganha um menu de categorias à esquerda; o resto das abas ocupa a
    // largura toda, porque lá o conteúdo é o que o jogador tem, não um catálogo fixo.
    const cat = estado.catCompra ?? 'bolas';
    const painel = document.createElement('div');
    painel.className = 'mk-com-lados';

    const lado = document.createElement('div');
    lado.className = 'mk-lado';
    for (const c of CATEGORIAS_COMPRA) {
      const bt = document.createElement('button');
      bt.className = 'mk-cat' + (c.id === cat ? ' on' : '');
      bt.textContent = t(c.nome);
      bt.onclick = () => {
        estado.catCompra = c.id;
        pintarMarket();
      };
      lado.appendChild(bt);
    }
    painel.appendChild(lado);
    painel.appendChild(grade);
    host.appendChild(painel);

    // As caixas são cards do Market como quaisquer outros — só o que entra na grade muda.
    if (cat === 'caixas') {
      grade.classList.add('mk-grade-caixas');
      pintarCaixasNpc(grade);
      return;
    }
    if (cat === 'ovos') {
      pintarOvosNpc(grade);
      return;
    }

    if (cat === 'bolas') {
      for (const b of estado.catalogoBolas.filter((x) => x.compravel)) {
        const preco = b.priceGold;
        const ctd = contadorCompra(preco);
        const { total, bt } = acaoComTotal(t('mk.comprar'), preco, ctd, { validarOuro: true });
        bt.onclick = () => enviar({ t: 'shop.buy', kind: 'ball', id: b.id, qty: ctd.ler() });
        const card = cardMarket({
          chave: `b${b.id}`,
          nome: b.nome,
          sub: `chance de captura ×${b.catchRate}`,
          preco,
          acao: [ctd.cx, total, bt],
        });
        card.querySelector('.mk-ico').appendChild(iconeBola(b.id, 40));
        grade.appendChild(card);
      }
    } else {
      const categoria = cat === 'revives' ? 'revive' : 'heal';
      for (const item of [...estado.itens.values()].filter((i) => i.category === categoria && i.npcPrice > 0)) {
        const preco = item.npcPrice;
        const ctd = contadorCompra(preco);
        const { total, bt } = acaoComTotal(t('mk.comprar'), preco, ctd, { validarOuro: true });
        bt.onclick = () => enviar({ t: 'shop.buy', kind: 'item', id: item.id, qty: ctd.ler() });
        const card = cardMarket({
          chave: `i${item.id}`,
          nome: nomeItem(item, item.name),
          sub: subItemMarket(item),
          preco,
          acao: [ctd.cx, total, bt],
        });
        // `iconeArquivo` e não um `<img>` cru: os sprites de poção e revive são de 13×21 a
        // 16×22 no arquivo, e o CSS do card só põe um TETO de 42 px — sem largura fixa eles
        // saíam no tamanho do PNG, um terço da pokébola de 40 px da categoria ao lado.
        const src = iconeItem(item.id);
        if (src) card.querySelector('.mk-ico').appendChild(iconeArquivo(src, 40));
        grade.appendChild(card);
      }
    }
    return; // a grade já entrou dentro do painel de dois lados
  }

  if (aba === 'venda') {
    // Só o que os pokémon dropam. Consumível comprável não volta para o NPC — espelha
    // o `precoDeVenda` do servidor, que também recusa.
    const vendaveis = Object.entries(estado.eu.items)
      .map(([id, q]) => ({ item: estado.itens.get(Number(id)), q }))
      .filter(({ item, q }) =>
        item && q > 0 && itemVendavelAoNpc(item, {
          bossTokenId: BOSS_TOKEN_ID,
          pvpFichaId: PVP_FICHA_ID,
          categoriasCompraveis: CATEGORIAS_COMPRAVEIS,
          itensCompraveisIds: new Set((estado.itensCompraveis ?? []).map((e) => e.itemId)),
        }),
      );

    const vendaveisLivres = vendaveis.filter(({ item }) => !itemLootTravadoCliente(item.id));
    const totalTudo = vendaveisLivres.reduce((s, { item, q }) => s + item.npcPrice * q, 0);
    const travados = vendaveis.length - vendaveisLivres.length;
    host.appendChild(
      barraVenderTudo(t('mk.venderTodoLoot'), vendaveisLivres.length, totalTudo, () =>
        enviar({ t: 'shop.sellAllItems' }),
        travados,
      ),
    );

    for (const { item, q } of vendaveis) {
      const travado = itemLootTravadoCliente(item.id);
      const ctd = contador(q);
      const { total, bt } = acaoComTotal(t('mk.vender'), item.npcPrice, ctd);
      bt.disabled = travado;
      if (travado) bt.title = t('mk.travadoVenda');
      bt.onclick = () => enviar({ t: 'shop.sellItem', id: item.id, qty: ctd.ler() });
      const card = cardMarket({
        chave: `v${item.id}`,
        nome: nomeItem(item, item.name),
        sub: t('mk.temQuantos', { q: num(q) }),
        preco: item.npcPrice,
        acao: [ctd.cx, total, bt],
        travado,
        aoTravar: () => alternarTravaLootCliente(item.id),
      });
      const src = iconeItem(item.id);
      if (src) card.querySelector('.mk-ico').innerHTML = `<img src="${src}" alt="">`;
      grade.appendChild(card);
    }
    if (!vendaveis.length) grade.innerHTML = `<div class="aviso-modal">${t('mk.semLoot')}</div>`;
  }

  if (aba === 'pokemons') {
    // O ativo nunca entra: o servidor recusa, e mostrar um botão que falha é pior que omitir.
    // A COLEÇÃO também não: é exatamente o que o jogador separou para não vender. Ela sai da
    // lista (e do "vender todo o depot"), e a faixa diz quantos ficaram lá.
    const colecao = conjuntoColecaoCliente();
    const noDepot = estado.eu.pokemons.filter((p) => p.id !== estado.eu.activeId && p.slot == null);
    const noDepotLivre = noDepot.filter((p) => !colecao.has(p.id));
    const travadosDepot = noDepot.length - noDepotLivre.length;
    const { tipo, ordem, ivMin } = estado.mkPokemonFiltro;
    const pisoIv = ivMinDoFiltro(ivMin);
    const filtrando = !!tipo || pisoIv != null;
    const lote = ordenarMarketPokemon(
      noDepotLivre.filter((p) => depotPassaFiltros(p, '', tipo, pisoIv)),
      ordem,
    );
    const venda = vendaDepotDaTela(filtrando ? lote : noDepotLivre, filtrando ? { tipo: tipo || null, ivMin: pisoIv } : null);

    const faixa = barraVenderTudo(
      t(filtrando ? 'mk.venderTodoDepotFiltrado' : 'mk.venderTodoDepot'),
      venda.lote.length,
      venda.lote.reduce((s, p) => s + precoDoPokemon(p), 0),
      () => enviar(venda.pedido),
      travadosDepot,
      {
        autoVenda: false,
        autoLockShiny: true,
        autoLockNota9: true,
        autoLockP5: true,
        lotePokemon: venda.lote,
        colecao: true,
      },
    );
    host.appendChild(faixa);
    const filtros = criarMkPokemonFiltros();
    host.appendChild(filtros);
    // No celular o funil mora na linha do "N para vender": é a única linha da faixa que tem
    // sobra à direita, e assim os filtros saem da tela sem custar uma fileira nova.
    if (montagemMovel()) {
      const info = faixa.querySelector('.mk-vt-info');
      const linha = document.createElement('div');
      linha.className = 'mk-vt-linha';
      info.replaceWith(linha);
      linha.appendChild(info);
      dobrarFiltrosNoCelular({ campos: [filtros], botaoEm: linha, host });
    }

    for (const p of lote) {
      const preco = precoDoPokemon(p);
      const travadoXpShare = pokemonTemXpShareHeld(p);
      const bt = document.createElement('button');
      bt.className = 'mk-acao';
      bt.textContent = t('mk.vender');
      bt.disabled = travadoXpShare;
      if (travadoXpShare) bt.title = t('xpshareheld.travaVenda');
      bt.onclick = () => enviar({ t: 'shop.sellPokemon', pokemonId: p.id });

      const card = cardMarket({
        chave: `p${p.id}`,
        nome: `${p.shiny ? prefixoShiny() : ''}${nomePkHtml(p)}`,
        // O nível e o "onde ele está" — qualidade, IV e nota desceram para a fileira de selos,
        // onde têm cor e são comparáveis de relance com os cards vizinhos.
        sub: t('mk.subPokemonCurta', {
          level: p.level,
          onde: p.slot == null ? t('painel.depot') : t('mk.equipe'),
        }),
        atributos: selosAtributos(p),
        preco,
        acao: [bt],
        classe: p.slot != null ? 'mk-card-equipe' : '',
        // O (i): a ficha inteira do bicho (IV por stat, stats, XP, refino). É o que a fileira
        // de selos NÃO resume — ela responde "guardo ou vendo?", a ficha responde "por quê?".
        aoVerFicha: () => abrirFichaDoPokemon(p),
      });
      const topo = card.querySelector('.mk-card-topo');
      topo.querySelector('.mk-ico').appendChild(spritePokemon(p, 44));
      // A setinha no lugar do antigo cadeado: manda para a Coleção, e o card sai desta lista.
      topo.appendChild(botaoColecao('colecao', () => moverColecao(p.id, 'colecao')));
      grade.appendChild(card);
    }
    if (!lote.length) {
      const msg = noDepotLivre.length && filtrando
        ? t('depot.nenhumResultado')
        : travadosDepot && !noDepotLivre.length ? t('colecao.tudoNaColecao') : t('mk.semPokemon');
      grade.innerHTML = `<div class="aviso-modal">${msg}</div>`;
    }
  }

  host.appendChild(grade);
  if (filtroIvComFoco) devolverFocoAoFiltroIv();
  if (notaAutoLockDigitando != null) {
    const campo = $('#mk-auto-lock-nota-min');
    if (campo) {
      campo.value = notaAutoLockDigitando;
      campo.focus();
    }
  }
}

/**
 * O que faz a aba atual precisar de redesenho. Compra inclui ouro (Máx).
 */
function assinaturaMarket() {
  const e = estado.eu;
  const aba = estado.abaMarket ?? 'compra';
  const travas = JSON.stringify({
    loot: e.automation?.lootTravado ?? [],
    pk: e.automation?.pokemonTravado ?? [],
  });
  if (aba === 'venda') return `${JSON.stringify(e.items)}|${travas}|${e.automation?.autoVendaLoot ? 1 : 0}`;
  if (aba === 'pokemons') {
    return `${e.activeId}|${e.pokemons.map((p) => `${p.id}:${p.slot}:${p.level}`).join(',')}|${travas}|${e.automation?.autoLockShiny ? 1 : 0}|${e.automation?.autoLockNota9 ? 1 : 0}|${e.automation?.autoLockNotaMin ?? ''}|${e.automation?.autoLockP5 ? 1 : 0}`;
  }
  if (aba === 'compra') return `compra|${e.gold ?? 0}`;
  return 'compra';
}

/** Só remonta a grade da Shop quando algo que muda o catálogo ou os botões mudou de verdade. */
function assinaturaLojaGrade() {
  const e = estado.eu;
  const l = e?.loja ?? {};
  return [
    estado.grupoLoja ?? '',
    estado.boostLoja ?? '',
    e?.diamonds ?? 0,
    JSON.stringify(l.ownedOutfits ?? []),
    JSON.stringify(l.comprasCooldown ?? {}),
    l.vipAte ?? 0,
    JSON.stringify(l.boosts ?? {}),
    l.looktype ?? '',
  ].join('|');
}

/** Atualização barata do Community Market — saldo de ouro e gemas, sem remontar a vitrine. */
function atualizarComunidade(e, anterior) {
  const gold = $('#cm-gold');
  if (gold && e.gold !== anterior?.gold) gold.textContent = num(e.gold ?? 0);
  const gemas = $('#cm-gemas');
  if (gemas && e.orbs !== anterior?.orbs) gemas.textContent = num(e.orbs ?? 0);
}

/** Atualização barata da Shop — diamantes e selos de boost; grade só quando muda o conteúdo. */
function atualizarLoja(e) {
  if (!$('#loja-grade')) return;
  const saldo = $('#loja-diamantes');
  if (saldo) saldo.textContent = num(e?.diamonds ?? 0);
  montarAtivosDaLoja();
  const assinatura = assinaturaLojaGrade();
  if (assinatura === estado.assinaturaLoja) return;
  estado.assinaturaLoja = assinatura;
  montarLoja();
}

/** Atualização barata da compra de diamantes — só o saldo; não mexe na quantidade digitada. */
function atualizarDiamantes(e, anterior) {
  if (e?.diamonds === anterior?.diamonds) return;
  const saldo = document.querySelector('#modal-corpo .dia-corpo .orbs-saldo b');
  if (saldo) saldo.textContent = num(e?.diamonds ?? 0);
}

/**
 * Refresh barato do Market: o saldo sempre; a grade só quando o conteúdo muda de verdade.
 *
 * Se o foco está dentro da grade o redesenho espera — senão o loot que cai durante o
 * combate apagaria o contador no meio da digitação. Volta no próximo snapshot.
 */
function atualizarMarket() {
  const saldo = document.querySelector('.mk-saldo');
  if (!saldo) return;
  saldo.innerHTML = moeda(estado.eu.gold);

  const corpo = $('#mk-corpo');
  const assinatura = assinaturaMarket();
  if (assinatura === estado.assinaturaMarket) return;

  // Só o CAMPO de quantidade segura o redesenho. Um clique de verdade deixa o foco no
  // botão que foi clicado — se qualquer foco dentro da grade bloqueasse, o card recém
  // vendido ficaria na tela até o jogador clicar em outro lugar.
  const foco = document.activeElement;
  if (foco?.tagName === 'INPUT' && corpo?.contains(foco)) return;

  // Guarda as quantidades já escolhidas nos contadores antes de remontar. Durante o combate
  // o ouro muda a cada snapshot (~500 ms) e isto cai aqui toda vez; sem preservar, o
  // contador voltava pra 1 sempre que o último toque foi no −/+/Máx (o foco fica no botão,
  // não no campo) ou fora da grade no celular. Chaveado por `data-chave` do card.
  const qtdSalvas = [];
  for (const campo of corpo?.querySelectorAll('.mk-card[data-chave] .mk-qtd input') ?? []) {
    const chave = campo.closest('.mk-card')?.dataset.chave;
    if (chave && campo.value && campo.value !== '1') qtdSalvas.push([chave, campo.value]);
  }

  estado.assinaturaMarket = assinatura;
  pintarMarket();

  for (const [chave, valor] of qtdSalvas) {
    const campo = corpo?.querySelector(`.mk-card[data-chave="${chave}"] .mk-qtd input`);
    if (!campo) continue;
    campo.value = valor;
    campo.dispatchEvent(new Event('input')); // reidrata o "total" e o "desabilita sem ouro"
  }
}

/** Aviso extra no popup de "vender todo o Depot" — shiny e P5 destrancados entram na venda. */
function avisoDepotValiosos(lote) {
  const valiosos = (lote ?? []).filter(
    (p) => p.shiny || Number(p.potencia) === POTENCIA_MAX,
  );
  if (!valiosos.length) return '';

  const max = 8;
  const mostrar = valiosos.slice(0, max);
  // Cada um como fichinha com o sprite: na pressa de "vender tudo", o olho reconhece o shiny pelo
  // desenho antes de ler o nome. O selo dourado (✨ / P5) é o motivo de ele estar na lista.
  const fichas = mostrar
    .map((p) => {
      const selos = [];
      if (p.shiny) selos.push(dlgIcone('brilho', 11));
      if (Number(p.potencia) === POTENCIA_MAX) selos.push('P5');
      return `<span class="dlg-ficha-pk">
        <span data-dlg-lt="${Number(looktypeDe(p)) || 0}" data-dlg-px="26" data-dlg-comum="${Number(especieDe(p)?.looktype ?? p.looktype) || 0}"></span>
        ${nomePkHtml(p)}<em>${selos.join(' ')}</em>
      </span>`;
    })
    .join('');
  const resto = valiosos.length - mostrar.length;
  const extra = resto > 0 ? `<small>${t('mk.confirmaDepotValiososMais', { n: num(resto) })}</small>` : '';
  return `
    <div class="dlg-aviso ouro dlg-valiosos">${dlgIcone('alerta', 18)}<span>
      ${t('mk.confirmaDepotValiososIntro')}
      <span class="dlg-fichas-pk">${fichas}</span>${extra}
    </span></div>`;
}

/** Faixa de "vender todos" no topo das abas de venda. Sempre pede confirmação. */
/**
 * O "Vender todo o Depot" — inteiro, ou só o que o FILTRO deixa na tela.
 *
 * `lote` é o que a confirmação mostra e é exatamente o que o servidor vai vender: fora quem segura
 * a Exp. Share (o servidor também deixa de fora, e ela some com o pokémon), e o pedido leva o
 * maior id da lista (`ateId`) — o pokémon capturado DEPOIS de a caixa abrir não entra numa venda
 * que o jogador não viu. Com filtro, vai o FILTRO e não a lista de ids: num depot de milhares de
 * pokémon a lista passaria do teto de 16 KB por mensagem do socket, e o servidor refaz a mesma
 * conta com a mesma função (`shared/filtro-depot.mjs`).
 */
function vendaDepotDaTela(pokemons, filtro = null) {
  const lote = pokemons.filter((p) => !pokemonTemXpShareHeld(p));
  const ateId = lote.reduce((m, p) => Math.max(m, Number(p.id) || 0), 0);
  const pedido = { t: 'shop.sellAllPokemons', ateId };
  if (filtro) pedido.filtro = filtro;
  return { lote, pedido };
}

function barraVenderTudo(rotulo, quantos, total, aoConfirmar, travados = 0, opcoes = {}) {
  const {
    autoVenda = true,
    autoLockShiny = false,
    autoLockNota9 = false,
    autoLockP5 = false,
    lotePokemon = null,
    colecao = false,
  } = opcoes;
  const el = document.createElement('div');
  el.className = 'mk-vender-tudo';
  // Na venda de POKÉMON, quem fica de fora é a Coleção — e o número vira atalho para ela.
  const extraTravados = !travados
    ? ''
    : colecao
      ? ` · <button type="button" class="mk-ver-colecao">${t('colecao.foraDaVenda', { n: num(travados) })}</button>`
      : ` · ${t('mk.travadosFora', { n: num(travados) })}`;
  const autoVendaOn = !!estado.eu?.automation?.autoVendaLoot;
  const autoLockOn = estado.eu?.automation?.autoLockShiny !== false;
  const autoLockNotaOn = !!estado.eu?.automation?.autoLockNota9;
  const autoLockP5On = !!estado.eu?.automation?.autoLockP5;
  const toggles = [
    autoVenda
      ? `<label class="auto-linha mk-auto-venda-linha">
        <span>${t('mk.vendaAutomatica')}</span>
        <input type="checkbox" id="mk-auto-venda"${autoVendaOn ? ' checked' : ''}>
      </label>`
      : '',
    autoLockShiny
      ? `<label class="auto-linha mk-auto-venda-linha">
        <span>${t('mk.autoLockShiny')}</span>
        <input type="checkbox" id="mk-auto-lock-shiny"${autoLockOn ? ' checked' : ''}>
      </label>`
      : '',
    // O `for` aponta o rótulo para o INTERRUPTOR: sem ele o label se ligaria ao primeiro campo
    // de dentro — o da nota —, e clicar em "Auto Lock" focaria o número em vez de ligar a trava.
    autoLockNota9
      ? `<label class="auto-linha mk-auto-venda-linha mk-auto-lock-nota-linha" for="mk-auto-lock-nota9"
          title="${escapar(t('mk.autoLockNotaDica'))}">
        <span>${t('mk.autoLockNota')}</span>
        <input type="number" class="mk-auto-lock-nota-min" id="mk-auto-lock-nota-min" min="0" max="10" step="0.1"
          inputmode="decimal" value="${notaAutoLockDoJogador()}" aria-label="${escapar(t('mk.autoLockNotaDica'))}">
        <span>+</span>
        <input type="checkbox" id="mk-auto-lock-nota9"${autoLockNotaOn ? ' checked' : ''}>
      </label>`
      : '',
    autoLockP5
      ? `<label class="auto-linha mk-auto-venda-linha">
        <span>${t('mk.autoLockP5')}</span>
        <input type="checkbox" id="mk-auto-lock-p5"${autoLockP5On ? ' checked' : ''}>
      </label>`
      : '',
  ]
    .filter(Boolean)
    .join('');
  el.innerHTML = `
    <div class="mk-vt-info">${quantos ? `${t('mk.paraVender', { n: num(quantos) })} · ${t('mk.rende', { v: moeda(total) })}${extraTravados}` : t('mk.nadaVender')}</div>
    <div class="mk-vt-acoes">
      ${toggles}
      <button type="button" class="mk-acao" ${quantos ? '' : 'disabled'}>${rotulo}</button>
    </div>`;
  // A venda em lote como troca: o que sai (sem cor) de um lado, as Coins do outro, e a etiqueta
  // do que ENTRA com o saldo subindo. O que fica de fora (trancados, Coleção) é aviso dourado; o
  // shiny e o P5 que vão junto, o aviso com as fichinhas.
  el.querySelector('.mk-acao').onclick = () =>
    confirmar({
      titulo: rotulo,
      texto: `
        ${dlgPalco(`
          ${dlgAtor({
            arte: lotePokemon?.length
              ? dlgFila(lotePokemon, 30, 6)
              : dlgArteHtml(dlgMedalha({ arte: `<span data-dlg-arquivo="${ICONE_ITEM_GENERICO}" data-dlg-px="40"></span>`, tom: 'ouro' })),
            nome: escapar(t('mk.nParaVender', { n: num(quantos) })),
            classe: 'sai',
          })}
          ${dlgSeta()}
          ${dlgAtor({ arte: dlgArteArquivo(ICONE_OURO, 48), nome: `+${num(total)}`, classe: 'novo' })}`, 'ouro')}
        ${dlgCusto({ moeda: 'ouro', valor: total, saldo: Math.floor(estado.eu?.gold ?? 0), ganha: true })}
        ${travados ? dlgAviso(t(colecao ? 'colecao.confirmaFora' : 'mk.confirmaTravadosFora', { n: num(travados) }), { icone: 'cadeado', tom: 'info' }) : ''}
        ${lotePokemon ? avisoDepotValiosos(lotePokemon) : ''}
        ${dlgSelos(dlgSelo('cadeado', escapar(t('mk.seloSemDesfazer')), 'perigo'))}`,
      aoConfirmar,
    });
  el.querySelector('.mk-ver-colecao')?.addEventListener('click', () => abrirColecao());
  el.querySelector('#mk-auto-venda')?.addEventListener('change', (ev) => {
    const cb = ev.target;
    if (cb.checked) alternarVendaAutomatica(true, cb);
    else alternarVendaAutomatica(false, cb);
  });
  el.querySelector('#mk-auto-lock-shiny')?.addEventListener('change', (ev) => {
    const cb = ev.target;
    alternarAutoLockShiny(cb.checked, cb);
  });
  el.querySelector('#mk-auto-lock-nota9')?.addEventListener('change', (ev) => {
    const cb = ev.target;
    alternarAutoLockNota9(cb.checked, cb);
  });
  // `change`, e não `input`: a nota só vale quando o jogador termina de digitar (Enter ou sair
  // do campo). A cada tecla, "3,2" passaria por "3" — e com a trava ligada isso trancaria de
  // passagem tudo o que tem nota 3 para cima.
  const campoNota = el.querySelector('#mk-auto-lock-nota-min');
  campoNota?.addEventListener('change', () => mudarNotaAutoLock(campoNota));
  campoNota?.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter') campoNota.blur();
  });
  el.querySelector('#mk-auto-lock-p5')?.addEventListener('change', (ev) => {
    const cb = ev.target;
    alternarAutoLockP5(cb.checked, cb);
  });
  return el;
}

/** Liga/desliga a venda automática de loot da hunt (só na aba Venda do Market). */
function alternarVendaAutomatica(ligar, interruptor = null) {
  const aplicar = (ativo, avisoVisto = false) => {
    if (!estado.eu?.automation) return;
    estado.eu.automation.autoVendaLoot = ativo;
    if (avisoVisto) estado.eu.automation.autoVendaLootAvisoVisto = true;
    if (interruptor) interruptor.checked = ativo;
    estado.assinaturaMarket = assinaturaMarket();
    if ($('#mk-corpo') && (estado.abaMarket ?? 'compra') === 'venda') pintarMarket();
  };
  if (ligar) {
    if (!estado.eu?.automation?.autoVendaLootAvisoVisto) {
      if (interruptor) interruptor.checked = false;
      // O exemplo de sempre (o Bee Sting) desenhado: o drop de um lado, as Coins do outro, a
      // seta dizendo "na hora". As regras viram linhas — a do cuidado em vermelho, por último,
      // que é a que precisa ficar na cabeça.
      const exemplo = itemPorNome('Bee Sting');
      confirmar({
        titulo: t('mk.vendaAutomatica'),
        texto: `
          ${dlgPalco(`
            ${dlgAtor({
              arte: exemplo ? dlgArteItem(exemplo.id, 48) : dlgArteArquivo(ICONE_ITEM_GENERICO, 48),
              nome: escapar(exemplo?.name ?? 'Loot'),
              sub: escapar(t('mk.vaSemCadeado')),
              classe: 'sai',
            })}
            ${dlgSeta({ rotulo: escapar(t('mk.vaNaHora')) })}
            ${dlgAtor({ arte: dlgArteArquivo(ICONE_OURO, 48), nome: 'Coins', classe: 'novo' })}`, 'ouro')}
          ${dlgLista([
            { icone: 'raio', html: t('mk.vaRegraHora') },
            { icone: 'cadeado', html: t('mk.vaRegraCadeado') },
            { icone: 'check', html: t('mk.vaRegraPedras') },
            { icone: 'alerta', html: t('mk.vaRegraCuidado'), perigo: true },
          ])}`,
        rotuloSim: t('mk.vendaAutomaticaLigar'),
        aoConfirmar: () => {
          aplicar(true, true);
          enviar({ t: 'shop.autoVendaLoot', ativo: true, avisoVisto: true });
        },
      });
      return;
    }
    aplicar(true);
    enviar({ t: 'shop.autoVendaLoot', ativo: true });
    return;
  }
  aplicar(false);
  enviar({ t: 'shop.autoVendaLoot', ativo: false });
}

/** Liga/desliga trava automática de shiny capturado (aba Venda Pokémons do Market). */
function alternarAutoLockShiny(ligar, interruptor = null) {
  const aplicar = (ativo) => {
    if (!estado.eu?.automation) return;
    estado.eu.automation.autoLockShiny = ativo;
    if (ativo) {
      const arr = (estado.eu.automation.pokemonTravado ??= []);
      for (const pk of estado.eu.pokemons ?? []) {
        if (pk.shiny && !arr.includes(pk.id)) arr.push(pk.id);
      }
    }
    if (interruptor) interruptor.checked = ativo;
    estado.assinaturaMarket = assinaturaMarket();
    if ($('#mk-corpo') && (estado.abaMarket ?? 'compra') === 'pokemons') pintarMarket();
  };
  aplicar(ligar);
  enviar({ t: 'shop.autoLockShiny', ativo: ligar });
}

/** A nota do Auto Lock N+ deste jogador: a que ele escolheu, ou o padrão. */
const notaAutoLockDoJogador = () =>
  notaAutoLockValida(estado.eu?.automation?.autoLockNotaMin) ?? AUTO_LOCK_NOTA_MIN;

/**
 * Espelho local do `travarTodosNota9` do servidor: quem tem nota ≥ `limiar` e ainda está
 * aberto. Devolve quantos são; com `soContar` não tranca nada (é a conta da caixa).
 */
function trancarPorNotaLocal(limiar, { soContar = false } = {}) {
  const lista = pokemonsQueANotaTranca(limiar);
  if (!soContar) (estado.eu.automation.pokemonTravado ??= []).push(...lista.map((pk) => pk.id));
  return lista.length;
}

/** Os pokémon que a nota `limiar` mandaria para a Coleção agora — os que ainda estão soltos. */
function pokemonsQueANotaTranca(limiar) {
  const arr = estado.eu.automation.pokemonTravado ?? [];
  return (estado.eu.pokemons ?? []).filter((pk) => {
    const nota = notaDoPokemon(pk);
    return nota != null && nota >= limiar && !arr.includes(pk.id);
  });
}

/** Liga/desliga trava automática de pokémon com nota ≥ a escolhida (aba Venda Pokémons do Market). */
function alternarAutoLockNota9(ligar, interruptor = null) {
  const aplicar = (ativo) => {
    if (!estado.eu?.automation) return;
    estado.eu.automation.autoLockNota9 = ativo;
    if (ativo) trancarPorNotaLocal(notaAutoLockDoJogador());
    if (interruptor) interruptor.checked = ativo;
    estado.assinaturaMarket = assinaturaMarket();
    if ($('#mk-corpo') && (estado.abaMarket ?? 'compra') === 'pokemons') pintarMarket();
  };
  aplicar(ligar);
  enviar({ t: 'shop.autoLockNota9', ativo: ligar });
}

/**
 * O jogador trocou a nota do Auto Lock N+.
 *
 * Desligado, é só a preferência guardada: nada tranca até ele ligar. LIGADO, a troca tranca na
 * hora, e cadeado automático não volta sozinho — por isso a caixa diz quantos pokémon vão
 * fechar antes de mandar. Sem ela, quem descesse pela setinha do campo de 3,5 até 2,0
 * trancaria de passagem tudo o que tem nota 2 para cima.
 *
 * O servidor valida a nota de novo (`notaAutoLockValida`); a daqui só evita mandar lixo.
 */
function mudarNotaAutoLock(campo) {
  if (!estado.eu?.automation) return;
  const atual = notaAutoLockDoJogador();
  const digitado = campo.value.trim() === '' ? Number.NaN : Number(campo.value);
  const nota = notaAutoLockValida(digitado);
  const voltar = () => {
    campo.value = String(atual);
  };
  if (nota == null) {
    voltar();
    return toast(t('mk.autoLockNotaInvalida'));
  }
  if (nota === atual) {
    campo.value = String(nota);
    return;
  }
  const ligado = !!estado.eu.automation.autoLockNota9;
  const aplicar = () => {
    if (!estado.eu?.automation) return;
    estado.eu.automation.autoLockNotaMin = nota;
    const trancou = ligado ? trancarPorNotaLocal(nota) : 0;
    estado.assinaturaMarket = assinaturaMarket();
    // Só redesenha quando algum cadeado FECHOU. O `change` dispara ao sair do campo — e sair do
    // campo é, muitas vezes, clicar no interruptor ao lado: redesenhar aqui trocaria o
    // interruptor de nó no meio do clique, e o clique se perderia. Sem cadeado novo, a única
    // coisa que mudou na tela é o número, e ele já está no campo.
    if (trancou && $('#mk-corpo') && (estado.abaMarket ?? 'compra') === 'pokemons') pintarMarket();
    enviar({ t: 'shop.autoLockNota9', ativo: ligado, nota });
  };
  const novos = ligado ? trancarPorNotaLocal(nota, { soContar: true }) : 0;
  if (!novos) return aplicar();
  const notaTxt = virgula(String(nota));
  // Até o jogador confirmar, o campo mostra a nota que ESTÁ valendo. Confirmou, o `aplicar`
  // redesenha a faixa já com a nova; cancelou (Não, Esc, clique fora), fica a de antes.
  voltar();
  // Os que vão para a Coleção AGORA, em fila, a seta, e a estrela dourada da Coleção. A nota é o
  // rótulo da seta: é ela que decide quem passa.
  const indo = pokemonsQueANotaTranca(nota);
  confirmar({
    titulo: t('mk.autoLockNotaTitulo', { nota: notaTxt }),
    texto: `
      ${dlgPalco(`
        ${dlgAtor({
          arte: indo.length ? dlgFila(indo, 30, 6) : dlgArteHtml(dlgMedalha({ icone: 'pessoa', tom: 'ouro' })),
          nome: escapar(t('oferenda.nPokemon', { n: num(novos) })),
        })}
        ${dlgSeta({ rotulo: escapar(t('mk.autoLockNotaSeta', { nota: notaTxt })) })}
        ${dlgAtor({ arte: dlgArteHtml(dlgMedalha({ icone: 'estrela', tom: 'ouro', px: 36 })), nome: escapar(t('colecao.titulo')), classe: 'novo' })}`, 'ouro')}
      ${dlgFrase('', t('mk.autoLockNotaConfirma', { nota: notaTxt, n: num(novos) }))}`,
    rotuloSim: t('mk.autoLockNotaTrancar', { n: num(novos) }),
    aoConfirmar: aplicar,
  });
}

/** Liga/desliga trava automática de pokémon com potência V (aba Venda Pokémons do Market). */
function alternarAutoLockP5(ligar, interruptor = null) {
  const aplicar = (ativo) => {
    if (!estado.eu?.automation) return;
    estado.eu.automation.autoLockP5 = ativo;
    if (ativo) {
      const arr = (estado.eu.automation.pokemonTravado ??= []);
      for (const pk of estado.eu.pokemons ?? []) {
        if ((Number(pk.potencia) || 1) === POTENCIA_MAX && !arr.includes(pk.id)) arr.push(pk.id);
      }
    }
    if (interruptor) interruptor.checked = ativo;
    estado.assinaturaMarket = assinaturaMarket();
    if ($('#mk-corpo') && (estado.abaMarket ?? 'compra') === 'pokemons') pintarMarket();
  };
  aplicar(ligar);
  enviar({ t: 'shop.autoLockP5', ativo: ligar });
}

/**
 * Abre o Tracker (`/tracker`) numa aba nova, já na ficha de quem clicou.
 *
 * `noopener` não é detalhe de estilo: sem ele a página aberta ganha um `window.opener` que
 * aponta para o jogo — e com ele dá para reescrever o endereço desta aba de fora. A página é
 * nossa, mas a trava é de graça e vale para o dia em que o endereço mudar.
 */
function abrirTracker() {
  const nick = estado.eu?.nick;
  const destino = nick ? `/tracker/j/${encodeURIComponent(nick)}` : '/tracker';
  window.open(destino, '_blank', 'noopener');
}

/**
 * O botão de ação no topo do modal, ao lado do fechar.
 *
 * Uma tabela e não um `if` espalhado: cada tela que quiser um atalho declara o rótulo e o que
 * ele faz numa linha só, e quem não estiver aqui simplesmente não mostra botão nenhum.
 */
const ACAO_DO_TOPO = {
  /**
   * O TRACKER — o único botão do jogo que leva para FORA dele.
   *
   * Ele mora aqui, ao lado do ×, e não numa quinta aba do PvP, por uma razão de expectativa: as
   * abas do modal trocam o miolo, e esta não trocaria — abre outra aba do navegador. Um controle
   * que faz algo de outra natureza tem de morar noutro lugar, e o topo do modal já é o canto
   * dos atalhos (é ele que leva a Pokédex aos shinys do servidor).
   *
   * Por que ABRE EM OUTRA ABA, e não no lugar: quem clica está no meio de uma sessão idle — os
   * pokémon estão caçando, e sair da página desconecta o socket. O jogador volta para a aba do
   * jogo e nada aconteceu; é o comportamento que ele já espera de um link de Discord.
   *
   * Por que o NICK vai no endereço: o jogador logado quase nunca quer a página inicial do
   * Tracker — ele quer a ficha DELE, e é dela que se chega a qualquer outra coisa. Sem sessão
   * (a tela de login do PvP não abre sem), cai na inicial.
   */
  pvp: {
    extras: [{
      id: 'modal-extra',
      icone: 'tracker',
      rotulo: 'pvp.tracker',
      dica: 'pvp.trackerDica',
      aoClicar: abrirTracker,
    }],
  },
  pokedex: {
    extras: [
      { id: 'modal-extra', icone: 'shiny', dica: 'dex.verShinysAjuda', aoClicar: () => abrirModal('shinys') },
      { id: 'modal-extra-b', icone: 'p5', dica: 'dex.verP5Ajuda', aoClicar: () => abrirModal('p5s') },
    ],
  },
  shinys: {
    extras: [{ id: 'modal-extra', rotulo: 'shl.voltarDex', voltar: true, dica: 'shl.voltarDexAjuda', aoClicar: () => abrirModal('pokedex') }],
  },
  p5s: {
    extras: [{ id: 'modal-extra', rotulo: 'p5l.voltarDex', voltar: true, dica: 'p5l.voltarDexAjuda', aoClicar: () => abrirModal('pokedex') }],
  },
  deposito: {
    extras: [{
      id: 'modal-extra',
      voltar: true,
      soSeta: true,
      dica: 'orbs.voltarComunidadeAjuda',
      aoClicar: () => abrirModal('community'),
    }],
  },
  withdraw: {
    extras: [{
      id: 'modal-extra',
      voltar: true,
      soSeta: true,
      dica: 'orbs.voltarComunidadeAjuda',
      aoClicar: () => abrirModal('community'),
    }],
  },
};

function montarAcaoDoTopo(nome) {
  const cfg = ACAO_DO_TOPO[nome];
  const extras = cfg?.extras ?? [];
  const mob = movelAtivo();
  for (const id of ['modal-extra', 'modal-extra-b']) {
    const bt = $(`#${id}`);
    if (!bt) continue;
    bt.classList.add('hidden');
    bt.classList.remove('modal-extra-ico', 'modal-extra-shiny', 'modal-extra-p5', 'modal-extra-voltar', 'modal-extra-tracker');
    bt.removeAttribute('aria-label');
    bt.onclick = null;
    bt.replaceChildren();
  }
  for (const ex of extras) {
    const bt = $(`#${ex.id}`);
    if (!bt) continue;
    bt.classList.remove('hidden');
    bt.title = t(ex.dica);
    bt.onclick = ex.aoClicar;

    if (ex.voltar && (mob || ex.soSeta)) {
      bt.classList.add('modal-extra-ico', 'modal-extra-voltar');
      bt.textContent = '‹';
      bt.setAttribute('aria-label', t(ex.dica));
    } else if (ex.icone === 'tracker') {
      // O ÚNICO extra com desenho E palavra, e só no desktop.
      //
      // O desenho sozinho não bastaria: "tracker" não tem um símbolo que o jogador já conheça
      // (a prancheta já é de outra coisa), e um ícone que ninguém decifra vira um botão que
      // ninguém clica. A palavra sozinha, num modal que no celular já tem título e ×, comeria
      // a linha do título — daí o celular ficar só com o gráfico e o rótulo mudar de lugar,
      // para o `aria-label` e o `title`.
      bt.classList.add('modal-extra-tracker');
      bt.setAttribute('aria-label', t(ex.rotulo));
      if (mob) {
        bt.classList.add('modal-extra-ico');
        bt.innerHTML = iconeGrafico();
      } else {
        bt.innerHTML = `${iconeGrafico()}<span>${escapar(t(ex.rotulo))}</span>`;
      }
    } else if (ex.icone) {
      bt.classList.add('modal-extra-ico');
      if (ex.icone === 'shiny') {
        bt.classList.add('modal-extra-shiny');
        bt.textContent = '✨';
      } else if (ex.icone === 'p5') {
        bt.classList.add('modal-extra-p5');
        bt.innerHTML = '<span class="cm-pot p5">P5</span>';
      }
    } else {
      bt.textContent = t(ex.rotulo);
    }
  }
}

/**
 * A DOBRA DOS FILTROS — só existe no celular.
 *
 * Duas telas do jogo são "uma barra de filtros e um resultado": o Mapa e o Mercado da
 * Comunidade. No desktop a barra fica de lado e não custa nada; num telefone ela empurra o
 * resultado (que é a razão da tela) para fora da dobra — os 18 selos de tipo sozinhos ocupam
 * quatro fileiras.
 *
 * Então no celular a barra nasce fechada e um botão a abre. A dobra é só uma classe na caixa
 * do modal; quem esconde o quê é o `mobile.css`, tela a tela.
 */
/**
 * O rodapé da folha de filtros do celular: uma barra grudada na base com o botão de sair.
 *
 * Ele estava no CANTO SUPERIOR DIREITO, ao lado do título — que é o pior lugar possível numa
 * tela de telefone: é o ponto mais longe do polegar, e ali o botão parecia colado no rótulo em
 * vez de ser a ação da tela. Na base ele cai debaixo do dedo e ganha a largura toda, que é o
 * que diz "terminei aqui".
 *
 * Fica `sticky`: com os 18 selos de tipo abertos a folha rola, e a saída não pode rolar junto.
 *
 * `extra` é uma ação opcional que entra À ESQUERDA do "Pronto" — hoje o "limpar filtros" do
 * Mercado. Fica aqui, e não no meio da folha, porque desfazer é irmão de sair: as duas são o
 * que se faz DEPOIS de olhar o filtro, e as duas têm de estar debaixo do polegar.
 */
function folhaDeFiltrosRodape(extra = '') {
  return `<div class="filtros-folha-rodape">
    ${extra}
    <button type="button" class="filtros-pronto" id="filtros-pronto">${t('filtros.pronto')}</button>
  </div>`;
}

/**
 * Devolve a folha de filtros ao estado ABERTO depois de um redesenho da tela.
 *
 * Separada de `ligarDobraDeFiltros` porque o `#filtros-bt` é um nó NOVO a cada `abrirModal`:
 * guardar a função `abrir` de lá não adiantaria, ela ficaria apontando para o botão velho.
 */
function reabrirFolhaDeFiltros() {
  $('#modal .modal-caixa')?.classList.add('filtros-abertos');
  $('#filtros-bt')?.classList.add('on');
}

function ligarDobraDeFiltros() {
  const caixa = $('#modal .modal-caixa');
  const bt = $('#filtros-bt');
  if (!caixa || !bt) return;
  const abrir = (sim) => {
    caixa.classList.toggle('filtros-abertos', sim);
    bt.classList.toggle('on', sim);
  };
  bt.addEventListener('click', () => abrir(!caixa.classList.contains('filtros-abertos')));
  // A folha cobre o corpo do modal inteiro, então o botão que a abriu fica embaixo dela: o
  // caminho de volta é o "Pronto" do topo dela (e o × do modal, que continua à vista).
  $('#filtros-pronto')?.addEventListener('click', () => abrir(false));
}

function abrirModal(nome) {
  const cfg = MODAIS[nome];
  if (!cfg) return;
  if (nome === 'calculadora') fecharCalculadora();
  document.querySelector('.cm-folha')?.remove();
  estado.modalAberto = nome;
  $('#modal-titulo').textContent = t(cfg.titulo);
  $('#modal-corpo').innerHTML = cfg.render();
  // Modal de proporção QUADRADA: as telas que são uma grade (a vitrine do Mercado) leem melhor
  // assim — numa caixa larga e baixa a grade vira uma tira de duas fileiras que rola sem fim.
  $('#modal .modal-caixa').classList.toggle('quadrado', !!cfg.quadrado);
  // Quem é a tela aberta, para o CSS poder ajustar a caixa sem uma classe por modal. Só a
  // Pokepédia usa hoje (ela é mais larga que um quadrado), mas o gancho vale para qualquer uma.
  $('#modal .modal-caixa').dataset.modal = nome;
  // A folha de filtros do celular nasce FECHADA a cada abertura. A classe mora na caixa, que é
  // a mesma para todos os modais: sem esta linha ela vazava — abrir o Mapa, abrir os filtros e
  // fechar deixava o Mercado da Comunidade nascer com a folha dele já por cima da vitrine.
  $('#modal .modal-caixa').classList.remove('filtros-abertos');
  // O `render()` acabou de trocar o HTML inteiro, então os `data-ico` que vieram nele ainda
  // são só marcação. Sem esta passada os ícones dos filtros não apareceriam.
  for (const el of $('#modal-corpo').querySelectorAll('[data-ico]')) pintarIcone(el);
  montarAcaoDoTopo(nome);
  $('#modal').classList.remove('hidden');

  if (nome === 'mapa') {
    mapaZoom.ancorou = false;
    ligarGestosDoMapa();
    montarMapaMundi(true);

    $('.mapa-areas').onclick = (ev) => {
      const b = ev.target.closest('.mapa-area');
      if (!b || b.disabled) return;
      estado.filtroMapa.regiao = b.dataset.regiao;
      abrirModal('mapa'); // a barra inteira é redesenhada com a região nova selecionada
    };
    $('#f-tipos').onclick = (ev) => {
      const b = ev.target.closest('.tipo-btn[data-f="tipo"]');
      if (!b) return;
      alternarFiltroTiposMapa(estado.filtroMapa.tipos, b.dataset.tipo);
      if (!estado.filtroMapa.tipos.length) {
        estado.filtroMapa.modoMatchup = '';
        const fr = $('#f-fraco-contra');
        const fo = $('#f-forte-contra');
        if (fr) fr.checked = false;
        if (fo) fo.checked = false;
      }
      const temTipos = estado.filtroMapa.tipos.length > 0;
      $('#f-fraco-contra') && ($('#f-fraco-contra').disabled = !temTipos);
      $('#f-forte-contra') && ($('#f-forte-contra').disabled = !temTipos);
      pintarFiltrosTipoMapa();
      montarMapaMundi();
    };
    // O seletor das Outlands. Só existe na aba Outland — daí a guarda.
    //
    // Não há pintura otimista: quem confirma a troca é o servidor (é ele que tem o nível), e a
    // resposta volta no snapshot seguinte, em meio segundo. Enquanto isso o `<select>` mostra
    // a opção clicada; se o servidor recusar, o `pintarSeletorOutland` do próximo
    // `montarMapaMundi` devolve a marca ao lugar e o aviso aparece no log.
    const selOutland = $('#f-outland');
    if (selOutland) {
      selOutland.onchange = (ev) => enviar({ t: 'outland.tier', tier: Number(ev.target.value) });
    }
    $('#f-liberadas').onchange = (ev) => {
      estado.filtroMapa.soLiberadas = ev.target.checked;
      montarMapaMundi();
    };
    $('#f-mapa').oninput = (ev) => {
      estado.filtroMapa.busca = ev.target.value;
      montarMapaMundi();
    };
    const atualizarFiltroNivel = (ev) => {
      estado.filtroMapa[ev.target.id === 'f-nivel-min' ? 'nivelMin' : 'nivelMax'] = ev.target.value;
      montarMapaMundi();
    };
    $('#f-nivel-min').oninput = atualizarFiltroNivel;
    $('#f-nivel-max').oninput = atualizarFiltroNivel;
    const mudarMatchup = (modo, marcado) => {
      if (marcado) {
        estado.filtroMapa.modoMatchup = modo;
        $('#f-fraco-contra').checked = modo === 'fraco';
        $('#f-forte-contra').checked = modo === 'forte';
      } else if (estado.filtroMapa.modoMatchup === modo) {
        estado.filtroMapa.modoMatchup = '';
      }
      montarMapaMundi();
    };
    $('#f-fraco-contra').onchange = (ev) => mudarMatchup('fraco', ev.target.checked);
    $('#f-forte-contra').onchange = (ev) => mudarMatchup('forte', ev.target.checked);
    ligarDobraDeFiltros();
  }

  if (nome === 'pokedex') ligarPokedex();
  if (nome === 'shinys') ligarShinys();
  if (nome === 'p5s') ligarP5s();

  if (nome === 'bosses') montarBosses();
  if (nome === 'ginasios') montarGinasios();
  if (nome === 'campeonato') montarCampeonato();
  if (nome === 'pokepedia') montarPokepedia();

  if (nome === 'perfil') {
    estado.caraPerfilDesenhada =
      `${estado.eu?.loja?.looktype}|${empacotarVisual(estado.eu?.loja?.visual).join(',')}`;
    $('#pf-retrato').appendChild(spriteDeMim(56));
    montarVitrinePerfil();
    $('#pf-vitrine-editar')?.addEventListener('click', abrirEditorVitrine);
    $('#pf-avatar')?.addEventListener('click', abrirEditorDeAvatar);
    $('#pf-armario')?.addEventListener('click', () => abrirModal('armario'));
    $('#pf-stats-publico')?.addEventListener('change', (ev) => {
      enviar({ t: 'perfil.statsPublico', publico: ev.target.checked });
    });
    // A parte de conta chega depois, sem segurar a abertura do modal — e as estatísticas também.
    montarContaDoPerfil();
    pedirEstatisticasDaConta();
  }

  if (nome === 'armario') montarArmario();
  if (nome === 'passe') montarPasse();
  if (nome === 'casa') aoAbrirCasa();
  if (nome === 'afiliados') montarAfiliados();
  if (nome === 'votar') montarVotar();
  if (nome === 'twitch') montarTwitch();
  if (nome === 'kick') montarKick();
  if (nome === 'calculadora') ligarCalculadora();
  if (nome === 'configuracoes') ligarConfiguracoes();
  if (nome === 'amigos') {
    $('#modal .modal-caixa').classList.remove('ver-painel'); // celular: começa na lista
    ligarAmigos();
  }

  if (nome === 'community') {
    $('#cm-anunciar').onclick = abrirAnuncio;
    $('#cm-deposito').onclick = () => abrirModal('deposito');
    $('#cm-withdraw').onclick = () => abrirModal('withdraw');
    $('#cm-historico').onclick = abrirHistoricoVendas;
    $('#cm-historico-compras').onclick = abrirHistoricoCompras;
    $('#cm-historico-global').onclick = abrirHistoricoGlobal;
    $('#cm-favoritos-atalho')?.addEventListener('click', alternarAbaFavoritos);
    $('#cm-meus').onclick = () => {
      estado.cmAba = estado.cmAba === 'meus' ? 'vitrine' : 'meus';
      estado.cmPagina = 0;
      abrirModal('community'); // redesenha a barra de cima com o botão no estado certo
    };
    // Mexer em QUALQUER filtro sai de "meus anúncios": o filtro é da vitrine, e deixar os
    // dois juntos faria o clique parecer não ter efeito nenhum.
    const aplicarFiltro = (mudar) => {
      estado.cmAba = 'vitrine';
      mudar();
      // As três de `ORDENS_MERCADO` valem nas duas abas, então trocar de aba não pode mais
      // deixar o `<select>` mostrando uma opção que o servidor ignora. O que era exclusivo de
      // pokémon virou critério, e a troca para itens zera os critérios logo abaixo.
      if (!ORDENS_MERCADO.some((o) => o.id === estado.cmFiltro.ordem)) {
        estado.cmFiltro.ordem = ORDENS_MERCADO[0].id;
      }
      estado.cmPagina = 0;
      // `abrirModal` fecha a folha de filtros de propósito — ela não pode vazar de uma tela
      // para a outra. Só que aqui o redesenho nasce DE DENTRO dela: fechar seria arrancar a
      // folha da mão de quem ainda está montando o filtro, e combinar "Apenas P5" com um IV
      // mínimo custaria uma reabertura por toque. Guarda antes, devolve depois.
      const folhaAberta = $('#modal .modal-caixa')?.classList.contains('filtros-abertos');
      abrirModal('community'); // redesenha a barra: os filtros dela dependem da aba
      if (folhaAberta) reabrirFolhaDeFiltros();
    };

    const aplicarMoedaFiltro = (moeda) => {
      if (estado.cmFiltro.moeda === moeda) return;
      aplicarFiltro(() => { estado.cmFiltro.moeda = moeda; });
    };

    $('.cm-moeda-bar')?.addEventListener('click', (ev) => {
      const b = ev.target.closest('[data-moeda-filtro]');
      if (!b) return;
      aplicarMoedaFiltro(b.dataset.moedaFiltro);
    });

    $('.cm-filtros').onclick = (ev) => {
      const moedaBtn = ev.target.closest('[data-moeda-filtro]');
      if (moedaBtn) {
        aplicarMoedaFiltro(moedaBtn.dataset.moedaFiltro);
        return;
      }
      const b = ev.target.closest('.cm-filtro');
      // O atalho "vender diamantes" usa a fôrma do `.cm-filtro` (é a linguagem da barra), mas
      // não é um filtro: ele tem ouvinte próprio, logo abaixo, e não pode cair aqui.
      if (!b || b.id === 'cm-dia-vender') return;
      // Favoritos não é filtro da vitrine: é outra lista, e trocar para ela não mexe nos filtros.
      if (b.id === 'cm-favoritos') return alternarAbaFavoritos();
      aplicarFiltro(() => {
        if (b.id === 'cm-shiny') estado.cmFiltro.soShiny = !estado.cmFiltro.soShiny;
        else if (b.id === 'cm-p5') estado.cmFiltro.soP5 = !estado.cmFiltro.soP5;
        else if (b.id === 'cm-tm-elemental') estado.cmFiltro.soTmElemental = !estado.cmFiltro.soTmElemental;
        else if (b.id === 'cm-tm-aoe') estado.cmFiltro.soTmAoe = !estado.cmFiltro.soTmAoe;
        else if (b.id === 'cm-sem-outland') estado.cmFiltro.semOutland = !estado.cmFiltro.semOutland;
        else if (b.id === 'cm-agregar') {
          estado.cmFiltro.agregarEspecies = !estado.cmFiltro.agregarEspecies;
          // Desligar DENTRO de uma espécie aberta volta para a lista inteira — é o que o botão
          // promete. Sem isto, a faixa "‹ Todas as espécies · Dragonite" continuaria de pé numa
          // vitrine que acabou de deixar de ter espécies.
          estado.cmEspecieSel = null;
          // E a lista em memória é de OUTRO formato (grupos de espécie não têm `ficha`): a
          // pintura acontece antes de a resposta nova chegar, e sem zerar aqui ela desenharia
          // card de anúncio com linha de espécie. Ver `dadosDaGradeCerta`.
          estado.cmDados = { linhas: [], carregando: true };
        }
        else if (b.id === 'cm-so-estoque') estado.cmFiltro.soComEstoque = !estado.cmFiltro.soComEstoque;
        else if ('tipo' in b.dataset) {
          estado.cmFiltro.tipo = b.dataset.tipo;
          // Trocar de aba volta para a GRADE de espécies: a aba de pokémon tem de reabrir na
          // primeira tela, e não dentro do Dragonite que o jogador olhou antes de ir aos itens.
          estado.cmEspecieSel = null;
          if (b.dataset.tipo === 'pokemon') {
            if (!estado.cmFiltro.moeda) estado.cmFiltro.moeda = MOEDA_TODAS;
          } else {
            // A MOEDA fica como está, inclusive em "Todas": itens e diamantes a leem como
            // Coins (ver `moedaDoPedido`), e zerá-la aqui faria quem deu uma olhada nos itens
            // voltar para Pokémon com o padrão trocado sem ter pedido nada.
            estado.cmFiltro.soShiny = false;
            estado.cmFiltro.soP5 = false;
            estado.cmFiltro.soTmElemental = false;
            estado.cmFiltro.soTmAoe = false;
            estado.cmFiltro.semOutland = false;
            zerarFaixasDoMercado(estado.cmFiltro);
            // Item não tem IV nem nota: guardar os critérios ligados voltaria a mandá-los ao
            // servidor na aba errada, e o seletor que os mostra nem está desenhado ali.
            estado.cmFiltro.criterios = [];
          }
        } else if ('cat' in b.dataset) estado.cmFiltro.categoria = b.dataset.cat;
      });
    };

    // O atalho da barra lateral da aba de Diamantes: abre a folha de anunciar já no passo
    // certo. `stopPropagation` porque ele mora dentro de `.cm-filtros`, cujo clique é o
    // manipulador dos filtros — sem isso ele seria lido como "trocar de aba" também.
    $('#cm-dia-vender')?.addEventListener('click', (ev) => {
      ev.stopPropagation();
      abrirAnuncio('diamante');
    });

    $('#cm-limpar')?.addEventListener('click', () => aplicarFiltro(limparFiltrosDoMercado));

    // Os 18 tipos, na mesma paleta do mapa-múndi, agora dentro do dropdown. Clicar no que já
    // está aceso desliga: é o caminho de volta para "todos" sem ter de procurar o botão.
    //
    // O `.cm-elem` no seletor (e não `[data-elem]` solto) é o que impede o clique no `<summary>`
    // de contar como escolha — ele carrega `data-elem` para o CSS pintar a plaquinha do tipo, e
    // sem esta distinção abrir o menu já aplicaria o filtro que ele ia mostrar.
    // `?.` porque a aba de DIAMANTES não desenha este seletor (diamante não tem tipo
    // elemental). Sem ele, `abrirModal` estourava num `null.onclick` e o `pedirMercado()` no
    // fim desta função nunca rodava — a vitrine ficava vazia, com o erro só no console.
    $('#cm-tipos')?.addEventListener('click', (ev) => {
      const b = ev.target.closest('.cm-elem');
      if (!b) return;
      aplicarFiltro(() => {
        estado.cmFiltro.elemento = estado.cmFiltro.elemento === b.dataset.elem ? '' : b.dataset.elem;
      });
    });

    /**
     * "Filtrar por": liga e desliga critérios SEM fechar o menu.
     *
     * Fechar a cada clique seria certo num `<select>` (escolha única) e é errado aqui: a graça
     * do filtro composto é montar "potência + IV + nota" numa sentada, e reabrir o menu entre
     * cada um custaria três toques a mais no celular por combinação.
     *
     * Por isso este ramo NÃO passa por `aplicarFiltro` (que redesenha a tela inteira e mataria
     * o `<details>` aberto): redesenha só o miolo do dropdown e pede a lista nova.
     */
    const dropCrit = $('#cm-filtrar');
    dropCrit?.addEventListener('click', (ev) => {
      const limpar = ev.target.closest('#cm-crit-limpar');
      const b = limpar ? null : ev.target.closest('.cm-crit');
      if (!b && !limpar) return;
      ev.preventDefault();
      if (limpar) estado.cmFiltro.criterios = [];
      else alternarCriterioMercado(b.dataset.crit);
      estado.cmAba = 'vitrine';
      estado.cmPagina = 0;
      repintarFiltrarPor();
      pedirMercado();
    });

    $('#cm-ordem')?.addEventListener('change', (ev) => {
      estado.cmFiltro.ordem = ev.target.value;
      estado.cmPagina = 0;
      estado.cmAba = 'vitrine';
      pedirMercado();
    });

    // Busca com folga de 250 ms: cada tecla vira consulta ao Postgres, e digitar
    // "water stone" dispararia onze.
    let timerBusca = null;
    $('#cm-busca').oninput = (ev) => {
      estado.cmFiltro.busca = ev.target.value;
      estado.cmPagina = 0;
      estado.cmAba = 'vitrine';
      // Buscar por nome é procurar OUTRA espécie: quem digita "chariz" dentro das ofertas de
      // Dragonite quer a grade de volta, não uma lista de Dragonite chamados Charizard (vazia).
      estado.cmEspecieSel = null;
      clearTimeout(timerBusca);
      timerBusca = setTimeout(pedirMercado, 250);
    };

    let timerStats = null;
    const aplicarFiltroNum = (campo, raw) => {
      estado.cmFiltro[campo] = raw;
      estado.cmPagina = 0;
      estado.cmAba = 'vitrine';
      clearTimeout(timerStats);
      timerStats = setTimeout(pedirMercado, 300);
    };
    for (const { id, campos: [piso, teto] } of FAIXAS_MERCADO) {
      $(`#cm-${id}-min`)?.addEventListener('input', (ev) => aplicarFiltroNum(piso, ev.target.value));
      $(`#cm-${id}-max`)?.addEventListener('input', (ev) => aplicarFiltroNum(teto, ev.target.value));
    }

    ligarDobraDeFiltros();
    pedirMercado();
    pintarMercado(); // desenha o que já estava em memória enquanto a resposta não chega
  }

  if (nome === 'deposito' || nome === 'withdraw') {
    // Desenha já com o que estiver em cache (abrir de novo não pisca) e pede o painel novo;
    // quem redesenha quando a resposta chega é `aoReceberOrbs`.
    if (estado.orbs) (nome === 'deposito' ? montarDeposito : montarWithdraw)();
    enviar({ t: 'orbs.painel' });
  }

  if (nome === 'diamantes') ligarCompraDiamantes();

  if (nome === 'shop') {
    montarLoja();
    estado.assinaturaLoja = assinaturaLojaGrade();
    // Recarregar diamante é a única porta de dinheiro que a Loja abre. Depósito e saque de
    // gema mudaram de lugar: são do Mercado da Comunidade, que é onde a gema se usa.
    $('#loja-comprar-diamantes').onclick = () => abrirCompraDeDiamantes();
    $('.loja-filtros').onclick = (ev) => {
      const b = ev.target.closest('.cm-filtro');
      if (!b) return;
      if ('grupo' in b.dataset) {
        estado.grupoLoja = b.dataset.grupo;
        // Sair de Boosts leva o filtro de tipo junto: guardá-lo faria a seção reabrir já
        // filtrada por um tipo escolhido dez minutos antes, sem nada na tela dizendo isso.
        estado.boostLoja = '';
        return abrirModal('shop'); // a barra lateral muda: o 2º nível só existe em Boosts
      }
      estado.boostLoja = b.dataset.boost;
      for (const outro of $('.loja-filtros').querySelectorAll('[data-boost]')) {
        outro.classList.toggle('on', outro === b);
      }
      montarLoja();
      estado.assinaturaLoja = assinaturaLojaGrade();
    };
  }

  // `montarPvp` liga as abas, pede `pvp.info` e `guild.pvp.info` e pinta a aba escolhida —
  // por isso aqui não há mais nada. Repetir os dois pedidos daria duas respostas para uma
  // tela só, e a segunda chegaria depois de o jogador já ter trocado de aba.
  if (nome === 'pvp') montarPvp();

  if (nome === 'ranking') {
    // O placar é do banco, não do estado do jogador: pede tudo de uma vez ao abrir, para as
    // abas trocarem sem espera e a coluna de destaques nascer completa. Bosses só pede o
    // boss selecionado — são dezenas de lendários e cada um é uma consulta própria.
    estado.buscaRanking = '';
    if (!estado.rankingBossKey) estado.rankingBossKey = bossKeyRankingPadrao();
    for (const a of ABAS_RANKING) {
      if (a.id === 'bosses') pedirRankingBoss(estado.rankingBossKey);
      else enviar({ t: 'ranking.pedir', aba: a.id });
    }
    pintarRanking();
    // No celular as sete abas são uma FITA que rola de lado, e só três cabem na tela. Quem
    // fechou o Ranking na aba "Guilds" reabria vendo Treinadores, Pokémon Forte e Top Catch —
    // nenhuma acesa —, e o placar embaixo era de uma aba invisível. Trazer a acesa para o
    // quadro é o que faz a fita se explicar sozinha.
    $('.rk-aba.on')?.scrollIntoView({ inline: 'center', block: 'nearest' });
    $('.rk-abas').onclick = (ev) => {
      const b = ev.target.closest('.rk-aba');
      if (!b) return;
      for (const outro of $('.rk-abas').children) outro.classList.toggle('on', outro === b);
      b.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
      abrirAbaRanking(b.dataset.aba);
    };
    $('#rk-boss-select')?.addEventListener('change', (ev) => {
      const key = ev.target.value;
      if (!key || key === estado.rankingBossKey) return;
      pedirRankingBoss(key);
      pintarRanking();
    });
    $('#rk-busca').oninput = (ev) => {
      estado.buscaRanking = ev.target.value;
      pintarRanking();
    };
  }

  if (nome === 'market') {
    $('.mk-abas').onclick = (ev) => {
      const b = ev.target.closest('.mk-aba');
      if (!b) return;
      estado.abaMarket = b.dataset.aba;
      abrirModal('market'); // redesenha o cabeçalho junto, para a aba certa ficar acesa
    };
    estado.assinaturaMarket = assinaturaMarket();
    pintarMarket();
  }

  if (nome === 'bolsa') {
    $('.bolsa-abas').onclick = (ev) => {
      const b = ev.target.closest('.bolsa-aba');
      if (!b) return;
      estado.abaBolsa = b.dataset.aba;
      abrirModal('bolsa');
    };
    estado.assinaturaBolsa = null;
    pintarBolsaCorpo();
    estado.assinaturaBolsa = assinaturaBolsa();
  }
}

// ------------------------------------------------- confirmação de ação em lote

// ------------------------------------------------------ revelação de recompensa
//
// A tela de "você recebeu" do sorteio da Casa, da Bicicleta e da peça de TM do boss.
//
// A dopamina é PROPORCIONAL à raridade, e isso é o design, não enfeite: se a Casa Comum
// explodisse em raios e confete, a Lendária não teria para onde subir — e quem tira a Comum
// (74,5% das vezes) aprenderia a fechar a tela sem olhar. Os cinco degraus (`nivel` 0–4) usam
// os mesmos ids de raridade da Casa e da Bicicleta; o que cada um acende mora no CSS
// (`.recompensa`). `nivel: -1` é o "não veio nada": a peça do boss que não caiu.
//
// Uma revelação por vez: se chegar outra com uma aberta, ela entra na fila e aparece quando
// a primeira fechar.

const RC_NIVEIS = ['comum', 'incomum', 'rara', 'mitica', 'lendaria'];
const PIECE_ELEMENTAL_UI = 59194;
const PIECE_AOE_UI = 40530;
// Os dois FRAGMENTOS DE MEGA caem do mesmo boss, na mesma escada de chance da peca de TM (o
// comum) e na metade dela (o shiny). Estes valores sao so o plano B: o id verdadeiro vem em
// `estado.mega`, do welcome, como acontece com a peca.
const FRAGMENTO_MEGA_UI = 70014;
const FRAGMENTO_MEGA_SHINY_UI = 70015;

/** Caiu TM Disk Piece (Elemental ou AoE) entre os drops de um boss? */
function dropouPecaDeTm(drops) {
  const cfg = estado.tmResearcher ?? {};
  const ids = [cfg.pieceElemental ?? PIECE_ELEMENTAL_UI, cfg.pieceAoe ?? PIECE_AOE_UI];
  return (drops ?? []).some((d) => ids.includes(Number(d.itemId)) && Number(d.qtd) > 0);
}
const rcFila = [];
let rcAoFechar = null;
// As opções da revelação aberta — `lote` é o que decide se o "Show para os X" aparece.
let rcAtual = null;

function imagemRecompensa(src, classe) {
  const img = new Image();
  img.src = src;
  img.alt = '';
  img.className = classe;
  return img;
}

const faixaDaRaridade = (nivel) => {
  if (nivel >= 4) return t('recompensa.faixaLendaria');
  if (nivel === 3) return t('recompensa.faixaMitica');
  if (nivel === 2) return t('recompensa.faixaRara');
  return '';
};

function mostrarRecompensa(opcoes) {
  const el = $('#recompensa');
  if (!el) return opcoes.aoFechar?.();
  if (!el.classList.contains('hidden')) {
    rcFila.push(opcoes);
    return void pintarPilhaRecompensa();
  }
  abrirRecompensa(opcoes);
}

/**
 * `lote` marca as telas do automático do boss: elas não fecham sozinhas e, com duas ou mais
 * esperando, ganham o botão que fecha todas de uma vez e mostra o resumo (`fecharLoteDoBoss`).
 * `classe` vai na raiz, para um layout próprio — o resumo troca a arte por uma lista.
 */
function abrirRecompensa(opcoes) {
  const {
    nivel = 0, faixa = '', lead = '', nome = '', sub = '', arte = null,
    rotuloOk = null, confete = null, aoFechar = null, classe = '',
  } = opcoes;
  const el = $('#recompensa');
  const n = Math.min(4, Math.max(-1, Math.floor(nivel)));
  rcAtual = opcoes;
  // Trocar a classe inteira (e forçar um reflow) é o que REINICIA as animações: sem isso, a
  // segunda Lendária da sessão abriria com os raios já parados no meio da volta.
  el.className = 'recompensa';
  void el.offsetWidth;
  el.className = `recompensa rc-${n < 0 ? 'nada' : RC_NIVEIS[n]}${classe ? ` ${classe}` : ''}`;
  el.setAttribute('aria-hidden', 'false');

  $('#rc-faixa').textContent = faixa;
  $('#rc-faixa').hidden = !faixa;
  $('#rc-lead').textContent = lead;
  $('#rc-nome').textContent = nome;
  $('#rc-sub').innerHTML = sub;
  $('#rc-arte').replaceChildren(...(arte ? [arte] : []));
  $('#rc-ok').textContent = rotuloOk ?? t('recompensa.ok');

  const part = $('#rc-particulas');
  part.replaceChildren();
  const sorte = (a, b) => a + Math.random() * (b - a);
  const faiscas = [0, 0, 8, 16, 26][n] ?? 0;
  const corFaisca = n >= 4 ? ['#fff7d0', '#ffe07a'] : n === 3 ? ['#f0dcff', '#d6a8ff'] : ['#e6f6ff', '#7fd0ff'];
  for (let i = 0; i < faiscas; i++) {
    const s = document.createElement('i');
    s.className = 'rc-faisca';
    s.style.cssText = `--x:${sorte(20, 80)}%;--y:${sorte(12, 82)}%;--t:${sorte(10, 30)}px;`
      + `--c:${corFaisca[i % 2]};--d:${sorte(1.1, 2.3)}s;--a:${sorte(0, 1.6)}s`;
    part.appendChild(s);
  }
  const cores = ['#ffe07a', '#e8a800', '#ffa7d7', '#ba5ad1', '#6fd08a', '#7fd0ff', '#fff7d0'];
  const confetes = confete ?? (n >= 4 ? 80 : 0);
  for (let i = 0; i < confetes; i++) {
    const c = document.createElement('i');
    c.className = 'rc-confete';
    c.style.cssText = `--x:${sorte(0, 100)}%;--c:${cores[i % cores.length]};`
      + `--d:${sorte(2.4, 4.6)}s;--a:${sorte(0, 2.6)}s;--r:${sorte(360, 1080)}deg`;
    part.appendChild(c);
  }

  rcAoFechar = aoFechar;
  pintarPilhaRecompensa();
}

/**
 * As cartas atrás da aberta (uma por revelação na fila, até duas) e o "Show para os X
 * pop-ups", que só aparece numa tela do automático do boss com outra do mesmo lote esperando.
 */
function pintarPilhaRecompensa() {
  $('#rc-pilha').dataset.n = String(Math.min(2, rcFila.length));
  const lote = rcAtual?.lote ? 1 + rcFila.filter((o) => o.lote).length : 0;
  const bt = $('#rc-todos');
  bt.hidden = lote < 2;
  if (lote >= 2) bt.textContent = t('recompensa.fecharTodas', { n: num(lote) });
}

function fecharRecompensa() {
  const el = $('#recompensa');
  if (!el || el.classList.contains('hidden')) return;
  el.className = 'recompensa hidden';
  el.setAttribute('aria-hidden', 'true');
  $('#rc-particulas').replaceChildren();
  rcAtual = null;
  const depois = rcAoFechar;
  rcAoFechar = null;
  depois?.();
  const proxima = rcFila.shift();
  if (proxima) abrirRecompensa(proxima);
}

$('#rc-ok').onclick = fecharRecompensa;
$('#rc-todos').onclick = () => fecharLoteDoBoss();
// Bloco, não expressão — ver a nota do `#confirmar`: devolver `false` cancelaria o clique.
$('#recompensa').onclick = (ev) => {
  if (ev.target === $('#recompensa') || ev.target.classList.contains('rc-palco')) fecharRecompensa();
};
document.addEventListener('keydown', (ev) => {
  if (ev.key === 'Escape' && !$('#recompensa').classList.contains('hidden')) fecharRecompensa();
});

/**
 * Casa fabricada: "Você recebeu uma: Casa Lendária", com o NÚMERO dela no servidor.
 *
 * Também a do CRAFT (`e.de`): a mesma tela, com uma linha a mais dizendo de onde ela veio e,
 * se havia pokémon nos postos das cinco, para onde eles foram.
 */
function revelarCasa(e) {
  const rar = e.raridade;
  const nivel = Math.max(0, RC_NIVEIS.indexOf(rar));
  const meta = metaRaridade(rar);
  // O número vem primeiro e em destaque: "a #000042 do servidor" é o que se tira print e manda
  // no chat. Depois, o que a casa rende e onde usá-la — ela já vale, não há o que equipar.
  const partes = [];
  if (e.casaId) partes.push(`<b class="rc-num-casa">${escapar(numeroDaCasa(e.casaId))}</b>`);
  if (meta) partes.push(escapar(resumoDaCasa(meta)));
  const craft = e.de
    ? [
      t('recompensa.casaSubCraft', { n: num(e.consumidas?.length ?? 5), rar: escapar(nomeCasaRaridade(e.de)) }),
      e.soltos ? t(e.soltos === 1 ? 'recompensa.casaSubColecaoUm' : 'recompensa.casaSubColecao', { n: num(e.soltos) }) : '',
    ].filter(Boolean).map((l) => `<br>${l}`).join('')
    : '';
  mostrarRecompensa({
    nivel,
    faixa: faixaDaRaridade(nivel),
    lead: t('recompensa.recebeuUma'),
    nome: nomeCasaRaridade(rar),
    // Com as vagas de uso cheias a casa chega GUARDADA — a tela diz, senão ela parece não valer.
    sub: partes.length
      ? `${partes.join(' · ')}<br>${e.emUso === false
        ? t('recompensa.casaSubGuardada', { max: num(e.maxEmUso ?? maxCasasEmUso()) })
        : t('recompensa.casaSubAtiva')}${craft}`
      : '',
    arte: imagemRecompensa(`/img/itens/casa-${rar}.png`, 'rc-img-casa'),
  });
}

/** Bicicleta fabricada: a mesma escada da Casa, com a velocidade e onde equipar. */
function revelarBicicleta(e) {
  const rar = e.raridade;
  const nivel = Math.max(0, RC_NIVEIS.indexOf(rar));
  const meta = (estado.bicicletas?.raridades ?? []).find((r) => r.id === rar);
  // Do CRAFT: de onde ela veio e, se a equipada entrou nele, que a nova já saiu equipada — aí o
  // "equipe em Bolsa → Itens Raros" da fabricada mandaria o jogador fazer o que já está feito.
  const craft = e.de
    ? [
      t('recompensa.casaSubCraft', { n: num(e.consumidas?.length ?? 5), rar: escapar(nomeBicicletaRaridade(e.de)) }),
      e.equipada ? t('recompensa.bikeSubEquipada') : '',
    ].filter(Boolean).map((l) => `<br>${l}`).join('')
    : '';
  mostrarRecompensa({
    nivel,
    faixa: faixaDaRaridade(nivel),
    lead: t('recompensa.recebeuUma'),
    nome: nomeBicicletaRaridade(rar),
    // O número primeiro, como na Casa: "a #000007 do servidor" é o que se tira print.
    sub: [
      e.bicicletaId ? `<b class="rc-num-casa">${escapar(numeroDaBicicleta(e.bicicletaId))}</b>` : '',
      meta
        ? (e.equipada ? escapar(resumoDaBicicleta(meta)) : t('recompensa.bikeSub', { vel: escapar(resumoDaBicicleta(meta)) }))
        : '',
    ].filter(Boolean).join(' · ') + craft,
    arte: imagemRecompensa(`/img/itens/bicicleta-${rar}.png`, 'rc-img-pixel'),
  });
}

/** A peça de TM que ESTE boss pode dar — sai da tabela de drops que o welcome manda. */
function pecaDoBoss(key) {
  const cfg = estado.tmResearcher ?? {};
  const ids = [cfg.pieceElemental ?? PIECE_ELEMENTAL_UI, cfg.pieceAoe ?? PIECE_AOE_UI];
  return (fichaDoBoss(key)?.drops ?? []).find((d) => ids.includes(d.itemId))?.itemId ?? null;
}

/** A tela da peça: com dopamina quando caiu, cinza e com "boa sorte" quando não. */
function mostrarRevelacaoPeca({ pecaId, qtd, aoFechar = null, lote = false }) {
  const cfg = estado.tmResearcher ?? {};
  const aoe = pecaId === (cfg.pieceAoe ?? PIECE_AOE_UI);
  const nome = t(aoe ? 'recompensa.pecaAoe' : 'recompensa.pecaElemental');
  const arte = imagemRecompensa(iconeItem(pecaId) ?? `/assets/${ICONE_ITEM_GENERICO}`, 'rc-img-pixel');
  if (!qtd) {
    return mostrarRecompensa({
      nivel: -1,
      nome: t('recompensa.semPeca', { nome }),
      sub: escapar(t('recompensa.semPecaSub')),
      arte,
      rotuloOk: t('bossLoot.ok'),
      aoFechar,
      lote,
    });
  }
  mostrarRecompensa({
    nivel: 3,
    confete: 28,
    faixa: t('recompensa.pecaFaixa'),
    lead: t('recompensa.pecaLead'),
    nome: qtd > 1 ? `${nome} ×${qtd}` : nome,
    sub: t('recompensa.pecaSub', { custo: num(aoe ? (cfg.custoAoe ?? 10) : (cfg.custoElemental ?? 10)) }),
    arte,
    aoFechar,
    lote,
  });
}

/** Quanto deste item veio nos drops do boss (o mesmo item pode vir em mais de uma linha). */
function qtdNosDrops(drops, itemId) {
  return (drops ?? [])
    .filter((d) => Number(d.itemId) === Number(itemId))
    .reduce((s, d) => s + (Number(d.qtd) || 0), 0);
}

/**
 * A tela do FRAGMENTO DE MEGA — a mesma da peça de TM, um degrau acima quando é o shiny.
 *
 * O comum sai em `nível 3` (Mítica) porque ele cai na MESMA escada da peça de TM (0,5% no
 * primeiro par de lendários, +0,5 p.p. por par), e o shiny em `nível 4` (LENDÁRIA, com os 80
 * confetes) porque a chance dele é a METADE — 0,25% lá embaixo. É a regra da casa, escrita no
 * cabeçalho deste bloco: a dopamina é proporcional à raridade. Dar a mesma festa aos dois
 * apagaria justamente o drop mais raro que um boss entrega.
 */
function mostrarRevelacaoFragmentoMega({ itemId, qtd, shiny, aoFechar = null, lote = false }) {
  const cfg = estado.mega ?? {};
  const nome = nomeItem(itemId, t(shiny ? 'item.fragmentoMegaShiny' : 'item.fragmentoMega'));
  const custo = num(shiny ? (cfg.custoShiny ?? 10) : (cfg.custo ?? 10));
  mostrarRecompensa({
    nivel: shiny ? 4 : 3,
    confete: shiny ? 80 : 28,
    faixa: t(shiny ? 'recompensa.fragMegaFaixaShiny' : 'recompensa.pecaFaixa'),
    lead: t('recompensa.pecaLead'),
    nome: qtd > 1 ? `${nome} ×${qtd}` : nome,
    sub: t('recompensa.fragMegaSub', { custo }),
    arte: imagemRecompensa(iconeItem(itemId) ?? `/assets/${ICONE_ITEM_GENERICO}`, 'rc-img-pixel'),
    aoFechar,
    lote,
  });
}

/**
 * Boss derrotado: as telas de drop dele, em fila. Devolve `true` se abriu alguma.
 *
 * São até três: a peça de TM, o Fragmento de MEGA Stone e o Fragmento de MEGA Shiny Stone.
 * A ordem é crescente de raridade de propósito — o shiny fecha a sequência, e não abre.
 *
 * Duas regras que não são detalhe:
 *
 *   · Só a PEÇA tem tela de "não veio". Ela é o que se vai buscar no boss, então o vazio dela
 *     informa; já três telas de "não veio" por vitória seriam três cliques que se aprende a
 *     dar sem ler — o oposto do que este bloco existe para fazer.
 *   · O `aoFechar` (que abre o resumo do boss) vai na ÚLTIMA tela, e não na primeira:
 *     `fecharRecompensa` dispara o `aoFechar` ANTES de puxar a próxima da fila, então
 *     prendê-lo na primeira abriria o resumo por cima das que ainda faltam.
 *
 * No automático (`auto`) só o que CAIU aparece: um "não veio" a cada repetição prenderia a
 * tela de quem ligou o automático para não precisar clicar. Mas o que caiu FICA — as telas
 * se empilham até o jogador voltar (fechar sozinho em 4,5 s fazia quem estava longe perder o
 * drop), e o "Show para os X pop-ups" fecha a pilha inteira e abre o resumo da série.
 */
function revelarDropsDoBoss(e, { aoFechar = null, auto = false } = {}) {
  const lote = auto;
  const telas = [];

  const pecaId = pecaDoBoss(e.key);
  if (pecaId) {
    const qtd = qtdNosDrops(e.drops, pecaId);
    if (qtd || !auto) telas.push((extra) => mostrarRevelacaoPeca({ pecaId, qtd, lote, ...extra }));
  }

  const cfg = estado.mega ?? {};
  for (const [itemId, shiny] of [
    [cfg.fragmentoId ?? FRAGMENTO_MEGA_UI, false],
    [cfg.fragmentoShinyId ?? FRAGMENTO_MEGA_SHINY_UI, true],
  ]) {
    const qtd = qtdNosDrops(e.drops, itemId);
    if (qtd > 0) telas.push((extra) => mostrarRevelacaoFragmentoMega({ itemId, qtd, shiny, lote, ...extra }));
  }

  // O MYSTICTICKET fecha a fila: é o drop mais raro do boss, de longe (ver `shared/mistico.mjs`).
  const qtdTicket = qtdNosDrops(e.drops, MYSTIC_TICKET_ID);
  if (qtdTicket > 0) telas.push((extra) => mostrarRevelacaoTicketMistico({ qtd: qtdTicket, lote, ...extra }));

  if (!telas.length) return false;
  // A fila do `mostrarRecompensa` cuida do resto: a primeira abre, as outras esperam.
  telas.forEach((abrir, i) => abrir(i === telas.length - 1 ? { aoFechar } : {}));
  return true;
}

/**
 * O placar da repetição automática do boss: zera quando o interruptor liga e vira o resumo
 * quando ele desliga — acabaram os tokens, ou o jogador parou. É o "resultado final" que a
 * série não tinha: cada tela conta um drop, e ninguém somava.
 *
 * Mora só no cliente, então conta o que ESTA aba viu; recarregar no meio recomeça a conta.
 */
const loteBoss = { vitorias: 0, itens: {} };

function zerarLoteBoss() {
  loteBoss.vitorias = 0;
  loteBoss.itens = {};
}

function somarNoLoteBoss(drops) {
  loteBoss.vitorias++;
  for (const d of drops ?? []) {
    const id = Number(d.itemId);
    loteBoss.itens[id] = (loteBoss.itens[id] ?? 0) + (Number(d.qtd) || 0);
  }
}

/**
 * As opções da tela de resumo: as cinco coisas raras que um boss dá (as duas peças de TM, os dois
 * fragmentos de Mega e o MysticTicket), com as que não caíram apagadas mas presentes — "0
 * fragmentos" também é resposta. `final` só troca a frase de baixo.
 */
function opcoesDoResumoBoss({ final }) {
  const tm = estado.tmResearcher ?? {};
  const mega = estado.mega ?? {};
  const fragId = mega.fragmentoId ?? FRAGMENTO_MEGA_UI;
  const fragShinyId = mega.fragmentoShinyId ?? FRAGMENTO_MEGA_SHINY_UI;
  const lista = document.createElement('div');
  lista.className = 'rc-resumo';
  for (const [itemId, nome] of [
    [tm.pieceElemental ?? PIECE_ELEMENTAL_UI, t('recompensa.pecaElemental')],
    [tm.pieceAoe ?? PIECE_AOE_UI, t('recompensa.pecaAoe')],
    [fragId, nomeItem(fragId, t('item.fragmentoMega'))],
    [fragShinyId, nomeItem(fragShinyId, t('item.fragmentoMegaShiny'))],
    [MYSTIC_TICKET_ID, nomeItem(MYSTIC_TICKET_ID, 'MysticTicket')],
  ]) {
    const qtd = loteBoss.itens[itemId] ?? 0;
    const linha = document.createElement('div');
    linha.className = `rc-resumo-linha${qtd ? '' : ' zero'}`;
    linha.appendChild(imgItem(itemId, 32));
    linha.insertAdjacentHTML('beforeend', `<span>${escapar(nome)}</span><b>×${num(qtd)}</b>`);
    lista.appendChild(linha);
  }
  return {
    resumoBoss: true,
    classe: 'rc-com-resumo',
    faixa: t('recompensa.resumoFaixa'),
    lead: t(loteBoss.vitorias === 1 ? 'recompensa.resumoLeadUma' : 'recompensa.resumoLead', { n: num(loteBoss.vitorias) }),
    arte: lista,
    sub: escapar(t(final ? 'recompensa.resumoFim' : 'recompensa.resumoSegue')),
  };
}

/** O automático desligou: o resumo entra no fim da fila, atrás das telas de drop que faltam. */
function fecharSerieDoBoss() {
  if (!loteBoss.vitorias) return;
  mostrarRecompensa(opcoesDoResumoBoss({ final: true }));
  zerarLoteBoss();
}

/**
 * "Show para os X pop-ups": fecha a aberta e todas as do lote que esperam, e mostra o resumo
 * na frente do que sobrar na fila (uma Casa, por exemplo, não é do lote e continua lá).
 *
 * Se a série já acabou, o resumo FINAL está na fila e é ele que abre — o placar já foi zerado,
 * e montar outro agora mostraria zero em tudo.
 */
function fecharLoteDoBoss() {
  const resumo = rcFila.find((o) => o.resumoBoss) ?? opcoesDoResumoBoss({ final: false });
  const resto = rcFila.filter((o) => !o.lote && !o.resumoBoss);
  rcFila.splice(0, rcFila.length, resumo, ...resto);
  fecharRecompensa();
}

// Só no servidor LOCAL: ver os degraus sem precisar de 20.000 sorteios para achar a Lendária.
//   pokeidleRecompensa('casa', 'lendaria') · pokeidleRecompensa('bicicleta', 'mitica')
//   pokeidleRecompensa('peca') · pokeidleRecompensa('peca-aoe') · pokeidleRecompensa('sem-peca')
//   pokeidleRecompensa('frag-mega') · pokeidleRecompensa('frag-mega-shiny')
//   pokeidleRecompensa('boss-tudo') — a fila inteira: peça + fragmento + fragmento shiny
//   pokeidleRecompensa('boss-auto', 8) — 8 vitórias do automático, com drops bem mais
//     generosos que os de verdade para a pilha crescer · pokeidleRecompensa('boss-auto-fim')
//     desliga a série e mostra o resumo final
if (['localhost', '127.0.0.1'].includes(location.hostname)) {
  window.pokeidleRecompensa = (tipo = 'casa', raridade = 'lendaria', casaId = 42) => {
    if (tipo === 'casa') return revelarCasa({ raridade, casaId });
    if (tipo === 'bicicleta') return revelarBicicleta({ raridade });
    if (tipo === 'boss-auto') {
      const cfg = estado.mega ?? {};
      const chave = (estado.bossesJogaveis ?? []).find((b) => pecaDoBoss(b.key))?.key ?? null;
      const ids = [
        pecaDoBoss(chave) ?? PIECE_ELEMENTAL_UI,
        cfg.fragmentoId ?? FRAGMENTO_MEGA_UI,
        cfg.fragmentoShinyId ?? FRAGMENTO_MEGA_SHINY_UI,
      ];
      for (let i = 0; i < (Number(raridade) || 5); i++) {
        const drops = ids.filter(() => Math.random() < 0.4).map((itemId) => ({ itemId, qtd: 1 }));
        somarNoLoteBoss(drops);
        revelarDropsDoBoss({ key: chave, drops }, { auto: true });
      }
      return;
    }
    if (tipo === 'boss-auto-fim') return fecharSerieDoBoss();
    if (tipo === 'boss-tudo') {
      const cfg = estado.mega ?? {};
      const chave = (estado.bossesJogaveis ?? []).find((b) => pecaDoBoss(b.key))?.key ?? null;
      return revelarDropsDoBoss({
        key: chave,
        drops: [
          { itemId: pecaDoBoss(chave) ?? PIECE_ELEMENTAL_UI, qtd: 1 },
          { itemId: cfg.fragmentoId ?? FRAGMENTO_MEGA_UI, qtd: 1 },
          { itemId: cfg.fragmentoShinyId ?? FRAGMENTO_MEGA_SHINY_UI, qtd: 2 },
        ],
      }, { aoFechar: () => console.log('[teste] aoFechar disparou — aqui abriria o resumo do boss') });
    }
    if (tipo === 'frag-mega' || tipo === 'frag-mega-shiny') {
      const shiny = tipo === 'frag-mega-shiny';
      const cfg = estado.mega ?? {};
      const itemId = shiny
        ? (cfg.fragmentoShinyId ?? FRAGMENTO_MEGA_SHINY_UI)
        : (cfg.fragmentoId ?? FRAGMENTO_MEGA_UI);
      return mostrarRevelacaoFragmentoMega({ itemId, qtd: 1, shiny });
    }
    const pecaId = tipo === 'peca-aoe' ? PIECE_AOE_UI : PIECE_ELEMENTAL_UI;
    return mostrarRevelacaoPeca({ pecaId, qtd: tipo === 'sem-peca' ? 0 : 1 });
  };
}

// ---------------------------------------------------------------- boss loot

/**
 * O resumo da vitória, no vocabulário do diálogo de jogo: o seu boneco aceso no pedestal e o
 * boss nocauteado (sem cor) do outro lado do troféu; o que a luta rendeu em placas com ícone; e
 * os itens que caíram como cartas que entram uma depois da outra. É tela de PRÊMIO — mais festa
 * que uma confirmação, menos que a revelação da peça de TM, que passa antes dela quando cai
 * (ver `revelarDropsDoBoss`).
 */
function abrirModalBossLoot(e) {
  // A arte mora no catálogo da galeria (`bossesCatalogo`), não na ficha de quem tem arena.
  const lt = estado.bossesCatalogo?.find((b) => b.key === e.key)?.looktype ?? null;
  $('#boss-loot-palco').innerHTML = dlgPalco(`
    ${dlgAtor({
      arte: dlgArteTreinador(null, null, 64),
      nome: escapar(estado.eu?.nick ?? ''),
      sub: escapar(t('bossLoot.vitoria')),
      classe: 'novo',
    })}
    <span class="bl-trofeu" aria-hidden="true">${dlgIcone('trofeu', 30)}</span>
    ${dlgAtor({
      arte: lt ? dlgArteLt(lt, 72) : dlgArteHtml(dlgMedalha({ icone: 'coroa', tom: 'ouro' })),
      nome: escapar(e.nome ?? ''),
      sub: escapar(t('bossLoot.derrotado')),
      classe: 'sai',
    })}`, 'ouro');

  const placa = (ico, rotulo, valor) => `
    <div class="boss-loot-stat">
      <span class="bl-ico">${ico}</span>
      <span class="bl-txt"><small>${rotulo}</small><b>${valor}</b></span>
    </div>`;
  const stats = [
    placa(dlgIcone('pessoa', 18), t('bossLoot.xpTreinador'), `+${num(e.xpTreinador ?? e.xp ?? 0)}`),
    placa(`<span data-dlg-arquivo="${SPRITE_BOLA[1]}" data-dlg-px="22"></span>`, t('bossLoot.xpPokemon'), `+${num(e.xpPokemon ?? e.xp ?? 0)}`),
    placa(dlgIcone('coroa', 18), t('bossLoot.pontos'), `+${num(e.pontos ?? 1)}`),
  ];
  if (e.valor) stats.push(placa(`<img src="${srcIcone(ICONE_OURO)}" alt="">`, t('bossLoot.valorNpc'), num(e.valor)));
  $('#boss-loot-stats').innerHTML = stats.join('');

  // Cada carta entra com um atraso a mais (`--i`): o loot "cai" um item de cada vez.
  $('#boss-loot-drops').innerHTML = e.drops?.length
    ? e.drops.map((d, i) => `
      <span class="boss-loot-drop" style="--i:${i}">
        <span class="bl-drop-arte" data-dlg-item="${Number(d.itemId) || 0}" data-dlg-px="34"></span>
        <b>${escapar(d.nome)}</b>
        <span class="bl-drop-qtd">×${num(d.qtd)}</span>
      </span>`).join('')
    : `<p class="boss-loot-vazio">${escapar(t('bossLoot.vazio'))}</p>`;

  hidratarDialogo($('#boss-loot .modal-corpo'));
  $('#boss-loot').classList.remove('hidden');
}

// Fechado, o palco se esvazia: os sprites animados param de girar o relógio deles.
const fecharBossLoot = () => {
  $('#boss-loot').classList.add('hidden');
  $('#boss-loot-palco').replaceChildren();
};

$('#boss-loot-ok').onclick = fecharBossLoot;
$('#boss-loot').onclick = (ev) => {
  if (ev.target === $('#boss-loot')) fecharBossLoot();
};

// ---------------------------------------------------------------- TM Researcher

function abrirTmResearcher() {
  if (!estado.tmResearcher) return toast('TM Researcher indisponível');
  estado.tmAba = 'trocar';
  estado.tmPkSel = null;
  estado.tmDiscoSel = null;
  for (const b of $('#tm-abas').children) b.classList.toggle('on', b.dataset.aba === estado.tmAba);
  montarTmResearcher();
  $('#tm-researcher').classList.remove('hidden');
}

const fecharTmResearcher = () => {
  $('#tm-researcher').classList.add('hidden');
};

function htmlTmInfo() {
  const cfg = estado.tmResearcher ?? {};
  // A chance da Outland ESCOLHIDA — este texto responde "quanto eu demoro para juntar um
  // token", e a resposta muda com o degrau em que o jogador está caçando.
  const chanceBoss = (estado.chanceBossToken ?? 0.0005) * multOutlandUi();
  const mediaBoss = num(Math.round(1 / chanceBoss));
  const custo = cfg.custoElemental ?? 10;
  const equipe = (estado.eu?.pokemons ?? []).filter((p) => p.slot != null);
  const pkSel = equipe.find((p) => p.id === estado.tmPkSel);
  const tiposPk = pkSel?.tipos ?? [];
  const tiposHtml = tiposPk.map((tipo) => selosDeTipo([tipo]) + ` <b>${tipo}</b>`).join(', ');

  // De onde vem cada peça: quantos bosses a soltam e a faixa de chance, lidos da tabela de drops
  // que o servidor manda (`bossesJogaveis`) — a mesma com que ele sorteia.
  const origemDaPeca = (itemId) => {
    const chances = (estado.bossesJogaveis ?? []).flatMap((b) =>
      (b.drops ?? []).filter((d) => d.itemId === itemId && d.chance).map((d) => d.chance));
    if (!chances.length) return '—';
    const min = Math.min(...chances);
    const max = Math.max(...chances);
    return `${num(chances.length)} bosses (${min === max ? pct(min) : `${pct(min)}–${pct(max)}`})`;
  };

  // O disco de exemplo é o de FIRE — o mesmo do texto ("TM FIRE"), para a arte e a frase
  // contarem a mesma história.
  const discoFire = (cfg.discos ?? []).find((d) => d.tipo === 'FIRE')?.itemId ?? null;
  const pecas = [
    {
      nome: t('tm.pecasElemental'),
      origem: origemDaPeca(cfg.pieceElemental),
      vira: t('tm.infoViraElemental'),
      viraSub: t('tm.infoViraElementalSub'),
      itemId: cfg.pieceElemental,
      disco: discoFire,
      custo,
    },
    {
      nome: t('tm.pecasAoe'),
      origem: origemDaPeca(cfg.pieceAoe),
      vira: t('tm.trocarAoe'),
      viraSub: t('tm.infoViraAoeSub'),
      itemId: cfg.pieceAoe,
      disco: cfg.diskAoe,
      custo: cfg.custoAoe ?? custo,
    },
  ];

  // Cada troca é um palco do diálogo de jogo — as peças → a seta → o disco —, no lugar da
  // tabela de três colunas: é uma TROCA, e troca se desenha.
  const trocas = pecas.map((p) => dlgPalco(`
    ${dlgAtor({
      arte: p.itemId ? dlgArteItem(p.itemId, 40) : '',
      nome: escapar(p.nome),
      sub: escapar(p.origem),
      qtd: `×${num(p.custo)}`,
    })}
    ${dlgSeta()}
    ${dlgAtor({ arte: p.disco ? dlgArteItem(p.disco, 44) : '', nome: escapar(p.vira), sub: escapar(p.viraSub), classe: 'novo' })}`, 'rx')).join('');
  const artePequena = (itemId) => (itemId ? `<span data-dlg-item="${Number(itemId)}" data-dlg-px="24"></span>` : null);

  const pkExtra = tiposPk.length
    ? `<p class="tm-info-nota">${t('tm.infoTiposPk', { tipos: tiposHtml })}</p>`
    : '';

  return `
    <p>${t('tm.infoIntro')}</p>

    <h3>${t('tm.infoSecAplicado')}</h3>
    ${dlgLista([
      { arte: artePequena(discoFire), icone: 'raio', html: t('tm.infoElemental', { tipo: 'FIRE' }) },
      { arte: artePequena(cfg.diskAoe), icone: 'raio', html: t('tm.infoAoe') },
    ])}

    <h3>${t('tm.infoSecTokens')}</h3>
    ${dlgLista([{ arte: artePequena(BOSS_TOKEN_ID), html: t('tm.infoTokens', { pct: pct(chanceBoss), media: mediaBoss }) }])}

    <h3>${t('tm.infoSecPecas')}</h3>
    <p>${t('tm.infoPecasIntro', { n: num(custo) })}</p>
    <div class="tmi-trocas">${trocas}</div>

    <h3>${t('tm.infoSecTipos')}</h3>
    <p>${t('tm.infoTipos')}</p>
    ${pkExtra}

    <h3>${t('tm.infoSecAvancado')}</h3>
    <p>${t('tm.infoAvancado')}</p>

    ${htmlInfoCasa()}
    ${htmlInfoBicicleta()}
    ${htmlInfoPedra()}
    ${htmlInfoMega()}`;
}

/**
 * O guia da bancada "Fabricar Casa", dentro do mesmo [i].
 *
 * O [i] deixou de ser "o guia dos TMs" quando o balcão virou quatro bancadas: quem abre ali
 * está perguntando "o que dá para fazer aqui?", e responder só sobre discos deixaria metade
 * do NPC sem explicação. A tabela de chances vem do welcome, como no resto do jogo.
 */
function htmlInfoCasa() {
  const cfg = estado.casas;
  if (!cfg?.raridades?.length) return '';
  const frag = cfg.fragmento ?? {};
  const total = cfg.raridades.reduce((s, r) => s + r.peso, 0) || 1;
  const linhas = cfg.raridades.map((r) => `
    <tr>
      <td><b>${escapar(nomeRaridade(r.id))}</b></td>
      <td>${escapar(resumoDaCasa(r))}</td>
      <td>${fmtChance((r.peso / total) * 100)}</td>
    </tr>`).join('');

  return `
    <h3>${escapar(t('casa.xpShare'))} — ${escapar(t('tm.abaCasa'))}</h3>
    <p>${escapar(t('info.casaIntro', { n: frag.custo ?? 10 }))}</p>
    <table class="wk-tabela">
      <thead><tr>
        <th>${escapar(t('info.colCasa'))}</th>
        <th>${escapar(t('info.colBonecos'))}</th>
        <th>${escapar(t('info.colChance'))}</th>
      </tr></thead>
      <tbody>${linhas}</tbody>
    </table>
    <p>${escapar(t('info.casaFrag', {
      chance: ((frag.chanceDrop ?? 0) * multOutlandUi() * 100).toFixed(3).replace(/0+$/, '').replace(/\.$/, ''),
    }))}</p>
    ${cfg.craft?.degraus?.length ? `<p>${escapar(t('info.casaCraft', { n: num(cfg.craft.custo ?? 5) }))}</p>` : ''}
    <p class="tm-info-nota">${escapar(t('info.casaXpShare', { max: num(maxCasasEmUso()) }))}</p>`;
}

/** O guia da bancada "Fabricar Bicicleta" — a mesma tabela da Casa, com a velocidade no lugar da fatia. */
function htmlInfoBicicleta() {
  const cfg = estado.bicicletas;
  if (!cfg?.raridades?.length) return '';
  const frag = cfg.fragmento ?? {};
  const total = cfg.raridades.reduce((s, r) => s + r.peso, 0) || 1;
  const linhas = cfg.raridades.map((r) => `
    <tr>
      <td><b>${escapar(nomeRaridade(r.id))}</b></td>
      <td>${escapar(resumoDaBicicleta(r))}</td>
      <td>${fmtChance((r.peso / total) * 100)}</td>
    </tr>`).join('');

  return `
    <h3>${escapar(t('tm.abaBicicleta'))}</h3>
    <p>${escapar(t('info.bicicletaIntro', { n: frag.custo ?? 10 }))}</p>
    <table class="wk-tabela">
      <thead><tr>
        <th>${escapar(t('info.colBicicleta'))}</th>
        <th>${escapar(t('info.colVelocidade'))}</th>
        <th>${escapar(t('info.colChance'))}</th>
      </tr></thead>
      <tbody>${linhas}</tbody>
    </table>
    <p>${escapar(t('info.bicicletaFrag', {
      chance: ((frag.chanceDrop ?? 0) * multOutlandUi() * 100).toFixed(3).replace(/0+$/, '').replace(/\.$/, ''),
    }))}</p>
    ${cfg.craft?.degraus?.length ? `<p>${escapar(t('info.bicicletaCraft', { n: num(cfg.craft.custo ?? 5) }))}</p>` : ''}
    <p class="tm-info-nota">${escapar(t('info.bicicletaNota'))}</p>`;
}

/** O guia da bancada "Fabricar Shiny Stone". */
function htmlInfoPedra() {
  const cfg = estado.shinyStone;
  if (!cfg) return '';
  return `
    <h3>${escapar(t('tm.abaPedra'))}</h3>
    <p>${escapar(t('info.pedraIntro', {
      n: cfg.custo ?? 10,
      chance: ((cfg.chanceDrop ?? 0) * multOutlandUi() * 100).toFixed(4).replace(/0+$/, '').replace(/\.$/, ''),
      media: num(Math.round(1 / ((cfg.chanceDrop || 1) * multOutlandUi()))),
    }))}</p>
    <p>${escapar(t('pedra.comoUsar'))}</p>
    <p class="tm-info-nota">${escapar(t('info.pedraAviso'))}</p>`;
}

/**
 * O guia da bancada "Fabricar Mega Stone".
 *
 * As duas chances saem do `welcome` (`mega.chanceBase` / `chanceBaseShiny`) e são as do
 * PRIMEIRO par de bosses. O guia diz isso em palavras em vez de listar os treze pares: a
 * escada inteira já está no modal de Bosses, ao lado de cada arena, e repeti-la aqui seria
 * uma tabela que envelhece sozinha a cada boss novo.
 */
function htmlInfoMega() {
  const cfg = estado.mega;
  if (!cfg?.pedras?.length) return '';
  const pct = (v) => Number(((v ?? 0) * 100).toPrecision(2));
  return `
    <h3>${escapar(t('tm.abaMega'))}</h3>
    <p>${escapar(t('info.megaIntro', {
      n: cfg.custo ?? 10,
      chance: pct(cfg.chanceBase),
      chanceShiny: pct(cfg.chanceBaseShiny),
    }))}</p>
    <p>${escapar(t('mega.comoUsar'))}</p>
    <p class="tm-info-nota">${escapar(t('info.megaAviso', { n: num(cfg.pedras.length) }))}</p>`;
}

function abrirTmInfo() {
  $('#tm-info-corpo').innerHTML = htmlTmInfo();
  hidratarDialogo($('#tm-info-corpo'));
  $('#tm-info').classList.remove('hidden');
}

const fecharTmInfo = () => {
  $('#tm-info').classList.add('hidden');
};

$('#tm-info-bt').onclick = abrirTmInfo;
$('#tm-info-fechar').onclick = fecharTmInfo;
$('#tm-info').onclick = (ev) => {
  if (ev.target === $('#tm-info')) fecharTmInfo();
};

$('#tm-fechar').onclick = fecharTmResearcher;
$('#tm-researcher').onclick = (ev) => {
  if (ev.target === $('#tm-researcher')) fecharTmResearcher();
};
$('#tm-abas').onclick = (ev) => {
  const b = ev.target.closest('.tm-aba');
  if (!b) return;
  estado.tmAba = b.dataset.aba;
  for (const x of $('#tm-abas').children) x.classList.toggle('on', x === b);
  montarTmResearcher();
};

function montarTmResearcher() {
  const cfg = estado.tmResearcher;
  const host = $('#tm-corpo');
  if (!cfg) return;
  // A rolagem só volta ao topo quando a ABA muda. Redesenhar a mesma aba (chegou um fragmento,
  // escolheu o pokémon) mantém a posição — senão quem escolhe o disco lá embaixo seria jogado
  // de volta ao cabeçalho a cada clique.
  const mesmaAba = host.dataset.aba === estado.tmAba;
  const topo = mesmaAba ? (host.querySelector('.tm-rolagem')?.scrollTop ?? 0) : 0;
  host.dataset.aba = estado.tmAba;
  if (estado.tmAba === 'casa') montarFabricarCasa(host);
  else if (estado.tmAba === 'bicicleta') montarFabricarBicicleta(host);
  else if (estado.tmAba === 'pedra') montarFabricarPedra(host);
  else if (estado.tmAba === 'mega') montarFabricarMega(host);
  else if (estado.tmAba === 'aplicar') montarTmAplicar(host, cfg);
  else montarTmTrocar(host, cfg);
  const rolagem = host.querySelector('.tm-rolagem');
  if (rolagem) rolagem.scrollTop = topo;
}

// --------------------------------------- Professor Carvalho: a moldura das bancadas
//
// As cinco abas desenham a MESMA forma — é o que faz o modal parar de parecer cinco telas
// coladas: o cabeçalho com o ícone e o que a bancada faz, o recurso que ela gasta com a barra
// até o custo ("7/10"), o miolo e, quando há uma ação principal, o botão preso no RODAPÉ. O
// rodapé fica fora da rolagem: a tabela de chances rola, o "Fabricar" não some junto.
//
// O tamanho do modal não depende do miolo (ver `.caixa-tm` no estilo): trocar de aba não
// encolhe nem estica a janela, no desktop nem no celular.

/** Os ícones das bancadas — os mesmos das abas, no `index.html`. */
const ICONE_BANCADA = {
  trocar: '/assets/site/assets/items/tm_disk_piece.png',
  aplicar: '/assets/site/assets/items/tm_disk_elemental.png',
  casa: '/img/itens/casa-comum.png',
  bicicleta: '/img/itens/bicicleta-comum.png',
  pedra: '/img/itens/shiny-stone.png',
  mega: '/img/itens/fragmento-mega-shiny.png',
};

function bancadaHtml({ aba, titulo, sub = '', corpo, rodape = '' }) {
  return `
    <div class="tm-rolagem">
      <header class="tm-banca-cab">
        <span class="tm-banca-ico tm-ico-${aba}"><img src="${ICONE_BANCADA[aba]}" alt=""></span>
        <span class="tm-banca-txt">
          <b class="tm-banca-tit">${escapar(titulo)}</b>
          ${sub ? `<span class="tm-banca-sub">${escapar(sub)}</span>` : ''}
        </span>
      </header>
      ${corpo}
    </div>
    ${rodape ? `<div class="tm-rodape">${rodape}</div>` : ''}`;
}

/** O recurso que a bancada gasta: ícone, nome, "tem/custo" e a barra que enche até o custo. */
function recursoHtml({ itemId, nome, tem, custo }) {
  const pct = Math.max(0, Math.min(100, (tem / Math.max(1, custo)) * 100));
  return `
    <div class="tm-recurso${tem >= custo ? ' pronto' : ''}">
      <span class="tm-recurso-ico">${imgItem(itemId, 32).outerHTML}</span>
      <span class="tm-recurso-info">
        <span class="tm-recurso-nome">${escapar(nome)}</span>
        <span class="tm-barra"><i style="width:${pct.toFixed(1)}%"></i></span>
      </span>
      <span class="tm-recurso-qtd"><b>${num(tem)}</b><small>${escapar(t('tm.custoCurto', { n: num(custo) }))}</small></span>
    </div>`;
}

/** A tabela de chances de um sorteio (Casa, Bicicleta), com a cor da raridade na lateral. */
function chancesHtml(raridades, nomeDe, resumoDe) {
  const total = raridades.reduce((s, r) => s + r.peso, 0) || 1;
  return `
    <b class="tm-secao">${escapar(t('tm.secaoChances'))}</b>
    <div class="tm-chances">${raridades.map((r) => `
      <div class="tm-chance rar-${r.id}">
        <span class="tm-chance-nome">${escapar(nomeDe(r.id))}</span>
        <span class="tm-chance-bonecos">${escapar(resumoDe(r))}</span>
        <span class="tm-chance-pct">${fmtChance((r.peso / total) * 100)}</span>
      </div>`).join('')}
    </div>`;
}

const bancadaVazia = (aba, titulo, sub, chave) =>
  bancadaHtml({ aba, titulo, sub, corpo: `<p class="tm-vazio">${escapar(t(chave))}</p>` });

/**
 * O "tem certeza?" antes de todo gasto do Professor.
 *
 * Nenhuma bancada daqui tem volta — a casa sorteada não se desfabrica, o disco aplicado não
 * sai do bicho — e o que elas gastam custou semanas de farm. As grades são justamente onde o
 * clique escorrega: 18 pedras lado a lado, megas que diferem por uma letra (Charizardite X e
 * Y). Um toque a mais é barato perto de um toque errado.
 *
 * A caixa é a `confirmar` de sempre, com a TROCA desenhada em cima da pergunta: o que sai, com
 * o saldo que fica, e o que entra. O olho confere o ícone antes de ler o nome.
 *
 * `gasta` é `{ itemId, qtd, nome, tem?, liso? }`, e o saldo sai da bolsa — ou de `tem`, quando o
 * que se gasta não mora nela (as casas do craft são peças numeradas). `ganha` é `{ arte, nome, sub?,
 * qtd?, liso? }`: a arte vem pronta porque cada bancada mostra uma coisa (o ícone do item, a
 * casa com o "?" do sorteio, o boneco que recebe o disco). `sub` e `pergunta` são HTML — quem
 * chama escapa o que veio de fora. `depois` recebe o corpo da caixa já montado, para o que não
 * sai de `innerHTML` (o sprite animado).
 */
function confirmarGasto({ titulo, gasta, ganha, pergunta, aviso = '', rotuloSim, aoConfirmar, depois = null }) {
  const tem = gasta.tem ?? Number(estado.eu?.items?.[gasta.itemId] ?? 0);
  // Bancada desenhada antes da bolsa nova: em vez de perguntar "gastar 10 de 0", ela se
  // redesenha e mostra o que falta.
  if (tem < gasta.qtd) return void montarTmResearcher();
  const lado = ({ classe, arte, qtd = '', nome, sub = '', liso = false }) => `
    <div class="fab-lado ${classe}">
      <span class="fab-arte${liso ? ' liso' : ''}">${arte}</span>
      ${qtd ? `<b class="fab-qtd">${qtd}</b>` : ''}
      <span class="fab-nome">${escapar(nome)}</span>
      ${sub ? `<span class="fab-sub">${sub}</span>` : ''}
    </div>`;
  confirmar({
    titulo,
    rotuloSim,
    texto: `
      <div class="fab-troca">
        ${lado({
          classe: 'sai',
          arte: imgItem(gasta.itemId, 40).outerHTML,
          liso: !!gasta.liso,
          qtd: `−${num(gasta.qtd)}`,
          nome: gasta.nome,
          sub: escapar(t('fab.saldo', { tem: num(tem), depois: num(Math.max(0, tem - gasta.qtd)) })),
        })}
        ${dlgSeta()}
        ${lado({ classe: 'entra', ...ganha })}
      </div>
      <p class="fab-pergunta">${pergunta}</p>
      ${aviso ? `<p class="tm-aviso fab-aviso">${aviso}</p>` : ''}`,
    aoConfirmar,
  });
  depois?.($('#confirmar-texto'));
}

/** A arte de um resultado SORTEADO: o ícone da bancada com o "?" do sorteio no canto. */
const arteSorteada = (aba) => `<img src="${ICONE_BANCADA[aba]}" alt=""><i class="fab-sorte">?</i>`;

// ------------------------------------------- Professor Carvalho: Fabricar Casa

/**
 * 10 Fragmentos de Chave → 1 Casa SORTEADA.
 *
 * A tabela de chances aparece ANTES do botão, e não numa nota de rodapé: o jogador está
 * prestes a gastar dez fragmentos com teto vitalício de dez, ou seja, metade de tudo o que a
 * conta dele vai poder farmar na vida. Esconder que a Lendária é 1 em 20.000 seria vender uma
 * caixa sem dizer o que tem dentro.
 */
function montarFabricarCasa(host) {
  const cfg = estado.casas;
  if (!cfg) return void (host.innerHTML = bancadaVazia('casa', t('tm.abaCasa'), '', 'casa.indisponivel'));
  if (estado.casaModo === 'craft' && cfg.craft?.degraus?.length) return montarCraftCasa(host, cfg);
  const frag = cfg.fragmento ?? {};
  const tem = Number(estado.eu?.items?.[frag.itemId] ?? 0);
  const custo = frag.custo ?? 10;
  const pode = tem >= custo;
  // A lista vem a mais rara primeiro: o ícone do status é o da melhor casa que ele tem.
  const casas = minhasCasas();

  // Sem trava de "já tem uma": casa se acumula sem teto — o teto é de USO, e a bancada diz os dois.
  host.innerHTML = bancadaHtml({
    aba: 'casa',
    titulo: t('tm.abaCasa'),
    sub: t('tm.subCasa', { n: custo }),
    corpo: `
      ${trocaModoCasaHtml(cfg)}
      ${recursoHtml({ itemId: frag.itemId, nome: nomeItem(frag.itemId, 'Key Fragment'), tem, custo })}
      <div class="tm-status tm-status-casa${casas.length ? ' on' : ''}">
        ${casas.length ? imgItem(CASA_ITEM_POR_RAR[casas[0].rar], 28).outerHTML : ''}
        <span>${escapar(!casas.length
          ? t('casa.nenhumaAinda')
          : t(casas.length === 1 ? 'casa.suasCasasResumoUma' : 'casa.suasCasasResumo', {
            n: num(casas.length), u: num(casasEmUsoNaTela().length), max: num(maxCasasEmUso()),
          }))}</span>
      </div>
      <p class="tm-nota">${escapar(t('casa.fabRegra', { max: num(maxCasasEmUso()) }))}</p>
      ${chancesHtml(cfg.raridades ?? [], nomeCasaRaridade, resumoDaCasa)}`,
    rodape: `
      <button type="button" class="casa-btn tm-fabricar" id="tm-fab-casa" ${pode ? '' : 'disabled'}>
        ${escapar(t(pode ? 'casa.fabricar' : 'casa.fabFaltam', { n: custo - tem }))}
      </button>`,
  });

  $('#tm-fab-casa').onclick = () => confirmarGasto({
    titulo: t('tm.abaCasa'),
    gasta: { itemId: frag.itemId, qtd: custo, nome: nomeItem(frag.itemId, 'Key Fragment') },
    ganha: { arte: arteSorteada('casa'), liso: true, qtd: '+1', nome: t('fab.casa'), sub: escapar(t('fab.sorteada')) },
    pergunta: t('fab.perguntaCasa', { n: num(custo) }),
    rotuloSim: t('fab.fabricar'),
    aoConfirmar: () => enviar({ t: 'casa.fabricar' }),
  });
  ligarTrocaModoCasa(host);
}

// ------------------------------------------- Professor Carvalho: Craft de Casas

/**
 * O interruptor da bancada da Casa: o SORTEIO com fragmentos ou o CRAFT com casas. Os dois
 * entregam casa, e quem chega aqui tem uma pergunta só — "como consigo uma casa melhor?" —, o
 * mesmo motivo de a Mega ter comum e shiny na mesma bancada (ver `montarFabricarMega`). Uma
 * sétima aba não caberia na fileira do celular.
 */
function trocaModoCasaHtml(cfg) {
  if (!cfg.craft?.degraus?.length) return '';
  const craft = estado.casaModo === 'craft';
  return `
    <div class="mega-troca casa-modo" role="group">
      <button type="button" class="mega-troca-bt${craft ? '' : ' on'}" data-modo="fragmentos">
        ${imgItem(cfg.fragmento?.itemId, 20).outerHTML}<span>${escapar(t('casa.modoFragmentos'))}</span>
      </button>
      <button type="button" class="mega-troca-bt${craft ? ' on' : ''}" data-modo="craft">
        <img class="liso" src="${arteDaCasa('rara')}" alt=""><span>${escapar(t('casa.modoCraft'))}</span>
      </button>
    </div>`;
}

function ligarTrocaModoCasa(host) {
  const el = host.querySelector('.casa-modo');
  if (!el) return;
  el.onclick = (ev) => {
    const b = ev.target.closest('.mega-troca-bt');
    if (!b || b.classList.contains('on')) return;
    estado.casaModo = b.dataset.modo;
    // Outro modo é outra tela: volta ao topo, como a troca de aba (ver `montarTmResearcher`).
    delete $('#tm-corpo').dataset.aba;
    montarTmResearcher();
  };
}

/**
 * As casas que podem entrar numa receita: as da MÃO, da raridade `de`, menos a casa em que o
 * jogador está (o servidor recusa — é preciso sair antes). Na ordem do número.
 */
function casasCraftaveis(de) {
  const dentro = estado.eu?.casa?.dentro ?? null;
  return minhasCasas()
    .filter((c) => !c.anunciada && c.rar === de && c.id !== dentro)
    .sort((a, b) => a.id - b.id);
}

const pokemonsNoPosto = (c) => (c.postos ?? []).filter((id) => id != null);

/**
 * A escolha PADRÃO das cinco — o jogador só mexe se quiser. Primeiro as que não custam nada a
 * ele (guardadas e sem pokémon), depois as em uso sem ninguém no posto, e por último as com
 * pokémon. Dentro de cada grupo, o número MAIOR primeiro: os números baixos são os que
 * colecionador guarda, e o craft não pode comer a #000012 de alguém só porque ela veio antes.
 */
function escolhaPadraoCraft(lista, n) {
  const peso = (c) => (pokemonsNoPosto(c).length ? 2 : c.emUso === false ? 0 : 1);
  return [...lista].sort((a, b) => peso(a) - peso(b) || b.id - a.id).slice(0, n).map((c) => c.id);
}

/**
 * A seleção da receita aberta. `sel: null` é "a padrão" — ela se recalcula sozinha quando uma
 * casa chega ou sai. O primeiro toque do jogador a congela, e daí em diante só perde o que
 * deixou de estar disponível (vendida, anunciada, consumida).
 */
function selecaoCraft(de, lista, n) {
  const st = (estado.craftCasa ??= { de: null, sel: null });
  if (st.de !== de) {
    st.de = de;
    st.sel = null;
  }
  if (!st.sel) return escolhaPadraoCraft(lista, n);
  const validos = new Set(lista.map((c) => c.id));
  st.sel = st.sel.filter((id) => validos.has(id));
  return st.sel;
}

/**
 * CRAFT: 5 casas da mesma raridade → 1 da raridade seguinte, SÓ ATÉ RARA.
 *
 * Em cima, uma receita por degrau (Comum → Incomum, Incomum → Rara), com quantas o jogador tem;
 * logo embaixo, o aviso do teto — Mítica e Lendária não se craftam, e isso tem de estar escrito
 * antes de alguém juntar vinte e cinco Raras esperando uma Mítica. Depois, as casas da receita,
 * uma por NÚMERO: casa é peça numerada, e é o jogador quem decide quais cinco somem. A escolha
 * padrão já vem marcada (ver `escolhaPadraoCraft`).
 */
function montarCraftCasa(host, cfg) {
  const craft = cfg.craft;
  const n = craft.custo ?? 5;
  const degraus = craft.degraus;
  // A receita aberta: a que ele escolheu, ou a primeira em que já tem casas bastantes.
  let de = estado.craftCasa?.de;
  if (!degraus.some((d) => d.de === de)) {
    de = (degraus.find((d) => casasCraftaveis(d.de).length >= n) ?? degraus[0]).de;
  }
  const para = degraus.find((d) => d.de === de).para;
  const lista = casasCraftaveis(de);
  const sel = selecaoCraft(de, lista, n);
  const pode = sel.length === n;
  const pks = new Map((estado.eu?.pokemons ?? []).map((pk) => [pk.id, pk]));
  const nPkSel = lista.filter((c) => sel.includes(c.id)).reduce((s, c) => s + pokemonsNoPosto(c).length, 0);

  const receitas = degraus.map((d) => {
    const tem = casasCraftaveis(d.de).length;
    return `
      <button type="button" class="cc-receita${d.de === de ? ' on' : ''}${tem >= n ? ' pronta' : ''}" data-de="${d.de}">
        <span class="cc-receita-troca">
          <span class="cc-receita-lado"><img src="${arteDaCasa(d.de)}" alt=""><b>×${num(n)}</b></span>
          <svg class="cc-seta" viewBox="0 0 16 16" aria-hidden="true"><path d="M1 5.5h7.5v-4L15 8l-6.5 6.5v-4H1z" fill="currentColor"/></svg>
          <span class="cc-receita-lado"><img src="${arteDaCasa(d.para)}" alt=""><b>×1</b></span>
        </span>
        <span class="cc-receita-nome">${escapar(t('casa.craftReceita', { de: nomeRaridade(d.de), para: nomeRaridade(d.para) }))}</span>
        <span class="cc-receita-tem">${escapar(t('casa.craftTem', { tem: num(tem), n: num(n) }))}</span>
      </button>`;
  }).join('');

  const chips = lista.map((c) => {
    const on = sel.includes(c.id);
    const nomes = pokemonsNoPosto(c).map((id) => pks.get(id)).filter(Boolean)
      .map((pk) => `${pk.shiny ? '★ ' : ''}${pk.nome}`);
    const estadoCasa = t(c.emUso === false ? 'casa.craftGuardada' : 'casa.craftEmUso');
    return `
      <button type="button" class="cc-casa rar-${c.rar}${on ? ' on' : ''}" data-id="${c.id}" aria-pressed="${on}">
        <img src="${arteDaCasa(c.rar)}" alt="" draggable="false">
        <span class="cc-casa-info">
          <b class="cc-casa-num">${escapar(numeroDaCasa(c.id))}</b>
          <span class="cc-casa-estado">${escapar(estadoCasa)}</span>
          ${nomes.length ? `<span class="cc-casa-pk">${escapar(nomes.join(', '))}</span>` : ''}
        </span>
        <i class="cc-check" aria-hidden="true"></i>
      </button>`;
  }).join('');

  const faltam = n - lista.length;
  const grade = !lista.length
    ? `<p class="tm-vazio">${escapar(t('casa.craftSemCasas', { rar: nomeCasaRaridade(de), n: num(n) }))}</p>`
    : `${faltam > 0 ? `<p class="tm-nota">${escapar(t('casa.craftFaltam', { n: num(faltam), rar: nomeCasaRaridade(de) }))}</p>` : ''}
       <div class="cc-grade">${chips}</div>`;

  host.innerHTML = bancadaHtml({
    aba: 'casa',
    titulo: t('casa.craftTitulo'),
    sub: t('tm.subCasaCraft', { n: num(n) }),
    corpo: `
      ${trocaModoCasaHtml(cfg)}
      <div class="cc-receitas">${receitas}</div>
      <p class="tm-aviso cc-teto">${t('casa.craftTeto')}</p>
      <b class="tm-secao">${escapar(t('casa.craftEscolha', { n: num(n), rar: nomeCasaRaridade(de), sel: num(sel.length) }))}</b>
      ${grade}
      ${nPkSel ? `<p class="tm-aviso">${t(nPkSel === 1 ? 'casa.craftAvisoPokemonUm' : 'casa.craftAvisoPokemon', { n: num(nPkSel) })}</p>` : ''}
      <p class="tm-nota">${escapar(t('casa.craftRegra', { n: num(n) }))}</p>`,
    rodape: `
      <button type="button" class="casa-btn tm-fabricar" id="tm-craft-casa" ${pode ? '' : 'disabled'}>
        ${escapar(pode
          ? t('casa.craftarPara', { rar: nomeCasaRaridade(para) })
          : faltam > 0
            ? t('casa.craftFaltamBt', { n: num(faltam) })
            : t('casa.craftEscolhaMais', { n: num(n - sel.length) }))}
      </button>`,
  });
  ligarTrocaModoCasa(host);

  host.querySelector('.cc-receitas').onclick = (ev) => {
    const b = ev.target.closest('.cc-receita');
    if (!b || b.dataset.de === de) return;
    estado.craftCasa = { de: b.dataset.de, sel: null };
    montarTmResearcher();
  };

  host.querySelector('.cc-grade')?.addEventListener('click', (ev) => {
    const b = ev.target.closest('.cc-casa');
    if (!b) return;
    const id = Number(b.dataset.id);
    const atual = [...sel];
    const i = atual.indexOf(id);
    if (i >= 0) atual.splice(i, 1);
    // Com as cinco marcadas, marcar outra não troca nenhuma sozinha: qual sairia seria um
    // palpite, e o jogador está justamente escolhendo quais somem.
    else if (atual.length >= n) return void toast(t('casa.craftJaCinco', { n: num(n) }));
    else atual.push(id);
    estado.craftCasa = { de, sel: atual };
    montarTmResearcher();
  });

  $('#tm-craft-casa').onclick = () => {
    const escolhidas = lista.filter((c) => sel.includes(c.id));
    if (escolhidas.length !== n) return;
    confirmarGasto({
      titulo: t('casa.craftTitulo'),
      gasta: { itemId: CASA_ITEM_POR_RAR[de], qtd: n, nome: nomeCasaRaridade(de), tem: lista.length, liso: true },
      ganha: {
        arte: imgItem(CASA_ITEM_POR_RAR[para], 40).outerHTML,
        liso: true,
        qtd: '+1',
        nome: nomeCasaRaridade(para),
        sub: escapar(t('casa.craftNumeroNovo')),
      },
      pergunta: t('casa.craftPergunta', {
        n: num(n),
        de: escapar(nomeCasaRaridade(de)),
        para: escapar(nomeCasaRaridade(para)),
        numeros: escolhidas.map((c) => `<b>${escapar(numeroDaCasa(c.id))}</b>`).join(', '),
      }),
      aviso: nPkSel ? t(nPkSel === 1 ? 'casa.craftAvisoPokemonUm' : 'casa.craftAvisoPokemon', { n: num(nPkSel) }) : '',
      rotuloSim: t('casa.craftar'),
      aoConfirmar: () => enviar({ t: 'casa.craftar', casaIds: escolhidas.map((c) => c.id) }),
    });
  };
}

// --------------------------------------- Professor Carvalho: Fabricar Bicicleta

/** O que a bicicleta DÁ, em uma linha: "+50% de velocidade na hunt". */
const resumoDaBicicleta = (r) => t('bicicleta.velocidade', { pct: Math.round((r.velocidade ?? 0) * 100) });

/** Nome completo na bolsa/mercado — "Bicicleta Rara", não só "Rara". */
const nomeBicicletaRaridade = (rarId) => nomeItem(BICICLETA_ITEM_POR_RAR[rarId] ?? 0, nomeRaridade(rarId));

/**
 * 10 Fragmentos de Bicicleta → 1 Bicicleta SORTEADA, a mais na bolsa. A bancada da Casa com a
 * velocidade no lugar da fatia de XP — e com a tabela de chances à vista ANTES do botão, pelo
 * mesmo motivo (ver `montarFabricarCasa`). Sem trava de "já tem uma": bicicleta se acumula, e
 * o que a bancada mostra é qual está EQUIPADA, que é a pergunta de quem volta a ela.
 */
function montarFabricarBicicleta(host) {
  const cfg = estado.bicicletas;
  if (!cfg) return void (host.innerHTML = bancadaVazia('bicicleta', t('tm.abaBicicleta'), '', 'bicicleta.indisponivel'));
  if (estado.bicicletaModo === 'craft' && cfg.craft?.degraus?.length) return montarCraftBicicleta(host, cfg);
  const frag = cfg.fragmento ?? {};
  const tem = Number(estado.eu?.items?.[frag.itemId] ?? 0);
  const custo = frag.custo ?? 10;
  const pode = tem >= custo;
  // A RARIDADE da equipada (o número não muda nada aqui: a velocidade é a da raridade).
  const equipada = estado.eu?.bicicleta?.equipadaRar ?? null;
  const metaEquipada = (cfg.raridades ?? []).find((r) => r.id === equipada) ?? null;

  host.innerHTML = bancadaHtml({
    aba: 'bicicleta',
    titulo: t('tm.abaBicicleta'),
    sub: t('tm.subBicicleta', { n: custo }),
    corpo: `
      ${trocaModoBicicletaHtml(cfg)}
      ${recursoHtml({ itemId: frag.itemId, nome: nomeItem(frag.itemId, 'Bicycle Fragment'), tem, custo })}
      <div class="tm-status${metaEquipada ? ' on' : ''}">
        ${metaEquipada ? imgItem(BICICLETA_ITEM_POR_RAR[equipada], 28).outerHTML : ''}
        <span>${escapar(metaEquipada
          ? t('bicicleta.suaAtual', { nome: nomeBicicletaRaridade(equipada), vel: resumoDaBicicleta(metaEquipada) })
          : t('bicicleta.nenhumaEquipada'))}</span>
      </div>
      <p class="tm-nota">${escapar(t('bicicleta.fabRegra'))}</p>
      ${chancesHtml(cfg.raridades ?? [], nomeBicicletaRaridade, resumoDaBicicleta)}`,
    rodape: `
      <button type="button" class="casa-btn tm-fabricar" id="tm-fab-bicicleta" ${pode ? '' : 'disabled'}>
        ${escapar(t(pode ? 'bicicleta.fabricar' : 'bicicleta.fabFaltam', { n: custo - tem }))}
      </button>`,
  });

  $('#tm-fab-bicicleta').onclick = () => confirmarGasto({
    titulo: t('tm.abaBicicleta'),
    gasta: { itemId: frag.itemId, qtd: custo, nome: nomeItem(frag.itemId, 'Bicycle Fragment') },
    ganha: { arte: arteSorteada('bicicleta'), qtd: '+1', nome: t('fab.bicicleta'), sub: escapar(t('fab.sorteada')) },
    pergunta: t('fab.perguntaBicicleta', { n: num(custo) }),
    rotuloSim: t('fab.fabricar'),
    aoConfirmar: () => enviar({ t: 'bicicleta.fabricar' }),
  });
  ligarTrocaModoBicicleta(host);
}

// -------------------------------------- Professor Carvalho: Craft de Bicicletas

/**
 * O interruptor da bancada da Bicicleta: o SORTEIO com fragmentos ou o CRAFT com bicicletas — o
 * mesmo da Casa (ver `trocaModoCasaHtml`), com a arte da bicicleta.
 */
function trocaModoBicicletaHtml(cfg) {
  if (!cfg.craft?.degraus?.length) return '';
  const craft = estado.bicicletaModo === 'craft';
  return `
    <div class="mega-troca bicicleta-modo" role="group">
      <button type="button" class="mega-troca-bt${craft ? '' : ' on'}" data-modo="fragmentos">
        ${imgItem(cfg.fragmento?.itemId, 20).outerHTML}<span>${escapar(t('casa.modoFragmentos'))}</span>
      </button>
      <button type="button" class="mega-troca-bt${craft ? ' on' : ''}" data-modo="craft">
        <img src="${arteDaBicicleta('rara')}" alt=""><span>${escapar(t('bicicleta.modoCraft'))}</span>
      </button>
    </div>`;
}

function ligarTrocaModoBicicleta(host) {
  const el = host.querySelector('.bicicleta-modo');
  if (!el) return;
  el.onclick = (ev) => {
    const b = ev.target.closest('.mega-troca-bt');
    if (!b || b.classList.contains('on')) return;
    estado.bicicletaModo = b.dataset.modo;
    delete $('#tm-corpo').dataset.aba;
    montarTmResearcher();
  };
}

/** As bicicletas que podem entrar numa receita: as da MÃO, da raridade `de`, na ordem do número. */
function bicicletasCraftaveis(de) {
  return (estado.eu?.bicicleta?.lista ?? [])
    .filter((b) => !b.anunciada && b.rar === de)
    .sort((a, b) => a.id - b.id);
}

/**
 * A escolha PADRÃO das cinco: primeiro as que estão só na bolsa, e a EQUIPADA por último — trocar
 * a bicicleta de quem está andando nela é o que o jogador tem de escolher, não receber pronto.
 * Dentro de cada grupo, o número MAIOR primeiro, pelo motivo da Casa (ver `escolhaPadraoCraft`).
 */
function escolhaPadraoCraftBicicleta(lista, n) {
  const equipada = estado.eu?.bicicleta?.equipada ?? null;
  const peso = (b) => (b.id === equipada ? 1 : 0);
  return [...lista].sort((a, b) => peso(a) - peso(b) || b.id - a.id).slice(0, n).map((b) => b.id);
}

/** A seleção da receita aberta — a `selecaoCraft` da Casa, com o estado próprio da bicicleta. */
function selecaoCraftBicicleta(de, lista, n) {
  const st = (estado.craftBicicleta ??= { de: null, sel: null });
  if (st.de !== de) {
    st.de = de;
    st.sel = null;
  }
  if (!st.sel) return escolhaPadraoCraftBicicleta(lista, n);
  const validos = new Set(lista.map((b) => b.id));
  st.sel = st.sel.filter((id) => validos.has(id));
  return st.sel;
}

/**
 * CRAFT: 5 bicicletas da mesma raridade → 1 da raridade seguinte, SÓ ATÉ RARA — a bancada do
 * Craft de Casas (`montarCraftCasa`), com as bicicletas da bolsa no lugar das casas. Em vez do
 * aviso dos postos, o da EQUIPADA: se ela entra, a nova sai equipada no lugar dela.
 */
function montarCraftBicicleta(host, cfg) {
  const craft = cfg.craft;
  const n = craft.custo ?? 5;
  const degraus = craft.degraus;
  let de = estado.craftBicicleta?.de;
  if (!degraus.some((d) => d.de === de)) {
    de = (degraus.find((d) => bicicletasCraftaveis(d.de).length >= n) ?? degraus[0]).de;
  }
  const para = degraus.find((d) => d.de === de).para;
  const lista = bicicletasCraftaveis(de);
  const sel = selecaoCraftBicicleta(de, lista, n);
  const pode = sel.length === n;
  const equipada = estado.eu?.bicicleta?.equipada ?? null;
  const equipadaNoCraft = equipada != null && sel.includes(equipada);

  const receitas = degraus.map((d) => {
    const tem = bicicletasCraftaveis(d.de).length;
    return `
      <button type="button" class="cc-receita${d.de === de ? ' on' : ''}${tem >= n ? ' pronta' : ''}" data-de="${d.de}">
        <span class="cc-receita-troca">
          <span class="cc-receita-lado"><img src="${arteDaBicicleta(d.de)}" alt=""><b>×${num(n)}</b></span>
          <svg class="cc-seta" viewBox="0 0 16 16" aria-hidden="true"><path d="M1 5.5h7.5v-4L15 8l-6.5 6.5v-4H1z" fill="currentColor"/></svg>
          <span class="cc-receita-lado"><img src="${arteDaBicicleta(d.para)}" alt=""><b>×1</b></span>
        </span>
        <span class="cc-receita-nome">${escapar(t('casa.craftReceita', { de: nomeRaridade(d.de), para: nomeRaridade(d.para) }))}</span>
        <span class="cc-receita-tem">${escapar(t('casa.craftTem', { tem: num(tem), n: num(n) }))}</span>
      </button>`;
  }).join('');

  const chips = lista.map((b) => {
    const on = sel.includes(b.id);
    return `
      <button type="button" class="cc-casa rar-${b.rar}${on ? ' on' : ''}" data-id="${b.id}" aria-pressed="${on}">
        <img src="${arteDaBicicleta(b.rar)}" alt="" draggable="false">
        <span class="cc-casa-info">
          <b class="cc-casa-num">${escapar(numeroDaBicicleta(b.id))}</b>
          <span class="cc-casa-estado">${escapar(t(b.id === equipada ? 'bicicleta.craftEquipada' : 'bicicleta.craftNaBolsa'))}</span>
        </span>
        <i class="cc-check" aria-hidden="true"></i>
      </button>`;
  }).join('');

  const faltam = n - lista.length;
  const grade = !lista.length
    ? `<p class="tm-vazio">${escapar(t('bicicleta.craftSemBicicletas', { rar: nomeBicicletaRaridade(de), n: num(n) }))}</p>`
    : `${faltam > 0 ? `<p class="tm-nota">${escapar(t('bicicleta.craftFaltam', { n: num(faltam) }))}</p>` : ''}
       <div class="cc-grade">${chips}</div>`;

  host.innerHTML = bancadaHtml({
    aba: 'bicicleta',
    titulo: t('bicicleta.craftTitulo'),
    sub: t('tm.subBicicletaCraft', { n: num(n) }),
    corpo: `
      ${trocaModoBicicletaHtml(cfg)}
      <div class="cc-receitas">${receitas}</div>
      <p class="tm-aviso cc-teto">${t('bicicleta.craftTeto')}</p>
      <b class="tm-secao">${escapar(t('bicicleta.craftEscolha', { n: num(n), sel: num(sel.length) }))}</b>
      ${grade}
      ${equipadaNoCraft ? `<p class="tm-aviso">${t('bicicleta.craftAvisoEquipada')}</p>` : ''}
      <p class="tm-nota">${escapar(t('bicicleta.craftRegra', { n: num(n) }))}</p>`,
    rodape: `
      <button type="button" class="casa-btn tm-fabricar" id="tm-craft-bicicleta" ${pode ? '' : 'disabled'}>
        ${escapar(pode
          ? t('casa.craftarPara', { rar: nomeBicicletaRaridade(para) })
          : faltam > 0
            ? t('bicicleta.craftFaltamBt', { n: num(faltam) })
            : t('casa.craftEscolhaMais', { n: num(n - sel.length) }))}
      </button>`,
  });
  ligarTrocaModoBicicleta(host);

  host.querySelector('.cc-receitas').onclick = (ev) => {
    const b = ev.target.closest('.cc-receita');
    if (!b || b.dataset.de === de) return;
    estado.craftBicicleta = { de: b.dataset.de, sel: null };
    montarTmResearcher();
  };

  host.querySelector('.cc-grade')?.addEventListener('click', (ev) => {
    const b = ev.target.closest('.cc-casa');
    if (!b) return;
    const id = Number(b.dataset.id);
    const atual = [...sel];
    const i = atual.indexOf(id);
    if (i >= 0) atual.splice(i, 1);
    // Com as cinco marcadas, marcar outra não troca nenhuma sozinha (ver `montarCraftCasa`).
    else if (atual.length >= n) return void toast(t('bicicleta.craftJaCinco', { n: num(n) }));
    else atual.push(id);
    estado.craftBicicleta = { de, sel: atual };
    montarTmResearcher();
  });

  $('#tm-craft-bicicleta').onclick = () => {
    const escolhidas = lista.filter((b) => sel.includes(b.id));
    if (escolhidas.length !== n) return;
    confirmarGasto({
      titulo: t('bicicleta.craftTitulo'),
      gasta: { itemId: BICICLETA_ITEM_POR_RAR[de], qtd: n, nome: nomeBicicletaRaridade(de), tem: lista.length },
      ganha: {
        arte: imgItem(BICICLETA_ITEM_POR_RAR[para], 40).outerHTML,
        qtd: '+1',
        nome: nomeBicicletaRaridade(para),
        sub: escapar(t('bicicleta.craftNumeroNovo')),
      },
      pergunta: t('bicicleta.craftPergunta', {
        n: num(n),
        de: escapar(nomeBicicletaRaridade(de)),
        para: escapar(nomeBicicletaRaridade(para)),
        numeros: escolhidas.map((b) => `<b>${escapar(numeroDaBicicleta(b.id))}</b>`).join(', '),
      }),
      aviso: equipadaNoCraft ? t('bicicleta.craftAvisoEquipada') : '',
      rotuloSim: t('casa.craftar'),
      aoConfirmar: () => enviar({ t: 'bicicleta.craftar', bicicletaIds: escolhidas.map((b) => b.id) }),
    });
  };
}

/** "0,005%" em vez de "0.005000000%" — corta os zeros sem mentir sobre a ordem de grandeza. */
function fmtChance(pct) {
  if (pct >= 1) return `${pct.toFixed(pct >= 10 ? 0 : 1)}%`;
  return `${Number(pct.toPrecision(2))}%`;
}

// ------------------------------------ Professor Carvalho: Fabricar Shiny Stone

/**
 * 10 Fragmentos de Shiny Stone → 1 pedra do TIPO escolhido.
 *
 * A escolha do tipo é o ponto da bancada: o fragmento cai a 0,0005% e é genérico, e é aqui
 * que ele vira a pedra do shiny que o jogador de fato tem. Sem a escolha, seria torcer para
 * cair a pedra certa — que é exatamente o que o TM Researcher já resolveu para os discos.
 */
function montarFabricarPedra(host) {
  const cfg = estado.shinyStone;
  if (!cfg) return void (host.innerHTML = bancadaVazia('pedra', t('tm.abaPedra'), '', 'casa.indisponivel'));
  const tem = Number(estado.eu?.items?.[cfg.fragmentoId] ?? 0);
  const custo = cfg.custo ?? 10;
  const pode = tem >= custo;

  const grade = (cfg.pedras ?? []).map((p) => {
    const qtd = Number(estado.eu?.items?.[p.itemId] ?? 0);
    // O selo de tipo JÁ escreve o nome, colorido — o `<span>` de texto que vinha depois dele
    // repetia a palavra ("NORMAL NORMAL ×3") e dobrava a largura de cada botão, que é o que
    // deixava a grade dos 18 tipos irregular. E `tm-grid` saiu da lista de classes porque ele
    // é declarado DEPOIS de `ss-grid` no estilo: com os dois no mesmo elemento, o
    // `display: flex` dele apagava a grade que o `ss-grid` define.
    return `
      <button type="button" class="tm-tipo ss-tipo" data-tipo="${p.tipo}" ${pode ? '' : 'disabled'}>
        ${selosDeTipo([p.tipo])}
        ${qtd ? `<span class="ss-tipo-qtd">×${num(qtd)}</span>` : ''}
      </button>`;
  }).join('');

  host.innerHTML = bancadaHtml({
    aba: 'pedra',
    titulo: t('tm.abaPedra'),
    sub: t('tm.subPedra', { n: custo }),
    corpo: `
      ${recursoHtml({ itemId: cfg.fragmentoId, nome: nomeItem(cfg.fragmentoId, 'Shiny Stone Fragment'), tem, custo })}
      <b class="tm-secao">${escapar(t(pode ? 'pedra.escolha' : 'pedra.faltam', { n: custo - tem }))}</b>
      <div class="ss-grid">${grade}</div>
      <p class="tm-nota">${escapar(t('pedra.comoUsar'))}</p>`,
  });

  host.querySelector('.ss-grid').onclick = (ev) => {
    const b = ev.target.closest('.ss-tipo');
    if (!b || b.disabled) return;
    const pedra = (cfg.pedras ?? []).find((p) => p.tipo === b.dataset.tipo);
    if (!pedra) return;
    const nome = nomeItem(pedra.itemId, `${pedra.tipo} Shiny Stone`);
    confirmarGasto({
      titulo: t('tm.abaPedra'),
      gasta: { itemId: cfg.fragmentoId, qtd: custo, nome: nomeItem(cfg.fragmentoId, 'Shiny Stone Fragment') },
      ganha: { arte: imgItem(pedra.itemId, 40).outerHTML, qtd: '+1', nome, sub: selosDeTipo([pedra.tipo]) },
      pergunta: t('fab.perguntaPedra', { n: num(custo), nome: escapar(nome) }),
      rotuloSim: t('fab.fabricar'),
      aoConfirmar: () => enviar({ t: 'shinyStone.fabricar', tipo: pedra.tipo }),
    });
  };
}

// ------------------------------------------ Professor Carvalho: Fabricar Mega Stone

/**
 * 10 Fragmentos de Mega Stone → a Mega Stone da ESPÉCIE escolhida (32 opções), e a mesma
 * escada em shiny com os Fragmentos de Mega Shiny Stone.
 *
 * ### Por que as duas famílias dividem a bancada, com um interruptor
 *
 * São o mesmo gesto com moedas diferentes, e o jogador chega aqui com uma pergunta só: "que
 * pedra eu consigo fazer agora?". Duas abas separadas obrigariam a sair e voltar para comparar
 * quantos fragmentos ele tem de cada lado. O interruptor em cima troca o recurso e a grade ao
 * mesmo tempo, e o contador de cada pedra já aparece no card.
 *
 * ### Por que a grade mostra o SPRITE da mega, e não só a pedra
 *
 * A Mega Stone é um quadradinho de 32 px; o que o jogador quer escolher é o BICHO. A grade é
 * de sprites com o nome embaixo — a mesma leitura da tela de escolha de evolução, e pela mesma
 * razão: escolher entre 32 coisas parecidas é um problema de olho, não de leitura.
 */
function montarFabricarMega(host) {
  const cfg = estado.mega;
  if (!cfg?.pedras?.length) {
    return void (host.innerHTML = bancadaVazia('mega', t('tm.abaMega'), '', 'casa.indisponivel'));
  }
  const shiny = estado.megaShiny === true;
  const fragId = shiny ? cfg.fragmentoShinyId : cfg.fragmentoId;
  const custo = (shiny ? cfg.custoShiny : cfg.custo) ?? 10;
  const tem = Number(estado.eu?.items?.[fragId] ?? 0);
  const pode = tem >= custo;
  const busca = (estado.megaBusca || '').trim().toLowerCase();

  // Sem `itemShinyId` = mega sem forma shiny (o Aggron, hoje). Some da grade shiny em vez de
  // aparecer desabilitada: uma pedra que não existe não é uma escolha travada, é uma escolha
  // que não há — e um card cinza sem explicação só faz o jogador procurar o que fazer para
  // destravá-lo.
  const lista = cfg.pedras.filter((x) => (shiny ? x.itemShinyId != null : true));
  const visiveis = busca
    ? lista.filter((x) => x.nome.toLowerCase().includes(busca) || x.pedra.toLowerCase().includes(busca))
    : lista;

  const cards = visiveis.map((x) => {
    const itemId = shiny ? x.itemShinyId : x.itemId;
    const qtd = Number(estado.eu?.items?.[itemId] ?? 0);
    const esp = estado.especies.get(x.megaPokeId);
    const look = shiny ? (estado.shinyLooks[x.megaPokeId] ?? esp?.looktype) : esp?.looktype;
    return `
      <button type="button" class="mega-op${qtd ? ' tem' : ''}" data-dex="${x.dex}" ${pode ? '' : 'disabled'}
              title="${escapar(x.pedra)}">
        <span class="mega-op-arte" data-look="${look ?? 0}"></span>
        <b class="mega-op-nome">${escapar(x.nome)}</b>
        <span class="mega-op-pedra">${imgItem(itemId, 18).outerHTML}${qtd ? `<i>×${num(qtd)}</i>` : ''}</span>
      </button>`;
  }).join('');

  host.innerHTML = bancadaHtml({
    aba: 'mega',
    titulo: t('tm.abaMega'),
    sub: t(shiny ? 'tm.subMegaShiny' : 'tm.subMega', { n: custo }),
    corpo: `
      <div class="mega-troca" role="group">
        <button type="button" class="mega-troca-bt${shiny ? '' : ' on'}" data-shiny="0">
          ${imgItem(cfg.fragmentoId, 20).outerHTML}<span>${escapar(t('mega.familiaComum'))}</span>
        </button>
        <button type="button" class="mega-troca-bt${shiny ? ' on' : ''}" data-shiny="1">
          ${imgItem(cfg.fragmentoShinyId, 20).outerHTML}<span>${escapar(t('mega.familiaShiny'))}</span>
        </button>
      </div>
      ${recursoHtml({
        itemId: fragId,
        nome: nomeItem(fragId, shiny ? 'Mega Shiny Stone Fragment' : 'Mega Stone Fragment'),
        tem,
        custo,
      })}
      <b class="tm-secao">${escapar(t(pode ? 'mega.escolha' : 'mega.faltam', { n: custo - tem }))}</b>
      <input type="search" class="mega-busca" id="mega-busca" autocomplete="off"
             placeholder="${escapar(t('mega.buscar'))}" value="${escapar(estado.megaBusca ?? '')}">
      <div class="mega-grid">${cards || `<p class="tm-vazio">${escapar(t('mega.semResultado'))}</p>`}</div>
      <p class="tm-nota">${escapar(t('mega.comoUsar'))}</p>`,
  });

  // O sprite animado não sai de `innerHTML` — cada card recebe o seu depois de montado, como a
  // grade da Pokédex faz.
  for (const alvo of host.querySelectorAll('.mega-op-arte')) {
    const look = Number(alvo.dataset.look);
    if (look > 0) alvo.appendChild(spriteAnimado(look, 40));
  }

  host.querySelector('.mega-troca').onclick = (ev) => {
    const b = ev.target.closest('.mega-troca-bt');
    if (!b) return;
    estado.megaShiny = b.dataset.shiny === '1';
    montarTmResearcher();
  };

  const campo = host.querySelector('#mega-busca');
  campo.oninput = () => {
    estado.megaBusca = campo.value;
    const foco = document.activeElement === campo;
    montarTmResearcher();
    if (foco) {
      const novo = $('#mega-busca');
      novo?.focus();
      novo?.setSelectionRange(novo.value.length, novo.value.length);
    }
  };

  host.querySelector('.mega-grid').onclick = (ev) => {
    const b = ev.target.closest('.mega-op');
    if (!b || b.disabled) return;
    const x = lista.find((m) => m.dex === Number(b.dataset.dex));
    if (!x) return;
    const itemId = shiny ? x.itemShinyId : x.itemId;
    // O mesmo nome que o toast de "fabricada" vai dizer (ver `megaStoneFabricada`).
    const nome = nomeItem(itemId, shiny ? `Shiny ${x.pedra}` : x.pedra);
    confirmarGasto({
      titulo: t('tm.abaMega'),
      gasta: { itemId: fragId, qtd: custo, nome: nomeItem(fragId, shiny ? 'Mega Shiny Stone Fragment' : 'Mega Stone Fragment') },
      ganha: { arte: imgItem(itemId, 40).outerHTML, qtd: '+1', nome, sub: escapar(x.nome) },
      pergunta: t('fab.perguntaPedra', { n: num(custo), nome: escapar(nome) }),
      rotuloSim: t('fab.fabricar'),
      aoConfirmar: () => enviar({ t: 'mega.fabricar', dex: x.dex, shiny }),
    });
  };
}

// -------------------------------------------- Professor Carvalho: Trocar peças

/**
 * Peças de boss → discos. Dois cartões, um por família de peça, cada um com o recurso e o que
 * ele compra. Os 18 discos elementais saem com o ÍCONE do disco daquele tipo (ver
 * `aplicarIconesTmElemental`) e o selo, em vez de "Disco FIRE" escrito — a grade fica com
 * botões do mesmo tamanho, e o olho acha o tipo pela cor antes de ler.
 */
function montarTmTrocar(host, cfg) {
  const items = estado.eu?.items ?? {};
  const pecasEl = items[cfg.pieceElemental] ?? 0;
  const pecasAoe = items[cfg.pieceAoe] ?? 0;
  const podeEl = pecasEl >= cfg.custoElemental;
  const podeAoe = pecasAoe >= cfg.custoAoe;
  host.innerHTML = bancadaHtml({
    aba: 'trocar',
    titulo: t('tm.abaTrocar'),
    sub: t('tm.introTrocar'),
    corpo: `
      <section class="tm-cartao">
        <b class="tm-secao">${escapar(t('tm.secaoElemental'))}</b>
        ${recursoHtml({ itemId: cfg.pieceElemental, nome: t('tm.pecasElemental'), tem: pecasEl, custo: cfg.custoElemental })}
        <div class="tm-grid-tipos" id="tm-tipos"></div>
      </section>
      <section class="tm-cartao">
        <b class="tm-secao">${escapar(t('tm.secaoAoe'))}</b>
        ${recursoHtml({ itemId: cfg.pieceAoe, nome: t('tm.pecasAoe'), tem: pecasAoe, custo: cfg.custoAoe })}
        <button type="button" class="tm-tipo tm-trocar-aoe" id="tm-trocar-aoe" ${podeAoe ? '' : 'disabled'}>
          ${imgItem(cfg.diskAoe, 24).outerHTML}<span>${escapar(t('tm.trocarAoe'))}</span>
        </button>
      </section>`,
  });
  // As duas famílias confirmam do mesmo jeito; muda a peça, o disco e o que vai ao servidor.
  const confirmarTroca = ({ peca, custo, nomePeca, disco, nome, sub = '', msg }) => confirmarGasto({
    titulo: t('tm.abaTrocar'),
    gasta: { itemId: peca, qtd: custo, nome: nomePeca },
    ganha: { arte: imgItem(disco, 40).outerHTML, qtd: '+1', nome, sub },
    pergunta: t('fab.perguntaDisco', { n: num(custo), nome: escapar(nome) }),
    rotuloSim: t('fab.trocar'),
    aoConfirmar: () => enviar(msg),
  });
  const grid = host.querySelector('#tm-tipos');
  for (const { tipo, itemId } of cfg.discos ?? []) {
    const bt = document.createElement('button');
    bt.type = 'button';
    bt.className = 'tm-tipo tm-disco-tipo';
    bt.disabled = !podeEl;
    bt.title = t('tm.trocarTipo', { tipo });
    bt.appendChild(imgItem(itemId, 22));
    bt.insertAdjacentHTML('beforeend', selosDeTipo([tipo]));
    bt.onclick = () => {
      if (!podeEl) return toast(t('tm.semPecas'));
      confirmarTroca({
        peca: cfg.pieceElemental, custo: cfg.custoElemental, nomePeca: t('tm.pecasElemental'),
        disco: itemId, nome: t('tm.trocarTipo', { tipo }), sub: selosDeTipo([tipo]),
        msg: { t: 'tm.trocar', modo: 'elemental', tipo },
      });
    };
    grid.appendChild(bt);
  }
  host.querySelector('#tm-trocar-aoe').onclick = () => {
    if (!podeAoe) return toast(t('tm.semPecas'));
    confirmarTroca({
      peca: cfg.pieceAoe, custo: cfg.custoAoe, nomePeca: t('tm.pecasAoe'),
      disco: cfg.diskAoe, nome: t('tm.trocarAoe'),
      msg: { t: 'tm.trocar', modo: 'aoe' },
    });
  };
}

/** Os TMs da equipe em uma linha — o que a aba "Aplicar disco" mostra e que o snapshot muda. */
function tmsDaEquipe(eu) {
  return (eu?.pokemons ?? [])
    .filter((p) => p.slot != null)
    .map((p) => `${p.id}:${p.tmElemental ?? ''}:${p.tmAoe ? 1 : 0}`)
    .join('|');
}

function discosTmNoInventario(cfg) {
  const items = estado.eu?.items ?? {};
  const saida = [];
  if ((items[cfg.diskAoe] ?? 0) > 0) {
    const item = estado.itens.get(cfg.diskAoe);
    saida.push({ itemId: cfg.diskAoe, nome: item?.name ?? 'AoE TM Disk', kind: 'aoe', qtd: items[cfg.diskAoe] });
  }
  for (const { tipo, itemId } of cfg.discos ?? []) {
    const q = items[itemId] ?? 0;
    if (q < 1) continue;
    const item = estado.itens.get(itemId);
    saida.push({ itemId, nome: item?.name ?? `${tipo} TM Disk`, kind: 'elemental', tipo, qtd: q });
  }
  return saida;
}

// ------------------------------------------- Professor Carvalho: Aplicar disco

/**
 * Pokémon da equipe + disco do inventário → golpe permanente. Em dois PASSOS numerados, com o
 * botão de aplicar preso no rodapé: a lista de equipe e a de discos rolam, o "Aplicar" fica à
 * vista. Escolher um pokémon ou um disco redesenha pela `montarTmResearcher`, que guarda a
 * rolagem — quem escolhe o disco no fim da lista não volta para o topo.
 */
function montarTmAplicar(host, cfg) {
  const equipe = (estado.eu?.pokemons ?? []).filter((p) => p.slot != null);
  const discos = discosTmNoInventario(cfg);
  const sub = t('tm.introAplicar');
  if (!equipe.length) return void (host.innerHTML = bancadaVazia('aplicar', t('tm.abaAplicar'), sub, 'tm.semEquipe'));
  if (!discos.length) {
    // Sem disco, a bancada ENSINA de onde ele vem — as peças → o disco, no palco do diálogo de
    // jogo — e leva à aba que resolve, em vez de parar num "você não tem" sem saída.
    const disco = (cfg.discos ?? []).find((d) => d.tipo === 'FIRE')?.itemId ?? cfg.diskAoe;
    host.innerHTML = bancadaHtml({
      aba: 'aplicar',
      titulo: t('tm.abaAplicar'),
      sub,
      corpo: `
        <div class="tm-vazio tm-vazio-cta">
          ${dlgPalco(`
            ${dlgAtor({ arte: dlgArteItem(cfg.pieceElemental, 40), nome: escapar(t('tm.pecasElemental')), qtd: `×${num(cfg.custoElemental ?? 10)}` })}
            ${dlgSeta()}
            ${dlgAtor({ arte: dlgArteItem(disco, 40), nome: escapar(t('tm.infoViraElemental')), classe: 'novo' })}`, 'rx')}
          <p>${escapar(t('tm.semDiscos'))}</p>
          <button type="button" class="camp-btn" id="tm-ir-trocar">${escapar(t('tm.abaTrocar'))}</button>
        </div>`,
    });
    hidratarDialogo(host);
    host.querySelector('#tm-ir-trocar').onclick = () => document.querySelector('#tm-abas [data-aba="trocar"]')?.click();
    return;
  }
  if (estado.tmPkSel != null && !equipe.some((p) => p.id === estado.tmPkSel)) estado.tmPkSel = null;
  if (estado.tmDiscoSel != null && !discos.some((d) => d.itemId === estado.tmDiscoSel)) estado.tmDiscoSel = null;

  host.innerHTML = bancadaHtml({
    aba: 'aplicar',
    titulo: t('tm.abaAplicar'),
    sub,
    corpo: `
      <b class="tm-secao"><span class="tm-passo">1</span>${escapar(t('tm.escolhaPk'))}</b>
      <div class="tm-equipe" id="tm-equipe"></div>
      <b class="tm-secao"><span class="tm-passo">2</span>${escapar(t('tm.escolhaDisco'))}</b>
      <div class="tm-discos" id="tm-discos"></div>`,
    rodape: `<button type="button" class="boss-desafiar tm-fabricar" id="tm-aplicar-bt">${escapar(t('tm.aplicar'))}</button>`,
  });

  const pkSel = equipe.find((p) => p.id === estado.tmPkSel);
  if (pkSel) {
    const hintHost = host.querySelector('#tm-equipe');
    const tipos = (pkSel.tipos ?? []).join(', ');
    const hints = [];
    if (tipos) hints.push(t('tm.compatTipos', { tipos }));
    hints.push(t('tm.compatAoe'));
    hintHost.insertAdjacentHTML('afterend', `<p class="tm-compat">${hints.join(' · ')}</p>`);
  }
  const lista = host.querySelector('#tm-equipe');
  for (const pk of equipe) {
    const el = document.createElement('div');
    el.className = 'tm-pk' + (pk.id === estado.tmPkSel ? ' on' : '');
    const status = pk.tmAoe && pk.tmElemental
      ? t('tm.jaTemAmbos', { tipo: pk.tmElemental })
      : pk.tmAoe
        ? t('tm.jaTemAoe')
        : pk.tmElemental
          ? t('tm.jaTemElemental', { tipo: pk.tmElemental })
          : '—';
    el.innerHTML = `<div class="tm-pk-nome">${escapar(pk.nome)} ${selosTm(pk)}<em>${escapar(status)}</em></div>`;
    el.prepend(spritePokemon(pk, 32));
    el.onclick = () => {
      estado.tmPkSel = pk.id;
      montarTmResearcher();
    };
    lista.appendChild(el);
  }
  // O disco que não serve no escolhido. O elemental IGUAL ao que ele já tem também trava: o
  // servidor aceitaria, gastaria o disco e não mudaria nada no bicho.
  const bloqueadoPara = (d) => (d.kind === 'aoe'
    ? !!pkSel?.tmAoe
    : !pkSel || !(pkSel.tipos ?? []).includes(d.tipo) || pkSel.tmElemental === d.tipo);
  const discosHost = host.querySelector('#tm-discos');
  for (const d of discos) {
    const bt = document.createElement('button');
    bt.type = 'button';
    bt.className = 'tm-disco' + (d.itemId === estado.tmDiscoSel ? ' on' : '');
    bt.disabled = bloqueadoPara(d);
    bt.appendChild(imgItem(d.itemId, 22));
    bt.insertAdjacentHTML('beforeend', `<span>${escapar(d.nome)} ×${num(d.qtd)}</span>`);
    bt.onclick = () => {
      estado.tmDiscoSel = d.itemId;
      montarTmResearcher();
    };
    discosHost.appendChild(bt);
  }
  const discoSel = discos.find((d) => d.itemId === estado.tmDiscoSel);
  const aplicar = host.querySelector('#tm-aplicar-bt');
  // Escolher outro pokémon não desmarca o disco: o FIRE escolhido antes continuaria aceso num
  // Blastoise, e o botão abriria uma confirmação que o servidor recusa.
  aplicar.disabled = !pkSel || !discoSel || bloqueadoPara(discoSel);
  aplicar.onclick = () => {
    if (aplicar.disabled) return;
    const aoe = discoSel.kind === 'aoe';
    const nomeDisco = aoe ? t('tm.trocarAoe') : t('tm.trocarTipo', { tipo: discoSel.tipo });
    // Cada bicho tem UM elemental, e aplicar outro apaga o de antes sem devolver o disco.
    const antigo = aoe ? null : (pkSel.tmElemental ?? null);
    confirmarGasto({
      titulo: t('tm.abaAplicar'),
      gasta: { itemId: discoSel.itemId, qtd: 1, nome: nomeDisco },
      ganha: {
        arte: '',
        nome: pkSel.nome,
        sub: `<span class="tm-selo${aoe ? ' aoe' : ''}">TM ${aoe ? 'AoE' : escapar(discoSel.tipo)}</span>`,
      },
      pergunta: t('fab.perguntaAplicar', { disco: escapar(nomeDisco), nome: escapar(pkSel.nome) }),
      aviso: antigo
        ? t('fab.aplicarSubstitui', { nome: escapar(pkSel.nome), antigo: escapar(antigo), novo: escapar(discoSel.tipo) })
        : '',
      rotuloSim: t('tm.aplicar'),
      aoConfirmar: () => enviar({ t: 'tm.aplicar', pokemonId: pkSel.id, itemId: discoSel.itemId }),
      depois: (corpo) => corpo.querySelector('.fab-lado.entra .fab-arte')?.appendChild(spritePokemon(pkSel, 40)),
    });
  };
}

// ------------------------------------------------------- o diálogo de jogo (dlg-)
//
// As peças que fazem da caixa de confirmação uma CENA: o palco com os bonecos, a seta que anda,
// os requisitos com a marca de ok/falta, o preço com o saldo antes → depois e os selos do que
// não tem volta. O porquê de cada uma está no cabeçalho do bloco `dlg-` em `estilo.css`; aqui é
// só a montagem.
//
// Tudo é TEMPLATE DE TEXTO, como o resto das telas, e a arte entra por marcação: `data-dlg-lt`
// (sprite animado de um looktype), `data-dlg-item` (ícone de item), `data-dlg-arquivo` (ícone do
// espelho ou nosso) e `data-dlg-treinador` (um boneco, com as cores dele). Quem troca a
// marcação pelo desenho é `hidratarDialogo`, que o `confirmar` chama logo depois do `innerHTML` —
// nenhuma caixa precisa lembrar de fazer isso, e nenhuma consegue esquecer.
//
// As peças recebem HTML PRONTO nos campos de texto: quem chama escapa o que veio de fora (o nome
// com apelido, o nick, o endereço da carteira), exatamente como já fazia com o `texto` cru.

